"use client";

import * as React from "react";
import {
  EASE_OUT,
  INTERACTION_FOCUS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * ACCORDION: sections that open in place
 *
 *   open     the section's height eases open (0fr → 1fr) while its
 *            content rises out of a blur a beat later; the chevron
 *            turns over in the same motion
 *   single   opening one folds the open one at the same time, so
 *            the page below barely moves
 *   keys     ↑/↓ move between headers, Home/End jump; Enter and
 *            Space open
 *
 * For FAQ sections on landing pages there is faq-accordion; this
 * is the plain one for settings, filters and details.
 * ───────────────────────────────────────────────────────── */

export interface AccordionItem {
  value: string;
  title: React.ReactNode;
  /** A second line under the title. */
  subtitle?: React.ReactNode;
  content: React.ReactNode;
  disabled?: boolean;
}

export interface AccordionProps {
  items: AccordionItem[];
  /** One open at a time, or any number. */
  type?: "single" | "multiple";
  value?: string[];
  defaultValue?: string[];
  onValueChange?: (value: string[]) => void;
  /** thin line rows, or each section as its own card. */
  variant?: "rows" | "cards";
  className?: string;
}

/** The fold every disclosure in the library uses: height by grid rows, content through a blur. */
export function Fold({
  open,
  children,
  reduced,
  id,
  labelledBy,
}: {
  open: boolean;
  children: React.ReactNode;
  reduced: boolean;
  id?: string;
  labelledBy?: string;
}) {
  return (
    <div
      id={id}
      role={labelledBy ? "region" : undefined}
      aria-labelledby={labelledBy}
      inert={!open || undefined}
      className="grid"
      style={{
        gridTemplateRows: open ? "1fr" : "0fr",
        transition: reduced ? "none" : `grid-template-rows 420ms ${EASE_OUT}`,
      }}
    >
      <div className="min-h-0 overflow-hidden">
        <div
          style={{
            opacity: open ? 1 : 0,
            filter: open || reduced ? "blur(0px)" : "blur(4px)",
            translate: open || reduced ? "0 0" : "0 -6px",
            transition: reduced
              ? "none"
              : open
                ? `opacity 300ms ${EASE_OUT} 90ms, filter 300ms ${EASE_OUT} 90ms, translate 420ms ${EASE_OUT}`
                : `opacity 160ms ${EASE_OUT}, filter 160ms ${EASE_OUT}, translate 260ms ${EASE_OUT}`,
          }}
        >
          {children}
        </div>
      </div>
    </div>
  );
}

export function Chevron({
  open,
  reduced,
}: {
  open: boolean;
  reduced: boolean;
}) {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      aria-hidden="true"
      className="size-3.5 shrink-0 text-muted-foreground"
      style={{
        transform: open ? "rotate(180deg)" : "none",
        transition: reduced ? "none" : `transform 420ms ${EASE_OUT}`,
      }}
    >
      <path
        d="M4 6l4 4 4-4"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

export function Accordion({
  items,
  type = "single",
  value,
  defaultValue = [],
  onValueChange,
  variant = "rows",
  className = "",
}: AccordionProps) {
  const reduced = useInteractionReducedMotion();
  const baseId = React.useId();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const [own, setOwn] = React.useState(defaultValue);
  const open = value ?? own;
  const cards = variant === "cards";

  const toggle = (v: string) => {
    const next = open.includes(v)
      ? open.filter((x) => x !== v)
      : type === "single"
        ? [v]
        : [...open, v];
    if (value === undefined) setOwn(next);
    onValueChange?.(next);
  };

  const onKeyDown = (e: React.KeyboardEvent) => {
    const heads = Array.from(
      rootRef.current?.querySelectorAll<HTMLButtonElement>(
        "[data-accordion-head]:not(:disabled)",
      ) ?? [],
    );
    const i = heads.indexOf(document.activeElement as HTMLButtonElement);
    if (i < 0) return;
    let next = -1;
    if (e.key === "ArrowDown") next = (i + 1) % heads.length;
    else if (e.key === "ArrowUp") next = (i - 1 + heads.length) % heads.length;
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = heads.length - 1;
    if (next < 0) return;
    e.preventDefault();
    heads[next].focus();
  };

  return (
    <div
      ref={rootRef}
      onKeyDown={onKeyDown}
      className={`flex w-full flex-col ${cards ? "gap-2" : "divide-y divide-border border-y border-border"} ${className}`}
    >
      {items.map((item) => {
        const on = open.includes(item.value);
        const head = `${baseId}-h-${item.value}`;
        const panel = `${baseId}-p-${item.value}`;
        return (
          <div
            key={item.value}
            className={
              cards
                ? `rounded-[16px] bg-card shadow-[inset_0_0_0_1px_var(--border)] transition-colors duration-300 ${on ? "" : "hover:bg-accent/40"}`
                : ""
            }
          >
            <h3 className="m-0">
              <button
                type="button"
                id={head}
                data-accordion-head=""
                aria-expanded={on}
                aria-controls={panel}
                disabled={item.disabled}
                onClick={() => toggle(item.value)}
                className={`flex w-full items-center gap-3 text-left cursor-pointer disabled:cursor-default disabled:opacity-40 ${cards ? "rounded-[16px] px-4 py-3.5" : "py-3.5"} ${INTERACTION_FOCUS} focus-visible:ring-offset-0`}
              >
                <span className="flex min-w-0 flex-1 flex-col gap-0.5">
                  <span className="text-[14px] font-medium text-foreground">
                    {item.title}
                  </span>
                  {item.subtitle && (
                    <span className="text-[12.5px] text-muted-foreground">
                      {item.subtitle}
                    </span>
                  )}
                </span>
                <Chevron open={on} reduced={reduced} />
              </button>
            </h3>
            <Fold open={on} reduced={reduced} id={panel} labelledBy={head}>
              <div
                className={`text-[13.5px] leading-relaxed text-muted-foreground ${cards ? "px-4 pb-4" : "pb-4"}`}
              >
                {item.content}
              </div>
            </Fold>
          </div>
        );
      })}
    </div>
  );
}

export default Accordion;

"use client";

import * as React from "react";
import { TextMorph } from "./text-morph";
import {
  EASE_OUT,
  INTERACTION_FOCUS,
  INTERACTION_PRESS,
  interactionIcon,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

export type ActionStatus = "idle" | "pending" | "success" | "error";

export interface ActionButtonProps extends Omit<
  React.ButtonHTMLAttributes<HTMLButtonElement>,
  "onClick"
> {
  /** Async or sync action to execute on click. Automatically handles idle -> pending -> success/error. */
  action?: () => Promise<unknown> | void;
  /** Explicit click handler if action is not used. */
  onClick?: (e: React.MouseEvent<HTMLButtonElement>) => void;
  /** Controlled status state. If passed, overrides internal action state. */
  status?: ActionStatus;
  /** Custom labels for each status. */
  labels?: Partial<Record<ActionStatus, string>>;
  /** Default label in idle state if children is not provided. */
  label?: string;
  /** Leading icon shown in idle state. */
  icon?: React.ReactNode;
  /** Visual variant. Defaults to primary. */
  variant?: "primary" | "secondary" | "destructive" | "outline" | "ghost";
  /** Button sizing. Defaults to md (36px). */
  size?: "sm" | "md" | "lg";
  /** Duration in ms to show success or error state before auto-reverting to idle. Defaults to 2000ms. */
  resetAfter?: number;
  /** Callback fired when auto-reset triggers. */
  onReset?: () => void;
  /** Called with whatever `action` threw. */
  onError?: (error: unknown) => void;
}

const DEFAULT_LABELS: Record<ActionStatus, string> = {
  idle: "Save changes",
  pending: "Saving",
  success: "Saved",
  error: "Try again",
};

function SelfDrawingCheck({
  drawn,
  reduced,
  size,
}: {
  drawn: boolean;
  reduced: boolean;
  size: number;
}) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 16 16"
      fill="none"
      className="shrink-0"
    >
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 420ms ${EASE_OUT} 120ms`
              : "none",
        }}
      />
    </svg>
  );
}

function StatusAlert({ size }: { size: number }) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 16 16"
      fill="none"
      className="shrink-0"
    >
      <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeWidth="1.5" />
      <path
        d="M8 4.75v3.75"
        stroke="currentColor"
        strokeWidth="1.75"
        strokeLinecap="round"
      />
      <circle cx="8" cy="11" r="1" fill="currentColor" />
    </svg>
  );
}

const variantStyles = {
  primary: "bg-primary text-primary-foreground hover:bg-primary/90",
  secondary:
    "bg-card text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent",
  outline:
    "bg-transparent text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent",
  destructive:
    "bg-red-500/10 text-red-600 dark:text-red-400 shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_30%,transparent)] hover:bg-red-500/15",
  ghost:
    "bg-transparent text-muted-foreground hover:bg-accent hover:text-foreground",
};

const sizeStyles = {
  sm: {
    height: "h-7 text-[12px] px-3",
    iconSize: 13,
    spinnerSize: "size-3",
  },
  md: {
    height: "h-9 text-[13px] px-4",
    iconSize: 14,
    spinnerSize: "size-3.5",
  },
  lg: {
    height: "h-10 text-[14px] px-5",
    iconSize: 16,
    spinnerSize: "size-4",
  },
};

export function ActionButton({
  action,
  onClick,
  status: controlledStatus,
  labels,
  label: defaultLabel,
  icon,
  variant = "primary",
  size = "md",
  resetAfter = 2000,
  onReset,
  onError,
  children,
  disabled = false,
  className = "",
  style,
  ...props
}: ActionButtonProps) {
  const reduced = useInteractionReducedMotion();
  const [internalStatus, setInternalStatus] =
    React.useState<ActionStatus>("idle");
  const btnRef = React.useRef<HTMLButtonElement | null>(null);
  const resetTimer = React.useRef<number>(0);

  const status = controlledStatus ?? internalStatus;
  const busy = status === "pending";
  const s = sizeStyles[size];

  // Resolve current label text
  const initialText = typeof children === "string" ? children : defaultLabel;
  const statusLabels = {
    ...DEFAULT_LABELS,
    idle: initialText || DEFAULT_LABELS.idle,
    ...labels,
  };
  const currentLabel = statusLabels[status];

  // Auto reset timer on success or error
  React.useEffect(() => {
    if (status !== "success" && status !== "error") return;
    if (resetAfter <= 0) return;

    window.clearTimeout(resetTimer.current);
    resetTimer.current = window.setTimeout(() => {
      if (controlledStatus === undefined) {
        setInternalStatus("idle");
      }
      onReset?.();
    }, resetAfter);

    return () => window.clearTimeout(resetTimer.current);
  }, [status, resetAfter, controlledStatus, onReset]);

  // Shake animation on error
  React.useEffect(() => {
    if (status !== "error" || reduced || !btnRef.current) return;
    btnRef.current.animate(
      [
        { transform: "none" },
        { transform: "translateX(-4px)" },
        { transform: "translateX(4px)" },
        { transform: "translateX(-2px)" },
        { transform: "translateX(2px)" },
        { transform: "none" },
      ],
      { duration: 380, easing: "ease-out" },
    );
  }, [status, reduced]);

  // Click / execution handler
  const handleClick = async (e: React.MouseEvent<HTMLButtonElement>) => {
    if (busy || disabled) {
      e.preventDefault();
      return;
    }

    if (onClick) {
      onClick(e);
    }

    if (action) {
      e.preventDefault();
      setInternalStatus("pending");
      try {
        await action();
        setInternalStatus("success");
      } catch (err) {
        setInternalStatus("error");
        onError?.(err);
      }
    }
  };

  // Tone resolution for error/success overrides
  const toneClass =
    status === "error"
      ? "bg-red-500/10 text-red-600 shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_30%,transparent)] dark:text-red-400"
      : status === "success" && variant === "destructive"
        ? "bg-emerald-500/10 text-emerald-600 shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-emerald-500)_30%,transparent)] dark:text-emerald-400"
        : variantStyles[variant];

  // Current status icon
  const showLeading = status !== "idle" || Boolean(icon);

  const icons: Record<ActionStatus, React.ReactNode> = {
    idle: icon,
    // Spins only while pending, so a hidden spinner never keeps the page busy.
    pending: (
      <span
        className={`inline-flex rounded-full border-[1.5px] border-current border-t-transparent ${s.spinnerSize} ${busy ? "animate-spin" : ""}`}
      />
    ),
    success: (
      <SelfDrawingCheck
        drawn={status === "success"}
        reduced={reduced}
        size={s.iconSize}
      />
    ),
    error: <StatusAlert size={s.iconSize} />,
  };

  return (
    <>
      <button
        ref={btnRef}
        type="button"
        disabled={disabled}
        aria-disabled={busy || undefined}
        aria-busy={busy || undefined}
        onClick={handleClick}
        style={style}
        className={`relative inline-flex select-none items-center justify-center whitespace-nowrap rounded-full font-medium cursor-pointer disabled:cursor-default aria-disabled:cursor-default disabled:opacity-45 ${s.height} ${toneClass} ${INTERACTION_PRESS} ${INTERACTION_FOCUS} ${className}`}
        {...props}
      >
        {/* The icon slot opens and closes; icons trade places through a blur. */}
        <span
          aria-hidden="true"
          className="relative flex shrink-0 items-center justify-center"
          style={{
            width: showLeading ? s.iconSize : 0,
            height: s.iconSize,
            marginRight: showLeading ? (size === "sm" ? 6 : 8) : 0,
            transition: reduced
              ? "none"
              : `width 380ms ${EASE_OUT}, margin-right 380ms ${EASE_OUT}`,
          }}
        >
          {(Object.keys(icons) as ActionStatus[]).map((key) => (
            <span
              key={key}
              className="absolute inset-0 flex items-center justify-center"
              style={interactionIcon(key === status, reduced)}
            >
              {icons[key]}
            </span>
          ))}
        </span>
        <TextMorph>{currentLabel}</TextMorph>
      </button>
      {/* Outside the button, so the announcement isn't read as part of its name. */}
      <span role="status" className="sr-only">
        {status === "idle" ? "" : currentLabel}
      </span>
    </>
  );
}

export default ActionButton;

"use client";

import * as React from "react";
import { Check, ChevronRight, RotateCcw, X } from "lucide-react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * ACTION RECEIPTS: what the agent did, and the way back
 *
 *   done      a quiet line per action: what happened, where;
 *             Undo with a ring that drains while you still can,
 *             folding away when the window closes
 *   undoing   the ring blurs into a spinner; "Undo" morphs to
 *             "Undoing"
 *   undone    a strike draws itself across the line; "Undone"
 *   failed    why it failed, and Retry
 *   stacked   three or more fold into "3 actions · Undo all",
 *             which opens into the list; the counts roll
 *
 * Undo is one button from first to last: its icon slot and label
 * change, it never gets swapped for another element.
 *
 * Feed it the actions your tools performed; it keeps the timing.
 * ───────────────────────────────────────────────────────── */

export type ReceiptStatus = "done" | "undoing" | "undone" | "failed";

export interface Receipt {
  id: string;
  /** What happened, e.g. "Added “Soft launch” to Saturday". */
  title: string;
  /** Where or when, e.g. "Calendar · 9:00 am". */
  detail?: string;
  icon?: React.ReactNode;
  status?: ReceiptStatus;
  error?: string;
  /** Until when it can be undone (ms timestamp). Without it, no Undo. */
  undoUntil?: number;
}

export interface ActionReceiptsProps extends React.HTMLAttributes<HTMLDivElement> {
  actions: Receipt[];
  onUndo?: (id: string) => void | Promise<void>;
  /** Defaults to undoing each undoable action. */
  onUndoAll?: () => void | Promise<void>;
  onRetry?: (id: string) => void;
  /** Fold into a summary from this many actions (0 never folds). */
  stackFrom?: number;
  /** How long the undo window is, for the ring (ms). */
  undoWindow?: number;
}

const EASE = "cubic-bezier(0.23,1,0.32,1)";
const MORPH = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const LINK = `inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full px-2.5 text-[12px] font-medium text-foreground transition-colors hover:bg-accent ${FOCUS}`;

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Icons trade places through a blur: the old one shrinks away as the new one grows in. */
const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 260ms ${MORPH}, transform 380ms ${MORPH}, filter 260ms ${MORPH}`,
});

/** A piece of a line that opens out of nothing and folds back into it. */
function Reveal({
  show,
  reduced,
  className = "",
  children,
}: {
  show: boolean;
  reduced: boolean;
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <span
      aria-hidden={!show || undefined}
      className={`grid ${className}`}
      style={{
        gridTemplateColumns: show ? "1fr" : "0fr",
        opacity: show ? 1 : 0,
        filter: show ? "none" : "blur(3px)",
        transition: reduced
          ? "none"
          : `grid-template-columns 420ms ${MORPH}, opacity ${show ? "300ms" : "160ms"} ${MORPH}, filter 300ms ${MORPH}`,
      }}
    >
      <span className="flex min-w-0 items-center whitespace-nowrap [clip-path:inset(-4px_-2px)]">
        {children}
      </span>
    </span>
  );
}

/** Re-renders when the next undo window closes, so Undo disappears on time. */
function useUndoClock(actions: Receipt[]) {
  const [now, setNow] = React.useState(() => Date.now());
  React.useEffect(() => {
    const next = actions
      .map((a) => a.undoUntil ?? 0)
      .filter((t) => t > now)
      .sort((a, b) => a - b)[0];
    if (!next) return;
    const timer = window.setTimeout(() => setNow(Date.now()), next - now + 20);
    return () => window.clearTimeout(timer);
  }, [actions, now]);
  return now;
}

/** A ring that drains from full to empty over the time left, with CSS only. */
function DrainRing({
  until,
  window: total,
  reduced,
}: {
  until: number;
  window: number;
  reduced: boolean;
}) {
  const [start] = React.useState(() => Date.now());
  const left = Math.max(0, until - start);
  const elapsed = Math.max(0, total - left);
  const c = 2 * Math.PI * 5.5;
  return (
    <svg aria-hidden="true" viewBox="0 0 14 14" className="size-3.5 -rotate-90">
      <circle
        cx="7"
        cy="7"
        r="5.5"
        fill="none"
        strokeWidth="1.5"
        className="stroke-border"
      />
      <circle
        cx="7"
        cy="7"
        r="5.5"
        fill="none"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeDasharray={c}
        className="stroke-foreground/70"
        style={
          reduced
            ? { strokeDashoffset: c * (elapsed / total) }
            : ({
                "--ui-ring": `${c}`,
                animation: `ui-drain ${total}ms linear -${elapsed}ms forwards`,
              } as React.CSSProperties)
        }
      />
    </svg>
  );
}

function Line({
  action,
  now,
  pending,
  undoWindow,
  reduced,
  onUndo,
  onRetry,
}: {
  action: Receipt;
  now: number;
  pending: boolean;
  undoWindow: number;
  reduced: boolean;
  onUndo?: (id: string) => void;
  onRetry?: (id: string) => void;
}) {
  const status = pending ? "undoing" : (action.status ?? "done");
  const canUndo =
    status === "done" && Boolean(onUndo) && (action.undoUntil ?? 0) > now;
  const undone = status === "undone";
  const failed = status === "failed";

  // The one button's state: what it says and whether it does anything.
  const mode =
    status === "undoing"
      ? "undoing"
      : undone
        ? "undone"
        : failed && onRetry
          ? "retry"
          : canUndo
            ? "undo"
            : null;
  const [lastMode, setLastMode] = React.useState(mode);
  if (mode && mode !== lastMode) setLastMode(mode);
  const shown = mode ?? lastMode;
  const actionable = mode === "undo" || mode === "retry";
  const label = {
    undo: "Undo",
    undoing: "Undoing",
    undone: "Undone",
    retry: "Retry",
  };
  const layer = "absolute inset-0 flex items-center justify-center";

  return (
    <li className="flex min-h-10 items-center gap-2.5 py-1 animate-[ui-fade-up_320ms_cubic-bezier(0.23,1,0.32,1)_both] motion-reduce:animate-none">
      <span
        aria-hidden="true"
        className={`relative flex size-6 shrink-0 items-center justify-center rounded-full transition-colors duration-300 [&_svg]:size-3.5 [&_svg]:stroke-[1.8] ${
          failed
            ? "bg-red-500/10 text-red-600 dark:text-red-400"
            : "bg-muted text-muted-foreground"
        }`}
      >
        <span className={layer} style={swap(!failed, reduced)}>
          {action.icon ?? <Check />}
        </span>
        <span className={layer} style={swap(failed, reduced)}>
          <X />
        </span>
      </span>
      <span className="min-w-0 flex-1">
        <span className="block truncate text-[13px]">
          {/* The strike draws itself across the title, left to right. */}
          <span
            className={`bg-[linear-gradient(color-mix(in_oklab,currentColor_55%,transparent),color-mix(in_oklab,currentColor_55%,transparent))] bg-no-repeat [background-position:0_58%] ${undone ? "text-muted-foreground" : "text-foreground"}`}
            style={{
              backgroundSize: undone ? "100% 1px" : "0% 1px",
              transition: reduced
                ? "none"
                : `background-size 480ms ${MORPH} 80ms, color 300ms`,
            }}
          >
            {action.title}
          </span>
        </span>
        {(failed ? action.error : action.detail) && (
          <span
            className={`block truncate text-[11.5px] transition-colors duration-300 ${failed ? "text-red-600 dark:text-red-400" : "text-muted-foreground"}`}
          >
            {failed ? action.error : action.detail}
          </span>
        )}
      </span>

      <span role="status" className="sr-only">
        {status === "undoing"
          ? `Undoing ${action.title}`
          : undone
            ? `Undone: ${action.title}`
            : failed
              ? `Failed: ${action.error ?? action.title}`
              : ""}
      </span>
      {shown && (
        <Reveal show={Boolean(mode)} reduced={reduced} className="shrink-0">
          <span className="block p-0.5">
            <button
              type="button"
              inert={!mode}
              aria-disabled={!actionable || undefined}
              aria-label={mode === "undo" ? `Undo: ${action.title}` : undefined}
              onClick={() =>
                mode === "undo"
                  ? onUndo?.(action.id)
                  : mode === "retry"
                    ? onRetry?.(action.id)
                    : undefined
              }
              className={`inline-flex h-7 items-center gap-1.5 rounded-full px-2.5 text-[12px] font-medium transition-colors ${FOCUS} ${
                actionable
                  ? "text-foreground hover:bg-accent"
                  : "cursor-default text-muted-foreground"
              }`}
            >
              <span
                aria-hidden="true"
                className="relative flex size-3.5 shrink-0 items-center justify-center"
              >
                {/* Keyed by the window, so a fresh window drains from full; paused once it has faded out. */}
                <span
                  className={`${layer} ${shown === "undo" ? "" : "[&_*]:[animation-play-state:paused]"}`}
                  style={swap(shown === "undo", reduced)}
                >
                  <DrainRing
                    key={action.undoUntil}
                    until={action.undoUntil ?? 0}
                    window={undoWindow}
                    reduced={reduced}
                  />
                </span>
                <span
                  className={layer}
                  style={swap(shown === "undoing", reduced)}
                >
                  <span
                    className={`size-3 rounded-full border-[1.5px] border-border border-t-foreground/70 motion-reduce:animate-none ${shown === "undoing" ? "animate-spin" : ""}`}
                  />
                </span>
                <span
                  className={layer}
                  style={swap(shown === "undone" || shown === "retry", reduced)}
                >
                  <RotateCcw className="size-3" />
                </span>
              </span>
              <TextMorph>{label[shown as keyof typeof label]}</TextMorph>
            </button>
          </span>
        </Reveal>
      )}
    </li>
  );
}

export function ActionReceipts({
  actions,
  onUndo,
  onUndoAll,
  onRetry,
  stackFrom = 3,
  undoWindow = 10_000,
  className = "",
  ...props
}: ActionReceiptsProps) {
  const reduced = useReducedMotion();
  const now = useUndoClock(actions);
  const [pending, setPending] = React.useState<Set<string>>(() => new Set());
  const [open, setOpen] = React.useState(false);
  const listId = React.useId();

  const undo = async (id: string) => {
    if (!onUndo) return;
    setPending((p) => new Set(p).add(id));
    try {
      await onUndo(id);
    } finally {
      setPending((p) => {
        const next = new Set(p);
        next.delete(id);
        return next;
      });
    }
  };

  const undoable = actions.filter(
    (a) =>
      (a.status ?? "done") === "done" &&
      (a.undoUntil ?? 0) > now &&
      !pending.has(a.id),
  );
  const undoAll = async () => {
    if (onUndoAll) {
      setPending(new Set(undoable.map((a) => a.id)));
      try {
        await onUndoAll();
      } finally {
        setPending(new Set());
      }
    } else await Promise.all(undoable.map((a) => undo(a.id)));
  };

  const stacked = stackFrom > 0 && actions.length >= stackFrom;
  const failed = actions.filter((a) => a.status === "failed").length;
  const undone = actions.filter((a) => a.status === "undone").length;
  const busy = pending.size > 0;

  const lines = (
    <ul aria-label="Actions taken">
      {actions.map((a) => (
        <Line
          key={a.id}
          action={a}
          now={now}
          pending={pending.has(a.id)}
          undoWindow={undoWindow}
          reduced={reduced}
          onUndo={onUndo ? undo : undefined}
          onRetry={onRetry}
        />
      ))}
    </ul>
  );

  if (!stacked) {
    return (
      <div className={`w-full ${className}`} {...props}>
        {lines}
      </div>
    );
  }

  return (
    <div className={`w-full ${className}`} {...props}>
      <div className="flex min-h-10 items-center gap-2.5">
        <button
          type="button"
          aria-expanded={open}
          aria-controls={listId}
          onClick={() => setOpen((o) => !o)}
          className="cursor-pointer group flex min-w-0 flex-1 items-center gap-2.5 rounded-lg py-1 text-left outline-none focus-visible:ring-2 focus-visible:ring-ring/40"
        >
          <span aria-hidden="true" className="flex shrink-0 items-center">
            {actions.slice(0, 3).map((a, i) => (
              <span
                key={a.id}
                className={`flex size-6 items-center justify-center rounded-full ring-2 ring-background [&_svg]:size-3.5 [&_svg]:stroke-[1.8] ${i ? "-ml-2" : ""} ${
                  a.status === "failed"
                    ? "bg-red-500/10 text-red-600 dark:text-red-400"
                    : "bg-muted text-muted-foreground"
                }`}
                style={{ zIndex: 3 - i }}
              >
                {a.status === "failed" ? <X /> : (a.icon ?? <Check />)}
              </span>
            ))}
          </span>
          {/* "4 actions · 1 failed · 2 undone": counts roll, and the extra parts open in as they apply. */}
          <span className="flex min-w-0 items-baseline truncate text-[13px] text-foreground">
            <NumberRoll value={actions.length} duration={600} />
            &nbsp;
            <TextMorph>{actions.length === 1 ? "action" : "actions"}</TextMorph>
            <Reveal show={failed > 0} reduced={reduced}>
              &nbsp;·&nbsp;
              <NumberRoll value={failed} duration={600} />
              &nbsp;failed
            </Reveal>
            <Reveal show={undone > 0} reduced={reduced}>
              &nbsp;·&nbsp;
              <NumberRoll value={undone} duration={600} />
              &nbsp;undone
            </Reveal>
          </span>
          <ChevronRight
            aria-hidden="true"
            className="size-3.5 shrink-0 text-muted-foreground transition-transform duration-300 group-hover:text-foreground motion-reduce:transition-none"
            style={{
              transform: open ? "rotate(90deg)" : "none",
              transitionTimingFunction: EASE,
            }}
          />
        </button>
        {onUndo && (
          // Opens while there's more than one thing to undo; says what it's doing while it does it.
          <Reveal
            show={undoable.length > 1 || busy}
            reduced={reduced}
            className="shrink-0"
          >
            <span className="block p-0.5">
              <button
                type="button"
                inert={!(undoable.length > 1 || busy)}
                onClick={() => !busy && undoAll()}
                aria-disabled={busy || undefined}
                className={`${LINK} ${busy ? "cursor-default text-muted-foreground hover:bg-transparent" : ""}`}
              >
                <span
                  aria-hidden="true"
                  className="relative flex size-3 shrink-0 items-center justify-center"
                >
                  <span
                    className="absolute inset-0 flex items-center justify-center"
                    style={swap(!busy, reduced)}
                  >
                    <RotateCcw className="size-3" />
                  </span>
                  <span
                    className="absolute inset-0 flex items-center justify-center"
                    style={swap(busy, reduced)}
                  >
                    <span
                      className={`size-3 rounded-full border-[1.5px] border-border border-t-foreground/70 motion-reduce:animate-none ${busy ? "animate-spin" : ""}`}
                    />
                  </span>
                </span>
                <TextMorph>{busy ? "Undoing all" : "Undo all"}</TextMorph>
              </button>
            </span>
          </Reveal>
        )}
      </div>
      <div
        id={listId}
        inert={!open}
        className="grid"
        style={{
          gridTemplateRows: open ? "1fr" : "0fr",
          transition: reduced ? "none" : `grid-template-rows 380ms ${EASE}`,
        }}
      >
        <div className="min-h-0 overflow-hidden">
          <div className="ml-3 border-l border-border pl-[18px]">{lines}</div>
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * ACTIVITY HEATMAP: every day as a square, weeks across
 *
 *   arrive    the first time it's on screen the days fill in
 *             as a wave from the oldest week to the newest, and
 *             the total rolls up from zero
 *   point     point at a day (or move to it with the arrow keys)
 *             and one readout glides along the rail above the
 *             grid to its week: the count rolls, the date morphs.
 *             At rest the readout sits on the busiest day
 *   level     point at a step of the legend and every day
 *             outside that band steps back
 *   data      new numbers or a new colour ripple across the grid
 *             week by week instead of switching at once
 *   fit       it shows as many of the weeks as fit at a readable
 *             size, newest on the right
 *
 * The grid is a real ARIA grid: one tab stop, arrow keys, Home
 * and End, and each day's count and date as its label.
 * ───────────────────────────────────────────────────────── */

export interface HeatmapDay {
  /** "YYYY-MM-DD". Days missing from the data count as zero. */
  date: string;
  value: number;
}

export interface ActivityHeatmapProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "title"
> {
  data: HeatmapDay[];
  /** The last day shown, "YYYY-MM-DD"; defaults to the latest day in the data. */
  end?: string;
  /** The most weeks to show; fewer when the card is narrow. */
  weeks?: number;
  /** The first row: 0 for Sunday, 1 for Monday. */
  weekStart?: 0 | 1;
  /** What's being counted, e.g. { one: "order", other: "orders" }. */
  unit?: { one: string; other: string };
  /** The colour of the busiest days; the other steps are mixed from it. */
  color?: string;
  /** Lower bounds of levels 1 to 4. By default they come from the data's own quartiles. */
  thresholds?: [number, number, number, number];
  title?: React.ReactNode;
  description?: React.ReactNode;
  action?: React.ReactNode;
  locales?: string | string[];
  onDayClick?: (day: HeatmapDay) => void;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const DAY = 86_400_000;
const GAP = 3;
const MIN_CELL = 10;
const MAX_CELL = 16;
const LABELS = 30;
const UNIT = { one: "contribution", other: "contributions" };
const MIX = [0, 28, 52, 76, 100];

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );
const subscribeNothing = () => () => {};
/** Dates in the visitor's language wait for hydration, so the server's en-US render and the first client render match. */
const useHydrated = () =>
  React.useSyncExternalStore(
    subscribeNothing,
    () => true,
    () => false,
  );

const parse = (date: string) => Date.parse(`${date}T00:00:00Z`);
const iso = (t: number) => new Date(t).toISOString().slice(0, 10);

/** The quartiles of the days that have anything, as the lower bounds of levels 2 to 4 (level 1 is anything above zero). */
function quartiles(values: number[]): [number, number, number, number] {
  const sorted = values.filter((v) => v > 0).sort((a, b) => a - b);
  if (!sorted.length) return [1, 2, 3, 4];
  const at = (q: number) =>
    sorted[Math.min(sorted.length - 1, Math.floor(q * sorted.length))];
  return [Number.MIN_VALUE, at(0.25), at(0.5), at(0.75)];
}

const levelOf = (v: number, t: [number, number, number, number]) =>
  v <= 0
    ? 0
    : v >= t[3]
      ? 4
      : v >= t[2]
        ? 3
        : v >= t[1]
          ? 2
          : v >= t[0]
            ? 1
            : 0;

export function ActivityHeatmap({
  data,
  end,
  weeks = 26,
  weekStart = 0,
  unit = UNIT,
  color = "var(--chart-3, #1baf7a)",
  thresholds,
  title,
  description,
  action,
  locales,
  onDayClick,
  className = "",
  ...props
}: ActivityHeatmapProps) {
  const reduced = useReducedMotion();
  const hydrated = useHydrated();
  const lang = hydrated ? locales : (locales ?? "en-US");
  const rootRef = React.useRef<HTMLDivElement>(null);
  const bodyRef = React.useRef<HTMLDivElement>(null);
  const pillRef = React.useRef<HTMLDivElement>(null);
  const cellRefs = React.useRef(new Map<string, HTMLElement>());
  const [width, setWidth] = React.useState(0);
  const [pillWidth, setPillWidth] = React.useState(0);
  const [visible, setVisible] = React.useState(false);
  const [pointed, setPointed] = React.useState<string | null>(null);
  const [focused, setFocused] = React.useState<string | null>(null);
  const [band, setBand] = React.useState<number | null>(null);

  React.useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          observer.disconnect();
        }
      },
      { rootMargin: "0px 0px -10% 0px" },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  // Measured before the first paint, so the grid never shows at the wrong size.
  React.useLayoutEffect(() => {
    const el = bodyRef.current;
    if (!el) return;
    const observer = new ResizeObserver(([entry]) => {
      const w = Math.floor(entry.contentRect.width);
      setWidth((prev) => (prev === w ? prev : w));
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  React.useEffect(() => {
    const el = pillRef.current;
    if (!el) return;
    const observer = new ResizeObserver(() => {
      const w = el.offsetWidth;
      setPillWidth((prev) => (prev === w ? prev : w));
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  // The weeks that fit: at least MIN_CELL a day, never more than asked for.
  const room = Math.max(0, width - LABELS);
  const shown = width
    ? Math.max(4, Math.min(weeks, Math.floor((room + GAP) / (MIN_CELL + GAP))))
    : weeks;
  const cell = width
    ? Math.min(MAX_CELL, (room + GAP) / shown - GAP)
    : MAX_CELL;
  const gridWidth = shown * (cell + GAP) - GAP;

  const values = new Map<string, number>();
  for (const d of data) values.set(d.date, (values.get(d.date) ?? 0) + d.value);
  const lastDate =
    end ??
    data.reduce(
      (latest, d) => (d.date > latest ? d.date : latest),
      data[0]?.date ?? "",
    );
  const last = lastDate ? parse(lastDate) : 0;
  const lastRow = last ? (new Date(last).getUTCDay() - weekStart + 7) % 7 : 0;
  const first = last - ((shown - 1) * 7 + lastRow) * DAY;

  // Columns are weeks, rows are weekdays; days after the last one are left out.
  const grid = Array.from({ length: 7 }, (_, row) =>
    Array.from({ length: shown }, (_, col) => {
      const t = first + (col * 7 + row) * DAY;
      const date = iso(t);
      return {
        date,
        t,
        row,
        col,
        value: values.get(date) ?? 0,
        future: t > last,
      };
    }),
  );
  // In date order (the grid itself runs row by row).
  const days = grid
    .flat()
    .filter((d) => !d.future && last)
    .sort((a, b) => a.t - b.t);
  const levels = thresholds ?? quartiles(days.map((d) => d.value));
  const total = days.reduce((sum, d) => sum + d.value, 0);
  const peak = days.reduce<(typeof days)[number] | null>(
    (best, d) => (!best || d.value > best.value ? d : best),
    null,
  );

  const current =
    days.find((d) => d.date === (pointed ?? focused)) ??
    (peak && peak.value > 0 ? peak : null);
  const named = (n: number) => (n === 1 ? unit.one : unit.other);
  const dayLabel = (t: number, long = false) =>
    new Intl.DateTimeFormat(lang, {
      timeZone: "UTC",
      weekday: long ? "long" : "short",
      day: "numeric",
      month: long ? "long" : "short",
    }).format(t);
  const month = (t: number) =>
    new Intl.DateTimeFormat(lang, { timeZone: "UTC", month: "short" }).format(
      t,
    );
  const weekday = (row: number) =>
    new Intl.DateTimeFormat(lang, { timeZone: "UTC", weekday: "short" }).format(
      Date.UTC(2026, 0, 4 + ((row + weekStart) % 7)),
    );

  // A month's name over the first week that starts in it, if there's room before the next.
  const months: { col: number; label: string }[] = [];
  for (let col = 0; col < shown; col++) {
    const t = grid[0][col].t;
    const prev = col > 0 ? grid[0][col - 1].t : null;
    if (
      prev === null
        ? new Date(t).getUTCDate() <= 7
        : new Date(t).getUTCMonth() !== new Date(prev).getUTCMonth()
    ) {
      if (!months.length || col - months[months.length - 1].col >= 3)
        months.push({ col, label: month(t) });
    }
  }

  const x = current ? LABELS + current.col * (cell + GAP) + cell / 2 : LABELS;
  const half = pillWidth / 2;
  const pillX = Math.min(
    Math.max(x, half),
    Math.max(half, LABELS + gridWidth - half),
  );

  const fill = (level: number) =>
    level === 0
      ? "color-mix(in oklab, var(--foreground) 7%, transparent)"
      : `color-mix(in oklab, ${color} ${MIX[level]}%, var(--background))`;

  const move = (date: string) => {
    setFocused(date);
    cellRefs.current.get(date)?.focus();
  };

  const onKeyDown = (e: React.KeyboardEvent) => {
    const at =
      days.find((d) => d.date === focused) ?? peak ?? days[days.length - 1];
    if (!at) return;
    const steps: Record<string, number> = {
      ArrowLeft: -7,
      ArrowRight: 7,
      ArrowUp: -1,
      ArrowDown: 1,
    };
    let next: number | null = null;
    if (e.key in steps) next = at.t + steps[e.key] * DAY;
    else if (e.key === "Home") next = days[0]?.t ?? null;
    else if (e.key === "End") next = days[days.length - 1]?.t ?? null;
    else if ((e.key === "Enter" || e.key === " ") && onDayClick) {
      e.preventDefault();
      onDayClick({ date: at.date, value: at.value });
      return;
    }
    if (next === null) return;
    e.preventDefault();
    if (next >= (days[0]?.t ?? 0) && next <= last) move(iso(next));
  };

  const wave = (col: number) =>
    reduced
      ? "none"
      : `background-color 520ms ${EASE} ${col * 16}ms, opacity 200ms ${EASE}, box-shadow 160ms ${EASE}`;
  const tabStop = focused ?? current?.date ?? days[days.length - 1]?.date;

  return (
    <div
      ref={rootRef}
      className={`w-full rounded-[22px] bg-background shadow-[0_0_0_1px_var(--border)] ${className}`}
      {...props}
    >
      {/* Its natural width where the parent sizes to its content (a centred flex column), without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 640px)" }}
      />
      <div className="@container w-full">
        <div className="p-4 @md:p-5">
          {(title || description || action) && (
            <div className="mb-3 flex items-start justify-between gap-3">
              <div className="min-w-0">
                {title && (
                  <p className="text-[13.5px] font-medium text-foreground @md:text-[14px]">
                    {title}
                  </p>
                )}
                {description && (
                  <p className="mt-0.5 text-[12px] text-muted-foreground @md:text-[12.5px]">
                    {description}
                  </p>
                )}
              </div>
              {action && <div className="shrink-0">{action}</div>}
            </div>
          )}

          <p className="flex flex-wrap items-baseline gap-x-1.5 text-[12px] text-muted-foreground @md:text-[12.5px]">
            <span className="text-[22px] font-semibold tracking-[-0.03em] text-foreground tabular-nums @md:text-[26px]">
              <NumberRoll
                value={visible ? total : 0}
                locales={locales}
                duration={1000}
              />
            </span>
            <span>
              {named(total)} in the last {shown} weeks
            </span>
          </p>

          <div
            ref={bodyRef}
            className="relative mt-3 w-full"
            onPointerLeave={() => setPointed(null)}
          >
            {/* The readout: one pill that glides to the day being pointed at, or rests on the busiest one. */}
            <div className="relative h-7">
              <div
                ref={pillRef}
                aria-hidden="true"
                className="absolute left-0 top-0 flex h-6 items-center gap-1.5 whitespace-nowrap rounded-full bg-foreground px-2.5 text-[11.5px] text-background"
                style={{
                  transform: `translateX(${pillX - half}px)`,
                  opacity: current && width ? 1 : 0,
                  transition: reduced
                    ? "none"
                    : `transform 300ms ${EASE}, opacity 200ms ${EASE}`,
                }}
              >
                <span className="font-medium tabular-nums">
                  <NumberRoll
                    value={current?.value ?? 0}
                    locales={locales}
                    duration={600}
                  />
                </span>
                <span className="opacity-70">
                  <TextMorph
                    duration={360}
                  >{`${named(current?.value ?? 0)} · ${current ? dayLabel(current.t) : ""}`}</TextMorph>
                </span>
              </div>
            </div>

            {/* Month names over the weeks they start in. */}
            <div
              aria-hidden="true"
              className="relative h-4 text-[10.5px] text-muted-foreground @md:text-[11px]"
              style={{ marginLeft: LABELS }}
            >
              {months.map((m) => (
                <span
                  key={m.col}
                  className="absolute top-0"
                  style={{ left: m.col * (cell + GAP) }}
                >
                  {m.label}
                </span>
              ))}
            </div>

            <div className="mt-1 flex">
              <div
                aria-hidden="true"
                className="grid shrink-0 text-[10.5px] text-muted-foreground @md:text-[11px]"
                style={{
                  width: LABELS,
                  gridTemplateRows: `repeat(7, ${cell}px)`,
                  rowGap: GAP,
                }}
              >
                {Array.from({ length: 7 }, (_, row) => (
                  <span
                    key={row}
                    className="leading-none"
                    style={{ lineHeight: `${cell}px` }}
                  >
                    {(
                      weekStart === 0 ? row % 2 === 1 : row % 2 === 0 && row < 6
                    )
                      ? weekday(row)
                      : ""}
                  </span>
                ))}
              </div>

              <div
                role="grid"
                aria-label={`${total} ${named(total)} in the last ${shown} weeks`}
                aria-readonly="true"
                onKeyDown={onKeyDown}
                onBlur={(e) => {
                  if (!e.currentTarget.contains(e.relatedTarget as Node | null))
                    setFocused(null);
                }}
                className="grid"
                style={{
                  width: gridWidth,
                  gridTemplateColumns: `repeat(${shown}, ${cell}px)`,
                  gridTemplateRows: `repeat(7, ${cell}px)`,
                  gap: GAP,
                }}
              >
                {grid.map((row, r) => (
                  <div key={r} role="row" className="contents">
                    {row.map((d) => {
                      const level = levelOf(d.value, levels);
                      const on = (pointed ?? focused) === d.date;
                      const out = band !== null && level !== band;
                      return (
                        <span
                          key={d.date}
                          ref={(el) => {
                            if (el) cellRefs.current.set(d.date, el);
                            else cellRefs.current.delete(d.date);
                          }}
                          role="gridcell"
                          aria-label={
                            d.future
                              ? undefined
                              : `${d.value} ${named(d.value)}, ${dayLabel(d.t, true)}`
                          }
                          aria-hidden={d.future || undefined}
                          tabIndex={!d.future && d.date === tabStop ? 0 : -1}
                          onPointerEnter={(e) =>
                            e.pointerType === "mouse" &&
                            !d.future &&
                            setPointed(d.date)
                          }
                          onPointerDown={(e) =>
                            e.pointerType !== "mouse" &&
                            !d.future &&
                            setPointed(d.date)
                          }
                          onFocus={() => setFocused(d.date)}
                          onClick={() =>
                            !d.future &&
                            onDayClick?.({ date: d.date, value: d.value })
                          }
                          className={`rounded-[3px] outline-none focus-visible:ring-2 focus-visible:ring-ring/50 ${onDayClick && !d.future ? "cursor-pointer" : ""}`}
                          style={{
                            gridColumn: d.col + 1,
                            gridRow: r + 1,
                            visibility: d.future ? "hidden" : undefined,
                            background: fill(visible ? level : 0),
                            opacity: out ? 0.22 : 1,
                            boxShadow: on
                              ? "inset 0 0 0 1.5px var(--foreground)"
                              : undefined,
                            transition: wave(d.col),
                          }}
                        />
                      );
                    })}
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* The scale: point at a step to see only the days in it. */}
          <div
            className="mt-3 flex items-center justify-end gap-1.5 text-[11px] text-muted-foreground"
            onPointerLeave={() => setBand(null)}
          >
            <span>Less</span>
            {[0, 1, 2, 3, 4].map((level) => (
              <span
                key={level}
                aria-hidden="true"
                onPointerEnter={() => setBand(level)}
                className="size-[11px] cursor-default rounded-[3px] transition-[box-shadow] duration-150"
                style={{
                  background: fill(level),
                  boxShadow:
                    band === level
                      ? "0 0 0 1.5px var(--foreground)"
                      : undefined,
                  transition: reduced
                    ? "none"
                    : `background-color 520ms ${EASE}`,
                }}
              />
            ))}
            <span>More</span>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * ACTIVITY RINGS: three daily goals as concentric rings
 *
 *   arrive    the first time it's on screen the rings sweep
 *             round from the top, outer first, and every figure
 *             rolls up from zero
 *   day       the week sits underneath as seven small rings:
 *             pick a day and the big rings sweep to it, the
 *             day's name morphs and every figure rolls; days
 *             still to come are quiet and can't be picked
 *   past      a goal beaten carries on round for a second lap,
 *             with a dot marking where it's got to
 *   focus     point at a ring or its row and the other two step
 *             back
 *
 * The legend is real text (figure, goal and share), the week is
 * a radio group, and the rings themselves are decoration.
 * ───────────────────────────────────────────────────────── */

export interface RingGoal {
  id: string;
  label: string;
  /** The day's target. */
  goal: number;
  format?: Intl.NumberFormatOptions;
}

export interface RingDay {
  key: string;
  /** Under the small ring, e.g. "F". */
  label: string;
  /** In the title, e.g. "Friday 9 October". */
  title?: string;
  /** One per goal; null for a day still to come. */
  values: (number | null)[];
}

export interface ActivityRingsProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onChange"
> {
  /** Up to three, outermost first. */
  goals: RingGoal[];
  /** The week, oldest first. */
  days: RingDay[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (key: string) => void;
  locales?: string | string[];
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const COLORS = [
  "var(--chart-1, var(--primary))",
  "var(--chart-2, #e8743b)",
  "var(--chart-3, #1baf7a)",
];
const BIG = { size: 132, stroke: 12, gap: 3 };
const SMALL = { size: 28, stroke: 3, gap: 1 };

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const radius = (g: typeof BIG, i: number) =>
  g.size / 2 - g.stroke / 2 - i * (g.stroke + g.gap);

/** One ring: its track, the first lap, and a second lap (with a dot at its lead) when the goal is beaten. */
function Ring({
  geo,
  i,
  share,
  color,
  dim,
  reduced,
  delay = 0,
  tip = true,
}: {
  geo: typeof BIG;
  i: number;
  share: number;
  color: string;
  dim: boolean;
  reduced: boolean;
  delay?: number;
  tip?: boolean;
}) {
  const r = radius(geo, i);
  const c = 2 * Math.PI * r;
  const lap = Math.min(1, Math.max(0, share));
  const over = Math.min(1, Math.max(0, share - 1));
  const centre = geo.size / 2;
  const angle = over * 2 * Math.PI - Math.PI / 2;
  const sweep = reduced
    ? "none"
    : `stroke-dashoffset 1100ms ${EASE} ${delay}ms, opacity 300ms ${EASE}`;
  return (
    <g
      style={{
        opacity: dim ? 0.3 : 1,
        transition: reduced ? "none" : `opacity 300ms ${EASE}`,
      }}
    >
      <circle
        cx={centre}
        cy={centre}
        r={r}
        fill="none"
        stroke={`color-mix(in oklab, ${color} 16%, var(--background))`}
        strokeWidth={geo.stroke}
      />
      <circle
        cx={centre}
        cy={centre}
        r={r}
        fill="none"
        stroke={color}
        strokeWidth={geo.stroke}
        strokeLinecap="round"
        strokeDasharray={c}
        transform={`rotate(-90 ${centre} ${centre})`}
        style={{
          strokeDashoffset: c * (1 - lap),
          opacity: lap > 0 ? 1 : 0,
          transition: sweep,
        }}
      />
      {tip && (
        <>
          <circle
            cx={centre}
            cy={centre}
            r={r}
            fill="none"
            stroke={color}
            strokeWidth={geo.stroke}
            strokeLinecap="round"
            strokeDasharray={c}
            transform={`rotate(-90 ${centre} ${centre})`}
            style={{
              strokeDashoffset: c * (1 - over),
              opacity: over > 0 ? 1 : 0,
              transition: sweep,
            }}
          />
          {/* Where the second lap has got to: a dot ringed in the surface colour, so it reads over the first lap. */}
          <circle
            cx={centre + r * Math.cos(angle)}
            cy={centre + r * Math.sin(angle)}
            r={geo.stroke / 2 - 1}
            fill={color}
            stroke="var(--background)"
            strokeWidth={2}
            style={{
              opacity: over > 0.02 ? 1 : 0,
              transition: reduced
                ? "none"
                : `opacity 300ms ${EASE} ${over > 0.02 ? 900 + delay : 0}ms`,
            }}
          />
        </>
      )}
    </g>
  );
}

export function ActivityRings({
  goals: allGoals,
  days,
  value,
  defaultValue,
  onValueChange,
  locales,
  className = "",
  ...props
}: ActivityRingsProps) {
  const reduced = useReducedMotion();
  const goals = allGoals.slice(0, 3);
  const lastDay = Math.max(
    0,
    days.reduce(
      (last, d, i) => (d.values.some((v) => v !== null) ? i : last),
      0,
    ),
  );
  const [own, setOwn] = React.useState(defaultValue ?? days[lastDay]?.key);
  const dayKey = value ?? own;
  const index = Math.max(
    0,
    days.findIndex((d) => d.key === dayKey),
  );
  const day = days[index];
  const [visible, setVisible] = React.useState(false);
  const [focus, setFocus] = React.useState<number | null>(null);
  const rootRef = React.useRef<HTMLDivElement>(null);
  const dayRefs = React.useRef<(HTMLButtonElement | null)[]>([]);

  React.useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          observer.disconnect();
        }
      },
      { rootMargin: "0px 0px -10% 0px" },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  const pick = (i: number, moveFocus = false) => {
    const target = days[i];
    if (!target || i > lastDay) return;
    if (value === undefined) setOwn(target.key);
    onValueChange?.(target.key);
    if (moveFocus) dayRefs.current[i]?.focus();
  };

  const share = (g: number, d = day) =>
    d && d.values[g] != null
      ? (d.values[g] as number) / (goals[g].goal || 1)
      : 0;
  const fmt = (n: number, g: RingGoal) =>
    new Intl.NumberFormat(locales, g.format).format(n);

  return (
    <div
      ref={rootRef}
      className={`@container w-full rounded-[22px] bg-background shadow-[0_0_0_1px_var(--border)] ${className}`}
      {...props}
    >
      <div className="p-4 @md:p-5">
        <p className="text-[12px] text-muted-foreground @md:text-[13px]">
          <TextMorph>{day?.title ?? day?.label ?? ""}</TextMorph>
        </p>

        <div
          className="mt-3 flex items-center gap-4 @md:gap-6"
          onPointerLeave={() => setFocus(null)}
        >
          <svg
            aria-hidden="true"
            viewBox={`0 0 ${BIG.size} ${BIG.size}`}
            className="w-[108px] shrink-0 @md:w-[132px]"
          >
            {goals.map((g, i) => (
              <Ring
                key={g.id}
                geo={BIG}
                i={i}
                share={visible ? share(i) : 0}
                color={COLORS[i]}
                dim={focus !== null && focus !== i}
                reduced={reduced}
                delay={visible ? i * 120 : 0}
              />
            ))}
          </svg>

          <ul className="min-w-0 flex-1 divide-y divide-border">
            {goals.map((g, i) => {
              const v = day?.values[i];
              const s = share(i);
              return (
                <li
                  key={g.id}
                  onPointerEnter={() => setFocus(i)}
                  className="py-1.5 transition-opacity duration-300 first:pt-0 last:pb-0 @md:py-2"
                  style={{ opacity: focus !== null && focus !== i ? 0.45 : 1 }}
                >
                  <span className="flex items-center gap-1.5 text-[11.5px] text-muted-foreground @md:text-[12px]">
                    <span
                      aria-hidden="true"
                      className="size-[7px] shrink-0 rounded-full"
                      style={{ background: COLORS[i] }}
                    />
                    <span className="truncate">{g.label}</span>
                  </span>
                  <span className="mt-0.5 flex items-baseline gap-1 whitespace-nowrap">
                    <span className="text-[14px] font-medium tracking-[-0.01em] text-foreground @md:text-[15px]">
                      <NumberRoll
                        value={visible && v != null ? v : 0}
                        format={g.format}
                        locales={locales}
                        duration={900}
                      />
                    </span>
                    <span className="text-[11px] text-muted-foreground @md:text-[11.5px]">
                      / {fmt(g.goal, g)}
                    </span>
                    <span
                      className={`ml-auto text-[11px] tabular-nums @md:text-[11.5px] ${s >= 1 ? "font-medium text-foreground" : "text-muted-foreground"}`}
                    >
                      <NumberRoll
                        value={visible ? s : 0}
                        format={{ style: "percent" }}
                        duration={900}
                      />
                    </span>
                  </span>
                </li>
              );
            })}
          </ul>
        </div>

        {/* The week: seven small rings; pick one to see that day. */}
        <div
          role="radiogroup"
          aria-label="Day"
          className="mt-4 grid grid-cols-7 gap-0.5 border-t border-border pt-3 @md:mt-5"
          onKeyDown={(e) => {
            const moves: Record<string, number> = {
              ArrowLeft: index - 1,
              ArrowRight: index + 1,
              Home: 0,
              End: lastDay,
            };
            if (!(e.key in moves)) return;
            e.preventDefault();
            pick(Math.min(lastDay, Math.max(0, moves[e.key])), true);
          }}
        >
          {days.map((d, i) => {
            const selected = i === index;
            const future = i > lastDay;
            return (
              <button
                key={d.key}
                ref={(el) => {
                  dayRefs.current[i] = el;
                }}
                type="button"
                role="radio"
                aria-checked={selected}
                aria-disabled={future || undefined}
                aria-label={`${d.title ?? d.label}${future ? ", still to come" : `: ${goals.map((g, gi) => `${g.label} ${Math.round(share(gi, d) * 100)}%`).join(", ")}`}`}
                tabIndex={selected ? 0 : -1}
                onClick={() => pick(i)}
                className={`flex flex-col items-center gap-1 rounded-[10px] py-1.5 transition-colors duration-300 ${FOCUS} ${selected ? "bg-accent" : future ? "cursor-default" : "hover:bg-accent/60"}`}
              >
                <svg
                  aria-hidden="true"
                  viewBox={`0 0 ${SMALL.size} ${SMALL.size}`}
                  className="w-6 @md:w-7"
                  style={{ opacity: future ? 0.35 : 1 }}
                >
                  {goals.map((g, gi) => (
                    <Ring
                      key={g.id}
                      geo={SMALL}
                      i={gi}
                      share={visible ? share(gi, d) : 0}
                      color={COLORS[gi]}
                      dim={false}
                      reduced={reduced}
                      delay={visible ? i * 40 : 0}
                      tip={false}
                    />
                  ))}
                </svg>
                <span
                  className={`text-[10.5px] leading-none @md:text-[11px] ${selected ? "font-medium text-foreground" : "text-muted-foreground"}`}
                >
                  {d.label}
                </span>
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import {
  ArrowUp,
  Folder,
  Gauge,
  GitBranch,
  Hand,
  ListChecks,
  Mic,
  Plus,
  ShieldAlert,
  Square,
} from "lucide-react";
import { ModelPicker, type ModelOption } from "./model-picker";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * AGENT COMPOSER: the taller composer for agent surfaces
 *
 *   status      a tab hangs off the card's top edge with the
 *               branch, the project folder and how full the
 *               context is; each morphs when it changes, and the
 *               context ring fills, turning amber past 80%
 *   prompt      type; Enter sends, Shift+Enter adds a line, and
 *               the field grows with the text
 *   permission  the pill under the prompt says how much the agent
 *               may do on its own (Auto, Ask first, Plan only,
 *               Full access) and grows into a list with a line on
 *               each, clear of the composer
 *   model       the model pill on the right grows into its own
 *               list, with thinking effort for models that reason
 *   send        the arrow blurs into a spinner, then into Stop;
 *               the mic beside it breathes while it listens
 *   files       + opens the file picker, and paste and drop work
 *               too; chips fold open above the prompt
 *
 * status takes useChat's status as is.
 * ───────────────────────────────────────────────────────── */

export type AgentComposerStatus = "ready" | "submitted" | "streaming" | "error";

export interface AgentComposerProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onSubmit" | "defaultValue"
> {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onSubmit: (value: string) => void;
  onStop?: () => void;
  /** Pass useChat's status straight through. */
  status?: AgentComposerStatus;
  placeholder?: string;
  /** The tab on top. Leave all three out and there's no tab. */
  branch?: string;
  folder?: string;
  context?: { used: number; limit: number };
  /** The permission modes; defaults to Auto, Ask first, Plan only and Full access. */
  permissions?: ModelOption[];
  permission?: string;
  defaultPermission?: string;
  onPermissionChange?: (id: string) => void;
  models: ModelOption[];
  model: string;
  onModelChange: (id: string) => void;
  effort?: string;
  onEffortChange?: (effort: string) => void;
  /** Enables +, paste and drop. */
  onFilesSelected?: (files: File[]) => void;
  accept?: string;
  /** Attachment chips, shown above the prompt. */
  attachments?: React.ReactNode;
  /** Shows the mic. */
  onVoice?: () => void;
  listening?: boolean;
}

export const AGENT_PERMISSIONS: ModelOption[] = [
  {
    id: "auto",
    name: "Auto",
    description: "Decides for itself, asks when it's unsure",
    icon: <Gauge />,
  },
  {
    id: "ask",
    name: "Ask first",
    description: "Checks with you before every change",
    icon: <Hand />,
  },
  {
    id: "plan",
    name: "Plan only",
    description: "Reads and plans, changes nothing",
    icon: <ListChecks />,
  },
  {
    id: "full",
    name: "Full access",
    description: "Runs everything without asking",
    icon: <ShieldAlert />,
  },
];

const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const MORPH = "cubic-bezier(0.16,1,0.3,1)";
const compactNumber = new Intl.NumberFormat("en-US", {
  notation: "compact",
  maximumFractionDigits: 1,
});

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 260ms ${MORPH}, transform 380ms ${MORPH}, filter 260ms ${MORPH}`,
});

function Fold({
  show,
  reduced,
  children,
}: {
  show: boolean;
  reduced: boolean;
  children: React.ReactNode;
}) {
  const [last, setLast] = React.useState(children);
  if (show && children !== last) setLast(children);
  return (
    <div
      aria-hidden={!show || undefined}
      inert={!show}
      className="grid"
      style={{
        gridTemplateRows: show ? "1fr" : "0fr",
        opacity: show ? 1 : 0,
        transition: reduced
          ? "none"
          : `grid-template-rows 380ms ${MORPH}, opacity ${show ? "280ms" : "140ms"} ${MORPH}`,
      }}
    >
      <div className="min-h-0 overflow-hidden">{show ? children : last}</div>
    </div>
  );
}

/** How full the context is: a small ring that fills, amber past 80% and red past 95%, with the share rolling beside it. */
function ContextMeter({
  used,
  limit,
  reduced,
}: {
  used: number;
  limit: number;
  reduced: boolean;
}) {
  const share = limit ? Math.min(1, used / limit) : 0;
  const c = 2 * Math.PI * 5;
  const tone =
    share >= 0.95
      ? "text-red-500"
      : share >= 0.8
        ? "text-amber-500"
        : "text-foreground/60";
  return (
    <span
      className="flex items-center gap-1.5"
      title={`${compactNumber.format(used)} of ${compactNumber.format(limit)} tokens`}
    >
      <svg
        viewBox="0 0 14 14"
        aria-hidden="true"
        className={`size-3.5 -rotate-90 transition-colors duration-300 ${tone}`}
      >
        <circle
          cx="7"
          cy="7"
          r="5"
          fill="none"
          stroke="currentColor"
          strokeOpacity="0.2"
          strokeWidth="2"
        />
        <circle
          cx="7"
          cy="7"
          r="5"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeDasharray={c}
          style={{
            strokeDashoffset: c * (1 - share),
            transition: reduced ? "none" : `stroke-dashoffset 600ms ${MORPH}`,
          }}
        />
      </svg>
      <span className="tabular-nums">
        <NumberRoll
          value={share}
          format={{ style: "percent" }}
          duration={600}
        />
      </span>
      <span className="sr-only">of the context used</span>
    </span>
  );
}

export function AgentComposer({
  value,
  defaultValue = "",
  onValueChange,
  onSubmit,
  onStop,
  status = "ready",
  placeholder = "What should we build?",
  branch,
  folder,
  context,
  permissions = AGENT_PERMISSIONS,
  permission,
  defaultPermission,
  onPermissionChange,
  models,
  model,
  onModelChange,
  effort,
  onEffortChange,
  onFilesSelected,
  accept,
  attachments,
  onVoice,
  listening = false,
  className = "",
  ...props
}: AgentComposerProps) {
  const reduced = useReducedMotion();
  const [own, setOwn] = React.useState(defaultValue);
  const [ownPermission, setOwnPermission] = React.useState(
    defaultPermission ?? permissions[0]?.id ?? "",
  );
  const [dragging, setDragging] = React.useState(false);
  const text = value ?? own;
  const chosenPermission = permission ?? ownPermission;
  const cardRef = React.useRef<HTMLFormElement>(null);
  const textareaRef = React.useRef<HTMLTextAreaElement>(null);
  const fileRef = React.useRef<HTMLInputElement>(null);
  const busy = status === "submitted" || status === "streaming";
  const canSend = !busy && text.trim().length > 0;
  const hasTab = Boolean(branch || folder || context);

  const setText = (next: string) => {
    if (value === undefined) setOwn(next);
    onValueChange?.(next);
  };

  React.useLayoutEffect(() => {
    const el = textareaRef.current;
    if (!el) return;
    el.style.height = "auto";
    el.style.height = `${Math.min(el.scrollHeight, 220)}px`;
  }, [text]);

  const submit = () => {
    if (!canSend) return;
    onSubmit(text);
    if (value === undefined) setOwn("");
  };

  const takeFiles = (list: FileList | null) => {
    if (!list || list.length === 0 || !onFilesSelected) return false;
    onFilesSelected(Array.from(list));
    return true;
  };

  const action = busy
    ? status === "streaming" && onStop
      ? "stop"
      : "wait"
    : "send";

  return (
    <div className={`w-full ${className}`} {...props}>
      {/* The tab: where the agent is working, and how full its context is. */}
      {hasTab && (
        <div className="mx-3.5 flex h-7 items-center gap-3 rounded-t-[12px] bg-muted px-3 text-[11.5px] text-muted-foreground">
          {branch && (
            <span className="flex min-w-0 items-center gap-1.5">
              <GitBranch aria-hidden="true" className="size-3.5 shrink-0" />
              <span className="sr-only">Branch</span>
              <span className="truncate">
                <TextMorph>{branch}</TextMorph>
              </span>
            </span>
          )}
          {folder && (
            <span className="flex min-w-0 items-center gap-1.5">
              <Folder aria-hidden="true" className="size-3.5 shrink-0" />
              <span className="sr-only">Project</span>
              <span className="truncate">
                <TextMorph>{folder}</TextMorph>
              </span>
            </span>
          )}
          {context && (
            <span className="ml-auto shrink-0">
              <ContextMeter
                used={context.used}
                limit={context.limit}
                reduced={reduced}
              />
            </span>
          )}
        </div>
      )}

      <form
        ref={cardRef}
        onSubmit={(e) => {
          e.preventDefault();
          submit();
        }}
        onDragOver={(e) => {
          if (!onFilesSelected || !e.dataTransfer.types.includes("Files"))
            return;
          e.preventDefault();
          setDragging(true);
        }}
        onDragLeave={(e) => {
          if (!e.currentTarget.contains(e.relatedTarget as Node))
            setDragging(false);
        }}
        onDrop={(e) => {
          if (!onFilesSelected) return;
          e.preventDefault();
          setDragging(false);
          takeFiles(e.dataTransfer.files);
        }}
        className={`@container relative rounded-[20px] bg-background p-1.5 transition-shadow duration-200 ${
          dragging
            ? "shadow-[0_0_0_1px_color-mix(in_oklab,var(--foreground)_40%,transparent)]"
            : "shadow-[0_0_0_1px_var(--border)] focus-within:shadow-[0_0_0_1px_color-mix(in_oklab,var(--foreground)_22%,transparent)]"
        }`}
      >
        <Fold show={Boolean(attachments)} reduced={reduced}>
          <div className="flex flex-wrap gap-2 px-2 pt-2">{attachments}</div>
        </Fold>

        <textarea
          ref={textareaRef}
          rows={1}
          value={text}
          placeholder={placeholder}
          aria-label={placeholder}
          onChange={(e) => setText(e.target.value)}
          onKeyDown={(e) => {
            if (
              e.key === "Enter" &&
              !e.shiftKey &&
              !e.nativeEvent.isComposing
            ) {
              e.preventDefault();
              submit();
            }
          }}
          onPaste={(e) => {
            if (
              takeFiles(e.clipboardData.files) &&
              !e.clipboardData.getData("text")
            )
              e.preventDefault();
          }}
          className="block max-h-[220px] w-full resize-none overflow-y-auto bg-transparent px-2.5 pb-2 pt-2 text-[14px] leading-6 text-foreground outline-none placeholder:text-muted-foreground"
        />

        <div className="flex items-center gap-0.5">
          {onFilesSelected && (
            <>
              <button
                type="button"
                aria-label="Add files"
                onClick={() => fileRef.current?.click()}
                className={`cursor-pointer flex size-7 shrink-0 items-center justify-center rounded-full bg-muted text-foreground transition-colors hover:bg-accent @min-[26rem]:size-8 ${FOCUS}`}
              >
                <Plus className="size-4" />
              </button>
              <input
                ref={fileRef}
                type="file"
                multiple
                accept={accept}
                className="hidden"
                onChange={(e) => {
                  takeFiles(e.target.files);
                  e.target.value = "";
                }}
              />
            </>
          )}
          <ModelPicker
            label="Permission"
            models={permissions}
            value={chosenPermission}
            onValueChange={(id) => {
              if (permission === undefined) setOwnPermission(id);
              onPermissionChange?.(id);
            }}
            anchorRef={cardRef}
            side="top"
            align="start"
          />

          <div className="ml-auto flex items-center gap-0.5 @min-[26rem]:gap-1">
            <ModelPicker
              label="Model"
              models={models}
              value={model}
              onValueChange={onModelChange}
              effort={effort}
              onEffortChange={onEffortChange}
              anchorRef={cardRef}
              side="top"
              align="end"
            />
            {onVoice && (
              <button
                type="button"
                aria-label={listening ? "Stop listening" : "Speak"}
                aria-pressed={listening}
                onClick={onVoice}
                // On the narrowest composers the mic steps aside so Send always fits.
                className={`cursor-pointer relative hidden size-7 shrink-0 items-center justify-center rounded-full transition-colors duration-200 @min-[22rem]:flex @min-[26rem]:size-8 ${FOCUS} ${
                  listening
                    ? "text-primary"
                    : "text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent"
                }`}
              >
                {/* Breathes only while it listens. */}
                <span
                  aria-hidden="true"
                  className="absolute inset-0 rounded-full bg-primary/12"
                  style={{
                    opacity: listening ? 1 : 0,
                    animation:
                      listening && !reduced
                        ? "ui-breathe 1.6s ease-in-out infinite"
                        : "none",
                    transition: `opacity 200ms ${MORPH}`,
                  }}
                />
                <Mic className="relative size-4" />
              </button>
            )}
            <button
              type={action === "send" ? "submit" : "button"}
              aria-label={
                action === "stop"
                  ? "Stop"
                  : action === "wait"
                    ? "Sending"
                    : "Send"
              }
              disabled={action === "send" ? !canSend : action === "wait"}
              onClick={action === "stop" ? onStop : undefined}
              className={`cursor-pointer disabled:cursor-default relative flex size-8 shrink-0 items-center justify-center rounded-full bg-primary text-primary-foreground transition-[opacity,transform] duration-200 active:scale-95 disabled:opacity-35 ${FOCUS}`}
            >
              <span
                aria-hidden="true"
                className="absolute inset-0 flex items-center justify-center"
                style={swap(action === "send", reduced)}
              >
                <ArrowUp className="size-4" />
              </span>
              <span
                aria-hidden="true"
                className="absolute inset-0 flex items-center justify-center"
                style={swap(action === "stop", reduced)}
              >
                <Square fill="currentColor" className="size-3" />
              </span>
              <span
                aria-hidden="true"
                className="absolute inset-0 flex items-center justify-center"
                style={swap(action === "wait", reduced)}
              >
                <span
                  className={`size-3.5 rounded-full border-[1.5px] border-current/35 border-t-current motion-reduce:animate-none ${action === "wait" ? "animate-spin" : ""}`}
                />
              </span>
            </button>
          </div>
        </div>

        <div
          aria-hidden="true"
          className="pointer-events-none absolute inset-0 flex items-center justify-center rounded-[20px] bg-background/85 text-[13px] font-medium text-foreground"
          style={{
            opacity: dragging ? 1 : 0,
            transition: reduced ? "none" : `opacity 200ms ${MORPH}`,
          }}
        >
          Drop files to attach
        </div>
      </form>
    </div>
  );
}

"use client";

import * as React from "react";
import { Pause, Play } from "lucide-react";
import { PromptComposer, type ComposerStatus } from "./prompt-composer";
import {
  AnswerActions,
  StreamingText,
  type AnswerSegment,
  type AnswerSource,
} from "./streaming-answer";
import { ThinkingTrace } from "./thinking-trace";
import { ToolCall, type ToolCallStatus } from "./tool-call";
import {
  WebResearch,
  type ResearchSource,
  type ResearchStatus,
} from "./web-research";

/* ─────────────────────────────────────────────────────────
 * AGENT PLAYBACK: your product, working, on a loop
 *
 *   typing     the prompt types itself into the composer, with
 *              a person's uneven rhythm
 *   sent       the text lifts out of the composer and glides
 *              into the message bubble; Send becomes a spinner
 *   working    the agent's blocks arrive one by one, each opening
 *              its own room so what's above glides up: a thinking
 *              trace ticking off steps, web research stacking
 *              sources, a tool call filling in its arguments
 *   answering  the answer streams in word by word, citations and
 *              all, then its actions settle in underneath
 *   next       a beat to read it, then the conversation dissolves
 *              and the next prompt starts typing
 *
 * Built from the real components (composer, thinking trace, web
 * research, tool call, streaming answer), so the hero shows
 * exactly what the product does. It pauses off-screen and in a
 * hidden tab, has its own pause button, and with reduced motion
 * shows the finished first conversation, still.
 * ───────────────────────────────────────────────────────── */

export type PlaybackStep =
  | {
      type: "thinking";
      steps: string[];
      label?: string;
      variant?: "steps" | "reasoning";
    }
  | { type: "search"; queries: { query: string; sources: ResearchSource[] }[] }
  | {
      type: "tool";
      name: string;
      title?: string;
      icon?: React.ReactNode;
      /** Fills in field by field, as a model writes the arguments. */
      input: Record<string, unknown>;
      output?: unknown;
      renderOutput?: (output: unknown) => React.ReactNode;
      /** How long it runs (ms); shown as its run time. */
      duration?: number;
      /** Show the arguments and result. Default true. */
      open?: boolean;
    }
  | {
      type: "answer";
      content: AnswerSegment[] | string;
      sources?: AnswerSource[];
    };

export interface PlaybackTurn {
  prompt: string;
  steps: PlaybackStep[];
}

export interface AgentPlaybackProps extends React.HTMLAttributes<HTMLDivElement> {
  /** The conversations to play, in order. */
  turns: PlaybackTurn[];
  /** Pace: 2 plays twice as fast. */
  speed?: number;
  /** How long a finished answer stays before the next prompt (ms). */
  hold?: number;
  /** Start again after the last turn. */
  loop?: boolean;
  /** Pause from outside, e.g. while a dialog is open. */
  paused?: boolean;
  placeholder?: string;
  /** Above the conversation, e.g. your product's name. */
  header?: React.ReactNode;
  /** The window's height; it never changes, so the page around it never moves. */
  height?: number;
}

type Block =
  | {
      id: number;
      type: "thinking";
      labels: string[];
      status: "running" | "done";
      startedAt: number;
      label?: string;
      variant: "steps" | "reasoning";
    }
  | {
      id: number;
      type: "search";
      status: ResearchStatus;
      queries: string[];
      sources: ResearchSource[];
    }
  | {
      id: number;
      type: "tool";
      step: Extract<PlaybackStep, { type: "tool" }>;
      status: ToolCallStatus;
      input: Record<string, unknown>;
    }
  | {
      id: number;
      type: "answer";
      content: AnswerSegment[];
      status: "streaming" | "done";
      sources?: AnswerSource[];
    };

type View = {
  turn: number;
  draft: string;
  sent: string | null;
  composer: ComposerStatus;
  blocks: Block[];
  leaving: boolean;
};

const MORPH = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const EMPTY: View = {
  turn: 0,
  draft: "",
  sent: null,
  composer: "ready",
  blocks: [],
  leaving: false,
};

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Icons trade places through a blur: the old one shrinks away as the new one grows in. */
const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 260ms ${MORPH}, transform 380ms ${MORPH}, filter 260ms ${MORPH}`,
});

/** Words and spaces as separate tokens, citations whole, so an answer can stream a few at a time. */
function tokens(content: AnswerSegment[] | string): AnswerSegment[] {
  const parts: AnswerSegment[] =
    typeof content === "string" ? [content] : content;
  return parts.flatMap((p): AnswerSegment[] =>
    typeof p === "string" ? p.split(/(\s+)/).filter(Boolean) : [p],
  );
}

/** The finished state of a turn, for reduced motion. */
function settled(turn: PlaybackTurn, index: number): View {
  let id = 0;
  const blocks: Block[] = turn.steps.map((step) => {
    id += 1;
    if (step.type === "thinking")
      return {
        id,
        type: "thinking",
        labels: step.steps,
        status: "done",
        startedAt: 0,
        label: step.label,
        variant: step.variant ?? "steps",
      };
    if (step.type === "search")
      return {
        id,
        type: "search",
        status: "done",
        queries: step.queries.map((q) => q.query),
        sources: step.queries.flatMap((q) => q.sources),
      };
    if (step.type === "tool")
      return { id, type: "tool", step, status: "done", input: step.input };
    return {
      id,
      type: "answer",
      content: tokens(step.content),
      status: "done",
      sources: step.sources,
    };
  });
  return {
    turn: index,
    draft: "",
    sent: turn.prompt,
    composer: "ready",
    blocks,
    leaving: false,
  };
}

/**
 * A clock whose waits can be paused mid-way and resumed for the time that was left,
 * so going off-screen (or pressing pause) freezes the story exactly where it is.
 */
function createClock() {
  let paused = false;
  let wait: {
    resolve: () => void;
    left: number;
    since: number;
    timer: number;
  } | null = null;
  const start = () => {
    if (!wait) return;
    wait.since = performance.now();
    wait.timer = window.setTimeout(
      () => {
        const done = wait?.resolve;
        wait = null;
        done?.();
      },
      Math.max(0, wait.left),
    );
  };
  return {
    sleep(ms: number) {
      return new Promise<void>((resolve) => {
        wait = { resolve, left: ms, since: 0, timer: 0 };
        if (!paused) start();
      });
    },
    pause() {
      if (paused) return;
      paused = true;
      if (wait?.timer) {
        window.clearTimeout(wait.timer);
        wait.left -= performance.now() - wait.since;
        wait.timer = 0;
      }
    },
    resume() {
      if (!paused) return;
      paused = false;
      if (wait && !wait.timer) start();
    },
    stop() {
      if (wait?.timer) window.clearTimeout(wait.timer);
      wait = null;
    },
  };
}

/** A block that opens its own room as it arrives, so everything above glides up instead of jumping. */
function Arrive({
  reduced,
  children,
}: {
  reduced: boolean;
  children: React.ReactNode;
}) {
  const [open, setOpen] = React.useState(reduced);
  React.useEffect(() => {
    if (open) return;
    const frame = requestAnimationFrame(() =>
      requestAnimationFrame(() => setOpen(true)),
    );
    return () => cancelAnimationFrame(frame);
  }, [open]);
  return (
    <div
      className="grid"
      style={{
        gridTemplateRows: open ? "1fr" : "0fr",
        opacity: open ? 1 : 0,
        transform: open ? "none" : "translateY(8px)",
        filter: open ? "none" : "blur(4px)",
        transition: reduced
          ? "none"
          : `grid-template-rows 520ms ${MORPH}, opacity 420ms ${MORPH} 80ms, transform 520ms ${MORPH}, filter 420ms ${MORPH} 80ms`,
      }}
    >
      <div className="min-h-0">{children}</div>
    </div>
  );
}

export function AgentPlayback({
  turns,
  speed = 1,
  hold = 4200,
  loop = true,
  paused = false,
  placeholder = "Ask anything",
  header,
  height = 540,
  className = "",
  ...props
}: AgentPlaybackProps) {
  const reduced = useReducedMotion();
  const [view, setView] = React.useState<View>(EMPTY);
  const [userPaused, setUserPaused] = React.useState(false);
  const [offscreen, setOffscreen] = React.useState(false);
  const [hidden, setHidden] = React.useState(false);
  const rootRef = React.useRef<HTMLDivElement>(null);
  const composerRef = React.useRef<HTMLDivElement>(null);
  const bubbleRef = React.useRef<HTMLDivElement>(null);
  const fromRect = React.useRef<DOMRect | null>(null);
  const clock = React.useMemo(createClock, []);
  const pausedAt = React.useRef<number | null>(null);
  const halted = paused || userPaused || offscreen || hidden;
  // Restart only when the script itself changes, so an inline array in a parent that re-renders is fine.
  const latest = React.useRef(turns);
  React.useLayoutEffect(() => {
    latest.current = turns;
  });
  const scriptKey = turns
    .map((t) => `${t.prompt}\u0000${t.steps.length}`)
    .join("\u0001");

  // Off-screen or in a background tab, the story waits.
  React.useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      ([entry]) => setOffscreen(!entry.isIntersecting),
      { threshold: 0.15 },
    );
    observer.observe(el);
    const onVisibility = () => setHidden(document.visibilityState === "hidden");
    onVisibility();
    document.addEventListener("visibilitychange", onVisibility);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
    };
  }, []);

  // Pausing freezes the clock; on resume, live timers skip the time they were paused for.
  React.useEffect(() => {
    if (halted) {
      clock.pause();
      pausedAt.current ??= Date.now();
      return;
    }
    const since = pausedAt.current;
    pausedAt.current = null;
    clock.resume();
    if (since !== null) {
      const gap = Date.now() - since;
      setView((v) => ({
        ...v,
        blocks: v.blocks.map((b) =>
          b.type === "thinking" && b.status === "running"
            ? { ...b, startedAt: b.startedAt + gap }
            : b,
        ),
      }));
    }
  }, [halted, clock]);

  // The script.
  React.useEffect(() => {
    const turns = latest.current;
    if (!turns.length) return;
    if (reduced) {
      setView(settled(turns[0], 0));
      return;
    }
    let alive = true;
    let id = 0;
    const pace = (ms: number) => clock.sleep(ms / Math.max(0.1, speed));
    const update = (fn: (v: View) => View) => alive && setView(fn);
    const patch = (blockId: number, fn: (b: Block) => Block) =>
      update((v) => ({
        ...v,
        blocks: v.blocks.map((b) => (b.id === blockId ? fn(b) : b)),
      }));

    const play = async () => {
      for (let t = 0; alive; t = (t + 1) % turns.length) {
        const turn = turns[t];
        update(() => ({ ...EMPTY, turn: t }));
        await pace(700);

        // A person typing: quick runs, small pauses after words and punctuation.
        for (let i = 1; i <= turn.prompt.length && alive; i++) {
          update((v) => ({ ...v, draft: turn.prompt.slice(0, i) }));
          const ch = turn.prompt[i - 1];
          await pace(
            /[,.?!]/.test(ch)
              ? 180
              : ch === " "
                ? 70 + Math.random() * 60
                : 26 + Math.random() * 34,
          );
        }
        if (!alive) return;
        await pace(420);

        // Send: note where the text sits in the composer so the bubble can glide out of it.
        const field = composerRef.current?.querySelector("textarea");
        fromRect.current = field?.getBoundingClientRect() ?? null;
        update((v) => ({
          ...v,
          draft: "",
          sent: turn.prompt,
          composer: "submitted",
        }));
        await pace(650);

        for (const step of turn.steps) {
          if (!alive) return;
          const blockId = ++id;
          if (step.type === "thinking") {
            update((v) => ({
              ...v,
              composer: "streaming",
              blocks: [
                ...v.blocks,
                {
                  id: blockId,
                  type: "thinking",
                  labels: [],
                  status: "running",
                  startedAt: Date.now(),
                  label: step.label,
                  variant: step.variant ?? "steps",
                },
              ],
            }));
            for (const label of step.steps) {
              await pace(650 + Math.random() * 350);
              patch(blockId, (b) =>
                b.type === "thinking"
                  ? { ...b, labels: [...b.labels, label] }
                  : b,
              );
            }
            await pace(900);
            patch(blockId, (b) =>
              b.type === "thinking" ? { ...b, status: "done" } : b,
            );
            await pace(700);
          } else if (step.type === "search") {
            update((v) => ({
              ...v,
              composer: "streaming",
              blocks: [
                ...v.blocks,
                {
                  id: blockId,
                  type: "search",
                  status: "searching",
                  queries: [],
                  sources: [],
                },
              ],
            }));
            for (const group of step.queries) {
              patch(blockId, (b) =>
                b.type === "search"
                  ? {
                      ...b,
                      status: "searching",
                      queries: [...b.queries, group.query],
                    }
                  : b,
              );
              await pace(1150);
              for (const source of group.sources) {
                patch(blockId, (b) =>
                  b.type === "search"
                    ? {
                        ...b,
                        status: "reading",
                        sources: [...b.sources, source],
                      }
                    : b,
                );
                await pace(360 + Math.random() * 160);
              }
              await pace(300);
            }
            patch(blockId, (b) =>
              b.type === "search" ? { ...b, status: "done" } : b,
            );
            await pace(650);
          } else if (step.type === "tool") {
            update((v) => ({
              ...v,
              composer: "streaming",
              blocks: [
                ...v.blocks,
                {
                  id: blockId,
                  type: "tool",
                  step,
                  status: "preparing",
                  input: {},
                },
              ],
            }));
            for (const [key, value] of Object.entries(step.input)) {
              await pace(280 + Math.random() * 140);
              patch(blockId, (b) =>
                b.type === "tool"
                  ? { ...b, input: { ...b.input, [key]: value } }
                  : b,
              );
            }
            await pace(350);
            patch(blockId, (b) =>
              b.type === "tool" ? { ...b, status: "running" } : b,
            );
            await pace(step.duration ?? 1300);
            patch(blockId, (b) =>
              b.type === "tool" ? { ...b, status: "done" } : b,
            );
            await pace(800);
          } else {
            const all = tokens(step.content);
            update((v) => ({
              ...v,
              composer: "streaming",
              blocks: [
                ...v.blocks,
                {
                  id: blockId,
                  type: "answer",
                  content: [],
                  status: "streaming",
                  sources: step.sources,
                },
              ],
            }));
            await pace(250);
            for (let i = 0; i < all.length && alive;) {
              i = Math.min(all.length, i + 1 + Math.floor(Math.random() * 3));
              const shown = all.slice(0, i);
              patch(blockId, (b) =>
                b.type === "answer" ? { ...b, content: shown } : b,
              );
              await pace(38 + Math.random() * 46);
            }
            patch(blockId, (b) =>
              b.type === "answer" ? { ...b, status: "done" } : b,
            );
          }
        }
        update((v) => ({ ...v, composer: "ready" }));
        await pace(hold);
        if (!loop && t === turns.length - 1) return;
        // The conversation dissolves before the next one starts.
        update((v) => ({ ...v, leaving: true }));
        await pace(520);
      }
    };
    play();
    return () => {
      alive = false;
      clock.stop();
    };
  }, [scriptKey, speed, hold, loop, reduced, clock]);

  // The sent text glides from where it was typed into its bubble.
  React.useLayoutEffect(() => {
    const bubble = bubbleRef.current;
    const from = fromRect.current;
    fromRect.current = null;
    if (!bubble || !from || reduced) return;
    const to = bubble.getBoundingClientRect();
    const dx = from.left + 14 - (to.left + 16);
    const dy = from.top + 12 - (to.top + 10);
    bubble.animate(
      [
        {
          transform: `translate(${dx}px, ${dy}px)`,
          backgroundColor: "transparent",
        },
        {
          transform: "none",
          backgroundColor: getComputedStyle(bubble).backgroundColor,
        },
      ],
      { duration: 620, easing: MORPH },
    );
  }, [view.sent, reduced]);

  const turn = turns[view.turn];

  return (
    <div
      ref={rootRef}
      role="region"
      aria-roledescription="demo"
      aria-label="Product demo"
      className={`relative flex flex-col overflow-hidden rounded-[22px] border border-border bg-background ${className}`}
      style={{ height }}
      {...props}
    >
      {/* What the demo shows, for people who can't watch it; the moving copy is hidden from them. */}
      <p className="sr-only">
        {turn
          ? `A looping demo. Someone asks: “${turn.prompt}”, and the assistant works through it and answers.`
          : ""}
      </p>

      {header && (
        <div className="flex h-11 shrink-0 items-center border-b border-border px-4 pr-12 text-[13px] font-medium text-foreground">
          {header}
        </div>
      )}

      <button
        type="button"
        aria-label={userPaused ? "Play demo" : "Pause demo"}
        aria-pressed={userPaused}
        onClick={() => setUserPaused((p) => !p)}
        className={`cursor-pointer absolute right-2.5 top-2 z-10 flex size-7 items-center justify-center rounded-full bg-background text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)] transition-colors hover:text-foreground ${FOCUS}`}
      >
        <span
          aria-hidden="true"
          className="absolute inset-0 flex items-center justify-center"
          style={swap(!userPaused, reduced)}
        >
          <Pause className="size-3" fill="currentColor" strokeWidth={0} />
        </span>
        <span
          aria-hidden="true"
          className="absolute inset-0 flex items-center justify-center"
          style={swap(userPaused, reduced)}
        >
          <Play
            className="size-3 translate-x-px"
            fill="currentColor"
            strokeWidth={0}
          />
        </span>
      </button>

      <div aria-hidden="true" inert className="flex min-h-0 flex-1 flex-col">
        {/* The conversation sits on the composer and grows upwards; older lines fade out at the top. */}
        <div className="relative min-h-0 flex-1 overflow-hidden [mask-image:linear-gradient(to_bottom,transparent,#000_56px)]">
          <div
            key={view.turn}
            className="absolute inset-x-0 bottom-0 flex flex-col gap-4 px-4 pb-4 sm:px-5"
            style={{
              opacity: view.leaving ? 0 : 1,
              filter: view.leaving ? "blur(6px)" : "none",
              transform: view.leaving ? "translateY(-12px)" : "none",
              transition: reduced
                ? "none"
                : `opacity 480ms ${MORPH}, filter 480ms ${MORPH}, transform 520ms ${MORPH}`,
            }}
          >
            {view.sent && (
              // Not wrapped in Arrive: its own glide out of the composer is the entrance.
              <div className="flex justify-end">
                <div
                  ref={bubbleRef}
                  className="max-w-[85%] whitespace-pre-wrap rounded-[20px] bg-muted px-4 py-2.5 text-[14px] leading-relaxed text-foreground"
                >
                  {view.sent}
                </div>
              </div>
            )}
            {view.blocks.map((b) => (
              <Arrive key={b.id} reduced={reduced}>
                {b.type === "thinking" ? (
                  <ThinkingTrace
                    variant={b.variant}
                    status={b.status}
                    label={b.label}
                    startedAt={reduced ? undefined : b.startedAt}
                    steps={b.labels.map((label) => ({ label }))}
                  />
                ) : b.type === "search" ? (
                  <WebResearch
                    status={b.status}
                    queries={b.queries}
                    sources={b.sources}
                  />
                ) : b.type === "tool" ? (
                  <ToolCall
                    name={b.step.name}
                    title={b.step.title}
                    icon={b.step.icon}
                    status={b.status}
                    input={b.input}
                    output={b.status === "done" ? b.step.output : undefined}
                    renderOutput={b.step.renderOutput}
                    duration={b.step.duration ?? 1300}
                    defaultOpen={b.step.open ?? true}
                  />
                ) : (
                  <div className="flex flex-col gap-2">
                    <StreamingText
                      content={b.content}
                      status={b.status}
                      className="text-[14px]"
                    />
                    <div
                      className="grid"
                      style={{
                        gridTemplateRows: b.status === "done" ? "1fr" : "0fr",
                        opacity: b.status === "done" ? 1 : 0,
                        transition: reduced
                          ? "none"
                          : `grid-template-rows 420ms ${MORPH}, opacity 360ms ${MORPH} 120ms`,
                      }}
                    >
                      <div className="min-h-0 overflow-hidden">
                        <AnswerActions copyText="" sources={b.sources} />
                      </div>
                    </div>
                  </div>
                )}
              </Arrive>
            ))}
          </div>
        </div>

        <div ref={composerRef} className="shrink-0 px-3 pb-3">
          <PromptComposer
            value={view.draft}
            status={view.composer}
            placeholder={placeholder}
            onSubmit={() => {}}
            onStop={() => {}}
          />
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import {
  EASE_OUT,
  INTERACTION_FOCUS,
  INTERACTION_PRESS,
  interactionIcon,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * ALERT: a message that sits in the page
 *
 *   tone     info, success, warning or danger: the tint, line and
 *            icon ease across when the tone changes (a sync that
 *            goes from "Syncing" to "Synced"), the icon swapping
 *            through a blur
 *   dismiss  the ✕ folds the alert away: it fades and lifts while
 *            its height closes, so the content below slides up
 *            instead of jumping
 *   action   an optional button on the right (or under it on
 *            narrow cards)
 * ───────────────────────────────────────────────────────── */

export type AlertTone = "info" | "success" | "warning" | "danger";

export interface AlertProps {
  tone?: AlertTone;
  title: React.ReactNode;
  children?: React.ReactNode;
  /** A button or link at the end. */
  action?: React.ReactNode;
  /** Show a ✕; called after the alert has folded away. */
  onDismiss?: () => void;
  /** Hide it (folds away) without unmounting. */
  hidden?: boolean;
  /** Replace the tone's icon. */
  icon?: React.ReactNode;
  className?: string;
}

const TONE: Record<AlertTone, string> = {
  info: "bg-card shadow-[inset_0_0_0_1px_var(--border)] text-foreground",
  success:
    "bg-emerald-500/[0.06] shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-emerald-500)_30%,transparent)] text-foreground",
  warning:
    "bg-amber-500/[0.07] shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-amber-500)_35%,transparent)] text-foreground",
  danger:
    "bg-red-500/[0.06] shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_30%,transparent)] text-foreground",
};
const ICON_TONE: Record<AlertTone, string> = {
  info: "text-muted-foreground",
  success: "text-emerald-600 dark:text-emerald-400",
  warning: "text-amber-600 dark:text-amber-400",
  danger: "text-red-600 dark:text-red-400",
};

const ICONS: Record<AlertTone, React.ReactNode> = {
  info: (
    <svg viewBox="0 0 16 16" fill="none" className="size-4">
      <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeWidth="1.5" />
      <path
        d="M8 7.25v3.5"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
      />
      <circle cx="8" cy="5" r="0.9" fill="currentColor" />
    </svg>
  ),
  success: (
    <svg viewBox="0 0 16 16" fill="none" className="size-4">
      <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeWidth="1.5" />
      <path
        d="M5.4 8.2 7.2 10l3.4-3.8"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  ),
  warning: (
    <svg viewBox="0 0 16 16" fill="none" className="size-4">
      <path
        d="M8 2.2 14.3 13H1.7L8 2.2Z"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinejoin="round"
      />
      <path
        d="M8 6.3v3.2"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
      />
      <circle cx="8" cy="11.2" r="0.85" fill="currentColor" />
    </svg>
  ),
  danger: (
    <svg viewBox="0 0 16 16" fill="none" className="size-4">
      <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeWidth="1.5" />
      <path
        d="M8 4.75v3.75"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
      />
      <circle cx="8" cy="11" r="0.9" fill="currentColor" />
    </svg>
  ),
};

export function Alert({
  tone = "info",
  title,
  children,
  action,
  onDismiss,
  hidden: hiddenProp,
  icon,
  className = "",
}: AlertProps) {
  const reduced = useInteractionReducedMotion();
  const [dismissed, setDismissed] = React.useState(false);
  const hidden = hiddenProp || dismissed;

  React.useEffect(() => {
    if (!dismissed) return;
    const timer = window.setTimeout(() => onDismiss?.(), reduced ? 0 : 380);
    return () => window.clearTimeout(timer);
  }, [dismissed, onDismiss, reduced]);

  return (
    <div
      className="grid w-full"
      aria-hidden={hidden || undefined}
      inert={hidden || undefined}
      style={{
        gridTemplateRows: hidden ? "0fr" : "1fr",
        transition: reduced
          ? "none"
          : `grid-template-rows 380ms ${EASE_OUT} ${hidden ? 80 : 0}ms`,
      }}
    >
      <div className="min-h-0 overflow-hidden [clip-path:inset(-2px)]">
        <div
          role={tone === "danger" || tone === "warning" ? "alert" : "status"}
          className={`@container flex items-start gap-3 rounded-[14px] p-3.5 transition-[background-color,box-shadow] duration-300 ${TONE[tone]} ${className}`}
          style={{
            opacity: hidden ? 0 : 1,
            translate: hidden && !reduced ? "0 -6px" : "0 0",
            scale: hidden && !reduced ? "0.98" : "1",
            transition: reduced
              ? "none"
              : `opacity 220ms ${EASE_OUT}, translate 320ms ${EASE_OUT}, scale 320ms ${EASE_OUT}, background-color 300ms, box-shadow 300ms`,
          }}
        >
          <span
            className={`relative mt-px size-4 shrink-0 transition-colors duration-300 ${ICON_TONE[tone]}`}
            aria-hidden="true"
          >
            {icon
              ? icon
              : (Object.keys(ICONS) as AlertTone[]).map((t) => (
                  <span
                    key={t}
                    className="absolute inset-0"
                    style={interactionIcon(t === tone, reduced)}
                  >
                    {ICONS[t]}
                  </span>
                ))}
          </span>
          <div className="flex min-w-0 flex-1 flex-col gap-2.5 @md:flex-row @md:items-start @md:justify-between">
            <div className="flex min-w-0 flex-col gap-0.5">
              <p className="text-[13.5px] font-medium leading-5">{title}</p>
              {children && (
                <div className="text-[13px] leading-relaxed text-muted-foreground">
                  {children}
                </div>
              )}
            </div>
            {action && (
              <div className="flex shrink-0 items-center gap-2">{action}</div>
            )}
          </div>
          {onDismiss && (
            <button
              type="button"
              aria-label="Dismiss"
              onClick={() => setDismissed(true)}
              className={`-mr-1 -mt-1 flex size-7 shrink-0 items-center justify-center rounded-full text-muted-foreground cursor-pointer hover:bg-accent hover:text-foreground ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`}
            >
              <svg viewBox="0 0 16 16" fill="none" className="size-3.5">
                <path
                  d="M4 4l8 8M12 4l-8 8"
                  stroke="currentColor"
                  strokeWidth="1.6"
                  strokeLinecap="round"
                />
              </svg>
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

export default Alert;

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * ANNOUNCEMENT PILL: "New: …" that opens into the news
 *
 *   rest    a badge and one line, in a thin line pill
 *   hover   the arrow nudges on and a second phrase folds open
 *           ("Read the changelog")
 *   open    the pill itself grows into a card with the details:
 *           its size and corners ease from pill to card while
 *           the line cross-fades into the content
 *   close   the card folds back into the pill
 *
 * Without card content it's simply a link.
 * ───────────────────────────────────────────────────────── */

export interface AnnouncementPillProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "children"
> {
  badge?: string;
  children: React.ReactNode;
  /** A second phrase that folds open on hover. */
  more?: string;
  /** Without card, the pill is a link to here. */
  href?: string;
  /** What the pill opens into. */
  card?: React.ReactNode;
  cardWidth?: number;
}

type Phase = "closed" | "opening" | "open" | "closing";

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const DURATION = 420;
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function Arrow() {
  return (
    <svg
      aria-hidden="true"
      viewBox="0 0 12 12"
      className="size-3 shrink-0 text-muted-foreground transition-[transform,color] duration-300 group-hover/pill:translate-x-0.5 group-hover/pill:text-foreground"
    >
      <path
        d="M2.5 6h7M6.5 3l3 3-3 3"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.4"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

export function AnnouncementPill({
  badge = "New",
  children,
  more,
  href,
  card,
  cardWidth = 360,
  className = "",
  ...props
}: AnnouncementPillProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const [phase, setPhase] = React.useState<Phase>("closed");
  const [pill, setPill] = React.useState({ width: 0, height: 32 });
  const [cardSize, setCardSize] = React.useState({
    width: cardWidth,
    height: 0,
  });
  const [moreWidth, setMoreWidth] = React.useState(0);
  const wrapRef = React.useRef<HTMLDivElement>(null);
  const pillRef = React.useRef<HTMLElement | null>(null);
  const cardRef = React.useRef<HTMLDivElement>(null);
  const moreRef = React.useRef<HTMLSpanElement>(null);
  const timer = React.useRef(0);

  const expanded = phase === "open";
  const mounted = phase !== "closed";

  React.useLayoutEffect(() => {
    const el = pillRef.current;
    if (!el) return;
    const measure = () =>
      setPill((p) =>
        p.width === el.offsetWidth && p.height === el.offsetHeight
          ? p
          : { width: el.offsetWidth, height: el.offsetHeight },
      );
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  React.useLayoutEffect(() => {
    const el = moreRef.current;
    if (el) setMoreWidth(el.offsetWidth);
  }, [more]);

  React.useLayoutEffect(() => {
    const el = cardRef.current;
    if (!el) return;
    const measure = () => {
      const width = Math.min(
        cardWidth,
        document.documentElement.clientWidth - 32,
      );
      setCardSize((c) =>
        c.width === width && c.height === el.offsetHeight
          ? c
          : { width, height: el.offsetHeight },
      );
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, [mounted, cardWidth]);

  const open = () => {
    window.clearTimeout(timer.current);
    setPhase(reduced ? "open" : "opening");
  };

  const close = React.useCallback(
    (refocus = true) => {
      window.clearTimeout(timer.current);
      if (refocus) pillRef.current?.focus({ preventScroll: true });
      if (reduced) return setPhase("closed");
      setPhase("closing");
      timer.current = window.setTimeout(() => setPhase("closed"), DURATION);
    },
    [reduced],
  );

  // Paint the surface at the pill's size first, then let it grow.
  React.useEffect(() => {
    if (phase !== "opening") return;
    let inner = 0;
    const outer = requestAnimationFrame(
      () => (inner = requestAnimationFrame(() => setPhase("open"))),
    );
    return () => {
      cancelAnimationFrame(outer);
      cancelAnimationFrame(inner);
    };
  }, [phase]);

  React.useEffect(() => () => window.clearTimeout(timer.current), []);

  React.useEffect(() => {
    if (!expanded) return;
    cardRef.current
      ?.querySelector<HTMLElement>("a[href], button")
      ?.focus({ preventScroll: true });
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && close();
    const onDown = (e: PointerEvent) =>
      !wrapRef.current?.contains(e.target as Node) && close(false);
    document.addEventListener("keydown", onKey);
    document.addEventListener("pointerdown", onDown);
    return () => {
      document.removeEventListener("keydown", onKey);
      document.removeEventListener("pointerdown", onDown);
    };
  }, [expanded, close]);

  const line = (
    <>
      <span className="flex h-6 shrink-0 items-center rounded-full bg-primary/10 px-2 text-[11.5px] font-medium text-primary">
        {badge}
      </span>
      <span className="whitespace-nowrap text-[13px] text-foreground">
        {children}
      </span>
      {more && (
        <span
          className="flex overflow-hidden whitespace-nowrap text-[13px] text-muted-foreground transition-[max-width,opacity] duration-500 group-hover/pill:opacity-100 group-focus-visible/pill:opacity-100 [max-width:0] group-hover/pill:[max-width:var(--more)] group-focus-visible/pill:[max-width:var(--more)] opacity-0"
          style={
            {
              "--more": `${moreWidth}px`,
              transitionTimingFunction: EASE,
            } as React.CSSProperties
          }
        >
          <span
            ref={moreRef}
            className="flex w-max shrink-0 items-center gap-1.5 pl-0.5"
          >
            <span aria-hidden="true" className="text-border">
              ·
            </span>
            {more}
          </span>
        </span>
      )}
      <Arrow />
    </>
  );

  const pillClass = `group/pill inline-flex h-8 items-center gap-2 rounded-full bg-background pl-1 pr-3 shadow-[inset_0_0_0_1px_var(--border)] transition-[box-shadow] duration-300 hover:shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--foreground)_22%,transparent)] ${FOCUS}`;

  if (!card) {
    return (
      <div className={`inline-flex ${className}`} {...props}>
        <a
          ref={(el) => void (pillRef.current = el)}
          href={href}
          className={pillClass}
        >
          {line}
        </a>
      </div>
    );
  }

  return (
    <div
      ref={wrapRef}
      className={`relative inline-flex ${className}`}
      {...props}
    >
      <button
        ref={(el) => void (pillRef.current = el)}
        type="button"
        aria-expanded={expanded}
        aria-controls={mounted ? `${id}-card` : undefined}
        onClick={() => (expanded ? close() : open())}
        className={`cursor-pointer ${pillClass} ${mounted ? "opacity-0" : ""}`}
      >
        {line}
      </button>

      {mounted && (
        <div
          id={`${id}-card`}
          role="dialog"
          aria-label={typeof children === "string" ? children : "Announcement"}
          className="absolute left-1/2 top-0 z-50 overflow-hidden bg-popover text-left text-popover-foreground"
          style={{
            width: expanded ? cardSize.width : pill.width,
            height: expanded ? cardSize.height : pill.height,
            transform: "translateX(-50%)",
            borderRadius: expanded ? 22 : pill.height / 2,
            boxShadow: "inset 0 0 0 1px var(--border)",
            transition: reduced
              ? "none"
              : `width ${DURATION}ms ${EASE}, height ${DURATION}ms ${EASE}, border-radius ${DURATION}ms ${EASE}`,
          }}
        >
          {/* The pill's line, fading out as the card grows and back in as it folds. */}
          <span
            aria-hidden="true"
            className="pointer-events-none absolute left-1/2 top-0 flex h-8 -translate-x-1/2 items-center gap-2 pl-1 pr-3"
            style={{
              opacity: expanded ? 0 : 1,
              transition: reduced
                ? "none"
                : expanded
                  ? "opacity 120ms ease-out"
                  : "opacity 200ms ease-out 180ms",
            }}
          >
            {line}
          </span>
          <div
            ref={cardRef}
            inert={!expanded}
            className="absolute left-0 top-0"
            style={{
              width: cardSize.width,
              opacity: expanded ? 1 : 0,
              transform: expanded ? "none" : "translateY(-6px)",
              transition: reduced
                ? "none"
                : expanded
                  ? `opacity 260ms ease-out 140ms, transform ${DURATION}ms ${EASE}`
                  : "opacity 100ms ease-out",
            }}
          >
            <button
              type="button"
              aria-label="Close"
              onClick={() => close()}
              className={`cursor-pointer absolute right-2.5 top-2.5 z-10 flex size-7 items-center justify-center rounded-full text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
            >
              <svg aria-hidden="true" viewBox="0 0 12 12" className="size-3">
                <path
                  d="M3 3l6 6M9 3l-6 6"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="1.5"
                  strokeLinecap="round"
                />
              </svg>
            </button>
            {card}
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import * as React from "react";
import { Copy, Plus, RotateCw, Trash2 } from "lucide-react";
import { ConfirmAction } from "./confirm-action";
import { NumberRoll } from "./number-roll";
import {
  formatDate,
  RelativeTime,
  toTime,
  type DateLike,
} from "./relative-time";
import { StatusButton, type ActionStatus } from "./status-button";
import { useRowMotion } from "./use-row-motion";

/* ─────────────────────────────────────────────────────────
 * API KEYS: the settings screen, done properly
 *
 *   create    "Create key" opens a row at the top of the list
 *             (the rows below glide down): a name, the scopes,
 *             Create. That same row becomes the new key
 *   reveal    the secret rises in under it character by
 *             character, with Copy and Done; it is never kept
 *             anywhere but on screen
 *   seal      Done folds the secret away: its prefix and last
 *             four characters fly up into the key's chip as the
 *             rest blurs out, so "sk_live_••••4f2a" is visibly
 *             what's left of the key you just saw
 *   roll      the old key's chip lifts away, the new secret
 *             rises in where it was, and the old key (if your
 *             server keeps it alive) counts down to its expiry
 *             in the row below
 *   revoke    the bin's own circle stretches into "Revoke";
 *             a check draws, then the row folds away and the
 *             rest glide up
 *
 * Keys are plain records; every change is one async function
 * that returns what your server stored.
 * ───────────────────────────────────────────────────────── */

export type { DateLike };

export interface ApiKey {
  id: string;
  name: string;
  /** The part of the key you show before the dots, e.g. "sk_live_". */
  prefix?: string;
  /** The last characters of the key, e.g. "4f2a". */
  last4: string;
  scopes?: string[];
  createdAt?: DateLike;
  lastUsedAt?: DateLike | null;
  /** A rolled key keeps working until then; it counts down in its row. */
  expiresAt?: DateLike | null;
}

export interface ApiKeyScope {
  value: string;
  label: string;
}

export interface ApiKeyCreated {
  key: ApiKey;
  /** The whole secret, shown once. */
  secret: string;
}

export interface ApiKeyRolled extends ApiKeyCreated {
  /** The old key as your server now keeps it (with expiresAt), if it still works for a while. */
  previous?: ApiKey | null;
}

export interface ApiKeysProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "defaultValue" | "onChange"
> {
  value?: ApiKey[];
  defaultValue?: ApiKey[];
  onValueChange?: (keys: ApiKey[]) => void;
  /** Creates the key. Return it with its secret; throw to keep the form and say why. */
  onCreate: (input: {
    name: string;
    scopes: string[];
  }) => Promise<ApiKeyCreated>;
  /** Replaces a key with a new secret. Without it there is no Roll button. */
  onRoll?: (key: ApiKey) => Promise<ApiKeyRolled>;
  /** Revokes a key. Without it there is no Revoke button. */
  onRevoke?: (key: ApiKey) => Promise<unknown> | unknown;
  /** What a key may do. Without it the form doesn't ask. */
  scopes?: ApiKeyScope[];
  /** Scopes a new key starts with; all of them by default. */
  defaultScopes?: string[];
  title?: string;
  description?: string;
  /** The name field's placeholder. */
  placeholder?: string;
}

type Draft = {
  rk: string;
  name: string;
  scopes: string[];
  status: ActionStatus;
  error: string | null;
};
type Reveal = { id: string; secret: string; sealing: boolean };
type Actions = {
  setDraft: (patch: Partial<Draft>) => void;
  submit: () => void;
  cancel: () => void;
  seal: (id: string) => void;
  roll: (key: ApiKey) => Promise<void>;
  revoke: (key: ApiKey) => Promise<void>;
};

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const NONE: ApiKey[] = [];
const DAY = 86_400_000;

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const masked = (k: ApiKey) => `${k.prefix ?? ""}••••${k.last4}`;
const message = (e: unknown, fallback: string) =>
  e instanceof Error && e.message ? e.message : fallback;

/** Text as one inline-block per character, so characters can be found and flown; lines still break between them. */
function Chars({ text }: { text: string }) {
  return (
    <>
      {Array.from(text).map((ch, i) => (
        <span key={i} data-ch={i} className="inline-block">
          {ch}
        </span>
      ))}
    </>
  );
}

/** A block that opens and closes by height; it keeps its last children while it closes. */
function Fold({
  open,
  reduced,
  children,
}: {
  open: boolean;
  reduced: boolean;
  children: React.ReactNode;
}) {
  return (
    <div
      className="grid"
      inert={!open}
      style={{
        gridTemplateRows: open ? "1fr" : "0fr",
        transition: reduced ? "none" : `grid-template-rows 460ms ${EASE}`,
      }}
    >
      <div className="min-h-0 overflow-clip">{children}</div>
    </div>
  );
}

/** "Expires in 23:59:41", rolling down a second at a time; a date when it's further off. */
function Expiry({ at }: { at: number }) {
  const [now, setNow] = React.useState<number | null>(null);
  const left = now === null ? null : at - now;
  const ticking = left !== null && left > 0 && left < 2 * DAY;

  React.useEffect(() => {
    if (now === null) {
      const timer = window.setTimeout(() => setNow(Date.now()), 0);
      return () => window.clearTimeout(timer);
    }
    if (!ticking) return;
    const timer = window.setTimeout(
      () => setNow(Date.now()),
      1000 - (Date.now() % 1000) + 10,
    );
    return () => window.clearTimeout(timer);
  }, [now, ticking]);

  if (left === null) return null;
  if (left <= 0)
    return <span className="text-red-600 dark:text-red-400">Expired</span>;
  if (!ticking) return <span>Expires {formatDate(at)}</span>;
  const s = Math.floor(left / 1000);
  const two = { minimumIntegerDigits: 2 };
  return (
    <span className="inline-flex items-baseline whitespace-nowrap tabular-nums text-amber-700 dark:text-amber-400">
      <span className="sr-only">
        Expires{" "}
        {new Date(at).toLocaleString("en-GB", {
          dateStyle: "medium",
          timeStyle: "short",
        })}
      </span>
      <span aria-hidden="true" className="inline-flex items-baseline">
        Expires in&nbsp;
        <NumberRoll value={Math.floor(s / 3600)} direction="down" />:
        <NumberRoll
          value={Math.floor(s / 60) % 60}
          format={two}
          direction="down"
        />
        :
        <NumberRoll value={s % 60} format={two} direction="down" />
      </span>
    </span>
  );
}

function ScopeChip({
  scope,
  on,
  reduced,
  onToggle,
}: {
  scope: ApiKeyScope;
  on: boolean;
  reduced: boolean;
  onToggle: () => void;
}) {
  return (
    <button
      type="button"
      aria-pressed={on}
      onClick={onToggle}
      className={`inline-flex h-7 cursor-pointer items-center rounded-full px-2.5 text-[12px] font-medium transition-[background-color,color,box-shadow] duration-200 ${FOCUS} ${
        on
          ? "bg-accent text-foreground shadow-[inset_0_0_0_1px_var(--border)]"
          : "text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:text-foreground"
      }`}
    >
      <span
        className="grid"
        style={{
          gridTemplateColumns: on ? "1fr" : "0fr",
          transition: reduced ? "none" : `grid-template-columns 320ms ${EASE}`,
        }}
      >
        <span className="min-w-0 overflow-clip">
          <svg
            viewBox="0 0 16 16"
            fill="none"
            aria-hidden="true"
            className="mr-1 size-3.5"
          >
            <path
              d="M3.5 8.5 6.5 11.5 12.5 4.5"
              stroke="currentColor"
              strokeWidth="1.8"
              strokeLinecap="round"
              strokeLinejoin="round"
              pathLength={1}
              strokeDasharray={1}
              style={{
                strokeDashoffset: on ? 0 : 1,
                transition: reduced
                  ? "none"
                  : `stroke-dashoffset 360ms ${EASE} ${on ? 120 : 0}ms`,
              }}
            />
          </svg>
        </span>
      </span>
      {scope.label}
    </button>
  );
}

function DraftFace({
  draft,
  scopes,
  placeholder,
  reduced,
  act,
}: {
  draft: Draft;
  scopes?: ApiKeyScope[];
  placeholder: string;
  reduced: boolean;
  act: React.RefObject<Actions>;
}) {
  const id = React.useId();
  const inputRef = React.useRef<HTMLInputElement>(null);
  const lineRef = React.useRef<HTMLParagraphElement>(null);
  const busy = draft.status === "pending";
  const line = draft.error ?? "The secret is shown once, when it's created.";

  React.useEffect(() => {
    inputRef.current?.focus({ preventScroll: true });
  }, []);

  // A new line under the form lifts in; the field shakes when the error is about it.
  React.useLayoutEffect(() => {
    if (reduced || !draft.error) return;
    lineRef.current?.animate(
      [
        { opacity: 0, transform: "translateY(4px)", filter: "blur(3px)" },
        { opacity: 1, transform: "none", filter: "blur(0px)" },
      ],
      { duration: 320, easing: EASE },
    );
    if (!draft.name.trim())
      inputRef.current?.animate(
        [
          { transform: "none" },
          { transform: "translateX(-4px)" },
          { transform: "translateX(4px)" },
          { transform: "translateX(-2px)" },
          { transform: "none" },
        ],
        { duration: 380, easing: "ease-out" },
      );
  }, [draft.error]);

  return (
    <form
      className="px-4 py-3.5 @md:px-5"
      onSubmit={(e) => {
        e.preventDefault();
        act.current.submit();
      }}
      onKeyDown={(e) => {
        if (e.key === "Escape" && !busy) {
          e.preventDefault();
          act.current.cancel();
        }
      }}
    >
      <label
        htmlFor={`${id}-name`}
        className="text-[11.5px] text-muted-foreground"
      >
        New key
      </label>
      <input
        ref={inputRef}
        id={`${id}-name`}
        value={draft.name}
        readOnly={busy}
        onChange={(e) =>
          act.current.setDraft({
            name: e.target.value,
            error: null,
            status: "idle",
          })
        }
        placeholder={placeholder}
        autoComplete="off"
        aria-invalid={Boolean(draft.error) || undefined}
        aria-describedby={`${id}-line`}
        className={`mt-1 h-9 w-full rounded-[10px] bg-transparent px-3 text-[16px] text-foreground outline-none transition-shadow duration-200 placeholder:text-muted-foreground/70 read-only:opacity-60 [@media(pointer:fine)]:text-[13.5px] ${
          draft.error
            ? "shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_45%,transparent)]"
            : "shadow-[inset_0_0_0_1px_var(--border)] focus:shadow-[inset_0_0_0_1px_var(--ring)]"
        }`}
      />
      {scopes && scopes.length > 0 && (
        <div
          role="group"
          aria-label="Scopes"
          className="mt-2.5 flex flex-wrap gap-1.5"
        >
          {scopes.map((s) => {
            const on = draft.scopes.includes(s.value);
            return (
              <ScopeChip
                key={s.value}
                scope={s}
                on={on}
                reduced={reduced}
                onToggle={() =>
                  act.current.setDraft({
                    scopes: on
                      ? draft.scopes.filter((v) => v !== s.value)
                      : [...draft.scopes, s.value],
                    error: null,
                    status: "idle",
                  })
                }
              />
            );
          })}
        </div>
      )}
      <div className="mt-3 flex flex-wrap items-center justify-end gap-x-3 gap-y-2">
        <p
          ref={lineRef}
          id={`${id}-line`}
          className={`mr-auto min-w-0 text-[11.5px] ${draft.error ? "text-red-600 dark:text-red-400" : "text-muted-foreground"}`}
        >
          {line}
        </p>
        <div className="flex items-center gap-1">
          <button
            type="button"
            onClick={() => act.current.cancel()}
            disabled={busy}
            className={`h-7 cursor-pointer rounded-full px-2.5 text-[12px] font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground disabled:cursor-default disabled:opacity-50 ${FOCUS}`}
          >
            Cancel
          </button>
          <StatusButton
            type="submit"
            size="sm"
            status={draft.status}
            labels={{
              idle: "Create key",
              pending: "Creating",
              success: "Created",
              error: "Try again",
            }}
          />
        </div>
      </div>
    </form>
  );
}

function SecretBlock({
  secret,
  reduced,
  blockRef,
}: {
  secret: string;
  reduced: boolean;
  blockRef: React.RefObject<HTMLElement | null>;
}) {
  // The secret rises in a character at a time, the whole of it inside half a second.
  React.useLayoutEffect(() => {
    const el = blockRef.current;
    if (!el || reduced) return;
    const chars = el.querySelectorAll<HTMLElement>("[data-ch]");
    const step = Math.min(10, 420 / Math.max(1, chars.length));
    chars.forEach((c, i) =>
      c.animate(
        [
          { opacity: 0, filter: "blur(4px)", transform: "translateY(0.35em)" },
          { opacity: 1, filter: "blur(0px)", transform: "none" },
        ],
        {
          duration: 360,
          delay: 140 + i * step,
          easing: EASE,
          fill: "backwards",
        },
      ),
    );
  }, [secret]);

  return (
    <code
      ref={blockRef as React.RefObject<HTMLElement>}
      className="block rounded-[10px] bg-muted px-3 py-2.5 font-mono text-[12px] leading-[1.6] break-all text-foreground shadow-[inset_0_0_0_1px_var(--border)]"
    >
      <Chars text={secret} />
    </code>
  );
}

interface RowProps {
  rk: string;
  apiKey: ApiKey | null;
  draft: Draft | null;
  reveal: Reveal | null;
  scopes?: ApiKeyScope[];
  placeholder: string;
  gone: boolean;
  canRoll: boolean;
  canRevoke: boolean;
  reduced: boolean;
  act: React.RefObject<Actions>;
}

const Row = React.memo(function Row({
  rk,
  apiKey,
  draft,
  reveal,
  scopes,
  placeholder,
  gone,
  canRoll,
  canRevoke,
  reduced,
  act,
}: RowProps) {
  const outerRef = React.useRef<HTMLLIElement>(null);
  const chipRef = React.useRef<HTMLSpanElement>(null);
  const blockRef = React.useRef<HTMLElement>(null);
  const height = React.useRef(0);
  const face = apiKey ? "key" : "draft";
  const lastFace = React.useRef(face);
  const [keptDraft, setKeptDraft] = React.useState(draft);
  if (draft && draft !== keptDraft) setKeptDraft(draft);
  // The form stays on screen, fading, in the same commit the key takes its place.
  const [faceSeen, setFaceSeen] = React.useState(face);
  const [leavingDraft, setLeavingDraft] = React.useState(false);
  if (faceSeen !== face) {
    setFaceSeen(face);
    setLeavingDraft(face === "key" && !reduced);
  }
  const shown = reveal && !reveal.sealing;
  // The secret stays in the fold while it closes, then leaves the page.
  const [kept, setKept] = React.useState<string | null>(reveal?.secret ?? null);
  if (reveal && reveal.secret !== kept) setKept(reveal.secret);
  if (!reveal && kept !== null) setKept(null);

  React.useLayoutEffect(() => {
    const el = outerRef.current;
    if (!el) return;
    const observer = new ResizeObserver(
      () => (height.current = el.offsetHeight),
    );
    height.current = el.offsetHeight;
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  // The form became the key: the row eases from the form's height to the key's while the form fades out over it.
  React.useLayoutEffect(() => {
    if (lastFace.current === face) return;
    lastFace.current = face;
    const el = outerRef.current;
    if (!el || reduced || face !== "key") return;
    const to = el.offsetHeight;
    if (Math.abs(to - height.current) > 0.5)
      el.animate([{ height: `${height.current}px` }, { height: `${to}px` }], {
        duration: 460,
        easing: EASE,
      });
  }, [face, reduced]);

  React.useEffect(() => {
    if (!leavingDraft) return;
    const timer = window.setTimeout(() => setLeavingDraft(false), 320);
    return () => window.clearTimeout(timer);
  }, [leavingDraft]);

  // Done: the prefix and last four fly from the secret into the chip; the rest blurs out as the fold closes.
  const sealing = Boolean(reveal?.sealing);
  React.useLayoutEffect(() => {
    if (!sealing || !apiKey || !reveal) return;
    const chip = chipRef.current;
    const block = blockRef.current;
    if (!chip || !block || reduced) return;
    const from = [...block.querySelectorAll<HTMLElement>("[data-ch]")];
    const to = [...chip.querySelectorAll<HTMLElement>("[data-ch]")];
    const text = masked(apiKey);
    const secret = reveal.secret;
    const pairs = new Map<number, number>();
    const prefix = apiKey.prefix ?? "";
    if (prefix && secret.startsWith(prefix))
      for (let i = 0; i < prefix.length; i++) pairs.set(i, i);
    if (secret.endsWith(apiKey.last4))
      for (let j = 0; j < apiKey.last4.length; j++)
        pairs.set(
          text.length - apiKey.last4.length + j,
          secret.length - apiKey.last4.length + j,
        );
    const flown = new Set(pairs.values());
    to.forEach((c, i) => {
      const source = pairs.get(i);
      if (source === undefined || !from[source]) {
        c.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: "translateY(0.35em)",
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          { duration: 380, delay: 220, easing: EASE, fill: "backwards" },
        );
        return;
      }
      const a = from[source].getBoundingClientRect();
      const b = c.getBoundingClientRect();
      // Together, so "sk_live_" and the last four travel as words.
      c.animate(
        [
          { transform: `translate(${a.left - b.left}px, ${a.top - b.top}px)` },
          { transform: "none" },
        ],
        { duration: 540, easing: EASE, fill: "backwards" },
      );
    });
    from.forEach((c, i) => {
      if (flown.has(i))
        c.animate([{ opacity: 0 }, { opacity: 0 }], {
          duration: 600,
          fill: "forwards",
        });
      else
        c.animate(
          [
            { opacity: 1, filter: "blur(0px)" },
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: "translateY(-0.3em)",
            },
          ],
          { duration: 220, easing: EASE, fill: "forwards" },
        );
    });
  }, [sealing]);

  const hide = Boolean(reveal) && !sealing;
  // While the chip is hidden it keeps the old key's characters, so a roll never flashes the new ones.
  const [chipText, setChipText] = React.useState(apiKey ? masked(apiKey) : "");
  if (apiKey && !hide && chipText !== masked(apiKey))
    setChipText(masked(apiKey));

  const scopeText = apiKey?.scopes?.length
    ? apiKey.scopes
        .map((v) => scopes?.find((s) => s.value === v)?.label ?? v)
        .join(", ")
    : null;
  const expires = apiKey?.expiresAt ? toTime(apiKey.expiresAt) : null;

  return (
    <li
      ref={outerRef}
      data-row-id={rk}
      className="relative overflow-clip border-t border-border first:border-t-0"
    >
      {apiKey ? (
        <div
          className="px-4 py-3 transition-opacity duration-300 @md:px-5"
          style={{ opacity: gone ? 0.5 : 1 }}
        >
          <div className="flex min-h-7 items-center gap-2">
            <p className="min-w-0 flex-1 truncate text-[13.5px] font-medium tracking-[-0.01em]">
              {apiKey.name}
            </p>
            <span
              ref={chipRef}
              className="relative inline-flex h-[22px] shrink-0 items-center px-1.5 font-mono text-[11.5px] text-foreground"
            >
              <span
                aria-hidden="true"
                className="absolute inset-0 rounded-md bg-muted shadow-[inset_0_0_0_1px_var(--border)]"
                style={{
                  opacity: hide ? 0 : 1,
                  transition: reduced
                    ? "none"
                    : `opacity ${hide ? 200 : 420}ms ${EASE} ${hide ? 0 : 160}ms`,
                }}
              />
              <span className="sr-only">{`Key ending ${apiKey.last4}`}</span>
              <span
                aria-hidden="true"
                className="relative whitespace-nowrap"
                style={{
                  opacity: hide ? 0 : 1,
                  filter: hide && !reduced ? "blur(3px)" : "none",
                  transition:
                    hide && !reduced
                      ? `opacity 200ms ${EASE}, filter 200ms ${EASE}`
                      : "none",
                }}
              >
                <Chars text={chipText} />
              </span>
            </span>
            {(canRoll || canRevoke) && (
              <div className="-mr-1 flex items-center">
                {canRoll && !expires && (
                  <ConfirmAction
                    tone="default"
                    icon={<RotateCw strokeWidth={1.75} />}
                    label={`Roll ${apiKey.name}`}
                    labels={{
                      idle: "Roll key",
                      pending: "Rolling",
                      success: "Rolled",
                      error: "Try again",
                    }}
                    onConfirm={() => act.current.roll(apiKey)}
                    resetAfter={1400}
                  />
                )}
                {canRevoke && (
                  <ConfirmAction
                    icon={<Trash2 strokeWidth={1.75} />}
                    label={`Revoke ${apiKey.name}`}
                    labels={{
                      idle: "Revoke",
                      pending: "Revoking",
                      success: "Revoked",
                      error: "Try again",
                    }}
                    onConfirm={() => act.current.revoke(apiKey)}
                  />
                )}
              </div>
            )}
          </div>
          <p className="mt-0.5 flex flex-wrap items-baseline gap-x-1.5 text-[11.5px] text-muted-foreground">
            {scopeText && (
              <>
                <span>{scopeText}</span>
                <span aria-hidden="true">·</span>
              </>
            )}
            {apiKey.createdAt != null && (
              <>
                <span>Created {formatDate(apiKey.createdAt)}</span>
                <span aria-hidden="true">·</span>
              </>
            )}
            {expires !== null ? (
              <Expiry at={expires} />
            ) : apiKey.lastUsedAt ? (
              <RelativeTime date={apiKey.lastUsedAt} prefix="Last used" />
            ) : (
              <span>Never used</span>
            )}
          </p>
          <Fold open={Boolean(shown)} reduced={reduced}>
            {kept && (
              <div className="pt-3">
                <SecretBlock
                  key={kept}
                  secret={kept}
                  reduced={reduced}
                  blockRef={blockRef}
                />
                <div className="mt-2.5 flex flex-wrap items-center justify-end gap-x-3 gap-y-2">
                  <p className="mr-auto text-[11.5px] text-muted-foreground">
                    Copy it now. You won&rsquo;t see it again.
                  </p>
                  <div className="flex items-center gap-1">
                    <button
                      type="button"
                      onClick={() => act.current.seal(apiKey.id)}
                      className={`h-7 cursor-pointer rounded-full px-2.5 text-[12px] font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
                    >
                      Done
                    </button>
                    <CopyButton secret={kept} autoFocus={Boolean(shown)} />
                  </div>
                </div>
              </div>
            )}
          </Fold>
        </div>
      ) : null}
      {(face === "draft" || leavingDraft) && (draft ?? keptDraft) && (
        <FaceOut leaving={face !== "draft"}>
          <DraftFace
            draft={(draft ?? keptDraft)!}
            scopes={scopes}
            placeholder={placeholder}
            reduced={reduced}
            act={act}
          />
        </FaceOut>
      )}
    </li>
  );
});

/** The form, fading out through a blur over the key that took its place. */
function FaceOut({
  leaving,
  children,
}: {
  leaving: boolean;
  children: React.ReactNode;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  React.useLayoutEffect(() => {
    if (!leaving) return;
    ref.current?.animate(
      [
        { opacity: 1, filter: "blur(0px)" },
        { opacity: 0, filter: "blur(4px)" },
      ],
      { duration: 260, easing: EASE, fill: "forwards" },
    );
  }, [leaving]);
  return (
    <div
      ref={ref}
      className={leaving ? "pointer-events-none absolute inset-x-0 top-0" : ""}
      inert={leaving}
      aria-hidden={leaving || undefined}
    >
      {children}
    </div>
  );
}

function CopyButton({
  secret,
  autoFocus,
}: {
  secret: string;
  autoFocus: boolean;
}) {
  const [status, setStatus] = React.useState<ActionStatus>("idle");
  const wrap = React.useRef<HTMLSpanElement>(null);
  React.useEffect(() => {
    if (autoFocus)
      wrap.current?.querySelector("button")?.focus({ preventScroll: true });
  }, [autoFocus]);
  return (
    <span ref={wrap} className="contents">
      <StatusButton
        size="sm"
        status={status}
        icon={<Copy strokeWidth={1.75} />}
        labels={{
          idle: "Copy",
          pending: "Copying",
          success: "Copied",
          error: "Try again",
        }}
        onReset={() => setStatus("idle")}
        onClick={async () => {
          setStatus("pending");
          try {
            await navigator.clipboard.writeText(secret);
            setStatus("success");
          } catch {
            setStatus("error");
          }
        }}
      />
    </span>
  );
}

export function ApiKeys({
  value,
  defaultValue = NONE,
  onValueChange,
  onCreate,
  onRoll,
  onRevoke,
  scopes,
  defaultScopes,
  title = "API keys",
  description = "Keys give your code access to this workspace. Keep them out of the browser.",
  placeholder = "e.g. Production server",
  className = "",
  ...props
}: ApiKeysProps) {
  const reduced = useReducedMotion();
  const [inner, setInner] = React.useState(defaultValue);
  const keys = value ?? inner;
  const [draft, setDraftState] = React.useState<Draft | null>(null);
  const [reveal, setReveal] = React.useState<Reveal | null>(null);
  const [alias, setAlias] = React.useState<Record<string, string>>({});
  const [gone, setGone] = React.useState<string[]>([]);
  const [announce, setAnnounce] = React.useState("");
  const listRef = React.useRef<HTMLUListElement>(null);
  const ghostRef = React.useRef<HTMLDivElement>(null);
  const createRef = React.useRef<HTMLButtonElement>(null);
  const counter = React.useRef(0);
  const latest = React.useRef({ keys, draft, alias });
  latest.current = { keys, draft, alias };

  const commit = (next: ApiKey[]) => {
    if (value === undefined) setInner(next);
    onValueChange?.(next);
  };
  const rkOf = (id: string, a = alias) => a[id] ?? id;

  const rows: { rk: string; apiKey: ApiKey | null }[] = [
    ...(draft ? [{ rk: draft.rk, apiKey: null }] : []),
    ...keys.map((k) => ({ rk: rkOf(k.id), apiKey: k })),
  ];
  const ranks = React.useMemo(
    () => new Map(rows.map((r, i) => [r.rk, i])),
    [rows.map((r) => r.rk).join("|")],
  );
  useRowMotion(listRef, { reduced, ranks, ghosts: ghostRef });

  const act = React.useRef<Actions>(null!);
  act.current = {
    setDraft: (patch) => setDraftState((d) => (d ? { ...d, ...patch } : d)),
    cancel: () => {
      setDraftState(null);
      requestAnimationFrame(() =>
        createRef.current?.focus({ preventScroll: true }),
      );
    },
    submit: async () => {
      const d = latest.current.draft;
      if (!d || d.status === "pending") return;
      const name = d.name.trim();
      if (!name)
        return setDraftState({
          ...d,
          error: "Give the key a name, so you know where it's used.",
          status: "idle",
        });
      if (scopes?.length && !d.scopes.length)
        return setDraftState({
          ...d,
          error: "Pick at least one scope.",
          status: "idle",
        });
      setDraftState({ ...d, status: "pending", error: null });
      try {
        const { key, secret } = await onCreate({ name, scopes: d.scopes });
        // One commit: the form's row becomes the key's row and opens on its secret.
        setAlias((a) => ({ ...a, [key.id]: d.rk }));
        commit([key, ...latest.current.keys]);
        setDraftState(null);
        setReveal({ id: key.id, secret, sealing: false });
        setAnnounce(
          `${key.name} created. Copy the secret now; it won't be shown again.`,
        );
      } catch (e) {
        setDraftState(
          (cur) =>
            cur && {
              ...cur,
              status: "error",
              error: message(e, "The key couldn't be created. Try again."),
            },
        );
      }
    },
    seal: (id) => {
      setReveal((r) => (r && r.id === id ? { ...r, sealing: true } : r));
      setAnnounce("Secret hidden.");
      window.setTimeout(
        () => setReveal((r) => (r && r.id === id && r.sealing ? null : r)),
        620,
      );
      requestAnimationFrame(() =>
        createRef.current?.focus({ preventScroll: true }),
      );
    },
    roll: async (key) => {
      if (!onRoll) return;
      const { key: next, secret, previous } = await onRoll(key);
      const { keys: now, alias: a } = latest.current;
      const rk = rkOf(key.id, a);
      setAlias((cur) => ({
        ...cur,
        [next.id]: rk,
        ...(previous ? { [previous.id]: `${rk}~${++counter.current}` } : {}),
      }));
      commit(
        now.flatMap((k) =>
          k.id === key.id ? [next, ...(previous ? [previous] : [])] : [k],
        ),
      );
      setReveal({ id: next.id, secret, sealing: false });
      setAnnounce(
        `${next.name} rolled. Copy the new secret now; it won't be shown again.`,
      );
    },
    revoke: async (key) => {
      await onRevoke?.(key);
      setGone((g) => [...g, key.id]);
      setAnnounce(`${key.name} revoked.`);
      // Long enough for the check to draw; then the row folds away.
      window.setTimeout(() => {
        commit(latest.current.keys.filter((k) => k.id !== key.id));
        setGone((g) => g.filter((id) => id !== key.id));
        setReveal((r) => (r?.id === key.id ? null : r));
      }, 700);
    },
  };

  const openDraft = () => {
    if (draft) return;
    setDraftState({
      rk: `draft-${++counter.current}`,
      name: "",
      scopes: defaultScopes ?? scopes?.map((s) => s.value) ?? [],
      status: "idle",
      error: null,
    });
  };

  return (
    <div
      className={`@container w-full rounded-[22px] border border-border bg-background text-foreground ${className}`}
      {...props}
    >
      <div className="flex items-start justify-between gap-3 px-4 pt-4 pb-3.5 @md:px-5 @md:pt-5">
        <div className="min-w-0">
          <p className="flex items-baseline gap-2 text-[14px] font-medium tracking-[-0.01em]">
            {title}
            <span className="text-[12px] font-normal text-muted-foreground tabular-nums">
              <NumberRoll value={keys.length} />
            </span>
          </p>
          <p className="mt-0.5 text-[12px] text-muted-foreground">
            {description}
          </p>
        </div>
        <button
          ref={createRef}
          type="button"
          onClick={openDraft}
          aria-disabled={Boolean(draft) || undefined}
          className={`inline-flex h-7 shrink-0 cursor-pointer items-center gap-1.5 rounded-full px-3 text-[12px] font-medium shadow-[inset_0_0_0_1px_var(--border)] transition-[background-color,opacity] duration-200 hover:bg-accent aria-disabled:cursor-default aria-disabled:opacity-40 aria-disabled:hover:bg-transparent ${FOCUS}`}
        >
          <Plus className="size-3.5" strokeWidth={1.75} aria-hidden="true" />
          Create key
        </button>
      </div>

      <div className="relative border-t border-border">
        <ul ref={listRef} aria-label={title} className="relative">
          {rows.map((r) => (
            <Row
              key={r.rk}
              rk={r.rk}
              apiKey={r.apiKey}
              draft={r.apiKey ? null : draft}
              reveal={r.apiKey && reveal?.id === r.apiKey.id ? reveal : null}
              scopes={scopes}
              placeholder={placeholder}
              gone={Boolean(r.apiKey && gone.includes(r.apiKey.id))}
              canRoll={Boolean(onRoll)}
              canRevoke={Boolean(onRevoke)}
              reduced={reduced}
              act={act}
            />
          ))}
        </ul>
        {/* Rows that went: their own elements, folding away where they stood (see use-row-motion). */}
        <div
          ref={ghostRef}
          aria-hidden="true"
          className="pointer-events-none absolute inset-0"
        />
        <Fold open={!rows.length} reduced={reduced}>
          <p className="px-4 py-6 text-center text-[12.5px] text-muted-foreground @md:px-5">
            No keys yet. Create one to call the API from your server.
          </p>
        </Fold>
      </div>

      <span className="sr-only" role="status">
        {announce}
      </span>
    </div>
  );
}

"use client";

import * as React from "react";
import { Ban, Clock, ShieldQuestion } from "lucide-react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * APPROVAL CARD: the agent asks before it acts
 *
 *   pending   what it wants to do, with Approve and Deny; an
 *             optional countdown rolls down second by second
 *   approved  the card folds into one line: the body closes,
 *             "Needs your approval" morphs to "Approved" and a
 *             check draws itself where the shield was
 *   denied    folds the same way into "Denied"
 *   expired   the countdown reaches 0:00 and it folds into
 *             "Expired"
 *
 * One surface throughout: it changes shape instead of being
 * replaced. Works controlled (pass status) or on its own (it
 * remembers the choice). Mark destructive actions so Approve
 * reads as such.
 * ───────────────────────────────────────────────────────── */

export type ApprovalStatus = "pending" | "approved" | "denied" | "expired";

export interface ApprovalDetail {
  label: string;
  value: React.ReactNode;
}

export interface ApprovalCardProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "title"
> {
  /** What the agent wants to do, e.g. "Send email to 3 people". */
  title: string;
  description?: string;
  /** The specifics worth checking before approving. */
  details?: ApprovalDetail[];
  /** Why approval is needed, e.g. AI SDK's approval.requestReason. */
  reason?: string;
  status?: ApprovalStatus;
  defaultStatus?: ApprovalStatus;
  onApprove?: () => void;
  onDeny?: () => void;
  approveLabel?: string;
  denyLabel?: string;
  /** Styles Approve as a destructive action. */
  destructive?: boolean;
  /** When the request lapses (ms). Shows a countdown, then expires. */
  expiresAt?: number;
  onExpire?: () => void;
}

const MORPH = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const LABELS: Record<ApprovalStatus, string> = {
  pending: "Needs your approval",
  approved: "Approved",
  denied: "Denied",
  expired: "Expired",
};

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Icons trade places through a blur: the old one shrinks away as the new one grows in. */
const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 260ms ${MORPH}, transform 380ms ${MORPH}, filter 260ms ${MORPH}`,
});

function DrawnCheck({ drawn, reduced }: { drawn: boolean; reduced: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="none" className="size-3.5">
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 420ms ${MORPH} 160ms`
              : "none",
        }}
      />
    </svg>
  );
}

export function ApprovalCard({
  title,
  description,
  details,
  reason,
  status,
  defaultStatus = "pending",
  onApprove,
  onDeny,
  approveLabel = "Approve",
  denyLabel = "Deny",
  destructive = false,
  expiresAt,
  onExpire,
  className = "",
  ...props
}: ApprovalCardProps) {
  const reduced = useReducedMotion();
  const [ownStatus, setOwnStatus] =
    React.useState<ApprovalStatus>(defaultStatus);
  const current = status ?? ownStatus;
  const decided = current !== "pending";
  const [now, setNow] = React.useState(expiresAt ?? 0);
  const cardRef = React.useRef<HTMLDivElement>(null);

  // Count down while pending; expire on time.
  React.useEffect(() => {
    if (current !== "pending" || expiresAt === undefined) return;
    const tick = () => {
      const t = Date.now();
      setNow(t);
      if (t >= expiresAt) {
        if (status === undefined) setOwnStatus("expired");
        onExpire?.();
      }
    };
    tick();
    const timer = window.setInterval(tick, 1000);
    return () => window.clearInterval(timer);
  }, [current, expiresAt, status, onExpire]);

  const decide = (next: "approved" | "denied") => {
    // The buttons are about to fold away: keep focus on the card instead of dropping it on the page.
    if (cardRef.current?.contains(document.activeElement))
      cardRef.current.focus({ preventScroll: true });
    if (status === undefined) setOwnStatus(next);
    if (next === "approved") onApprove?.();
    else onDeny?.();
  };

  const left =
    expiresAt === undefined
      ? 0
      : Math.max(0, Math.ceil((expiresAt - now) / 1000));
  const icons: Record<ApprovalStatus, React.ReactNode> = {
    pending: <ShieldQuestion className="size-3.5" />,
    approved: (
      <span className="text-emerald-600 dark:text-emerald-400">
        <DrawnCheck drawn={current === "approved"} reduced={reduced} />
      </span>
    ),
    denied: <Ban className="size-3.5" />,
    expired: <Clock className="size-3.5" />,
  };
  const fold = (open: boolean): React.CSSProperties => ({
    gridTemplateRows: open ? "1fr" : "0fr",
    transition: reduced ? "none" : `grid-template-rows 480ms ${MORPH}`,
  });
  const fade = (on: boolean): React.CSSProperties => ({
    opacity: on ? 1 : 0,
    filter: on ? "none" : "blur(4px)",
    transition: reduced
      ? "none"
      : on
        ? `opacity 380ms ${MORPH} 120ms, filter 380ms ${MORPH} 120ms`
        : `opacity 160ms ease-out, filter 160ms ease-out`,
  });

  return (
    <div
      ref={cardRef}
      tabIndex={-1}
      role="group"
      aria-label={
        decided ? `${LABELS[current]}: ${title}` : `Approval needed: ${title}`
      }
      className={`rounded-xl border border-border bg-background outline-none animate-[ui-fade-up_320ms_cubic-bezier(0.23,1,0.32,1)_both] motion-reduce:animate-none ${className}`}
      style={{
        padding: decided ? "10px 12px" : 16,
        transition: reduced ? "none" : `padding 480ms ${MORPH}`,
      }}
      {...props}
    >
      {/* The header is also the folded line: it keeps its place while everything under it closes. */}
      <div className="flex min-w-0 items-center gap-2 text-[12.5px] font-medium">
        <span
          aria-hidden="true"
          className={`relative flex size-3.5 shrink-0 items-center justify-center transition-colors duration-300 ${decided ? "text-foreground/70" : "text-muted-foreground"}`}
        >
          {(Object.keys(icons) as ApprovalStatus[]).map((s) => (
            <span
              key={s}
              className="absolute inset-0 flex items-center justify-center"
              style={swap(s === current, reduced)}
            >
              {icons[s]}
            </span>
          ))}
        </span>
        <span
          className={`shrink-0 transition-colors duration-300 ${decided ? "text-foreground" : "text-muted-foreground"}`}
        >
          <TextMorph>{LABELS[current]}</TextMorph>
        </span>
        {/* The action slides into the line as the card folds. */}
        <span
          aria-hidden={!decided || undefined}
          className="grid min-w-0 flex-1"
          style={{
            gridTemplateColumns: decided ? "1fr" : "0fr",
            ...fade(decided),
            transition: reduced
              ? "none"
              : `grid-template-columns 480ms ${MORPH}, ${decided ? `opacity 380ms ${MORPH} 160ms, filter 380ms ${MORPH} 160ms` : "opacity 160ms ease-out, filter 160ms ease-out"}`,
          }}
        >
          <span className="min-w-0 truncate font-normal text-muted-foreground">
            {title}
          </span>
        </span>
        {expiresAt !== undefined && (
          <span
            aria-hidden={decided || undefined}
            className="ml-auto grid shrink-0"
            style={{
              gridTemplateColumns: decided ? "0fr" : "1fr",
              ...fade(!decided),
              transition: reduced
                ? "none"
                : `grid-template-columns 480ms ${MORPH}, opacity 160ms ease-out, filter 160ms ease-out`,
            }}
          >
            <span className="flex min-w-0 overflow-hidden font-mono font-normal tabular-nums text-muted-foreground">
              <span className="sr-only">Time left: </span>
              <NumberRoll value={Math.floor(left / 60)} duration={600} />
              <span aria-hidden="true">:</span>
              <NumberRoll
                value={left % 60}
                format={{ minimumIntegerDigits: 2 }}
                direction="down"
                duration={600}
              />
            </span>
          </span>
        )}
      </div>

      {/* Everything else folds shut once it's answered. */}
      <div
        inert={decided}
        aria-hidden={decided || undefined}
        className="grid"
        style={fold(!decided)}
      >
        <div className="min-h-0 overflow-hidden">
          <div style={fade(!decided)}>
            <p className="pt-2 text-[14px] font-medium leading-snug text-foreground">
              {title}
            </p>
            {description && (
              <p className="mt-1 text-[13px] leading-relaxed text-muted-foreground">
                {description}
              </p>
            )}

            {details && details.length > 0 && (
              <dl className="mt-3 grid grid-cols-[minmax(0,auto)_1fr] gap-x-4 gap-y-1.5 rounded-lg bg-muted px-3 py-2.5 text-[12.5px]">
                {details.map((d) => (
                  <React.Fragment key={d.label}>
                    <dt className="text-muted-foreground">{d.label}</dt>
                    <dd className="min-w-0 break-words text-foreground">
                      {d.value}
                    </dd>
                  </React.Fragment>
                ))}
              </dl>
            )}

            {reason && (
              <p className="mt-2.5 text-[12px] leading-relaxed text-muted-foreground">
                {reason}
              </p>
            )}

            <div className="mt-4 flex justify-end gap-2">
              <button
                type="button"
                onClick={() => decide("denied")}
                className={`cursor-pointer h-8 rounded-lg border border-border px-3 text-[12.5px] font-medium text-foreground transition-colors hover:bg-accent ${FOCUS}`}
              >
                {denyLabel}
              </button>
              <button
                type="button"
                onClick={() => decide("approved")}
                className={`cursor-pointer h-8 rounded-lg px-3.5 text-[12.5px] font-medium transition-[background-color,transform] active:scale-[0.98] ${FOCUS} ${
                  destructive
                    ? "bg-red-600 text-white hover:bg-red-700"
                    : "bg-primary text-primary-foreground hover:bg-primary/90"
                }`}
              >
                {approveLabel}
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Announces the answer; outside the buttons so their names stay their labels. */}
      <span role="status" className="sr-only">
        {decided ? `${LABELS[current]}: ${title}` : ""}
      </span>
    </div>
  );
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * AREA CHART: several series, stacked, overlapping or as shares
 *
 *   arrive    the first time it's on screen the chart draws
 *             itself from left to right and every figure rolls
 *             up from zero
 *   layout    Stacked, Overlap, 100%: the pill is thrown to the
 *             choice and every band morphs to its new place, the
 *             scale rolling to counts or percentages
 *   toggle    the tiles are the legend: press one and its band
 *             shrinks away while the others settle into the room,
 *             press it again and it grows back. Colours stay with
 *             their series
 *   hover     a thin line follows the pointer with a dot on each
 *             band, and the tiles become the readout: the period
 *             morphs to that week and every figure rolls to it
 *
 * The plot is one tab stop: arrow keys move between points and
 * the readout is announced. The tiles are toggle buttons. Every
 * figure is also in a table for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface AreaSeries {
  id: string;
  label: string;
  /** One value per label. */
  values: number[];
}

export type AreaLayout = "stacked" | "overlap" | "percent";

export interface AreaChartProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onChange"
> {
  title?: string;
  /** Under the total, e.g. "orders in the last 12 weeks". */
  caption?: string;
  /** Along the bottom, one per point. */
  labels: string[];
  /** In the readout, e.g. "Week of 28 Sept". Defaults to labels. */
  titles?: string[];
  /** Up to five, in a fixed colour order (--chart-1 to --chart-5). */
  series: AreaSeries[];
  layout?: AreaLayout;
  defaultLayout?: AreaLayout;
  onLayoutChange?: (layout: AreaLayout) => void;
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const PLOT = 200;
const TOP = 10;
const LABELS = 24;
const PAD = 6;
const STEPS = 4;
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const COLORS = [
  "var(--chart-1, var(--primary))",
  "var(--chart-2, #e8743b)",
  "var(--chart-3, #1baf7a)",
  "var(--chart-4, #8b6fe8)",
  "var(--chart-5, #e0a21b)",
];
const LAYOUTS: { id: AreaLayout; label: string }[] = [
  { id: "stacked", label: "Stacked" },
  { id: "overlap", label: "Overlap" },
  { id: "percent", label: "100%" },
];

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function niceTop(value: number) {
  if (value <= 0) return STEPS;
  const raw = value / STEPS;
  const mag = 10 ** Math.floor(Math.log10(raw));
  const step =
    [1, 1.5, 2, 2.5, 3, 4, 5, 6, 8, 10]
      .map((m) => m * mag)
      .find((s) => s >= raw) ?? 10 * mag;
  return step * STEPS;
}

/** A smooth line through the points that never overshoots them (monotone cubic). Works left to right or right to left. */
function monotone(points: [number, number][], move = true) {
  const n = points.length;
  if (!n) return "";
  const r = (v: number) => Math.round(v * 100) / 100;
  const head = `${move ? "M" : "L"}${r(points[0][0])},${r(points[0][1])}`;
  if (n === 1) return head;
  const m: number[] = [];
  for (let i = 0; i < n - 1; i++)
    m.push(
      (points[i + 1][1] - points[i][1]) /
        (points[i + 1][0] - points[i][0] || 1),
    );
  const t: number[] = [m[0]];
  for (let i = 1; i < n - 1; i++)
    t.push(m[i - 1] * m[i] <= 0 ? 0 : (m[i - 1] + m[i]) / 2);
  t.push(m[n - 2]);
  for (let i = 0; i < n - 1; i++) {
    if (m[i] === 0) {
      t[i] = 0;
      t[i + 1] = 0;
      continue;
    }
    const a = t[i] / m[i];
    const b = t[i + 1] / m[i];
    const s = a * a + b * b;
    if (s > 9) {
      const k = 3 / Math.sqrt(s);
      t[i] = k * a * m[i];
      t[i + 1] = k * b * m[i];
    }
  }
  let d = head;
  for (let i = 0; i < n - 1; i++) {
    const [x0, y0] = points[i];
    const [x1, y1] = points[i + 1];
    const dx = (x1 - x0) / 3;
    d += `C${r(x0 + dx)},${r(y0 + t[i] * dx)} ${r(x1 - dx)},${r(y1 - t[i + 1] * dx)} ${r(x1)},${r(y1)}`;
  }
  return d;
}

/** Tweens a list of numbers toward a target, so bands reshape instead of being replaced. */
function useTween(target: number[], reduced: boolean, duration = 620) {
  const [value, setValue] = React.useState(target);
  const from = React.useRef(target);
  const targetRef = React.useRef(target);
  React.useLayoutEffect(() => {
    targetRef.current = target;
  });

  const targetKey = target.join(",");

  React.useEffect(() => {
    from.current = reduced ? target : value;
  });

  React.useEffect(() => {
    if (reduced) return;
    const start = from.current;
    const begin = performance.now();
    let frame = 0;
    const step = (now: number) => {
      const currentTarget = targetRef.current;
      const t = Math.min(1, (now - begin) / duration);
      const e = 1 - Math.pow(1 - t, 4);
      const next = currentTarget.map(
        (v, i) => (start[i] ?? 0) + (v - (start[i] ?? 0)) * e,
      );
      from.current = next;
      setValue(next);
      if (t < 1) frame = requestAnimationFrame(step);
    };
    frame = requestAnimationFrame(step);
    return () => cancelAnimationFrame(frame);
  }, [targetKey, reduced, duration]);

  return reduced ? target : value;
}

export function AreaChart({
  title = "Orders",
  caption,
  labels,
  titles,
  series: allSeries,
  layout: layoutProp,
  defaultLayout = "stacked",
  onLayoutChange,
  format,
  locales,
  className = "",
  ...props
}: AreaChartProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const series = allSeries.slice(0, COLORS.length);
  const [ownLayout, setOwnLayout] = React.useState<AreaLayout>(defaultLayout);
  const layout = layoutProp ?? ownLayout;
  const [hidden, setHidden] = React.useState<Set<string>>(() => new Set());
  const [visible, setVisible] = React.useState(false);
  const [plotH, setPlotH] = React.useState(PLOT);
  const [active, setActive] = React.useState<number | null>(null);
  const [keyboard, setKeyboard] = React.useState(false);
  const [width, setWidth] = React.useState(0);
  const [pill, setPill] = React.useState({ left: 0, width: 0, ready: false });
  const rootRef = React.useRef<HTMLDivElement>(null);
  const chartRef = React.useRef<HTMLDivElement>(null);
  const plotRef = React.useRef<HTMLDivElement>(null);
  const chipRefs = React.useRef<(HTMLButtonElement | null)[]>([]);

  const n = labels.length;
  const on = (s: AreaSeries) => !hidden.has(s.id);
  // Each series as a band [lower, upper] at every point, in the layout's units; a hidden series is a band of no height.
  const bands = React.useMemo(() => {
    const shown = series.map((s) =>
      !hidden.has(s.id) ? s.values : s.values.map(() => 0),
    );
    const sums = labels.map((_, i) =>
      shown.reduce((sum, v) => sum + (v[i] ?? 0), 0),
    );
    const result: { lower: number[]; upper: number[] }[] = [];
    let running = labels.map(() => 0);
    for (const values of shown) {
      if (layout === "overlap") {
        result.push({
          lower: labels.map(() => 0),
          upper: labels.map((_, i) => values[i] ?? 0),
        });
      } else {
        const lower = running;
        const upper = labels.map(
          (_, i) =>
            lower[i] +
            (layout === "percent"
              ? sums[i]
                ? (values[i] ?? 0) / sums[i]
                : 0
              : (values[i] ?? 0)),
        );
        running = upper;
        result.push({ lower, upper });
      }
    }
    return result;
  }, [series, labels, layout, hidden]);
  const max =
    layout === "percent"
      ? 1
      : niceTop(Math.max(0, ...bands.flatMap((b) => b.upper)));
  const flat = useTween(
    [max, ...bands.flatMap((b) => [...b.lower, ...b.upper])],
    reduced,
  );
  const drawnMax = flat[0] || 1;
  const drawn = bands.map((_, s) => ({
    lower: flat.slice(1 + s * 2 * n, 1 + s * 2 * n + n),
    upper: flat.slice(1 + s * 2 * n + n, 1 + (s + 1) * 2 * n),
  }));

  // The plot's height is set by the card's width in CSS; read it so the drawing fits.
  React.useLayoutEffect(() => {
    const el = chartRef.current;
    if (!el) return;
    const measure = () =>
      setPlotH((h) => {
        const next = el.offsetHeight - LABELS;
        return next > 0 && next !== h ? next : h;
      });
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  React.useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          observer.disconnect();
        }
      },
      { rootMargin: "0px 0px -10% 0px" },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  React.useLayoutEffect(() => {
    const el = plotRef.current;
    if (!el) return;
    const measure = () =>
      setWidth((w) => (w === el.offsetWidth ? w : el.offsetWidth));
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  React.useLayoutEffect(() => {
    const el = chipRefs.current[LAYOUTS.findIndex((l) => l.id === layout)];
    if (!el) return;
    setPill((p) =>
      p.left === el.offsetLeft && p.width === el.offsetWidth
        ? p
        : { left: el.offsetLeft, width: el.offsetWidth, ready: p.width > 0 },
    );
  }, [layout]);

  const x = (i: number) =>
    PAD + (n > 1 ? (i * (width - PAD * 2)) / (n - 1) : (width - PAD * 2) / 2);
  const y = (v: number) => TOP + (plotH - TOP) * (1 - v / drawnMax);

  const choose = (next: AreaLayout) => {
    if (next === layout) return;
    if (layoutProp === undefined) setOwnLayout(next);
    onLayoutChange?.(next);
  };
  const toggle = (sid: string) =>
    setHidden((h) => {
      const next = new Set(h);
      if (next.has(sid)) next.delete(sid);
      // Keep at least one series showing.
      else if (series.filter((s) => !next.has(s.id)).length > 1) next.add(sid);
      return next;
    });
  const pointAt = (clientX: number) => {
    const r = plotRef.current?.getBoundingClientRect();
    if (!r || n < 2) return null;
    return Math.min(
      n - 1,
      Math.max(
        0,
        Math.round(((clientX - r.left - PAD) / (r.width - PAD * 2)) * (n - 1)),
      ),
    );
  };
  const onKeyDown = (e: React.KeyboardEvent) => {
    if (!n) return;
    const from = active ?? n - 1;
    const moves: Record<string, number> = {
      ArrowLeft: from - 1,
      ArrowRight: from + 1,
      Home: 0,
      End: n - 1,
    };
    if (e.key === "Escape") return setActive(null);
    if (!(e.key in moves)) return;
    e.preventDefault();
    setKeyboard(true);
    setActive(
      Math.min(n - 1, Math.max(0, active === null ? from : moves[e.key])),
    );
  };

  const fmt = (v: number) => new Intl.NumberFormat(locales, format).format(v);
  const totalOf = (s: AreaSeries) =>
    active !== null
      ? (s.values[active] ?? 0)
      : s.values.reduce((sum, v) => sum + v, 0);
  const shownTotal = series.filter(on).reduce((sum, s) => sum + totalOf(s), 0);
  const scaleFormat: Intl.NumberFormatOptions =
    layout === "percent"
      ? { style: "percent" }
      : {
          ...format,
          notation: "compact",
          minimumFractionDigits: 0,
          maximumFractionDigits: 1,
        };
  const every = width && n ? Math.max(1, Math.ceil(40 / (width / n))) : 1;
  // Labels thin out on narrow screens; the hovered one always shows, and its close neighbours step aside for it.
  const label = (i: number) =>
    active === i ||
    ((n - 1 - i) % every === 0 &&
      (active === null || every === 1 || Math.abs(i - active) >= every));
  const name = (i: number) => titles?.[i] ?? labels[i];

  return (
    <div
      ref={rootRef}
      className={`@container w-full rounded-[22px] bg-background shadow-[0_0_0_1px_var(--border)] ${className}`}
      {...props}
    >
      <div className="p-4 @md:p-5 [--gutter:30px] @md:[--gutter:40px] [--plot:160px] @md:[--plot:200px]">
        {/* The title and its control share a row; the figures sit under both. */}
        <div className="flex flex-wrap items-center justify-between gap-x-3 gap-y-2">
          <p className="text-[12px] text-muted-foreground @md:text-[13px]">
            {title}
          </p>
          <div
            role="radiogroup"
            aria-label="Layout"
            className="relative -my-1 inline-flex shrink-0 rounded-full bg-muted p-0.5"
          >
            <span
              aria-hidden="true"
              className="absolute inset-y-0.5 left-0 rounded-full bg-background shadow-[0_0_0_1px_var(--border)]"
              style={{
                width: pill.width,
                transform: `translateX(${pill.left}px)`,
                transition:
                  pill.ready && !reduced
                    ? `transform 460ms ${THROW}, width 380ms ${EASE}`
                    : "none",
              }}
            />
            {LAYOUTS.map((l, i) => {
              const selected = l.id === layout;
              return (
                <button
                  key={l.id}
                  ref={(el) => {
                    chipRefs.current[i] = el;
                  }}
                  type="button"
                  role="radio"
                  aria-checked={selected}
                  tabIndex={selected ? 0 : -1}
                  onClick={() => choose(l.id)}
                  onKeyDown={(e) => {
                    if (e.key !== "ArrowRight" && e.key !== "ArrowLeft") return;
                    e.preventDefault();
                    const next =
                      (i + (e.key === "ArrowRight" ? 1 : -1) + LAYOUTS.length) %
                      LAYOUTS.length;
                    choose(LAYOUTS[next].id);
                    chipRefs.current[next]?.focus();
                  }}
                  className={`cursor-pointer relative h-6 whitespace-nowrap rounded-full px-2.5 text-[11.5px] font-medium @md:h-7 @md:px-3 @md:text-[12.5px] transition-colors duration-300 ${FOCUS} ${
                    selected
                      ? "text-foreground"
                      : "text-muted-foreground hover:text-foreground"
                  }`}
                >
                  {l.label}
                </button>
              );
            })}
          </div>
        </div>
        <p className="mt-0.5 text-[22px] font-medium leading-tight tracking-[-0.03em] @md:text-[26px] text-foreground">
          <NumberRoll
            value={visible ? shownTotal : 0}
            format={format}
            locales={locales}
            duration={active !== null ? 600 : 1000}
          />
        </p>
        <p className="mt-1 whitespace-nowrap text-[11.5px] text-muted-foreground @md:text-[12.5px]">
          <TextMorph>
            {active !== null ? name(active) : (caption ?? " ")}
          </TextMorph>
        </p>

        <div
          ref={chartRef}
          className="relative mt-4 @md:mt-5"
          style={{ height: `calc(var(--plot) + ${LABELS}px)` }}
        >
          {Array.from({ length: STEPS + 1 }, (_, k) => 1 - k / STEPS).map(
            (f) => (
              <div
                key={f}
                aria-hidden="true"
                className="absolute inset-x-0"
                style={{ top: TOP + (plotH - TOP) * (1 - f) }}
              >
                <span
                  className="absolute left-0 top-0 -translate-y-1/2 text-[10px] leading-none tabular-nums text-muted-foreground/80"
                  style={{
                    width: "calc(var(--gutter) - 8px)",
                    textAlign: "right",
                  }}
                >
                  <NumberRoll
                    value={visible ? max * f : 0}
                    format={scaleFormat}
                    locales={locales}
                    duration={700}
                  />
                </span>
                <div
                  className="border-t border-border"
                  style={{ marginLeft: "var(--gutter)" }}
                />
              </div>
            ),
          )}

          <div
            ref={plotRef}
            role="group"
            tabIndex={0}
            aria-label={`${title}. Use the arrow keys to read each point.`}
            onKeyDown={onKeyDown}
            onBlur={() => keyboard && (setActive(null), setKeyboard(false))}
            onPointerMove={(e) => {
              setKeyboard(false);
              setActive(pointAt(e.clientX));
            }}
            onPointerDown={(e) => setActive(pointAt(e.clientX))}
            onPointerLeave={(e) => e.pointerType === "mouse" && setActive(null)}
            className={`absolute inset-y-0 right-0 touch-pan-y select-none rounded-lg ${FOCUS}`}
            style={{ left: "var(--gutter)" }}
          >
            <div
              className="absolute inset-x-0 top-0"
              style={{
                height: plotH,
                clipPath: visible
                  ? "inset(-8px -8px -8px -8px)"
                  : "inset(-8px 100% -8px -8px)",
                transition: reduced ? "none" : `clip-path 1200ms ${EASE}`,
              }}
            >
              <svg
                aria-hidden="true"
                width={width}
                height={plotH}
                className="absolute inset-0 overflow-visible"
              >
                {width > 0 &&
                  drawn.map((b, s) => {
                    const upper = b.upper.map(
                      (v, i) => [x(i), y(v)] as [number, number],
                    );
                    const lower = b.lower
                      .map((v, i) => [x(i), y(v)] as [number, number])
                      .reverse();
                    const top = monotone(upper);
                    const fill = `${top}${monotone(lower, false)}Z`;
                    const shown = on(series[s]);
                    // Overlap fills lightly so the bands behind still show; stacked bands fill a little more.
                    const wash = layout === "overlap" ? 0.1 : 0.2;
                    return (
                      <g
                        key={series[s].id}
                        style={{
                          opacity: shown ? 1 : 0,
                          transition: reduced
                            ? "none"
                            : `opacity 300ms ${EASE}`,
                        }}
                      >
                        <path d={fill} fill={COLORS[s]} fillOpacity={wash} />
                        <path
                          d={top}
                          fill="none"
                          stroke={COLORS[s]}
                          strokeWidth="2"
                          strokeLinecap="round"
                          strokeLinejoin="round"
                        />
                      </g>
                    );
                  })}
              </svg>
            </div>

            <span
              aria-hidden="true"
              className="pointer-events-none absolute top-0 w-px bg-foreground/20"
              style={{
                height: plotH,
                left: active !== null ? x(active) : 0,
                opacity: active !== null ? 1 : 0,
                transition: reduced
                  ? "none"
                  : `left 260ms ${THROW}, opacity 200ms ${EASE}`,
              }}
            />
            {series.map((s, si) => {
              const showDot = active !== null && on(s);
              const v = drawn[si]?.upper[active ?? n - 1] ?? 0;
              return (
                <span
                  key={s.id}
                  aria-hidden="true"
                  className="pointer-events-none absolute size-2.5 -translate-x-1/2 -translate-y-1/2 rounded-full shadow-[0_0_0_2px_var(--background)]"
                  style={{
                    left: x(active ?? n - 1),
                    top: y(v),
                    background: COLORS[si],
                    opacity: showDot ? 1 : 0,
                    scale: showDot ? "1" : "0.4",
                    transition: reduced
                      ? "none"
                      : `left 260ms ${THROW}, top 260ms ${THROW}, opacity 200ms ${EASE}, scale 260ms ${EASE}`,
                  }}
                />
              );
            })}

            {labels.map((l, i) => (
              <span
                key={l + i}
                aria-hidden="true"
                className={`absolute -translate-x-1/2 whitespace-nowrap text-[11px] leading-none transition-colors duration-200 ${active === i ? "text-foreground" : "text-muted-foreground"}`}
                style={{
                  left: x(i),
                  top: plotH + 9,
                  opacity: label(i) ? 1 : 0,
                }}
              >
                {l}
              </span>
            ))}
          </div>
        </div>

        {/* The tiles: the legend, the switches, and the readout while you point. */}
        {/* The legend as a compact strip: each series is a toggle with its figure and share. */}
        <div
          className="mt-4 grid gap-x-1 border-t border-border pt-2.5 @md:mt-5 @md:pt-3"
          style={{
            gridTemplateColumns: `repeat(${Math.min(series.length, 3)}, minmax(0, 1fr))`,
          }}
        >
          {series.map((s, si) => {
            const shown = on(s);
            const value = totalOf(s);
            const share = shownTotal ? value / shownTotal : 0;
            return (
              <button
                key={s.id}
                type="button"
                aria-pressed={shown}
                onClick={() => toggle(s.id)}
                className={`cursor-pointer -mx-1.5 flex min-w-0 flex-col items-start rounded-lg px-1.5 py-1 text-left transition-[opacity,background-color] duration-300 hover:bg-accent ${FOCUS} ${
                  shown ? "" : "opacity-45"
                }`}
              >
                <span className="flex max-w-full items-center gap-1.5 text-[11px] text-muted-foreground @md:text-[11.5px]">
                  <span
                    aria-hidden="true"
                    className="size-[7px] shrink-0 rounded-full transition-[background-color,box-shadow] duration-300"
                    style={{
                      background: shown ? COLORS[si] : "transparent",
                      boxShadow: `inset 0 0 0 1.5px ${COLORS[si]}`,
                    }}
                  />
                  <span className="truncate">{s.label}</span>
                </span>
                <span className="mt-0.5 flex items-baseline gap-1">
                  <span className="text-[13.5px] font-medium tracking-[-0.01em] text-foreground @md:text-[14.5px]">
                    <NumberRoll
                      value={visible && shown ? value : 0}
                      format={format}
                      locales={locales}
                      duration={600}
                    />
                  </span>
                  <span className="text-[10.5px] text-muted-foreground @md:text-[11px]">
                    <NumberRoll
                      value={visible && shown ? share : 0}
                      format={{ style: "percent" }}
                      duration={600}
                    />
                  </span>
                </span>
              </button>
            );
          })}
        </div>

        <p aria-live="polite" className="sr-only">
          {keyboard && active !== null
            ? `${name(active)}: ${series
                .filter(on)
                .map((s) => `${s.label} ${fmt(s.values[active] ?? 0)}`)
                .join(", ")}`
            : ""}
        </p>
        <table className="sr-only">
          <caption>
            {title}
            {caption ? `, ${caption}` : ""}
          </caption>
          <thead>
            <tr>
              <th scope="col">Point</th>
              {series.map((s) => (
                <th key={s.id} scope="col">
                  {s.label}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {labels.map((l, i) => (
              <tr key={l + i} id={`${id}-${i}`}>
                <th scope="row">{name(i)}</th>
                {series.map((s) => (
                  <td key={s.id}>{fmt(s.values[i] ?? 0)}</td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

