              ))}
            </button>
          </div>
          {errorLine}
          <div className="mt-3 flex items-center justify-between gap-2">
            {onForgot ? (
              <ForgotButton
                onForgot={async () => {
                  await onForgot(email);
                  go("reset");
                }}
              />
            ) : (
              <span />
            )}
            <StatusButton
              type="submit"
              status={status}
              labels={{
                idle: "Sign in",
                pending: "Signing in",
