                  ).map((d, i) => {
                    if (!d) return <span key={i} className="h-[62px]" />;
                    const k = keyOf(d);
                    const count = byDay.get(k)?.length ?? 0;
                    const on = k === dayKey;
                    const off = !loading && count === 0;
                    return (
                      <button
                        key={k}
                        type="button"
                        role="radio"
                        data-key={k}
                        aria-checked={on}
                        aria-label={`${fmt.date.format(noon(d))}, ${loading ? "loading" : count ? `${count} times` : "no times"}`}
