import * as React from "react";
import { TextMorph } from "./text-morph";
import {
  EASE_OUT,
  INTERACTION_PRESS,
  interactionIcon,
} from "./imported-ui-interaction-motion";

export type ButtonVariant =
  | "primary"
  | "brand"
  | "secondary"
  | "outline"
  | "ghost"
  | "destructive"
  | "link";

export type ButtonSize = "xs" | "sm" | "md" | "lg" | "icon";
export type ActionStatus = "idle" | "pending" | "success" | "error";

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  ref?: React.Ref<HTMLButtonElement>;
  variant?: ButtonVariant;
  size?: ButtonSize;
  loading?: boolean;
  status?: ActionStatus;
  /** Custom labels for each state when using status/async flows. */
  statusLabels?: Partial<Record<ActionStatus, string>>;
  /** Automatically reset back to idle after success/error (ms). Default 1800ms. */
  resetAfter?: number;
  onReset?: () => void;
  icon?: React.ReactNode;
  trailingIcon?: React.ReactNode;
}

const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const variantStyles: Record<ButtonVariant, string> = {
  primary: "bg-primary text-primary-foreground hover:bg-primary/90",
  brand: "bg-primary text-primary-foreground hover:bg-primary/90",
  secondary:
    "bg-card text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent",
  outline:
    "bg-transparent text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent",
  ghost:
    "bg-transparent text-muted-foreground hover:bg-accent hover:text-foreground",
  destructive:
    "bg-red-500/10 text-red-600 shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_30%,transparent)] dark:text-red-400 hover:bg-red-500/15",
  link: "bg-transparent text-primary underline-offset-4 hover:underline p-0 h-auto font-normal",
};

interface SizeConfig {
  height: string;
  padding: string;
  fontSize: string;
  iconSize: number;
  iconGap: number;
}

const sizeConfigs: Record<ButtonSize, SizeConfig> = {
  xs: {
    height: "h-6",
    padding: "px-2.5",
    fontSize: "text-[12px]",
    iconSize: 12,
    iconGap: 5,
  },
  sm: {
    height: "h-7",
    padding: "px-3",
    fontSize: "text-[12px]",
    iconSize: 13,
    iconGap: 6,
  },
  md: {
    height: "h-9",
    padding: "px-4",
    fontSize: "text-[13px]",
    iconSize: 14,
    iconGap: 7,
  },
  lg: {
    height: "h-10",
    padding: "px-5",
    fontSize: "text-[14px]",
    iconSize: 16,
    iconGap: 8,
  },
  icon: {
    height: "size-9 p-0 justify-center items-center shrink-0",
    padding: "p-0",
    fontSize: "text-[13px]",
    iconSize: 15,
    iconGap: 0,
  },
};

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function SelfDrawingCheck({
  drawn,
  reduced,
  size,
}: {
  drawn: boolean;
  reduced: boolean;
  size: number;
}) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 16 16"
      fill="none"
      className="shrink-0"
    >
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 420ms ${EASE_OUT} 100ms`
              : "none",
        }}
      />
    </svg>
  );
}

function StatusAlert({ size }: { size: number }) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 16 16"
      fill="none"
      className="shrink-0"
    >
      <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeWidth="1.5" />
      <path
        d="M8 4.75v3.75"
        stroke="currentColor"
        strokeWidth="1.75"
        strokeLinecap="round"
      />
      <circle cx="8" cy="11" r="1" fill="currentColor" />
    </svg>
  );
}

const DEFAULT_LABELS: Record<ActionStatus, string> = {
  idle: "Save",
  pending: "Saving",
  success: "Saved",
  error: "Try again",
};

/**
 * Button: high-craft tactile action primitive with rounded-full pill geometry,
 * StatusButton visual parity, self-drawing checkmark morphs, TextMorph label transitions,
 * and error shake physics.
 */
export function Button({
  ref,
  variant = "primary",
  size = "md",
  loading = false,
  status,
  statusLabels,
  resetAfter = 1800,
  onReset,
  disabled = false,
  icon,
  trailingIcon,
  className = "",
  children,
  onClick,
  ...props
}: ButtonProps) {
  const innerRef = React.useRef<HTMLButtonElement | null>(null);
  const reduced = useReducedMotion();

  React.useImperativeHandle(ref, () => innerRef.current as HTMLButtonElement);

  // Normalize status from explicit prop or loading boolean
  const currentStatus: ActionStatus = status ?? (loading ? "pending" : "idle");
  const isAsyncFlow = status !== undefined || loading;

  // Resolve current text label
  const idleLabel =
    typeof children === "string" ? children : DEFAULT_LABELS.idle;
  const labels: Record<ActionStatus, string> = {
    idle: statusLabels?.idle ?? idleLabel,
    pending: statusLabels?.pending ?? DEFAULT_LABELS.pending,
    success: statusLabels?.success ?? DEFAULT_LABELS.success,
    error: statusLabels?.error ?? DEFAULT_LABELS.error,
  };
  const activeLabel = labels[currentStatus];

  // Auto-reset timer for success or error states
  React.useEffect(() => {
    if ((currentStatus !== "success" && currentStatus !== "error") || !onReset)
      return;
    const timer = window.setTimeout(onReset, resetAfter);
    return () => window.clearTimeout(timer);
  }, [currentStatus, onReset, resetAfter]);

  // Error state horizontal shake
  React.useEffect(() => {
    if (currentStatus !== "error" || reduced) return;
    innerRef.current?.animate(
      [
        { transform: "none" },
        { transform: "translateX(-4px)" },
        { transform: "translateX(4px)" },
        { transform: "translateX(-2px)" },
        { transform: "none" },
      ],
      { duration: 380, easing: "ease-out" },
    );
  }, [currentStatus, reduced]);

  const cfg = sizeConfigs[size];
  const isBusy = currentStatus === "pending";
  const isInert = disabled || isBusy;

  // Icon slot state: open if an icon was provided, or if in async status
  const showLeadingSlot =
    size !== "icon" &&
    (Boolean(icon) || (isAsyncFlow && currentStatus !== "idle"));

  const icons: Record<ActionStatus, React.ReactNode> = {
    idle: icon,
    pending: (
      <span
        style={{ width: cfg.iconSize, height: cfg.iconSize }}
        className={`rounded-full border-[1.5px] border-current border-t-transparent motion-reduce:animate-none opacity-85 ${
          currentStatus === "pending" ? "animate-spin" : ""
        }`}
      />
    ),
    success: (
      <span
        className={
          variant === "primary"
            ? "text-primary-foreground"
            : "text-emerald-600 dark:text-emerald-400"
        }
      >
        <SelfDrawingCheck
          drawn={currentStatus === "success"}
          reduced={reduced}
          size={cfg.iconSize}
        />
      </span>
    ),
    error: (
      <span className="text-red-600 dark:text-red-400">
        <StatusAlert size={cfg.iconSize} />
      </span>
    ),
  };

  const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    if (isInert) {
      e.preventDefault();
      return;
    }
    onClick?.(e);
  };

  // Tone shifts for error states
  const toneClass =
    currentStatus === "error"
      ? "bg-red-500/10 text-red-600 shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_30%,transparent)] dark:text-red-400"
      : variantStyles[variant];

  return (
    <>
      <button
        ref={innerRef}
        type={props.type ?? "button"}
        disabled={disabled}
        aria-disabled={isInert ? true : undefined}
        aria-busy={isBusy ? true : undefined}
        onClick={handleClick}
        className={`relative inline-flex items-center justify-center font-medium select-none whitespace-nowrap cursor-pointer rounded-full disabled:cursor-default disabled:opacity-45 ${variant === "link" ? "transition-colors" : INTERACTION_PRESS} ${FOCUS} ${
          toneClass
        } ${cfg.height} ${cfg.padding} ${cfg.fontSize} ${className}`}
        {...props}
      >
        {/* Leading Icon / Status Slot with explicit width, height, and marginRight */}
        {size !== "icon" && (
          <span
            aria-hidden="true"
            className="relative flex shrink-0 items-center justify-center overflow-hidden"
            style={{
              width: showLeadingSlot ? cfg.iconSize : 0,
              height: cfg.iconSize,
              marginRight: showLeadingSlot ? cfg.iconGap : 0,
              transition: reduced
                ? "none"
                : `width 360ms ${EASE_OUT}, margin-right 360ms ${EASE_OUT}`,
            }}
          >
            {(Object.keys(icons) as ActionStatus[]).map((st) => (
              <span
                key={st}
                className="absolute inset-0 flex items-center justify-center"
                style={interactionIcon(st === currentStatus, reduced)}
              >
                {icons[st]}
              </span>
            ))}
          </span>
        )}

        {/* Icon-only mode: the same stacked layers, so the icon never hard-swaps. */}
        {size === "icon" && (
          <span
            aria-hidden="true"
            className="relative shrink-0"
            style={{ width: cfg.iconSize, height: cfg.iconSize }}
          >
            {(Object.keys(icons) as ActionStatus[]).map((st) => (
              <span
                key={st}
                className="absolute inset-0 flex items-center justify-center"
                style={interactionIcon(st === currentStatus, reduced)}
              >
                {st === "idle" ? (icon ?? children) : icons[st]}
              </span>
            ))}
          </span>
        )}

        {/* Text Label: uses TextMorph for silky label transitions */}
        {size !== "icon" && (
          <span className="inline-flex items-center">
            {typeof children === "string" || isAsyncFlow ? (
              <TextMorph>{activeLabel}</TextMorph>
            ) : (
              children
            )}
          </span>
        )}

        {/* Trailing Icon with guaranteed calibrated spacing */}
        {trailingIcon && size !== "icon" && (
          <span
            aria-hidden="true"
            className="inline-flex shrink-0 items-center justify-center"
            style={{ marginLeft: cfg.iconGap }}
          >
            {trailingIcon}
          </span>
        )}
      </button>

      {/* Screen Reader live region outside button */}
      {isAsyncFlow && (
        <span role="status" aria-live="polite" className="sr-only">
          {currentStatus === "idle" ? "" : activeLabel}
        </span>
      )}
    </>
  );
}

export default Button;

"use client";

import * as React from "react";
import { BellRing, ShoppingBag } from "lucide-react";
import { Faces } from "./faces";
import { Input } from "./input";
import { NumberRoll } from "./number-roll";
import { StatusButton, type ActionStatus } from "./status-button";
import { StepperInput } from "./stepper-input";
import { TextMorph } from "./text-morph";
import {
  EASE_THROW,
  INTERACTION_FOCUS,
  INTERACTION_PRESS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * BUY BOX: the swatch that repaints the product
 *
 *   stage     the product stands on a pedestal of engraved rings
 *             in a stage painted in the colour you picked; a new
 *             colour floods the stage and ripples the rings
 *   options   swatches and sizes from your variants; what isn't
 *             made or is sold out is struck through; the price
 *             rolls when the variant costs more or less
 *   add       Add to bag goes Adding → Added and the product is
 *             thrown into the bag in the corner, which bumps as
 *             its count rolls
 *   sold out  the button becomes Notify me, and an email field
 *             grows out of it
 *
 * The catalogue is yours: pass options and variants (price and
 * stock per variant), and do the work in onAddToCart and onNotify.
 * Throw an Error and its message shows under the button.
 * ───────────────────────────────────────────────────────── */

export interface BuyBoxValue {
  id: string;
  label: string;
  /** A CSS colour: makes this a swatch, and paints the stage when picked. */
  swatch?: string;
}

export interface BuyBoxOption {
  id: string;
  /** e.g. "Colour", "Size". */
  label: string;
  values: BuyBoxValue[];
}

export interface BuyBoxVariant {
  id: string;
  /** The value id picked for each option, e.g. { colour: "sand", size: "m" }. */
  options: Record<string, string>;
  price: number;
  /** The old price, shown struck through. */
  compareAt?: number;
  /** Left in stock; leave out for plenty, 0 is sold out. */
  stock?: number;
  /** A photo of this variant; the stage shows `icon` when missing. */
  image?: string;
}

export interface BuyBoxProps {
  name: string;
  brand?: string;
  options: BuyBoxOption[];
  variants: BuyBoxVariant[];
  /** Starting picks; defaults to the first variant in stock. */
  defaultSelection?: Record<string, string>;
  /** The product's glyph on the stage when there's no image. */
  icon?: React.ReactNode;
  /** Items already in the bag. */
  bagCount?: number;
  /** "Only 3 left" from this many down. */
  lowStockAt?: number;
  /** Add to the bag; throw an Error to say why not. */
  onAddToCart: (variant: BuyBoxVariant, quantity: number) => Promise<unknown>;
  /** Shows Notify me on sold-out variants. */
  onNotify?: (variant: BuyBoxVariant, email: string) => Promise<unknown>;
  currency?: string;
  locale?: string;
  className?: string;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const subscribeNothing = () => () => {};
/** False on the server and while hydrating: text is formatted in one fixed locale until then, so the server's and the visitor's never disagree. */
const useHydrated = () =>
  React.useSyncExternalStore(
    subscribeNothing,
    () => true,
    () => false,
  );
const mix = (color: string, amount: number, into = "transparent") =>
  `color-mix(in oklab, ${color} ${amount}%, ${into})`;
const CARD: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, var(--card), ${mix("var(--card)", 95, "var(--foreground)")})`,
  boxShadow: `0 0 0 1px var(--border), inset 0 1px 0 ${mix("var(--background)", 85)}`,
};
const LIT: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, ${mix("var(--primary-foreground)", 16)}, transparent 60%)`,
  boxShadow: `inset 0 1px 0 ${mix("var(--primary-foreground)", 32)}, inset 0 0 0 1px ${mix("black", 10)}`,
};
const money = (currency: string, n: number): Intl.NumberFormatOptions => ({
  style: "currency",
  currency,
  minimumFractionDigits: n % 1 ? 2 : 0,
  maximumFractionDigits: 2,
});

const matches = (
  v: BuyBoxVariant,
  pick: Record<string, string>,
  skip?: string,
) =>
  Object.entries(pick).every(([k, val]) => k === skip || v.options[k] === val);

/** The pedestal: fine engraved rings the product stands on. */
function Rings({
  ringsRef,
}: {
  ringsRef: React.RefObject<SVGSVGElement | null>;
}) {
  return (
    <svg
      ref={ringsRef}
      aria-hidden="true"
      viewBox="0 0 200 80"
      className="absolute bottom-[6%] left-1/2 w-[78%] -translate-x-1/2 overflow-visible"
      fill="none"
      stroke="currentColor"
    >
      {Array.from({ length: 7 }, (_, i) => (
        <ellipse
          key={i}
          cx="100"
          cy="40"
          rx={30 + i * 12}
          ry={8 + i * 3.6}
          strokeWidth="0.8"
          strokeOpacity={0.34 - i * 0.04}
        />
      ))}
    </svg>
  );
}

export function BuyBox({
  name,
  brand,
  options,
  variants,
  defaultSelection,
  icon,
  bagCount = 0,
  lowStockAt = 5,
  onAddToCart,
  onNotify,
  currency = "USD",
  locale,
  className = "",
}: BuyBoxProps) {
  const reduced = useInteractionReducedMotion();
  const hydrated = useHydrated();
  const baseId = React.useId();
  const [pick, setPick] = React.useState<Record<string, string>>(
    () =>
      defaultSelection ??
      (variants.find((v) => v.stock !== 0) ?? variants[0])?.options ??
      {},
  );
  const [quantity, setQuantity] = React.useState(1);
  const [add, setAdd] = React.useState<{
    status: ActionStatus;
    error?: string;
  }>({ status: "idle" });
  const [notify, setNotify] = React.useState<{
    open: boolean;
    email: string;
    status: ActionStatus;
    error?: string;
  }>({ open: false, email: "", status: "idle" });
  const [added, setAdded] = React.useState(0);
  const [ready, setReady] = React.useState(false);
  const [said, setSaid] = React.useState("");

  const sectionRef = React.useRef<HTMLElement>(null);
  const productRef = React.useRef<HTMLDivElement>(null);
  const bagRef = React.useRef<HTMLSpanElement>(null);
  const ringsRef = React.useRef<SVGSVGElement>(null);
  const emailRef = React.useRef<HTMLInputElement>(null);

  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setReady(true));
    return () => cancelAnimationFrame(frame);
  }, []);

  const variant =
    variants.find(
      (v) =>
        matches(v, pick) && options.every((o) => v.options[o.id] !== undefined),
    ) ?? null;
  const swatchOption = options.find((o) => o.values.some((v) => v.swatch));
  const swatch =
    swatchOption?.values.find((v) => v.id === pick[swatchOption.id])?.swatch ??
    "var(--primary)";
  const price = variant?.price ?? Math.min(...variants.map((v) => v.price));
  const soldOut = variant?.stock === 0;
  const low =
    variant?.stock !== undefined &&
    variant.stock > 0 &&
    variant.stock <= lowStockAt;
  const saving =
    variant?.compareAt && variant.compareAt > variant.price
      ? Math.round((1 - variant.price / variant.compareAt) * 100)
      : 0;
  const busy = add.status === "pending";
  const bag = bagCount + added;

  /** Is this value made with the rest of what's picked, and in stock? */
  const state = (optionId: string, valueId: string): "ok" | "out" | "none" => {
    const made = variants.filter(
      (v) => v.options[optionId] === valueId && matches(v, pick, optionId),
    );
    if (!made.length) return "none";
    return made.some((v) => v.stock !== 0) ? "ok" : "out";
  };

  const choose = (optionId: string, valueId: string) => {
    if (busy) return;
    const next = { ...pick, [optionId]: valueId };
    // Not made with the rest of the picks: move the others to the closest variant that is.
    const exact = variants.some((v) => matches(v, next));
    const fallback = exact
      ? next
      : (
          variants.find(
            (v) => v.options[optionId] === valueId && v.stock !== 0,
          ) ?? variants.find((v) => v.options[optionId] === valueId)
        )?.options;
    setPick(fallback ?? next);
    setAdd({ status: "idle" });
    if (notify.open)
      setNotify((n) => ({
        ...n,
        open: false,
        status: "idle",
        error: undefined,
      }));
    if (
      optionId === swatchOption?.id &&
      !reduced &&
      valueId !== pick[optionId]
    ) {
      // The rings are centred with `translate`, so the ripple only scales.
      ringsRef.current?.animate(
        [
          { transform: "scale(0.9)", opacity: 0.35 },
          { transform: "scale(1)", opacity: 1 },
        ],
        { duration: 620, easing: EASE_THROW },
      );
    }
  };

  // The product is thrown into the bag: a copy arcs from the stage to the bag, which bumps as it lands.
  const fly = () => {
    const section = sectionRef.current;
    const from = productRef.current;
    const to = bagRef.current;
    if (!section || !from || !to || reduced) {
      setAdded((n) => n + quantity);
      return;
    }
    const box = section.getBoundingClientRect();
    // Screen px to the block's own px, so the throw lands true inside a scaled or zoomed container too.
    const k = box.width / (section.offsetWidth || box.width) || 1;
    const a = from.getBoundingClientRect();
    const b = to.getBoundingClientRect();
    const copy = from.cloneNode(true) as HTMLElement;
    copy.setAttribute("aria-hidden", "true");
    Object.assign(copy.style, {
      position: "absolute",
      left: `${(a.left - box.left) / k}px`,
      top: `${(a.top - box.top) / k}px`,
      width: `${a.width / k}px`,
      height: `${a.height / k}px`,
      margin: "0",
      zIndex: "20",
      pointerEvents: "none",
      willChange: "transform",
    });
    section.appendChild(copy);
    const dx = (b.left + b.width / 2 - (a.left + a.width / 2)) / k;
    const dy = (b.top + b.height / 2 - (a.top + a.height / 2)) / k;
    const s = Math.min(b.height / a.height, 0.3);
    const flight = copy.animate(
      [
        { transform: "translate(0,0) scale(1)", opacity: 1 },
        {
          transform: `translate(${dx * 0.55}px, ${dy * 0.35 - 40}px) scale(${(1 + s) / 2}) rotate(-8deg)`,
          opacity: 1,
          offset: 0.5,
        },
        {
          transform: `translate(${dx}px, ${dy}px) scale(${s}) rotate(-14deg)`,
          opacity: 0.2,
        },
      ],
      { duration: 680, easing: "cubic-bezier(0.5,0,0.25,1)", fill: "forwards" },
    );
    flight.onfinish = flight.oncancel = () => {
      copy.remove();
      setAdded((n) => n + quantity);
      bagRef.current?.animate(
        [
          { transform: "scale(1)" },
          { transform: "scale(1.16)" },
          { transform: "scale(1)" },
        ],
        { duration: 420, easing: EASE_THROW },
      );
    };
  };

  const addToBag = async () => {
    if (!variant || busy || soldOut) return;
    setAdd({ status: "pending" });
    try {
      await onAddToCart(variant, quantity);
      setAdd({ status: "success" });
      setSaid(`Added ${quantity} ${name} to your bag.`);
      fly();
    } catch (e) {
      setAdd({
        status: "error",
        error:
          e instanceof Error && e.message
            ? e.message
            : "Couldn’t add that. Try again.",
      });
    }
  };

  const sendNotify = async () => {
    if (!variant || !onNotify) return;
    if (!notify.open) {
      setNotify((n) => ({ ...n, open: true }));
      window.setTimeout(
        () => emailRef.current?.focus({ preventScroll: true }),
        reduced ? 0 : 300,
      );
      return;
    }
    if (!EMAIL.test(notify.email.trim()))
      return setNotify((n) => ({
        ...n,
        status: "idle",
        error: "Add an email we can write to",
      }));
    setNotify((n) => ({ ...n, status: "pending", error: undefined }));
    try {
      await onNotify(variant, notify.email.trim());
      setNotify((n) => ({ ...n, status: "success" }));
      setSaid("We’ll email you when it’s back.");
    } catch (e) {
      setNotify((n) => ({
        ...n,
        status: "error",
        error:
          e instanceof Error && e.message
            ? e.message
            : "Couldn’t save that. Try again.",
      }));
    }
  };

  const stock = soldOut
    ? "Sold out"
    : low
      ? `Only ${variant?.stock} left`
      : variant
        ? "In stock, ships today"
        : "Pick an option";
  const fmt = (n: number) => money(currency, n);

  return (
    <section
      ref={sectionRef}
      aria-labelledby={`${baseId}-name`}
      className={`relative w-full max-w-[400px] rounded-[28px] p-2 text-card-foreground ${className}`}
      style={CARD}
    >
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 400px)" }}
      />
      <div className="@container w-full">
        {/* The one lit surface: the stage, painted in the colour you picked. */}
        <div
          className="relative h-[220px] overflow-clip rounded-[22px]"
          style={{
            backgroundColor: mix(swatch, 48, "var(--card)"),
            backgroundImage: `radial-gradient(120% 90% at 0% 0%, ${mix("white", 34)} 0%, transparent 55%), linear-gradient(175deg, transparent 45%, ${mix("black", 14)} 100%)`,
            boxShadow: `inset 0 1px 0 ${mix("white", 40)}, inset 0 0 0 1px ${mix(swatch, 30)}`,
            color: mix(swatch, 62, "black"),
            transition: reduced
              ? "none"
              : `background-color 520ms ${EASE}, color 520ms ${EASE}, box-shadow 520ms ${EASE}`,
          }}
        >
          <Rings ringsRef={ringsRef} />
          <div
            ref={productRef}
            className="absolute inset-x-0 top-[14%] mx-auto flex size-[128px] items-center justify-center [&_svg]:size-[92px]"
          >
            {variant?.image ? (
              <img
                key={variant.image}
                src={variant.image}
                alt=""
                decoding="async"
                className="size-full object-contain motion-safe:animate-[ui-fade-in_420ms_ease-out_both]"
              />
            ) : (
              <span aria-hidden="true" className="flex [&_svg]:stroke-[1.2]">
                {icon ?? <ShoppingBag />}
              </span>
            )}
          </div>
          {saving > 0 && (
            <span className="absolute left-3 top-3 rounded-full bg-foreground px-2 py-1 text-[11.5px] font-medium tabular-nums text-background">
              −<NumberRoll value={saving} duration={600} />%
            </span>
          )}
          <span
            ref={bagRef}
            className="absolute right-3 top-3 inline-flex h-8 items-center gap-1.5 rounded-full bg-card px-3 text-[12.5px] font-medium text-foreground shadow-[inset_0_0_0_1px_var(--border)]"
            aria-label={`${bag} in your bag`}
          >
            <ShoppingBag aria-hidden="true" className="size-3.5" />
            <NumberRoll value={bag} duration={600} aria-hidden="true" />
          </span>
        </div>

        <div className="px-2 pb-1 pt-3">
          <div className="flex items-start justify-between gap-3">
            <div className="min-w-0">
              {brand && (
                <p className="text-[12px] text-muted-foreground">{brand}</p>
              )}
              <h2
                id={`${baseId}-name`}
                className="text-[18px] font-medium leading-tight tracking-[-0.02em]"
              >
                {name}
              </h2>
            </div>
            <div className="shrink-0 text-right">
              <p className="text-[22px] font-medium leading-none tracking-[-0.03em] tabular-nums">
                <NumberRoll
                  value={price}
                  locales={locale}
                  format={fmt(price)}
                  duration={800}
                />
              </p>
              {saving > 0 && variant?.compareAt && (
                <p className="mt-1 text-[12px] text-muted-foreground tabular-nums line-through">
                  {new Intl.NumberFormat(
                    locale ?? (hydrated ? undefined : "en-US"),
                    fmt(variant.compareAt),
                  ).format(variant.compareAt)}
                </p>
              )}
            </div>
          </div>

          {options.map((o) => {
            const chosen = o.values.find((v) => v.id === pick[o.id]);
            return (
              <div key={o.id} className="mt-3.5">
                <p className="text-[12.5px] text-muted-foreground">
                  {o.label} ·{" "}
                  <TextMorph className="text-foreground">
                    {chosen?.label ?? "Choose"}
                  </TextMorph>
                </p>
                <div
                  role="radiogroup"
                  aria-label={o.label}
                  className="mt-2 flex flex-wrap gap-1.5"
                >
                  {o.values.map((v) => {
                    const on = v.id === pick[o.id];
                    const st = state(o.id, v.id);
                    const label = `${v.label}${st === "out" ? ", sold out" : st === "none" ? ", not made in this combination" : ""}`;
                    return v.swatch ? (
                      <button
                        key={v.id}
                        type="button"
                        role="radio"
                        aria-checked={on}
                        aria-label={label}
                        title={v.label}
                        onClick={() => choose(o.id, v.id)}
                        className={`relative size-8 cursor-pointer rounded-full ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`}
                        style={{
                          background: v.swatch,
                          boxShadow: on
                            ? `inset 0 0 0 1px ${mix("black", 14)}, 0 0 0 2px var(--card), 0 0 0 3.5px var(--primary)`
                            : `inset 0 0 0 1px ${mix("black", 14)}, 0 0 0 2px var(--card), 0 0 0 2px transparent`,
                          opacity: st === "ok" ? 1 : 0.45,
                          transition: reduced
                            ? "none"
                            : `box-shadow 280ms ${EASE_THROW}, opacity 200ms`,
                        }}
                      >
                        {st !== "ok" && (
                          <span
                            aria-hidden="true"
                            className="absolute left-1/2 top-1/2 h-px w-[130%] -translate-x-1/2 -translate-y-1/2 -rotate-45 bg-foreground/60"
                          />
                        )}
                      </button>
                    ) : (
                      <button
                        key={v.id}
                        type="button"
                        role="radio"
                        aria-checked={on}
                        aria-label={label}
                        onClick={() => choose(o.id, v.id)}
                        className={`h-9 min-w-11 cursor-pointer rounded-full px-3 text-[13px] tabular-nums ${INTERACTION_PRESS} ${INTERACTION_FOCUS} ${
                          on
                            ? "bg-primary/[0.08] font-medium text-primary shadow-[inset_0_0_0_1.5px_var(--primary)]"
                            : "text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent"
                        } ${st !== "ok" ? "text-muted-foreground line-through decoration-1" : ""}`}
                      >
                        {v.label}
                      </button>
                    );
                  })}
                </div>
              </div>
            );
          })}

          <p
            className={`mt-3.5 flex items-center gap-1.5 text-[12.5px] ${soldOut ? "text-red-600 dark:text-red-400" : low ? "text-amber-600 dark:text-amber-400" : "text-muted-foreground"}`}
          >
            <span
              aria-hidden="true"
              className={`size-1.5 rounded-full ${soldOut ? "bg-red-500" : low ? "bg-amber-500" : "bg-emerald-500"}`}
            />
            <TextMorph>{stock}</TextMorph>
          </p>

          <div className="mt-2.5">
            <Faces active={notify.open ? 1 : 0} reduced={reduced} ready={ready}>
              <div className="flex items-center gap-2">
                <StepperInput
                  label="Quantity"
                  value={quantity}
                  min={1}
                  max={variant?.stock && variant.stock > 0 ? variant.stock : 10}
                  onValueChange={setQuantity}
                  disabled={soldOut || busy}
                />
                {soldOut && onNotify ? (
                  <button
                    type="button"
                    onClick={() => void sendNotify()}
                    className={`inline-flex h-11 flex-1 cursor-pointer items-center justify-center gap-2 rounded-full text-[14.5px] font-medium text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`}
                  >
                    <BellRing aria-hidden="true" className="size-4" />
                    Notify me
                  </button>
                ) : (
                  <StatusButton
                    status={add.status}
                    labels={{
                      idle: soldOut ? "Sold out" : "Add to bag",
                      pending: "Adding",
                      success: "Added",
                      error: "Try again",
                    }}
                    icon={<ShoppingBag aria-hidden="true" />}
                    disabled={!variant || soldOut}
                    onReset={() => setAdd({ status: "idle" })}
                    resetAfter={1500}
                    onClick={() => void addToBag()}
                    className="h-11 flex-1 text-[14.5px] disabled:opacity-45"
                    style={add.status === "error" ? undefined : LIT}
                  />
                )}
              </div>
              <form
                className="flex items-start gap-2"
                onSubmit={(e) => {
                  e.preventDefault();
                  void sendNotify();
                }}
              >
                <Input
                  ref={emailRef}
                  aria-label="Email for a restock note"
                  type="email"
                  inputMode="email"
                  autoComplete="email"
                  placeholder="you@email.com"
                  value={notify.email}
                  error={notify.error}
                  disabled={
                    notify.status === "pending" || notify.status === "success"
                  }
                  onValueChange={(email) =>
                    setNotify((n) => ({
                      ...n,
                      email,
                      error: undefined,
                      status: n.status === "error" ? "idle" : n.status,
                    }))
                  }
                  className="flex-1"
                />
                <StatusButton
                  type="submit"
                  status={notify.status}
                  labels={{
                    idle: "Notify me",
                    pending: "Saving",
                    success: "You’re on the list",
                    error: "Try again",
                  }}
                  className="h-9 shrink-0 px-4 text-[13px]"
                  style={notify.status === "error" ? undefined : LIT}
                />
              </form>
            </Faces>
            {add.error && (
              <p
                role="alert"
                className="mt-1.5 text-[12px] text-red-600 dark:text-red-400"
              >
                {add.error}
              </p>
            )}
          </div>
        </div>

        <span className="sr-only" role="status">
          {said}
        </span>
      </div>
    </section>
  );
}

export default BuyBox;

"use client";

import * as React from "react";
import { ArrowLeft, ArrowRight } from "lucide-react";
import {
  EASE_OUT,
  EASE_SETTLE,
  INTERACTION_FOCUS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";
import { useCardDeckGesture, type DeckThrow } from "./use-card-deck-gesture";
import { NumberRoll } from "./number-roll";

export interface CardDeckProps<T extends { id: string }> extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "children" | "onChange"
> {
  items: T[];
  renderCard: (
    item: T,
    state: { active: boolean; index: number },
  ) => React.ReactNode;
  getLabel?: (item: T) => string;
  value?: string;
  defaultValue?: string;
  onValueChange?: (id: string) => void;
  label?: string;
  /** Fixed card height keeps the stack stable while content changes. */
  height?: number;
}

function DepartingCard({
  motion,
  reduced,
  children,
}: {
  motion: DeckThrow;
  reduced: boolean;
  children: React.ReactNode;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el || reduced) return;
    const end = -motion.direction * el.offsetWidth * 1.35;
    const fromAngle =
      Math.sign(motion.from) *
      Math.min(16, Math.sqrt(Math.abs(motion.from)) * 1.05);
    const endAngle = -motion.direction * 15;
    const dur = Math.min(
      380,
      Math.max(260, 360 - Math.abs(motion.velocity) * 80),
    );
    const animation = el.animate(
      [
        {
          transform: `translate3d(${motion.from}px,${-Math.abs(motion.from) * 0.05}px,0) rotate(${fromAngle}deg)`,
          opacity: 1,
        },
        {
          transform: `translate3d(${end}px,-10px,0) rotate(${endAngle}deg)`,
          opacity: 0,
        },
      ],
      { duration: dur, easing: EASE_OUT, fill: "forwards" },
    );
    return () => animation.cancel();
  }, [motion, reduced]);
  return (
    <div
      ref={ref}
      aria-hidden="true"
      inert
      className="pointer-events-none absolute inset-0 z-20 overflow-hidden rounded-[22px] border border-border bg-card text-card-foreground"
    >
      {children}
    </div>
  );
}

/** Where a card behind the front one sits: lower and smaller by depth, rising as the front card leaves. */
const stackTransform = (depth: number, progress: number, fanned: boolean) =>
  `translate3d(0,${depth * (fanned ? 16 : 11) - progress * 11}px,0) scale(${1 - depth * 0.05 + progress * 0.05}) rotate(${fanned ? (depth % 2 ? -1 : 1) * depth * 1.3 : 0}deg)`;

/**
 * A tactile stack. Gestures write transforms straight onto the cards, and every card has its own compositor layer,
 * so a drag moves pictures instead of repainting them. React changes only when a card is chosen.
 */
export function CardDeck<T extends { id: string }>({
  items,
  renderCard,
  getLabel = (item) => item.id,
  value,
  defaultValue,
  onValueChange,
  label = "Card collection",
  height = 340,
  className = "",
  ...props
}: CardDeckProps<T>) {
  const reduced = useInteractionReducedMotion();
  const [own, setOwn] = React.useState(defaultValue ?? items[0]?.id);
  const selected = value ?? own;
  const index = Math.max(
    0,
    items.findIndex((item) => item.id === selected),
  );
  const current = items[index];
  const [leaving, setLeaving] = React.useState<DeckThrow | null>(null);
  const busy = React.useRef(false);
  const [fanned, setFanned] = React.useState(false);
  const restoreCardFocus = React.useRef(false);

  const choose = (direction: number, from?: number, velocity = 0) => {
    if (items.length < 2 || !current || busy.current) return false;
    const next = items[(index + direction + items.length) % items.length];
    restoreCardFocus.current = Boolean(
      document.activeElement?.hasAttribute("data-deck-active"),
    );
    busy.current = !reduced;
    const transform = frontRef.current
      ? getComputedStyle(frontRef.current).transform
      : "none";
    const origin =
      from ?? (transform === "none" ? 0 : new DOMMatrixReadOnly(transform).m41);
    if (!reduced)
      setLeaving({ id: current.id, direction, from: origin, velocity });
    if (value === undefined) setOwn(next.id);
    onValueChange?.(next.id);
    return true;
  };
  const backs = React.useRef(new Map<number, HTMLDivElement>());
  const fannedRef = React.useRef(false);
  const onProgress = (progress: number, settle: boolean) => {
    if (reduced) return;
    backs.current.forEach((el, depth) => {
      el.style.transition = settle ? `transform 480ms ${EASE_SETTLE}` : "none";
      el.style.transform = stackTransform(depth, progress, fannedRef.current);
    });
  };
  const { rootRef, frontRef, dragging, handlers, resetFront } =
    useCardDeckGesture({
      id: current?.id,
      count: items.length,
      reduced,
      onThrow: choose,
      onProgress,
    });

  if (leaving && leaving.id === current?.id) {
    setLeaving(null);
  }

  React.useLayoutEffect(() => {
    if (restoreCardFocus.current) {
      frontRef.current?.focus({ preventScroll: true });
      restoreCardFocus.current = false;
    }
  }, [current?.id, frontRef]);

  React.useLayoutEffect(() => {
    if (leaving && leaving.id === current?.id) {
      // A controlled parent may reject a selection. Keep the original card available.
      resetFront();
      busy.current = false;
    }
  }, [leaving, current?.id, resetFront]);

  React.useEffect(() => {
    const timer = window.setTimeout(
      () => {
        setLeaving(null);
        busy.current = false;
      },
      reduced ? 0 : 430,
    );
    return () => window.clearTimeout(timer);
  }, [selected, leaving, reduced]);

  const ordered = current
    ? Array.from({ length: Math.min(4, items.length) }, (_, depth) => ({
        item: items[(index + depth) % items.length],
        depth,
      }))
    : [];
  const departing = leaving && items.find((item) => item.id === leaving.id);
  const expanded = fanned && !reduced;
  React.useLayoutEffect(() => {
    fannedRef.current = expanded;
  });

  return (
    <div
      ref={rootRef}
      aria-label={label}
      role="region"
      className={`w-full text-foreground ${className}`}
      {...props}
    >
      <div className="mx-auto max-w-[320px] px-3">
        <div
          className="relative isolate"
          style={{ height: Math.max(120, height) }}
          onPointerEnter={() => setFanned(true)}
          onPointerLeave={() => setFanned(false)}
        >
          {ordered
            .slice()
            .reverse()
            .map(({ item, depth }) => {
              const active = depth === 0;
              return (
                <div
                  key={item.id}
                  ref={
                    active
                      ? frontRef
                      : (el) => {
                          if (el) backs.current.set(depth, el);
                        }
                  }
                  tabIndex={active ? 0 : -1}
                  role="group"
                  aria-roledescription="card"
                  aria-label={
                    active
                      ? `${getLabel(item)}, ${index + 1} of ${items.length}. Use Left and Right to browse.`
                      : undefined
                  }
                  aria-hidden={!active || undefined}
                  inert={!active}
                  data-deck-active={active || undefined}
                  onKeyDown={
                    active
                      ? (event) => {
                          if (event.target !== event.currentTarget) return;
                          if (
                            event.key === "ArrowRight" ||
                            event.key === "ArrowLeft"
                          ) {
                            event.preventDefault();
                            choose(event.key === "ArrowRight" ? 1 : -1);
                          }
                        }
                      : undefined
                  }
                  onFocus={active ? () => setFanned(true) : undefined}
                  onBlur={
                    active
                      ? (event) => {
                          if (
                            !event.currentTarget.contains(
                              event.relatedTarget as Node,
                            )
                          )
                            setFanned(false);
                        }
                      : undefined
                  }
                  {...(active ? handlers : {})}
                  className={`absolute inset-0 overflow-hidden rounded-[22px] border border-border bg-card text-card-foreground ${active ? `${dragging ? "cursor-grabbing" : "cursor-grab"} ${INTERACTION_FOCUS}` : "pointer-events-none"}`}
                  style={{
                    zIndex: 10 - depth,
                    touchAction: active ? "pan-y" : undefined,
                    willChange: reduced ? undefined : "transform",
                    transform: active
                      ? undefined
                      : stackTransform(depth, 0, expanded),
                    transformOrigin: "50% 100%",
                    transition:
                      reduced || dragging
                        ? "none"
                        : `transform 520ms ${EASE_SETTLE}`,
                  }}
                >
                  {renderCard(item, { active, index: items.indexOf(item) })}
                </div>
              );
            })}
          {leaving && departing && (
            <DepartingCard key={leaving.id} motion={leaving} reduced={reduced}>
              {renderCard(departing, {
                active: false,
                index: items.indexOf(departing),
              })}
            </DepartingCard>
          )}
        </div>
      </div>
      {current && (
        <div className="mt-14 flex items-center justify-center gap-5">
          <button
            type="button"
            aria-label="Previous card"
            disabled={items.length < 2}
            onClick={() => choose(-1)}
            className={`cursor-pointer disabled:cursor-default flex size-9 items-center justify-center rounded-full border border-border transition-colors hover:bg-accent disabled:opacity-30 ${INTERACTION_FOCUS}`}
          >
            <ArrowLeft className="size-3.5" aria-hidden="true" />
          </button>
          <p
            aria-live="polite"
            aria-atomic="true"
            className="min-w-12 text-center font-mono text-[11px] tabular-nums text-muted-foreground"
          >
            <NumberRoll
              value={index + 1}
              format={{ minimumIntegerDigits: 2 }}
            />{" "}
            /{" "}
            <NumberRoll
              value={items.length}
              format={{ minimumIntegerDigits: 2 }}
            />
          </p>
          <button
            type="button"
            aria-label="Next card"
            disabled={items.length < 2}
            onClick={() => choose(1)}
            className={`cursor-pointer disabled:cursor-default flex size-9 items-center justify-center rounded-full border border-border transition-colors hover:bg-accent disabled:opacity-30 ${INTERACTION_FOCUS}`}
          >
            <ArrowRight className="size-3.5" aria-hidden="true" />
          </button>
        </div>
      )}
    </div>
  );
}

"use client";

import * as React from "react";
import { ArrowRight, Tag, X } from "lucide-react";
import { Faces } from "./faces";
import { Input } from "./input";
import { NumberRoll } from "./number-roll";
import { StatusButton, type ActionStatus } from "./status-button";
import { StepperInput } from "./stepper-input";
import { TextMorph } from "./text-morph";
import {
  EASE_THROW,
  INTERACTION_FOCUS,
  INTERACTION_PRESS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * CART: a receipt that does the maths in front of you
 *
 *   items     rows with a tile, a stepper and a line total that
 *             rolls; changes are sent once you stop pressing, and
 *             a refusal ("Only 2 left") puts the row back and says so
 *   remove    the row folds into "Removed · Undo" over a draining
 *             thin line; nothing is removed until it runs out
 *   code      the code you apply is stamped onto the cart as a
 *             chip, and the discount rolls into the receipt
 *   receipt   the lit surface: a rail of light fills toward free
 *             shipping, every line and the total roll as you go
 *
 * The cart is yours: pass items, and do the work in onQuantity-
 * Change, onRemove, onApplyCode and onCheckout. Each is one async
 * call to your API; throw an Error and its message shows where
 * the thing happened.
 * ───────────────────────────────────────────────────────── */

export interface CartItem {
  id: string;
  name: string;
  /** A line under the name, e.g. "Sand · M". */
  variant?: string;
  /** Unit price in major units. */
  price: number;
  quantity: number;
  /** Most you can have, e.g. what's in stock. */
  max?: number;
  /** Product photo; a tinted tile with the icon or initials when missing. */
  image?: string;
  icon?: React.ReactNode;
}

export interface CartDiscount {
  code: string;
  /** Off the subtotal, e.g. 20 for 20%. */
  percent?: number;
  /** A fixed amount off, in major units. */
  amount?: number;
}

export interface CartSummary {
  items: { id: string; quantity: number }[];
  code: string | null;
  subtotal: number;
  discount: number;
  shipping: number;
  total: number;
}

export interface CartProps {
  items: CartItem[];
  /** The applied code, if you keep it (controlled); otherwise the cart remembers what onApplyCode returned. */
  discount?: CartDiscount | null;
  /** Flat shipping cost below the free-shipping threshold. */
  shipping?: number;
  /** Order value (after discount) that ships free; draws the rail on the receipt. */
  freeShippingAt?: number;
  /** Save a new quantity; throw an Error (e.g. "Only 2 left") to put it back. */
  onQuantityChange?: (id: string, quantity: number) => Promise<unknown>;
  /** Remove an item once its Undo runs out. */
  onRemove?: (id: string) => Promise<unknown>;
  /** Check a code and return what it's worth; throw an Error to say why not. */
  onApplyCode?: (code: string) => Promise<CartDiscount>;
  onRemoveCode?: () => Promise<unknown>;
  /** Start checkout; resolve once you're redirecting. */
  onCheckout?: (summary: CartSummary) => Promise<unknown>;
  title?: string;
  currency?: string;
  locale?: string;
  className?: string;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const UNDO_MS = 4000;
const SEND_AFTER = 450;
const NO_DISCOUNT = null;

const mix = (color: string, amount: number, into = "transparent") =>
  `color-mix(in oklab, ${color} ${amount}%, ${into})`;
const RECEIPT: React.CSSProperties = {
  backgroundColor: "var(--primary)",
  backgroundImage: `radial-gradient(120% 90% at 0% 0%, ${mix("var(--primary-foreground)", 22)} 0%, transparent 55%), linear-gradient(170deg, transparent 40%, ${mix("black", 24)} 100%)`,
  boxShadow: `inset 0 1px 0 ${mix("var(--primary-foreground)", 36)}, inset 0 0 0 1px ${mix("var(--primary-foreground)", 12)}`,
};
const CARD: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, var(--card), ${mix("var(--card)", 95, "var(--foreground)")})`,
  boxShadow: `0 0 0 1px var(--border), inset 0 1px 0 ${mix("var(--background)", 85)}`,
};
/* The action on the lit receipt: the light colour with the brand colour as its text. */
const INVERSE: React.CSSProperties = {
  background: "var(--primary-foreground)",
  color: "var(--primary)",
  boxShadow: `inset 0 -1px 0 ${mix("black", 8)}`,
};
/* The rail's ruler: an engraved tick every tenth of the way, the light running over it. */
const TICKS: React.CSSProperties = {
  backgroundImage: `repeating-linear-gradient(90deg, ${mix("var(--primary-foreground)", 28)} 0 1px, transparent 1px 10%)`,
};

function tint(seed: string): React.CSSProperties {
  let h = 0;
  for (const c of seed) h = (h * 31 + c.charCodeAt(0)) >>> 0;
  const chart = `var(--chart-${(h % 5) + 1}, var(--primary))`;
  return {
    background: mix(chart, 18, "var(--card)"),
    color: mix(chart, 72, "var(--foreground)"),
    boxShadow: `inset 0 0 0 1px ${mix(chart, 24)}`,
  };
}

const initials = (name: string) =>
  name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((w) => w[0]?.toUpperCase())
    .join("");

const money = (currency: string, n: number): Intl.NumberFormatOptions => ({
  style: "currency",
  currency,
  minimumFractionDigits: n % 1 ? 2 : 0,
  maximumFractionDigits: 2,
});
const errorOf = (e: unknown, fallback: string) =>
  e instanceof Error && e.message ? e.message : fallback;

/** A line that comes and goes by height, keeping its last content while it folds. */
function Fold({
  open,
  reduced,
  children,
}: {
  open: boolean;
  reduced: boolean;
  children: React.ReactNode;
}) {
  return (
    <div
      className="grid grid-cols-1"
      style={{
        gridTemplateRows: open ? "1fr" : "0fr",
        opacity: open ? 1 : 0,
        transition: reduced
          ? "opacity 160ms"
          : `grid-template-rows 420ms ${EASE}, opacity ${open ? 320 : 140}ms ${EASE}`,
      }}
    >
      <div className="min-h-0 overflow-clip">{children}</div>
    </div>
  );
}

type Row = {
  qty?: number;
  settled?: boolean;
  pending?: boolean;
  error?: string;
  removing?: boolean;
  gone?: boolean;
};

export function Cart({
  items,
  discount: discountProp,
  shipping,
  freeShippingAt,
  onQuantityChange,
  onRemove,
  onApplyCode,
  onRemoveCode,
  onCheckout,
  title = "Your cart",
  currency = "USD",
  locale,
  className = "",
}: CartProps) {
  const reduced = useInteractionReducedMotion();
  const baseId = React.useId();
  const [rows, setRows] = React.useState<Record<string, Row>>({});
  const [ready, setReady] = React.useState(false);
  const [ownDiscount, setOwnDiscount] = React.useState<CartDiscount | null>(
    NO_DISCOUNT,
  );
  const discount = discountProp !== undefined ? discountProp : ownDiscount;
  const [code, setCode] = React.useState("");
  const [codeStatus, setCodeStatus] = React.useState<ActionStatus>("idle");
  const [codeError, setCodeError] = React.useState<string | null>(null);
  const [checkout, setCheckout] = React.useState<{
    status: ActionStatus;
    error?: string;
  }>({ status: "idle" });
  const [said, setSaid] = React.useState("");
  const timers = React.useRef(new Map<string, number>());
  const rowEls = React.useRef(new Map<string, HTMLElement>());
  const chipRef = React.useRef<HTMLDivElement>(null);
  const codeInputRef = React.useRef<HTMLInputElement>(null);

  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setReady(true));
    const all = timers.current;
    return () => {
      cancelAnimationFrame(frame);
      all.forEach((t) => window.clearTimeout(t));
    };
  }, []);

  // When your items change, quantities you've saved give way to what you now say.
  const [seenItems, setSeenItems] = React.useState(items);
  if (items !== seenItems) {
    setSeenItems(items);
    setRows((r) =>
      Object.fromEntries(
        Object.entries(r).filter(
          ([id, row]) => items.some((i) => i.id === id) && !row.settled,
        ),
      ),
    );
  }

  const patch = (id: string, next: Partial<Row> | null) =>
    setRows((r) => {
      const copy = { ...r };
      if (next === null) delete copy[id];
      else copy[id] = { ...copy[id], ...next };
      return copy;
    });

  const qtyOf = (i: CartItem) => rows[i.id]?.qty ?? i.quantity;
  const live = items.filter((i) => !rows[i.id]?.removing && !rows[i.id]?.gone);
  const count = live.reduce((n, i) => n + qtyOf(i), 0);
  const subtotal =
    Math.round(live.reduce((n, i) => n + i.price * qtyOf(i), 0) * 100) / 100;
  const off = discount
    ? Math.min(
        subtotal,
        Math.round(
          (discount.percent
            ? (subtotal * discount.percent) / 100
            : (discount.amount ?? 0)) * 100,
        ) / 100,
      )
    : 0;
  const after = subtotal - off;
  const free = freeShippingAt !== undefined && after >= freeShippingAt;
  const ship = live.length === 0 || free ? 0 : (shipping ?? 0);
  const total = Math.round((after + ship) * 100) / 100;
  const progress = freeShippingAt ? Math.min(1, after / freeShippingAt) : 0;
  const busy = checkout.status === "pending" || checkout.status === "success";

  const setQty = (item: CartItem, q: number) => {
    patch(item.id, { qty: q, settled: false, error: undefined });
    window.clearTimeout(timers.current.get(item.id));
    // Sent once you stop pressing, so five taps are one request.
    timers.current.set(
      item.id,
      window.setTimeout(async () => {
        if (!onQuantityChange) return patch(item.id, { settled: true });
        patch(item.id, { pending: true });
        try {
          await onQuantityChange(item.id, q);
          patch(item.id, { pending: false, settled: true });
        } catch (e) {
          setRows((r) => ({
            ...r,
            [item.id]: { error: errorOf(e, "Couldn’t update that.") },
          }));
          rowEls.current
            .get(item.id)
            ?.animate(
              [
                { transform: "none" },
                { transform: "translateX(-4px)" },
                { transform: "translateX(4px)" },
                { transform: "none" },
              ],
              { duration: 340, easing: "ease-out" },
            );
        }
      }, SEND_AFTER),
    );
  };

  const remove = (item: CartItem) => {
    window.clearTimeout(timers.current.get(item.id));
    patch(item.id, { removing: true, error: undefined });
    setSaid(`${item.name} removed. Undo is available for a few seconds.`);
    timers.current.set(
      item.id,
      window.setTimeout(async () => {
        patch(item.id, { gone: true });
        try {
          await onRemove?.(item.id);
        } catch (e) {
          patch(item.id, {
            gone: false,
            removing: false,
            error: errorOf(e, "Couldn’t remove that."),
          });
        }
      }, UNDO_MS),
    );
  };

  const undo = (item: CartItem) => {
    window.clearTimeout(timers.current.get(item.id));
    patch(item.id, { removing: false });
    setSaid(`${item.name} is back in your cart.`);
    window.setTimeout(
      () =>
        rowEls.current
          .get(item.id)
          ?.querySelector<HTMLElement>("input,button")
          ?.focus({ preventScroll: true }),
      60,
    );
  };

  const apply = async () => {
    const value = code.trim();
    if (!value || codeStatus === "pending") return;
    if (!onApplyCode) return;
    setCodeStatus("pending");
    setCodeError(null);
    try {
      const d = await onApplyCode(value);
      setOwnDiscount(d);
      setCodeStatus("idle");
      setCode("");
      setSaid(`Code ${d.code} applied.`);
    } catch (e) {
      setCodeStatus("error");
      setCodeError(errorOf(e, "That code didn’t work."));
    }
  };

  const removeCode = async () => {
    setOwnDiscount(null);
    setSaid("Code removed.");
    window.setTimeout(
      () => codeInputRef.current?.focus({ preventScroll: true }),
      80,
    );
    try {
      await onRemoveCode?.();
    } catch {
      // The code stays off here; your server is the judge on the next checkout.
    }
  };

  // The code is stamped on: it lands big and tilted out of a blur and is thrown down flat.
  const stamped = discount?.code ?? null;
  const lastStamp = React.useRef<string | null>(null);
  React.useLayoutEffect(() => {
    const was = lastStamp.current;
    lastStamp.current = stamped;
    if (!ready || !stamped || stamped === was || reduced) return;
    chipRef.current?.animate(
      [
        {
          transform: "scale(1.5) rotate(-9deg)",
          opacity: 0,
          filter: "blur(6px)",
        },
        {
          transform: "scale(0.94) rotate(1.5deg)",
          opacity: 1,
          filter: "blur(0px)",
          offset: 0.55,
        },
        { transform: "none", opacity: 1, filter: "blur(0px)" },
      ],
      { duration: 560, easing: EASE_THROW },
    );
  }, [stamped, ready, reduced]);

  const pay = async () => {
    if (busy || !live.length) return;
    setCheckout({ status: "pending" });
    try {
      await onCheckout?.({
        items: live.map((i) => ({ id: i.id, quantity: qtyOf(i) })),
        code: discount?.code ?? null,
        subtotal,
        discount: off,
        shipping: ship,
        total,
      });
      setCheckout({ status: "success" });
    } catch (e) {
      setCheckout({
        status: "error",
        error: errorOf(e, "Couldn’t start checkout. Try again."),
      });
    }
  };

  const fmt = (n: number) => money(currency, n);

  return (
    <section
      aria-labelledby={`${baseId}-title`}
      className={`w-full max-w-[440px] rounded-[28px] p-2 text-card-foreground ${className}`}
      style={CARD}
    >
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 440px)" }}
      />
      <div className="@container w-full">
        <div className="flex items-baseline justify-between px-3 pb-1 pt-2.5">
          <h2
            id={`${baseId}-title`}
            className="text-[15px] font-medium tracking-[-0.01em]"
          >
            {title}
          </h2>
          <p className="text-[12.5px] tabular-nums text-muted-foreground">
            <NumberRoll value={count} duration={600} />{" "}
            <TextMorph>{count === 1 ? "item" : "items"}</TextMorph>
          </p>
        </div>

        <Fold
          open={live.length === 0 && !items.some((i) => rows[i.id]?.removing)}
          reduced={reduced}
        >
          <p className="px-3 py-6 text-center text-[13.5px] text-muted-foreground">
            Your cart is empty.
          </p>
        </Fold>

        <ul className="px-1">
          {items.map((item) => {
            const row = rows[item.id] ?? {};
            const q = qtyOf(item);
            return (
              <li
                key={item.id}
                className="grid grid-cols-1"
                style={{
                  gridTemplateRows: row.gone ? "0fr" : "1fr",
                  opacity: row.gone ? 0 : 1,
                  transition: reduced
                    ? "opacity 160ms"
                    : `grid-template-rows 380ms ${EASE} 100ms, opacity 200ms ${EASE}`,
                }}
              >
                <div className="min-h-0 overflow-clip">
                  <div
                    ref={(el) => {
                      if (el) rowEls.current.set(item.id, el);
                      else rowEls.current.delete(item.id);
                    }}
                    className="border-b border-border/70 py-2"
                  >
                    <Faces
                      active={row.removing ? 1 : 0}
                      reduced={reduced}
                      ready={ready}
                    >
                      <div className="flex gap-3 px-2">
                        <span
                          aria-hidden="true"
                          className="relative flex size-[52px] shrink-0 items-center justify-center overflow-hidden rounded-[14px] text-[14px] font-medium [&_svg]:size-[22px]"
                          style={tint(item.name)}
                        >
                          {item.icon ?? initials(item.name)}
                          {item.image && (
                            <img
                              src={item.image}
                              alt=""
                              decoding="async"
                              className="absolute inset-0 size-full object-cover"
