/* ─────────────────────────────────────────────────────────
 * CAST SPRITE: play a strip of animation frames on an element
 *
 * A strip is a row of frames in one image. Playing it
 * is one Web Animation of background-position in steps(), so
 * a looping idle costs no frame loop and no React renders;
 * reduced motion shows the first frame and nothing moves.
 * ───────────────────────────────────────────────────────── */

export interface StripPlay {
  /** The strip, as an image URL. */
  src: string;
  frames: number;
  fps: number;
  /** One frame's size on screen, in px (height defaults to width). */
  size: number;
  height?: number;
  /** Loop forever (an idle), or play once and hold the last frame. */
  loop?: boolean;
  /** Play a one-shot strip backwards, ending on its first frame. */
  reverse?: boolean;
  reduced?: boolean;
  /** Called once a one-shot strip has played. */
  onEnd?: () => void;
}

/** Show `play` on `el`, replacing whatever it was playing. Returns the animation, if any. */
export function playStrip(
  el: HTMLElement | null,
  play: StripPlay,
): Animation | null {
  if (!el) return null;
  el.getAnimations().forEach((a) => a.cancel());
  const {
    src,
    frames,
    fps,
    size,
    height = size,
    loop = true,
    reverse = false,
    reduced = false,
    onEnd,
  } = play;
  const width = frames * size;
  if (el.dataset.strip !== src) {
    el.dataset.strip = src;
    el.style.backgroundImage = `url("${src}")`;
  }
  el.style.backgroundSize = `${width}px ${height}px`;
  el.style.backgroundRepeat = "no-repeat";
  const end = -(frames - 1) * size;
  const rest = loop || reverse ? 0 : end;
  el.style.backgroundPosition = `${rest}px 0px`;
  if (reduced || frames < 2) {
    onEnd?.();
    return null;
  }
  // steps(end) shows the start value first and lands on the end value as it finishes (the resting style then holds it)
  const keys =
    reverse && !loop
      ? [
          { backgroundPosition: `${end}px 0px` },
          { backgroundPosition: "0px 0px" },
        ]
      : [
          { backgroundPosition: "0px 0px" },
          { backgroundPosition: `${loop ? -width : end}px 0px` },
        ];
  const a = el.animate(keys, {
    duration: ((loop ? frames : frames - 1) * 1000) / fps,
    iterations: loop ? Infinity : 1,
    easing: `steps(${loop ? frames : frames - 1}, end)`,
  });
  if (!loop && onEnd) a.onfinish = () => onEnd();
  return a;
}

/** Decode strips up front, so the first frame of each is there the moment it plays. */
export function preloadStrips(srcs: string[]) {
  for (const src of srcs) {
    const img = new Image();
    img.src = src;
    void img.decode?.().catch(() => {});
  }
}

"use client";

import {
  Children,
  cloneElement,
  isValidElement,
  useEffect,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type KeyboardEvent,
  type PointerEvent,
  type ReactNode,
  type Ref,
} from "react";
import {
  animate,
  motion,
  useMotionValue,
  useReducedMotion,
} from "motion/react";

export type AnswerPaperLevel = {
  id: string;
  label: string;
  content: ReactNode;
  /** Estimated reading time in seconds, supplied with each answer version. */
  readTime: number;
};

export type CavemioAnswerPaperProps = {
  /** Answer versions ordered from shortest to longest. */
  levels: readonly AnswerPaperLevel[];
  /** Controlled index into levels. */
  level?: number;
  /** Starts with the longest answer when omitted. */
  defaultLevel?: number;
  onLevelChange?: (index: number) => void;
  paperColor?: CSSProperties["backgroundColor"];
  paperRadius?: CSSProperties["borderRadius"];
  textColor?: CSSProperties["color"];
  handleColor?: CSSProperties["color"];
  disabled?: boolean;
  ariaLabel?: string;
  className?: string;
  style?: CSSProperties;
};

const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));
const indexWithin = (value: number, count: number) =>
  clamp(Number.isFinite(value) ? Math.round(value) : count - 1, 0, count - 1);

const WORD_EASE = "cubic-bezier(0.16,1,0.3,1)";

// Keep rich-text structure and natural whitespace while giving each word a box.
function wordify(content: ReactNode): ReactNode {
  return Children.map(content, (child) => {
    if (typeof child === "string" || typeof child === "number") {
      return String(child)
        .split(/(\s+)/)
        .map((part, index) =>
          !part || /^\s+$/.test(part) ? (
            part
          ) : (
            <span key={index} data-answer-word="" className="inline-block">
              {part}
            </span>
          ),
        );
    }
    if (
      isValidElement<{ children?: ReactNode }>(child) &&
      child.props.children
    ) {
      return cloneElement(child, { children: wordify(child.props.children) });
    }
    return child;
  });
}

// Match shared words in reading order.
// Matching across blocks lets a sentence glide from a section into a summary.
function matchWords(before: HTMLElement[], after: HTMLElement[]) {
  const beforeText = before.map((word) => word.textContent);
  const afterText = after.map((word) => word.textContent);
  const table = Array.from(
    { length: before.length + 1 },
    () => new Uint32Array(after.length + 1),
  );
  for (let i = before.length - 1; i >= 0; i--) {
    for (let j = after.length - 1; j >= 0; j--) {
      table[i][j] =
        beforeText[i] === afterText[j]
          ? table[i + 1][j + 1] + 1
          : Math.max(table[i + 1][j], table[i][j + 1]);
    }
  }
  const matches = new Map<number, number>();
  let i = 0;
  let j = 0;
  while (i < before.length && j < after.length) {
    if (beforeText[i] === afterText[j]) {
      matches.set(j++, i++);
    } else if (table[i + 1][j] >= table[i][j + 1]) i++;
    else j++;
  }
  return matches;
}

function useWordTransition(
  active: number,
  layers: { current: (HTMLDivElement | null)[] },
  overlay: { current: HTMLDivElement | null },
  reduced: boolean,
) {
  const previous = useRef(active);
  useLayoutEffect(() => {
    const from = layers.current[previous.current];
    const to = layers.current[active];
    const ghosts = overlay.current;
    previous.current = active;
    if (!to || !ghosts) return;
    if (reduced) {
      layers.current.forEach((layer) =>
        layer
          ?.getAnimations({ subtree: true })
          .forEach((animation) => animation.cancel()),
      );
      ghosts.replaceChildren();
      return;
    }
    if (!from || from === to) return;

    const before = Array.from(
      from.querySelectorAll<HTMLElement>("[data-answer-word]"),
    );
    const after = Array.from(
      to.querySelectorAll<HTMLElement>("[data-answer-word]"),
    );
    const origin = ghosts.getBoundingClientRect();
    // Read presentation positions and opacity BEFORE cancelling an interrupted morph.
    const first = before.map((word) => {
      const rect = word.getBoundingClientRect();
      const style = getComputedStyle(word);
      return {
        rect,
        opacity: style.opacity,
        filter: style.filter,
        font: style.font,
        letterSpacing: style.letterSpacing,
        color: style.color,
      };
    });
    const matches = matchWords(before, after);
    const kept = new Set(matches.values());
    layers.current.forEach((layer) =>
      layer
        ?.getAnimations({ subtree: true })
        .forEach((animation) => animation.cancel()),
    );
    ghosts.replaceChildren();
    const last = after.map((word) => word.getBoundingClientRect());
    let fresh = 0;
    after.forEach((word, index) => {
      const match = matches.get(index);
      const was = match === undefined ? undefined : first[match];
      if (was) {
        word.animate(
          [
            {
              transform: `translate(${was.rect.left - last[index].left}px, ${was.rect.top - last[index].top}px)`,
              opacity: was.opacity,
              filter: was.filter,
            },
            { transform: "none", opacity: 1, filter: "blur(0px)" },
          ],
          { duration: 480, easing: WORD_EASE },
        );
      } else {
        word.animate(
          [
            {
              opacity: 0,
              transform: "translateY(0.35em)",
              filter: "blur(4px)",
            },
            { opacity: 1, transform: "none", filter: "blur(0px)" },
          ],
          {
            duration: 380,
            delay: Math.min(fresh++ * 14, 120),
            easing: WORD_EASE,
            fill: "backwards",
          },
        );
      }
    });
    before.forEach((word, index) => {
      if (kept.has(index)) return;
      const was = first[index];
      if (Number(was.opacity) === 0) return;
      const ghost = document.createElement("span");
      ghost.textContent = word.textContent;
      Object.assign(ghost.style, {
        position: "absolute",
        whiteSpace: "pre",
        font: was.font,
        letterSpacing: was.letterSpacing,
        color: was.color,
        left: `${was.rect.left - origin.left}px`,
        top: `${was.rect.top - origin.top}px`,
      });
      ghosts.appendChild(ghost);
      const animation = ghost.animate(
        [
          { opacity: was.opacity, transform: "none", filter: was.filter },
          {
            opacity: 0,
            transform: "translateY(-0.2em) scale(0.96)",
            filter: "blur(4px)",
          },
        ],
        { duration: 240, easing: WORD_EASE, fill: "forwards" },
      );
      animation.onfinish = () => ghost.remove();
    });
  }, [active, layers, overlay, reduced]);

  useEffect(() => {
    const nodes = layers.current;
    const ghosts = overlay.current;
    return () => {
      nodes.forEach((node) =>
        node
          ?.getAnimations({ subtree: true })
          .forEach((animation) => animation.cancel()),
      );
      ghosts?.replaceChildren();
    };
  }, [layers, overlay]);
}

function AnswerLayer({
  answer,
  index,
  active,
  contentRef,
  answerId,
}: {
  answer: AnswerPaperLevel;
  index: number;
  active: number;
  contentRef: Ref<HTMLDivElement>;
  answerId: string;
}) {
  const content = useMemo(() => wordify(answer.content), [answer.content]);
  return (
    <div
      ref={contentRef}
      data-answer-layer=""
      id={index === active ? answerId : undefined}
      aria-hidden={index !== active}
      inert={index !== active}
      className="absolute inset-x-0 top-0 p-6 text-[15px] font-normal leading-[1.65] tracking-[-0.012em] [&_h3]:mb-2 [&_h3]:text-[16px] [&_h3]:font-semibold [&_h3]:leading-[1.35] [&_p]:m-0 [&_section+section]:mt-6 [&_ul]:my-3 [&_ul]:list-disc [&_ul]:pl-5 [&_li+li]:mt-1"
      style={{
        // Chrome can retain an animated child's inherited visibility:hidden
        // after its layer becomes visible. Opacity does not inherit, so words
        // always settle back to their normal painted state.
        opacity: index === active ? 1 : 0,
        pointerEvents: index === active ? "auto" : "none",
      }}
    >
      {content}
    </div>
  );
}

/** A resizable answer whose content changes in detail as its paper is dragged. */
export function CavemioAnswerPaper({
  levels,
  level,
  defaultLevel = levels.length - 1,
  onLevelChange,
  paperColor = "var(--card, var(--background))",
  paperRadius = 14,
  textColor = "var(--foreground)",
  handleColor = "var(--accent-ink, var(--foreground))",
  disabled = false,
  ariaLabel = "Answer length",
  className,
  style,
}: CavemioAnswerPaperProps) {
  const [internalLevel, setInternalLevel] = useState(defaultLevel);
  const [heights, setHeights] = useState<number[]>([]);
  const [dragging, setDragging] = useState(false);
  const active = indexWithin(level ?? internalLevel, levels.length);
  const selected = levels[active];
  const contentRefs = useRef<(HTMLDivElement | null)[]>([]);
  const overlayRef = useRef<HTMLDivElement | null>(null);
  const height = useMotionValue(0);
  const reducedMotion = useReducedMotion();
  const releaseVelocity = useRef(0);
  const activeRef = useRef(active);
  const drag = useRef<{
    pointer: number;
    target: HTMLDivElement;
    y: number;
    height: number;
    startLevel: number;
    samples: { y: number; time: number }[];
  } | null>(null);
  const instructionsId = useId();
  const answerId = useId();
  activeRef.current = active;
  useWordTransition(active, contentRefs, overlayRef, Boolean(reducedMotion));

  useLayoutEffect(() => {
    const nodes = contentRefs.current.slice(0, levels.length);
    const measure = () => {
      const next = nodes.map((node) => node?.offsetHeight ?? 0);
      if (next.some((size) => size === 0)) return;
      setHeights((previous) =>
        next.length === previous.length &&
        next.every((size, i) => size === previous[i])
          ? previous
          : next,
      );
      if (height.get() === 0) height.jump(next[activeRef.current]);
    };
    measure();
    const observer = new ResizeObserver(measure);
    nodes.forEach((node) => node && observer.observe(node));
    return () => observer.disconnect();
  }, [levels, height]);

  useLayoutEffect(() => {
    if (drag.current && !disabled) return;
    const gesture = drag.current;
    drag.current = null;
    if (gesture?.target.hasPointerCapture(gesture.pointer)) {
      gesture.target.releasePointerCapture(gesture.pointer);
    }
    if (disabled && dragging) setDragging(false);
    if (!heights[active]) return;
    if (reducedMotion) {
      height.jump(heights[active]);
      return;
    }
    const animation = animate(height, heights[active], {
      type: "spring",
      stiffness: 440,
      damping: 42,
      mass: 0.8,
      velocity: releaseVelocity.current,
    });
    releaseVelocity.current = 0;
    return () => animation.stop();
  }, [active, heights, dragging, disabled, height, reducedMotion]);

  if (!selected) {
    throw new Error("CavemioAnswerPaper needs at least one answer level.");
  }

  function select(index: number) {
    const next = indexWithin(index, levels.length);
    if (next === activeRef.current) return;
    activeRef.current = next;
    if (level === undefined) setInternalLevel(next);
    onLevelChange?.(next);
  }

  function levelAtHeight(size: number, current = activeRef.current) {
    let next = current;
    // Separate thresholds prevent tiny pointer reversals from restarting a rewrite.
    // Shorten early, before the longer answer would be clipped by its paper.
    while (next > 0) {
      const gap = heights[next] - heights[next - 1];
      if (size >= heights[next] - Math.min(52, gap * 0.32)) break;
      next--;
    }
    while (next < heights.length - 1) {
      const gap = heights[next + 1] - heights[next];
      if (size <= heights[next + 1] - Math.min(28, gap * 0.16)) break;
      next++;
    }
    return next;
  }

  function start(event: PointerEvent<HTMLDivElement>) {
    if (
      disabled ||
      levels.length < 2 ||
      heights.length !== levels.length ||
      event.button !== 0 ||
      drag.current
    )
      return;
    event.preventDefault();
    event.currentTarget.dataset.pointerFocus = "true";
    event.currentTarget.focus({ preventScroll: true });
    event.currentTarget.setPointerCapture(event.pointerId);
    height.stop();
    drag.current = {
      pointer: event.pointerId,
      target: event.currentTarget,
      y: event.clientY,
      height: height.get(),
      startLevel: active,
      samples: [{ y: event.clientY, time: event.timeStamp }],
    };
    setDragging(true);
  }

  function move(event: PointerEvent<HTMLDivElement>) {
    const gesture = drag.current;
    if (!gesture || gesture.pointer !== event.pointerId) return;
    const min = Math.min(...heights);
    const max = Math.max(...heights);
    const raw = gesture.height + event.clientY - gesture.y;
    const bounded = clamp(raw, min, max);
    const overflow = raw - bounded;
    // A soft edge stays responsive without letting the paper escape its bounds.
    const resistance = reducedMotion
      ? 0
      : (overflow * 0.18) / (1 + Math.abs(overflow) / 100);
    height.set(bounded + resistance);
    gesture.samples.push({ y: event.clientY, time: event.timeStamp });
    gesture.samples = gesture.samples.filter(
      (sample) => event.timeStamp - sample.time <= 80,
    );
    select(levelAtHeight(bounded));
  }

  function finish(event: PointerEvent<HTMLDivElement>, cancelled = false) {
    const gesture = drag.current;
    if (!gesture || gesture.pointer !== event.pointerId) return;
    const first = gesture.samples[0];
    const last = gesture.samples.at(-1)!;
    const velocity =
      event.timeStamp - last.time < 100 && last.time > first.time
        ? clamp(
            ((last.y - first.y) / (last.time - first.time)) * 1000,
            -1600,
            1600,
          )
        : 0;
    drag.current = null;
    releaseVelocity.current = cancelled ? 0 : velocity;
    select(
      cancelled
        ? gesture.startLevel
        : levelAtHeight(height.get() + clamp(velocity * 0.08, -44, 44)),
    );
    setDragging(false);
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }
  }

  function keyDown(event: KeyboardEvent<HTMLDivElement>) {
    delete event.currentTarget.dataset.pointerFocus;
    if (disabled) return;
    const next = {
      ArrowUp: active - 1,
      ArrowLeft: active - 1,
      ArrowDown: active + 1,
      ArrowRight: active + 1,
      Home: 0,
      End: levels.length - 1,
    }[event.key];
    if (next === undefined) return;
    event.preventDefault();
    // Keyboard input takes over immediately, even while a pointer is held down.
    const gesture = drag.current;
    if (gesture) {
      drag.current = null;
      releaseVelocity.current = 0;
      setDragging(false);
      if (gesture.target.hasPointerCapture(gesture.pointer)) {
        gesture.target.releasePointerCapture(gesture.pointer);
      }
    }
    select(next);
  }

  return (
    <div className={className} style={{ width: "100%", ...style }}>
      <div className="relative">
        <motion.div
          style={{
            height,
            backgroundColor: paperColor,
            borderRadius: paperRadius,
            color: textColor,
            boxShadow:
              "0 26px 38px -30px rgba(48, 61, 28, 0.28), inset 0 1px 0 rgba(255,255,255,0.75)",
          }}
          className="relative overflow-hidden"
        >
          {levels.map((answer, index) => (
            <AnswerLayer
              key={answer.id}
              answer={answer}
              index={index}
              active={active}
              answerId={answerId}
              contentRef={(node) => {
                contentRefs.current[index] = node;
              }}
            />
          ))}
          <div
            ref={overlayRef}
            aria-hidden="true"
            inert
            className="pointer-events-none absolute inset-0"
          />
        </motion.div>
        <div
          role="slider"
          tabIndex={disabled || levels.length < 2 ? -1 : 0}
          aria-label={ariaLabel}
          aria-orientation="vertical"
          aria-valuemin={0}
          aria-valuemax={levels.length - 1}
          aria-valuenow={active}
          aria-valuetext={`${selected.label}, ${selected.readTime} second read`}
          aria-controls={answerId}
          aria-describedby={instructionsId}
          aria-disabled={disabled || levels.length < 2}
          onPointerDown={start}
          onPointerMove={move}
          onPointerUp={(event) => finish(event)}
          onPointerCancel={(event) => finish(event, true)}
          onLostPointerCapture={(event) => finish(event, true)}
          onKeyDown={keyDown}
          onBlur={(event) => {
            delete event.currentTarget.dataset.pointerFocus;
          }}
          title="Drag up to shorten · drag down for more detail"
          className="absolute bottom-0 left-1/2 z-10 flex h-11 w-20 -translate-x-1/2 translate-y-1/2 touch-none select-none items-center justify-center rounded-full outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-4 data-[pointer-focus=true]:ring-0 data-[pointer-focus=true]:ring-offset-0"
          style={{
            cursor:
              disabled || levels.length < 2
                ? "default"
                : dragging
                  ? "grabbing"
                  : "ns-resize",
          }}
        >
          <motion.span
            aria-hidden="true"
            animate={{
              scale: dragging && !disabled && !reducedMotion ? 1.06 : 1,
            }}
            transition={{ duration: reducedMotion ? 0 : 0.12 }}
            className="flex h-[22px] w-[56px] items-center justify-center rounded-full border border-border bg-background"
            style={{
              boxShadow:
                "0 3px 5px rgba(48,61,28,0.10), 0 10px 18px rgba(48,61,28,0.05)",
              opacity: disabled ? 0.5 : 1,
            }}
          >
            <span
              className="h-[3px] w-5 rounded-full"
              style={{ backgroundColor: handleColor }}
            />
          </motion.span>
        </div>
      </div>
      <div
        className="mt-5 pr-1 text-right text-[12px] leading-5 tabular-nums text-muted-foreground"
        aria-hidden="true"
      >
        {selected.readTime} s read
      </div>
      <span id={instructionsId} className="sr-only">
        Drag up for a shorter answer or down for more detail. Use Up and Down
        arrow keys, Home for the shortest answer, or End for the full answer.
      </span>
    </div>
  );
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * CHANGELOG SCRUBBER: release history on a ruler you scrub
 *
 *   scrub     drag the playhead along a ruler of days; the ticks
 *             swell under it like a lens and the card changes to
 *             whichever release is nearest
 *   settle    let go, click, tap or press an arrow key and the
 *             playhead is thrown onto a release
 *   change    the version riding the playhead, the date and the
 *             tag morph, the count rolls, and the release slides
 *             in from the side the playhead moved toward while
 *             the card eases to its new height
 *   step      the arrows beside the count step one release; on
 *             a phone, swipe the card: the release follows your
 *             finger and springs back at either end
 *   play      plays the history from the first release to the
 *             latest, at the pace it actually shipped; pause
 *             holds it wherever it is
 *
 * The ruler is a slider: arrows step between releases, Home and
 * End jump to the first and the latest. Nothing listens to the
 * page's scroll; frames run only while the playhead moves.
 * ───────────────────────────────────────────────────────── */

export interface ChangelogEntry {
  id: string;
  date: string | Date;
  title: string;
  version?: string;
  /** e.g. ["new"], ["improved", "fixed"]. */
  tags?: string[];
  body?: React.ReactNode;
  /** An image or video under the text. */
  media?: React.ReactNode;
}

export interface ChangelogScrubberProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onChange"
> {
  /** Newest first, as in a timeline; the ruler runs from the oldest on the left to the newest on the right. */
  entries: ChangelogEntry[];
  /** The release on show, by id. Starts on the newest. */
  value?: string;
  defaultValue?: string;
  onValueChange?: (id: string) => void;
  /** How long play takes from the first release to the latest, in ms. Defaults to 1.2s a release. */
  playDuration?: number;
  locales?: string | string[];
}

type Leaving = { index: number; dir: number; key: number; from: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const MORPH = 460;
const DAY = 86_400_000;
const LENS = 7; // how far the lens reaches either side of the playhead, in % of the ruler
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const TAG_LABEL: Record<string, string> = {
  new: "New",
  improved: "Improved",
  fixed: "Fixed",
};
const TAG_TONE: Record<string, string> = {
  new: "bg-primary/10 text-primary",
  improved: "bg-muted text-foreground/80",
  fixed: "bg-muted text-muted-foreground",
};

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** A CSS cubic-bezier solved in JS, so the playhead's tweens run on the same curves as everything else. */
function bezier(x1: number, y1: number, x2: number, y2: number) {
  const curve = (t: number, p1: number, p2: number) =>
    3 * (1 - t) * (1 - t) * t * p1 + 3 * (1 - t) * t * t * p2 + t * t * t;
  const slope = (t: number, p1: number, p2: number) =>
    3 * (1 - t) * (1 - t) * p1 +
    6 * (1 - t) * t * (p2 - p1) +
    3 * t * t * (1 - p2);
  return (x: number) => {
    if (x <= 0) return 0;
    if (x >= 1) return 1;
    let t = x;
    for (let i = 0; i < 8; i++) {
      const s = slope(t, x1, x2);
      if (Math.abs(s) < 1e-6) break;
      t = Math.min(1, Math.max(0, t - (curve(t, x1, x2) - x) / s));
    }
    return curve(t, y1, y2);
  };
}
const THROWN = bezier(0.34, 1.36, 0.64, 1);
const LINEAR = (t: number) => t;

/** A tick at p% that swells as the playhead (--x, set on the ruler) comes near. Pure CSS, so moving the playhead is one style write. */
const lens = (p: number, gain: number) =>
  ({
    left: `${p}%`,
    "--p": String(p),
    "--f": `max(0, 1 - max(var(--x) - var(--p), var(--p) - var(--x)) / ${LENS})`,
    transform: `scaleY(calc(1 + ${gain} * var(--f) * var(--f)))`,
  }) as React.CSSProperties;

const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "scale(1)" : "scale(0.6)",
  filter: on ? "blur(0px)" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 240ms ${EASE}, transform 360ms ${EASE}, filter 240ms ${EASE}`,
});

/** One release in the card; it comes in from the side the playhead moved toward and leaves the other way (from where a swipe let it go). */
function Pane({
  children,
  dir,
  leaving,
  reduced,
  from = 0,
  paneRef,
}: {
  children: React.ReactNode;
  dir: number;
  leaving: boolean;
  reduced: boolean;
  from?: number;
  paneRef?: (el: HTMLDivElement | null) => void;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el || reduced || dir === 0) return;
    const shift = 24 * dir;
    const animation = leaving
      ? el.animate(
          [
            {
              opacity: 1,
              filter: "blur(0px)",
              transform: `translateX(${from}px)`,
            },
            {
              opacity: 0,
              filter: "blur(6px)",
              transform: `translateX(${from - shift}px)`,
            },
          ],
          { duration: MORPH * 0.6, easing: EASE, fill: "forwards" },
        )
      : el.animate(
          [
            {
              opacity: 0,
              filter: "blur(6px)",
              transform: `translateX(${shift}px)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          { duration: MORPH, easing: EASE, delay: 60, fill: "backwards" },
        );
    return () => animation.cancel();
  }, [dir, leaving, reduced, from]);
  return (
    <div
      ref={(el) => {
        ref.current = el;
        paneRef?.(el);
      }}
      inert={leaving}
      aria-hidden={leaving || undefined}
      className={leaving ? "absolute inset-x-0 top-0" : "relative"}
    >
      {children}
    </div>
  );
}

/** Older / newer. At either end it fades and does nothing, but stays focusable so focus never drops. */
function Step({
  dir,
  disabled,
  onStep,
}: {
  dir: -1 | 1;
  disabled: boolean;
  onStep: () => void;
}) {
  return (
    <button
      type="button"
      aria-label={dir < 0 ? "Older release" : "Newer release"}
      aria-disabled={disabled || undefined}
      onClick={() => !disabled && onStep()}
      className={`flex size-7 items-center justify-center rounded-full text-foreground transition-[background-color,opacity] duration-300 ${FOCUS} ${disabled ? "cursor-default opacity-30" : "hover:bg-accent"}`}
    >
      <svg
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth={1.6}
        strokeLinecap="round"
        strokeLinejoin="round"
        aria-hidden="true"
        className="size-3.5"
      >
        <path d={dir < 0 ? "M10 3.5 5.5 8l4.5 4.5" : "M6 3.5 10.5 8 6 12.5"} />
      </svg>
    </button>
  );
}

export function ChangelogScrubber({
  entries,
  value,
  defaultValue,
  onValueChange,
  playDuration,
  locales,
  className = "",
  ...props
}: ChangelogScrubberProps) {
  const reduced = useReducedMotion();

  // The ruler: releases oldest to newest, a little room either side, a tick a day (a week, then four, on long histories) and the months.
  const model = React.useMemo(() => {
    const releases = entries
      .map((entry) => ({ entry, t: new Date(entry.date).getTime() }))
      .sort((a, b) => a.t - b.t);
    const first = releases[0]?.t ?? 0;
    const last = releases[releases.length - 1]?.t ?? first;
    const span = Math.max(14 * DAY, last - first);
    const pad = Math.max(3 * DAY, span * 0.08);
    const start = first - pad;
    const end = last + pad;
    const pos = (t: number) => ((t - start) / (end - start)) * 100;
    const days = (end - start) / DAY;
    const every = days <= 120 ? 1 : days <= 840 ? 7 : 28;
    const ticks: number[] = [];
    const d = new Date(start);
    d.setHours(0, 0, 0, 0);
    if (d.getTime() < start) d.setDate(d.getDate() + 1);
    while (every > 1 && d.getDay() !== 1) d.setDate(d.getDate() + 1);
    for (; d.getTime() <= end; d.setDate(d.getDate() + every))
      ticks.push(pos(d.getTime()));
    const label = (m: Date) =>
      m.toLocaleDateString(
        locales ?? "en-GB",
        m.getMonth() === 0
          ? { month: "short", year: "numeric" }
          : { month: "short" },
      );
    const months: { p: number; label: string; edge?: boolean }[] = [];
    const m = new Date(start);
    m.setHours(0, 0, 0, 0);
    m.setDate(1);
    const opening = label(m);
    for (
      m.setMonth(m.getMonth() + 1);
      m.getTime() <= end;
      m.setMonth(m.getMonth() + 1)
    )
      months.push({ p: pos(m.getTime()), label: label(m) });
    // The month the ruler opens in gets a label too, when there's room before the next.
    if (!months.length || months[0].p > 14)
      months.unshift({ p: 0, label: opening, edge: true });
    const keep = Math.ceil(months.length / 8);
    return {
      releases,
      at: releases.map((r) => pos(r.t)),
      ticks,
      months: months.filter((_, i) => i % keep === 0),
    };
  }, [entries, locales]);

  const n = model.releases.length;
  const [own, setOwn] = React.useState(
    defaultValue ?? model.releases[n - 1]?.entry.id,
  );
  const active = value ?? own;
  const found = model.releases.findIndex((r) => r.entry.id === active);
  const index = found === -1 ? n - 1 : found;
  const current = model.releases[index]?.entry;

  const [playing, setPlaying] = React.useState(false);
  const [dragging, setDragging] = React.useState(false);
  const [height, setHeight] = React.useState<number | null>(null);
  const [initialX] = React.useState(() => String(model.at[index] ?? 0));
  const rulerRef = React.useRef<HTMLDivElement>(null);
  const ghostRef = React.useRef<HTMLSpanElement>(null);
  const paneRef = React.useRef<HTMLDivElement | null>(null);
  const xRef = React.useRef(model.at[index] ?? 0);
  const indexRef = React.useRef(index);
  const tweenRef = React.useRef(0);
  const playingRef = React.useRef(false);
  const dragRef = React.useRef<{ startX: number; moved: boolean } | null>(null);
  const reducedRef = React.useRef(reduced);
  const stageRef = React.useRef<HTMLDivElement>(null);
  const swipeRef = React.useRef<{
    id: number;
    x: number;
    y: number;
    t: number;
    dx: number;
    axis: "x" | "y" | null;
  } | null>(null);
  const [carry, setCarry] = React.useState(0);

  // Which release left, and which way: kept from the render before, so a controlled value slides the same way.
  const [prev, setPrev] = React.useState({ index, n: 0, dir: 0 });
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  if (prev.index !== index) {
    const dir = Math.sign(index - prev.index);
    setPrev({ index, n: prev.n + 1, dir });
    setLeaving((l) => [
      ...l.slice(-1),
      { index: prev.index, dir, key: prev.n, from: carry },
    ]);
    if (carry) setCarry(0);
  }

  React.useEffect(() => {
    indexRef.current = index;
    reducedRef.current = reduced;
  });

  React.useEffect(() => {
    if (!leaving.length) return;
    const timer = window.setTimeout(() => setLeaving([]), MORPH);
    return () => window.clearTimeout(timer);
  }, [leaving]);

  // The card takes the height of the release it's showing.
  React.useLayoutEffect(() => {
    const pane = paneRef.current;
    if (!pane) return;
    const measure = () =>
      setHeight((h) => (h === pane.offsetHeight ? h : pane.offsetHeight));
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(pane);
    return () => observer.disconnect();
  }, [index]);

  React.useEffect(() => () => cancelAnimationFrame(tweenRef.current), []);

  const paint = React.useCallback((x: number) => {
    xRef.current = x;
    rulerRef.current?.style.setProperty("--x", x.toFixed(3));
  }, []);

  /** Moves the playhead; every frame is one custom property on the ruler. */
  const tween = React.useCallback(
    (
      to: number,
      duration: number,
      ease: (t: number) => number,
      onFrame: (x: number) => void = paint,
      onEnd?: () => void,
    ) => {
      cancelAnimationFrame(tweenRef.current);
      const from = xRef.current;
      const start = performance.now();
      const step = (now: number) => {
        const t = duration > 0 ? Math.min(1, (now - start) / duration) : 1;
        onFrame(from + (to - from) * ease(t));
        if (t < 1) tweenRef.current = requestAnimationFrame(step);
        else {
          tweenRef.current = 0;
          onEnd?.();
        }
      };
      if (duration > 0) tweenRef.current = requestAnimationFrame(step);
      else step(start);
    },
    [paint],
  );

  const settle = React.useCallback(
    (to: number) => tween(to, reducedRef.current ? 0 : 520, THROWN),
    [tween],
  );

  const choose = (i: number) => {
    const id = model.releases[i]?.entry.id;
    if (!id || i === indexRef.current) return;
    indexRef.current = i;
    if (value === undefined) setOwn(id);
    onValueChange?.(id);
  };
  const nearest = (x: number) =>
    model.at.reduce(
      (best, p, i) =>
        Math.abs(p - x) < Math.abs(model.at[best] - x) ? i : best,
      0,
    );
  const lastPassed = (x: number) =>
    model.at.reduce((found, p, i) => (p <= x + 1e-6 ? i : found), 0);

  // A new release from outside the ruler (keys, a click, a controlled value): throw the playhead onto it.
  React.useEffect(() => {
    if (dragRef.current?.moved || playingRef.current) return;
    const to = model.at[index];
    if (to !== undefined && Math.abs(xRef.current - to) > 0.01) settle(to);
  }, [index, model, settle]);

  const setPaneRef = React.useCallback((el: HTMLDivElement | null) => {
    paneRef.current = el;
  }, []);

  // A link to a release (#its-id) opens on it.
  React.useEffect(() => {
    const hash = decodeURIComponent(window.location.hash.slice(1));
    if (value === undefined && hash && entries.some((e) => e.id === hash)) {
      const frame = requestAnimationFrame(() => setOwn(hash));
      return () => cancelAnimationFrame(frame);
    }
  }, [entries, value]);

  const pause = () => {
    if (!playingRef.current) return;
    cancelAnimationFrame(tweenRef.current);
    tweenRef.current = 0;
    playingRef.current = false;
    setPlaying(false);
  };

  // Play runs at the pace the releases shipped: the playhead moves at one speed and the card changes as it passes each one.
  // With reduced motion the playhead steps from release to release instead of gliding.
  const play = () => {
    if (playingRef.current) return pause();
    const { at } = model;
    if (at.length < 2) return;
    const first = at[0];
    const last = at[at.length - 1];
    if (xRef.current >= last - 0.01) {
      paint(first);
      choose(0);
    }
    playingRef.current = true;
    setPlaying(true);
    const total = playDuration ?? at.length * 1200;
    tween(
      last,
      (total * (last - xRef.current)) / (last - first),
      LINEAR,
      (x) => {
        const i = lastPassed(x);
        xRef.current = x;
        rulerRef.current?.style.setProperty(
          "--x",
          (reducedRef.current ? at[i] : x).toFixed(3),
        );
        choose(i);
      },
      () => {
        playingRef.current = false;
        setPlaying(false);
      },
    );
  };

  const xAt = (clientX: number) => {
    const r = rulerRef.current?.getBoundingClientRect();
    return r
      ? Math.min(100, Math.max(0, ((clientX - r.left) / r.width) * 100))
      : xRef.current;
  };
  const ghost = (x: number | null) => {
    if (x !== null) rulerRef.current?.style.setProperty("--h", x.toFixed(3));
    if (ghostRef.current)
      ghostRef.current.style.opacity = x === null ? "0" : "1";
  };
  const release = (clientX: number, up: boolean) => {
    const drag = dragRef.current;
    if (!drag) return;
    dragRef.current = null;
    if (drag.moved) {
      setDragging(false);
      settle(model.at[nearest(xRef.current)]);
      return;
    }
    if (!up) return;
    const i = nearest(xAt(clientX));
    if (i === indexRef.current) settle(model.at[i]);
    else choose(i);
  };

  const onKeyDown = (e: React.KeyboardEvent) => {
    const moves: Record<string, number> = {
      ArrowLeft: index - 1,
      ArrowDown: index - 1,
      ArrowRight: index + 1,
      ArrowUp: index + 1,
      Home: 0,
      End: n - 1,
    };
    if (!(e.key in moves)) return;
    e.preventDefault();
    pause();
    const i = Math.min(n - 1, Math.max(0, moves[e.key]));
    if (i === index) settle(model.at[i]);
    else choose(i);
  };

  const step = (d: number) => {
    pause();
    const i = Math.min(n - 1, Math.max(0, indexRef.current + d));
    if (i !== indexRef.current) choose(i);
  };

  // Swiping the card (touch and pen; a mouse selects text): the release follows the finger, a swipe past 56px or a quick
  // flick moves one release and the old one carries on from where it was let go; anything less springs back.
  const onSwipeStart = (e: React.PointerEvent) => {
    if (
      e.pointerType === "mouse" ||
      (e.target as HTMLElement).closest("button, a")
    )
      return;
    swipeRef.current = {
      id: e.pointerId,
      x: e.clientX,
      y: e.clientY,
      t: performance.now(),
      dx: 0,
      axis: null,
    };
  };
  const onSwipeMove = (e: React.PointerEvent) => {
    const s = swipeRef.current;
    if (!s || s.id !== e.pointerId) return;
    const dx = e.clientX - s.x;
    const dy = e.clientY - s.y;
    if (!s.axis) {
      if (Math.abs(dx) < 8 && Math.abs(dy) < 8) return;
      s.axis = Math.abs(dx) > Math.abs(dy) ? "x" : "y";
      if (s.axis === "y") {
        swipeRef.current = null;
        return;
      }
      e.currentTarget.setPointerCapture(e.pointerId);
      pause();
    }
    const edge =
      (dx < 0 && indexRef.current === n - 1) ||
      (dx > 0 && indexRef.current === 0);
    s.dx = dx * (edge ? 0.3 : 0.8);
    const stage = stageRef.current;
    if (stage && !reducedRef.current) {
      stage.style.transition = "none";
      stage.style.transform = `translateX(${s.dx}px)`;
    }
  };
  const onSwipeEnd = (e: React.PointerEvent, commit: boolean) => {
    const s = swipeRef.current;
    if (!s || s.id !== e.pointerId) return;
    swipeRef.current = null;
    if (s.axis !== "x") return;
    const stage = stageRef.current;
    const raw = e.clientX - s.x;
    const flick = performance.now() - s.t < 260 && Math.abs(raw) > 24;
    const d = commit && (Math.abs(raw) > 56 || flick) ? (raw < 0 ? 1 : -1) : 0;
    const i = Math.min(n - 1, Math.max(0, indexRef.current + d));
    if (d && i !== indexRef.current) {
      if (stage) {
        stage.style.transition = "none";
        stage.style.transform = "";
      }
      setCarry(reducedRef.current ? 0 : s.dx);
      step(d);
    } else if (stage) {
      stage.style.transition = `transform 420ms ${THROW}`;
      stage.style.transform = "";
    }
  };

  if (!current) return null;

  const dateText = (d: string | Date, short = false) =>
    new Date(d).toLocaleDateString(
      locales ?? "en-GB",
      short
        ? { day: "numeric", month: "short" }
        : { day: "numeric", month: "short", year: "numeric" },
    );
  const tags = current.tags ?? [];
  const tagText = tags.map((t) => TAG_LABEL[t] ?? t).join(", ");

  return (
    <div className={`w-full ${className}`} {...props}>
      <div className="flex items-start gap-3">
        <button
          type="button"
          aria-label={playing ? "Pause" : "Play the releases"}
          onClick={play}
          className={`cursor-pointer relative mt-5 flex size-8 shrink-0 items-center justify-center rounded-full text-foreground shadow-[inset_0_0_0_1px_var(--border)] transition-colors hover:bg-accent ${FOCUS}`}
        >
          <svg
            viewBox="0 0 16 16"
            fill="currentColor"
            aria-hidden="true"
            className="absolute size-3.5 translate-x-px"
            style={swap(!playing, reduced)}
          >
            <path d="M5 3.6v8.8a.6.6 0 0 0 .92.5l6.9-4.4a.6.6 0 0 0 0-1L5.92 3.1A.6.6 0 0 0 5 3.6Z" />
          </svg>
          <svg
            viewBox="0 0 16 16"
            fill="currentColor"
            aria-hidden="true"
            className="absolute size-3.5"
            style={swap(playing, reduced)}
          >
            <rect x="4" y="3" width="2.75" height="10" rx="0.8" />
            <rect x="9.25" y="3" width="2.75" height="10" rx="0.8" />
          </svg>
        </button>

        <div
          ref={rulerRef}
          role="slider"
          tabIndex={0}
          aria-label="Release"
          aria-valuemin={1}
          aria-valuemax={n}
          aria-valuenow={index + 1}
          aria-valuetext={`${current.version ? `${current.version}, ` : ""}${current.title}, ${dateText(current.date)}`}
          onKeyDown={onKeyDown}
          onPointerDown={(e) => {
            if (e.button !== 0) return;
            e.currentTarget.setPointerCapture(e.pointerId);
            pause();
            dragRef.current = { startX: e.clientX, moved: false };
          }}
          onPointerMove={(e) => {
            const drag = dragRef.current;
            if (!drag) {
              if (e.pointerType === "mouse") ghost(xAt(e.clientX));
              return;
            }
            if (!drag.moved) {
              if (Math.abs(e.clientX - drag.startX) < 4) return;
              drag.moved = true;
              setDragging(true);
              ghost(null);
            }
            cancelAnimationFrame(tweenRef.current);
            tweenRef.current = 0;
            const x = xAt(e.clientX);
            paint(x);
            choose(nearest(x));
          }}
          onPointerUp={(e) => release(e.clientX, true)}
          onPointerCancel={(e) => release(e.clientX, false)}
          onPointerLeave={() => ghost(null)}
          className={`relative h-[66px] min-w-0 flex-1 touch-none select-none rounded-lg [container-type:inline-size] ${dragging ? "cursor-grabbing" : "cursor-grab"} ${FOCUS}`}
          style={{ "--x": initialX } as React.CSSProperties}
        >
          {/* The baseline, and the part of history already behind the playhead. */}
          <span
            aria-hidden="true"
            className="absolute inset-x-0 top-[46px] h-px bg-border"
          />
          <span
            aria-hidden="true"
            className="absolute inset-x-0 top-[46px] h-px origin-left bg-foreground/50"
            style={{ transform: "scaleX(calc(var(--x) / 100))" }}
          />
          {model.ticks.map((p, i) => (
            <span
              key={i}
              aria-hidden="true"
              className="absolute top-[40px] h-[6px] w-px origin-bottom bg-border"
              style={lens(p, 1.6)}
            />
          ))}
          {model.months.map((m) =>
            m.edge ? null : (
              <span
                key={`tick-${m.p}`}
                aria-hidden="true"
                className="absolute top-[36px] h-[10px] w-px origin-bottom bg-foreground/25"
                style={lens(m.p, 0.9)}
              />
            ),
          )}
          {model.at.map((p, i) => (
            <span
              key={model.releases[i].entry.id}
              aria-hidden="true"
              className={`absolute top-[32px] h-[14px] w-px origin-bottom transition-colors duration-300 ${i === index ? "bg-foreground" : "bg-foreground/40"}`}
              style={lens(p, 0.45)}
            />
          ))}
          {model.months.map((m) => (
            <span
              key={`label-${m.p}`}
              aria-hidden="true"
              className={`absolute top-[53px] whitespace-nowrap text-[11px] leading-none text-muted-foreground ${m.p > 90 ? "-translate-x-full pr-1" : "pl-1"}`}
              style={{ left: `${m.p}%` }}
            >
              {m.label}
            </span>
          ))}

          {/* Where the pointer would land. */}
          <span
            ref={ghostRef}
            aria-hidden="true"
            className="pointer-events-none absolute left-0 top-[26px] h-[24px] w-px bg-foreground/25 opacity-0 transition-opacity duration-200"
            style={{ transform: "translateX(calc(var(--h, 0) * 1cqw))" }}
          />

          {/* The playhead, carrying the version it's on. */}
          <div
            aria-hidden="true"
            className="pointer-events-none absolute inset-y-0 left-0 w-px"
            style={{ transform: "translateX(calc(var(--x) * 1cqw))" }}
          >
            <span className="absolute left-0 top-[20px] h-[30px] w-px bg-primary" />
            <span className="absolute left-0 top-0 flex h-5 -translate-x-1/2 items-center whitespace-nowrap rounded-full bg-primary px-2 font-mono text-[11px] font-medium text-primary-foreground">
              <TextMorph>
                {current.version ?? dateText(current.date, true)}
              </TextMorph>
            </span>
          </div>
        </div>
      </div>

      <div
        onPointerDown={onSwipeStart}
        onPointerMove={onSwipeMove}
        onPointerUp={(e) => onSwipeEnd(e, true)}
        onPointerCancel={(e) => onSwipeEnd(e, false)}
        className="mt-5 touch-pan-y touch-pinch-zoom rounded-[22px] bg-background p-5 shadow-[0_0_0_1px_var(--border)] sm:p-6"
      >
        <div className="flex items-center justify-between gap-3 text-[12.5px] text-muted-foreground">
          <div className="flex min-w-0 items-center">
            <span
              className="grid"
              style={{
                gridTemplateColumns: tags.length ? "1fr" : "0fr",
                opacity: tags.length ? 1 : 0,
                transition: reduced
                  ? "none"
                  : `grid-template-columns 380ms ${EASE}, opacity 240ms ${EASE}`,
              }}
            >
              <span className="min-w-0 pr-2 [clip-path:inset(-4px_-2px)]">
                <span
                  className={`inline-flex whitespace-nowrap rounded-full px-2 py-px text-[11px] font-medium transition-colors duration-300 ${TAG_TONE[tags[0]] ?? "bg-muted text-foreground/80"}`}
                >
                  <TextMorph>{tagText || " "}</TextMorph>
                </span>
              </span>
            </span>
            <time dateTime={new Date(current.date).toISOString()}>
              <TextMorph>{dateText(current.date)}</TextMorph>
            </time>
          </div>
          <div className="-my-1 -mr-2 flex shrink-0 items-center">
            <Step dir={-1} disabled={index === 0} onStep={() => step(-1)} />
            <p className="flex items-baseline gap-[0.3em] px-1 tabular-nums">
              <NumberRoll value={index + 1} duration={600} />
              <span>of {n}</span>
            </p>
            <Step dir={1} disabled={index === n - 1} onStep={() => step(1)} />
          </div>
        </div>

        <div
          className="relative mt-4 [clip-path:inset(0_-20px)]"
          style={{
            height: height ?? undefined,
            transition:
              reduced || height === null ? "none" : `height ${MORPH}ms ${EASE}`,
          }}
        >
          {/* What a swipe moves. */}
          <div ref={stageRef} className="relative">
            {leaving.map((l) => {
              const e = model.releases[l.index]?.entry;
              return e ? (
                <Pane
                  key={`out-${l.key}`}
                  dir={l.dir}
                  leaving
                  reduced={reduced}
                  from={l.from}
                >
                  <Release entry={e} />
                </Pane>
              ) : null;
            })}
            <Pane
              key={current.id}
              dir={prev.dir}
              leaving={false}
              reduced={reduced}
              paneRef={setPaneRef}
            >
              <Release entry={current} />
            </Pane>
          </div>
        </div>
      </div>
    </div>
  );
}

function Release({ entry }: { entry: ChangelogEntry }) {
  return (
    <>
      <h3 className="text-[19px] font-medium leading-snug tracking-[-0.02em] text-foreground">
        {entry.title}
      </h3>
      {entry.body && (
        <div className="mt-2 text-[14px] leading-relaxed text-muted-foreground [&_li]:mt-1 [&_ul]:mt-2 [&_ul]:list-disc [&_ul]:pl-5">
          {entry.body}
        </div>
      )}
      {entry.media && (
        <div className="mt-4 overflow-hidden rounded-[16px] border border-border">
          {entry.media}
        </div>
      )}
    </>
  );
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * CHANGELOG TIMELINE: what shipped, drawn as you read
 *
 *   read      a thin line rail runs down the page and fills as you
 *             scroll; each entry's dot fills as the line reaches it
 *   arrive    entries rise out of a light blur the first time they
 *             come into view
 *   filter    All, New, Improved, Fixed: a pill is thrown to the
 *             choice, entries that don't match fold away and the
 *             count rolls
 *   older     "Show 6 older" folds the rest open and morphs to
 *             "Show fewer"
 *
 * Every entry has an anchor, so a release can be linked to.
 * ───────────────────────────────────────────────────────── */

export interface ChangelogEntry {
  id: string;
  date: string | Date;
  title: string;
  version?: string;
  /** e.g. ["new"], ["improved", "fixed"]. */
  tags?: string[];
  body?: React.ReactNode;
  /** An image or video under the text. */
  media?: React.ReactNode;
}

export interface ChangelogTimelineProps extends React.HTMLAttributes<HTMLDivElement> {
  entries: ChangelogEntry[];
  /** How many show before "Show older". */
  initialCount?: number;
  /** Filter chips, by tag; defaults to the tags in the entries. */
  filters?: { tag: string; label: string }[];
  locales?: string | string[];
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const TAG_LABEL: Record<string, string> = {
  new: "New",
  improved: "Improved",
  fixed: "Fixed",
};
const TAG_TONE: Record<string, string> = {
  new: "bg-primary/10 text-primary",
  improved: "bg-muted text-foreground/80",
  fixed: "bg-muted text-muted-foreground",
};

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Rises out of a light blur the first time it scrolls into view. */
function Arrive({
  reduced,
  children,
}: {
  reduced: boolean;
  children: React.ReactNode;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  const [seen, setSeen] = React.useState(reduced);
  React.useEffect(() => {
    if (seen) return;
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setSeen(true);
          observer.disconnect();
        }
      },
      { rootMargin: "0px 0px -12% 0px" },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [seen]);
  return (
    <div
      ref={ref}
      style={{
        opacity: seen ? 1 : 0,
        transform: seen ? "none" : "translateY(14px)",
        filter: seen ? "none" : "blur(4px)",
        transition: reduced
          ? "none"
          : `opacity 560ms ${EASE}, transform 700ms ${EASE}, filter 560ms ${EASE}`,
      }}
    >
      {children}
    </div>
  );
}

export function ChangelogTimeline({
  entries,
  initialCount = 4,
  filters: filtersProp,
  locales,
  className = "",
  ...props
}: ChangelogTimelineProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const [filter, setFilter] = React.useState<string | null>(null);
  const [showAll, setShowAll] = React.useState(false);
  const [progress, setProgress] = React.useState(0);
  const [passed, setPassed] = React.useState<Set<string>>(() => new Set());
  const rootRef = React.useRef<HTMLDivElement>(null);
  const railRef = React.useRef<HTMLDivElement>(null);
  const dotRefs = React.useRef(new Map<string, HTMLSpanElement>());
  const chipRefs = React.useRef<(HTMLButtonElement | null)[]>([]);
  const [pill, setPill] = React.useState({ left: 0, width: 0, ready: false });

  const filters = React.useMemo(() => {
    if (filtersProp) return filtersProp;
    const tags = Array.from(new Set(entries.flatMap((e) => e.tags ?? [])));
    return tags.map((tag) => ({
      tag,
      label: TAG_LABEL[tag] ?? tag.charAt(0).toUpperCase() + tag.slice(1),
    }));
  }, [entries, filtersProp]);
  const chips = [{ tag: null as string | null, label: "All" }, ...filters];

  const matches = entries.filter((e) => !filter || e.tags?.includes(filter));
  const limit = showAll ? Infinity : initialCount;
  const shownIds = new Set(matches.slice(0, limit).map((e) => e.id));
  const hiddenOlder = Math.max(0, matches.length - initialCount);

  // The rail fills to the middle of the screen as you read; dots fill as the line reaches them.
  React.useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    let frame = 0;
    let visible = false;
    const update = () => {
      frame = 0;
      const rail = railRef.current?.getBoundingClientRect();
      if (!rail) return;
      const anchor = window.innerHeight * 0.55;
      const p = Math.min(
        1,
        Math.max(0, (anchor - rail.top) / Math.max(1, rail.height)),
      );
      setProgress((x) => (Math.abs(x - p) < 0.002 ? x : p));
      const now = new Set<string>();
      dotRefs.current.forEach((dot, key) => {
        if (dot.getBoundingClientRect().top + 5 <= anchor) now.add(key);
      });
      setPassed((s) =>
        s.size === now.size && [...now].every((k) => s.has(k)) ? s : now,
      );
    };
    const onScroll = () => {
      if (visible && !frame) frame = requestAnimationFrame(update);
    };
    // Only listen while the timeline is on screen.
    const observer = new IntersectionObserver(([entry]) => {
      visible = entry.isIntersecting;
      if (visible) update();
    });
    observer.observe(root);
    window.addEventListener("scroll", onScroll, {
      passive: true,
      capture: true,
    });
    window.addEventListener("resize", onScroll);
    return () => {
      observer.disconnect();
      window.removeEventListener("scroll", onScroll, { capture: true });
      window.removeEventListener("resize", onScroll);
      cancelAnimationFrame(frame);
    };
  }, []);

  // Folding entries move the dots: re-check once the folds have settled.
  React.useEffect(() => {
    const t = window.setTimeout(
      () => window.dispatchEvent(new Event("resize")),
      520,
    );
    return () => window.clearTimeout(t);
  }, [filter, showAll]);

  React.useLayoutEffect(() => {
    const el = chipRefs.current[chips.findIndex((c) => c.tag === filter)];
    if (!el) return;
    setPill((p) =>
      p.left === el.offsetLeft && p.width === el.offsetWidth
        ? p
        : { left: el.offsetLeft, width: el.offsetWidth, ready: p.width > 0 },
    );
  }, [filter, filters.length]);

  const dateText = (d: string | Date) =>
    new Date(d).toLocaleDateString(locales ?? "en-GB", {
      day: "numeric",
      month: "short",
      year: "numeric",
    });
  const fold = (open: boolean): React.CSSProperties => ({
    gridTemplateRows: open ? "1fr" : "0fr",
    opacity: open ? 1 : 0,
    transition: reduced
      ? "none"
      : `grid-template-rows 480ms ${EASE}, opacity ${open ? "380ms" : "160ms"} ${EASE}`,
  });

  return (
    // Laid out by its own width, not the screen's, so it reads right in a narrow column too.
    <div className="w-full">
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 720px)" }}
      />
      <div className="@container w-full">
        <div ref={rootRef} className={`w-full ${className}`} {...props}>
          <div className="mb-8 flex flex-wrap items-center justify-between gap-3">
            <div
              role="radiogroup"
              aria-label="Show"
              className="relative inline-flex rounded-full bg-muted p-0.5"
            >
              <span
                aria-hidden="true"
                className="absolute inset-y-0.5 left-0 rounded-full bg-background shadow-[0_0_0_1px_var(--border)]"
                style={{
                  width: pill.width,
                  transform: `translateX(${pill.left}px)`,
                  transition:
                    pill.ready && !reduced
                      ? `transform 460ms ${THROW}, width 380ms ${EASE}`
                      : "none",
                }}
              />
              {chips.map((c, i) => {
                const selected = c.tag === filter;
                return (
                  <button
                    key={c.label}
                    ref={(el) => {
                      chipRefs.current[i] = el;
                    }}
                    type="button"
                    role="radio"
                    aria-checked={selected}
                    tabIndex={selected ? 0 : -1}
                    onClick={() => setFilter(c.tag)}
                    onKeyDown={(e) => {
                      if (e.key !== "ArrowRight" && e.key !== "ArrowLeft")
                        return;
                      e.preventDefault();
                      const next =
                        (i + (e.key === "ArrowRight" ? 1 : -1) + chips.length) %
                        chips.length;
                      setFilter(chips[next].tag);
                      chipRefs.current[next]?.focus();
                    }}
                    className={`cursor-pointer relative h-8 rounded-full px-3.5 text-[12.5px] font-medium transition-colors duration-300 ${FOCUS} ${selected ? "text-foreground" : "text-muted-foreground hover:text-foreground"}`}
                  >
                    {c.label}
                  </button>
                );
              })}
            </div>
            <p className="flex items-baseline gap-[0.3em] text-[12.5px] tabular-nums text-muted-foreground">
              <NumberRoll value={matches.length} duration={600} />
              <TextMorph>
                {matches.length === 1 ? "update" : "updates"}
              </TextMorph>
            </p>
          </div>

          <div className="relative">
            {/* The rail, and the line that fills it as you read. */}
            <div
              ref={railRef}
              aria-hidden="true"
              className="absolute bottom-2 top-2 left-[5px] w-px bg-border @[36rem]:left-[133px]"
            >
              <div
                className="absolute inset-0 origin-top bg-foreground/70"
                style={{ transform: `scaleY(${progress})` }}
              />
            </div>

            <ol className="relative">
              {entries.map((e) => {
                const shown = shownIds.has(e.id);
                const lit = passed.has(e.id);
                return (
                  <li
                    key={e.id}
                    id={e.id}
                    inert={!shown}
                    aria-hidden={!shown || undefined}
                    className="grid scroll-mt-24"
                    style={fold(shown)}
                  >
                    <div className="min-h-0 overflow-hidden">
                      <Arrive reduced={reduced}>
                        <article className="grid grid-cols-[11px_1fr] gap-x-5 pb-12 @[36rem]:grid-cols-[110px_11px_1fr] @[36rem]:gap-x-[17px]">
                          <div className="hidden pt-0.5 text-right @[36rem]:block">
                            <time
                              dateTime={new Date(e.date).toISOString()}
                              className="text-[12.5px] text-muted-foreground"
                            >
                              {dateText(e.date)}
                            </time>
                            {e.version && (
                              <p className="mt-1 font-mono text-[11.5px] text-muted-foreground/80">
                                {e.version}
                              </p>
                            )}
                          </div>
                          {/* The dot fills when the line reaches it. */}
                          <span
                            ref={(el) => {
                              if (el) dotRefs.current.set(e.id, el);
                              else dotRefs.current.delete(e.id);
                            }}
                            aria-hidden="true"
                            className="relative mt-[5px] flex size-[11px] items-center justify-center rounded-full bg-background shadow-[inset_0_0_0_1px_var(--border)] transition-[box-shadow] duration-500"
                            style={{
                              boxShadow: lit
                                ? "inset 0 0 0 1px color-mix(in oklab, var(--foreground) 70%, transparent)"
                                : undefined,
                            }}
                          >
                            <span
                              className="size-[5px] rounded-full bg-foreground/70"
                              style={{
                                transform: lit ? "scale(1)" : "scale(0)",
                                transition: reduced
                                  ? "none"
                                  : `transform 420ms ${THROW}`,
                              }}
                            />
                          </span>
                          <div className="min-w-0">
                            <div className="mb-2 flex flex-wrap items-center gap-2 @[36rem]:hidden">
                              <time
                                dateTime={new Date(e.date).toISOString()}
                                className="text-[12px] text-muted-foreground"
                              >
                                {dateText(e.date)}
                              </time>
                              {e.version && (
                                <span className="font-mono text-[11px] text-muted-foreground/80">
                                  {e.version}
                                </span>
                              )}
                            </div>
                            {e.tags && e.tags.length > 0 && (
                              <div className="mb-2 flex flex-wrap gap-1.5">
                                {e.tags.map((t) => (
                                  <span
                                    key={t}
                                    className={`rounded-full px-2 py-px text-[11px] font-medium ${TAG_TONE[t] ?? "bg-muted text-foreground/80"}`}
                                  >
                                    {TAG_LABEL[t] ?? t}
                                  </span>
                                ))}
                              </div>
                            )}
                            <h3 className="text-[17px] font-medium leading-snug tracking-[-0.015em] text-foreground">
                              <a
                                href={`#${e.id}`}
                                className={`rounded hover:underline hover:decoration-border hover:underline-offset-4 ${FOCUS}`}
                              >
                                {e.title}
                              </a>
                            </h3>
                            {e.body && (
                              <div className="mt-2 text-[14px] leading-relaxed text-muted-foreground [&_li]:mt-1 [&_ul]:mt-2 [&_ul]:list-disc [&_ul]:pl-5">
                                {e.body}
                              </div>
                            )}
                            {e.media && (
                              <div className="mt-4 overflow-hidden rounded-[16px] border border-border">
                                {e.media}
                              </div>
                            )}
                          </div>
                        </article>
                      </Arrive>
                    </div>
                  </li>
                );
              })}
            </ol>

            {hiddenOlder > 0 && (
              <div className="pl-[31px] @[36rem]:pl-[155px]">
                <button
                  type="button"
                  aria-expanded={showAll}
                  onClick={() => setShowAll((s) => !s)}
                  className={`cursor-pointer inline-flex h-9 items-center rounded-full px-4 text-[13px] font-medium text-foreground shadow-[inset_0_0_0_1px_var(--border)] transition-colors hover:bg-accent ${FOCUS}`}
                >
                  <TextMorph>
                    {showAll ? "Show fewer" : `Show ${hiddenOlder} older`}
                  </TextMorph>
                </button>
              </div>
            )}
          </div>
          <p id={`${id}-status`} role="status" className="sr-only">
            {`${matches.length} ${matches.length === 1 ? "update" : "updates"}`}
          </p>
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * CHANGELOG TRACE: what shipped, routed like a circuit
 *
 *   read      the line is a trace: straight through each
 *             release, stepped aside in between. A bead runs
 *             down it as you scroll, a beat behind the page,
 *             following every bend, and fills each dot it reaches
 *   arrive    entries rise out of a light blur the first time
 *             they come into view
 *   filter    All, New, Improved, Fixed: the pill is thrown to
 *             the choice, entries that don't match fold away,
 *             the trace re-routes as they close and the count
 *             rolls
 *   older     "Show 3 older" folds the rest open and morphs to
 *             "Show fewer"
 *
 * Every entry has an anchor, so a release can be linked to.
 * ───────────────────────────────────────────────────────── */

export interface ChangelogEntry {
  id: string;
  date: string | Date;
  title: string;
  version?: string;
  /** e.g. ["new"], ["improved", "fixed"]. */
  tags?: string[];
  body?: React.ReactNode;
  /** An image or video under the text. */
  media?: React.ReactNode;
}

export interface ChangelogTraceProps extends React.HTMLAttributes<HTMLDivElement> {
  entries: ChangelogEntry[];
  /** How many show before "Show older". */
  initialCount?: number;
  /** Filter chips, by tag; defaults to the tags in the entries. */
  filters?: { tag: string; label: string }[];
  locales?: string | string[];
}

type Point = { x: number; y: number };
type Route = { xs: number[]; ys: number[]; ls: number[]; total: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const TAG_LABEL: Record<string, string> = {
  new: "New",
  improved: "Improved",
  fixed: "Fixed",
};
const TAG_TONE: Record<string, string> = {
  new: "bg-primary/10 text-primary",
  improved: "bg-muted text-foreground/80",
  fixed: "bg-muted text-muted-foreground",
};
const STEP = 14; // how far the trace steps aside between releases
const CLEAR = 24; // straight run either side of a dot
const CORNER = 8; // how much of each bend is rounded
const LAG = 120; // how far the bead trails the page, in ms

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** The bends: straight through each stop, stepped aside between. A step shrinks with its gap, so a release folding away flattens it smoothly. */
function corners(x: number, stops: number[]): Point[] {
  const points: Point[] = [{ x, y: stops[0] }];
  for (let i = 0; i < stops.length - 1; i++) {
    const a = stops[i];
    const b = stops[i + 1];
    const step = Math.min(STEP, Math.max(0, (b - a - 2 * CLEAR) / 3));
    if (step < 0.5) continue;
    points.push(
      { x, y: a + CLEAR },
      { x: x - step, y: a + CLEAR + step },
      { x: x - step, y: b - CLEAR - step },
      { x, y: b - CLEAR },
    );
  }
  points.push({ x, y: stops[stops.length - 1] });
  return points;
}

/** Rounds every bend into the path, and samples it so the bead can find any height along it without asking the DOM. */
function trace(points: Point[]): { d: string; route: Route } {
  const r = (n: number) => Math.round(n * 100) / 100;
  const xs = [points[0].x];
  const ys = [points[0].y];
  const ls = [0];
  const add = (x: number, y: number) => {
    const i = xs.length - 1;
    ls.push(ls[i] + Math.hypot(x - xs[i], y - ys[i]));
    xs.push(x);
    ys.push(y);
  };
  let d = `M${r(points[0].x)} ${r(points[0].y)}`;
  for (let i = 1; i < points.length - 1; i++) {
    const [prev, p, next] = [points[i - 1], points[i], points[i + 1]];
    const d1 = Math.hypot(p.x - prev.x, p.y - prev.y);
    const d2 = Math.hypot(next.x - p.x, next.y - p.y);
    const k = Math.min(CORNER, d1 / 2, d2 / 2);
    if (!(k > 0)) continue;
    const a = {
      x: p.x + ((prev.x - p.x) * k) / d1,
      y: p.y + ((prev.y - p.y) * k) / d1,
    };
    const b = {
      x: p.x + ((next.x - p.x) * k) / d2,
      y: p.y + ((next.y - p.y) * k) / d2,
    };
    d += `L${r(a.x)} ${r(a.y)}Q${r(p.x)} ${r(p.y)} ${r(b.x)} ${r(b.y)}`;
    add(a.x, a.y);
    for (let s = 1; s <= 6; s++) {
      const t = s / 6;
      const u = 1 - t;
      add(
        u * u * a.x + 2 * u * t * p.x + t * t * b.x,
        u * u * a.y + 2 * u * t * p.y + t * t * b.y,
      );
    }
  }
  const last = points[points.length - 1];
  d += `L${r(last.x)} ${r(last.y)}`;
  add(last.x, last.y);
  return { d, route: { xs, ys, ls, total: ls[ls.length - 1] } };
}

/** Where the trace is at height y, and how far along it that is. The trace only ever runs downward. */
function at(route: Route, y: number) {
  const { xs, ys, ls } = route;
  const n = ys.length - 1;
  if (y <= ys[0]) return { x: xs[0], l: 0 };
  if (y >= ys[n]) return { x: xs[n], l: ls[n] };
  let lo = 0;
  let hi = n;
  while (hi - lo > 1) {
    const mid = (lo + hi) >> 1;
    if (ys[mid] < y) lo = mid;
    else hi = mid;
  }
  const t = ys[hi] === ys[lo] ? 0 : (y - ys[lo]) / (ys[hi] - ys[lo]);
  return {
    x: xs[lo] + (xs[hi] - xs[lo]) * t,
    l: ls[lo] + (ls[hi] - ls[lo]) * t,
  };
}

/** Position inside `root` from layout boxes, so transforms (an entry still arriving) don't throw it off. */
function offsetIn(el: HTMLElement, root: HTMLElement) {
  let x = el.offsetWidth / 2;
  let y = el.offsetHeight / 2;
  let node: HTMLElement | null = el;
  while (node && node !== root) {
    x += node.offsetLeft;
    y += node.offsetTop;
    node = node.offsetParent as HTMLElement | null;
  }
  return { x, y };
}

/** Rises out of a light blur the first time it scrolls into view. */
function Arrive({
  reduced,
  children,
}: {
  reduced: boolean;
  children: React.ReactNode;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  const [seen, setSeen] = React.useState(reduced);
  React.useEffect(() => {
    if (seen) return;
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setSeen(true);
          observer.disconnect();
        }
      },
      { rootMargin: "0px 0px -12% 0px" },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [seen]);
  return (
    <div
      ref={ref}
      style={{
        opacity: seen ? 1 : 0,
        transform: seen ? "none" : "translateY(14px)",
        filter: seen ? "none" : "blur(4px)",
        transition: reduced
          ? "none"
          : `opacity 560ms ${EASE}, transform 700ms ${EASE}, filter 560ms ${EASE}`,
      }}
    >
      {children}
    </div>
  );
}

export function ChangelogTrace({
  entries,
  initialCount = 4,
  filters: filtersProp,
  locales,
  className = "",
  ...props
}: ChangelogTraceProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const [filter, setFilter] = React.useState<string | null>(null);
  const [showAll, setShowAll] = React.useState(false);
  const [lit, setLit] = React.useState<Set<string>>(() => new Set());
  const listRef = React.useRef<HTMLOListElement>(null);
  const baseRef = React.useRef<SVGPathElement>(null);
  const fillRef = React.useRef<SVGPathElement>(null);
  const beadRef = React.useRef<SVGCircleElement>(null);
  const dotRefs = React.useRef(new Map<string, HTMLSpanElement>());
  const reducedRef = React.useRef(reduced);
  const chipRefs = React.useRef<(HTMLButtonElement | null)[]>([]);
  const [pill, setPill] = React.useState({ left: 0, width: 0, ready: false });

  const filters = React.useMemo(() => {
    if (filtersProp) return filtersProp;
    const tags = Array.from(new Set(entries.flatMap((e) => e.tags ?? [])));
    return tags.map((tag) => ({
      tag,
      label: TAG_LABEL[tag] ?? tag.charAt(0).toUpperCase() + tag.slice(1),
    }));
  }, [entries, filtersProp]);
  const chips = [{ tag: null as string | null, label: "All" }, ...filters];

  const matches = entries.filter((e) => !filter || e.tags?.includes(filter));
  const limit = showAll ? Infinity : initialCount;
  const shownIds = new Set(matches.slice(0, limit).map((e) => e.id));
  const hiddenOlder = Math.max(0, matches.length - initialCount);
  const idsKey = entries.map((e) => e.id).join("\n");

  React.useEffect(() => {
    reducedRef.current = reduced;
  }, [reduced]);

  // The trace is laid out from where the dots sit, and drawn as far as the reader has got. Every frame writes straight to the SVG;
  // React only hears about it when a dot lights.
  React.useEffect(() => {
    const list = listRef.current;
    const base = baseRef.current;
    const fill = fillRef.current;
    const bead = beadRef.current;
    if (!list || !base || !fill || !bead) return;
    let route: Route | null = null;
    let dots: { id: string; y: number }[] = [];
    let drawn = NaN;
    let frame = 0;
    let last = 0;
    let visible = false;
    let litKey = "";

    const paint = () => {
      if (!route) return;
      const top = route.ys[0];
      const end = route.ys[route.ys.length - 1];
      const y = Math.min(end, Math.max(top, drawn));
      const { x, l } = at(route, y);
      fill.style.strokeDashoffset = String(route.total - l);
      bead.style.transform = `translate(${x}px, ${y}px)`;
      bead.style.opacity = y > top + 1 && y < end - 1 ? "1" : "0";
      const now = dots.filter((d) => d.y <= y + 0.5).map((d) => d.id);
      const key = now.join(" ");
      if (key !== litKey) {
        litKey = key;
        setLit(new Set(now));
      }
    };

    // One frame: aim at 55% down the screen, close part of the gap (all of it with reduced motion), draw.
    const tick = (now: number) => {
      frame = 0;
      if (!route) return;
      const top = route.ys[0];
      const end = route.ys[route.ys.length - 1];
      const target = Math.min(
        end,
        Math.max(
          top,
          window.innerHeight * 0.55 - list.getBoundingClientRect().top,
        ),
      );
      const dt = last ? Math.min(64, now - last) : 16;
      last = now;
      if (Number.isNaN(drawn)) drawn = top;
      drawn +=
        (target - drawn) * (reducedRef.current ? 1 : 1 - Math.exp(-dt / LAG));
      if (Math.abs(target - drawn) < 0.25) drawn = target;
      paint();
      if (drawn !== target) frame = requestAnimationFrame(tick);
      else last = 0;
    };
    const run = () => {
      if (visible && !frame) frame = requestAnimationFrame(tick);
    };

    const ids = idsKey.split("\n");
    const layout = () => {
      // Folded releases at the end sit just below the list; hold them to its last line.
      const end = list.offsetHeight - 8;
      const found = ids.flatMap((key) => {
        const el = dotRefs.current.get(key);
        if (!el) return [];
        const { x, y } = offsetIn(el, list);
        return [{ id: key, x, y: Math.min(y, end) }];
      });
      if (!found.length) return;
      dots = found.map(({ id, y }) => ({ id, y }));
      const { d, route: next } = trace(
        corners(found[0].x, [
          ...dots.map((dot) => dot.y),
          Math.max(end, dots[dots.length - 1].y),
        ]),
      );
      route = next;
      base.setAttribute("d", d);
      fill.setAttribute("d", d);
      fill.setAttribute("pathLength", String(next.total));
      fill.style.strokeDasharray = `${next.total} ${next.total}`;
      if (Number.isNaN(drawn)) fill.style.strokeDashoffset = String(next.total);
      else paint();
      run();
    };

    // Folding entries resize the list every frame they move, so the trace re-routes with them.
    const resize = new ResizeObserver(layout);
    resize.observe(list);
    list.querySelectorAll(":scope > li").forEach((li) => resize.observe(li));
    // Only listen while the timeline is on screen.
    const seen = new IntersectionObserver(([entry]) => {
      visible = entry.isIntersecting;
      run();
    });
    seen.observe(list);
    window.addEventListener("scroll", run, { passive: true, capture: true });
    window.addEventListener("resize", run);
    return () => {
      resize.disconnect();
      seen.disconnect();
      window.removeEventListener("scroll", run, { capture: true });
      window.removeEventListener("resize", run);
      cancelAnimationFrame(frame);
    };
  }, [idsKey]);

  React.useLayoutEffect(() => {
    const el = chipRefs.current[chips.findIndex((c) => c.tag === filter)];
    if (!el) return;
    setPill((p) =>
      p.left === el.offsetLeft && p.width === el.offsetWidth
        ? p
        : { left: el.offsetLeft, width: el.offsetWidth, ready: p.width > 0 },
    );
  }, [filter, filters.length]);

  const dateText = (d: string | Date) =>
    new Date(d).toLocaleDateString(locales ?? "en-GB", {
      day: "numeric",
      month: "short",
      year: "numeric",
    });
  const fold = (open: boolean): React.CSSProperties => ({
    gridTemplateRows: open ? "1fr" : "0fr",
    opacity: open ? 1 : 0,
    transition: reduced
      ? "none"
      : `grid-template-rows 480ms ${EASE}, opacity ${open ? "380ms" : "160ms"} ${EASE}`,
  });

  return (
    // Laid out by its own width, not the screen's, so it reads right in a narrow column too.
    <div className="w-full">
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 720px)" }}
      />
      <div className="@container w-full">
        <div className={`w-full ${className}`} {...props}>
          <div className="mb-8 flex flex-wrap items-center justify-between gap-3">
            <div
              role="radiogroup"
              aria-label="Show"
              className="relative inline-flex rounded-full bg-muted p-0.5"
            >
              <span
                aria-hidden="true"
                className="absolute inset-y-0.5 left-0 rounded-full bg-background shadow-[0_0_0_1px_var(--border)]"
                style={{
                  width: pill.width,
                  transform: `translateX(${pill.left}px)`,
                  transition:
                    pill.ready && !reduced
                      ? `transform 460ms ${THROW}, width 380ms ${EASE}`
                      : "none",
                }}
              />
              {chips.map((c, i) => {
                const selected = c.tag === filter;
                return (
                  <button
                    key={c.label}
                    ref={(el) => {
                      chipRefs.current[i] = el;
                    }}
                    type="button"
                    role="radio"
                    aria-checked={selected}
                    tabIndex={selected ? 0 : -1}
                    onClick={() => setFilter(c.tag)}
                    onKeyDown={(e) => {
                      if (e.key !== "ArrowRight" && e.key !== "ArrowLeft")
                        return;
                      e.preventDefault();
                      const next =
                        (i + (e.key === "ArrowRight" ? 1 : -1) + chips.length) %
                        chips.length;
                      setFilter(chips[next].tag);
                      chipRefs.current[next]?.focus();
                    }}
                    className={`cursor-pointer relative h-8 rounded-full px-3.5 text-[12.5px] font-medium transition-colors duration-300 ${FOCUS} ${selected ? "text-foreground" : "text-muted-foreground hover:text-foreground"}`}
                  >
                    {c.label}
                  </button>
                );
              })}
            </div>
            <p className="flex items-baseline gap-[0.3em] text-[12.5px] tabular-nums text-muted-foreground">
              <NumberRoll value={matches.length} duration={600} />
              <TextMorph>
                {matches.length === 1 ? "update" : "updates"}
              </TextMorph>
            </p>
          </div>

          <div className="relative">
            {/* The trace, the part of it you've read, and the bead at its tip. */}
            <svg
              aria-hidden="true"
              className="pointer-events-none absolute inset-0 h-full w-full overflow-visible"
            >
              <path
                ref={baseRef}
                fill="none"
                strokeWidth={1}
                className="stroke-border"
              />
              <path
                ref={fillRef}
                fill="none"
                strokeWidth={1}
                strokeLinecap="round"
                className="stroke-foreground/70"
              />
              <circle
                ref={beadRef}
                r={2.5}
                className="fill-foreground"
                style={{
                  opacity: 0,
                  transition: reduced ? "none" : "opacity 200ms",
                }}
              />
            </svg>

            <ol ref={listRef} className="relative">
              {entries.map((e) => {
                const shown = shownIds.has(e.id);
                const on = lit.has(e.id);
                return (
                  <li
                    key={e.id}
                    id={e.id}
                    inert={!shown}
                    aria-hidden={!shown || undefined}
                    className="grid scroll-mt-24"
                    style={fold(shown)}
                  >
                    <div className="min-h-0 overflow-hidden">
                      <Arrive reduced={reduced}>
                        <article className="grid grid-cols-[11px_1fr] gap-x-5 pb-12 pl-4 @[36rem]:grid-cols-[104px_11px_1fr] @[36rem]:gap-x-6 @[36rem]:pl-0">
                          <div className="hidden pt-0.5 text-right @[36rem]:block">
                            <time
                              dateTime={new Date(e.date).toISOString()}
                              className="text-[12.5px] text-muted-foreground"
                            >
                              {dateText(e.date)}
                            </time>
                            {e.version && (
                              <p className="mt-1 font-mono text-[11.5px] text-muted-foreground/80">
                                {e.version}
                              </p>
                            )}
                          </div>
                          {/* The dot fills when the bead reaches it. */}
                          <span
                            ref={(el) => {
                              if (el) dotRefs.current.set(e.id, el);
                              else dotRefs.current.delete(e.id);
                            }}
                            aria-hidden="true"
                            className="relative mt-[5px] flex size-[11px] items-center justify-center rounded-full bg-background shadow-[inset_0_0_0_1px_var(--border)] transition-[box-shadow] duration-500"
                            style={{
                              boxShadow: on
                                ? "inset 0 0 0 1px color-mix(in oklab, var(--foreground) 70%, transparent)"
                                : undefined,
                            }}
                          >
                            <span
                              className="size-[5px] rounded-full bg-foreground/70"
                              style={{
                                transform: on ? "scale(1)" : "scale(0)",
                                transition: reduced
                                  ? "none"
                                  : `transform 420ms ${THROW}`,
                              }}
                            />
                          </span>
                          <div className="min-w-0">
                            <div className="mb-2 flex flex-wrap items-center gap-2 @[36rem]:hidden">
                              <time
                                dateTime={new Date(e.date).toISOString()}
                                className="text-[12px] text-muted-foreground"
                              >
                                {dateText(e.date)}
                              </time>
                              {e.version && (
                                <span className="font-mono text-[11px] text-muted-foreground/80">
                                  {e.version}
                                </span>
                              )}
                            </div>
                            {e.tags && e.tags.length > 0 && (
                              <div className="mb-2 flex flex-wrap gap-1.5">
                                {e.tags.map((t) => (
                                  <span
                                    key={t}
                                    className={`rounded-full px-2 py-px text-[11px] font-medium ${TAG_TONE[t] ?? "bg-muted text-foreground/80"}`}
                                  >
                                    {TAG_LABEL[t] ?? t}
                                  </span>
                                ))}
                              </div>
                            )}
                            <h3 className="text-[17px] font-medium leading-snug tracking-[-0.015em] text-foreground">
                              <a
                                href={`#${e.id}`}
                                className={`rounded hover:underline hover:decoration-border hover:underline-offset-4 ${FOCUS}`}
                              >
                                {e.title}
                              </a>
                            </h3>
                            {e.body && (
                              <div className="mt-2 text-[14px] leading-relaxed text-muted-foreground [&_li]:mt-1 [&_ul]:mt-2 [&_ul]:list-disc [&_ul]:pl-5">
                                {e.body}
                              </div>
                            )}
                            {e.media && (
                              <div className="mt-4 overflow-hidden rounded-[16px] border border-border">
                                {e.media}
                              </div>
                            )}
                          </div>
                        </article>
                      </Arrive>
                    </div>
                  </li>
                );
              })}
            </ol>

            {hiddenOlder > 0 && (
              <div className="pl-[47px] @[36rem]:pl-[163px]">
                <button
                  type="button"
                  aria-expanded={showAll}
                  onClick={() => setShowAll((s) => !s)}
                  className={`cursor-pointer inline-flex h-9 items-center rounded-full px-4 text-[13px] font-medium text-foreground shadow-[inset_0_0_0_1px_var(--border)] transition-colors hover:bg-accent ${FOCUS}`}
                >
                  <TextMorph>
                    {showAll ? "Show fewer" : `Show ${hiddenOlder} older`}
                  </TextMorph>
                </button>
              </div>
            )}
          </div>
          <p id={`${id}-status`} role="status" className="sr-only">
            {`${matches.length} ${matches.length === 1 ? "update" : "updates"}`}
          </p>
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import {
  Pencil,
  Pin,
  PinOff,
  Search,
  SquarePen,
  Trash2,
  X,
} from "lucide-react";

/* ─────────────────────────────────────────────────────────
 * CHAT HISTORY: past conversations, findable and tidy
 *
 *   grouped    Pinned, Today, Yesterday, Previous 7 days,
 *              Previous 30 days, then by month
 *   new        a fresh chat shimmers "New chat" until its title
 *              is generated, then the title types itself in
 *   search     filters as you type and marks the match; the rows
 *              that stay glide up to close the gaps
 *   pin        the row glides into Pinned (and back); the pin
 *              icon trades places with unpin through a blur
 *   rename     the row turns into a field in place
 *   delete     the row's text gives way to "Chat deleted · Undo";
 *              it is only deleted once the undo window passes,
 *              then folds away
 *
 * Rows are buttons; arrow keys move between them.
 * ───────────────────────────────────────────────────────── */

export interface ChatSummary {
  id: string;
  /** Empty while the title is being generated. */
  title?: string;
  updatedAt: number | Date;
  pinned?: boolean;
  /** True while the title is being generated. */
  generating?: boolean;
}

export interface ChatHistoryProps extends Omit<
  React.HTMLAttributes<HTMLElement>,
  "onSelect"
> {
  chats: ChatSummary[];
  activeId?: string;
  onSelect: (id: string) => void;
  onNew?: () => void;
  onRename?: (id: string, title: string) => void;
  /** Called once the undo window has passed. */
  onDelete?: (id: string) => void;
  onPin?: (id: string, pinned: boolean) => void;
  /** How long Undo is offered after deleting (ms). */
  undoWindow?: number;
  searchable?: boolean;
  defaultQuery?: string;
}

const EASE = "cubic-bezier(0.23,1,0.32,1)";
const MORPH = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const ICON = `cursor-pointer flex size-6 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-background hover:text-foreground [&_svg]:size-3.5 ${FOCUS}`;
const SHIMMER =
  "bg-[linear-gradient(90deg,color-mix(in_oklab,var(--muted-foreground)_55%,transparent)_35%,var(--foreground)_50%,color-mix(in_oklab,var(--muted-foreground)_55%,transparent)_65%)] bg-[length:200%_100%] bg-clip-text text-transparent animate-[ui-shimmer_1.4s_linear_infinite] motion-reduce:animate-none motion-reduce:bg-none motion-reduce:text-foreground/70";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Icons trade places through a blur: the old one shrinks away as the new one grows in. */
const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 260ms ${MORPH}, transform 380ms ${MORPH}, filter 260ms ${MORPH}`,
});

/** One layer of a row: it fades in through a blur when it becomes the row, and out when it stops being it. */
const layer = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  filter: on ? "none" : "blur(4px)",
  transition: reduced
    ? "none"
    : on
      ? `opacity 280ms ${MORPH} 60ms, filter 280ms ${MORPH} 60ms`
      : "opacity 140ms ease-out, filter 140ms ease-out",
});

/** Rows that weren't in the list before rise in; rows that were (even if they moved group) don't replay it. */
function Arrive({
  id,
  isFresh,
  reduced,
  children,
}: {
  id: string;
  isFresh: (id: string) => boolean;
  reduced: boolean;
  children: React.ReactNode;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el || reduced) return;
    if (!isFresh(id)) return;
    const a = el.animate(
      [
        { opacity: 0, transform: "translateY(4px)" },
        { opacity: 1, transform: "none" },
      ],
      {
        duration: 280,
        easing: "cubic-bezier(0.23,1,0.32,1)",
        fill: "backwards",
      },
    );
    return () => a.cancel();
  }, [id, isFresh, reduced]);
  return <div ref={ref}>{children}</div>;
}

const DAY = 86_400_000;
const startOfDay = (d: Date) =>
  new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime();

function bucket(date: Date, today: number) {
  const days = Math.round((today - startOfDay(date)) / DAY);
  if (days <= 0) return "Today";
  if (days === 1) return "Yesterday";
  if (days < 7) return "Previous 7 days";
  if (days < 30) return "Previous 30 days";
  return date.toLocaleDateString("en-US", {
    month: "long",
    year:
      new Date(today).getFullYear() === date.getFullYear()
        ? undefined
        : "numeric",
  });
}

function Mark({ text, query }: { text: string; query: string }) {
  const i = query ? text.toLowerCase().indexOf(query.toLowerCase()) : -1;
  if (i < 0) return <>{text}</>;
  return (
    <>
      {text.slice(0, i)}
      <mark className="rounded-[3px] bg-primary/15 text-foreground">
        {text.slice(i, i + query.length)}
      </mark>
      {text.slice(i + query.length)}
    </>
  );
}

/** Types a freshly generated title in, once; titles that were already there just show. */
function useArrivingTitle(
  title: string | undefined,
  generating: boolean,
  reduced: boolean,
) {
  const [shown, setShown] = React.useState(title ?? "");
  const waited = React.useRef(generating || !title);
  React.useEffect(() => {
    if (generating || !title) {
      waited.current = true;
      return;
    }
    if (!waited.current || reduced) {
      setShown(title);
      return;
    }
    waited.current = false;
    let i = 0;
    let frame = 0;
    const step = () => {
      i = Math.min(title.length, i + 1);
      setShown(title.slice(0, i));
      if (i < title.length) frame = requestAnimationFrame(step);
    };
    frame = requestAnimationFrame(step);
    return () => cancelAnimationFrame(frame);
  }, [title, generating, reduced]);
  return shown;
}

function Row({
  chat,
  active,
  query,
  reduced,
  deleted,
  onSelect,
  onRename,
  onPin,
  onDelete,
  onUndo,
}: {
  chat: ChatSummary;
  active: boolean;
  query: string;
  reduced: boolean;
  deleted: boolean;
  onSelect: () => void;
  onRename?: (title: string) => void;
  onPin?: () => void;
  onDelete?: () => void;
  onUndo: () => void;
}) {
  const generating = Boolean(chat.generating || !chat.title);
  const title = useArrivingTitle(chat.title, generating, reduced);
  const [renaming, setRenaming] = React.useState(false);
  const [draft, setDraft] = React.useState("");
  const fieldRef = React.useRef<HTMLInputElement>(null);
  const rowRef = React.useRef<HTMLButtonElement>(null);

  React.useEffect(() => {
    if (!renaming) return;
    fieldRef.current?.focus();
    fieldRef.current?.select();
  }, [renaming]);

  const save = () => {
    const next = draft.trim();
    setRenaming(false);
    if (next && next !== chat.title) onRename?.(next);
    requestAnimationFrame(() => rowRef.current?.focus({ preventScroll: true }));
  };

  const mode = deleted ? "deleted" : renaming ? "renaming" : "row";

  // One surface: the row, its rename field and its "deleted" note are layers of the same box.
  return (
    <div
      className={`group/row relative flex h-9 items-center rounded-xl transition-[background-color,box-shadow] duration-200 ${
        mode === "renaming"
          ? "bg-background shadow-[0_0_0_1px_var(--border)]"
          : mode === "deleted"
            ? "shadow-[0_0_0_1px_transparent]"
            : active
              ? "bg-accent shadow-[0_0_0_1px_transparent]"
              : "shadow-[0_0_0_1px_transparent] hover:bg-accent/70 focus-within:bg-accent/70"
      }`}
    >
      <div
        inert={mode !== "row"}
        className="flex h-9 min-w-0 flex-1 items-center"
        style={layer(mode === "row", reduced)}
      >
        <button
          ref={rowRef}
          type="button"
          data-chat=""
          aria-current={active ? "page" : undefined}
          onClick={onSelect}
          className={`cursor-pointer flex h-9 min-w-0 flex-1 items-center rounded-xl pl-3 pr-2 text-left text-[13px] outline-none focus-visible:ring-2 focus-visible:ring-ring/40 ${active ? "font-medium text-foreground" : "text-foreground/80"}`}
        >
          <span className="min-w-0 flex-1 truncate group-focus-within/row:[mask-image:linear-gradient(to_right,#000_calc(100%_-_4.5rem),transparent)] group-hover/row:[mask-image:linear-gradient(to_right,#000_calc(100%_-_4.5rem),transparent)]">
            {generating ? (
              <span className={SHIMMER}>New chat</span>
            ) : (
              <Mark text={title} query={query} />
            )}
          </span>
        </button>
        {!generating && (onPin || onRename || onDelete) && (
          <span className="absolute right-1.5 flex items-center gap-0.5 opacity-0 transition-opacity duration-150 group-focus-within/row:opacity-100 group-hover/row:opacity-100 [@media(hover:none)]:opacity-100">
            {onPin && (
              <button
                type="button"
                aria-label={
                  chat.pinned ? `Unpin ${chat.title}` : `Pin ${chat.title}`
                }
                onClick={onPin}
                className={`cursor-pointer relative ${ICON}`}
              >
                <span
                  aria-hidden="true"
                  className="absolute inset-0 flex items-center justify-center"
                  style={swap(!chat.pinned, reduced)}
                >
                  <Pin />
                </span>
                <span
                  aria-hidden="true"
                  className="absolute inset-0 flex items-center justify-center"
                  style={swap(Boolean(chat.pinned), reduced)}
                >
                  <PinOff />
                </span>
              </button>
            )}
            {onRename && (
              <button
                type="button"
                aria-label={`Rename ${chat.title}`}
                onClick={() => {
                  setDraft(chat.title ?? "");
                  setRenaming(true);
                }}
                className={ICON}
              >
                <Pencil />
              </button>
            )}
            {onDelete && (
              <button
                type="button"
                aria-label={`Delete ${chat.title}`}
                onClick={onDelete}
                className={`cursor-pointer ${ICON} hover:text-red-600`}
              >
                <Trash2 />
              </button>
            )}
          </span>
        )}
      </div>

      {(onRename || renaming) && (
        <div
          inert={mode !== "renaming"}
          className="absolute inset-0 flex items-center px-1"
          style={layer(mode === "renaming", reduced)}
        >
          <input
            ref={fieldRef}
            value={draft}
            aria-label="Chat title"
            tabIndex={mode === "renaming" ? 0 : -1}
            onChange={(e) => setDraft(e.target.value)}
            onBlur={() => mode === "renaming" && save()}
            onKeyDown={(e) => {
              if (e.nativeEvent.isComposing) return;
              if (e.key === "Enter") {
                e.preventDefault();
                save();
              } else if (e.key === "Escape") {
                e.preventDefault();
                setDraft(chat.title ?? "");
                setRenaming(false);
                requestAnimationFrame(() =>
                  rowRef.current?.focus({ preventScroll: true }),
                );
              }
            }}
            className="h-7 min-w-0 flex-1 rounded-lg bg-transparent px-2 text-[13px] text-foreground outline-none"
          />
        </div>
      )}

      <div
        inert={mode !== "deleted"}
        className="absolute inset-0 flex items-center justify-between gap-2 px-3 text-[12.5px] text-muted-foreground"
        style={layer(mode === "deleted", reduced)}
      >
        <span role="status" className="truncate">
          {deleted ? "Chat deleted" : ""}
        </span>
        <button
          type="button"
          onClick={onUndo}
          className={`cursor-pointer rounded font-medium text-foreground underline decoration-border underline-offset-4 hover:decoration-foreground ${FOCUS}`}
        >
          Undo
        </button>
      </div>
    </div>
  );
}

export function ChatHistory({
  chats,
  activeId,
  onSelect,
  onNew,
  onRename,
  onDelete,
  onPin,
  undoWindow = 5000,
  searchable = true,
  defaultQuery = "",
  className = "",
  ...props
}: ChatHistoryProps) {
  const reduced = useReducedMotion();
  const [query, setQuery] = React.useState(defaultQuery);
  const [deleted, setDeleted] = React.useState<Set<string>>(() => new Set());
  const [gone, setGone] = React.useState<Set<string>>(() => new Set());
  const timers = React.useRef(new Map<string, number>());
  const listRef = React.useRef<HTMLDivElement>(null);
  const known = React.useRef(new Set<string>());
  const isFresh = React.useCallback((id: string) => {
    if (known.current.has(id)) return false;
    known.current.add(id);
    return true;
  }, []);
  const snapshot = React.useRef<{
    at: number;
    tops: Map<string, number>;
  } | null>(null);
  const [today, setToday] = React.useState(() => startOfDay(new Date()));

  // Just before a reorder (a pin, a search keystroke), note where every row is...
  const capture = () => {
    const tops = new Map<string, number>();
    listRef.current
      ?.querySelectorAll<HTMLElement>("[data-row]")
      .forEach((el) => tops.set(el.dataset.row ?? "", el.offsetTop));
    snapshot.current = { at: performance.now(), tops };
  };

  // ...then glide each row from there to its new place: into Pinned and back, or up as a search filters others out.
  React.useLayoutEffect(() => {
    const list = listRef.current;
    const before = snapshot.current;
    if (list)
      known.current = new Set(
        [...list.querySelectorAll<HTMLElement>("[data-row]")].map(
          (el) => el.dataset.row ?? "",
        ),
      );
    if (!list || !before) return;
    snapshot.current = null;
    if (reduced || performance.now() - before.at > 1000) return;
    list.querySelectorAll<HTMLElement>("[data-row]").forEach((el) => {
      const from = before.tops.get(el.dataset.row ?? "");
      if (from !== undefined && Math.abs(from - el.offsetTop) > 1) {
        el.animate(
          [
            { transform: `translateY(${from - el.offsetTop}px)` },
            { transform: "none" },
          ],
          { duration: 420, easing: MORPH },
        );
      }
    });
  });

  React.useEffect(() => {
    const all = timers.current;
    return () => all.forEach((t) => window.clearTimeout(t));
  }, []);

  // Regroup at midnight.
  React.useEffect(() => {
    const timer = window.setTimeout(
      () => setToday(startOfDay(new Date())),
      today + DAY - Date.now() + 1000,
    );
    return () => window.clearTimeout(timer);
  }, [today]);

  const remove = (id: string) => {
    setDeleted((d) => new Set(d).add(id));
    timers.current.set(
      id,
      window.setTimeout(() => {
        timers.current.delete(id);
        setGone((g) => new Set(g).add(id));
        // Let the row fold away before the parent drops it.
        window.setTimeout(() => onDelete?.(id), reduced ? 0 : 360);
      }, undoWindow),
    );
  };

  const undo = (id: string) => {
    window.clearTimeout(timers.current.get(id));
    timers.current.delete(id);
    setDeleted((d) => {
      const next = new Set(d);
      next.delete(id);
      return next;
    });
  };

  const q = query.trim().toLowerCase();
  const visible = chats.filter(
    (c) => !q || (c.title ?? "").toLowerCase().includes(q),
  );
  const groups = new Map<string, ChatSummary[]>();
  for (const chat of [...visible].sort(
    (a, b) => +new Date(b.updatedAt) - +new Date(a.updatedAt),
  )) {
    const name = chat.pinned
      ? "Pinned"
      : bucket(new Date(chat.updatedAt), today);
    groups.set(name, [...(groups.get(name) ?? []), chat]);
  }
  const ordered = [...groups.entries()].sort(([a], [b]) =>
    a === "Pinned" ? -1 : b === "Pinned" ? 1 : 0,
  );

  // Up and down move between chats.
  const onKeyDown = (e: React.KeyboardEvent) => {
    if (e.key !== "ArrowDown" && e.key !== "ArrowUp") return;
    if (e.target instanceof HTMLInputElement && e.key === "ArrowUp") return;
    const rows = Array.from(
      listRef.current?.querySelectorAll<HTMLButtonElement>("[data-chat]") ?? [],
    );
    if (!rows.length) return;
    e.preventDefault();
    const i = rows.indexOf(document.activeElement as HTMLButtonElement);
    const next =
      e.key === "ArrowDown"
        ? i < 0
          ? 0
          : Math.min(rows.length - 1, i + 1)
        : Math.max(0, i - 1);
    rows[next]?.focus();
  };

  return (
    <nav
      aria-label="Chat history"
      onKeyDown={onKeyDown}
      className={`flex min-h-0 flex-col ${className}`}
      {...props}
    >
      {(searchable || onNew) && (
        <div className="flex items-center gap-1.5 pb-2">
          {searchable && (
            <label className="flex h-9 min-w-0 flex-1 items-center gap-2 rounded-xl border border-border px-3 transition-colors focus-within:border-foreground/25">
              <Search
                aria-hidden="true"
                className="size-3.5 shrink-0 text-muted-foreground"
              />
              <input
                type="search"
                value={query}
                onChange={(e) => {
                  capture();
                  setQuery(e.target.value);
                }}
                onKeyDown={(e) => {
                  if (e.key !== "Escape") return;
                  capture();
                  setQuery("");
                }}
                placeholder="Search chats"
                aria-label="Search chats"
                className="h-full min-w-0 flex-1 bg-transparent text-[13px] text-foreground outline-none placeholder:text-muted-foreground [&::-webkit-search-cancel-button]:hidden"
              />
              {query && (
                <button
                  type="button"
                  aria-label="Clear search"
                  onClick={() => {
                    capture();
                    setQuery("");
                  }}
                  className={`cursor-pointer -mr-1.5 ${ICON}`}
                >
                  <X />
                </button>
              )}
            </label>
          )}
          {onNew && (
            <button
              type="button"
              aria-label="New chat"
              onClick={onNew}
              className={`cursor-pointer flex size-9 shrink-0 items-center justify-center rounded-xl border border-border text-muted-foreground transition-colors hover:bg-accent hover:text-foreground [&_svg]:size-4 ${FOCUS}`}
            >
              <SquarePen />
            </button>
          )}
        </div>
      )}

      <div
        ref={listRef}
        className="relative min-h-0 flex-1 overflow-y-auto overscroll-contain [scrollbar-color:var(--border)_transparent] [scrollbar-width:thin]"
      >
        {ordered.length === 0 && (
          <p
            role="status"
            className="px-3 py-6 text-center text-[12.5px] text-muted-foreground"
          >
            {q ? `No chats match “${query.trim()}”` : "No chats yet"}
          </p>
        )}
        {ordered.map(([name, items]) => (
          <section key={name} aria-label={name} className="pb-2">
            <h3 className="px-3 pb-1 pt-2 text-[11.5px] font-medium text-muted-foreground">
              {name}
            </h3>
            <ul>
              {items.map((chat) => (
                <li
                  key={chat.id}
                  data-row={chat.id}
                  className="grid"
                  style={{
                    gridTemplateRows: gone.has(chat.id) ? "0fr" : "1fr",
                    opacity: gone.has(chat.id) ? 0 : 1,
                    transition: reduced
                      ? "none"
                      : `grid-template-rows 340ms ${EASE}, opacity 240ms ease-out`,
                  }}
                >
                  <div className="min-h-0 overflow-hidden">
                    <Arrive id={chat.id} isFresh={isFresh} reduced={reduced}>
                      <Row
                        chat={chat}
                        active={chat.id === activeId}
                        query={q}
                        reduced={reduced}
                        deleted={deleted.has(chat.id)}
                        onSelect={() => onSelect(chat.id)}
                        onRename={
                          onRename
                            ? (title) => onRename(chat.id, title)
                            : undefined
                        }
                        onPin={
                          onPin
                            ? () => {
                                capture();
                                onPin(chat.id, !chat.pinned);
                              }
                            : undefined
                        }
                        onDelete={onDelete ? () => remove(chat.id) : undefined}
                        onUndo={() => undo(chat.id)}
                      />
                    </Arrive>
                  </div>
                </li>
              ))}
            </ul>
          </section>
        ))}
      </div>
    </nav>
  );
}

"use client";

import * as React from "react";
import {
  AlertCircle,
  ChevronDown,
  Hourglass,
  Layers,
  RotateCcw,
  WifiOff,
} from "lucide-react";
import { NumberRoll } from "./number-roll";
import { StatusButton } from "./status-button";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * CHAT NOTICE: the moments an AI app has to say no
 *
 *   error       the answer failed; Retry opens a spinner and
 *               morphs to "Retrying" while it runs
 *   offline     no connection; "Reconnecting" opens in
 *   rate-limit  out of messages; the countdown rolls down to
 *               the reset, then the hourglass blurs into a check
 *               that draws itself and the words morph to "You can
 *               send messages again"
 *   context     the chat is too long; start fresh with a summary
 *
 * Calm, inline and specific: what happened, what happens next,
 * and the one action that helps. Technical details fold away.
 * ───────────────────────────────────────────────────────── */

export type ChatNoticeKind = "error" | "offline" | "rate-limit" | "context";

export interface ChatNoticeProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "title"
> {
  kind: ChatNoticeKind;
  title?: string;
  description?: string;
  /** Rate limit: when sending is allowed again (ms). Shows a live countdown. */
  resetAt?: number;
  onReset?: () => void;
  onRetry?: () => void;
  /** Shows a spinner on Retry, or "Reconnecting" when offline. */
  retrying?: boolean;
  onUpgrade?: () => void;
  upgradeLabel?: string;
  /** Context: start a new chat carrying a summary of this one. */
  onSummarize?: () => void;
  onNewChat?: () => void;
  /** Technical details, e.g. an error message or request ID. */
  details?: string;
}

const MORPH = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const BUTTON = `inline-flex h-7 items-center gap-1.5 rounded-full px-3 text-[12px] font-medium transition-[background-color,color,transform] duration-300 active:scale-[0.97] ${FOCUS}`;
const SECONDARY = `cursor-pointer ${BUTTON} text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent`;
const PRIMARY = `cursor-pointer ${BUTTON} bg-primary text-primary-foreground hover:bg-primary/90`;
const TWO_DIGITS = { minimumIntegerDigits: 2 };

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Icons trade places through a blur: the old one shrinks away as the new one grows in. */
const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 260ms ${MORPH}, transform 380ms ${MORPH}, filter 260ms ${MORPH}`,
});

/** A piece of a line that opens out of nothing and folds back into it. */
function Reveal({
  show,
  reduced,
  className = "",
  children,
}: {
  show: boolean;
  reduced: boolean;
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <span
      aria-hidden={!show || undefined}
      className={`inline-grid align-bottom ${className}`}
      style={{
        gridTemplateColumns: show ? "1fr" : "0fr",
        opacity: show ? 1 : 0,
        filter: show ? "none" : "blur(3px)",
        transition: reduced
          ? "none"
          : `grid-template-columns 460ms ${MORPH}, opacity ${show ? "320ms" : "160ms"} ${MORPH}, filter 320ms ${MORPH}`,
      }}
    >
      <span className="min-w-0 whitespace-nowrap [clip-path:inset(-4px_-2px)]">
        {children}
      </span>
    </span>
  );
}

function useCountdown(resetAt: number | undefined, onReset?: () => void) {
  // Unknown until mounted, so the first paint never claims the limit has already reset.
  const [now, setNow] = React.useState<number | null>(null);
  const fired = React.useRef(false);
  React.useEffect(() => {
    if (resetAt === undefined) return;
    fired.current = false;
    const tick = () => {
      const t = Date.now();
      setNow(t);
      if (t >= resetAt && !fired.current) {
        fired.current = true;
        onReset?.();
      }
    };
    tick();
    const timer = window.setInterval(tick, 1000);
    return () => window.clearInterval(timer);
  }, [resetAt, onReset]);
  return resetAt === undefined || now === null
    ? undefined
    : Math.max(0, resetAt - now);
}

/** "4:59" rolling down a second at a time ("1h 05m" when it's over an hour); seconds roll back 00 → 59 like a clock. */
function Countdown({ ms, reduced }: { ms: number; reduced: boolean }) {
  const s = Math.max(0, Math.ceil(ms / 1000));
  const hours = Math.floor(s / 3600);
  const minutes = hours ? Math.floor((s % 3600) / 60) : Math.floor(s / 60);
  return (
    <span className="inline-flex items-baseline tabular-nums">
      <Reveal show={hours > 0} reduced={reduced}>
        <NumberRoll value={hours} suffix="h" duration={600} />
        &nbsp;
      </Reveal>
      <NumberRoll
        value={minutes}
        suffix={hours ? "m" : ""}
        format={hours ? TWO_DIGITS : undefined}
        direction="down"
        duration={600}
      />
      <Reveal show={!hours} reduced={reduced}>
        :
        <NumberRoll
          value={s % 60}
          format={TWO_DIGITS}
          direction="down"
          duration={600}
        />
      </Reveal>
    </span>
  );
}

export function ChatNotice({
  kind,
  title,
  description,
  resetAt,
  onReset,
  onRetry,
  retrying = false,
  onUpgrade,
  upgradeLabel = "Upgrade",
  onSummarize,
  onNewChat,
  details,
  className = "",
  ...props
}: ChatNoticeProps) {
  const reduced = useReducedMotion();
  const left = useCountdown(
    kind === "rate-limit" ? resetAt : undefined,
    onReset,
  );
  const ready = left === 0;
  const [detailsOpen, setDetailsOpen] = React.useState(false);
  const detailsId = React.useId();
  const counting =
    kind === "rate-limit" &&
    description === undefined &&
    resetAt !== undefined &&
    !ready;

  const preset = {
    error: {
      title: "Something went wrong",
      description: "The answer didn’t finish. Your message is safe.",
    },
    offline: {
      title: "You’re offline",
      description:
        "We’ll pick up where you left off when your connection is back.",
    },
    "rate-limit": {
      title: ready
        ? "You can send messages again"
        : "You’ve reached your limit",
      description: ready
        ? "Your limit has reset."
        : resetAt !== undefined
          ? "It resets in"
          : "It resets soon.",
    },
    context: {
      title: "This chat is getting long",
      description:
        "Earlier messages may be forgotten. Start fresh with a summary to keep answers sharp.",
    },
  }[kind];

  const iconKey = kind === "rate-limit" && ready ? "ready" : kind;
  const icons: Record<string, React.ReactNode> = {
    error: <AlertCircle className="size-4 text-red-500" />,
    offline: <WifiOff className="size-4 text-muted-foreground" />,
    "rate-limit": <Hourglass className="size-4 text-amber-500" />,
    ready: (
      <svg
        viewBox="0 0 16 16"
        fill="none"
        className="size-4 text-emerald-600 dark:text-emerald-400"
      >
        <path
          d="M3.5 8.5 6.5 11.5 12.5 4.5"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
          pathLength={1}
          strokeDasharray={1}
          style={{
            strokeDashoffset: iconKey === "ready" ? 0 : 1,
            transition:
              iconKey === "ready" && !reduced
                ? `stroke-dashoffset 420ms ${MORPH} 140ms`
                : "none",
          }}
        />
      </svg>
    ),
    context: <Layers className="size-4 text-muted-foreground" />,
  };
  const shownIcons = kind === "rate-limit" ? ["rate-limit", "ready"] : [kind];
  const resetsAt =
    resetAt !== undefined && left !== undefined
      ? new Date(resetAt).toLocaleTimeString([], {
          hour: "numeric",
          minute: "2-digit",
        })
      : undefined;

  return (
    // Laid out by its own width, not the screen's, so it reads right in a narrow column too.
    <div className="w-full">
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 560px)" }}
      />
      <div className="@container w-full">
        <div
          role={kind === "error" ? "alert" : "status"}
          className={`flex flex-col gap-3 rounded-xl border border-border bg-background px-3.5 py-3 animate-[ui-fade-up_320ms_cubic-bezier(0.23,1,0.32,1)_both] motion-reduce:animate-none @[36rem]:flex-row @[36rem]:items-start ${className}`}
          {...props}
        >
          <div className="flex min-w-0 flex-1 gap-3">
            <span
              aria-hidden="true"
              className="relative mt-0.5 flex size-4 shrink-0"
            >
              {shownIcons.map((k) => (
                <span
                  key={k}
                  className="absolute inset-0 flex items-center justify-center"
                  style={swap(k === iconKey, reduced)}
                >
                  {icons[k]}
                </span>
              ))}
            </span>
            <div className="min-w-0">
              <p className="text-[13px] font-medium leading-5 text-foreground">
                <TextMorph animateWidth={false}>
                  {title ?? preset.title}
                </TextMorph>
              </p>
              <p className="text-[12.5px] leading-5 text-muted-foreground">
                <TextMorph animateWidth={false}>
                  {description ?? preset.description}
                </TextMorph>
                {kind === "rate-limit" &&
                  description === undefined &&
                  resetAt !== undefined && (
                    // The ticking digits are hidden from screen readers (the notice is a live region); they hear the time it resets instead.
                    <Reveal
                      show={counting && left !== undefined}
                      reduced={reduced}
                    >
                      <span aria-hidden="true">
                        &nbsp;
                        {left !== undefined && (
                          <Countdown ms={left} reduced={reduced} />
                        )}
                        .
                      </span>
                      {resetsAt && counting && (
                        <span className="sr-only"> at {resetsAt}</span>
                      )}
                    </Reveal>
                  )}
                {kind === "offline" && (
                  <Reveal show={retrying} reduced={reduced}>
                    <span className="ml-1.5 inline-flex items-center gap-1.5 text-foreground/70">
                      <span
                        aria-hidden="true"
                        className={`size-1.5 rounded-full bg-amber-500 motion-reduce:animate-none ${retrying ? "animate-[ui-breathe_1.4s_ease-in-out_infinite]" : ""}`}
                      />
                      Reconnecting
                    </span>
                  </Reveal>
                )}
              </p>
              {details && (
                <>
                  <button
                    type="button"
                    aria-expanded={detailsOpen}
                    aria-controls={detailsId}
                    onClick={() => setDetailsOpen((o) => !o)}
                    className={`cursor-pointer mt-1.5 flex items-center gap-1 rounded text-[11.5px] text-muted-foreground transition-colors hover:text-foreground ${FOCUS}`}
                  >
                    <TextMorph>
                      {detailsOpen ? "Hide details" : "Show details"}
                    </TextMorph>
                    <ChevronDown
                      aria-hidden="true"
                      className="size-3 transition-transform duration-300 motion-reduce:transition-none"
                      style={{
                        transform: detailsOpen ? "rotate(180deg)" : "none",
                        transitionTimingFunction: MORPH,
                      }}
                    />
                  </button>
                  <div
                    id={detailsId}
                    inert={!detailsOpen}
                    className="grid"
                    style={{
                      gridTemplateRows: detailsOpen ? "1fr" : "0fr",
                      opacity: detailsOpen ? 1 : 0,
                      transition: reduced
                        ? "none"
                        : `grid-template-rows 420ms ${MORPH}, opacity ${detailsOpen ? "320ms" : "160ms"} ${MORPH}`,
                    }}
                  >
                    <div className="min-h-0 overflow-hidden">
                      <p className="pt-1 break-all font-mono text-[11px] leading-5 text-muted-foreground">
                        {details}
                      </p>
                    </div>
                  </div>
                </>
              )}
            </div>
          </div>

          <div className="flex shrink-0 flex-wrap items-center gap-2 pl-7 @[36rem]:pl-0">
            {(kind === "error" || kind === "offline") && onRetry && (
              <StatusButton
                variant="outline"
                size="sm"
                icon={<RotateCcw />}
                status={retrying ? "pending" : "idle"}
                labels={
                  kind === "offline"
                    ? { idle: "Try now", pending: "Trying" }
                    : { idle: "Retry", pending: "Retrying" }
                }
                onClick={onRetry}
              />
            )}
            {kind === "rate-limit" && onUpgrade && (
              // Folds away once the limit has reset.
              <Reveal show={!ready} reduced={reduced}>
                <span className="block p-0.5">
                  <button
                    type="button"
                    inert={ready}
                    onClick={onUpgrade}
                    className={PRIMARY}
                  >
                    {upgradeLabel}
                  </button>
                </span>
              </Reveal>
            )}
            {kind === "context" && onNewChat && (
              <button type="button" onClick={onNewChat} className={SECONDARY}>
                New chat
              </button>
            )}
            {kind === "context" && onSummarize && (
              <button type="button" onClick={onSummarize} className={PRIMARY}>
                Continue with summary
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { ArrowDown } from "lucide-react";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * JUMP TO LATEST: a chat that follows the answer, until you
 * scroll away
 *
 *   following  pinned to the bottom while text streams in
 *   away       you scrolled up: it lets go at once, and a round
 *              ↓ button appears
 *   new below  text arrived while you were away: the button
 *              widens into "● Writing"; when the answer ends the
 *              label morphs to "New reply"
 *   back       a click glides down, chasing the moving bottom,
 *              and it follows again
 *
 * Wrap your messages. Give it a height (or flex-1) and change
 * followKey when someone sends, to bring them back down.
 * ───────────────────────────────────────────────────────── */

export interface ChatScrollProps extends React.HTMLAttributes<HTMLDivElement> {
  children: React.ReactNode;
  /** True while an answer streams; the button says "Writing". */
  streaming?: boolean;
  /** Change it (e.g. to the latest message id) to jump to the bottom, e.g. after sending. */
  followKey?: React.Key;
  /** How close to the bottom (px) still counts as at the bottom. */
  threshold?: number;
  /** Classes for the inner content column. */
  contentClassName?: string;
}

const EASE = "cubic-bezier(0.23,1,0.32,1)";
// A light that sweeps across the label. A mask, not a text clip, so it reaches letters that are mid-morph.
const SHEEN =
  "text-foreground [mask-image:linear-gradient(90deg,rgb(0_0_0/0.45)_35%,#000_50%,rgb(0_0_0/0.45)_65%)] [mask-size:200%_100%] animate-[ui-sheen_1.4s_linear_infinite] motion-reduce:animate-none motion-reduce:[mask-image:none] motion-reduce:text-foreground/70";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

export function ChatScroll({
  children,
  streaming = false,
  followKey,
  threshold = 48,
  className = "",
  contentClassName = "",
  ...props
}: ChatScrollProps) {
  const reduced = useReducedMotion();
  const scrollerRef = React.useRef<HTMLDivElement>(null);
  const contentRef = React.useRef<HTMLDivElement>(null);
  const stuck = React.useRef(true);
  const lastTop = React.useRef(0);
  const touchY = React.useRef(0);
  const frame = React.useRef(0);
  const gliding = React.useRef(false);
  // When the person last reached for the scroll; only their own scrolling lets go of the bottom.
  const intent = React.useRef(0);
  const [away, setAway] = React.useState(false);
  const [unread, setUnread] = React.useState(false);

  const distance = () => {
    const el = scrollerRef.current;
    return el ? el.scrollHeight - el.clientHeight - el.scrollTop : 0;
  };

  const release = () => {
    cancelAnimationFrame(frame.current);
    gliding.current = false;
    stuck.current = false;
  };

  /* Glide to the bottom, re-reading it every frame because it moves while text streams in. */
  const toBottom = React.useCallback(
    (smooth: boolean) => {
      const el = scrollerRef.current;
      if (!el) return;
      cancelAnimationFrame(frame.current);
      stuck.current = true;
      setAway(false);
      setUnread(false);
      if (!smooth || reduced) {
        el.scrollTop = el.scrollHeight;
        return;
      }
      gliding.current = true;
      const from = el.scrollTop;
      const start = performance.now();
      const step = (now: number) => {
        const t = Math.min(1, (now - start) / 520);
        const eased = 1 - Math.pow(1 - t, 4);
        el.scrollTop =
          from + (el.scrollHeight - el.clientHeight - from) * eased;
        if (t < 1) frame.current = requestAnimationFrame(step);
        else gliding.current = false;
      };
      frame.current = requestAnimationFrame(step);
    },
    [reduced],
  );

  // Start at the latest message.
  React.useLayoutEffect(() => {
    const el = scrollerRef.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, []);

  // While following, every bit of new content keeps the bottom in view; while away, it's unread.
  React.useEffect(() => {
    const content = contentRef.current;
    const el = scrollerRef.current;
    if (!content || !el) return;
    const observer = new ResizeObserver(() => {
      if (stuck.current) {
        if (!gliding.current) el.scrollTop = el.scrollHeight;
      } else if (distance() > threshold) {
        setUnread(true);
        setAway(true);
      }
    });
    observer.observe(content);
    return () => {
      observer.disconnect();
      cancelAnimationFrame(frame.current);
    };
  }, [threshold]);

  // A new message from the person brings them back down.
  const firstKey = React.useRef(followKey);
  React.useEffect(() => {
    if (followKey === firstKey.current) return;
    firstKey.current = followKey;
    toBottom(true);
  }, [followKey, toBottom]);

  const onScroll = () => {
    const el = scrollerRef.current;
    if (!el) return;
    const top = el.scrollTop;
    const d = distance();
    // Upward movement counts only if the person caused it, not when content shrinks and the browser clamps.
    const userUp =
      top < lastTop.current - 1 &&
      !gliding.current &&
      performance.now() - intent.current < 800;
    lastTop.current = top;
    if (userUp) {
      release();
      setAway(d > threshold);
    } else if (!stuck.current && d <= threshold) {
      // Back at the bottom: follow again.
      stuck.current = true;
      setAway(false);
      setUnread(false);
    } else if (!stuck.current) setAway(d > threshold);
  };

  const reach = () => (intent.current = performance.now());

  return (
    <div className={`relative min-h-0 ${className}`} {...props}>
      <div
        ref={scrollerRef}
        tabIndex={0}
        aria-label="Conversation"
        onScroll={onScroll}
        // Let go the moment someone reaches for the scroll, before the next frame of text pulls them down.
        onWheel={(e) => {
          reach();
          if (e.deltaY < 0) release();
        }}
        onTouchStart={(e) => {
          reach();
          touchY.current = e.touches[0]?.clientY ?? 0;
        }}
        onTouchMove={(e) => {
          reach();
          if ((e.touches[0]?.clientY ?? 0) > touchY.current) release();
        }}
        onKeyDown={(e) => {
          reach();
          if (["ArrowUp", "PageUp", "Home"].includes(e.key)) release();
        }}
        // Dragging the scrollbar.
        onPointerDown={reach}
        className="h-full overflow-y-auto overscroll-contain outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/30"
      >
        <div ref={contentRef} className={contentClassName}>
          {children}
        </div>
      </div>

      <div className="pointer-events-none absolute inset-x-0 bottom-3 flex justify-center">
        <button
          type="button"
          inert={!away}
          onClick={() => toBottom(true)}
          aria-label={
            unread
              ? `${streaming ? "Still writing" : "New reply"} below. Jump to latest`
              : "Jump to latest"
          }
          className="cursor-pointer pointer-events-auto flex h-8 items-center rounded-full border border-border bg-background px-2 text-[12.5px] font-medium text-foreground outline-none focus-visible:ring-2 focus-visible:ring-ring/40 active:scale-[0.96]"
          style={{
            opacity: away ? 1 : 0,
            transform: away ? "none" : "translateY(8px) scale(0.92)",
            transition: reduced
              ? "none"
              : `opacity 220ms ${EASE}, transform 320ms ${EASE}`,
          }}
        >
          {/* The label opens out of the round button; its words morph from "Writing" to "New reply" and the pill follows. */}
          <span
            aria-hidden="true"
            className="grid"
            style={{
              gridTemplateColumns: unread ? "1fr" : "0fr",
              opacity: unread ? 1 : 0,
              transition: reduced
                ? "none"
                : `grid-template-columns 380ms ${EASE}, opacity 260ms ${EASE}`,
            }}
          >
            <span className="flex min-w-0 items-center gap-1.5 overflow-hidden whitespace-nowrap">
              <span className="flex shrink-0 items-center gap-1.5 pl-1 pr-1.5">
                <span className="relative flex size-1.5">
                  <span
                    className={`absolute inset-0 rounded-full bg-primary motion-reduce:animate-none ${streaming ? "animate-[ui-ping_1.4s_cubic-bezier(0,0,0.2,1)_infinite]" : "opacity-0"}`}
                  />
                  <span className="relative size-1.5 rounded-full bg-primary" />
                </span>
                <span
                  className={`transition-colors duration-300 ${streaming ? SHEEN : ""}`}
                >
                  <TextMorph>{streaming ? "Writing" : "New reply"}</TextMorph>
                </span>
              </span>
            </span>
          </span>
          <ArrowDown aria-hidden="true" className="size-4" />
        </button>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import {
  EASE_OUT,
  EASE_THROW,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * CHECKBOX: a tick that draws itself
 *
 *   check    the box fills from its centre (a slight overshoot)
 *            and the tick draws itself along its stroke
 *   uncheck  the tick retracts the way it came, the fill shrinks
 *   mixed    a dash grows from the middle; mixed → checked bends
 *            the dash into the tick
 *   press    the box gives under the finger
 *
 * A real <input type="checkbox"> underneath, so forms, labels,
 * Space and screen readers all work as they always do.
 * ───────────────────────────────────────────────────────── */

export interface CheckboxProps extends Omit<
  React.InputHTMLAttributes<HTMLInputElement>,
  "type" | "size" | "checked" | "defaultChecked"
> {
  checked?: boolean | "mixed";
  defaultChecked?: boolean;
  onCheckedChange?: (checked: boolean) => void;
  label?: React.ReactNode;
  description?: React.ReactNode;
  /** 14px or 16px box. */
  size?: "sm" | "md";
  ref?: React.Ref<HTMLInputElement>;
}

export function Checkbox({
  checked,
  defaultChecked = false,
  onCheckedChange,
  label,
  description,
  size = "md",
  disabled,
  className = "",
  onChange,
  ref,
  id,
  ...props
}: CheckboxProps) {
  const reduced = useInteractionReducedMotion();
  const auto = React.useId();
  const inputId = id ?? auto;
  const inner = React.useRef<HTMLInputElement>(null);
  const [own, setOwn] = React.useState(defaultChecked);
  const state = checked !== undefined ? checked : own;
  const on = state === true;
  const mixed = state === "mixed";

  React.useEffect(() => {
    if (inner.current) inner.current.indeterminate = mixed;
  }, [mixed]);

  const box = size === "sm" ? "size-3.5 rounded-[4px]" : "size-4 rounded-[5px]";
  const t = (ms: number, delay = 0, ease = EASE_OUT) =>
    reduced ? "none" : `${ms}ms ${ease} ${delay}ms`;

  return (
    <label
      htmlFor={inputId}
      className={`group/cb inline-flex select-none items-start gap-2.5 ${disabled ? "cursor-default opacity-50" : "cursor-pointer"} ${className}`}
    >
      <span className={`relative mt-[2px] inline-flex shrink-0 ${box}`}>
        <input
          ref={(el) => {
            inner.current = el;
            if (typeof ref === "function") ref(el);
            else if (ref)
              (ref as React.RefObject<HTMLInputElement | null>).current = el;
          }}
          id={inputId}
          type="checkbox"
          checked={on}
          disabled={disabled}
          aria-checked={mixed ? "mixed" : on}
          onChange={(e) => {
            if (checked === undefined) setOwn(e.target.checked);
            onChange?.(e);
            onCheckedChange?.(e.target.checked);
          }}
          className="peer absolute inset-0 m-0 size-full cursor-[inherit] appearance-none rounded-[inherit] outline-none"
          {...props}
        />
        {/* The box: a thin line that the fill grows over. */}
        <span
          aria-hidden="true"
          className={`pointer-events-none absolute inset-0 rounded-[inherit] bg-background shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--foreground)_22%,var(--border))] transition-[box-shadow,scale] duration-200 group-hover/cb:shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--foreground)_40%,var(--border))] group-active/cb:scale-[0.88] peer-focus-visible:shadow-[inset_0_0_0_1px_var(--ring),0_0_0_3px_color-mix(in_oklab,var(--ring)_20%,transparent)] motion-reduce:group-active/cb:scale-100`}
        >
          <span
            className="absolute inset-0 rounded-[inherit] bg-primary"
            style={{
              transform: on || mixed ? "scale(1)" : "scale(0.4)",
              opacity: on || mixed ? 1 : 0,
              transition: reduced
                ? "none"
                : `transform ${t(320, 0, EASE_THROW)}, opacity ${t(160)}`,
            }}
          />
          <svg
            viewBox="0 0 16 16"
            fill="none"
            className="absolute inset-0 size-full text-primary-foreground"
          >
            {/* The tick draws on the way in and retracts on the way out. */}
            <path
              d="M4 8.4 6.8 11 12 5.2"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
              pathLength={1}
              strokeDasharray={1}
              style={{
                strokeDashoffset: on ? 0 : 1,
                transition: reduced
                  ? "none"
                  : `stroke-dashoffset ${on ? t(300, 90) : t(160)}`,
              }}
            />
            <path
              d="M4.5 8h7"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              style={{
                transform: mixed ? "scaleX(1)" : "scaleX(0)",
                transformOrigin: "8px 8px",
                transition: reduced
                  ? "none"
                  : `transform ${t(260, mixed ? 60 : 0)}`,
              }}
            />
          </svg>
        </span>
      </span>
      {(label || description) && (
        <span className="flex min-w-0 flex-col gap-0.5">
          {label && (
            <span className="text-[13.5px] font-medium leading-5 text-foreground">
              {label}
            </span>
          )}
          {description && (
            <span className="text-[12.5px] leading-snug text-muted-foreground">
              {description}
            </span>
          )}
        </span>
      )}
    </label>
  );
}

export default Checkbox;

"use client";

import * as React from "react";
import { Lock } from "lucide-react";
import { Input } from "./input";
import { NumberRoll } from "./number-roll";
import { Select } from "./select";
import { StatusButton, type ActionStatus } from "./status-button";
import { TextMorph } from "./text-morph";
import {
  EASE_THROW,
  INTERACTION_FOCUS,
  INTERACTION_PRESS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * CHECKOUT: steps that stack into a receipt
 *
 *   steps     contact, shipping, delivery and payment on one
 *             surface; the step you're on is open, a rail of light
 *             runs down the numbers as you finish them
 *   stack     a finished step folds into one line under its title
 *             ("Iris Okafor, 12 Elm Street, Leeds · Change") with
 *             a check drawn in its number
 *   delivery  speeds show the day they arrive; the total on the
 *             lit summary rolls when you switch
 *   placed    Place order goes Placing order → your order number,
 *             and the steps lock
 *
 * Payment is your provider's: put its element (Stripe's Payment
 * Element, PayPal buttons, anything) in the `payment` slot, so this
 * block never sees card data. onPlaceOrder gets the order; resolve
 * with { number } to show it, throw an Error to say why not.
 * ───────────────────────────────────────────────────────── */

export interface CheckoutLine {
  id: string;
  name: string;
  /** e.g. "Sand · M". */
  detail?: string;
  quantity: number;
  /** Unit price, major units. */
  price: number;
  image?: string;
  icon?: React.ReactNode;
}

export interface CheckoutAddress {
  name: string;
  line1: string;
  line2: string;
  city: string;
  postcode: string;
  country: string;
}

export interface CheckoutDelivery {
  id: string;
  label: string;
  /** e.g. "Royal Mail Tracked". */
  detail?: string;
  price: number;
  /** Days from today it arrives: one number, or the earliest and latest. */
  days: number | [number, number];
}

export interface CheckoutOrder {
  email: string;
  address: CheckoutAddress;
  delivery: CheckoutDelivery;
  lines: CheckoutLine[];
  subtotal: number;
  discount: number;
  shipping: number;
  tax: number;
  total: number;
}

export interface CheckoutProps {
  lines: CheckoutLine[];
  deliveries: CheckoutDelivery[];
  /** Off the subtotal, major units. */
  discount?: number;
  /** Tax rate on the goods and delivery, e.g. 0.2 for 20%. */
  taxRate?: number;
  countries?: { value: string; label: string }[];
  defaultEmail?: string;
  defaultAddress?: Partial<CheckoutAddress>;
  /** Your payment provider's element, shown in the payment step. */
  payment?: React.ReactNode;
  /** Place the order; resolve with { number } to show it, throw an Error to say why not. */
  onPlaceOrder: (order: CheckoutOrder) => Promise<unknown>;
  currency?: string;
  locale?: string;
  className?: string;
}

type Step = "contact" | "shipping" | "delivery" | "payment";
const STEPS: { id: Step; title: string }[] = [
  { id: "contact", title: "Contact" },
  { id: "shipping", title: "Shipping address" },
  { id: "delivery", title: "Delivery" },
  { id: "payment", title: "Payment" },
];
const COUNTRIES = [
  { value: "US", label: "United States" },
  { value: "GB", label: "United Kingdom" },
  { value: "CA", label: "Canada" },
  { value: "DE", label: "Germany" },
  { value: "FR", label: "France" },
  { value: "AU", label: "Australia" },
  { value: "IN", label: "India" },
];
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const EASE = "cubic-bezier(0.16,1,0.3,1)";
const DAY = 86_400_000;

const subscribeNothing = () => () => {};
/** False on the server and while hydrating: text is formatted in one fixed locale until then, so the server's and the visitor's never disagree. */
const useHydrated = () =>
  React.useSyncExternalStore(
    subscribeNothing,
    () => true,
    () => false,
  );

const mix = (color: string, amount: number, into = "transparent") =>
  `color-mix(in oklab, ${color} ${amount}%, ${into})`;
const SUMMARY: React.CSSProperties = {
  backgroundColor: "var(--primary)",
  backgroundImage: `radial-gradient(120% 70% at 100% 0%, ${mix("var(--primary-foreground)", 22)} 0%, transparent 55%), linear-gradient(175deg, transparent 40%, ${mix("black", 24)} 100%)`,
  boxShadow: `inset 0 1px 0 ${mix("var(--primary-foreground)", 36)}, inset 0 0 0 1px ${mix("var(--primary-foreground)", 12)}`,
};
const CARD: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, var(--card), ${mix("var(--card)", 95, "var(--foreground)")})`,
  boxShadow: `0 0 0 1px var(--border), inset 0 1px 0 ${mix("var(--background)", 85)}`,
};
const INVERSE: React.CSSProperties = {
  background: "var(--primary-foreground)",
  color: "var(--primary)",
  boxShadow: `inset 0 -1px 0 ${mix("black", 8)}`,
};

function tint(seed: string): React.CSSProperties {
  let h = 0;
  for (const c of seed) h = (h * 31 + c.charCodeAt(0)) >>> 0;
  const chart = `var(--chart-${(h % 5) + 1}, var(--primary))`;
  return {
    background: mix(chart, 22, "var(--primary-foreground)"),
    color: mix(chart, 80, "black"),
  };
}

const money = (currency: string, n: number): Intl.NumberFormatOptions => ({
  style: "currency",
  currency,
  minimumFractionDigits: n % 1 ? 2 : 0,
  maximumFractionDigits: 2,
});
const round = (n: number) => Math.round(n * 100) / 100;

/** A fold that keeps its children laid out, so its height eases open and shut. */
function Fold({
  open,
  reduced,
  children,
}: {
  open: boolean;
  reduced: boolean;
  children: React.ReactNode;
}) {
  return (
    <div
      className="grid grid-cols-1"
      style={{
        gridTemplateRows: open ? "1fr" : "0fr",
        opacity: open ? 1 : 0,
        transition: reduced
          ? "opacity 160ms"
          : `grid-template-rows 440ms ${EASE}, opacity ${open ? 320 : 140}ms ${EASE} ${open ? 80 : 0}ms`,
      }}
    >
      <div className="min-h-0 overflow-clip" inert={!open || undefined}>
        {children}
      </div>
    </div>
  );
}

export function Checkout({
  lines,
  deliveries,
  discount = 0,
  taxRate = 0,
  countries = COUNTRIES,
  defaultEmail = "",
  defaultAddress,
  payment,
  onPlaceOrder,
  currency = "USD",
  locale,
  className = "",
}: CheckoutProps) {
  const reduced = useInteractionReducedMotion();
  const hydrated = useHydrated();
  const baseId = React.useId();
  const [step, setStep] = React.useState<Step>("contact");
  const [done, setDone] = React.useState<ReadonlySet<Step>>(() => new Set());
  const [email, setEmail] = React.useState(defaultEmail);
  const [address, setAddress] = React.useState<CheckoutAddress>({
    name: "",
    line1: "",
    line2: "",
    city: "",
    postcode: "",
    country: countries[0]?.value ?? "",
    ...defaultAddress,
  });
  const [deliveryId, setDeliveryId] = React.useState<string | null>(null);
  const [errors, setErrors] = React.useState<
    Partial<Record<keyof CheckoutAddress | "email", string>>
  >({});
  const [place, setPlace] = React.useState<{
    status: ActionStatus;
    number?: string;
    error?: string;
  }>({ status: "idle" });
  const [today, setToday] = React.useState<number | null>(null);
  const [said, setSaid] = React.useState("");
  const bodies = React.useRef(new Map<Step, HTMLElement>());

  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setToday(Date.now()));
    return () => cancelAnimationFrame(frame);
  }, []);

  const delivery = deliveries.find((d) => d.id === deliveryId) ?? null;
  const subtotal = round(lines.reduce((n, l) => n + l.price * l.quantity, 0));
  const off = Math.min(discount, subtotal);
  const shipping = delivery?.price ?? 0;
  const tax = round((subtotal - off + shipping) * taxRate);
  const total = round(subtotal - off + shipping + tax);
  const placed = place.status === "success";
  const busy = place.status === "pending" || placed;
  const index = STEPS.findIndex((s) => s.id === step);
  const ready =
    done.has("contact") && done.has("shipping") && done.has("delivery");

  const fmt = (n: number) => money(currency, n);
  const loc = locale ?? (hydrated ? undefined : "en-US");
  const cash = (n: number) => new Intl.NumberFormat(loc, fmt(n)).format(n);
  const arrives = (d: CheckoutDelivery) => {
    if (today === null) return "";
    const [a, b] = Array.isArray(d.days) ? d.days : [d.days, d.days];
    const day = new Intl.DateTimeFormat(loc, {
      weekday: "short",
      day: "numeric",
      month: "short",
    });
    return a === b
      ? `Arrives ${day.format(today + a * DAY)}`
      : `Arrives ${day.formatRange(today + a * DAY, today + b * DAY)}`;
  };
  const country =
    countries.find((c) => c.value === address.country)?.label ??
    address.country;
  const summaries: Record<Step, string> = {
    contact: email,
    shipping: [
      address.name,
      address.line1,
      address.line2,
      `${address.city} ${address.postcode}`.trim(),
      country,
    ]
      .filter(Boolean)
      .join(", "),
    delivery: delivery
      ? `${delivery.label} · ${delivery.price ? cash(delivery.price) : "Free"}`
      : "",
    payment: "",
  };

  const open = (s: Step) => {
    if (busy) return;
    setStep(s);
    window.setTimeout(
      () =>
        bodies.current
          .get(s)
          ?.querySelector<HTMLElement>("input,button[role=radio],button")
          ?.focus({ preventScroll: true }),
      reduced ? 0 : 320,
    );
  };

  const finish = (s: Step) => {
    if (s === "contact") {
      const problem = EMAIL.test(email.trim())
        ? undefined
        : email.trim()
          ? "That email doesn’t look right"
          : "Add your email";
      setErrors({ email: problem });
      if (problem) return;
    }
    if (s === "shipping") {
      const need: (keyof CheckoutAddress)[] = [
        "name",
        "line1",
        "city",
        "postcode",
      ];
      const problems = Object.fromEntries(
        need.filter((k) => !address[k].trim()).map((k) => [k, "Required"]),
      );
      setErrors(problems);
      if (Object.keys(problems).length) return;
    }
    if (s === "delivery" && !delivery) return;
    setDone((d) => new Set([...d, s]));
    const next =
      STEPS.find(
        (x, i) => i > STEPS.findIndex((y) => y.id === s) && !done.has(x.id),
      )?.id ?? "payment";
    setSaid(`${STEPS.find((x) => x.id === s)?.title} saved.`);
    open(next);
  };

  const placeOrder = async () => {
    if (!ready || !delivery || busy) return;
    setPlace({ status: "pending" });
    try {
      const result = await onPlaceOrder({
        email: email.trim(),
        address,
        delivery,
        lines,
        subtotal,
        discount: off,
        shipping,
        tax,
        total,
      });
      const number =
        result && typeof result === "object" && "number" in result
          ? String((result as { number: unknown }).number)
          : undefined;
      setPlace({ status: "success", number });
      setSaid(number ? `Order ${number} placed.` : "Order placed.");
    } catch (e) {
      setPlace({
        status: "error",
        error:
          e instanceof Error && e.message
            ? e.message
            : "Couldn’t place the order. Try again.",
      });
    }
  };

  const field = (
    k: keyof CheckoutAddress,
    label: string,
    autoComplete: string,
    extra?: Partial<React.ComponentProps<typeof Input>>,
  ) => (
    <Input
      label={label}
      autoComplete={autoComplete}
      value={address[k]}
      error={errors[k]}
      onValueChange={(v) => {
        setAddress((a) => ({ ...a, [k]: v }));
        if (errors[k]) setErrors((e) => ({ ...e, [k]: undefined }));
      }}
      {...extra}
    />
  );

  const next = `inline-flex h-10 cursor-pointer items-center justify-center rounded-full bg-primary px-5 text-[13.5px] font-medium text-primary-foreground hover:bg-primary/90 disabled:cursor-default disabled:opacity-45 ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`;

  return (
    <section
      aria-labelledby={`${baseId}-title`}
      className={`w-full max-w-[860px] rounded-[28px] p-2 text-card-foreground ${className}`}
      style={CARD}
    >
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 860px)" }}
      />
      <div className="@container w-full">
        <h2 id={`${baseId}-title`} className="sr-only">
          Checkout
        </h2>
        <div className="grid grid-cols-1 gap-2 @[700px]:grid-cols-[minmax(0,1fr)_320px] @[700px]:items-start">
          {/* Flat: the steps, finished ones stacked as one line each. */}
          <ol className="relative px-2 py-1" inert={placed || undefined}>
            {/* The rail of light down the numbers, as far as you've got. */}
            <span
              aria-hidden="true"
              className="absolute bottom-6 left-[19.5px] top-6 w-px bg-border"
            />
            <span
              aria-hidden="true"
              className="absolute left-[19.5px] top-6 w-px origin-top bg-primary"
              style={{
                height: "calc(100% - 48px)",
                transform: `scaleY(${Math.min(done.size, STEPS.length - 1) / (STEPS.length - 1)})`,
                transition: reduced ? "none" : `transform 620ms ${EASE}`,
              }}
            />
            {STEPS.map((s, i) => {
              const isOn = s.id === step;
              const isDone = done.has(s.id) && !isOn;
              const reachable =
                isDone ||
                i <= index ||
                STEPS.slice(0, i).every((p) => done.has(p.id));
              return (
                <li key={s.id} className="relative py-2.5 pl-9">
                  <span
                    aria-hidden="true"
                    className="absolute left-0 top-[13px] flex size-6 items-center justify-center rounded-full text-[11.5px] font-medium tabular-nums"
                    style={{
                      background: isDone ? "var(--primary)" : "var(--card)",
                      color: isDone
                        ? "var(--primary-foreground)"
                        : isOn
                          ? "var(--primary)"
                          : "var(--muted-foreground)",
                      boxShadow: isDone
                        ? "none"
                        : `inset 0 0 0 ${isOn ? 1.5 : 1}px ${isOn ? "var(--primary)" : "var(--border)"}`,
                      transition: reduced
                        ? "none"
                        : `background-color 300ms ${EASE}, box-shadow 300ms ${EASE}, color 300ms`,
                    }}
                  >
                    {isDone ? (
                      <svg viewBox="0 0 16 16" fill="none" className="size-3.5">
                        <path
                          d="M3.5 8.5 6.5 11.5 12.5 4.5"
                          stroke="currentColor"
                          strokeWidth="2.2"
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeDasharray={24}
                          className="motion-safe:animate-[ui-draw_420ms_cubic-bezier(0.16,1,0.3,1)_120ms_both]"
                        />
                      </svg>
                    ) : (
                      i + 1
                    )}
                  </span>
                  <div className="flex min-h-7 items-center justify-between gap-3">
                    <h3
                      className={`text-[14.5px] font-medium tracking-[-0.01em] ${isOn || isDone ? "text-foreground" : "text-muted-foreground"}`}
                    >
                      {s.title}
                    </h3>
                    {isDone && !placed && (
                      <button
                        type="button"
                        onClick={() => open(s.id)}
                        aria-label={`Change ${s.title.toLowerCase()}`}
                        className={`-mr-1.5 h-7 cursor-pointer rounded-full px-2.5 text-[12.5px] text-primary hover:bg-primary/10 ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`}
                      >
                        Change
                      </button>
                    )}
                  </div>
                  {/* The finished step, as a line of the receipt. */}
                  <Fold
                    open={isDone && Boolean(summaries[s.id])}
                    reduced={reduced}
                  >
                    <p className="truncate pb-0.5 text-[13px] text-muted-foreground">
                      {summaries[s.id]}
                    </p>
                  </Fold>
                  <Fold open={isOn} reduced={reduced}>
                    <div
                      ref={(el) => {
                        if (el) bodies.current.set(s.id, el);
                      }}
                      className="pb-1 pt-3"
                    >
                      {s.id === "contact" && (
                        <form
                          noValidate
                          className="flex flex-col gap-3 @[480px]:flex-row @[480px]:items-start"
                          onSubmit={(e) => {
                            e.preventDefault();
                            finish("contact");
                          }}
                        >
                          <Input
                            aria-label="Email"
                            type="email"
                            inputMode="email"
                            autoComplete="email"
                            placeholder="you@email.com"
                            value={email}
                            error={errors.email}
                            onValueChange={(v) => {
                              setEmail(v);
                              if (errors.email)
                                setErrors((e) => ({ ...e, email: undefined }));
                            }}
                            className="@[480px]:flex-1"
                          />
                          <button type="submit" className={next}>
                            Continue
                          </button>
                        </form>
                      )}
                      {s.id === "shipping" && (
                        <form
                          noValidate
                          className="grid grid-cols-1 gap-3 @[480px]:grid-cols-2"
                          onSubmit={(e) => {
                            e.preventDefault();
                            finish("shipping");
                          }}
                        >
                          <div className="@[480px]:col-span-2">
                            {field("name", "Full name", "name")}
                          </div>
                          <div className="@[480px]:col-span-2">
                            {field("line1", "Address", "address-line1")}
                          </div>
                          <div className="@[480px]:col-span-2">
                            {field(
                              "line2",
                              "Apartment, suite (optional)",
                              "address-line2",
                            )}
                          </div>
                          {field("city", "City", "address-level2")}
                          {field("postcode", "Postcode", "postal-code")}
                          <div className="@[480px]:col-span-2">
                            <Select
                              label="Country"
                              options={countries}
                              value={address.country}
                              onValueChange={(v) =>
                                setAddress((a) => ({ ...a, country: v }))
                              }
                            />
                          </div>
                          <div className="@[480px]:col-span-2">
                            <button type="submit" className={next}>
                              Continue
                            </button>
                          </div>
                        </form>
                      )}
                      {s.id === "delivery" && (
                        <div>
                          <div
                            role="radiogroup"
                            aria-label="Delivery speed"
                            className="overflow-clip rounded-[18px] border border-border"
                          >
                            {deliveries.map((d) => {
                              const on = d.id === deliveryId;
                              return (
                                <button
                                  key={d.id}
                                  type="button"
