"use client";

import * as React from "react";
import { Globe } from "lucide-react";

/* ─────────────────────────────────────────────────────────
 * CITATION: an inline [1] that previews its source
 *
 *   closed       a small numbered marker in the sentence
 *   open         hover or focus: the card rises out of a light blur
 *                with the site, title and snippet, and sinks back
 *                when you leave
 *   unavailable  the source couldn't be fetched
 *
 * The marker is the link itself, so clicking opens the source.
 * The card is a tooltip describing it; it flips above near the
 * bottom of the screen and shifts to stay inside the viewport.
 * ───────────────────────────────────────────────────────── */

export interface CitationSource {
  title: string;
  url: string;
  snippet?: string;
  /** A favicon, e.g. <img src="…" alt="" />. */
  icon?: React.ReactNode;
}

export interface CitationProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  index: number;
  source?: CitationSource;
  status?: "available" | "unavailable";
}

const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const CARD_WIDTH = 288;
const MORPH = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function hostname(url: string) {
  try {
    return new URL(url).hostname.replace(/^www\./, "");
  } catch {
    return url;
  }
}

export function Citation({
  index,
  source,
  status = "available",
  className = "",
  ...props
}: CitationProps) {
  const reduced = useReducedMotion();
  const [open, setOpen] = React.useState(false);
  // The card stays mounted while it sinks away after closing.
  const [mounted, setMounted] = React.useState(false);
  if (open && !mounted) setMounted(true);
  if (!open && reduced && mounted) setMounted(false);
  const [place, setPlace] = React.useState<{ above: boolean; shift: number }>({
    above: false,
    shift: 0,
  });
  const triggerRef = React.useRef<HTMLAnchorElement>(null);
  const cardRef = React.useRef<HTMLSpanElement>(null);
  const timer = React.useRef<number | undefined>(undefined);
  const id = React.useId();
  const unavailable = status === "unavailable" || !source;

  const show = (delay: number) => {
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => setOpen(true), delay);
  };
  const hide = (delay: number) => {
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => setOpen(false), delay);
  };
  React.useEffect(() => () => window.clearTimeout(timer.current), []);

  // Keep the card on screen: flip above near the bottom, shift left near the right edge.
  React.useLayoutEffect(() => {
    if (!open || !triggerRef.current || !cardRef.current) return;
    const t = triggerRef.current.getBoundingClientRect();
    const h = cardRef.current.offsetHeight;
    const overflowRight = t.left + CARD_WIDTH - (window.innerWidth - 12);
    setPlace({
      above: t.bottom + h + 12 > window.innerHeight && t.top > h + 12,
      shift: Math.max(0, overflowRight),
    });
  }, [open]);

  // Rise in from the side it opens on; sink back the same way, then unmount.
  React.useLayoutEffect(() => {
    const el = cardRef.current;
    if (!el || reduced) return;
    const from = `translateY(${place.above ? 4 : -4}px)`;
    if (open) {
      const enter = el.animate(
        [
          { opacity: 0, transform: from, filter: "blur(2px)" },
          { opacity: 1, transform: "none", filter: "blur(0px)" },
        ],
        { duration: 220, easing: MORPH },
      );
      return () => enter.cancel();
    }
    const leave = el.animate(
      [
        { opacity: 1, transform: "none" },
        { opacity: 0, transform: from },
      ],
      { duration: 140, easing: "ease-out", fill: "forwards" },
    );
    leave.onfinish = () => setMounted(false);
    return () => leave.cancel();
  }, [open, mounted, place.above, reduced]);

  React.useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && setOpen(false);
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [open]);

  return (
    <span
      className={`relative inline-block align-baseline ${className}`}
      onMouseEnter={() => show(120)}
      onMouseLeave={() => hide(150)}
      {...props}
    >
      <a
        ref={triggerRef}
        href={source?.url}
        target="_blank"
        rel="noreferrer"
        aria-describedby={open ? id : undefined}
        aria-label={`Source ${index}${source ? `: ${source.title}` : ""}`}
        onFocus={() => show(0)}
        onBlur={() => hide(0)}
        className={`mx-0.5 inline-flex h-[1.2em] min-w-[1.2em] -translate-y-[0.12em] items-center justify-center rounded-[5px] px-1 font-mono text-[10.5px] leading-none no-underline transition-colors ${FOCUS} ${
          unavailable
            ? "bg-muted text-muted-foreground/60 line-through"
            : open
              ? "bg-foreground text-background"
              : "bg-muted text-muted-foreground hover:bg-accent hover:text-foreground"
        }`}
      >
        {index}
      </a>

      {mounted && (
        <span
          ref={cardRef}
          id={id}
          role="tooltip"
          aria-hidden={!open || undefined}
          className={`absolute z-50 block rounded-xl border border-border bg-background p-3 text-left ${place.above ? "bottom-full mb-1.5" : "top-full mt-1.5"} ${
            open ? "" : "pointer-events-none"
          }`}
          // Shifted with left, not transform, so the entrance animation can't undo it.
          style={{ width: CARD_WIDTH, left: -place.shift }}
        >
          {unavailable ? (
            <span className="block text-[12.5px] text-muted-foreground">
              This source couldn’t be loaded.
            </span>
          ) : (
            <>
              <span className="flex items-center gap-1.5 text-[11.5px] text-muted-foreground">
                <span
                  aria-hidden="true"
                  className="flex size-3.5 shrink-0 items-center justify-center overflow-hidden rounded-full"
                >
                  {source.icon ?? <Globe className="size-3.5" />}
                </span>
                <span className="truncate">{hostname(source.url)}</span>
              </span>
              <span className="mt-1.5 line-clamp-2 block text-[13px] font-medium leading-snug text-foreground">
                {source.title}
              </span>
              {source.snippet && (
                <span className="mt-1 line-clamp-3 block text-[12px] leading-relaxed text-muted-foreground">
                  {source.snippet}
                </span>
              )}
            </>
          )}
        </span>
      )}
    </span>
  );
}

"use client";

import * as React from "react";
import { ArrowUp } from "lucide-react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * CLARIFYING QUESTION: the agent pauses to ask
 *
 *   asking    the question and its options; press 1–9 or click
 *   other     "Something else" turns into a field in place
 *   multiple  options toggle (their checks draw themselves), then
 *             "Continue · 3", the count rolling as you pick
 *   answered  the same card folds into one line: the options close,
 *             "Needs your answer" lifts away and the question and
 *             your answer slide into its place as a check draws
 *   skipped   "Skipped, the agent will decide"
 *
 * Pair it with a client-side tool that has no execute: render it
 * for the tool's input and send the answer back as the output.
 * ───────────────────────────────────────────────────────── */

export interface QuestionOption {
  id: string;
  label: string;
  description?: string;
}

export interface QuestionAnswer {
  ids: string[];
  labels: string[];
  /** What they typed under "Something else". */
  other?: string;
}

export interface ClarifyingQuestionProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onSubmit"
> {
  question: string;
  detail?: string;
  options: QuestionOption[];
  /** Allow several answers, confirmed with Continue. */
  multiple?: boolean;
  /** Offer "Something else" with a field. */
  allowOther?: boolean;
  otherLabel?: string;
  /** The answer once given, e.g. the tool's output; shows the folded line. */
  answer?: QuestionAnswer | null;
  onAnswer: (answer: QuestionAnswer) => void;
  /** Shows Skip; the agent continues with its own choice. */
  onSkip?: () => void;
  skipped?: boolean;
  skippedText?: string;
  autoFocus?: boolean;
}

const OTHER = "__other__";
const EASE = "cubic-bezier(0.23,1,0.32,1)";
const MORPH = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Icons trade places through a blur: the old one shrinks away as the new one grows in. */
const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 260ms ${MORPH}, transform 380ms ${MORPH}, filter 260ms ${MORPH}`,
});

/** A piece of a line that opens out of nothing and folds back into it. */
function Reveal({
  show,
  reduced,
  className = "",
  children,
}: {
  show: boolean;
  reduced: boolean;
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <span
      aria-hidden={!show || undefined}
      className={`grid ${className}`}
      style={{
        gridTemplateColumns: show ? "1fr" : "0fr",
        opacity: show ? 1 : 0,
        filter: show ? "none" : "blur(3px)",
        transition: reduced
          ? "none"
          : `grid-template-columns 460ms ${MORPH}, opacity ${show ? "320ms" : "160ms"} ${MORPH}, filter 320ms ${MORPH}`,
      }}
    >
      <span className="min-w-0 truncate [clip-path:inset(-4px_-2px)]">
        {children}
      </span>
    </span>
  );
}

function DrawnCheck({
  drawn,
  reduced,
  className = "size-3",
}: {
  drawn: boolean;
  reduced: boolean;
  className?: string;
}) {
  return (
    <svg viewBox="0 0 16 16" fill="none" className={className}>
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2.4"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 320ms ${MORPH} 60ms`
              : "none",
        }}
      />
    </svg>
  );
}

export function ClarifyingQuestion({
  question,
  detail,
  options,
  multiple = false,
  allowOther = true,
  otherLabel = "Something else",
  answer,
  onAnswer,
  onSkip,
  skipped = false,
  skippedText = "the agent will decide",
  autoFocus = false,
  className = "",
  ...props
}: ClarifyingQuestionProps) {
  const id = React.useId();
  const reduced = useReducedMotion();
  const [own, setOwn] = React.useState<QuestionAnswer | null>(null);
  const [ownSkipped, setOwnSkipped] = React.useState(false);
  const [picked, setPicked] = React.useState<string[]>([]);
  const [otherOpen, setOtherOpen] = React.useState(false);
  const [otherText, setOtherText] = React.useState("");
  const [active, setActive] = React.useState(0);
  const [highlight, setHighlight] = React.useState({
    top: 0,
    height: 0,
    ready: false,
  });

  const surfaceRef = React.useRef<HTMLDivElement>(null);
  const rowRefs = React.useRef<(HTMLButtonElement | HTMLDivElement | null)[]>(
    [],
  );
  const otherRef = React.useRef<HTMLInputElement>(null);

  const final = answer ?? own;
  const isSkipped = skipped || ownSkipped;
  const done = Boolean(final) || isSkipped;
  const rows = allowOther
    ? [...options, { id: OTHER, label: otherLabel }]
    : options;

  // The options are about to fold away: keep focus on the card instead of dropping it on the page.
  const fold = () => {
    if (surfaceRef.current?.contains(document.activeElement))
      surfaceRef.current.focus({ preventScroll: true });
  };

  React.useEffect(() => {
    if (autoFocus && !done)
      (rowRefs.current[0] as HTMLElement | null)?.focus({
        preventScroll: true,
      });
    // Autofocus applies only when this question mounts.
  }, []);

  React.useEffect(() => {
    if (otherOpen) otherRef.current?.focus({ preventScroll: true });
  }, [otherOpen]);

  // Digits also answer when nothing else has focus (never while typing in a field).
  const chooseRef = React.useRef<(i: number) => void>(() => {});
  React.useEffect(() => {
    if (done) return;
    const onKey = (e: KeyboardEvent) => {
      const focused = document.activeElement;
      if (
        (focused && focused !== document.body) ||
        e.metaKey ||
        e.ctrlKey ||
        e.altKey ||
        !/^[1-9]$/.test(e.key)
      )
        return;
      if (Number(e.key) > rows.length) return;
      e.preventDefault();
      chooseRef.current(Number(e.key) - 1);
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [done, rows.length]);

  // The highlight slides to the active row and takes its height.
  React.useLayoutEffect(() => {
    const row = rowRefs.current[active];
    if (!row || done) return;
    const measure = () => {
      const top = row.offsetTop;
      const height = row.offsetHeight;
      setHighlight((h) =>
        h.top === top && h.height === height && h.ready
          ? h
          : { top, height, ready: h.height > 0 },
      );
    };
    measure();
    // Descriptions can wrap after a resize or font load without changing selection.
    const observer = new ResizeObserver(measure);
    observer.observe(row);
    if (row.parentElement) observer.observe(row.parentElement);
    return () => observer.disconnect();
  }, [active, otherOpen, done, rows.length]);

  const submit = (picks: string[], other?: string) => {
    const order = (x: string) => options.findIndex((o) => o.id === x);
    const ids = [...picks].sort((a, b) => order(a) - order(b));
    const next: QuestionAnswer = {
      ids,
      labels: ids.map((i) => options.find((o) => o.id === i)?.label ?? i),
      ...(other ? { other } : {}),
    };
    fold();
    if (answer === undefined) setOwn(next);
    onAnswer(next);
  };

  const skip = () => {
    fold();
    setOwnSkipped(true);
    onSkip?.();
  };

  const choose = (i: number) => {
    const row = rows[i];
    if (!row) return;
    setActive(i);
    if (row.id === OTHER) {
      setOtherOpen((o) => (multiple ? !o : true));
      return;
    }
    if (multiple)
      setPicked((p) =>
        p.includes(row.id) ? p.filter((x) => x !== row.id) : [...p, row.id],
      );
    else submit([row.id]);
  };

  React.useLayoutEffect(() => {
    chooseRef.current = choose;
  });

  const submitOther = () => {
    const text = otherText.trim();
    if (!text) return;
    if (multiple) submit(picked, text);
    else submit([], text);
  };

  const onListKey = (e: React.KeyboardEvent) => {
    if (e.target instanceof HTMLInputElement) return;
    if (/^[1-9]$/.test(e.key) && Number(e.key) <= rows.length) {
      e.preventDefault();
      const next = Number(e.key) - 1;
      choose(next);
      // A single answer has already focused the receipt; don't refocus a closing row.
      if (multiple || rows[next].id === OTHER)
        (rowRefs.current[next] as HTMLElement | null)?.focus();
    } else if (e.key === "ArrowDown" || e.key === "ArrowUp") {
      e.preventDefault();
      const next =
        (active + (e.key === "ArrowDown" ? 1 : -1) + rows.length) % rows.length;
      setActive(next);
      (rowRefs.current[next] as HTMLElement | null)?.focus();
    }
  };

  const summary = final
    ? [...final.labels, final.other].filter(Boolean).join(", ")
    : "";
  const receipt = isSkipped && !final ? `Skipped, ${skippedText}` : summary;
  const count = picked.length + (otherOpen && otherText.trim() ? 1 : 0);
  const canContinue = count > 0;

  return (
    <div
      ref={surfaceRef}
      tabIndex={-1}
      className={`overflow-hidden rounded-[14px] border border-border bg-background outline-none ${className}`}
      {...props}
    >
      {/* The header stays put; once answered it becomes the whole card: question · answer. */}
      <div
        className="flex min-w-0 items-center text-[12px]"
        style={{
          padding: done ? "13px 16px" : "14px 16px 0",
          transition: reduced ? "none" : `padding 460ms ${MORPH}`,
        }}
      >
        <span
          aria-hidden="true"
          className="relative mr-2 flex size-4 shrink-0 items-center justify-center"
        >
          <span
            className="absolute inset-0 flex items-center justify-center"
            style={swap(!done, reduced)}
          >
            <span className="relative flex size-1.5">
              <span
                className={`absolute inset-0 rounded-full bg-primary motion-reduce:animate-none ${done ? "" : "animate-[ui-ping_1.6s_cubic-bezier(0,0,0.2,1)_infinite]"}`}
              />
              <span className="relative size-1.5 rounded-full bg-primary" />
            </span>
          </span>
          <span
            className="absolute inset-0 flex items-center justify-center rounded-full bg-muted text-muted-foreground"
            style={swap(done, reduced)}
          >
            <DrawnCheck drawn={done} reduced={reduced} className="size-2.5" />
          </span>
        </span>
        <span
          aria-hidden={done || undefined}
          className="shrink-0 text-muted-foreground"
        >
          <TextMorph>{done ? "" : "Needs your answer"}</TextMorph>
        </span>
        <Reveal show={done} reduced={reduced} className="min-w-0">
          <span title={question} className="text-muted-foreground">
            {question}
          </span>
        </Reveal>
        <Reveal show={done} reduced={reduced} className="max-w-[55%] shrink-0">
          <span aria-hidden="true" className="px-2 text-muted-foreground/50">
            ·
          </span>
          <span title={receipt} className="font-medium text-foreground">
            {receipt}
          </span>
        </Reveal>
      </div>
      <span role="status" className="sr-only">
        {done ? `${question}: ${receipt}` : ""}
      </span>

      {/* Everything else folds shut once it's answered. */}
      <div
        inert={done}
        aria-hidden={done || undefined}
        className="grid"
        style={{
          gridTemplateRows: done ? "0fr" : "1fr",
          opacity: done ? 0 : 1,
          transition: reduced
            ? "none"
            : `grid-template-rows 460ms ${MORPH}, opacity ${done ? "180ms" : "320ms"} ${MORPH}`,
        }}
      >
        <div className="min-h-0 overflow-hidden">
          <div className="p-1.5 pt-0">
            <div className="px-2.5 pb-2.5">
              <p
                id={`${id}-q`}
                className="mt-1.5 text-[14px] font-medium leading-snug text-foreground"
              >
                {question}
              </p>
              {detail && (
                <p className="mt-0.5 text-[12.5px] leading-relaxed text-muted-foreground">
                  {detail}
                </p>
              )}
            </div>

            <div
              role={multiple ? "group" : "radiogroup"}
              aria-labelledby={`${id}-q`}
              onKeyDown={onListKey}
              className="relative"
            >
              <span
                aria-hidden="true"
                className="absolute inset-x-0 top-0 rounded-[14px] bg-accent"
                style={{
                  height: highlight.height,
                  transform: `translateY(${highlight.top}px)`,
                  transition:
                    highlight.ready && !reduced
                      ? `transform 200ms ${EASE}, height 200ms ${EASE}`
                      : "none",
                }}
              />
              {rows.map((row, i) => {
                const isOther = row.id === OTHER;
                const checked = isOther ? otherOpen : picked.includes(row.id);
                const description =
                  "description" in row ? row.description : undefined;
                const marker = multiple ? (
                  <span
                    aria-hidden="true"
                    className={`flex size-[18px] shrink-0 items-center justify-center rounded-[6px] transition-[background-color,box-shadow] duration-200 ${
                      checked
                        ? "bg-primary text-primary-foreground"
                        : "shadow-[inset_0_0_0_1.5px_var(--border)]"
                    }`}
                  >
                    <DrawnCheck drawn={checked} reduced={reduced} />
                  </span>
                ) : (
                  <kbd
                    aria-hidden="true"
                    className={`flex size-[18px] shrink-0 items-center justify-center rounded-[6px] font-mono text-[10.5px] transition-colors ${
                      i === active
                        ? "bg-background text-foreground shadow-[0_0_0_1px_var(--border)]"
                        : "text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)]"
                    }`}
                  >
                    {i + 1}
                  </kbd>
                );

                if (isOther && otherOpen) {
                  return (
                    <div
                      key={row.id}
                      ref={(el) => {
                        rowRefs.current[i] = el;
                      }}
                      className="relative flex min-h-11 items-center gap-3 rounded-[14px] px-2.5"
                    >
                      {marker}
                      <input
                        ref={otherRef}
                        value={otherText}
                        onChange={(e) => setOtherText(e.target.value)}
                        onFocus={() => setActive(i)}
                        onKeyDown={(e) => {
                          if (e.nativeEvent.isComposing) return;
                          if (e.key === "Enter") {
                            e.preventDefault();
                            submitOther();
                          } else if (e.key === "Escape") {
                            e.preventDefault();
                            setOtherOpen(false);
                            requestAnimationFrame(() =>
                              (
                                rowRefs.current[i] as HTMLElement | null
                              )?.focus(),
                            );
                          }
                        }}
                        placeholder="Type your answer"
                        aria-label={otherLabel}
                        className="h-8 min-w-0 flex-1 bg-transparent text-[13.5px] text-foreground outline-none placeholder:text-muted-foreground animate-[ui-fade-in_200ms_ease-out_both] motion-reduce:animate-none"
                      />
                      {!multiple && (
                        <button
                          type="button"
                          aria-label="Send answer"
                          disabled={!otherText.trim()}
                          onClick={submitOther}
                          className={`cursor-pointer disabled:cursor-default flex size-7 shrink-0 items-center justify-center rounded-full bg-primary text-primary-foreground transition-[opacity,transform] active:scale-[0.94] disabled:opacity-30 ${FOCUS}`}
                        >
                          <ArrowUp className="size-3.5" strokeWidth={2.4} />
                        </button>
                      )}
                    </div>
                  );
                }

                return (
                  <button
                    key={row.id}
                    ref={(el) => {
                      rowRefs.current[i] = el;
                    }}
                    type="button"
                    role={multiple ? "checkbox" : "radio"}
                    aria-checked={multiple ? checked : false}
                    tabIndex={i === active ? 0 : -1}
                    onClick={() => choose(i)}
                    onPointerMove={() => i !== active && setActive(i)}
                    onFocus={() => setActive(i)}
                    className="cursor-pointer relative flex min-h-11 w-full items-center gap-3 rounded-[14px] px-2.5 py-2 text-left outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/30"
                  >
                    {marker}
                    <span className="min-w-0 flex-1">
                      <span
                        className={`block text-[13.5px] ${isOther ? "text-muted-foreground" : "text-foreground"}`}
                      >
                        {isOther ? `${row.label}…` : row.label}
                      </span>
                      {description && (
                        <span className="mt-px block text-[12px] leading-snug text-muted-foreground">
                          {description}
                        </span>
                      )}
                    </span>
                  </button>
                );
              })}
            </div>

            {(onSkip || multiple) && (
              <div className="flex items-center justify-between gap-2 px-1 pb-0.5 pt-1.5">
                {onSkip ? (
                  <button
                    type="button"
                    onClick={skip}
                    className={`cursor-pointer h-8 rounded-full px-2.5 text-[12.5px] text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
                  >
                    Skip
                  </button>
                ) : (
                  <span />
                )}
                {multiple && (
                  <button
                    type="button"
                    disabled={!canContinue}
                    onClick={() =>
                      submit(
                        picked,
                        otherOpen && otherText.trim()
                          ? otherText.trim()
                          : undefined,
                      )
                    }
                    className={`cursor-pointer disabled:cursor-default inline-flex h-8 items-center rounded-full bg-primary px-3.5 text-[12.5px] font-medium text-primary-foreground transition-[opacity,transform] duration-300 active:scale-[0.96] disabled:opacity-35 ${FOCUS}`}
                  >
                    Continue
                    {/* " · 3" opens beside it with the first pick and rolls as you pick more. */}
                    <span
                      aria-hidden="true"
                      className="grid"
                      style={{
                        gridTemplateColumns: count > 0 ? "1fr" : "0fr",
                        opacity: count > 0 ? 1 : 0,
                        transition: reduced
                          ? "none"
                          : `grid-template-columns 380ms ${MORPH}, opacity 260ms ${MORPH}`,
                      }}
                    >
                      <span className="flex min-w-0 items-baseline overflow-hidden whitespace-nowrap tabular-nums">
                        &nbsp;·&nbsp;
                        <NumberRoll value={Math.max(count, 1)} duration={500} />
                      </span>
                    </span>
                    {count > 0 && (
                      <span className="sr-only">, {count} selected</span>
                    )}
                  </button>
                )}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { ChevronDown, Copy, CornerDownLeft, WrapText } from "lucide-react";
import { StatusButton, type ActionStatus } from "./status-button";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * CODE BLOCK: code in an answer, as it streams and after
 *
 *   streaming  lines arrive with a caret, already highlighted
 *   complete   language and file name, Copy and wrap; wrapping
 *              eases the block to its new height
 *   copied     the copy icon blurs into a check that draws
 *              itself while "Copy" morphs to "Copied"
 *   folded     long code shows its start and "Show 42 more
 *              lines"; it opens smoothly, the fade dissolves and
 *              the label morphs to "Show less"
 *   apply      optional: Apply → Applying → Applied, one button
 *              that settles into a quiet receipt
 *
 * A light highlighter is built in (keywords, strings, comments,
 * numbers, calls) so it works mid-stream with no dependencies.
 * ───────────────────────────────────────────────────────── */

export interface CodeBlockProps extends React.HTMLAttributes<HTMLDivElement> {
  code: string;
  /** e.g. "ts", "python", "bash"; shown in the header and used for comments. */
  language?: string;
  filename?: string;
  /** True while the code is still arriving. */
  streaming?: boolean;
  lineNumbers?: boolean;
  /** Fold code longer than this many lines (0 never folds). */
  collapseAfter?: number;
  /** Shows Apply; return a promise to show progress. */
  onApply?: () => void | Promise<void>;
  applyLabel?: string;
  /** Turn the built-in highlighting off, e.g. for plain output. */
  highlight?: boolean;
}

const LINE = 21;
const PAD = 12;
const EASE = "cubic-bezier(0.23,1,0.32,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const COPY_LABELS = { idle: "Copy", success: "Copied", error: "Couldn’t copy" };
const ACTION = `cursor-pointer inline-flex h-7 items-center gap-1.5 rounded-full px-2.5 text-[12px] font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground disabled:pointer-events-none disabled:opacity-40 [&_svg]:size-3.5 ${FOCUS}`;

// A GitHub-like palette for light and dark themes.
const TONE = {
  keyword: "text-[#cf222e] dark:text-[#ff7b72]",
  string: "text-[#0a3069] dark:text-[#a5d6ff]",
  comment: "italic text-[#6e7781] dark:text-[#8b949e]",
  number: "text-[#0550ae] dark:text-[#79c0ff]",
  call: "text-[#8250df] dark:text-[#d2a8ff]",
};

const KEYWORDS =
  "const|let|var|function|return|if|else|for|while|do|switch|case|break|continue|import|from|export|default|async|await|new|class|extends|implements|type|interface|enum|true|false|null|undefined|this|try|catch|finally|throw|yield|in|of|typeof|instanceof|as|def|elif|lambda|None|True|False|pass|with|raise|except|and|or|not|is|self|fn|pub|use|mut|impl|struct|match|func|package|go|echo|then|fi|done|esac|local|public|private|protected|static|void|int|string|bool|select|where|insert|update|delete|create|table";
const HASH_COMMENTS =
  /^(py|python|sh|bash|shell|zsh|yaml|yml|rb|ruby|toml|dockerfile|r|perl)$/i;

function tokenize(line: string, hashComments: boolean): React.ReactNode[] {
  const comment = hashComments
    ? String.raw`#.*$|\/\/.*$`
    : String.raw`\/\/.*$|\/\*.*?\*\/|<!--.*?-->`;
  const re = new RegExp(
    String.raw`(${comment})|("(?:[^"\\]|\\.)*"?|'(?:[^'\\]|\\.)*'?|` +
      "`(?:[^`\\\\]|\\\\.)*`?" +
      String.raw`)|(\b\d[\d_]*(?:\.\d+)?\b)|\b(${KEYWORDS})\b|([A-Za-z_$][\w$]*)(?=\()`,
    "g",
  );
  const out: React.ReactNode[] = [];
  let last = 0;
  let m: RegExpExecArray | null;
  while ((m = re.exec(line))) {
    if (m.index > last) out.push(line.slice(last, m.index));
    const tone = m[1]
      ? TONE.comment
      : m[2]
        ? TONE.string
        : m[3]
          ? TONE.number
          : m[4]
            ? TONE.keyword
            : TONE.call;
    out.push(
      <span key={m.index} className={tone}>
        {m[0]}
      </span>,
    );
    last = m.index + m[0].length;
    if (m[0].length === 0) re.lastIndex++;
  }
  if (last < line.length) out.push(line.slice(last));
  return out;
}

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

export function CodeBlock({
  code,
  language,
  filename,
  streaming = false,
  lineNumbers = true,
  collapseAfter = 18,
  onApply,
  applyLabel = "Apply",
  highlight = true,
  className = "",
  ...props
}: CodeBlockProps) {
  const reduced = useReducedMotion();
  const [copy, setCopy] = React.useState<ActionStatus>("idle");
  const [wrap, setWrap] = React.useState(false);
  // Code you watched stream in stays open; only code that arrives complete (e.g. history) starts folded.
  const [expanded, setExpanded] = React.useState(streaming);
  const [apply, setApply] = React.useState<ActionStatus>("idle");
  // New code (a regenerated answer) can be applied again: "Applied" or "Try again" goes back to Apply.
  const [appliedCode, setAppliedCode] = React.useState(code);
  if (appliedCode !== code) {
    setAppliedCode(code);
    if (apply === "success" || apply === "error") setApply("idle");
  }
  const [fullHeight, setFullHeight] = React.useState(0);
  const bodyRef = React.useRef<HTMLDivElement>(null);
  const wrapFrom = React.useRef<number | null>(null);

  const lines = React.useMemo(
    () => code.replace(/\n$/, "").split("\n"),
    [code],
  );
  const hash = HASH_COMMENTS.test(language ?? "");
  const rendered = React.useMemo(
    () => lines.map((line) => (highlight ? tokenize(line, hash) : [line])),
    [lines, highlight, hash],
  );

  const foldable =
    !streaming && collapseAfter > 0 && lines.length > collapseAfter + 3;
  const folded = foldable && !expanded;
  const hidden = lines.length - collapseAfter;

  React.useLayoutEffect(() => {
    const body = bodyRef.current;
    if (!body) return;
    const measure = () =>
      setFullHeight((h) => (h === body.scrollHeight ? h : body.scrollHeight));
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(body.firstElementChild as Element);
    return () => observer.disconnect();
  }, [wrap]);

  // Wrapping changes how tall the code is: ease the block there instead of jumping. (Folded code has its own transition.)
  React.useLayoutEffect(() => {
    const body = bodyRef.current;
    const from = wrapFrom.current;
    wrapFrom.current = null;
    if (!body || from === null || reduced || foldable) return;
    const to = body.offsetHeight;
    if (Math.abs(to - from) > 1)
      body.animate([{ height: `${from}px` }, { height: `${to}px` }], {
        duration: 460,
        easing: EASE,
      });
  }, [wrap, reduced]);

  // A blocked clipboard says so, then quietly goes back to Copy.
  React.useEffect(() => {
    if (copy !== "error") return;
    const timer = window.setTimeout(() => setCopy("idle"), 2400);
    return () => window.clearTimeout(timer);
  }, [copy]);

  const copyCode = async () => {
    try {
      await navigator.clipboard.writeText(code);
      setCopy("success");
    } catch {
      setCopy("error");
    }
  };

  const runApply = async () => {
    if (!onApply || apply === "pending" || apply === "success") return;
    setApply("pending");
    try {
      await onApply();
      setApply("success");
    } catch {
      setApply("error");
    }
  };

  const gutter = String(lines.length).length;

  return (
    <div
      className={`w-full overflow-hidden rounded-[16px] border border-border bg-background ${className}`}
      {...props}
    >
      <div className="flex h-10 items-center gap-2 border-b border-border/70 pl-3.5 pr-1.5">
        <span className="min-w-0 flex-1 truncate font-mono text-[11.5px] text-muted-foreground">
          {filename ? (
            <>
              <span className="text-foreground/80">{filename}</span>
              {language && <span className="ml-2 opacity-70">{language}</span>}
            </>
          ) : (
            (language ?? "code")
          )}
        </span>
        <button
          type="button"
          aria-label="Wrap lines"
          aria-pressed={wrap}
          onClick={() => {
            wrapFrom.current = bodyRef.current?.offsetHeight ?? null;
            setWrap((w) => !w);
          }}
          className={`cursor-pointer ${ACTION} ${wrap ? "bg-accent text-foreground" : ""} w-7 justify-center px-0`}
        >
          <WrapText />
        </button>
        <StatusButton
          variant="ghost"
          size="sm"
          icon={<Copy />}
          status={copy}
          labels={COPY_LABELS}
          aria-label="Copy code"
          onClick={copyCode}
          onReset={() => setCopy("idle")}
          resetAfter={1600}
        />
        {onApply && (
          // Waits, faded, until the code has finished arriving.
          <span
            className="inline-flex transition-opacity duration-300"
            style={{ opacity: streaming ? 0.4 : 1 }}
          >
            <StatusButton
              size="sm"
              // Once applied it settles from a call to action into a quiet receipt.
              variant={apply === "success" ? "ghost" : "primary"}
              icon={<CornerDownLeft />}
              status={apply}
              labels={{
                idle: applyLabel,
                pending: "Applying",
                success: "Applied",
                error: "Try again",
              }}
              disabled={streaming}
              onClick={runApply}
              className="disabled:pointer-events-none"
            />
          </span>
        )}
      </div>

      <div className="relative">
        <div
          ref={bodyRef}
          className="overflow-hidden"
          style={{
            // Only foldable code gets a height cap (animated between its start and its full height).
            maxHeight: foldable
              ? folded
                ? PAD + collapseAfter * LINE
                : fullHeight || undefined
              : undefined,
            transition: reduced ? "none" : `max-height 460ms ${EASE}`,
          }}
        >
          <pre
            className={`py-3 font-mono text-[12.5px] leading-[21px] text-foreground/90 [scrollbar-color:var(--border)_transparent] [scrollbar-width:thin] ${wrap ? "whitespace-pre-wrap break-words" : "overflow-x-auto"}`}
            tabIndex={wrap ? undefined : 0}
            aria-label={`${language ?? "Code"}${filename ? `, ${filename}` : ""}`}
          >
            <code className="block min-w-fit">
              {rendered.map((tokens, i) => (
                <span key={i} className="flex">
                  {lineNumbers && (
                    <span
                      aria-hidden="true"
                      className="sticky left-0 shrink-0 select-none bg-background pl-3.5 pr-4 text-right tabular-nums text-muted-foreground/50"
                      style={{ width: `calc(${gutter}ch + 2.25rem)` }}
                    >
                      {i + 1}
                    </span>
                  )}
                  <span
                    className={`min-w-0 ${lineNumbers ? "pr-4" : "px-4"} ${wrap ? "whitespace-pre-wrap break-words" : "whitespace-pre"}`}
                  >
                    {tokens.length ? tokens : " "}
                    {streaming && i === rendered.length - 1 && (
                      <span
                        aria-hidden="true"
                        className="ml-px inline-block h-[15px] w-[7px] translate-y-[3px] bg-foreground/60 animate-[ui-blink_1s_steps(1)_infinite]"
                      />
                    )}
                  </span>
                </span>
              ))}
            </code>
          </pre>
        </div>

        {/* The fade over folded code dissolves as it opens; the bar under it never moves. */}
        {foldable && (
          <div
            aria-hidden="true"
            className="pointer-events-none absolute inset-x-0 bottom-0 h-16 bg-gradient-to-t from-background to-transparent"
            style={{
              opacity: folded ? 1 : 0,
              transition: reduced ? "none" : `opacity 360ms ${EASE}`,
            }}
          />
        )}
      </div>

      {foldable && (
        <div className="flex justify-center border-t border-border/60 py-1.5">
          <button
            type="button"
            onClick={() => setExpanded((e) => !e)}
            aria-expanded={expanded}
            className={ACTION}
          >
            <ChevronDown
              className="transition-transform duration-300 motion-reduce:transition-none"
              style={{
                transform: expanded ? "rotate(180deg)" : "none",
                transitionTimingFunction: EASE,
              }}
            />
            <TextMorph>
              {expanded
                ? "Show less"
                : `Show ${hidden} more line${hidden === 1 ? "" : "s"}`}
            </TextMorph>
          </button>
        </div>
      )}
    </div>
  );
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { StatusButton, type ActionStatus } from "./status-button";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * CODE INPUT: the six boxes, done properly
 *
 *   typing     each digit rises into its box out of a blur; the
 *              box you're on carries a blinking caret; deleting
 *              lifts a digit away rather than blinking it out
 *   paste      a pasted or autofilled code drops in one box after
 *              another
 *   checking   with every box full, the row carries a sweep of
 *              light while onComplete runs
 *   wrong      the row shakes, the boxes turn red, the label
 *              says so, and the digits clear from the right
 *   right      the digits stay where they are while the boxes'
 *              own outlines melt into one pill around them; a
 *              check draws itself at its end, "Verified"
 *   resend     "Resend in 0:28", the seconds rolling down, then
 *              a Resend button that spins, ticks and starts the
 *              clock again
 *
 * One real input sits over the boxes (one-time-code autofill,
 * paste and the numeric keyboard all just work); the boxes are
 * only what you see.
 * ───────────────────────────────────────────────────────── */

export interface CodeInputProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onChange" | "defaultValue"
> {
  length?: number;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Runs when every box is filled. Resolve (or return true) to accept; throw or return false to reject. */
  onComplete?: (code: string) => Promise<boolean | void> | boolean | void;
  /** Shows the resend line; the clock starts on mount and after each resend. */
  onResend?: () => Promise<unknown> | void;
  /** Seconds before a code can be resent. */
  resendAfter?: number;
  label?: string;
  /** Box groups, e.g. [3, 3] puts a dash between two threes. */
  groups?: number[];
  /** Letters as well as digits. */
  alphanumeric?: boolean;
  autoFocus?: boolean;
}

type Phase = "idle" | "checking" | "wrong" | "right";

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SHEEN =
  "[mask-image:linear-gradient(90deg,rgb(0_0_0/0.4)_35%,#000_50%,rgb(0_0_0/0.4)_65%)] [mask-size:200%_100%] animate-[ui-sheen_1.4s_linear_infinite] motion-reduce:animate-none motion-reduce:[mask-image:none]";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** One character: rises in out of a blur when it arrives, lifts away when it goes. */
function Glyph({
  char,
  delay,
  reduced,
}: {
  char: string | undefined;
  delay: number;
  reduced: boolean;
}) {
  const [shown, setShown] = React.useState(char);
  const [leaving, setLeaving] = React.useState(false);
  const ref = React.useRef<HTMLSpanElement>(null);
  // The character last drawn rising in: the one there on mount never rises, a new one always does.
  const risen = React.useRef(char);
  if (char !== undefined && (char !== shown || leaving)) {
    setShown(char);
    setLeaving(false);
  } else if (
    char === undefined &&
    shown !== undefined &&
    (!leaving || reduced)
  ) {
    // With reduced motion a character just goes; otherwise it lifts away first.
    if (reduced) {
      setShown(undefined);
      setLeaving(false);
    } else setLeaving(true);
  }

  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el || reduced) return;
    if (leaving) {
      const a = el.animate(
        [
          { opacity: 1, transform: "none", filter: "blur(0px)" },
          { opacity: 0, transform: "translateY(-35%)", filter: "blur(4px)" },
        ],
        { duration: 200, delay, easing: EASE, fill: "forwards" },
      );
      a.onfinish = () => setShown(undefined);
      return () => a.cancel();
    }
    if (shown === undefined) {
      risen.current = undefined;
      return;
    }
    if (risen.current === shown) return;
    risen.current = shown;
    const a = el.animate(
      [
        { opacity: 0, transform: "translateY(45%)", filter: "blur(4px)" },
        { opacity: 1, transform: "none", filter: "blur(0px)" },
      ],
      { duration: 300, delay, easing: EASE, fill: "backwards" },
    );
    return () => a.cancel();
  }, [shown, leaving]);

  if (shown === undefined) return null;
  return (
    <span ref={ref} className="inline-block">
      {shown}
    </span>
  );
}

export function CodeInput({
  length = 6,
  value,
  defaultValue = "",
  onValueChange,
  onComplete,
  onResend,
  resendAfter = 30,
  label = `Enter the ${length}-digit code`,
  groups,
  alphanumeric = false,
  autoFocus,
  className = "",
  ...props
}: CodeInputProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const [own, setOwn] = React.useState(defaultValue.slice(0, length));
  const code = (value ?? own).slice(0, length);
  const [phase, setPhase] = React.useState<Phase>("idle");
  const [focused, setFocused] = React.useState(false);
  const [arrival, setArrival] = React.useState({
    length: code.length,
    from: code.length,
  });
  const [clearing, setClearing] = React.useState(false);
  // Resend clock: whole seconds, running from the start when there's a resend, and again after each one.
  const [left, setLeft] = React.useState<number | null>(
    onResend ? resendAfter : null,
  );
  const [resend, setResend] = React.useState<ActionStatus>("idle");
  const inputRef = React.useRef<HTMLInputElement>(null);
  const rowRef = React.useRef<HTMLDivElement>(null);

  // How the new characters arrived: one typed, or several at once (paste, autofill) to cascade in.
  if (arrival.length !== code.length)
    setArrival({ length: code.length, from: arrival.length });
  const arrivedFrom = arrival.from;

  const setCode = (next: string) => {
    if (value === undefined) setOwn(next);
    onValueChange?.(next);
  };

  const startClock = React.useCallback(
    () => setLeft(resendAfter),
    [resendAfter],
  );
  React.useEffect(() => {
    if (left === null || left <= 0) return;
    const timer = window.setTimeout(
      () => setLeft((s) => (s === null ? s : s - 1)),
      1000,
    );
    return () => window.clearTimeout(timer);
  }, [left]);

  const check = async (full: string) => {
    if (!onComplete) return;
    setPhase("checking");
    let ok = true;
    try {
      ok = (await onComplete(full)) !== false;
    } catch {
      ok = false;
    }
    if (ok) {
      setPhase("right");
      inputRef.current?.blur();
      return;
    }
    setPhase("wrong");
    if (!reduced) {
      rowRef.current?.animate(
        [
          { transform: "none" },
          { transform: "translateX(-5px)" },
          { transform: "translateX(5px)" },
          { transform: "translateX(-3px)" },
          { transform: "none" },
        ],
        { duration: 380, easing: "ease-out" },
      );
    }
    // Let the shake land, then clear from the right and start again at the first box.
    window.setTimeout(
      () => {
        setClearing(true);
        setCode("");
        inputRef.current?.focus();
        window.setTimeout(() => setClearing(false), 400);
      },
      reduced ? 0 : 650,
    );
  };

  const onChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (phase === "checking" || phase === "right") return;
    const raw = e.target.value;
    const clean = (
      alphanumeric
        ? raw.replace(/[^a-z0-9]/gi, "").toUpperCase()
        : raw.replace(/\D/g, "")
    ).slice(0, length);
    if (phase === "wrong") setPhase("idle");
    setCode(clean);
  };

  // A full code, however it arrived (typed, pasted, autofilled or set from outside), gets checked once.
  const lastLength = React.useRef(code.length);
  React.useEffect(() => {
    if (
      code.length === length &&
      lastLength.current < length &&
      (phase === "idle" || phase === "wrong")
    )
      check(code);
    lastLength.current = code.length;
  }, [code]);

  const doResend = async () => {
    if (!onResend || resend === "pending") return;
    setResend("pending");
    try {
      await onResend();
      setResend("success");
      window.setTimeout(
        () => {
          setResend("idle");
          startClock();
        },
        reduced ? 0 : 1100,
      );
    } catch {
      setResend("error");
    }
  };

  // Where the dashes go between groups.
  const breaks = new Set<number>();
  if (groups)
    groups.reduce((at, size) => (breaks.add(at + size), at + size), 0);
  const right = phase === "right";
  const wrong = phase === "wrong";
  const active =
    focused && phase !== "checking" && !right
      ? Math.min(code.length, length - 1)
      : -1;
  const labelText = right
    ? "Verified"
    : wrong
      ? "That code didn't work"
      : phase === "checking"
        ? "Checking the code"
        : label;

  return (
    <div className={`@container w-full ${className}`} {...props}>
      <label
        htmlFor={id}
        className={`block text-[12.5px] transition-colors duration-300 ${wrong ? "text-red-600 dark:text-red-400" : "text-muted-foreground"}`}
      >
        <TextMorph>{labelText}</TextMorph>
      </label>

      <div className="relative mt-2 w-fit">
        <input
          ref={inputRef}
          id={id}
          value={code}
          onChange={onChange}
          onFocus={(e) => {
            setFocused(true);
            const end = e.currentTarget.value.length;
            e.currentTarget.setSelectionRange(end, end);
          }}
          onBlur={() => setFocused(false)}
          onSelect={(e) => {
            // The caret always sits at the end; the boxes show where you are.
            const el = e.currentTarget;
            if (el.selectionStart !== el.value.length)
              el.setSelectionRange(el.value.length, el.value.length);
          }}
          readOnly={phase === "checking" || right}
          autoFocus={autoFocus}
          autoComplete="one-time-code"
          inputMode={alphanumeric ? "text" : "numeric"}
          pattern={alphanumeric ? "[A-Za-z0-9]*" : "[0-9]*"}
          maxLength={length}
          spellCheck={false}
          aria-invalid={wrong || undefined}
          className="absolute inset-0 z-10 h-full w-full cursor-text bg-transparent text-[16px] text-transparent caret-transparent opacity-0 outline-none [&::selection]:bg-transparent"
        />

        {/* The boxes, and the one pill they become when the code is right. */}
        <div
          ref={rowRef}
          aria-hidden="true"
          className={`relative flex items-center gap-[var(--code-gap,8px)] rounded-[12px] @max-[19rem]:gap-[var(--code-gap,4px)] transition-[box-shadow,background-color] duration-500 ${phase === "checking" ? SHEEN : ""}`}
          style={{
            boxShadow: right
              ? "0 0 0 1px color-mix(in oklab, #10b981 55%, transparent)"
              : "0 0 0 1px transparent",
            background: right
              ? "color-mix(in oklab, #10b981 6%, var(--background))"
              : "transparent",
            transitionTimingFunction: EASE,
          }}
        >
          {Array.from({ length }, (_, i) => {
            const char = code[i];
            const isActive = i === active;
            const cascade =
              !clearing && code.length - arrivedFrom > 1 && i >= arrivedFrom
                ? (i - arrivedFrom) * 45
                : 0;
            const exitDelay = clearing ? (length - 1 - i) * 30 : 0;
            return (
              <React.Fragment key={i}>
                {/* The dash fades but keeps its place, so no digit moves when the code is right. */}
                {breaks.has(i) && i > 0 && (
                  <span
                    className="mx-0.5 block h-px w-2 bg-muted-foreground/40 transition-opacity duration-300"
                    style={{ opacity: right ? 0 : 1 }}
                  />
                )}
                <span
                  className="relative flex h-10 w-[34px] shrink-0 items-center justify-center text-[18px] font-medium tabular-nums text-foreground transition-[box-shadow,background-color] duration-300 @max-[19rem]:w-[30px] @min-[22rem]:h-11 @min-[22rem]:w-9 @min-[22rem]:text-[19px]"
                  style={{
                    borderRadius: 10,
                    boxShadow: right
                      ? "inset 0 0 0 1px transparent"
                      : wrong
                        ? "inset 0 0 0 1px color-mix(in oklab, #ef4444 60%, transparent)"
                        : isActive
                          ? "inset 0 0 0 1.5px color-mix(in oklab, var(--ring) 70%, transparent)"
                          : "inset 0 0 0 1px var(--border)",
                    background: right ? "transparent" : "var(--background)",
                  }}
                >
                  <Glyph
                    char={char}
                    delay={char !== undefined ? cascade : exitDelay}
                    reduced={reduced}
                  />
                  {/* The caret, blinking only in the box you're on. */}
                  {isActive && char === undefined && (
                    <span className="absolute h-5 w-px bg-foreground animate-[ui-blink_1s_steps(1)_infinite] motion-reduce:animate-none" />
                  )}
                </span>
              </React.Fragment>
            );
          })}

          {/* The check at the end of the pill: the pill grows to the right for it, the digits stay put. */}
          <span
            className="grid transition-[grid-template-columns,opacity] duration-500"
            style={{
              gridTemplateColumns: right ? "1fr" : "0fr",
              opacity: right ? 1 : 0,
              transitionTimingFunction: EASE,
            }}
          >
            <span className="flex min-w-0 items-center overflow-hidden">
              <svg
                viewBox="0 0 16 16"
                className="ml-1 mr-3 size-4 shrink-0 text-emerald-600"
                fill="none"
              >
                <path
                  d="M3.5 8.5 6.5 11.5 12.5 4.5"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  pathLength={1}
                  strokeDasharray={1}
                  style={{
                    strokeDashoffset: right ? 0 : 1,
                    transition: reduced
                      ? "none"
                      : `stroke-dashoffset 420ms ${EASE} 260ms`,
                  }}
                />
              </svg>
            </span>
          </span>
        </div>
      </div>

      {onResend && !right && (
        <div className="mt-3 flex h-7 items-center gap-1.5 text-[12px] text-muted-foreground">
          <span>Didn’t get it?</span>
          {/* The countdown and the button share one place; each fades through a blur into the other. */}
          <span className="grid items-center">
            {/* The ticking digits stay out of screen readers; they hear that a resend is coming instead. */}
            <span className="sr-only">
              {left && left > 0 ? "You can resend the code shortly." : ""}
            </span>
            <span
              className="col-start-1 row-start-1 flex items-baseline whitespace-nowrap tabular-nums"
              aria-hidden="true"
              style={{
                opacity: left && left > 0 ? 1 : 0,
                filter: left && left > 0 ? "none" : "blur(3px)",
                transition: reduced
                  ? "none"
                  : `opacity 260ms ${EASE}, filter 260ms ${EASE}`,
              }}
            >
              Resend in 0:
              <NumberRoll
                value={left ?? resendAfter}
                format={{ minimumIntegerDigits: 2 }}
                direction="down"
                duration={700}
              />
            </span>
            <span
              className="col-start-1 row-start-1"
              inert={!!(left && left > 0)}
              style={{
                opacity: left && left > 0 ? 0 : 1,
                filter: left && left > 0 ? "blur(3px)" : "none",
                transition: reduced
                  ? "none"
                  : `opacity 260ms ${EASE}, filter 260ms ${EASE}`,
              }}
            >
              <StatusButton
                variant="ghost"
                size="sm"
                status={resend}
                labels={{
                  idle: "Resend code",
                  pending: "Sending",
                  success: "Sent",
                  error: "Try again",
                }}
                onClick={doResend}
                className="-ml-2"
              />
            </span>
          </span>
        </div>
      )}

      <p role="status" aria-live="polite" className="sr-only">
        {right
          ? "Code verified"
          : wrong
            ? "That code didn't work. Enter it again."
            : phase === "checking"
              ? "Checking the code"
              : ""}
      </p>
    </div>
  );
}

"use client";

import * as React from "react";
import { Chevron, Fold } from "./accordion";
import { TextMorph } from "./text-morph";
import {
  INTERACTION_FOCUS,
  INTERACTION_PRESS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * COLLAPSIBLE: "Show 4 more" that opens in place
 *
 *   open     the hidden part's height eases open while its content
 *            rises out of a blur; the button's words morph
 *            ("Show 4 more" → "Show less") and its chevron turns
 *   close    the reverse; the button stays where your finger is
 *            when it sits above the content (`placement="top"`)
 *
 * One disclosure: aria-expanded on the button, the content a
 * region it controls, folded content inert.
 * ───────────────────────────────────────────────────────── */

export interface CollapsibleProps {
  children: React.ReactNode;
  /** Words on the button when closed and open. */
  labels?: { closed: string; open: string };
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Button above the hidden part (details) or below it ("show more" lists). */
  placement?: "top" | "bottom";
  className?: string;
}

export function Collapsible({
  children,
  labels = { closed: "Show more", open: "Show less" },
  open: controlled,
  defaultOpen = false,
  onOpenChange,
  placement = "bottom",
  className = "",
}: CollapsibleProps) {
  const reduced = useInteractionReducedMotion();
  const id = React.useId();
  const [own, setOwn] = React.useState(defaultOpen);
  const open = controlled ?? own;

  const button = (
    <button
      type="button"
      aria-expanded={open}
      aria-controls={id}
      onClick={() => {
        if (controlled === undefined) setOwn(!open);
        onOpenChange?.(!open);
      }}
      className={`-ml-3 inline-flex h-8 items-center gap-1.5 self-start rounded-full px-3 text-[13px] font-medium text-foreground cursor-pointer hover:bg-accent ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`}
    >
      <TextMorph>{open ? labels.open : labels.closed}</TextMorph>
      <Chevron open={open} reduced={reduced} />
    </button>
  );

  return (
    <div className={`flex w-full flex-col gap-1 ${className}`}>
      {placement === "top" && button}
      <Fold open={open} reduced={reduced} id={id}>
        {children}
      </Fold>
      {placement === "bottom" && button}
    </div>
  );
}

export default Collapsible;

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * COMBO CHART: every day as a bar, the trend as a line, one scale
 *
 *   arrive    the first time it's on screen the bars grow up out
 *             of the baseline in a wave and the average draws
 *             itself across them; the figures roll up from zero
 *   hover     the bar under the pointer fills while the rest
 *             dim, the line's dot slides along it and pings once
 *             where it lands, and the header becomes the readout:
 *             the title morphs to the day, the total rolls to its
 *             count, the line below to its average
 *   tiles     the best day, the daily average and the quietest
 *             day, each rolling up on arrival
 *
 * Bars and line share one scale (never two axes), so the line
 * reads in the same units as the bars. The plot is one tab stop:
 * arrow keys move between days and the readout is announced.
 * Every figure is also in a table for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface ComboDay {
  key: string;
  /** Under the bar, e.g. "2 Oct". */
  label: string;
  value: number;
  /** In the readout, e.g. "Thursday 2 October". Defaults to label. */
  title?: string;
}

export interface ComboChartProps extends React.HTMLAttributes<HTMLDivElement> {
  title?: string;
  days: ComboDay[];
  /** The line: a rolling average over this many days. */
  rolling?: number;
  /** Your own line values instead (e.g. an average that includes days before the first bar). */
  average?: number[];
  /** The total of the period before, for the change chip. */
  previous?: number;
  /** The two marks' names, for the legend and the readout. */
  series?: [string, string];
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const PLOT = 190;
const TOP = 10;
const LABELS = 24;
const STEPS = 4;
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const BAR = "var(--chart-1, var(--primary))";
const LINE = "var(--chart-2, #e8743b)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function niceTop(value: number) {
  if (value <= 0) return STEPS;
  const raw = value / STEPS;
  const mag = 10 ** Math.floor(Math.log10(raw));
  const step =
    [1, 1.5, 2, 2.5, 3, 4, 5, 6, 8, 10]
      .map((m) => m * mag)
      .find((s) => s >= raw) ?? 10 * mag;
  return step * STEPS;
}

function monotone(points: [number, number][]) {
  const n = points.length;
  if (!n) return "";
  const r = (v: number) => Math.round(v * 100) / 100;
  if (n === 1) return `M${r(points[0][0])},${r(points[0][1])}`;
  const m: number[] = [];
  for (let i = 0; i < n - 1; i++)
    m.push(
      (points[i + 1][1] - points[i][1]) /
        (points[i + 1][0] - points[i][0] || 1),
    );
  const t: number[] = [m[0]];
  for (let i = 1; i < n - 1; i++)
    t.push(m[i - 1] * m[i] <= 0 ? 0 : (m[i - 1] + m[i]) / 2);
  t.push(m[n - 2]);
  for (let i = 0; i < n - 1; i++) {
    if (m[i] === 0) {
      t[i] = 0;
      t[i + 1] = 0;
      continue;
    }
    const a = t[i] / m[i];
    const b = t[i + 1] / m[i];
    const s = a * a + b * b;
    if (s > 9) {
      const k = 3 / Math.sqrt(s);
      t[i] = k * a * m[i];
      t[i + 1] = k * b * m[i];
    }
  }
  let d = `M${r(points[0][0])},${r(points[0][1])}`;
  for (let i = 0; i < n - 1; i++) {
    const [x0, y0] = points[i];
    const [x1, y1] = points[i + 1];
    const dx = (x1 - x0) / 3;
    d += `C${r(x0 + dx)},${r(y0 + t[i] * dx)} ${r(x1 - dx)},${r(y1 - t[i + 1] * dx)} ${r(x1)},${r(y1)}`;
  }
  return d;
}

export function ComboChart({
  title = "Orders",
  days,
  rolling = 7,
  average: averageProp,
  previous,
  series = ["Orders", "7-day average"],
  format,
  locales,
  className = "",
  ...props
}: ComboChartProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const [visible, setVisible] = React.useState(false);
  const [plotH, setPlotH] = React.useState(PLOT);
  const [active, setActive] = React.useState<number | null>(null);
  const [keyboard, setKeyboard] = React.useState(false);
  const [width, setWidth] = React.useState(0);
  const rootRef = React.useRef<HTMLDivElement>(null);
  const chartRef = React.useRef<HTMLDivElement>(null);
  const plotRef = React.useRef<HTMLDivElement>(null);
  const pingRef = React.useRef<HTMLSpanElement>(null);

  const n = days.length;
  const values = React.useMemo(() => days.map((d) => d.value), [days]);
  // A rolling average over the days available (the first few average over fewer days).
  const average = React.useMemo(
    () =>
      averageProp ??
      values.map((_, i) => {
        const from = Math.max(0, i - rolling + 1);
        const run = values.slice(from, i + 1);
        return run.reduce((s, v) => s + v, 0) / run.length;
      }),
    [averageProp, values, rolling],
  );
  const max = niceTop(Math.max(0, ...values, ...average));
  const total = values.reduce((s, v) => s + v, 0);
  const daily = n ? total / n : 0;
  const best = values.indexOf(Math.max(...values));
  const quiet = values.indexOf(Math.min(...values));
  const change = previous ? (total - previous) / previous : null;

  // The plot's height is set by the card's width in CSS; read it so the drawing fits.
  React.useLayoutEffect(() => {
    const el = chartRef.current;
    if (!el) return;
    const measure = () =>
      setPlotH((h) => {
        const next = el.offsetHeight - LABELS;
        return next > 0 && next !== h ? next : h;
      });
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  React.useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          observer.disconnect();
        }
      },
      { rootMargin: "0px 0px -10% 0px" },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  React.useLayoutEffect(() => {
    const el = plotRef.current;
    if (!el) return;
    const measure = () =>
      setWidth((w) => (w === el.offsetWidth ? w : el.offsetWidth));
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  // The dot pings once each time it lands on a new day.
  React.useEffect(() => {
    if (active === null || reduced) return;
    const ring = pingRef.current;
    if (!ring) return;
    const timer = window.setTimeout(() => {
      ring.animate(
        [
          { transform: "translate(-50%, -50%) scale(1)", opacity: 0.45 },
          { transform: "translate(-50%, -50%) scale(2.6)", opacity: 0 },
        ],
        { duration: 640, easing: "cubic-bezier(0.22,1,0.36,1)" },
      );
    }, 180);
    return () => window.clearTimeout(timer);
  }, [active, reduced]);

  const slot = n ? width / n : 0;
  const cx = (i: number) => (i + 0.5) * slot;
  const y = (v: number) => TOP + (plotH - TOP) * (1 - v / max);
  const line = width
    ? monotone(average.map((v, i) => [cx(i), y(v)] as [number, number]))
    : "";
  const barWidth = Math.max(3, Math.min(24, slot * 0.62));

  const pointAt = (clientX: number) => {
    const r = plotRef.current?.getBoundingClientRect();
    if (!r || !n) return null;
    return Math.min(
      n - 1,
      Math.max(0, Math.floor(((clientX - r.left) / r.width) * n)),
    );
  };
  const onKeyDown = (e: React.KeyboardEvent) => {
    if (!n) return;
    const from = active ?? n - 1;
    const moves: Record<string, number> = {
      ArrowLeft: from - 1,
      ArrowRight: from + 1,
      Home: 0,
      End: n - 1,
    };
    if (e.key === "Escape") return setActive(null);
    if (!(e.key in moves)) return;
    e.preventDefault();
    setKeyboard(true);
    setActive(
      Math.min(n - 1, Math.max(0, active === null ? from : moves[e.key])),
    );
  };

  const fmt = (v: number) =>
    new Intl.NumberFormat(locales, {
      maximumFractionDigits: 0,
      ...format,
    }).format(v);
  const name = (i: number) => days[i]?.title ?? days[i]?.label ?? "";
  const every = width && n ? Math.max(1, Math.ceil(44 / (width / n))) : 1;
  // Labels thin out on narrow screens; the hovered one always shows, and its close neighbours step aside for it.
  const label = (i: number) =>
    active === i ||
    ((n - 1 - i) % every === 0 &&
      (active === null || every === 1 || Math.abs(i - active) >= every));
  const whole = { maximumFractionDigits: 0, ...format };
  const compact: Intl.NumberFormatOptions = {
    ...format,
    notation: "compact",
    minimumFractionDigits: 0,
    maximumFractionDigits: 1,
  };

  return (
    <div
      ref={rootRef}
      className={`@container w-full rounded-[22px] bg-background shadow-[0_0_0_1px_var(--border)] ${className}`}
      {...props}
    >
      <div className="p-4 @md:p-5 [--gutter:30px] @md:[--gutter:40px] [--plot:150px] @md:[--plot:190px]">
        <div className="flex flex-wrap items-start justify-between gap-x-4 gap-y-3">
          <div className="min-w-0">
            <p className="text-[12px] text-muted-foreground @md:text-[13px]">
              <TextMorph>
                {active !== null ? `${title} on ${name(active)}` : title}
              </TextMorph>
            </p>
            <p className="mt-1 flex flex-wrap items-center gap-x-2.5 gap-y-1">
              <span className="text-[22px] font-medium leading-tight tracking-[-0.03em] @md:text-[26px] text-foreground">
                <NumberRoll
                  value={
                    visible ? (active !== null ? values[active] : total) : 0
                  }
                  format={whole}
                  locales={locales}
                  duration={active !== null ? 600 : 1000}
                />
              </span>
              {change !== null && (
                <span
                  className="grid"
                  style={{
                    gridTemplateColumns: active === null ? "1fr" : "0fr",
                    opacity: active === null ? 1 : 0,
                    transition: reduced
                      ? "none"
                      : `grid-template-columns 380ms ${EASE}, opacity 220ms ${EASE}`,
                  }}
                >
                  <span className="min-w-0 [clip-path:inset(-4px_-2px)]">
                    <span
                      className={`inline-flex items-center gap-1 whitespace-nowrap rounded-full px-1.5 py-px text-[12.5px] font-medium ${
                        change >= 0
                          ? "bg-emerald-500/10 text-emerald-600"
                          : "bg-red-500/10 text-red-600 dark:text-red-400"
                      }`}
                    >
                      <svg
                        viewBox="0 0 12 12"
                        aria-hidden="true"
                        className="size-3"
                        style={{
                          transform: change >= 0 ? "none" : "rotate(180deg)",
                        }}
                      >
                        <path
                          d="M6 9.5V2.5M2.8 5.6 6 2.5l3.2 3.1"
                          fill="none"
                          stroke="currentColor"
                          strokeWidth="1.5"
                          strokeLinecap="round"
                          strokeLinejoin="round"
                        />
                      </svg>
                      <NumberRoll
                        value={visible ? Math.abs(change) : 0}
                        format={{ style: "percent", maximumFractionDigits: 1 }}
                        duration={700}
                      />
                    </span>
                  </span>
                </span>
              )}
            </p>
            <p className="mt-1 flex items-baseline gap-[0.3em] whitespace-nowrap text-[11.5px] text-muted-foreground @md:text-[12.5px]">
              <NumberRoll
                value={
                  visible ? (active !== null ? average[active] : daily) : 0
                }
                format={whole}
                locales={locales}
                duration={700}
              />
              <TextMorph>
                {active !== null
                  ? `on the ${series[1].toLowerCase()}`
                  : "a day on average"}
              </TextMorph>
            </p>
          </div>
        </div>

        {/* The legend: a bar key and a line key, so the two read by shape as well as colour. */}
        <div className="mt-3 flex items-center gap-4 text-[11.5px] text-muted-foreground @md:mt-4 @md:text-[12px]">
          <span className="flex items-center gap-1.5">
            <span
              aria-hidden="true"
              className="h-2.5 w-2 rounded-t-[2px]"
              style={{ background: BAR }}
            />
            {series[0]}
          </span>
          <span className="flex items-center gap-1.5">
            <span
              aria-hidden="true"
              className="h-0.5 w-3.5 rounded-full"
              style={{ background: LINE }}
            />
            {series[1]}
          </span>
        </div>

        <div
          ref={chartRef}
          className="relative mt-3"
          style={{ height: `calc(var(--plot) + ${LABELS}px)` }}
        >
          {Array.from({ length: STEPS + 1 }, (_, k) => 1 - k / STEPS).map(
            (f) => (
              <div
                key={f}
                aria-hidden="true"
                className="absolute inset-x-0"
                style={{ top: TOP + (plotH - TOP) * (1 - f) }}
              >
                <span
                  className="absolute left-0 top-0 -translate-y-1/2 text-[10px] leading-none tabular-nums text-muted-foreground/80"
                  style={{
                    width: "calc(var(--gutter) - 8px)",
                    textAlign: "right",
                  }}
                >
                  <NumberRoll
                    value={visible ? max * f : 0}
                    format={compact}
                    locales={locales}
                    duration={700}
                  />
                </span>
                <div
                  className="border-t border-border"
                  style={{ marginLeft: "var(--gutter)" }}
                />
              </div>
            ),
          )}

          <div
            ref={plotRef}
            role="group"
            tabIndex={0}
            aria-label={`${title}: ${series[0]} with the ${series[1].toLowerCase()}. Use the arrow keys to read each day.`}
            onKeyDown={onKeyDown}
            onBlur={() => keyboard && (setActive(null), setKeyboard(false))}
            onPointerMove={(e) => {
              setKeyboard(false);
              setActive(pointAt(e.clientX));
            }}
            onPointerDown={(e) => setActive(pointAt(e.clientX))}
            onPointerLeave={(e) => e.pointerType === "mouse" && setActive(null)}
            className={`absolute inset-y-0 right-0 touch-pan-y select-none rounded-lg ${FOCUS}`}
            style={{ left: "var(--gutter)" }}
          >
            {days.map((d, i) => {
              const hovered = active === i;
              return (
                <React.Fragment key={d.key}>
                  <span
                    aria-hidden="true"
                    className="absolute rounded-t-[4px]"
                    style={{
                      left: cx(i) - barWidth / 2,
                      width: barWidth,
                      top: TOP,
                      height: plotH - TOP,
                      transformOrigin: "bottom",
                      // The bar is drawn full height and scaled, so its 4px rounded top stays round while it grows.
                      clipPath: `inset(${visible ? ((plotH - TOP) * (1 - d.value / max)).toFixed(1) : plotH - TOP}px 0 0 0 round 4px 4px 0 0)`,
                      background: BAR,
                      opacity: hovered ? 1 : active !== null ? 0.18 : 0.32,
                      transition: reduced
                        ? "none"
                        : `clip-path 640ms ${EASE} ${Math.min(i, 40) * 14}ms, opacity 240ms ${EASE}`,
                    }}
                  />
                  <span
                    aria-hidden="true"
                    className={`absolute -translate-x-1/2 whitespace-nowrap text-[11px] leading-none transition-colors duration-200 ${hovered ? "text-foreground" : "text-muted-foreground"}`}
                    style={{
                      left: cx(i),
                      top: plotH + 9,
                      opacity: label(i) ? 1 : 0,
                    }}
                  >
                    {d.label}
                  </span>
                </React.Fragment>
              );
            })}

            <div
              className="pointer-events-none absolute inset-x-0 top-0"
              style={{
                height: plotH,
                clipPath: visible
                  ? "inset(-8px -8px -8px -8px)"
                  : "inset(-8px 100% -8px -8px)",
                transition: reduced ? "none" : `clip-path 1100ms ${EASE} 260ms`,
              }}
            >
              <svg
                aria-hidden="true"
                width={width}
                height={plotH}
                className="absolute inset-0 overflow-visible"
              >
                {line && (
                  <path
                    d={line}
                    fill="none"
                    stroke={LINE}
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                )}
              </svg>
            </div>

            {/* The line's dot, and the ring that pings when it lands. */}
            <span
              ref={pingRef}
              aria-hidden="true"
              className="pointer-events-none absolute size-2.5 rounded-full"
              style={{
                left: cx(active ?? n - 1),
                top: y(average[active ?? n - 1] ?? 0),
                transform: "translate(-50%, -50%)",
                background: LINE,
                opacity: 0,
                transition: reduced
                  ? "none"
                  : `left 260ms ${THROW}, top 260ms ${THROW}, opacity 200ms ${EASE}`,
              }}
            />
            <span
              aria-hidden="true"
              className="pointer-events-none absolute size-2.5 rounded-full shadow-[0_0_0_2px_var(--background)]"
              style={{
                left: cx(active ?? n - 1),
                top: y(average[active ?? n - 1] ?? 0),
                transform: "translate(-50%, -50%)",
                background: LINE,
                opacity: active !== null ? 1 : 0,
                transition: reduced
                  ? "none"
                  : `left 260ms ${THROW}, top 260ms ${THROW}, opacity 200ms ${EASE}`,
              }}
            />
          </div>
        </div>

        {/* The day's highlights as a compact strip under a thin line. */}
        <dl className="mt-4 grid grid-cols-3 divide-x divide-border border-t border-border pt-2.5 @md:mt-5 @md:pt-3">
          {[
            {
              label: "Best day",
              value: values[best] ?? 0,
              note: days[best]?.label,
            },
            { label: "Daily average", value: daily, note: `over ${n} days` },
            {
              label: "Quietest day",
              value: values[quiet] ?? 0,
              note: days[quiet]?.label,
            },
          ].map((t) => (
            <div
              key={t.label}
              className="min-w-0 px-2.5 first:pl-0 last:pr-0 @md:px-3.5"
            >
              <dt className="truncate text-[11px] text-muted-foreground @md:text-[11.5px]">
                {t.label}
              </dt>
              <dd className="mt-0.5 text-[13.5px] font-medium tracking-[-0.01em] text-foreground @md:text-[14.5px]">
                <NumberRoll
                  value={visible ? t.value : 0}
                  format={whole}
                  locales={locales}
                  duration={800}
                />
              </dd>
              <dd className="truncate text-[10.5px] text-muted-foreground @md:text-[11px]">
                {t.note}
              </dd>
            </div>
          ))}
        </dl>

        <p aria-live="polite" className="sr-only">
          {keyboard && active !== null
            ? `${name(active)}: ${fmt(values[active])}, ${series[1].toLowerCase()} ${fmt(average[active])}`
            : ""}
        </p>
        <table className="sr-only">
          <caption>
            {title}: {fmt(total)} over {n} days
          </caption>
          <thead>
            <tr>
              <th scope="col">Day</th>
              <th scope="col">{series[0]}</th>
              <th scope="col">{series[1]}</th>
            </tr>
          </thead>
          <tbody>
            {days.map((d, i) => (
              <tr key={d.key} id={`${id}-${d.key}`}>
                <th scope="row">{name(i)}</th>
                <td>{fmt(d.value)}</td>
                <td>{fmt(average[i])}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

/* ─────────────────────────────────────────────────────────
 * COMBOBOX MOTION: how rows, chips and picked labels move
 *
 *   rows     results that change (a new query, an answer from
 *            the server) don't flash: rows that stay glide to
 *            their new place, new ones rise in, and gone ones
 *            fade where they stood (their own detached elements,
 *            so leaving costs no render)
 *   chips    removing one glides the rest into the gap
 *   flight   a picked option's label is carried from its row to
 *            the chip it becomes
 *
 * Positions are layout offsets taken right before the change,
 * and glides are additive, so a change mid-glide never jumps.
 * ───────────────────────────────────────────────────────── */

export const EASE = "cubic-bezier(0.16,1,0.3,1)";

type Seen = { x: number; y: number; w: number; el: HTMLElement };
export type Snapshot = Map<string, Seen>;

/** Layout offsets (transforms ignored) of every element carrying the attribute, by its value. */
export function snapshot(root: HTMLElement | null, attr: string): Snapshot {
  const out: Snapshot = new Map();
  root?.querySelectorAll<HTMLElement>(`[${attr}]`).forEach((el) =>
    out.set(el.getAttribute(attr)!, {
      x: el.offsetLeft,
      y: el.offsetTop,
      w: el.offsetWidth,
      el,
    }),
  );
  return out;
}

/**
 * After a render: glide what moved, raise what's new, and fade what left in `ghosts` (a layer React never renders into).
 * `enter` decides what new elements do; pass null to let them simply appear.
 */
export function play(
  root: HTMLElement | null,
  attr: string,
  before: Snapshot,
  ghosts: HTMLElement | null,
  {
    enter = "rise",
    duration = 300,
  }: { enter?: "rise" | "pop" | null; duration?: number } = {},
) {
  if (!root) return;
  const present = new Set<string>();
  let order = 0;
  root.querySelectorAll<HTMLElement>(`[${attr}]`).forEach((el) => {
    const key = el.getAttribute(attr)!;
    present.add(key);
    const was = before.get(key);
    if (was) {
      const dx = was.x - el.offsetLeft;
      const dy = was.y - el.offsetTop;
      if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
        el.animate(
          [
            { transform: `translate(${dx}px, ${dy}px)` },
            { transform: "translate(0px, 0px)" },
          ],
          { duration, easing: EASE, composite: "add" },
        );
    } else if (enter === "rise") {
      el.animate(
        [
          { opacity: 0, transform: "translateY(4px)", filter: "blur(3px)" },
          { opacity: 1, transform: "none", filter: "blur(0px)" },
        ],
        {
          duration: 280,
          delay: Math.min(order++ * 14, 140),
          easing: EASE,
          fill: "backwards",
        },
      );
    } else if (enter === "pop") {
      el.animate(
        [
          { opacity: 0, transform: "scale(0.9)" },
          { opacity: 1, transform: "none" },
        ],
        { duration: 260, easing: EASE, fill: "backwards" },
      );
    }
  });
  if (!ghosts) return;
  before.forEach((was, key) => {
    if (present.has(key) || was.el.isConnected) return;
    const el = was.el;
    el.removeAttribute("id");
    el.removeAttribute(attr);
    el.setAttribute("aria-hidden", "true");
    el.style.position = "absolute";
    el.style.margin = "0";
    el.style.left = `${was.x}px`;
    el.style.top = `${was.y}px`;
    el.style.width = `${was.w}px`;
    el.style.pointerEvents = "none";
    ghosts.appendChild(el);
    el.animate(
      [
        { opacity: 1, transform: "none", filter: "blur(0px)" },
        { opacity: 0, transform: "scale(0.94)", filter: "blur(2px)" },
      ],
      { duration: 180, easing: EASE, fill: "forwards" },
    ).onfinish = () => el.remove();
  });
}

/** The box of an element's letters (not its padding), so a copy can land letter on letter. */
export function textRect(el: HTMLElement): DOMRect {
  const range = document.createRange();
  range.selectNodeContents(el);
  const r = range.getBoundingClientRect();
  return r.width ? r : el.getBoundingClientRect();
}

/**
 * Carries a copy of `from` (a row's label) onto `to` (the chip's label), which stays hidden until it lands.
 * The copy lives on the page's body with the label's own type and colour, so nothing clips it on the way.
 */
export function fly(
  from: { rect: DOMRect; style: Partial<CSSStyleDeclaration>; text: string },
  to: HTMLElement,
  duration = 460,
) {
  const target = textRect(to);
  if (!target.width) return;
  const copy = document.createElement("span");
  copy.textContent = from.text;
  copy.setAttribute("aria-hidden", "true");
  Object.assign(copy.style, from.style, {
    position: "fixed",
    left: `${from.rect.left}px`,
    top: `${from.rect.top}px`,
    margin: "0",
    // The copy's box is exactly its letters' box, so it starts and lands letter on letter.
    lineHeight: `${from.rect.height}px`,
    whiteSpace: "nowrap",
    pointerEvents: "none",
    zIndex: "70",
    transformOrigin: "0 0",
  });
  document.body.appendChild(copy);
  to.style.opacity = "0";
  const flight = copy.animate(
    [
      { transform: "none", opacity: 1 },
      {
        transform: `translate(${target.left - from.rect.left}px, ${target.top - from.rect.top}px)`,
        opacity: 1,
      },
    ],
    { duration, easing: EASE, fill: "forwards" },
  );
  const land = () => {
    to.style.opacity = "";
    copy.remove();
  };
  flight.onfinish = land;
  flight.oncancel = land;
}

"use client";

import * as React from "react";
import { createPortal } from "react-dom";
import {
  EASE,
  fly,
  play,
  snapshot,
  textRect,
  type Snapshot,
} from "./combobox-motion";
import { NumberRoll } from "./number-roll";
import { StatusButton } from "./status-button";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * COMBOBOX: pick from a list too long to scroll, or one your
 * server has to search
 *
 *   open      the panel unfolds from the field's edge, clear of
 *             it, with the search field already focused; things
 *             you picked before come first
 *   search    your search() is called as you type: debounced,
 *             older requests aborted, answers cached so going
 *             back a letter is instant. While it asks, the old
 *             results stay (dimmed after a beat) and a thin line
 *             runs under the field; when the answer lands, rows
 *             that stay glide to their new places, new ones rise
 *             in and gone ones fade where they stood
 *   match     the letters you typed are picked out in each row
 *   pick      one: the panel folds and the label morphs. Several:
 *             the row's name is carried up into the chip it
 *             becomes, and a check draws in the row
 *   remove    a chip's × (or Backspace in an empty search) and
 *             the other chips glide into its place
 *   create    nothing fits: "Create “design-review”" runs your
 *             onCreate and picks what it returns
 *
 * The panel lives on the page's body, so no card or scroller
 * clips it; it follows the field when the page scrolls and
 * opens upward when there's no room below.
 * ───────────────────────────────────────────────────────── */

export interface ComboboxOption {
  value: string;
  label: string;
  /** A second line: an email, a repository's owner, a count. */
  description?: string;
  /** An avatar picture. */
  image?: string;
  /** Letters for an avatar without a picture. */
  initials?: string;
  /** Any icon instead of an avatar. */
  icon?: React.ReactNode;
  /** More words a search should match (a team, an old name). */
  keywords?: string[];
  /** Rows with the same group sit together under its name. */
  group?: string;
  disabled?: boolean;
}

interface ComboboxBase {
  /** Accessible name, e.g. "Assignee". */
  label: string;
  /** What the field says while nothing is picked. */
  placeholder?: string;
  searchPlaceholder?: string;
  /** A list to filter here. */
  options?: ComboboxOption[];
  /** Or ask your server. Called with "" when the panel opens; pass the signal on to fetch. */
  search?: (
    query: string,
    context: { signal: AbortSignal },
  ) => Promise<ComboboxOption[]>;
  /** Milliseconds to wait after a keystroke before calling search. */
  debounce?: number;
  /** Shows "Create …" when nothing matches exactly; return the new option (or nothing to use the text). */
  onCreate?: (
    query: string,
  ) => Promise<ComboboxOption | void> | ComboboxOption | void;
  createLabel?: (query: string) => string;
  emptyMessage?: (query: string) => string;
  /** Rows to show at once; the rest wait for a narrower search. */
  limit?: number;
  /** "field" is a 38px form field; "pill" a 28px pill for sidebars and toolbars. */
  variant?: "field" | "pill";
  /** The panel's least width; it's never narrower than the field. */
  width?: number;
  /** Which edge of the field the panel lines up with. */
  align?: "start" | "end";
  /** A × that clears a single choice. */
  clearable?: boolean;
  /** Submits the chosen values with a form. */
  name?: string;
  disabled?: boolean;
  className?: string;
}

export interface ComboboxSingleProps extends ComboboxBase {
  multiple?: false;
  value?: ComboboxOption | null;
  defaultValue?: ComboboxOption | null;
  onValueChange?: (value: ComboboxOption | null) => void;
}

export interface ComboboxMultipleProps extends ComboboxBase {
  multiple: true;
  value?: ComboboxOption[];
  defaultValue?: ComboboxOption[];
  onValueChange?: (value: ComboboxOption[]) => void;
  /** How many can be picked. */
  max?: number;
}

export type ComboboxProps = ComboboxSingleProps | ComboboxMultipleProps;

type Phase = "closed" | "opening" | "open" | "closing";
type Nav = { key: string; option?: ComboboxOption; create?: true };
type Flight = {
  value: string;
  rect: DOMRect;
  text: string;
  style: Partial<CSSStyleDeclaration>;
};

const GAP = 6;
const MAX_LIST = 300;
const SEARCH_H = 41;
const FOOTER_H = 37;
const CREATE_KEY = "+create";
const NONE: ComboboxOption[] = [];
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
// The theme travels with the panel, so it matches the field wherever the field's colours were set.
const TOKENS = [
  "--background",
  "--foreground",
  "--popover",
  "--popover-foreground",
  "--border",
  "--accent",
  "--accent-foreground",
  "--primary",
  "--primary-foreground",
  "--muted",
  "--muted-foreground",
  "--ring",
];

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/* ── Matching ─────────────────────────────────────────── */

const fold = (s: string) =>
  s.toLowerCase().normalize("NFKD").replace(/[̀-ͯ]/g, "");
const terms = (q: string) => fold(q).split(/\s+/).filter(Boolean);
const BOUNDARY = /[\s\-_/.@:#(]/;

/** Lower is better: the label starts with it, a word in it does, it's inside it, or only the description has it. */
function rank(option: ComboboxOption, words: string[]): number | null {
  const label = fold(option.label);
  const rest = fold(
    [option.description ?? "", ...(option.keywords ?? []), option.value].join(
      " ",
    ),
  );
  let score = 0;
  for (const w of words) {
    const at = label.indexOf(w);
    if (at === 0) continue;
    if (at > 0) score += BOUNDARY.test(label[at - 1]) ? 1 : 2;
    else if (rest.includes(w)) score += 3;
    else return null;
  }
  return score;
}

/** Filters and orders a list the way the panel would; useful on a server too. */
export function filterOptions(
  options: ComboboxOption[],
  query: string,
): ComboboxOption[] {
  const words = terms(query);
  if (!words.length) return options;
  return options
    .map((option, i) => ({ option, i, score: rank(option, words) }))
    .filter(
      (x): x is { option: ComboboxOption; i: number; score: number } =>
        x.score !== null,
    )
    .sort((a, b) => a.score - b.score || a.i - b.i)
    .map((x) => x.option);
}

/** The label with the typed words picked out (a word start wins over a match mid-word). */
function Highlight({ text, query }: { text: string; query: string }) {
  const words = terms(query);
  const folded = fold(text);
  if (!words.length || folded.length !== text.length) return <>{text}</>;
  const hit = new Array<boolean>(text.length).fill(false);
  for (const w of words) {
    let at = -1;
    for (let i = folded.indexOf(w); i !== -1; i = folded.indexOf(w, i + 1)) {
      if (at === -1) at = i;
      if (i === 0 || BOUNDARY.test(folded[i - 1])) {
        at = i;
        break;
      }
    }
    if (at !== -1) for (let i = at; i < at + w.length; i++) hit[i] = true;
  }
  const parts: React.ReactNode[] = [];
  let start = 0;
  for (let i = 1; i <= text.length; i++) {
    if (i === text.length || hit[i] !== hit[start]) {
      const piece = text.slice(start, i);
      parts.push(
        hit[start] ? (
          <span key={start} className="font-semibold text-foreground">
            {piece}
          </span>
        ) : (
          piece
        ),
      );
      start = i;
    }
  }
  return <>{parts}</>;
}

/** Keeps each group's rows together, groups in the order they first appear. */
function grouped(list: ComboboxOption[]) {
  if (!list.some((o) => o.group)) return list;
  const order: string[] = [];
  for (const o of list)
    if (!order.includes(o.group ?? "")) order.push(o.group ?? "");
  return order.flatMap((g) => list.filter((o) => (o.group ?? "") === g));
}

const unique = (list: ComboboxOption[]) => {
  const seen = new Set<string>();
  return list.filter((o) =>
    seen.has(o.value) ? false : (seen.add(o.value), true),
  );
};

/* ── Small parts ──────────────────────────────────────── */

const hasLead = (o?: ComboboxOption | null) =>
  Boolean(o && (o.icon || o.image || o.initials));

function Lead({ option, size }: { option: ComboboxOption; size: number }) {
  if (option.icon)
    return (
      <span
        className="flex shrink-0 items-center justify-center text-muted-foreground [&_svg]:size-full"
        style={{ width: size, height: size }}
      >
        {option.icon}
      </span>
    );
  if (option.image)
    return (
      <img
        src={option.image}
        alt=""
        draggable={false}
        className="shrink-0 rounded-full object-cover"
        style={{ width: size, height: size }}
      />
    );
  return (
    <span
      className="flex shrink-0 items-center justify-center rounded-full bg-muted font-medium text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)]"
      style={{ width: size, height: size, fontSize: Math.round(size * 0.42) }}
    >
      {option.initials}
    </span>
  );
}

/** The single choice's avatar or icon: the slot opens and closes, and a new one scales in through a blur as the old one leaves. */
function LeadSlot({
  option,
  size,
  reduced,
}: {
  option: ComboboxOption | undefined;
  size: number;
  reduced: boolean;
}) {
  const [out, setOut] = React.useState<ComboboxOption | null>(null);
  const last = React.useRef(option);
  const key = option?.value ?? "";
  React.useLayoutEffect(() => {
    const prev = last.current;
    last.current = option;
    if (!prev || prev.value === key || !hasLead(prev) || reduced) return;
    setOut(prev);
    const timer = window.setTimeout(() => setOut(null), 260);
    return () => window.clearTimeout(timer);
  }, [key, reduced]);
  const on = hasLead(option);
  return (
    <span
      aria-hidden="true"
      className="relative flex shrink-0 items-center justify-center"
      style={{
        width: on ? size : 0,
        height: size,
        marginRight: on ? 8 : 0,
        transition: reduced
          ? "none"
          : `width 380ms ${EASE}, margin 380ms ${EASE}`,
      }}
    >
      {out && (
        <span
          key={`out-${out.value}`}
          className="absolute inset-0 flex items-center justify-center"
          ref={(el) => {
            if (!el || el.dataset.out) return;
            el.dataset.out = "1";
            el.animate(
              [
                { opacity: 1, transform: "none", filter: "blur(0px)" },
                { opacity: 0, transform: "scale(0.6)", filter: "blur(3px)" },
              ],
              { duration: 220, easing: EASE, fill: "forwards" },
            );
          }}
        >
          <Lead option={out} size={size} />
        </span>
      )}
      {on && option && (
        <span
          key={key}
          className="absolute inset-0 flex items-center justify-center"
          ref={(el) => {
            if (!el || reduced || el.dataset.in) return;
            el.dataset.in = "1";
            el.animate(
              [
                { opacity: 0, transform: "scale(0.6)", filter: "blur(3px)" },
                { opacity: 1, transform: "none", filter: "blur(0px)" },
              ],
              { duration: 380, delay: 60, easing: EASE, fill: "backwards" },
            );
          }}
        >
          <Lead option={option} size={size} />
        </span>
      )}
    </span>
  );
}

function Chevron({
  up,
  reduced,
  className = "",
}: {
  up: boolean;
  reduced: boolean;
  className?: string;
}) {
  return (
