}

function Check({
  drawn,
  reduced,
  className = "size-3.5",
}: {
  drawn: boolean;
  reduced: boolean;
  className?: string;
}) {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      aria-hidden="true"
