const shake = (el: Element | null | undefined, reduced: boolean) => {
  if (!el || reduced) return;
  el.animate(
    [
      { transform: "none" },
      { transform: "translateX(-4px)" },
      { transform: "translateX(4px)" },
      { transform: "translateX(-2px)" },
      { transform: "none" },
    ],
    {
      duration: 380,
      easing: "ease-out",
      composite: "add",
    },
  );
};

/* ── The combobox ─────────────────────────────────────── */

export function Combobox(props: ComboboxProps) {
  const {
    label,
    placeholder = "Choose",
    searchPlaceholder = "Search",
    options,
    search,
    debounce = 180,
    onCreate,
    createLabel = (q: string) => `Create “${q}”`,
    emptyMessage = (q: string) =>
      q ? `No matches for “${q}”` : "Nothing to choose yet",
    limit = 100,
    variant = "field",
    width = 280,
    align = "start",
    clearable = false,
    name,
    disabled = false,
    className = "",
  } = props;
  const multiple = props.multiple === true;
  const max = props.multiple ? props.max : undefined;
  const uid = React.useId();
  const reduced = useReducedMotion();

  // What's picked, always a list inside.
  const listOf = (v: ComboboxOption | ComboboxOption[] | null | undefined) =>
    v == null ? NONE : Array.isArray(v) ? v : [v];
  const [own, setOwn] = React.useState<ComboboxOption[]>(() =>
    listOf(props.defaultValue),
  );
  const selected = props.value !== undefined ? listOf(props.value) : own;
  const selectedKey = selected.map((o) => o.value).join("\u0000");
  const picked = React.useMemo(
    () => new Set(selected.map((o) => o.value)),
    [selectedKey],
  );

  const [phase, setPhase] = React.useState<Phase>("closed");
  const [fit, setFit] = React.useState({
    x: 0,
    y: 0,
    w: width,
    up: false,
    room: 480,
    theme: {} as Record<string, string>,
  });
  const [query, setQuery] = React.useState("");
  const [results, setResults] = React.useState<ComboboxOption[] | null>(null);
  const [resultsFor, setResultsFor] = React.useState<string | null>(null);
  const [loading, setLoading] = React.useState(false);
  const [failed, setFailed] = React.useState<string | null>(null);
  const [retry, setRetry] = React.useState(0);
  const [created, setCreated] = React.useState<ComboboxOption[]>([]);
  const [creating, setCreating] = React.useState<"idle" | "pending" | "error">(
    "idle",
  );
  const [pinned, setPinned] = React.useState<ComboboxOption[]>([]);
  const [activeKey, setActiveKey] = React.useState<string | null>(null);
  const [mark, setMark] = React.useState({
    y: 0,
    h: 0,
    on: false,
    slide: false,
  });
  const [listH, setListH] = React.useState(0);
  const [sized, setSized] = React.useState(false);
  const [fieldH, setFieldH] = React.useState(0);
  const [ring, setRing] = React.useState(false);
  const [notice, setNotice] = React.useState<string | null>(null);
  const [announce, setAnnounce] = React.useState("");

  const anchorRef = React.useRef<HTMLDivElement>(null);
  const triggerRef = React.useRef<HTMLButtonElement>(null);
  const surfaceRef = React.useRef<HTMLDivElement>(null);
  const inputRef = React.useRef<HTMLInputElement>(null);
  const listRef = React.useRef<HTMLDivElement>(null);
  const rowGhosts = React.useRef<HTMLDivElement>(null);
  const chipsRef = React.useRef<HTMLDivElement>(null);
  const chipGhosts = React.useRef<HTMLDivElement>(null);
  const cache = React.useRef(new Map<string, ComboboxOption[]>());
  const searchRef = React.useRef(search);
  const resultsForRef = React.useRef<string | null>(null);
  const rowSnap = React.useRef<Snapshot | null>(null);
  const chipSnap = React.useRef<Snapshot | null>(null);
  const flight = React.useRef<Flight | null>(null);
  const timer = React.useRef(0);

  const mounted = phase !== "closed";
  const expanded = phase === "open";
  const async = Boolean(search);
  const q = query.trim();
  const panelId = `${uid}-panel`;
  const listId = `${uid}-list`;

  React.useLayoutEffect(() => {
    searchRef.current = search;
    resultsForRef.current = resultsFor;
  });

  const commit = (next: ComboboxOption[]) => {
    if (props.value === undefined) setOwn(next);
    if (props.multiple === true) props.onValueChange?.(next);
    else (props as ComboboxSingleProps).onValueChange?.(next[0] ?? null);
  };

  /* ── What the list shows ── */

  const pool = React.useMemo(() => {
    const extra = filterOptions(created, query);
    // Rows for an older query stay while a newer one is asked, but not under its error.
    const answer = failed && resultsFor !== q ? NONE : (results ?? NONE);
    const base = async
      ? unique([...extra, ...answer])
      : filterOptions(unique([...created, ...(options ?? [])]), query);
    if (q || !pinned.length) return grouped(base);
    // Before you type, what you'd already picked comes first, in the order it was when the panel opened.
    const first = pinned.map((p) => base.find((o) => o.value === p.value) ?? p);
    const ids = new Set(first.map((o) => o.value));
    return [...first, ...grouped(base.filter((o) => !ids.has(o.value)))];
  }, [async, results, resultsFor, failed, options, created, query, q, pinned]);
  const shown = pool.length > limit ? pool.slice(0, limit) : pool;
  const more = pool.length - shown.length;
  const canCreate = Boolean(
    onCreate && q && !pool.some((o) => fold(o.label) === fold(q)),
  );
  const firstLoad = async && results === null && !failed;
  const nav: Nav[] = React.useMemo(() => {
    const out: Nav[] = shown
      .filter((o) => !o.disabled)
      .map((o) => ({ key: o.value, option: o }));
    if (canCreate) out.push({ key: CREATE_KEY, create: true });
    return out;
  }, [shown, canCreate]);
  const activeIndex = Math.max(
    0,
    nav.findIndex((n) => n.key === activeKey),
  );
  const active = nav.length ? nav[activeIndex] : undefined;
  const rowsKey = [
    ...shown.map((o) => o.value),
    canCreate ? CREATE_KEY : "",
    firstLoad ? "!loading" : "",
    failed ? "!error" : "",
    !shown.length && !canCreate && !firstLoad && !failed ? "!empty" : "",
    more ? "!more" : "",
  ].join("\u0000");
  const stale = async && loading && resultsFor !== null && resultsFor !== q;

  /* ── Panel placement ── */

  const place = React.useCallback(() => {
    const anchor = anchorRef.current;
    if (!anchor) return;
    const r = anchor.getBoundingClientRect();
    const vw = document.documentElement.clientWidth;
    const vh = window.innerHeight;
    const w = Math.min(Math.max(width, r.width), vw - 16);
    const x = Math.min(
      Math.max(8, align === "start" ? r.left : r.right - w),
      vw - 8 - w,
    );
    const below = vh - r.bottom - GAP - 8;
    const above = r.top - GAP - 8;
    const up = below < 240 && above > below;
    const cs = getComputedStyle(anchor);
    const theme: Record<string, string> = {
      colorScheme: cs.colorScheme,
      fontFamily: cs.fontFamily,
    };
    for (const t of TOKENS) {
      const v = cs.getPropertyValue(t);
      if (v) theme[t] = v;
    }
    setFit({
      x,
      y: up ? vh - r.top + GAP : r.bottom + GAP,
      w,
      up,
      room: up ? above : below,
      theme,
    });
  }, [width, align]);

  const open = (seed = "") => {
    if (disabled || phase === "open" || phase === "opening") return;
    window.clearTimeout(timer.current);
    place();
    setQuery(seed);
    const hit = async ? cache.current.get(seed.trim()) : undefined;
    setResults(hit ?? null);
    setResultsFor(hit ? seed.trim() : null);
    setFailed(null);
    setPinned(multiple ? selected : NONE);
    setActiveKey(!multiple && selected[0] ? selected[0].value : null);
    setNotice(null);
    setCreating("idle");
    setSized(false);
    setMark({ y: 0, h: 0, on: false, slide: false });
    setPhase(reduced ? "open" : "opening");
  };

  const close = React.useCallback(
    (refocus = true) => {
      window.clearTimeout(timer.current);
      if (refocus) triggerRef.current?.focus({ preventScroll: true });
      if (reduced) return setPhase("closed");
      setPhase("closing");
      timer.current = window.setTimeout(() => setPhase("closed"), 240);
    },
    [reduced],
  );

  const toggle = () =>
    phase === "open" || phase === "opening" ? close() : open();

  React.useEffect(() => {
    if (phase !== "opening") return;
    let inner = 0;
    const outer = requestAnimationFrame(
      () => (inner = requestAnimationFrame(() => setPhase("open"))),
    );
    return () => {
      cancelAnimationFrame(outer);
      cancelAnimationFrame(inner);
    };
  }, [phase]);
  React.useEffect(() => () => window.clearTimeout(timer.current), []);

  React.useLayoutEffect(() => {
    if (phase === "opening" || (reduced && phase === "open"))
      inputRef.current?.focus({ preventScroll: true });
  }, [phase, reduced]);

  // Outside presses close it; the page scrolling or resizing carries it along with the field.
  React.useEffect(() => {
    if (!mounted) return;
    const inside = (n: Node) =>
      Boolean(
        anchorRef.current?.contains(n) || surfaceRef.current?.contains(n),
      );
    const onDown = (e: PointerEvent) => {
      if (!inside(e.target as Node)) close(false);
    };
    let frame = 0;
    const follow = (e: Event) => {
      if (e.target instanceof Node && surfaceRef.current?.contains(e.target))
        return;
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(() => {
        const r = anchorRef.current?.getBoundingClientRect();
        if (!r || r.bottom < 0 || r.top > window.innerHeight) close(false);
        else place();
      });
    };
    document.addEventListener("pointerdown", onDown);
    window.addEventListener("scroll", follow, true);
    window.addEventListener("resize", follow);
    // A field that grows (chips wrapping onto a new line) pushes the panel down with it.
    const resized = new ResizeObserver(() => place());
    if (anchorRef.current) resized.observe(anchorRef.current);
    return () => {
      resized.disconnect();
      cancelAnimationFrame(frame);
      document.removeEventListener("pointerdown", onDown);
      window.removeEventListener("scroll", follow, true);
      window.removeEventListener("resize", follow);
    };
  }, [mounted, close, place]);

  /* ── Asking the server ── */

  const show = (list: ComboboxOption[], forQuery: string) => {
    if (!reduced) rowSnap.current = snapshot(listRef.current, "data-row");
    setResults(list);
    setResultsFor(forQuery);
  };

  React.useEffect(() => {
    const ask = searchRef.current;
    if (!mounted || !ask) return;
    const hit = cache.current.get(q);
    if (hit) {
      if (resultsForRef.current !== q) show(hit, q);
      setLoading(false);
      setFailed(null);
      return;
    }
    const controller = new AbortController();
    setLoading(true);
    const wait = window.setTimeout(
      () => {
        ask(q, { signal: controller.signal }).then(
          (list) => {
            if (controller.signal.aborted) return;
            cache.current.set(q, list);
            // A small memory: the oldest answers go first.
            if (cache.current.size > 40)
              cache.current.delete(cache.current.keys().next().value!);
            show(list, q);
            setLoading(false);
            setFailed(null);
          },
          (err: unknown) => {
            if (
              controller.signal.aborted ||
              (err instanceof Error && err.name === "AbortError")
            )
              return;
            if (!reduced)
              rowSnap.current = snapshot(listRef.current, "data-row");
            setLoading(false);
            setFailed(
              err instanceof Error && err.message
                ? err.message
                : "Couldn’t load results.",
            );
          },
        );
      },
      resultsForRef.current === null ? 0 : debounce,
    );
    return () => {
      window.clearTimeout(wait);
      controller.abort();
    };
  }, [q, mounted, retry, debounce]);

  // Rows that changed: glide, rise in, fade out (from positions taken right before the change).
  React.useLayoutEffect(() => {
    const snap = rowSnap.current;
    rowSnap.current = null;
    if (snap) play(listRef.current, "data-row", snap, rowGhosts.current);
  }, [rowsKey]);

  // The count, said once typing settles.
  React.useEffect(() => {
    if (!expanded || !q || firstLoad) return;
    const t = window.setTimeout(
      () =>
        setAnnounce(
          shown.length
            ? `${pool.length} ${pool.length === 1 ? "result" : "results"}`
            : emptyMessage(q),
        ),
      500,
    );
    return () => window.clearTimeout(t);
  }, [rowsKey, expanded]);

  /* ── List height and the highlight ── */

  React.useLayoutEffect(() => {
    const list = listRef.current;
    if (!list || !mounted) return;
    const measure = () =>
      setListH((h) => (h === list.offsetHeight ? h : list.offsetHeight));
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(list);
    return () => observer.disconnect();
  }, [mounted]);
  React.useEffect(() => {
    if (expanded && listH && !sized) {
      const frame = requestAnimationFrame(() => setSized(true));
      return () => cancelAnimationFrame(frame);
    }
  }, [expanded, listH, sized]);

  React.useLayoutEffect(() => {
    const list = listRef.current;
    if (!list || !mounted) return;
    const row = active
      ? list.querySelector<HTMLElement>(`[data-nav="${activeIndex}"]`)
      : null;
    if (!row) {
      setMark((m) => (m.on ? { ...m, on: false, slide: false } : m));
      return;
    }
    setMark((m) =>
      m.y === row.offsetTop && m.h === row.offsetHeight && m.on
        ? m
        : { y: row.offsetTop, h: row.offsetHeight, on: true, slide: m.on },
    );
    const scroller = list.parentElement;
    if (scroller && scroller.scrollHeight > scroller.clientHeight) {
      if (row.offsetTop < scroller.scrollTop)
        scroller.scrollTop = row.offsetTop - 4;
      else if (
        row.offsetTop + row.offsetHeight >
        scroller.scrollTop + scroller.clientHeight
      )
        scroller.scrollTop =
          row.offsetTop + row.offsetHeight - scroller.clientHeight + 8;
    }
  }, [activeIndex, active, rowsKey, mounted, listH]);

  /* ── Chips ── */

  React.useLayoutEffect(() => {
    const chips = chipsRef.current;
    if (!chips) return;
    const measure = () =>
      setFieldH((h) => (h === chips.offsetHeight ? h : chips.offsetHeight));
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(chips);
    return () => observer.disconnect();
  }, []);

  React.useLayoutEffect(() => {
    const snap = chipSnap.current;
    chipSnap.current = null;
    const f = flight.current;
    flight.current = null;
    const to =
      f &&
      chipsRef.current?.querySelector<HTMLElement>(
        `[data-chip="${CSS.escape(f.value)}"] [data-chip-label]`,
      );
    if (f && to) fly(f, to);
    if (snap)
      play(chipsRef.current, "data-chip", snap, chipGhosts.current, {
        enter: "pop",
        duration: 340,
      });
  }, [selectedKey]);

  // Declared after the effects that use them: a snapshot no change used (the same rows came back) would be stale by the next one.
  React.useLayoutEffect(() => {
    rowSnap.current = null;
    chipSnap.current = null;
    flight.current = null;
  });

  /* ── Picking ── */

  const pick = (option: ComboboxOption, row?: HTMLElement | null) => {
    if (option.disabled) return;
    if (!multiple) {
      if (option.value !== selected[0]?.value) commit([option]);
      setAnnounce(`${option.label} selected`);
      close();
      return;
    }
    const on = picked.has(option.value);
    if (!on && max !== undefined && selected.length >= max) {
      setNotice(`You can pick up to ${max}.`);
      shake(row, reduced);
      return;
    }
    if (!reduced) chipSnap.current = snapshot(chipsRef.current, "data-chip");
    const label = row?.querySelector<HTMLElement>("[data-label]");
    if (!on && label && variant === "field" && !reduced) {
      const cs = getComputedStyle(label);
      flight.current = {
        value: option.value,
        rect: textRect(label),
        text: option.label,
        style: {
          fontFamily: cs.fontFamily,
          fontSize: cs.fontSize,
          fontWeight: cs.fontWeight,
          fontStyle: cs.fontStyle,
          color: cs.color,
          letterSpacing: cs.letterSpacing,
        },
      };
    }
    const next = on
      ? selected.filter((o) => o.value !== option.value)
      : [...selected, option];
    commit(next);
    setNotice(null);
    setAnnounce(
      `${option.label} ${on ? "removed" : "added"}. ${next.length} selected.`,
    );
  };

  const remove = (option: ComboboxOption) => {
    if (!reduced) chipSnap.current = snapshot(chipsRef.current, "data-chip");
    const next = selected.filter((o) => o.value !== option.value);
    commit(next);
    setNotice(null);
    setAnnounce(`${option.label} removed. ${next.length} selected.`);
  };

  const clear = () => {
    if (!reduced) chipSnap.current = snapshot(chipsRef.current, "data-chip");
    commit(NONE);
    setNotice(null);
    setAnnounce("Cleared");
  };

  const create = async () => {
    if (!onCreate || !q || creating === "pending") return;
    const row = listRef.current?.querySelector<HTMLElement>(
      `[data-row="${CREATE_KEY}"]`,
    );
    setCreating("pending");
    setNotice(null);
    try {
      const made = await onCreate(q);
      const option =
        made && typeof made === "object" ? made : { value: q, label: q };
      setCreated((list) => [
        option,
        ...list.filter((o) => o.value !== option.value),
      ]);
      setCreating("idle");
      setActiveKey(option.value);
      pick(option, row);
    } catch (err) {
      setCreating("error");
      setNotice(
        err instanceof Error && err.message
          ? err.message
          : `Couldn’t create “${q}”.`,
      );
      shake(row, reduced);
    }
  };

  const onInputKey = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.nativeEvent.isComposing) return;
    const go = (i: number) => {
      e.preventDefault();
      if (nav.length)
        setActiveKey(nav[((i % nav.length) + nav.length) % nav.length].key);
    };
    if (e.key === "ArrowDown") go(activeIndex + 1);
    else if (e.key === "ArrowUp") go(activeIndex - 1);
    else if (e.key === "PageDown")
      go(Math.min(nav.length - 1, activeIndex + 8));
    else if (e.key === "PageUp") go(Math.max(0, activeIndex - 8));
    else if (e.key === "Enter") {
      e.preventDefault();
      if (!active) return;
      if (active.create) void create();
      else if (active.option)
        pick(
          active.option,
          listRef.current?.querySelector<HTMLElement>(
            `[data-nav="${activeIndex}"]`,
          ),
        );
    } else if (e.key === "Escape") {
      e.preventDefault();
      e.stopPropagation();
      close();
    } else if (e.key === "Tab") {
      e.preventDefault();
      close();
    } else if (e.key === "Backspace" && multiple && !query && selected.length) {
      e.preventDefault();
      remove(selected[selected.length - 1]);
    }
  };

  const onTriggerKey = (e: React.KeyboardEvent<HTMLButtonElement>) => {
    if (e.key === "ArrowDown" || e.key === "ArrowUp") {
      e.preventDefault();
      open();
    } else if (
      e.key.length === 1 &&
      /\S/.test(e.key) &&
      !e.metaKey &&
      !e.ctrlKey &&
      !e.altKey
    ) {
      // Typing on the closed field opens it with what you typed.
      e.preventDefault();
      open(e.key);
    } else if (
      e.key === "Backspace" &&
      multiple &&
      selected.length &&
      !mounted
    ) {
      e.preventDefault();
      remove(selected[selected.length - 1]);
    }
  };

  /* ── The field ── */

  const single = selected[0];
  const pill = variant === "pill";
  const summary = !selected.length
    ? placeholder
    : multiple
      ? selected.length === 1
        ? selected[0].label
        : `${selected[0].label} +${selected.length - 1}`
      : single!.label;
  const triggerName = `${label}: ${selected.length ? selected.map((o) => o.label).join(", ") : "none"}`;
  const ringStyle =
    mounted || ring
      ? "color-mix(in oklab, var(--ring) 55%, var(--border))"
      : "var(--border)";
  const triggerProps = {
    ref: triggerRef,
    type: "button" as const,
    disabled,
    "aria-haspopup": "dialog" as const,
    "aria-expanded": expanded,
    "aria-controls": mounted ? panelId : undefined,
    "aria-label": triggerName,
    onKeyDown: onTriggerKey,
    onFocus: (e: React.FocusEvent<HTMLButtonElement>) =>
      setRing(e.currentTarget.matches(":focus-visible")),
    onBlur: () => setRing(false),
  };

  let field: React.ReactNode;
  if (multiple && !pill) {
    field = (
      <div
        onMouseDown={(e) => {
          if (
            disabled ||
            e.button !== 0 ||
            (e.target as HTMLElement).closest("[data-chip-remove]")
          )
            return;
          e.preventDefault();
          toggle();
        }}
        className={`rounded-[19px] border bg-background transition-[border-color] duration-200 ${disabled ? "cursor-default opacity-60" : "cursor-pointer"}`}
        style={{ borderColor: ringStyle }}
      >
        {/* clip, not hidden: hidden boxes still scroll, and focus would scroll the chips away. */}
        <div
          className="overflow-clip"
          style={{
            height: fieldH || undefined,
            transition: reduced || !fieldH ? "none" : `height 320ms ${EASE}`,
          }}
        >
          <div
            ref={chipsRef}
            className="relative flex flex-wrap items-center gap-1.5 py-[5px] pl-[5px] pr-8"
          >
            {selected.map((o) => (
              <span
                key={o.value}
                data-chip={o.value}
                className="relative z-[1] inline-flex h-7 max-w-full shrink-0 items-center rounded-full bg-background text-[13px] shadow-[inset_0_0_0_1px_var(--border)]"
              >
                {hasLead(o) && (
                  <span className="ml-1 flex">
                    <Lead option={o} size={20} />
                  </span>
                )}
                <span
                  data-chip-label=""
                  className="max-w-[12rem] truncate py-1"
                  style={{ marginLeft: hasLead(o) ? 6 : 10, marginRight: 2 }}
                >
                  {o.label}
                </span>
                <button
                  type="button"
                  data-chip-remove=""
                  tabIndex={-1}
                  aria-label={`Remove ${o.label}`}
                  disabled={disabled}
                  onMouseDown={(e) => e.preventDefault()}
                  onClick={() => remove(o)}
                  className="relative mr-1 flex size-5 shrink-0 cursor-pointer items-center justify-center rounded-full text-muted-foreground transition-colors hover:bg-accent hover:text-foreground disabled:cursor-default"
                >
                  <Cross />
                </button>
              </span>
            ))}
            <button
              {...triggerProps}
              onClick={(e) => {
                // The field's own press handles the mouse; this is Enter and Space.
                if (e.detail === 0) toggle();
              }}
              // With chips it lies behind them across the whole field, so it never needs a line of its own.
              className={`cursor-pointer text-left text-[14px] outline-none disabled:cursor-default ${selected.length ? "absolute inset-0" : "flex h-7 min-w-[7rem] flex-1 items-center pl-1.5"}`}
            >
              {!selected.length && (
                <span className="min-w-0 flex-1 truncate text-muted-foreground">
                  {placeholder}
                </span>
              )}
            </button>
            {/* In the first line's corner, so it never wraps onto a line of its own. */}
            <Chevron
              up={expanded}
              reduced={reduced}
              className="pointer-events-none absolute right-3 top-[12px] size-3.5"
            />
            <div
              ref={chipGhosts}
              aria-hidden="true"
              className="pointer-events-none absolute inset-0"
            />
          </div>
        </div>
      </div>
    );
  } else {
    const leadSize = pill ? 18 : 22;
    field = (
      <button
        {...triggerProps}
        onClick={toggle}
        className={`relative flex w-full min-w-0 cursor-pointer items-center whitespace-nowrap text-left transition-[background-color,border-color] duration-200 disabled:cursor-default disabled:opacity-60 ${
          pill
            ? `h-7 rounded-full px-2.5 text-[12px] font-medium shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent ${FOCUS} ${expanded ? "bg-accent" : ""}`
            : "h-[38px] rounded-[19px] border bg-background pl-3 pr-2.5 text-[14px] outline-none"
        }`}
        style={pill ? undefined : { borderColor: ringStyle }}
      >
        {!multiple && (
          <LeadSlot option={single} size={leadSize} reduced={reduced} />
        )}
        <span
          className={`min-w-0 flex-1 overflow-hidden ${selected.length ? "text-foreground" : "text-muted-foreground"}`}
        >
          <TextMorph>{summary}</TextMorph>
        </span>
        {/* Room for the clear button, which can't live inside this one. */}
        {clearable && !multiple && (
          <span
            aria-hidden="true"
            className="shrink-0"
            style={{
              width: single ? 22 : 0,
              transition: reduced ? "none" : `width 320ms ${EASE}`,
            }}
          />
        )}
        <Chevron
          up={expanded}
          reduced={reduced}
          className={pill ? "ml-1.5 size-3" : "ml-2 size-3.5"}
        />
      </button>
    );
  }

  /* ── The panel ── */

  const maxList = Math.max(
    120,
    Math.min(MAX_LIST, fit.room - SEARCH_H - (multiple ? FOOTER_H : 0) - 10),
  );
  let navIndex = 0;
  let lastGroup: string | undefined;
  const rows: React.ReactNode[] = [];
  const pinnedFirst = !q && pinned.length > 0;
  const hasGroups = shown.some((o) => o.group);
  shown.forEach((o, index) => {
    const isPinned = pinnedFirst && index < pinned.length;
    if (isPinned && index === 0 && hasGroups)
      rows.push(
        <div
          key="#selected"
          data-row="#selected"
          role="presentation"
          className="px-2 pb-1 pt-1 text-[11.5px] font-medium text-muted-foreground"
        >
          Selected
        </div>,
      );
    if (o.group && o.group !== lastGroup && !isPinned)
      rows.push(
        <div
          key={`#${o.group}`}
          data-row={`#${o.group}`}
          role="presentation"
          className="px-2 pb-1 pt-2.5 text-[11.5px] font-medium text-muted-foreground first:pt-1"
        >
          {o.group}
        </div>,
      );
    if (!isPinned) lastGroup = o.group;
    const on = picked.has(o.value);
    const i = o.disabled ? -1 : navIndex++;
    rows.push(
      <div
        key={o.value}
        data-row={o.value}
        data-nav={i === -1 ? undefined : i}
        id={i === -1 ? undefined : `${uid}-o${i}`}
        role="option"
        aria-selected={on}
        aria-disabled={o.disabled || undefined}
        onPointerMove={() => {
          if (!o.disabled && activeKey !== o.value) setActiveKey(o.value);
        }}
        onClick={(e) => pick(o, e.currentTarget)}
        className={`relative flex min-h-9 items-center gap-2.5 rounded-[10px] px-2 py-1.5 ${o.disabled ? "cursor-default opacity-45" : "cursor-pointer"}`}
      >
        {multiple && <Box on={on} reduced={reduced} />}
        {hasLead(o) && <Lead option={o} size={22} />}
        <span className="min-w-0 flex-1">
          <span
            data-label=""
            className="block truncate text-[13px] leading-tight"
          >
            <Highlight text={o.label} query={query} />
          </span>
          {o.description && (
            <span className="mt-0.5 block truncate text-[12px] leading-tight text-muted-foreground">
              {o.description}
            </span>
          )}
        </span>
        {!multiple && <Check drawn={on && expanded} reduced={reduced} />}
      </div>,
    );
  });
  if (canCreate) {
    const i = navIndex++;
    rows.push(
      <div
        key={CREATE_KEY}
        data-row={CREATE_KEY}
        data-nav={i}
        id={`${uid}-o${i}`}
        role="option"
        aria-selected={false}
        onPointerMove={() =>
          activeKey !== CREATE_KEY && setActiveKey(CREATE_KEY)
        }
        onClick={() => void create()}
        className={`relative flex min-h-9 cursor-pointer items-center gap-2.5 rounded-[10px] px-2 py-1.5 text-[13px] ${creating === "error" ? "text-red-600 dark:text-red-400" : ""}`}
      >
        <span className="relative flex size-[22px] shrink-0 items-center justify-center rounded-full text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)]">
          <span
            className="absolute inset-0 flex items-center justify-center"
            style={{
              opacity: creating === "pending" ? 0 : 1,
              transition: `opacity 200ms ${EASE}`,
            }}
          >
            <svg
              viewBox="0 0 12 12"
              className="size-3"
              fill="none"
              aria-hidden="true"
            >
              <path
                d="M6 2.5v7M2.5 6h7"
                stroke="currentColor"
                strokeWidth="1.4"
                strokeLinecap="round"
              />
            </svg>
          </span>
          <span
            className={`size-3 rounded-full border-[1.5px] border-current border-t-transparent motion-reduce:animate-none ${creating === "pending" ? "animate-spin" : ""}`}
            style={{
              opacity: creating === "pending" ? 1 : 0,
              transition: `opacity 200ms ${EASE}`,
            }}
          />
        </span>
        <span data-label="" className="min-w-0 truncate">
          <TextMorph>
            {creating === "pending" ? `Creating “${q}”` : createLabel(q)}
          </TextMorph>
        </span>
      </div>,
    );
  }
  if (firstLoad)
    rows.push(
      <div
        key="!loading"
        data-row="!loading"
        role="presentation"
        className="flex min-h-9 items-center gap-2.5 px-2 text-[13px] text-muted-foreground"
      >
        <span className="size-3 rounded-full border-[1.5px] border-current border-t-transparent motion-safe:animate-spin" />
        Searching
      </div>,
    );
  else if (failed)
    rows.push(
      <div
        key="!error"
        data-row="!error"
        role="presentation"
        className="flex min-h-10 items-center gap-2 px-2 text-[13px] text-red-600 dark:text-red-400"
      >
        <AlertIcon />
        <span className="min-w-0 flex-1 truncate">{failed}</span>
        <StatusButton
          variant="ghost"
          size="sm"
          status={loading ? "pending" : "idle"}
          labels={{ idle: "Retry", pending: "Retrying" }}
          onClick={() => {
            setFailed(null);
            setRetry((r) => r + 1);
          }}
        />
      </div>,
    );
  else if (!shown.length && !canCreate)
    rows.push(
      <div
        key="!empty"
        data-row="!empty"
        role="presentation"
        className="flex min-h-9 items-center px-2 text-[13px] text-muted-foreground"
      >
        {emptyMessage(q)}
      </div>,
    );
  if (more)
    rows.push(
      <div
        key="!more"
        data-row="!more"
        role="presentation"
        className="px-2 pb-1.5 pt-2 text-[12px] text-muted-foreground"
      >
        Showing {shown.length} of {pool.length}. Keep typing to narrow it down.
      </div>,
    );

  const panel = mounted
    ? createPortal(
        <div
          ref={surfaceRef}
          id={panelId}
          role="dialog"
          aria-label={label}
          onKeyDown={(e) => {
            if (e.key === "Escape") {
              e.preventDefault();
              e.stopPropagation();
              close();
            }
          }}
          onMouseDown={(e) => {
            // Presses in the panel keep focus in the search field.
            // (The scroller itself is only the target when its scrollbar is pressed.)
            if (!(e.target as HTMLElement).matches("input, [data-scroll-bar]"))
              e.preventDefault();
          }}
          className={`fixed z-[60] flex overflow-hidden rounded-[14px] border border-border bg-popover text-popover-foreground ${fit.up ? "flex-col-reverse" : "flex-col"}`}
          style={{
            ...fit.theme,
            left: fit.x,
            [fit.up ? "bottom" : "top"]: fit.y,
            width: fit.w,
            clipPath: expanded
              ? "inset(0px 0px 0px 0px round 14px)"
              : fit.up
                ? "inset(100% 0px 0px 0px round 14px)"
                : "inset(0px 0px 100% 0px round 14px)",
            opacity: expanded ? 1 : 0,
            transition: reduced
              ? "none"
              : phase === "closing"
                ? `clip-path 220ms ${EASE}, opacity 180ms ${EASE} 40ms`
                : `clip-path 360ms ${EASE}, opacity 200ms ${EASE}`,
          }}
        >
          <div
            className={`relative flex shrink-0 items-center gap-2 px-3 ${fit.up ? "border-t" : "border-b"} border-border`}
            style={{ height: SEARCH_H - 1 }}
          >
            <SearchIcon />
            <input
              ref={inputRef}
              role="combobox"
              aria-expanded={expanded}
              aria-controls={listId}
              aria-autocomplete="list"
              aria-activedescendant={
                active ? `${uid}-o${activeIndex}` : undefined
              }
              aria-label={`Search ${label.toLowerCase()}`}
              aria-busy={loading || undefined}
              value={query}
              placeholder={searchPlaceholder}
              autoComplete="off"
              spellCheck={false}
              onChange={(e) => {
                if (!async && !reduced)
                  rowSnap.current = snapshot(listRef.current, "data-row");
                setQuery(e.target.value);
                if (creating === "error") setCreating("idle");
                setNotice(null);
              }}
              onKeyDown={onInputKey}
              className="h-full min-w-0 flex-1 bg-transparent text-[13.5px] text-foreground outline-none placeholder:text-muted-foreground [@media(pointer:coarse)]:text-[16px]"
            />
            {/* A thin line that runs along the edge while the server is asked. */}
            <span
              aria-hidden="true"
              className={`pointer-events-none absolute inset-x-0 h-px overflow-hidden ${fit.up ? "top-[-1px]" : "bottom-[-1px]"}`}
              style={{
                opacity: loading ? 1 : 0,
                transition: `opacity ${loading ? 200 : 400}ms ${EASE} ${loading ? 150 : 0}ms`,
              }}
            >
              <span
                className={`absolute inset-y-0 left-0 w-2/5 bg-primary/70 ${loading && !reduced ? "animate-[ui-scan_1.1s_cubic-bezier(0.45,0,0.55,1)_infinite]" : ""}`}
              />
            </span>
          </div>

          <div
            data-scroll-bar=""
            className="overflow-y-auto overscroll-contain p-1"
            style={{
              height: listH ? Math.min(listH + 8, maxList) : undefined,
              transition: sized && !reduced ? `height 280ms ${EASE}` : "none",
            }}
          >
            <div
              ref={listRef}
              id={listId}
              role="listbox"
              aria-label={label}
              aria-multiselectable={multiple || undefined}
              className="relative"
              style={{
                opacity: stale ? 0.55 : 1,
                transition: `opacity ${stale ? 240 : 160}ms ${EASE} ${stale ? 140 : 0}ms`,
              }}
            >
              <span
                aria-hidden="true"
                className="pointer-events-none absolute inset-x-0 top-0 rounded-[10px] bg-accent"
                style={{
                  height: mark.h,
                  transform: `translateY(${mark.y}px)`,
                  opacity: mark.on ? 1 : 0,
                  transition: reduced
                    ? "none"
                    : `${mark.slide ? `transform 220ms ${EASE}, height 220ms ${EASE}, ` : ""}opacity 160ms ${EASE}`,
                }}
              />
              {rows}
              <div
                ref={rowGhosts}
                aria-hidden="true"
                className="pointer-events-none absolute inset-0"
              />
            </div>
          </div>

          {multiple && (
            <div
              className={`flex shrink-0 items-center justify-between gap-3 px-3 text-[12px] text-muted-foreground ${fit.up ? "border-b" : "border-t"} border-border`}
              style={{ height: FOOTER_H }}
            >
              <span
                className={`min-w-0 truncate tabular-nums ${notice ? "text-amber-700 dark:text-amber-400" : ""}`}
              >
                {notice ? (
                  <span
                    key={notice}
                    className="inline-block animate-[ui-fade-in_320ms_cubic-bezier(0.16,1,0.3,1)_both]"
                  >
                    {notice}
                  </span>
                ) : (
                  <span className="inline-flex items-baseline">
                    <NumberRoll value={selected.length} duration={600} />
                    {max !== undefined && (
                      <span className="ml-1">of {max}</span>
                    )}
                    <span className="ml-1">selected</span>
                  </span>
                )}
              </span>
              <span className="flex shrink-0 items-center gap-0.5">
                <span
                  className="grid"
                  style={{
                    gridTemplateColumns: selected.length ? "1fr" : "0fr",
                    opacity: selected.length ? 1 : 0,
                    transition: reduced
                      ? "none"
                      : `grid-template-columns 320ms ${EASE}, opacity 200ms ${EASE}`,
                  }}
                >
                  <span className="min-w-0 overflow-hidden">
                    <button
                      type="button"
                      tabIndex={selected.length ? 0 : -1}
                      onClick={clear}
                      className={`inline-flex h-6 cursor-pointer items-center rounded-full px-2 font-medium transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
                    >
                      Clear
                    </button>
                  </span>
                </span>
                <button
                  type="button"
                  onClick={() => close()}
                  className={`inline-flex h-6 cursor-pointer items-center rounded-full px-2 font-medium text-foreground transition-colors hover:bg-accent ${FOCUS}`}
                >
                  Done
                </button>
              </span>
            </div>
          )}
        </div>,
        document.body,
      )
    : null;

  return (
    <div
      ref={anchorRef}
      className={`relative ${pill ? "inline-flex max-w-full" : "w-full"} ${className}`}
    >
      {field}
      {clearable && !multiple && (
        <button
          type="button"
          aria-label={`Clear ${label.toLowerCase()}`}
          tabIndex={single ? 0 : -1}
          disabled={disabled || !single}
          onClick={() => {
            commit(NONE);
            setAnnounce("Cleared");
            triggerRef.current?.focus({ preventScroll: true });
          }}
          className={`absolute top-1/2 flex size-5 -translate-y-1/2 cursor-pointer items-center justify-center rounded-full text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS} ${pill ? "right-6" : "right-8"}`}
          style={{
            opacity: single ? 1 : 0,
            filter: single ? "none" : "blur(3px)",
            pointerEvents: single ? undefined : "none",
            transition: reduced
              ? "none"
              : `opacity 240ms ${EASE}, filter 240ms ${EASE}`,
          }}
        >
          <Cross />
        </button>
      )}
      {panel}
      {name &&
        (selected.length ? (
          selected.map((o) => (
            <input key={o.value} type="hidden" name={name} value={o.value} />
          ))
        ) : (
          <input type="hidden" name={name} value="" />
        ))}
      <span className="sr-only" role="status" aria-live="polite">
        {announce}
      </span>
    </div>
  );
}

"use client";

import * as React from "react";
import { ChevronRight, Square, X } from "lucide-react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * COMMAND OUTPUT: a command the agent runs, and its log
 *
 *   running    $ pnpm test, "running" with seconds that roll, and
 *              Stop; the log streams in and follows the newest line
 *   success    the spinner blurs into a check that draws itself,
 *              "running" morphs to "done" and the time gains its
 *              tenths; Stop folds away as the chevron opens in, and
 *              the log folds away a beat later (open it any time)
 *   error      "exit 1" in red, the code rolling in; the log stays
 *              open with the failing lines marked and in view
 *   cancelled  stopped by you
 *
 * Pass the lines as they arrive; plain strings work, ANSI
 * colour codes are stripped, and lines that look like errors
 * are marked (or set level yourself).
 * ───────────────────────────────────────────────────────── */

export type CommandStatus = "running" | "success" | "error" | "cancelled";

export interface CommandLine {
  text: string;
  level?: "info" | "error" | "warn" | "success";
}

export interface CommandOutputProps extends React.HTMLAttributes<HTMLDivElement> {
  command: string;
  status: CommandStatus;
  lines: (string | CommandLine)[];
  exitCode?: number;
  /** When it started (ms); shows a live timer, then the duration. */
  startedAt?: number;
  endedAt?: number;
  onStop?: () => void;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
}

const EASE = "cubic-bezier(0.23,1,0.32,1)";
const MORPH = "cubic-bezier(0.16,1,0.3,1)";
const TENTHS = { minimumFractionDigits: 1, maximumFractionDigits: 1 };
const TWO_DIGITS = { minimumIntegerDigits: 2, maximumFractionDigits: 0 };
const WHOLE = { maximumFractionDigits: 0 };
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const ANSI = /\u001b\[[0-9;]*[A-Za-z]/g;
const LOOKS_LIKE_ERROR =
  /(^|\s)(error|err!|failed|fail|fatal|exception|✗|✕|×)(\s|:|$)/i;

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Icons trade places through a blur: the old one shrinks away as the new one grows in. */
const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 260ms ${MORPH}, transform 380ms ${MORPH}, filter 260ms ${MORPH}`,
});

/** A piece of a line that opens out of nothing and folds back into it. */
function Reveal({
  show,
  reduced,
  className = "",
  children,
}: {
  show: boolean;
  reduced: boolean;
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <span
      aria-hidden={!show || undefined}
      className={`grid ${className}`}
      style={{
        gridTemplateColumns: show ? "1fr" : "0fr",
        opacity: show ? 1 : 0,
        filter: show ? "none" : "blur(3px)",
        transition: reduced
          ? "none"
          : `grid-template-columns 420ms ${MORPH}, opacity ${show ? "300ms" : "160ms"} ${MORPH}, filter 300ms ${MORPH}`,
      }}
    >
      <span className="flex min-w-0 items-center whitespace-nowrap [clip-path:inset(-4px_-2px)]">
        {children}
      </span>
    </span>
  );
}

/** Seconds that roll up as they pass and minutes that slide open; a short finished run gains its tenths ("1.8s"). */
function Elapsed({
  ms,
  settled,
  reduced,
}: {
  ms: number;
  settled: boolean;
  reduced: boolean;
}) {
  const total = Math.max(0, ms) / 1000;
  const minutes = Math.floor(total / 60);
  const tenths = settled && total < 10;
  const seconds = minutes
    ? Math.floor(total % 60)
    : tenths
      ? Math.floor(total * 10) / 10
      : Math.floor(total);
  return (
    <span className="inline-flex items-baseline">
      <Reveal show={minutes > 0} reduced={reduced}>
        <NumberRoll value={minutes} suffix="m" duration={500} />
        &nbsp;
      </Reveal>
      <NumberRoll
        value={seconds}
        format={minutes ? TWO_DIGITS : tenths ? TENTHS : WHOLE}
        suffix="s"
        direction="up"
        duration={500}
      />
    </span>
  );
}

function DrawnCheck({ drawn, reduced }: { drawn: boolean; reduced: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="none" className="size-2.5">
      <path
        d="M3 8.5 6.5 12 13 4.5"
        stroke="currentColor"
        strokeWidth="3"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 380ms ${MORPH} 120ms`
              : "none",
        }}
      />
    </svg>
  );
}

export function CommandOutput({
  command,
  status,
  lines,
  exitCode,
  startedAt,
  endedAt,
  onStop,
  open: openProp,
  onOpenChange,
  className = "",
  ...props
}: CommandOutputProps) {
  const reduced = useReducedMotion();
  const running = status === "running";
  const [now, setNow] = React.useState(startedAt ?? 0);
  const [userOpen, setUserOpen] = React.useState<boolean | null>(null);
  const [settled, setSettled] = React.useState(status === "success");
  const [seenStatus, setSeenStatus] = React.useState(status);
  if (status !== seenStatus) {
    setSeenStatus(status);
    if (status !== "success") setSettled(false);
  }
  const logRef = React.useRef<HTMLDivElement>(null);
  const firstError = React.useRef<HTMLDivElement | null>(null);
  const follow = React.useRef(true);
  const stopRef = React.useRef<HTMLButtonElement>(null);
  const toggleRef = React.useRef<HTMLButtonElement>(null);
  const id = React.useId();

  // Stop folds away when the run ends; if it had focus, hand it to the chevron that takes its place.
  React.useLayoutEffect(() => {
    if (!running && document.activeElement === stopRef.current)
      toggleRef.current?.focus({ preventScroll: true });
  }, [running]);

  const rows = React.useMemo(
    () =>
      lines.map((line) => {
        const l = typeof line === "string" ? { text: line } : line;
        const text = l.text.replace(ANSI, "");
        return {
          text,
          level: l.level ?? (LOOKS_LIKE_ERROR.test(text) ? "error" : "info"),
        };
      }),
    [lines],
  );

  // Success folds the log a beat after the last line, so the end is seen before it goes.
  React.useEffect(() => {
    if (status !== "success") return;
    const timer = window.setTimeout(() => setSettled(true), reduced ? 0 : 900);
    return () => window.clearTimeout(timer);
  }, [status, reduced]);

  const open =
    openProp ??
    userOpen ??
    !(status === "success" ? settled : status === "cancelled");
  const toggle = () => {
    setUserOpen(!open);
    onOpenChange?.(!open);
  };

  React.useEffect(() => {
    if (!running || startedAt === undefined) return;
    const tick = () => setNow(Date.now());
    const first = window.setTimeout(tick, 0);
    const timer = window.setInterval(tick, 1000);
    return () => {
      window.clearTimeout(first);
      window.clearInterval(timer);
    };
  }, [running, startedAt]);

  // Follow the newest line while running, unless the reader scrolled up.
  React.useLayoutEffect(() => {
    const log = logRef.current;
    if (log && follow.current) log.scrollTop = log.scrollHeight;
  }, [rows.length]);

  // On failure, bring the first failing line into view.
  React.useEffect(() => {
    if (status !== "error") return;
    const log = logRef.current;
    const line = firstError.current;
    if (log && line)
      log.scrollTo({
        top: Math.max(0, line.offsetTop - 16),
        behavior: reduced ? "auto" : "smooth",
      });
  }, [status, reduced]);

  const elapsedMs =
    startedAt === undefined
      ? null
      : running
        ? now - startedAt
        : endedAt !== undefined
          ? endedAt - startedAt
          : null;
  const word = {
    running: "running",
    success: "done",
    error: "exit",
    cancelled: "stopped",
  }[status];
  const showCode = status === "error" && exitCode !== undefined;
  const canToggle = !running && rows.length > 0;
  const firstErrorIndex = rows.findIndex((r) => r.level === "error");

  return (
    <div
      className={`w-full rounded-[18px] border border-border bg-background p-1 ${className}`}
      {...props}
    >
      <div className="flex h-9 items-center gap-2.5 pl-2.5 pr-1">
        <span
          aria-hidden="true"
          className="relative flex size-4 shrink-0 items-center justify-center"
        >
          <span
            className="absolute inset-0 flex items-center justify-center"
            style={swap(running, reduced)}
          >
            {/* Spins only while it's showing. */}
            <span
              className={`size-3 rounded-full border-[1.5px] border-border border-t-foreground/70 motion-reduce:animate-none ${running ? "animate-spin" : ""}`}
            />
          </span>
          <span
            className="absolute inset-0 flex items-center justify-center rounded-full bg-emerald-500/15 text-emerald-600 dark:text-emerald-400"
            style={swap(status === "success", reduced)}
          >
            <DrawnCheck drawn={status === "success"} reduced={reduced} />
          </span>
          <span
            className="absolute inset-0 flex items-center justify-center rounded-full bg-red-500/15 text-red-600 dark:text-red-400"
            style={swap(status === "error", reduced)}
          >
            <X className="size-2.5" strokeWidth={3} />
          </span>
          <span
            className="absolute inset-0 flex items-center justify-center rounded-full bg-muted text-muted-foreground"
            style={swap(status === "cancelled", reduced)}
          >
            <Square className="size-2" fill="currentColor" />
          </span>
        </span>

        <code className="min-w-0 flex-1 truncate font-mono text-[12.5px] text-foreground">
          <span className="select-none text-muted-foreground">$ </span>
          {command}
        </code>

        {/* One status: the word morphs, the exit code rolls in, the time rolls on and settles. */}
        <span
          aria-hidden="true"
          className={`flex shrink-0 items-baseline font-mono text-[11.5px] tabular-nums transition-colors duration-300 ${status === "error" ? "text-red-600 dark:text-red-400" : "text-muted-foreground"}`}
        >
          <TextMorph>{word}</TextMorph>
          {exitCode !== undefined && (
            <Reveal show={showCode} reduced={reduced}>
              &nbsp;
              <NumberRoll value={showCode ? exitCode : 0} duration={600} />
            </Reveal>
          )}
          {elapsedMs !== null && (
            <span
              className={`pl-2 transition-colors duration-300 ${status === "error" ? "text-muted-foreground" : ""}`}
            >
              <Elapsed ms={elapsedMs} settled={!running} reduced={reduced} />
            </span>
          )}
        </span>
        <span role="status" className="sr-only">
          {running
            ? "Running"
            : status === "success"
              ? "Finished"
              : status === "error"
                ? `Failed${exitCode !== undefined ? ` with exit code ${exitCode}` : ""}`
                : "Stopped"}
        </span>

        {onStop && (
          <Reveal show={running} reduced={reduced} className="shrink-0">
            <button
              ref={stopRef}
              type="button"
              inert={!running}
              onClick={onStop}
              aria-label="Stop command"
              className={`cursor-pointer flex h-7 items-center gap-1.5 rounded-full px-2.5 text-[12px] font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
            >
              <Square className="size-2.5" fill="currentColor" />
              Stop
            </button>
          </Reveal>
        )}
        {rows.length > 0 && (
          <Reveal show={canToggle} reduced={reduced} className="shrink-0">
            <button
              ref={toggleRef}
              type="button"
              inert={!canToggle}
              aria-expanded={open}
              aria-controls={id}
              aria-label={open ? "Hide output" : "Show output"}
              onClick={toggle}
              className={`cursor-pointer flex size-7 items-center justify-center rounded-full text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
            >
              <ChevronRight
                className="size-3.5 transition-transform duration-300 motion-reduce:transition-none"
                style={{
                  transform: open ? "rotate(90deg)" : "none",
                  transitionTimingFunction: EASE,
                }}
              />
            </button>
          </Reveal>
        )}
      </div>

      <div
        id={id}
        inert={!open}
        className="grid"
        style={{
          gridTemplateRows: open && rows.length ? "1fr" : "0fr",
          transition: reduced ? "none" : `grid-template-rows 420ms ${EASE}`,
        }}
      >
        <div className="min-h-0 overflow-hidden">
          <div
            ref={logRef}
            role="log"
            aria-label={`Output of ${command}`}
            tabIndex={0}
            onScroll={(e) => {
              const el = e.currentTarget;
              follow.current =
                el.scrollHeight - el.clientHeight - el.scrollTop < 24;
            }}
            className="max-h-56 overflow-y-auto overflow-x-hidden rounded-[14px] bg-muted/70 py-2.5 font-mono text-[11.5px] leading-[1.65] outline-none [scrollbar-color:var(--border)_transparent] [scrollbar-width:thin] focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/30"
          >
            {rows.map((row, i) => {
              const isError = row.level === "error";
              const ref = i === firstErrorIndex ? firstError : undefined;
              return (
                <div
                  key={i}
                  ref={ref}
                  className={`whitespace-pre-wrap break-words px-3 animate-[ui-fade-in_160ms_ease-out_both] motion-reduce:animate-none ${
                    isError
                      ? "bg-red-500/[0.08] text-red-700 dark:text-red-300"
                      : row.level === "warn"
                        ? "text-amber-700 dark:text-amber-300"
                        : row.level === "success"
                          ? "text-emerald-700 dark:text-emerald-400"
                          : "text-foreground/75"
                  }`}
                >
                  {row.text || " "}
                </div>
              );
            })}
            {running && (
              <div aria-hidden="true" className="px-3">
                <span className="inline-block h-3.5 w-[7px] translate-y-[2px] bg-foreground/60 animate-[ui-blink_1s_steps(1)_infinite]" />
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { createPortal } from "react-dom";
import { TextMorph } from "./text-morph";
import { Kbd } from "./kbd";

/* ─────────────────────────────────────────────────────────
 * COMMAND PALETTE: ⌘K, from the pill that was always there
 *
 *   closed    an action label followed by a Kbd shortcut badge
 *   opening   the pill itself lifts and grows into the palette:
 *             position, size and corners ease from pill to panel
 *             while its placeholder becomes the field's
 *   search    results narrow as you type, the letters that match
 *             are marked, the panel's height eases to fit and a
 *             highlight glides between rows
 *   nested    "Change theme…" opens its own list in place: it
 *             slides in from the right as a chip joins the field;
 *             Backspace slides back
 *   running   a command's shortcut blurs into a spinner, then a
 *             check that draws itself, and the palette folds back
 *             into the pill, which it lands as exactly (hotkey
 *             and all), so the hand-off never shows
 *   empty     "No results for “xyz”", morphing as you type
 *
 * A real dialog: focus moves in and back, arrow keys, Home/End,
 * Enter, Escape (back, then close) and the hotkey to toggle.
 * ───────────────────────────────────────────────────────── */

export interface CommandItem {
  id: string;
  label: string;
  /** Rows are grouped under this heading, in the order groups first appear. */
  group?: string;
  icon?: React.ReactNode;
  /** Shown on the right, e.g. ["⌘", "N"]. */
  shortcut?: string[];
  /** Other words that should find it, e.g. ["dark", "light"] for "Change theme". */
  keywords?: string[];
  description?: string;
  /** Navigate here when chosen. */
  href?: string;
  /** Run it. Return a promise to show progress on the row before the palette closes. */
  onSelect?: (context: { signal: AbortSignal }) => void | Promise<unknown>;
  /** A nested list, opened in place (e.g. "Change theme…"). */
  items?: CommandItem[];
}

export interface CommandFilter {
  id: string;
  label: string;
  icon?: React.ReactNode;
}

export interface CommandPaletteProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onSelect"
> {
  items: CommandItem[];
  placeholder?: string;
  /** Accessible name of the search field. */
  searchLabel?: string;
  /** The letter that opens it with ⌘ (or Ctrl). Empty string turns the hotkey off. */
  hotkey?: string;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Show the command menu trigger. Without it, open with the hotkey or the open prop. */
  showTrigger?: boolean;
  /** The pill's words. */
  triggerLabel?: string;
  /** Leading trigger icon. Defaults to search; pass null to omit it. */
  triggerIcon?: React.ReactNode;
  /** Caller-owned active search scopes. The caller also filters items. */
  filters?: CommandFilter[];
  filtersLabel?: string;
  onFilterRemove?: (id: string) => void;
  /** Optional help copy, links, or actions alongside the keyboard hints. */
  footer?: React.ReactNode;
}

type Phase = "closed" | "opening" | "open" | "closing";
type Page = { title: string; items: CommandItem[] };
type Row = { item: CommandItem; marks: number[]; score: number };
type Rect = {
  left: number;
  top: number;
  width: number;
  height: number;
  radius: number;
};
type RunState = { id: string; state: "pending" | "done" | "error" };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const OPEN_DURATION = 440;
const CLOSE_DURATION = 320;
const WIDTH = 640;
const ROW = 40;
const LIST_MAX = 440;
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Icons trade places through a blur: the old one shrinks away as the new one grows in. */
const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 220ms ${EASE}, transform 340ms ${EASE}, filter 220ms ${EASE}`,
});

/** Where the query's letters land in the text: one run if it's there whole, otherwise in order. */
function match(text: string, query: string): number[] | null {
  const t = text.toLowerCase();
  const q = query.toLowerCase().replace(/\s+/g, " ").trim();
  if (!q) return [];
  const at = t.indexOf(q);
  if (at >= 0) return Array.from({ length: q.length }, (_, i) => at + i);
  const marks: number[] = [];
  let j = 0;
  for (let i = 0; i < t.length && j < q.length; i++) {
    if (q[j] === " ") j++;
    if (t[i] === q[j]) {
      marks.push(i);
      j++;
    }
  }
  return j >= q.length ? marks : null;
}

function rank(items: CommandItem[], query: string): Row[] {
  const q = query.trim();
  if (!q) return items.map((item) => ({ item, marks: [], score: 0 }));
  const rows: Row[] = [];
  for (const item of items) {
    const marks = match(item.label, q);
    if (marks) {
      const contiguous =
        marks.length > 1 &&
        marks[marks.length - 1] - marks[0] === marks.length - 1;
      const start = marks[0] ?? 0;
      const wordStart = start === 0 || item.label[start - 1] === " ";
      const score =
        (contiguous ? 60 : 30) +
        (start === 0 ? 40 : wordStart ? 20 : 0) -
        (marks[marks.length - 1] - start) * 0.5;
      rows.push({ item, marks, score });
    } else if (
      item.keywords?.some((k) => match(k, q)) ||
      (item.description && match(item.description, q))
    ) {
      rows.push({ item, marks: [], score: 10 });
    }
  }
  return rows.sort((a, b) => b.score - a.score);
}

function Marked({ text, marks }: { text: string; marks: number[] }) {
  if (!marks.length) return <>{text}</>;
  const set = new Set(marks);
  return (
    <>
      {Array.from(text).map((ch, i) =>
        set.has(i) ? (
          <span key={i} className="font-medium text-foreground">
            {ch}
          </span>
        ) : (
          <React.Fragment key={i}>{ch}</React.Fragment>
        ),
      )}
    </>
  );
}

function SearchIcon({ className = "" }: { className?: string }) {
  return (
    <svg
      aria-hidden="true"
      viewBox="0 0 16 16"
      fill="none"
      className={`size-4 shrink-0 ${className}`}
    >
      <circle cx="7" cy="7" r="4.75" stroke="currentColor" strokeWidth="1.5" />
      <path
        d="m10.5 10.5 3 3"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
      />
    </svg>
  );
}

function Check({ drawn, reduced }: { drawn: boolean; reduced: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="none" className="size-4">
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="1.8"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced ? `stroke-dashoffset 360ms ${EASE} 80ms` : "none",
        }}
      />
    </svg>
  );
}

/** One page of results. Kept as its own piece so the page you leave can slide out while the next slides in. */
function Results({
  rows,
  active,
  run,
  reduced,
  listId,
  optionId,
  setActive,
  choose,
  rowRefs,
}: {
  rows: Row[];
  active: number;
  run: RunState | null;
  reduced: boolean;
  listId?: string;
  optionId?: (i: number) => string;
  setActive?: (i: number) => void;
  choose?: (i: number) => void;
  rowRefs?: React.MutableRefObject<(HTMLDivElement | null)[]>;
}) {
  return (
    <div
      id={listId}
      role={listId ? "listbox" : undefined}
      aria-label={listId ? "Commands" : undefined}
    >
      {rows.map((row, i) => {
        const { item } = row;
        const heading =
          item.group && item.group !== rows[i - 1]?.item.group
            ? item.group
            : null;
        const running = run?.id === item.id;
        const state = running ? run.state : null;
        return (
          <React.Fragment key={item.id}>
            {heading && (
              <div
                role="presentation"
                className={`px-3 pb-1 pt-2 text-[12px] font-medium text-muted-foreground ${i > 0 ? "mt-1 border-t border-border" : ""}`}
              >
                {heading}
              </div>
            )}
            <div
              ref={(el) => {
                if (rowRefs) rowRefs.current[i] = el;
              }}
              id={optionId?.(i)}
              role="option"
              aria-selected={i === active}
              aria-disabled={Boolean(run) || undefined}
              onPointerMove={() => i !== active && setActive?.(i)}
              onClick={() => choose?.(i)}
              className="relative flex cursor-pointer items-center gap-3 rounded-xl px-3 text-[13.5px] text-foreground/80"
              style={{ height: ROW }}
            >
              {item.icon && (
                <span
                  aria-hidden="true"
                  className="flex size-5 shrink-0 items-center justify-center text-muted-foreground [&_svg]:size-5 [&_svg]:stroke-[1.7] [&_img]:size-5 [&_img]:object-contain"
                >
                  {item.icon}
                </span>
              )}
              <span className="min-w-0 truncate">
                <Marked text={item.label} marks={row.marks} />
                {item.items && <span className="text-muted-foreground">…</span>}
              </span>
              {item.description && (
                <span className="hidden min-w-0 flex-1 truncate text-[12px] text-muted-foreground sm:block">
                  {item.description}
                </span>
              )}
              {/* The right edge: shortcut or chevron, which blurs into a spinner and then a check while it runs. */}
              <span className="relative ml-auto flex h-5 shrink-0 items-center justify-end">
                <span
                  className="flex items-center gap-1"
                  style={swap(!state, reduced)}
                >
                  {item.items ? (
                    <svg
                      aria-hidden="true"
                      viewBox="0 0 12 12"
                      className="size-3 text-muted-foreground"
                    >
                      <path
                        d="m4.5 2.5 3.5 3.5-3.5 3.5"
                        fill="none"
                        stroke="currentColor"
                        strokeWidth="1.4"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                      />
                    </svg>
                  ) : (
                    item.shortcut?.map((k) => <Kbd key={k}>{k}</Kbd>)
                  )}
                </span>
                <span
                  aria-hidden="true"
                  className="absolute inset-y-0 right-0 flex items-center"
                  style={swap(state === "pending", reduced)}
                >
                  <span
                    className={`size-3.5 rounded-full border-[1.5px] border-border border-t-foreground/70 motion-reduce:animate-none ${state === "pending" ? "animate-spin" : ""}`}
                  />
                </span>
                <span
                  aria-hidden="true"
                  className="absolute inset-y-0 right-0 flex items-center text-[var(--success,var(--color-emerald-600))]"
                  style={swap(state === "done", reduced)}
                >
                  <Check drawn={state === "done"} reduced={reduced} />
                </span>
              </span>
            </div>
          </React.Fragment>
        );
      })}
    </div>
  );
}

export function CommandPalette({
  items,
  placeholder = "Search or jump to…",
  hotkey = "k",
  searchLabel = "Search commands",
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  showTrigger = true,
  triggerLabel = "Search...",
  triggerIcon = <SearchIcon />,
  filters = [],
  filtersLabel = "Recent searches",
  onFilterRemove,
  footer,
  className = "",
  ...props
}: CommandPaletteProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const [phase, setPhase] = React.useState<Phase>(
    defaultOpen ? "open" : "closed",
  );
  const [query, setQuery] = React.useState("");
  const [stack, setStack] = React.useState<Page[]>([]);
  const [active, setActive] = React.useState(0);
  const [run, setRun] = React.useState<RunState | null>(null);
  const [from, setFrom] = React.useState<Rect | null>(null);
  const [listHeight, setListHeight] = React.useState(0);
  const [highlight, setHighlight] = React.useState({
    top: 0,
    ready: false,
    depth: 0,
  });
  const [leaving, setLeaving] = React.useState<
    { key: number; rows: Row[]; active: number; dir: number; top: number }[]
  >([]);
  const [enterDir, setEnterDir] = React.useState(0);
  const [portal, setPortal] = React.useState<HTMLElement | null>(null);

  const [viewport, setViewport] = React.useState({
    width: 0,
    height: 0,
    top: 0,
  });
  const overlayRef = React.useRef<HTMLDivElement>(null);
  const closeRef = React.useRef<HTMLButtonElement>(null);
  const footerRef = React.useRef<HTMLDivElement>(null);
  const [footerHeight, setFooterHeight] = React.useState(48);
  const wasMounted = React.useRef(false);
  const triggerRef = React.useRef<HTMLButtonElement>(null);
  const inputRef = React.useRef<HTMLInputElement>(null);
  const listRef = React.useRef<HTMLDivElement>(null);
  const innerRef = React.useRef<HTMLDivElement>(null);
  const paneRef = React.useRef<HTMLDivElement>(null);
  const rowRefs = React.useRef<(HTMLDivElement | null)[]>([]);
  const returnFocus = React.useRef<HTMLElement | null>(null);
  const timer = React.useRef(0);
  const commandRun = React.useRef<AbortController | null>(null);
  const failureMotion = React.useRef<Animation | null>(null);
  const [error, setError] = React.useState("");
  const leaveKey = React.useRef(0);

  const isOpen = phase === "open";
  const mounted = phase !== "closed";
  const page = stack[stack.length - 1];
  const pageItems = page ? page.items : items;
  const rows = React.useMemo(() => rank(pageItems, query), [pageItems, query]);

  React.useEffect(() => {
    // Browser-only portal discovery after hydration.

    setPortal(document.body);
  }, []);

  // Where the pill is, so the palette can grow out of it (and fold back into it).
  const pillRect = (): Rect | null => {
    const el = triggerRef.current;
    if (!el || !showTrigger) return null;
    const r = el.getBoundingClientRect();
    // Off screen, or hidden (a pill tucked away on narrow screens has no box): open in place instead.
    if (!r.width || r.bottom < 0 || r.top > window.innerHeight) return null;
    return {
      left: r.left,
      top: r.top,
      width: r.width,
      height: r.height,
      radius: parseFloat(getComputedStyle(el).borderTopLeftRadius),
    };
  };

  const target = (): Rect => {
    const vw = viewport.width || document.documentElement.clientWidth;
    const vh = viewport.height || window.innerHeight;
    const width = Math.min(WIDTH, vw - 24);
    const compactTop = Math.max(16, Math.min(96, Math.round(vh * 0.16)));
    // Shorten travel when the full result area fits, without taking space from
    // the list on short screens. Reserve the maximum height so searching or
    // entering a nested page does not move the shell's anchor.
    const fullHeight = 52 + LIST_MAX + 12 + footerHeight;
    const top = Math.max(
      compactTop,
      Math.min(160, Math.round(vh * 0.16), vh - fullHeight - 16),
    );
    return {
      left: (vw - width) / 2,
      top: viewport.top + top,
      width,
      height: 0,
      radius: 14,
    };
  };

  // Reset before mounting the input. A post-mount effect can erase typing
  // delivered during the opening frames, making Enter choose the wrong row.
  const resetSession = React.useCallback(() => {
    commandRun.current?.abort();
    failureMotion.current?.cancel();
    window.clearTimeout(timer.current);
    setError("");
    setQuery("");
    setStack([]);
    setActive(0);
    setRun(null);
    setLeaving([]);
    setHighlight({ top: 0, ready: false, depth: 0 });
  }, []);

  const setOpen = React.useCallback(
    (next: boolean) => {
      if (!next) {
        commandRun.current?.abort();
        failureMotion.current?.cancel();
      }
      if (openProp === undefined) {
        window.clearTimeout(timer.current);
        if (next) {
          if (phase === "closed") {
            returnFocus.current = document.activeElement as HTMLElement | null;
            resetSession();
          }
          setFrom(pillRect());
          setPhase(reduced ? "open" : "opening");
        } else {
          setFrom(pillRect());
          if (reduced) setPhase("closed");
          else {
            setPhase("closing");
            timer.current = window.setTimeout(
              () => setPhase("closed"),
              CLOSE_DURATION,
            );
          }
        }
      }
      onOpenChange?.(next);
    },

    [openProp, onOpenChange, reduced, showTrigger, phase, resetSession],
  );

  // Controlled: follow the prop through the same phases.
  React.useEffect(() => {
    if (openProp === undefined) return;
    window.clearTimeout(timer.current);
    if (openProp && (phase === "closed" || phase === "closing")) {
      if (phase === "closed") {
        returnFocus.current = document.activeElement as HTMLElement | null;
        // Synchronize the controlled prop before exposing a new search session.

        resetSession();
      }
      setFrom(pillRect());
      setPhase(reduced ? "open" : "opening");
    } else if (!openProp && (phase === "open" || phase === "opening")) {
      commandRun.current?.abort();
      failureMotion.current?.cancel();
      setFrom(pillRect());
      if (reduced) setPhase("closed");
      else {
        setPhase("closing");
        timer.current = window.setTimeout(
          () => setPhase("closed"),
          CLOSE_DURATION,
        );
      }
    }
  }, [openProp]);

  // Paint at the pill's size first, then let it grow.
  React.useEffect(() => {
    if (phase !== "opening") return;
    let inner = 0;
    const outer = requestAnimationFrame(
      () => (inner = requestAnimationFrame(() => setPhase("open"))),
    );
    return () => {
      cancelAnimationFrame(outer);
      cancelAnimationFrame(inner);
    };
  }, [phase]);

  // Accept typing from the first mounted frame, including while the pill grows.
  React.useLayoutEffect(() => {
    if (mounted) inputRef.current?.focus({ preventScroll: true });
  }, [mounted, portal]);

  React.useEffect(
    () => () => {
      window.clearTimeout(timer.current);
      commandRun.current?.abort();
      failureMotion.current?.cancel();
    },
    [],
  );

  // The page behind stays where it is.
  React.useEffect(() => {
    if (!mounted) return;
    const html = document.documentElement;
    const gap = window.innerWidth - html.clientWidth;
    const before = {
      overflow: html.style.overflow,
      paddingRight: html.style.paddingRight,
    };
    html.style.overflow = "hidden";
    if (gap > 0) html.style.paddingRight = `${gap}px`;
    return () => {
      html.style.overflow = before.overflow;
      html.style.paddingRight = before.paddingRight;
    };
  }, [mounted]);

  // Keep the background inert for the full morph, then restore focus after
  // that inert state is released (including controlled and reduced-motion close).
  React.useEffect(() => {
    if (!mounted || !overlayRef.current) return;
    const siblings = Array.from(document.body.children).filter(
      (el): el is HTMLElement =>
        el instanceof HTMLElement &&
        el !== overlayRef.current &&
        !el.contains(overlayRef.current),
    );
    const before = siblings.map((el) => el.inert);
    siblings.forEach((el) => {
      el.inert = true;
    });
    return () =>
      siblings.forEach((el, i) => {
        el.inert = before[i];
      });
  }, [mounted, portal]);

  React.useEffect(() => {
    if (mounted) {
      wasMounted.current = true;
      return;
    }
    if (!wasMounted.current) return;
    wasMounted.current = false;
    const back = returnFocus.current;
    const frame = requestAnimationFrame(() =>
      (back && document.contains(back) ? back : triggerRef.current)?.focus({
        preventScroll: true,
      }),
    );
    return () => cancelAnimationFrame(frame);
  }, [mounted]);

  React.useEffect(() => {
    if (!mounted) return;
    const measure = () =>
      setViewport({
        width: document.documentElement.clientWidth,
        height: window.visualViewport?.height ?? window.innerHeight,
        top: window.visualViewport?.offsetTop ?? 0,
      });
    measure();
    window.addEventListener("resize", measure);
    window.visualViewport?.addEventListener("resize", measure);
    window.visualViewport?.addEventListener("scroll", measure);
    return () => {
      window.removeEventListener("resize", measure);
      window.visualViewport?.removeEventListener("resize", measure);
      window.visualViewport?.removeEventListener("scroll", measure);
    };
  }, [mounted]);

  // Switching preferences during a transition settles it without clearing the query.
  React.useLayoutEffect(() => {
    if (!reduced) return;
    failureMotion.current?.cancel();
    window.clearTimeout(timer.current);
    // Settle an in-flight animation immediately when the OS preference changes.

    setPhase((value) =>
      value === "closing" ? "closed" : value === "opening" ? "open" : value,
    );
    setLeaving((value) => (value.length ? [] : value));
  }, [reduced]);

  // The list's height, so the panel can ease to fit the results.
  React.useLayoutEffect(() => {
    const el = innerRef.current;
    if (!el) return;
    const measure = () =>
      setListHeight((h) => (h === el.offsetHeight ? h : el.offsetHeight));
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, [mounted, portal]);

  React.useLayoutEffect(() => {
    const el = footerRef.current;
    if (!el) return;
    const measure = () => setFooterHeight(el.getBoundingClientRect().height);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, [mounted, portal]);

  // Keep the active row in range as the results change.
  React.useEffect(() => {
    // Clamp keyboard selection after an external catalog update.

    setActive((a) => Math.min(a, Math.max(0, rows.length - 1)));
  }, [rows.length]);

  // The highlight glides to the active row; the list scrolls only as far as it must.
  React.useLayoutEffect(() => {
    const row = rowRefs.current[active];
    const list = listRef.current;
    const pane = paneRef.current;
    if (!row || !list || !pane) return;
    // The highlight belongs to this pane, so it shares the rows' coordinates
    // and slide transform. Scrolling still uses the full list-content offset.
    const top = row.offsetTop;
    const listTop = pane.offsetTop + top;
    setHighlight((h) =>
      h.top === top && h.ready && h.depth === stack.length
        ? h
        : {
            top,
            // A new page takes its initial position without gliding from the
            // previous page. Subsequent selection changes still animate.
            ready: h.depth === stack.length && (h.ready || isOpen),
            depth: stack.length,
          },
    );
    if (active === 0) list.scrollTop = 0;
    else if (listTop < list.scrollTop) list.scrollTop = listTop - 4;
    else if (listTop + ROW > list.scrollTop + list.clientHeight)
      list.scrollTop = listTop + ROW - list.clientHeight + 4;
  }, [active, rows, isOpen, listHeight, stack.length]);

  // A new page slides in from the side you went.
  React.useLayoutEffect(() => {
    if (!enterDir || reduced) return;
    const animation = paneRef.current?.animate(
      [
        {
          opacity: 0,
          filter: "blur(4px)",
          transform: `translateX(${enterDir * 28}px)`,
        },
        { opacity: 1, filter: "blur(0px)", transform: "none" },
      ],
      { duration: 360, easing: EASE, delay: 40, fill: "backwards" },
    );
    return () => animation?.cancel();
  }, [stack.length, enterDir, reduced]);

  React.useEffect(() => {
    if (!leaving.length) return;
    const t = window.setTimeout(() => setLeaving([]), 260);
    return () => window.clearTimeout(t);
  }, [leaving]);

  const go = (dir: 1 | -1, next: Page[]) => {
    if (!reduced)
      setLeaving((l) => [
        ...l,
        {
          key: ++leaveKey.current,
          rows,
          active,
          dir,
          top: paneRef.current?.offsetTop ?? 0,
        },
      ]);
    setEnterDir(dir);
    setStack(next);
    setQuery("");
    setActive(0);
    setHighlight((h) => ({ ...h, ready: false }));
  };

  const choose = async (i: number) => {
    const row = rows[i];
    if (!row || run) return;
    const { item } = row;
    setActive(i);
    if (item.items)
      return go(1, [
        ...stack,
        { title: item.label.replace(/…$/, ""), items: item.items },
      ]);
    if (item.href && !item.onSelect) {
      setOpen(false);
      window.location.assign(item.href);
      return;
    }
    commandRun.current?.abort();
    const controller = new AbortController();
    failureMotion.current?.cancel();
    commandRun.current = controller;
    setError("");
    try {
      const result = item.onSelect?.({ signal: controller.signal });
      if (!result) return setOpen(false);
      setRun({ id: item.id, state: "pending" });
      await result;
      if (controller.signal.aborted) return;
      setRun({ id: item.id, state: "done" });
      timer.current = window.setTimeout(
        () => setOpen(false),
        reduced ? 0 : 520,
      );
    } catch {
      if (controller.signal.aborted) return;
      setError(`${item.label} failed. Try again.`);
      setRun(null);
      if (!reduced)
        failureMotion.current =
          rowRefs.current[i]?.animate(
            [
              { transform: "none" },
              { transform: "translateX(-4px)" },
              { transform: "translateX(4px)" },
              { transform: "translateX(-2px)" },
              { transform: "none" },
            ],
            { duration: 380, easing: "ease-out" },
          ) ?? null;
    }
  };

  const onKeyDown = (e: React.KeyboardEvent) => {
    if (e.nativeEvent.isComposing) return;
    if (e.key === "Tab") {
      const controls = Array.from(
        overlayRef.current?.querySelectorAll<HTMLElement>(
          'input, button:not(:disabled), a[href], [tabindex="0"]',
        ) ?? [],
      ).filter(
        (el) => !el.closest("[inert]") && el.getClientRects().length > 0,
      );
      const index = controls.indexOf(document.activeElement as HTMLElement);
      e.preventDefault();
      controls[
        (index + (e.shiftKey ? -1 : 1) + controls.length) % controls.length
      ]?.focus();
      return;
    }
    if (e.key !== "Escape" && e.target !== inputRef.current) return;
    const moves: Record<string, number> = {
      ArrowDown: active + 1,
      ArrowUp: active - 1,
      Home: 0,
      End: rows.length - 1,
    };
    if (e.key in moves && rows.length) {
      if ((e.key === "Home" || e.key === "End") && query) return;
      e.preventDefault();
      setActive((moves[e.key] + rows.length) % rows.length);
    } else if (e.key === "Enter") {
      e.preventDefault();
      choose(active);
    } else if (e.key === "Escape") {
      e.preventDefault();
      if (query) setQuery("");
      else if (stack.length) go(-1, stack.slice(0, -1));
      else setOpen(false);
    } else if (e.key === "Backspace" && !query && stack.length) {
      e.preventDefault();
      go(-1, stack.slice(0, -1));
    }
  };

  const duration = phase === "closing" ? CLOSE_DURATION : OPEN_DURATION;
  const final = mounted && portal ? target() : null;
  const shape = isOpen || !from ? final : from;
  const listVisible = Math.min(
    listHeight,
    LIST_MAX,
    Math.max(
      40,
      (viewport.height || 600) -
        ((final?.top ?? 0) - viewport.top) -
        52 -
        footerHeight -
        28,
    ),
  );
  const panelHeight = 52 + (listVisible ? listVisible + 12 : 0) + footerHeight;
  const empty = rows.length === 0;

  const triggerContent = (
    <>
      {triggerIcon && (
        <span
          aria-hidden="true"
          className="flex size-4 shrink-0 items-center justify-center [&_svg]:size-4 [&_img]:size-4"
        >
          {triggerIcon}
        </span>
      )}
      {triggerLabel}
    </>
  );

  const panel =
    mounted && final && shape ? (
      <div
        ref={overlayRef}
        className="cavemio-command-palette fixed inset-0 z-[100]"
        onKeyDown={onKeyDown}
        data-phase={phase}
      >
        {/* A faint veil over the page; clicking it closes. */}
        <div
          aria-hidden="true"
          onPointerDown={() => setOpen(false)}
          className="absolute inset-0 bg-background/55"
          style={{
            opacity: isOpen ? 1 : 0,
            transition: reduced ? "none" : `opacity ${duration}ms ${EASE}`,
          }}
        />
        <div
          role="dialog"
          aria-modal="true"
          aria-label="Command palette"
          className="absolute overflow-hidden bg-popover text-popover-foreground"
          style={{
            left: shape.left,
            top: shape.top,
            width: shape.width,
            height: isOpen || !from ? panelHeight : from.height,
            borderRadius: shape.radius,
            backgroundColor: !isOpen && from ? "transparent" : "var(--popover)",
            boxShadow: "inset 0 0 0 1px var(--border)",
            opacity: !from && !isOpen ? 0 : 1,
            transform:
              !from && !isOpen ? "scale(0.97) translateY(-6px)" : "none",
            transition: reduced
              ? "none"
              : `left ${duration}ms ${EASE}, top ${duration}ms ${EASE}, width ${duration}ms ${EASE}, height ${duration}ms ${EASE}, border-radius ${duration}ms ${EASE}, background-color ${duration}ms ${EASE}, opacity 240ms ${EASE}, transform ${duration}ms ${EASE}`,
          }}
        >
          {(run || error) && (
            <p role="status" className="sr-only">
              {run
                ? `${rows.find((row) => row.item.id === run.id)?.item.label ?? "Command"}: ${run.state === "pending" ? "Running" : "Complete"}`
                : error}
            </p>
          )}
          {/* The pill's face, hotkey and all, fading as the panel grows out of it and back as it folds in. */}
          {from && (
            <span
              aria-hidden="true"
              data-command-trigger-copy=""
              className="pointer-events-none absolute left-0 top-0 flex items-center whitespace-nowrap"
              style={{
                height: from.height,
                opacity: isOpen ? 0 : 1,
                transition: reduced
                  ? "none"
                  : isOpen
                    ? "opacity 100ms ease-out"
                    : "opacity 140ms ease-out 160ms",
              }}
            >
              <Kbd hotkey={hotkey} label={triggerContent} />
            </span>
          )}

          <div
            inert={phase === "closing"}
            className="absolute left-0 top-0 flex flex-col"
            style={{
              width: final.width,
              opacity: isOpen ? 1 : 0,
              transition: reduced
                ? "none"
                : isOpen
                  ? "opacity 240ms ease-out 60ms"
                  : "opacity 100ms ease-out",
            }}
          >
            <div className="flex h-[52px] shrink-0 items-center gap-2.5 border-b border-border px-5">
              <SearchIcon className="text-muted-foreground" />
              {/* Where you are, as a chip that opens in when you go into a list. */}
              <span
                className="grid shrink-0"
                style={{
                  gridTemplateColumns: page ? "1fr" : "0fr",
                  opacity: page ? 1 : 0,
                  transition: reduced
                    ? "none"
                    : `grid-template-columns 360ms ${EASE}, opacity 240ms ${EASE}`,
                }}
              >
                <span className="min-w-0 overflow-hidden">
                  <span className="mr-0.5 flex h-6 items-center whitespace-nowrap rounded-md bg-muted px-2 text-[12px] font-medium text-foreground">
                    <TextMorph>{page?.title ?? ""}</TextMorph>
                  </span>
                </span>
              </span>
              <input
                ref={inputRef}
                value={query}
                onChange={(e) => {
                  setQuery(e.target.value);
                  setActive(0);
                }}
                placeholder={
                  page ? `Search ${page.title.toLowerCase()}…` : placeholder
                }
                aria-label={searchLabel}
                role="combobox"
                aria-expanded="true"
                aria-controls={`${id}-list`}
                aria-activedescendant={
                  rows.length ? `${id}-opt-${active}` : undefined
                }
                aria-autocomplete="list"
                spellCheck={false}
                className="h-full min-w-0 flex-1 bg-transparent text-[14.5px] text-foreground outline-none placeholder:text-muted-foreground"
              />
              <button
                ref={closeRef}
                type="button"
                aria-label="Close search"
                onClick={() => setOpen(false)}
                className={`rounded-md p-1 ${FOCUS}`}
              >
                <Kbd>esc</Kbd>
              </button>
            </div>

            <div
              ref={listRef}
              className="relative overflow-y-auto overscroll-contain px-2 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
              style={{
                height: listVisible ? listVisible + 12 : 0,
                transition:
                  reduced || !isOpen ? "none" : `height 300ms ${EASE}`,
              }}
            >
              <div ref={innerRef} className="relative py-1.5">
                {!page && filters.length > 0 && (
                  <div
                    className="border-b border-border px-3 py-2"
                    data-command-filters=""
                  >
                    <p className="mb-1 text-[12px] font-medium text-muted-foreground">
                      {filtersLabel}
                    </p>
                    <div className="flex flex-wrap gap-2">
                      {filters.map((filter) => (
                        <button
                          key={filter.id}
                          type="button"
                          aria-label={`Remove ${filter.label} filter`}
                          disabled={!onFilterRemove}
                          onClick={() => {
                            inputRef.current?.focus({ preventScroll: true });
                            onFilterRemove?.(filter.id);
                            setActive(0);
                          }}
                          className={`flex min-h-8 max-w-full items-center gap-1.5 rounded-lg bg-muted px-2.5 text-[12px] text-muted-foreground enabled:cursor-pointer enabled:hover:bg-accent enabled:hover:text-foreground ${FOCUS}`}
                        >
                          {filter.icon && (
                            <span
                              aria-hidden="true"
                              className="flex size-4 shrink-0 items-center justify-center [&_svg]:size-4 [&_img]:size-4"
                            >
                              {filter.icon}
                            </span>
                          )}
                          <span className="truncate">{filter.label}</span>
                          {onFilterRemove && (
                            <svg
                              aria-hidden="true"
                              viewBox="0 0 16 16"
                              fill="none"
                              className="size-3.5 shrink-0"
                            >
                              <path
                                d="m4 4 8 8M12 4l-8 8"
                                stroke="currentColor"
                                strokeWidth="1.5"
                                strokeLinecap="round"
                              />
                            </svg>
                          )}
                        </button>
                      ))}
                    </div>
                  </div>
                )}
                {leaving.map((l) => (
                  <LeavingPane key={l.key} dir={l.dir} top={l.top}>
                    <Results
                      rows={l.rows}
                      active={l.active}
                      run={null}
                      reduced={reduced}
                    />
                  </LeavingPane>
                ))}
                <div ref={paneRef} key={stack.length} className="relative">
                  {!empty && (
                    <span
                      aria-hidden="true"
                      data-command-highlight=""
                      className="absolute inset-x-0 rounded-xl bg-accent"
                      style={{
                        top: 0,
                        height: ROW,
                        transform: `translateY(${highlight.top}px)`,
                        transition:
                          highlight.ready && !reduced
                            ? `transform 200ms ${EASE}`
                            : "none",
                      }}
                    />
                  )}
                  <Results
                    rows={rows}
                    active={active}
                    run={run}
                    reduced={reduced}
                    listId={`${id}-list`}
                    optionId={(i) => `${id}-opt-${i}`}
                    setActive={(i) => !run && setActive(i)}
                    choose={choose}
                    rowRefs={rowRefs}
                  />
                </div>
                {empty && (
                  <p
                    role="status"
                    className="flex min-w-0 items-center overflow-hidden px-3 text-[13px] text-muted-foreground"
                    style={{ height: ROW }}
                  >
                    <TextMorph>
                      {query
                        ? `No results for “${query.trim()}”`
                        : "Nothing here yet"}
                    </TextMorph>
                  </p>
                )}
              </div>
            </div>

            <div
              ref={footerRef}
              className="flex min-h-12 shrink-0 flex-wrap items-center justify-between gap-x-6 gap-y-3 border-t border-border px-5 py-3 text-[12px] text-muted-foreground"
            >
              <div className="flex flex-wrap items-center gap-x-3 gap-y-2">
                <span className="flex items-center gap-1.5">
                  <Kbd>↑</Kbd>
                  <Kbd>↓</Kbd>Navigate
                </span>
                <span className="flex items-center gap-1.5">
                  <Kbd>↵</Kbd>Select
                </span>
                {page && (
                  <span className="flex items-center gap-1.5">
                    <Kbd>⌫</Kbd>Back
                  </span>
                )}
              </div>
              {footer && (
                <div
                  data-command-footer=""
                  className="min-w-0 leading-5 [&_a]:underline [&_a]:underline-offset-4 [&_a:focus-visible]:outline [&_a:focus-visible]:outline-2 [&_a:focus-visible]:outline-ring"
                >
                  {footer}
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    ) : null;

  return (
    <div className={`inline-flex ${className}`} {...props}>
      <Kbd
        ref={triggerRef}
        hotkey={hotkey}
        label={triggerContent}
        onTrigger={(event) =>
          setOpen(
            event.type === "click" ||
              !(phase === "open" || phase === "opening"),
          )
        }
        stopPropagation
        hidden={!showTrigger}
        aria-label={triggerLabel}
        aria-haspopup="dialog"
        aria-expanded={isOpen}
        style={{
          display: showTrigger ? undefined : "none",
          opacity: mounted ? 0 : 1,
          transition:
            mounted || reduced || from ? "none" : "opacity 160ms ease-out",
        }}
      />
      {portal && panel ? createPortal(panel, portal) : null}
    </div>
  );
}

/** The page you left: it slides out toward the side you came from, then removes itself. */
function LeavingPane({
  dir,
  top,
  children,
}: {
  dir: number;
  top: number;
  children: React.ReactNode;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  React.useLayoutEffect(() => {
    const animation = ref.current?.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        {
          opacity: 0,
          filter: "blur(4px)",
          transform: `translateX(${-dir * 28}px)`,
        },
      ],
      { duration: 240, easing: EASE, fill: "forwards" },
    );
    return () => animation?.cancel();
  }, [dir]);
  return (
    <div
      ref={ref}
      inert
      aria-hidden="true"
      className="pointer-events-none absolute inset-x-0"
      style={{ top }}
    >
      {children}
    </div>
  );
}

"use client";

import * as React from "react";
import { Price, PricingToggle } from "./pricing-toggle";

/* ─────────────────────────────────────────────────────────
 * COMPARISON TABLE: plans side by side, and one that stands out
 *
 *   rest      the recommended plan sits in a thin line column that
 *             runs the height of the table
 *   point     move across the table and the column glides to the
 *             plan under you with a little give, then settles
 *             back when you leave
 *   billing   Monthly/Yearly is thrown to the choice and every
 *             price rolls; the note under it slides the same way
 *   groups    each section folds open and shut to its height
 *   phone     one plan at a time: a switch is thrown to the plan
 *             and its column slides in from the side you went
 *
 * Header stays at the top while the features scroll past.
 * ───────────────────────────────────────────────────────── */

export interface ComparisonPlan {
  id: string;
  name: string;
  /** Monthly price, or { monthly, yearly } per month; null for "Custom". */
  price: number | { monthly: number; yearly: number } | null;
  description?: string;
  /** The column that's highlighted at rest. */
  featured?: boolean;
  badge?: string;
  cta?: { label: string; href?: string; onClick?: () => void };
}

export type ComparisonValue = boolean | string | number | null | undefined;

export interface ComparisonRow {
  label: string;
  hint?: string;
  values: Record<string, ComparisonValue>;
}

export interface ComparisonGroup {
  title: string;
  rows: ComparisonRow[];
  /** Start folded. */
  collapsed?: boolean;
}

export interface ComparisonTableProps extends React.HTMLAttributes<HTMLDivElement> {
  plans: ComparisonPlan[];
  groups: ComparisonGroup[];
  currency?: string;
  /** Shows a Monthly/Yearly switch, e.g. "Save 20%". */
  yearlyBadge?: string;
  /** How far from the top the header sticks (e.g. under a fixed navbar). */
  stickyTop?: number;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function Cell({ value }: { value: ComparisonValue }) {
  if (value === true)
    return (
      <svg
        role="img"
        aria-label="Included"
        viewBox="0 0 16 16"
        fill="none"
        className="size-4 text-foreground"
      >
        <path
          d="M3.5 8.5 6.5 11.5 12.5 4.5"
          stroke="currentColor"
          strokeWidth="1.8"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </svg>
    );
  if (value === false || value === null || value === undefined)
    return (
      <svg
        role="img"
        aria-label="Not included"
        viewBox="0 0 16 16"
        fill="none"
        className="size-4 text-muted-foreground/45"
      >
        <path
          d="M4.5 8h7"
          stroke="currentColor"
          strokeWidth="1.6"
          strokeLinecap="round"
        />
      </svg>
    );
  return <span className="text-[13px] text-foreground">{value}</span>;
}

export function ComparisonTable({
  plans,
  groups,
  currency = "USD",
  yearlyBadge,
  stickyTop = 0,
  className = "",
  ...props
}: ComparisonTableProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const [billing, setBilling] = React.useState("monthly");
  const [billingDir, setBillingDir] = React.useState(1);
  const [hover, setHover] = React.useState<number | null>(null);
  const [selected, setSelected] = React.useState(() =>
    Math.max(
      0,
      plans.findIndex((p) => p.featured),
    ),
  );
  const [dir, setDir] = React.useState(1);
  const [open, setOpen] = React.useState(() => groups.map((g) => !g.collapsed));
  const [cols, setCols] = React.useState<{ left: number; width: number }[]>([]);
  const [ready, setReady] = React.useState(false);
  const headRefs = React.useRef<(HTMLDivElement | null)[]>([]);
  const headerRef = React.useRef<HTMLDivElement>(null);
  const [headerHeight, setHeaderHeight] = React.useState(0);
  const switchRefs = React.useRef<(HTMLButtonElement | null)[]>([]);
  const [thumb, setThumb] = React.useState({ left: 0, width: 0 });

  const featured = plans.findIndex((p) => p.featured);
  const lit = hover ?? (featured >= 0 ? featured : null);
  const template = `minmax(9.5rem,1.35fr) repeat(${plans.length}, minmax(0,1fr))`;

  // Where each plan's column is, so the highlight can glide between them.
  React.useLayoutEffect(() => {
    const measure = () => {
      const next = headRefs.current.map((el) => ({
        left: el?.offsetLeft ?? 0,
        width: el?.offsetWidth ?? 0,
      }));
      setCols((c) =>
        c.length === next.length &&
        c.every((x, i) => x.left === next[i].left && x.width === next[i].width)
          ? c
          : next,
      );
      setHeaderHeight((h) =>
        h === headerRef.current?.offsetHeight
          ? h
          : (headerRef.current?.offsetHeight ?? 0),
      );
    };
    measure();
    const observer = new ResizeObserver(measure);
    headRefs.current.forEach((el) => el && observer.observe(el));
    if (headerRef.current) observer.observe(headerRef.current);
    const frame = requestAnimationFrame(() => setReady(true));
    return () => {
      observer.disconnect();
      cancelAnimationFrame(frame);
    };
  }, [plans.length]);

  // The phone switch's thumb.
  React.useLayoutEffect(() => {
    const el = switchRefs.current[selected];
    if (el)
      setThumb((t) =>
        t.left === el.offsetLeft && t.width === el.offsetWidth
          ? t
          : { left: el.offsetLeft, width: el.offsetWidth },
      );
  }, [selected, plans.length]);

  const pick = (i: number) => {
    setDir(i >= selected ? 1 : -1);
    setSelected(i);
  };

  const onMove = (e: React.PointerEvent) => {
    if (e.pointerType === "touch") return;
    const x =
      e.clientX - (e.currentTarget as HTMLElement).getBoundingClientRect().left;
    const i = cols.findIndex(
      (c) => x >= c.left - 6 && x <= c.left + c.width + 6,
    );
    setHover(i >= 0 ? i : null);
  };

  const column = lit !== null ? cols[lit] : undefined;
  const glide =
    ready && !reduced
      ? `transform 520ms ${THROW}, width 420ms ${EASE}, opacity 300ms ${EASE}`
      : "none";
  // On a phone only the chosen plan shows; it slides in from the side you went.
  const phone = (i: number) =>
    i === selected
      ? `@max-[36rem]:block ${dir > 0 ? "@max-[36rem]:animate-[ui-slide-from-right_360ms_cubic-bezier(0.16,1,0.3,1)_both]" : "@max-[36rem]:animate-[ui-slide-from-left_360ms_cubic-bezier(0.16,1,0.3,1)_both]"} motion-reduce:animate-none`
      : "@max-[36rem]:hidden";

  const priceOf = (plan: ComparisonPlan) =>
    plan.price === null
      ? null
      : typeof plan.price === "number"
        ? plan.price
        : billing === "yearly"
          ? plan.price.yearly
          : plan.price.monthly;

  return (
    // Laid out by its own width, not the screen's, so it reads right in a narrow column too.
    <div className="w-full">
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 880px)" }}
      />
      <div className="@container w-full">
        <div className={`w-full ${className}`} {...props}>
          <div className="mb-6 flex flex-wrap items-center justify-between gap-3">
            {yearlyBadge && (
              <PricingToggle
                value={billing}
                onValueChange={(v) => {
                  setBillingDir(v === "yearly" ? 1 : -1);
                  setBilling(v);
                }}
                options={[
                  { value: "monthly", label: "Monthly" },
                  { value: "yearly", label: "Yearly", badge: yearlyBadge },
                ]}
              />
            )}
            {/* Phones: one plan at a time. */}
            <div
              role="tablist"
              aria-label="Plan"
              className="relative inline-flex rounded-full bg-muted p-0.5 @[36rem]:hidden"
            >
              <span
                aria-hidden="true"
                className="absolute inset-y-0.5 left-0 rounded-full bg-background shadow-[0_0_0_1px_var(--border)]"
                style={{
                  width: thumb.width,
                  transform: `translateX(${thumb.left}px)`,
                  transition:
                    thumb.width && !reduced
                      ? `transform 460ms ${THROW}, width 380ms ${EASE}`
                      : "none",
                }}
              />
              {plans.map((p, i) => (
                <button
                  key={p.id}
                  ref={(el) => {
                    switchRefs.current[i] = el;
                  }}
                  type="button"
                  role="tab"
                  aria-selected={i === selected}
                  onClick={() => pick(i)}
                  className={`cursor-pointer relative h-8 rounded-full px-3.5 text-[12.5px] font-medium transition-colors duration-300 ${FOCUS} ${i === selected ? "text-foreground" : "text-muted-foreground"}`}
                >
                  {p.name}
                </button>
              ))}
            </div>
          </div>

          <div
            role="table"
            aria-label="Plan comparison"
            className="relative"
            onPointerMove={onMove}
            onPointerLeave={() => setHover(null)}
          >
            {/* The column that runs the height of the table and glides between plans: this part under the header… */}
            <span
              aria-hidden="true"
              className="pointer-events-none absolute bottom-0 left-0 hidden rounded-b-[18px] bg-accent/60 shadow-[inset_1px_0_0_0_var(--border),inset_-1px_0_0_0_var(--border),inset_0_-1px_0_0_var(--border)] @[36rem]:block"
              style={{
                top: headerHeight,
                width: column?.width ?? 0,
                transform: `translateX(${column?.left ?? 0}px)`,
                opacity: column ? 1 : 0,
                transition: glide,
              }}
            />

            {/* Plan headers, kept in view while the features scroll by. */}
            <div
              ref={headerRef}
              role="rowgroup"
              className="sticky z-10 bg-background"
              style={{ top: stickyTop }}
            >
              {/* …and this part in the header, gliding in step, so the column reads as one even while the header sticks. */}
              <span
                aria-hidden="true"
                className="pointer-events-none absolute inset-y-0 left-0 hidden rounded-t-[18px] bg-accent/60 shadow-[inset_1px_0_0_0_var(--border),inset_-1px_0_0_0_var(--border),inset_0_1px_0_0_var(--border)] @[36rem]:block"
                style={{
                  width: column?.width ?? 0,
                  transform: `translateX(${column?.left ?? 0}px)`,
                  opacity: column ? 1 : 0,
                  transition: glide,
                }}
              />
              <div
                role="row"
                className="grid @max-[36rem]:!grid-cols-[minmax(0,1fr)_minmax(0,1.2fr)]"
                style={{ gridTemplateColumns: template }}
              >
                <div
                  role="columnheader"
                  className="flex items-end pb-5 pr-4 text-[12px] text-muted-foreground @max-[36rem]:hidden"
                >
                  <span className="sr-only">Feature</span>
                </div>
                {plans.map((plan, i) => {
                  const amount = priceOf(plan);
                  return (
                    <div
                      key={plan.id}
                      ref={(el) => {
                        headRefs.current[i] = el;
                      }}
                      role="columnheader"
                      aria-label={plan.name}
                      className={`relative px-4 pb-5 pt-5 @max-[36rem]:col-span-2 @max-[36rem]:px-0 ${phone(i)}`}
                    >
                      <div className="relative flex items-center gap-2">
                        <span className="text-[14px] font-medium text-foreground">
                          {plan.name}
                        </span>
                        {plan.badge && (
                          <span className="rounded-full bg-primary/10 px-2 py-px text-[11px] font-medium text-primary">
                            {plan.badge}
                          </span>
                        )}
                      </div>
                      {plan.description && (
                        <p className="relative mt-1 min-h-8 text-[12px] leading-4 text-muted-foreground">
                          {plan.description}
                        </p>
                      )}
                      <div className="relative mt-3">
                        {amount === null ? (
                          <p className="text-[28px] font-medium leading-[1.15] tracking-[-0.03em] text-foreground">
                            Custom
                          </p>
                        ) : (
                          <Price
                            amount={amount}
                            currency={currency}
                            direction={billingDir}
                            numberClassName="text-[28px] font-medium leading-[1.15] tracking-[-0.03em] text-foreground"
                          />
                        )}
                      </div>
                      {plan.cta && (
                        <a
                          href={plan.cta.href ?? "#"}
                          onClick={(e) => {
                            if (plan.cta?.onClick) {
                              e.preventDefault();
                              plan.cta.onClick();
                            }
                          }}
                          className={`relative mt-4 flex h-9 items-center justify-center rounded-full text-[13px] font-medium transition-[background-color,color,box-shadow] duration-300 ${FOCUS} ${
                            plan.featured
                              ? "bg-primary text-primary-foreground hover:bg-primary/90"
                              : "text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent"
                          }`}
                        >
                          {plan.cta.label}
                        </a>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>

            {groups.map((group, g) => {
              const isOpen = open[g];
              const groupId = `${id}-g${g}`;
              return (
                <div key={group.title} role="rowgroup">
                  <div role="row" className="relative">
                    <div role="rowheader" className="border-t border-border">
                      <button
                        type="button"
                        aria-expanded={isOpen}
                        aria-controls={groupId}
                        onClick={() =>
                          setOpen((o) => o.map((v, i) => (i === g ? !v : v)))
                        }
                        className={`cursor-pointer flex w-full items-center gap-2 rounded-md py-3.5 text-left text-[12.5px] font-medium text-foreground ${FOCUS}`}
                      >
                        <svg
                          aria-hidden="true"
                          viewBox="0 0 12 12"
                          className="size-3 text-muted-foreground transition-transform duration-300 motion-reduce:transition-none"
                          style={{
                            transform: isOpen ? "rotate(90deg)" : "none",
                            transitionTimingFunction: EASE,
                          }}
                        >
                          <path
                            d="m4.5 2.5 3.5 3.5-3.5 3.5"
                            fill="none"
                            stroke="currentColor"
                            strokeWidth="1.4"
