        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinejoin="round"
      />
      <circle cx="7.3" cy="8.6" r="1" fill="currentColor" />
      <circle cx="12.2" cy="13" r="1" fill="currentColor" />
