}

/** A button that confirms itself: a spinner while your server records it, then a drawn check and a new label. */
function ActionButton({
  label,
  doneLabel,
  stage,
  locked,
  tone,
  reduced,
  onClick,
  className = "",
}: {
  label: string;
  doneLabel: string;
  stage: "idle" | Work["stage"];
  locked: boolean;
  tone: keyof typeof TONES;
  reduced: boolean;
  onClick: () => void;
  className?: string;
}) {
  const on = stage !== "idle";
  return (
    <button
      type="button"
      onClick={() => !locked && onClick()}
      aria-disabled={(locked && !on) || undefined}
      aria-busy={stage === "busy" || undefined}
      className={`cursor-pointer disabled:cursor-default aria-disabled:cursor-default inline-flex h-8 shrink-0 items-center justify-center rounded-full px-3.5 text-[12.5px] font-medium transition-colors ${FOCUS} ${TONES[tone]} ${className}`}
    >
      <span
        aria-hidden="true"
        className="relative flex h-3.5 shrink-0 items-center justify-center"
        style={{
          width: on ? 14 : 0,
          marginRight: on ? 6 : 0,
          transition: reduced
            ? "none"
            : `width 320ms ${EASE}, margin 320ms ${EASE}`,
        }}
      >
        <span
          className={`absolute size-3 rounded-full border-[1.5px] border-current/30 border-t-current motion-reduce:animate-none ${stage === "busy" ? "animate-spin" : ""}`}
          style={{
            opacity: stage === "busy" ? 1 : 0,
            transition: reduced ? "none" : "opacity 200ms",
          }}
        />
        <svg
          viewBox="0 0 16 16"
          fill="none"
          className="absolute size-3.5"
          style={{ opacity: stage === "done" ? 1 : 0 }}
        >
          <path
            d="M3.5 8.5 6.5 11.5 12.5 4.5"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
            pathLength={1}
            strokeDasharray={1}
            style={{
              strokeDashoffset: stage === "done" ? 0 : 1,
              transition:
                stage === "done" && !reduced
                  ? `stroke-dashoffset 380ms ${EASE} 120ms`
                  : "none",
            }}
          />
        </svg>
      </span>
      <TextMorph>{stage === "done" ? doneLabel : label}</TextMorph>
    </button>
  );
}

function Switch({
  id,
  checked,
  describedBy,
  reduced,
  onChange,
}: {
  id: string;
  checked: boolean;
  describedBy: string;
  reduced: boolean;
  onChange: (on: boolean) => void;
}) {
  return (
    <button
      id={id}
      type="button"
      role="switch"
      aria-checked={checked}
      aria-describedby={describedBy}
      onClick={() => onChange(!checked)}
      className={`cursor-pointer relative mt-0.5 h-6 w-10 shrink-0 rounded-full ${FOCUS} ${checked ? "bg-primary" : "bg-muted shadow-[inset_0_0_0_1px_var(--border)]"}`}
      style={{
        transition: reduced ? "none" : `background-color 300ms ${EASE}`,
      }}
    >
      <span
        aria-hidden="true"
        className="absolute left-0.5 top-0.5 size-5 rounded-full bg-background shadow-[0_0_0_1px_var(--border)]"
        style={{
          transform: checked ? "translateX(16px)" : "none",
          transition: reduced ? "none" : `transform 400ms ${THROW}`,
        }}
      />
    </button>
  );
}

const subscribeNothing = () => () => {};

export function CookieBanner({
  categories = DEFAULT_CATEGORIES,
  message = "We use cookies to keep the site working and, if you agree, to see how it’s used.",
  policyHref,
  onConsentChange,
  storageKey = "cookie-consent",
  expiresAfter = 365,
  position = "bottom-left",
  strategy = "fixed",
  showReopen = true,
  className = "",
  ...props
}: CookieBannerProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const required = React.useCallback(
    () =>
      Object.fromEntries(categories.map((c) => [c.id, Boolean(c.required)])),
    [categories],
  );
  const [phase, setPhase] = React.useState<Phase>("hidden");
  const [work, setWork] = React.useState<Work | null>(null);
  const [choice, setChoice] = React.useState<CookieConsent>(required);
  const gpc = React.useSyncExternalStore(
    subscribeNothing,
    () =>
      Boolean(
        (navigator as Navigator & { globalPrivacyControl?: boolean })
          .globalPrivacyControl,
      ),
    () => false,
  );
  const [size, setSize] = React.useState({
    ask: { w: 0, h: 0 },
    prefs: { w: 0, h: 0 },
  });
  const [room, setRoom] = React.useState(432);
  const regionRef = React.useRef<HTMLDivElement>(null);
  const cardRef = React.useRef<HTMLDivElement>(null);
  const askRef = React.useRef<HTMLDivElement>(null);
  const prefsRef = React.useRef<HTMLDivElement>(null);
  const customiseRef = React.useRef<HTMLButtonElement>(null);
  const cornerRef = React.useRef<HTMLButtonElement>(null);
  const live = React.useRef({ phase, locked: false });
  const back = React.useRef<Phase>("ask");
  const saved = React.useRef<CookieConsent | null>(null);
  const focusTo = React.useRef<"prefs" | "ask" | "corner" | null>(null);
  const timers = React.useRef<number[]>([]);
  const change = React.useRef(onConsentChange);

  React.useEffect(() => {
    live.current.phase = phase;
    change.current = onConsentChange;
  });

  const later = (fn: () => void, ms: number) => {
    timers.current.push(window.setTimeout(fn, ms));
  };
  React.useEffect(() => () => timers.current.forEach(window.clearTimeout), []);

  // On load: a remembered, current choice goes straight to the corner button; otherwise ask.
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => {
      try {
        const stored = JSON.parse(
          localStorage.getItem(storageKey) ?? "null",
        ) as Saved | null;
        if (stored?.choices) {
          setChoice({ ...required(), ...stored.choices });
          const fresh = Date.now() - stored.savedAt < expiresAfter * 864e5;
          const complete = categories.every(
            (c) => c.required || c.id in stored.choices,
          );
          if (fresh && complete) {
            saved.current = stored.choices;
            change.current?.(stored.choices, "load");
            setPhase("folded");
            return;
          }
        }
      } catch {}
      setPhase("ask");
    });
    return () => cancelAnimationFrame(frame);
  }, [storageKey, categories, expiresAfter, required]);

  const visible = phase !== "hidden" && (phase !== "folded" || showReopen);

  // How much room there is: the window, or the parent when it's positioned inside one.
  React.useLayoutEffect(() => {
    if (!visible) return;
    const parent =
      strategy === "absolute" ? regionRef.current?.offsetParent : null;
    const fit = () =>
      setRoom(
        parent instanceof HTMLElement
          ? parent.clientWidth
          : document.documentElement.clientWidth,
      );
    fit();
    window.addEventListener("resize", fit);
    const observer =
      parent instanceof HTMLElement ? new ResizeObserver(fit) : null;
    if (parent instanceof HTMLElement) observer?.observe(parent);
    return () => {
      window.removeEventListener("resize", fit);
      observer?.disconnect();
    };
  }, [visible, strategy]);

  // The card's two open shapes, measured, so it can grow from one to the other.
  React.useLayoutEffect(() => {
    if (!visible) return;
    const measure = () => {
      const a = askRef.current;
      const p = prefsRef.current;
      setSize((s) => {
        const next = {
          ask: { w: a?.offsetWidth ?? 0, h: a?.offsetHeight ?? 0 },
          prefs: { w: p?.offsetWidth ?? 0, h: p?.offsetHeight ?? 0 },
        };
        return s.ask.w === next.ask.w &&
          s.ask.h === next.ask.h &&
          s.prefs.w === next.prefs.w &&
          s.prefs.h === next.prefs.h
          ? s
          : next;
      });
    };
    measure();
    const observer = new ResizeObserver(measure);
    if (askRef.current) observer.observe(askRef.current);
    if (prefsRef.current) observer.observe(prefsRef.current);
    return () => observer.disconnect();
  }, [visible]);

  // Arrives by rising out of the corner, a beat after the page.
  React.useLayoutEffect(() => {
    if (!visible || reduced) return;
    cardRef.current?.animate(
      [
        { transform: "translateY(20px) scale(0.97)", opacity: 0 },
        { transform: "none", opacity: 1 },
      ],
      {
        duration: 640,
        delay: phase === "ask" ? 400 : 0,
        easing: EASE,
        fill: "backwards",
      },
    );
  }, [visible]);

  // Focus follows the surface, so keyboard people never land on something that just faded.
  React.useEffect(() => {
    const target = focusTo.current;
    if (!target) return;
    focusTo.current = null;
    if (target === "prefs")
      prefsRef.current
        ?.querySelector<HTMLElement>('[role="switch"]')
        ?.focus({ preventScroll: true });
    if (target === "ask") customiseRef.current?.focus({ preventScroll: true });
    if (target === "corner") cornerRef.current?.focus({ preventScroll: true });
  }, [phase]);

  const openPrefs = () => {
    const p = live.current.phase;
    if (live.current.locked || p === "hidden" || p === "prefs") return;
    back.current = p;
    focusTo.current = "prefs";
    setPhase("prefs");
  };

  React.useEffect(() => {
    window.addEventListener(OPEN_EVENT, openPrefs);
    return () => window.removeEventListener(OPEN_EVENT, openPrefs);
  }, []);

  const close = () => {
    if (live.current.locked) return;
    const to = back.current === "folded" ? "folded" : "ask";
    if (to === "folded" && saved.current)
      setChoice({ ...required(), ...saved.current });
    focusTo.current = to === "folded" ? "corner" : "ask";
    setPhase(to);
  };

  const commit = async (action: Action, consent: CookieConsent) => {
    if (live.current.locked) return;
    live.current.locked = true;
    const final = Object.fromEntries(
      categories.map((c) => [c.id, Boolean(c.required || consent[c.id])]),
    );
    setChoice(final);
    saved.current = final;
    try {
      localStorage.setItem(
        storageKey,
        JSON.stringify({ choices: final, savedAt: Date.now() } satisfies Saved),
      );
    } catch {}
    const pending = change.current?.(final, "save");
    if (pending && typeof pending.then === "function") {
      setWork({ action, stage: "busy" });
      await pending.then(undefined, () => {});
    }
    setWork({ action, stage: "done" });
    later(() => {
      if (cardRef.current?.contains(document.activeElement))
        focusTo.current = "corner";
      setPhase("folded");
      later(() => {
        setWork(null);
        live.current.locked = false;
      }, 500);
    }, 950);
  };

  const all = (on: boolean) =>
    Object.fromEntries(
      categories.map((c) => [
        c.id,
        Boolean(c.required || (on && !(gpc && c.tracking))),
      ]),
    );
  const stageOf = (action: Action) =>
    work?.action === action ? work.stage : "idle";
  const locked = work !== null;
  const prefs = phase === "prefs";
  const folded = phase === "folded";
  const shape = folded ? { w: 44, h: 44 } : prefs ? size.prefs : size.ask;
  const place =
    position === "bottom-right"
      ? "right-4"
      : position === "bottom-center"
        ? "left-1/2 -translate-x-1/2"
        : "left-4";
  const fadeIn = (delay: number) =>
    reduced
      ? "none"
      : `opacity 320ms ${EASE} ${delay}ms, filter 320ms ${EASE} ${delay}ms`;
  const fadeOut = reduced
    ? "none"
    : "opacity 120ms ease-out, filter 120ms ease-out";

  if (!visible) return null;

  return (
    <div
      ref={regionRef}
      role="region"
      aria-label="Cookie consent"
      className={`${strategy} bottom-4 z-[80] ${place} ${className}`}
      onKeyDown={(e) => {
        if (e.key === "Escape" && prefs) close();
      }}
      {...props}
    >
      {/* One surface: the banner, the preferences and the corner button are three sizes of it. */}
      <div
        ref={cardRef}
        className="relative overflow-hidden bg-popover text-popover-foreground"
        style={{
          width: shape.w || undefined,
          height: shape.h || undefined,
          borderRadius: folded ? 22 : 20,
          boxShadow: "inset 0 0 0 1px var(--border)",
          transition: reduced
            ? "none"
            : `width ${DURATION}ms ${EASE}, height ${DURATION}ms ${EASE}, border-radius ${DURATION}ms ${EASE}`,
        }}
      >
        {/* The ask. */}
        <div
          ref={askRef}
          inert={phase !== "ask"}
          aria-hidden={phase !== "ask" || undefined}
          className="absolute bottom-0 left-0 p-4"
          style={{
            width: Math.min(400, room - 32),
            opacity: phase === "ask" ? 1 : 0,
            filter: phase === "ask" ? "none" : "blur(4px)",
            transition: phase === "ask" ? fadeIn(160) : fadeOut,
          }}
        >
          <div className="flex gap-3">
            <span className="mt-[3px] text-muted-foreground">
              <CookieIcon />
            </span>
            <p className="text-[13px] leading-relaxed text-foreground">
              {message}
              {policyHref && (
                <>
                  {" "}
                  <a
                    href={policyHref}
                    className={`rounded-sm text-muted-foreground underline decoration-border underline-offset-4 transition-colors hover:text-foreground hover:decoration-current ${FOCUS}`}
                  >
                    Cookie policy
                  </a>
                </>
              )}
            </p>
          </div>
          {/* Reject all and Accept all share the width equally; in a narrow card they take their own row. */}
          <div className="mt-4 flex flex-wrap-reverse items-center gap-2">
            <button
              ref={customiseRef}
              type="button"
              onClick={openPrefs}
              aria-disabled={locked || undefined}
              className={`cursor-pointer disabled:cursor-default aria-disabled:cursor-default -ml-1.5 h-8 shrink-0 rounded-full px-2.5 text-[12.5px] font-medium ${FOCUS} ${TONES.ghost}`}
            >
              Customise
            </button>
            <div className="ml-auto flex min-w-[200px] max-w-[248px] flex-1 gap-2">
              <ActionButton
                label="Reject all"
                doneLabel="Rejected"
                stage={stageOf("reject")}
                locked={locked}
                tone="line"
                reduced={reduced}
                onClick={() => commit("reject", all(false))}
                className="flex-1"
              />
              <ActionButton
                label="Accept all"
                doneLabel="Accepted"
                stage={stageOf("accept")}
                locked={locked}
                tone="solid"
                reduced={reduced}
                onClick={() => commit("accept", all(true))}
                className="flex-1"
              />
            </div>
          </div>
        </div>

        {/* The preferences. */}
        <div
          ref={prefsRef}
          role="group"
          aria-labelledby={`${id}-title`}
          inert={!prefs}
          aria-hidden={!prefs || undefined}
          className="absolute bottom-0 left-0 p-4"
          style={{
            width: Math.min(420, room - 32),
            opacity: prefs ? 1 : 0,
            filter: prefs ? "none" : "blur(4px)",
            transition: prefs ? fadeIn(180) : fadeOut,
          }}
        >
          <div className="flex items-start justify-between gap-3">
            <div>
              <p
                id={`${id}-title`}
                className="text-[14px] font-medium text-foreground"
              >
                Choose your cookies
              </p>
              {gpc && (
                <p className="mt-1 text-[12px] leading-relaxed text-muted-foreground">
                  Your browser asks sites not to track you, so tracking stays
                  off unless you switch it on.
                </p>
              )}
            </div>
            <button
              type="button"
              aria-label="Close"
              onClick={close}
              className={`cursor-pointer -mr-1.5 -mt-1 grid size-7 shrink-0 place-items-center rounded-full ${FOCUS} ${TONES.ghost}`}
            >
              <svg
                aria-hidden="true"
                viewBox="0 0 16 16"
                fill="none"
                className="size-3.5"
              >
                <path
                  d="m4 4 8 8M12 4l-8 8"
                  stroke="currentColor"
                  strokeWidth="1.5"
                  strokeLinecap="round"
                />
              </svg>
            </button>
          </div>
          <ul className="mt-3 max-h-[min(55vh,360px)] divide-y divide-border overflow-y-auto overscroll-contain border-y border-border">
            {categories.map((c) => (
              <li key={c.id} className="flex items-start gap-4 py-3 pr-1">
                <div className="min-w-0 flex-1">
                  {c.required ? (
                    <p className="text-[13px] font-medium text-foreground">
                      {c.label}
                    </p>
                  ) : (
                    <label
                      htmlFor={`${id}-${c.id}`}
                      className="cursor-pointer text-[13px] font-medium text-foreground"
                    >
                      {c.label}
                    </label>
                  )}
                  <p
                    id={`${id}-${c.id}-about`}
                    className="mt-0.5 text-[12px] leading-relaxed text-muted-foreground"
                  >
                    {c.description}
                  </p>
                </div>
                {c.required ? (
                  <span className="mt-0.5 shrink-0 text-[12px] font-medium text-muted-foreground">
                    Always on
                  </span>
                ) : (
                  <Switch
                    id={`${id}-${c.id}`}
                    checked={Boolean(choice[c.id])}
                    describedBy={`${id}-${c.id}-about`}
                    reduced={reduced}
                    onChange={(on) =>
                      !locked && setChoice((x) => ({ ...x, [c.id]: on }))
                    }
                  />
                )}
              </li>
            ))}
          </ul>
          <div className="mt-3 flex items-center justify-end gap-2">
            <ActionButton
              label="Reject all"
              doneLabel="Rejected"
              stage={stageOf("reject")}
              locked={locked}
              tone="line"
              reduced={reduced}
              onClick={() => commit("reject", all(false))}
            />
            <ActionButton
              label="Save choices"
              doneLabel="Saved"
              stage={stageOf("save")}
              locked={locked}
              tone="solid"
              reduced={reduced}
              onClick={() => commit("save", choice)}
            />
          </div>
        </div>

        {/* The corner button it shrinks into; it grows back into the preferences. */}
        <button
          ref={cornerRef}
          type="button"
          inert={!folded}
          aria-hidden={!folded || undefined}
          aria-label="Cookie preferences"
          onClick={openPrefs}
          className="cursor-pointer group absolute inset-0 flex items-center justify-center rounded-full text-muted-foreground transition-colors hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/50"
          style={{
            opacity: folded ? 1 : 0,
            transform: folded ? "none" : "scale(0.5) rotate(-40deg)",
            transition: reduced
              ? "none"
              : folded
                ? `opacity 260ms ${EASE} 280ms, transform 520ms ${THROW} 240ms`
                : "opacity 100ms ease-out, transform 200ms ease-out",
          }}
        >
          <span className="transition-transform duration-300 group-hover:-rotate-[18deg] motion-reduce:transition-none">
            <CookieIcon className="size-5" />
          </span>
        </button>
      </div>
      <span role="status" className="sr-only">
        {work?.stage === "done" ? "Cookie choices saved" : ""}
      </span>
    </div>
  );
}

"use client";

import * as React from "react";
import { Crumb, type CrumbHandle, type Point } from "./cookie-crumb";
import { StatusButton, type ActionStatus } from "./status-button";
import { Switch } from "./switch";
import { TextMorph } from "./text-morph";
import { useInteractionReducedMotion } from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * COOKIE CONSENT: every cookie you allow goes to Crumb
 *
 *   ask       Crumb, an animated bread bun, sits on the lit
 *             stage pleading, hungry; Necessary is always on
 *   allow     switch a category on and a cookie leaps from the
 *             switch into Crumb's hands and he eats it, bite by
 *             bite, crumbs falling, and settles a little fuller;
 *             with everything allowed he's stuffed
 *   take back switch one off and the bitten cookie flies back
 *             while he eases back to how full he was
 *   decide    Reject all hands every cookie back; Accept all
 *             feeds the rest; the main button says Accept all or
 *             Save choices, and saving gets a happy hop
 *
 * The choice is yours to keep: onSave gets { [category]: on }
 * to write to a cookie, your consent platform or your API.
 * ───────────────────────────────────────────────────────── */

export interface CookieCategory {
  id: string;
  label: string;
  description?: string;
  /** Always on and can't be switched off, e.g. sign-in and security. */
  required?: boolean;
}

export type CookieChoices = Record<string, boolean>;

export interface CookieConsentProps {
  categories?: CookieCategory[];
  value?: CookieChoices;
  defaultValue?: CookieChoices;
  onValueChange?: (choices: CookieChoices) => void;
  /** Keep the choices (a cookie, your consent platform, your API); throw an Error to say why not. */
  onSave: (choices: CookieChoices) => Promise<unknown>;
  title?: string;
  description?: string;
  /** Your cookie policy, linked under the choices. */
  policyHref?: string;
  /** What the mascot is called in its lines. */
  name?: string;
  className?: string;
}

const CATEGORIES: CookieCategory[] = [
  {
    id: "necessary",
    label: "Necessary",
    description: "Sign-in, security and your choices here.",
    required: true,
  },
  {
    id: "analytics",
    label: "Analytics",
    description: "Counts visits so we know what to fix.",
  },
  {
    id: "marketing",
    label: "Marketing",
    description: "Measures ads and where you came from.",
  },
  {
    id: "personalization",
    label: "Personalization",
    description: "Remembers what you like.",
  },
];
const EMPTY: CookieChoices = {};

const mix = (color: string, amount: number, into = "transparent") =>
  `color-mix(in oklab, ${color} ${amount}%, ${into})`;
const CARD: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, var(--card), ${mix("var(--card)", 95, "var(--foreground)")})`,
  boxShadow: `0 0 0 1px var(--border), inset 0 1px 0 ${mix("var(--background)", 85)}`,
};
const STAGE: React.CSSProperties = {
  backgroundColor: "var(--primary)",
  backgroundImage: `radial-gradient(90% 80% at 50% 100%, ${mix("var(--primary-foreground)", 20)} 0%, transparent 60%), radial-gradient(120% 90% at 0% 0%, ${mix("var(--primary-foreground)", 16)} 0%, transparent 55%), linear-gradient(175deg, transparent 40%, ${mix("black", 22)} 100%)`,
  boxShadow: `inset 0 1px 0 ${mix("var(--primary-foreground)", 36)}, inset 0 0 0 1px ${mix("var(--primary-foreground)", 12)}`,
};
const LIT: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, ${mix("var(--primary-foreground)", 16)}, transparent 60%)`,
  boxShadow: `inset 0 1px 0 ${mix("var(--primary-foreground)", 32)}, inset 0 0 0 1px ${mix("black", 10)}`,
};
/* Crumb's cookie crumbs and the pool of light he sits in; each can be overridden. */
const CRUMB = {
  "--crumb-floor": mix("var(--primary-foreground)", 45),
  "--crumb-cookie": "oklch(0.7 0.11 65)",
} as React.CSSProperties;

export function CookieConsent({
  categories = CATEGORIES,
  value,
  defaultValue = EMPTY,
  onValueChange,
  onSave,
  title = "Cookie settings",
  description,
  policyHref,
  name = "Crumb",
  className = "",
}: CookieConsentProps) {
  const reduced = useInteractionReducedMotion();
  const baseId = React.useId();
  const [own, setOwn] = React.useState<CookieChoices>(defaultValue);
  const choices = value ?? own;
  const [act, setAct] = React.useState<{
    which: "accept" | "reject" | null;
    status: ActionStatus;
    error?: string;
  }>({ which: null, status: "idle" });
  const [said, setSaid] = React.useState("");
  const sectionRef = React.useRef<HTMLElement>(null);
  const overlayRef = React.useRef<SVGSVGElement>(null);
  const stageRef = React.useRef<HTMLDivElement>(null);
  const crumb = React.useRef<CrumbHandle>(null);
  const switches = React.useRef(new Map<string, HTMLElement>());

  const optional = categories.filter((c) => !c.required);
  const isOn = (c: CookieCategory) => Boolean(c.required || choices[c.id]);
  const fed = optional.filter(isOn).length;
  const allOn = fed === optional.length;
  const busy = act.status === "pending";

  const commit = (next: CookieChoices) => {
    if (value === undefined) setOwn(next);
    onValueChange?.(next);
  };

  /** Where a category's switch is, in the block's own px. */
  const switchAt = (id: string): Point => {
    const section = sectionRef.current;
    const el = switches.current.get(id);
    if (!section || !el) return { x: 0, y: 0 };
    const box = section.getBoundingClientRect();
    const k = box.width / (section.offsetWidth || box.width) || 1;
    const r = el.getBoundingClientRect();
    return {
      x: (r.left + r.width / 2 - box.left) / k,
      y: (r.top + r.height / 2 - box.top) / k,
    };
  };

  const toggle = (c: CookieCategory, on: boolean) => {
    if (busy || c.required) return;
    commit({ ...choices, [c.id]: on });
    if (on) crumb.current?.feed(switchAt(c.id));
    else crumb.current?.giveBack(switchAt(c.id));
    setSaid(`${c.label} ${on ? "allowed" : "off"}.`);
    if (act.status !== "idle") setAct({ which: null, status: "idle" });
  };

  const save = async (
    which: "accept" | "reject",
    next: CookieChoices,
    wait: number,
  ) => {
    setAct({ which, status: "pending" });
    try {
      // let the cookies land before the choice is kept
      await new Promise((r) => window.setTimeout(r, wait));
      await onSave(next);
      setAct({ which, status: "success" });
      setSaid(
        which === "reject"
          ? "Saved: only necessary cookies."
          : `Saved your cookie choices.`,
      );
      crumb.current?.wave();
    } catch (e) {
      setAct({
        which,
        status: "error",
        error:
          e instanceof Error && e.message
            ? e.message
            : "Couldn’t save that. Try again.",
      });
    }
  };

  const acceptAll = () => {
    if (busy) return;
    const off = optional.filter((c) => !choices[c.id]);
    const keep = fed > 0 && !allOn;
    if (keep)
      return void save(
        "accept",
        {
          ...choices,
          ...Object.fromEntries(
            categories.filter((c) => c.required).map((c) => [c.id, true]),
          ),
        },
        0,
      );
    const next = Object.fromEntries(categories.map((c) => [c.id, true]));
    commit(next);
    off.forEach((c, i) => crumb.current?.feed(switchAt(c.id), i * 170));
    void save(
      "accept",
      next,
      reduced || !off.length ? 0 : off.length * 170 + 620,
    );
  };

  const rejectAll = () => {
    if (busy) return;
    const on = optional.filter((c) => choices[c.id]);
    const next = Object.fromEntries(
      categories.map((c) => [c.id, Boolean(c.required)]),
    );
    commit(next);
    on.forEach((c, i) => crumb.current?.giveBack(switchAt(c.id), i * 140));
    void save(
      "reject",
      next,
      reduced || !on.length ? 0 : on.length * 140 + 640,
    );
  };

  const mood =
    fed === 0
      ? `${name} is hungry`
      : allOn
        ? `${name} is stuffed`
        : `${name} could eat more`;
  const mainLabel = fed > 0 && !allOn ? "Save choices" : "Accept all";

  return (
    <section
      ref={sectionRef}
      aria-labelledby={`${baseId}-title`}
      className={`relative w-full max-w-[380px] rounded-[28px] p-2 text-card-foreground ${className}`}
      style={{ ...CARD, ...CRUMB }}
    >
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 380px)" }}
      />
      <div className="@container w-full">
        {/* The one lit surface: Crumb's stage. */}
        <div
          ref={stageRef}
          className="relative h-[172px] overflow-clip rounded-[22px] text-primary-foreground"
          style={STAGE}
        >
          <p className="absolute left-3.5 top-3 z-10 text-[12.5px] font-medium text-primary-foreground/80">
            <TextMorph>{mood}</TextMorph>
          </p>
          <Crumb
            ref={crumb}
            fed={fed}
            total={optional.length}
            reduced={reduced}
            overlay={overlayRef}
            stage={stageRef}
          />
        </div>

        <div className="px-2 pt-3">
          <h2
            id={`${baseId}-title`}
            className="px-1 text-[15px] font-medium tracking-[-0.01em]"
          >
            {title}
          </h2>
          <p className="mt-0.5 px-1 text-[12.5px] text-muted-foreground">
            {description ?? `Every cookie you allow goes to ${name}.`}
          </p>

          <ul className="mt-2">
            {categories.map((c) => (
              <li
                key={c.id}
                className="flex min-h-12 items-center gap-3 border-t border-border/70 px-1 py-2 first:border-t-0"
              >
                <span className="min-w-0 flex-1">
                  <span
                    id={`${baseId}-${c.id}`}
                    className="block text-[13.5px] font-medium"
                  >
                    {c.label}
                  </span>
                  {c.description && (
                    <span className="block truncate text-[12px] text-muted-foreground">
                      {c.description}
                    </span>
                  )}
                </span>
                {c.required ? (
                  <span className="shrink-0 rounded-full bg-muted px-2 py-0.5 text-[11.5px] text-muted-foreground">
                    Always on
                  </span>
                ) : (
                  <span
                    ref={(el) => {
                      if (el) switches.current.set(c.id, el);
                      else switches.current.delete(c.id);
                    }}
                    className="flex shrink-0"
                  >
                    <Switch
                      size="sm"
                      checked={isOn(c)}
                      aria-labelledby={`${baseId}-${c.id}`}
                      disabled={busy}
                      onCheckedChange={(on) => toggle(c, on)}
                    />
                  </span>
                )}
              </li>
            ))}
          </ul>

          <div className="mt-2.5 grid grid-cols-2 gap-2">
            <StatusButton
              variant="outline"
              status={act.which === "reject" ? act.status : "idle"}
              labels={{
                idle: "Reject all",
                pending: "Saving",
                success: "Saved",
                error: "Try again",
              }}
              disabled={busy && act.which !== "reject"}
              onClick={rejectAll}
              className="h-10 w-full text-[13.5px]"
            />
            <StatusButton
              status={act.which === "accept" ? act.status : "idle"}
              labels={{
                idle: mainLabel,
                pending: "Saving",
                success: "Saved",
                error: "Try again",
              }}
              disabled={busy && act.which !== "accept"}
              onClick={acceptAll}
              className="h-10 w-full text-[13.5px]"
              style={
                act.which === "accept" && act.status === "error"
                  ? undefined
                  : LIT
              }
            />
          </div>
          <p
            role={act.error ? "alert" : undefined}
            className={`mt-2 pb-1 text-center text-[12px] ${act.error ? "text-red-600 dark:text-red-400" : "text-muted-foreground"}`}
          >
            {act.error ?? (
              <>
                Change this any time{policyHref ? " · " : "."}
                {policyHref && (
                  <a
                    href={policyHref}
                    className="underline decoration-border underline-offset-2 hover:text-foreground"
                  >
                    Cookie policy
                  </a>
                )}
              </>
            )}
          </p>
        </div>
      </div>

      {/* Cookies fly over the whole block, from a switch to the mouth and back. */}
      <svg
        ref={overlayRef}
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 z-20 size-full overflow-visible"
      />

      <span className="sr-only" role="status">
        {said}
      </span>
    </section>
  );
}

export default CookieConsent;

"use client";

import * as React from "react";
import { CRUMB_ART as ART, CRUMB_FRAMES as F } from "./crumb-art";

/* ─────────────────────────────────────────────────────────
 * CRUMB: a bread bun who eats the cookies you allow
 *
 * Crumb is animated, not posed: three short eating clips cut
 * into frames (hungry → content → full → stuffed), played in
 * code.
 *
 *   hungry   nothing allowed yet: pleading eyes, hands clasped
 *   feed     a cookie arcs from a switch into his hands; the
 *            next clip takes over from the frame where it's
 *            there, and he eats it bite by bite, crumbs falling,
 *            chews and ends a little fuller
 *   give     a switch off: the bitten cookie flies back to its
 *            switch and he eases back to how full he was before
 *   wave     a happy hop once the choices are saved
 *
 * Cookies fly in an <svg> overlay that covers the whole block,
 * in the block's own px. One frame loop outside React flies
 * them, steps the frames and sleeps when he's still.
 * ───────────────────────────────────────────────────────── */

export type Point = { x: number; y: number };

export interface CrumbHandle {
  /** A cookie flies from `from` (block px) into his hands, and he eats it. */
  feed: (from: Point, delay?: number) => void;
  /** A bitten cookie flies from him back to `to` (block px). */
  giveBack: (to: Point, delay?: number) => void;
  /** A happy hop, e.g. once the choices are saved. */
  wave: () => void;
}

const TALL = 130; // px on the stage
const K = TALL / F.h;
const WIDE = F.w * K;
const NS = "http://www.w3.org/2000/svg";
const STEP = 1000 / F.fps;

const ease = (k: number) => 1 - Math.pow(1 - k, 3);
const inOut = (k: number) =>
  k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
const clamp = (v: number, a = 0, b = 1) => Math.min(b, Math.max(a, v));

/** Which clip eats the cookie that brings him to `fed` of `total`, so any number of categories ends stuffed. */
const clipFor = (fed: number, total: number) =>
  Math.min(2, Math.max(0, Math.floor((fed / Math.max(1, total)) * 3 - 1e-3)));
/** The still he rests on with `fed` of `total` eaten: [strip, frame]. */
const restFor = (fed: number, total: number): [number, number] =>
  fed <= 0 ? [0, 0] : [clipFor(fed, total), F.count - 1];

type Spring = { x: number; v: number };
function step(s: Spring, target: number, dt: number, k = 170, c = 18) {
  s.v += ((target - s.x) * k - s.v * c) * dt;
  s.x += s.v * dt;
  if (Math.abs(target - s.x) < 1e-3 && Math.abs(s.v) < 1e-3) {
    s.x = target;
    s.v = 0;
    return true;
  }
  return false;
}

/** An element's place inside `root` from layout offsets, so transforms (a hop, a breath) don't move it. */
function offsetIn(el: HTMLElement, root: Element): Point {
  let x = 0;
  let y = 0;
  for (
    let n: HTMLElement | null = el;
    n && n !== root;
    n = n.offsetParent as HTMLElement | null
  ) {
    x += n.offsetLeft;
    y += n.offsetTop;
  }
  return { x, y };
}

type Flight = {
  dir: 1 | -1;
  a: Point;
  b: Point;
  t0: number;
  dur: number;
  el: SVGGElement;
  done: boolean;
  clip: number;
};

export class CrumbEngine {
  parts: Record<string, Element | null> = {};
  overlayRef: React.RefObject<SVGSVGElement | null> | null = null;
  reduced = false;
  fed = 0;
  total = 3;
  /** His own count: feeds and give-backs move it at once, before the block's count re-renders. */
  count = 0;
  /** What's on screen: a strip and a frame, and the one fading out under it. */
  shown: [number, number] = [0, 0];
  under: [number, number] | null = null;
  fadeAt = 0;
  /** Clips waiting to play (a cookie in his hands each), and the one playing. */
  queue: number[] = [];
  playing: { clip: number; t0: number } | null = null;
  flights: Flight[] = [];
  hop: Spring = { x: 0, v: 0 };
  lean: Spring = { x: 0, v: 0 };
  breath: Animation | null = null;
  raf = 0;
  last = 0;
  frame = (now: number) => this.tick(now);

  part = (name: string) => (el: Element | null) => {
    this.parts[name] = el;
  };

  get overlay() {
    return this.overlayRef?.current ?? null;
  }

  mount(
    overlay: React.RefObject<SVGSVGElement | null>,
    reduced: boolean,
    fed: number,
    total: number,
  ) {
    this.overlayRef = overlay;
    this.reduced = reduced;
    this.fed = fed;
    this.total = total;
    this.count = fed;
    this.shown = restFor(fed, total);
    // decode the clips up front, so the first frame of each is there the moment a cookie lands
    for (const src of ART.strips) {
      const img = new Image();
      img.src = src;
      void img.decode?.().catch(() => {});
    }
    if (!reduced) {
      this.breath =
        (this.parts.breathe as HTMLElement | null)?.animate(
          [{ transform: "none" }, { transform: "scale(1.012, 1.022)" }],
          {
            duration: 1500,
            iterations: Infinity,
            direction: "alternate",
            easing: "ease-in-out",
          },
        ) ?? null;
    }
    this.draw(performance.now());
  }

  destroy() {
    cancelAnimationFrame(this.raf);
    this.raf = 0;
    this.breath?.cancel();
    this.flights.forEach((f) => f.el.remove());
    this.flights = [];
  }

  /** The count changed; feeds and give-backs bring their own motion, so this only settles where he rests. */
  setTarget(fed: number, total: number) {
    this.fed = fed;
    this.total = total;
    const busy = this.playing || this.queue.length || this.flights.length;
    if (!busy) this.count = fed;
    if (this.reduced) {
      this.show(restFor(fed, total), false);
      return;
    }
    if (!busy) this.show(restFor(fed, total), true);
  }

  wake() {
    if (this.raf || !this.parts.bun) return;
    this.last = performance.now();
    this.raf = requestAnimationFrame(this.frame);
  }

  /** Where the cookie sits in his hands, in block px. */
  hands(): Point {
    const bun = this.parts.bun as HTMLElement | null;
    const root = this.overlay?.parentElement;
    if (!bun || !root) return { x: 0, y: 0 };
    const at = offsetIn(bun, root);
    return { x: at.x + WIDE * F.hands.x, y: at.y + TALL * F.hands.y };
  }

  fly(dir: 1 | -1, p: Point, delay: number) {
    const overlay = this.overlay;
    this.count = clamp(this.count + dir, 0, this.total);
    // the clip that eats this cookie
    const clip = clipFor(this.count, this.total);
    if (this.reduced || !overlay) {
      this.show(restFor(this.count, this.total), false);
      return;
    }
    const now = performance.now();
    const size = WIDE * F.hands.size;
    const el = document.createElementNS(NS, "g") as SVGGElement;
    const img = document.createElementNS(NS, "image");
    img.setAttribute("href", dir === 1 ? ART.cookie : ART.bitten);
    img.setAttribute("width", String(size));
    img.setAttribute("height", String(size));
    img.setAttribute("x", String(-size / 2));
    img.setAttribute("y", String(-size / 2));
    el.appendChild(img);
    el.style.opacity = "0";
    overlay.appendChild(el);
    const at = this.hands();
    this.flights.push(
      dir === 1
        ? { dir, a: p, b: at, t0: now + delay, dur: 620, el, done: false, clip }
        : {
            dir,
            a: at,
            b: p,
            t0: now + delay,
            dur: 640,
            el,
            done: false,
            clip,
          },
    );
    if (dir === -1) {
      // he lets it go and eases back to how full he was
      this.hop.v -= 40;
      const count = this.count;
      window.setTimeout(
        () => !this.playing && this.show(restFor(count, this.total), true),
        delay + 120,
      );
    }
    this.wake();
  }

  wave() {
    if (this.reduced) return;
    this.hop.v -= 260;
    this.wake();
  }

  /** Put a still on screen, cross-fading from the last one when it changes. */
  show(next: [number, number], fade: boolean) {
    if (next[0] === this.shown[0] && next[1] === this.shown[1]) return;
    this.under = fade && !this.reduced ? this.shown : null;
    this.fadeAt = performance.now();
    this.shown = next;
    this.draw(this.fadeAt);
    if (this.under) this.wake();
  }

  tick(now: number) {
    const dt = Math.min(0.05, (now - this.last) / 1000);
    this.last = now;
    let busy = false;
    let lean = 0;

    for (const f of this.flights) {
      busy = true;
      if (now < f.t0) continue;
      const k = clamp((now - f.t0) / f.dur);
      const e = f.dir === 1 ? ease(k) : inOut(k);
      const mx = (f.a.x + f.b.x) / 2;
      const my = Math.min(f.a.y, f.b.y) - (f.dir === 1 ? 64 : 50);
      const x =
        (1 - e) * (1 - e) * f.a.x + 2 * (1 - e) * e * mx + e * e * f.b.x;
      const y =
        (1 - e) * (1 - e) * f.a.y + 2 * (1 - e) * e * my + e * e * f.b.y;
      const spin = f.dir === 1 ? 300 * (1 - e) : -240 * e;
      const scale = f.dir === 1 ? 0.6 + 0.4 * clamp(k / 0.25) : 1 - 0.1 * k;
      f.el.setAttribute(
        "transform",
        `translate(${x.toFixed(1)} ${y.toFixed(1)}) rotate(${spin.toFixed(1)}) scale(${scale.toFixed(3)})`,
      );
      f.el.style.opacity = String(
        f.dir === 1 ? 1 : 1 - clamp((k - 0.85) / 0.15),
      );
      if (f.dir === 1) lean = clamp((x - f.b.x) / 140, -1, 1) * (1 - k);
      if (k >= 1) {
        f.done = true;
        f.el.remove();
        // caught: the clip takes over from the frame with the cookie in his hands
        if (f.dir === 1) {
          this.queue.push(f.clip);
          this.hop.v += 60;
        }
      }
    }
    this.flights = this.flights.filter((f) => !f.done);

    if (!this.playing && this.queue.length) {
      this.playing = { clip: this.queue.shift()!, t0: now };
      this.under = null;
    }
    if (this.playing) {
      busy = true;
      const i = 1 + Math.floor((now - this.playing.t0) / STEP);
      if (i >= F.count) {
        this.shown = [this.playing.clip, F.count - 1];
        this.playing = null;
        // nothing else to eat: settle where the count says (a switch may have gone off meanwhile)
        if (!this.queue.length && !this.flights.some((f) => f.dir === 1))
          this.show(restFor(this.count, this.total), true);
      } else this.shown = [this.playing.clip, i];
    }

    const fading = this.under !== null && now - this.fadeAt < 280;
    if (!fading) this.under = null;
    const settled = [
      step(this.hop, 0, dt, 300, 14),
      step(this.lean, lean, dt, 220, 20),
    ].every(Boolean);
    if (!settled || fading) busy = true;

    this.draw(now);
    this.raf = busy ? requestAnimationFrame(this.frame) : 0;
  }

  paint(el: HTMLElement | null, at: [number, number] | null, opacity: number) {
    if (!el) return;
    if (!at) {
      el.style.opacity = "0";
      return;
    }
    const image = `url("${ART.strips[at[0]]}")`;
    if (el.dataset.strip !== String(at[0])) {
      el.dataset.strip = String(at[0]);
      el.style.backgroundImage = image;
    }
    el.style.backgroundPosition = `${(-at[1] * WIDE).toFixed(2)}px 0px`;
    el.style.opacity = String(opacity);
  }

  draw(now: number) {
    const bun = this.parts.bun as HTMLElement | null;
    if (!bun) return;
    const fade = this.under ? clamp((now - this.fadeAt) / 260) : 1;
    this.paint(this.parts.front as HTMLElement | null, this.shown, fade);
    this.paint(this.parts.back as HTMLElement | null, this.under, 1);
    const squash = clamp(this.hop.v * 0.0005, -0.05, 0.05);
    bun.style.transform = `translateY(${(this.hop.x * 0.05).toFixed(2)}px) rotate(${(this.lean.x * 4).toFixed(2)}deg) scale(${(1 + squash * 0.6).toFixed(4)}, ${(1 - squash).toFixed(4)})`;
  }
}

export function Crumb({
  fed,
  total,
  reduced,
  overlay,
  ref,
}: {
  /** Cookies eaten so far. */
  fed: number;
  /** Cookies there are to eat. */
  total: number;
  reduced: boolean;
  /** The block-wide <svg> the cookies fly in. */
  overlay: React.RefObject<SVGSVGElement | null>;
  /** Kept for compatibility; Crumb measures himself. */
  stage?: React.RefObject<HTMLElement | null>;
  ref?: React.Ref<CrumbHandle>;
}) {
  const [engine] = React.useState(() => new CrumbEngine());

  React.useLayoutEffect(() => {
    engine.mount(overlay, reduced, fed, total);
    return () => engine.destroy();
    // mounted once per reduced-motion setting; fed/total arrive through setTarget below
  }, [engine, overlay, reduced]);

  React.useEffect(() => {
    engine.setTarget(fed, total);
  }, [engine, fed, total]);

  React.useImperativeHandle(
    ref,
    () => ({
      feed: (p, d = 0) => engine.fly(1, p, d),
      giveBack: (p, d = 0) => engine.fly(-1, p, d),
      wave: () => engine.wave(),
    }),
    [engine],
  );

  const layer: React.CSSProperties = {
    backgroundSize: `${(F.count * WIDE).toFixed(2)}px ${TALL}px`,
    backgroundRepeat: "no-repeat",
  };
  return (
    <div aria-hidden="true" className="absolute inset-0">
      {/* a soft pool of light where he sits */}
      <span
        className="absolute bottom-1.5 left-1/2 h-4 w-32 -translate-x-1/2 rounded-[50%]"
        style={{
          background:
            "radial-gradient(closest-side, var(--crumb-floor), transparent)",
        }}
      />
      <div
        ref={engine.part("bun")}
        className="absolute bottom-1"
        style={{
          left: `calc(50% - ${(WIDE / 2).toFixed(2)}px)`,
          width: WIDE,
          height: TALL,
          transformOrigin: "50% 100%",
        }}
      >
        <div
          ref={engine.part("breathe")}
          className="absolute inset-0"
          style={{ transformOrigin: "50% 100%" }}
        >
          <div
            ref={engine.part("back")}
            className="absolute inset-0"
            style={{ ...layer, opacity: 0 }}
          />
          <div
            ref={engine.part("front")}
            className="absolute inset-0"
            style={{ ...layer, backgroundImage: `url("${ART.strips[0]}")` }}
          />
        </div>
      </div>
    </div>
  );
}

export default Crumb;

"use client";

import * as React from "react";
import { Copy } from "lucide-react";
import { TextMorph } from "./text-morph";
import {
  EASE_OUT,
  INTERACTION_FOCUS,
  INTERACTION_PRESS,
  interactionIcon,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * COPY BUTTON: copies, and says so the moment you press
 *
 *   idle     the copy icon (and "Copy" when labelled)
 *   copied   flips on the press itself, not after the clipboard
 *            answers: the icon blurs out, a check draws itself,
 *            "Copy" morphs to "Copied" and the pill eases wider
 *   error    if the clipboard refuses, the check gives way to an
 *            alert, the label says "Failed" and the button shakes
 *
 * Pressing again while copied copies again and restarts the timer.
 * A status region outside the button tells screen readers.
 * ───────────────────────────────────────────────────────── */

export type CopyState = "idle" | "copied" | "error";

export interface CopyButtonProps extends Omit<
  React.ButtonHTMLAttributes<HTMLButtonElement>,
  "children"
> {
  /** The text to copy. */
  text: string;
  /** Label while idle; also the icon-only button's accessible name. */
  label?: string;
  /** Label once copied. */
  copiedLabel?: string;
  /** Label if the clipboard refuses. */
  errorLabel?: string;
  /** Show the label beside the icon. Defaults to false (icon only). */
  showLabel?: boolean;
  /** How long "Copied" stays before it returns to idle (ms). */
  timeoutMs?: number;
  variant?: "secondary" | "outline" | "ghost";
  /** xs 24px, sm 28px, md 36px tall. */
  size?: "xs" | "sm" | "md";
  onCopySuccess?: (text: string) => void;
  onCopyError?: (error: unknown) => void;
}

const SIZES = {
  xs: {
    square: "size-6",
    pill: "h-6 pl-2 pr-2.5 text-[12px]",
    icon: 12,
    gap: 5,
  },
  sm: {
    square: "size-7",
    pill: "h-7 pl-2.5 pr-3 text-[12px]",
    icon: 13,
    gap: 6,
  },
  md: {
    square: "size-9",
    pill: "h-9 pl-3.5 pr-4 text-[13px]",
    icon: 15,
    gap: 7,
  },
};

const TONES = {
  secondary:
    "bg-card text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent",
  outline:
    "bg-transparent text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent",
  ghost:
    "bg-transparent text-muted-foreground hover:bg-accent hover:text-foreground",
};

const ERROR_TONE =
  "bg-red-500/10 text-red-600 shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_30%,transparent)] dark:text-red-400";

function writeClipboard(text: string): Promise<void> {
  if (navigator.clipboard?.writeText)
    return navigator.clipboard.writeText(text);
  // Older browsers and plain-http pages: the selection fallback.
  return new Promise((resolve, reject) => {
    const area = document.createElement("textarea");
    area.value = text;
    area.setAttribute("readonly", "");
    area.style.cssText =
      "position:fixed;top:0;left:0;opacity:0;pointer-events:none";
    document.body.appendChild(area);
    area.select();
    const ok = document.execCommand("copy");
    area.remove();
    if (ok) resolve();
    else reject(new Error("Copy was refused"));
  });
}

function Check({ drawn, reduced }: { drawn: boolean; reduced: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="none" className="size-full">
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          // Draws on the way in; on the way out it stays whole until its layer has faded.
          transition: reduced
            ? "none"
            : drawn
              ? `stroke-dashoffset 360ms ${EASE_OUT} 70ms`
              : "stroke-dashoffset 0ms linear 300ms",
        }}
      />
    </svg>
  );
}

function Alert() {
  return (
    <svg viewBox="0 0 16 16" fill="none" className="size-full">
      <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeWidth="1.5" />
      <path
        d="M8 4.75v3.75"
        stroke="currentColor"
        strokeWidth="1.75"
        strokeLinecap="round"
      />
      <circle cx="8" cy="11" r="1" fill="currentColor" />
    </svg>
  );
}

export function CopyButton({
  text,
  label = "Copy",
  copiedLabel = "Copied",
  errorLabel = "Failed",
  showLabel = false,
  timeoutMs = 2000,
  variant = "ghost",
  size = "sm",
  onCopySuccess,
  onCopyError,
  className = "",
  disabled,
  onClick,
  ...props
}: CopyButtonProps) {
  const reduced = useInteractionReducedMotion();
  const ref = React.useRef<HTMLButtonElement>(null);
  const [state, setState] = React.useState<CopyState>("idle");
  // Bumped on every copy so a second press restarts the timer.
  const [stamp, setStamp] = React.useState(0);

  React.useEffect(() => {
    if (state === "idle") return;
    const timer = window.setTimeout(() => setState("idle"), timeoutMs);
    return () => window.clearTimeout(timer);
  }, [state, stamp, timeoutMs]);

  React.useEffect(() => {
    if (state !== "error" || reduced) return;
    ref.current?.animate(
      [
        { transform: "none" },
        { transform: "translateX(-4px)" },
        { transform: "translateX(4px)" },
        { transform: "translateX(-2px)" },
        { transform: "none" },
      ],
      { duration: 380, easing: "ease-out" },
    );
  }, [state, stamp, reduced]);

  const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    onClick?.(e);
    if (e.defaultPrevented || disabled || !text) return;
    // Optimistic: the feedback lands on the press, the clipboard catches up.
    setState("copied");
    setStamp((n) => n + 1);
    writeClipboard(text).then(
      () => onCopySuccess?.(text),
      (error: unknown) => {
        setState("error");
        setStamp((n) => n + 1);
        onCopyError?.(error);
      },
    );
  };

  const s = SIZES[size];
  const current =
    state === "copied" ? copiedLabel : state === "error" ? errorLabel : label;

  return (
    <>
      <button
        ref={ref}
        type="button"
        disabled={disabled}
        onClick={handleClick}
        aria-label={showLabel ? undefined : label}
        data-state={state}
        className={`relative inline-flex shrink-0 select-none items-center justify-center whitespace-nowrap rounded-full font-medium cursor-pointer disabled:cursor-default disabled:opacity-45 ${INTERACTION_PRESS} ${INTERACTION_FOCUS} ${
          state === "error" ? ERROR_TONE : TONES[variant]
        } ${showLabel ? s.pill : s.square} ${className}`}
        {...props}
      >
        <span
          aria-hidden="true"
          className="relative shrink-0"
          style={{ width: s.icon, height: s.icon }}
        >
          <span
            className="absolute inset-0 flex items-center justify-center"
            style={interactionIcon(state === "idle", reduced)}
          >
            <Copy size={s.icon} strokeWidth={1.75} />
          </span>
          <span
            className="absolute inset-0 text-emerald-600 dark:text-emerald-400"
            style={interactionIcon(state === "copied", reduced)}
          >
            <Check drawn={state === "copied"} reduced={reduced} />
          </span>
          <span
            className="absolute inset-0"
            style={interactionIcon(state === "error", reduced)}
          >
            <Alert />
          </span>
        </span>
        {showLabel && (
          <TextMorph style={{ marginLeft: s.gap }}>{current}</TextMorph>
        )}
      </button>
      {/* Outside the button, so the announcement isn't read as part of its name. */}
      <span role="status" className="sr-only">
        {state === "idle" ? "" : current}
      </span>
    </>
  );
}

