"use client";

import * as React from "react";
import { Hide, type HideHandle, type Point } from "./hide-chameleon";
import { PasswordInput } from "./password-input";
import { StatusButton, type ActionStatus } from "./status-button";
import { TextMorph } from "./text-morph";
import {
  EASE_OUT,
  EASE_THROW,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * CREATE PASSWORD: the stronger it is, the harder Hide is to find
 *
 *   spot     Hide, a chameleon, sits on a branch on the lit
 *            stage in full colour, watching the caret
 *   catch    each rule the password meets, his tongue shoots
 *            out to its circle and leaves a check there; lose
 *            one and he takes the check back and swallows it
 *   blend    with every check a front of colour change runs a
 *            little further from his tail to his snout; with
 *            all of them he's gone but for his eye
 *   exposed  Show password and his colour floods back, eye
 *            squeezed shut, cheek flushed
 *   startle  wipe the field and his cover's blown: he jumps
 *   breached with checkBreaches, a password seen in a breach
 *            turns him red and says how often
 *   done     Continue → Saving → Password set, and a wink
 *
 * onSubmit gets the password; keep it however you keep them.
 * ───────────────────────────────────────────────────────── */

export interface PasswordRule {
  id: string;
  label: string;
  test: (password: string) => boolean;
}

export const PASSWORD_RULES: PasswordRule[] = [
  { id: "length", label: "8+ characters", test: (p) => p.length >= 8 },
  { id: "number", label: "A number", test: (p) => /\d/.test(p) },
  { id: "capital", label: "A capital letter", test: (p) => /[A-Z]/.test(p) },
  { id: "symbol", label: "A symbol", test: (p) => /[^A-Za-z0-9\s]/.test(p) },
];

export interface CreatePasswordProps {
  /** Keep the password (your sign-up or reset endpoint); throw an Error to say why not. */
  onSubmit: (password: string) => Promise<unknown>;
  /** How many known breaches the password appears in (0 if none), e.g. from Have I Been Pwned's range API. */
  checkBreaches?: (password: string, signal: AbortSignal) => Promise<number>;
  rules?: PasswordRule[];
  /** The account's email or username, so password managers save the pair. */
  username?: string;
  onValueChange?: (password: string) => void;
  title?: string;
  description?: string;
  submitLabel?: string;
  /** What the chameleon is called in his lines. */
  name?: string;
  className?: string;
}

const mix = (color: string, amount: number, into = "transparent") =>
  `color-mix(in oklab, ${color} ${amount}%, ${into})`;
const PF = "var(--primary-foreground)";
const CARD: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, var(--card), ${mix("var(--card)", 95, "var(--foreground)")})`,
  boxShadow: `0 0 0 1px var(--border), inset 0 1px 0 ${mix("var(--background)", 85)}`,
};
/* The one lit surface, engraved with fine scales like his skin: whatever he blends into, it's this. */
const SCALE = `radial-gradient(circle at 50% 0%, transparent 5.1px, ${mix(PF, 11)} 5.6px, transparent 6.3px)`;
const STAGE: React.CSSProperties = {
  backgroundColor: "var(--primary)",
  backgroundImage: [
    `radial-gradient(90% 70% at 50% 100%, ${mix(PF, 18)} 0%, transparent 62%)`,
    `radial-gradient(120% 90% at 0% 0%, ${mix(PF, 16)} 0%, transparent 55%)`,
    `linear-gradient(175deg, transparent 40%, ${mix("black", 22)} 100%)`,
    SCALE,
    SCALE,
  ].join(", "),
  backgroundSize: "auto, auto, auto, 12px 7px, 12px 7px",
  backgroundPosition: "0 0, 0 0, 0 0, 0 0, 6px 3.5px",
  boxShadow: `inset 0 1px 0 ${mix(PF, 36)}, inset 0 0 0 1px ${mix(PF, 12)}`,
};
const LIT: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, ${mix(PF, 16)}, transparent 60%)`,
  boxShadow: `inset 0 1px 0 ${mix(PF, 32)}, inset 0 0 0 1px ${mix("black", 10)}`,
};
/* Hide's own colours; each can be overridden. */
const HIDE = {
  "--hide-pupil": "oklch(0.2 0.03 150)",
  "--hide-tongue": "oklch(0.74 0.14 6)",
  "--hide-tongue-line": "oklch(0.44 0.11 8)",
  "--hide-blush": "oklch(0.7 0.17 15)",
  "--hide-check": "var(--color-emerald-500, oklch(0.7 0.16 162))",
} as React.CSSProperties;

let measure: CanvasRenderingContext2D | null = null;
/** Where the caret is on screen, near enough for an eye to follow. */
function caretAt(input: HTMLInputElement): Point {
  const r = input.getBoundingClientRect();
  const cs = getComputedStyle(input);
  measure ??= document.createElement("canvas").getContext("2d");
  const upto = input.selectionStart ?? input.value.length;
  const text =
    input.type === "password" ? "•".repeat(upto) : input.value.slice(0, upto);
  let w = 0;
  if (measure) {
    measure.font = `${cs.fontWeight} ${cs.fontSize} ${cs.fontFamily}`;
    w = measure.measureText(text).width;
  }
  return {
    x:
      r.left +
      Math.min(r.width - 6, parseFloat(cs.paddingLeft) + w - input.scrollLeft),
    y: r.top + r.height / 2,
  };
}

export function CreatePassword({
  onSubmit,
  checkBreaches,
  rules = PASSWORD_RULES,
  username,
  onValueChange,
  title = "Create a password",
  description,
  submitLabel = "Continue",
  name = "Hide",
  className = "",
}: CreatePasswordProps) {
  const reduced = useInteractionReducedMotion();
  const baseId = React.useId();
  const [password, setPassword] = React.useState("");
  const [shown, setShown] = React.useState(false);
  const [placed, setPlaced] = React.useState<Record<string, boolean>>({});
  const [breach, setBreach] = React.useState<{
    password: string;
    count: number;
  } | null>(null);
  const [act, setAct] = React.useState<{
    status: ActionStatus;
    checking?: boolean;
    error?: string;
  }>({ status: "idle" });
  const [startled, setStartled] = React.useState(false);
  const [said, setSaid] = React.useState("");
  const overlayRef = React.useRef<SVGSVGElement>(null);
  const inputRef = React.useRef<HTMLInputElement>(null);
  const hide = React.useRef<HideHandle>(null);
  const circles = React.useRef(new Map<string, HTMLElement>());
  // what the tongue has done and is about to do; the latest password for its callbacks
  const placedRef = React.useRef<Record<string, boolean>>({});
  const pending = React.useRef(new Set<string>());
  const latest = React.useRef("");
  const typedAt = React.useRef(0);
  const startleTimer = React.useRef(0);
  const checkRef = React.useRef(checkBreaches);

  React.useEffect(() => {
    checkRef.current = checkBreaches;
  });
  React.useEffect(() => () => window.clearTimeout(startleTimer.current), []);

  const met = rules.map((r) => r.test(password));
  const allMet = met.every(Boolean);
  const done = rules.filter((r) => placed[r.id]).length;
  const breached = Boolean(
    breach && breach.password === password && breach.count > 0,
  );
  const busy = act.status === "pending";

  // Once every rule is met, ask about breaches after a pause in the typing; a newer password aborts the older ask.
  React.useEffect(() => {
    if (!allMet || !checkRef.current) return;
    const ctrl = new AbortController();
    const timer = window.setTimeout(() => {
      checkRef.current?.(password, ctrl.signal).then(
        (count) => !ctrl.signal.aborted && setBreach({ password, count }),
        () => {},
      );
    }, 450);
    return () => {
      window.clearTimeout(timer);
      ctrl.abort();
    };
  }, [allMet, password]);

  const place = (next: Record<string, boolean>) => {
    placedRef.current = next;
    setPlaced(next);
  };

  /** Send the tongue wherever a check is wrong, one rule at a time. */
  const reconcile = () => {
    const value = latest.current;
    if (reduced) {
      place(Object.fromEntries(rules.map((r) => [r.id, r.test(value)])));
      return;
    }
    for (const r of rules) {
      const want = r.test(value);
      const target = circles.current.get(r.id);
      if (
        pending.current.has(r.id) ||
        want === Boolean(placedRef.current[r.id]) ||
        !target
      )
        continue;
      pending.current.add(r.id);
      hide.current?.flick(target, want ? "give" : "take", () => {
        pending.current.delete(r.id);
        place({ ...placedRef.current, [r.id]: want });
        setSaid(`${r.label}: ${want ? "done" : "missing"}.`);
        // the password may have moved on while the tongue was out
        window.setTimeout(reconcile, 0);
      });
    }
  };

  const change = (next: string) => {
    const before = Object.values(placedRef.current).filter(Boolean).length;
    latest.current = next;
    setPassword(next);
    onValueChange?.(next);
    if (act.status === "error" || act.status === "success")
      setAct({ status: "idle" });
    if (!next) {
      // wiped: the checks fall away at once and, if he was well hidden, he jumps
      pending.current.clear();
      place({});
      if (before >= 2) {
        hide.current?.startle();
        setStartled(true);
        window.clearTimeout(startleTimer.current);
        startleTimer.current = window.setTimeout(
          () => setStartled(false),
          1800,
        );
      }
      return;
    }
    setStartled(false);
    reconcile();
  };

  const followCaret = () => {
    const input = inputRef.current;
    if (input) hide.current?.look(caretAt(input));
  };

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!allMet || breached || busy) return;
    const value = password;
    try {
      const check = checkRef.current;
      if (check && !(breach && breach.password === value)) {
        setAct({ status: "pending", checking: true });
        let count = 0;
        try {
          count = await check(value, new AbortController().signal);
        } catch {
          // a breach service that's down shouldn't stop a sign-up
        }
        setBreach({ password: value, count });
        if (count > 0) {
          setAct({ status: "idle" });
          return;
        }
      }
      setAct({ status: "pending" });
      await onSubmit(value);
      setAct({ status: "success" });
      hide.current?.wink();
    } catch (err) {
      setAct({
        status: "error",
        error:
          err instanceof Error && err.message
            ? err.message
            : "Couldn’t save that. Try again.",
      });
    }
  };

  const mood =
    act.status === "success"
      ? `${name} is safe with you`
      : startled
        ? "Hey! I was hiding."
        : breached
          ? `${name} has been spotted`
          : shown && password
            ? `${name} feels exposed`
            : done === rules.length
              ? `Where did ${name} go?`
              : done > 0
                ? `${name} is blending in`
                : `${name} is easy to spot`;

  const error = breached
    ? `Seen in ${breach!.count.toLocaleString("en-US")} data breach${breach!.count === 1 ? "" : "es"}. Try another.`
    : act.status === "error"
      ? act.error
      : undefined;
  const ready = allMet && !breached;

  return (
    <section
      aria-labelledby={`${baseId}-title`}
      className={`relative w-full max-w-[380px] rounded-[28px] p-2 text-card-foreground ${className}`}
      style={{ ...CARD, ...HIDE }}
      onPointerMove={(e) => {
        // the pointer, unless he's watching the caret
        if (e.pointerType === "mouse" && e.timeStamp - typedAt.current > 1400)
          hide.current?.look({ x: e.clientX, y: e.clientY });
      }}
      onPointerLeave={() => hide.current?.look(null)}
    >
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 380px)" }}
      />
      <div className="@container w-full">
        <div
          className="relative isolate overflow-clip rounded-[22px] text-primary-foreground"
          style={STAGE}
        >
          <p className="absolute left-3.5 top-3 z-10 text-[12.5px] font-medium text-primary-foreground/85">
            <TextMorph>{mood}</TextMorph>
          </p>
          <Hide
            ref={hide}
            camo={done / Math.max(1, rules.length)}
            alarm={breached}
            exposed={shown && password.length > 0}
            reduced={reduced}
            overlay={overlayRef}
          />
        </div>

        <form className="px-2 pb-1 pt-3" onSubmit={submit} noValidate>
          <h2
            id={`${baseId}-title`}
            className="px-1 text-[15px] font-medium tracking-[-0.01em]"
          >
            {title}
          </h2>
          <p className="mt-0.5 px-1 text-[12.5px] text-muted-foreground">
            {description ??
              `The stronger it is, the harder ${name} is to find.`}
          </p>

          {username !== undefined && (
            <input
              type="text"
              name="username"
              autoComplete="username"
              value={username}
              readOnly
              hidden
            />
          )}
          <PasswordInput
            ref={inputRef}
            aria-label="Password"
            name="password"
            autoComplete="new-password"
            placeholder="Enter a password"
            className="mt-3"
            value={password}
            onValueChange={change}
            shown={shown}
            onShownChange={(on) => {
              setShown(on);
              setSaid(on ? "Password shown." : "Password hidden.");
            }}
            error={error}
            disabled={busy}
            onKeyDown={(e) => {
              typedAt.current = e.timeStamp;
            }}
            onKeyUp={followCaret}
            onSelect={followCaret}
            onFocus={followCaret}
            onClick={followCaret}
            onBlur={() => hide.current?.look(null)}
          />

          <ul
            aria-label="Your password needs"
            className="mt-2.5 grid grid-cols-1 gap-x-3 gap-y-1.5 px-1 @[270px]:grid-cols-2"
          >
            {rules.map((r) => {
              const on = Boolean(placed[r.id]);
              return (
                <li
                  key={r.id}
                  className="flex min-w-0 items-center gap-2 text-[12.5px]"
                >
                  <span
                    ref={(el) => {
                      if (el) circles.current.set(r.id, el);
                      else circles.current.delete(r.id);
                    }}
                    className="relative grid size-4 shrink-0 place-items-center rounded-full"
                    style={{
                      boxShadow: `inset 0 0 0 1px ${mix("var(--foreground)", 22, "var(--border)")}`,
                    }}
                  >
                    <span
                      className="absolute inset-0 rounded-full"
                      style={{
                        background: "var(--hide-check)",
                        opacity: on ? 1 : 0,
                        transform: on ? "scale(1)" : "scale(0.4)",
                        transition: reduced
                          ? "none"
                          : `opacity 200ms ${EASE_OUT}, transform 420ms ${EASE_THROW}`,
                      }}
                    />
                    <svg
                      viewBox="0 0 16 16"
                      className="relative size-3"
                      fill="none"
                      aria-hidden="true"
                    >
                      <path
                        d="M3.8 8.3 6.6 11 12.2 5"
                        stroke="white"
                        strokeWidth="2"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        pathLength={1}
                        strokeDasharray={1}
                        style={{
                          strokeDashoffset: on ? 0 : 1,
                          transition: reduced
                            ? "none"
                            : on
                              ? `stroke-dashoffset 320ms ${EASE_OUT} 60ms`
                              : "stroke-dashoffset 120ms",
                        }}
                      />
                    </svg>
                  </span>
                  <span
                    className={`truncate transition-colors duration-300 ${on ? "text-foreground" : "text-muted-foreground"}`}
                  >
                    {r.label}
                    <span className="sr-only">
                      {on ? ", done" : ", not yet"}
                    </span>
                  </span>
                </li>
              );
            })}
          </ul>

          <StatusButton
            type="submit"
            status={act.status}
            labels={{
              idle: submitLabel,
              pending: act.checking ? "Checking" : "Saving",
              success: "Password set",
              error: "Try again",
            }}
            disabled={!ready && !busy}
            className="mt-3 h-10 w-full text-[13.5px] disabled:bg-[color-mix(in_oklab,var(--foreground)_7%,transparent)] disabled:text-muted-foreground"
            style={ready && act.status !== "error" ? LIT : undefined}
          />
        </form>
      </div>

      {/* His tongue is drawn over the whole block, from his mouth to a rule and back. */}
      <svg
        ref={overlayRef}
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 z-20 size-full overflow-visible"
      />

      <span className="sr-only" role="status">
        {said}
      </span>
    </section>
  );
}

export default CreatePassword;

"use client";

import * as React from "react";
import {
  CRON_FIELDS,
  cronTokens,
  describeCron,
  nextRuns,
  parseCron,
  parseSchedule,
  type CronParse,
  type CronSchedule,
} from "./cron-parse";
import { NumberRoll } from "./number-roll";
import { PillSelect } from "./imported-pill-select";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * CRON INPUT: a schedule field people can read
 *
 *   type      a cron expression; each part has its name under
 *             it, and the part your caret is in lights up and
 *             gets a thin line that glides from part to part
 *   explain   the line below says it in words ("At 09:00,
 *             Monday to Friday") and crossfades as you type
 *   runs      the next five times it fires, in the schedule's
 *             time zone; hours and minutes roll as you edit
 *   english   "every weekday at 9am" works too: it's read as
 *             you type, and Enter turns the words into cron
 *   presets   a highlight slides to the preset that matches,
 *             and picking one morphs the expression into it:
 *             the parts both share stay where they are
 *   wrong     the part at fault turns red and says why; the last
 *             good runs stay, dimmed, so nothing jumps
 *   clocks    a run that a clock change skips or repeats says so
 * ───────────────────────────────────────────────────────── */

export interface CronPreset {
  label: string;
  expression: string;
}

export interface CronInputProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "defaultValue" | "onChange"
> {
  /** The schedule, controlled: a cron expression. */
  value?: string;
  /** A cron expression, or a schedule in English ("every weekday at 9am"). */
  defaultValue?: string;
  /** Called with each valid expression (tidied) and what it means. */
  onValueChange?: (expression: string, schedule: CronSchedule) => void;
  /** The zone the schedule runs in. Many schedulers only run in UTC. */
  timeZone?: string;
  defaultTimeZone?: string;
  /** Zones to choose from; with two or more, the zone becomes a dropdown. */
  timeZones?: string[];
  onTimeZoneChange?: (timeZone: string) => void;
  /** How many upcoming runs to list; 0 hides the list. */
  runs?: number;
  /** Shortcuts above the field; [] hides them. */
  presets?: CronPreset[];
  /** Read schedules typed in English. */
  english?: boolean;
  /** 1:30pm instead of 13:30. */
  hour12?: boolean;
  /** Accessible name of the field. */
  label?: string;
  locales?: string | string[];
  disabled?: boolean;
  name?: string;
}

export const CRON_PRESETS: CronPreset[] = [
  { label: "Every 15 min", expression: "*/15 * * * *" },
  { label: "Hourly", expression: "0 * * * *" },
  { label: "Daily 09:00", expression: "0 9 * * *" },
  { label: "Weekdays 09:00", expression: "0 9 * * 1-5" },
  { label: "Mondays 08:00", expression: "0 8 * * 1" },
  { label: "Monthly", expression: "0 0 1 * *" },
];

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FIELD_LABELS = ["minute", "hour", "day", "month", "weekday"];
const NAMES = new Set([
  "JAN",
  "FEB",
  "MAR",
  "APR",
  "MAY",
  "JUN",
  "JUL",
  "AUG",
  "SEP",
  "OCT",
  "NOV",
  "DEC",
  "SUN",
  "MON",
  "TUE",
  "WED",
  "THU",
  "FRI",
  "SAT",
  "L",
  "W",
]);
/** The field's type: one size for the input, its measuring copy and its morphing copy. */
const TYPE =
  "font-mono text-[14.5px] tracking-[0.02em] [@media(pointer:coarse)]:text-[16px]";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const tidy = (text: string) => text.trim().split(/\s+/).join(" ");
/** English if any word isn't a cron name (MON, JAN, L). */
const looksEnglish = (text: string) =>
  (text.match(/[a-z]+/gi) ?? ([] as string[])).some(
    (w) => !NAMES.has(w.toUpperCase()) && !/^\d*L$/i.test(w),
  );

function relative(ms: number) {
  const min = Math.round(ms / 60000);
  if (min < 1) return "in under a minute";
  if (min < 60) return `in ${min} min`;
  const h = Math.round(min / 60);
  if (h < 36) return `in ${h} h`;
  const d = Math.round(h / 24);
  if (d < 14) return `in ${d} days`;
  if (d < 60) return `in ${Math.round(d / 7)} weeks`;
  const mo = Math.round(d / 30.4);
  if (mo < 24) return `in ${mo} months`;
  return `in ${Math.round(d / 365)} years`;
}

function zoneOffset(timeZone: string) {
  try {
    const part = new Intl.DateTimeFormat("en-US", {
      timeZone,
      timeZoneName: "shortOffset",
    })
      .formatToParts(new Date())
      .find((p) => p.type === "timeZoneName");
    return part?.value.replace("GMT", "UTC") ?? "";
  } catch {
    return "";
  }
}
const cityOf = (tz: string) =>
  tz === "UTC" ? "UTC" : (tz.split("/").pop() ?? tz).replace(/_/g, " ");

/** A sentence that changes crossfades whole: the old one lifts away through a blur while the new one rises in. */
function Line({ text, reduced }: { text: string; reduced: boolean }) {
  const [shown, setShown] = React.useState({ text, key: 0 });
  const [leaving, setLeaving] = React.useState<{ text: string; key: number }[]>(
    [],
  );
  if (text !== shown.text) {
    if (shown.text && !reduced) setLeaving((l) => [...l.slice(-2), shown]);
    setShown({ text, key: shown.key + 1 });
  }
  return (
    <span className="relative block">
      <span
        key={shown.key}
        className="block"
        ref={(el) => {
          if (!el || reduced || shown.key === 0 || el.dataset.in) return;
          el.dataset.in = "1";
          el.animate(
            [
              {
                opacity: 0,
                transform: "translateY(0.3em)",
                filter: "blur(4px)",
              },
              { opacity: 1, transform: "none", filter: "blur(0px)" },
            ],
            { duration: 380, delay: 60, easing: EASE, fill: "backwards" },
          );
        }}
      >
        {shown.text || " "}
      </span>
      {leaving.map((l) => (
        <span
          key={l.key}
          aria-hidden="true"
          className="pointer-events-none absolute inset-x-0 top-0 block"
          ref={(el) => {
            if (!el || el.dataset.out) return;
            el.dataset.out = "1";
            el.animate(
              [
                { opacity: 1, transform: "none", filter: "blur(0px)" },
                {
                  opacity: 0,
                  transform: "translateY(-0.3em)",
                  filter: "blur(4px)",
                },
              ],
              { duration: 180, easing: EASE, fill: "forwards" },
            ).onfinish = () =>
              setLeaving((all) => all.filter((x) => x.key !== l.key));
          }}
        >
          {l.text}
        </span>
      ))}
    </span>
  );
}

/** The expression on its way from one text to another: TextMorph, started from what the field showed. */
function MorphOnce({
  from,
  to,
  onDone,
}: {
  from: string;
  to: string;
  onDone: () => void;
}) {
  const [text, setText] = React.useState(from);
  React.useEffect(() => {
    let inner = 0;
    const outer = requestAnimationFrame(
      () => (inner = requestAnimationFrame(() => setText(to))),
    );
    const timer = window.setTimeout(onDone, 820);
    return () => {
      cancelAnimationFrame(outer);
      cancelAnimationFrame(inner);
      window.clearTimeout(timer);
    };
  }, [to, onDone]);
  return (
    <TextMorph animateWidth={false} className="whitespace-pre">
      {text}
    </TextMorph>
  );
}

export function CronInput({
  value,
  defaultValue = "0 9 * * 1-5",
  onValueChange,
  timeZone,
  defaultTimeZone = "UTC",
  timeZones,
  onTimeZoneChange,
  runs: runCount = 5,
  presets = CRON_PRESETS,
  english = true,
  hour12 = false,
  label = "Schedule",
  locales,
  disabled = false,
  name,
  className = "",
  ...props
}: CronInputProps) {
  const uid = React.useId();
  const reduced = useReducedMotion();
  // A default written in English starts as those words, already read as cron.
  const [own, setOwn] = React.useState(() =>
    parseCron(defaultValue).ok || !english
      ? tidy(defaultValue)
      : (parseSchedule(defaultValue) ?? tidy(defaultValue)),
  );
  const committed = value !== undefined ? tidy(value) : own;
  const [text, setText] = React.useState(() =>
    value !== undefined ? tidy(value) : defaultValue.trim(),
  );
  const [ownZone, setOwnZone] = React.useState(defaultTimeZone);
  const zone = timeZone ?? ownZone;
  const [caret, setCaret] = React.useState<number | null>(null);
  const [focused, setFocused] = React.useState(false);
  const [morph, setMorph] = React.useState<{
    from: string;
    to: string;
    key: number;
  } | null>(null);
  const [marks, setMarks] = React.useState<{ x: number; w: number }[]>([]);
  const [labelX, setLabelX] = React.useState<number[]>([]);
  const [now, setNow] = React.useState<Date | null>(null);
  const [announce, setAnnounce] = React.useState("");
  const [presetMark, setPresetMark] = React.useState({
    x: 0,
    w: 0,
    on: false,
    slide: false,
  });
  const inputRef = React.useRef<HTMLInputElement>(null);
  const labelRefs = React.useRef<(HTMLSpanElement | null)[]>([]);
  const labelRow = React.useRef<HTMLDivElement>(null);
  const mirrorRef = React.useRef<HTMLSpanElement>(null);
  const presetRefs = React.useRef<(HTMLButtonElement | null)[]>([]);
  const [morphSeq, setMorphSeq] = React.useState(0);
  const [lastGood, setLastGood] = React.useState<CronSchedule | null>(null);

  // What the text means: cron, English that reads as cron, or a problem with a part to point at.
  const read = React.useMemo(() => {
    const cron = parseCron(text);
    if (cron.ok) return { kind: "cron" as const, schedule: cron.schedule };
    if (english && looksEnglish(text)) {
      const converted = parseSchedule(text);
      const parsed = converted ? parseCron(converted) : null;
      if (parsed?.ok)
        return { kind: "english" as const, schedule: parsed.schedule };
      return {
        kind: "error" as const,
        message:
          "Couldn’t read that. Try “every weekday at 9am” or cron like 0 9 * * 1-5.",
        field: null as number | null,
      };
    }
    const bad = cron as Extract<CronParse, { ok: false }>;
    return { kind: "error" as const, message: bad.message, field: bad.field };
  }, [text, english]);
  const schedule = read.kind === "error" ? null : read.schedule;
  if (schedule && lastGood !== schedule) {
    setLastGood(schedule);
  }
  const shownSchedule = schedule ?? lastGood;

  // A new value from outside morphs in.
  const [seen, setSeen] = React.useState(committed);
  if (committed !== seen) {
    setSeen(committed);
    if (tidy(text) !== committed) {
      const nextKey = morphSeq + 1;
      setMorphSeq(nextKey);
      if (!reduced) setMorph({ from: text, to: committed, key: nextKey });
      setText(committed);
    }
  }

  // Each valid cron expression is passed on as it's typed.
  if (
    value === undefined &&
    read.kind === "cron" &&
    read.schedule.expression !== own
  ) {
    setOwn(read.schedule.expression);
    setSeen(read.schedule.expression);
  }

  React.useEffect(() => {
    if (read.kind === "cron" && read.schedule.expression !== committed) {
      onValueChange?.(read.schedule.expression, read.schedule);
    }
  }, [read, committed, onValueChange]);

  const morphTo = (next: string) => {
    if (!reduced && next !== text) {
      setMorphSeq((k) => {
        const nextKey = k + 1;
        setMorph((m) => ({ from: m ? m.to : text, to: next, key: nextKey }));
        return nextKey;
      });
    }
    setText(next);
  };
  const morphDone = React.useCallback(() => setMorph(null), []);

  // English becomes cron on Enter or when you leave the field.
  const settle = () => {
    if (read.kind === "english") {
      morphTo(read.schedule.expression);
      setAnnounce(
        `Set to ${read.schedule.expression}: ${describeCron(read.schedule, { hour12 })}`,
      );
    }
  };

  // The clock for "in 3 h", re-read on each new minute (and only after mount, so the server's render matches).
  React.useEffect(() => {
    let timer = 0;
    const tick = () => {
      setNow(new Date());
      timer = window.setTimeout(tick, 60_000 - (Date.now() % 60_000) + 50);
    };
    tick();
    return () => window.clearTimeout(timer);
  }, []);

  const upcoming = React.useMemo(
    () =>
      shownSchedule && now && runCount
        ? nextRuns(shownSchedule, {
            from: now,
            count: runCount,
            timeZone: zone,
          })
        : [],
    [shownSchedule, now, runCount, zone],
  );

  // Where each part sits in the field, measured from a copy of the text in the same type.
  const tokens = React.useMemo(
    () => (read.kind === "english" ? [] : cronTokens(text)),
    [read.kind, text],
  );
  React.useLayoutEffect(() => {
    const mirror = mirrorRef.current;
    const input = inputRef.current;
    const node = mirror?.firstChild;
    if (!mirror || !input) return;
    const base = mirror.getBoundingClientRect().left;
    const next = tokens.slice(0, 6).map((t) => {
      if (!node) return { x: 0, w: 0 };
      const range = document.createRange();
      range.setStart(node, Math.min(t.start, node.textContent!.length));
      range.setEnd(node, Math.min(t.end, node.textContent!.length));
      const r = range.getBoundingClientRect();
      return { x: r.left - base - input.scrollLeft, w: r.width };
    });
    setMarks((prev) =>
      prev.length === next.length &&
      prev.every(
        (p, i) =>
          Math.abs(p.x - next[i].x) < 0.5 && Math.abs(p.w - next[i].w) < 0.5,
      )
        ? prev
        : next,
    );
  }, [tokens]);

  // Each name sits centred under its part, nudged along so none overlap or run past the edges.
  React.useLayoutEffect(() => {
    const row = labelRow.current;
    if (!row) return;
    const ws = FIELD_LABELS.map(
      (_, i) => labelRefs.current[i]?.offsetWidth ?? 0,
    );
    const xs = FIELD_LABELS.map((_, i) =>
      marks[i] ? marks[i].x + marks[i].w / 2 - ws[i] / 2 : 0,
    );
    const n = Math.min(marks.length, FIELD_LABELS.length);
    for (let i = 0; i < n; i++)
      xs[i] = Math.max(xs[i], i ? xs[i - 1] + ws[i - 1] + 8 : 0);
    for (let i = n - 1; i >= 0; i--)
      xs[i] = Math.min(
        xs[i],
        i === n - 1 ? row.offsetWidth - ws[i] : xs[i + 1] - 8 - ws[i],
      );
    setLabelX((prev) =>
      prev.length === xs.length &&
      prev.every((x, i) => Math.abs(x - xs[i]) < 0.5)
        ? prev
        : xs,
    );
  }, [marks]);

  const activeField =
    caret === null || !focused
      ? -1
      : tokens.findIndex((t) => caret >= t.start && caret <= t.end);
  const badField = read.kind === "error" ? read.field : null;
  const underline =
    badField !== null && badField < marks.length ? badField : activeField;

  // The highlight slides to the preset the schedule matches.
  const presetIndex = schedule
    ? presets.findIndex((p) => tidy(p.expression) === schedule.expression)
    : -1;
  React.useLayoutEffect(() => {
    const el = presetRefs.current[presetIndex];
    setPresetMark((m) =>
      el
        ? m.x === el.offsetLeft && m.w === el.offsetWidth && m.on
          ? m
          : { x: el.offsetLeft, w: el.offsetWidth, on: true, slide: m.on }
        : m.on
          ? { ...m, on: false, slide: false }
          : m,
    );
  }, [presetIndex, presets]);

  // The meaning, said once typing settles.
  const sentence = schedule ? describeCron(schedule, { hour12 }) : "";
  React.useEffect(() => {
    if (!focused) return;
    const t = window.setTimeout(
      () => setAnnounce(read.kind === "error" ? read.message : sentence),
      900,
    );
    return () => window.clearTimeout(t);
  }, [sentence, read, focused]);

  const lineText =
    read.kind === "error"
      ? read.message
      : read.kind === "english"
        ? `${sentence}. Press Enter to use ${read.schedule.expression}`
        : sentence;
  const dateFmt = React.useMemo(
    () =>
      new Intl.DateTimeFormat(locales ?? "en-GB", {
        weekday: "short",
        day: "numeric",
        month: "short",
        timeZone: "UTC",
      }),
    [locales],
  );
  const yearFmt = React.useMemo(
    () =>
      new Intl.DateTimeFormat(locales ?? "en-GB", {
        weekday: "short",
        day: "numeric",
        month: "short",
        year: "numeric",
        timeZone: "UTC",
      }),
    [locales],
  );
  const zoneOptions = React.useMemo(
    () =>
      (timeZones ?? []).map((tz) => ({
        value: tz,
        label: cityOf(tz),
        description: `${tz} · ${zoneOffset(tz)}`,
      })),
    [timeZones],
  );
  const nowYear = now?.getUTCFullYear();
  const errorTone = "text-red-600 dark:text-red-400";

  return (
    <div className={`w-full text-foreground ${className}`} {...props}>
      {presets.length > 0 && (
        <div
          role="group"
          aria-label="Presets"
          className="relative -mx-1 mb-2.5 flex gap-1 overflow-x-auto px-1 pb-0.5 [mask-image:linear-gradient(to_right,transparent,black_6px,black_calc(100%_-_20px),transparent)] [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
        >
          <span
            aria-hidden="true"
            className="pointer-events-none absolute left-0 top-0 h-7 rounded-full bg-accent shadow-[inset_0_0_0_1px_var(--border)]"
            style={{
              width: presetMark.w,
              transform: `translateX(${presetMark.x}px)`,
              opacity: presetMark.on ? 1 : 0,
              transition: reduced
                ? "none"
                : `${presetMark.slide ? `transform 380ms ${EASE}, width 380ms ${EASE}, ` : ""}opacity 200ms ${EASE}`,
            }}
          />
          {presets.map((p, i) => (
            <button
              key={p.expression}
              ref={(el) => {
                presetRefs.current[i] = el;
              }}
              type="button"
              disabled={disabled}
              aria-pressed={i === presetIndex}
              onClick={() => {
                morphTo(tidy(p.expression));
                inputRef.current?.focus({ preventScroll: true });
              }}
              className={`relative h-7 shrink-0 cursor-pointer whitespace-nowrap rounded-full px-2.5 text-[12px] font-medium transition-colors duration-200 hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 disabled:cursor-default ${
                i === presetIndex ? "text-foreground" : "text-muted-foreground"
              }`}
            >
              {p.label}
            </button>
          ))}
        </div>
      )}

      <div
        onMouseDown={(e) => {
          if ((e.target as HTMLElement).closest("button, input")) return;
          e.preventDefault();
          inputRef.current?.focus();
        }}
        className={`rounded-[14px] border bg-background px-3 pb-1.5 pt-2 transition-[border-color] duration-200 ${disabled ? "opacity-60" : "cursor-text"}`}
        style={{
          borderColor:
            read.kind === "error" && !focused
              ? "color-mix(in oklab, #ef4444 45%, var(--border))"
              : focused
                ? "color-mix(in oklab, var(--ring) 55%, var(--border))"
                : "var(--border)",
        }}
      >
        <div className="flex items-center gap-2">
          <div className="relative min-w-0 flex-1">
            <input
              ref={inputRef}
              value={text}
              disabled={disabled}
              aria-label={label}
              aria-invalid={read.kind === "error" || undefined}
              aria-describedby={`${uid}-line`}
              autoComplete="off"
              autoCapitalize="off"
              spellCheck={false}
              onChange={(e) => {
                setText(e.target.value);
                setCaret(e.target.selectionStart);
              }}
              onSelect={(e) => setCaret(e.currentTarget.selectionStart)}
              onFocus={() => setFocused(true)}
              onBlur={() => {
                setFocused(false);
                settle();
              }}
              onKeyDown={(e) => {
                if (e.key === "Enter") {
                  e.preventDefault();
                  settle();
                } else if (e.key === "Escape" && tidy(text) !== committed) {
                  e.preventDefault();
                  e.stopPropagation();
                  morphTo(committed);
                }
              }}
              placeholder="0 9 * * 1-5"
              className={`h-8 w-full min-w-0 bg-transparent outline-none placeholder:text-muted-foreground disabled:cursor-default ${TYPE}`}
              style={{
                wordSpacing: read.kind === "english" ? "normal" : "1.1em",
                color: morph ? "transparent" : undefined,
                caretColor: morph ? "var(--foreground)" : undefined,
              }}
            />
            {/* A copy of the text in the same type, measured to place each part's name under it. */}
            <span
              ref={mirrorRef}
              aria-hidden="true"
              className={`pointer-events-none invisible absolute left-0 top-0 whitespace-pre ${TYPE}`}
              style={{
                wordSpacing: read.kind === "english" ? "normal" : "1.1em",
              }}
            >
              {text}
            </span>
            {morph && (
              <span
                aria-hidden="true"
                className={`pointer-events-none absolute inset-y-0 left-0 flex items-center whitespace-pre ${TYPE}`}
                style={{ wordSpacing: "1.1em" }}
              >
                <MorphOnce
                  key={morph.key}
                  from={morph.from}
                  to={morph.to}
                  onDone={morphDone}
                />
              </span>
            )}
            {/* The part you're in, or the part at fault: a thin line that glides from part to part. */}
            <span
              aria-hidden="true"
              className={`pointer-events-none absolute -bottom-px left-0 h-px ${badField !== null ? "bg-red-500" : "bg-primary"}`}
              style={{
                width: marks[underline]?.w ?? 0,
                transform: `translateX(${marks[underline]?.x ?? 0}px)`,
                opacity: underline >= 0 && marks[underline] && !morph ? 1 : 0,
                transition: reduced
                  ? "none"
                  : `transform 300ms ${EASE}, width 300ms ${EASE}, opacity 200ms ${EASE}`,
              }}
            />
          </div>
          {zoneOptions.length > 1 ? (
            <PillSelect
              label="Time zone"
              options={zoneOptions}
              value={zone}
              align="end"
              width={250}
              display={(o) => o?.label ?? cityOf(zone)}
              onValueChange={(tz) => {
                if (timeZone === undefined) setOwnZone(tz);
                onTimeZoneChange?.(tz);
              }}
            />
          ) : (
            <span className="shrink-0 text-[12px] font-medium text-muted-foreground">
              {cityOf(zone)}
            </span>
          )}
        </div>

        {/* The name of each part, under it; folds away while you write in English. */}
        <div
          className="grid"
          style={{
            gridTemplateRows: read.kind === "english" ? "0fr" : "1fr",
            transition: reduced ? "none" : `grid-template-rows 320ms ${EASE}`,
          }}
        >
          <div className="min-h-0 overflow-hidden">
            <div
              ref={labelRow}
              aria-hidden="true"
              className="relative mt-0.5 h-4 text-[10.5px] leading-4"
            >
              {FIELD_LABELS.map((name, i) => {
                const m = marks[i];
                const tone =
                  badField === i
                    ? errorTone
                    : activeField === i
                      ? "text-foreground"
                      : "text-muted-foreground";
                return (
                  <span
                    key={name}
                    ref={(el) => {
                      labelRefs.current[i] = el;
                    }}
                    className={`absolute left-0 top-0 whitespace-nowrap transition-colors duration-200 ${tone}`}
                    style={{
                      transform: `translateX(${labelX[i] ?? i * 48}px)`,
                      opacity: m && read.kind !== "english" ? 1 : 0,
                      transition: reduced
                        ? "none"
                        : `transform 340ms ${EASE}, opacity 200ms ${EASE}, color 200ms`,
                    }}
                  >
                    {name}
                  </span>
                );
              })}
            </div>
          </div>
        </div>
      </div>

      <p
        id={`${uid}-line`}
        className={`mt-2 min-h-[1.45em] pl-1 text-[12.5px] leading-[1.45] transition-colors duration-300 ${read.kind === "error" ? errorTone : "text-muted-foreground"}`}
      >
        <Line text={lineText} reduced={reduced} />
      </p>

      {runCount > 0 && (
        <div className="mt-3 border-t border-border pt-3">
          <div className="flex items-baseline justify-between gap-3 text-[11.5px] text-muted-foreground">
            <span className="font-medium">Next runs</span>
            <span className="truncate">
              {zone === "UTC"
                ? "Times in UTC"
                : `Times in ${cityOf(zone)} · ${zoneOffset(zone)}`}
            </span>
          </div>
          {now && upcoming.length === 0 && shownSchedule && (
            <p className={`mt-2 text-[12.5px] ${errorTone}`}>
              This never runs: no date in the next six years matches it.
            </p>
          )}
          <ol
            aria-label="Next runs"
            className="mt-1.5 transition-opacity duration-300"
            style={{
              opacity: schedule ? 1 : 0.45,
              transitionTimingFunction: EASE,
            }}
          >
            {upcoming.map((r, i) => {
              const w = r.wall;
              const dayDate = new Date(Date.UTC(w.year, w.month - 1, w.day));
              const day = (w.year === nowYear ? dateFmt : yearFmt).format(
                dayDate,
              );
              const h = hour12 ? w.hour % 12 || 12 : w.hour;
              const note = r.skipped
                ? `Clocks go forward that night: ${String(w.hour).padStart(2, "0")}:${String(w.minute).padStart(2, "0")} doesn’t happen in ${cityOf(zone)}.`
                : r.repeated
                  ? `Clocks go back that night: ${String(w.hour).padStart(2, "0")}:${String(w.minute).padStart(2, "0")} happens twice in ${cityOf(zone)}.`
                  : null;
              return (
                <li
                  key={i}
                  className="border-b border-border/60 py-1.5 last:border-b-0"
                >
                  <span className="sr-only">
                    {day}, {String(w.hour).padStart(2, "0")}:
                    {String(w.minute).padStart(2, "0")},{" "}
                    {now ? relative(r.at.getTime() - now.getTime()) : ""}
                    {note ? `. ${note}` : ""}
                  </span>
                  <span
                    aria-hidden="true"
                    className="flex items-baseline gap-3 text-[13px]"
                  >
                    <span className="w-[6.5rem] shrink-0">
                      <TextMorph>{day}</TextMorph>
                    </span>
                    <span className="inline-flex font-medium tabular-nums">
                      <NumberRoll
                        value={h}
                        format={
                          hour12 ? undefined : { minimumIntegerDigits: 2 }
                        }
                        duration={700}
                      />
                      <span>:</span>
                      <NumberRoll
                        value={w.minute}
                        format={{ minimumIntegerDigits: 2 }}
                        duration={700}
                      />
                      {hour12 && (
                        <TextMorph className="ml-0.5">
                          {w.hour < 12 ? "am" : "pm"}
                        </TextMorph>
                      )}
                    </span>
                    {note && (
                      <svg
                        viewBox="0 0 16 16"
                        fill="none"
                        className="size-3.5 shrink-0 self-center text-amber-600 dark:text-amber-400"
                      >
                        <circle
                          cx="8"
                          cy="8"
                          r="6.25"
                          stroke="currentColor"
                          strokeWidth="1.5"
                        />
                        <path
                          d="M8 4.75v3.75"
                          stroke="currentColor"
                          strokeWidth="1.75"
                          strokeLinecap="round"
                        />
                        <circle cx="8" cy="11" r="1" fill="currentColor" />
                      </svg>
                    )}
                    <span className="ml-auto truncate text-[12px] text-muted-foreground">
                      <TextMorph>
                        {now ? relative(r.at.getTime() - now.getTime()) : ""}
                      </TextMorph>
                    </span>
                  </span>
                  {note && (
                    <span className="mt-0.5 block text-[11.5px] leading-snug text-amber-700 dark:text-amber-400">
                      {note}
                    </span>
                  )}
                </li>
              );
            })}
          </ol>
        </div>
      )}

      {name && <input type="hidden" name={name} value={committed} />}
      <span className="sr-only" role="status" aria-live="polite">
        {announce}
      </span>
    </div>
  );
}

export { describeCron, nextRuns, parseCron, parseSchedule };
export type { CronSchedule };
export { CRON_FIELDS };

/* ─────────────────────────────────────────────────────────
 * CRON PARSE: read, explain and run a cron expression
 *
 *   parseCron      five fields (minute hour day month weekday),
 *                  @macros, names (MON, JAN), ranges, lists,
 *                  steps, L for the last day of the month, and
 *                  FRI#2 / 5L for the nth or last weekday. Errors
 *                  say which field and why
 *   describeCron   the schedule in plain words: "At 09:00,
 *                  Monday to Friday"
 *   nextRuns       the next times it fires in a time zone,
 *                  flagging clock changes that skip or repeat one
 *   parseSchedule  plain English to cron: "every weekday at 9am",
 *                  "every 15 minutes from 9 to 5", "last friday
 *                  of the month at 17:30"
 *
 * Day and weekday follow Unix cron: when both are set, either
 * one matching is enough; when one starts with *, the other
 * decides. 0 and 7 are both Sunday.
 * ───────────────────────────────────────────────────────── */

export type CronFieldName = "minute" | "hour" | "day" | "month" | "weekday";

export const CRON_FIELDS: { name: CronFieldName; min: number; max: number }[] =
  [
    { name: "minute", min: 0, max: 59 },
    { name: "hour", min: 0, max: 23 },
    { name: "day", min: 1, max: 31 },
    { name: "month", min: 1, max: 12 },
    { name: "weekday", min: 0, max: 7 },
  ];

const MONTHS = [
  "JAN",
  "FEB",
  "MAR",
  "APR",
  "MAY",
  "JUN",
  "JUL",
  "AUG",
  "SEP",
  "OCT",
  "NOV",
  "DEC",
];
const DAYS = ["SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT"];
const MONTH_NAMES = [
  "January",
  "February",
  "March",
  "April",
  "May",
  "June",
  "July",
  "August",
  "September",
  "October",
  "November",
  "December",
];
const DAY_NAMES = [
  "Sunday",
  "Monday",
  "Tuesday",
  "Wednesday",
  "Thursday",
  "Friday",
  "Saturday",
];
const NTH = ["", "first", "second", "third", "fourth", "fifth"];
const MACROS: Record<string, string> = {
  "@yearly": "0 0 1 1 *",
  "@annually": "0 0 1 1 *",
  "@monthly": "0 0 1 * *",
  "@weekly": "0 0 * * 0",
  "@daily": "0 0 * * *",
  "@midnight": "0 0 * * *",
  "@hourly": "0 * * * *",
};

export interface CronSchedule {
  /** The five fields, tidied: single spaces, macros expanded. */
  expression: string;
  minutes: number[];
  hours: number[];
  days: number[];
  months: number[];
  /** 0–6, Sunday first. */
  weekdays: number[];
  /** L in the day field. */
  lastDay: boolean;
  /** FRI#2 (nth 2) or 5L (nth -1). */
  nthWeekdays: { weekday: number; nth: number }[];
  /** The field started with * (or ?), so the other one decides. */
  dayStar: boolean;
  weekdayStar: boolean;
}

export type CronParse =
  | { ok: true; schedule: CronSchedule }
  | { ok: false; message: string; field: number | null };

/** Where each field sits in the text, for pointing at it. */
export function cronTokens(
  text: string,
): { start: number; end: number; text: string }[] {
  const out: { start: number; end: number; text: string }[] = [];
  const re = /\S+/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(text)))
    out.push({ start: m.index, end: m.index + m[0].length, text: m[0] });
  return out;
}

const range = (a: number, b: number, step = 1) => {
  const out: number[] = [];
  for (let i = a; i <= b; i += step) out.push(i);
  return out;
};

type Field = {
  values: Set<number>;
  star: boolean;
  last?: boolean;
  nth?: { weekday: number; nth: number }[];
};

function value(raw: string, f: number): number | string {
  const { min, max, name } = CRON_FIELDS[f];
  const up = raw.toUpperCase();
  if (f === 3 && MONTHS.includes(up)) return MONTHS.indexOf(up) + 1;
  if (f === 4 && DAYS.includes(up)) return DAYS.indexOf(up);
  if (!/^\d+$/.test(raw)) {
    if (f === 3) return `“${raw}” isn’t a month. Use 1–12 or JAN–DEC.`;
    if (f === 4) return `“${raw}” isn’t a weekday. Use 0–6 or SUN–SAT.`;
    return `“${raw}” isn’t a number. The ${name} goes from ${min} to ${max}.`;
  }
  const n = Number(raw);
  if (n < min || n > max)
    return `The ${name} goes from ${min} to ${max}${f === 4 ? " (0 and 7 are Sunday)" : ""}, not ${n}.`;
  return n;
}

function field(token: string, f: number): Field | string {
  const { min, max, name } = CRON_FIELDS[f];
  const out: Field = {
    values: new Set(),
    star: token[0] === "*" || token[0] === "?",
  };
  for (const part of token.split(",")) {
    if (!part) return `There’s an empty item in the ${name} list.`;
    if (f === 2 && /^L$/i.test(part)) {
      out.last = true;
      continue;
    }
    if (f === 4) {
      const nth = part.match(/^(\w+)(?:#(\d)|(L))$/i);
      if (nth) {
        const day = value(nth[1], 4);
        if (typeof day === "string") return day;
        const n = nth[3] ? -1 : Number(nth[2]);
        if (n === 0 || n > 5)
          return `#${nth[2]} can’t be: a weekday comes 1 to 5 times a month.`;
        (out.nth ??= []).push({ weekday: day % 7, nth: n });
        continue;
      }
    }
    if (/W/i.test(part) && f === 2)
      return "W (nearest weekday) isn’t supported. Use a day number or L.";
    const [base, stepText] = part.split("/");
    let step = 1;
    if (stepText !== undefined) {
      if (!/^\d+$/.test(stepText) || Number(stepText) < 1)
        return `A step needs a number after the slash, like ${base || "*"}/5.`;
      step = Number(stepText);
      if (step > max)
        return `A ${name} step of ${step} is bigger than the ${name} range.`;
    }
    let lo: number;
    let hi: number;
    if (base === "*" || base === "?") {
      lo = min;
      hi = f === 4 ? 6 : max;
    } else if (base.includes("-")) {
      const [a, b, extra] = base.split("-");
      if (extra !== undefined || !a || !b)
        return `“${base}” isn’t a range. Write it as low-high, like 1-5.`;
      const va = value(a, f);
      const vb = value(b, f);
      if (typeof va === "string") return va;
      if (typeof vb === "string") return vb;
      if (va > vb && !(f === 4 && vb === 0))
        return `Ranges go from low to high: ${b}-${a}, not ${base}.`;
      lo = va;
      hi = f === 4 && vb === 0 ? 7 : vb;
    } else {
      const v = value(base, f);
      if (typeof v === "string") return v;
      lo = v;
      hi = stepText !== undefined ? (f === 4 ? 6 : max) : v;
    }
    for (const n of range(lo, hi, step)) out.values.add(f === 4 ? n % 7 : n);
  }
  return out;
}

export function parseCron(text: string): CronParse {
  const trimmed = text.trim();
  if (!trimmed)
    return {
      ok: false,
      message: "Type a cron expression, like 0 9 * * 1-5.",
      field: null,
    };
  const macro = MACROS[trimmed.toLowerCase()];
  const tokens = (macro ?? trimmed).split(/\s+/);
  if (trimmed.startsWith("@") && !macro)
    return {
      ok: false,
      message: `${trimmed} isn’t a shortcut cron knows. Try @daily, @weekly or @hourly.`,
      field: 0,
    };
  if (tokens.length !== 5)
    return {
      ok: false,
      message:
        tokens.length < 5
          ? `Cron has five parts: minute, hour, day, month, weekday. This has ${tokens.length}.`
          : `Cron has five parts; this has ${tokens.length}. Seconds and years aren’t supported.`,
      field: tokens.length > 5 ? 5 : null,
    };
  const fields: Field[] = [];
  for (let i = 0; i < 5; i++) {
    const r = field(tokens[i], i);
    if (typeof r === "string") return { ok: false, message: r, field: i };
    fields.push(r);
  }
  const sorted = (f: Field) => [...f.values].sort((a, b) => a - b);
  return {
    ok: true,
    schedule: {
      expression: tokens.join(" "),
      minutes: sorted(fields[0]),
      hours: sorted(fields[1]),
      days: sorted(fields[2]),
      months: sorted(fields[3]),
      weekdays: sorted(fields[4]),
      lastDay: Boolean(fields[2].last),
      nthWeekdays: fields[4].nth ?? [],
      dayStar: fields[2].star,
      weekdayStar: fields[4].star,
    },
  };
}

/* ── Plain words ──────────────────────────────────────── */

const pad = (n: number) => String(n).padStart(2, "0");
const ordinal = (n: number) => {
  const s =
    n % 100 >= 11 && n % 100 <= 13
      ? "th"
      : (["th", "st", "nd", "rd"][n % 10] ?? "th");
  return `${n}${s}`;
};
const list = (items: string[]) =>
  items.length <= 1
    ? (items[0] ?? "")
    : `${items.slice(0, -1).join(", ")} and ${items[items.length - 1]}`;
/** [a..b] if the values run without a gap. */
const run = (v: number[]) =>
  v.length > 1 && v.every((n, i) => i === 0 || n === v[i - 1] + 1)
    ? [v[0], v[v.length - 1]]
    : null;
/** k if the values are min, min+k, min+2k… to the end of the range. */
const stepOf = (v: number[], min: number, max: number) => {
  if (v.length < 2 || v[0] !== min) return null;
  const k = v[1] - v[0];
  if (k < 2 || !v.every((n, i) => n === min + i * k)) return null;
  return v[v.length - 1] + k > max ? k : null;
};

export function describeCron(
  s: CronSchedule,
  { hour12 = false }: { hour12?: boolean } = {},
): string {
  const time = (h: number, m: number) =>
    hour12
      ? `${h % 12 || 12}:${pad(m)}${h < 12 ? "am" : "pm"}`
      : `${pad(h)}:${pad(m)}`;
  const M = s.minutes;
  const H = s.hours;
  const allM = M.length === 60;
  const allH = H.length === 24;
  const mStep = stepOf(M, 0, 59);
  const hStep = stepOf(H, 0, 23);
  const hRun = run(H);

  let when: string;
  if (allM && allH) when = "Every minute";
  else if (allM && hRun)
    when = `Every minute from ${time(hRun[0], 0)} to ${time(hRun[1], 59)}`;
  else if (mStep && allH) when = `Every ${mStep} minutes`;
  else if (mStep && hRun)
    when = `Every ${mStep} minutes from ${time(hRun[0], 0)} to ${time(hRun[1], M[M.length - 1])}`;
  else if (M.length === 1 && allH)
    when = M[0] === 0 ? "Every hour" : `Every hour at :${pad(M[0])}`;
  else if (M.length === 1 && hStep)
    when = `Every ${hStep} hours${M[0] ? ` at :${pad(M[0])}` : ""}`;
  else if (M.length === 1 && hRun && H.length >= 4)
    when = `Every hour from ${time(hRun[0], M[0])} to ${time(hRun[1], M[0])}`;
  else if (M.length * H.length <= 6 && !allH && !allM)
    when = `At ${list(H.flatMap((h) => M.map((m) => time(h, m))))}`;
  else if (M.length <= 4 && allH)
    when = `At ${list(M.map((m) => `:${pad(m)}`))} past every hour`;
  else {
    const part = (v: number[], min: number, max: number) => {
      const k = stepOf(v, min, max);
      const r = run(v);
      return k ? `every ${k}` : r ? `${r[0]} to ${r[1]}` : list(v.map(String));
    };
    when = `At minute ${allM ? "every" : part(M, 0, 59)} past ${allH ? "every hour" : `hour ${part(H, 0, 23)}`}`;
  }

  // Which days.
  const wd = s.weekdays;
  const weekdayWords = () => {
    const nth = s.nthWeekdays.map(
      (n) =>
        `the ${n.nth === -1 ? "last" : NTH[n.nth]} ${DAY_NAMES[n.weekday]} of the month`,
    );
    let plain = "";
    if (wd.length && wd.length < 7) {
      const r = run(wd);
      if (wd.length === 5 && wd[0] === 1 && wd[4] === 5)
        plain = "Monday to Friday";
      else if (wd.length === 2 && wd[0] === 0 && wd[1] === 6)
        plain = "on weekends";
      else if (r && r[1] - r[0] >= 2)
        plain = `${DAY_NAMES[r[0]]} to ${DAY_NAMES[r[1]]}`;
      else
        plain =
          wd.length === 1
            ? `every ${DAY_NAMES[wd[0]]}`
            : `on ${list(wd.map((d) => `${DAY_NAMES[d]}s`))}`;
    }
    const nthText = nth.length ? `on ${list(nth)}` : "";
    return [plain, nthText].filter(Boolean).join(" and ");
  };
  const dayWords = () => {
    const days = s.days.length === 31 ? [] : s.days;
    const k = stepOf(s.days, 1, 31);
    const parts: string[] = [];
    if (k) parts.push(`every ${k} days of the month`);
    else if (days.length) {
      const r = run(days);
      parts.push(
        r && r[1] - r[0] >= 2
          ? `on days ${r[0]} to ${r[1]} of the month`
          : `on the ${list(days.map(ordinal))} of the month`,
      );
    }
    if (s.lastDay) parts.push("on the last day of the month");
    return parts.join(" and ");
  };
  const restrictedDay = s.lastDay || s.days.length < 31;
  const restrictedWeekday = s.nthWeekdays.length > 0 || wd.length < 7;
  let days = "";
  // Both set: Unix cron runs on either (unless one starts with *, when both must match).
  if (restrictedDay && restrictedWeekday)
    days =
      !s.dayStar && !s.weekdayStar
        ? `${dayWords()}, and ${weekdayWords()}`
        : `${dayWords()}, ${weekdayWords()}`;
  else if (restrictedWeekday) days = weekdayWords();
  else if (restrictedDay) days = dayWords();

  // Which months; one day in one month reads as a date.
  const mo = s.months;
  let months = "";
  if (mo.length < 12) {
    const r = run(mo);
    if (
      mo.length === 1 &&
      s.days.length === 1 &&
      !restrictedWeekday &&
      !s.lastDay
    ) {
      days = `on ${s.days[0]} ${MONTH_NAMES[mo[0] - 1]}`;
    } else
      months =
        r && r[1] - r[0] >= 2
          ? `in ${MONTH_NAMES[r[0] - 1]} to ${MONTH_NAMES[r[1] - 1]}`
          : `in ${list(mo.map((m) => MONTH_NAMES[m - 1]))}`;
  }

  if (!days && !months)
    return when.startsWith("At ") && !when.includes("past")
      ? `Every day at ${when.slice(3)}`
      : when;
  const joiner = (phrase: string) =>
    phrase.startsWith("on ") ||
    phrase.startsWith("in ") ||
    phrase.startsWith("every ")
      ? " "
      : ", ";
  let out = when;
  if (days) out += joiner(days) + days;
  if (months) out += (days ? ", " : joiner(months)) + months;
  return out;
}

/* ── Next runs ────────────────────────────────────────── */

export interface CronRun {
  at: Date;
  /** The wall-clock time it was asked for, in the time zone. */
  wall: {
    year: number;
    month: number;
    day: number;
    hour: number;
    minute: number;
    weekday: number;
  };
  /** Clocks go forward over this time: it doesn't exist that day. */
  skipped?: boolean;
  /** Clocks go back over this time: it happens twice (this is the first). */
  repeated?: boolean;
}

const formatters = new Map<string, Intl.DateTimeFormat>();
function wallAt(epoch: number, timeZone: string) {
  let f = formatters.get(timeZone);
  if (!f) {
    f = new Intl.DateTimeFormat("en-US", {
      timeZone,
      hourCycle: "h23",
      year: "numeric",
      month: "numeric",
      day: "numeric",
      hour: "numeric",
      minute: "numeric",
      second: "numeric",
    });
    formatters.set(timeZone, f);
  }
  const p: Record<string, number> = {};
  for (const part of f.formatToParts(new Date(epoch)))
    if (part.type !== "literal") p[part.type] = Number(part.value);
  return {
    year: p.year,
    month: p.month,
    day: p.day,
    hour: p.hour % 24,
    minute: p.minute,
    second: p.second,
  };
}
/** Minutes the zone is ahead of UTC at an instant. */
function offsetAt(epoch: number, timeZone: string) {
  const w = wallAt(epoch, timeZone);
  return Math.round(
    (Date.UTC(w.year, w.month - 1, w.day, w.hour, w.minute, w.second) -
      Math.floor(epoch / 1000) * 1000) /
      60000,
  );
}

/** The instant a wall-clock time happens in a zone, and whether a clock change skips or repeats it. */
export function zonedTime(
  year: number,
  month: number,
  day: number,
  hour: number,
  minute: number,
  timeZone: string,
) {
  const guess = Date.UTC(year, month - 1, day, hour, minute);
  const before = offsetAt(guess - 6 * 3600_000, timeZone);
  const after = offsetAt(guess + 6 * 3600_000, timeZone);
  const fits = (t: number) => {
    const w = wallAt(t, timeZone);
    return (
      w.year === year &&
      w.month === month &&
      w.day === day &&
      w.hour === hour &&
      w.minute === minute
    );
  };
  if (before === after)
    return { at: guess - before * 60000, skipped: false, repeated: false };
  const a = guess - before * 60000;
  const b = guess - after * 60000;
  const fa = fits(a);
  const fb = fits(b);
  if (fa && fb && a !== b)
    return { at: Math.min(a, b), skipped: false, repeated: true };
  if (fa || fb) return { at: fa ? a : b, skipped: false, repeated: false };
  // In the gap: it would land an hour (the jump) later on the clock.
  return { at: a, skipped: true, repeated: false };
}

const daysIn = (y: number, m: number) =>
  new Date(Date.UTC(y, m, 0)).getUTCDate();

/** The next `count` times the schedule fires after `from`, in `timeZone` (UTC by default). Looks up to six years ahead. */
export function nextRuns(
  s: CronSchedule,
  {
    from = new Date(),
    count = 5,
    timeZone = "UTC",
  }: { from?: Date; count?: number; timeZone?: string } = {},
): CronRun[] {
  const out: CronRun[] = [];
  const start = wallAt(from.getTime() + 60_000, timeZone);
  const months = new Set(s.months);
  const days = new Set(s.days);
  const weekdays = new Set(s.weekdays);
  const first = Date.UTC(start.year, start.month - 1, start.day);
  for (let i = 0; i < 366 * 6 && out.length < count; i++) {
    const date = new Date(first + i * 86_400_000);
    const y = date.getUTCFullYear();
    const m = date.getUTCMonth() + 1;
    const d = date.getUTCDate();
    const wd = date.getUTCDay();
    if (!months.has(m)) continue;
    const dim = daysIn(y, m);
    const dayHit = days.has(d) || (s.lastDay && d === dim);
    const weekdayHit =
      weekdays.has(wd) ||
      s.nthWeekdays.some(
        (n) =>
          n.weekday === wd &&
          (n.nth === -1 ? d + 7 > dim : Math.ceil(d / 7) === n.nth),
      );
    // Unix cron: if either field starts with *, both must match; if both are set, either one is enough.
    if (
      s.dayStar || s.weekdayStar
        ? !(dayHit && weekdayHit)
        : !(dayHit || weekdayHit)
    )
      continue;
    for (const h of s.hours) {
      if (i === 0 && h < start.hour) continue;
      for (const min of s.minutes) {
        if (i === 0 && h === start.hour && min < start.minute) continue;
        const z = zonedTime(y, m, d, h, min, timeZone);
        if (z.at <= from.getTime()) continue;
        out.push({
          at: new Date(z.at),
          wall: {
            year: y,
            month: m,
            day: d,
            hour: h,
            minute: min,
            weekday: wd,
          },
          skipped: z.skipped || undefined,
          repeated: z.repeated || undefined,
        });
        if (out.length === count) return out;
      }
    }
  }
  return out;
}

/* ── Plain English in ─────────────────────────────────── */

const DAY_WORDS: Record<string, number> = {
  sun: 0,
  sunday: 0,
  mon: 1,
  monday: 1,
  tue: 2,
  tues: 2,
  tuesday: 2,
  wed: 3,
  weds: 3,
  wednesday: 3,
  thu: 4,
  thur: 4,
  thurs: 4,
  thursday: 4,
  fri: 5,
  friday: 5,
  sat: 6,
  saturday: 6,
};
const MONTH_WORDS: Record<string, number> = Object.fromEntries(
  MONTH_NAMES.flatMap((name, i) => [
    [name.toLowerCase(), i + 1],
    [name.slice(0, 3).toLowerCase(), i + 1],
  ]).concat([["sept", 9]]),
);
const NTH_WORDS: Record<string, number> = {
  first: 1,
  "1st": 1,
  second: 2,
  "2nd": 2,
  third: 3,
  "3rd": 3,
  fourth: 4,
  "4th": 4,
  last: -1,
};
const DAY_RE = `(?:${Object.keys(DAY_WORDS)
  .sort((a, b) => b.length - a.length)
  .join("|")})`;
const MONTH_RE = `(?:${Object.keys(MONTH_WORDS)
  .sort((a, b) => b.length - a.length)
  .join("|")})`;
const TIME_ANY = String.raw`(?:noon|midday|midnight|\d{1,2}(?:[:.h]\d{2})?\s?(?:am|pm)?)`;
const TIME_STRICT = String.raw`(?:noon|midday|midnight|\d{1,2}[:.h]\d{2}\s?(?:am|pm)?|\d{1,2}\s?(?:am|pm))`;
const FILLER = new Set([
  "at",
  "on",
  "the",
  "of",
  "and",
  "every",
  "each",
  "in",
  "run",
  "runs",
  "it",
  "please",
  "a",
  "month",
  "day",
  "days",
]);

function readTime(raw: string): { h: number; m: number } | null {
  const t = raw.trim();
  if (t === "noon" || t === "midday") return { h: 12, m: 0 };
  if (t === "midnight") return { h: 0, m: 0 };
  const m = t.match(/^(\d{1,2})(?:[:.h](\d{2}))?\s?(am|pm)?$/);
  if (!m) return null;
  let h = Number(m[1]);
  const min = m[2] ? Number(m[2]) : 0;
  if (m[3]) {
    if (h < 1 || h > 12) return null;
    h = (h % 12) + (m[3] === "pm" ? 12 : 0);
  }
  if (h > 23 || min > 59) return null;
  return { h, m: min };
}

/** Turns a schedule written in English into cron, or null if it can't be read. */
export function parseSchedule(text: string): string | null {
  let s = ` ${text
    .toLowerCase()
    .replace(/[,;]/g, " ")
    .replace(/\b(through|thru|until|till)\b/g, "to")
    .replace(/\s+/g, " ")
    .trim()} `;
  const take = (re: RegExp) => {
    const m = s.match(re);
    if (m) s = s.replace(m[0], " ");
    return m;
  };
  let minute: string | null = null;
  let hour: string | null = null;
  let dom = "*";
  let mon = "*";
  let dow = "*";
  let m: RegExpMatchArray | null;

  if ((m = take(/ every (\d+ )?(?:minutes?|mins?) /))) {
    const n = m[1] ? Number(m[1]) : 1;
    if (n < 1 || n > 59) return null;
    minute = n === 1 ? "*" : `*/${n}`;
    hour = "*";
  } else if (
    (m = take(/ every (\d+ )?(?:hours?|hrs?) /)) ||
    (m = take(/ hourly /))
  ) {
    const n = m[1] ? Number(m[1]) : 1;
    if (n < 1 || n > 23) return null;
    minute = "0";
    hour = n === 1 ? "*" : `*/${n}`;
    const past = take(/ at :?(\d{1,2})(?: minutes)?(?: past)? /);
    if (past) {
      if (Number(past[1]) > 59) return null;
      minute = String(Number(past[1]));
    }
  }

  // A window for steps: "from 9am to 5pm", "between 9 and 17".
  if (
    (m = take(
      new RegExp(` (?:from|between) (${TIME_ANY}) (?:to|and|-) (${TIME_ANY}) `),
    ))
  ) {
    const a = readTime(m[1]);
    const b = readTime(m[2]);
    if (!a || !b || minute === null || hour !== "*") return null;
    // "to 5pm" means stop before 5pm.
    const last = b.m === 0 ? b.h - 1 : b.h;
    if (last < a.h) return null;
    hour = last === a.h ? String(a.h) : `${a.h}-${last}`;
  }

  // Days of the week.
  if (
    (m = take(
      new RegExp(
        ` (?:on )?(?:the )?(first|1st|second|2nd|third|3rd|fourth|4th|last) (${DAY_RE}) (?:of )?(?:the |every |each )?(?:month )?`,
      ),
    ))
  ) {
    const n = NTH_WORDS[m[1]];
    const d = DAY_WORDS[m[2]];
    dow = n === -1 ? `${d}L` : `${d}#${n}`;
  } else if (
    (m = take(/ (?:every |on )?(?:weekdays?|workdays?|business days?) /))
  )
    dow = "1-5";
  else if ((m = take(/ (?:every |on )?(?:the )?weekends? /))) dow = "0,6";
  else if (
    (m = take(
      new RegExp(` (?:every |on )?(${DAY_RE})s? (?:to|-) (${DAY_RE})s? `),
    ))
  ) {
    const a = DAY_WORDS[m[1]];
    const b = DAY_WORDS[m[2]];
    dow = a < b ? `${a}-${b}` : `${a}-${b === 0 ? 7 : b}`;
  } else if (
    (m = take(
      new RegExp(
        ` (?:every |on |each )?((?:${DAY_RE})s?(?:(?: and | & | |/)(?:${DAY_RE})s?)*) `,
      ),
    ))
  ) {
    const found = m[1]
      .split(/ and | & | |\//)
      .map((w) => DAY_WORDS[w.replace(/s$/, "")] ?? DAY_WORDS[w]);
    if (found.some((d) => d === undefined)) return null;
    dow = [...new Set(found)].sort((a, b) => a - b).join(",");
  }

  // Days of the month.
  if (
    (m = take(
      / (?:on )?(?:the )?last day (?:of )?(?:the |every |each )?(?:month )?/,
    ))
  )
    dom = "L";
  else if (
    (m = take(
      new RegExp(` (?:on )?(?:the )?(${MONTH_RE}) (\\d{1,2})(?:st|nd|rd|th)? `),
    )) ||
    (m = take(
      new RegExp(
        ` (?:on )?(?:the )?(\\d{1,2})(?:st|nd|rd|th)? (?:of )?(${MONTH_RE}) `,
      ),
    ))
  ) {
    const monthFirst = isNaN(Number(m[1]));
    const mo = MONTH_WORDS[monthFirst ? m[1] : m[2]];
    const day = Number(monthFirst ? m[2] : m[1]);
    if (day < 1 || day > daysIn(2024, mo)) return null;
    mon = String(mo);
    dom = String(day);
  } else if (
    (m = take(
      / (?:on )?(?:the )?((?:\d{1,2}(?:st|nd|rd|th))(?:(?: and | & | )(?:the )?\d{1,2}(?:st|nd|rd|th))*) (?:of )?(?:the |every |each )?(?:month )?/,
    ))
  ) {
    const nums = m[1].match(/\d{1,2}/g)!.map(Number);
    if (nums.some((n) => n < 1 || n > 31)) return null;
    dom = [...new Set(nums)].sort((a, b) => a - b).join(",");
  } else if (take(/ (?:monthly|every month|each month|once a month) /))
    dom = "1";

  // Months.
  if (
    (m = take(
      new RegExp(
        ` (?:in |every |each |during )?((?:${MONTH_RE})(?:(?: and | & | |-| to )(?:${MONTH_RE}))*) `,
      ),
    ))
  ) {
    const range = m[1].match(
      new RegExp(`^(${MONTH_RE})(?:-| to )(${MONTH_RE})$`),
    );
    if (range) mon = `${MONTH_WORDS[range[1]]}-${MONTH_WORDS[range[2]]}`;
    else
      mon = [...new Set(m[1].split(/ and | & | /).map((w) => MONTH_WORDS[w]))]
        .sort((a, b) => a - b)
        .join(",");
    if (mon.includes("undefined")) return null;
  }
  if (take(/ (?:yearly|annually|every year|each year|once a year) /)) {
    if (dom === "*") dom = "1";
    if (mon === "*") mon = "1";
  }
  if (take(/ (?:weekly|every week|each week|once a week) /) && dow === "*")
    dow = "1";
  take(/ (?:daily|every ?day|each day|nightly|every night|every morning) /);

  // Times of day.
  if (minute === null) {
    const times =
      take(new RegExp(` at (${TIME_ANY}(?:(?: and | & | )${TIME_ANY})*) `)) ??
      take(new RegExp(` (${TIME_STRICT}(?:(?: and | & | )${TIME_STRICT})*) `));
    if (times) {
      const parsed = times[1].split(/ and | & | (?=\d|noon|mid)/).map(readTime);
      if (parsed.some((t) => !t)) return null;
      const ts = parsed as { h: number; m: number }[];
      const mins = [...new Set(ts.map((t) => t.m))];
      const hours = [...new Set(ts.map((t) => t.h))].sort((a, b) => a - b);
      // Cron can't say "9:30 and 17:00": every time must share its minute.
      if (mins.length > 1) return null;
      minute = String(mins[0]);
      hour = hours.join(",");
    } else {
      minute = "0";
      hour = "0";
    }
  }

  const left = s
    .trim()
    .split(" ")
    .filter((w) => w && !FILLER.has(w));
  if (left.length) return null;
  return `${minute} ${hour} ${dom} ${mon} ${dow}`;
}

"use client";

import * as React from "react";
import { Download, FileSpreadsheet } from "lucide-react";
import { CsvMapper } from "./csv-mapper";
import { autoMatch, parseCsv, toCsv } from "./csv-parse";
import { NumberRoll } from "./number-roll";
import { StatusButton } from "./status-button";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * CSV IMPORT: Contacts → Import, done properly
 *
 *   drop      drop a file (the target lifts to meet it) or
 *             choose one; it's read in slices with the row
 *             count rolling, so a big file never freezes the page
 *   match     the file's columns line up against your fields;
 *             the ones that match by name are threaded together
 *             already. Carry a column onto a field to change it,
 *             or use the field's select
 *   review    "2,996 ready · 4 need a look": the rows with
 *             problems open with their bad cells as fields;
 *             fix one and it ticks and folds away, the counts
 *             rolling. Or skip what's left
 *   import    rows go to onImport in batches; the bar fills and
 *             "1,250 of 2,996" rolls; Cancel stops after the
 *             batch in flight
 *   done      a ring and a check draw; anything skipped or
 *             refused downloads as a CSV with the reason per row
 *
 * The file never leaves the browser until onImport sends your
 * rows, already shaped as { [field]: value }.
 * ───────────────────────────────────────────────────────── */

export interface CsvField {
  key: string;
  label: string;
  required?: boolean;
  /** Other names the column might have in a file, e.g. ["e-mail", "email address"]. */
  match?: string[];
  /** Return why a value won't do. */
  validate?: (
    value: string,
    row: Record<string, string>,
  ) => string | null | undefined | void;
}

export interface CsvImportResult {
  /** Rows in this batch your server refused, by their index in the batch. */
  failed?: { index: number; reason: string }[];
}

export interface CsvImportHandle {
  /** Reads text as if it were a dropped file. */
  load: (text: string, name?: string) => void;
}

export interface CsvImportProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "title"
> {
  fields: CsvField[];
  /** Saves one batch of rows. Throw to mark the whole batch as not imported. */
  onImport: (
    rows: Record<string, string>[],
    options: { signal: AbortSignal; start: number },
  ) => Promise<CsvImportResult | void>;
  /** Rows per onImport call. */
  batchSize?: number;
  maxRows?: number;
  /** What a row is: { one: "contact", many: "contacts" }. */
  noun?: { one: string; many: string };
  /** A link to a template file to fill in. */
  templateHref?: string;
  title?: string;
  description?: string;
  onDone?: (summary: {
    imported: number;
    skipped: number;
    cancelled: boolean;
  }) => void;
  ref?: React.Ref<CsvImportHandle>;
}

type Step = "drop" | "map" | "review" | "import" | "done";
type Skipped = { row: Record<string, string>; reason: string };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const ORDER: Step[] = ["drop", "map", "review", "import", "done"];
const SHOWN = 40;

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const message = (e: unknown, fallback: string) =>
  e instanceof Error && e.message ? e.message : fallback;
const count = (n: number) => n.toLocaleString("en-GB");

function Face({
  out,
  enter,
  dir,
  reduced,
  onGone,
  children,
}: {
  out: boolean;
  enter: boolean;
  dir: number;
  reduced: boolean;
  onGone: () => void;
  children: React.ReactNode;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    el.getAnimations().forEach((a) => a.cancel());
    if (reduced) return;
    if (out) {
      const a = el.animate(
        [
          { opacity: 1, transform: "none", filter: "blur(0px)" },
          {
            opacity: 0,
            transform: `translateX(${-dir * 28}px)`,
            filter: "blur(4px)",
          },
        ],
        { duration: 240, easing: EASE, fill: "forwards" },
      );
      a.onfinish = onGone;
      return;
    }
    if (enter)
      el.animate(
        [
          {
            opacity: 0,
            transform: `translateX(${dir * 28}px)`,
            filter: "blur(4px)",
          },
          { opacity: 1, transform: "none", filter: "blur(0px)" },
        ],
        { duration: 440, delay: 80, easing: EASE, fill: "backwards" },
      );
  }, [out]);
  return (
    <div
      ref={ref}
      inert={out}
      aria-hidden={out || undefined}
      className={out ? "pointer-events-none absolute inset-x-0 top-0" : ""}
    >
      {children}
    </div>
  );
}

/** Steps slide in from the side you went; the card eases to the new height. */
function Slides({
  step,
  dir,
  reduced,
  render,
}: {
  step: Step;
  dir: number;
  reduced: boolean;
  render: (s: Step) => React.ReactNode;
}) {
  const [faces, setFaces] = React.useState<
    { s: Step; out: boolean; dir: number; enter: boolean }[]
  >([{ s: step, out: false, dir, enter: false }]);
  const [seen, setSeen] = React.useState(step);
  const boxRef = React.useRef<HTMLDivElement>(null);
  const height = React.useRef(0);
  // Clipped only while a step slides; at rest a menu can open past its edge.
  const [moving, setMoving] = React.useState(false);
  React.useEffect(() => {
    if (!moving) return;
    const timer = window.setTimeout(() => setMoving(false), 560);
    return () => window.clearTimeout(timer);
  }, [moving, step]);
  if (seen !== step) {
    setSeen(step);
    if (!reduced) setMoving(true);
    setFaces((f) => [
      ...f.filter((x) => x.out && x.s !== step && x.s !== seen),
      ...(reduced ? [] : [{ s: seen, out: true, dir, enter: false }]),
      { s: step, out: false, dir, enter: true },
    ]);
  }
  React.useLayoutEffect(() => {
    const el = boxRef.current;
    if (!el) return;
    height.current = el.offsetHeight;
    const observer = new ResizeObserver(
      () => (height.current = el.offsetHeight),
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, []);
  React.useLayoutEffect(() => {
    const el = boxRef.current;
    if (!el || reduced) return;
    const to = el.offsetHeight;
    if (Math.abs(to - height.current) > 0.5)
      el.animate([{ height: `${height.current}px` }, { height: `${to}px` }], {
        duration: 460,
        easing: EASE,
      });
  }, [step]);
  return (
    <div
      ref={boxRef}
      className="relative [overflow-clip-margin:8px]"
      style={{ overflowY: moving ? "clip" : "visible" }}
    >
      {faces.map((f) => (
        <Face
          key={f.s}
          out={f.out}
          enter={f.enter}
          dir={f.dir}
          reduced={reduced}
          onGone={() =>
            setFaces((all) => all.filter((x) => !(x.s === f.s && x.out)))
          }
        >
          {render(f.s)}
        </Face>
      ))}
    </div>
  );
}

function Fold({
  open,
  reduced,
  children,
}: {
  open: boolean;
  reduced: boolean;
  children: React.ReactNode;
}) {
  const [kept, setKept] = React.useState(children);
  if (open && kept !== children) {
    setKept(children);
  }
  return (
    <div
      className="grid"
      inert={!open}
      aria-hidden={!open || undefined}
      style={{
        gridTemplateRows: open ? "1fr" : "0fr",
        opacity: open ? 1 : 0,
        transition: reduced
          ? "none"
          : `grid-template-rows 420ms ${EASE}, opacity ${open ? 300 : 160}ms ${EASE}`,
      }}
    >
      <div className="min-h-0 min-w-0 overflow-clip [overflow-clip-margin:6px]">
        {open ? children : kept}
      </div>
    </div>
  );
}

function Drawn({
  reduced,
  className = "size-12",
  tone = "text-emerald-600 dark:text-emerald-400",
}: {
  reduced: boolean;
  className?: string;
  tone?: string;
}) {
  const ring = React.useRef<SVGCircleElement>(null);
  const tick = React.useRef<SVGPathElement>(null);
  React.useLayoutEffect(() => {
    if (reduced) return;
    ring.current?.animate([{ strokeDashoffset: 1 }, { strokeDashoffset: 0 }], {
      duration: 640,
      delay: 120,
      easing: EASE,
      fill: "backwards",
    });
    tick.current?.animate([{ strokeDashoffset: 1 }, { strokeDashoffset: 0 }], {
      duration: 420,
      delay: 560,
      easing: EASE,
      fill: "backwards",
    });
  }, [reduced]);
  return (
    <svg
      viewBox="0 0 48 48"
      fill="none"
      aria-hidden="true"
      className={`${className} ${tone}`}
    >
      <circle cx="24" cy="24" r="22.5" stroke="var(--border)" strokeWidth="1" />
      <circle
        ref={ring}
        cx="24"
        cy="24"
        r="22.5"
        stroke="currentColor"
        strokeWidth="1.25"
        pathLength={1}
        strokeDasharray={1}
        strokeDashoffset={0}
        transform="rotate(-90 24 24)"
      />
      <path
        ref={tick}
        d="M16.5 24.5 21.5 29.5 31.5 18.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        strokeDashoffset={0}
      />
    </svg>
  );
}

function Switch({
  on,
  onToggle,
  label,
  reduced,
}: {
  on: boolean;
  onToggle: () => void;
  label: string;
  reduced: boolean;
}) {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={on}
      onClick={onToggle}
      className={`inline-flex cursor-pointer items-center gap-2.5 rounded-full py-1 pr-2 pl-1 text-left text-[12.5px] transition-colors hover:bg-accent/60 ${FOCUS}`}
    >
      <span
        className={`relative h-5 w-9 shrink-0 rounded-full transition-[background-color,box-shadow] duration-300 ${on ? "bg-primary" : "bg-muted shadow-[inset_0_0_0_1px_var(--border)]"}`}
      >
        <span
          className="absolute top-0.5 left-0.5 size-4 rounded-full bg-background shadow-[0_0_0_1px_var(--border)]"
          style={{
            transform: on ? "translateX(16px)" : "none",
            transition: reduced ? "none" : `transform 420ms ${THROW}`,
          }}
        />
      </span>
      {label}
    </button>
  );
}

/** One row with problems: its bad cells as fields; once they're right it ticks and folds away. */
function ProblemRow({
  index,
  row,
  problems,
  fields,
  fixed,
  reduced,
  onEdit,
}: {
  index: number;
  row: Record<string, string>;
  problems: Record<string, string>;
  fields: CsvField[];
  fixed: boolean;
  reduced: boolean;
  onEdit: (index: number, key: string, value: string) => void;
}) {
  const keys = Object.keys(problems);
  const [shownKeys] = React.useState(keys);
  // Fixed: it says so for a moment, then folds away.
  const [gone, setGone] = React.useState(false);
  const [seenFixed, setSeenFixed] = React.useState(fixed);
  if (fixed !== seenFixed) {
    setSeenFixed(fixed);
    if (!fixed) setGone(false);
  }
  React.useEffect(() => {
    if (!fixed) return;
    const timer = window.setTimeout(() => setGone(true), 650);
    return () => window.clearTimeout(timer);
  }, [fixed]);
  const context = fields
    .filter((f) => !shownKeys.includes(f.key) && row[f.key])
    .slice(0, 2);
  return (
    <Fold open={!gone} reduced={reduced}>
      <div className="mb-2 rounded-[12px] px-3 py-2.5 shadow-[inset_0_0_0_1px_var(--border)]">
        <p className="flex items-center gap-2 text-[11.5px] text-muted-foreground">
          <span className="font-mono">Row {count(index + 2)}</span>
          {context.length > 0 && (
            <span className="min-w-0 truncate">
              · {context.map((f) => row[f.key]).join(" · ")}
            </span>
          )}
          <span
            className={`ml-auto inline-flex shrink-0 items-center gap-1 transition-colors ${fixed ? "text-emerald-600 dark:text-emerald-400" : "text-amber-700 dark:text-amber-400"}`}
          >
            <TextMorph>
              {fixed
                ? "Fixed"
                : keys.length === 1
                  ? "1 problem"
                  : `${keys.length} problems`}
            </TextMorph>
          </span>
        </p>
        <div className="mt-2 grid gap-2 @md:grid-cols-2">
          {shownKeys.map((k) => {
            const f = fields.find((x) => x.key === k)!;
            const bad = problems[k];
            return (
              <label key={k} className="block min-w-0">
                <span className="block text-[11.5px] font-medium">
                  {f.label}
                </span>
                <input
                  value={row[k] ?? ""}
                  onChange={(e) => onEdit(index, k, e.target.value)}
                  aria-invalid={Boolean(bad) || undefined}
                  className={`mt-1 h-8 w-full rounded-[8px] bg-transparent px-2.5 text-[16px] text-foreground outline-none transition-shadow [@media(pointer:fine)]:text-[12.5px] ${
                    bad
                      ? "shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_45%,transparent)]"
                      : "shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-emerald-500)_45%,transparent)]"
                  }`}
                />
                <span
                  className={`mt-1 block text-[11px] transition-colors ${bad ? "text-red-600 dark:text-red-400" : "text-emerald-600 dark:text-emerald-400"}`}
                >
                  {bad ?? "Looks right"}
                </span>
              </label>
            );
          })}
        </div>
      </div>
    </Fold>
  );
}

export function CsvImport({
  fields,
  onImport,
  batchSize = 250,
  maxRows = 50_000,
  noun = { one: "row", many: "rows" },
  templateHref,
  title = "Import",
  description = "Bring rows in from a spreadsheet. Nothing is saved until you import.",
  onDone,
  ref,
  className = "",
  ...props
}: CsvImportProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const [step, setStep] = React.useState<Step>("drop");
  const [dir, setDir] = React.useState(1);
  const [fileName, setFileName] = React.useState("");
  const [headers, setHeaders] = React.useState<string[]>([]);
  const [data, setData] = React.useState<string[][]>([]);
  const [mapping, setMapping] = React.useState<Record<string, number | null>>(
    {},
  );
  const [reading, setReading] = React.useState<{ name: string } | null>(null);
  const [dropError, setDropError] = React.useState<string | null>(null);
  const [over, setOver] = React.useState(false);
  const [edits, setEdits] = React.useState<
    Record<number, Record<string, string>>
  >({});
  const [fixing, setFixing] = React.useState<number[]>([]);
  const [skipBad, setSkipBad] = React.useState(true);
  const [progress, setProgress] = React.useState({ done: 0, total: 0 });
  const [result, setResult] = React.useState<{
    imported: number;
    skipped: Skipped[];
    cancelled: boolean;
  } | null>(null);
  const [announce, setAnnounce] = React.useState("");
  const inputRef = React.useRef<HTMLInputElement>(null);
  const dropRef = React.useRef<HTMLLabelElement>(null);
  const ctrl = React.useRef<AbortController | null>(null);
  const many = noun.many;

  const go = (next: Step) => {
    setDir(ORDER.indexOf(next) >= ORDER.indexOf(step) ? 1 : -1);
    setStep(next);
  };

  const read = async (text: string, name: string) => {
    setDropError(null);
    setReading({ name });
    try {
      const rows = await parseCsv(text);
      const [head, ...body] = rows;
      if (!head || !body.length)
        throw new Error("That file has no rows under its header.");
      if (body.length > maxRows)
        throw new Error(
          `That file has ${count(body.length)} rows; up to ${count(maxRows)} can be imported at once.`,
        );
      const width = head.length;
      setHeaders(head.map((h) => h.trim()));
      setData(
        body.map((r) =>
          r.length === width
            ? r
            : [...r, ...Array(Math.max(0, width - r.length)).fill("")].slice(
                0,
                width,
              ),
        ),
      );
      setMapping(autoMatch(head, fields));
      setEdits({});
      setFixing([]);
      setFileName(name);
      setReading(null);
      go("map");
      setAnnounce(
        `${name}: ${count(body.length)} ${body.length === 1 ? noun.one : many}, ${width} columns. Match them to your fields.`,
      );
    } catch (e) {
      setReading(null);
      setDropError(message(e, "That file couldn't be read."));
      if (!reduced)
        dropRef.current?.animate(
          [
            { transform: "none" },
            { transform: "translateX(-4px)" },
            { transform: "translateX(4px)" },
            { transform: "translateX(-2px)" },
            { transform: "none" },
          ],
          { duration: 380, easing: "ease-out" },
        );
    }
  };

  const take = async (file: File | undefined) => {
    if (!file) return;
    if (!/\.(csv|tsv|txt)$/i.test(file.name) && !/^text\//.test(file.type)) {
      setDropError(
        `“${file.name}” isn't a CSV file. Export your sheet as CSV first.`,
      );
      return;
    }
    read(await file.text(), file.name);
  };

  React.useImperativeHandle(ref, () => ({
    load: (text, name = "pasted.csv") => read(text, name),
  }));

  const rowAt = React.useCallback(
    (i: number) => {
      const out: Record<string, string> = {};
      for (const f of fields) {
        const col = mapping[f.key];
        out[f.key] =
          edits[i]?.[f.key] ??
          (col === null || col === undefined
            ? ""
            : (data[i]?.[col] ?? "").trim());
      }
      return out;
    },
    [fields, mapping, edits, data],
  );

  const problemsOf = React.useCallback(
    (row: Record<string, string>) => {
      const out: Record<string, string> = {};
      for (const f of fields) {
        const v = row[f.key];
        if (f.required && !v) out[f.key] = `${f.label} is missing.`;
        else if (v && f.validate) {
          const why = f.validate(v, row);
          if (why) out[f.key] = why;
        }
      }
      return out;
    },
    [fields],
  );

  // Every row is checked once per mapping; an edit re-checks only its own row.
  const checking = step === "review" || step === "import";
  const base = React.useMemo(() => {
    if (!checking) return [];
    return data.map((r) => {
      const row: Record<string, string> = {};
      for (const f of fields) {
        const col = mapping[f.key];
        row[f.key] =
          col === null || col === undefined ? "" : (r[col] ?? "").trim();
      }
      return problemsOf(row);
    });
  }, [checking, data, mapping, fields, problemsOf]);
  const checks = React.useMemo(() => {
    const next = base.slice();
    for (const i of Object.keys(edits))
      next[Number(i)] = problemsOf(rowAt(Number(i)));
    return next;
  }, [base, edits, problemsOf, rowAt]);
  const bad = React.useMemo(
    () =>
      checks
        .map((p, i) => (Object.keys(p).length ? i : -1))
        .filter((i) => i >= 0),
    [checks],
  );
  const ready = data.length - bad.length;
  const missing = fields.filter(
    (f) =>
      f.required && (mapping[f.key] === null || mapping[f.key] === undefined),
  );
  const matched = fields.filter(
    (f) => mapping[f.key] !== null && mapping[f.key] !== undefined,
  ).length;
  const samples = React.useMemo(
    () => headers.map((_, c) => data.slice(0, 6).map((r) => r[c] ?? "")),
    [headers, data],
  );
  const listed = [...new Set([...bad.slice(0, SHOWN), ...fixing])].sort(
    (a, b) => a - b,
  );

  const edit = (index: number, key: string, value: string) => {
    setEdits((e) => ({ ...e, [index]: { ...e[index], [key]: value } }));
    const row = { ...rowAt(index), [key]: value };
    if (!Object.keys(problemsOf(row)).length && !fixing.includes(index)) {
      // Fixed: it stays to say so, then folds away.
      setFixing((f) => [...f, index]);
      window.setTimeout(
        () => setFixing((f) => f.filter((x) => x !== index)),
        1400,
      );
    }
  };

  const run = async () => {
    const indices = data.map((_, i) => i).filter((i) => !bad.includes(i));
    const rows = indices.map(rowAt);
    const skipped: Skipped[] = bad.map((i) => ({
      row: rowAt(i),
      reason: Object.values(checks[i]).join(" "),
    }));
    const c = new AbortController();
    ctrl.current = c;
    setProgress({ done: 0, total: rows.length });
    go("import");
    let imported = 0;
    for (let s = 0; s < rows.length; s += batchSize) {
      if (c.signal.aborted) break;
      const batch = rows.slice(s, s + batchSize);
      try {
        const r = await onImport(batch, { signal: c.signal, start: s });
        const failed = (r ? r.failed : undefined) ?? [];
        failed.forEach(
          (f) =>
            batch[f.index] &&
            skipped.push({ row: batch[f.index], reason: f.reason }),
        );
        imported += batch.length - failed.length;
      } catch (e) {
        if (c.signal.aborted) break;
        const why = message(e, "Your server didn't take this batch.");
        batch.forEach((row) => skipped.push({ row, reason: why }));
      }
      setProgress({
        done: Math.min(rows.length, s + batch.length),
        total: rows.length,
      });
    }
    const cancelled = c.signal.aborted;
    setResult({ imported, skipped, cancelled });
    go("done");
    setAnnounce(
      `${count(imported)} ${imported === 1 ? noun.one : many} imported${skipped.length ? `, ${count(skipped.length)} skipped` : ""}${cancelled ? ". Stopped early" : ""}.`,
    );
    onDone?.({ imported, skipped: skipped.length, cancelled });
  };

  const reset = () => {
    setResult(null);
    setData([]);
    setHeaders([]);
    setFileName("");
    go("drop");
    requestAnimationFrame(() =>
      inputRef.current?.focus({ preventScroll: true }),
    );
  };

  // The skipped rows, as a file to fix and import again.
  const skippedHref = React.useMemo(() => {
    if (!result?.skipped.length) return null;
    const csv = toCsv([
      [...fields.map((f) => f.label), "Why it was skipped"],
      ...result.skipped.map((s) => [
        ...fields.map((f) => s.row[f.key] ?? ""),
        s.reason,
      ]),
    ]);
    return URL.createObjectURL(
      new Blob([csv], { type: "text/csv;charset=utf-8" }),
    );
  }, [result, fields]);
  React.useEffect(
    () => () => void (skippedHref && URL.revokeObjectURL(skippedHref)),
    [skippedHref],
  );

  const header = (
    <div className="flex items-center gap-2.5">
      <span className="grid size-8 shrink-0 place-items-center rounded-[9px] text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)]">
        <FileSpreadsheet
          className="size-4"
          strokeWidth={1.75}
          aria-hidden="true"
        />
      </span>
      <span className="min-w-0 flex-1">
        <span className="block truncate text-[13px] font-medium">
          {fileName}
        </span>
        <span className="block text-[11.5px] text-muted-foreground tabular-nums">
          {count(data.length)} {data.length === 1 ? noun.one : many} ·{" "}
          {headers.length} columns
        </span>
      </span>
    </div>
  );

  const render = (s: Step): React.ReactNode => {
    if (s === "drop")
      return (
        <div className="px-4 pb-4 @md:px-5 @md:pb-5">
          <input
            ref={inputRef}
            id={`${id}-file`}
            type="file"
            accept=".csv,.tsv,.txt,text/csv,text/tab-separated-values,text/plain"
            className="peer sr-only"
            onChange={(e) => {
              take(e.target.files?.[0]);
              e.target.value = "";
            }}
          />
          <label
            ref={dropRef}
            htmlFor={`${id}-file`}
            onDragEnter={(e) => {
              e.preventDefault();
              setOver(true);
            }}
            onDragOver={(e) => {
              e.preventDefault();
              e.dataTransfer.dropEffect = "copy";
            }}
            onDragLeave={(e) => {
              if (!e.currentTarget.contains(e.relatedTarget as Node))
                setOver(false);
            }}
            onDrop={(e) => {
              e.preventDefault();
              setOver(false);
              take(e.dataTransfer.files[0]);
            }}
            className={`flex cursor-pointer flex-col items-center justify-center rounded-[16px] border border-dashed px-4 py-9 text-center transition-[background-color,border-color] duration-300 peer-focus-visible:ring-2 peer-focus-visible:ring-ring/40 ${
              over
                ? "border-primary bg-accent"
                : dropError
                  ? "border-red-500/50"
                  : "border-border hover:bg-accent/40"
            }`}
          >
            <span
              className="grid size-11 place-items-center rounded-[12px] bg-background text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)]"
              style={{
                transform: over ? "translateY(-4px) scale(1.06)" : "none",
                transition: reduced ? "none" : `transform 420ms ${THROW}`,
              }}
            >
              {reading ? (
                <span className="size-4 animate-spin rounded-full border-[1.5px] border-current border-t-transparent motion-reduce:animate-none" />
              ) : (
                <FileSpreadsheet
                  className="size-5"
                  strokeWidth={1.5}
                  aria-hidden="true"
                />
              )}
            </span>
            <span className="mt-3 text-[13.5px] font-medium">
              <TextMorph>
                {reading
                  ? `Reading ${reading.name}`
                  : over
                    ? "Drop to read it"
                    : "Drop a CSV file here"}
              </TextMorph>
            </span>
            <span className="mt-1 text-[12px] text-muted-foreground">
              or{" "}
              <span className="font-medium text-foreground underline underline-offset-2">
                choose a file
              </span>
            </span>
            <span className="mt-3 text-[11.5px] text-muted-foreground">
              Up to {count(maxRows)} rows. Comma, semicolon or tab separated.
            </span>
          </label>
          <Fold open={Boolean(dropError)} reduced={reduced}>
            <p
              role="alert"
              className="pt-2.5 text-[12px] text-red-600 dark:text-red-400"
            >
              {dropError}
            </p>
          </Fold>
          {templateHref && (
            <a
              href={templateHref}
              download
              className={`mt-3 inline-flex items-center gap-1.5 rounded-sm text-[12px] font-medium text-muted-foreground underline-offset-2 hover:text-foreground hover:underline ${FOCUS}`}
            >
              <Download
                className="size-3.5"
                strokeWidth={1.75}
                aria-hidden="true"
              />
              Download a template
            </a>
          )}
        </div>
      );

    if (s === "map")
      return (
        <div className="px-4 pb-4 @md:px-5 @md:pb-5">
          {header}
          <div className="mt-4 mb-2.5 flex items-baseline justify-between gap-3">
            <p className="text-[12.5px] font-medium">Match your columns</p>
            <p className="text-[11.5px] text-muted-foreground tabular-nums">
              <NumberRoll value={matched} /> of {fields.length} fields matched
            </p>
          </div>
          <CsvMapper
            headers={headers}
            samples={samples}
            fields={fields}
            mapping={mapping}
            onChange={setMapping}
            reduced={reduced}
          />
          <div className="mt-4 flex flex-wrap items-center justify-end gap-x-3 gap-y-2">
            <p
              className={`mr-auto min-w-0 text-[11.5px] ${missing.length ? "text-amber-700 dark:text-amber-400" : "text-muted-foreground"}`}
            >
              {missing.length
                ? `Match ${missing.map((f) => f.label).join(" and ")} to continue.`
                : "Carry a column onto a field, or pick it from the list."}
            </p>
            <button
              type="button"
              onClick={reset}
              className={`h-7 cursor-pointer rounded-full px-2.5 text-[12px] font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
            >
              Change file
            </button>
            <StatusButton
              size="sm"
              labels={{ idle: "Continue" }}
              onClick={() => !missing.length && go("review")}
              aria-disabled={missing.length > 0 || undefined}
              className={missing.length ? "pointer-events-none opacity-50" : ""}
            />
          </div>
        </div>
      );

    if (s === "review") {
      const blocked = !skipBad && bad.length > 0;
      return (
        <div className="px-4 pb-4 @md:px-5 @md:pb-5">
          {header}
          <div className="mt-4 flex flex-wrap gap-2 text-[12px] tabular-nums">
            <span className="inline-flex items-center gap-1.5 rounded-full py-1 pr-2.5 pl-2 text-emerald-700 shadow-[inset_0_0_0_1px_var(--border)] dark:text-emerald-400">
              <span
                className="size-1.5 rounded-full bg-emerald-500"
                aria-hidden="true"
              />
              <NumberRoll value={ready} />
              &nbsp;ready
            </span>
            <span
              className="inline-grid"
              style={{
                gridTemplateColumns: bad.length ? "1fr" : "0fr",
                opacity: bad.length ? 1 : 0,
                transition: reduced
                  ? "none"
                  : `grid-template-columns 420ms ${EASE}, opacity 260ms ${EASE}`,
              }}
            >
              <span className="min-w-0 overflow-clip">
                <span className="inline-flex items-center gap-1.5 rounded-full py-1 pr-2.5 pl-2 whitespace-nowrap text-amber-800 shadow-[inset_0_0_0_1px_var(--border)] dark:text-amber-400">
                  <span
                    className="size-1.5 rounded-full bg-amber-500"
                    aria-hidden="true"
                  />
                  <NumberRoll value={bad.length || 1} />
                  &nbsp;need a look
                </span>
              </span>
            </span>
          </div>

          <Fold open={listed.length > 0} reduced={reduced}>
            <div className="mt-3 max-h-[19rem] overflow-y-auto overscroll-contain pr-1">
              {listed.map((i) => (
                <ProblemRow
                  key={i}
                  index={i}
                  row={rowAt(i)}
                  problems={checks[i] ?? {}}
                  fields={fields}
                  fixed={!Object.keys(checks[i] ?? {}).length}
                  reduced={reduced}
                  onEdit={edit}
                />
              ))}
              {bad.length > SHOWN && (
                <p className="py-1 text-center text-[11.5px] text-muted-foreground">
                  and {count(bad.length - SHOWN)} more like these
                </p>
              )}
            </div>
            <div className="mt-2">
              <Switch
                on={skipBad}
                onToggle={() => setSkipBad((v) => !v)}
                label="Skip the rows that still need a look"
                reduced={reduced}
              />
            </div>
          </Fold>
          <Fold open={!bad.length && !fixing.length} reduced={reduced}>
            <div className="mt-4 flex items-center gap-3 rounded-[12px] px-3 py-3 shadow-[inset_0_0_0_1px_var(--border)]">
              <Drawn reduced={reduced} className="size-7" />
              <p className="text-[12.5px]">Every row looks right.</p>
            </div>
          </Fold>

          <div className="mt-4 flex flex-wrap items-center justify-end gap-x-3 gap-y-2">
            {blocked && (
              <p className="mr-auto text-[11.5px] text-amber-700 dark:text-amber-400">
                Fix the rows above, or skip them.
              </p>
            )}
            <button
              type="button"
              onClick={() => go("map")}
              className={`h-7 cursor-pointer rounded-full px-2.5 text-[12px] font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
            >
              Back
            </button>
            <StatusButton
              size="sm"
              labels={{
                idle: `Import ${count(ready)} ${ready === 1 ? noun.one : many}`,
              }}
              onClick={() => !blocked && ready > 0 && run()}
              aria-disabled={blocked || !ready || undefined}
              className={
                blocked || !ready ? "pointer-events-none opacity-50" : ""
              }
            />
          </div>
        </div>
      );
    }

    if (s === "import") {
      const share = progress.total ? progress.done / progress.total : 0;
      return (
        <div className="px-4 pb-5 @md:px-5">
          {header}
          <div
            className="mt-5 h-1 overflow-hidden rounded-full bg-muted"
            role="progressbar"
            aria-label={`Importing ${fileName}`}
            aria-valuemin={0}
            aria-valuemax={progress.total}
            aria-valuenow={progress.done}
          >
            <span
              className="block h-full origin-left rounded-full bg-primary"
              style={{
                transform: `scaleX(${share})`,
                transition: reduced ? "none" : `transform 360ms ${EASE}`,
              }}
            />
          </div>
          <div className="mt-3 flex items-center justify-between gap-3 text-[12.5px]">
            <p className="inline-flex items-baseline text-muted-foreground tabular-nums">
              <span className="font-medium text-foreground">
                <NumberRoll value={progress.done} />
              </span>
              &nbsp;of {count(progress.total)} {many}
            </p>
            <button
              type="button"
              onClick={() => ctrl.current?.abort()}
              className={`h-7 cursor-pointer rounded-full px-2.5 text-[12px] font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
            >
              Cancel
            </button>
          </div>
        </div>
      );
    }

    const r = result;
    return (
      <div className="flex flex-col items-center px-4 pt-2 pb-5 text-center @md:px-5">
        <Drawn
          reduced={reduced}
          tone={
            r?.imported
              ? "text-emerald-600 dark:text-emerald-400"
              : "text-amber-600 dark:text-amber-400"
          }
        />
        <p className="mt-3 text-[15px] font-medium tracking-[-0.01em] tabular-nums">
          {count(r?.imported ?? 0)} {r?.imported === 1 ? noun.one : many}{" "}
          imported
        </p>
        <p className="mt-1 text-[12px] text-muted-foreground">
          {r?.cancelled
            ? "You stopped it early; the rest weren't sent."
            : r?.skipped.length
              ? `${count(r.skipped.length)} skipped. Download them with the reason for each, fix them, and import that file.`
              : `Everything in ${fileName} is in.`}
        </p>
        <div className="mt-4 flex flex-wrap items-center justify-center gap-2">
          {skippedHref && (
            <a
              href={skippedHref}
              download={`${fileName.replace(/\.[^.]+$/, "")}-skipped.csv`}
              className={`inline-flex h-8 items-center gap-1.5 rounded-full px-3 text-[12.5px] font-medium shadow-[inset_0_0_0_1px_var(--border)] transition-colors hover:bg-accent ${FOCUS}`}
            >
              <Download
                className="size-3.5"
                strokeWidth={1.75}
                aria-hidden="true"
              />
              Skipped rows
            </a>
          )}
          <button
            type="button"
            onClick={reset}
            className={`inline-flex h-8 cursor-pointer items-center rounded-full bg-primary px-3.5 text-[12.5px] font-medium text-primary-foreground transition-colors hover:bg-primary/90 ${FOCUS}`}
          >
            Import another file
          </button>
        </div>
      </div>
    );
  };

  return (
    <div
      className={`@container w-full rounded-[22px] border border-border bg-background text-foreground ${className}`}
      {...props}
    >
      <div className="px-4 pt-4 pb-3.5 @md:px-5 @md:pt-5">
        <p className="text-[14px] font-medium tracking-[-0.01em]">{title}</p>
        <p className="mt-0.5 text-[12px] text-muted-foreground">
          {description}
        </p>
      </div>
      <Slides step={step} dir={dir} reduced={reduced} render={render} />
      <span className="sr-only" role="status">
        {announce}
      </span>
    </div>
  );
}

"use client";

import * as React from "react";
import { PillSelect, type PillOption } from "./imported-pill-select";

/* ─────────────────────────────────────────────────────────
 * CSV MAPPER: your file's columns against your fields
 *
 *   threads   on a wide card each match is a thin line thread
 *             from the file's column to your field, drawn in
 *             when it's made
 *   drag      carry a column (or its dot) onto a field to match
 *             them; the thread follows the pointer. Or click a
 *             column, then a field
 *   select    every field also has a plain select, the whole
 *             mapping on a narrow card and for the keyboard
 * ───────────────────────────────────────────────────────── */

export interface MapperField {
  key: string;
  label: string;
  required?: boolean;
}

export interface CsvMapperProps {
  headers: string[];
  /** A few values from each column. */
  samples: string[][];
  fields: MapperField[];
  mapping: Record<string, number | null>;
  onChange: (mapping: Record<string, number | null>) => void;
  reduced: boolean;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const curve = (x1: number, y1: number, x2: number, y2: number) => {
  const dx = Math.max(24, (x2 - x1) / 2);
  return `M${x1} ${y1} C${x1 + dx} ${y1}, ${x2 - dx} ${y2}, ${x2} ${y2}`;
};

function Thread({
  d,
  reduced,
  lit,
}: {
  d: string;
  reduced: boolean;
  lit: boolean;
}) {
  const ref = React.useRef<SVGPathElement>(null);
  React.useLayoutEffect(() => {
    if (!reduced)
      ref.current?.animate([{ strokeDashoffset: 1 }, { strokeDashoffset: 0 }], {
        duration: 520,
        easing: EASE,
        fill: "backwards",
      });
  }, []);
  return (
    <path
      ref={ref}
      d={d}
      fill="none"
      stroke="var(--primary)"
      strokeWidth={lit ? 1.5 : 1}
      strokeOpacity={lit ? 0.9 : 0.5}
      pathLength={1}
      strokeDasharray={1}
      strokeDashoffset={0}
      style={{
        transition: reduced
          ? "none"
          : "stroke-opacity 200ms, stroke-width 200ms",
      }}
    />
  );
}

export function CsvMapper({
  headers,
  samples,
  fields,
  mapping,
  onChange,
  reduced,
}: CsvMapperProps) {
  const id = React.useId();
  const boxRef = React.useRef<HTMLDivElement>(null);
  const tempRef = React.useRef<SVGPathElement>(null);
  const [wide, setWide] = React.useState(false);
  const [lines, setLines] = React.useState<
    { key: string; col: number; d: string }[]
  >([]);
  const [picked, setPicked] = React.useState<number | null>(null);
  const [carrying, setCarrying] = React.useState<number | null>(null);
  const [hover, setHover] = React.useState<string | null>(null);
  const [size, setSize] = React.useState({ w: 0, h: 0 });

  const assign = (key: string, col: number | null) => {
    const next: Record<string, number | null> = { ...mapping };
    if (col !== null)
      for (const k of Object.keys(next)) if (next[k] === col) next[k] = null;
    next[key] = col;
    onChange(next);
  };
  const owner = (col: number) => fields.find((f) => mapping[f.key] === col);

  // Where each thread runs: from a column's dot to its field's dot.
  const measure = React.useCallback(() => {
    const box = boxRef.current;
    if (!box) return;
    const w = box.offsetWidth;
    const isWide = w >= 520;
    setWide((v) => (v === isWide ? v : isWide));
    setSize((s) =>
      s.w === w && s.h === box.offsetHeight ? s : { w, h: box.offsetHeight },
    );
    if (!isWide) return setLines((l) => (l.length ? [] : l));
    const r = box.getBoundingClientRect();
    const next: { key: string; col: number; d: string }[] = [];
    for (const f of fields) {
      const col = mapping[f.key];
      if (col === null || col === undefined) continue;
      const a = box
        .querySelector<HTMLElement>(`[data-col-dot="${col}"]`)
        ?.getBoundingClientRect();
      const b = box
        .querySelector<HTMLElement>(`[data-field-dot="${CSS.escape(f.key)}"]`)
        ?.getBoundingClientRect();
      if (!a || !b) continue;
      next.push({
        key: f.key,
        col,
        d: curve(
          a.left + a.width / 2 - r.left,
          a.top + a.height / 2 - r.top,
          b.left + b.width / 2 - r.left,
          b.top + b.height / 2 - r.top,
        ),
      });
    }
    setLines((l) =>
      l.length === next.length &&
      l.every((x, i) => x.d === next[i].d && x.key === next[i].key)
        ? l
        : next,
    );
  }, [fields, mapping]);

  React.useLayoutEffect(() => {
    measure();
    const box = boxRef.current;
    if (!box) return;
    const observer = new ResizeObserver(measure);
    observer.observe(box);
    return () => observer.disconnect();
  }, [measure]);

  // Carrying a column: a loose thread follows the pointer, written straight to the path.
  const carry = (col: number, e: React.PointerEvent) => {
    if (!wide || e.button !== 0) return;
    const box = boxRef.current;
    const dot = box?.querySelector<HTMLElement>(`[data-col-dot="${col}"]`);
    if (!box || !dot) return;
    const sx = e.clientX;
    const sy = e.clientY;
    let started = false;
    const move = (ev: PointerEvent) => {
      if (!started && Math.hypot(ev.clientX - sx, ev.clientY - sy) < 5) return;
      if (!started) {
        started = true;
        setCarrying(col);
      }
      const r = box.getBoundingClientRect();
      const a = dot.getBoundingClientRect();
      tempRef.current?.setAttribute(
        "d",
        curve(
          a.left + a.width / 2 - r.left,
          a.top + a.height / 2 - r.top,
          ev.clientX - r.left,
          ev.clientY - r.top,
        ),
      );
      const over = (
        document.elementFromPoint(ev.clientX, ev.clientY) as HTMLElement | null
      )?.closest<HTMLElement>("[data-field]");
      setHover((h) =>
        h === (over?.dataset.field ?? null) ? h : (over?.dataset.field ?? null),
      );
    };
    const up = (ev: PointerEvent) => {
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", up);
      window.removeEventListener("pointercancel", up);
      if (!started) return;
      const over = (
        document.elementFromPoint(ev.clientX, ev.clientY) as HTMLElement | null
      )?.closest<HTMLElement>("[data-field]");
      if (over?.dataset.field) assign(over.dataset.field, col);
      setCarrying(null);
      setHover(null);
      tempRef.current?.setAttribute("d", "");
      // The click that ends a carry shouldn't also pick the column.
      window.addEventListener("click", (c) => c.stopPropagation(), {
        capture: true,
        once: true,
      });
    };
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", up);
    window.addEventListener("pointercancel", up);
  };

  React.useEffect(() => {
    if (picked === null) return;
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && setPicked(null);
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [picked]);

  const lit = hover ?? (picked !== null ? (owner(picked)?.key ?? null) : null);
  const options = React.useMemo<PillOption[]>(
    () => [
      { value: "", label: "Don’t import" },
      ...headers.map((h, i) => ({
        value: String(i),
        label: h || `Column ${i + 1}`,
        description:
          samples[i]?.filter(Boolean).slice(0, 2).join(" · ") || "Empty",
      })),
    ],
    [headers, samples],
  );

  return (
    <div
      ref={boxRef}
      className={`relative ${wide ? "grid grid-cols-[minmax(0,1fr)_48px_minmax(0,1.1fr)]" : ""}`}
    >
      {wide && (
        <>
          <ol aria-label="Columns in your file" className="space-y-1.5">
            {headers.map((h, i) => {
              const used = owner(i);
              const on = picked === i || carrying === i;
              return (
                <li key={i}>
                  <button
                    type="button"
                    data-col={i}
                    aria-pressed={picked === i}
                    onPointerDown={(e) => carry(i, e)}
                    onClick={() => setPicked((p) => (p === i ? null : i))}
                    className={`relative flex w-full cursor-grab items-center gap-2 rounded-[10px] py-1.5 pr-5 pl-2.5 text-left transition-[background-color,box-shadow] active:cursor-grabbing ${FOCUS} ${
                      on
                        ? "bg-accent shadow-[inset_0_0_0_1px_var(--ring)]"
                        : "shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent/60"
                    }`}
                  >
                    <span className="min-w-0 flex-1">
                      <span
                        className={`block truncate font-mono text-[12px] ${used ? "text-foreground" : "text-muted-foreground"}`}
                      >
                        {h || `Column ${i + 1}`}
                      </span>
                      <span className="block truncate text-[11px] text-muted-foreground">
                        {samples[i]?.filter(Boolean).slice(0, 2).join(" · ") ||
                          "Empty"}
                      </span>
                    </span>
                    <span
                      data-col-dot={i}
                      aria-hidden="true"
                      className={`absolute top-1/2 -right-[5px] size-2.5 -translate-y-1/2 rounded-full transition-colors duration-300 ${used ? "bg-primary" : "bg-background shadow-[inset_0_0_0_1px_var(--muted-foreground)]"}`}
                    />
                  </button>
                </li>
              );
            })}
          </ol>
          <span aria-hidden="true" />
        </>
      )}

      <ol aria-label="Your fields" className="space-y-1.5">
        {fields.map((f) => {
          const col = mapping[f.key];
          const target = picked !== null || carrying !== null;
          const isLit = lit === f.key;
          return (
            <li
              key={f.key}
              data-field={f.key}
              onClick={(e) => {
                if (
                  picked === null ||
                  (e.target as HTMLElement).closest(
                    '[aria-haspopup="listbox"], [role="listbox"]',
                  )
                )
                  return;
                assign(f.key, picked);
                setPicked(null);
              }}
              className={`relative flex items-center gap-2 rounded-[10px] py-1.5 pr-1.5 pl-3 transition-[background-color,box-shadow] duration-200 ${
                isLit
                  ? "bg-accent shadow-[inset_0_0_0_1px_var(--ring)]"
                  : target
                    ? "cursor-pointer shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent/60"
                    : "shadow-[inset_0_0_0_1px_var(--border)]"
              }`}
            >
              {wide && (
                <span
                  data-field-dot={f.key}
                  aria-hidden="true"
                  className={`absolute top-1/2 -left-[5px] size-2.5 -translate-y-1/2 rounded-full transition-colors duration-300 ${col !== null && col !== undefined ? "bg-primary" : "bg-background shadow-[inset_0_0_0_1px_var(--muted-foreground)]"}`}
                />
              )}
              <span className="min-w-0 flex-1">
                <span
                  id={`${id}-${f.key}`}
                  className="block truncate text-[12.5px] font-medium"
                >
                  {f.label}
                  {f.required && (
                    <span className="text-muted-foreground"> *</span>
                  )}
                </span>
                {!wide && (
                  <span className="block truncate text-[11px] text-muted-foreground">
                    {col !== null && col !== undefined
                      ? samples[col]?.filter(Boolean).slice(0, 2).join(" · ") ||
                        "Empty"
                      : f.required
                        ? "Needed to import"
                        : "Not imported"}
                  </span>
                )}
              </span>
              <span className="flex w-[45%] max-w-[11rem] shrink-0">
                <PillSelect
                  block
                  mono
                  align="end"
                  width={250}
                  label={`Column for ${f.label}`}
                  options={options}
                  value={col === null || col === undefined ? "" : String(col)}
                  onValueChange={(v) =>
                    assign(f.key, v === "" ? null : Number(v))
                  }
                  muted={col === null || col === undefined}
                />
              </span>
            </li>
          );
        })}
      </ol>

      {wide && (
        <svg
          aria-hidden="true"
          className="pointer-events-none absolute inset-0 overflow-visible"
          width={size.w}
          height={size.h}
        >
          {lines.map((l) => (
            <Thread
              key={`${l.key}:${l.col}`}
              d={l.d}
              reduced={reduced}
              lit={lit === l.key}
            />
          ))}
          <path
            ref={tempRef}
            d=""
            fill="none"
            stroke="var(--primary)"
            strokeWidth={1.5}
            strokeDasharray="3 3"
            style={{ opacity: carrying !== null ? 0.9 : 0 }}
          />
        </svg>
      )}
      <p className="sr-only" aria-live="polite">
        {picked !== null
          ? `${headers[picked] || `Column ${picked + 1}`} picked. Choose the field it fills.`
          : ""}
      </p>
    </div>
  );
}

/* ─────────────────────────────────────────────────────────
 * CSV PARSE: reading, matching and writing CSV for csv-import
 *
 *   parse     RFC 4180: quoted fields, doubled quotes, commas
 *             and line breaks inside quotes, CRLF or LF, a
 *             byte-order mark. The separator (comma, semicolon,
 *             tab) is taken from the first line. Long files are
 *             read in slices with a pause between, so the page
 *             keeps drawing
 *   match     a column matches a field when their names agree
 *             once case, spaces and punctuation are ignored
 *             ("E-mail address" → email), or one contains the
 *             other
 *   write     the rows you skipped, back out as CSV
 * ───────────────────────────────────────────────────────── */

export interface CsvMatchable {
  key: string;
  label: string;
  /** Other names the column might have, e.g. ["e-mail", "email address"]. */
  match?: string[];
}

const SLICE = 200_000;
const pause = () => new Promise<void>((r) => setTimeout(r, 0));

/** The separator the first line uses most, outside quotes. */
export function detectDelimiter(text: string): string {
  const counts: Record<string, number> = { ",": 0, ";": 0, "\t": 0 };
  let quoted = false;
  for (let i = 0; i < text.length && i < 10_000; i++) {
    const c = text[i];
    if (c === '"') quoted = !quoted;
    else if (!quoted && (c === "\n" || c === "\r")) break;
    else if (!quoted && c in counts) counts[c]++;
  }
  return Object.entries(counts).sort((a, b) => b[1] - a[1])[0][1]
    ? Object.entries(counts).sort((a, b) => b[1] - a[1])[0][0]
    : ",";
}

/** Every row as an array of fields; empty lines are dropped. */
export async function parseCsv(
  input: string,
  options: {
    delimiter?: string;
    onProgress?: (fraction: number) => void;
    signal?: AbortSignal;
  } = {},
): Promise<string[][]> {
  const text = input.charCodeAt(0) === 0xfeff ? input.slice(1) : input;
  const d = options.delimiter ?? detectDelimiter(text);
  const rows: string[][] = [];
  let row: string[] = [];
  let field = "";
  let quoted = false;
  let start = 0;
  const n = text.length;
  for (let i = 0; i < n; i++) {
    const c = text.charCodeAt(i);
    if (quoted) {
      if (c === 34) {
        if (text.charCodeAt(i + 1) === 34) {
          field += text.slice(start, i + 1);
          i++;
          start = i + 1;
        } else {
          field += text.slice(start, i);
          quoted = false;
          start = i + 1;
        }
      }
    } else if (c === 34 && field === "" && start === i) {
      quoted = true;
      start = i + 1;
    } else if (text[i] === d) {
      row.push(field + text.slice(start, i));
      field = "";
      start = i + 1;
    } else if (c === 10 || c === 13) {
      row.push(field + text.slice(start, i));
      if (row.length > 1 || row[0] !== "") rows.push(row);
      row = [];
      field = "";
      if (c === 13 && text.charCodeAt(i + 1) === 10) i++;
      start = i + 1;
    }
    if (i % SLICE === 0 && i) {
      if (options.signal?.aborted)
        throw new DOMException("Aborted", "AbortError");
      options.onProgress?.(i / n);
      await pause();
    }
  }
  if (start < n || field || row.length) {
    row.push(field + text.slice(start, quoted ? n : n));
    if (row.length > 1 || row[0] !== "") rows.push(row);
  }
  options.onProgress?.(1);
  return rows;
}

const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9]/g, "");

/** Which column (by index) each field should take, or null. Each column is used once. */
export function autoMatch(
  headers: string[],
  fields: CsvMatchable[],
): Record<string, number | null> {
  const used = new Set<number>();
  const out: Record<string, number | null> = {};
  const heads = headers.map(norm);
  for (const f of fields) {
    const names = [f.key, f.label, ...(f.match ?? [])]
      .map(norm)
      .filter(Boolean);
    let hit = heads.findIndex((h, i) => !used.has(i) && names.includes(h));
    if (hit === -1)
      hit = heads.findIndex(
        (h, i) =>
          !used.has(i) &&
          h.length > 2 &&
          names.some((x) => x.length > 2 && (h.includes(x) || x.includes(h))),
      );
    out[f.key] = hit === -1 ? null : hit;
    if (hit !== -1) used.add(hit);
  }
  return out;
}

/** Rows back out as CSV text, quoting what needs it. */
export function toCsv(rows: string[][]): string {
  const esc = (v: string) =>
    /[",\r\n]/.test(v) ? `"${v.replace(/"/g, '""')}"` : v;
  return rows.map((r) => r.map(esc).join(",")).join("\r\n");
}

"use client";

import * as React from "react";
import {
  ArrowUp,
  ChevronDown,
  ChevronLeft,
  ChevronRight,
  Search,
  X,
} from "lucide-react";
import { NumberRoll } from "./number-roll";
import { PillSelect, type PillOption } from "./imported-pill-select";
import { StatusButton, type ActionStatus } from "./status-button";
import { TextMorph } from "./text-morph";
import { useRowMotion } from "./use-row-motion";

/* ─────────────────────────────────────────────────────────
 * DATA TABLE: rows that travel
 *
 *   sort      click a header and every row glides to its new
 *             rank, top first; rows that didn't move stay put;
 *             the arrow flips with a slight overshoot
 *   live      new data re-sorts itself: a row whose amount
 *             grows glides past the ones above it, new rows
 *             fade in as the rows below make room
 *   search    rows that stop matching fold away, the rest close
 *             up, and "248 payments" rolls down to the count
 *   select    tick a row and the toolbar becomes the selection
 *             ("3 selected · Export · Delete"); Shift ticks a
 *             range one row after another
 *   remove    rows fold out and the toolbar holds "3 deleted ·
 *             Undo" over a draining thin line before it commits
 *   detail    a row opens into its detail by measured height
 *   edit      double-click a cell (or Enter on it) to edit in
 *             place; it saves with a check, or shakes back
 *   pages     the next page slides in from the side you went;
 *             "11–20 of 248" rolls
 *
 * Narrow containers get one card per row instead of columns.
 * ───────────────────────────────────────────────────────── */

export type DataTableValue = string | number | Date | null | undefined;

export interface DataTableColumn<T> {
  key: string;
  header: string;
  /** What the column sorts, searches and edits by. Defaults to row[key]. */
  value?: (row: T) => DataTableValue;
  /** What the cell shows. Defaults to the value as text. */
  cell?: (row: T) => React.ReactNode;
  align?: "left" | "right";
  /** A grid track, e.g. "minmax(0,1.6fr)" or "120px". */
  width?: string;
  sortable?: boolean;
  /** Search looks in this column. */
  searchable?: boolean;
  /** Double-click or Enter edits it in place (needs onEdit). */
  editable?: boolean;
  /** Its place in the card a narrow container shows instead of columns. */
  card?: "title" | "subtitle" | "trailing" | "hidden";
}

export interface DataTableAction<T> {
  id: string;
  label: string;
  /** Labels while it runs and once it's done, e.g. ["Exporting", "Exported"]. */
  progress?: [string, string];
  tone?: "default" | "destructive";
  /** The rows leave at once and the toolbar offers Undo; run() is called when the chance to undo is over. */
  removes?: boolean;
  run: (rows: T[]) => Promise<void> | void;
}

export type DataTableSort = { key: string; dir: "asc" | "desc" };

export interface DataTableProps<T> extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "children"
> {
  columns: DataTableColumn<T>[];
  rows: T[];
  /** Defaults to row.id. */
  getRowId?: (row: T) => string;
  /** How a row is named when announced; defaults to its first column. */
  rowLabel?: (row: T) => string;
  /** What a row is called: ["payment", "payments"]. */
  noun?: [string, string];
  sort?: DataTableSort | null;
  defaultSort?: DataTableSort | null;
  onSortChange?: (sort: DataTableSort | null) => void;
  /** Shows the search field; it looks in columns marked searchable (or all, if none are). */
  searchable?: boolean;
  searchPlaceholder?: string;
  selectable?: boolean;
  selected?: string[];
  defaultSelected?: string[];
  onSelectedChange?: (ids: string[]) => void;
  /** What the toolbar offers for the selected rows. */
  actions?: DataTableAction<T>[];
  /** How long Undo is offered after a removing action, ms. */
  undoFor?: number;
  /** Saves an edited cell. Throw to put the old value back. */
  onEdit?: (row: T, key: string, value: string) => Promise<void> | void;
  /** Rows open into this. */
  renderDetail?: (row: T) => React.ReactNode;
  pageSize?: number;
  label?: string;
}

type Undo<T> = {
  key: number;
  ids: string[];
  rows: T[];
  action: DataTableAction<T>;
};
type Cursor = { id: string; col: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const CELL_FOCUS =
  "outline-none focus-visible:shadow-[inset_0_0_0_1.5px_var(--ring)]";
const NO_IDS: string[] = [];

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const swap = (
  on: boolean,
  reduced: boolean,
  from = 8,
): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : `translateY(${from}px)`,
  filter: on ? "none" : "blur(4px)",
  transition: reduced
    ? "none"
    : `opacity 240ms ${EASE}, transform 420ms ${EASE}, filter 240ms ${EASE}`,
  pointerEvents: on ? undefined : "none",
});

const compare = (a: DataTableValue, b: DataTableValue) => {
  if (a == null && b == null) return 0;
  if (a == null) return 1;
  if (b == null) return -1;
  if (a instanceof Date && b instanceof Date) return a.getTime() - b.getTime();
  if (typeof a === "number" && typeof b === "number") return a - b;
  return String(a).localeCompare(String(b), undefined, {
    numeric: true,
    sensitivity: "base",
  });
};

/** A checkbox that draws: the check (or the dash, for some) strokes itself in. */
function Box({
  state,
  reduced,
  delay = 0,
}: {
  state: "on" | "off" | "some";
  reduced: boolean;
  delay?: number;
}) {
  const t = (on: boolean) =>
    reduced
      ? "none"
      : `stroke-dashoffset ${on ? 300 : 120}ms ${EASE} ${on ? delay + 60 : 0}ms`;
  return (
    <span
      aria-hidden="true"
      className="relative flex size-4 items-center justify-center rounded-[5px] transition-[background-color,box-shadow] duration-200"
      style={{
        background: state === "off" ? "var(--background)" : "var(--primary)",
        boxShadow:
          state === "off"
            ? "inset 0 0 0 1px color-mix(in oklab, var(--foreground) 28%, transparent)"
            : "none",
        transitionDelay: state === "off" ? "0ms" : `${delay}ms`,
      }}
    >
      <svg
        viewBox="0 0 16 16"
        className="absolute size-3 text-primary-foreground"
        fill="none"
      >
        <path
          d="M3.5 8.5 6.5 11.5 12.5 4.5"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
          pathLength={1}
          strokeDasharray={1}
          style={{
            strokeDashoffset: state === "on" ? 0 : 1,
            transition: t(state === "on"),
          }}
        />
        <path
          d="M4 8h8"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          pathLength={1}
          strokeDasharray={1}
          style={{
            strokeDashoffset: state === "some" ? 0 : 1,
            transition: t(state === "some"),
          }}
        />
      </svg>
    </span>
  );
}

const cellValue = <T,>(c: DataTableColumn<T>, row: T): DataTableValue =>
  c.value
    ? c.value(row)
    : ((row as Record<string, unknown>)[c.key] as DataTableValue);
const cellText = <T,>(c: DataTableColumn<T>, row: T): React.ReactNode =>
  c.cell ? c.cell(row) : String(cellValue(c, row) ?? "");

type RowActions<T> = {
  toggle: (id: string, range: boolean) => void;
  toggleOpen: (id: string, row: T) => void;
  cursor: (c: Cursor) => void;
  edit: (e: { id: string; key: string }) => void;
  finish: (row: T, key: string, value: string | null) => void;
  detail: (row: T) => React.ReactNode;
};

type RowProps<T> = {
  row: T;
  id: string;
  index: number;
  columns: DataTableColumn<T>[];
  tracks: string;
  selectable: boolean;
  canEdit: boolean;
  hasDetail: boolean;
  isSelected: boolean;
  isOpen: boolean;
  /** When its tick draws, in a range selection. */
  delay: number;
  /** The focused cell in this row (-1: the row itself), or null. */
  focusCol: number | null;
  rowTab: 0 | -1;
  editingKey: string | null;
  drafts: ReadonlyMap<string, { value: string; status: "pending" | "done" }>;
  reduced: boolean;
  name: string;
  actions: React.RefObject<RowActions<T>>;
};

/** One row, memoised on plain values: a sort, a selection or a keystroke re-renders only the rows it changes. */
function TableRowView<T>(p: RowProps<T>) {
  const { row, id, columns, reduced, actions: a } = p;
  const editable = (c: DataTableColumn<T>) => !!(c.editable && p.canEdit);
  const title = columns.find((c) => c.card === "title") ?? columns[0];
  const subtitles = columns.filter((c) => c.card === "subtitle");
  const trailing = columns.filter((c) => c.card === "trailing");

  const cell = (col: DataTableColumn<T>) => {
    const draft = p.drafts.get(`${id}:${col.key}`);
    if (p.editingKey === col.key)
      return (
        <input
          autoFocus
          defaultValue={String(cellValue(col, row) ?? "")}
          aria-label={`${col.header} for ${p.name}`}
          onFocus={(e) => e.currentTarget.select()}
          onKeyDown={(e) => {
            e.stopPropagation();
            if (e.key === "Enter")
              a.current.finish(row, col.key, e.currentTarget.value);
            if (e.key === "Escape") a.current.finish(row, col.key, null);
          }}
          onBlur={(e) => a.current.finish(row, col.key, e.currentTarget.value)}
          className={`-mx-1.5 h-8 w-[calc(100%+12px)] min-w-0 rounded-[8px] bg-background px-1.5 text-[13px] shadow-[inset_0_0_0_1.5px_var(--ring)] outline-none [@media(pointer:coarse)]:text-[16px] ${col.align === "right" ? "text-right" : ""}`}
        />
      );
    return (
      <span
        className={`flex min-w-0 items-center gap-1.5 ${col.align === "right" ? "justify-end" : ""}`}
      >
        <span className="min-w-0 truncate">
          {draft ? (
            <TextMorph animateWidth={false}>{draft.value}</TextMorph>
          ) : (
            cellText(col, row)
          )}
        </span>
        {draft && (
          <span className="relative size-3.5 shrink-0" aria-hidden="true">
            <span
              className="absolute inset-0 flex items-center justify-center"
              style={swap(draft.status === "pending", reduced, 0)}
            >
              <span className="size-3 rounded-full border-[1.5px] border-muted-foreground border-t-transparent motion-safe:animate-spin" />
            </span>
            <svg
              viewBox="0 0 16 16"
              className="absolute inset-0 size-3.5 text-emerald-600 dark:text-emerald-400"
              fill="none"
              style={{
                opacity: draft.status === "done" ? 1 : 0,
                transition: `opacity 200ms ${EASE}`,
              }}
            >
              <path
                d="M3.5 8.5 6.5 11.5 12.5 4.5"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
                pathLength={1}
                strokeDasharray={1}
                style={{
                  strokeDashoffset: draft.status === "done" ? 0 : 1,
                  transition: reduced
                    ? "none"
                    : `stroke-dashoffset 380ms ${EASE} 80ms`,
                }}
              />
            </svg>
          </span>
        )}
      </span>
    );
  };

  return (
    <div
      data-row-id={id}
      role="row"
      aria-rowindex={p.index}
      aria-selected={p.selectable ? p.isSelected : undefined}
      aria-expanded={p.hasDetail ? p.isOpen : undefined}
      tabIndex={p.rowTab}
      onFocus={(e) =>
        e.target === e.currentTarget && a.current.cursor({ id, col: -1 })
      }
      className={`relative border-b border-border transition-colors duration-200 last:border-b-0 ${CELL_FOCUS}`}
      style={{
        background: p.isSelected
          ? "color-mix(in oklab, var(--primary) 5%, var(--background))"
          : "var(--background)",
      }}
    >
      {/* Columns, wide */}
      <div
        className="grid min-h-12 items-center @max-[34rem]:hidden"
        style={{ gridTemplateColumns: p.tracks }}
      >
        {p.selectable && (
          <span role="gridcell" className="flex items-center justify-center">
            <button
              type="button"
              tabIndex={-1}
              aria-label={`Select ${p.name}`}
              aria-pressed={p.isSelected}
              onClick={(e) => a.current.toggle(id, e.shiftKey)}
              className="flex size-8 cursor-pointer items-center justify-center rounded-[8px] hover:bg-accent"
            >
              <Box
                state={p.isSelected ? "on" : "off"}
                reduced={reduced}
                delay={p.delay}
              />
            </button>
          </span>
        )}
        {columns.map((col, ci) => (
          <span
            key={col.key}
            role="gridcell"
            data-col-key={col.key}
            data-col-index={ci}
            tabIndex={p.focusCol === ci ? 0 : -1}
            onFocus={() => a.current.cursor({ id, col: ci })}
            onDoubleClick={() =>
              editable(col) && a.current.edit({ id, key: col.key })
            }
            className={`min-w-0 rounded-[6px] px-3 py-2 text-[13px] ${col.align === "right" ? "text-right tabular-nums" : ""} ${editable(col) ? "cursor-text" : ""} ${CELL_FOCUS}`}
          >
            {cell(col)}
          </span>
        ))}
        {p.hasDetail && (
          <span role="gridcell" className="flex items-center justify-center">
            <button
              type="button"
              tabIndex={-1}
              aria-label={`${p.isOpen ? "Close" : "Open"} ${p.name}`}
              aria-expanded={p.isOpen}
              onClick={() => a.current.toggleOpen(id, row)}
              className="flex size-8 cursor-pointer items-center justify-center rounded-[8px] text-muted-foreground hover:bg-accent hover:text-foreground"
            >
              <ChevronDown
                className="size-4"
                strokeWidth={1.75}
                style={{
                  transform: p.isOpen ? "rotate(180deg)" : "none",
                  transition: reduced ? "none" : `transform 420ms ${THROW}`,
                }}
              />
            </button>
          </span>
        )}
      </div>

      {/* One card, narrow */}
      <div
        className="hidden min-h-[60px] items-center gap-3 py-2.5 pr-3 @max-[34rem]:flex"
        style={{ paddingLeft: p.selectable ? 0 : 12 }}
      >
        {p.selectable && (
          <button
            type="button"
            tabIndex={-1}
            aria-label={`Select ${p.name}`}
            aria-pressed={p.isSelected}
            onClick={(e) => a.current.toggle(id, e.shiftKey)}
            className="flex size-10 shrink-0 cursor-pointer items-center justify-center"
          >
            <Box
              state={p.isSelected ? "on" : "off"}
              reduced={reduced}
              delay={p.delay}
            />
          </button>
        )}
        <button
          type="button"
          tabIndex={-1}
          disabled={!p.hasDetail}
          onClick={() => p.hasDetail && a.current.toggleOpen(id, row)}
          className="flex min-w-0 flex-1 cursor-pointer items-center gap-3 text-left disabled:cursor-default"
        >
          <span className="min-w-0 flex-1">
            <span className="block truncate text-[13.5px] font-medium">
              {cellText(title, row)}
            </span>
            {subtitles.length > 0 && (
              <span className="mt-0.5 flex min-w-0 items-center gap-1.5 truncate text-[12px] text-muted-foreground">
                {subtitles.map((c, i) => (
                  <React.Fragment key={c.key}>
                    {i > 0 && <span aria-hidden="true">·</span>}
                    <span className="truncate">{cellText(c, row)}</span>
                  </React.Fragment>
                ))}
              </span>
            )}
          </span>
          {trailing.length > 0 && (
            <span className="flex shrink-0 flex-col items-end gap-1 text-[13px] tabular-nums">
              {trailing.map((c) => (
                <span key={c.key}>{cellText(c, row)}</span>
              ))}
            </span>
          )}
        </button>
      </div>

      {/* Detail: the row opens by its own measured height. */}
      {p.hasDetail && (
        <div
          className="grid transition-[grid-template-rows] duration-[420ms]"
          style={{
            gridTemplateRows: p.isOpen ? "1fr" : "0fr",
            transitionTimingFunction: EASE,
          }}
          inert={!p.isOpen}
        >
          <div className="min-h-0 overflow-hidden">
            <div
              className="border-t border-dashed border-border px-3 pb-4 pt-3"
              style={{
                paddingLeft: p.selectable ? 52 : 12,
                opacity: p.isOpen ? 1 : 0,
                transition: reduced
                  ? "none"
                  : `opacity 300ms ${EASE} ${p.isOpen ? 120 : 0}ms`,
              }}
            >
              {a.current?.detail(row)}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

const TableRow = React.memo(TableRowView) as typeof TableRowView;

export function DataTable<T>({
  columns,
  rows,
  getRowId = (row) => String((row as { id?: unknown }).id),
  rowLabel,
  noun = ["row", "rows"],
  sort: sortProp,
  defaultSort = null,
  onSortChange,
  searchable = true,
  searchPlaceholder = "Search",
  selectable = false,
  selected: selectedProp,
  defaultSelected = NO_IDS,
  onSelectedChange,
  actions = [],
  undoFor = 5000,
  onEdit,
  renderDetail,
  pageSize = 10,
  label = "Table",
  className = "",
  ...props
}: DataTableProps<T>) {
  const reduced = useReducedMotion();
  const uid = React.useId();
  const [sortOwn, setSortOwn] = React.useState<DataTableSort | null>(
    defaultSort,
  );
  const sort = sortProp === undefined ? sortOwn : sortProp;
  const [selectedOwn, setSelectedOwn] =
    React.useState<string[]>(defaultSelected);
  const selectedIds = selectedProp ?? selectedOwn;
  const selected = React.useMemo(() => new Set(selectedIds), [selectedIds]);
  const [query, setQuery] = React.useState("");
  const [page, setPage] = React.useState(0);
  const [pageDir, setPageDir] = React.useState(0);
  const [hidden, setHidden] = React.useState<ReadonlySet<string>>(
    () => new Set(),
  );
  const [undo, setUndo] = React.useState<Undo<T> | null>(null);
  const [open, setOpen] = React.useState<ReadonlySet<string>>(() => new Set());
  const [editing, setEditingState] = React.useState<{
    id: string;
    key: string;
  } | null>(null);
  // Enter and the blur that follows it both finish an edit; only the first counts.
  const editingRef = React.useRef<{ id: string; key: string } | null>(null);
  const setEditing = (e: { id: string; key: string } | null) => {
    editingRef.current = e;
    setEditingState(e);
  };
  const [drafts, setDrafts] = React.useState<
    ReadonlyMap<string, { value: string; status: "pending" | "done" }>
  >(() => new Map());
  const [actionStatus, setActionStatus] = React.useState<
    Record<string, ActionStatus>
  >({});
  const [notice, setNotice] = React.useState<{
    text: string;
    key: number;
  } | null>(null);
  const [announce, setAnnounce] = React.useState("");
  const [cursor, setCursor] = React.useState<Cursor | null>(null);
  const [cascade, setCascade] = React.useState<{
    ids: string[];
    key: number;
  } | null>(null);
  const [holdUndo, setHoldUndo] = React.useState(false);
  const anchor = React.useRef<string | null>(null);
  const bodyRef = React.useRef<HTMLDivElement>(null);
  const wrapRef = React.useRef<HTMLDivElement>(null);
  const gridRef = React.useRef<HTMLDivElement>(null);
  const ghostRef = React.useRef<HTMLDivElement>(null);
  const seq = React.useRef(0);

  const name = (row: T) =>
    rowLabel?.(row) ?? String(valueOf(columns[0], row) ?? getRowId(row));
  const valueOf = cellValue;
  const count = (n: number) => `${n === 1 ? noun[0] : noun[1]}`;
  const say = (text: string) =>
    setAnnounce((a) => (a === text ? `${text} ` : text));
  const flash = (text: string) => {
    const key = ++seq.current;
    setNotice({ text, key });
    window.setTimeout(
      () => setNotice((n) => (n?.key === key ? null : n)),
      3600,
    );
  };

  const setSelected = (next: string[]) => {
    if (selectedProp === undefined) setSelectedOwn(next);
    onSelectedChange?.(next);
  };

  // ── Rows in view ───────────────────────────────────────
  const searchCols = columns.some((c) => c.searchable)
    ? columns.filter((c) => c.searchable)
    : columns;
  const q = query.trim().toLowerCase();
  const visible = rows.filter((r) => !hidden.has(getRowId(r)));
  const matched = q
    ? visible.filter((r) =>
        searchCols.some((c) =>
          String(valueOf(c, r) ?? "")
            .toLowerCase()
            .includes(q),
        ),
      )
    : visible;
  const sortCol = sort ? columns.find((c) => c.key === sort.key) : undefined;
  const sorted = sortCol
    ? [...matched].sort(
        (a, b) =>
          compare(valueOf(sortCol, a), valueOf(sortCol, b)) *
          (sort!.dir === "asc" ? 1 : -1),
      )
    : matched;
  const pages = Math.max(1, Math.ceil(sorted.length / pageSize));
  const current = Math.min(page, pages - 1);
  const pageRows = sorted.slice(
    current * pageSize,
    current * pageSize + pageSize,
  );

  const ranks = new Map(sorted.map((r, i) => [getRowId(r), i]));
  const motion = useRowMotion(bodyRef, {
    reduced,
    resetKey: current,
    ranks,
    ghosts: ghostRef,
  });

  // A new page slides in from the side you went toward.
  const shownPage = React.useRef(current);
  React.useLayoutEffect(() => {
    if (shownPage.current === current) return;
    const dir = Math.sign(current - shownPage.current) || pageDir;
    shownPage.current = current;
    if (reduced) return;
    bodyRef.current?.animate(
      [
        {
          transform: `translateX(${dir * 28}px)`,
          opacity: 0,
          filter: "blur(4px)",
        },
        { transform: "none", opacity: 1, filter: "blur(0px)" },
      ],
      { duration: 440, easing: EASE },
    );
  }, [current, pageDir, reduced]);

  // The list's height eases to fit, so rows folding away or arriving never make the page jump.
  React.useLayoutEffect(() => {
    const wrap = wrapRef.current;
    const body = bodyRef.current;
    if (!wrap || !body) return;
    const fit = () => {
      const h = `${body.offsetHeight}px`;
      if (wrap.style.height === h) return;
      wrap.style.transition =
        wrap.dataset.ready && !reduced ? `height 420ms ${EASE}` : "none";
      wrap.style.height = h;
      wrap.dataset.ready = "1";
    };
    fit();
    const observer = new ResizeObserver(fit);
    observer.observe(body);
    return () => observer.disconnect();
  }, [reduced]);

  // ── Sorting ────────────────────────────────────────────
  const sortBy = (key: string) => {
    const col = columns.find((c) => c.key === key)!;
    const sample = rows.map((r) => valueOf(col, r)).find((v) => v != null);
    const firstDir =
      typeof sample === "number" || sample instanceof Date ? "desc" : "asc";
    const next: DataTableSort | null =
      sort?.key !== key
        ? { key, dir: firstDir }
        : { key, dir: sort.dir === "asc" ? "desc" : "asc" };
    motion.stagger();
    if (sortProp === undefined) setSortOwn(next);
    onSortChange?.(next);
    say(
      `Sorted by ${col.header}, ${next.dir === "asc" ? "ascending" : "descending"}.`,
    );
  };

  // ── Selection ──────────────────────────────────────────
  const toggle = (id: string, range: boolean) => {
    const ids = sorted.map(getRowId);
    if (range && anchor.current && ids.includes(anchor.current)) {
      const a = ids.indexOf(anchor.current);
      const b = ids.indexOf(id);
      const span = ids.slice(Math.min(a, b), Math.max(a, b) + 1);
      const on = !selected.has(id);
      const next = new Set(selected);
      span.forEach((x) => (on ? next.add(x) : next.delete(x)));
      // Ticks run down the range one after another, from the anchor.
      setCascade({
        ids: a <= b ? span : [...span].reverse(),
        key: ++seq.current,
      });
      setSelected([...next]);
      say(`${next.size} selected.`);
    } else {
      const next = new Set(selected);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      setCascade(null);
      setSelected([...next]);
      say(`${next.size ? `${next.size} selected` : "Selection cleared"}.`);
    }
    anchor.current = id;
  };
  const allIds = sorted.map(getRowId);
  const allState: "on" | "off" | "some" =
    allIds.length && allIds.every((i) => selected.has(i))
      ? "on"
      : allIds.some((i) => selected.has(i))
        ? "some"
        : "off";
  const toggleAll = () => {
    setCascade(
      allState === "on"
        ? null
        : { ids: pageRows.map(getRowId), key: ++seq.current },
    );
    setSelected(allState === "on" ? [] : allIds);
    say(
      allState === "on" ? "Selection cleared." : `${allIds.length} selected.`,
    );
  };

  // ── Actions ────────────────────────────────────────────
  const run = async (action: DataTableAction<T>) => {
    const chosen = rows.filter((r) => selected.has(getRowId(r)));
    if (!chosen.length) return;
    if (action.removes) {
      const ids = chosen.map(getRowId);
      // Commit whatever was waiting before this one takes the toolbar.
      if (undo) commitUndo(undo);
      setHidden((h) => new Set([...h, ...ids]));
      setSelected([]);
      setUndo({ key: ++seq.current, ids, rows: chosen, action });
      say(
        `${ids.length} ${count(ids.length)} ${action.progress?.[1]?.toLowerCase() ?? "removed"}. Undo is available.`,
      );
      return;
    }
    setActionStatus((s) => ({ ...s, [action.id]: "pending" }));
    try {
      await action.run(chosen);
      setActionStatus((s) => ({ ...s, [action.id]: "success" }));
      say(
        `${action.progress?.[1] ?? "Done"}: ${chosen.length} ${count(chosen.length)}.`,
      );
    } catch {
      setActionStatus((s) => ({ ...s, [action.id]: "error" }));
      say(`${action.label} failed.`);
    }
  };

  const commitUndo = async (u: Undo<T>) => {
    setUndo((cur) => (cur?.key === u.key ? null : cur));
    try {
      await u.action.run(u.rows);
    } catch {
      setHidden((h) => {
        const n = new Set(h);
        u.ids.forEach((i) => n.delete(i));
        return n;
      });
      flash(
        `Couldn't ${u.action.label.toLowerCase()} ${u.ids.length} ${count(u.ids.length)}. They're back.`,
      );
      say(`${u.action.label} failed. The rows are back.`);
    }
  };

  const takeBack = () => {
    if (!undo) return;
    setHidden((h) => {
      const n = new Set(h);
      undo.ids.forEach((i) => n.delete(i));
      return n;
    });
    setUndo(null);
    say(`Undone. ${undo.ids.length} ${count(undo.ids.length)} back.`);
  };

  // ── Editing ────────────────────────────────────────────
  const finishEdit = async (row: T, key: string, value: string | null) => {
    const id = getRowId(row);
    if (editingRef.current?.id !== id || editingRef.current.key !== key) return;
    setEditing(null);
    const cellKey = `${id}:${key}`;
    requestAnimationFrame(() =>
      gridRef.current
        ?.querySelector<HTMLElement>(
          `[data-row-id="${CSS.escape(id)}"] [data-col-key="${CSS.escape(key)}"]`,
        )
        ?.focus({ preventScroll: true }),
    );
    const col = columns.find((c) => c.key === key)!;
    if (value === null || value === String(valueOf(col, row) ?? "") || !onEdit)
      return;
    setDrafts((d) => new Map(d).set(cellKey, { value, status: "pending" }));
    try {
      await onEdit(row, key, value);
      setDrafts((d) => new Map(d).set(cellKey, { value, status: "done" }));
      say(`Saved ${col.header.toLowerCase()}.`);
      window.setTimeout(
        () =>
          setDrafts((d) => {
            const n = new Map(d);
            if (n.get(cellKey)?.status === "done") n.delete(cellKey);
            return n;
          }),
        1400,
      );
    } catch {
      setDrafts((d) => {
        const n = new Map(d);
        n.delete(cellKey);
        return n;
      });
      if (!reduced)
        gridRef.current
          ?.querySelector<HTMLElement>(
            `[data-row-id="${CSS.escape(id)}"] [data-col-key="${CSS.escape(key)}"]`,
          )
          ?.animate(
            [
              { transform: "none" },
              { transform: "translateX(-4px)" },
              { transform: "translateX(4px)" },
              { transform: "translateX(-2px)" },
              { transform: "none" },
            ],
            { duration: 380, easing: "ease-out" },
          );
      flash(`Couldn't save ${col.header.toLowerCase()} for ${name(row)}.`);
      say(`Couldn't save. ${col.header} is back to what it was.`);
    }
  };

  // ── Pages ──────────────────────────────────────────────
  const goPage = (dir: number) => {
    const next = Math.max(0, Math.min(pages - 1, current + dir));
    if (next === current) return;
    setPageDir(dir);
    setPage(next);
    setCursor(null);
    say(`Page ${next + 1} of ${pages}.`);
  };

  // ── Keys: rows, then cells ─────────────────────────────
  const editable = (c: DataTableColumn<T>) => !!(c.editable && onEdit);
  const focusAt = (c: Cursor) => {
    setCursor(c);
    requestAnimationFrame(() => {
      const row = gridRef.current?.querySelector<HTMLElement>(
        `[data-row-id="${CSS.escape(c.id)}"]`,
      );
      const cell =
        c.col < 0
          ? null
          : row?.querySelector<HTMLElement>(`[data-col-index="${c.col}"]`);
      // Narrow, the cells are a card and can't take focus: the row does.
      (cell && cell.offsetParent ? cell : row)?.focus({ preventScroll: false });
    });
  };
  const onGridKey = (e: React.KeyboardEvent) => {
    if (editing || (e.target as HTMLElement).closest("input, button")) return;
    const ids = pageRows.map(getRowId);
    const c =
      cursor && ids.includes(cursor.id)
        ? cursor
        : ids.length
          ? { id: ids[0], col: -1 }
          : null;
    if (!c) return;
    const i = ids.indexOf(c.id);
    const row = pageRows[i];
    const keys: Record<string, () => void> = {
      ArrowDown: () =>
        i < ids.length - 1 && focusAt({ id: ids[i + 1], col: c.col }),
      ArrowUp: () => i > 0 && focusAt({ id: ids[i - 1], col: c.col }),
      ArrowRight: () =>
        c.col < columns.length - 1 && focusAt({ id: c.id, col: c.col + 1 }),
      ArrowLeft: () => c.col > -1 && focusAt({ id: c.id, col: c.col - 1 }),
      Home: () => focusAt({ id: ids[0], col: c.col }),
      End: () => focusAt({ id: ids[ids.length - 1], col: c.col }),
      PageDown: () => goPage(1),
      PageUp: () => goPage(-1),
      " ": () => selectable && toggle(c.id, e.shiftKey),
      Enter: () => {
        const col = columns[c.col];
        if (col && editable(col)) setEditing({ id: c.id, key: col.key });
        else if (renderDetail) toggleOpen(c.id, row);
      },
    };
    const go = keys[e.key];
    if (!go) return;
    e.preventDefault();
    go();
  };

  const toggleOpen = (id: string, row: T) => {
    setOpen((o) => {
      const n = new Set(o);
      if (n.has(id)) n.delete(id);
      else n.add(id);
      return n;
    });
    say(`${open.has(id) ? "Closed" : "Opened"} ${name(row)}.`);
  };

  // ── Render ─────────────────────────────────────────────
  const tracks = `${selectable ? "40px " : ""}${columns.map((c) => c.width ?? "minmax(0,1fr)").join(" ")}${renderDetail ? " 40px" : ""}`;
  const mode = undo ? "undo" : selected.size ? "selection" : "search";
  const from = sorted.length ? current * pageSize + 1 : 0;
  const to = Math.min(sorted.length, current * pageSize + pageSize);
  const sortable = columns.filter((c) => c.sortable);
  const sortOptions: PillOption[] = [
    { value: "", label: "Unsorted" },
    ...sortable.flatMap((c) => [
      { value: `${c.key}:asc`, label: `${c.header}, ascending` },
      { value: `${c.key}:desc`, label: `${c.header}, descending` },
    ]),
  ];

  // What the memoised rows call, through one ref, so a row never re-renders just because these were re-created.
  const rowActions = React.useRef<RowActions<T>>({
    toggle,
    toggleOpen,
    cursor: (c) => setCursor(c),
    edit: (e) => setEditing(e),
    finish: finishEdit,
    detail: (row) => renderDetail?.(row),
  });
  React.useLayoutEffect(() => {
    rowActions.current = {
      toggle,
      toggleOpen,
      cursor: (c) => setCursor(c),
      edit: (e) => setEditing(e),
      finish: finishEdit,
      detail: (row) => renderDetail?.(row),
    };
  });

  return (
    <div
      className={`@container w-full text-foreground ${className}`}
      {...props}
    >
      {/* Toolbar: one surface that is the search, the selection or the undo. */}
      <div
        onPointerEnter={() => setHoldUndo(true)}
        onPointerLeave={() => setHoldUndo(false)}
        onFocus={() => setHoldUndo(true)}
        onBlur={(e) =>
          !e.currentTarget.contains(e.relatedTarget as Node | null) &&
          setHoldUndo(false)
        }
        className="relative h-11 overflow-hidden rounded-[14px] border border-border transition-colors duration-300"
        style={{
          background:
            mode === "search"
              ? "var(--background)"
              : "color-mix(in oklab, var(--primary) 6%, var(--background))",
        }}
      >
        <div
          className="absolute inset-0 flex items-center gap-2 pl-3 pr-2"
          style={swap(mode === "search", reduced, mode === "search" ? 0 : -8)}
          inert={mode !== "search"}
        >
          {searchable ? (
            <label className="flex min-w-0 flex-1 items-center gap-2">
              <Search
                className="size-4 shrink-0 text-muted-foreground"
                strokeWidth={1.75}
                aria-hidden="true"
              />
              <input
                value={query}
                onChange={(e) => {
                  setQuery(e.target.value);
                  setPage(0);
                }}
                placeholder={searchPlaceholder}
                aria-label={searchPlaceholder}
                aria-describedby={`${uid}-count`}
                className="h-9 min-w-0 flex-1 bg-transparent text-[13.5px] outline-none placeholder:text-muted-foreground [@media(pointer:coarse)]:text-[16px]"
              />
              <button
                type="button"
                aria-label="Clear search"
                onClick={() => setQuery("")}
                className="flex size-7 shrink-0 cursor-pointer items-center justify-center rounded-full text-muted-foreground hover:bg-accent hover:text-foreground"
                style={swap(!!query, reduced, 0)}
                tabIndex={query ? 0 : -1}
              >
                <X className="size-3.5" strokeWidth={1.75} />
              </button>
            </label>
          ) : (
            <span className="flex-1" />
          )}
          {sortable.length > 0 && (
            <span className="hidden shrink-0 @max-[34rem]:flex">
              <PillSelect
                label="Sort by"
                align="end"
                width={220}
                options={sortOptions}
                value={sort ? `${sort.key}:${sort.dir}` : ""}
                onValueChange={(v) => {
                  const [key, dir] = v.split(":");
                  const next = key ? { key, dir: dir as "asc" | "desc" } : null;
                  motion.stagger();
                  if (sortProp === undefined) setSortOwn(next);
                  onSortChange?.(next);
                }}
                // Plain text: this pill is hidden on wide tables, and a morph there would still measure every letter.
                renderValue={() => (
                  <span className="inline-flex items-center text-muted-foreground">
                    {sortCol ? sortCol.header : "Sort"}
                    <ArrowUp
                      className="ml-1 size-3"
                      strokeWidth={2}
                      aria-hidden="true"
                      style={{
                        transform:
                          sort?.dir === "desc" ? "rotate(180deg)" : "none",
                        transition: reduced
                          ? "none"
                          : `transform 420ms ${THROW}`,
                      }}
                    />
                  </span>
                )}
              />
            </span>
          )}
          <span
            id={`${uid}-count`}
            className="shrink-0 whitespace-nowrap pr-1 text-[12px] tabular-nums text-muted-foreground @max-[34rem]:hidden"
          >
            <NumberRoll value={sorted.length} />{" "}
            <TextMorph>{count(sorted.length)}</TextMorph>
          </span>
        </div>

        <div
          className="absolute inset-0 flex items-center gap-1 pl-1.5 pr-1.5"
          style={swap(
            mode === "selection",
            reduced,
            mode === "search" ? 8 : -8,
          )}
          inert={mode !== "selection"}
        >
          <button
            type="button"
            aria-label="Clear selection"
            onClick={() => setSelected([])}
            className={`flex size-8 shrink-0 cursor-pointer items-center justify-center rounded-full text-muted-foreground hover:bg-accent hover:text-foreground ${FOCUS}`}
          >
            <X className="size-4" strokeWidth={1.75} />
          </button>
          <span className="mr-auto whitespace-nowrap text-[13px] font-medium tabular-nums">
            <NumberRoll value={Math.max(1, selected.size)} /> selected
          </span>
          {actions.map((a) => (
            <StatusButton
              key={a.id}
              variant="ghost"
              size="sm"
              status={actionStatus[a.id] ?? "idle"}
              labels={{
                idle: a.label,
                pending: a.progress?.[0] ?? a.label,
                success: a.progress?.[1] ?? "Done",
                error: "Try again",
              }}
              onClick={() => run(a)}
              onReset={() => setActionStatus((s) => ({ ...s, [a.id]: "idle" }))}
              className={
                a.tone === "destructive" &&
                (actionStatus[a.id] ?? "idle") === "idle"
                  ? "!text-red-600 hover:!bg-red-500/10 dark:!text-red-400"
                  : ""
              }
            />
          ))}
        </div>

        <div
          className="absolute inset-0 flex items-center gap-2 pl-3 pr-1.5"
          style={swap(mode === "undo", reduced, 8)}
          inert={mode !== "undo"}
        >
          <span className="mr-auto whitespace-nowrap text-[13px] tabular-nums">
            {undo && (
              <>
                <NumberRoll value={undo.ids.length} /> {count(undo.ids.length)}{" "}
                {undo.action.progress?.[1]?.toLowerCase() ?? "removed"}
              </>
            )}
          </span>
          <button
            type="button"
            onClick={takeBack}
            className={`inline-flex h-7 cursor-pointer items-center rounded-full px-3 text-[12px] font-medium hover:bg-accent ${FOCUS}`}
          >
            Undo
          </button>
          {undo && (
            // The chance to undo, as a cavemio that drains; hovering holds it.
            <span
              key={undo.key}
              aria-hidden="true"
              className="absolute inset-x-0 bottom-0 h-px origin-left bg-foreground/40"
              style={{
                animation: `ui-progress ${undoFor}ms linear reverse forwards`,
                animationPlayState: holdUndo ? "paused" : "running",
              }}
              onAnimationEnd={() => commitUndo(undo)}
            />
          )}
        </div>
      </div>

      {/* Notice: one line that folds in when something went wrong. */}
      <div
        className="grid transition-[grid-template-rows] duration-300"
        style={{
          gridTemplateRows: notice ? "1fr" : "0fr",
          transitionTimingFunction: EASE,
        }}
      >
        <div className="min-w-0 overflow-hidden">
          <p className="truncate pl-1 pt-2 text-[12.5px] text-red-600 dark:text-red-400">
            {notice?.text ?? " "}
          </p>
        </div>
      </div>

      {/* Layout containment: re-laying the rows out after a sort never reaches the rest of the page. */}
      <div
        ref={gridRef}
        role="grid"
        aria-label={label}
        aria-rowcount={sorted.length + 1}
        aria-multiselectable={selectable || undefined}
        onKeyDown={onGridKey}
        className="mt-3 overflow-hidden rounded-[16px] border border-border [contain:layout_paint]"
      >
        {/* Header */}
        <div
          role="row"
          className="grid h-10 items-center border-b border-border text-[12px] text-muted-foreground @max-[34rem]:hidden"
          style={{ gridTemplateColumns: tracks }}
        >
          {selectable && (
            <span
              role="columnheader"
              className="flex items-center justify-center"
            >
              <button
                type="button"
                aria-label={
                  allState === "on" ? "Clear selection" : "Select all"
                }
                onClick={toggleAll}
                className={`flex size-8 cursor-pointer items-center justify-center rounded-[8px] hover:bg-accent ${FOCUS}`}
              >
                <Box state={allState} reduced={reduced} />
              </button>
            </span>
          )}
          {columns.map((col) => {
            const active = sort?.key === col.key;
            return (
              <span
                key={col.key}
                role="columnheader"
                aria-sort={
                  active
                    ? sort!.dir === "asc"
                      ? "ascending"
                      : "descending"
                    : col.sortable
                      ? "none"
                      : undefined
                }
                className={`min-w-0 px-1.5 ${col.align === "right" ? "text-right" : ""}`}
              >
                {col.sortable ? (
                  <button
                    type="button"
                    onClick={() => sortBy(col.key)}
                    className={`inline-flex h-7 max-w-full cursor-pointer items-center gap-1 rounded-[8px] px-1.5 transition-colors hover:bg-accent hover:text-foreground ${active ? "text-foreground" : ""} ${col.align === "right" ? "flex-row-reverse" : ""} ${FOCUS}`}
                  >
                    <span className="truncate">{col.header}</span>
                    <ArrowUp
                      className="size-3 shrink-0"
                      strokeWidth={2}
                      aria-hidden="true"
                      style={{
                        opacity: active ? 1 : 0,
                        transform: `${active && sort!.dir === "desc" ? "rotate(180deg)" : "rotate(0deg)"} scale(${active ? 1 : 0.6})`,
                        transition: reduced
                          ? "none"
                          : `transform 460ms ${THROW}, opacity 200ms ${EASE}`,
                      }}
                    />
                  </button>
                ) : (
                  <span className="block truncate px-1.5">{col.header}</span>
                )}
              </span>
            );
          })}
          {renderDetail && <span role="columnheader" aria-label="Details" />}
        </div>

        {/* Body: eases to its height; the page slides in from the side you went. */}
        <div ref={wrapRef} className="overflow-clip">
          <div ref={bodyRef} className="relative">
            {pageRows.map((row, i) => {
              const id = getRowId(row);
              return (
                <TableRow
                  key={id}
                  row={row}
                  id={id}
                  index={current * pageSize + i + 2}
                  columns={columns}
                  tracks={tracks}
                  selectable={selectable}
                  canEdit={!!onEdit}
                  hasDetail={!!renderDetail}
                  isSelected={selected.has(id)}
                  isOpen={open.has(id)}
                  delay={
                    cascade ? Math.max(0, cascade.ids.indexOf(id)) * 28 : 0
                  }
                  focusCol={cursor?.id === id ? cursor.col : null}
                  rowTab={
                    cursor
                      ? cursor.id === id && cursor.col === -1
                        ? 0
                        : -1
                      : i === 0
                        ? 0
                        : -1
                  }
                  editingKey={editing?.id === id ? editing.key : null}
                  drafts={drafts}
                  reduced={reduced}
                  name={name(row)}
                  actions={rowActions}
                />
              );
            })}

            {/* Rows that went: their own elements, folding away where they stood (see use-row-motion). */}
            <div
              ref={ghostRef}
              aria-hidden="true"
              className="pointer-events-none absolute inset-0"
            />

            {/* Nothing matches: said in the same place, the same height as a row. */}
            <div
              className="grid transition-[grid-template-rows,opacity] duration-300"
              style={{
                gridTemplateRows: pageRows.length ? "0fr" : "1fr",
                opacity: pageRows.length ? 0 : 1,
                transitionTimingFunction: EASE,
              }}
              aria-hidden={!!pageRows.length}
            >
              <div className="min-h-0 overflow-hidden">
                <p className="px-4 py-6 text-center text-[13px] text-muted-foreground">
                  <TextMorph animateWidth={false}>
                    {q
                      ? `No ${noun[1]} match “${query.trim()}”`
                      : `No ${noun[1]} yet`}
                  </TextMorph>
                </p>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Pages */}
      {pages > 1 && (
        <div className="mt-2.5 flex items-center justify-between gap-2 px-1 text-[12px] tabular-nums text-muted-foreground">
          <span className="inline-flex items-baseline">
            <NumberRoll value={from} />–<NumberRoll value={to} />
            &nbsp;of&nbsp;
            <NumberRoll value={sorted.length} />
          </span>
          <span className="flex items-center gap-0.5">
            <button
              type="button"
              aria-label="Previous page"
              disabled={current === 0}
              onClick={() => goPage(-1)}
              className={`flex size-7 cursor-pointer items-center justify-center rounded-full hover:bg-accent hover:text-foreground disabled:cursor-default disabled:opacity-40 ${FOCUS}`}
            >
              <ChevronLeft className="size-4" strokeWidth={1.75} />
            </button>
            <button
              type="button"
              aria-label="Next page"
              disabled={current >= pages - 1}
              onClick={() => goPage(1)}
              className={`flex size-7 cursor-pointer items-center justify-center rounded-full hover:bg-accent hover:text-foreground disabled:cursor-default disabled:opacity-40 ${FOCUS}`}
            >
              <ChevronRight className="size-4" strokeWidth={1.75} />
            </button>
          </span>
        </div>
      )}

      <p className="sr-only" role="status" aria-live="polite">
        {announce}
      </p>
    </div>
  );
}

"use client";

import * as React from "react";
import { createPortal } from "react-dom";
import { Field, fieldSurface, useFieldIds, useShake } from "./imported-field";
import {
  enterStyle,
  themeVars,
  useDismiss,
  useFloating,
  usePresence,
} from "./floating";
import { TextMorph } from "./text-morph";
import {
  EASE_OUT,
  EASE_THROW,
  INTERACTION_FOCUS,
  INTERACTION_PRESS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * DATE PICKER: one date, typed or picked
 *
 *   type     the field reads what people write: "tomorrow",
 *            "next fri", "in 3 days", "4 nov", "2026-11-04"; Enter
 *            or leaving the field settles it into "Wed 4 Nov 2026",
 *            and anything it can't read shakes and says so
 *   pick     the calendar rises off the field; months slide in from
 *            the side you moved toward while the month name morphs;
 *            the chosen day's mark glides from day to day
 *   keys     arrows move a day or a week, Page Up/Down a month,
 *            Home/End the week's ends, Enter picks, Escape closes
 *
 * Values are plain "YYYY-MM-DD" strings: no time zones to trip on.
 * ───────────────────────────────────────────────────────── */

export interface DatePickerProps {
  value?: string | null;
  defaultValue?: string | null;
  onValueChange?: (value: string | null) => void;
  label?: React.ReactNode;
  hint?: React.ReactNode;
  error?: React.ReactNode;
  placeholder?: string;
  /** Earliest and latest allowed days, "YYYY-MM-DD". */
  min?: string;
  max?: string;
  /** 1 = Monday (default), 0 = Sunday. */
  weekStartsOn?: 0 | 1;
  locale?: string;
  id?: string;
  disabled?: boolean;
  className?: string;
}

// ── Plain-date helpers (UTC under the hood so no zone shifts a day) ──
const toISO = (d: Date) => d.toISOString().slice(0, 10);
const fromISO = (s: string) => new Date(`${s}T00:00:00Z`);
const addDays = (s: string, n: number) => {
  const d = fromISO(s);
  d.setUTCDate(d.getUTCDate() + n);
  return toISO(d);
};
const addMonths = (s: string, n: number) => {
  const d = fromISO(s);
  const day = d.getUTCDate();
  d.setUTCDate(1);
  d.setUTCMonth(d.getUTCMonth() + n);
  const last = new Date(
    Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 0),
  ).getUTCDate();
  d.setUTCDate(Math.min(day, last));
  return toISO(d);
};
const monthOf = (s: string) => s.slice(0, 7);
const localToday = () => {
  const n = new Date();
  return `${n.getFullYear()}-${String(n.getMonth() + 1).padStart(2, "0")}-${String(n.getDate()).padStart(2, "0")}`;
};
const subscribeDay = (cb: () => void) => {
  const t = window.setInterval(cb, 60_000);
  return () => window.clearInterval(t);
};

const MONTHS = [
  "jan",
  "feb",
  "mar",
  "apr",
  "may",
  "jun",
  "jul",
  "aug",
  "sep",
  "oct",
  "nov",
  "dec",
];
const DAYS = ["sun", "mon", "tue", "wed", "thu", "fri", "sat"];

/** Reads a typed date relative to `today`; null if it can't. */
export function parseDate(input: string, today: string): string | null {
  const t = input.trim().toLowerCase().replace(/\s+/g, " ");
  if (!t) return null;
  if (t === "today" || t === "now") return today;
  if (t === "tomorrow" || t === "tmr") return addDays(today, 1);
  if (t === "yesterday") return addDays(today, -1);
  let m = t.match(
    /^(?:in )?\+?(\d+) ?(d|day|days|w|wk|week|weeks|m|mo|month|months)(?: from now)?$/,
  );
  if (m) {
    const n = Number(m[1]);
    return m[2].startsWith("m")
      ? addMonths(today, n)
      : addDays(today, m[2].startsWith("w") ? n * 7 : n);
  }
  m = t.match(/^(next |this )?(sun|mon|tue|wed|thu|fri|sat)[a-z]*$/);
  if (m) {
    const want = DAYS.indexOf(m[2]);
    const now = fromISO(today).getUTCDay();
    let diff = (want - now + 7) % 7;
    if (diff === 0 || m[1] === "next ") diff = diff === 0 ? 7 : diff;
    return addDays(today, diff);
  }
  m = t.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (m) return valid(+m[1], +m[2], +m[3]);
  // "4 nov", "4 november 2027", "nov 4", "november 4, 2027"
  m =
    t.match(/^(\d{1,2})(?:st|nd|rd|th)? ([a-z]{3})[a-z]*,? ?(\d{4})?$/) ?? null;
  if (m) return withYear(+m[1], MONTHS.indexOf(m[2]) + 1, m[3], today);
  m = t.match(/^([a-z]{3})[a-z]* (\d{1,2})(?:st|nd|rd|th)?,? ?(\d{4})?$/);
  if (m) return withYear(+m[2], MONTHS.indexOf(m[1]) + 1, m[3], today);
  // 4/11/2026 reads day first
  m = t.match(/^(\d{1,2})[/.](\d{1,2})(?:[/.](\d{2,4}))?$/);
  if (m)
    return withYear(
      +m[1],
      +m[2],
      m[3] ? (m[3].length === 2 ? `20${m[3]}` : m[3]) : undefined,
      today,
    );
  return null;
}
function valid(y: number, mo: number, d: number) {
  if (mo < 1 || mo > 12 || d < 1) return null;
  const date = new Date(Date.UTC(y, mo - 1, d));
  return date.getUTCMonth() === mo - 1 ? toISO(date) : null;
}
function withYear(d: number, mo: number, y: string | undefined, today: string) {
  if (mo < 1) return null;
  if (y) return valid(+y, mo, d);
  const thisYear = valid(+today.slice(0, 4), mo, d);
  // No year: the next time that date comes round.
  return thisYear && thisYear < today
    ? valid(+today.slice(0, 4) + 1, mo, d)
    : thisYear;
}

function Arrow({ back }: { back?: boolean }) {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      aria-hidden="true"
      className="size-3.5"
    >
      <path
        d={back ? "M10 3.5 5.5 8l4.5 4.5" : "M6 3.5 10.5 8 6 12.5"}
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

export function DatePicker({
  value,
  defaultValue = null,
  onValueChange,
  label,
  hint,
  error,
  placeholder = "Pick a date or type one",
  min,
  max,
  weekStartsOn = 1,
  locale = "en-GB",
  id,
  disabled,
  className = "",
}: DatePickerProps) {
  const reduced = useInteractionReducedMotion();
  const ids = useFieldIds(id);
  const today = React.useSyncExternalStore(
    subscribeDay,
    localToday,
    () => null,
  );
  const [own, setOwn] = React.useState<string | null>(defaultValue);
  const current = value !== undefined ? value : own;
  const [draft, setDraft] = React.useState<string | null>(null);
  const [badInput, setBadInput] = React.useState(false);
  const [open, setOpen] = React.useState(false);
  const [view, setView] = React.useState(() =>
    monthOf(current ?? defaultValue ?? "2026-01-01"),
  );
  const [focusDay, setFocusDay] = React.useState<string | null>(null);
  const [dir, setDir] = React.useState(0);
  const anchor = React.useRef<HTMLDivElement>(null);
  const surface = React.useRef<HTMLDivElement>(null);
  const grid = React.useRef<HTMLDivElement>(null);
  const { mounted, shown } = usePresence(open, 180);
  const place = useFloating({
    open: mounted,
    anchor,
    floating: surface,
    side: "bottom",
    align: "start",
    offset: 6,
  });
  const [vars, setVars] = React.useState<React.CSSProperties>({});
  const shakeRef = useShake<HTMLDivElement>(badInput || !!error);
  const [mark, setMark] = React.useState<{ x: number; y: number } | null>(null);
  const [markReady, setMarkReady] = React.useState(false);

  const fmt = React.useMemo(
    () =>
      new Intl.DateTimeFormat(locale, {
        weekday: "short",
        day: "numeric",
        month: "short",
        year: "numeric",
        timeZone: "UTC",
      }),
    [locale],
  );
  const monthFmt = React.useMemo(
    () =>
      new Intl.DateTimeFormat(locale, {
        month: "long",
        year: "numeric",
        timeZone: "UTC",
      }),
    [locale],
  );
  const dayFmt = React.useMemo(
    () =>
      new Intl.DateTimeFormat(locale, {
        weekday: "long",
        day: "numeric",
        month: "long",
        year: "numeric",
        timeZone: "UTC",
      }),
    [locale],
  );
  const headFmt = React.useMemo(
    () =>
      new Intl.DateTimeFormat(locale, { weekday: "narrow", timeZone: "UTC" }),
    [locale],
  );

  const allowed = (d: string) => (!min || d >= min) && (!max || d <= max);
  const commit = (next: string | null) => {
    if (value === undefined) setOwn(next);
    onValueChange?.(next);
  };

  const settle = () => {
    if (draft === null) return;
    const text = draft.trim();
    if (!text) {
      setDraft(null);
      setBadInput(false);
      return commit(null);
    }
    const parsed = parseDate(text, today ?? localToday());
    if (!parsed || !allowed(parsed)) return setBadInput(true);
    setDraft(null);
    setBadInput(false);
    setView(monthOf(parsed));
    commit(parsed);
  };

  const openCalendar = () => {
    const start = current ?? today ?? localToday();
    setView(monthOf(start));
    setFocusDay(start);
    setDir(0);
    setOpen(true);
  };
  const close = (refocus: boolean) => {
    setOpen(false);
    if (refocus) document.getElementById(ids.id)?.focus();
  };
  useDismiss(open, (reason) => close(reason === "escape"), [anchor, surface]);

  React.useLayoutEffect(() => {
    if (mounted) setVars(themeVars(anchor.current));
  }, [mounted]);

  // Days of the shown month, padded to whole weeks.
  const days = React.useMemo(() => {
    const first = fromISO(`${view}-01`);
    const lead = (first.getUTCDay() - weekStartsOn + 7) % 7;
    const start = addDays(`${view}-01`, -lead);
    const count =
      Math.ceil(
        (lead +
          new Date(
            Date.UTC(first.getUTCFullYear(), first.getUTCMonth() + 1, 0),
          ).getUTCDate()) /
          7,
      ) * 7;
    return Array.from({ length: count }, (_, i) => addDays(start, i));
  }, [view, weekStartsOn]);

  const goMonth = (n: number) => {
    setDir(n);
    setView((v) => monthOf(addMonths(`${v}-01`, n)));
    setFocusDay((f) => (f ? addMonths(f, n) : f));
  };

  // The chosen day's mark glides within a month; a new month slides in from its side.
  React.useLayoutEffect(() => {
    const g = grid.current;
    if (!g) return;
    const measure = () => {
      const el = current
        ? g.querySelector<HTMLElement>(`[data-day="${current}"]`)
        : null;
      setMark((p) =>
        el
          ? p && p.x === el.offsetLeft && p.y === el.offsetTop
            ? p
            : { x: el.offsetLeft, y: el.offsetTop }
          : null,
      );
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(g);
    return () => ro.disconnect();
  }, [current, view, mounted]);
  React.useEffect(() => {
    if (!mark || markReady) return;
    const f = requestAnimationFrame(() => setMarkReady(true));
    return () => cancelAnimationFrame(f);
  }, [mark, markReady]);
  React.useLayoutEffect(() => {
    if (!dir || reduced) return;
    grid.current?.animate(
      [
        {
          opacity: 0,
          transform: `translateX(${dir * 24}px)`,
          filter: "blur(4px)",
        },
        { opacity: 1, transform: "none", filter: "blur(0px)" },
      ],
      { duration: 360, easing: EASE_OUT },
    );
  }, [view, dir, reduced]);

  // Keep keyboard focus on the focused day once the calendar is up.
  React.useEffect(() => {
    if (!open || !shown || !focusDay) return;
    grid.current
      ?.querySelector<HTMLElement>(`[data-day="${focusDay}"]`)
      ?.focus({ preventScroll: true });
  }, [open, shown, focusDay, view]);

  const onGridKey = (e: React.KeyboardEvent) => {
    if (!focusDay) return;
    const moves: Record<string, () => string> = {
      ArrowLeft: () => addDays(focusDay, -1),
      ArrowRight: () => addDays(focusDay, 1),
      ArrowUp: () => addDays(focusDay, -7),
      ArrowDown: () => addDays(focusDay, 7),
      PageUp: () => addMonths(focusDay, -1),
      PageDown: () => addMonths(focusDay, 1),
      Home: () =>
        addDays(
          focusDay,
          -((fromISO(focusDay).getUTCDay() - weekStartsOn + 7) % 7),
        ),
      End: () =>
        addDays(
          focusDay,
          6 - ((fromISO(focusDay).getUTCDay() - weekStartsOn + 7) % 7),
        ),
    };
    if (e.key in moves) {
      e.preventDefault();
      const next = moves[e.key]();
      if (monthOf(next) !== view) {
        setDir(next > focusDay ? 1 : -1);
        setView(monthOf(next));
      }
      setFocusDay(next);
    } else if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      if (allowed(focusDay)) {
        commit(focusDay);
        close(true);
      }
    }
  };

  const shownText = draft ?? (current ? fmt.format(fromISO(current)) : "");
  const describedBy =
    [
      hint && !error && !badInput ? ids.hint : null,
      error || badInput ? ids.error : null,
    ]
      .filter(Boolean)
      .join(" ") || undefined;

  return (
    <Field
      id={ids.id}
      label={label}
      hint={hint}
      error={
        error ??
        (badInput
          ? "Couldn't read that date. Try “tomorrow” or “4 Nov”."
          : undefined)
      }
      className={className}
    >
      <div ref={anchor}>
        <div
          ref={shakeRef}
          className={`${fieldSurface({ invalid: !!error || badInput, disabled })} h-9 text-[16px] sm:text-[13.5px]`}
        >
          <input
            id={ids.id}
            value={shownText}
            placeholder={placeholder}
            disabled={disabled}
            aria-invalid={error || badInput ? true : undefined}
            aria-describedby={describedBy}
            onChange={(e) => {
              setDraft(e.target.value);
              setBadInput(false);
            }}
            onBlur={(e) => {
              if (!surface.current?.contains(e.relatedTarget as Node)) settle();
            }}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                e.preventDefault();
                settle();
              } else if (e.key === "ArrowDown" && e.altKey) {
                e.preventDefault();
                openCalendar();
              }
            }}
            className="h-full min-w-0 flex-1 bg-transparent pl-4 pr-1 outline-none placeholder:text-muted-foreground/70"
          />
          <button
            type="button"
            aria-label="Choose date"
            aria-haspopup="dialog"
            aria-expanded={open}
            disabled={disabled}
            onClick={() => (open ? close(false) : openCalendar())}
            className={`mr-1 flex size-7 shrink-0 items-center justify-center rounded-full text-muted-foreground cursor-pointer hover:bg-accent hover:text-foreground ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`}
          >
            <svg
              viewBox="0 0 16 16"
              fill="none"
              aria-hidden="true"
              className="size-3.5"
            >
              <rect
                x="2.5"
                y="3.5"
                width="11"
                height="10"
                rx="2"
                stroke="currentColor"
                strokeWidth="1.4"
              />
              <path
                d="M2.5 6.5h11M5.5 2v3M10.5 2v3"
                stroke="currentColor"
                strokeWidth="1.4"
                strokeLinecap="round"
              />
            </svg>
          </button>
        </div>
      </div>
      {mounted &&
        createPortal(
          <div
            ref={surface}
            role="dialog"
            aria-label="Choose date"
            className="fixed left-0 top-0 z-[55] w-[284px] rounded-[18px] bg-popover p-3 text-popover-foreground shadow-[0_0_0_1px_var(--border)]"
            style={{
              ...vars,
              left: place.x,
              top: place.y,
              transformOrigin: place.origin,
              ...enterStyle(shown, place.side, reduced),
            }}
          >
            <div className="mb-2 flex items-center justify-between pl-2">
              <span
                className="text-[13.5px] font-medium text-foreground"
                aria-live="polite"
              >
                <TextMorph>{monthFmt.format(fromISO(`${view}-01`))}</TextMorph>
              </span>
              <div className="flex">
                {[-1, 1].map((n) => (
                  <button
                    key={n}
                    type="button"
                    aria-label={n < 0 ? "Previous month" : "Next month"}
                    onClick={() => goMonth(n)}
                    className={`flex size-7 items-center justify-center rounded-full text-muted-foreground cursor-pointer hover:bg-accent hover:text-foreground ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`}
                  >
                    <Arrow back={n < 0} />
                  </button>
                ))}
              </div>
            </div>
            <div
              className="grid grid-cols-7 pb-1 text-center text-[11px] text-muted-foreground"
              aria-hidden="true"
            >
              {days.slice(0, 7).map((d) => (
                <span key={d}>{headFmt.format(fromISO(d))}</span>
              ))}
            </div>
            <div
              ref={grid}
              role="grid"
              aria-label={monthFmt.format(fromISO(`${view}-01`))}
              onKeyDown={onGridKey}
              className="relative grid grid-cols-7 gap-y-0.5"
            >
              <span
                aria-hidden="true"
                className="pointer-events-none absolute left-0 top-0 size-9 rounded-full bg-primary"
                style={{
                  transform: `translate3d(${mark?.x ?? 0}px, ${mark?.y ?? 0}px, 0)`,
                  opacity: mark ? 1 : 0,
                  transition:
                    reduced || !markReady
                      ? "none"
                      : `transform 420ms ${EASE_THROW}, opacity 200ms ${EASE_OUT}`,
                }}
              />
              {days.map((d) => {
                const inMonth = monthOf(d) === view;
                const on = d === current;
                const ok = allowed(d);
                return (
                  <button
                    key={d}
                    type="button"
                    role="gridcell"
                    data-day={d}
                    aria-selected={on}
                    aria-label={dayFmt.format(fromISO(d))}
                    aria-current={d === today ? "date" : undefined}
                    tabIndex={d === focusDay ? 0 : -1}
                    disabled={!ok}
                    onClick={() => {
                      commit(d);
                      setDraft(null);
                      setBadInput(false);
                      close(true);
                    }}
                    className={`relative z-10 mx-auto flex size-9 items-center justify-center rounded-full text-[13px] tabular-nums cursor-pointer transition-colors duration-200 disabled:cursor-default disabled:opacity-30 ${INTERACTION_FOCUS} focus-visible:ring-offset-0 ${
                      on
                        ? "text-primary-foreground"
                        : inMonth
                          ? "text-foreground hover:bg-accent"
                          : "text-muted-foreground/50 hover:bg-accent"
                    } ${d === today && !on ? "shadow-[inset_0_0_0_1px_var(--border)]" : ""}`}
                  >
                    {Number(d.slice(8))}
                  </button>
                );
              })}
            </div>
            <div className="mt-2 flex justify-between border-t border-border pt-2">
              <button
                type="button"
                onClick={() => {
                  const t = today ?? localToday();
                  commit(t);
                  setDraft(null);
                  close(true);
                }}
                className={`h-7 rounded-full px-2.5 text-[12.5px] font-medium text-foreground cursor-pointer hover:bg-accent ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`}
              >
                Today
              </button>
              {current && (
                <button
                  type="button"
                  onClick={() => {
                    commit(null);
                    setDraft(null);
                    close(true);
                  }}
                  className={`h-7 rounded-full px-2.5 text-[12.5px] text-muted-foreground cursor-pointer hover:bg-accent hover:text-foreground ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`}
                >
                  Clear
                </button>
              )}
            </div>
          </div>,
          document.body,
        )}
    </Field>
  );
}

export default DatePicker;

"use client";

import * as React from "react";
import {
  CalendarDays,
  ChevronDown,
  ChevronLeft,
  ChevronRight,
} from "lucide-react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * DATE RANGE PICKER: the range is one liquid band
 *
 *   open      the panel unfolds out of the pill's footprint:
 *             presets on one side, the month on the other
 *   pick      the first day you tap drops a dot; a band follows
 *             the pointer to wherever you'd end it, and a second
 *             dot rides along with it. The second tap sets it.
 *             The band is one shape per week, stretching between
 *             days, and the dots glide from day to day, so
 *             nothing lights up cell by cell
 *   presets   a highlight slides to the preset you choose; the
 *             band flows to its span and the label and the day
 *             count morph and roll to match
 *   month     ‹ and › slide the next month in from the side you
 *             went
 *   apply     the pill's label morphs to the new range; Cancel,
 *             Escape or a tap outside folds the panel back into
 *             the pill unchanged
 *
 * The days are a grid for the keyboard too: arrows, Home/End,
 * Page Up/Down for months, Enter to pick.
 * ───────────────────────────────────────────────────────── */

export interface DateRange {
  start: Date;
  end: Date;
}

export interface DateRangePreset {
  label: string;
  range: (today: Date) => DateRange;
}

export interface DateRangePickerProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onChange" | "defaultValue"
> {
  value?: DateRange | null;
  defaultValue?: DateRange | null;
  onValueChange?: (range: DateRange) => void;
  /** Shortcuts down the side; pass [] for none. */
  presets?: DateRangePreset[];
  /** Days before or after these can't be picked. */
  min?: Date;
  max?: Date;
  /** Count days (analytics) or nights (stays, which need at least one). */
  unit?: "days" | "nights";
  /** Weeks start on Monday (1) or Sunday (0). */
  weekStartsOn?: 0 | 1;
  locales?: string | string[];
  placeholder?: string;
  /** Line the panel up with the pill's left or right edge. */
  align?: "start" | "end";
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const GLIDE = 340;
/** The gap between a day's dot and its cell, in CSS. */
const INSET = "calc((var(--cell) - var(--dot)) / 2)";

const day = (d: Date) => new Date(d.getFullYear(), d.getMonth(), d.getDate());
const addDays = (d: Date, n: number) =>
  new Date(d.getFullYear(), d.getMonth(), d.getDate() + n);
const monthOf = (d: Date) => new Date(d.getFullYear(), d.getMonth(), 1);
const same = (a: Date, b: Date) =>
  a.getFullYear() === b.getFullYear() &&
  a.getMonth() === b.getMonth() &&
  a.getDate() === b.getDate();
const order = (a: Date, b: Date): DateRange =>
  a <= b ? { start: day(a), end: day(b) } : { start: day(b), end: day(a) };
const span = (r: DateRange) =>
  Math.round((day(r.end).getTime() - day(r.start).getTime()) / 86_400_000) + 1;
/** The same day of the month n months on, kept inside that month. */
const shiftMonth = (d: Date, n: number) => {
  const last = new Date(d.getFullYear(), d.getMonth() + n + 1, 0).getDate();
  return new Date(
    d.getFullYear(),
    d.getMonth() + n,
    Math.min(d.getDate(), last),
  );
};

export const DATE_RANGE_PRESETS: DateRangePreset[] = [
  { label: "Today", range: (t) => ({ start: t, end: t }) },
  { label: "Last 7 days", range: (t) => ({ start: addDays(t, -6), end: t }) },
  { label: "Last 30 days", range: (t) => ({ start: addDays(t, -29), end: t }) },
  {
    label: "This month",
    range: (t) => ({
      start: new Date(t.getFullYear(), t.getMonth(), 1),
      end: t,
    }),
  },
  {
    label: "Last month",
    range: (t) => ({
      start: new Date(t.getFullYear(), t.getMonth() - 1, 1),
      end: new Date(t.getFullYear(), t.getMonth(), 0),
    }),
  },
  {
    label: "This year",
    range: (t) => ({ start: new Date(t.getFullYear(), 0, 1), end: t }),
  },
];

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Six weeks of days for the month, starting on the week's first day. */
function weeksOf(month: Date, weekStartsOn: number) {
  const lead = (month.getDay() - weekStartsOn + 7) % 7;
  const start = addDays(month, -lead);
  return Array.from({ length: 6 }, (_, w) =>
    Array.from({ length: 7 }, (_, d) => addDays(start, w * 7 + d)),
  );
}

/** The dot on the range's first or last day; it glides when the day changes and pops in when it appears. */
function Dot({
  row,
  col,
  reduced,
  light,
}: {
  row: number;
  col: number;
  reduced: boolean;
  light: boolean;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useEffect(() => {
    if (reduced) return;
    ref.current?.animate(
      [
        { transform: "scale(0.5)", opacity: 0 },
        { transform: "scale(1)", opacity: 1 },
      ],
      { duration: 300, easing: THROW },
    );
  }, [reduced]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className={`absolute rounded-full ${light ? "bg-primary/80" : "bg-primary"}`}
      style={{
        left: `calc(var(--cell) * ${col} + ${INSET})`,
        top: `calc(var(--cell) * ${row} + ${INSET})`,
        width: "var(--dot)",
        height: "var(--dot)",
        transition: reduced
          ? "none"
          : `left ${GLIDE}ms ${EASE}, top ${GLIDE}ms ${EASE}, background-color 200ms`,
      }}
    />
  );
}

export function DateRangePicker({
  value,
  defaultValue = null,
  onValueChange,
  presets = DATE_RANGE_PRESETS,
  min,
  max,
  unit = "days",
  weekStartsOn = 1,
  locales,
  placeholder = "Pick dates",
  align = "start",
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  className = "",
  ...props
}: DateRangePickerProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const [today] = React.useState(() => day(new Date()));
  const [own, setOwn] = React.useState<DateRange | null>(defaultValue);
  const committed = value === undefined ? own : value;
  const [phase, setPhase] = React.useState<
    "closed" | "opening" | "open" | "closing"
  >(() => ((openProp ?? defaultOpen) ? "open" : "closed"));
  const [draft, setDraft] = React.useState<DateRange | null>(
    () => committed && order(committed.start, committed.end),
  );
  const [anchor, setAnchor] = React.useState<Date | null>(null);
  const [hover, setHover] = React.useState<Date | null>(null);
  const [month, setMonth] = React.useState(() =>
    monthOf(committed?.end ?? today),
  );
  const [focusDay, setFocusDay] = React.useState<Date>(() =>
    day(committed?.end ?? today),
  );
  const [frame, setFrame] = React.useState({
    shift: 0,
    left: 0,
    right: 0,
    max: 0,
  });
  const [mark, setMark] = React.useState({
    x: 0,
    y: 0,
    w: 0,
    h: 0,
    on: false,
    slide: false,
  });
  const [announce, setAnnounce] = React.useState("");
  const rootRef = React.useRef<HTMLDivElement>(null);
  const triggerRef = React.useRef<HTMLButtonElement>(null);
  const panelRef = React.useRef<HTMLDivElement>(null);
  const gridRef = React.useRef<HTMLDivElement>(null);
  const presetRefs = React.useRef<(HTMLButtonElement | null)[]>([]);
  const dayRefs = React.useRef(new Map<string, HTMLButtonElement>());
  const focusGrid = React.useRef(false);
  const isOpen = phase === "open" || phase === "opening";
  const mounted = phase !== "closed";
  const nights = unit === "nights";
  const lo = min ? day(min) : null;
  const hi = max ? day(max) : null;
  const blocked = (d: Date) => Boolean((lo && d < lo) || (hi && d > hi));

  const fmt = React.useMemo(
    () =>
      new Intl.DateTimeFormat(locales ?? "en-GB", {
        day: "numeric",
        month: "short",
        year: "numeric",
      }),
    [locales],
  );
  const longFmt = React.useMemo(
    () =>
      new Intl.DateTimeFormat(locales ?? "en-GB", {
        weekday: "long",
        day: "numeric",
        month: "long",
        year: "numeric",
      }),
    [locales],
  );
  const label = (r: DateRange | null) =>
    r
      ? same(r.start, r.end)
        ? fmt.format(r.start)
        : fmt.formatRange(r.start, r.end)
      : placeholder;
  const monthTitle = new Intl.DateTimeFormat(locales ?? "en-GB", {
    month: "long",
    year: "numeric",
  }).format(month);
  const weekdays = React.useMemo(() => {
    const narrow = new Intl.DateTimeFormat(locales ?? "en-GB", {
      weekday: "narrow",
    });
    return Array.from({ length: 7 }, (_, i) =>
      narrow.format(new Date(2024, 0, 7 + i + weekStartsOn)),
    ); // 7 Jan 2024 was a Sunday
  }, [locales, weekStartsOn]);
  const weeks = React.useMemo(
    () => weeksOf(month, weekStartsOn),
    [month, weekStartsOn],
  );

  const begin = () => {
    setDraft(committed && order(committed.start, committed.end));
    setAnchor(null);
    setHover(null);
    setMonth(monthOf(committed?.end ?? today));
    setFocusDay(day(committed?.end ?? today));
    setPhase("opening");
  };
  const end = () => setPhase((p) => (p === "closed" ? p : "closing"));
  const request = (next: boolean, returnFocus = true) => {
    if (openProp === undefined) (next ? begin : end)();
    onOpenChange?.(next);
    if (!next && returnFocus) triggerRef.current?.focus();
  };

  // Controlled: follow the open prop as soon as it changes.
  const [seenOpenProp, setSeenOpenProp] = React.useState(openProp);
  if (openProp !== seenOpenProp) {
    setSeenOpenProp(openProp);
    if (openProp && !isOpen) begin();
    if (openProp === false && isOpen) end();
  }

  // Before the panel shows: keep it inside the screen and any box that clips it (narrowing it if it
  // has to), and find the pill's footprint inside it to unfold from.
  const place = React.useCallback(() => {
    const panel = panelRef.current;
    const trigger = triggerRef.current;
    if (!panel || !trigger) return;
    let lo = 0;
    let hi = window.innerWidth;
    for (
      let el = rootRef.current?.parentElement;
      el && el !== document.body;
      el = el.parentElement
    ) {
      if (getComputedStyle(el).overflowX === "visible") continue;
      const r = el.getBoundingClientRect();
      lo = Math.max(lo, r.left);
      hi = Math.min(hi, r.right);
    }
    const edge = 8;
    const max = Math.max(240, hi - lo - edge * 2);
    panel.style.maxWidth = `${max}px`;
    setFrame((f) => {
      const p = panel.getBoundingClientRect();
      const left = p.left - f.shift;
      let shift = 0;
      if (left + p.width > hi - edge) shift = hi - edge - p.width - left;
      if (left + shift < lo + edge) shift = lo + edge - left;
      const t = trigger.getBoundingClientRect();
      return {
        shift,
        max,
        left: Math.max(0, t.left - (left + shift)),
        right: Math.max(0, left + shift + p.width - t.right),
      };
    });
  }, []);
  React.useLayoutEffect(() => {
    if (
      phase === "opening" ||
      (phase === "open" && frame.left === 0 && frame.right === 0)
    )
      place();
  }, [phase, place, frame.left, frame.right]);
  React.useEffect(() => {
    if (!mounted) return;
    window.addEventListener("resize", place);
    return () => window.removeEventListener("resize", place);
  }, [mounted, place]);

  // Opening grows the panel on the next frame; closing folds it back, then unmounts it.
  React.useEffect(() => {
    if (phase === "opening") {
      let inner = 0;
      const outer = requestAnimationFrame(
        () => (inner = requestAnimationFrame(() => setPhase("open"))),
      );
      return () => {
        cancelAnimationFrame(outer);
        cancelAnimationFrame(inner);
      };
    }
    if (phase === "closing") {
      const timer = window.setTimeout(
        () => setPhase("closed"),
        reduced ? 0 : 240,
      );
      return () => window.clearTimeout(timer);
    }
  }, [phase, reduced]);

  React.useEffect(() => {
    if (!mounted) return;
    const onDown = (e: PointerEvent) => {
      if (!rootRef.current?.contains(e.target as Node)) request(false, false);
    };
    window.addEventListener("pointerdown", onDown);
    return () => window.removeEventListener("pointerdown", onDown);
  });

  // Keyboard moves (and opening from the pill) put focus on the day; clicks elsewhere leave it alone.
  React.useEffect(() => {
    if (phase !== "open" || !focusGrid.current) return;
    focusGrid.current = false;
    dayRefs.current
      .get(focusDay.toDateString())
      ?.focus({ preventScroll: true });
  }, [focusDay, phase, month]);

  const showMonth = (target: Date) => {
    const next = monthOf(target);
    const dir = Math.sign(next.getTime() - month.getTime());
    if (!dir) return;
    setMonth(next);
    if (reduced) return;
    gridRef.current?.animate(
      [
        {
          transform: `translateX(${dir * 20}px)`,
          opacity: 0,
          filter: "blur(4px)",
        },
        { transform: "none", opacity: 1, filter: "blur(0px)" },
      ],
      { duration: 380, easing: EASE },
    );
  };
  const step = (n: number) => {
    setFocusDay((d) => shiftMonth(d, n));
    showMonth(new Date(month.getFullYear(), month.getMonth() + n, 1));
  };

  const pick = (d: Date) => {
    if (blocked(d)) return;
    if (!anchor) {
      setAnchor(d);
      setDraft({ start: d, end: d });
      return;
    }
    if (nights && same(anchor, d)) return; // a stay needs at least one night
    const r = order(anchor, d);
    setDraft(r);
    setAnchor(null);
    setHover(null);
    setAnnounce(label(r));
  };

  const choose = (p: DateRangePreset) => {
    const r = p.range(today);
    setDraft(r);
    setAnchor(null);
    setHover(null);
    setFocusDay(day(r.end));
    showMonth(r.end);
    setAnnounce(label(r));
  };

  const apply = () => {
    if (!draft) return;
    if (value === undefined) setOwn(draft);
    onValueChange?.(draft);
    request(false);
  };

  // What the band shows: the range being picked (first day to pointer), otherwise the draft.
  const band: DateRange | null = anchor && hover ? order(anchor, hover) : draft;
  const count = band ? span(band) - (nights ? 1 : 0) : 0;
  const ready =
    Boolean(draft) && !(nights && draft && same(draft.start, draft.end));
  const presetIndex = presets.findIndex((p) => {
    if (!draft || anchor) return false;
    const r = p.range(today);
    return same(r.start, draft.start) && same(r.end, draft.end);
  });

  // The preset highlight slides between presets; with none chosen it fades out where it is.
  React.useLayoutEffect(() => {
    if (!mounted) return;
    const el = presetRefs.current[presetIndex];
    setMark((m) =>
      el
        ? {
            x: el.offsetLeft,
            y: el.offsetTop,
            w: el.offsetWidth,
            h: el.offsetHeight,
            on: true,
            slide: m.on,
          }
        : { ...m, on: false, slide: false },
    );
    // In the narrow row of chips, scroll the chosen one into the middle.
    const row = el?.parentElement;
    if (el && row && row.scrollWidth > row.clientWidth)
      row.scrollTo({
        left: el.offsetLeft - (row.clientWidth - el.offsetWidth) / 2,
        behavior: phase === "open" && !reduced ? "smooth" : "auto",
      });
  }, [presetIndex, mounted, phase, reduced]);

  const tabDay = weeks.some((w) => w.some((d) => same(d, focusDay)))
    ? focusDay
    : month;
  const onGridKey = (e: React.KeyboardEvent) => {
    const col = (focusDay.getDay() - weekStartsOn + 7) % 7;
    const moves: Record<string, () => Date> = {
      ArrowLeft: () => addDays(focusDay, -1),
      ArrowRight: () => addDays(focusDay, 1),
      ArrowUp: () => addDays(focusDay, -7),
      ArrowDown: () => addDays(focusDay, 7),
      Home: () => addDays(focusDay, -col),
      End: () => addDays(focusDay, 6 - col),
      PageUp: () => shiftMonth(focusDay, -1),
      PageDown: () => shiftMonth(focusDay, 1),
    };
    if (!(e.key in moves)) return;
    e.preventDefault();
    const next = moves[e.key]();
    focusGrid.current = true;
    setFocusDay(next);
    if (anchor) setHover(next);
    showMonth(next);
  };

  const find = (d: Date) => {
    for (let r = 0; r < 6; r++)
      for (let c = 0; c < 7; c++) if (same(weeks[r][c], d)) return { r, c };
    return null;
  };
  const startAt = band ? find(band.start) : null;
  const endAt = band ? find(band.end) : null;
  const monthKey = `${month.getFullYear()}-${month.getMonth()}`;
  const prevOff = Boolean(lo && month <= monthOf(lo));
  const nextOff = Boolean(hi && month >= monthOf(hi));
  const closedClip = `inset(0 ${frame.right}px calc(100% - 36px) ${frame.left}px round 18px)`;

  return (
    <div
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
      onKeyDown={(e) => {
        props.onKeyDown?.(e);
        if (e.key !== "Escape" || !isOpen) return;
        e.stopPropagation();
        request(false);
      }}
    >
      <button
        ref={triggerRef}
        type="button"
        aria-haspopup="dialog"
        aria-expanded={isOpen}
        aria-controls={mounted ? `${id}-panel` : undefined}
        onClick={() => {
          if (!isOpen) focusGrid.current = true;
          request(!isOpen);
        }}
        className={`cursor-pointer inline-flex h-9 max-w-full items-center gap-2 rounded-full border border-border pl-3 pr-2.5 text-[13px] font-medium text-foreground transition-colors hover:bg-accent ${isOpen ? "bg-accent" : "bg-background"} ${FOCUS}`}
      >
        <CalendarDays
          aria-hidden="true"
          className="size-4 shrink-0 text-muted-foreground"
        />
        <TextMorph className="truncate tabular-nums">
          {label(committed)}
        </TextMorph>
        <ChevronDown
          aria-hidden="true"
          className="size-3.5 shrink-0 text-muted-foreground"
          style={{
            transform: isOpen ? "rotate(180deg)" : "none",
            transition: reduced ? "none" : `transform 320ms ${EASE}`,
          }}
        />
      </button>

      {mounted && (
        <div
          ref={panelRef}
          id={`${id}-panel`}
          role="dialog"
          aria-label="Choose dates"
          className={`@container absolute top-full z-50 mt-2 rounded-[20px] border border-border bg-popover text-popover-foreground ${align === "end" ? "right-0" : "left-0"} ${
            presets.length
              ? "w-[min(400px,calc(100vw-24px))]"
              : "w-[min(292px,calc(100vw-24px))]"
          }`}
          style={{
            translate: `${frame.shift}px 0`,
            maxWidth: frame.max || undefined,
            clipPath:
              phase === "open" ? "inset(0 0 0 0 round 20px)" : closedClip,
            opacity: phase === "open" ? 1 : 0,
            transition: reduced
              ? "none"
              : phase === "closing"
                ? `clip-path 240ms ${EASE}, opacity 180ms ${EASE} 40ms`
                : `clip-path 440ms ${EASE}, opacity 200ms ${EASE}`,
          }}
        >
          <div
            className={`grid p-2 [--cell:min(40px,calc((100cqw_-_26px)/7))] [--dot:calc(var(--cell)_-_6px)] ${
              presets.length
                ? "@min-[390px]:grid-cols-[112px_1fr] @min-[390px]:[--cell:36px]"
                : ""
            }`}
          >
            {presets.length > 0 && (
              <div
                role="group"
                aria-label="Presets"
                className="relative -mx-2 flex gap-1 overflow-x-auto px-2 pb-2 pr-8 [mask-image:linear-gradient(to_right,transparent,black_10px,black_calc(100%_-_32px),transparent)] [scrollbar-width:none] @min-[390px]:mx-0 @min-[390px]:flex-col @min-[390px]:overflow-visible @min-[390px]:border-r @min-[390px]:border-border @min-[390px]:px-0 @min-[390px]:pb-0 @min-[390px]:pr-2 @min-[390px]:[mask-image:none] [&::-webkit-scrollbar]:hidden"
              >
                <span
                  aria-hidden="true"
                  className="absolute left-0 top-0 rounded-full bg-accent @min-[390px]:rounded-[10px]"
                  style={{
                    transform: `translate(${mark.x}px, ${mark.y}px)`,
                    width: mark.w,
                    height: mark.h,
                    opacity: mark.on ? 1 : 0,
                    transition: reduced
                      ? "none"
                      : `${mark.slide ? `transform 380ms ${EASE}, width 380ms ${EASE}, height 380ms ${EASE}, ` : ""}opacity 200ms ${EASE}`,
                  }}
                />
                {presets.map((p, i) => (
                  <button
                    key={p.label}
                    ref={(el) => {
                      presetRefs.current[i] = el;
                    }}
                    type="button"
                    aria-pressed={i === presetIndex}
                    onClick={() => choose(p)}
                    className={`cursor-pointer relative h-8 shrink-0 whitespace-nowrap rounded-full px-3 text-left text-[12.5px] transition-colors duration-200 @min-[390px]:rounded-[10px] @min-[390px]:px-2.5 ${FOCUS} ${
                      i === presetIndex
                        ? "font-medium text-foreground"
                        : "text-muted-foreground hover:text-foreground"
                    }`}
                  >
                    {p.label}
                  </button>
                ))}
              </div>
            )}

            <div className="mx-auto" style={{ width: "calc(var(--cell) * 7)" }}>
              <div className="flex h-9 items-center justify-between">
                <button
                  type="button"
                  aria-label="Previous month"
                  disabled={prevOff}
                  onClick={() => step(-1)}
                  className={`cursor-pointer disabled:cursor-default -ml-1 flex size-8 items-center justify-center rounded-full text-foreground transition-opacity hover:bg-accent disabled:pointer-events-none disabled:opacity-30 ${FOCUS}`}
                >
                  <ChevronLeft className="size-4" aria-hidden="true" />
                </button>
                <p
                  className="text-[13px] font-medium text-foreground"
                  aria-live="polite"
                >
                  <TextMorph>{monthTitle}</TextMorph>
                </p>
                <button
                  type="button"
                  aria-label="Next month"
                  disabled={nextOff}
                  onClick={() => step(1)}
                  className={`cursor-pointer disabled:cursor-default -mr-1 flex size-8 items-center justify-center rounded-full text-foreground transition-opacity hover:bg-accent disabled:pointer-events-none disabled:opacity-30 ${FOCUS}`}
                >
                  <ChevronRight className="size-4" aria-hidden="true" />
                </button>
              </div>

              <div
                className="flex text-[11px] text-muted-foreground"
                aria-hidden="true"
              >
                {weekdays.map((w, i) => (
                  <span
                    key={i}
                    className="flex h-7 items-center justify-center"
                    style={{ width: "var(--cell)" }}
                  >
                    {w}
                  </span>
                ))}
              </div>

              <div
                ref={gridRef}
                role="grid"
                aria-label={monthTitle}
                onKeyDown={onGridKey}
                onPointerLeave={() => setHover(null)}
                className="relative"
              >
                {/* The band and its dots, laid out per month so they never glide across a month change. */}
                <div
                  key={monthKey}
                  aria-hidden="true"
                  className="pointer-events-none absolute inset-0"
                >
                  {weeks.map((row, r) => {
                    let a = -1;
                    let b = -1;
                    if (band)
                      row.forEach((d, c) => {
                        if (d >= band.start && d <= band.end) {
                          if (a === -1) a = c;
                          b = c;
                        }
                      });
                    const on = a !== -1 && band !== null;
                    const opens = on && same(row[a], band.start);
                    const closes = on && same(row[b], band.end);
                    const after = band !== null && row[0] > band.end;
                    return (
                      <span
                        key={r}
                        className={`absolute ${anchor ? "bg-primary/[0.07]" : "bg-primary/[0.1]"}`}
                        style={{
                          top: `calc(var(--cell) * ${r} + ${INSET})`,
                          height: "var(--dot)",
                          left: on
                            ? `calc(var(--cell) * ${a} + ${opens ? INSET : "2px"})`
                            : after
                              ? "2px"
                              : "calc(var(--cell) * 7 - 2px)",
                          width: on
                            ? `calc(var(--cell) * ${b - a + 1} - ${opens ? INSET : "2px"} - ${closes ? INSET : "2px"})`
                            : "0px",
                          opacity: on ? 1 : 0,
                          borderRadius: `${opens ? 999 : 8}px ${closes ? 999 : 8}px ${closes ? 999 : 8}px ${opens ? 999 : 8}px`,
                          transition: reduced
                            ? "none"
                            : `left ${GLIDE}ms ${EASE}, width ${GLIDE}ms ${EASE}, opacity 220ms ${EASE}, border-radius 260ms ${EASE}, background-color 200ms`,
                        }}
                      />
                    );
                  })}
                  {startAt && (
                    <Dot
                      row={startAt.r}
                      col={startAt.c}
                      reduced={reduced}
                      light={false}
                    />
                  )}
                  {endAt && (
                    <Dot
                      row={endAt.r}
                      col={endAt.c}
                      reduced={reduced}
                      light={Boolean(anchor && hover)}
                    />
                  )}
                </div>

                {weeks.map((row, r) => (
                  <div key={r} role="row" className="relative flex">
                    {row.map((d) => {
                      const inMonth = d.getMonth() === month.getMonth();
                      const edge =
                        band !== null &&
                        (same(d, band.start) || same(d, band.end));
                      const off = blocked(d);
                      return (
                        <button
                          key={d.toDateString()}
                          ref={(el) => {
                            if (el) dayRefs.current.set(d.toDateString(), el);
                            else dayRefs.current.delete(d.toDateString());
                          }}
                          type="button"
                          role="gridcell"
                          tabIndex={same(d, tabDay) ? 0 : -1}
                          aria-selected={
                            band !== null && d >= band.start && d <= band.end
                          }
                          aria-disabled={off || undefined}
                          aria-current={same(d, today) ? "date" : undefined}
                          aria-label={longFmt.format(d)}
                          onClick={() => {
                            setFocusDay(d);
                            pick(d);
                          }}
                          onPointerEnter={() => {
                            if (anchor && !off) setHover(d);
                          }}
                          className={`group flex items-center justify-center outline-none ${off ? "cursor-default" : ""}`}
                          style={{
                            width: "var(--cell)",
                            height: "var(--cell)",
                          }}
                        >
                          <span
                            className={`flex items-center justify-center rounded-full text-[13px] tabular-nums group-focus-visible:ring-2 group-focus-visible:ring-ring/40 @min-[390px]:text-[12.5px] ${
                              edge
                                ? "font-medium text-primary-foreground"
                                : off
                                  ? "text-muted-foreground/35"
                                  : `${inMonth ? "text-foreground" : "text-muted-foreground/60"} group-hover:bg-accent`
                            } ${same(d, today) && !edge ? "shadow-[inset_0_0_0_1px_var(--border)]" : ""}`}
                            style={{
                              width: "var(--dot)",
                              height: "var(--dot)",
                              transition: reduced
                                ? "none"
                                : `color 220ms ${EASE} ${edge ? 90 : 0}ms, background-color 160ms`,
                            }}
                          >
                            {d.getDate()}
                          </span>
                        </button>
                      );
                    })}
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* The range as it stands, morphing while you pick, and the way out. */}
          <div className="flex items-center justify-between gap-3 border-t border-border py-2 pl-3.5 pr-2">
            <div className="min-w-0 leading-tight">
              <p className="truncate text-[12.5px] font-medium tabular-nums text-foreground">
                <TextMorph>{band ? label(band) : placeholder}</TextMorph>
              </p>
              <p
                className="mt-0.5 text-[11.5px] text-muted-foreground"
                aria-hidden="true"
              >
                <NumberRoll value={count} />{" "}
                <TextMorph>
                  {nights
                    ? count === 1
                      ? "night"
                      : "nights"
                    : count === 1
                      ? "day"
                      : "days"}
                </TextMorph>
              </p>
            </div>
            <div className="flex shrink-0 gap-1">
              <button
                type="button"
                onClick={() => request(false)}
                className={`cursor-pointer h-8 rounded-full px-3 text-[12.5px] font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={apply}
                disabled={!ready}
                className={`cursor-pointer disabled:cursor-default h-8 rounded-full bg-primary px-3.5 text-[12.5px] font-medium text-primary-foreground transition-opacity disabled:opacity-40 ${FOCUS}`}
              >
                Apply
              </button>
            </div>
          </div>
          <p className="sr-only" role="status">
            {announce}
          </p>
        </div>
      )}
    </div>
  );
}

"use client";

import * as React from "react";
import { Trash2 } from "lucide-react";
import { Boo, type BooMode } from "./boo-ghost";
import { HoldToConfirm, type HoldStatus } from "./hold-to-confirm";
import { Input } from "./input";
import { StatusButton, type ActionStatus } from "./status-button";
import { TextMorph } from "./text-morph";
import {
  EASE_OUT,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * DELETE WORKSPACE: its ghost climbs out as you type its name
 *
 *   safe     the workspace's tile sits on the lit stage
 *   type     each letter of its name you type brings Boo, its
 *            ghost, further up out of the tile while the tile
 *            loses its colour; a wrong letter and he shivers
 *            and sinks back to where the name still matches
 *   hold     with the name right, Delete arms; holding it, Boo
 *            waves and drifts up out of the stage over the hold,
 *            and drops back if you let go
 *   deleted  the tile is an empty dashed outline, and a moment
 *            later Boo peeks up over the edge; Restore (for
 *            graceDays) brings him diving back into his tile
 *
 * onDelete and onRestore are yours; nothing happens until the
 * whole name is typed and the hold completes.
 * ───────────────────────────────────────────────────────── */

export interface DeleteWorkspaceProps {
  /** The name to type, exactly. */
  name: string;
  /** Its logo; initials on `color` without one. */
  avatar?: string;
  color?: string;
  /** What's being deleted: workspace, project, account… */
  kind?: string;
  /** What goes with it, one short line each ("12 projects and their history"). */
  consequences?: string[];
  /** Delete it; throw to keep it and offer another hold. */
  onDelete: () => Promise<unknown>;
  /** Shows Restore after the delete. */
  onRestore?: () => Promise<unknown>;
  /** Days it can be restored in, for the line after the delete. */
  graceDays?: number;
  /** How long Delete has to be held, in ms. */
  holdMs?: number;
  className?: string;
}

const mix = (color: string, amount: number, into = "transparent") =>
  `color-mix(in oklab, ${color} ${amount}%, ${into})`;
const PF = "var(--primary-foreground)";
const CARD: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, var(--card), ${mix("var(--card)", 95, "var(--foreground)")})`,
  boxShadow: `0 0 0 1px var(--border), inset 0 1px 0 ${mix("var(--background)", 85)}`,
};
/* The one lit surface, with a faint spotlight on the tile: it's the thing everyone's looking at. */
const STAGE: React.CSSProperties = {
  backgroundColor: "var(--primary)",
  backgroundImage: [
    `radial-gradient(34% 46% at 50% 66%, ${mix(PF, 22)} 0%, transparent 100%)`,
    `radial-gradient(120% 90% at 0% 0%, ${mix(PF, 14)} 0%, transparent 55%)`,
    `linear-gradient(175deg, transparent 40%, ${mix("black", 24)} 100%)`,
  ].join(", "),
  boxShadow: `inset 0 1px 0 ${mix(PF, 36)}, inset 0 0 0 1px ${mix(PF, 12)}`,
};
const DANGER: React.CSSProperties = {
  background: "var(--color-red-600, oklch(0.58 0.22 27))",
  borderColor: "transparent",
  color: "white",
};
/* not armed yet: a quiet grey, not a faded version of the main colour */
const UNARMED: React.CSSProperties = {
  background: mix("var(--foreground)", 7),
  borderColor: "transparent",
  color: "var(--muted-foreground)",
};

const initials = (name: string) =>
  name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((w) => w[0]!.toUpperCase())
    .join("");

export function DeleteWorkspace({
  name,
  avatar,
  color = "var(--chart-1, var(--primary))",
  kind = "workspace",
  consequences,
  onDelete,
  onRestore,
  graceDays = 30,
  holdMs = 1500,
  className = "",
}: DeleteWorkspaceProps) {
  const reduced = useInteractionReducedMotion();
  const baseId = React.useId();
  const boo = React.useRef<{ shiver: () => void }>(null);
  const [typed, setTyped] = React.useState("");
  const [hold, setHold] = React.useState<HoldStatus>("idle");
  const [deleted, setDeleted] = React.useState(false);
  const [restore, setRestore] = React.useState<ActionStatus>("idle");
  const [back, setBack] = React.useState(false);
  // a new round after a restore starts the hold button afresh
  const [round, setRound] = React.useState(0);
  const timers = React.useRef<number[]>([]);
  React.useEffect(
    () => () => timers.current.forEach((t) => window.clearTimeout(t)),
    [],
  );
  const later = (fn: () => void, ms: number) =>
    timers.current.push(window.setTimeout(fn, reduced ? 0 : ms));

  // how much of the name is right so far: a wrong letter sends him back to where it still matches
  let matched = 0;
  while (
    matched < typed.length &&
    matched < name.length &&
    typed[matched] === name[matched]
  )
    matched++;
  const full = typed === name;
  const rise = name.length ? matched / name.length : 0;

  const mode: BooMode = back
    ? "back"
    : deleted || hold === "success"
      ? "gone"
      : hold === "holding" || hold === "pending"
        ? "hold"
        : "type";
  const mood = back
    ? `Welcome back, ${name}`
    : deleted
      ? `${name} is gone, mostly`
      : hold === "holding" || hold === "pending"
        ? `Goodbye, ${name}`
        : hold === "success"
          ? `${name} is gone`
          : hold === "error"
            ? `${name} is still here`
            : full
              ? `Last chance for ${name}`
              : matched > 0
                ? `${name} is fading`
                : `${name} is safe and sound`;

  const change = (next: string) => {
    let m = 0;
    while (m < next.length && m < name.length && next[m] === name[m]) m++;
    // a letter that doesn't belong: he shivers on his way back down
    if (next.length > typed.length && m < next.length) boo.current?.shiver();
    setTyped(next);
  };

  const doRestore = async () => {
    if (!onRestore || restore === "pending") return;
    setRestore("pending");
    try {
      await onRestore();
      setRestore("success");
      setBack(true);
      later(() => {
        setDeleted(false);
        setBack(false);
        setTyped("");
        setHold("idle");
        setRestore("idle");
        setRound((r) => r + 1);
      }, 1400);
    } catch {
      setRestore("error");
    }
  };

  const gone = deleted || back;
  const tile = (
    <div className="relative size-full">
      <div
        className="absolute inset-0 grid place-items-center overflow-clip rounded-[16px] text-[21px] font-semibold tracking-[-0.02em] text-white"
        style={{
          background: avatar ? undefined : color,
          boxShadow: `inset 0 1px 0 ${mix("white", 30)}, 0 0 0 1px ${mix("black", 12)}`,
          filter: `grayscale(${gone && !back ? 1 : rise * 0.95})`,
          opacity: deleted && !back ? 0 : 1 - rise * 0.35,
          transform: deleted && !back ? "scale(0.86)" : "none",
          transition: reduced
            ? "none"
            : `filter 380ms ${EASE_OUT}, opacity 380ms ${EASE_OUT}, transform 480ms ${EASE_OUT}`,
        }}
      >
        {avatar ? (
          <img src={avatar} alt="" className="size-full object-cover" />
        ) : (
          initials(name)
        )}
      </div>
      {/* where it was */}
      <div
        className="absolute inset-0 rounded-[16px] border-[1.5px] border-dashed"
        style={{
          borderColor: mix(PF, 55),
          opacity: deleted && !back ? 1 : 0,
          transition: reduced ? "none" : `opacity 380ms ${EASE_OUT} 120ms`,
        }}
      />
    </div>
  );

  return (
    <section
      aria-labelledby={`${baseId}-title`}
      className={`relative w-full max-w-[380px] rounded-[28px] p-2 text-card-foreground ${className}`}
      style={CARD}
    >
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 380px)" }}
      />
      <div className="@container w-full">
        <div
          className="relative overflow-clip rounded-[22px] text-primary-foreground"
          style={STAGE}
        >
          <Boo
            ref={boo}
            rise={rise}
            mode={mode}
            holdMs={holdMs}
            reduced={reduced}
            tile={tile}
          />
          <p className="absolute inset-x-0 bottom-2.5 z-10 text-center text-[12.5px] font-medium text-primary-foreground/85">
            <TextMorph>{mood}</TextMorph>
          </p>
        </div>

        {/* the confirm form and the after-delete panel trade places in one surface */}
        <div className="grid">
          <div
            className="col-start-1 row-start-1 grid"
            style={{
              gridTemplateRows: deleted ? "0fr" : "1fr",
              opacity: deleted ? 0 : 1,
              pointerEvents: deleted ? "none" : undefined,
              transition: reduced
                ? "none"
                : `grid-template-rows 460ms ${EASE_OUT}, opacity 220ms`,
            }}
          >
            <div className="min-w-0 overflow-clip" inert={deleted}>
              <div className="px-3 pb-2 pt-3">
                <h2
                  id={`${baseId}-title`}
                  className="text-[15px] font-medium tracking-[-0.01em]"
                >
                  Delete {kind}
                </h2>
                <p className="mt-0.5 text-[12.5px] text-muted-foreground">
                  This deletes{" "}
                  <span className="font-medium text-foreground">{name}</span>{" "}
                  and everything in it.
                </p>
                {consequences && consequences.length > 0 && (
                  <ul className="mt-2 grid gap-1 text-[12.5px] text-muted-foreground">
                    {consequences.map((c) => (
                      <li key={c} className="flex items-center gap-2">
                        <span className="size-1 shrink-0 rounded-full bg-red-500" />
                        {c}
                      </li>
                    ))}
                  </ul>
                )}
                <Input
                  className="mt-3"
                  label={
                    <>
                      Type{" "}
                      <span className="font-medium text-foreground">
                        {name}
                      </span>{" "}
                      to confirm
                    </>
                  }
                  value={typed}
                  onValueChange={change}
                  autoComplete="off"
                  spellCheck={false}
                  autoCapitalize="off"
                  disabled={
                    hold === "holding" ||
                    hold === "pending" ||
                    hold === "success"
                  }
                />
                <HoldToConfirm
                  key={round}
                  className="mt-3 w-full"
                  style={full ? DANGER : UNARMED}
                  icon={<Trash2 />}
                  duration={holdMs}
                  resetAfter={0}
                  disabled={!full}
                  labels={{
                    idle: `Hold to delete`,
                    holding: "Keep holding",
                    pending: "Deleting",
                    success: "Deleted",
                    error: "Hold to try again",
                  }}
                  onStatusChange={(s) => {
                    setHold(s);
                    if (s === "success") later(() => setDeleted(true), 900);
                  }}
                  onConfirm={async () => {
                    await onDelete();
                  }}
                />
              </div>
            </div>
          </div>

          <div
            className="col-start-1 row-start-1 grid"
            style={{
              gridTemplateRows: deleted ? "1fr" : "0fr",
              opacity: deleted ? 1 : 0,
              pointerEvents: deleted ? undefined : "none",
              transition: reduced
                ? "none"
                : `grid-template-rows 460ms ${EASE_OUT}, opacity 260ms 120ms`,
            }}
          >
            <div className="min-w-0 overflow-clip" inert={!deleted}>
              <div className="flex items-center gap-3 px-3 pb-2 pt-3">
                <div className="min-w-0 flex-1">
                  <p className="text-[15px] font-medium tracking-[-0.01em]">
                    {name} was deleted
                  </p>
                  <p className="mt-0.5 text-[12.5px] text-muted-foreground">
                    {onRestore
                      ? `You can restore it for ${graceDays} days.`
                      : "It’s gone for good."}
                  </p>
                </div>
                {onRestore && (
                  <StatusButton
                    variant="outline"
                    status={restore}
                    labels={{
                      idle: "Restore",
                      pending: "Restoring",
                      success: "Restored",
                      error: "Try again",
                    }}
                    onClick={doRestore}
                    className="shrink-0"
                  />
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
      <span className="sr-only" role="status">
        {deleted
          ? `${name} was deleted.`
          : full
            ? `Name matches. Hold Delete to confirm.`
            : ""}
      </span>
    </section>
  );
}

