  reduced,
}: {
  r: DnsRecord;
  index: number;
  reduced: boolean;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  const status = r.status ?? "pending";
  const was = React.useRef(status);
  // A record that just verified lights up for a moment.
