/** "Checking again in 0:42", rolling down; "Checking" while it asks. */
function Countdown({
  at,
  checking,
  reduced,
}: {
  at: number | null;
  checking: boolean;
  reduced: boolean;
}) {
  const [now, setNow] = React.useState(() => Date.now());
  const left = at === null ? 0 : Math.max(0, Math.ceil((at - now) / 1000));
  React.useEffect(() => {
    if (at === null || checking) return;
    const id = requestAnimationFrame(() => setNow(Date.now()));
    return () => cancelAnimationFrame(id);
  }, [at, checking]);
  React.useEffect(() => {
    if (at === null || checking || left <= 0) return;
    const timer = window.setTimeout(
      () => setNow(Date.now()),
      1000 - (Date.now() % 1000) + 10,
    );
    return () => window.clearTimeout(timer);
  }, [at, checking, left, now]);
  const counting = !checking && at !== null && left > 0;
  return (
    <span className="inline-flex items-center gap-1.5 whitespace-nowrap tabular-nums">
      <Swap
        show={checking ? "checking" : "waiting"}
        reduced={reduced}
        className="size-3"
        layers={{
          waiting: <Clock className="size-3" strokeWidth={2} />,
          checking: <Spinner on={checking} />,
        }}
      />
      <TextMorph>{checking ? "Checking DNS" : "Checking again in"}</TextMorph>
      <span
        aria-hidden="true"
        className="-ml-1.5 inline-grid"
        style={{
          gridTemplateColumns: counting ? "1fr" : "0fr",
          opacity: counting ? 1 : 0,
          transition: reduced
            ? "none"
            : `grid-template-columns 380ms ${EASE}, opacity 240ms ${EASE}`,
        }}
      >
        <span className="min-w-0 [clip-path:inset(-4px_0)]">
          <span className="inline-flex items-baseline pl-1.5">
            <NumberRoll value={Math.floor(left / 60)} direction="down" />:
            <NumberRoll
              value={left % 60}
              format={{ minimumIntegerDigits: 2 }}
              direction="down"
            />
          </span>
        </span>
      </span>
    </span>
  );
}

const STEPS = ["DNS records", "Certificate", "Live"];

function Rail({ state, reduced }: { state: DomainState; reduced: boolean }) {
  const total = state.records.length || 1;
  const found = state.records.filter((r) => r.status === "verified").length;
  const fill =
    state.status === "active"
      ? 1
      : state.status === "issuing"
        ? 0.5
        : (found / total) * 0.5;
  const reached = (i: number) =>
    i === 0
      ? found === total ||
        state.status === "issuing" ||
        state.status === "active"
      : state.status === "active";
  const current =
    state.status === "failed"
      ? -1
      : state.status === "active"
        ? -1
        : state.status === "issuing"
          ? 1
          : 0;
  return (
    <div className="px-1 pt-1" aria-hidden="true">
      <div className="relative mx-[9px] h-px bg-border">
        <span
          className={`absolute inset-0 origin-left ${state.status === "failed" ? "bg-red-500" : "bg-emerald-500"}`}
          style={{
            transform: `scaleX(${fill})`,
            transition: reduced ? "none" : `transform 760ms ${EASE}`,
          }}
        />
        {STEPS.map((_, i) => {
          const done = reached(i);
          return (
            <span
              key={i}
              className={`absolute top-1/2 grid size-[18px] -translate-x-1/2 -translate-y-1/2 place-items-center rounded-full bg-background shadow-[inset_0_0_0_1px_var(--border)] transition-colors duration-500 ${done ? "text-emerald-600 dark:text-emerald-400" : "text-muted-foreground"}`}
              style={{ left: `${i * 50}%` }}
            >
              {current === i && !done ? (
                <Spinner on />
              ) : (
                <Check drawn={done} reduced={reduced} className="size-3" />
              )}
            </span>
          );
        })}
      </div>
      <div className="mt-3.5 grid grid-cols-3 text-[11px] text-muted-foreground">
        {STEPS.map((s, i) => (
          <span
            key={s}
            className={`${i === 0 ? "text-left" : i === 1 ? "text-center" : "text-right"} ${reached(i) ? "text-foreground" : ""} transition-colors duration-500`}
          >
            {s}
          </span>
        ))}
      </div>
    </div>
  );
}

export function DomainConnect({
  value,
  defaultValue = null,
  onValueChange,
  onAdd,
  check,
  onRemove,
  schedule = SCHEDULE,
  title = "Custom domain",
  description = "Serve your workspace from an address you own.",
  placeholder = "app.yourcompany.com",
  className = "",
  ...props
}: DomainConnectProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const [inner, setInner] = React.useState<DomainState | null>(defaultValue);
  const state = value !== undefined ? value : inner;
  const [typed, setTyped] = React.useState("");
  const [adding, setAdding] = React.useState<ActionStatus>("idle");
  const [addError, setAddError] = React.useState<string | null>(null);
  const [checking, setChecking] = React.useState(false);
  const [nextAt, setNextAt] = React.useState<number | null>(null);
  const [showRecords, setShowRecords] = React.useState(false);
  const [announce, setAnnounce] = React.useState("");
  const inputRef = React.useRef<HTMLInputElement>(null);
  const fieldRef = React.useRef<HTMLDivElement>(null);
  const headRef = React.useRef<HTMLParagraphElement>(null);
  const flight = React.useRef<DOMRect | null>(null);
  const attempt = React.useRef(0);
  const ctrl = React.useRef<AbortController | null>(null);
  const latest = React.useRef(state);
  React.useLayoutEffect(() => {
    latest.current = state;
  });

  const commit = (next: DomainState | null) => {
    if (value === undefined) setInner(next);
    onValueChange?.(next);
  };

  const waiting = Boolean(
    state && (state.status === "pending" || state.status === "issuing"),
  );

  const runCheck = React.useCallback(async () => {
    const cur = latest.current;
    if (!cur) return;
    ctrl.current?.abort();
    const c = new AbortController();
    ctrl.current = c;
    setChecking(true);
    setNextAt(null);
    try {
      const next = await check(cur.domain, { signal: c.signal });
      if (c.signal.aborted || latest.current?.domain !== cur.domain) return;
      const before = cur.records.filter((r) => r.status === "verified").length;
      const after = next.records.filter((r) => r.status === "verified").length;
      if (next.status !== cur.status)
        setAnnounce(
          next.status === "active"
            ? `${next.domain} is live.`
            : next.status === "issuing"
              ? "DNS records found. Issuing a certificate."
              : next.status === "failed"
                ? (next.message ?? "The domain couldn't be connected.")
                : "",
        );
      else if (after > before)
        setAnnounce(`${after} of ${next.records.length} records found.`);
      commit(next);
      attempt.current++;
    } catch {
      if (c.signal.aborted) return;
      attempt.current++;
    } finally {
      if (!c.signal.aborted) setChecking(false);
    }
  }, [check, onValueChange, value]);

  // The next automatic check: further off each time, never while the tab is hidden.
  React.useEffect(() => {
    if (!waiting || checking) return;
    const wait =
      schedule[Math.min(attempt.current, schedule.length - 1)] * 1000;
    const at = Date.now() + wait;
    setNextAt(at);
    let onShow: (() => void) | null = null;
    const timer = window.setTimeout(() => {
      if (!document.hidden) return runCheck();
      // Hidden tab: wait until it's looked at again.
      onShow = () => {
        document.removeEventListener("visibilitychange", onShow!);
        onShow = null;
        runCheck();
      };
      document.addEventListener("visibilitychange", onShow);
    }, wait);
    return () => {
      window.clearTimeout(timer);
      if (onShow) document.removeEventListener("visibilitychange", onShow);
    };
  }, [waiting, checking, schedule, runCheck, state?.domain, state?.status]);

  React.useEffect(() => () => ctrl.current?.abort(), []);

  // The address lifts out of the field into the heading.
  React.useLayoutEffect(() => {
    const from = flight.current;
    const head = headRef.current;
    if (!from || !head || !state || reduced) return;
    flight.current = null;
    const to = head.getBoundingClientRect();
    head.animate(
      [
        {
          transform: `translate(${from.left - to.left}px, ${from.top + from.height / 2 - (to.top + to.height / 2)}px)`,
        },
        { transform: "none" },
      ],
      { duration: 620, easing: EASE },
    );
  }, [state, reduced]);

  const add = async () => {
    if (adding === "pending") return;
    const host = toHost(typed);
    if (!HOST.test(host)) {
      setAddError(
        host
          ? `“${host}” isn't a domain. Try something like ${placeholder}.`
          : "Enter the domain you want to use.",
      );
      if (!reduced)
        fieldRef.current?.animate(SHAKE, { duration: 380, easing: "ease-out" });
      inputRef.current?.focus();
      return;
    }
    if (host !== typed) setTyped(host);
    setAdding("pending");
    setAddError(null);
    try {
      const next = await onAdd(host);
      const input = inputRef.current;
      if (input) {
        const r = input.getBoundingClientRect();
        const pad = parseFloat(getComputedStyle(input).paddingLeft) || 0;
        flight.current = new DOMRect(r.left + pad, r.top, r.width, r.height);
      }
      attempt.current = 0;
      setShowRecords(false);
      commit(next);
      setAdding("idle");
      setTyped("");
      setAnnounce(
        `${next.domain} added. Add the records below at your DNS provider.`,
      );
    } catch (e) {
      setAdding("error");
      setAddError(message(e, "That domain couldn't be added. Try again."));
    }
  };

  const remove = async () => {
    if (!state) return;
    await onRemove?.(state.domain);
    ctrl.current?.abort();
    setChecking(false);
    setNextAt(null);
    setAnnounce(`${state.domain} removed.`);
    window.setTimeout(() => {
      commit(null);
      requestAnimationFrame(() =>
        inputRef.current?.focus({ preventScroll: true }),
      );
    }, 500);
  };

  const live = state?.status === "active";
  const failed = state?.status === "failed";
  const found = state
    ? state.records.filter((r) => r.status === "verified").length
    : 0;
  const pill = !state
    ? ""
    : live
      ? "Live"
      : failed
        ? "Not connected"
        : state.status === "issuing"
          ? "Issuing certificate"
          : found
            ? `${found} of ${state.records.length} records found`
            : "Waiting for DNS";

  return (
    <div
      className={`@container w-full rounded-[22px] border border-border bg-background text-foreground ${className}`}
      {...props}
    >
      <div className="px-4 pt-4 @md:px-5 @md:pt-5">
        <p className="text-[14px] font-medium tracking-[-0.01em]">{title}</p>
        <p className="mt-0.5 text-[12px] text-muted-foreground">
          {description}
        </p>
      </div>

      {/* The field: only while there's no domain. */}
      <Fold open={!state} reduced={reduced}>
        <form
          noValidate
          className="px-4 pt-3.5 pb-4 @md:px-5 @md:pb-5"
          onSubmit={(e) => {
            e.preventDefault();
            add();
          }}
        >
          <label htmlFor={`${id}-domain`} className="sr-only">
            Domain
          </label>
          <div className="flex flex-col gap-2 @sm:flex-row">
            <div
              ref={fieldRef}
              // Grows sideways only beside the button; stacked on a narrow card, flex-1 would override its height.
              className={`flex h-9 min-w-0 shrink-0 items-center rounded-full px-3.5 transition-shadow @sm:flex-1 duration-200 ${addError ? "shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_45%,transparent)]" : "shadow-[inset_0_0_0_1px_var(--border)] focus-within:shadow-[inset_0_0_0_1px_var(--ring)]"}`}
            >
              <Globe
                className="mr-2 size-3.5 shrink-0 text-muted-foreground"
                strokeWidth={1.75}
                aria-hidden="true"
              />
              <input
                ref={inputRef}
                id={`${id}-domain`}
                value={typed}
                onChange={(e) => {
                  setTyped(e.target.value);
                  setAddError(null);
                  if (adding === "error") setAdding("idle");
                }}
                onBlur={() => typed && setTyped(toHost(typed))}
                onPaste={(e) => {
                  const text = e.clipboardData.getData("text");
                  if (!/[:/]/.test(text)) return;
                  e.preventDefault();
                  setTyped(toHost(text));
                }}
                readOnly={adding === "pending"}
                placeholder={placeholder}
                inputMode="url"
                autoComplete="off"
                autoCapitalize="off"
                spellCheck={false}
                aria-invalid={Boolean(addError) || undefined}
                aria-describedby={addError ? `${id}-error` : undefined}
                className="h-full min-w-0 flex-1 bg-transparent text-[16px] text-foreground outline-none placeholder:text-muted-foreground/70 [@media(pointer:fine)]:text-[13.5px]"
              />
            </div>
            <StatusButton
              type="submit"
              status={adding}
              labels={{
                idle: "Connect",
                pending: "Connecting",
                error: "Try again",
              }}
            />
          </div>
          <Fold open={Boolean(addError)} reduced={reduced}>
            <p
              id={`${id}-error`}
              className="px-1 pt-2 text-[12px] text-red-600 dark:text-red-400"
            >
              {addError}
            </p>
          </Fold>
        </form>
      </Fold>

      {/* The domain: heading, rail, records, and the next check. */}
      <Fold open={Boolean(state)} reduced={reduced}>
        {state && (
          <div className="px-4 pt-3.5 pb-4 @md:px-5 @md:pb-5">
            <div className="flex items-center gap-3">
              <div className="min-w-0 flex-1">
                <p
                  ref={headRef}
                  className="truncate text-[15px] font-medium tracking-[-0.01em]"
                >
                  {live ? (
                    <a
                      href={`https://${state.domain}`}
                      target="_blank"
                      rel="noopener noreferrer"
                      className={`inline-flex items-center gap-1 underline-offset-4 hover:underline ${FOCUS}`}
                    >
                      {state.domain}
                      <ArrowUpRight
                        className="size-3.5 text-muted-foreground"
                        strokeWidth={2}
                        aria-hidden="true"
                      />
                    </a>
                  ) : (
                    state.domain
                  )}
                </p>
                <p
                  className={`mt-0.5 flex items-center gap-1.5 text-[12px] transition-colors duration-500 ${live ? "text-emerald-600 dark:text-emerald-400" : failed ? "text-red-600 dark:text-red-400" : "text-amber-700 dark:text-amber-400"}`}
                >
                  <span
                    className="relative grid size-2 place-items-center"
                    aria-hidden="true"
                  >
                    <span className="size-1.5 rounded-full bg-current" />
                    {waiting && !reduced && (
                      <span className="absolute inset-0 rounded-full bg-current opacity-40 motion-safe:animate-[ui-ping_1.6s_ease-out_infinite]" />
                    )}
                  </span>
                  <TextMorph>{pill}</TextMorph>
                </p>
              </div>
              {onRemove && (
                <ConfirmAction
                  icon={<Trash2 strokeWidth={1.75} />}
                  label={`Remove ${state.domain}`}
                  labels={{
                    idle: "Remove",
                    pending: "Removing",
                    success: "Removed",
                    error: "Try again",
                  }}
                  onConfirm={remove}
                />
              )}
            </div>

            <div className="mt-4">
              <Rail state={state} reduced={reduced} />
            </div>

            <Fold open={!live || showRecords} reduced={reduced}>
              <div className="pt-4">
                <p className="text-[12px] text-muted-foreground">
                  {live
                    ? "These records keep it connected."
                    : "Add these at your DNS provider. Changes can take a few minutes to show."}
                </p>
                <div
                  role="table"
                  aria-label={`DNS records for ${state.domain}`}
                  className="mt-2 rounded-[14px] p-1 shadow-[inset_0_0_0_1px_var(--border)]"
                >
                  {state.records.map((r, i) => (
                    <RecordRow
                      key={`${r.type}-${r.name}-${r.value}`}
                      r={r}
                      index={i}
                      reduced={reduced}
                    />
                  ))}
                </div>
              </div>
            </Fold>

            <Fold open={Boolean(state.message)} reduced={reduced}>
              <p
                className={`pt-3 text-[12px] ${failed ? "text-red-600 dark:text-red-400" : "text-muted-foreground"}`}
              >
                {state.message}
              </p>
            </Fold>

            <div className="mt-3.5 flex min-h-7 items-center justify-between gap-3 text-[12px] text-muted-foreground">
              {live ? (
                <button
                  type="button"
                  aria-expanded={showRecords}
                  onClick={() => setShowRecords((s) => !s)}
                  className={`-ml-2 h-7 cursor-pointer rounded-full px-2 font-medium transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
                >
                  <TextMorph>
                    {showRecords ? "Hide records" : "Show records"}
                  </TextMorph>
                </button>
              ) : failed ? (
                <span className="text-red-600 dark:text-red-400">
                  Fix the records, then check again.
                </span>
              ) : (
                <Countdown at={nextAt} checking={checking} reduced={reduced} />
              )}
              {!live && (
                <button
                  type="button"
                  onClick={() => {
                    attempt.current = 0;
                    runCheck();
                  }}
                  aria-disabled={checking || undefined}
                  className={`h-7 shrink-0 cursor-pointer rounded-full px-3 font-medium text-foreground shadow-[inset_0_0_0_1px_var(--border)] transition-[background-color,opacity] hover:bg-accent aria-disabled:cursor-default aria-disabled:opacity-50 ${FOCUS}`}
                >
                  Check now
                </button>
              )}
            </div>
          </div>
        )}
      </Fold>

      <span className="sr-only" role="status">
        {announce}
      </span>
    </div>
  );
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * DONUT CHART: parts of a whole as a ring or a half-ring gauge
 *
 *   arrive    the first time it's on screen each slice draws
 *             round from where it starts, one after another,
 *             and the total rolls up from zero
 *   point     point at a slice (or its legend row) and it
 *             thickens while the others step back; the centre's
 *             label morphs to the slice's name and the figure
 *             rolls from the total to its value, with its share
 *             opening underneath
 *   toggle    a legend row hides or shows its slice: the others
 *             slide round to close the gap and every share and
 *             the total roll to the new sums
 *   data      new numbers (another month) slide every slice to
 *             its new place instead of redrawing
 *   max       given a max, the slices fill only their share of
 *             it and the rest of the track stays empty: budget
 *             spent, storage used
 *
 * Each slice is one circle's stroke: its length and where it
 * starts are stroke-dasharray and stroke-dashoffset, so a CSS
 * transition carries every change. The legend is the accessible
 * part (buttons that show and hide slices); the ring is drawn
 * for the eye only.
 * ───────────────────────────────────────────────────────── */

export interface DonutSlice {
  id: string;
  label: string;
  value: number;
  /** Any CSS colour; slices without one take --chart-1 to --chart-5 in order. */
  color?: string;
}

export interface DonutChartProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "title"
> {
  data: DonutSlice[];
  /** A full ring, or a half-ring gauge read from left to right. */
  variant?: "donut" | "gauge";
  /** What a full ring stands for. With it the slices fill only their share and the rest of the track stays empty. */
  max?: number;
  title?: React.ReactNode;
  description?: React.ReactNode;
  /** Beside the title, e.g. a period switch. */
  action?: React.ReactNode;
  /** Above the figure in the centre while nothing is pointed at. */
  centerLabel?: string;
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  /** Ring thickness in px, at the ring's full size. */
  thickness?: number;
  /** Ids of the slices taken out, controlled or not. */
  hiddenSlices?: string[];
  defaultHiddenSlices?: string[];
  onHiddenSlicesChange?: (hidden: string[]) => void;
  /** Show the legend (which also shows and hides slices). */
  legend?: boolean;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const PALETTE = [
  "var(--chart-1, var(--primary))",
  "var(--chart-2, #e8743b)",
  "var(--chart-3, #1baf7a)",
  "var(--chart-4, #8b6fe8)",
  "var(--chart-5, #e0a21b)",
];
const NONE: string[] = [];
const SIZE = 200;
/** How much a pointed-at slice thickens, in px; the ring leaves room for it. */
const GROW = 5;
/** The gap between two slices, in px along the ring. */
const GAP = 3.5;

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );
const subscribeNothing = () => () => {};
/** Text in the visitor's locale waits for hydration, so the server's en-US render and the first client render match. */
const useHydrated = () =>
  React.useSyncExternalStore(
    subscribeNothing,
    () => true,
    () => false,
  );

/** Past the fifth slice, colours repeat a step darker so neighbours never match. */
const colorOf = (slice: DonutSlice, i: number) =>
  slice.color ??
  (i < PALETTE.length
    ? PALETTE[i]
    : `color-mix(in oklab, ${PALETTE[i % PALETTE.length]} 70%, var(--foreground))`);

export function DonutChart({
  data,
  variant = "donut",
  max,
  title,
  description,
  action,
  centerLabel = "Total",
  format,
  locales,
  thickness = 16,
  hiddenSlices,
  defaultHiddenSlices = NONE,
  onHiddenSlicesChange,
  legend = true,
  className = "",
  ...props
}: DonutChartProps) {
  const reduced = useReducedMotion();
  const gauge = variant === "gauge";
  const [ownHidden, setOwnHidden] = React.useState(defaultHiddenSlices);
  const off = hiddenSlices ?? ownHidden;
  const [active, setActive] = React.useState<string | null>(null);
  const [visible, setVisible] = React.useState(false);
  const [settled, setSettled] = React.useState(false);
  const hydrated = useHydrated();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const ringRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          observer.disconnect();
        }
      },
      { rootMargin: "0px 0px -10% 0px" },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  // Slices draw in one after another the first time only; after that every change moves them together.
  React.useEffect(() => {
    if (!visible) return;
    const timer = window.setTimeout(
      () => setSettled(true),
      900 + data.length * 90,
    );
    return () => window.clearTimeout(timer);
  }, [visible, data.length]);

  // A tap on a slice holds it; a tap anywhere else lets go.
  React.useEffect(() => {
    if (active === null) return;
    const onDown = (e: PointerEvent) => {
      if (!ringRef.current?.contains(e.target as Node)) setActive(null);
    };
    document.addEventListener("pointerdown", onDown);
    return () => document.removeEventListener("pointerdown", onDown);
  }, [active]);

  const toggle = (id: string) => {
    const shown = data.filter((s) => !off.includes(s.id)).length;
    const next = off.includes(id)
      ? off.filter((x) => x !== id)
      : shown > 1
        ? [...off, id]
        : off;
    if (next === off) return;
    if (hiddenSlices === undefined) setOwnHidden(next);
    onHiddenSlicesChange?.(next);
  };

  // Geometry: one circle, the slices laid along its stroke.
  const stroke = thickness;
  const r = SIZE / 2 - (stroke + GROW) / 2 - 1;
  const circumference = 2 * Math.PI * r;
  const span = gauge ? circumference / 2 : circumference;
  const height = gauge ? SIZE / 2 + (stroke + GROW) / 2 + 1 : SIZE;
  const centre = SIZE / 2;

  const slices = data.map((s, i) => ({
    ...s,
    color: colorOf(s, i),
    shown: !off.includes(s.id),
    amount: Math.max(0, s.value),
  }));
  const total = slices.reduce((sum, s) => sum + (s.shown ? s.amount : 0), 0);
  const fill = max && max > 0 ? Math.min(1, total / max) : 1;
  const shownCount = slices.filter((s) => s.shown && s.amount > 0).length;
  const whole = !gauge && fill >= 1 && shownCount === 1;

  const shares = slices.map((s) =>
    s.shown && total > 0 ? s.amount / total : 0,
  );
  const starts: number[] = [];
  for (let i = 0, run = 0; i < shares.length; i++) {
    starts.push(run);
    run += shares[i] * fill * span;
  }
  const arcs = slices.map((s, i) => {
    const share = shares[i];
    const length = share * fill * span;
    const start = starts[i];
    // Round caps reach past each end by half the stroke: shorten the dash so the gaps stay GAP wide.
    const drawn =
      whole && share > 0 ? circumference : Math.max(0, length - GAP - stroke);
    const at = whole
      ? 0
      : start +
        (GAP + stroke) / 2 +
        (length > 0 && length < GAP + stroke ? (length - GAP - stroke) / 2 : 0);
    return {
      ...s,
      share,
      drawn: visible ? drawn : 0,
      at,
      on: visible && share > 0,
      delay: settled ? 0 : i * 90,
    };
  });

  const current = arcs.find((a) => a.id === active && a.shown) ?? null;
  const fmt = (n: number) =>
    new Intl.NumberFormat(
      hydrated ? locales : (locales ?? "en-US"),
      format,
    ).format(n);
  const trackLength = gauge ? span - stroke : circumference;
  const turn = gauge ? 180 : -90;
  const transitionFor = (delay: number) =>
    reduced
      ? "none"
      : `stroke-dasharray 900ms ${EASE} ${delay}ms, stroke-dashoffset 900ms ${EASE} ${delay}ms, stroke-width 320ms ${EASE}, opacity 300ms ${EASE}`;
  const point = (id: string | null) => setActive(id);

  const figureSize = gauge
    ? "text-[26px] @md:text-[30px]"
    : "text-[24px] @md:text-[28px]";

  return (
    <div
      ref={rootRef}
      className={`w-full rounded-[22px] bg-background shadow-[0_0_0_1px_var(--border)] ${className}`}
      {...props}
    >
      {/* Its natural width where the parent sizes to its content (a centred flex column), without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 520px)" }}
      />
      <div className="@container w-full">
        <div className="p-4 @md:p-5">
          {(title || description || action) && (
            <div className="mb-4 flex items-start justify-between gap-3">
              <div className="min-w-0">
                {title && (
                  <p className="text-[13.5px] font-medium text-foreground @md:text-[14px]">
                    {title}
                  </p>
                )}
                {description && (
                  <p className="mt-0.5 text-[12px] text-muted-foreground @md:text-[12.5px]">
                    {description}
                  </p>
                )}
              </div>
              {action && <div className="shrink-0">{action}</div>}
            </div>
          )}

          <div
            className={`flex flex-col items-center gap-4 ${legend && !gauge ? "@lg:flex-row @lg:items-center @lg:gap-6" : ""}`}
          >
            <div
              ref={ringRef}
              className={`relative shrink-0 ${gauge ? "w-[220px] @md:w-[236px]" : "w-[176px] @md:w-[196px]"}`}
              onPointerLeave={(e) => e.pointerType === "mouse" && point(null)}
            >
              <svg
                viewBox={`0 0 ${SIZE} ${height}`}
                className="block w-full overflow-visible"
                aria-hidden="true"
              >
                <circle
                  cx={centre}
                  cy={centre}
                  r={r}
                  fill="none"
                  stroke="color-mix(in oklab, var(--foreground) 7%, transparent)"
                  strokeWidth={stroke}
                  strokeLinecap={gauge ? "round" : "butt"}
                  strokeDasharray={`${trackLength} ${circumference}`}
                  strokeDashoffset={gauge ? -stroke / 2 : 0}
                  transform={`rotate(${turn} ${centre} ${centre})`}
                />
                {arcs.map((a) => {
                  const dim = current !== null && current.id !== a.id;
                  const common = {
                    cx: centre,
                    cy: centre,
                    r,
                    fill: "none",
                    strokeLinecap: "round" as const,
                    strokeDasharray: `${a.drawn} ${circumference}`,
                    strokeDashoffset: -a.at,
                    transform: `rotate(${turn} ${centre} ${centre})`,
                  };
                  return (
                    <g key={a.id}>
                      <circle
                        {...common}
                        stroke={a.color}
                        strokeWidth={
                          current?.id === a.id ? stroke + GROW : stroke
                        }
                        style={{
                          opacity: a.on ? (dim ? 0.3 : 1) : 0,
                          transition: transitionFor(a.delay),
                        }}
                      />
                      {/* A wider, invisible copy takes the pointer, so thin slices are easy to hit. */}
                      <circle
                        {...common}
                        stroke="transparent"
                        strokeWidth={stroke + 14}
                        pointerEvents={a.on ? "stroke" : "none"}
                        className="cursor-pointer"
                        onPointerEnter={(e) =>
                          e.pointerType === "mouse" && point(a.id)
                        }
                        onClick={() => point(active === a.id ? null : a.id)}
                      />
                    </g>
                  );
                })}
              </svg>

              {/* The centre: the total, or the slice being pointed at. */}
              <div
                className={`pointer-events-none absolute inset-x-0 flex flex-col items-center text-center ${gauge ? "bottom-0" : "inset-y-0 justify-center"}`}
              >
                <span className="max-w-[70%] truncate text-[11.5px] text-muted-foreground @md:text-[12px]">
                  <TextMorph>
                    {total === 0
                      ? "No data"
                      : current
                        ? current.label
                        : centerLabel}
                  </TextMorph>
                </span>
                <span
                  className={`font-semibold leading-tight tracking-[-0.03em] text-foreground tabular-nums ${figureSize}`}
                >
                  <NumberRoll
                    value={visible ? (current ? current.amount : total) : 0}
                    format={format}
                    locales={locales}
                    duration={900}
                  />
                </span>
                <span
                  className="grid text-[11.5px] text-muted-foreground tabular-nums transition-[grid-template-rows,opacity] duration-300 @md:text-[12px]"
                  style={{
                    gridTemplateRows: current || max ? "1fr" : "0fr",
                    opacity: current || max ? 1 : 0,
                    transitionTimingFunction: EASE,
                  }}
                >
                  <span className="min-h-0 overflow-hidden">
                    {current ? (
                      <NumberRoll
                        value={current.share}
                        format={{ style: "percent" }}
                        duration={700}
                      />
                    ) : max ? (
                      <>
                        of{" "}
                        <NumberRoll
                          value={max}
                          format={format}
                          locales={locales}
                          duration={900}
                        />
                      </>
                    ) : (
                      " "
                    )}
                  </span>
                </span>
              </div>
            </div>

            {legend && (
              <ul className="w-full min-w-0 flex-1" aria-label="Slices">
                {arcs.map((a) => (
                  <li key={a.id}>
                    <button
                      type="button"
                      aria-pressed={a.shown}
                      aria-label={`${a.label}: ${fmt(a.amount)}${a.shown ? `, ${Math.round(a.share * 100)}%` : ", hidden"}`}
                      onClick={() => toggle(a.id)}
                      onPointerEnter={(e) =>
                        e.pointerType === "mouse" && point(a.id)
                      }
                      onPointerLeave={(e) =>
                        e.pointerType === "mouse" && point(null)
                      }
                      onFocus={() => point(a.id)}
                      onBlur={() => point(null)}
                      className={`flex h-9 w-full cursor-pointer items-center gap-2.5 rounded-[10px] px-2 text-left text-[12.5px] transition-[background-color,opacity] duration-200 hover:bg-accent @md:text-[13px] ${FOCUS}`}
                      style={{
                        opacity: a.shown
                          ? current && current.id !== a.id
                            ? 0.55
                            : 1
                          : 0.45,
                      }}
                    >
                      <span
                        aria-hidden="true"
                        className="size-2.5 shrink-0 rounded-full transition-[background-color,box-shadow] duration-300"
                        style={{
                          background: a.shown ? a.color : "transparent",
                          boxShadow: `inset 0 0 0 1.5px ${a.color}`,
                        }}
                      />
                      <span
                        className={`min-w-0 flex-1 truncate ${a.shown ? "text-foreground" : "text-muted-foreground line-through decoration-muted-foreground/60"}`}
                      >
                        {a.label}
                      </span>
                      <span className="tabular-nums text-foreground">
                        <NumberRoll
                          value={visible ? a.amount : 0}
                          format={format}
                          locales={locales}
                          duration={900}
                        />
                      </span>
                      <span className="w-10 text-right text-[11.5px] tabular-nums text-muted-foreground @md:text-[12px]">
                        <NumberRoll
                          value={visible ? a.share : 0}
                          format={{ style: "percent" }}
                          duration={900}
                        />
                      </span>
                    </button>
                  </li>
                ))}
              </ul>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import {
  File as FileIcon,
  FileImage,
  FileText,
  RotateCcw,
  X,
} from "lucide-react";
import type { DropZoneFile } from "./drop-zone-types";
import { formatBytes } from "./drop-zone-utils";
import { DropZoneStatusMark } from "./drop-zone-status";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";
import { INTERACTION_FOCUS } from "./imported-ui-interaction-motion";

const action = `flex size-8 shrink-0 cursor-pointer items-center justify-center rounded-full text-muted-foreground transition-colors hover:bg-muted hover:text-foreground disabled:cursor-default disabled:opacity-40 motion-reduce:transition-none ${INTERACTION_FOCUS}`;

export function DropZoneFileRow({
  row,
  disabled,
  onRemove,
  onRetry,
}: {
  row: DropZoneFile;
  disabled: boolean;
  onRemove: () => void;
  onRetry: () => void;
}) {
  const { file, status, progress, error } = row;
  const Icon = file.type.startsWith("image/")
    ? FileImage
    : file.type === "application/pdf" || file.type.startsWith("text/")
      ? FileText
      : FileIcon;
  const uploading = status === "uploading";
  const errorId = `${row.id}-error`;

  return (
    <li
      className={`relative min-w-0 border-b ${status === "error" ? "border-destructive" : "border-border"}`}
      aria-describedby={error ? errorId : undefined}
    >
      <div className="flex h-11 min-w-0 items-center gap-2 sm:gap-3">
        <span className="flex min-w-0 flex-1 items-center gap-2.5 text-[13px]">
          <Icon
            className="size-4 shrink-0 text-muted-foreground"
            strokeWidth={1.75}
            aria-hidden="true"
          />
          <span className="truncate" title={file.name}>
            {file.name}
          </span>
        </span>
        <span className="flex shrink-0 items-center gap-1 text-[12px] tabular-nums text-muted-foreground">
          <span
            className={`whitespace-nowrap ${status === "error" ? "text-red-600 dark:text-red-400" : ""}`}
          >
            {status === "error" ? (
              <TextMorph>Failed</TextMorph>
            ) : (
              <>
                {formatBytes(file.size)}
                {uploading && (
                  <span className="ml-1">
                    <span aria-hidden="true">· </span>
                    <NumberRoll
                      value={Math.floor(progress * 100)}
                      suffix="%"
                      duration={400}
                    />
                  </span>
                )}
              </>
            )}
          </span>
          <DropZoneStatusMark status={status} progress={progress} />
          <span className="sr-only">
            {status === "done"
              ? "Uploaded"
              : status === "ready"
                ? "Ready"
                : uploading
                  ? "Uploading"
                  : "Upload failed"}
          </span>
          {status === "error" && (
            <button
              type="button"
              aria-label={`Retry upload of ${file.name}`}
              title="Retry upload"
              disabled={disabled}
              onClick={onRetry}
              className={action}
            >
              <RotateCcw
                className="size-3.5"
                strokeWidth={1.75}
                aria-hidden="true"
              />
            </button>
          )}
          <button
            type="button"
            aria-label={`${uploading ? "Cancel upload of" : "Remove"} ${file.name}`}
            title={uploading ? "Cancel upload" : "Remove file"}
            disabled={disabled}
            onClick={onRemove}
            className={action}
          >
            <X className="size-3.5" strokeWidth={1.75} aria-hidden="true" />
          </button>
        </span>
      </div>
      {error && (
        <p
          id={errorId}
          className="pb-2.5 pl-[26px] pr-1 text-[11.5px] leading-relaxed text-red-600 [overflow-wrap:anywhere] dark:text-red-400"
        >
          {error}
        </p>
      )}
      {uploading && (
        <span
          role="progressbar"
          aria-label={`Upload progress for ${file.name}`}
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={Math.floor(progress * 100)}
          className="pointer-events-none absolute inset-x-0 -bottom-px h-px"
        >
          <span
            className="block h-full origin-left bg-primary transition-transform duration-200 motion-reduce:transition-none"
            style={{ transform: `scaleX(${progress})` }}
          />
        </span>
      )}
    </li>
  );
}

"use client";

/* ─────────────────────────────────────────────────────────
 * DROP ZONE: the border reaches for the file
 *
 *   armed     drag files anywhere over the page and the line
 *             breathes out a pixel and takes the accent
 *   reach     bring them near and the nearest stretch of line
 *             bends out to meet them; the arrow turns to watch.
 *             Close to the edge the bulge reaches past the
 *             file, so it is held before it crosses
 *   over      inside, the line lets go with a wobble, the zone
 *             swells, and the label says what you're holding
 *   drop      the border gulps and rings out from the drop
 *             point; files appear directly as attachment cards
 *   upload    Attachment shows ready, uploading,
 *             processing, failed and complete states
 *   refuse    a type the zone can't take makes the line recoil
 *             and turns it red; a refused drop is pushed back
 *             out where it landed, and the label says why
 *
 * The zone is a real button: Enter or Space browses, paste
 * works while it has focus, and every result is announced.
 * Your own drags (a file from a sidebar, say) drive it too,
 * through the handle: drag, cancel, drop.
 * ───────────────────────────────────────────────────────── */

import * as React from "react";
import { ArrowUp, X } from "lucide-react";
import {
  MembraneAttachment,
  formatBytes,
  type MembraneAttachmentStatus,
} from "./membrane-attachment";
export { MembraneAttachment, formatBytes } from "./membrane-attachment";
import { TextMorph } from "./text-morph";
import {
  EASE_OUT,
  INTERACTION_FOCUS,
  interactionIcon,
  useInteractionReducedMotion,
} from "./ui-interaction-motion";
import { useMembrane } from "./use-membrane";

export type DropZoneMembraneStatus = MembraneAttachmentStatus;

export interface DropZoneMembraneFile {
  id: string;
  file: File;
  status: DropZoneMembraneStatus;
  /** 0 to 1. */
  progress: number;
  error?: string;
}

export type DropZoneMembraneUpload = (
  file: File,
  context: {
    progress: (fraction: number) => void;
    processing: () => void;
    signal: AbortSignal;
  },
) => void | Promise<void>;

export interface DropZoneMembraneHandle {
  /** Something your app is dragging (not a file from the system) is at these client coordinates. Returns whether a drop there would land. */
  drag: (clientX: number, clientY: number, types?: string[]) => boolean;
  /** Your drag ended without a drop. */
  cancel: () => void;
  /** Drop files as if from the system, at client coordinates or the zone's centre. */
  drop: (files: File[], at?: { x: number; y: number }) => void;
  /** Open the file picker. */
  browse: () => void;
}

export interface DropZoneMembraneProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onDrop" | "title"
> {
  /** Uploads one file: report progress, honour the signal, resolve when done or throw to show an error with Retry. */
  onUpload?: DropZoneMembraneUpload;
  /** Start uploads on selection. False exposes an Upload action on each ready file. */
  autoUpload?: boolean;
  /** The files currently in the list, after every add and remove. */
  onFilesChange?: (files: File[]) => void;
  /** Like an input's accept: MIME types, wildcards and extensions, e.g. "image/*,.pdf". */
  accept?: string;
  /** Largest file in bytes. */
  maxSize?: number;
  maxFiles?: number;
  /** One file at a time: a new drop replaces it. */
  multiple?: boolean;
  /** The resting label. */
  title?: string;
  /** File requirements in the tray footer, e.g. "PNG, JPG or PDF, up to 10 MB". */
  hint?: string;
  disabled?: boolean;
  ref?: React.Ref<DropZoneMembraneHandle>;
}

type Row = DropZoneMembraneFile & { closing: boolean };
type Drag = { count: number; ok: boolean; held: boolean };

const RADIUS = 14;
const HOLD = 16; // a file this close outside the zone is already held by the bulge, and drops into it

const matchRule = (rule: string, type: string, name: string) =>
  rule.startsWith(".")
    ? name.endsWith(rule)
    : rule.endsWith("/*")
      ? type.startsWith(rule.slice(0, -1))
      : type === rule;
const rulesOf = (accept?: string) =>
  (accept ?? "")
    .split(",")
    .map((r) => r.trim().toLowerCase())
    .filter(Boolean);
const EXTENSIONS: Record<string, string> = {
  ".pdf": "application/pdf",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".gif": "image/gif",
  ".webp": "image/webp",
  ".avif": "image/avif",
  ".svg": "image/svg+xml",
  ".txt": "text/plain",
  ".csv": "text/csv",
  ".md": "text/markdown",
  ".json": "application/json",
  ".zip": "application/zip",
  ".mp4": "video/mp4",
  ".mov": "video/quicktime",
  ".webm": "video/webm",
  ".mp3": "audio/mpeg",
  ".wav": "audio/wav",
};
/** During a drag only the type is known, and sometimes not even that: refuse only what surely can't match. */
const mightAccept = (rules: string[], type: string) => {
  if (!rules.length || !type) return true;
  const t = type.toLowerCase();
  return rules.some((r) =>
    r.startsWith(".")
      ? !EXTENSIONS[r] || EXTENSIONS[r] === t
      : matchRule(r, t, ""),
  );
};
const accepts = (rules: string[], file: File) =>
  !rules.length ||
  rules.some((r) =>
    matchRule(
      r,
      file.type.toLowerCase() ||
        EXTENSIONS[file.name.toLowerCase().slice(file.name.lastIndexOf("."))] ||
        "",
      file.name.toLowerCase(),
    ),
  );

const onlyLabel = (hint?: string) =>
  hint
    ? `Only ${/^.[a-z]/.test(hint) ? hint[0].toLowerCase() + hint.slice(1) : hint}`
    : undefined;
let counter = 0;

export function DropZoneMembrane({
  onUpload,
  autoUpload = true,
  onFilesChange,
  accept = "image/*,.pdf",
  maxSize = 10_000_000,
  maxFiles = 2,
  multiple = true,
  title = "Drop files here",
  hint = "images or PDFs, up to 10 MB",
  disabled = false,
  ref,
  className = "",
  ...props
}: DropZoneMembraneProps) {
  const reduced = useInteractionReducedMotion();
  const hintId = React.useId();
  const membrane = useMembrane({ radius: RADIUS, reduced });
  const rules = React.useMemo(() => rulesOf(accept), [accept]);
  const root = React.useRef<HTMLDivElement>(null);
  const zone = React.useRef<HTMLButtonElement | null>(null);
  const input = React.useRef<HTMLInputElement>(null);
  const [drag, setDrag] = React.useState<Drag | null>(null);
  const [notice, setNotice] = React.useState<{
    text: string;
    error: boolean;
  } | null>(null);
  const [rows, setRows] = React.useState<Row[]>([]);
  const [said, setSaid] = React.useState("");
  const rowsRef = React.useRef(rows);
  const updateRows = React.useCallback((update: (rows: Row[]) => Row[]) => {
    const next = update(rowsRef.current);
    rowsRef.current = next;
    setRows(next);
  }, []);
  const controllers = React.useRef(new Map<string, AbortController>());
  const timers = React.useRef(new Set<ReturnType<typeof setTimeout>>());
  const noticeTimer = React.useRef<ReturnType<typeof setTimeout> | null>(null);
  const upload = React.useRef(onUpload);
  upload.current = onUpload;

  const later = React.useCallback((fn: () => void, ms: number) => {
    const t = setTimeout(() => {
      timers.current.delete(t);
      fn();
    }, ms);
    timers.current.add(t);
  }, []);
  React.useEffect(
    () => () => {
      timers.current.forEach(clearTimeout);
      if (noticeTimer.current) clearTimeout(noticeTimer.current);
      controllers.current.forEach((c) => c.abort());
    },
    [],
  );

  const tell = React.useCallback((text: string, error: boolean) => {
    if (noticeTimer.current) clearTimeout(noticeTimer.current);
    setNotice({ text, error });
    noticeTimer.current = setTimeout(
      () => setNotice(null),
      error ? 2800 : 1800,
    );
  }, []);

  const local = (clientX: number, clientY: number) => {
    const r = zone.current?.getBoundingClientRect();
    return r
      ? { x: clientX - r.left, y: clientY - r.top, w: r.width, h: r.height }
      : { x: 0, y: 0, w: 0, h: 0 };
  };

  // Follow a drag: bend the line, decide whether the file is held, and update the label only when that changes.
  const track = React.useCallback(
    (clientX: number, clientY: number, types: string[]) => {
      if (disabled) return false;
      const p = local(clientX, clientY);
      const outside = Math.hypot(
        Math.max(-p.x, 0, p.x - p.w),
        Math.max(-p.y, 0, p.y - p.h),
      );
      const ok = !types.length || types.some((t) => mightAccept(rules, t));
      const isHeld = outside < HOLD;
      membrane.set("pointer", {
        x: p.x,
        y: p.y,
        kind: ok ? "reach" : "recoil",
      });
      membrane.swell(isHeld ? (ok ? 3 : -2) : 1.5);
      setDrag((d) =>
        d && d.count === types.length && d.ok === ok && d.held === isHeld
          ? d
          : { count: types.length, ok, held: isHeld },
      );
      return isHeld;
    },
    [disabled, rules, membrane],
  );

  const release = React.useCallback(() => {
    membrane.set("pointer", null);
    membrane.swell(0);
    setDrag(null);
  }, [membrane]);

  const start = React.useCallback(
    (id: string, file: File) => {
      if (!rowsRef.current.some((r) => r.id === id && !r.closing)) return;
      controllers.current.get(id)?.abort();
      const run = upload.current;
      const patch = (next: Partial<Row>) =>
        updateRows((list) =>
          list.map((r) => (r.id === id ? { ...r, ...next } : r)),
        );
      if (!run) return patch({ status: "idle", progress: 0 });
      const controller = new AbortController();
      controllers.current.set(id, controller);
      const active = () =>
        !controller.signal.aborted &&
        controllers.current.get(id) === controller;
      patch({ status: "uploading", progress: 0, error: undefined });
      let last = 0;
      const progress = (f: number) => {
        const v = Math.max(last, Math.min(1, Number.isFinite(f) ? f : 0));
        if (!active() || Math.abs(v - last) < 0.005) return;
        last = v;
        patch({ progress: v });
      };
      Promise.resolve()
        .then(() => {
          if (controller.signal.aborted) return;
          return run(file, {
            progress,
            processing: () => {
              if (active()) patch({ status: "processing", progress: 1 });
            },
            signal: controller.signal,
          });
        })
        .then(
          () => {
            if (controller.signal.aborted) return;
            patch({ status: "done", progress: 1 });
            setSaid(`${file.name} uploaded`);
          },
          (error: unknown) => {
            if (controller.signal.aborted) return;
            const message =
              error instanceof Error && error.message
                ? error.message
                : "Upload failed";
            patch({ status: "error", error: message });
            setSaid(`${file.name} failed to upload. ${message}`);
          },
        )
        .finally(() => {
          if (controllers.current.get(id) === controller)
            controllers.current.delete(id);
        });
    },
    [updateRows],
  );

  const remove = React.useCallback(
    (id: string) => {
      const item = rowsRef.current.find((r) => r.id === id);
      const focused = root.current
        ?.querySelector('[data-file="' + id + '"]')
        ?.contains(document.activeElement);
      if (focused) zone.current?.focus({ preventScroll: true });
      controllers.current.get(id)?.abort();
      controllers.current.delete(id);
      if (item) setSaid(item.file.name + " removed");
      updateRows((list) =>
        list.map((r) => (r.id === id ? { ...r, closing: true } : r)),
      );
      later(
        () => updateRows((list) => list.filter((r) => r.id !== id)),
        reduced ? 0 : 420,
      );
    },
    [later, reduced, updateRows],
  );

  // React to the drop point, then insert the actual attachment cards.
  const take = React.useCallback(
    (files: File[], at: { x: number; y: number }) => {
      if (disabled || !files.length) return;
      const current = rowsRef.current.filter((r) => !r.closing);
      const room = multiple ? (maxFiles ?? Infinity) - current.length : 1;
      const accepted: File[] = [];
      const refused: string[] = [];
      for (const file of multiple ? files : files.slice(0, 1)) {
        if (!accepts(rules, file)) refused.push(`${file.name} isn't accepted`);
        else if (maxSize !== undefined && file.size > maxSize)
          refused.push(`${file.name} is over ${formatBytes(maxSize)}`);
        else if (accepted.length >= room)
          refused.push(`Up to ${maxFiles} files`);
        else if (
          [...current.map((r) => r.file), ...accepted].some(
            (f) =>
              f.name === file.name &&
              f.size === file.size &&
              f.lastModified === file.lastModified &&
              f.type === file.type,
          )
        )
          refused.push(file.name + " is already added");
        else accepted.push(file);
      }
      if (!multiple && files.length > 1) refused.push("One file at a time");
      if (!accepted.length) {
        membrane.spit(at.x, at.y);
        tell(refused[0] ?? "Nothing to add", true);
        setSaid(refused.join(". "));
        return;
      }
      membrane.gulp(at.x, at.y);
      if (!multiple) current.forEach((r) => remove(r.id));
      const added: Row[] = accepted.map((file) => ({
        id: `f${++counter}`,
        file,
        status: "idle",
        progress: 0,
        closing: false,
      }));
      updateRows((list) => [...list, ...added]);
      if (autoUpload && upload.current)
        added.forEach((r) => start(r.id, r.file));
      const summary =
        accepted.length === 1
          ? `Added ${accepted[0].name}`
          : `Added ${accepted.length} files`;
      tell(
        refused.length
          ? refused.length === 1
            ? refused[0]
            : `${refused.length} files skipped`
          : accepted.length === 1
            ? "File added"
            : summary,
        refused.length > 0,
      );
      setSaid([summary, ...refused].join(". "));
    },
    [
      disabled,
      multiple,
      maxFiles,
      maxSize,
      rules,
      membrane,
      tell,
      remove,
      start,
      autoUpload,
      updateRows,
    ],
  );

  const centre = () => {
    const el = zone.current;
    return { x: (el?.offsetWidth ?? 0) / 2, y: (el?.offsetHeight ?? 0) / 2 };
  };

  // Files dragged in from the system: watch the whole window so the line can reach out before the file arrives.
  React.useEffect(() => {
    if (disabled) {
      release();
      return;
    }
    let quiet: ReturnType<typeof setTimeout> | null = null;
    const end = () => {
      if (quiet) clearTimeout(quiet);
      release();
    };
    const over = (e: DragEvent) => {
      const data = e.dataTransfer;
      if (!data || !Array.from(data.types).includes("Files")) return;
      // dragover repeats while a drag is over the page; silence means it left.
      if (quiet) clearTimeout(quiet);
      quiet = setTimeout(end, 400);
      const types = Array.from(data.items)
        .filter((i) => i.kind === "file")
        .map((i) => i.type);
      if (track(e.clientX, e.clientY, types)) {
        e.preventDefault();
        data.dropEffect = "copy";
      }
    };
    const leave = (e: DragEvent) => {
      if (
        !e.relatedTarget &&
        (e.clientX <= 0 ||
          e.clientY <= 0 ||
          e.clientX >= window.innerWidth ||
          e.clientY >= window.innerHeight)
      )
        end();
    };
    const drop = (e: DragEvent) => {
      const files = Array.from(e.dataTransfer?.files ?? []);
      const p = local(e.clientX, e.clientY);
      const isHeld =
        p.w > 0 &&
        Math.hypot(Math.max(-p.x, 0, p.x - p.w), Math.max(-p.y, 0, p.y - p.h)) <
          HOLD;
      if (isHeld && files.length) {
        e.preventDefault();
        take(files, {
          x: Math.max(0, Math.min(p.w, p.x)),
          y: Math.max(0, Math.min(p.h, p.y)),
        });
      }
      end();
    };
    window.addEventListener("dragenter", over);
    window.addEventListener("dragover", over);
    window.addEventListener("dragleave", leave);
    window.addEventListener("drop", drop);
    window.addEventListener("dragend", end);
    window.addEventListener("blur", end);
    return () => {
      if (quiet) clearTimeout(quiet);
      window.removeEventListener("dragenter", over);
      window.removeEventListener("dragover", over);
      window.removeEventListener("dragleave", leave);
      window.removeEventListener("drop", drop);
      window.removeEventListener("dragend", end);
      window.removeEventListener("blur", end);
    };
  }, [disabled, track, release, take]);

  React.useImperativeHandle(
    ref,
    () => ({
      drag: (x, y, types = []) => track(x, y, types),
      cancel: release,
      drop: (files, at) => {
        const p = at ? local(at.x, at.y) : { ...centre(), w: 0, h: 0 };
        release();
        take(files, { x: p.x, y: p.y });
      },
      browse: () => {
        if (!disabled) input.current?.click();
      },
    }),
    [track, release, take, disabled],
  );

  const live = rows.filter((r) => !r.closing);
  const liveKey = live.map((r) => r.id).join();
  const report = React.useRef(onFilesChange);
  report.current = onFilesChange;
  const first = React.useRef(true);
  React.useEffect(() => {
    if (first.current) {
      first.current = false;
      return;
    }
    report.current?.(
      rowsRef.current.filter((r) => !r.closing).map((r) => r.file),
    );
  }, [liveKey]);

  const refusing = drag ? !drag.ok : (notice?.error ?? false);
  const label = drag
    ? !drag.ok
      ? (onlyLabel(hint) ?? "This type can't be added")
      : drag.held
        ? drag.count > 1
          ? `Release to add ${drag.count}`
          : "Release to add"
        : drag.count > 1
          ? `Drop ${drag.count} files here`
          : "Drop it here"
    : (notice?.text ?? title);
  const icon: "arrow" | "refuse" | "added" = refusing
    ? "refuse"
    : notice && !notice.error
      ? "added"
      : "arrow";
  const tone = refusing
    ? "refuse"
    : drag?.held
      ? "over"
      : drag
        ? "armed"
        : "rest";
  const colors = {
    rest: {
      stroke: "var(--border)",
      fill: "color-mix(in oklab, var(--muted) 45%, transparent)",
    },
    armed: {
      stroke: "color-mix(in oklab, var(--primary) 55%, var(--border))",
      fill: "color-mix(in oklab, var(--primary) 3%, var(--background))",
    },
    over: {
      stroke: "var(--primary)",
      fill: "color-mix(in oklab, var(--primary) 7%, var(--background))",
    },
    refuse: {
      stroke: "var(--destructive, #dc2626)",
      fill: "color-mix(in oklab, var(--destructive, #dc2626) 5%, var(--background))",
    },
  }[tone];

  return (
    <div
      ref={root}
      className={`@container relative w-full text-foreground ${className}`}
      {...props}
    >
      <button
        ref={(el) => {
          zone.current = el;
          membrane.attach(el);
        }}
        type="button"
        disabled={disabled}
        aria-label="Browse files"
        data-slot="membrane-zone"
        aria-describedby={hint ? hintId : undefined}
        onClick={() => input.current?.click()}
        onPaste={(e) => {
          const files = Array.from(e.clipboardData.files);
          if (!files.length) return;
          e.preventDefault();
          take(files, centre());
        }}
        className={`group/zone relative grid w-full cursor-pointer grid-cols-[40px_minmax(0,1fr)] items-center gap-x-3 gap-y-3 rounded-[14px] p-4 text-left disabled:cursor-default disabled:opacity-55 @sm:grid-cols-[40px_minmax(0,1fr)_auto] ${INTERACTION_FOCUS}`}
      >
        <svg
          aria-hidden="true"
          className="pointer-events-none absolute inset-0 size-full overflow-visible"
        >
          <path
            ref={membrane.path}
            strokeWidth={1}
            style={{
              ...colors,
              transition: reduced
                ? "none"
                : `stroke 280ms ${EASE_OUT}, fill 360ms ${EASE_OUT}`,
            }}
          />
        </svg>
        <span
          aria-hidden="true"
          className="relative flex size-10 items-center justify-center rounded-xl border bg-background transition-colors duration-300"
          style={{
            borderColor: tone === "rest" ? "var(--border)" : colors.stroke,
            color:
              tone === "refuse"
                ? colors.stroke
                : tone === "rest"
                  ? "var(--muted-foreground)"
                  : "var(--accent-ink, var(--foreground))",
          }}
        >
          <span
            ref={membrane.arrow}
            className="absolute inset-0 flex items-center justify-center will-change-transform"
            style={interactionIcon(icon === "arrow", reduced)}
          >
            <ArrowUp className="size-4" strokeWidth={1.75} />
          </span>
          <span
            className="absolute inset-0 flex items-center justify-center"
            style={interactionIcon(icon === "refuse", reduced)}
          >
            <X className="size-4" strokeWidth={1.75} />
          </span>
          <span
            className="absolute inset-0 flex items-center justify-center"
            style={interactionIcon(icon === "added", reduced)}
          >
            <DrawnCheck on={icon === "added"} reduced={reduced} />
          </span>
        </span>
        <span className="relative flex min-w-0 flex-col items-start gap-1">
          <span
            title={label}
            className={`max-w-full overflow-hidden text-[13.5px] font-medium tracking-[-0.01em] transition-colors duration-300 ${refusing ? "text-destructive" : ""}`}
          >
            <TextMorph className="max-w-full overflow-hidden align-bottom">
              {label}
            </TextMorph>
          </span>
          <span className="text-[12px] leading-relaxed text-muted-foreground">
            Drag & drop, or paste a file
          </span>
        </span>
        {/* One native button owns the whole tray, including this visual action. */}
        <span
          aria-hidden="true"
          data-slot="membrane-browse"
          className="relative col-start-2 inline-flex min-h-11 w-fit items-center justify-center rounded-xl border border-border bg-background px-3.5 text-[12px] font-medium text-foreground transition-colors duration-200 group-hover/zone:bg-accent group-focus-visible/zone:bg-accent @sm:col-start-auto"
        >
          Add files
        </span>
        <span
          id={hintId}
          data-slot="membrane-requirements"
          className="relative col-span-full flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1 border-t border-border/70 pt-3 text-[11px] leading-relaxed text-muted-foreground"
        >
          {hint && (
            <span className="min-w-0 [overflow-wrap:anywhere]">{hint}</span>
          )}
          {hint && <span aria-hidden="true">·</span>}
          <span>
            {multiple ? `Up to ${maxFiles} files` : "One file at a time"}
          </span>
        </span>
      </button>
      <input
        ref={input}
        type="file"
        disabled={disabled}
        hidden
        multiple={multiple}
        accept={accept}
        onChange={(e) => {
          const files = Array.from(e.currentTarget.files ?? []);
          e.currentTarget.value = "";
          take(files, centre());
        }}
      />

      {rows.length > 0 && (
        <ul aria-label="Files" className="mt-3 list-none p-0">
          {rows.map((r) => (
            <FileRow
              key={r.id}
              row={r}
              reduced={reduced}
              disabled={disabled}
              canUpload={!!onUpload}
              onRemove={() => remove(r.id)}
              onRetry={() => start(r.id, r.file)}
            />
          ))}
        </ul>
      )}

      <p role="status" className="sr-only">
        {said}
      </p>
    </div>
  );
}

function FileRow({
  row,
  reduced,
  disabled,
  canUpload,
  onRemove,
  onRetry,
}: {
  row: Row;
  reduced: boolean;
  disabled: boolean;
  canUpload: boolean;
  onRemove: () => void;
  onRetry: () => void;
}) {
  const [open, setOpen] = React.useState(reduced);
  React.useEffect(() => {
    if (open) return;
    let b = 0;
    const a = requestAnimationFrame(() => {
      b = requestAnimationFrame(() => setOpen(true));
    });
    return () => {
      cancelAnimationFrame(a);
      cancelAnimationFrame(b);
    };
  }, [open]);
  const shown = open && !row.closing;
  return (
    <li
      data-file={row.id}
      className="grid"
      inert={row.closing}
      aria-hidden={row.closing || undefined}
      style={{
        gridTemplateRows: shown ? "1fr" : "0fr",
        opacity: shown ? 1 : 0,
        transition: reduced
          ? "none"
          : "grid-template-rows 420ms " +
            EASE_OUT +
            ", opacity 200ms " +
            EASE_OUT,
      }}
    >
      <div className="min-h-0 overflow-hidden">
        <div className="pb-2">
          <MembraneAttachment
            file={row.file}
            status={row.status}
            progress={row.progress}
            error={row.error}
            disabled={disabled}
            onRemove={onRemove}
            onRetry={canUpload ? onRetry : undefined}
            onUpload={canUpload ? onRetry : undefined}
          />
        </div>
      </div>
    </li>
  );
}

function DrawnCheck({ on, reduced }: { on: boolean; reduced: boolean }) {
  return (
    <svg
      viewBox="0 0 16 16"
      className="size-4"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.75"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <path
        d="M3.5 8.5l3 3 6-7"
        pathLength={1}
        strokeDasharray="1"
        strokeDashoffset={on ? 0 : 1}
        style={{
          transition: reduced
            ? "none"
            : `stroke-dashoffset ${on ? 420 : 0}ms ${EASE_OUT} ${on ? 120 : 0}ms`,
        }}
      />
    </svg>
  );
}

