import type * as React from "react";

export type DropZoneStatus = "ready" | "uploading" | "done" | "error";

export interface DropZoneFile {
  id: string;
  file: File;
  status: DropZoneStatus;
  /** A fraction from 0 to 1. */
  progress: number;
  error?: string;
}

export type DropZoneUpload = (
  file: File,
  context: { progress: (fraction: number) => void; signal: AbortSignal },
) => void | Promise<void>;

export interface DropZoneRejection {
  file: File;
  code: "type" | "size" | "count" | "duplicate";
  reason: string;
}

export interface DropZoneHandle {
  /** Tracks a drag from your app. Only coordinates inside the drop area return true. */
  drag: (clientX: number, clientY: number, types?: string[]) => boolean;
  cancel: () => void;
  /** Adds files from your app; optional coordinates must be inside the drop area. */
  drop: (files: File[], at?: { x: number; y: number }) => void;
  browse: () => void;
}

export interface DropZoneProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onDrop" | "title"
> {
  /** Resolve when uploaded, throw to offer Retry, and honour the abort signal. */
  onUpload?: DropZoneUpload;
  /** Current selection after adding, replacing or removing files. */
  onFilesChange?: (files: File[]) => void;
  onFilesRejected?: (rejections: DropZoneRejection[]) => void;
  /** Native input syntax: MIME types, wildcards or extensions, e.g. "image/*,.pdf". */
  accept?: string;
  /** Maximum size of each file in bytes. */
  maxSize?: number;
  maxFiles?: number;
  /** false replaces the current file when a valid new file is selected. */
  multiple?: boolean;
  title?: string;
  hint?: string;
  disabled?: boolean;
  ref?: React.Ref<DropZoneHandle>;
}

import type { DropZoneRejection } from "./drop-zone-types";

export function formatBytes(bytes: number) {
  if (bytes < 1000) return `${bytes} B`;
  const unit = bytes < 1e6 ? "KB" : bytes < 1e9 ? "MB" : "GB";
  const value = bytes / (unit === "KB" ? 1000 : unit === "MB" ? 1e6 : 1e9);
  return `${Number(value.toFixed(1))} ${unit}`;
}

export const acceptRules = (accept = "") =>
  accept
    .split(",")
    .map((rule) => rule.trim().toLowerCase())
    .filter(Boolean);

export function acceptsFile(file: File, rules: string[]) {
  const name = file.name.toLowerCase();
  const type = file.type.toLowerCase();
  return (
    !rules.length ||
    rules.some((rule) =>
      rule.startsWith(".")
        ? name.endsWith(rule)
        : rule.endsWith("/*")
          ? type.startsWith(rule.slice(0, -1))
          : type === rule,
    )
  );
}

export const sameFile = (a: File, b: File) =>
  a.name === b.name &&
  a.size === b.size &&
  a.type === b.type &&
  a.lastModified === b.lastModified;

export function selectionHint(
  accept?: string,
  maxSize?: number,
  maxFiles?: number,
) {
  const types = acceptRules(accept)
    .map((rule) =>
      rule.startsWith(".")
        ? rule.slice(1).toUpperCase()
        : rule.endsWith("/*")
          ? `${rule.slice(0, -2)} files`
          : rule.split("/").pop(),
    )
    .join(", ");
  return [
    types || "Any file type",
    maxSize === undefined ? "" : `Up to ${formatBytes(maxSize)} per file`,
    maxFiles === undefined
      ? ""
      : `${maxFiles} file${maxFiles === 1 ? "" : "s"} maximum`,
  ]
    .filter(Boolean)
    .join(" · ");
}

/** Validate a whole batch before replacing a single-file selection. */
export function selectFiles(
  files: File[],
  current: File[],
  options: {
    accept?: string;
    maxSize?: number;
    maxFiles?: number;
    multiple?: boolean;
  },
) {
  const { maxSize, maxFiles, multiple = true } = options;
  const rules = acceptRules(options.accept);
  const limit =
    maxFiles === undefined ? Infinity : Math.max(0, Math.floor(maxFiles));
  const room = multiple
    ? Math.max(0, limit - current.length)
    : Math.min(1, limit);
  const accepted: File[] = [];
  const rejected: DropZoneRejection[] = [];
  for (const file of files) {
    let problem: Omit<DropZoneRejection, "file"> | undefined;
    if (!acceptsFile(file, rules))
      problem = { code: "type", reason: "This file type is not supported." };
    else if (maxSize !== undefined && file.size > maxSize)
      problem = {
        code: "size",
        reason: `Exceeds the ${formatBytes(maxSize)} limit.`,
      };
    else if ([...current, ...accepted].some((other) => sameFile(file, other)))
      problem = {
        code: "duplicate",
        reason: "This file has already been added.",
      };
    else if (accepted.length >= room)
      problem = {
        code: "count",
        reason: multiple
          ? `You can add up to ${maxFiles} files.`
          : "Choose one file at a time.",
      };
    if (problem) rejected.push({ file, ...problem });
    else accepted.push(file);
  }
  return { accepted, rejected };
}

"use client";

import * as React from "react";
import { ArrowUp, CircleAlert, X } from "lucide-react";
import { DropZoneFileRow } from "./drop-zone-file-row";
import type { DropZoneProps } from "./drop-zone-types";
import { selectionHint } from "./drop-zone-utils";
import { useDropZone } from "./use-drop-zone";
import { TextMorph } from "./text-morph";
import { INTERACTION_FOCUS } from "./imported-ui-interaction-motion";

export type {
  DropZoneStatus,
  DropZoneFile,
  DropZoneUpload,
  DropZoneRejection,
  DropZoneHandle,
  DropZoneProps,
} from "./drop-zone-types";
export { formatBytes } from "./drop-zone-utils";

const carriesFiles = (data: DataTransfer) =>
  Array.from(data.types).includes("Files");

export function DropZone({
  onUpload,
  onFilesChange,
  onFilesRejected,
  accept,
  maxSize,
  maxFiles,
  multiple = true,
  title = "Drop files here",
  hint,
  disabled = false,
  ref,
  className = "",
  onPaste,
  ...props
}: DropZoneProps) {
  const input = React.useRef<HTMLInputElement>(null);
  const area = React.useRef<HTMLButtonElement>(null);
  const depth = React.useRef(0);
  const [dragging, setDragging] = React.useState(false);
  const id = React.useId();
  const {
    rows,
    rejections,
    announcement,
    add,
    remove,
    retry,
    dismissRejections,
  } = useDropZone({
    onUpload,
    onFilesChange,
    onFilesRejected,
    accept,
    maxSize,
    maxFiles,
    multiple,
    disabled,
  });
  const description =
    hint ?? selectionHint(accept, maxSize, multiple ? maxFiles : 1);

  const cancel = React.useCallback(() => {
    depth.current = 0;
    setDragging(false);
  }, []);
  const browse = React.useCallback(() => {
    if (!disabled) input.current?.click();
  }, [disabled]);
  const contains = React.useCallback((x: number, y: number) => {
    const rect = area.current?.getBoundingClientRect();
    return (
      !!rect &&
      rect.width > 0 &&
      rect.height > 0 &&
      x >= rect.left &&
      x <= rect.right &&
      y >= rect.top &&
      y <= rect.bottom
    );
  }, []);

  const [seenDisabled, setSeenDisabled] = React.useState(disabled);
  if (disabled !== seenDisabled) {
    setSeenDisabled(disabled);
    if (disabled && dragging) setDragging(false);
  }
  React.useEffect(() => {
    if (disabled) depth.current = 0;
  }, [disabled]);
  React.useImperativeHandle(
    ref,
    () => ({
      browse,
      cancel,
      drag: (x, y) => {
        const inside = !disabled && contains(x, y);
        setDragging(inside);
        return inside;
      },
      drop: (files, at) => {
        cancel();
        if (!at || contains(at.x, at.y)) add(files);
      },
    }),
    [browse, cancel, disabled, contains, add],
  );

  return (
    <div
      {...props}
      className={`@container relative w-full min-w-0 text-foreground ${className}`}
      onPaste={(event) => {
        onPaste?.(event);
        if (event.defaultPrevented || disabled) return;
        const files = Array.from(event.clipboardData.files);
        if (files.length) {
          event.preventDefault();
          cancel();
          add(files);
        }
      }}
    >
      <button
        ref={area}
        type="button"
        disabled={disabled}
        onClick={browse}
        aria-label={`Browse ${multiple ? "files" : "file"}`}
        aria-describedby={`${id}-title ${id}-hint`}
        data-drop-zone=""
        data-dragging={dragging || undefined}
        aria-disabled={disabled || undefined}
        onDragEnter={(event) => {
          if (!carriesFiles(event.dataTransfer)) return;
          event.preventDefault();
          if (!disabled) {
            depth.current++;
            setDragging(true);
          }
        }}
        onDragOver={(event) => {
          if (!carriesFiles(event.dataTransfer)) return;
          event.preventDefault();
          event.dataTransfer.dropEffect = disabled ? "none" : "copy";
          if (!disabled) setDragging(true);
        }}
        onDragLeave={(event) => {
          event.preventDefault();
          depth.current = Math.max(0, depth.current - 1);
          if (!depth.current) setDragging(false);
        }}
        onDrop={(event) => {
          event.preventDefault();
          cancel();
          add(Array.from(event.dataTransfer.files));
        }}
        onDragEnd={cancel}
        className={`relative flex min-h-[152px] w-full cursor-pointer flex-col items-center justify-center gap-3 rounded-[18px] border px-5 py-5 text-center transition-colors duration-200 disabled:cursor-default disabled:opacity-55 motion-reduce:transition-none @md:min-h-[176px] ${INTERACTION_FOCUS} ${
          dragging ? "border-primary bg-primary/5" : "border-border bg-muted/45"
        }`}
      >
        <span
          className={`relative flex size-9 shrink-0 items-center justify-center rounded-full border bg-background transition-colors duration-200 motion-reduce:transition-none ${dragging ? "border-primary/30 text-primary" : "border-border text-muted-foreground"}`}
        >
          <ArrowUp className="size-4" strokeWidth={1.75} aria-hidden="true" />
        </span>
        <span className="relative flex max-w-full flex-col items-center gap-1">
          <span
            id={`${id}-title`}
            className="text-[13.5px] font-medium tracking-[-0.01em]"
          >
            <TextMorph>{dragging ? "Release to add" : title}</TextMorph>
          </span>
          <span
            id={`${id}-hint`}
            className="text-balance text-[12px] leading-relaxed text-muted-foreground"
          >
            <span className="whitespace-nowrap">
              <span className="text-foreground underline decoration-border underline-offset-[3px]">
                Browse
              </span>{" "}
              or paste ·
            </span>{" "}
            {description}
          </span>
        </span>
      </button>
      <input
        ref={input}
        type="file"
        hidden
        disabled={disabled}
        multiple={multiple}
        accept={accept}
        onChange={(event) => {
          const files = Array.from(event.currentTarget.files ?? []);
          event.currentTarget.value = "";
          cancel();
          add(files);
        }}
      />

      {rejections.length > 0 && (
        <div
          role="alert"
          className="mt-2 flex items-start gap-2 text-red-600 dark:text-red-400"
        >
          <CircleAlert className="mt-2 size-3.5 shrink-0" aria-hidden="true" />
          <div className="min-w-0 flex-1 py-1.5 text-[12px] leading-relaxed [overflow-wrap:anywhere]">
            {rejections.slice(0, 3).map((rejection, index) => (
              <p key={index} className="break-words">
                <span className="font-medium">{rejection.file.name}</span> —{" "}
                {rejection.reason}
              </p>
            ))}
            {rejections.length > 3 && (
              <p className="mt-1">
                {rejections.length - 3} more files skipped.
              </p>
            )}
          </div>
          <button
            type="button"
            aria-label="Dismiss file errors"
            onClick={dismissRejections}
            className={`flex size-8 shrink-0 cursor-pointer items-center justify-center rounded-full hover:bg-muted ${INTERACTION_FOCUS}`}
          >
            <X className="size-3.5" aria-hidden="true" />
          </button>
        </div>
      )}

      {rows.length > 0 && (
        <ul aria-label="Files" className="mt-3 min-w-0">
          {rows.map((row) => (
            <DropZoneFileRow
              key={row.id}
              row={row}
              disabled={disabled}
              onRemove={() => remove(row.id)}
              onRetry={() => retry(row.id)}
            />
          ))}
        </ul>
      )}
      <p
        role="status"
        aria-live="polite"
        aria-atomic="true"
        className="sr-only"
      >
        {announcement}
      </p>
    </div>
  );
}

"use client";

import * as React from "react";
import { createPortal } from "react-dom";
import {
  enterStyle,
  themeVars,
  useDismiss,
  useFloating,
  usePresence,
  type Align,
  type Side,
} from "./floating";
import { MenuList, type MenuEntry } from "./menu-list";
import { useInteractionReducedMotion } from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * DROPDOWN MENU: actions behind a button
 *
 *   open     the menu rises off the trigger out of a blur, from
 *            the point on the trigger nearest to it; it flips
 *            above when there's no room below
 *   move     one highlight glides between rows
 *   pick     the menu closes and focus goes back to the trigger;
 *            checkbox rows draw their tick and stay open
 *
 * Opening from the keyboard (Enter, Space, ↓) focuses the first
 * row; ↑ focuses the last. Escape or a press outside closes it.
 * ───────────────────────────────────────────────────────── */

export type { MenuEntry } from "./menu-list";

export interface DropdownMenuProps {
  /** The button that opens it. It gets aria-haspopup, aria-expanded and the click. */
  trigger: React.ReactElement<React.HTMLAttributes<HTMLElement>>;
  items: MenuEntry[];
  side?: Side;
  align?: Align;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Accessible name of the menu. */
  label?: string;
  /** Minimum width in px; never narrower than the trigger. */
  minWidth?: number;
}

export function DropdownMenu({
  trigger,
  items,
  side = "bottom",
  align = "start",
  open: controlled,
  onOpenChange,
  label,
  minWidth = 200,
}: DropdownMenuProps) {
  const reduced = useInteractionReducedMotion();
  const anchor = React.useRef<HTMLSpanElement>(null);
  const surface = React.useRef<HTMLDivElement>(null);
  const [own, setOwn] = React.useState(false);
  const [focusOn, setFocusOn] = React.useState<"first" | "last" | "none">(
    "none",
  );
  const open = controlled ?? own;
  const { mounted, shown } = usePresence(open, 180);
  const place = useFloating({
    open: mounted,
    anchor,
    floating: surface,
    side,
    align,
    offset: 6,
  });
  const [vars, setVars] = React.useState<React.CSSProperties>({});
  const id = React.useId();
  const triggerId = React.useId();

  const setOpen = (next: boolean, refocus = false) => {
    if (controlled === undefined) setOwn(next);
    onOpenChange?.(next);
    // By id rather than a ref: this runs from handlers that are created while rendering.
    if (!next && refocus)
      document.getElementById(trigger.props.id ?? triggerId)?.focus();
  };

  useDismiss(open, (reason) => setOpen(false, reason === "escape"), [
    anchor,
    surface,
  ]);

  const [width, setWidth] = React.useState(minWidth);
  React.useLayoutEffect(() => {
    if (!mounted) return;
    setVars(themeVars(anchor.current));
    setWidth(Math.max(minWidth, anchor.current?.offsetWidth ?? 0));
  }, [mounted, minWidth]);

  return (
    <>
      <span ref={anchor} className="inline-flex">
        {React.cloneElement(trigger, {
          id: trigger.props.id ?? triggerId,
          "aria-haspopup": "menu",
          "aria-expanded": open,
          "aria-controls": open ? id : undefined,
          onClick: (e: React.MouseEvent<HTMLElement>) => {
            trigger.props.onClick?.(e);
            setFocusOn(e.detail === 0 ? "first" : "none");
            setOpen(!open);
          },
          onKeyDown: (e: React.KeyboardEvent<HTMLElement>) => {
            trigger.props.onKeyDown?.(e);
            if (e.key === "ArrowDown" || e.key === "ArrowUp") {
              e.preventDefault();
              setFocusOn(e.key === "ArrowDown" ? "first" : "last");
              setOpen(true);
            }
          },
        })}
      </span>
      {mounted &&
        createPortal(
          <div
            ref={surface}
            id={id}
            className="fixed left-0 top-0 z-[55] overflow-hidden rounded-[14px] bg-popover text-popover-foreground shadow-[0_0_0_1px_var(--border)]"
            style={{
              ...vars,
              left: place.x,
              top: place.y,
              minWidth: width,
              transformOrigin: place.origin,
              ...enterStyle(shown, place.side, reduced),
            }}
          >
            <MenuList
              items={items}
              label={label}
              autoFocus={focusOn}
              onClose={() => setOpen(false, true)}
            />
          </div>,
          document.body,
        )}
    </>
  );
}

export default DropdownMenu;

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * EARNINGS CHART: a bar chart that changes instead of redrawing
 *
 *   arrive    the first time it's on screen the bars grow up out
 *             of the baseline one after another and the total
 *             rolls up from zero
 *   period    6M, 1Y, All: the pill is thrown to the choice. Bars
 *             the two periods share glide to their new place and
 *             height, bars that leave fold away on their side,
 *             new ones grow in, the scale's labels roll and so
 *             does the total
 *   hover     a thin line column follows the pointer from bar to
 *             bar and the readout at its top slides along, its
 *             month morphing and its amount rolling
 *   change    the difference from the period before sits in a
 *             chip that turns emerald or red, its arrow turning
 *             with it
 *
 * The plot is one tab stop: arrow keys move between bars and
 * the readout is announced. Every figure is also in a table for
 * screen readers.
 * ───────────────────────────────────────────────────────── */

export interface EarningsBar {
  /** Stays the same across periods for the same month, so shared bars glide instead of popping. */
  key: string;
  /** Under the bar, e.g. "Aug". */
  label: string;
  value: number;
  /** In the readout, e.g. "August 2026". Defaults to label. */
  title?: string;
}

export interface EarningsPeriod {
  id: string;
  /** In the switch, e.g. "6M". */
  label: string;
  bars: EarningsBar[];
  /** The total of the period before, for the change chip. */
  previous?: number;
  /** After the chip, e.g. "vs the 6 months before". */
  comparison?: string;
}

export interface EarningsChartProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onChange"
> {
  title?: string;
  periods: EarningsPeriod[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (id: string) => void;
  /** Intl.NumberFormat options for amounts. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  /** The bar drawn in your primary colour, by key. Defaults to the last bar. */
  highlight?: string;
}

type Column = EarningsBar & {
  left: number;
  width: number;
  height: number;
  index: number;
  leaving?: "start" | "end";
};

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const GLIDE = "cubic-bezier(0.77,0,0.175,1)";
const MORPH = 560;
const PLOT = 176; // the bars' area
const HEADROOM = 30; // above the tallest bar, for the readout
const LABELS = 26;
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const CURRENCY: Intl.NumberFormatOptions = {
  style: "currency",
  currency: "USD",
  maximumFractionDigits: 0,
};

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** A round top for the scale: 4,820 → 5,000. */
function niceMax(value: number) {
  if (value <= 0) return 1;
  const step = 10 ** Math.floor(Math.log10(value));
  for (const m of [1, 1.2, 1.5, 2, 2.5, 3, 4, 5, 6, 8, 10])
    if (m * step >= value) return m * step;
  return 10 * step;
}

/** One bar and its label. It grows out of the baseline when it first appears, and folds away when it leaves. */
function ColumnView({
  col,
  grown,
  delay,
  tone,
  reduced,
  label,
}: {
  col: Column;
  grown: boolean;
  delay: number;
  tone: string;
  reduced: boolean;
  label: boolean;
}) {
  const [born, setBorn] = React.useState(false);
  React.useEffect(() => {
    let inner = 0;
    const outer = requestAnimationFrame(
      () => (inner = requestAnimationFrame(() => setBorn(true))),
    );
    return () => {
      cancelAnimationFrame(outer);
      cancelAnimationFrame(inner);
    };
  }, []);
  const up = grown && born && !col.leaving;
  return (
    <div
      aria-hidden="true"
      className="absolute top-0 h-full"
      style={{
        left: `${col.left}%`,
        width: `${col.width}%`,
        opacity: col.leaving ? 0 : 1,
        transition: reduced
          ? "none"
          : `left ${MORPH}ms ${GLIDE}, width ${MORPH}ms ${GLIDE}, opacity ${col.leaving ? 240 : 360}ms ${EASE}`,
      }}
    >
      <div
        className={`absolute bottom-[26px] left-1/2 w-[min(24px,62%)] -translate-x-1/2 rounded-t-[4px] ${tone}`}
        style={{
          height: up ? Math.max(2, col.height) : 0,
          transition: reduced
            ? "none"
            : `height 640ms ${EASE} ${delay}ms, background-color 300ms ${EASE}`,
        }}
      />
      <span
        className="absolute bottom-0 left-1/2 -translate-x-1/2 whitespace-nowrap text-[11px] leading-[18px] text-muted-foreground"
        style={{
          opacity: label ? 1 : 0,
          transition: reduced ? "none" : `opacity 300ms ${EASE}`,
        }}
      >
        {col.label}
      </span>
    </div>
  );
}

export function EarningsChart({
  title = "Earnings",
  periods,
  value,
  defaultValue,
  onValueChange,
  format = CURRENCY,
  locales,
  highlight,
  className = "",
  ...props
}: EarningsChartProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const [own, setOwn] = React.useState(
    defaultValue ?? periods[periods.length - 1]?.id,
  );
  const periodId = value ?? own;
  const period = periods.find((p) => p.id === periodId) ?? periods[0];
  const bars = period?.bars ?? [];
  // Set by the card's width in CSS and measured below.
  const [plotH, setPlotH] = React.useState(PLOT);
  const total = bars.reduce((sum, b) => sum + b.value, 0);
  const max = niceMax(Math.max(0, ...bars.map((b) => b.value)));
  const slot = bars.length ? 100 / bars.length : 100;
  const layout: Column[] = bars.map((b, index) => ({
    ...b,
    index,
    left: index * slot,
    width: slot,
    height: (b.value / max) * (plotH - HEADROOM),
  }));
  const hi = highlight ?? bars[bars.length - 1]?.key;

  const [visible, setVisible] = React.useState(false);
  const [active, setActive] = React.useState<number | null>(null);
  const [keyboard, setKeyboard] = React.useState(false);
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const [prev, setPrev] = React.useState(() => ({
    id: periodId,
    bars,
    layout,
  }));
  const [pill, setPill] = React.useState({ left: 0, width: 0, ready: false });
  const rootRef = React.useRef<HTMLDivElement>(null);
  const plotRef = React.useRef<HTMLDivElement>(null);
  const barsRef = React.useRef<HTMLDivElement>(null);
  const chipRefs = React.useRef<(HTMLButtonElement | null)[]>([]);
  const [width, setWidth] = React.useState(0);

  // A new period: bars it doesn't have fold away on the side they were on, past the bars both periods share.
  if (prev.id !== periodId) {
    const keys = new Set(bars.map((b) => b.key));
    const shared = prev.layout
      .filter((c) => keys.has(c.key))
      .map((c) => c.index);
    const firstShared = shared.length
      ? Math.min(...shared)
      : prev.layout.length;
    setLeaving(
      prev.layout
        .filter((c) => !keys.has(c.key))
        .map((c) => {
          const side = c.index < firstShared ? "start" : "end";
          // Same key as before, so the bar that was there is the one that folds away.
          return {
            ...c,
            leaving: side,
            left: side === "start" ? 0 : 100,
            width: 0,
            height: 0,
          };
        }),
    );
    setPrev({ id: periodId, bars, layout });
    setActive(null);
  } else if (prev.bars !== bars) {
    setPrev({ id: periodId, bars, layout });
  }

  React.useEffect(() => {
    if (!leaving.length) return;
    const timer = window.setTimeout(() => setLeaving([]), MORPH);
    return () => window.clearTimeout(timer);
  }, [leaving]);

  // The plot's height is set by the card's width in CSS; read it so the drawing fits.
  React.useLayoutEffect(() => {
    const el = plotRef.current;
    if (!el) return;
    const measure = () =>
      setPlotH((h) => {
        const next = el.offsetHeight - LABELS;
        return next > 0 && next !== h ? next : h;
      });
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  React.useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          observer.disconnect();
        }
      },
      { rootMargin: "0px 0px -10% 0px" },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  // Narrow bars show every other label (or fewer), always keeping the latest.
  React.useLayoutEffect(() => {
    const el = barsRef.current;
    if (!el) return;
    const measure = () =>
      setWidth((w) => (w === el.offsetWidth ? w : el.offsetWidth));
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, []);
  const every =
    width && bars.length
      ? Math.max(1, Math.ceil(30 / (width / bars.length)))
      : 1;

  React.useLayoutEffect(() => {
    const el = chipRefs.current[periods.findIndex((p) => p.id === periodId)];
    if (!el) return;
    setPill((p) =>
      p.left === el.offsetLeft && p.width === el.offsetWidth
        ? p
        : { left: el.offsetLeft, width: el.offsetWidth, ready: p.width > 0 },
    );
  }, [periodId, periods]);

  const choose = (next: string) => {
    if (next === periodId) return;
    if (value === undefined) setOwn(next);
    onValueChange?.(next);
  };

  const pointAt = (clientX: number) => {
    const r = barsRef.current?.getBoundingClientRect();
    if (!r || !bars.length) return null;
    return Math.min(
      bars.length - 1,
      Math.max(0, Math.floor(((clientX - r.left) / r.width) * bars.length)),
    );
  };

  const onKeyDown = (e: React.KeyboardEvent) => {
    if (!bars.length) return;
    const from =
      active ??
      Math.max(
        0,
        bars.findIndex((b) => b.key === hi),
      );
    const moves: Record<string, number> = {
      ArrowLeft: from - 1,
      ArrowRight: from + 1,
      Home: 0,
      End: bars.length - 1,
    };
    if (e.key === "Escape") return setActive(null);
    if (!(e.key in moves)) return;
    e.preventDefault();
    setKeyboard(true);
    setActive(
      Math.min(
        bars.length - 1,
        Math.max(0, active === null ? from : moves[e.key]),
      ),
    );
  };

  const fmt = (n: number) => new Intl.NumberFormat(locales, format).format(n);
  const change = period?.previous
    ? (total - period.previous) / period.previous
    : null;
  // The chip folds away for a period with nothing to compare against, holding its last figure while it goes.
  const [lastChange, setLastChange] = React.useState(change ?? 0);
  if (change !== null && change !== lastChange) setLastChange(change);
  const shownChange = change ?? lastChange;
  const up = shownChange >= 0;
  const comparable = periods.some((p) => p.previous);
  const shown = active !== null ? bars[active] : null;
  const col = active !== null ? layout[active] : null;
  const compact = {
    ...format,
    notation: "compact" as const,
    minimumFractionDigits: 0,
    maximumFractionDigits: 1,
  };

  return (
    <div
      ref={rootRef}
      className={`@container w-full rounded-[22px] bg-background shadow-[0_0_0_1px_var(--border)] ${className}`}
      {...props}
    >
      <div className="p-4 @md:p-5 [--gutter:30px] @md:[--gutter:40px] [--plot:148px] @md:[--plot:176px]">
        {/* The title and its control share a row; the figures sit under both. */}
        <div className="flex flex-wrap items-center justify-between gap-x-3 gap-y-2">
          <p className="text-[12px] text-muted-foreground @md:text-[13px]">
            {title}
          </p>
          <div
            role="radiogroup"
            aria-label="Period"
            className="relative -my-1 inline-flex shrink-0 rounded-full bg-muted p-0.5"
          >
            <span
              aria-hidden="true"
              className="absolute inset-y-0.5 left-0 rounded-full bg-background shadow-[0_0_0_1px_var(--border)]"
              style={{
                width: pill.width,
                transform: `translateX(${pill.left}px)`,
                transition:
                  pill.ready && !reduced
                    ? `transform 460ms ${THROW}, width 380ms ${EASE}`
                    : "none",
              }}
            />
            {periods.map((p, i) => {
              const selected = p.id === periodId;
              return (
                <button
                  key={p.id}
                  ref={(el) => {
                    chipRefs.current[i] = el;
                  }}
                  type="button"
                  role="radio"
                  aria-checked={selected}
                  tabIndex={selected ? 0 : -1}
                  onClick={() => choose(p.id)}
                  onKeyDown={(e) => {
                    if (e.key !== "ArrowRight" && e.key !== "ArrowLeft") return;
                    e.preventDefault();
                    const next =
                      (i + (e.key === "ArrowRight" ? 1 : -1) + periods.length) %
                      periods.length;
                    choose(periods[next].id);
                    chipRefs.current[next]?.focus();
                  }}
                  className={`cursor-pointer relative h-6 rounded-full px-2.5 text-[11.5px] font-medium @md:h-7 @md:px-3 @md:text-[12.5px] tabular-nums transition-colors duration-300 ${FOCUS} ${
                    selected
                      ? "text-foreground"
                      : "text-muted-foreground hover:text-foreground"
                  }`}
                >
                  {p.label}
                </button>
              );
            })}
          </div>
        </div>
        <p className="mt-0.5 text-[22px] font-medium leading-tight tracking-[-0.03em] @md:text-[26px] text-foreground">
          <NumberRoll
            value={visible ? total : 0}
            format={format}
            locales={locales}
            duration={1000}
          />
        </p>
        {(comparable || period?.comparison) && (
          <p className="mt-1 flex items-center text-[11.5px] text-muted-foreground @md:text-[12.5px]">
            <span
              className="grid"
              style={{
                gridTemplateColumns: change !== null ? "1fr" : "0fr",
                opacity: change !== null ? 1 : 0,
                transition: reduced
                  ? "none"
                  : `grid-template-columns 420ms ${EASE}, opacity 240ms ${EASE}`,
              }}
            >
              <span className="min-w-0 pr-2 [clip-path:inset(-4px_-2px)]">
                <span
                  className={`inline-flex items-center gap-1 whitespace-nowrap rounded-full px-1.5 py-px font-medium tabular-nums transition-colors duration-300 ${
                    up
                      ? "bg-emerald-500/10 text-emerald-600"
                      : "bg-red-500/10 text-red-600 dark:text-red-400"
                  }`}
                >
                  <svg
                    viewBox="0 0 12 12"
                    aria-hidden="true"
                    className="size-3"
                    style={{
                      transform: up ? "none" : "rotate(180deg)",
                      transition: reduced ? "none" : `transform 420ms ${THROW}`,
                    }}
                  >
                    <path
                      d="M6 9.5V2.5M2.8 5.6 6 2.5l3.2 3.1"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="1.5"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    />
                  </svg>
                  <NumberRoll
                    value={visible ? Math.abs(shownChange) : 0}
                    format={{ style: "percent", maximumFractionDigits: 1 }}
                    duration={800}
                  />
                </span>
              </span>
            </span>
            <span className="whitespace-nowrap">
              <TextMorph>{period?.comparison ?? " "}</TextMorph>
            </span>
          </p>
        )}

        <div
          ref={plotRef}
          role="group"
          tabIndex={0}
          aria-label={`${title}, ${period?.label ?? ""}. Use the arrow keys to read each bar.`}
          onKeyDown={onKeyDown}
          onBlur={() => keyboard && (setActive(null), setKeyboard(false))}
          onPointerMove={(e) => {
            setKeyboard(false);
            setActive(pointAt(e.clientX));
          }}
          onPointerDown={(e) => setActive(pointAt(e.clientX))}
          onPointerLeave={(e) => e.pointerType === "mouse" && setActive(null)}
          className={`relative mt-4 touch-pan-y @md:mt-5 select-none rounded-lg ${FOCUS}`}
          style={{ height: `calc(var(--plot) + ${LABELS}px)` }}
        >
          {/* The scale: rolling labels in the gutter, the top and the middle as fine lines, and the baseline. */}
          {[1, 0.5, 0].map((f) => (
            <div
              key={f}
              aria-hidden="true"
              className="absolute right-0"
              style={{ left: 0, top: HEADROOM + (1 - f) * (plotH - HEADROOM) }}
            >
              <span
                className="absolute left-0 top-0 -translate-y-1/2 text-[10.5px] tabular-nums leading-none text-muted-foreground/80"
                style={{
                  width: "calc(var(--gutter) - 8px)",
                  textAlign: "right",
                }}
              >
                <NumberRoll
                  value={visible ? max * f : 0}
                  format={compact}
                  locales={locales}
                  duration={700}
                />
              </span>
              <div
                className="border-t border-border"
                style={{ marginLeft: "var(--gutter)" }}
              />
            </div>
          ))}

          <div
            ref={barsRef}
            className="absolute inset-y-0 right-0"
            style={{ left: "var(--gutter)" }}
          >
            {/* The hovered column: a thin line lane from the readout down to the baseline. */}
            <div
              aria-hidden="true"
              className="pointer-events-none absolute rounded-[10px] bg-foreground/[0.02] shadow-[inset_0_0_0_1px_var(--border)]"
              style={{
                top: 2,
                height: plotH - 2,
                left: col ? `calc(${col.left}% + 2px)` : 0,
                width: col ? `calc(${col.width}% - 4px)` : 0,
                opacity: col ? 1 : 0,
                transition: reduced
                  ? "none"
                  : `left 380ms ${THROW}, width 380ms ${EASE}, opacity 200ms ${EASE}`,
              }}
            />

            {[
              ...layout,
              ...leaving.filter((l) => !bars.some((b) => b.key === l.key)),
            ].map((c) => (
              <ColumnView
                key={c.key}
                col={c}
                grown={visible}
                delay={c.leaving ? 0 : Math.min(c.index, 12) * 28}
                label={!c.leaving && (bars.length - 1 - c.index) % every === 0}
                reduced={reduced}
                tone={
                  c.key === hi
                    ? "bg-primary"
                    : active !== null && bars[active]?.key === c.key
                      ? "bg-foreground/25"
                      : active !== null
                        ? "bg-foreground/[0.07]"
                        : "bg-foreground/[0.11]"
                }
              />
            ))}

            {/* The readout rides the top of the lane: month morphs, amount rolls. */}
            <div
              aria-hidden="true"
              className="pointer-events-none absolute top-[5px] flex h-[22px] -translate-x-1/2 items-center gap-1.5 whitespace-nowrap rounded-full bg-background px-2.5 text-[11.5px] shadow-[0_0_0_1px_var(--border)]"
              style={{
                left: col
                  ? `clamp(56px, ${col.left + col.width / 2}%, calc(100% - 56px))`
                  : "50%",
                opacity: shown ? 1 : 0,
                scale: shown ? "1" : "0.94",
                transition: reduced
                  ? "none"
                  : `left 380ms ${THROW}, opacity 200ms ${EASE}, scale 260ms ${EASE}`,
              }}
            >
              <span className="text-muted-foreground">
                <TextMorph>
                  {shown ? (shown.title ?? shown.label) : " "}
                </TextMorph>
              </span>
              <span className="font-medium tabular-nums text-foreground">
                <NumberRoll
                  value={shown?.value ?? 0}
                  format={format}
                  locales={locales}
                  duration={600}
                />
              </span>
            </div>
          </div>
        </div>

        <p aria-live="polite" className="sr-only">
          {keyboard && shown
            ? `${shown.title ?? shown.label}: ${fmt(shown.value)}`
            : ""}
        </p>
        <table className="sr-only">
          <caption>
            {title}, {period?.label}: {fmt(total)}
          </caption>
          <tbody>
            {bars.map((b) => (
              <tr key={b.key} id={`${id}-${b.key}`}>
                <th scope="row">{b.title ?? b.label}</th>
                <td>{fmt(b.value)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

/* ─────────────────────────────────────────────────────────
 * EMPTY STATE SCENES: the isometric line drawings, as data
 *
 * Every scene is built in three dimensions on the same 6 × 6 tile
 * and projected with the standard isometric angle (30°). A shape is
 * one closed face or one line, listed back to front, so faces drawn
 * later cover what's behind them and the drawing keeps only the
 * lines you'd see. Shapes in the "hero" part move together for the
 * action's poses (a sheet that lands, a plug that goes in).
 * ───────────────────────────────────────────────────────── */

export type EmptyStateScene = "inbox" | "search" | "done" | "offline" | "chart";

/** What a face is filled with; the component maps these to theme tokens. */
export type SceneFill =
  | "top"
  | "left"
  | "right"
  | "hole"
  | "glass"
  | "accent"
  | "accent-side"
  | "none";
export type SceneStroke = "line" | "faint" | "accent";

export interface SceneShape {
  d: string;
  fill: SceneFill;
  stroke: SceneStroke;
  /** Dashed outlines are ghosts (nothing there yet); they fade in instead of drawing. */
  dashed?: boolean;
  /** Even-odd fill, for faces with a hole in them (the tray's rim, the lens). */
  ring?: boolean;
  /** Clipped to this outline (the inside of the tray). */
  clip?: string;
  /** Moves with the action's poses. */
  hero?: boolean;
}

type Vec3 = [number, number, number];

export interface SceneDef {
  shapes: SceneShape[];
  /** Where the hero part stands while the action runs and once it has worked, in tile units. */
  poses?: { pending?: Vec3; success?: Vec3 };
}

/** One tile unit in px. */
export const UNIT = 14;
const C = Math.cos(Math.PI / 6);
/** The drawing's box: the tile and everything that stands on it, same for every scene so the tile never moves. */
export const VIEW = { x: -78, y: -36, width: 156, height: 130 };

export const project = ([x, y, z]: Vec3): [number, number] => [
  (x - y) * C * UNIT,
  (x + y) * 0.5 * UNIT - z * UNIT,
];

const n = (v: number) => (Math.round(v * 100) / 100).toString();
const path = (points: Vec3[], close = true) =>
  points
    .map((p, i) => `${i ? "L" : "M"}${n(project(p)[0])} ${n(project(p)[1])}`)
    .join(" ") + (close ? " Z" : "");

type Style = {
  fills?: [SceneFill, SceneFill, SceneFill];
  stroke?: SceneStroke;
  dashed?: boolean;
  hero?: boolean;
};

/** The three faces you can see of an upright box: the left-front, the right-front and the top. */
function box(
  x: number,
  y: number,
  z: number,
  w: number,
  d: number,
  h: number,
  style: Style = {},
): SceneShape[] {
  const [X, Y, Z] = [x + w, y + d, z + h];
  const [left, right, top] = style.fills ?? ["left", "right", "top"];
  const base = {
    stroke: style.stroke ?? "line",
    dashed: style.dashed,
    hero: style.hero,
  };
  return [
    {
      ...base,
      fill: left,
      d: path([
        [x, Y, z],
        [X, Y, z],
        [X, Y, Z],
        [x, Y, Z],
      ]),
    },
    {
      ...base,
      fill: right,
      d: path([
        [X, y, z],
        [X, Y, z],
        [X, Y, Z],
        [X, y, Z],
      ]),
    },
    {
      ...base,
      fill: top,
      d: path([
        [x, y, Z],
        [X, y, Z],
        [X, Y, Z],
        [x, Y, Z],
      ]),
    },
  ];
}

const line = (
  points: Vec3[],
  stroke: SceneStroke = "line",
  hero = false,
): SceneShape => ({ d: path(points, false), fill: "none", stroke, hero });

/** A circle standing upright and turned to face you (the plane x + y = constant), so it reads round. */
const facingCircle = (cx: number, cy: number, cz: number, r: number): Vec3[] =>
  Array.from({ length: 48 }, (_, i) => {
    const a = (i / 48) * Math.PI * 2;
    const u = (r * Math.cos(a)) / Math.SQRT2;
    return [cx + u, cy - u, cz + r * Math.sin(a)];
  });

/** The tile everything stands on, with a faint drafting grid. Drawn once; scenes change on top of it. */
export const TILE: SceneShape[] = [
  ...box(0, 0, -0.45, 6, 6, 0.45),
  ...[2, 4].flatMap((v) => [
    line(
      [
        [v, 0, 0],
        [v, 6, 0],
      ],
      "faint",
    ),
    line(
      [
        [0, v, 0],
        [6, v, 0],
      ],
      "faint",
    ),
  ]),
];

/** Nothing here yet: an open tray, and the first sheet waiting above it. */
function inbox(): SceneDef {
  const [x0, x1, top, floor, inset] = [1.3, 4.7, 0.8, 0.25, 0.3];
  const [i0, i1] = [x0 + inset, x1 - inset];
  const hole = path([
    [i0, i0, top],
    [i1, i0, top],
    [i1, i1, top],
    [i0, i1, top],
  ]);
  const outer = path([
    [x0, x0, top],
    [x1, x0, top],
    [x1, x1, top],
    [x0, x1, top],
  ]);
  const sheet: [number, number, number] = [2.0, 1.95, 2.05];
  const textTop = sheet[2] + 0.06;
  return {
    shapes: [
      ...box(x0, x0, 0, x1 - x0, x1 - x0, top).slice(0, 2),
      { d: `${outer} ${hole}`, fill: "top", stroke: "line", ring: true },
      {
        d: path([
          [i0, i0, floor],
          [i1, i0, floor],
          [i1, i1, floor],
          [i0, i1, floor],
        ]),
        fill: "hole",
        stroke: "faint",
        clip: hole,
      },
      {
        d: path([
          [i0, i0, top],
          [i0, i1, top],
          [i0, i1, floor],
          [i0, i0, floor],
        ]),
        fill: "right",
        stroke: "line",
        clip: hole,
      },
      {
        d: path([
          [i0, i0, top],
          [i1, i0, top],
          [i1, i0, floor],
          [i0, i0, floor],
        ]),
        fill: "left",
        stroke: "line",
        clip: hole,
      },
      ...box(sheet[0], sheet[1], sheet[2], 2.0, 2.5, 0.06, { hero: true }),
      ...[2.45, 2.95, 3.45].map((y, i) =>
        line(
          [
            [2.35, y, textTop],
            [i === 2 ? 3.1 : 3.65, y, textTop],
          ],
          "accent",
          true,
        ),
      ),
    ],
    // It hovers a little lower while the action runs, then lands on the rim.
    poses: { pending: [0, 0, -0.55], success: [0, 0, top - sheet[2]] },
  };
}

/** No results: a lens held over three empty result rows. */
function search(): SceneDef {
  const [cx, cy, cz, r, t] = [3.15, 2.85, 1.85, 1.3, 0.26];
  const outer = facingCircle(cx, cy, cz, r);
  const inner = facingCircle(cx, cy, cz, r - t);
  // The handle leaves the rim down and to the right, in the lens's own plane.
  const a = -0.95;
  const along = (d: number): Vec3 => {
    const u = (d * Math.cos(a)) / Math.SQRT2;
    return [cx + u, cy - u, cz + d * Math.sin(a)];
  };
  const side = (p: Vec3, w: number): Vec3 => {
    const u = (w * Math.cos(a + Math.PI / 2)) / Math.SQRT2;
    return [p[0] + u, p[1] - u, p[2] + w * Math.sin(a + Math.PI / 2)];
  };
  const [h0, h1] = [along(r - 0.05), along(r + 1.15)];
  const rows = [0.9, 2.35, 3.8].flatMap((y, i) =>
    box(0.9, y, 0, i === 2 ? 3.3 : 4.2, 1.05, 0.1, {
      fills: ["none", "none", "none"],
      stroke: "line",
      dashed: true,
    }),
  );
  return {
    shapes: [
      ...rows,
      {
        d: path([
          side(h0, 0.16),
          side(h1, 0.16),
          side(h1, -0.16),
          side(h0, -0.16),
        ]),
        fill: "right",
        stroke: "line",
        hero: true,
      },
      { d: path(inner), fill: "glass", stroke: "faint", hero: true },
      {
        d: `${path(outer)} ${path(inner)}`,
        fill: "left",
        stroke: "accent",
        ring: true,
        hero: true,
      },
    ],
    // The lens sweeps across the empty rows while a search runs again.
    poses: { pending: [-0.7, 0.7, 0] },
  };
}

/** All caught up: a thick check standing on a low platform, turned to face you. */
function done(): SceneDef {
  const [A, B, Cp] = [
    [-1.35, 1.95],
    [-0.45, 1.0],
    [1.7, 3.15],
  ] as [number, number][];
  const unit = (v: [number, number]): [number, number] => {
    const l = Math.hypot(v[0], v[1]);
    return [v[0] / l, v[1] / l];
  };
  const h = 0.26;
  const d1 = unit([B[0] - A[0], B[1] - A[1]]);
  const d2 = unit([Cp[0] - B[0], Cp[1] - B[1]]);
  const n1: [number, number] = [-d1[1], d1[0]];
  const n2: [number, number] = [-d2[1], d2[0]];
  const m0 = unit([n1[0] + n2[0], n1[1] + n2[1]]);
  const mLen = h / (m0[0] * n1[0] + m0[1] * n1[1]);
  const m: [number, number] = [m0[0] * mLen, m0[1] * mLen];
  // The outline in the check's own plane (u across, z up), with each edge's outward normal.
  const outline: [number, number][] = [
    [A[0] + n1[0] * h, A[1] + n1[1] * h],
    [B[0] + m[0], B[1] + m[1]],
    [Cp[0] + n2[0] * h, Cp[1] + n2[1] * h],
    [Cp[0] - n2[0] * h, Cp[1] - n2[1] * h],
    [B[0] - m[0], B[1] - m[1]],
    [A[0] - n1[0] * h, A[1] - n1[1] * h],
  ];
  const normals: [number, number][] = [
    n1,
    n2,
    d2,
    [-n2[0], -n2[1]],
    [-n1[0], -n1[1]],
    [-d1[0], -d1[1]],
  ];
  // Its plane is x + y = 6 through the platform's middle; the thickness runs toward you, so the faces that look up show.
  const at = (depth: number) =>
    outline.map(
      ([u, z]) =>
        [3 + u / Math.SQRT2 + depth, 3 - u / Math.SQRT2 + depth, z] as Vec3,
    );
  const [front, back] = [0.16, -0.16];
  const edge = (p: [number, number], q: [number, number]): Vec3[] => {
    const [pb, qb] = [at(back), at(back)];
    const [pf, qf] = [at(front), at(front)];
    const i = outline.indexOf(p);
    const j = outline.indexOf(q);
    return [pb[i], qb[j], qf[j], pf[i]];
  };
  const sides = outline
    .map((p, i) => ({
      p,
      q: outline[(i + 1) % outline.length],
      nrm: normals[i],
    }))
    .filter(({ nrm }) => nrm[1] > 0.02)
    .map(({ p, q }) => ({
      d: path(edge(p, q)),
      fill: "accent-side" as const,
      stroke: "accent" as const,
      hero: true,
    }));
  return {
    shapes: [
      ...box(1.3, 1.3, 0, 3.4, 3.4, 0.55),
      { d: path(at(back)), fill: "accent-side", stroke: "accent", hero: true },
      ...sides,
      { d: path(at(front)), fill: "accent", stroke: "accent", hero: true },
    ],
  };
}

/** Can't connect: a plug lying short of its socket, its cable loose on the tile. */
function offline(): SceneDef {
  const face = 2.2;
  const slot = (x: number) => ({
    d: path([
      [x, face, 0.8],
      [x + 0.2, face, 0.8],
      [x + 0.2, face, 1.2],
      [x, face, 1.2],
    ]),
    fill: "hole" as const,
    stroke: "line" as const,
  });
  const prong = (x: number) =>
    line(
      [
        [x, 3.9, 1.0],
        [x, 2.9, 1.0],
      ],
      "accent",
      true,
    );
  return {
    shapes: [
      ...box(3.1, 0.7, 0, 2.3, face - 0.7, 2.0),
      slot(3.75),
      slot(4.55),
      prong(3.85),
      prong(4.65),
      ...box(3.5, 3.9, 0, 1.5, 1.2, 1.6, { hero: true }),
      line(
        [
          [4.25, 5.1, 0.55],
          [4.25, 5.5, 0.03],
          [3.1, 5.6, 0.03],
          [2.0, 5.15, 0.03],
          [0.8, 5.4, 0.03],
        ],
        "line",
        true,
      ),
    ],
    // It slides toward the socket while you retry, and goes in when it works.
    poses: { pending: [0, -0.4, 0], success: [0, -0.72, 0] },
  };
}

/** No data yet: a chart's back wall with ghost bars waiting to be filled. */
function chart(): SceneDef {
  const wall = 0.8;
  return {
    shapes: [
      ...box(0.6, wall - 0.2, 0, 4.8, 0.2, 2.2),
      ...[0.75, 1.5].map((z) =>
        line(
          [
            [0.8, wall, z],
            [5.2, wall, z],
          ],
          "faint",
        ),
      ),
      ...[
        [0.9, 0.9],
        [2.05, 1.6],
        [3.2, 1.2],
        [4.35, 2.1],
      ].flatMap(([x, h]) =>
        box(x, 2.2, 0, 0.85, 0.85, h, {
          stroke: "line",
          dashed: true,
          hero: true,
        }),
      ),
    ],
    // Ghost bars rise a touch while the first data is fetched.
    poses: { pending: [0, 0, 0.3] },
  };
}

export const SCENES: Record<EmptyStateScene, () => SceneDef> = {
  inbox,
  search,
  done,
  offline,
  chart,
};

/** A pose in tile units, as a screen offset in px. */
export const poseOffset = ([x, y, z]: Vec3): [number, number] => [
  (x - y) * C * UNIT,
  (x + y) * 0.5 * UNIT - z * UNIT,
];

"use client";

import * as React from "react";
import { StatusButton, type ActionStatus } from "./status-button";
import { TextMorph } from "./text-morph";
import {
  EASE_OUT,
  EASE_SETTLE,
  INTERACTION_FOCUS,
  INTERACTION_PRESS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";
import {
  SCENES,
  TILE,
  VIEW,
  poseOffset,
  type EmptyStateScene,
  type SceneFill,
  type SceneShape,
  type SceneStroke,
} from "./empty-state-scenes";

export type { EmptyStateScene } from "./empty-state-scenes";

/* ─────────────────────────────────────────────────────────
 * EMPTY STATE: what a list says before there's anything in it
 *
 *   drawing   an isometric line drawing built in code on one tile,
 *             in the theme's own colours: it draws itself the first
 *             time it's seen, and when the state changes (nothing
 *             yet → no results → all done) the old object un-draws
 *             and the new one rises from the same tile
 *   action    the main action is a Status button, and the drawing
 *             acts it out: the first sheet lands in the tray, the
 *             plug goes into its socket, the lens sweeps the cards;
 *             if it throws, the piece springs back with a shake and
 *             the reason folds in under the buttons
 *   text      the title morphs letter by letter, the description
 *             cross-fades, and the height eases between them
 * ───────────────────────────────────────────────────────── */

export interface EmptyStateAction {
  label: string;
  /** Runs the action. Return a promise to show it running, then done; throw to say why it failed. */
  onAction?: () => unknown;
  /** Labels while it runs, once it worked and after it failed (Working, Done, Try again). */
  pendingLabel?: string;
  successLabel?: string;
  errorLabel?: string;
  /** Shown before the label while idle. */
  icon?: React.ReactNode;
}

export interface EmptyStateSecondaryAction {
  label: string;
  onAction?: () => void;
  /** A link instead of a button. */
  href?: string;
}

export interface EmptyStateProps {
  /** Which drawing: nothing yet (inbox), no results (search), all done, can't connect (offline) or no data (chart). */
  scene?: EmptyStateScene;
  /** Your own art in place of the drawing. */
  illustration?: React.ReactNode;
  title: string;
  description?: React.ReactNode;
  /** The main action, run as a Status button; or your own button. */
  action?: EmptyStateAction | React.ReactNode;
  /** A quieter second action, such as Clear filters or Learn more. */
  secondaryAction?: EmptyStateSecondaryAction;
  /** Anything under the text, such as suggested searches. */
  children?: React.ReactNode;
  className?: string;
}

const FILL: Record<SceneFill, string> = {
  top: "color-mix(in oklab, var(--foreground) 3%, var(--background))",
  left: "color-mix(in oklab, var(--foreground) 7%, var(--background))",
  right: "color-mix(in oklab, var(--foreground) 12%, var(--background))",
  hole: "color-mix(in oklab, var(--foreground) 16%, var(--background))",
  glass: "color-mix(in oklab, var(--primary) 7%, var(--background))",
  accent: "color-mix(in oklab, var(--primary) 16%, var(--background))",
  "accent-side": "color-mix(in oklab, var(--primary) 32%, var(--background))",
  none: "none",
};
const STROKE: Record<SceneStroke, string> = {
  line: "color-mix(in oklab, var(--foreground) 46%, var(--background))",
  faint: "color-mix(in oklab, var(--foreground) 20%, var(--background))",
  accent: "var(--primary)",
};

// Slightly longer than the path, so a drawn line never shows a cavemio gap where it closes.
const DASH = 1.02;
const DRAW_EASE = "cubic-bezier(0.65, 0, 0.35, 1)";

const isAction = (action: unknown): action is EmptyStateAction =>
  Boolean(action) &&
  typeof action === "object" &&
  !React.isValidElement(action) &&
  "label" in (action as object);

/** Lines draw themselves back to front, then their faces fill; ghosts fade in. */
function drawIn(root: Element, delay = 0) {
  root.querySelectorAll<SVGPathElement>("[data-shape]").forEach((el, i) => {
    const at = delay + Math.min(i * 34, 560);
    if (el.dataset.dashed) {
      el.animate([{ opacity: 0 }, { opacity: 1 }], {
        duration: 420,
        delay: at,
        easing: EASE_OUT,
        fill: "backwards",
      });
      return;
    }
    el.animate(
      [
        { strokeDashoffset: DASH, fillOpacity: 0 },
        { strokeDashoffset: 0, fillOpacity: 0, offset: 0.62 },
        { strokeDashoffset: 0, fillOpacity: 1 },
      ],
      { duration: 640, delay: at, easing: DRAW_EASE, fill: "backwards" },
    );
  });
}

/** The reverse, front to back and quicker: lines retract and faces empty. */
function drawOut(root: Element) {
  const shapes = [
    ...root.querySelectorAll<SVGPathElement>("[data-shape]"),
  ].reverse();
  shapes.forEach((el, i) => {
    const delay = Math.min(i * 14, 200);
    if (el.dataset.dashed) {
      el.animate([{ opacity: 1 }, { opacity: 0 }], {
        duration: 200,
        delay,
        easing: EASE_OUT,
        fill: "forwards",
      });
      return;
    }
    el.animate(
      [
        { strokeDashoffset: 0, fillOpacity: 1 },
        { strokeDashoffset: 0, fillOpacity: 0, offset: 0.35 },
        { strokeDashoffset: -DASH, fillOpacity: 0 },
      ],
      { duration: 340, delay, easing: DRAW_EASE, fill: "forwards" },
    );
  });
}

function Shape({ shape, clipId }: { shape: SceneShape; clipId?: string }) {
  const el = (
    <path
      data-shape=""
      data-dashed={shape.dashed ? "" : undefined}
      d={shape.d}
      fillRule={shape.ring ? "evenodd" : undefined}
      pathLength={shape.dashed ? undefined : 1}
      strokeDasharray={shape.dashed ? "2 2.5" : `${DASH} ${DASH}`}
      strokeLinejoin="round"
      strokeLinecap="round"
      strokeWidth={shape.stroke === "accent" && shape.fill === "none" ? 1.5 : 1}
      style={{ fill: FILL[shape.fill], stroke: STROKE[shape.stroke] }}
    />
  );
  return clipId ? <g clipPath={`url(#${clipId})`}>{el}</g> : el;
}

function Shapes({ shapes, id }: { shapes: SceneShape[]; id: string }) {
  const clips = [...new Set(shapes.flatMap((s) => (s.clip ? [s.clip] : [])))];
  return (
    <>
      {clips.length > 0 && (
        <defs>
          {clips.map((d, i) => (
            <clipPath key={d} id={`${id}-${i}`}>
              <path d={d} />
            </clipPath>
          ))}
        </defs>
      )}
      {shapes.map((shape, i) => (
        <Shape
          key={i}
          shape={shape}
          clipId={shape.clip ? `${id}-${clips.indexOf(shape.clip)}` : undefined}
        />
      ))}
    </>
  );
}

/** Plays its drawing in once `seen` (the first time on screen, or at once for a scene that replaces another). */
function useDrawIn(seen: boolean, reduced: boolean, delay: number) {
  const ref = React.useRef<SVGGElement>(null);
  const drawn = React.useRef(false);
  React.useLayoutEffect(() => {
    if (!seen || drawn.current) return;
    drawn.current = true;
    if (!reduced && ref.current) drawIn(ref.current, delay);
  }, [seen, reduced, delay]);
  return ref;
}

const Tile = React.memo(function Tile({
  seen,
  reduced,
  id,
}: {
  seen: boolean;
  reduced: boolean;
  id: string;
}) {
  const ref = useDrawIn(seen, reduced, 0);
  return (
    <g ref={ref}>
      <Shapes shapes={TILE} id={id} />
    </g>
  );
});

interface LayerProps {
  scene: EmptyStateScene;
  leaving: boolean;
  seen: boolean;
  reduced: boolean;
  status: ActionStatus;
  /** The first scene waits for the tile; later ones wait for the old one to start leaving. */
  delay: number;
  id: string;
  heroRef?: React.Ref<SVGGElement>;
}

const Layer = React.memo(function Layer({
  scene,
  leaving,
  seen,
  reduced,
  status,
  delay,
  id,
  heroRef,
}: LayerProps) {
  const def = React.useMemo(() => SCENES[scene](), [scene]);
  const ref = useDrawIn(seen, reduced, delay);

  React.useLayoutEffect(() => {
    if (leaving && !reduced && ref.current) drawOut(ref.current);
  }, [leaving, reduced, ref]);

  const pose =
    (status === "pending" && def.poses?.pending) ||
    (status === "success" && def.poses?.success) ||
    ([0, 0, 0] as [number, number, number]);
  const [dx, dy] = poseOffset(pose);
  const landing = status === "success";
  const base = def.shapes.filter((s) => !s.hero);
  const hero = def.shapes.filter((s) => s.hero);

  return (
    <g
      ref={ref}
      style={{
        opacity: leaving && reduced ? 0 : 1,
        transition: reduced ? "opacity 200ms linear" : undefined,
      }}
    >
      <Shapes shapes={base} id={`${id}-b`} />
      <g
        ref={heroRef}
        style={{
          transform: `translate(${dx}px, ${dy}px)`,
          transition: reduced
            ? "none"
            : `transform ${landing ? 620 : 520}ms ${landing ? EASE_SETTLE : EASE_OUT}`,
        }}
      >
        <Shapes shapes={hero} id={`${id}-h`} />
      </g>
    </g>
  );
});

/** Keeps the old content a moment so it can cross-fade out while the new one comes in, with the height eased between. */
function Swap({
  swapKey,
  reduced,
  children,
}: {
  swapKey: string;
  reduced: boolean;
  children: React.ReactNode;
}) {
  const [shown, setShown] = React.useState({ key: swapKey, node: children });
  const [prev, setPrev] = React.useState<{
    key: string;
    node: React.ReactNode;
  } | null>(null);
  if (swapKey !== shown.key) {
    setPrev(shown);
    setShown({ key: swapKey, node: children });
  }
  const inner = React.useRef<HTMLDivElement>(null);
  const [height, setHeight] = React.useState<number | null>(null);

  React.useEffect(() => {
    if (!prev) return;
    const timer = window.setTimeout(() => setPrev(null), 260);
    return () => window.clearTimeout(timer);
  }, [prev]);

  // The inner box is a new element for each description, so it's observed again after every swap.
  React.useLayoutEffect(() => {
    const el = inner.current;
    if (!el) return;
    const observer = new ResizeObserver(() =>
      setHeight((h) => (h === el.offsetHeight ? h : el.offsetHeight)),
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [shown.key]);

  return (
    <div
      className="relative w-full"
      style={{
        height: height ?? undefined,
        transition:
          reduced || height === null ? "none" : `height 380ms ${EASE_OUT}`,
      }}
    >
      {prev && !reduced && (
        <div
          key={prev.key}
          aria-hidden="true"
          className="pointer-events-none absolute inset-x-0 top-0 animate-[ui-empty-out_200ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
        >
          {prev.node}
        </div>
      )}
      <div
        ref={inner}
        key={shown.key}
        className={
          prev && !reduced
            ? "animate-[ui-empty-in_360ms_cubic-bezier(0.16,1,0.3,1)_80ms_backwards]"
            : undefined
        }
      >
        {children}
      </div>
    </div>
  );
}

export function EmptyState({
  scene = "inbox",
  illustration,
  title,
  description,
  action,
  secondaryAction,
  children,
  className = "",
}: EmptyStateProps) {
  const reduced = useInteractionReducedMotion();
  const id = React.useId().replace(/:/g, "");
  const rootRef = React.useRef<HTMLDivElement>(null);
  const heroRef = React.useRef<SVGGElement>(null);
  const [seen, setSeen] = React.useState(false);
  const [status, setStatus] = React.useState<ActionStatus>("idle");
  const [error, setError] = React.useState<string | null>(null);
  const [layers, setLayers] = React.useState([
    { key: 0, scene, leaving: false },
  ]);
  const [lastScene, setLastScene] = React.useState(scene);
  const [generation, setGeneration] = React.useState(0);
  const generationRef = React.useRef(generation);

  // A new scene: the old drawing starts leaving, the new one comes in over it, and the action starts over.
  if (scene !== lastScene) {
    setLastScene(scene);
    setLayers((prev) => [
      ...prev.filter((l) => !l.leaving).map((l) => ({ ...l, leaving: true })),
      { key: Math.max(...prev.map((l) => l.key)) + 1, scene, leaving: false },
    ]);
    setStatus("idle");
    setError(null);
    setGeneration((g) => g + 1);
  }

  React.useEffect(() => {
    generationRef.current = generation;
  }, [generation]);

  React.useEffect(() => {
    if (!layers.some((l) => l.leaving)) return;
    const timer = window.setTimeout(
      () => setLayers((prev) => prev.filter((l) => !l.leaving)),
      reduced ? 220 : 560,
    );
    return () => window.clearTimeout(timer);
  }, [layers, reduced]);

  // The drawing waits until it's on screen, so it's never played out of sight.
  React.useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (!entry.isIntersecting) return;
        setSeen(true);
        observer.disconnect();
      },
      { threshold: 0.25 },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  // The piece that acts the action out springs back with a shake when it fails.
  React.useEffect(() => {
    if (status !== "error" || reduced) return;
    heroRef.current?.animate(
      [
        { transform: "translateX(0)" },
        { transform: "translateX(-4px)" },
        { transform: "translateX(4px)" },
        { transform: "translateX(-2px)" },
        { transform: "translateX(0)" },
      ],
      { duration: 380, easing: "ease-out", composite: "add" },
    );
  }, [status, reduced]);

  const act = isAction(action) ? action : null;
  const run = async () => {
    if (!act?.onAction || status === "pending") return;
    const mine = generationRef.current;
    setStatus("pending");
    setError(null);
    try {
      await act.onAction();
      if (generationRef.current === mine) setStatus("success");
    } catch (reason) {
      if (generationRef.current !== mine) return;
      setStatus("error");
      setError(
        reason instanceof Error
          ? reason.message
          : typeof reason === "string"
            ? reason
            : null,
      );
    }
  };

  const descriptionKey =
    typeof description === "string" ? description : `${scene}:${title}`;
  const hasActions = Boolean(action || secondaryAction);
  const secondaryClass = `inline-flex h-9 cursor-pointer items-center rounded-full px-4 text-[13px] font-medium text-muted-foreground hover:bg-accent hover:text-foreground ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`;

  return (
    <div ref={rootRef} className={`@container w-full ${className}`}>
      <div className="flex flex-col items-center px-6 py-10 text-center @max-[22rem]:px-4 @max-[22rem]:py-7">
        <div
          className="mb-5 flex h-[140px] w-[168px] items-center justify-center @max-[22rem]:mb-4 @max-[22rem]:h-[110px] @max-[22rem]:w-[132px]"
          aria-hidden="true"
        >
          {illustration ?? (
            <svg
              viewBox={`${VIEW.x} ${VIEW.y} ${VIEW.width} ${VIEW.height}`}
              className="size-full overflow-visible"
              style={{ opacity: seen || reduced ? 1 : 0 }}
            >
              <Tile seen={seen || reduced} reduced={reduced} id={`${id}-t`} />
              {layers.map((layer) => (
                <Layer
                  key={layer.key}
                  scene={layer.scene}
                  leaving={layer.leaving}
                  seen={seen || reduced}
                  reduced={reduced}
                  status={layer.leaving ? "idle" : status}
                  delay={layer.key === 0 ? 260 : 160}
                  id={`${id}-${layer.key}`}
                  heroRef={layer.leaving ? undefined : heroRef}
                />
              ))}
            </svg>
          )}
        </div>

        <h3 className="max-w-full text-[15px] font-medium leading-6 tracking-[-0.01em] text-foreground">
          <TextMorph>{title}</TextMorph>
        </h3>
        {description !== undefined && (
          <div className="mt-1 w-full max-w-[36ch] text-[13.5px] leading-[1.55] text-muted-foreground">
            <Swap swapKey={descriptionKey} reduced={reduced}>
              {description}
            </Swap>
          </div>
        )}
        {children && (
          <div className="mt-4 flex w-full flex-wrap items-center justify-center gap-2">
            {children}
          </div>
        )}

        <div
          className="grid w-full"
          style={{
            gridTemplateRows: hasActions ? "1fr" : "0fr",
            transition: reduced
              ? "none"
              : `grid-template-rows 380ms ${EASE_OUT}`,
          }}
        >
          <div className="min-h-0 overflow-clip">
            <div className="flex flex-wrap items-center justify-center gap-2 pt-5">
              {act ? (
                <StatusButton
                  status={status}
                  icon={act.icon}
                  labels={{
                    idle: act.label,
                    pending: act.pendingLabel ?? "Working",
                    success: act.successLabel ?? "Done",
                    error: act.errorLabel ?? "Try again",
                  }}
                  onClick={run}
                />
              ) : (
                (action as React.ReactNode)
              )}
              {secondaryAction &&
                (secondaryAction.href ? (
                  <a
                    href={secondaryAction.href}
                    onClick={secondaryAction.onAction}
                    className={secondaryClass}
                  >
                    {secondaryAction.label}
                  </a>
                ) : (
                  <button
                    type="button"
                    onClick={secondaryAction.onAction}
                    className={secondaryClass}
                  >
                    {secondaryAction.label}
                  </button>
                ))}
            </div>
          </div>
        </div>

        <div
          className="grid w-full"
          style={{
            gridTemplateRows: error ? "1fr" : "0fr",
            transition: reduced
              ? "none"
              : `grid-template-rows 320ms ${EASE_OUT}`,
          }}
        >
          <div className="min-h-0 overflow-clip">
            <p
              role="alert"
              className="pt-3 text-[12.5px] text-red-600 dark:text-red-400"
            >
              {error}
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}

export default EmptyState;

"use client";

import * as React from "react";
import { TextMorph } from "./text-morph";
import {
  EASE_OUT,
  INTERACTION_FOCUS,
  INTERACTION_PRESS,
  interactionIcon,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * EXPANDING BUTTON GROUP: an icon toolbar that names what you point at
 *
 *   point    the action under the mouse (or keyboard focus) opens
 *            its label; the column eases from 0fr to 1fr while the
 *            text lifts out of a blur, so neighbours slide aside
 *            instead of jumping. Each change retargets mid-way.
 *   tap      on touch nothing hovers: a tap acts and opens the
 *            label for a moment, so you see what you pressed
 *   ask      items with `confirm` ask first: the label morphs to
 *            "Delete?" and the next press acts (3s, Esc or moving
 *            away cancels)
 *   done     items with `confirmLabel` answer in place: the icon
 *            gives way to a drawn check, the label morphs
 *
 * Hover follows real pointer movement only, so a label opening
 * under a still cursor never hands the hover to a neighbour.
 * ───────────────────────────────────────────────────────── */

export type ExpandingItemTone = "default" | "primary" | "danger";

export interface ExpandingButtonItem {
  id: string;
  label: string;
  icon: React.ReactNode;
  tone?: ExpandingItemTone;
  /** Ask before acting: the label morphs to this ("Delete?") and the next press runs onClick. */
  confirm?: string;
  /** Shown with a drawn check after the action runs ("Archived"). */
  confirmLabel?: string;
  onClick?: () => void;
  disabled?: boolean;
}

export interface ExpandingButtonGroupProps extends React.HTMLAttributes<HTMLDivElement> {
  items: ExpandingButtonItem[];
  /** The item that stays open while nothing is pointed at (controlled). */
  expandedId?: string | null;
  /** The item that stays open while nothing is pointed at. */
  defaultExpandedId?: string | null;
  /** sm: 24px buttons in a 32px bar. md: 28px buttons in a 36px bar. */
  size?: "sm" | "md";
  /** Accessible name of the toolbar. */
  label?: string;
}

const TONES: Record<ExpandingItemTone, { idle: string; open: string }> = {
  default: {
    idle: "text-muted-foreground hover:text-foreground",
    open: "bg-accent text-foreground",
  },
  primary: {
    idle: "text-muted-foreground hover:text-foreground",
    open: "bg-primary text-primary-foreground",
  },
  danger: {
    idle: "text-muted-foreground hover:text-red-600 dark:hover:text-red-400",
    open: "bg-red-500/10 text-red-600 shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_25%,transparent)] dark:text-red-400",
  },
};

const ASK_MS = 3000;
const DONE_MS = 1600;
const TAP_MS = 2400;

function Check({ drawn, reduced }: { drawn: boolean; reduced: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="none" className="size-full">
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition: reduced
            ? "none"
            : drawn
              ? `stroke-dashoffset 360ms ${EASE_OUT} 80ms`
              : "stroke-dashoffset 0ms linear 300ms",
        }}
      />
    </svg>
  );
}

export function ExpandingButtonGroup({
  items,
  expandedId,
  defaultExpandedId = null,
  size = "md",
  label = "Actions",
  className = "",
  onKeyDown,
  ...props
}: ExpandingButtonGroupProps) {
  const reduced = useInteractionReducedMotion();
  const groupRef = React.useRef<HTMLDivElement>(null);
  const [hoverId, setHoverId] = React.useState<string | null>(null);
  const [focusId, setFocusId] = React.useState<string | null>(null);
  const [tapId, setTapId] = React.useState<string | null>(null);
  const [askId, setAskId] = React.useState<string | null>(null);
  const [doneId, setDoneId] = React.useState<string | null>(null);
  const [tabStop, setTabStop] = React.useState<string | null>(null);
  const lastPoint = React.useRef({ x: NaN, y: NaN });
  const pointerType = React.useRef("mouse");

  const restId = expandedId !== undefined ? expandedId : defaultExpandedId;
  const openId = hoverId ?? focusId ?? askId ?? doneId ?? tapId ?? restId;
  const firstEnabled = items.find((item) => !item.disabled)?.id ?? null;
  const stop = items.some((item) => item.id === tabStop && !item.disabled)
    ? tabStop
    : firstEnabled;

  // Each transient state lets go on its own.
  React.useEffect(() => {
    if (!askId) return;
    const timer = window.setTimeout(() => setAskId(null), ASK_MS);
    return () => window.clearTimeout(timer);
  }, [askId]);
  React.useEffect(() => {
    if (!doneId) return;
    const timer = window.setTimeout(() => setDoneId(null), DONE_MS);
    return () => window.clearTimeout(timer);
  }, [doneId]);
  React.useEffect(() => {
    if (!tapId) return;
    const timer = window.setTimeout(() => setTapId(null), TAP_MS);
    return () => window.clearTimeout(timer);
  }, [tapId]);

  const point = (id: string | null) => {
    setHoverId(id);
    if (askId && id !== askId) setAskId(null);
  };

  // Hover follows movement, not boundary events: when a label opens under a still cursor,
  // the neighbour that slides beneath it doesn't steal the hover.
  const handlePointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    pointerType.current = e.pointerType;
    if (e.pointerType !== "mouse") return;
    if (e.clientX === lastPoint.current.x && e.clientY === lastPoint.current.y)
      return;
    lastPoint.current = { x: e.clientX, y: e.clientY };
    const el = (e.target as HTMLElement).closest<HTMLElement>(
      "[data-expanding-item]",
    );
    const item = el
      ? items.find((i) => i.id === el.dataset.expandingItem)
      : undefined;
    if (item && !item.disabled && item.id !== hoverId) point(item.id);
  };

  const handleClick = (item: ExpandingButtonItem) => {
    if (item.disabled) return;
    setTabStop(item.id);
    if (pointerType.current !== "mouse") setTapId(item.id);
    if (item.confirm && askId !== item.id) {
      setDoneId(null);
      setAskId(item.id);
      return;
    }
    setAskId(null);
    item.onClick?.();
    if (item.confirmLabel) setDoneId(item.id);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(e);
    if (e.key === "Escape" && askId) {
      e.preventDefault();
      setAskId(null);
      return;
    }
    const enabled = items.filter((item) => !item.disabled);
    const index = enabled.findIndex((item) => item.id === stop);
    let next = -1;
    if (e.key === "ArrowRight") next = (index + 1) % enabled.length;
    else if (e.key === "ArrowLeft")
      next = (index - 1 + enabled.length) % enabled.length;
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = enabled.length - 1;
    if (next < 0 || !enabled[next]) return;
    e.preventDefault();
    const id = enabled[next].id;
    setTabStop(id);
    groupRef.current
      ?.querySelector<HTMLElement>(`[data-expanding-item="${CSS.escape(id)}"]`)
      ?.focus();
  };

  const sm = size === "sm";
  const iconSize = sm ? 12 : 14;
  const announce = askId
    ? items.find((i) => i.id === askId)?.confirm
    : doneId
      ? items.find((i) => i.id === doneId)?.confirmLabel
      : undefined;

  return (
    <>
      <div
        ref={groupRef}
        role="toolbar"
        aria-label={label}
        onKeyDown={handleKeyDown}
        onPointerDown={(e) => (pointerType.current = e.pointerType)}
        onPointerMove={handlePointerMove}
        onPointerLeave={(e) => {
          // A lifted finger "leaves" too; only a mouse leaving ends the hover (and an open ask).
          if (e.pointerType !== "mouse") return;
          lastPoint.current = { x: NaN, y: NaN };
          point(null);
        }}
        onBlur={(e) => {
          if (groupRef.current?.contains(e.relatedTarget as Node)) return;
          setFocusId(null);
          setAskId(null);
        }}
        className={`relative inline-flex max-w-full select-none items-center gap-0.5 rounded-full bg-card p-1 text-foreground shadow-[inset_0_0_0_1px_var(--border)] ${className}`}
        {...props}
      >
        {items.map((item) => {
          const open = openId === item.id;
          const done = doneId === item.id;
          const tone = TONES[item.tone ?? "default"];
          const text = done
            ? (item.confirmLabel ?? item.label)
            : askId === item.id
              ? (item.confirm ?? item.label)
              : item.label;
          return (
            <button
              key={item.id}
              type="button"
              data-expanding-item={item.id}
              data-state={open ? "open" : "closed"}
              disabled={item.disabled}
              tabIndex={stop === item.id ? 0 : -1}
              onClick={() => handleClick(item)}
              onFocus={(e) => {
                setTabStop(item.id);
                // Keyboard focus opens the label; a tap's focus doesn't (the tap does).
                setFocusId(
                  e.currentTarget.matches(":focus-visible") ? item.id : null,
                );
              }}
              className={`relative inline-flex shrink-0 items-center rounded-full font-medium cursor-pointer disabled:cursor-default disabled:opacity-40 ${INTERACTION_PRESS} ${INTERACTION_FOCUS} ${
                sm ? "h-6 px-1.5 text-[12px]" : "h-7 px-[7px] text-[12.5px]"
              } ${open ? tone.open : tone.idle}`}
            >
              <span
                aria-hidden="true"
                className="relative shrink-0"
                style={{ width: iconSize, height: iconSize }}
              >
                <span
                  className="absolute inset-0 flex items-center justify-center [&_svg]:size-full"
                  style={interactionIcon(!done, reduced)}
                >
                  {item.icon}
                </span>
                <span
                  className={`absolute inset-0 ${item.tone === "primary" && open ? "" : "text-emerald-600 dark:text-emerald-400"}`}
                  style={interactionIcon(done, reduced)}
                >
                  <Check drawn={done} reduced={reduced} />
                </span>
              </span>
              {/* The label's column eases 0fr ↔ 1fr, so the button and its neighbours move as one. */}
              <span
                className="grid"
                style={{
                  gridTemplateColumns: open ? "1fr" : "0fr",
                  transition: reduced
                    ? "none"
                    : `grid-template-columns 400ms ${EASE_OUT}`,
                }}
              >
                <span className="min-w-0 overflow-hidden [clip-path:inset(-4px_0)]">
                  <span
                    className="block w-max whitespace-nowrap pl-1.5 pr-1"
                    style={{
                      opacity: open ? 1 : 0,
                      filter: open ? "blur(0px)" : "blur(4px)",
                      transform: open ? "none" : "translateX(-4px)",
                      transition: reduced
                        ? "none"
                        : open
                          ? `opacity 260ms ${EASE_OUT} 80ms, filter 260ms ${EASE_OUT} 80ms, transform 400ms ${EASE_OUT}`
                          : `opacity 140ms ${EASE_OUT}, filter 140ms ${EASE_OUT}, transform 300ms ${EASE_OUT}`,
                    }}
                  >
                    <TextMorph>{text}</TextMorph>
                  </span>
                </span>
              </span>
            </button>
          );
        })}
      </div>
      <span role="status" className="sr-only">
        {announce ?? ""}
      </span>
    </>
  );
}

export default ExpandingButtonGroup;

"use client";

import * as React from "react";
import { ArrowUpRight } from "lucide-react";
import { GalleryViewer } from "./gallery-viewer";
import { GalleryPicture, type GalleryImage } from "./gallery-picture";
import { INTERACTION_FOCUS } from "./imported-ui-interaction-motion";
import { NumberRoll } from "./number-roll";

export type { GalleryImage } from "./gallery-picture";

export interface ExpandingGalleryProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onSelect"
> {
  images: GalleryImage[];
  label?: string;
  onImageChange?: (image: GalleryImage | null) => void;
}

/** An image keeps its identity from the thumbnail to the viewer and back. */
export function ExpandingGallery({
  images,
  label = "Selected work",
  onImageChange,
  className = "",
  ...props
}: ExpandingGalleryProps) {
  const [selected, setSelected] = React.useState<string | null>(null);
  const frames = React.useRef(new Map<string, HTMLDivElement>());
  const triggers = React.useRef(new Map<string, HTMLButtonElement>());
  const [openingRect, setOpeningRect] = React.useState<DOMRect | null>(null);
  const index = images.findIndex((image) => image.id === selected);
  const visible = index >= 0;

  const select = (next: number) => {
    const image = images[next];
    if (!image) return;
    if (selected === null)
      setOpeningRect(
        frames.current.get(image.id)?.getBoundingClientRect() ?? null,
      );
    setSelected(image.id);
    onImageChange?.(image);
  };
  const close = () => {
    setSelected(null);
    setOpeningRect(null);
    onImageChange?.(null);
    // Focus returns to the thumbnail of the image you were on, including after browsing.
    triggers.current.get(selected ?? "")?.focus({ preventScroll: true });
  };

  return (
    <div className={`w-full text-foreground ${className}`} {...props}>
      <div className="mb-5 flex items-baseline justify-between gap-4">
        <span className="text-[13px] font-medium">{label}</span>
        <span className="font-mono text-[10px] uppercase tracking-[0.16em] text-muted-foreground">
          <NumberRoll
            value={images.length}
            format={{ minimumIntegerDigits: 2 }}
          />{" "}
          studies
        </span>
      </div>
      <div className="grid grid-cols-2 gap-x-3 gap-y-5 sm:gap-x-4">
        {images.map((image, i) => (
          <button
            key={image.id}
            type="button"
            aria-label={`Open ${image.title}`}
            aria-haspopup="dialog"
            ref={(el) => {
              if (el) triggers.current.set(image.id, el);
              else triggers.current.delete(image.id);
            }}
            onClick={() => select(i)}
            className={`group min-w-0 cursor-zoom-in rounded-2xl text-left ${INTERACTION_FOCUS}`}
          >
            <div
              ref={(el) => {
                if (el) frames.current.set(image.id, el);
                else frames.current.delete(image.id);
              }}
              className="relative overflow-hidden rounded-2xl bg-muted"
              style={{
                aspectRatio: `${Math.max(1, image.width)} / ${Math.max(1, image.height)}`,
                visibility:
                  visible && selected === image.id ? "hidden" : undefined,
              }}
            >
              <div className="size-full transition-transform duration-500 ease-out group-hover:scale-[1.025] motion-reduce:transform-none">
                <GalleryPicture key={image.src} image={image} />
              </div>
              <span className="absolute bottom-3 right-3 flex size-7 items-center justify-center rounded-full border border-border bg-background text-foreground opacity-0 transition-opacity group-hover:opacity-100 group-focus-visible:opacity-100 [@media(hover:none)]:opacity-100">
                <ArrowUpRight className="size-3.5" aria-hidden="true" />
              </span>
            </div>
            <span className="mt-2.5 flex items-baseline justify-between gap-2 px-0.5">
              <span className="truncate text-[12px] font-medium">
                {image.title}
              </span>
              <span className="font-mono text-[10px] text-muted-foreground">
                {String(i + 1).padStart(2, "0")}
              </span>
            </span>
            {image.meta && (
              <span className="mt-0.5 block truncate px-0.5 text-[11px] text-muted-foreground">
                {image.meta}
              </span>
            )}
          </button>
        ))}
      </div>
      {visible && (
        <GalleryViewer
          images={images}
          index={index}
          label={label}
          openingRect={openingRect}
          getOrigin={(id) => frames.current.get(id)}
          onSelect={select}
          onClose={close}
        />
      )}
    </div>
  );
}

