  EASE_THROW,
  INTERACTION_FOCUS,
  INTERACTION_PRESS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * FEEDBACK: the score that changes the question
 *
 *   ask       the lit surface holds the question and a scale
 *             (0–10, or five stars); a light along its top
 *             follows the score you're on
 *   score     the thumb is thrown to your score and the number
 *             rolls into the chip beside the question
 *   follow    the follow-up opens under it and fits the score:
 *             "What went wrong?" for a 3, "What do you love?" for
 *             a 9, each with its own quick tags; change band and
 *             the question and tags swap the way the score moved
 *   thanks    Send goes Sending → Sent, and the follow-up turns
 *             into the thanks with what you said
 *
 * Where it goes is yours: onSubmit gets { score, band, tags,
 * comment } and sends it to your API, a sheet or an analytics
 * tool. Throw an Error and its message shows under the button.
 * ───────────────────────────────────────────────────────── */

export type FeedbackBand = "low" | "mid" | "high";

export interface FeedbackPrompt {
  question: string;
  tags: string[];
}

export interface FeedbackAnswer {
  score: number;
  band: FeedbackBand;
  tags: string[];
  comment: string;
}

export interface FeedbackProps {
  question?: string;
  /** 0–10 (net promoter) or one to five stars. */
  scale?: "nps" | "stars";
  /** Words under each end of the scale. */
  ends?: [string, string];
  /** The follow-up for each band; defaults fit a product. */
  prompts?: Partial<Record<FeedbackBand, FeedbackPrompt>>;
  onSubmit: (answer: FeedbackAnswer) => Promise<unknown>;
  /** Shows a close button. */
  onDismiss?: () => void;
  className?: string;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const PROMPTS: Record<FeedbackBand, FeedbackPrompt> = {
  low: {
    question: "What went wrong?",
    tags: [
      "Too slow",
      "Hard to use",
      "Missing a feature",
      "Bugs",
      "Too expensive",
    ],
  },
  mid: {
    question: "What would make it a 10?",
    tags: ["Faster", "Easier to start", "More integrations", "Better docs"],
  },
  high: {
    question: "What do you love most?",
    tags: ["Speed", "Design", "Support", "Saves me time"],
  },
};
const NPS_ENDS: [string, string] = ["Not likely", "Very likely"];
const STAR_ENDS: [string, string] = ["Poor", "Great"];
const STAR_WORDS = ["Poor", "Fair", "Okay", "Good", "Great"];

const mix = (color: string, amount: number, into = "transparent") =>
  `color-mix(in oklab, ${color} ${amount}%, ${into})`;
const PANEL: React.CSSProperties = {
  backgroundColor: "var(--primary)",
  backgroundImage: `linear-gradient(175deg, transparent 35%, ${mix("black", 26)} 100%)`,
  boxShadow: `inset 0 1px 0 ${mix("var(--primary-foreground)", 36)}, inset 0 0 0 1px ${mix("var(--primary-foreground)", 12)}`,
};
const CARD: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, var(--card), ${mix("var(--card)", 95, "var(--foreground)")})`,
  boxShadow: `0 0 0 1px var(--border), inset 0 1px 0 ${mix("var(--background)", 85)}`,
};
const LIT: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, ${mix("var(--primary-foreground)", 16)}, transparent 60%)`,
  boxShadow: `inset 0 1px 0 ${mix("var(--primary-foreground)", 32)}, inset 0 0 0 1px ${mix("black", 10)}`,
};
const TRACK: React.CSSProperties = {
  background: mix("black", 16),
  boxShadow: `inset 0 1px 1px ${mix("black", 16)}, inset 0 0 0 1px ${mix("var(--primary-foreground)", 10)}`,
};

const bandOf = (scale: "nps" | "stars", s: number): FeedbackBand =>
  scale === "nps"
    ? s <= 6
      ? "low"
      : s <= 8
        ? "mid"
        : "high"
    : s <= 2
      ? "low"
      : s === 3
        ? "mid"
        : "high";
const RANK: Record<FeedbackBand, number> = { low: 0, mid: 1, high: 2 };

export function Feedback({
  question = "How likely are you to recommend us to a friend?",
  scale = "nps",
  ends,
  prompts,
  onSubmit,
  onDismiss,
  className = "",
}: FeedbackProps) {
  const reduced = useInteractionReducedMotion();
  const baseId = React.useId();
  const [score, setScore] = React.useState<number | null>(null);
  const [hover, setHover] = React.useState<number | null>(null);
  const [tags, setTags] = React.useState<string[]>([]);
  const [comment, setComment] = React.useState("");
  const [status, setStatus] = React.useState<ActionStatus>("idle");
  const [error, setError] = React.useState<string | null>(null);
  const [sent, setSent] = React.useState(false);
  const [ready, setReady] = React.useState(false);
  const tagsRef = React.useRef<HTMLDivElement>(null);
  const scaleRef = React.useRef<HTMLDivElement>(null);
  const followRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setReady(true));
    return () => cancelAnimationFrame(frame);
  }, []);

  const nps = scale === "nps";
  const values = nps
    ? Array.from({ length: 11 }, (_, i) => i)
    : [1, 2, 3, 4, 5];
  const [lo, hi] = ends ?? (nps ? NPS_ENDS : STAR_ENDS);
  const band = score === null ? null : bandOf(scale, score);
  const prompt = band
    ? {
        ...PROMPTS[band],
        ...(band === "mid" && !nps
          ? { question: "What would make it better?" }
          : {}),
        ...prompts?.[band],
      }
    : null;
  const shown = hover ?? score;
  const idx = shown === null ? -1 : values.indexOf(shown);
  const busy = status === "pending" || status === "success";

  // A new band brings its own question and tags in from the side the score moved.
  const lastBand = React.useRef<FeedbackBand | null>(null);
  React.useLayoutEffect(() => {
    const was = lastBand.current;
    lastBand.current = band;
    if (!band || !was || was === band || reduced) return;
    const dir = RANK[band] > RANK[was] ? 1 : -1;
    tagsRef.current
      ?.querySelectorAll<HTMLElement>("[data-tag], [data-prompt]")
      .forEach((el, i) =>
        el.animate(
          [
            {
              opacity: 0,
              transform: `translateX(${dir * 14}px)`,
              filter: "blur(4px)",
            },
            { opacity: 1, transform: "none", filter: "blur(0px)" },
          ],
          { duration: 380, delay: i * 35, easing: EASE, fill: "backwards" },
        ),
      );
  }, [band, reduced]);

  const pick = (s: number) => {
    if (busy || sent) return;
    if (score === null)
      window.setTimeout(
        () =>
          followRef.current?.scrollIntoView({
            block: "nearest",
            behavior: reduced ? "auto" : "smooth",
          }),
        420,
      );
    if (score !== null && bandOf(scale, s) !== band) setTags([]);
    setScore(s);
    setError(null);
    if (status === "error") setStatus("idle");
  };

  const submit = async () => {
    if (score === null || !band || busy) return;
    setStatus("pending");
    setError(null);
    try {
      await onSubmit({ score, band, tags, comment: comment.trim() });
      setStatus("success");
      window.setTimeout(() => setSent(true), reduced ? 300 : 650);
    } catch (e) {
      setStatus("error");
      setError(
        e instanceof Error && e.message
          ? e.message
          : "Couldn’t send that. Try again.",
      );
    }
  };

  const onScaleKey = (e: React.KeyboardEvent<HTMLDivElement>) => {
    const i = Math.max(0, score === null ? -1 : values.indexOf(score));
    let next = -1;
    if (e.key === "ArrowRight" || e.key === "ArrowUp")
      next = Math.min(values.length - 1, score === null ? 0 : i + 1);
    else if (e.key === "ArrowLeft" || e.key === "ArrowDown")
      next = Math.max(0, score === null ? 0 : i - 1);
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = values.length - 1;
    else if (/^[0-9]$/.test(e.key) && values.includes(Number(e.key)))
      next = values.indexOf(Number(e.key));
    if (next < 0) return;
    e.preventDefault();
    pick(values[next]);
    scaleRef.current
      ?.querySelector<HTMLElement>(`[data-value="${values[next]}"]`)
      ?.focus();
  };

  // The light along the panel's top sits over the score you're on.
  const glow = idx < 0 ? 0.5 : (idx + 0.5) / values.length;

  return (
    <section
      aria-labelledby={`${baseId}-q`}
      className={`w-full max-w-[400px] rounded-[28px] p-2 text-card-foreground ${className}`}
      style={CARD}
    >
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 400px)" }}
      />
      <div className="@container w-full">
        {/* The one lit surface: the question and its scale. */}
        <div
          className="relative overflow-clip rounded-[22px] p-4 text-primary-foreground"
          style={PANEL}
        >
          <span
            aria-hidden="true"
            className="pointer-events-none absolute inset-0"
            style={{
              transform: `translateX(${(glow - 0.5) * 100}%)`,
              transition: reduced ? "none" : `transform 620ms ${EASE}`,
            }}
          >
            <span
              className="absolute inset-x-[-30%] -top-1/2 h-full"
              style={{
                background: `radial-gradient(50% 60% at 50% 50%, ${mix("var(--primary-foreground)", score === null ? 18 : 30)}, transparent 70%)`,
                transition: "background 400ms",
              }}
            />
          </span>

          <div className="relative flex items-start gap-3">
            <h2
              id={`${baseId}-q`}
              className="min-w-0 flex-1 pt-0.5 text-[15px] font-medium leading-snug tracking-[-0.01em]"
            >
              {question}
            </h2>
            <span
              aria-hidden="true"
              className="flex h-12 min-w-12 shrink-0 items-center justify-center rounded-[14px] px-2 text-[26px] font-medium leading-none tracking-[-0.04em] tabular-nums"
              style={TRACK}
            >
              {shown === null ? (
                <span className="text-primary-foreground/40">?</span>
              ) : (
                <NumberRoll value={shown} duration={700} />
              )}
            </span>
            {onDismiss && (
              <button
                type="button"
                aria-label="Close"
                onClick={onDismiss}
                className={`-mr-1.5 -mt-1 flex size-7 shrink-0 cursor-pointer items-center justify-center rounded-full text-primary-foreground/70 hover:bg-primary-foreground/10 hover:text-primary-foreground ${INTERACTION_PRESS}`}
              >
                <X aria-hidden="true" className="size-4" />
              </button>
            )}
          </div>

          <div
            ref={scaleRef}
            role="radiogroup"
            aria-labelledby={`${baseId}-q`}
            onKeyDown={onScaleKey}
            onPointerLeave={() => setHover(null)}
            className={`relative mt-3.5 grid rounded-full p-1 ${nps ? "h-10" : "h-11"}`}
            style={{
              ...TRACK,
              gridTemplateColumns: `repeat(${values.length}, minmax(0, 1fr))`,
            }}
          >
            {nps && (
              <span
                aria-hidden="true"
                className="pointer-events-none absolute bottom-1 left-1 top-1 rounded-full"
                style={{
                  width: `calc((100% - 8px) / ${values.length})`,
                  background: "var(--primary-foreground)",
                  boxShadow: `0 1px 0 ${mix("black", 14)}`,
                  opacity:
                    idx < 0 ? 0 : hover !== null && hover !== score ? 0.55 : 1,
                  transform: `translateX(${Math.max(0, idx) * 100}%)`,
                  transition:
                    reduced || !ready
                      ? "opacity 160ms"
                      : `transform 460ms ${EASE_THROW}, opacity 200ms`,
                }}
              />
            )}
            {values.map((v, i) => {
              const on = v === score;
              const filled = !nps && shown !== null && v <= shown;
              return (
                <button
                  key={v}
                  type="button"
                  role="radio"
                  data-value={v}
                  aria-checked={on}
                  aria-label={
                    nps
                      ? String(v)
                      : `${v} ${v === 1 ? "star" : "stars"}, ${STAR_WORDS[v - 1]}`
                  }
                  tabIndex={on || (score === null && i === 0) ? 0 : -1}
                  disabled={sent}
                  onClick={() => pick(v)}
                  onPointerMove={(e) =>
                    e.pointerType === "mouse" && hover !== v && setHover(v)
                  }
                  className={`relative z-10 flex cursor-pointer items-center justify-center rounded-full text-[13px] font-medium tabular-nums outline-none focus-visible:ring-2 focus-visible:ring-primary-foreground/70 disabled:cursor-default ${INTERACTION_PRESS}`}
                  style={{
                    color:
                      nps && (hover ?? score) === v
                        ? "var(--primary)"
                        : undefined,
                    transition: "color 200ms",
                  }}
                >
                  {nps ? (
                    <span
                      className={
                        on || hover === v ? "" : "text-primary-foreground/80"
                      }
                    >
                      {v}
                    </span>
                  ) : (
                    <Star
                      aria-hidden="true"
                      className="size-[22px]"
                      strokeWidth={1.6}
                      style={{
                        fill: filled
                          ? "var(--primary-foreground)"
                          : "transparent",
                        color: filled
                          ? "var(--primary-foreground)"
                          : mix("var(--primary-foreground)", 55),
                        transform: filled && !reduced ? "scale(1.08)" : "none",
                        transition: reduced
                          ? "none"
                          : `fill 220ms ${EASE} ${i * 40}ms, color 220ms ${EASE} ${i * 40}ms, transform 360ms ${EASE_THROW} ${i * 40}ms`,
                      }}
                    />
                  )}
                </button>
              );
            })}
          </div>
          <div className="relative mt-1.5 flex justify-between px-1 text-[11.5px] text-primary-foreground/65">
            <span>{lo}</span>
            {!nps && shown !== null && (
              <span className="text-primary-foreground/90">
                <TextMorph>{STAR_WORDS[shown - 1]}</TextMorph>
              </span>
            )}
            <span>{hi}</span>
          </div>
        </div>

        {/* Flat: the follow-up that fits the score, then the thanks. */}
        <div
          className="grid"
          style={{
            gridTemplateRows: score === null ? "0fr" : "1fr",
            opacity: score === null ? 0 : 1,
            transition: reduced
              ? "opacity 160ms"
              : `grid-template-rows 460ms ${EASE}, opacity 320ms ${EASE} 80ms`,
          }}
        >
          <div
            ref={followRef}
            className="min-h-0 overflow-clip"
            inert={score === null || undefined}
          >
            <Faces active={sent ? 1 : 0} reduced={reduced} ready={ready}>
              <form
                className="px-2 pb-1 pt-3"
                onSubmit={(e) => {
                  e.preventDefault();
                  void submit();
                }}
              >
                <div ref={tagsRef}>
                  <p
                    data-prompt
                    className="px-1 text-[14px] font-medium tracking-[-0.01em]"
                  >
                    {prompt?.question}
                  </p>
                  <div
                    role="group"
                    aria-label={prompt?.question}
                    className="mt-2 flex flex-wrap gap-1.5"
                  >
                    {prompt?.tags.map((t) => {
                      const on = tags.includes(t);
                      return (
                        <button
                          key={`${band}-${t}`}
                          data-tag
                          type="button"
                          aria-pressed={on}
                          disabled={busy}
                          onClick={() =>
                            setTags((list) =>
                              on ? list.filter((x) => x !== t) : [...list, t],
                            )
                          }
                          className={`inline-flex h-8 cursor-pointer items-center rounded-full px-3 text-[12.5px] disabled:cursor-default ${INTERACTION_PRESS} ${INTERACTION_FOCUS} ${
                            on
                              ? "bg-primary/[0.08] font-medium text-primary shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--primary)_40%,transparent)]"
                              : "text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent"
                          }`}
                        >
                          <span
                            className="grid"
                            style={{
                              gridTemplateColumns: on ? "1fr" : "0fr",
                              transition: reduced
                                ? "none"
                                : `grid-template-columns 300ms ${EASE}`,
                            }}
                          >
                            <span className="min-w-0 overflow-hidden">
                              <Check
                                aria-hidden="true"
                                className="mr-1 size-3.5"
                                strokeWidth={2.5}
                              />
                            </span>
                          </span>
                          {t}
                        </button>
                      );
                    })}
                  </div>
                </div>
                <Textarea
                  aria-label="Anything else?"
                  value={comment}
                  onValueChange={setComment}
                  disabled={busy}
                  placeholder="Anything else? (optional)"
                  minRows={2}
                  maxRows={5}
                  maxLength={1000}
                  showCount={false}
                  className="mt-2.5"
                />
                <StatusButton
                  type="submit"
                  status={status}
                  labels={{
                    idle: "Send feedback",
                    pending: "Sending",
                    success: "Sent",
                    error: "Try again",
                  }}
                  className="mt-2.5 h-11 w-full text-[14.5px]"
                  style={status === "error" ? undefined : LIT}
                />
                {error && (
                  <p
                    role="alert"
                    className="mt-1.5 text-center text-[12px] text-red-600 dark:text-red-400"
                  >
                    {error}
                  </p>
                )}
              </form>

              <div
                className="flex items-start gap-3 px-3 pb-2 pt-4"
                role="status"
              >
                <span className="flex size-9 shrink-0 items-center justify-center rounded-full bg-primary/10 text-primary">
                  <svg
                    viewBox="0 0 16 16"
                    fill="none"
                    className="size-4"
                    aria-hidden="true"
                  >
                    <path
                      d="M3.5 8.5 6.5 11.5 12.5 4.5"
                      stroke="currentColor"
                      strokeWidth="2"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      pathLength={1}
                      strokeDasharray={1}
                      style={{
                        strokeDashoffset: sent ? 0 : 1,
                        transition:
                          sent && !reduced
                            ? `stroke-dashoffset 460ms ${EASE} 240ms`
                            : "none",
                      }}
                    />
                  </svg>
                </span>
                <div className="min-w-0">
                  <p className="text-[14.5px] font-medium tracking-[-0.01em]">
                    {sent ? "Thanks, that helps." : ""}
                  </p>
                  <p className="mt-0.5 text-[12.5px] text-muted-foreground">
                    {sent && score !== null
                      ? `You gave ${nps ? score : `${score} of 5`}${tags.length ? ` · ${tags.join(", ")}` : ""}`
                      : ""}
                  </p>
                </div>
              </div>
            </Faces>
          </div>
        </div>
      </div>
    </section>
  );
}

export default Feedback;

/* Fetch's art: a golden retriever puppy sitting, sniffing, running, and back with a newspaper or a stick. Each clip is a strip of square frames cut from a generated animation, keyed to
 * transparent WebP; every clip shares one crop, so frames line up across clips. As data URIs so
 * one install brings everything. */

export const FETCH_ART = {
  sit: "data:image/webp;base64,",
  sniff:
    "data:image/webp;base64,",
  run: "data:image/webp;base64,",
  paper:
    "data:image/webp;base64,",
  stick:
    "data:image/webp;base64,",
};

export const FETCH_FRAMES = {
  /** One frame, in image px. */
  w: 150,
  h: 150,
  clips: {
    sit: { frames: 10, fps: 8 },
    sniff: { frames: 5, fps: 10 },
    run: { frames: 7, fps: 15 },
    paper: { frames: 10, fps: 8 },
    stick: { frames: 10, fps: 8 },
  },
} as const;

"use client";

import * as React from "react";
import { playStrip, preloadStrips } from "./cast-sprite";
import { FETCH_ART as ART, FETCH_FRAMES as F } from "./fetch-art";

/* ─────────────────────────────────────────────────────────
 * FETCH: the puppy who fetches your search
 *
 * Fetch is animated: each state is a loop of frames cut from
 * a generated animation, played in code.
 *
 *   sit      waiting: panting, tail wagging, a head tilt
 *   sniff    nose to the ground while you type
 *   go       a search starts: he gallops off the right edge
 *   back     the answer is in: he gallops back in and sits,
 *            wagging proudly with a newspaper (results) or
 *            looking sheepish with a stick (none)
 *
 * The scene is drawn at 364 × 168 and scaled to the stage.
 * Loops are Web Animations (no frame loop); one rAF loop moves
 * him across the stage only while he runs.
 * ───────────────────────────────────────────────────────── */

export type FetchCarry = "paper" | "stick" | "sit";

export interface FetchHandle {
  sniff: () => void;
  /** Off to fetch. */
  go: () => void;
  /** Back with what he found. */
  back: (carry: FetchCarry) => void;
}

type Clip = keyof typeof F.clips;

const W = 364;
const H = 168;
const FRAME = 124; // one frame on the stage
const HOME = 96; // the middle of the frame when he sits
const AWAY = W + 110;
const OUT_MS = 520;
const IN_MS = 700;

const clamp = (v: number, a = 0, b = 1) => Math.min(b, Math.max(a, v));
const easeIn = (k: number) => k * k;
const easeOut = (k: number) => 1 - Math.pow(1 - k, 3);

export class FetchEngine {
  parts: Record<string, Element | null> = {};
  reduced = false;
  leg: "home" | "out" | "away" | "in" = "home";
  t0 = 0;
  carry: FetchCarry = "sit";
  pending: FetchCarry | null = null;
  clip: Clip | null = null;
  sniffTimer = 0;
  raf = 0;
  observer: ResizeObserver | null = null;
  frame = (now: number) => this.tick(now);

  part = (name: string) => (el: Element | null) => {
    this.parts[name] = el;
  };

  mount(reduced: boolean) {
    this.reduced = reduced;
    const host = this.parts.host as HTMLElement | null;
    const scene = this.parts.scene as HTMLElement | null;
    if (host && scene) {
      const fit = () =>
        scene.style.setProperty("transform", `scale(${host.clientWidth / W})`);
      fit();
      this.observer = new ResizeObserver(fit);
      this.observer.observe(host);
    }
    preloadStrips(Object.values(ART));
    this.play("sit");
    this.place(HOME, 1);
  }

  destroy() {
    cancelAnimationFrame(this.raf);
    window.clearTimeout(this.sniffTimer);
    this.raf = 0;
    this.observer?.disconnect();
    this.observer = null;
    (this.parts.sprite as HTMLElement | null)
      ?.getAnimations()
      .forEach((a) => a.cancel());
  }

  play(clip: Clip) {
    if (this.clip === clip) return;
    this.clip = clip;
    playStrip(this.parts.sprite as HTMLElement | null, {
      src: ART[clip],
      frames: F.clips[clip].frames,
      fps: F.clips[clip].fps,
      size: FRAME,
      reduced: this.reduced,
    });
  }

  place(x: number, flip: number) {
    (this.parts.dog as HTMLElement | null)?.style.setProperty(
      "transform",
      `translateX(${(x - FRAME / 2).toFixed(1)}px) scaleX(${flip})`,
    );
  }

  sniff() {
    if (this.leg !== "home") return;
    this.play("sniff");
    window.clearTimeout(this.sniffTimer);
    this.sniffTimer = window.setTimeout(
      () => this.leg === "home" && this.play(this.carry),
      800,
    );
  }

  go() {
    window.clearTimeout(this.sniffTimer);
    this.pending = null;
    if (this.leg === "out" || this.leg === "away") return;
    if (this.reduced) {
      this.leg = "away";
      return;
    }
    this.leg = "out";
    this.t0 = performance.now();
    this.play("run");
    this.wake();
  }

  back(carry: FetchCarry) {
    if (this.leg === "home" || this.reduced) {
      this.leg = "home";
      this.carry = carry;
      this.play(carry);
      this.place(HOME, 1);
      return;
    }
    // still on his way out: he turns round once he's off the stage
    this.pending = carry;
    if (this.leg === "away") this.turn(performance.now());
    this.wake();
  }

  turn(now: number) {
    if (this.pending === null) return;
    this.carry = this.pending;
    this.pending = null;
    this.leg = "in";
    this.t0 = now;
    this.play("run");
  }

  wake() {
    if (this.raf || !this.parts.dog) return;
    this.raf = requestAnimationFrame(this.frame);
  }

  tick(now: number) {
    const t = now - this.t0;
    let busy = true;
    if (this.leg === "out") {
      this.place(HOME + (AWAY - HOME) * easeIn(clamp(t / OUT_MS)), 1);
      if (t >= OUT_MS) {
        this.leg = "away";
        this.turn(now);
      }
    } else if (this.leg === "in") {
      this.place(HOME + (AWAY - HOME) * (1 - easeOut(clamp(t / IN_MS))), -1);
      if (t >= IN_MS) {
        this.leg = "home";
        this.place(HOME, 1);
        this.play(this.carry);
        busy = false;
      }
    } else busy = false;
    this.raf = busy ? requestAnimationFrame(this.frame) : 0;
  }
}

export function Fetch({
  reduced,
  ref,
  children,
  className = "",
}: {
  reduced: boolean;
  ref?: React.Ref<FetchHandle>;
  children?: React.ReactNode;
  className?: string;
}) {
  const [engine] = React.useState(() => new FetchEngine());

  React.useLayoutEffect(() => {
    engine.mount(reduced);
    return () => engine.destroy();
  }, [engine, reduced]);

  React.useImperativeHandle(
    ref,
    () => ({
      sniff: () => engine.sniff(),
      go: () => engine.go(),
      back: (c) => engine.back(c),
    }),
    [engine],
  );

  return (
    <div
      ref={engine.part("host")}
      aria-hidden="true"
      className={`relative w-full ${className}`}
      style={{ aspectRatio: `${W} / ${H}` }}
    >
      <div
        ref={engine.part("scene")}
        className="absolute left-0 top-0 origin-top-left"
        style={{ width: W, height: H }}
      >
        {children}
        <div
          ref={engine.part("dog")}
          className="absolute left-0 will-change-transform"
          style={{ top: 154 - FRAME, width: FRAME, height: FRAME }}
        >
          <div ref={engine.part("sprite")} className="size-full" />
        </div>
      </div>
    </div>
  );
}

export default Fetch;

"use client";

import * as React from "react";
import { EASE_OUT, useInteractionReducedMotion } from "./ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * FIELD: the column every text control sits in
 *
 *   label    above, with an optional aside on the right (a count)
 *   hint     under the control while all is well
 *   error    takes the hint's place: the hint folds away, the
 *            error rises in out of a blur, the control shakes once
 *
 * Shared by input, textarea, password, search and select so the
 * whole family has one surface, one focus ring and one error.
 * ───────────────────────────────────────────────────────── */

export interface FieldProps {
  id: string;
  label?: React.ReactNode;
  /** Right side of the label row, e.g. a character count. */
  aside?: React.ReactNode;
  hint?: React.ReactNode;
  error?: React.ReactNode;
  required?: boolean;
  className?: string;
  children: React.ReactNode;
}

export type FieldSize = "sm" | "md";

/** The surface of a text control: a thin line that darkens on hover and turns to the ring on focus. */
export function fieldSurface({
  invalid,
  disabled,
  round = true,
}: {
  invalid?: boolean;
  disabled?: boolean;
  round?: boolean;
}) {
  const ring = invalid
    ? "shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_55%,transparent)] focus-within:shadow-[inset_0_0_0_1px_var(--color-red-500),0_0_0_3px_color-mix(in_oklab,var(--color-red-500)_14%,transparent)]"
    : "shadow-[inset_0_0_0_1px_var(--border)] [&:not(:focus-within)]:hover:shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--foreground)_24%,var(--border))] focus-within:shadow-[inset_0_0_0_1px_var(--ring),0_0_0_3px_color-mix(in_oklab,var(--ring)_16%,transparent)]";
  return `relative flex w-full items-center bg-background text-foreground transition-[box-shadow,background-color,opacity] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] ${round ? "rounded-full" : "rounded-[14px]"} ${ring} ${
    disabled ? "pointer-events-none opacity-50" : ""
  }`;
}

/** ids for the control's label, hint and error. */
export function useFieldIds(id?: string) {
  const auto = React.useId();
  const base = id ?? auto;
  return { id: base, hint: `${base}-hint`, error: `${base}-error` };
}

/** One short shake whenever `on` turns true (an error arrives). */
export function useShake<T extends HTMLElement>(on: boolean) {
  const ref = React.useRef<T>(null);
  const reduced = useInteractionReducedMotion();
  React.useEffect(() => {
    if (!on || reduced) return;
    ref.current?.animate(
      [
        { transform: "none" },
        { transform: "translateX(-4px)" },
        { transform: "translateX(4px)" },
        { transform: "translateX(-2px)" },
        { transform: "none" },
      ],
      { duration: 380, easing: "ease-out" },
    );
  }, [on, reduced]);
  return ref;
}

/** Sets a native input's value so React's onChange still fires (clear buttons, pickers). */
export function setNativeValue(
  el: HTMLInputElement | HTMLTextAreaElement,
  value: string,
) {
  const proto =
    el instanceof HTMLTextAreaElement
      ? HTMLTextAreaElement.prototype
      : HTMLInputElement.prototype;
  Object.getOwnPropertyDescriptor(proto, "value")?.set?.call(el, value);
  el.dispatchEvent(new Event("input", { bubbles: true }));
}

/** A line under the control that folds open and closed; keeps its last words while closing. */
function Line({
  show,
  children,
  id,
  tone,
  reduced,
}: {
  show: boolean;
  children: React.ReactNode;
  id: string;
  tone: string;
  reduced: boolean;
}) {
  const [kept, setKept] = React.useState(children);
  if (show && children !== kept) setKept(children);
  return (
    <div
      className="grid"
      style={{
        gridTemplateRows: show ? "1fr" : "0fr",
        transition: reduced ? "none" : `grid-template-rows 320ms ${EASE_OUT}`,
      }}
    >
      <div className="min-h-0 overflow-hidden">
        <p
          id={id}
          className={`pt-1.5 pl-3 text-[12.5px] leading-snug ${tone}`}
          style={{
            opacity: show ? 1 : 0,
            filter: show ? "blur(0px)" : "blur(4px)",
            transform: show ? "none" : "translateY(-4px)",
            transition: reduced
              ? "none"
              : show
                ? `opacity 280ms ${EASE_OUT} 60ms, filter 280ms ${EASE_OUT} 60ms, transform 380ms ${EASE_OUT}`
                : `opacity 140ms ${EASE_OUT}, filter 140ms ${EASE_OUT}, transform 200ms ${EASE_OUT}`,
          }}
        >
          {show ? children : kept}
        </p>
      </div>
    </div>
  );
}

export function Field({
  id,
  label,
  aside,
  hint,
  error,
  required,
  className = "",
  children,
}: FieldProps) {
  const reduced = useInteractionReducedMotion();
  const ids = { hint: `${id}-hint`, error: `${id}-error` };
  return (
    <div className={`flex w-full flex-col ${className}`}>
      {(label || aside) && (
        <div className="flex items-baseline justify-between gap-3 px-3 pb-1.5">
          {label && (
            <label
              htmlFor={id}
              className="text-[13px] font-medium text-foreground"
            >
              {label}
              {required && (
                <span
                  aria-hidden="true"
                  className="ml-0.5 text-muted-foreground"
                >
                  *
                </span>
              )}
            </label>
          )}
          {aside && (
            <span className="text-[12px] tabular-nums text-muted-foreground">
              {aside}
            </span>
          )}
        </div>
      )}
      {children}
      <Line
        show={!error && !!hint}
        id={ids.hint}
        tone="text-muted-foreground"
        reduced={reduced}
      >
        {hint}
      </Line>
      <Line
        show={!!error}
        id={ids.error}
        tone="text-red-600 dark:text-red-400"
        reduced={reduced}
      >
        {error}
      </Line>
    </div>
  );
}

export default Field;

"use client";

import * as React from "react";
import { Lock, RotateCw, Upload, X } from "lucide-react";
import { CopyButton } from "./copy-button";
import { Faces } from "./faces";
import { Input } from "./input";
import { NumberRoll } from "./number-roll";
import { SegmentedControl } from "./segmented-control";
import { StatusButton, type ActionStatus } from "./status-button";
import { Switch } from "./switch";
import { TextMorph } from "./text-morph";
import {
  INTERACTION_FOCUS,
  INTERACTION_PRESS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * FILE SHARE: files that fold into one link
 *
 *   drop      the lit panel is the drop area; dragging files over
 *             it brightens its edge and says how many will land
 *   upload    each file uploads as soon as it's added, its row
 *             filling with a thin line and rolling its percent;
 *             a failed one offers Retry, a removed one is aborted
 *   options   how long the link lives, and an optional password
 *   link      Create link goes Creating → the rows fly up into the
 *             panel, which turns into the link card: the URL with
 *             Copy, what's in it, and the files fanned as a stack
 *
 * Storage is yours: onUpload sends one file (report progress and
 * honour the signal), onCreateLink makes the link from what your
 * uploads returned. Throw an Error and its message shows in place.
 * ───────────────────────────────────────────────────────── */

export interface FileShareUploadContext {
  /** Report progress from 0 to 1. */
  onProgress: (fraction: number) => void;
  /** Aborted when the file is removed. */
  signal: AbortSignal;
}

export interface FileShareFile {
  name: string;
  size: number;
  type: string;
  /** Whatever onUpload resolved with for this file, e.g. its storage key. */
  result: unknown;
}

export interface FileShareRequest {
  files: FileShareFile[];
  /** Days the link lives. */
  expiresIn: number;
  password?: string;
}

export interface FileShareHandle {
  /** Add files from anywhere: a paste handler, a button of your own. */
  add: (files: File[]) => void;
}

export interface FileShareProps {
  /** Upload one file; resolve with what you'll need to make the link (a key, an id). */
  onUpload: (file: File, context: FileShareUploadContext) => Promise<unknown>;
  /** Make the link; resolve with its URL. */
  onCreateLink: (share: FileShareRequest) => Promise<{ url: string }>;
  /** Native input syntax, e.g. "image/*,.pdf". */
  accept?: string;
  /** Bytes per file. */
  maxSize?: number;
  maxFiles?: number;
  /** Choices for how many days the link lives. */
  expiries?: number[];
  ref?: React.Ref<FileShareHandle>;
  className?: string;
}

type Item = {
  id: string;
  file: File;
  progress: number;
  status: "uploading" | "done" | "error";
  error?: string;
  result?: unknown;
  controller?: AbortController;
};

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const EXPIRIES = [1, 7, 30];
const mix = (color: string, amount: number, into = "transparent") =>
  `color-mix(in oklab, ${color} ${amount}%, ${into})`;
const LIT: React.CSSProperties = {
  backgroundColor: "var(--primary)",
  backgroundImage: `radial-gradient(120% 90% at 0% 0%, ${mix("var(--primary-foreground)", 22)} 0%, transparent 55%), linear-gradient(175deg, transparent 40%, ${mix("black", 24)} 100%)`,
  boxShadow: `inset 0 1px 0 ${mix("var(--primary-foreground)", 36)}, inset 0 0 0 1px ${mix("var(--primary-foreground)", 12)}`,
};
const CARD: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, var(--card), ${mix("var(--card)", 95, "var(--foreground)")})`,
  boxShadow: `0 0 0 1px var(--border), inset 0 1px 0 ${mix("var(--background)", 85)}`,
};
const ACTION: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, ${mix("var(--primary-foreground)", 16)}, transparent 60%)`,
  boxShadow: `inset 0 1px 0 ${mix("var(--primary-foreground)", 32)}, inset 0 0 0 1px ${mix("black", 10)}`,
};

const extOf = (name: string) =>
  name.includes(".")
    ? name.split(".").pop()!.slice(0, 4).toUpperCase()
    : "FILE";
function tint(seed: string): React.CSSProperties {
  let h = 0;
  for (const c of seed) h = (h * 31 + c.charCodeAt(0)) >>> 0;
  const chart = `var(--chart-${(h % 5) + 1}, var(--primary))`;
  return {
    background: mix(chart, 20, "var(--card)"),
    color: mix(chart, 75, "var(--foreground)"),
    boxShadow: `inset 0 0 0 1px ${mix(chart, 26)}`,
  };
}
function size(bytes: number) {
  const units = ["B", "KB", "MB", "GB"];
  let n = bytes;
  let u = 0;
  while (n >= 1000 && u < units.length - 1) {
    n /= 1000;
    u++;
  }
  return `${n >= 10 || u === 0 ? Math.round(n) : n.toFixed(1)} ${units[u]}`;
}
let seq = 0;

export function FileShare({
  onUpload,
  onCreateLink,
  accept,
  maxSize,
  maxFiles = 20,
  expiries = EXPIRIES,
  ref,
  className = "",
}: FileShareProps) {
  const reduced = useInteractionReducedMotion();
  const baseId = React.useId();
  const [items, setItems] = React.useState<Item[]>([]);
  const [over, setOver] = React.useState(0);
  const [expires, setExpires] = React.useState(
    expiries[Math.min(1, expiries.length - 1)] ?? 7,
  );
  const [lock, setLock] = React.useState(false);
  const [password, setPassword] = React.useState("");
  const [create, setCreate] = React.useState<{
    status: ActionStatus;
    error?: string;
  }>({ status: "idle" });
  const [link, setLink] = React.useState<{
    url: string;
    files: Item[];
    flown?: boolean;
  } | null>(null);
  // While the rows fly up, the list stops clipping so they can leave it.
  const [flying, setFlying] = React.useState(false);
  const [ready, setReady] = React.useState(false);
  const [said, setSaid] = React.useState("");
  const inputRef = React.useRef<HTMLInputElement>(null);
  const sectionRef = React.useRef<HTMLElement>(null);
  const panelRef = React.useRef<HTMLDivElement>(null);
  const listRef = React.useRef<HTMLUListElement>(null);
  const depth = React.useRef(0);

  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setReady(true));
    return () => cancelAnimationFrame(frame);
  }, []);

  const patch = (id: string, next: Partial<Item>) =>
    setItems((list) => list.map((i) => (i.id === id ? { ...i, ...next } : i)));

  const upload = (item: Item) => {
    const controller = new AbortController();
    patch(item.id, {
      status: "uploading",
      progress: 0,
      error: undefined,
      controller,
    });
    onUpload(item.file, {
      onProgress: (f) =>
        patch(item.id, { progress: Math.max(0, Math.min(1, f)) }),
      signal: controller.signal,
    })
      .then((result) => {
        if (!controller.signal.aborted)
          patch(item.id, { status: "done", progress: 1, result });
      })
      .catch((e) => {
        if (!controller.signal.aborted)
          patch(item.id, {
            status: "error",
            error:
              e instanceof Error && e.message ? e.message : "Upload failed",
          });
      });
  };

  const add = (files: FileList | File[]) => {
    if (link) return;
    const room = Math.max(0, maxFiles - items.length);
    const next: Item[] = [...files].slice(0, room).map((file) => ({
      id: `f${++seq}`,
      file,
      progress: 0,
      status: "uploading" as const,
    }));
    for (const item of next) {
      if (maxSize && item.file.size > maxSize) {
        item.status = "error";
        item.error = `Over ${size(maxSize)}`;
      }
    }
    setItems((list) => [...list, ...next]);
    setCreate({ status: "idle" });
    setSaid(`${next.length} ${next.length === 1 ? "file" : "files"} added.`);
    next.filter((i) => i.status !== "error").forEach(upload);
  };

  React.useImperativeHandle(ref, () => ({
    add: (files: File[]) => add(files),
  }));

  const remove = (item: Item) => {
    item.controller?.abort();
    setItems((list) => list.filter((i) => i.id !== item.id));
  };

  const doneItems = items.filter((i) => i.status === "done");
  const uploading = items.some((i) => i.status === "uploading");
  const total = items.reduce((n, i) => n + i.file.size, 0);
  const sent = items.reduce(
    (n, i) => n + i.file.size * (i.status === "done" ? 1 : i.progress),
    0,
  );
  const canCreate =
    doneItems.length > 0 && !uploading && (!lock || password.trim().length > 0);
  const busy = create.status === "pending" || create.status === "success";

  const createLink = async () => {
    if (!canCreate || busy) return;
    setCreate({ status: "pending" });
    try {
      const { url } = await onCreateLink({
        files: doneItems.map((i) => ({
          name: i.file.name,
          size: i.file.size,
          type: i.file.type,
          result: i.result,
        })),
        expiresIn: expires,
        password: lock && password.trim() ? password.trim() : undefined,
      });
      setCreate({ status: "success" });
      setSaid(`Link ready: ${url}`);
      // Each file's tile leaps into the corner where the link's stack appears and lands as one of its cards,
      // while the rows fold away; then the panel turns into the link under tiles already in place.
      const section = sectionRef.current;
      const panel = panelRef.current?.getBoundingClientRect();
      const rows = [
        ...(listRef.current?.querySelectorAll<HTMLElement>("[data-file]") ??
          []),
      ];
      const flights: HTMLElement[] = [];
      if (section && panel && rows.length && !reduced) {
        setFlying(true);
        const box = section.getBoundingClientRect();
        // Screen px to the block's own px, so the tiles land true inside a scaled or zoomed container too.
        const k = box.width / (section.offsetWidth || box.width) || 1;
        // The stack's centre on the link face: the panel's top-right corner, inside its padding.
        const fan = { x: panel.right - 54 * k, y: panel.top + 46 * k };
        const shown = rows.slice(0, 3);
        shown.forEach((row, i) => {
          row.animate(
            [
              { opacity: 1, transform: "none" },
              { opacity: 0, transform: "translateY(-6px)" },
            ],
            {
              duration: 260,
              delay: 120 + i * 90,
              easing: EASE,
              fill: "forwards",
            },
          );
          const tile = row.querySelector<HTMLElement>("[data-tile]");
          if (!tile) return;
          const r = tile.getBoundingClientRect();
          const copy = tile.cloneNode(true) as HTMLElement;
          Object.assign(copy.style, {
            position: "absolute",
            left: `${(r.left - box.left) / k}px`,
            top: `${(r.top - box.top) / k}px`,
            width: `${r.width / k}px`,
            height: `${r.height / k}px`,
            margin: "0",
            zIndex: "30",
            pointerEvents: "none",
            willChange: "transform",
          });
          section.appendChild(copy);
          flights.push(copy);
          const turn = (i - (shown.length - 1) / 2) * 10;
          const dx = (fan.x - (r.left + r.width / 2)) / k + turn * 0.6;
          const dy = (fan.y - (r.top + r.height / 2)) / k;
          const grow = 40 / (r.width / k);
          copy.animate(
            [
              { transform: "translate(0px, 0px) rotate(0deg) scale(1)" },
              {
                transform: `translate(${dx * 0.42}px, ${dy * 0.58 - 28}px) rotate(${turn * 0.5 - 6}deg) scale(${(1 + grow) / 2})`,
                offset: 0.55,
              },
              {
                transform: `translate(${dx}px, ${dy}px) rotate(${turn}deg) scale(${grow})`,
              },
            ],
            {
              duration: 640,
              delay: i * 90,
              easing: "cubic-bezier(0.45,0,0.2,1)",
              fill: "forwards",
            },
          );
        });
      }
      const landed =
        reduced || !flights.length ? 300 : 560 + (flights.length - 1) * 90;
      window.setTimeout(() => {
        setLink({ url, files: doneItems, flown: flights.length > 0 });
        setFlying(false);
        // The real stack is under the flown tiles now; they hand over and go.
        flights.forEach(
          (f) =>
            (f.animate([{ opacity: 1 }, { opacity: 0 }], {
              duration: 220,
              delay: 260,
              fill: "forwards",
            }).onfinish = () => f.remove()),
        );
      }, landed);
    } catch (e) {
      setCreate({
        status: "error",
        error:
          e instanceof Error && e.message
            ? e.message
            : "Couldn’t make the link. Try again.",
      });
    }
  };

  const reset = () => {
    setItems([]);
    setLink(null);
    setCreate({ status: "idle" });
    setPassword("");
    setLock(false);
  };

  const shared = link?.files ?? [];
  const sharedSize = shared.reduce((n, i) => n + i.file.size, 0);

  return (
    <section
      ref={sectionRef}
      aria-labelledby={`${baseId}-title`}
      className={`relative w-full max-w-[420px] rounded-[28px] p-2 text-card-foreground ${className}`}
      style={CARD}
      onDragEnter={(e) => {
        if (link || !e.dataTransfer.types.includes("Files")) return;
        e.preventDefault();
        depth.current++;
        setOver(e.dataTransfer.items.length || 1);
      }}
      onDragOver={(e) => {
        if (link || !e.dataTransfer.types.includes("Files")) return;
        e.preventDefault();
        e.dataTransfer.dropEffect = "copy";
      }}
      onDragLeave={() => {
        depth.current = Math.max(0, depth.current - 1);
        if (!depth.current) setOver(0);
      }}
      onDrop={(e) => {
        if (link) return;
        e.preventDefault();
        depth.current = 0;
        setOver(0);
        add(e.dataTransfer.files);
      }}
    >
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 420px)" }}
      />
      <div className="@container w-full">
        <input
          ref={inputRef}
          type="file"
          multiple
          accept={accept}
          className="sr-only"
          tabIndex={-1}
          aria-hidden="true"
          onChange={(e) => {
            if (e.target.files?.length) add(e.target.files);
            e.target.value = "";
          }}
        />

        {/* The one lit surface: the drop area, which becomes the link. */}
        <div
          ref={panelRef}
          className="rounded-[22px] p-2 text-primary-foreground"
          style={LIT}
        >
          <Faces active={link ? 1 : 0} reduced={reduced} ready={ready}>
            <div
              className="flex min-h-[132px] flex-col items-center justify-center rounded-[16px] px-4 py-5 text-center"
              style={{
                boxShadow: `inset 0 0 0 1px ${over ? "var(--primary-foreground)" : mix("var(--primary-foreground)", 30)}`,
                background: over
                  ? mix("var(--primary-foreground)", 10)
                  : "transparent",
                transform: over && !reduced ? "scale(0.985)" : "none",
                transition: reduced
                  ? "none"
                  : `box-shadow 200ms, background-color 200ms, transform 320ms ${EASE}`,
              }}
            >
              <span
                className="flex size-10 items-center justify-center rounded-full"
                style={{ background: mix("var(--primary-foreground)", 14) }}
              >
                <Upload
                  aria-hidden="true"
                  className="size-[18px]"
                  style={{
                    transform: over && !reduced ? "translateY(-2px)" : "none",
                    transition: `transform 300ms ${EASE}`,
                  }}
                />
              </span>
              <h2
                id={`${baseId}-title`}
                className="mt-2.5 text-[15px] font-medium tracking-[-0.01em]"
              >
                <TextMorph>
                  {over
                    ? `Release to add ${over === 1 ? "it" : over}`
                    : items.length
                      ? "Add more files"
                      : "Drop files to share"}
                </TextMorph>
              </h2>
              <p className="mt-1 text-[12.5px] text-primary-foreground/70">
                or{" "}
                <button
                  type="button"
                  onClick={() => inputRef.current?.click()}
                  className={`cursor-pointer rounded-full font-medium text-primary-foreground underline decoration-primary-foreground/40 underline-offset-[3px] hover:decoration-primary-foreground ${INTERACTION_FOCUS}`}
                >
                  choose files
                </button>
                {maxSize ? ` · up to ${size(maxSize)} each` : ""}
              </p>
            </div>

            <div className="p-2.5">
              <div className="flex items-start justify-between gap-3">
                <div className="min-w-0">
                  <p className="text-[12.5px] text-primary-foreground/70">
                    Ready to share
                  </p>
                  <p className="mt-0.5 text-[17px] font-medium leading-tight tracking-[-0.02em]">
                    {shared.length} {shared.length === 1 ? "file" : "files"} ·{" "}
                    {size(sharedSize)}
                  </p>
                  <p className="mt-1 inline-flex items-center gap-1.5 text-[12.5px] text-primary-foreground/75">
                    {lock && <Lock aria-hidden="true" className="size-3" />}
                    Expires in {expires} {expires === 1 ? "day" : "days"}
                    {lock ? " · password" : ""}
                  </p>
                </div>
                {/* The files, fanned as the stack they folded into. */}
                <span
                  aria-hidden="true"
                  className="relative mr-2 mt-1 h-12 w-14 shrink-0"
                >
                  {shared.slice(0, 3).map((it, i, all) => {
                    const turn = (i - (all.length - 1) / 2) * 10;
                    return (
                      // The fan is on the outer layer, the pop on the inner one, so the keyframe never undoes the turn.
                      <span
                        key={it.id}
                        className="absolute left-2 top-0"
                        style={{
                          transform: `rotate(${turn}deg) translateX(${turn * 0.6}px)`,
                        }}
                      >
                        <span
                          className={`flex h-12 w-10 items-end justify-center rounded-[8px] pb-1 font-mono text-[8.5px] font-medium ${link?.flown ? "" : "motion-safe:animate-[ui-pop-in_420ms_cubic-bezier(0.34,1.36,0.64,1)_both]"}`}
                          style={{
                            ...tint(extOf(it.file.name)),
                            animationDelay: `${i * 70}ms`,
                            boxShadow: `0 0 0 1px ${mix("var(--primary)", 60)}`,
                          }}
                        >
                          {extOf(it.file.name)}
                        </span>
                      </span>
                    );
                  })}
                </span>
              </div>
              <div
                className="mt-3 flex h-10 items-center gap-2 rounded-full pl-4 pr-1"
                style={{
                  background: mix("black", 14),
