"use client";

import * as React from "react";
import { CircleAlert, Fingerprint } from "lucide-react";
import { TextMorph } from "./text-morph";
import {
  INTERACTION_FOCUS,
  interactionIcon,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";
import { useHoldConfirm, type HoldStatus } from "./use-hold-confirm";
export type { HoldStatus } from "./use-hold-confirm";

export interface HoldToConfirmProps extends Omit<
  React.ButtonHTMLAttributes<HTMLButtonElement>,
  "onClick" | "children"
> {
  onConfirm: () => void | Promise<void>;
  duration?: number;
  resetAfter?: number;
  labels?: Partial<Record<HoldStatus, string>>;
  icon?: React.ReactNode;
  /** Every change of state: holding, pending, success, error, back to idle. */
  onStatusChange?: (status: HoldStatus) => void;
}
const LABELS = {
  idle: "Hold to confirm",
  holding: "Keep holding",
  pending: "Confirming",
  success: "Confirmed",
  error: "Hold to retry",
};

/** Press and keep holding. The threshold owns the action; a click never submits it. */
export function HoldToConfirm({
  onConfirm,
  duration = 1100,
  resetAfter = 2200,
  labels,
  icon,
  onStatusChange,
  disabled = false,
  className = "",
  ...props
}: HoldToConfirmProps) {
  const reduced = useInteractionReducedMotion();
  const delay = Number.isFinite(duration)
    ? Math.max(300, Math.min(5000, duration))
    : 1100;
  const { status, progress, begin, cancel } = useHoldConfirm(
    onConfirm,
    delay,
    resetAfter,
    disabled,
    reduced,
  );
  const report = React.useRef(onStatusChange);
  React.useLayoutEffect(() => {
    report.current = onStatusChange;
  });
  React.useEffect(() => {
    report.current?.(status);
  }, [status]);
  const text = { ...LABELS, ...labels }[status];
  const hint = React.useId();
  const pending = status === "pending",
    succeeded = status === "success";
  return (
    <>
      <button
        {...props}
        type="button"
        disabled={disabled}
        aria-describedby={hint}
        aria-busy={pending || undefined}
        aria-disabled={pending || succeeded || disabled || undefined}
        onPointerDown={(event) => {
          if (event.button !== 0 || !event.isPrimary) return;
          event.currentTarget.setPointerCapture(event.pointerId);
          event.currentTarget.focus({ preventScroll: true });
          begin(`pointer:${event.pointerId}`);
        }}
        onPointerMove={(event) => {
          if (!event.currentTarget.hasPointerCapture(event.pointerId)) return;
          const rect = event.currentTarget.getBoundingClientRect();
          if (
            event.clientX < rect.left ||
            event.clientX > rect.right ||
            event.clientY < rect.top ||
            event.clientY > rect.bottom
          )
            cancel(`pointer:${event.pointerId}`);
        }}
        onPointerUp={(event) => cancel(`pointer:${event.pointerId}`)}
        onPointerCancel={(event) => cancel(`pointer:${event.pointerId}`)}
        onLostPointerCapture={(event) => cancel(`pointer:${event.pointerId}`)}
        onPointerLeave={(event) => cancel(`pointer:${event.pointerId}`)}
        onBlur={() => cancel()}
        onKeyDown={(event) => {
          if (event.key === "Escape") {
            event.preventDefault();
            cancel();
          }
          if (event.key === " " || event.key === "Enter") {
            event.preventDefault();
            if (!event.repeat) begin(`key:${event.key}`);
          }
        }}
        onKeyUp={(event) => {
          if (event.key === " " || event.key === "Enter") {
            event.preventDefault();
            cancel(`key:${event.key}`);
          }
        }}
        onClick={(event) => event.preventDefault()}
        className={`cursor-pointer disabled:cursor-default aria-disabled:cursor-default relative inline-flex h-11 select-none items-center justify-center gap-2.5 overflow-clip rounded-full border px-4 text-[13px] font-medium transition-colors disabled:opacity-40 ${status === "error" ? "border-destructive/40 bg-destructive/5 text-destructive" : "border-primary bg-primary text-primary-foreground hover:bg-primary/90"} ${INTERACTION_FOCUS} ${className}`}
        style={{ touchAction: "none", ...props.style }}
      >
        <span aria-hidden="true" className="relative size-5 shrink-0">
          <span
            className="absolute inset-0 flex items-center justify-center [&>svg]:size-4"
            style={interactionIcon(
              status === "idle" || status === "holding",
              reduced,
            )}
          >
            {icon ?? <Fingerprint />}
          </span>
          <svg
            viewBox="0 0 24 24"
            className="absolute -inset-1 size-7 -rotate-90"
            style={{
              opacity: status === "holding" ? 1 : 0,
              transition: reduced ? "none" : "opacity 180ms ease-out",
            }}
          >
            <circle
              cx="12"
              cy="12"
              r="10.5"
              fill="none"
              stroke="currentColor"
              strokeOpacity="0.2"
              strokeWidth="1"
            />
            <circle
              ref={progress}
              cx="12"
              cy="12"
              r="10.5"
              pathLength="1"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.5"
              strokeLinecap="round"
              strokeDasharray="1"
              strokeDashoffset="1"
            />
          </svg>
          <span
            className="absolute inset-0 flex items-center justify-center"
            style={interactionIcon(pending, reduced)}
          >
            <span
              className={`size-4 rounded-full border-[1.5px] border-current/30 border-t-current ${pending && !reduced ? "animate-spin" : ""}`}
            />
          </span>
          <svg
            viewBox="0 0 20 20"
            className="absolute inset-0 size-5"
            style={interactionIcon(succeeded, reduced)}
          >
            <path
              d="m4 10 4 4 8-8"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.6"
              strokeLinecap="round"
              strokeLinejoin="round"
              pathLength="1"
              style={{
                strokeDasharray: 1,
                strokeDashoffset: succeeded ? 0 : 1,
                transition: reduced
                  ? "none"
                  : "stroke-dashoffset 380ms ease-out 80ms",
              }}
            />
          </svg>
          <CircleAlert
            className="absolute inset-0 size-5"
            style={interactionIcon(status === "error", reduced)}
          />
        </span>
        <TextMorph>{text}</TextMorph>
      </button>
      <span id={hint} className="sr-only">
        Hold the pointer, Space or Enter for {delay / 1000} seconds. Release
        early or press Escape to cancel.
      </span>
      <span role="status" className="sr-only">
        {status === "idle" ? "" : text}
      </span>
    </>
  );
}

"use client";

import * as React from "react";
import { createPortal } from "react-dom";
import {
  enterStyle,
  themeVars,
  useFloating,
  usePresence,
  type Align,
  type Side,
} from "./floating";
import { useInteractionReducedMotion } from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * HOVER CARD: a preview of what a link points to
 *
 *   rest     after resting on the link (600ms) the card rises off
 *            it out of a blur, from the point nearest to it
 *   travel   moving from the link onto the card keeps it open, so
 *            its buttons can be used; leaving both closes it after
 *            a short grace (300ms), so a diagonal path doesn't
 *   keys     focusing the link from the keyboard opens it at once;
 *            Escape closes it
 *
 * Touch has no hover: a tap follows the link, as people expect.
 * The card adds to the link, so nothing in it should be the only
 * way to reach something.
 * ───────────────────────────────────────────────────────── */

export interface HoverCardProps {
  /** The link or name it previews. */
  children: React.ReactElement<{ "aria-describedby"?: string }>;
  content: React.ReactNode;
  side?: Side;
  align?: Align;
  /** Rest before it opens (ms). */
  openDelay?: number;
  /** Grace before it closes once the pointer has left both (ms). */
  closeDelay?: number;
  width?: number;
  className?: string;
}

export function HoverCard({
  children,
  content,
  side = "bottom",
  align = "start",
  openDelay = 600,
  closeDelay = 300,
  width = 300,
  className = "",
}: HoverCardProps) {
  const reduced = useInteractionReducedMotion();
  const anchor = React.useRef<HTMLSpanElement>(null);
  const surface = React.useRef<HTMLDivElement>(null);
  const [open, setOpen] = React.useState(false);
  const timer = React.useRef(0);
  const id = React.useId();
  const { mounted, shown } = usePresence(open, 160);
  const place = useFloating({
    open: mounted,
    anchor,
    floating: surface,
    side,
    align,
    offset: 8,
  });
  const [vars, setVars] = React.useState<React.CSSProperties>({});

  const later = (next: boolean, ms: number) => {
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => setOpen(next), ms);
  };
  const enter = (e: React.PointerEvent) =>
    e.pointerType === "mouse" && later(true, open ? 0 : openDelay);
  const leave = (e: React.PointerEvent) =>
    e.pointerType === "mouse" && later(false, closeDelay);

  React.useEffect(() => () => window.clearTimeout(timer.current), []);
  React.useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && setOpen(false);
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [open]);
  React.useLayoutEffect(() => {
    if (mounted) setVars(themeVars(anchor.current));
  }, [mounted]);

  return (
    <>
      <span
        ref={anchor}
        className="inline"
        onPointerEnter={enter}
        onPointerLeave={leave}
        onFocus={(e) => {
          if ((e.target as HTMLElement).matches(":focus-visible")) {
            window.clearTimeout(timer.current);
            setOpen(true);
          }
        }}
        onBlur={(e) => {
          if (!surface.current?.contains(e.relatedTarget as Node))
            later(false, 0);
        }}
      >
        {React.cloneElement(children, {
          "aria-describedby": open ? id : children.props["aria-describedby"],
        })}
      </span>
      {mounted &&
        createPortal(
          <div
            ref={surface}
            id={id}
            role="tooltip"
            onPointerEnter={enter}
            onPointerLeave={leave}
            className={`fixed left-0 top-0 z-[55] max-w-[calc(100vw_-_16px)] rounded-[16px] bg-popover p-4 text-[13.5px] text-popover-foreground shadow-[0_0_0_1px_var(--border)] ${className}`}
            style={{
              ...vars,
              width,
              left: place.x,
              top: place.y,
              transformOrigin: place.origin,
              ...enterStyle(shown, place.side, reduced),
            }}
          >
            {content}
          </div>,
          document.body,
        )}
    </>
  );
}

export default HoverCard;

"use client";

import * as React from "react";
import {
  EASE_OUT,
  EASE_THROW,
  INTERACTION_FOCUS,
  INTERACTION_PRESS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * ICON MORPH: one icon becoming another
 *
 *   blur     the old icon shrinks into a 3px blur while the new
 *            one pops out of it with a slight overshoot
 *   rotate   a quarter turn that keeps its direction: forward
 *            turns clockwise, back turns the other way
 *   flip     a card turn: the old icon goes edge-on, the new one
 *            comes round from behind
 *   draw     the new icon's strokes draw themselves, one after
 *            another, as the old one blurs away
 *
 * Every change starts from wherever the last one is, so fast
 * toggling never jumps. Two icons (from/to + active) or any
 * number (icons + value). Reduced motion gets a short crossfade.
 * ───────────────────────────────────────────────────────── */

export type IconMorphMode = "blur" | "rotate" | "flip" | "draw" | "scale";

export interface IconMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  /** Shown while `active` is false. */
  from?: React.ReactNode;
  /** Shown while `active` is true. */
  to?: React.ReactNode;
  active?: boolean;
  /** Any number of icons by name; `value` picks one. Order sets the direction of rotate and flip. */
  icons?: Record<string, React.ReactNode>;
  value?: string;
  /** How the icons trade places. "scale" is the old name for "blur". */
  mode?: IconMorphMode;
  /** Box size in px. */
  size?: number;
}

type Pose = { opacity: string; transform: string; filter: string };

const SHOWN: Pose = { opacity: "1", transform: "none", filter: "blur(0px)" };
const STROKES = "path, line, polyline, polygon, circle, rect, ellipse";

function hidden(mode: IconMorphMode, dir: number, leaving: boolean): Pose {
  const side = leaving ? dir : -dir;
  if (mode === "rotate")
    return {
      opacity: "0",
      transform: `rotate(${90 * side}deg) scale(0.5)`,
      filter: "blur(2px)",
    };
  if (mode === "flip")
    return {
      opacity: "0",
      transform: `rotateY(${90 * side}deg)`,
      filter: "blur(0px)",
    };
  if (mode === "draw")
    return { opacity: "0", transform: "scale(0.85)", filter: "blur(3px)" };
  return { opacity: "0", transform: "scale(0.6)", filter: "blur(3px)" };
}

/**
 * Where a layer starts from. Mid-animation, that's wherever it is now (so a fast toggle turns
 * back instead of jumping); at rest, the pose it held before this render flipped its opacity.
 */
function startPose(el: HTMLElement, rest: Pose): Pose {
  if (!el.getAnimations().some((a) => a.playState === "running")) return rest;
  const style = getComputedStyle(el);
  return {
    opacity: style.opacity,
    transform: style.transform,
    filter: style.filter === "none" ? "blur(0px)" : style.filter,
  };
}

function animateLayer(
  el: HTMLElement,
  mode: IconMorphMode,
  dir: number,
  entering: boolean,
  reduced: boolean,
) {
  const from = startPose(el, entering ? hidden(mode, dir, false) : SHOWN);
  el.getAnimations().forEach((a) => a.cancel());
  el.querySelectorAll<SVGElement>(STROKES).forEach((s) =>
    s.getAnimations().forEach((a) => a.cancel()),
  );

  if (reduced) {
    el.animate([{ opacity: from.opacity }, { opacity: entering ? "1" : "0" }], {
      duration: 160,
      easing: "ease-out",
    });
    return;
  }

  if (!entering) {
    if (mode === "flip")
      el.animate([from, hidden(mode, dir, true)], {
        duration: 170,
        easing: "cubic-bezier(0.5,0,0.75,0)",
      });
    else
      el.animate([from, hidden(mode, dir, true)], {
        duration: 200,
        easing: EASE_OUT,
      });
    return;
  }

  if (mode === "flip") {
    // Waits until the old face is edge-on, then comes round from behind.
    const wait = Number(from.opacity) < 0.02;
    el.animate(
      wait
        ? [
            { ...from, offset: 0 },
            { ...from, offset: 0.34, easing: EASE_OUT },
            { ...SHOWN, offset: 1 },
          ]
        : [from, SHOWN],
      {
        duration: wait ? 500 : 340,
        easing: wait ? "linear" : EASE_OUT,
      },
    );
    return;
  }
  el.animate(
    [
      { opacity: from.opacity, filter: from.filter },
      { opacity: "1", filter: "blur(0px)" },
    ],
    { duration: mode === "draw" ? 180 : 260, easing: EASE_OUT },
  );
  el.animate([{ transform: from.transform }, { transform: "none" }], {
    duration: mode === "rotate" ? 480 : 440,
    easing: EASE_THROW,
  });
  if (mode !== "draw") return;
  el.querySelectorAll<SVGGeometryElement>(STROKES).forEach((stroke, i) => {
    const length =
      typeof stroke.getTotalLength === "function" ? stroke.getTotalLength() : 0;
    if (!length) return;
    stroke.animate(
      [
        { strokeDasharray: `${length}`, strokeDashoffset: `${length}` },
        { strokeDasharray: `${length}`, strokeDashoffset: "0" },
      ],
      {
        duration: 420,
        delay: 40 + Math.min(i, 5) * 60,
        easing: EASE_OUT,
        fill: "backwards",
      },
    );
  });
}

export function IconMorph({
  from,
  to,
  active = false,
  icons,
  value,
  mode = "blur",
  size = 16,
  className = "",
  style,
  ...props
}: IconMorphProps) {
  const reduced = useInteractionReducedMotion();
  const layers = React.useMemo<[string, React.ReactNode][]>(
    () =>
      icons
        ? Object.entries(icons)
        : [
            ["from", from],
            ["to", to],
          ],
    [icons, from, to],
  );
  const key = icons ? (value ?? layers[0]?.[0]) : active ? "to" : "from";
  const refs = React.useRef(new Map<string, HTMLSpanElement>());
  const shownRef = React.useRef(key);
  const kind: IconMorphMode = mode === "scale" ? "blur" : mode;

  React.useLayoutEffect(() => {
    const prev = shownRef.current;
    if (prev === key) return;
    shownRef.current = key;
    const order = layers.map(([k]) => k);
    const dir = order.indexOf(key) >= order.indexOf(prev) ? 1 : -1;
    const leaving = refs.current.get(prev);
    const entering = refs.current.get(key);
    if (leaving) animateLayer(leaving, kind, dir, false, reduced);
    if (entering) animateLayer(entering, kind, dir, true, reduced);
  }, [key, layers, kind, reduced]);

  return (
    <span
      aria-hidden="true"
      className={`relative inline-flex shrink-0 items-center justify-center ${className}`}
      style={{
        width: size,
        height: size,
        perspective: kind === "flip" ? 240 : undefined,
        ...style,
      }}
      {...props}
    >
      {layers.map(([k, node]) => (
        <span
          key={k}
          ref={(el) => {
            if (el) refs.current.set(k, el);
            else refs.current.delete(k);
          }}
          className="absolute inset-0 flex items-center justify-center [backface-visibility:hidden] [&_svg]:size-full"
          style={{
            opacity: k === key ? 1 : 0,
            willChange: "transform, opacity",
          }}
        >
          {node}
        </span>
      ))}
    </span>
  );
}

export interface IconMorphButtonProps extends Omit<
  React.ButtonHTMLAttributes<HTMLButtonElement>,
  "children"
> {
  from: React.ReactNode;
  to: React.ReactNode;
  active?: boolean;
  defaultActive?: boolean;
  onActiveChange?: (next: boolean) => void;
  mode?: IconMorphMode;
  /** sm 28px, md 36px, lg 40px. */
  size?: "sm" | "md" | "lg";
  variant?: "outline" | "ghost" | "solid";
  /** Accessible name; the pressed state is announced with it. */
  label: string;
}

const BUTTON_SIZES = {
  sm: { box: "size-7", icon: 14 },
  md: { box: "size-9", icon: 16 },
  lg: { box: "size-10", icon: 18 },
};

const BUTTON_TONES = {
  outline:
    "bg-card text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent",
  ghost:
    "bg-transparent text-muted-foreground hover:bg-accent hover:text-foreground",
  solid: "bg-primary text-primary-foreground hover:bg-primary/90",
};

export function IconMorphButton({
  from,
  to,
  active: controlled,
  defaultActive = false,
  onActiveChange,
  mode = "blur",
  size = "md",
  variant = "outline",
  label,
  className = "",
  onClick,
  ...props
}: IconMorphButtonProps) {
  const [inner, setInner] = React.useState(defaultActive);
  const active = controlled ?? inner;
  const s = BUTTON_SIZES[size];

  return (
    <button
      type="button"
      aria-label={label}
      aria-pressed={active}
      onClick={(e) => {
        onClick?.(e);
        if (e.defaultPrevented) return;
        if (controlled === undefined) setInner(!active);
        onActiveChange?.(!active);
      }}
      className={`inline-flex shrink-0 select-none items-center justify-center rounded-full cursor-pointer disabled:cursor-default disabled:opacity-45 ${s.box} ${BUTTON_TONES[variant]} ${INTERACTION_PRESS} ${INTERACTION_FOCUS} ${className}`}
      {...props}
    >
      <IconMorph
        from={from}
        to={to}
        active={active}
        mode={mode}
        size={s.icon}
      />
    </button>
  );
}

export default IconMorph;

"use client";

/* ─────────────────────────────────────────────────────────
 * IMAGE COMPARE: two pictures, one divide
 *
 *   drag     press anywhere and the divide is thrown to your
 *            finger, then follows it exactly
 *   reveal   the "after" picture sits in a window that slides one
 *            way while the picture inside slides back the other:
 *            two moving layers, nothing repainted while you drag
 *   labels   each side's label fades as its picture runs out
 *   keys     arrows by 1%, Shift by 10%, Home and End; a
 *            double-click brings the divide home to the middle
 * ───────────────────────────────────────────────────────── */

import * as React from "react";
import { ChevronsLeftRight, ImageOff } from "lucide-react";
import {
  EASE_OUT,
  INTERACTION_FOCUS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";
import { TextMorph } from "./text-morph";

export type CompareImage = { src: string; alt: string; className?: string };
export interface ImageCompareProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onChange"
> {
  before: CompareImage;
  after: CompareImage;
  beforeLabel?: string;
  afterLabel?: string;
  label?: string;
  value?: number;
  defaultValue?: number;
  onValueChange?: (value: number) => void;
  onValueCommit?: (value: number) => void;
  aspectRatio?: number;
}
const clamp = (value: number) =>
  Number.isFinite(value) ? Math.max(0, Math.min(100, value)) : 50;

function Picture({ image }: { image: CompareImage }) {
  const [failed, setFailed] = React.useState(false);
  return failed ? (
    <div
      role="img"
      aria-label={`${image.alt} (unavailable)`}
      className="flex size-full items-center justify-center bg-muted text-muted-foreground"
    >
      <ImageOff className="size-6" aria-hidden="true" />
    </div>
  ) : (
    <img
      src={image.src}
      alt={image.alt}
      draggable={false}
      decoding="async"
      onError={() => setFailed(true)}
      className={`size-full select-none object-cover ${image.className ?? ""}`}
    />
  );
}

// The same strings are written by React and by the gesture, so either can take over from the other.
const windowAt = (p: number) => `translate3d(${p - 100}%,0,0)`;
const pictureAt = (p: number) => `translate3d(${100 - p}%,0,0)`;
const lineAt = (p: number) => `translate3d(${p}%,0,0)`;
const handleAt = (p: number) =>
  `translate3d(clamp(22px, ${p}%, calc(100% - 22px)),0,0)`;

export function ImageCompare({
  before,
  after,
  beforeLabel = "Before",
  afterLabel = "After",
  label = "Image comparison",
  value,
  defaultValue = 50,
  onValueChange,
  onValueCommit,
  aspectRatio = 1.6,
  className = "",
  ...props
}: ImageCompareProps) {
  const reduced = useInteractionReducedMotion();
  const [own, setOwn] = React.useState(clamp(defaultValue));
  const position = clamp(value ?? own);
  const frame = React.useRef<HTMLDivElement>(null);
  const win = React.useRef<HTMLDivElement>(null);
  const picture = React.useRef<HTMLDivElement>(null);
  const line = React.useRef<HTMLDivElement>(null);
  const rail = React.useRef<HTMLDivElement>(null);
  const handle = React.useRef<HTMLButtonElement>(null);
  const afterTag = React.useRef<HTMLSpanElement>(null);
  const beforeTag = React.useRef<HTMLSpanElement>(null);
  const gesture = React.useRef<{
    id: number;
    origin: number;
    last: number;
    left: number;
    width: number;
    moved: boolean;
  } | null>(null);
  const hintId = React.useId();

  const motion = (on: boolean) => {
    const t = on && !reduced ? `transform 420ms ${EASE_OUT}` : "none";
    for (const el of [win.current, picture.current, line.current, rail.current])
      if (el) el.style.transition = t;
  };
  const paint = (p: number) => {
    if (win.current) win.current.style.transform = windowAt(p);
    if (picture.current) picture.current.style.transform = pictureAt(p);
    if (line.current) line.current.style.transform = lineAt(p);
    if (rail.current) rail.current.style.transform = handleAt(p);
    if (afterTag.current) afterTag.current.style.opacity = p > 12 ? "1" : "0";
    if (beforeTag.current) beforeTag.current.style.opacity = p < 88 ? "1" : "0";
    handle.current?.setAttribute("aria-valuenow", String(Math.round(p)));
    handle.current?.setAttribute(
      "aria-valuetext",
      `${Math.round(p)}% ${afterLabel}`,
    );
  };
  /** Settle on a value: React state, the parent, and an eased move when it wasn't under the finger. */
  const go = (next: number, animate: boolean, commit = true) => {
    const p = clamp(next);
    motion(animate);
    paint(p);
    if (value === undefined) setOwn(p);
    onValueChange?.(p);
    if (commit) onValueCommit?.(p);
    return p;
  };

  // A controlled value that changes from outside eases there.
  React.useLayoutEffect(() => {
    if (gesture.current) return;
    motion(true);
    paint(position);
  }, [position]);

  const finish = (event: React.PointerEvent, cancelled = false) => {
    const state = gesture.current;
    if (!state || event.pointerId !== state.id) return;
    gesture.current = null;
    // A release near the middle snaps home.
    const next = cancelled
      ? state.origin
      : Math.abs(state.last - 50) < 3
        ? 50
        : state.last;
    go(next, cancelled || next !== state.last || !state.moved, !cancelled);
  };

  return (
    <div
      {...props}
      role="region"
      aria-label={label}
      className={`w-full text-foreground ${className}`}
    >
      <div
        ref={frame}
        className="relative isolate cursor-ew-resize overflow-clip rounded-[20px] border border-border bg-muted"
        style={{
          aspectRatio: Math.max(0.25, aspectRatio),
          touchAction: "pan-y",
        }}
        onPointerDown={(event) => {
          if (event.button !== 0 || !event.isPrimary) return;
          // Keep the handle focused: the mousedown that follows would otherwise move focus to the page.
          event.preventDefault();
          const rect = event.currentTarget.getBoundingClientRect();
          event.currentTarget.setPointerCapture(event.pointerId);
          // Focus follows the press so the arrow keys work next, without a keyboard focus ring after a mouse drag.
          handle.current?.focus({
            preventScroll: true,
            focusVisible: false,
          } as FocusOptions);
          const p = clamp(
            ((event.clientX - rect.left) / Math.max(1, rect.width)) * 100,
          );
          gesture.current = {
            id: event.pointerId,
            origin: position,
            last: p,
            left: rect.left,
            width: Math.max(1, rect.width),
            moved: false,
          };
          // Thrown to the finger, then attached to it.
          motion(true);
          paint(p);
        }}
        onPointerMove={(event) => {
          const state = gesture.current;
          if (!state || state.id !== event.pointerId) return;
          if (!state.moved) {
            state.moved = true;
            motion(false);
          }
          state.last = clamp(
            ((event.clientX - state.left) / state.width) * 100,
          );
          paint(state.last);
          onValueChange?.(state.last);
        }}
        onDoubleClick={() => go(50, true)}
        onPointerUp={(event) => finish(event)}
        onPointerCancel={(event) => finish(event, true)}
        onLostPointerCapture={(event) => finish(event, true)}
      >
        <div className="absolute inset-0">
          <Picture key={before.src} image={before} />
        </div>
        <div
          ref={win}
          className="absolute inset-0 overflow-hidden will-change-transform"
          style={{ transform: windowAt(position) }}
        >
          <div
            ref={picture}
            className="absolute inset-0 will-change-transform"
            style={{ transform: pictureAt(position) }}
          >
            <Picture key={after.src} image={after} />
          </div>
        </div>
        <div
          ref={line}
          aria-hidden="true"
          className="pointer-events-none absolute inset-0 will-change-transform"
          style={{ transform: lineAt(position) }}
        >
          <span className="absolute inset-y-0 left-0 w-px -translate-x-1/2 bg-background" />
        </div>
        <div
          ref={rail}
          className="pointer-events-none absolute inset-0 will-change-transform"
          style={{ transform: handleAt(position) }}
        >
          <button
            ref={handle}
            type="button"
            role="slider"
            aria-label={label}
            aria-describedby={hintId}
            aria-valuemin={0}
            aria-valuemax={100}
            aria-valuenow={Math.round(position)}
            aria-valuetext={`${Math.round(position)}% ${afterLabel}`}
            aria-orientation="horizontal"
            onKeyDown={(event) => {
              if (
                ![
                  "ArrowLeft",
                  "ArrowRight",
                  "ArrowUp",
                  "ArrowDown",
                  "Home",
                  "End",
                ].includes(event.key)
              )
                return;
              event.preventDefault();
              const step =
                (event.key === "ArrowRight" || event.key === "ArrowUp"
                  ? 1
                  : -1) * (event.shiftKey ? 10 : 1);
              go(
                event.key === "Home"
                  ? 0
                  : event.key === "End"
                    ? 100
                    : position + step,
                true,
              );
            }}
            className={`pointer-events-auto absolute left-0 top-1/2 flex size-10 -translate-x-1/2 -translate-y-1/2 cursor-ew-resize items-center justify-center rounded-full border border-border bg-background text-foreground ${INTERACTION_FOCUS}`}
          >
            <ChevronsLeftRight className="size-4" aria-hidden="true" />
          </button>
        </div>
        <span
          ref={afterTag}
          className="pointer-events-none absolute bottom-3 left-3 rounded-full border border-border bg-background px-3 py-1.5 text-[10px] font-medium transition-opacity duration-300 motion-reduce:transition-none"
          style={{ opacity: position > 12 ? 1 : 0 }}
        >
          <TextMorph>{afterLabel}</TextMorph>
        </span>
        <span
          ref={beforeTag}
          className="pointer-events-none absolute bottom-3 right-3 rounded-full border border-border bg-background px-3 py-1.5 text-[10px] font-medium transition-opacity duration-300 motion-reduce:transition-none"
          style={{ opacity: position < 88 ? 1 : 0 }}
        >
          <TextMorph>{beforeLabel}</TextMorph>
        </span>
      </div>
      <p id={hintId} className="sr-only">
        Drag to compare. Arrow keys adjust by one percent, Shift and arrows by
        ten. Home and End reveal either image. Double-click to centre.
      </p>
    </div>
  );
}

"use client";

import * as React from "react";
import {
  EASE_OUT,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * FIELD: the column every text control sits in
 *
 *   label    above, with an optional aside on the right (a count)
 *   hint     under the control while all is well
 *   error    takes the hint's place: the hint folds away, the
 *            error rises in out of a blur, the control shakes once
 *
 * Shared by input, textarea, password, search and select so the
 * whole family has one surface, one focus ring and one error.
 * ───────────────────────────────────────────────────────── */

export interface FieldProps {
  id: string;
  label?: React.ReactNode;
  /** Right side of the label row, e.g. a character count. */
  aside?: React.ReactNode;
  hint?: React.ReactNode;
  error?: React.ReactNode;
  required?: boolean;
  className?: string;
  children: React.ReactNode;
}

export type FieldSize = "sm" | "md";

/** The surface of a text control: a thin line that darkens on hover and turns to the ring on focus. */
export function fieldSurface({
  invalid,
  disabled,
  round = true,
}: {
  invalid?: boolean;
  disabled?: boolean;
  round?: boolean;
}) {
  const ring = invalid
    ? "shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_55%,transparent)] focus-within:shadow-[inset_0_0_0_1px_var(--color-red-500),0_0_0_3px_color-mix(in_oklab,var(--color-red-500)_14%,transparent)]"
    : "shadow-[inset_0_0_0_1px_var(--border)] [&:not(:focus-within)]:hover:shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--foreground)_24%,var(--border))] focus-within:shadow-[inset_0_0_0_1px_var(--ring),0_0_0_3px_color-mix(in_oklab,var(--ring)_16%,transparent)]";
  return `relative flex w-full items-center bg-background text-foreground transition-[box-shadow,background-color,opacity] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] ${round ? "rounded-full" : "rounded-[14px]"} ${ring} ${
    disabled ? "pointer-events-none opacity-50" : ""
  }`;
}

/** ids for the control's label, hint and error. */
export function useFieldIds(id?: string) {
  const auto = React.useId();
  const base = id ?? auto;
  return { id: base, hint: `${base}-hint`, error: `${base}-error` };
}

/** One short shake whenever `on` turns true (an error arrives). */
export function useShake<T extends HTMLElement>(on: boolean) {
  const ref = React.useRef<T>(null);
  const reduced = useInteractionReducedMotion();
  React.useEffect(() => {
    if (!on || reduced) return;
    ref.current?.animate(
      [
        { transform: "none" },
        { transform: "translateX(-4px)" },
        { transform: "translateX(4px)" },
        { transform: "translateX(-2px)" },
        { transform: "none" },
      ],
      { duration: 380, easing: "ease-out" },
    );
  }, [on, reduced]);
  return ref;
}

/** Sets a native input's value so React's onChange still fires (clear buttons, pickers). */
export function setNativeValue(
  el: HTMLInputElement | HTMLTextAreaElement,
  value: string,
) {
  const proto =
    el instanceof HTMLTextAreaElement
      ? HTMLTextAreaElement.prototype
      : HTMLInputElement.prototype;
  Object.getOwnPropertyDescriptor(proto, "value")?.set?.call(el, value);
  el.dispatchEvent(new Event("input", { bubbles: true }));
}

/** A line under the control that folds open and closed; keeps its last words while closing. */
function Line({
  show,
  children,
  id,
  tone,
  reduced,
}: {
  show: boolean;
  children: React.ReactNode;
  id: string;
  tone: string;
  reduced: boolean;
}) {
  const [kept, setKept] = React.useState(children);
  if (show && children !== kept) setKept(children);
  return (
    <div
      className="grid"
      style={{
        gridTemplateRows: show ? "1fr" : "0fr",
        transition: reduced ? "none" : `grid-template-rows 320ms ${EASE_OUT}`,
      }}
    >
      <div className="min-h-0 overflow-hidden">
        <p
          id={id}
          className={`pt-1.5 pl-3 text-[12.5px] leading-snug ${tone}`}
          style={{
            opacity: show ? 1 : 0,
            filter: show ? "blur(0px)" : "blur(4px)",
            transform: show ? "none" : "translateY(-4px)",
            transition: reduced
              ? "none"
              : show
                ? `opacity 280ms ${EASE_OUT} 60ms, filter 280ms ${EASE_OUT} 60ms, transform 380ms ${EASE_OUT}`
                : `opacity 140ms ${EASE_OUT}, filter 140ms ${EASE_OUT}, transform 200ms ${EASE_OUT}`,
          }}
        >
          {show ? children : kept}
        </p>
      </div>
    </div>
  );
}

export function Field({
  id,
  label,
  aside,
  hint,
  error,
  required,
  className = "",
  children,
}: FieldProps) {
  const reduced = useInteractionReducedMotion();
  const ids = { hint: `${id}-hint`, error: `${id}-error` };
  return (
    <div className={`flex w-full flex-col ${className}`}>
      {(label || aside) && (
        <div className="flex items-baseline justify-between gap-3 px-3 pb-1.5">
          {label && (
            <label
              htmlFor={id}
              className="text-[13px] font-medium text-foreground"
            >
              {label}
              {required && (
                <span
                  aria-hidden="true"
                  className="ml-0.5 text-muted-foreground"
                >
                  *
                </span>
              )}
            </label>
          )}
          {aside && (
            <span className="text-[12px] tabular-nums text-muted-foreground">
              {aside}
            </span>
          )}
        </div>
      )}
      {children}
      <Line
        show={!error && !!hint}
        id={ids.hint}
        tone="text-muted-foreground"
        reduced={reduced}
      >
        {hint}
      </Line>
      <Line
        show={!!error}
        id={ids.error}
        tone="text-red-600 dark:text-red-400"
        reduced={reduced}
      >
        {error}
      </Line>
    </div>
  );
}

export default Field;

"use client";

import * as React from "react";
import { createPortal } from "react-dom";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * PILL SELECT: a select that's the same surface as its pill
 *
 *   open      the pill grows into its list (size and corners
 *             ease) from the edge it's lined up with, while its
 *             label fades into the options; it opens upward when
 *             there's no room below, and long lists scroll
 *   pick      the list folds back into the pill and the label
 *             morphs to the new choice; the current option
 *             carries a drawn check
 *   keys      arrows move a highlight that glides between rows,
 *             Home and End jump, typing a few letters finds an
 *             option, Enter picks, Escape folds it back
 *
 * The list lives in a portal on the page's body, placed over
 * the pill, so a clipping toolbar, fold or scroller never cuts
 * it off; it carries the theme's colours with it. Scrolling
 * the page closes it.
 *
 * Used wherever a component needs a choice from a list; never
 * the browser's own dropdown, which can't follow the theme.
 * ───────────────────────────────────────────────────────── */

export interface PillOption {
  value: string;
  label: string;
  /** A second line in the list, e.g. a sample value. */
  description?: string;
}

export interface PillSelectProps {
  options: PillOption[];
  value: string | null | undefined;
  onValueChange: (value: string) => void;
  /** Accessible name, e.g. "Column for Email". */
  label: string;
  /** Shown while nothing is chosen. */
  placeholder?: string;
  /** What the pill shows for a choice; the option's label by default. */
  display?: (option: PillOption | undefined) => string;
  /** The pill's contents, when it needs more than text (an icon that turns). */
  renderValue?: (
    option: PillOption | undefined,
    open: boolean,
  ) => React.ReactNode;
  /** Monospace labels, for code-like values (event names, column headers). */
  mono?: boolean;
  /** Which edge of the pill the list lines up with. */
  align?: "start" | "end";
  /** The list's width; never narrower than the pill. */
  width?: number;
  /** Fill the width it's given. */
  block?: boolean;
  /** Dims the pill's text, e.g. for "Don't import". */
  muted?: boolean;
  disabled?: boolean;
  /** "sm" is the 28px pill for toolbars; "md" is 36px, the height of the other form fields. */
  size?: "sm" | "md";
  className?: string;
}

type Phase = "closed" | "opening" | "open" | "closing";

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const DURATION = 420;
const MAX_LIST = 280;
const PILL_SIZE = {
  sm: "h-7 px-2.5 text-[12px]",
  md: "h-9 pl-4 pr-3.5 text-[13.5px]",
};
// The theme travels with the list, so it matches the pill wherever the pill's colours were set.
const TOKENS = [
  "--background",
  "--foreground",
  "--popover",
  "--popover-foreground",
  "--border",
  "--accent",
  "--accent-foreground",
  "--primary",
  "--primary-foreground",
  "--muted",
  "--muted-foreground",
  "--ring",
];
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function Chevron({ up, reduced }: { up: boolean; reduced: boolean }) {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      aria-hidden="true"
      className="size-3 shrink-0 text-muted-foreground"
      style={{
        transform: up ? "rotate(180deg)" : "none",
        transition: reduced ? "none" : `transform 320ms ${EASE}`,
      }}
    >
      <path
        d="M4.5 6.25 8 9.75l3.5-3.5"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

export function PillSelect({
  options,
  value,
  onValueChange,
  label,
  placeholder = "Choose",
  display,
  renderValue,
  mono = false,
  align = "start",
  width = 240,
  block = false,
  muted = false,
  disabled = false,
  size = "sm",
  className = "",
}: PillSelectProps) {
  const id = React.useId();
  const reduced = useReducedMotion();
  const [phase, setPhase] = React.useState<Phase>("closed");
  const [active, setActive] = React.useState(0);
  const [pill, setPill] = React.useState({ width: 0, height: 28 });
  const [panelHeight, setPanelHeight] = React.useState(0);
  const [fit, setFit] = React.useState({
    up: false,
    width,
    shift: 0,
    x: 0,
    y: 0,
    theme: {} as Record<string, string>,
  });
  const [highlight, setHighlight] = React.useState({
    top: 0,
    height: 0,
    ready: false,
  });
  const [quiet, setQuiet] = React.useState(false);
  const wrapRef = React.useRef<HTMLDivElement>(null);
  const triggerRef = React.useRef<HTMLButtonElement>(null);
  const panelRef = React.useRef<HTMLDivElement>(null);
  const surfaceRef = React.useRef<HTMLDivElement>(null);
  const listRef = React.useRef<HTMLDivElement>(null);
  const rowRefs = React.useRef<(HTMLDivElement | null)[]>([]);
  const timer = React.useRef(0);
  const typed = React.useRef({ text: "", at: 0 });
  const selected = options.find((o) => o.value === value);
  const expanded = phase === "open";
  const mounted = phase !== "closed";
  const [prevPhase, setPrevPhase] = React.useState(phase);
  if (phase !== prevPhase) {
    setPrevPhase(phase);
    if (phase === "closed") {
      setHighlight({ top: 0, height: 0, ready: false });
    }
  }
  const text = display ? display(selected) : (selected?.label ?? placeholder);

  const measureFit = () => {
    const wrap = wrapRef.current;
    if (!wrap) return;
    const rect = wrap.getBoundingClientRect();
    const vw = document.documentElement.clientWidth;
    const w = Math.min(Math.max(width, rect.width), vw - 24);
    // Lined up with the pill's edge, nudged back on screen.
    const shift =
      align === "start"
        ? Math.min(0, vw - 12 - (rect.left + w))
        : Math.max(0, 12 - (rect.right - w));
    const estimate =
      Math.min(
        MAX_LIST,
        options.length * (options.some((o) => o.description) ? 46 : 32),
      ) + 12;
    const vh = window.innerHeight;
    const below = vh - 8 - rect.top;
    const above = rect.bottom - 8;
    const up = below < estimate + 8 && above > below;
    // Fixed coordinates of the pill's corner the list grows from.
    const x = align === "start" ? rect.left : vw - rect.right;
    const y = up ? vh - rect.bottom : rect.top;
    const cs = getComputedStyle(wrap);
    const theme: Record<string, string> = {
      colorScheme: cs.colorScheme,
      fontFamily: cs.fontFamily,
    };
    for (const t of TOKENS) {
      const v = cs.getPropertyValue(t);
      if (v) theme[t] = v;
    }
    setFit({ up, width: w, shift, x, y, theme });
  };

  const open = () => {
    if (disabled || phase === "open" || phase === "opening") return;
    window.clearTimeout(timer.current);
    measureFit();
    setActive(
      Math.max(
        0,
        options.findIndex((o) => o.value === value),
      ),
    );
    setPhase(reduced ? "open" : "opening");
  };

  const close = React.useCallback(
    (refocus = true) => {
      window.clearTimeout(timer.current);
      if (refocus) triggerRef.current?.focus({ preventScroll: true });
      if (reduced) return setPhase("closed");
      setPhase("closing");
      timer.current = window.setTimeout(() => setPhase("closed"), DURATION);
    },
    [reduced],
  );

  React.useEffect(() => {
    if (phase !== "opening") return;
    let inner = 0;
    const outer = requestAnimationFrame(
      () => (inner = requestAnimationFrame(() => setPhase("open"))),
    );
    return () => {
      cancelAnimationFrame(outer);
      cancelAnimationFrame(inner);
    };
  }, [phase]);
  React.useEffect(() => () => window.clearTimeout(timer.current), []);

  React.useLayoutEffect(() => {
    const trigger = triggerRef.current;
    if (!trigger) return;
    const measure = () =>
      setPill((p) =>
        p.width === trigger.offsetWidth && p.height === trigger.offsetHeight
          ? p
          : { width: trigger.offsetWidth, height: trigger.offsetHeight },
      );
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(trigger);
    return () => observer.disconnect();
  }, []);

  React.useLayoutEffect(() => {
    const panel = panelRef.current;
    if (panel) setPanelHeight(panel.offsetHeight);
  }, [mounted, options]);

  // The highlight glides to the active row, and the list scrolls to keep it in view.
  React.useLayoutEffect(() => {
    const row = rowRefs.current[active];
    const list = listRef.current;
    if (!row || !list) return;
    setHighlight((h) =>
      h.top === row.offsetTop &&
      h.height === row.offsetHeight &&
      h.ready === (h.ready || expanded)
        ? h
        : {
            top: row.offsetTop,
            height: row.offsetHeight,
            ready: h.ready || expanded,
          },
    );
    const scroller = list.parentElement;
    if (scroller && scroller.scrollHeight > scroller.clientHeight) {
      if (row.offsetTop < scroller.scrollTop)
        scroller.scrollTop = row.offsetTop - 4;
      else if (
        row.offsetTop + row.offsetHeight >
        scroller.scrollTop + scroller.clientHeight
      )
        scroller.scrollTop =
          row.offsetTop + row.offsetHeight - scroller.clientHeight + 4;
    }
  }, [active, expanded, mounted]);

  React.useEffect(() => {
    if (expanded) listRef.current?.focus({ preventScroll: true });
  }, [expanded]);

  React.useEffect(() => {
    if (!expanded) return;
    const inside = (n: Node) =>
      Boolean(wrapRef.current?.contains(n) || surfaceRef.current?.contains(n));
    const onDown = (e: PointerEvent) => {
      if (!inside(e.target as Node)) close(false);
    };
    // The list sits where the pill was; if the page moves under it, it goes at once rather than fold in the wrong place.
    const gone = () => {
      window.clearTimeout(timer.current);
      setPhase("closed");
    };
    const onScroll = (e: Event) => {
      if (!surfaceRef.current?.contains(e.target as Node)) gone();
    };
    const onResize = gone;
    document.addEventListener("pointerdown", onDown);
    window.addEventListener("scroll", onScroll, true);
    window.addEventListener("resize", onResize);
    return () => {
      document.removeEventListener("pointerdown", onDown);
      window.removeEventListener("scroll", onScroll, true);
      window.removeEventListener("resize", onResize);
    };
  }, [expanded, close]);

  const choose = (o: PillOption) => {
    close();
    if (o.value !== value) onValueChange(o.value);
  };

  const onListKey = (e: React.KeyboardEvent) => {
    const last = options.length - 1;
    const move = (to: number) => {
      e.preventDefault();
      setActive(Math.max(0, Math.min(last, to)));
    };
    if (e.key === "ArrowDown") move(active === last ? 0 : active + 1);
    else if (e.key === "ArrowUp") move(active === 0 ? last : active - 1);
    else if (e.key === "Home") move(0);
    else if (e.key === "End") move(last);
    else if (e.key === "PageDown") move(active + 6);
    else if (e.key === "PageUp") move(active - 6);
    else if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      if (options[active]) choose(options[active]);
    } else if (e.key === "Tab") close(false);
    else if (e.key.length === 1 && /\S/.test(e.key)) {
      // A few letters typed quickly find the option that starts with them.
      const now = performance.now();
      typed.current = {
        text:
          (now - typed.current.at < 700 ? typed.current.text : "") +
          e.key.toLowerCase(),
        at: now,
      };
      const hit = options.findIndex((o) =>
        o.label.toLowerCase().startsWith(typed.current.text),
      );
      if (hit !== -1) setActive(hit);
    }
  };

  const w = expanded ? fit.width : pill.width;
  const h = expanded ? panelHeight : pill.height;
  const listId = `${id}-list`;
  const pillText = renderValue ? null : (
    <>
      <span
        className={`min-w-0 flex-1 truncate text-left ${mono ? "font-mono text-[11.5px]" : ""} ${muted || !selected ? "text-muted-foreground" : "text-foreground"}`}
      >
        {block ? text : <TextMorph>{text}</TextMorph>}
      </span>
      <Chevron up={expanded} reduced={reduced} />
    </>
  );

  return (
    <div
      ref={wrapRef}
      className={`relative ${block ? "flex w-full min-w-0" : "inline-flex"} ${className}`}
      onKeyDown={(e) => {
        setQuiet(false);
        if (e.key === "Escape" && expanded) {
          e.preventDefault();
          e.stopPropagation();
          close();
        }
      }}
      onBlur={(e) => {
        const to = e.relatedTarget as Node | null;
        if (
          expanded &&
          document.hasFocus() &&
          !(
            to &&
            (wrapRef.current?.contains(to) || surfaceRef.current?.contains(to))
          )
        )
          close(false);
      }}
    >
      <button
        ref={triggerRef}
        type="button"
        aria-haspopup="listbox"
        aria-expanded={expanded}
        aria-controls={mounted ? listId : undefined}
        aria-label={`${label}: ${selected?.label ?? placeholder}`}
        disabled={disabled}
        onClick={() => (expanded ? close() : open())}
        onKeyDown={(e) => {
          if (e.key === "ArrowDown" || e.key === "ArrowUp") {
            e.preventDefault();
            open();
          }
        }}
        onPointerDown={() => setQuiet(true)}
        className={`inline-flex ${PILL_SIZE[size]} min-w-0 cursor-pointer items-center gap-1.5 rounded-full font-medium whitespace-nowrap shadow-[inset_0_0_0_1px_var(--border)] transition-colors duration-150 hover:bg-accent disabled:cursor-default disabled:opacity-50 disabled:hover:bg-transparent ${block ? "w-full" : ""} ${quiet ? "outline-none" : FOCUS}`}
      >
        {renderValue ? renderValue(selected, expanded) : pillText}
      </button>

      {mounted &&
        createPortal(
          <div
            ref={surfaceRef}
            onKeyDown={(e) => {
              if (e.key === "Escape") {
                e.preventDefault();
                e.stopPropagation();
                close();
              }
            }}
            onPointerDown={(e) => {
              if (!(e.target as HTMLElement).closest("[data-scroll]"))
                e.preventDefault();
              setQuiet(true);
            }}
            className="fixed z-[60] overflow-hidden bg-popover text-popover-foreground"
            style={{
              ...fit.theme,
              [fit.up ? "bottom" : "top"]: fit.y,
              [align === "start" ? "left" : "right"]:
                fit.x +
                (expanded ? (align === "start" ? fit.shift : -fit.shift) : 0),
              width: w,
              height: h,
              borderRadius: expanded ? 16 : pill.height / 2,
              // The pill's own cavemio, the whole way: it is the same surface.
              boxShadow: "inset 0 0 0 1px var(--border)",
              transition: reduced
                ? "none"
                : `width ${DURATION}ms ${EASE}, height ${DURATION}ms ${EASE}, left ${DURATION}ms ${EASE}, right ${DURATION}ms ${EASE}, border-radius ${DURATION}ms ${EASE}`,
            }}
          >
            {/* The pill's label, fading out as the surface grows and back in as it folds. */}
            <span
              aria-hidden="true"
              className={`pointer-events-none absolute inline-flex ${PILL_SIZE[size]} items-center gap-1.5 font-medium whitespace-nowrap ${fit.up ? "bottom-0" : "top-0"} ${align === "start" ? "left-0" : "right-0"}`}
              style={{
                width: pill.width,
                opacity: expanded ? 0 : 1,
                transition: reduced
                  ? "none"
                  : `opacity ${expanded ? 120 : 260}ms ${EASE} ${expanded ? 0 : 120}ms`,
              }}
            >
              {renderValue ? renderValue(selected, expanded) : pillText}
            </span>
            <div
              ref={panelRef}
              className={`absolute p-1 ${fit.up ? "bottom-0" : "top-0"} ${align === "start" ? "left-0" : "right-0"}`}
              style={{
                width: fit.width,
                opacity: expanded ? 1 : 0,
                transition: reduced
                  ? "none"
                  : `opacity ${expanded ? 260 : 120}ms ${EASE} ${expanded ? 90 : 0}ms`,
              }}
            >
              <div
                data-scroll=""
                className="overflow-y-auto overscroll-contain"
                style={{ maxHeight: MAX_LIST }}
              >
                <div
                  ref={listRef}
                  id={listId}
                  role="listbox"
                  tabIndex={-1}
                  aria-label={label}
                  aria-activedescendant={`${id}-o${active}`}
                  onKeyDown={onListKey}
                  className="relative outline-none"
                >
                  <span
                    aria-hidden="true"
                    className="pointer-events-none absolute inset-x-0 top-0 rounded-[12px] bg-accent"
                    style={{
                      height: highlight.height,
                      transform: `translateY(${highlight.top}px)`,
                      opacity: highlight.ready ? 1 : 0,
                      transition:
                        highlight.ready && !reduced
                          ? `transform 260ms ${EASE}, height 260ms ${EASE}, opacity 200ms`
                          : "none",
                    }}
                  />
                  {options.map((o, i) => {
                    const on = o.value === value;
                    return (
                      <div
                        key={o.value}
                        ref={(el) => {
                          rowRefs.current[i] = el;
                        }}
                        id={`${id}-o${i}`}
                        role="option"
                        aria-selected={on}
                        onPointerMove={() => setActive(i)}
                        onClick={() => choose(o)}
                        className="relative flex cursor-pointer items-start gap-2 rounded-[12px] px-2.5 py-1.5"
                      >
                        <span className="min-w-0 flex-1">
                          <span
                            className={`block truncate ${mono ? "font-mono text-[12px]" : "text-[12.5px] font-medium"}`}
                          >
                            {o.label}
                          </span>
                          {o.description && (
                            <span className="mt-0.5 block truncate text-[11.5px] text-muted-foreground">
                              {o.description}
                            </span>
                          )}
                        </span>
                        <svg
                          viewBox="0 0 16 16"
                          fill="none"
                          aria-hidden="true"
                          className="mt-0.5 size-3.5 shrink-0"
                        >
                          <path
                            d="M3.5 8.5 6.5 11.5 12.5 4.5"
                            stroke="currentColor"
                            strokeWidth="1.8"
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            pathLength={1}
                            strokeDasharray={1}
                            style={{
                              strokeDashoffset: on && expanded ? 0 : 1,
                              transition: reduced
                                ? "none"
                                : `stroke-dashoffset 380ms ${EASE} 160ms`,
                            }}
                          />
                        </svg>
                      </div>
                    );
                  })}
                </div>
              </div>
            </div>
          </div>,
          document.body,
        )}
    </div>
  );
}

"use client";

import * as React from "react";

export const EASE_OUT = "cubic-bezier(0.16, 1, 0.3, 1)";
export const EASE_SETTLE = "cubic-bezier(0.22, 1.18, 0.36, 1)";
/** Thrown things (indicators, thumbs): a slight overshoot on transform only. */
export const EASE_THROW = "cubic-bezier(0.34, 1.36, 0.64, 1)";
/**
 * The press every button primitive shares: a 3% give that eases in and settles back.
 * Tailwind v4's scale-* writes the `scale` property, so `scale` has to be in the list
 * or the press snaps.
 */
export const INTERACTION_PRESS =
  "transition-[background-color,color,box-shadow,opacity,scale] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] active:scale-[0.97] motion-reduce:transition-none motion-reduce:active:scale-100";
export const INTERACTION_FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const query = "(prefers-reduced-motion: reduce)";
const subscribe = (notify: () => void) => {
  const media = window.matchMedia(query);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};
export const useInteractionReducedMotion = () =>
  React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => false,
  );

export function useInteractionActivity<T extends Element>() {
  const ref = React.useRef<T>(null);
  const [visible, setVisible] = React.useState(false);
  const [hidden, setHidden] = React.useState(false);
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(([entry]) =>
      setVisible(entry.isIntersecting),
    );
    observer.observe(el);
    const visibility = () => setHidden(document.hidden);
    visibility();
    document.addEventListener("visibilitychange", visibility);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", visibility);
    };
  }, []);
  return { ref, active: visible && !hidden };
}

export function interactionIcon(
  on: boolean,
  reduced: boolean,
): React.CSSProperties {
  return {
    opacity: on ? 1 : 0,
    transform: on ? "none" : "scale(0.6)",
    filter: on ? "blur(0px)" : "blur(3px)",
    transition: reduced
      ? "none"
      : `opacity 220ms ${EASE_OUT}, transform 380ms ${EASE_OUT}, filter 220ms ${EASE_OUT}`,
  };
}

/** Sample recent movement rather than averaging a long drag and losing its release velocity. */
export type PointerSample = { x: number; time: number };
export function samplePointer(
  samples: PointerSample[],
  x: number,
  time: number,
) {
  samples.push({ x, time });
  while (samples.length > 2 && time - samples[0].time > 100) samples.shift();
}
export function releaseVelocity(samples: PointerSample[], now: number) {
  if (samples.length < 2 || now - samples[samples.length - 1].time > 100)
    return 0;
  const first = samples[0],
    last = samples[samples.length - 1];
  return (last.x - first.x) / Math.max(1, last.time - first.time);
}

/** Smooth Apple/rational rubber-band curve: continuous exponential-like resistance without linear kinks. */
export function rubberBand(
  overshoot: number,
  dimension = 320,
  constant = 0.55,
): number {
  const d = dimension || 320;
  const abs = Math.abs(overshoot);
  return Math.sign(overshoot) * (1 - 1 / ((abs * constant) / d + 1)) * d;
}

/** Projects resting travel from release velocity (velocity in px/ms; time in seconds). */
export function projectInertia(
  distance: number,
  velocity: number,
  time = 0.12,
): number {
  return distance + velocity * 1000 * time;
}

/** Smooths incoming release velocity toward a boundary so springs don't slam or clip into walls. */
export function softenVelocity(
  velocity: number,
  distanceToTarget: number,
  factor = 10,
): number {
  const maxAllowed = Math.abs(distanceToTarget) * factor;
  return Math.sign(velocity) * Math.min(Math.abs(velocity), maxAllowed);
}

/** A damped spring sampled by WAAPI: tuned for organic lightness with a hint of life (3% breath). */
export function springFrames(
  from: number,
  to: number,
  velocity = 0,
  duration = 480,
  config: { omega?: number; damping?: number; steps?: number } = {},
) {
  const { omega = 16, damping = 0.74, steps = 36 } = config;
  const damped = omega * Math.sqrt(Math.max(0.001, 1 - damping * damping));
  const displacement = from - to;
  const coefficient =
    (velocity * 1000 + damping * omega * displacement) / damped;
  return Array.from({ length: steps + 1 }, (_, i) => {
    const t = (i / steps) * (duration / 1000);
    const value =
      to +
      Math.exp(-damping * omega * t) *
        (displacement * Math.cos(damped * t) +
          coefficient * Math.sin(damped * t));
    return { value: i === steps ? to : value, offset: i / steps };
  });
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * INLINE EDIT: rename it where it stands
 *
 *   rest      plain text in your own type; a thin line frame,
 *             sized by the text, fades in under the pointer
 *   edit      a click puts the caret exactly where you clicked
 *             (it's a real field under the text, so double-click
 *             selects a word); Tab or F2 selects it all. The text
 *             never moves: the frame just turns to the focus
 *             colour, and grows with what you type
 *   save      Enter or leaving the field. The new name stays, a
 *             spinner opens beside it and a check draws itself;
 *             if the server stores something else ("relay-web"),
 *             the text morphs into it
 *   refused   onSave throws: the field opens again with what you
 *             typed, shakes, turns red and says why under it
 *   cancel    Escape morphs the text back to the saved name
 *   elsewhere a new value from outside (someone renamed it)
 *             morphs in, unless you're in the middle of an edit
 *
 * Type comes from where you put it: the frame and its padding
 * are in em, so a 13px table cell and a 24px page title both
 * look right.
 * ───────────────────────────────────────────────────────── */

export interface InlineEditProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "defaultValue" | "onChange"
> {
  /** The saved text, controlled. */
  value?: string;
  defaultValue?: string;
  /** The saved text after a successful save. */
  onValueChange?: (value: string) => void;
  /** Saves a new value. Return what was stored (it morphs in if it differs); throw an Error to refuse with its message. */
  onSave?: (
    value: string,
    previous: string,
  ) => Promise<string | void> | string | void;
  /** Refuse a value before it's sent; the message opens under the field. */
  validate?: (value: string) => string | null | undefined | void;
  /** Applied before validating and saving. Collapses spaces and trims by default. */
  normalize?: (value: string) => string;
  /** Accessible name, e.g. "Project name". */
  label: string;
  placeholder?: string;
  /** Fill the width and wrap onto more lines (titles). Off: one line that sizes to its text (cells, breadcrumbs). */
  wrap?: boolean;
  maxLength?: number;
  /** What leaving the field does with an edit. */
  blurAction?: "save" | "cancel";
  /** An empty value cancels the edit unless allowed. */
  allowEmpty?: boolean;
  /** Submits the saved value with a form. */
  name?: string;
  disabled?: boolean;
}

type Status = "idle" | "pending" | "success" | "error";
type Morph = { from: string; to: string; key: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const TIDY = (v: string) => v.replace(/\s+/g, " ").trim();
/** Same box, same letters: the field and the text must lay out identically, so neither kerns nor ligates. */
const TYPE: React.CSSProperties = {
  fontKerning: "none",
  fontVariantLigatures: "none",
};
/** Frame padding in em, so it follows the type it's set in. */
const PAD_X = "0.4em";
const PAD_Y = "0.12em";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 240ms ${EASE}, transform 380ms ${EASE}, filter 240ms ${EASE}`,
});

/** One line of words that morphs from one text to the next: TextMorph, started from the text that was showing. */
function MorphOnce({
  from,
  to,
  onDone,
}: {
  from: string;
  to: string;
  onDone: () => void;
}) {
  const [text, setText] = React.useState(from);
  React.useEffect(() => {
    let inner = 0;
    const outer = requestAnimationFrame(
      () => (inner = requestAnimationFrame(() => setText(to))),
    );
    const timer = window.setTimeout(onDone, 780);
    return () => {
      cancelAnimationFrame(outer);
      cancelAnimationFrame(inner);
      window.clearTimeout(timer);
    };
  }, [to, onDone]);
  return <TextMorph className="whitespace-pre">{text}</TextMorph>;
}

/** Wrapped text changes as a whole: the old lines lift out through a blur while the new ones rise in. */
function SwapOnce({
  from,
  to,
  onDone,
}: {
  from: string;
  to: string;
  onDone: () => void;
}) {
  const inRef = React.useRef<HTMLSpanElement>(null);
  const outRef = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    inRef.current?.animate(
      [
        { opacity: 0, transform: "translateY(0.3em)", filter: "blur(4px)" },
        { opacity: 1, transform: "none", filter: "blur(0px)" },
      ],
      { duration: 420, delay: 60, easing: EASE, fill: "backwards" },
    );
    outRef.current?.animate(
      [
        { opacity: 1, transform: "none", filter: "blur(0px)" },
        { opacity: 0, transform: "translateY(-0.3em)", filter: "blur(4px)" },
      ],
      { duration: 220, easing: EASE, fill: "forwards" },
    );
    const timer = window.setTimeout(onDone, 560);
    return () => window.clearTimeout(timer);
  }, [onDone]);
  return (
    <span className="relative block min-w-0">
      <span ref={inRef} className="block">
        {to || " "}
      </span>
      <span
        ref={outRef}
        aria-hidden="true"
        className="pointer-events-none absolute inset-x-0 top-0 block"
      >
        {from}
      </span>
    </span>
  );
}

/** A sentence under the field that crossfades whole when it changes, and folds away when there's nothing to say. */
function Line({
  children,
  show,
  id,
  tone,
  wide,
  reduced,
}: {
  children: React.ReactNode;
  show: boolean;
  id: string;
  tone: string;
  wide: boolean;
  reduced: boolean;
}) {
  // While it folds away it keeps saying what it said, instead of emptying first.
  const [kept, setKept] = React.useState(children);
  if (show && kept !== children) {
    setKept(children);
  }
  return (
    // Under one-line text the message may run past the field's width without widening it (or wrapping what's beside it).
    <span
      className={`grid ${wide ? "[contain:inline-size]" : ""}`}
      style={{
        gridTemplateRows: show ? "1fr" : "0fr",
        transition: reduced ? "none" : `grid-template-rows 320ms ${EASE}`,
      }}
    >
      <span
        className={`min-h-0 min-w-0 ${wide ? "[clip-path:inset(0_-100vw_0_0)]" : "overflow-hidden"}`}
      >
        <span
          id={id}
          className={`block pt-1.5 text-[12.5px] leading-[1.45] font-normal tracking-normal normal-case transition-[color,opacity,filter] duration-300 ${wide ? "w-max max-w-[min(24rem,calc(100vw_-_3rem))]" : ""} ${tone}`}
          style={{ opacity: show ? 1 : 0, filter: show ? "none" : "blur(3px)" }}
        >
          {show ? children : kept}
        </span>
      </span>
    </span>
  );
}

export function InlineEdit({
  value,
  defaultValue = "",
  onValueChange,
  onSave,
  validate,
  normalize = TIDY,
  label,
  placeholder = "Untitled",
  wrap = false,
  maxLength,
  blurAction = "save",
  allowEmpty = false,
  name,
  disabled = false,
  className = "",
  ...props
}: InlineEditProps) {
  const uid = React.useId();
  const reduced = useReducedMotion();
  const [own, setOwn] = React.useState(defaultValue);
  const saved = value ?? own;
  const [editing, setEditing] = React.useState(false);
  const [focused, setFocused] = React.useState(false);
  // Edits started with the keyboard keep a focus frame after saving; a mouse user sees the text settle.
  const [viaKeys, setViaKeys] = React.useState(false);
  const [draft, setDraft] = React.useState(saved);
  const [optimistic, setOptimistic] = React.useState<string | null>(null);
  const [status, setStatus] = React.useState<Status>("idle");
  const [error, setError] = React.useState<string | null>(null);
  const [morph, setMorph] = React.useState<Morph | null>(null);
  const [announce, setAnnounce] = React.useState("");
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const fieldRef = React.useRef<HTMLTextAreaElement>(null);
  const pointerFocus = React.useRef(false);
  const selectAll = React.useRef(false);
  const saveId = React.useRef(0);
  const morphKey = React.useRef(0);
  const lastHeight = React.useRef(0);

  // What the text says when it isn't being edited: the name on its way to the server, or the saved one.
  const shown = optimistic ?? saved;
  const editingRef = React.useRef(editing);

  const startMorph = React.useCallback(
    (from: string, to: string) => {
      if (from === to || reduced) return;
      // A morph that's still running is re-aimed rather than restarted, so it never jumps.
      setMorph((m) =>
        m ? { ...m, to } : { from, to, key: ++morphKey.current },
      );
    },
    [reduced],
  );
  const morphDone = React.useCallback(() => setMorph(null), []);

  // A new value from outside (someone else renamed it) morphs in, unless you're editing.
  const [seen, setSeen] = React.useState(value);
  const currentShown = morph ? morph.to : shown;
  const [lastShown, setLastShown] = React.useState(currentShown);
  if (value !== seen) {
    setSeen(value);
    if (
      value !== undefined &&
      !editing &&
      optimistic === null &&
      value !== lastShown
    )
      startMorph(lastShown, value);
  }
  if (currentShown !== lastShown) {
    setLastShown(currentShown);
  }
  React.useLayoutEffect(() => {
    editingRef.current = editing;
  });

  const shake = () => {
    if (reduced) return;
    rootRef.current?.animate(
      [
        { transform: "none" },
        { transform: "translateX(-4px)" },
        { transform: "translateX(4px)" },
        { transform: "translateX(-2px)" },
        { transform: "none" },
      ],
      { duration: 380, easing: "ease-out" },
    );
  };

  const begin = (select: boolean, keys = select) => {
    if (disabled) return;
    if (!editing) {
      setDraft(shown);
      setEditing(true);
    }
    if (status === "success") setStatus("idle");
    selectAll.current = select;
    setViaKeys(keys);
  };

  // Keyboard entry selects everything (like renaming a file); a click leaves the caret where it landed.
  React.useLayoutEffect(() => {
    if (!editing || !selectAll.current) return;
    selectAll.current = false;
    fieldRef.current?.select();
  }, [editing]);

  const cancel = () => {
    if (draft !== saved) startMorph(draft, saved);
    setEditing(false);
    setError(null);
    if (status === "error") setStatus("idle");
  };

  const settle = (result: string, sent: string, id: number) => {
    if (id !== saveId.current) return;
    setOptimistic(null);
    if (result !== sent) startMorph(sent, result);
    if (value === undefined) setOwn(result);
    onValueChange?.(result);
    setStatus("success");
    setAnnounce(result === sent ? "Saved" : `Saved as ${result}`);
  };

  const refuse = (message: string, sent: string, id: number) => {
    if (id !== saveId.current) return;
    setOptimistic(null);
    // Already typing something newer: keep it, just say why the last one failed.
    if (!editingRef.current) setDraft(sent);
    setEditing(true);
    setStatus("error");
    setError(message);
    setAnnounce(`Not saved. ${message}`);
    shake();
  };

  const commit = () => {
    const next = normalize(draft);
    if (next === normalize(saved) || (!next && !allowEmpty)) {
      // Nothing to save (or an emptied name): the text settles back to what's saved.
      cancel();
      return;
    }
    const problem = validate?.(next);
    if (problem) {
      setError(problem);
      setStatus("error");
      setAnnounce(problem);
      shake();
      return;
    }
    const id = ++saveId.current;
    setEditing(false);
    setError(null);
    if (draft !== next) startMorph(draft, next);
    setOptimistic(next);
    let result: Promise<string | void> | string | void;
    try {
      result = onSave?.(next, saved);
    } catch (err) {
      refuse(
        err instanceof Error ? err.message : "Couldn't save that.",
        next,
        id,
      );
      return;
    }
    if (
      result &&
      typeof (result as Promise<string | void>).then === "function"
    ) {
      setStatus("pending");
      (result as Promise<string | void>).then(
        (stored) =>
          settle(typeof stored === "string" ? stored : next, next, id),
        (err) =>
          refuse(
            err instanceof Error ? err.message : "Couldn't save that.",
            next,
            id,
          ),
      );
    } else settle(typeof result === "string" ? result : next, next, id);
  };

  // The check stays a moment, then the slot closes.
  React.useEffect(() => {
    if (status !== "success") return;
    const timer = window.setTimeout(() => setStatus("idle"), 1400);
    return () => window.clearTimeout(timer);
  }, [status]);

  // Wrapped text that changes line count eases to its new height (typing follows the text at once).
  React.useLayoutEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const h = el.offsetHeight;
    const prev = lastHeight.current;
    lastHeight.current = h;
    if (wrap && !editing && !reduced && prev && Math.abs(prev - h) > 0.5)
      el.animate([{ height: `${prev}px` }, { height: `${h}px` }], {
        duration: 420,
        easing: EASE,
      });
  });

  const left = maxLength !== undefined ? maxLength - draft.length : Infinity;
  const counting = editing && left <= 10;
  const lineText =
    error ??
    (counting
      ? "count"
      : wrap && (status === "pending" || status === "success")
        ? status
        : null);
  const tone = error
    ? "text-red-600 dark:text-red-400"
    : "text-muted-foreground";
  const framed = editing || (focused && viaKeys && !disabled);
  const shell: React.CSSProperties = {
    opacity: framed || status === "error" ? 1 : undefined,
    background:
      status === "error" && error
        ? "color-mix(in oklab, #ef4444 7%, var(--background))"
        : editing
          ? "var(--background)"
          : "transparent",
    boxShadow:
      status === "error" && error
        ? "inset 0 0 0 1px color-mix(in oklab, #ef4444 45%, transparent)"
        : editing
          ? "inset 0 0 0 1px color-mix(in oklab, var(--ring) 55%, var(--border))"
          : focused && viaKeys
            ? "inset 0 0 0 1px color-mix(in oklab, var(--ring) 40%, var(--border))"
            : "inset 0 0 0 1px var(--border)",
    transition: reduced
      ? "none"
      : `opacity 160ms ${EASE}, box-shadow 200ms ${EASE}, background-color 200ms ${EASE}`,
  };
  const pad: React.CSSProperties = {
    padding: `${PAD_Y} calc(${PAD_X} + 2px) ${PAD_Y} ${PAD_X}`,
  };
  const flow = wrap
    ? "whitespace-pre-wrap [overflow-wrap:break-word]"
    : "whitespace-pre";

  let display: React.ReactNode;
  if (morph)
    display = wrap ? (
      <SwapOnce
        key={morph.key}
        from={morph.from}
        to={morph.to}
        onDone={morphDone}
      />
    ) : (
      <MorphOnce
        key={morph.key}
        from={morph.from}
        to={morph.to}
        onDone={morphDone}
      />
    );
  else
    display = shown || (
      <span className="text-muted-foreground">{placeholder}</span>
    );

  return (
    // Spans throughout: it goes inside headings, paragraphs and table cells.
    <span
      className={`${wrap ? "flex w-full flex-col" : "inline-flex max-w-full flex-col align-baseline"} ${className}`}
      {...props}
    >
      <span className={`flex min-w-0 items-center ${wrap ? "w-full" : ""}`}>
        <span
          ref={rootRef}
          className={`group relative flex min-w-0 rounded-[0.4em] ${wrap ? "w-full" : ""} ${disabled ? "" : "cursor-text"}`}
          style={{
            ...TYPE,
            ...pad,
            margin: `-${PAD_Y} -${PAD_X}`,
            overflow: "clip",
          }}
        >
          <span
            aria-hidden="true"
            className={`pointer-events-none absolute inset-0 rounded-[inherit] opacity-0 ${disabled ? "" : "group-hover:opacity-100"}`}
            style={shell}
          />
          {editing ? (
            <span
              aria-hidden="true"
              className={`invisible relative min-w-[2ch] ${wrap ? "w-full" : "overflow-hidden"} ${flow}`}
            >
              {draft || placeholder || "​"}
            </span>
          ) : (
            <span
              aria-hidden="true"
              className={`relative min-w-0 ${wrap ? `w-full ${flow}` : morph ? "whitespace-pre" : "overflow-hidden text-ellipsis whitespace-pre"}`}
            >
              {display}
            </span>
          )}
          <textarea
            ref={fieldRef}
            rows={1}
            wrap={wrap ? "soft" : "off"}
            value={editing ? draft : shown}
            disabled={disabled}
            maxLength={maxLength}
            placeholder={editing ? placeholder : undefined}
            aria-label={label}
            aria-invalid={Boolean(error) || undefined}
            aria-describedby={lineText ? `${uid}-line` : undefined}
            spellCheck={editing}
            autoComplete="off"
            onPointerDown={() => {
              pointerFocus.current = true;
            }}
            onFocus={() => {
              setFocused(true);
              begin(!pointerFocus.current);
              pointerFocus.current = false;
            }}
            onBlur={() => {
              setFocused(false);
              if (!editing) return;
              if (blurAction === "save") commit();
              else cancel();
            }}
            onChange={(e) => {
              // A title is one line: pasted line breaks become spaces.
              const text = e.target.value.replace(/\s*\r?\n\s*/g, " ");
              if (!editing) begin(false, true);
              setDraft(text);
              if (error) {
                setError(null);
                setStatus("idle");
              }
            }}
            onKeyDown={(e) => {
              if (e.nativeEvent.isComposing) return;
              if (e.key === "Enter" || (e.key === "F2" && !editing)) {
                e.preventDefault();
                if (editing) commit();
                else begin(true);
              } else if (e.key === "Escape" && editing) {
                e.preventDefault();
                e.stopPropagation();
                cancel();
              }
            }}
            className={`absolute inset-0 m-0 block size-full resize-none overflow-hidden border-0 bg-transparent outline-none placeholder:text-muted-foreground disabled:cursor-default ${flow}`}
            style={{
              ...TYPE,
              ...pad,
              font: "inherit",
              letterSpacing: "inherit",
              wordSpacing: "inherit",
              textAlign: "inherit",
              textTransform: "inherit",
              color: editing ? "inherit" : "transparent",
              caretColor: editing ? undefined : "transparent",
            }}
          />
        </span>

        {/* Spinner, drawn check or alert beside one-line text; wrapped text says it in the line below. */}
        {!wrap && (
          <span
            aria-hidden="true"
            className="relative flex h-[1em] shrink-0 items-center justify-center"
            style={{
              width: status === "idle" ? 0 : 14,
              marginLeft: status === "idle" ? 0 : 8,
              transition: reduced
                ? "none"
                : `width 380ms ${EASE}, margin 380ms ${EASE}`,
            }}
          >
            <span
              className="absolute inset-0 flex items-center justify-center"
              style={swap(status === "pending", reduced)}
            >
              <span
                className={`size-3 rounded-full border-[1.5px] border-muted-foreground border-t-transparent motion-reduce:animate-none ${status === "pending" ? "animate-spin" : ""}`}
              />
            </span>
            <span
              className="absolute inset-0 flex items-center justify-center text-emerald-600 dark:text-emerald-400"
              style={swap(status === "success", reduced)}
            >
              <Check drawn={status === "success"} reduced={reduced} />
            </span>
            <span
              className="absolute inset-0 flex items-center justify-center text-red-600 dark:text-red-400"
              style={swap(status === "error", reduced)}
            >
              <Alert />
            </span>
          </span>
        )}
      </span>

      <Line
        id={`${uid}-line`}
        show={lineText !== null}
        tone={tone}
        wide={!wrap}
        reduced={reduced}
      >
        {error ? (
          error
        ) : counting ? (
          <span className="inline-flex items-baseline tabular-nums">
            <NumberRoll value={Math.max(0, left)} duration={600} />
            <TextMorph className="ml-1">
              {left === 1 ? "character left" : "characters left"}
            </TextMorph>
          </span>
        ) : (
          <span className="inline-flex items-center gap-1.5">
            <span className="relative flex size-3.5 items-center justify-center">
              <span
                className="absolute inset-0 flex items-center justify-center"
                style={swap(status === "pending", reduced)}
              >
                <span
                  className={`size-3 rounded-full border-[1.5px] border-current border-t-transparent motion-reduce:animate-none ${status === "pending" ? "animate-spin" : ""}`}
                />
              </span>
              <span
                className="absolute inset-0 flex items-center justify-center text-emerald-600 dark:text-emerald-400"
                style={swap(status === "success", reduced)}
              >
                <Check drawn={status === "success"} reduced={reduced} />
              </span>
            </span>
            <TextMorph>{status === "success" ? "Saved" : "Saving"}</TextMorph>
          </span>
        )}
      </Line>

      {name && <input type="hidden" name={name} value={saved} />}
      <span className="sr-only" role="status" aria-live="polite">
        {announce}
      </span>
    </span>
  );
}

function Check({ drawn, reduced }: { drawn: boolean; reduced: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="none" className="size-3.5">
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 420ms ${EASE} 120ms`
              : "none",
        }}
      />
    </svg>
  );
}

function Alert() {
  return (
    <svg viewBox="0 0 16 16" fill="none" className="size-3.5">
      <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeWidth="1.5" />
      <path
        d="M8 4.75v3.75"
        stroke="currentColor"
        strokeWidth="1.75"
        strokeLinecap="round"
      />
      <circle cx="8" cy="11" r="1" fill="currentColor" />
    </svg>
  );
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * INLINE REWRITE: drag a dial, the paragraph rewrites itself
 *
 *   dial      one thumb on a track of versions (Shorter, Original,
 *             Longer; or Blunt, Neutral, Warm). Drag it, tap the
 *             track or use the arrow keys; its label morphs and
 *             it settles onto the nearest stop with a little throw
 *   rewrite   the paragraph changes in place, word by word: the
 *             words both versions share glide to their new places,
 *             the ones that go blur out where they stood, the new
 *             ones rise in one after another and glow for a moment
 *             so you can see what changed. The box eases to its
 *             new height
 *   on demand versions without text are written the first time the
 *             dial settles on them (onRewrite): a spinner opens in
 *             the thumb and a sheen runs over the paragraph until
 *             the new words arrive
 *   count     the word count rolls; +added and −cut against the
 *             original roll beside it
 * ───────────────────────────────────────────────────────── */

export interface RewriteVersion {
  label: string;
  /** Leave it out to have onRewrite write it the first time it's chosen. */
  text?: string;
}

export interface RewriteRequest {
  index: number;
  label: string;
  /** The paragraph as it reads now, and the original version. */
  current: string;
  original: string;
  /** Aborted if the component unmounts first. */
  signal: AbortSignal;
}

export interface InlineRewriteProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "children" | "defaultValue"
> {
  versions: RewriteVersion[];
  /** The chosen version's index. */
  value?: number;
  defaultValue?: number;
  onValueChange?: (index: number) => void;
  /** The version the counts compare against. Defaults to the one chosen first. */
  originalIndex?: number;
  onRewrite?: (request: RewriteRequest) => Promise<string>;
  /** Visible heading and accessible name for the slider, e.g. "Tone". */
  label?: string;
  /** Optional help text, shown beside the heading in an info tooltip. */
  description?: string;
  /** Let new words glow for a moment after each rewrite. */
  highlight?: boolean;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SHEEN =
  "[mask-image:linear-gradient(90deg,rgb(0_0_0/0.4)_35%,#000_50%,rgb(0_0_0/0.4)_65%)] [mask-size:200%_100%] animate-[ui-sheen_1.4s_linear_infinite] motion-reduce:animate-none motion-reduce:[mask-image:none]";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const split = (text: string) => text.split(/\s+/).filter(Boolean);
const clamp = (n: number, lo: number, hi: number) =>
  Math.min(hi, Math.max(lo, n));

/** Longest common subsequence table over words: dp[i][j] is the match length of a[i..] and b[j..]. */
function table(a: string[], b: string[]) {
  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);
  return dp;
}

type Word = { key: number; text: string };
type Leaving = Word & { x: number; y: number; batch: number };

/** Keep the words two texts share (and their keys); everything else is new. */
function morphWords(
  previous: Word[],
  next: string[],
  nextKey: () => number,
): Word[] {
  const a = previous.map((w) => w.text);
  const dp = table(a, next);
  const out: Word[] = [];
  let i = 0;
  let j = 0;
  while (j < next.length) {
    if (i < a.length && a[i] === next[j]) {
      out.push(previous[i]);
      i++;
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), text: next[j++] });
  }
  return out;
}

/** The paragraph: words as their own boxes so each can move, leave or arrive. */
function Words({
  text,
  reduced,
  highlight,
  className,
}: {
  text: string;
  reduced: boolean;
  highlight: boolean;
  className: string;
}) {
  const boxRef = React.useRef<HTMLParagraphElement>(null);
  const seq = React.useRef(1_000_000); // above the first render's keys
  const [words, setWords] = React.useState<Word[]>(() =>
    split(text).map((t, i) => ({ key: i + 1, text: t })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const shown = React.useRef(text);
  const flip = React.useRef<{
    first: Map<number, DOMRect>;
    height: number;
  } | null>(null);
  const batch = React.useRef(0);

  // Before the new words render: note where every word is, and keep the leaving ones where they stood.
  React.useLayoutEffect(() => {
    if (text === shown.current) return;
    shown.current = text;
    const next = morphWords(words, split(text), () => ++seq.current);
    const box = boxRef.current;
    if (!box || reduced) {
      setWords(next);
      setLeaving([]);
      return;
    }
    const b = box.getBoundingClientRect();
    const first = new Map<number, DOMRect>();
    box.querySelectorAll<HTMLElement>("[data-k]").forEach((el) => {
      // Undo the last glow's reach over the spaces (it never moved anything) so boxes are just the words.
      el.style.marginLeft = el.style.paddingLeft = el.style.borderRadius = "";
      first.set(Number(el.dataset.k), el.getBoundingClientRect());
    });
    const keep = new Set(next.map((w) => w.key));
    const id = ++batch.current;
    const gone: Leaving[] = [];
    for (const w of words) {
      const r = first.get(w.key);
      if (!keep.has(w.key) && r)
        gone.push({ ...w, x: r.left - b.left, y: r.top - b.top, batch: id });
    }
    flip.current = { first, height: b.height };
    setWords(next);
    if (gone.length) {
      setLeaving((l) => [...l, ...gone]);
      window.setTimeout(
        () => setLeaving((l) => l.filter((w) => w.batch !== id)),
        320,
      );
    }
  }, [text, reduced, words]);

  // After: glide the kept words from where they were, raise the new ones, blur the leaving ones away.
  React.useLayoutEffect(() => {
    const f = flip.current;
    const box = boxRef.current;
    if (!f || !box) return;
    flip.current = null;
    const els = Array.from(box.querySelectorAll<HTMLElement>("[data-k]"));
    box.getAnimations().forEach((a) => a.cancel());
    els.forEach((el) => el.getAnimations().forEach((a) => a.cancel()));
    const height = box.getBoundingClientRect().height;
    const rects = els.map((el) => el.getBoundingClientRect());
    if (Math.abs(height - f.height) > 0.5)
      box.animate([{ height: `${f.height}px` }, { height: `${height}px` }], {
        duration: 480,
        easing: EASE,
      });
    const primary = highlight
      ? getComputedStyle(box).getPropertyValue("--primary").trim()
      : "";
    const glow = primary
      ? `color-mix(in oklab, ${primary} 16%, transparent)`
      : "rgb(0 0 0 / 0.06)";
    const isNew = els.map((el) => !f.first.has(Number(el.dataset.k)));
    const sameLine = (i: number, j: number) =>
      Math.abs(rects[i].top - rects[j].top) < 2;
    let fresh = 0;
    els.forEach((el, i) => {
      const was = f.first.get(Number(el.dataset.k));
      if (was) {
        const dx = was.left - rects[i].left;
        const dy = was.top - rects[i].top;
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration: 480, easing: EASE },
          );
        return;
      }
      const delay = Math.min(90 + fresh++ * 14, 420);
      el.animate(
        [
          { opacity: 0, transform: "translateY(0.35em)", filter: "blur(4px)" },
          { opacity: 1, transform: "none", filter: "blur(0px)" },
        ],
        { duration: 380, delay, easing: EASE, fill: "backwards" },
      );
      if (!highlight) return;
      // New words side by side glow as one run: reach back over the space between them, round only the run's ends.
      const joinsBefore = i > 0 && isNew[i - 1] && sameLine(i - 1, i);
      const joinsAfter =
        i < els.length - 1 && isNew[i + 1] && sameLine(i, i + 1);
      if (joinsBefore) {
        const gap = Math.max(0, rects[i].left - rects[i - 1].right);
        el.style.marginLeft = `${-gap}px`;
        el.style.paddingLeft = `${gap}px`;
      }
      el.style.borderRadius = `${joinsBefore ? 0 : 4}px ${joinsAfter ? 0 : 4}px ${joinsAfter ? 0 : 4}px ${joinsBefore ? 0 : 4}px`;
      el.animate(
        [
          { backgroundColor: glow },
          { backgroundColor: glow, offset: 0.35 },
          { backgroundColor: "transparent" },
        ],
        {
          duration: 1800,
          delay,
          easing: "ease-out",
          fill: "backwards",
        },
      );
    });
    box
      .querySelectorAll<HTMLElement>("[data-leave]:not([data-out])")
      .forEach((el) => {
        el.dataset.out = "";
        el.animate(
          [
            { opacity: 1, transform: "none", filter: "blur(0px)" },
            {
              opacity: 0,
              transform: "translateY(-0.2em) scale(0.96)",
              filter: "blur(4px)",
            },
          ],
          { duration: 240, easing: EASE, fill: "forwards" },
        );
      });
  }, [words, highlight]);

  return (
    <p ref={boxRef} className={`relative ${className}`}>
      {words.map((w, i) => (
        <React.Fragment key={w.key}>
          {i > 0 && " "}
          <span data-k={w.key} className="inline-block">
            {w.text}
          </span>
        </React.Fragment>
      ))}
      {leaving.map((w) => (
        <span
          key={`gone-${w.batch}-${w.key}`}
          data-leave=""
          aria-hidden="true"
          className="pointer-events-none absolute whitespace-nowrap"
          style={{ left: w.x, top: w.y }}
        >
          {w.text}
        </span>
      ))}
    </p>
  );
}

/** A gradient track with a floating value label and a circular thumb. */
function Dial({
  labels,
  index,
  busy,
  label,
  description,
  reduced,
  onMove,
}: {
  labels: string[];
  index: number;
  busy: boolean;
  label: string;
  description?: string;
  reduced: boolean;
  onMove: (index: number, settled: boolean) => void;
}) {
  const trackRef = React.useRef<HTMLDivElement>(null);
  const thumbRef = React.useRef<HTMLDivElement>(null);
  const headingRef = React.useRef<HTMLDivElement>(null);
  const badgeRef = React.useRef<HTMLDivElement>(null);
  const descriptionId = React.useId();
  const [size, setSize] = React.useState({ width: 0, heading: 0, badge: 0 });
  const [ready, setReady] = React.useState(false);
  const [drag, setDrag] = React.useState<number | null>(null);
  const live = React.useRef({ index, drag: null as number | null });
  live.current = { index, drag };
  const n = labels.length;
  const disabled = n < 2;

  React.useLayoutEffect(() => {
    const track = trackRef.current;
    if (!track) return;
    const measure = () => {
      setSize({
        width: track.clientWidth,
        heading: headingRef.current?.offsetWidth ?? 0,
        badge: badgeRef.current?.offsetWidth ?? 0,
      });
    };
    measure();
    const frame = requestAnimationFrame(() => setReady(true));
    const observer = new ResizeObserver(measure);
    observer.observe(track);
    if (headingRef.current) observer.observe(headingRef.current);
    if (badgeRef.current) observer.observe(badgeRef.current);
    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
    };
  }, []);

  const pad = Math.min(11, size.width / 2);
  const span = Math.max(1, size.width - pad * 2);
  const stopX = (i: number) =>
    n < 2 ? size.width / 2 : pad + (i * span) / (n - 1);
  const nearest = (x: number) =>
    n < 2 ? 0 : clamp(Math.round(((x - pad) / span) * (n - 1)), 0, n - 1);
  const x = drag === null ? stopX(index) : clamp(drag, pad, size.width - pad);
  // Keep the value inside the component, clear of the heading at the first stops.
  const badgeHalf = size.badge / 2;
  const badgeX = clamp(
    x,
    Math.min(size.heading + 12 + badgeHalf, size.width - badgeHalf),
    size.width - badgeHalf,
  );
  const arrowX = x - badgeX + badgeHalf;
  const transition = (property: string) =>
    drag !== null || reduced || !ready ? "none" : `${property} 420ms ${EASE}`;

  const at = (e: React.PointerEvent) =>
    e.clientX - (trackRef.current?.getBoundingClientRect().left ?? 0);
  const follow = (px: number, settled: boolean) => {
    const i = nearest(px);
    if (i !== live.current.index || settled) onMove(i, settled);
  };
  const finish = () => {
    const px = live.current.drag;
    if (px === null) return;
    live.current.drag = null;
    setDrag(null);
    follow(px, true);
  };

  const onKey = (e: React.KeyboardEvent) => {
    if (disabled) return;
    const steps: Record<string, number> = {
      ArrowLeft: -1,
      ArrowDown: -1,
      ArrowRight: 1,
      ArrowUp: 1,
    };
    let next: number | null = null;
    if (e.key in steps) next = clamp(index + steps[e.key], 0, n - 1);
    if (e.key === "Home") next = 0;
    if (e.key === "End") next = n - 1;
    if (next === null) return;
    e.preventDefault();
    if (next !== index) onMove(next, true);
  };

  return (
    <div>
      <div className="flex h-7 items-center">
        <div ref={headingRef} className="flex items-center gap-2">
          <span className="text-[14px] font-medium text-foreground">
            {label}
          </span>
          {description && (
            <span className="group/info relative inline-flex">
              <button
                type="button"
                aria-label={`About ${label}`}
                aria-describedby={descriptionId}
                className="inline-flex size-4 items-center justify-center rounded-full text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40"
              >
                <svg
                  viewBox="0 0 20 20"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="1.6"
                  aria-hidden="true"
                  className="size-4"
                >
                  <circle cx="10" cy="10" r="8" />
                  <path d="M10 9v5" />
                  <circle
                    cx="10"
                    cy="6"
                    r=".8"
                    fill="currentColor"
                    stroke="none"
                  />
                </svg>
              </button>
              <span
                id={descriptionId}
                role="tooltip"
                className="pointer-events-none invisible absolute left-0 top-full z-20 mt-2 w-48 rounded-lg border border-border bg-background px-3 py-2 text-[12px] leading-relaxed text-muted-foreground shadow-sm group-hover/info:visible group-focus-within/info:visible"
              >
                {description}
              </span>
            </span>
          )}
        </div>
      </div>
      <div
        ref={trackRef}
        onPointerDown={(e) => {
          if (disabled || e.button !== 0 || !e.isPrimary) return;
          e.currentTarget.setPointerCapture(e.pointerId);
          const px = at(e);
          live.current.drag = px;
          setDrag(px);
          follow(px, false);
          thumbRef.current?.focus({ preventScroll: true });
        }}
        onPointerMove={(e) => {
          if (live.current.drag === null || !e.isPrimary) return;
          const px = at(e);
          live.current.drag = px;
          setDrag(px);
          follow(px, false);
        }}
        onPointerUp={finish}
        onPointerCancel={finish}
        onLostPointerCapture={finish}
        className={`relative mt-2 h-7 w-full touch-pan-y select-none ${
          disabled
            ? "cursor-default"
            : drag === null
              ? "cursor-pointer"
              : "cursor-grabbing"
        }`}
      >
        <div
          aria-hidden="true"
          className="pointer-events-none absolute inset-x-0 top-1/2 h-3 -translate-y-1/2 overflow-hidden rounded-full bg-muted"
        >
          <div
            className="h-full rounded-full bg-linear-to-r from-muted to-primary"
            style={{ width: x, transition: transition("width") }}
          />
        </div>
        <div
          ref={badgeRef}
          aria-hidden="true"
          className="pointer-events-none absolute bottom-[calc(50%+20px)] flex max-w-full -translate-x-1/2 items-center rounded-xl bg-muted px-3.5 py-1 text-[13px] leading-5 text-muted-foreground dark:bg-muted"
          style={{
            left: badgeX,
            opacity: size.width ? 1 : 0,
            transition: transition("left"),
          }}
        >
          <span
            className="absolute -bottom-[3px] size-2 -translate-x-1/2 rotate-45 bg-inherit"
            style={{
              left: arrowX,
              opacity: arrowX >= 8 && arrowX <= size.badge - 8 ? 1 : 0,
            }}
          />
          <span className="relative truncate">
            <TextMorph animateWidth={false}>{labels[index] ?? ""}</TextMorph>
          </span>
        </div>
        <div
          ref={thumbRef}
          role="slider"
          tabIndex={disabled ? -1 : 0}
          aria-label={label}
          aria-describedby={description ? descriptionId : undefined}
          aria-orientation="horizontal"
          aria-valuemin={0}
          aria-valuemax={Math.max(0, n - 1)}
          aria-valuenow={Math.max(0, index)}
          aria-valuetext={labels[index]}
          aria-disabled={disabled || undefined}
          aria-busy={busy || undefined}
          onKeyDown={onKey}
          className={`absolute top-1/2 flex size-[22px] -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-full border border-border bg-background text-muted-foreground shadow-[0_2px_6px_#0000001a,0_1px_2px_#0000000d] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 focus-visible:ring-offset-2 focus-visible:ring-offset-background dark:border-border dark:bg-background ${
            disabled
              ? "cursor-default"
              : drag === null
                ? "cursor-grab"
                : "cursor-grabbing"
          }`}
          style={{
            left: x,
            opacity: size.width ? 1 : 0,
            transition: transition("left"),
          }}
        >
          {busy && (
            <span
              aria-hidden="true"
              className="size-3 animate-spin rounded-full border-[1.5px] border-current border-t-transparent motion-reduce:animate-none"
            />
          )}
        </div>
      </div>
      <div
        aria-hidden="true"
        className="mt-1 flex justify-between gap-3 text-[13px] leading-5 text-muted-foreground"
      >
        <span>{labels[0]}</span>
        {n > 1 && <span className="text-right">{labels[n - 1]}</span>}
      </div>
    </div>
  );
}

export function InlineRewrite({
  versions,
  value,
  defaultValue = 0,
  onValueChange,
  originalIndex,
  onRewrite,
  label = "Rewrite",
  description,
  highlight = true,
  className = "",
  ...props
}: InlineRewriteProps) {
  const reduced = useReducedMotion();
  const [own, setOwn] = React.useState(defaultValue);
  const index = clamp(value ?? own, 0, versions.length - 1);
  const [first] = React.useState(index);
  const original = originalIndex ?? first;
  const [made, setMade] = React.useState<Record<number, string>>({});
  const textAt = (i: number) => versions[i]?.text ?? made[i];
  const [shown, setShown] = React.useState(() =>
    textAt(index) !== undefined ? index : original,
  );
  const [settled, setSettled] = React.useState(true);
  const [busy, setBusy] = React.useState<number | null>(null);
  const [failed, setFailed] = React.useState(false);
  const inflight = React.useRef(new Set<number>());
  const controllers = React.useRef(new Set<AbortController>());
  const latest = React.useRef({
    shown,
    original,
    value,
    onValueChange,
    onRewrite,
    versions,
    made,
  });
  latest.current = {
    shown,
    original,
    value,
    onValueChange,
    onRewrite,
    versions,
    made,
  };

  const choose = (i: number, done: boolean) => {
    setSettled(done);
    if (i === index) return;
    setFailed(false);
    if (value === undefined) setOwn(i);
    onValueChange?.(i);
  };

  // Show the chosen version as soon as it has words; write it first if it has none (once the dial settles).
  React.useEffect(() => {
    if (textAt(index) !== undefined) {
      setShown(index);
      return;
    }
    const { onRewrite: rewrite } = latest.current;
    if (!settled || !rewrite || inflight.current.has(index)) return;
    const i = index;
    const controller = new AbortController();
    controllers.current.add(controller);
    inflight.current.add(i);
    setBusy(i);
    setFailed(false);
    const at = (n: number) =>
      latest.current.versions[n]?.text ?? latest.current.made[n] ?? "";
    rewrite({
      index: i,
      label: versions[i].label,
      current: at(latest.current.shown),
      original: at(latest.current.original),
      signal: controller.signal,
    })
      .then((t) => {
        if (!controller.signal.aborted) setMade((m) => ({ ...m, [i]: t }));
      })
      .catch(() => {
        if (controller.signal.aborted) return;
        // It didn't work: the dial goes back to what the paragraph says.
        setFailed(true);
        const back = latest.current.shown;
        if (latest.current.value === undefined) setOwn(back);
        latest.current.onValueChange?.(back);
      })
      .finally(() => {
        inflight.current.delete(i);
        controllers.current.delete(controller);
        setBusy((b) => (b === i ? null : b));
      });
  }, [index, settled, made, versions]);

  React.useEffect(() => {
    if (!failed) return;
    const timer = window.setTimeout(() => setFailed(false), 4000);
    return () => window.clearTimeout(timer);
  }, [failed]);

  React.useEffect(() => {
    const all = controllers.current;
    return () => all.forEach((c) => c.abort());
  }, []);

  const words = split(textAt(shown) ?? "");
  const base = split(textAt(original) ?? "");
  const common = React.useMemo(
    () => table(base, words)[0][0],
    [base.join(" "), words.join(" ")],
  );
  const added = words.length - common;
  const cut = base.length - common;
  const working = busy !== null && busy === index;
  const status = failed ? "Couldn’t rewrite it" : working ? "Rewriting" : "";

  return (
    <div className={`@container w-full ${className}`} {...props}>
      <Dial
        labels={versions.map((v) => v.label)}
        index={index}
        busy={working}
        label={label}
        description={description}
        reduced={reduced}
        onMove={choose}
      />

      <Words
        text={textAt(shown) ?? ""}
        reduced={reduced}
        highlight={highlight}
        className={`mt-4 text-[14px] leading-[1.65] text-foreground @md:text-[15px] ${working ? SHEEN : ""}`}
      />

      <div className="mt-3 flex items-center gap-2.5 text-[12px] tabular-nums text-muted-foreground">
        <span>
          <NumberRoll value={words.length} />{" "}
          <TextMorph>{words.length === 1 ? "word" : "words"}</TextMorph>
        </span>
        <span
          aria-hidden="true"
          className="size-[3px] rounded-full bg-muted-foreground/40"
        />
        {/* Against the original: the counts, or the word "Original" when you're on it. */}
        <span className="grid">
          <span
            className="col-start-1 row-start-1 flex gap-2"
            aria-hidden={shown === original}
            style={{
              opacity: shown === original ? 0 : 1,
              transition: `opacity 220ms ${EASE}`,
            }}
          >
            <span className="text-[var(--success,var(--color-emerald-600))]">
              +<NumberRoll value={added} />
            </span>
            <span className="text-destructive">
              −<NumberRoll value={cut} />
            </span>
          </span>
          <span
            className="col-start-1 row-start-1"
            aria-hidden={shown !== original}
            style={{
              opacity: shown === original ? 1 : 0,
              transition: `opacity 220ms ${EASE}`,
            }}
          >
            Original
          </span>
        </span>
        <span className={`ml-auto ${failed ? "text-destructive" : ""}`}>
          <TextMorph>{status}</TextMorph>
        </span>
      </div>
      <p className="sr-only" role="status">
        {failed
          ? "Couldn’t rewrite it. Try again."
          : `${versions[shown]?.label ?? ""}, ${words.length} words`}
      </p>
    </div>
  );
}

"use client";

import * as React from "react";
import {
  Field,
  fieldSurface,
  setNativeValue,
  useFieldIds,
  useShake,
  type FieldSize,
} from "./imported-field";
import {
  EASE_OUT,
  INTERACTION_FOCUS,
  interactionIcon,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * INPUT: a one-line field
 *
 *   rest     a thin line pill; hover darkens the line
 *   focus    the line turns to the ring with a 3px halo
 *   typing   a clear button folds in once there is text and
 *            folds away when it's gone (it hands focus back)
 *   error    the line turns red, the hint gives way to the
 *            error and the field shakes once
 * ───────────────────────────────────────────────────────── */

export interface InputProps extends Omit<
  React.InputHTMLAttributes<HTMLInputElement>,
  "size"
> {
  label?: React.ReactNode;
  hint?: React.ReactNode;
  /** Shows red and replaces the hint. */
  error?: React.ReactNode;
  /** An icon or text before the value. */
  leading?: React.ReactNode;
  /** An icon, text or button after the value. */
  trailing?: React.ReactNode;
  /** A button that empties the field once it has text. */
  clearable?: boolean;
  /** 28px or 36px tall. */
  size?: FieldSize;
  /** Called with the new text on every change. */
  onValueChange?: (value: string) => void;
  ref?: React.Ref<HTMLInputElement>;
  /** Class for the outer column. */
  className?: string;
  /** Class for the input element itself. */
  inputClassName?: string;
}

function ClearIcon() {
  return (
    <svg viewBox="0 0 16 16" fill="none" className="size-3.5">
      <path
        d="M4.5 4.5l7 7M11.5 4.5l-7 7"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
      />
    </svg>
  );
}

export function Input({
  label,
  hint,
  error,
  leading,
  trailing,
  clearable,
  size = "md",
  onValueChange,
  ref,
  id,
  className = "",
  inputClassName = "",
  value,
  defaultValue,
  onChange,
  disabled,
  required,
  ...props
}: InputProps) {
  const reduced = useInteractionReducedMotion();
  const ids = useFieldIds(id);
  const inner = React.useRef<HTMLInputElement>(null);
  const [text, setText] = React.useState(String(defaultValue ?? ""));
  const current = value !== undefined ? String(value) : text;
  const shakeRef = useShake<HTMLDivElement>(!!error);
  const sm = size === "sm";
  const showClear = !!clearable && current.length > 0 && !disabled;

  const setRefs = (el: HTMLInputElement | null) => {
    inner.current = el;
    if (typeof ref === "function") ref(el);
    else if (ref)
      (ref as React.RefObject<HTMLInputElement | null>).current = el;
  };

  const describedBy =
    [hint && !error ? ids.hint : null, error ? ids.error : null]
      .filter(Boolean)
      .join(" ") || undefined;

  return (
    <Field
      id={ids.id}
      label={label}
      hint={hint}
      error={error}
      required={required}
      className={className}
    >
      <div
        ref={shakeRef}
        className={`${fieldSurface({ invalid: !!error, disabled })} ${sm ? "h-7 text-[16px] sm:text-[12.5px]" : "h-9 text-[16px] sm:text-[13.5px]"}`}
      >
        {leading && (
          <span
            className={`flex shrink-0 items-center text-muted-foreground ${sm ? "pl-2.5" : "pl-3.5"} [&_svg]:size-3.5`}
          >
            {leading}
          </span>
        )}
        <input
          ref={setRefs}
          id={ids.id}
          value={value}
          defaultValue={defaultValue}
          disabled={disabled}
          required={required}
          aria-invalid={error ? true : undefined}
          aria-describedby={describedBy}
          onChange={(e) => {
            if (value === undefined) setText(e.target.value);
            onChange?.(e);
            onValueChange?.(e.target.value);
          }}
          className={`h-full min-w-0 flex-1 bg-transparent outline-none placeholder:text-muted-foreground/70 ${leading ? "pl-2" : sm ? "pl-3" : "pl-4"} ${trailing || clearable ? "pr-1" : sm ? "pr-3" : "pr-4"} ${inputClassName}`}
          {...props}
        />
        {clearable && (
          // The clear button folds its own width open, so the text never jumps.
          <span
            className="grid shrink-0"
            style={{
              gridTemplateColumns: showClear ? "1fr" : "0fr",
              transition: reduced
                ? "none"
                : `grid-template-columns 320ms ${EASE_OUT}`,
            }}
          >
            <span className="min-w-0 overflow-hidden">
              <button
                type="button"
                tabIndex={showClear ? 0 : -1}
                aria-hidden={!showClear}
                aria-label="Clear"
                onClick={() => {
                  if (!inner.current) return;
                  setNativeValue(inner.current, "");
                  inner.current.focus();
                }}
                className={`mr-1 flex items-center justify-center rounded-full text-muted-foreground cursor-pointer hover:bg-accent hover:text-foreground ${sm ? "size-5" : "size-7"} ${INTERACTION_FOCUS}`}
                style={interactionIcon(showClear, reduced)}
              >
                <ClearIcon />
              </button>
            </span>
          </span>
        )}
        {trailing && (
          <span
            className={`flex shrink-0 items-center text-muted-foreground ${sm ? "pr-1" : "pr-1.5"} [&_svg]:size-3.5`}
          >
            {trailing}
          </span>
        )}
      </div>
    </Field>
  );
}

export default Input;

"use client";

import * as React from "react";
import { ArrowUpRight, Search, Unplug } from "lucide-react";
import { ConfirmAction } from "./confirm-action";
