"use client";

import * as React from "react";
import { ArrowUpRight, Search } from "lucide-react";
import { Fetch, type FetchHandle } from "./fetch-dog";
import { Input } from "./input";
import { TextMorph } from "./text-morph";
import {
  EASE_OUT,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * NOT FOUND: Fetch goes and looks for it
 *
 *   lost     a 404 engraved into the lit stage and Fetch, a
 *            puppy, sitting in front of it; your popular pages
 *            are listed under the search
 *   sniff    typing: nose to the ground, a twitch per key
 *   fetch    350ms after the typing stops, search() runs and he
 *            sprints off the edge of the stage; a newer query
 *            aborts the older one
 *   found    he runs back in with a newspaper and the results
 *            drop in under the field
 *   stick    nothing found: he comes back with a stick, and
 *            your links come back too
 *
 * search(query, signal) is yours: your site search, your docs
 * index, a fetch to your own API.
 * ───────────────────────────────────────────────────────── */

export interface NotFoundResult {
  title: string;
  href: string;
  /** A short line under the title: a section, a path, a date. */
  hint?: string;
}

export interface NotFoundProps {
  /** Find pages for a query; aborted when a newer one starts. */
  search: (query: string, signal: AbortSignal) => Promise<NotFoundResult[]>;
  /** Shown before anyone searches, and when nothing is found. */
  links?: NotFoundResult[];
  /** The address that wasn't found, shown under the title. */
  path?: string;
  homeHref?: string;
  /** What the puppy is called in his lines. */
  name?: string;
  className?: string;
}

const mix = (color: string, amount: number, into = "transparent") =>
  `color-mix(in oklab, ${color} ${amount}%, ${into})`;
const PF = "var(--primary-foreground)";
const CARD: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, var(--card), ${mix("var(--card)", 95, "var(--foreground)")})`,
  boxShadow: `0 0 0 1px var(--border), inset 0 1px 0 ${mix("var(--background)", 85)}`,
};
const STAGE: React.CSSProperties = {
  backgroundColor: "var(--primary)",
  backgroundImage: [
    `radial-gradient(60% 70% at 26% 100%, ${mix(PF, 22)} 0%, transparent 70%)`,
    `linear-gradient(175deg, transparent 40%, ${mix("black", 22)} 100%)`,
  ].join(", "),
  boxShadow: `inset 0 1px 0 ${mix(PF, 36)}, inset 0 0 0 1px ${mix(PF, 12)}`,
};

type Phase = "idle" | "typing" | "fetching" | "found" | "none" | "error";

export function NotFound({
  search,
  links = [],
  path,
  homeHref = "/",
  name = "Fetch",
  className = "",
}: NotFoundProps) {
  const reduced = useInteractionReducedMotion();
  const baseId = React.useId();
  const dog = React.useRef<FetchHandle>(null);
  const [query, setQuery] = React.useState("");
  const [phase, setPhase] = React.useState<Phase>("idle");
  const [results, setResults] = React.useState<NotFoundResult[]>([]);
  const [shown, setShown] = React.useState(0);
  const run = React.useRef<{ timer: number; ctrl: AbortController | null }>({
    timer: 0,
    ctrl: null,
  });
  const searchRef = React.useRef(search);
  React.useEffect(() => {
    searchRef.current = search;
  });
  React.useEffect(
    () => () => {
      window.clearTimeout(run.current.timer);
      run.current.ctrl?.abort();
    },
    [],
  );

  const change = (next: string) => {
    setQuery(next);
    window.clearTimeout(run.current.timer);
    run.current.ctrl?.abort();
    const q = next.trim();
    if (!q) {
      setPhase("idle");
      dog.current?.back("sit");
      return;
    }
    setPhase("typing");
    dog.current?.sniff();
    run.current.timer = window.setTimeout(async () => {
      const ctrl = new AbortController();
      run.current.ctrl = ctrl;
      setPhase("fetching");
      dog.current?.go();
      try {
        const found = await searchRef.current(q, ctrl.signal);
        if (ctrl.signal.aborted) return;
        setResults(found);
        setShown((n) => n + 1);
        setPhase(found.length ? "found" : "none");
        dog.current?.back(found.length ? "paper" : "stick");
      } catch {
        if (ctrl.signal.aborted) return;
        setPhase("error");
        dog.current?.back("sit");
      }
    }, 350);
  };

  const mood =
    phase === "fetching"
      ? `${name} is fetching…`
      : phase === "typing"
        ? `${name} has a scent`
        : phase === "found"
          ? `${name} found ${results.length === 1 ? "one" : results.length}`
          : phase === "none"
            ? "fetch() came back with a stick"
            : phase === "error"
              ? `${name} couldn’t get out`
              : `${name} lost this page too`;
  const list =
    phase === "found"
      ? results
      : phase === "fetching" && results.length
        ? results
        : links;
  const listTitle =
    phase === "found" || (phase === "fetching" && results.length)
      ? "Found"
      : phase === "none"
        ? "Try one of these"
        : "Popular pages";

  return (
    <section
      aria-labelledby={`${baseId}-title`}
      className={`relative w-full max-w-[380px] rounded-[28px] p-2 text-card-foreground ${className}`}
      style={CARD}
    >
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 380px)" }}
      />
      <div className="@container w-full">
        <div
          className="relative overflow-clip rounded-[22px] text-primary-foreground"
          style={STAGE}
        >
          <Fetch ref={dog} reduced={reduced}>
            {/* the signature: a 404 engraved into the stage, outlines only */}
            <span
              aria-hidden="true"
              className="absolute select-none font-semibold leading-none tracking-[-0.06em]"
              style={{
                left: 166,
                top: 34,
                fontSize: 104,
                color: "transparent",
                WebkitTextStroke: `1px ${mix(PF, 34)}`,
              }}
            >
              404
            </span>
            {/* the floor he sits on */}
            <span
              aria-hidden="true"
              className="absolute inset-x-0 h-px"
              style={{ top: 152, background: mix(PF, 18) }}
            />
          </Fetch>
          <p className="absolute left-3.5 top-3 z-10 text-[12.5px] font-medium text-primary-foreground/85">
            <TextMorph>{mood}</TextMorph>
          </p>
        </div>

        <div className="px-3 pb-2 pt-3">
          <h2
            id={`${baseId}-title`}
            className="text-[15px] font-medium tracking-[-0.01em]"
          >
            Page not found
          </h2>
          <p className="mt-0.5 text-[12.5px] text-muted-foreground">
            {path ? (
              <>
                Nothing lives at{" "}
                <span className="font-mono text-[12px] text-foreground">
                  {path}
                </span>
                .{" "}
              </>
            ) : (
              "This page moved or never existed. "
            )}
            Ask {name} to find it.
          </p>
          <Input
            className="mt-3"
            aria-label="Search the site"
            placeholder="Search pages"
            leading={<Search />}
            clearable
            value={query}
            onValueChange={change}
            autoComplete="off"
            spellCheck={false}
          />

          {list.length > 0 && (
            <div className="mt-3">
              <p className="px-1 text-[11.5px] font-medium text-muted-foreground">
                <TextMorph>{listTitle}</TextMorph>
              </p>
              <ul
                key={`${listTitle}-${shown}`}
                className="mt-1"
                aria-live="polite"
              >
                {list.slice(0, 5).map((r, i) => (
                  <li
                    key={r.href}
                    style={
                      reduced
                        ? undefined
                        : {
                            animation: `ui-fade-up 360ms ${EASE_OUT} ${i * 50}ms backwards`,
                          }
                    }
                  >
                    <a
                      href={r.href}
                      className="group flex min-h-10 items-center gap-2 rounded-[10px] px-2 py-1.5 outline-none hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring/40"
                    >
                      <span className="min-w-0 flex-1">
                        <span className="block truncate text-[13px] font-medium">
                          {r.title}
                        </span>
                        {r.hint && (
                          <span className="block truncate text-[11.5px] text-muted-foreground">
                            {r.hint}
                          </span>
                        )}
                      </span>
                      <ArrowUpRight className="size-3.5 shrink-0 text-muted-foreground transition-transform duration-200 group-hover:-translate-y-0.5 group-hover:translate-x-0.5" />
                    </a>
                  </li>
                ))}
              </ul>
            </div>
          )}

          <a
            href={homeHref}
            className="mt-2 inline-block px-1 text-[12.5px] text-muted-foreground underline decoration-border underline-offset-2 hover:text-foreground"
          >
            Take me home
          </a>
        </div>
      </div>
    </section>
  );
}

export default NotFound;

"use client";

import * as React from "react";
import { Archive, Bell, X } from "lucide-react";
import { NumberRoll } from "./number-roll";
import { RelativeTime, toTime, type DateLike } from "./relative-time";
import { StatusButton, type ActionStatus } from "./status-button";
import { TextMorph } from "./text-morph";
import { useRowMotion } from "./use-row-motion";

/* ─────────────────────────────────────────────────────────
 * NOTIFICATION INBOX: the bell, done properly
 *
 *   arrive    a new notification rings the bell (a short swing
 *             from its top) and the count rolls; if the inbox is
 *             open it fades in on top while the rest glide down
 *   open      the bell's own circle grows into the inbox: size
 *             and corners ease, the bell fades into the list,
 *             and it folds back the same way
 *   tabs      Unread / All, the highlight sliding between them;
 *             Unread counts as you go
 *   read      opening a notification reads it; the dot shrinks,
 *             the title settles to grey, and in Unread the row
 *             folds away a moment later. Mark all read does
 *             them together
 *   archive   the row folds away and the rest glide up
 *   empty     "You're all caught up", with a drawn check
 *
 * Items are plain records; subscribe() feeds new ones from
 * Knock, Novu, Supabase Realtime or your own stream.
 * ───────────────────────────────────────────────────────── */

export type { DateLike };

export interface InboxItem {
  id: string;
  title: string;
  body?: string;
  at: DateLike;
  read?: boolean;
  actor?: { name: string; image?: string };
  /** Where opening it goes. */
  href?: string;
}

export interface NotificationInboxProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "defaultValue" | "onChange"
> {
  value?: InboxItem[];
  defaultValue?: InboxItem[];
  onValueChange?: (items: InboxItem[]) => void;
  /** Feeds new notifications: call push with one or many; return a function that stops it. */
  subscribe?: (push: (items: InboxItem | InboxItem[]) => void) => () => void;
  /** Saves read state. Throw to put it back. */
  onRead?: (ids: string[], read: boolean) => Promise<unknown> | unknown;
  onArchive?: (ids: string[]) => Promise<unknown> | unknown;
  /** Called when a notification is opened (after it's marked read). */
  onOpen?: (item: InboxItem) => void;
  /** Older notifications, newest first; an empty list means there are no more. */
  loadMore?: (before: InboxItem) => Promise<InboxItem[]>;
  /** Which edge of the bell the inbox lines up with. */
  align?: "end" | "start";
  label?: string;
  defaultOpen?: boolean;
}

type Phase = "closed" | "opening" | "open" | "closing";

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const DURATION = 460;
const WIDTH = 384;
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const NONE: InboxItem[] = [];

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const DAY = 86_400_000;
const groupOf = (at: DateLike) => {
  const t = new Date(toTime(at));
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const start = today.getTime();
  return t.getTime() >= start
    ? "Today"
    : t.getTime() >= start - DAY
      ? "Yesterday"
      : "Earlier";
};

function Avatar({ item }: { item: InboxItem }) {
  if (item.actor?.image)
    return (
      <img
        src={item.actor.image}
        alt=""
        className="size-7 shrink-0 rounded-full object-cover shadow-[0_0_0_1px_var(--border)]"
      />
    );
  const letters = (item.actor?.name ?? "•")
    .split(/\s+/)
    .slice(0, 2)
    .map((w) => w[0]?.toUpperCase())
    .join("");
  return (
    <span
      aria-hidden="true"
      className="grid size-7 shrink-0 place-items-center rounded-full bg-muted text-[10.5px] font-medium text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)]"
    >
      {letters}
    </span>
  );
}

interface RowProps {
  item: InboxItem;
  reduced: boolean;
  canArchive: boolean;
  act: React.RefObject<{
    open: (i: InboxItem) => void;
    read: (i: InboxItem, read: boolean) => void;
    archive: (i: InboxItem) => void;
  }>;
}

const Row = React.memo(function Row({
  item,
  reduced,
  canArchive,
  act,
}: RowProps) {
  const unread = !item.read;
  const Body = item.href ? "a" : "button";
  return (
    <li data-row-id={item.id} className="group relative">
      <Body
        {...(item.href ? { href: item.href } : { type: "button" as const })}
        onClick={() => act.current.open(item)}
        className={`flex w-full cursor-pointer items-start gap-3 rounded-[12px] px-3 py-2.5 pr-16 text-left transition-colors hover:bg-accent/60 ${FOCUS}`}
      >
        <span className="relative mt-0.5">
          <Avatar item={item} />
        </span>
        <span className="min-w-0 flex-1">
          <span
            className={`block text-[13px] leading-[1.4] transition-colors duration-500 ${unread ? "font-medium text-foreground" : "text-muted-foreground"}`}
          >
            {item.title}
            <span className="sr-only">{unread ? ", unread" : ""}</span>
          </span>
          {item.body && (
            <span className="mt-0.5 line-clamp-2 block text-[12px] leading-[1.45] text-muted-foreground">
              {item.body}
            </span>
          )}
          <span className="mt-1 block text-[11px] text-muted-foreground">
            <RelativeTime date={item.at} />
          </span>
        </span>
      </Body>
      {/* The unread dot doubles as the read / unread toggle; archive sits beside it. */}
      <span className="absolute top-2.5 right-2 flex items-center gap-0.5">
        {canArchive && (
          <button
            type="button"
            aria-label={`Archive “${item.title}”`}
            onClick={() => act.current.archive(item)}
            className={`grid size-7 cursor-pointer place-items-center rounded-full text-muted-foreground opacity-0 transition-[opacity,background-color,color] group-focus-within:opacity-100 group-hover:opacity-100 hover:bg-accent hover:text-foreground [@media(pointer:coarse)]:opacity-100 ${FOCUS}`}
          >
            <Archive
              className="size-3.5"
              strokeWidth={1.75}
              aria-hidden="true"
            />
          </button>
        )}
        <button
          type="button"
          aria-label={
            unread ? `Mark “${item.title}” read` : `Mark “${item.title}” unread`
          }
          aria-pressed={!unread}
          onClick={() => act.current.read(item, unread)}
          className={`grid size-7 cursor-pointer place-items-center rounded-full transition-colors hover:bg-accent ${FOCUS}`}
        >
          <span
            aria-hidden="true"
            className={`size-2 rounded-full transition-[transform,background-color,box-shadow] ${unread ? "bg-primary" : "bg-transparent shadow-[inset_0_0_0_1px_var(--border)] group-hover:shadow-[inset_0_0_0_1px_var(--muted-foreground)]"}`}
            style={{
              transform: unread ? "scale(1)" : "scale(0.8)",
              transitionDuration: reduced ? "0ms" : "420ms",
              transitionTimingFunction: EASE,
            }}
          />
        </button>
      </span>
    </li>
  );
});

export function NotificationInbox({
  value,
  defaultValue = NONE,
  onValueChange,
  subscribe,
  onRead,
  onArchive,
  onOpen,
  loadMore,
  align = "end",
  label = "Inbox",
  defaultOpen = false,
  className = "",
  ...props
}: NotificationInboxProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const [inner, setInner] = React.useState(defaultValue);
  const items = value ?? inner;
  const [phase, setPhase] = React.useState<Phase>(
    defaultOpen ? "open" : "closed",
  );
  const [tab, setTab] = React.useState<"unread" | "all">("unread");
  const [leaving, setLeaving] = React.useState<string[]>([]);
  const [markAll, setMarkAll] = React.useState<ActionStatus>("idle");
  const [loading, setLoading] = React.useState(false);
  const [noMore, setNoMore] = React.useState(!loadMore);
  const [panelHeight, setPanelHeight] = React.useState(0);
  const [fit, setFit] = React.useState({ width: WIDTH, shift: 0 });
  const [announce, setAnnounce] = React.useState("");
  const [bar, setBar] = React.useState({ left: 0, width: 0, ready: false });
  const wrapRef = React.useRef<HTMLDivElement>(null);
  const bellRef = React.useRef<HTMLButtonElement>(null);
  const iconRef = React.useRef<HTMLSpanElement>(null);
  const panelRef = React.useRef<HTMLDivElement>(null);
  const listRef = React.useRef<HTMLUListElement>(null);
  const ghostRef = React.useRef<HTMLDivElement>(null);
  const tabRefs = React.useRef<Record<string, HTMLButtonElement | null>>({});
  const timer = React.useRef(0);
  const latest = React.useRef(items);
  React.useLayoutEffect(() => {
    latest.current = items;
  });
  const expanded = phase === "open";
  const mounted = phase !== "closed";

  const commit = React.useCallback(
    (next: InboxItem[]) => {
      if (value === undefined) setInner(next);
      onValueChange?.(next);
    },
    [value, onValueChange],
  );

  const unreadCount = items.filter((i) => !i.read).length;
  const shown = items.filter(
    (i) => tab === "all" || !i.read || leaving.includes(i.id),
  );
  const rows: (
    { kind: "head"; key: string } | { kind: "item"; item: InboxItem }
  )[] = [];
  let lastGroup = "";
  for (const item of shown) {
    const g = groupOf(item.at);
    if (g !== lastGroup) rows.push({ kind: "head", key: `head-${g}` });
    lastGroup = g;
    rows.push({ kind: "item", item });
  }
  const ranks = new Map(
    rows.map((r, i) => [r.kind === "head" ? r.key : r.item.id, i]),
  );
  useRowMotion(listRef, { reduced, ranks, ghosts: ghostRef, resetKey: tab });

  // New notifications: the bell swings, the count rolls.
  const ring = React.useCallback(() => {
    if (reduced) return;
    iconRef.current?.animate(
      [
        { transform: "rotate(0deg)" },
        { transform: "rotate(-16deg)" },
        { transform: "rotate(13deg)" },
        { transform: "rotate(-8deg)" },
        { transform: "rotate(4deg)" },
        { transform: "rotate(0deg)" },
      ],
      { duration: 720, easing: "ease-out" },
    );
  }, [reduced]);

  React.useEffect(() => {
    if (!subscribe) return;
    return subscribe((incoming) => {
      const list = Array.isArray(incoming) ? incoming : [incoming];
      const fresh = list.filter(
        (n) => !latest.current.some((i) => i.id === n.id),
      );
      if (!fresh.length) return;
      commit([...fresh, ...latest.current]);
      ring();
      setAnnounce(
        fresh.length === 1
          ? `New: ${fresh[0].title}`
          : `${fresh.length} new notifications`,
      );
    });
  }, [subscribe, commit, ring]);

  const measureFit = () => {
    const wrap = wrapRef.current;
    if (!wrap) return;
    const r = wrap.getBoundingClientRect();
    const vw = document.documentElement.clientWidth;
    const width = Math.min(WIDTH, vw - 24);
    // Lined up with the bell's edge, nudged back on screen.
    const shift =
      align === "end"
        ? Math.max(0, 12 - (r.right - width))
        : Math.min(0, vw - 12 - (r.left + width));
    setFit((f) =>
      f.width === width && f.shift === shift ? f : { width, shift },
    );
  };

  // Opened from the start: fit it to the screen before the first paint.
  React.useLayoutEffect(() => {
    if (defaultOpen) measureFit();
  }, []);

  const open = () => {
    if (phase === "open" || phase === "opening") return;
    window.clearTimeout(timer.current);
    measureFit();
    setPhase(reduced ? "open" : "opening");
  };
  const close = React.useCallback(
    (refocus = true) => {
      window.clearTimeout(timer.current);
      if (refocus) bellRef.current?.focus({ preventScroll: true });
      if (reduced) return setPhase("closed");
      setPhase("closing");
      timer.current = window.setTimeout(() => setPhase("closed"), DURATION);
    },
    [reduced],
  );

  React.useEffect(() => {
    if (phase !== "opening") return;
    let inner = 0;
    const outer = requestAnimationFrame(
      () => (inner = requestAnimationFrame(() => setPhase("open"))),
    );
    return () => {
      cancelAnimationFrame(outer);
      cancelAnimationFrame(inner);
    };
  }, [phase]);
  React.useEffect(() => () => window.clearTimeout(timer.current), []);

  React.useLayoutEffect(() => {
    const panel = panelRef.current;
    if (!panel) return;
    const measure = () => setPanelHeight(panel.offsetHeight);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(panel);
    return () => observer.disconnect();
  }, [mounted]);

  React.useLayoutEffect(() => {
    const b = tabRefs.current[tab];
    if (!b) return;
    setBar((p) =>
      p.left === b.offsetLeft && p.width === b.offsetWidth
        ? p
        : { left: b.offsetLeft, width: b.offsetWidth, ready: p.width > 0 },
    );
  }, [tab, mounted, unreadCount]);

  React.useEffect(() => {
    if (expanded) tabRefs.current[tab]?.focus({ preventScroll: true });
  }, [expanded]);

  React.useEffect(() => {
    if (!expanded) return;
    const onDown = (e: PointerEvent) => {
      if (!wrapRef.current?.contains(e.target as Node)) close(false);
    };
    document.addEventListener("pointerdown", onDown);
    return () => document.removeEventListener("pointerdown", onDown);
  }, [expanded, close]);

  const setRead = async (ids: string[], read: boolean) => {
    const before = latest.current;
    commit(before.map((i) => (ids.includes(i.id) ? { ...i, read } : i)));
    if (read && tab === "unread") {
      // Read rows stay a moment in Unread, then fold away.
      setLeaving((l) => [...l, ...ids]);
      window.setTimeout(
        () => setLeaving((l) => l.filter((x) => !ids.includes(x))),
        900,
      );
    }
    try {
      await onRead?.(ids, read);
    } catch {
      commit(
        latest.current.map((i) =>
          ids.includes(i.id) ? { ...i, read: !read } : i,
        ),
      );
      setAnnounce("That change couldn't be saved.");
    }
  };

  const act = React.useRef<RowProps["act"]["current"]>(null!);
  React.useLayoutEffect(() => {
    act.current = {
      open: (item) => {
        if (!item.read) setRead([item.id], true);
        onOpen?.(item);
      },
      read: (item, read) => {
        setRead([item.id], read);
        setAnnounce(read ? "Marked read." : "Marked unread.");
      },
      archive: async (item) => {
        const before = latest.current;
        commit(before.filter((i) => i.id !== item.id));
        setAnnounce("Archived.");
        try {
          await onArchive?.([item.id]);
        } catch {
          commit(
            [item, ...latest.current].sort(
              (a, b) => toTime(b.at) - toTime(a.at),
            ),
          );
          setAnnounce("That couldn't be archived.");
        }
      },
    };
  });

  const readAll = async () => {
    const ids = latest.current.filter((i) => !i.read).map((i) => i.id);
    if (!ids.length) return;
    setMarkAll("pending");
    try {
      await setRead(ids, true);
      setMarkAll("success");
      setAnnounce("All marked read.");
    } catch {
      setMarkAll("error");
    }
  };

  const more = async () => {
    const last = latest.current[latest.current.length - 1];
    if (!loadMore || !last || loading) return;
    setLoading(true);
    try {
      const older = await loadMore(last);
      if (!older.length) setNoMore(true);
      else
        commit([
          ...latest.current,
          ...older.filter((o) => !latest.current.some((i) => i.id === o.id)),
        ]);
    } finally {
      setLoading(false);
    }
  };

  const width = expanded ? fit.width : 36;
  const height = expanded ? panelHeight : 36;
  const empty = !shown.length;

  return (
    <div
      ref={wrapRef}
      className={`relative inline-flex ${className}`}
      onKeyDown={(e) => {
        if (e.key === "Escape" && expanded) {
          e.preventDefault();
          close();
        }
      }}
      {...props}
    >
      <button
        ref={bellRef}
        type="button"
        aria-label={`${label}${unreadCount ? `, ${unreadCount} unread` : ""}`}
        aria-haspopup="dialog"
        aria-expanded={expanded}
        aria-controls={mounted ? `${id}-panel` : undefined}
        onClick={() => (expanded ? close() : open())}
        className={`relative grid size-9 cursor-pointer place-items-center rounded-full text-foreground shadow-[inset_0_0_0_1px_var(--border)] transition-colors hover:bg-accent ${FOCUS}`}
      >
        <span ref={iconRef} className="grid origin-top place-items-center">
          <Bell className="size-4" strokeWidth={1.75} aria-hidden="true" />
        </span>
        <span
          aria-hidden="true"
          className="absolute -top-1 -right-1 inline-flex h-4 min-w-4 items-center justify-center rounded-full bg-primary px-1 text-[10px] font-medium text-primary-foreground tabular-nums shadow-[0_0_0_2px_var(--background)]"
          // Hidden while the inbox is open: the count is in the Unread tab then.
          style={{
            transform: unreadCount && !mounted ? "scale(1)" : "scale(0)",
            transition: reduced
              ? "none"
              : `transform 380ms ${unreadCount && !mounted ? "cubic-bezier(0.34,1.36,0.64,1)" : EASE}`,
          }}
        >
          <NumberRoll value={Math.min(99, unreadCount || 1)} />
        </span>
      </button>

      {mounted && (
        <div
          id={`${id}-panel`}
          role="dialog"
          aria-label={label}
          className="absolute top-0 z-40 overflow-hidden bg-popover text-popover-foreground"
          style={{
            [align === "end" ? "right" : "left"]: expanded
              ? align === "end"
                ? -fit.shift
                : fit.shift
              : 0,
            width,
            height,
            borderRadius: expanded ? 20 : 18,
            boxShadow: "inset 0 0 0 1px var(--border)",
            transition: reduced
              ? "none"
              : `width ${DURATION}ms ${EASE}, height ${DURATION}ms ${EASE}, right ${DURATION}ms ${EASE}, left ${DURATION}ms ${EASE}, border-radius ${DURATION}ms ${EASE}`,
          }}
        >
          {/* The bell, fading as its circle grows into the inbox. */}
          <span
            aria-hidden="true"
            className={`pointer-events-none absolute top-0 grid size-9 place-items-center ${align === "end" ? "right-0" : "left-0"}`}
            style={{
              opacity: expanded ? 0 : 1,
              transition: reduced
                ? "none"
                : `opacity ${expanded ? 140 : 260}ms ${EASE} ${expanded ? 0 : 140}ms`,
            }}
          >
            <Bell className="size-4" strokeWidth={1.75} />
          </span>

          <div
            ref={panelRef}
            inert={!expanded}
            className={`absolute top-0 ${align === "end" ? "right-0" : "left-0"}`}
            style={{
              width: fit.width,
              opacity: expanded ? 1 : 0,
              transition: reduced
                ? "none"
                : `opacity ${expanded ? 280 : 120}ms ${EASE} ${expanded ? 100 : 0}ms`,
            }}
          >
            <div className="flex items-center gap-2 px-3 pt-3 pb-2">
              <div
                role="tablist"
                aria-label={label}
                className="relative flex items-center gap-0.5"
              >
                <span
                  aria-hidden="true"
                  className="absolute top-0 left-0 h-7 rounded-full bg-accent shadow-[inset_0_0_0_1px_var(--border)]"
                  style={{
                    width: bar.width,
                    transform: `translateX(${bar.left}px)`,
                    transition:
                      bar.ready && !reduced
                        ? `transform 360ms ${EASE}, width 360ms ${EASE}`
                        : "none",
                  }}
                />
                {(["unread", "all"] as const).map((t) => (
                  <button
                    key={t}
                    ref={(el) => {
                      tabRefs.current[t] = el;
                    }}
                    role="tab"
                    aria-selected={tab === t}
                    tabIndex={tab === t ? 0 : -1}
                    onClick={() => setTab(t)}
                    onKeyDown={(e) => {
                      if (e.key !== "ArrowLeft" && e.key !== "ArrowRight")
                        return;
                      e.preventDefault();
                      const next = t === "unread" ? "all" : "unread";
                      setTab(next);
                      tabRefs.current[next]?.focus();
                    }}
                    className={`relative inline-flex h-7 cursor-pointer items-center gap-1.5 rounded-full px-3 text-[12.5px] font-medium transition-colors ${FOCUS} ${tab === t ? "text-foreground" : "text-muted-foreground hover:text-foreground"}`}
                  >
                    {t === "unread" ? "Unread" : "All"}
                    {t === "unread" && (
                      <span className="text-[11.5px] font-normal text-muted-foreground tabular-nums">
                        <NumberRoll value={unreadCount} />
                      </span>
                    )}
                  </button>
                ))}
              </div>
              <span className="ml-auto" />
              {onRead && (
                <StatusButton
                  size="sm"
                  variant="ghost"
                  status={markAll}
                  labels={{
                    idle: "Mark all read",
                    pending: "Marking",
                    success: "All read",
                    error: "Try again",
                  }}
                  onClick={readAll}
                  onReset={() => setMarkAll("idle")}
                  aria-disabled={
                    (!unreadCount && markAll === "idle") || undefined
                  }
                  className={
                    !unreadCount && markAll === "idle"
                      ? "pointer-events-none opacity-40"
                      : ""
                  }
                />
              )}
              <button
                type="button"
                aria-label={`Close ${label.toLowerCase()}`}
                onClick={() => close()}
                className={`grid size-7 shrink-0 cursor-pointer place-items-center rounded-full text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
              >
                <X className="size-3.5" strokeWidth={1.75} aria-hidden="true" />
              </button>
            </div>

            <div
              className="max-h-[min(26rem,calc(100dvh_-_10rem))] overflow-y-auto overscroll-contain px-1.5 pb-1.5"
              role="tabpanel"
            >
              <div className="relative">
                <ul
                  ref={listRef}
                  aria-label={
                    tab === "unread"
                      ? "Unread notifications"
                      : "All notifications"
                  }
                  className="relative"
                >
                  {rows.map((r) =>
                    r.kind === "head" ? (
                      <li
                        key={r.key}
                        data-row-id={r.key}
                        aria-hidden="true"
                        className="px-3 pt-2 pb-1 text-[11px] font-medium text-muted-foreground"
                      >
                        {r.key.slice(5)}
                      </li>
                    ) : (
                      <Row
                        key={r.item.id}
                        item={r.item}
                        reduced={reduced}
                        canArchive={Boolean(onArchive)}
                        act={act}
                      />
                    ),
                  )}
                </ul>
                <div
                  ref={ghostRef}
                  aria-hidden="true"
                  className="pointer-events-none absolute inset-0"
                />
              </div>

              <div
                className="grid"
                style={{
                  gridTemplateRows: empty ? "1fr" : "0fr",
                  opacity: empty ? 1 : 0,
                  transition: reduced
                    ? "none"
                    : `grid-template-rows 420ms ${EASE}, opacity 300ms ${EASE} ${empty ? 120 : 0}ms`,
                }}
              >
                <div className="min-h-0 min-w-0 overflow-clip">
                  <div className="flex flex-col items-center gap-2 py-9 text-center">
                    <span className="grid size-9 place-items-center rounded-full text-emerald-600 shadow-[inset_0_0_0_1px_var(--border)] dark:text-emerald-400">
                      <svg
                        viewBox="0 0 16 16"
                        fill="none"
                        aria-hidden="true"
                        className="size-4"
                      >
                        <path
                          d="M3.5 8.5 6.5 11.5 12.5 4.5"
                          stroke="currentColor"
                          strokeWidth="1.8"
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          pathLength={1}
                          strokeDasharray={1}
                          style={{
                            strokeDashoffset: empty && expanded ? 0 : 1,
                            transition: reduced
                              ? "none"
                              : `stroke-dashoffset 480ms ${EASE} 260ms`,
                          }}
                        />
                      </svg>
                    </span>
                    <p className="text-[13px] font-medium">
                      {tab === "unread"
                        ? "You're all caught up"
                        : "Nothing here yet"}
                    </p>
                    <p className="text-[12px] text-muted-foreground">
                      {tab === "unread"
                        ? "New notifications will show up here."
                        : "When something happens, you'll hear about it here."}
                    </p>
                  </div>
                </div>
              </div>

              {loadMore && !noMore && tab === "all" && !empty && (
                <div className="flex justify-center py-1.5">
                  <button
                    type="button"
                    onClick={more}
                    aria-busy={loading || undefined}
                    className={`h-7 cursor-pointer rounded-full px-3 text-[12px] font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
                  >
                    <TextMorph>{loading ? "Loading" : "Show older"}</TextMorph>
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      <span className="sr-only" role="status">
        {announce}
      </span>
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

/* ─────────────────────────────────────────────────────────
 * OAUTH WINDOW: open a provider's sign-in in a small window
 * and wait for your callback page to say how it went
 *
 *   open      a centred popup on the provider's authorise URL.
 *             Call it straight from the click (before any await)
 *             or the browser will block it
 *   done      your callback page (same origin as the app) posts
 *             { type: "oauth:done", ...whatever you need } to
 *             window.opener, and on a BroadcastChannel as well,
 *             then closes itself
 *   closed    if the window closes without a message, the
 *             promise rejects so the row can say so
 *
 * The callback page, for example /integrations/callback:
 *
 *   const data = { type: "oauth:done", account: { name: "Northwind" } };
 *   window.opener?.postMessage(data, location.origin);
 *   new BroadcastChannel("oauth").postMessage(data);
 *   window.close();
 * ───────────────────────────────────────────────────────── */

export interface OAuthWindowOptions {
  /** Window name; one per provider keeps a second click on the same window. */
  name?: string;
  width?: number;
  height?: number;
  /** The message type your callback page posts. */
  type?: string;
  /** Give up after this long (ms). */
  timeout?: number;
}

export function openOAuthWindow<
  T extends Record<string, unknown> = Record<string, unknown>,
>(url: string, options: OAuthWindowOptions = {}): Promise<T> {
  const {
    name = "oauth",
    width = 520,
    height = 680,
    type = "oauth:done",
    timeout = 10 * 60_000,
  } = options;
  const left = Math.round(window.screenX + (window.outerWidth - width) / 2);
  const top = Math.round(window.screenY + (window.outerHeight - height) / 2.5);
  const popup = window.open(
    url,
    name,
    `popup=yes,width=${width},height=${height},left=${left},top=${top}`,
  );
  if (!popup)
    return Promise.reject(
      new Error(
        "The sign-in window was blocked. Allow pop-ups for this site and try again.",
      ),
    );
  popup.focus();

  return new Promise<T>((resolve, reject) => {
    const channel =
      "BroadcastChannel" in window ? new BroadcastChannel("oauth") : null;
    let settled = false;
    let closedAt = 0;

    const finish = (data: unknown) => {
      if (settled) return;
      const msg = data as { type?: string; error?: string } | null;
      if (!msg || msg.type !== type) return;
      settled = true;
      cleanup();
      if (msg.error) reject(new Error(String(msg.error)));
      else resolve(msg as T);
    };
    const onMessage = (e: MessageEvent) => {
      if (e.origin === window.location.origin) finish(e.data);
    };
    const onChannel = (e: MessageEvent) => finish(e.data);
    const poll = window.setInterval(() => {
      if (!popup.closed) return;
      // The callback posts right before it closes; give that message a moment to land.
      if (!closedAt) closedAt = Date.now();
      else if (Date.now() - closedAt > 1200 && !settled) {
        settled = true;
        cleanup();
        reject(new Error("The window was closed before it finished."));
      }
    }, 300);
    const limit = window.setTimeout(() => {
      if (settled) return;
      settled = true;
      cleanup();
      reject(new Error("That took too long. Try again."));
    }, timeout);

    function cleanup() {
      window.removeEventListener("message", onMessage);
      channel?.removeEventListener("message", onChannel);
      channel?.close();
      window.clearInterval(poll);
      window.clearTimeout(limit);
      try {
        if (!popup!.closed) popup!.close();
      } catch {
        /* Already gone. */
      }
    }

    window.addEventListener("message", onMessage);
    channel?.addEventListener("message", onChannel);
  });
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * ONBOARDING CHECKLIST: the first five things, ticked off
 *
 *   next       the first open task is open in place: what it is,
 *              why it matters and the one button that does it
 *   doing      its button spins while your action runs, then a
 *              check draws itself on the row, a strike draws
 *              through the label and the next task opens
 *   progress   a ring fills and "2 of 5" rolls with every tick
 *   pick       open any task by its row, done or not
 *   folded     the whole card folds to its header (ring and
 *              count) and opens again
 *   done       the list folds away, the ring fills and becomes a
 *              check with a small burst, and the title morphs to
 *              "You're all set"
 *
 * Drive it from your data (done per task) or let it keep its own.
 * ───────────────────────────────────────────────────────── */

export interface OnboardingTask {
  id: string;
  title: string;
  description?: string;
  /** The one button that does the task. Return a promise to show progress; it's ticked off when it resolves. */
  action?: {
    label: string;
    /** Shown while a promise runs, e.g. "Connecting". */ pendingLabel?: string;
    onClick?: () => void | Promise<unknown>;
    href?: string;
  };
  /** Controlled: whether it's done. Leave out to let the checklist track it. */
  done?: boolean;
}

export interface OnboardingChecklistProps extends React.HTMLAttributes<HTMLDivElement> {
  tasks: OnboardingTask[];
  title?: string;
  doneTitle?: string;
  doneDescription?: string;
  /** Called when a task is ticked off (its action resolved). */
  onTaskComplete?: (id: string) => void;
  /** Called with "Hide" once everything is done. */
  onDismiss?: () => void;
  defaultCollapsed?: boolean;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Icons trade places through a blur: the old one shrinks away as the new one grows in. */
const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 240ms ${EASE}, transform 360ms ${EASE}, filter 240ms ${EASE}`,
});

function Check({
  drawn,
  reduced,
  width = 2,
  delay = 80,
}: {
  drawn: boolean;
  reduced: boolean;
  width?: number;
  delay?: number;
}) {
  return (
    <svg viewBox="0 0 16 16" fill="none" className="size-full">
      <path
        d="M4.2 8.4 6.8 11 11.8 5.4"
        stroke="currentColor"
        strokeWidth={width}
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 380ms ${EASE} ${delay}ms`
              : "none",
        }}
      />
    </svg>
  );
}

/** The ring that fills with progress, and becomes a check with a small burst when it's full. */
function Ring({
  value,
  complete,
  reduced,
}: {
  value: number;
  complete: boolean;
  reduced: boolean;
}) {
  const c = 2 * Math.PI * 9;
  const burstRef = React.useRef<HTMLSpanElement>(null);
  const first = React.useRef(true);
  React.useEffect(() => {
    if (first.current) {
      first.current = false;
      return;
    }
    if (!complete || reduced) return;
    const dots = burstRef.current?.children;
    if (!dots) return;
    Array.from(dots).forEach((dot, i) => {
      const angle = (i / dots.length) * Math.PI * 2;
      const dist = 20 + (i % 2) * 6;
      (dot as HTMLElement).animate(
        [
          { transform: "translate(0,0) scale(1)", opacity: 0 },
          { opacity: 1, offset: 0.2 },
          {
            transform: `translate(${Math.cos(angle) * dist}px, ${Math.sin(angle) * dist}px) scale(0.4)`,
            opacity: 0,
          },
        ],
        { duration: 700, easing: EASE, delay: 260 },
      );
    });
  }, [complete, reduced]);
  return (
    <span
      aria-hidden="true"
      className="relative flex size-6 shrink-0 items-center justify-center"
    >
      <svg
        viewBox="0 0 24 24"
        className="absolute inset-0 size-full -rotate-90"
      >
        <circle
          cx="12"
          cy="12"
          r="9"
          fill="none"
          strokeWidth="2"
          className="stroke-border"
        />
        <circle
          cx="12"
          cy="12"
          r="9"
          fill="none"
          strokeWidth="2"
          strokeLinecap="round"
          strokeDasharray={c}
          className="stroke-primary"
          style={{
            strokeDashoffset: c * (1 - value),
            transition: reduced ? "none" : `stroke-dashoffset 640ms ${EASE}`,
          }}
        />
      </svg>
      <span
        className="absolute inset-0 rounded-full bg-primary text-primary-foreground"
        style={{
          transform: complete ? "none" : "scale(0.4)",
          opacity: complete ? 1 : 0,
          transition: reduced
            ? "none"
            : `transform 460ms ${THROW} 180ms, opacity 260ms ${EASE} 180ms`,
        }}
      >
        <span className="absolute inset-[5px]">
          <Check drawn={complete} reduced={reduced} width={2.4} delay={360} />
        </span>
      </span>
      <span
        ref={burstRef}
        className="pointer-events-none absolute inset-0 flex items-center justify-center"
      >
        {Array.from({ length: 10 }, (_, i) => (
          <span
            key={i}
            className="absolute size-1 rounded-full bg-primary opacity-0"
          />
        ))}
      </span>
    </span>
  );
}

export function OnboardingChecklist({
  tasks,
  title = "Get started",
  doneTitle = "You’re all set",
  doneDescription = "Everything’s in place. Here’s to the first busy Saturday.",
  onTaskComplete,
  onDismiss,
  defaultCollapsed = false,
  className = "",
  ...props
}: OnboardingChecklistProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const [own, setOwn] = React.useState<Set<string>>(() => new Set());
  const [running, setRunning] = React.useState<string | null>(null);
  const [collapsed, setCollapsed] = React.useState(defaultCollapsed);
  const isDone = (t: OnboardingTask) => t.done ?? own.has(t.id);
  const firstOpen = tasks.find((t) => !isDone(t))?.id ?? null;
  const [picked, setPicked] = React.useState<string | null>(null);
  const openId = picked ?? firstOpen;
  const count = tasks.filter(isDone).length;
  const complete = count === tasks.length && tasks.length > 0;

  // When the open task gets done, the next open one takes over (unless someone picked a row since).
  const lastFirst = React.useRef(firstOpen);
  React.useEffect(() => {
    if (lastFirst.current !== firstOpen) {
      lastFirst.current = firstOpen;
      setPicked(null);
    }
  }, [firstOpen]);

  const run = async (task: OnboardingTask) => {
    if (!task.action || running) return;
    const result = task.action.onClick?.();
    if (task.action.href && !task.action.onClick) {
      window.location.assign(task.action.href);
      return;
    }
    if (result instanceof Promise) {
      setRunning(task.id);
      try {
        await result;
      } catch {
        setRunning(null);
        return;
      }
      setRunning(null);
    }
    if (task.done === undefined) setOwn((s) => new Set(s).add(task.id));
    onTaskComplete?.(task.id);
  };

  return (
    <section
      aria-labelledby={`${id}-title`}
      className={`w-full overflow-hidden rounded-[20px] border border-border bg-background ${className}`}
      {...props}
    >
      <div className="flex items-center gap-3 px-4 py-3.5">
        <Ring
          value={tasks.length ? count / tasks.length : 0}
          complete={complete}
          reduced={reduced}
        />
        <div className="min-w-0 flex-1">
          <h3
            id={`${id}-title`}
            className="text-[14px] font-medium leading-5 text-foreground"
          >
            <TextMorph>{complete ? doneTitle : title}</TextMorph>
          </h3>
          <p className="flex items-baseline gap-[0.3em] text-[12px] leading-4 text-muted-foreground tabular-nums">
            <NumberRoll value={count} duration={700} /> of {tasks.length} done
          </p>
        </div>
        <span role="status" className="sr-only">
          {complete ? doneTitle : `${count} of ${tasks.length} done`}
        </span>
        {complete && onDismiss ? (
          <button
            type="button"
            onClick={onDismiss}
            className={`cursor-pointer h-8 rounded-full px-3 text-[12.5px] font-medium text-foreground shadow-[inset_0_0_0_1px_var(--border)] transition-colors hover:bg-accent animate-[ui-fade-in_300ms_ease-out_400ms_both] motion-reduce:animate-none ${FOCUS}`}
          >
            Hide
          </button>
        ) : (
          <button
            type="button"
            aria-expanded={!collapsed}
            aria-controls={`${id}-list`}
            aria-label={collapsed ? "Show checklist" : "Fold checklist"}
            onClick={() => setCollapsed((c) => !c)}
            className={`cursor-pointer flex size-8 items-center justify-center rounded-full text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
          >
            <svg
              aria-hidden="true"
              viewBox="0 0 12 12"
              className="size-3 transition-transform duration-300 motion-reduce:transition-none"
              style={{
                transform: collapsed ? "none" : "rotate(180deg)",
                transitionTimingFunction: EASE,
              }}
            >
              <path
                d="m3 4.5 3 3 3-3"
                fill="none"
                stroke="currentColor"
                strokeWidth="1.4"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          </button>
        )}
      </div>

      {/* Done: the list folds away and a line says so. */}
      <div
        aria-hidden={!complete || undefined}
        className="grid"
        style={{
          gridTemplateRows: complete ? "1fr" : "0fr",
          opacity: complete ? 1 : 0,
          transition: reduced
            ? "none"
            : `grid-template-rows 460ms ${EASE} 200ms, opacity 360ms ${EASE} 320ms`,
        }}
      >
        <div className="min-h-0 overflow-hidden">
          <p className="px-4 pb-4 text-[13px] leading-relaxed text-muted-foreground">
            {doneDescription}
          </p>
        </div>
      </div>

      <div
        id={`${id}-list`}
        inert={collapsed || complete}
        className="grid"
        style={{
          gridTemplateRows: collapsed || complete ? "0fr" : "1fr",
          opacity: collapsed || complete ? 0 : 1,
          transition: reduced
            ? "none"
            : `grid-template-rows 460ms ${EASE}, opacity ${collapsed || complete ? "180ms" : "360ms"} ${EASE}`,
        }}
      >
        <div className="min-h-0 overflow-hidden">
          <ol className="border-t border-border p-1.5">
            {tasks.map((task, i) => {
              const done = isDone(task);
              const open = task.id === openId;
              const busy = running === task.id;
              return (
                <li
                  key={task.id}
                  className={`rounded-[14px] transition-colors duration-300 ${open ? "bg-accent/60" : ""}`}
                >
                  <button
                    type="button"
                    aria-expanded={open}
                    aria-controls={`${id}-t${i}`}
                    onClick={() =>
                      setPicked(
                        open
                          ? task.id === firstOpen
                            ? "__none__"
                            : null
                          : task.id,
                      )
                    }
                    className={`cursor-pointer flex w-full items-center gap-3 rounded-[14px] px-2.5 py-2.5 text-left ${FOCUS}`}
                  >
                    {/* An open ring that becomes a filled, drawn check. */}
                    <span
                      aria-hidden="true"
                      className="relative flex size-5 shrink-0 items-center justify-center"
                    >
                      <span
                        className="absolute inset-0 rounded-full shadow-[inset_0_0_0_1.5px_var(--border)]"
                        style={swap(!done, reduced)}
                      />
                      <span
                        className="absolute inset-0 rounded-full bg-foreground text-background"
                        style={swap(done, reduced)}
                      >
                        <Check drawn={done} reduced={reduced} />
                      </span>
                    </span>
                    <span className="min-w-0 flex-1 text-[13.5px]">
                      {/* The strike draws itself through the label once it's done. */}
                      <span
                        className={`bg-[linear-gradient(currentColor,currentColor)] bg-no-repeat [background-position:0_58%] transition-colors duration-300 ${done ? "text-muted-foreground" : "text-foreground"}`}
                        style={{
                          backgroundSize: done ? "100% 1px" : "0% 1px",
                          transition: reduced
                            ? "none"
                            : `background-size 480ms ${EASE} 120ms, color 300ms`,
                        }}
                      >
                        {task.title}
                      </span>
                      <span className="sr-only">{done ? ", done" : ""}</span>
                    </span>
                  </button>
                  <div
                    id={`${id}-t${i}`}
                    inert={!open}
                    className="grid"
                    style={{
                      gridTemplateRows: open ? "1fr" : "0fr",
                      opacity: open ? 1 : 0,
                      transition: reduced
                        ? "none"
                        : `grid-template-rows 420ms ${EASE}, opacity ${open ? "320ms" : "140ms"} ${EASE}`,
                    }}
                  >
                    <div className="min-h-0 overflow-hidden">
                      <div className="pb-3 pl-[42px] pr-3">
                        {task.description && (
                          <p className="text-[12.5px] leading-relaxed text-muted-foreground">
                            {task.description}
                          </p>
                        )}
                        {task.action && !done && (
                          <button
                            type="button"
                            onClick={() => run(task)}
                            aria-busy={busy || undefined}
                            className={`cursor-pointer mt-3 inline-flex h-8 items-center rounded-full bg-primary px-3.5 text-[12.5px] font-medium text-primary-foreground transition-[background-color,transform] duration-200 hover:bg-primary/90 active:scale-[0.97] ${FOCUS}`}
                          >
                            <span
                              aria-hidden="true"
                              className="flex shrink-0 items-center justify-center overflow-hidden"
                              style={{
                                width: busy ? 18 : 0,
                                transition: reduced
                                  ? "none"
                                  : `width 320ms ${EASE}`,
                              }}
                            >
                              <span
                                className={`size-3 rounded-full border-[1.5px] border-primary-foreground/40 border-t-primary-foreground motion-reduce:animate-none ${busy ? "animate-spin" : ""}`}
                              />
                            </span>
                            <TextMorph>
                              {busy
                                ? (task.action.pendingLabel ?? "Working on it")
                                : task.action.label}
                            </TextMorph>
                          </button>
                        )}
                      </div>
                    </div>
                  </div>
                </li>
              );
            })}
          </ol>
        </div>
      </div>
    </section>
  );
}

"use client";

import * as React from "react";
import { ArrowUpRight, Package } from "lucide-react";
import { CopyButton } from "./copy-button";
import { NumberRoll } from "./number-roll";
import { StatusButton, type ActionStatus } from "./status-button";
import { TextMorph } from "./text-morph";
import { useRowMotion } from "./use-row-motion";
import {
  EASE_THROW,
  INTERACTION_FOCUS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * ORDER STATUS: the parcel on its route
 *
 *   route     the lit card carries the order's route, Ordered →
 *             Packed → Shipped → Out for delivery → Delivered, as a
 *             thin line; a parcel rides it to where the order is
 *             and every stop it passes lights as it goes by
 *   arriving  the day it arrives is large; when the date moves the
 *             weekday morphs and the day rolls
 *   events    the carrier's scans, newest first; a new one slides
 *             in at the top
 *   cancel    before it ships, Cancel order asks once, then goes
 *             Cancelling → Cancelled and the route dims
 *
 * The order is yours: pass status, eta and events from your
 * database or the carrier's webhook (a refetch, a poll or a
 * socket); onCancel does the cancelling.
 * ───────────────────────────────────────────────────────── */

export type OrderStage = "ordered" | "packed" | "shipped" | "out" | "delivered";

export interface OrderEvent {
  id: string;
  at: Date | string | number;
  title: string;
  /** Where it happened, e.g. "Leeds depot". */
  place?: string;
}

export interface OrderStatusProps {
  /** Shown as "Order #HL-2048". */
  number: string;
  status: OrderStage | "cancelled";
  /** When it's expected; when it arrived once delivered. */
  eta?: Date | string | number;
  /** e.g. "by 9pm", after the date. */
  window?: string;
  /** Where it's going, one line. */
  address?: string;
  carrier?: string;
  tracking?: string;
  trackingUrl?: string;
  /** Newest first. */
  events?: OrderEvent[];
  /** Offered until the order ships; throw an Error to say why not. */
  onCancel?: () => Promise<unknown>;
  /** Events shown before Show all. */
  visibleEvents?: number;
  locale?: string;
  className?: string;
}

const STAGES: { id: OrderStage; label: string; short: string }[] = [
  { id: "ordered", label: "Order placed", short: "Ordered" },
  { id: "packed", label: "Packed", short: "Packed" },
  { id: "shipped", label: "Shipped", short: "Shipped" },
  { id: "out", label: "Out for delivery", short: "Out" },
  { id: "delivered", label: "Delivered", short: "Delivered" },
];
const EASE = "cubic-bezier(0.16,1,0.3,1)";
const RIDE = 1100;
const NONE: OrderEvent[] = [];

const subscribeNothing = () => () => {};
/** False on the server and while hydrating: text is formatted in one fixed locale until then, so the server's and the visitor's never disagree. */
const useHydrated = () =>
  React.useSyncExternalStore(
    subscribeNothing,
    () => true,
    () => false,
  );

const mix = (color: string, amount: number, into = "transparent") =>
  `color-mix(in oklab, ${color} ${amount}%, ${into})`;
const CARD_LIT: React.CSSProperties = {
  backgroundColor: "var(--primary)",
  backgroundImage: `radial-gradient(120% 80% at 0% 0%, ${mix("var(--primary-foreground)", 22)} 0%, transparent 55%), linear-gradient(175deg, transparent 40%, ${mix("black", 24)} 100%)`,
  boxShadow: `inset 0 1px 0 ${mix("var(--primary-foreground)", 36)}, inset 0 0 0 1px ${mix("var(--primary-foreground)", 12)}`,
};
const CARD: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, var(--card), ${mix("var(--card)", 95, "var(--foreground)")})`,
  boxShadow: `0 0 0 1px var(--border), inset 0 1px 0 ${mix("var(--background)", 85)}`,
};

export function OrderStatus({
  number,
  status,
  eta,
  window: timeWindow,
  address,
  carrier,
  tracking,
  trackingUrl,
  events = NONE,
  onCancel,
  visibleEvents = 3,
  locale,
  className = "",
}: OrderStatusProps) {
  const reduced = useInteractionReducedMotion();
  // Dates depend on the visitor's locale and time zone, so they're written once the block is in the browser.
  const hydrated = useHydrated();
  const baseId = React.useId();
  const [cancel, setCancel] = React.useState<{
    status: ActionStatus;
    confirm: boolean;
    error?: string;
  }>({ status: "idle", confirm: false });
  const [expanded, setExpanded] = React.useState(false);
  const listRef = React.useRef<HTMLOListElement>(null);
  const ghostRef = React.useRef<HTMLDivElement>(null);

  const cancelled = status === "cancelled" || cancel.status === "success";
  const at = Math.max(
    0,
    STAGES.findIndex((s) => s.id === status),
  );
  const stage = cancelled ? null : STAGES[at];
  const progress = at / (STAGES.length - 1);

  // Where the parcel set off from, so stops light up as it passes them, not all at once.
  const [from, setFrom] = React.useState(at);
  const [seenAt, setSeenAt] = React.useState(at);
  if (at !== seenAt) {
    setFrom(seenAt);
    setSeenAt(at);
  }
  const passDelay = (i: number) =>
    reduced || at <= from || i <= from
      ? 0
      : ((i - from) / (at - from)) * RIDE * 0.85;

  const fmt = React.useMemo(
    () => ({
      weekday: new Intl.DateTimeFormat(locale, { weekday: "long" }),
      month: new Intl.DateTimeFormat(locale, { month: "short" }),
      time: new Intl.DateTimeFormat(locale, {
        hour: "numeric",
        minute: "2-digit",
      }),
      day: new Intl.DateTimeFormat(locale, { day: "numeric", month: "short" }),
    }),
    [locale],
  );
  const etaDate = eta !== undefined && hydrated ? new Date(eta) : null;

  const rows = expanded ? events : events.slice(0, visibleEvents);
  const ranks = React.useMemo(
    () => new Map(events.map((e, i) => [e.id, i])),
    [events],
  );
  useRowMotion(listRef, { reduced, ranks, ghosts: ghostRef });

  const canCancel =
    Boolean(onCancel) &&
    (cancel.status === "success" ||
      (!cancelled && (status === "ordered" || status === "packed")));
  const cancelOrder = async () => {
    if (!onCancel || cancel.status === "pending") return;
    if (!cancel.confirm) return setCancel({ status: "idle", confirm: true });
    setCancel({ status: "pending", confirm: true });
    try {
      await onCancel();
      setCancel({ status: "success", confirm: true });
    } catch (e) {
      setCancel({
        status: "error",
        confirm: true,
        error:
          e instanceof Error && e.message
            ? e.message
            : "Couldn’t cancel. Try again.",
      });
    }
  };

  React.useEffect(() => {
    if (!cancel.confirm || cancel.status !== "idle") return;
    const timer = window.setTimeout(
      () => setCancel({ status: "idle", confirm: false }),
      4000,
    );
    return () => window.clearTimeout(timer);
  }, [cancel]);

  const headline = cancelled
    ? "Cancelled"
    : status === "delivered"
      ? "Delivered"
      : "Arriving";

  return (
    <section
      aria-labelledby={`${baseId}-title`}
      className={`w-full max-w-[420px] rounded-[28px] p-2 text-card-foreground ${className}`}
      style={CARD}
    >
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 420px)" }}
      />
      <div className="@container w-full">
        {/* The one lit surface: the arrival and the route. */}
        <div
          className="rounded-[22px] p-4 text-primary-foreground"
          style={{
            ...CARD_LIT,
            filter: cancelled ? "saturate(0.35)" : "none",
            transition: reduced ? "none" : `filter 500ms ${EASE}`,
          }}
        >
          <div className="flex items-center justify-between gap-3 text-[12.5px]">
            <h2
              id={`${baseId}-title`}
              className="font-mono text-primary-foreground/75"
            >
              Order #{number}
            </h2>
            <span
              className="rounded-full px-2 py-0.5 font-medium"
              style={{ background: mix("var(--primary-foreground)", 16) }}
              role="status"
            >
              <TextMorph>
                {cancelled ? "Cancelled" : (stage?.label ?? "")}
              </TextMorph>
            </span>
          </div>

          <p className="mt-3 text-[12.5px] text-primary-foreground/70">
            <TextMorph>{headline}</TextMorph>
          </p>
          <p
            className="mt-0.5 flex items-baseline gap-[0.28em] text-[30px] font-medium leading-none tracking-[-0.035em]"
            suppressHydrationWarning
          >
            {etaDate && !cancelled ? (
              <>
                <TextMorph>{fmt.weekday.format(etaDate)}</TextMorph>
                <span className="tabular-nums">
                  <NumberRoll value={etaDate.getDate()} duration={800} />
                </span>
                <TextMorph className="text-primary-foreground/70">
                  {fmt.month.format(etaDate)}
                </TextMorph>
              </>
            ) : (
              <span className="text-primary-foreground/60">
                {cancelled
                  ? "Not on its way"
                  : hydrated
                    ? "Date to follow"
                    : " "}
              </span>
            )}
          </p>
          {(timeWindow || address) && !cancelled && (
            <p className="mt-1.5 truncate text-[12.5px] text-primary-foreground/70">
              {[
                status === "delivered" ? null : timeWindow,
                address ? `to ${address}` : null,
              ]
                .filter(Boolean)
                .join(" · ")}
            </p>
          )}

          {/* The route: stops on a thin line, the parcel riding to where the order is. */}
          <div
            className="relative mt-5 px-3"
            style={{
              opacity: cancelled ? 0.5 : 1,
              transition: "opacity 400ms",
            }}
          >
            <div className="relative h-6">
              <span
                aria-hidden="true"
                className="absolute inset-x-0 top-1/2 h-px -translate-y-1/2"
                style={{ background: mix("var(--primary-foreground)", 26) }}
              />
              <span
                aria-hidden="true"
                className="absolute inset-x-0 top-1/2 h-[2px] origin-left -translate-y-1/2 rounded-full"
                style={{
                  background: "var(--primary-foreground)",
                  transform: `scaleX(${progress})`,
                  transition: reduced ? "none" : `transform ${RIDE}ms ${EASE}`,
                }}
              />
              <ol className="absolute inset-0 flex items-center justify-between">
                {STAGES.map((s, i) => {
                  const lit = !cancelled && i <= at;
                  return (
                    <li
                      key={s.id}
                      className="relative flex size-0 items-center justify-center"
                      aria-current={i === at && !cancelled ? "step" : undefined}
                    >
                      <span className="sr-only">{`${s.label}${lit ? (i === at ? ", current" : ", done") : ""}`}</span>
                      <span
                        aria-hidden="true"
                        className="absolute size-2.5 rounded-full"
                        style={{
                          background: lit
                            ? "var(--primary-foreground)"
                            : "var(--primary)",
                          boxShadow: `0 0 0 1.5px ${lit ? "var(--primary-foreground)" : mix("var(--primary-foreground)", 45)}`,
                          transform:
                            lit && !reduced ? "scale(1)" : "scale(0.8)",
                          transition: reduced
                            ? "none"
                            : `background-color 240ms ${EASE} ${passDelay(i)}ms, transform 420ms ${EASE_THROW} ${passDelay(i)}ms, box-shadow 240ms ${passDelay(i)}ms`,
                        }}
                      />
                    </li>
                  );
                })}
              </ol>
              {/* The parcel rides the right edge of a full-width layer that slides in from the left: one composited transform,
                    and nothing past the card's right edge to scroll to. */}
              <span
                aria-hidden="true"
                className="pointer-events-none absolute inset-0"
                style={{
                  transform: `translateX(${(progress - 1) * 100}%)`,
                  transition: reduced ? "none" : `transform ${RIDE}ms ${EASE}`,
                }}
              >
                <span
                  className="absolute right-0 top-1/2 flex size-7 translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-[9px]"
                  style={{
                    background: "var(--primary-foreground)",
                    color: "var(--primary)",
                    boxShadow: `0 0 0 3px ${mix("var(--primary-foreground)", 22)}`,
                    opacity: cancelled ? 0 : 1,
                    transition: "opacity 300ms",
                  }}
                >
                  <Package className="size-4" strokeWidth={1.9} />
                </span>
              </span>
            </div>
            <div aria-hidden="true" className="relative mt-2 h-4 text-[11px]">
              {STAGES.map((s, i) => (
                <span
                  key={s.id}
                  className="absolute top-0 whitespace-nowrap"
                  style={{
                    left: `${(i / (STAGES.length - 1)) * 100}%`,
                    transform:
                      i === 0
                        ? "translateX(-12px)"
                        : i === STAGES.length - 1
                          ? "translateX(calc(-100% + 12px))"
                          : "translateX(-50%)",
                    color:
                      !cancelled && i <= at
                        ? "var(--primary-foreground)"
                        : mix("var(--primary-foreground)", 55),
                    fontWeight: i === at && !cancelled ? 500 : 400,
                    transition: `color 240ms ${passDelay(i)}ms`,
                  }}
                >
                  {s.short}
                </span>
              ))}
            </div>
          </div>
        </div>

        {/* Flat: tracking, the scans, and Cancel while it can be. */}
        {(carrier || tracking) && (
          <div className="mx-1 mt-2 flex h-10 items-center gap-2 rounded-full px-3 text-[13px] shadow-[inset_0_0_0_1px_var(--border)]">
            <span className="shrink-0 text-muted-foreground">
              {carrier ?? "Tracking"}
            </span>
            {tracking && (
              <span className="min-w-0 flex-1 truncate font-mono text-[12.5px] text-foreground">
                {tracking}
              </span>
            )}
            {tracking && (
              <CopyButton
                text={tracking}
                label="Copy tracking number"
                size="sm"
                variant="ghost"
                className="shrink-0"
              />
            )}
            {trackingUrl && (
              <a
                href={trackingUrl}
                target="_blank"
                rel="noreferrer"
                className={`-mr-1 inline-flex h-7 shrink-0 items-center gap-0.5 rounded-full px-2 text-[12.5px] text-primary hover:bg-primary/10 ${INTERACTION_FOCUS}`}
              >
                Track
                <ArrowUpRight aria-hidden="true" className="size-3.5" />
              </a>
            )}
          </div>
        )}

        {events.length > 0 && (
          <div className="px-3 pb-1 pt-3">
            <div className="flex items-center justify-between">
              <h3 className="text-[12.5px] font-normal text-muted-foreground">
                Updates
              </h3>
              {events.length > visibleEvents && (
                <button
                  type="button"
                  aria-expanded={expanded}
                  onClick={() => setExpanded((v) => !v)}
                  className={`-mr-2 cursor-pointer rounded-full px-2 py-1 text-[12.5px] text-foreground hover:bg-accent ${INTERACTION_FOCUS}`}
                >
                  <TextMorph>
                    {expanded ? "Show less" : `Show all ${events.length}`}
                  </TextMorph>
                </button>
              )}
            </div>
            <div className="relative mt-1">
              <div
                ref={ghostRef}
                aria-hidden="true"
                className="pointer-events-none absolute inset-0"
              />
              <ol ref={listRef} className="relative">
                {rows.map((e, i) => {
                  const when = new Date(e.at);
                  return (
                    <li
                      key={e.id}
                      data-row-id={e.id}
                      className="relative flex gap-3 py-2 pl-4"
                    >
                      <span
                        aria-hidden="true"
                        className={`absolute left-0 top-[13px] size-[7px] rounded-full ${i === 0 && !cancelled ? "bg-primary shadow-[0_0_0_3px_color-mix(in_oklab,var(--primary)_18%,transparent)]" : "bg-border"}`}
                      />
                      {i < rows.length - 1 && (
                        <span
                          aria-hidden="true"
                          className="absolute bottom-[-7px] left-[3px] top-[24px] w-px bg-border"
                        />
                      )}
                      <span className="min-w-0 flex-1">
                        <span
                          className={`block text-[13.5px] ${i === 0 ? "font-medium text-foreground" : "text-foreground/85"}`}
                        >
                          {e.title}
                        </span>
                        {e.place && (
                          <span className="block truncate text-[12px] text-muted-foreground">
                            {e.place}
                          </span>
                        )}
                      </span>
                      <span
                        className="shrink-0 pt-px text-right text-[12px] tabular-nums text-muted-foreground"
                        suppressHydrationWarning
                      >
                        {hydrated ? fmt.day.format(when) : ""}
                        <span className="block">
                          {hydrated ? fmt.time.format(when) : ""}
                        </span>
                      </span>
                    </li>
                  );
                })}
              </ol>
            </div>
          </div>
        )}

        {canCancel && (
          <div className="flex flex-col items-center px-3 pb-1.5 pt-1">
            <StatusButton
              variant="ghost"
              status={cancel.status}
              labels={{
                idle: cancel.confirm
                  ? "Yes, cancel this order"
                  : "Cancel order",
                pending: "Cancelling",
                success: "Cancelled",
                error: "Try again",
              }}
              onClick={() => void cancelOrder()}
              className={`h-9 px-4 text-[13px] ${cancel.confirm && cancel.status === "idle" ? "text-red-600 hover:text-red-600 dark:text-red-400 dark:hover:text-red-400" : ""}`}
            />
            {cancel.error && (
              <p
                role="alert"
                className="mt-1 text-center text-[12px] text-red-600 dark:text-red-400"
              >
                {cancel.error}
              </p>
            )}
          </div>
        )}
      </div>
    </section>
  );
}

