"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import {
  EASE_OUT,
  EASE_THROW,
  INTERACTION_FOCUS,
  INTERACTION_PRESS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * PAGINATION: pages of a long list
 *
 *   move     the current-page mark is thrown to the new number
 *            (slight overshoot) instead of each number repainting
 *   window   first, last and the pages round the current one, with
 *            "…" between; the window keeps its width as you move
 *   narrow   in a small container it becomes ‹ "3 of 12" › and the
 *            numbers roll the way you moved
 * ───────────────────────────────────────────────────────── */

export interface PaginationProps {
  page?: number;
  defaultPage?: number;
  pageCount: number;
  onPageChange?: (page: number) => void;
  /** Pages either side of the current one. */
  siblings?: number;
  /** Build hrefs so pages are real links (good for search engines). */
  hrefFor?: (page: number) => string;
  className?: string;
}

type Slot = number | "gap-start" | "gap-end";

function windowFor(page: number, count: number, siblings: number): Slot[] {
  const total = siblings * 2 + 5;
  if (count <= total) return Array.from({ length: count }, (_, i) => i + 1);
  const left = Math.max(page - siblings, 2);
  const right = Math.min(page + siblings, count - 1);
  const showLeftGap = left > 3;
  const showRightGap = right < count - 2;
  if (!showLeftGap)
    return [
      ...Array.from({ length: 3 + siblings * 2 }, (_, i) => i + 1),
      "gap-end",
      count,
    ];
  if (!showRightGap)
    return [
      1,
      "gap-start",
      ...Array.from(
        { length: 3 + siblings * 2 },
        (_, i) => count - (2 + siblings * 2) + i,
      ),
    ];
  return [
    1,
    "gap-start",
    ...Array.from({ length: right - left + 1 }, (_, i) => left + i),
    "gap-end",
    count,
  ];
}

function Arrow({ back }: { back?: boolean }) {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      aria-hidden="true"
      className="size-3.5"
    >
      <path
        d={back ? "M10 3.5 5.5 8l4.5 4.5" : "M6 3.5 10.5 8 6 12.5"}
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

export function Pagination({
  page: controlled,
  defaultPage = 1,
  pageCount,
  onPageChange,
  siblings = 1,
  hrefFor,
  className = "",
}: PaginationProps) {
  const reduced = useInteractionReducedMotion();
  const listRef = React.useRef<HTMLDivElement>(null);
  const [own, setOwn] = React.useState(defaultPage);
  const page = Math.min(Math.max(1, controlled ?? own), Math.max(1, pageCount));
  const [mark, setMark] = React.useState<{ x: number; w: number } | null>(null);
  const [ready, setReady] = React.useState(false);
  const slots = windowFor(page, pageCount, siblings);

  const go = (p: number) => {
    const next = Math.min(Math.max(1, p), pageCount);
    if (next === page) return;
    if (controlled === undefined) setOwn(next);
    onPageChange?.(next);
  };

  React.useLayoutEffect(() => {
    const list = listRef.current;
    if (!list) return;
    const measure = () => {
      const el = list.querySelector<HTMLElement>('[aria-current="page"]');
      if (!el || !el.offsetWidth) return setMark(null);
      const next = { x: el.offsetLeft, w: el.offsetWidth };
      setMark((p) => (p && p.x === next.x && p.w === next.w ? p : next));
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(list);
    return () => ro.disconnect();
  }, [page, pageCount]);

  React.useEffect(() => {
    if (!mark || ready) return;
    const frame = requestAnimationFrame(() => setReady(true));
    return () => cancelAnimationFrame(frame);
  }, [mark, ready]);

  const btn = `inline-flex size-8 shrink-0 items-center justify-center rounded-full text-[13px] tabular-nums cursor-pointer disabled:cursor-default disabled:opacity-35 ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`;
  const linkProps = (p: number) =>
    hrefFor
      ? {
          href: hrefFor(p),
          onClick: (e: React.MouseEvent) => {
            if (e.metaKey || e.ctrlKey || e.shiftKey) return;
            e.preventDefault();
            go(p);
          },
        }
      : { onClick: () => go(p), type: "button" as const };
  const Tag = (hrefFor ? "a" : "button") as "button";

  return (
    <nav aria-label="Pagination" className={`@container w-full ${className}`}>
      <div className="flex items-center justify-center gap-1">
        <button
          type="button"
          aria-label="Previous page"
          disabled={page <= 1}
          onClick={() => go(page - 1)}
          className={`${btn} text-muted-foreground hover:bg-accent hover:text-foreground`}
        >
          <Arrow back />
        </button>

        {/* Wide: the numbers, with one mark that moves. */}
        <div
          ref={listRef}
          className="relative hidden items-center gap-1 @[22rem]:flex"
        >
          <span
            aria-hidden="true"
            className="pointer-events-none absolute left-0 top-0 h-8 rounded-full bg-foreground"
            style={{
              transform: `translateX(${mark?.x ?? 0}px)`,
              width: mark?.w ?? 0,
              opacity: mark ? 1 : 0,
              transition:
                reduced || !ready
                  ? "none"
                  : `transform 420ms ${EASE_THROW}, width 300ms ${EASE_OUT}`,
            }}
          />
          {slots.map((slot) =>
            typeof slot === "number" ? (
              <Tag
                key={slot}
                {...linkProps(slot)}
                aria-label={`Page ${slot}`}
                aria-current={slot === page ? "page" : undefined}
                className={`${btn} relative z-10 min-w-8 px-1 transition-colors duration-300 ${slot === page ? "text-background" : "text-muted-foreground hover:bg-accent hover:text-foreground"}`}
              >
                {slot}
              </Tag>
            ) : (
              <span
                key={slot}
                aria-hidden="true"
                className="inline-flex size-8 items-center justify-center text-[13px] text-muted-foreground"
              >
                …
              </span>
            ),
          )}
        </div>

        {/* Narrow: "3 of 12", rolling. */}
        <span className="inline-flex items-center gap-1 px-2 text-[13px] tabular-nums text-muted-foreground @[22rem]:hidden">
          <span className="font-medium text-foreground">
            <NumberRoll value={page} />
          </span>
          of {pageCount}
        </span>

        <button
          type="button"
          aria-label="Next page"
          disabled={page >= pageCount}
          onClick={() => go(page + 1)}
          className={`${btn} text-muted-foreground hover:bg-accent hover:text-foreground`}
        >
          <Arrow />
        </button>
      </div>
    </nav>
  );
}

export default Pagination;

"use client";

import * as React from "react";
import { Eye, EyeOff } from "lucide-react";
import { IconMorph } from "./icon-morph";
import { Input, type InputProps } from "./input";
import { TextMorph } from "./text-morph";
import {
  EASE_OUT,
  INTERACTION_FOCUS,
  INTERACTION_PRESS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * PASSWORD INPUT: show, measure, warn
 *
 *   show     the eye turns into eye-off (rotate morph) and the
 *            dots become letters; focus stays in the field
 *   measure  with `strength`, four segments fill left to right
 *            as the score climbs and the word morphs
 *            (Weak → Fair → Good → Strong)
 *   warn     Caps Lock on while typing folds a note in under it
 * ───────────────────────────────────────────────────────── */

export type PasswordScore = 0 | 1 | 2 | 3 | 4;

export interface PasswordInputProps extends Omit<
  InputProps,
  "type" | "trailing" | "clearable"
> {
  /** Show the four-segment meter. Pass a function to score it yourself (e.g. zxcvbn). */
  strength?: boolean | ((value: string) => PasswordScore);
  /** Words for scores 1 to 4. */
  strengthLabels?: [string, string, string, string];
  /** Whether the password shows as text, controlled or not. */
  shown?: boolean;
  defaultShown?: boolean;
  onShownChange?: (shown: boolean) => void;
}

/** A plain score: length and variety. Swap in zxcvbn for real checks. */
export function scorePassword(value: string): PasswordScore {
  if (!value) return 0;
  let score = 0;
  if (value.length >= 8) score++;
  if (value.length >= 12) score++;
  if (/[a-z]/.test(value) && /[A-Z]/.test(value)) score++;
  if (/\d/.test(value) && /[^A-Za-z0-9]/.test(value)) score++;
  return Math.max(1, Math.min(4, score)) as PasswordScore;
}

const TONES = [
  "bg-red-500",
  "bg-amber-500",
  "bg-emerald-500",
  "bg-emerald-500",
];
const TEXT = [
  "text-red-600 dark:text-red-400",
  "text-amber-600 dark:text-amber-400",
  "text-emerald-600 dark:text-emerald-400",
  "text-emerald-600 dark:text-emerald-400",
];

export function PasswordInput({
  strength,
  strengthLabels = ["Weak", "Fair", "Good", "Strong"],
  hint,
  value,
  defaultValue,
  onValueChange,
  onKeyDown,
  onKeyUp,
  onBlur,
  size = "md",
  shown: shownProp,
  defaultShown = false,
  onShownChange,
  ...props
}: PasswordInputProps) {
  const reduced = useInteractionReducedMotion();
  const [ownShown, setOwnShown] = React.useState(defaultShown);
  const shown = shownProp ?? ownShown;
  const [text, setText] = React.useState(String(defaultValue ?? ""));
  const [caps, setCaps] = React.useState(false);
  const current = value !== undefined ? String(value) : text;
  const score: PasswordScore =
    !strength || !current
      ? 0
      : typeof strength === "function"
        ? strength(current)
        : scorePassword(current);
  const readCaps = (e: React.KeyboardEvent<HTMLInputElement>) =>
    setCaps(e.getModifierState?.("CapsLock") ?? false);

  return (
    <div className="flex w-full flex-col">
      <Input
        {...props}
        size={size}
        type={shown ? "text" : "password"}
        autoComplete={props.autoComplete ?? "current-password"}
        value={value}
        defaultValue={defaultValue}
        hint={caps ? "Caps Lock is on" : hint}
        onValueChange={(v) => {
          if (value === undefined) setText(v);
          onValueChange?.(v);
        }}
        onKeyDown={(e) => {
          readCaps(e);
          onKeyDown?.(e);
        }}
        onKeyUp={(e) => {
          readCaps(e);
          onKeyUp?.(e);
        }}
        onBlur={(e) => {
          setCaps(false);
          onBlur?.(e);
        }}
        trailing={
          <button
            type="button"
            aria-label={shown ? "Hide password" : "Show password"}
            aria-pressed={shown}
            // Keep focus (and the caret) in the field.
            onPointerDown={(e) => e.preventDefault()}
            onClick={() => {
              if (shownProp === undefined) setOwnShown(!shown);
              onShownChange?.(!shown);
            }}
            className={`flex items-center justify-center rounded-full text-muted-foreground cursor-pointer hover:bg-accent hover:text-foreground ${size === "sm" ? "size-5" : "size-7"} ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`}
          >
            <IconMorph
              size={14}
              mode="rotate"
              active={shown}
              from={<Eye />}
              to={<EyeOff />}
            />
          </button>
        }
      />
      {strength && (
        <div className="flex items-center gap-3 px-3 pt-2" aria-live="polite">
          <div className="flex flex-1 gap-1" aria-hidden="true">
            {[1, 2, 3, 4].map((step) => (
              <span
                key={step}
                className="relative h-1 flex-1 overflow-hidden rounded-full bg-muted"
              >
                <span
                  className={`absolute inset-0 origin-left rounded-full ${TONES[Math.max(0, score - 1)]}`}
                  style={{
                    transform: score >= step ? "scaleX(1)" : "scaleX(0)",
                    transition: reduced
                      ? "none"
                      : `transform 420ms ${EASE_OUT} ${score >= step ? (step - 1) * 50 : 0}ms, background-color 300ms`,
                  }}
                />
              </span>
            ))}
          </div>
          <span
            className={`w-12 text-right text-[12px] font-medium ${score ? TEXT[score - 1] : "text-muted-foreground"}`}
          >
            <TextMorph>{score ? strengthLabels[score - 1] : " "}</TextMorph>
          </span>
        </div>
      )}
    </div>
  );
}

export default PasswordInput;

"use client";

import * as React from "react";
import { createPortal } from "react-dom";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * PILL SELECT: a select that's the same surface as its pill
 *
 *   open      the pill grows into its list (size and corners
 *             ease) from the edge it's lined up with, while its
 *             label fades into the options; it opens upward when
 *             there's no room below, and long lists scroll
 *   pick      the list folds back into the pill and the label
 *             morphs to the new choice; the current option
 *             carries a drawn check
 *   keys      arrows move a highlight that glides between rows,
 *             Home and End jump, typing a few letters finds an
 *             option, Enter picks, Escape folds it back
 *
 * The list lives in a portal on the page's body, placed over
 * the pill, so a clipping toolbar, fold or scroller never cuts
 * it off; it carries the theme's colours with it. Scrolling
 * the page closes it.
 *
 * Used wherever a component needs a choice from a list; never
 * the browser's own dropdown, which can't follow the theme.
 * ───────────────────────────────────────────────────────── */

export interface PillOption {
  value: string;
  label: string;
  /** A second line in the list, e.g. a sample value. */
  description?: string;
}

export interface PillSelectProps {
  id?: string;
  "aria-describedby"?: string;
  "aria-invalid"?: boolean;
  options: PillOption[];
  value: string | null | undefined;
  onValueChange: (value: string) => void;
  /** Accessible name, e.g. "Column for Email". */
  label: string;
  /** Shown while nothing is chosen. */
  placeholder?: string;
  /** What the pill shows for a choice; the option's label by default. */
  display?: (option: PillOption | undefined) => string;
  /** The pill's contents, when it needs more than text (an icon that turns). */
  renderValue?: (
    option: PillOption | undefined,
    open: boolean,
  ) => React.ReactNode;
  /** Monospace labels, for code-like values (event names, column headers). */
  mono?: boolean;
  /** Which edge of the pill the list lines up with. */
  align?: "start" | "end";
  /** The list's width; never narrower than the pill. */
  width?: number;
  /** Fill the width it's given. */
  block?: boolean;
  /** Dims the pill's text, e.g. for "Don't import". */
  muted?: boolean;
  disabled?: boolean;
  /** "sm" is the 28px pill for toolbars; "md" is 36px, the height of the other form fields. */
  size?: "sm" | "md";
  className?: string;
}

type Phase = "closed" | "opening" | "open" | "closing";

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const DURATION = 420;
const MAX_LIST = 280;
const PILL_SIZE = {
  sm: "h-7 px-2.5 text-[12px]",
  md: "h-9 pl-4 pr-3.5 text-[13.5px]",
};
// The theme travels with the list, so it matches the pill wherever the pill's colours were set.
const TOKENS = [
  "--background",
  "--foreground",
  "--popover",
  "--popover-foreground",
  "--border",
  "--accent",
  "--accent-foreground",
  "--primary",
  "--primary-foreground",
  "--muted",
  "--muted-foreground",
  "--ring",
];
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function Chevron({ up, reduced }: { up: boolean; reduced: boolean }) {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      aria-hidden="true"
      className="size-3 shrink-0 text-muted-foreground"
      style={{
        transform: up ? "rotate(180deg)" : "none",
        transition: reduced ? "none" : `transform 320ms ${EASE}`,
      }}
    >
      <path
        d="M4.5 6.25 8 9.75l3.5-3.5"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

export function PillSelect({
  id: controlId,
  "aria-describedby": describedBy,
  "aria-invalid": invalid,
  options,
  value,
  onValueChange,
  label,
  placeholder = "Choose",
  display,
  renderValue,
  mono = false,
  align = "start",
  width = 240,
  block = false,
  muted = false,
  disabled = false,
  size = "sm",
  className = "",
}: PillSelectProps) {
  const id = React.useId();
  const reduced = useReducedMotion();
  const [phase, setPhase] = React.useState<Phase>("closed");
  const [active, setActive] = React.useState(0);
  const [pill, setPill] = React.useState({ width: 0, height: 28 });
  const [panelHeight, setPanelHeight] = React.useState(0);
  const [fit, setFit] = React.useState({
    up: false,
    width,
    shift: 0,
    x: 0,
    y: 0,
    theme: {} as Record<string, string>,
  });
  const [highlight, setHighlight] = React.useState({
    top: 0,
    height: 0,
    ready: false,
  });
  const [quiet, setQuiet] = React.useState(false);
  const wrapRef = React.useRef<HTMLDivElement>(null);
  const triggerRef = React.useRef<HTMLButtonElement>(null);
  const panelRef = React.useRef<HTMLDivElement>(null);
  const surfaceRef = React.useRef<HTMLDivElement>(null);
  const listRef = React.useRef<HTMLDivElement>(null);
  const rowRefs = React.useRef<(HTMLDivElement | null)[]>([]);
  const timer = React.useRef(0);
  const typed = React.useRef({ text: "", at: 0 });
  const selected = options.find((o) => o.value === value);
  // Disabling closes an existing popup before it can accept another choice.
  if (disabled && phase !== "closed") setPhase("closed");
  const expanded = !disabled && phase === "open";
  const mounted = !disabled && phase !== "closed";
  const [prevPhase, setPrevPhase] = React.useState(phase);
  if (phase !== prevPhase) {
    setPrevPhase(phase);
    if (phase === "closed") {
      setHighlight({ top: 0, height: 0, ready: false });
    }
  }
  const text = display ? display(selected) : (selected?.label ?? placeholder);

  const measureFit = () => {
    const wrap = wrapRef.current;
    if (!wrap) return;
    const rect = wrap.getBoundingClientRect();
    const vw = document.documentElement.clientWidth;
    const w = Math.min(Math.max(width, rect.width), vw - 24);
    // Lined up with the pill's edge, nudged back on screen.
    const shift =
      align === "start"
        ? Math.min(0, vw - 12 - (rect.left + w))
        : Math.max(0, 12 - (rect.right - w));
    const estimate =
      Math.min(
        MAX_LIST,
        options.length * (options.some((o) => o.description) ? 46 : 32),
      ) + 12;
    const vh = window.innerHeight;
    const below = vh - 8 - rect.top;
    const above = rect.bottom - 8;
    const up = below < estimate + 8 && above > below;
    // Fixed coordinates of the pill's corner the list grows from.
    const x = align === "start" ? rect.left : vw - rect.right;
    const y = up ? vh - rect.bottom : rect.top;
    const cs = getComputedStyle(wrap);
    const theme: Record<string, string> = {
      colorScheme: cs.colorScheme,
      fontFamily: cs.fontFamily,
    };
    for (const t of TOKENS) {
      const v = cs.getPropertyValue(t);
      if (v) theme[t] = v;
    }
    setFit({ up, width: w, shift, x, y, theme });
  };

  const open = () => {
    if (disabled || phase === "open" || phase === "opening") return;
    window.clearTimeout(timer.current);
    measureFit();
    setActive(
      Math.max(
        0,
        options.findIndex((o) => o.value === value),
      ),
    );
    setPhase(reduced ? "open" : "opening");
  };

  const close = React.useCallback(
    (refocus = true) => {
      window.clearTimeout(timer.current);
      if (refocus) triggerRef.current?.focus({ preventScroll: true });
      if (reduced) return setPhase("closed");
      setPhase("closing");
      timer.current = window.setTimeout(() => setPhase("closed"), DURATION);
    },
    [reduced],
  );

  React.useEffect(() => {
    if (phase !== "opening") return;
    let inner = 0;
    const outer = requestAnimationFrame(
      () => (inner = requestAnimationFrame(() => setPhase("open"))),
    );
    return () => {
      cancelAnimationFrame(outer);
      cancelAnimationFrame(inner);
    };
  }, [phase]);
  React.useEffect(() => () => window.clearTimeout(timer.current), []);
  React.useEffect(() => {
    if (disabled) window.clearTimeout(timer.current);
  }, [disabled]);

  React.useLayoutEffect(() => {
    const trigger = triggerRef.current;
    if (!trigger) return;
    const measure = () =>
      setPill((p) =>
        p.width === trigger.offsetWidth && p.height === trigger.offsetHeight
          ? p
          : { width: trigger.offsetWidth, height: trigger.offsetHeight },
      );
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(trigger);
    return () => observer.disconnect();
  }, []);

  React.useLayoutEffect(() => {
    const panel = panelRef.current;
    if (panel) setPanelHeight(panel.offsetHeight);
  }, [mounted, options]);

  // The highlight glides to the active row, and the list scrolls to keep it in view.
  React.useLayoutEffect(() => {
    const row = rowRefs.current[active];
    const list = listRef.current;
    if (!row || !list) return;
    setHighlight((h) =>
      h.top === row.offsetTop &&
      h.height === row.offsetHeight &&
      h.ready === (h.ready || expanded)
        ? h
        : {
            top: row.offsetTop,
            height: row.offsetHeight,
            ready: h.ready || expanded,
          },
    );
    const scroller = list.parentElement;
    if (scroller && scroller.scrollHeight > scroller.clientHeight) {
      if (row.offsetTop < scroller.scrollTop)
        scroller.scrollTop = row.offsetTop - 4;
      else if (
        row.offsetTop + row.offsetHeight >
        scroller.scrollTop + scroller.clientHeight
      )
        scroller.scrollTop =
          row.offsetTop + row.offsetHeight - scroller.clientHeight + 4;
    }
  }, [active, expanded, mounted]);

  React.useEffect(() => {
    if (expanded) listRef.current?.focus({ preventScroll: true });
  }, [expanded]);

  React.useEffect(() => {
    if (!expanded) return;
    const inside = (n: Node) =>
      Boolean(wrapRef.current?.contains(n) || surfaceRef.current?.contains(n));
    const onDown = (e: PointerEvent) => {
      if (!inside(e.target as Node)) close(false);
    };
    // The list sits where the pill was; if the page moves under it, it goes at once rather than fold in the wrong place.
    const gone = () => {
      window.clearTimeout(timer.current);
      setPhase("closed");
    };
    const onScroll = (e: Event) => {
      if (!surfaceRef.current?.contains(e.target as Node)) gone();
    };
    const onResize = gone;
    document.addEventListener("pointerdown", onDown);
    window.addEventListener("scroll", onScroll, true);
    window.addEventListener("resize", onResize);
    return () => {
      document.removeEventListener("pointerdown", onDown);
      window.removeEventListener("scroll", onScroll, true);
      window.removeEventListener("resize", onResize);
    };
  }, [expanded, close]);

  const choose = (o: PillOption) => {
    if (disabled) return;
    close();
    if (o.value !== value) onValueChange(o.value);
  };

  const onListKey = (e: React.KeyboardEvent) => {
    const last = options.length - 1;
    const move = (to: number) => {
      e.preventDefault();
      setActive(Math.max(0, Math.min(last, to)));
    };
    if (e.key === "ArrowDown") move(active === last ? 0 : active + 1);
    else if (e.key === "ArrowUp") move(active === 0 ? last : active - 1);
    else if (e.key === "Home") move(0);
    else if (e.key === "End") move(last);
    else if (e.key === "PageDown") move(active + 6);
    else if (e.key === "PageUp") move(active - 6);
    else if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      if (options[active]) choose(options[active]);
    } else if (e.key === "Tab") close();
    else if (e.key.length === 1 && /\S/.test(e.key)) {
      // A few letters typed quickly find the option that starts with them.
      const now = performance.now();
      typed.current = {
        text:
          (now - typed.current.at < 700 ? typed.current.text : "") +
          e.key.toLowerCase(),
        at: now,
      };
      const hit = options.findIndex((o) =>
        o.label.toLowerCase().startsWith(typed.current.text),
      );
      if (hit !== -1) setActive(hit);
    }
  };

  const w = expanded ? fit.width : pill.width;
  const h = expanded ? panelHeight : pill.height;
  const listId = `${id}-list`;
  const pillText = renderValue ? null : (
    <>
      <span
        className={`min-w-0 flex-1 truncate text-left ${mono ? "font-mono text-[11.5px]" : ""} ${muted || !selected ? "text-muted-foreground" : "text-foreground"}`}
      >
        {block ? text : <TextMorph>{text}</TextMorph>}
      </span>
      <Chevron up={expanded} reduced={reduced} />
    </>
  );

  return (
    <div
      ref={wrapRef}
      className={`relative ${block ? "flex w-full min-w-0" : "inline-flex"} ${className}`}
      onKeyDown={(e) => {
        setQuiet(false);
        if (e.key === "Escape" && expanded) {
          e.preventDefault();
          e.stopPropagation();
          close();
        }
      }}
      onBlur={(e) => {
        const to = e.relatedTarget as Node | null;
        if (
          expanded &&
          document.hasFocus() &&
          !(
            to &&
            (wrapRef.current?.contains(to) || surfaceRef.current?.contains(to))
          )
        )
          close(false);
      }}
    >
      <button
        ref={triggerRef}
        id={controlId}
        aria-describedby={describedBy}
        aria-invalid={invalid}
        data-invalid={invalid || undefined}
        type="button"
        aria-haspopup="listbox"
        aria-expanded={expanded}
        aria-controls={mounted ? listId : undefined}
        aria-label={`${label}: ${selected?.label ?? placeholder}`}
        disabled={disabled}
        onClick={() => (expanded ? close() : open())}
        onKeyDown={(e) => {
          if (e.key === "ArrowDown" || e.key === "ArrowUp") {
            e.preventDefault();
            open();
          }
        }}
        onPointerDown={() => setQuiet(true)}
        className={`inline-flex ${PILL_SIZE[size]} min-w-0 cursor-pointer items-center gap-1.5 rounded-full font-medium whitespace-nowrap shadow-[inset_0_0_0_1px_var(--border)] transition-colors duration-150 hover:bg-accent disabled:cursor-default disabled:opacity-50 disabled:hover:bg-transparent ${block ? "w-full" : ""} ${quiet ? "outline-none" : FOCUS}`}
      >
        {renderValue ? renderValue(selected, expanded) : pillText}
      </button>

      {mounted &&
        createPortal(
          <div
            ref={surfaceRef}
            onKeyDown={(e) => {
              if (e.key === "Escape") {
                e.preventDefault();
                e.stopPropagation();
                close();
              }
            }}
            onPointerDown={(e) => {
              if (!(e.target as HTMLElement).closest("[data-scroll]"))
                e.preventDefault();
              setQuiet(true);
            }}
            className="fixed z-[60] overflow-hidden bg-popover text-popover-foreground"
            style={{
              ...fit.theme,
              pointerEvents: expanded ? "auto" : "none",
              [fit.up ? "bottom" : "top"]: fit.y,
              [align === "start" ? "left" : "right"]:
                fit.x +
                (expanded ? (align === "start" ? fit.shift : -fit.shift) : 0),
              width: w,
              height: h,
              borderRadius: expanded ? 16 : pill.height / 2,
              // The pill's own cavemio, the whole way: it is the same surface.
              boxShadow: "inset 0 0 0 1px var(--border)",
              transition: reduced
                ? "none"
                : `width ${DURATION}ms ${EASE}, height ${DURATION}ms ${EASE}, left ${DURATION}ms ${EASE}, right ${DURATION}ms ${EASE}, border-radius ${DURATION}ms ${EASE}`,
            }}
          >
            {/* The pill's label, fading out as the surface grows and back in as it folds. */}
            <span
              aria-hidden="true"
              className={`pointer-events-none absolute inline-flex ${PILL_SIZE[size]} items-center gap-1.5 font-medium whitespace-nowrap ${fit.up ? "bottom-0" : "top-0"} ${align === "start" ? "left-0" : "right-0"}`}
              style={{
                width: pill.width,
                opacity: expanded ? 0 : 1,
                transition: reduced
                  ? "none"
                  : `opacity ${expanded ? 120 : 260}ms ${EASE} ${expanded ? 0 : 120}ms`,
              }}
            >
              {renderValue ? renderValue(selected, expanded) : pillText}
            </span>
            <div
              ref={panelRef}
              inert={!expanded}
              aria-hidden={!expanded}
              className={`absolute p-1 ${fit.up ? "bottom-0" : "top-0"} ${align === "start" ? "left-0" : "right-0"}`}
              style={{
                width: fit.width,
                opacity: expanded ? 1 : 0,
                transition: reduced
                  ? "none"
                  : `opacity ${expanded ? 260 : 120}ms ${EASE} ${expanded ? 90 : 0}ms`,
              }}
            >
              <div
                data-scroll=""
                className="overflow-y-auto overscroll-contain"
                style={{ maxHeight: MAX_LIST }}
              >
                <div
                  ref={listRef}
                  id={listId}
                  role="listbox"
                  tabIndex={-1}
                  aria-label={label}
                  aria-activedescendant={`${id}-o${active}`}
                  onKeyDown={onListKey}
                  className="relative outline-none"
                >
                  <span
                    aria-hidden="true"
                    className="pointer-events-none absolute inset-x-0 top-0 rounded-[12px] bg-accent"
                    style={{
                      height: highlight.height,
                      transform: `translateY(${highlight.top}px)`,
                      opacity: highlight.ready ? 1 : 0,
                      transition:
                        highlight.ready && !reduced
                          ? `transform 260ms ${EASE}, height 260ms ${EASE}, opacity 200ms`
                          : "none",
                    }}
                  />
                  {options.map((o, i) => {
                    const on = o.value === value;
                    return (
                      <div
                        key={o.value}
                        ref={(el) => {
                          rowRefs.current[i] = el;
                        }}
                        id={`${id}-o${i}`}
                        role="option"
                        aria-selected={on}
                        onPointerMove={() => setActive(i)}
                        onClick={() => choose(o)}
                        className="relative flex cursor-pointer items-start gap-2 rounded-[12px] px-2.5 py-1.5"
                      >
                        <span className="min-w-0 flex-1">
                          <span
                            className={`block truncate ${mono ? "font-mono text-[12px]" : "text-[12.5px] font-medium"}`}
                          >
                            {o.label}
                          </span>
                          {o.description && (
                            <span className="mt-0.5 block truncate text-[11.5px] text-muted-foreground">
                              {o.description}
                            </span>
                          )}
                        </span>
                        <svg
                          viewBox="0 0 16 16"
                          fill="none"
                          aria-hidden="true"
                          className="mt-0.5 size-3.5 shrink-0"
                        >
                          <path
                            d="M3.5 8.5 6.5 11.5 12.5 4.5"
                            stroke="currentColor"
                            strokeWidth="1.8"
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            pathLength={1}
                            strokeDasharray={1}
                            style={{
                              strokeDashoffset: on && expanded ? 0 : 1,
                              transition: reduced
                                ? "none"
                                : `stroke-dashoffset 380ms ${EASE} 160ms`,
                            }}
                          />
                        </svg>
                      </div>
                    );
                  })}
                </div>
              </div>
            </div>
          </div>,
          document.body,
        )}
    </div>
  );
}

"use client";

import * as React from "react";
import { ChevronDown, ListChecks, X } from "lucide-react";
import { NumberRoll } from "./number-roll";

/* ─────────────────────────────────────────────────────────
 * PLAN: an agent's checklist, ticking itself off
 *
 *   pending   not started
 *   running   being worked on now; the ring turns into a spinner
 *   done      finished; the spinner blurs into a check that draws
 *             itself, and a strike-through draws across the label
 *   skipped   no longer needed
 *   failed    couldn't be done; the reason folds open underneath
 *
 * A thin line under the header fills as tasks finish and the count
 * rolls ("3 of 5"). When every task is settled "done" slides in
 * beside it and the plan folds into that one line.
 * ───────────────────────────────────────────────────────── */

export type PlanTaskStatus =
  "pending" | "running" | "done" | "skipped" | "failed";

export interface PlanTask {
  id?: string;
  label: string;
  /** A note under the task, e.g. why it failed or what it produced. */
  detail?: string;
  status: PlanTaskStatus;
}

export interface PlanProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "title"
> {
  tasks: PlanTask[];
  title?: string;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Fold into the summary once every task is settled. */
  collapseWhenDone?: boolean;
}

const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const STATUS_TEXT: Record<PlanTaskStatus, string> = {
  pending: "Not started",
  running: "In progress",
  done: "Done",
  skipped: "Skipped",
  failed: "Failed",
};

const MORPH = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Icons trade places through a blur: the old one shrinks away as the new one grows in. */
const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 260ms ${MORPH}, transform 380ms ${MORPH}, filter 260ms ${MORPH}`,
});

/** Every mark is there at once; the one for the task's status shows, and they trade places through a blur. */
function Mark({
  status,
  reduced,
}: {
  status: PlanTaskStatus;
  reduced: boolean;
}) {
  const layer = "absolute inset-0 flex items-center justify-center";
  return (
    <span aria-hidden="true" className="relative flex size-3.5 shrink-0">
      <span className={layer} style={swap(status === "pending", reduced)}>
        <span className="size-3.5 rounded-full border-[1.5px] border-border" />
      </span>
      <span className={layer} style={swap(status === "running", reduced)}>
        {/* Spins only while it's showing. */}
        <span
          className={`size-3.5 rounded-full border-[1.5px] border-border border-t-foreground motion-reduce:animate-none ${status === "running" ? "animate-spin" : ""}`}
        />
      </span>
      <span className={layer} style={swap(status === "done", reduced)}>
        <svg viewBox="0 0 16 16" className="size-3.5">
          <circle cx="8" cy="8" r="8" className="fill-foreground" />
          <path
            d="M4.8 8.3l2.1 2.1 4.3-4.6"
            fill="none"
            strokeWidth="1.8"
            strokeLinecap="round"
            strokeLinejoin="round"
            pathLength={1}
            strokeDasharray={1}
            className="stroke-background"
            style={{
              strokeDashoffset: status === "done" ? 0 : 1,
              transition:
                status === "done" && !reduced
                  ? `stroke-dashoffset 420ms ${MORPH} 140ms`
                  : "none",
            }}
          />
        </svg>
      </span>
      <span className={layer} style={swap(status === "skipped", reduced)}>
        <span className="flex size-3.5 items-center justify-center rounded-full border-[1.5px] border-border">
          <span className="h-[1.5px] w-1.5 rounded-full bg-muted-foreground" />
        </span>
      </span>
      <span className={layer} style={swap(status === "failed", reduced)}>
        <span className="flex size-3.5 items-center justify-center rounded-full bg-red-500 text-white">
          <X className="size-2.5" strokeWidth={3} />
        </span>
      </span>
    </span>
  );
}

/** A note that folds open under its task and folds shut again, keeping its words while it closes. */
function Detail({
  text,
  failed,
  reduced,
}: {
  text?: string;
  failed: boolean;
  reduced: boolean;
}) {
  const [last, setLast] = React.useState(text);
  if (text && text !== last) setLast(text);
  return (
    <span
      aria-hidden={!text || undefined}
      className="grid"
      style={{
        gridTemplateRows: text ? "1fr" : "0fr",
        opacity: text ? 1 : 0,
        transition: reduced
          ? "none"
          : `grid-template-rows 420ms ${MORPH}, opacity ${text ? "320ms" : "160ms"} ${MORPH}, color 300ms`,
      }}
    >
      <span
        className={`min-h-0 overflow-hidden text-[12px] leading-5 transition-colors duration-300 ${failed ? "text-red-500" : "text-muted-foreground"}`}
      >
        <span className="block pt-0.5">{text ?? last}</span>
      </span>
    </span>
  );
}

export function Plan({
  tasks,
  title = "Plan",
  open,
  defaultOpen = true,
  onOpenChange,
  collapseWhenDone = true,
  className = "",
  ...props
}: PlanProps) {
  const reduced = useReducedMotion();
  const [ownOpen, setOwnOpen] = React.useState(defaultOpen);
  const [touched, setTouched] = React.useState(false);
  const panelId = React.useId();

  const done = tasks.filter((t) => t.status === "done").length;
  const settled =
    tasks.length > 0 &&
    tasks.every(
      (t) =>
        t.status === "done" || t.status === "skipped" || t.status === "failed",
    );
  const failed = tasks.some((t) => t.status === "failed");
  const expanded = open ?? ownOpen;

  // Fold away once everything is settled, unless the user has taken control or something failed.
  React.useEffect(() => {
    if (
      !collapseWhenDone ||
      open !== undefined ||
      touched ||
      !settled ||
      failed
    )
      return;
    const timer = window.setTimeout(() => setOwnOpen(false), 1200);
    return () => window.clearTimeout(timer);
  }, [collapseWhenDone, open, touched, settled, failed]);

  const toggle = () => {
    const next = !expanded;
    setTouched(true);
    if (open === undefined) setOwnOpen(next);
    onOpenChange?.(next);
  };

  return (
    <div className={`w-full ${className}`} {...props}>
      <button
        type="button"
        aria-expanded={expanded}
        aria-controls={panelId}
        onClick={toggle}
        className={`cursor-pointer -mx-1.5 flex w-[calc(100%+0.75rem)] items-center gap-2 rounded-lg px-1.5 py-1 text-left transition-colors hover:bg-accent ${FOCUS}`}
      >
        <ListChecks
          aria-hidden="true"
          className="size-4 shrink-0 text-muted-foreground"
        />
        <span className="text-[13px] font-medium text-foreground">{title}</span>
        <span
          aria-hidden="true"
          className="ml-auto flex items-baseline font-mono text-[11.5px] tabular-nums text-muted-foreground"
        >
          <NumberRoll value={done} duration={600} />
          &nbsp;of&nbsp;
          <NumberRoll value={tasks.length} duration={600} />
          <span
            className="grid"
            style={{
              gridTemplateColumns: settled ? "1fr" : "0fr",
              opacity: settled ? 1 : 0,
              transition: reduced
                ? "none"
                : `grid-template-columns 420ms ${MORPH}, opacity 300ms ${MORPH}`,
            }}
          >
            <span className="min-w-0 overflow-hidden whitespace-nowrap">
              &nbsp;done
            </span>
          </span>
        </span>
        <ChevronDown
          aria-hidden="true"
          className={`size-3.5 shrink-0 text-muted-foreground transition-transform duration-300 motion-reduce:transition-none ${expanded ? "rotate-180" : ""}`}
        />
      </button>
      {/* Outside the button, so its name stays the title. */}
      <span role="status" aria-live="polite" className="sr-only">
        {settled
          ? `${done} of ${tasks.length} done`
          : `${done} of ${tasks.length}`}
      </span>

      <div
        aria-hidden="true"
        className="mt-1.5 h-px w-full overflow-hidden bg-border"
      >
        <div
          className="h-full bg-foreground transition-[width] duration-700 ease-[cubic-bezier(0.23,1,0.32,1)] motion-reduce:transition-none"
          style={{
            width: `${tasks.length ? (done / tasks.length) * 100 : 0}%`,
          }}
        />
      </div>

      <div
        id={panelId}
        inert={!expanded}
        className={`grid transition-[grid-template-rows,opacity] duration-[400ms] ease-[cubic-bezier(0.23,1,0.32,1)] motion-reduce:transition-none ${
          expanded ? "grid-rows-[1fr] opacity-100" : "grid-rows-[0fr] opacity-0"
        }`}
      >
        <div className="overflow-hidden">
          <ol aria-label={title} className="flex flex-col gap-0.5 pt-2.5">
            {tasks.map((task, i) => {
              const quiet = task.status === "done" || task.status === "skipped";
              return (
                <li
                  key={task.id ?? `${i}-${task.label}`}
                  className="flex gap-2.5 py-1"
                >
                  <span className="mt-[3px] flex">
                    <Mark status={task.status} reduced={reduced} />
                  </span>
                  <span className="min-w-0">
                    <span className="block text-[13px] leading-5">
                      {/* The strike draws itself across each line of the label, left to right. */}
                      <span
                        className={`bg-[linear-gradient(var(--border),var(--border))] bg-no-repeat [background-position:0_58%] [box-decoration-break:clone] [-webkit-box-decoration-break:clone] ${
                          quiet
                            ? "text-muted-foreground"
                            : task.status === "pending"
                              ? "text-foreground/70"
                              : "text-foreground"
                        }`}
                        style={{
                          backgroundSize: quiet ? "100% 1px" : "0% 1px",
                          transition: reduced
                            ? "none"
                            : `background-size 520ms ${MORPH} 120ms, color 300ms`,
                        }}
                      >
                        {task.label}
                      </span>
                      <span className="sr-only">
                        , {STATUS_TEXT[task.status]}
                      </span>
                    </span>
                    <Detail
                      text={task.detail}
                      failed={task.status === "failed"}
                      reduced={reduced}
                    />
                  </span>
                </li>
              );
            })}
          </ol>
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { Check, Vote } from "lucide-react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";
import {
  EASE_THROW,
  INTERACTION_FOCUS,
  INTERACTION_PRESS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * POLL: the bars race to their share
 *
 *   ask       the lit card holds the question and its options as
 *             inset rows; tap one to vote
 *   reveal    every row fills with light to its share, one after
 *             another, while the percentages roll up from zero;
 *             your pick is ringed with a check and the leader's
 *             share is set in full weight
 *   live      as votes come in the bars glide and the numbers roll;
 *             change your vote and both rows move at once
 *   closed    after closesAt the results are final
 *
 * The votes are yours: pass options with their counts and the
 * visitor's vote from your database, and record it in onVote.
 * The bars move on your vote straight away; throw an Error and
 * they go back and say why.
 * ───────────────────────────────────────────────────────── */

export interface PollOption {
  id: string;
  label: string;
  votes: number;
}

export interface PollVoter {
  id: string;
  name: string;
  src?: string;
}

export interface PollProps {
  question: string;
  options: PollOption[];
  /** The visitor's vote, if they've voted. */
  vote?: string | null;
  /** Record a vote (or a changed one); throw an Error to say why not. */
  onVote: (optionId: string) => Promise<unknown>;
  /** After this the results are final. */
  closesAt?: Date | string | number;
  /** A few recent voters, shown as faces. */
  voters?: PollVoter[];
  /** Let people change their vote. */
  allowChange?: boolean;
  /** Who's asking, e.g. "Relay community". */
  source?: string;
  locale?: string;
  className?: string;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const HOUR = 3_600_000;
const NO_VOTERS: PollVoter[] = [];
const subscribeNothing = () => () => {};
const useHydrated = () =>
  React.useSyncExternalStore(
    subscribeNothing,
    () => true,
    () => false,
  );

const mix = (color: string, amount: number, into = "transparent") =>
  `color-mix(in oklab, ${color} ${amount}%, ${into})`;
const LIT: React.CSSProperties = {
  backgroundColor: "var(--primary)",
  backgroundImage: `radial-gradient(120% 80% at 0% 0%, ${mix("var(--primary-foreground)", 22)} 0%, transparent 55%), linear-gradient(175deg, transparent 40%, ${mix("black", 24)} 100%)`,
  boxShadow: `inset 0 1px 0 ${mix("var(--primary-foreground)", 36)}, inset 0 0 0 1px ${mix("var(--primary-foreground)", 12)}`,
};
const CARD: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, var(--card), ${mix("var(--card)", 95, "var(--foreground)")})`,
  boxShadow: `0 0 0 1px var(--border), inset 0 1px 0 ${mix("var(--background)", 85)}`,
};
const ROW: React.CSSProperties = {
  background: mix("black", 14),
  boxShadow: `inset 0 1px 1px ${mix("black", 12)}, inset 0 0 0 1px ${mix("var(--primary-foreground)", 10)}`,
};

function tint(seed: string): React.CSSProperties {
  let h = 0;
  for (const c of seed) h = (h * 31 + c.charCodeAt(0)) >>> 0;
  const chart = `var(--chart-${(h % 5) + 1}, var(--primary))`;
  return {
    background: mix(chart, 20, "var(--card)"),
    color: mix(chart, 75, "var(--foreground)"),
  };
}
const initials = (name: string) =>
  name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((w) => w[0]?.toUpperCase())
    .join("");

export function Poll({
  question,
  options,
  vote: voteProp,
  onVote,
  closesAt,
  voters = NO_VOTERS,
  allowChange = true,
  source,
  locale,
  className = "",
}: PollProps) {
  const reduced = useInteractionReducedMotion();
  const hydrated = useHydrated();
  const baseId = React.useId();
  const [now, setNow] = React.useState<number | null>(null);
  // The vote on screen: yours as soon as you tap, until your server agrees (or refuses).
  const [mine, setMine] = React.useState<{
    id: string | null;
    pending: boolean;
  } | null>(null);
  const [error, setError] = React.useState<string | null>(null);
  const [changing, setChanging] = React.useState(false);
  const [said, setSaid] = React.useState("");

  React.useEffect(() => {
    const tick = () => setNow(Date.now());
    const frame = requestAnimationFrame(tick);
    const timer = window.setInterval(tick, 60_000);
    return () => {
      cancelAnimationFrame(frame);
      window.clearInterval(timer);
    };
  }, []);

  const server = voteProp ?? null;
  const vote = mine ? mine.id : server;
  const closes = closesAt !== undefined ? new Date(closesAt).getTime() : null;
  const closed = closes !== null && now !== null && now >= closes;
  const showing = vote !== null || closed;
  // The first reveal races the bars in one after another; later changes all move at once.
  const firstReveal = server === null && mine !== null;

  // Counts with your vote moved in straight away, so the bars answer the tap.
  const counts = options.map(
    (o) =>
      o.votes +
      (mine && mine.id !== server
        ? (o.id === mine.id ? 1 : 0) - (o.id === server ? 1 : 0)
        : 0),
  );
  const total = counts.reduce((a, b) => a + b, 0);
  const top = Math.max(...counts);

  const left = closes === null || now === null ? null : closes - now;
  const timeLeft = closed
    ? "Final results"
    : left === null
      ? ""
      : left > 48 * HOUR
        ? `${Math.round(left / (24 * HOUR))} days left`
        : left > HOUR
          ? `${Math.round(left / HOUR)} hours left`
          : "Closing soon";

  const cast = async (id: string) => {
    if (closed || (mine?.pending ?? false)) return;
    if (vote === id && !changing) return;
    setChanging(false);
    setError(null);
    setMine({ id, pending: true });
    try {
      await onVote(id);
      setMine({ id, pending: false });
      setSaid(`Voted for ${options.find((o) => o.id === id)?.label}.`);
    } catch (e) {
      setMine(null);
      setError(
        e instanceof Error && e.message
          ? e.message
          : "Couldn’t record your vote. Try again.",
      );
    }
  };

  // Your vote reached your data: hand the display back to it.
  if (mine && !mine.pending && server === mine.id) setMine(null);

  const fmt = new Intl.NumberFormat(locale ?? (hydrated ? undefined : "en-US"));
  const shown = voters.slice(0, 3);
  const others = Math.max(0, total - shown.length);

  return (
    <section
      aria-labelledby={`${baseId}-q`}
      className={`w-full max-w-[400px] rounded-[28px] p-2 text-card-foreground ${className}`}
      style={CARD}
    >
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 400px)" }}
      />
      <div className="@container w-full">
        {/* The one lit surface: the question and its options, which fill to their share. */}
        <div className="rounded-[22px] p-4 text-primary-foreground" style={LIT}>
          <div className="flex items-center justify-between gap-3 text-[12px] text-primary-foreground/70">
            <span className="inline-flex min-w-0 items-center gap-1.5 truncate">
              <Vote aria-hidden="true" className="size-3.5 shrink-0" />
              {source ?? "Poll"}
            </span>
            <span className="shrink-0 tabular-nums">
              <NumberRoll value={total} locales={locale} duration={700} />{" "}
              {total === 1 ? "vote" : "votes"}
              {timeLeft ? ` · ${timeLeft}` : ""}
            </span>
          </div>
          <h2
            id={`${baseId}-q`}
            className="mt-2 text-[17px] font-medium leading-snug tracking-[-0.015em]"
          >
            {question}
          </h2>

          <ul
            className="mt-3 space-y-1.5"
            role={showing ? "list" : "radiogroup"}
            aria-labelledby={`${baseId}-q`}
          >
            {options.map((o, i) => {
              const share = total ? counts[i] / total : 0;
              const pct = Math.round(share * 100);
              const yours = vote === o.id;
              const leads = showing && counts[i] === top && top > 0;
              return (
                <li key={o.id}>
                  <button
                    type="button"
                    role={showing ? undefined : "radio"}
                    aria-checked={showing ? undefined : false}
                    aria-label={
                      showing
                        ? `${o.label}, ${pct}%${yours ? ", your vote" : changing ? ". Change your vote to this" : ""}`
                        : `Vote for ${o.label}`
                    }
                    disabled={
                      closed ||
                      (mine?.pending ?? false) ||
                      (showing && (!changing || yours))
                    }
                    onClick={() => void cast(o.id)}
                    className={`relative flex h-11 w-full cursor-pointer items-center gap-2 overflow-clip rounded-[14px] px-3.5 text-left text-[14px] disabled:cursor-default ${INTERACTION_PRESS} focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary-foreground/70 ${!showing || (changing && !yours) ? "hover:brightness-110" : ""}`}
                    style={{
                      ...ROW,
                      boxShadow:
                        yours && showing
                          ? `inset 0 0 0 1.5px var(--primary-foreground)`
                          : ROW.boxShadow,
                      transition: reduced
                        ? "none"
                        : `box-shadow 320ms ${EASE_THROW}`,
                    }}
                  >
                    {/* The share, as light filling the row. */}
                    <span
                      aria-hidden="true"
                      className="absolute inset-y-0 left-0 w-full origin-left"
                      style={{
                        background: mix(
                          "var(--primary-foreground)",
                          yours ? 34 : 18,
                        ),
                        transform: `scaleX(${showing ? share : 0})`,
                        transition: reduced
                          ? "none"
                          : `transform ${firstReveal ? 900 : 700}ms ${EASE} ${firstReveal ? i * 70 : 0}ms, background-color 300ms`,
                      }}
                    />
                    <span
                      className={`relative min-w-0 flex-1 truncate ${leads ? "font-medium" : ""}`}
                    >
                      {o.label}
                    </span>
                    <span className="relative flex shrink-0 items-center gap-1.5 tabular-nums">
                      <span
                        className="grid"
                        style={{
                          gridTemplateColumns: yours ? "1fr" : "0fr",
                          transition: reduced
                            ? "none"
                            : `grid-template-columns 320ms ${EASE}`,
                        }}
                      >
                        <span className="min-w-0 overflow-hidden">
                          <Check
                            aria-hidden="true"
                            className="size-4"
                            strokeWidth={2.5}
                          />
                        </span>
                      </span>
                      <span
                        className={
                          leads ? "font-medium" : "text-primary-foreground/85"
                        }
                        style={{
                          opacity: showing ? 1 : 0,
                          transition: "opacity 300ms",
                        }}
                      >
                        <NumberRoll value={showing ? pct : 0} duration={900} />%
                      </span>
                      {!showing && (
                        <span
                          aria-hidden="true"
                          className="absolute right-0 size-[18px] rounded-full"
                          style={{
                            boxShadow: `inset 0 0 0 1.5px ${mix("var(--primary-foreground)", 55)}`,
                          }}
                        />
                      )}
                    </span>
                  </button>
                </li>
              );
            })}
          </ul>
        </div>

        {/* Flat: who voted, and changing your mind. */}
        <div className="flex min-h-11 items-center justify-between gap-3 px-3 pb-1 pt-2">
          <span className="flex min-w-0 items-center gap-2">
            {shown.length > 0 && (
              <span aria-hidden="true" className="flex shrink-0 -space-x-1.5">
                {shown.map((v) => (
                  <span
                    key={v.id}
                    className="relative flex size-6 items-center justify-center overflow-hidden rounded-full text-[9.5px] font-medium ring-2 ring-card"
                    style={tint(v.name)}
                  >
                    {initials(v.name)}
                    {v.src && (
                      <img
                        src={v.src}
                        alt=""
                        className="absolute inset-0 size-full object-cover"
                      />
                    )}
                  </span>
                ))}
              </span>
            )}
            <span className="truncate text-[12.5px] text-muted-foreground">
              {error ? (
                <span role="alert" className="text-red-600 dark:text-red-400">
                  {error}
                </span>
              ) : shown.length ? (
                `${shown.map((v) => v.name.split(" ")[0]).join(", ")}${others ? ` and ${fmt.format(others)} others` : ""}`
              ) : changing ? (
                "Tap another option to move your vote"
              ) : showing ? (
                "Results update as votes come in"
              ) : (
                "Vote to see the results"
              )}
            </span>
          </span>
          {allowChange && !closed && vote !== null && (
            <button
              type="button"
              onClick={() => setChanging((c) => !c)}
              disabled={mine?.pending ?? false}
              className={`h-8 shrink-0 cursor-pointer rounded-full px-3 text-[12.5px] text-foreground hover:bg-accent ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`}
            >
              <TextMorph>{changing ? "Keep my vote" : "Change vote"}</TextMorph>
            </button>
          )}
        </div>

        <span className="sr-only" role="status">
          {said}
        </span>
      </div>
    </section>
  );
}

export default Poll;

"use client";

import * as React from "react";
import { createPortal } from "react-dom";
import {
  enterStyle,
  themeVars,
  useDismiss,
  useFloating,
  usePresence,
  type Align,
  type Side,
} from "./floating";
import { useInteractionReducedMotion } from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * POPOVER: a small panel that belongs to a button
 *
 *   open     the panel rises off its trigger out of a blur, from
 *            the point on the trigger nearest to it, and flips
 *            or shifts to stay in the window
 *   inside   focus moves to the first field in it (or the panel)
 *   close    Escape returns focus to the trigger; a press
 *            outside just closes; `close()` from inside too
 *
 * For a list of actions use DropdownMenu; this is for content
 * (a short form, a colour picker, details).
 * ───────────────────────────────────────────────────────── */

export interface PopoverProps {
  trigger: React.ReactElement<React.HTMLAttributes<HTMLElement>>;
  /** The content, or a function that gets `close`. */
  children: React.ReactNode | ((api: { close: () => void }) => React.ReactNode);
  side?: Side;
  align?: Align;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Width of the panel in px. */
  width?: number;
  /** Accessible name of the panel. */
  label?: string;
  className?: string;
}

const FOCUSABLE =
  'input, textarea, select, button, [href], [tabindex]:not([tabindex="-1"])';

export function Popover({
  trigger,
  children,
  side = "bottom",
  align = "center",
  open: controlled,
  onOpenChange,
  width = 280,
  label,
  className = "",
}: PopoverProps) {
  const reduced = useInteractionReducedMotion();
  const anchor = React.useRef<HTMLSpanElement>(null);
  const surface = React.useRef<HTMLDivElement>(null);
  const [own, setOwn] = React.useState(false);
  const open = controlled ?? own;
  const { mounted, shown } = usePresence(open, 180);
  const place = useFloating({
    open: mounted,
    anchor,
    floating: surface,
    side,
    align,
    offset: 8,
  });
  const [vars, setVars] = React.useState<React.CSSProperties>({});
  const id = React.useId();
  const triggerId = React.useId();

  const setOpen = (next: boolean, refocus = false) => {
    if (controlled === undefined) setOwn(next);
    onOpenChange?.(next);
    // By id rather than a ref: this runs from handlers that are created while rendering.
    if (!next && refocus)
      document.getElementById(trigger.props.id ?? triggerId)?.focus();
  };

  useDismiss(open, (reason) => setOpen(false, reason === "escape"), [
    anchor,
    surface,
  ]);

  React.useLayoutEffect(() => {
    if (mounted) setVars(themeVars(anchor.current));
  }, [mounted]);

  React.useEffect(() => {
    if (!open || !place.ready) return;
    const el = surface.current;
    (el?.querySelector<HTMLElement>(FOCUSABLE) ?? el)?.focus({
      preventScroll: true,
    });
  }, [open, place.ready]);

  const close = () => setOpen(false, true);

  return (
    <>
      <span ref={anchor} className="inline-flex">
        {React.cloneElement(trigger, {
          id: trigger.props.id ?? triggerId,
          "aria-haspopup": "dialog",
          "aria-expanded": open,
          "aria-controls": open ? id : undefined,
          onClick: (e: React.MouseEvent<HTMLElement>) => {
            trigger.props.onClick?.(e);
            setOpen(!open);
          },
        })}
      </span>
      {mounted &&
        createPortal(
          <div
            ref={surface}
            id={id}
            role="dialog"
            aria-label={label}
            tabIndex={-1}
            className={`fixed left-0 top-0 z-[55] max-w-[calc(100vw_-_16px)] rounded-[16px] bg-popover p-4 text-[13.5px] text-popover-foreground shadow-[0_0_0_1px_var(--border)] outline-none ${className}`}
            style={{
              ...vars,
              width,
              left: place.x,
              top: place.y,
              transformOrigin: place.origin,
              ...enterStyle(shown, place.side, reduced),
            }}
          >
            {typeof children === "function" ? children({ close }) : children}
          </div>,
          document.body,
        )}
    </>
  );
}

export default Popover;

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { PricingToggle } from "./pricing-toggle";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * PRICING CALCULATOR: drag to your size, watch the price
 *
 *   drag      the thumb follows your finger; the fill and a
 *             value bubble ride with it and the price rolls as
 *             you go
 *   jump      click the track (or tap a mark) and the thumb is
 *             thrown there with a little give
 *   tiers     crossing a mark morphs the plan's name and lights
 *             the mark; the button's words follow
 *   contact   past the last tier the price folds away and the
 *             line becomes "Let's talk"
 *   yearly    with a discount, a Monthly/Yearly switch rolls every
 *             figure to its yearly price
 *
 * Bring your own formula: price(value) and plan(value). A real
 * slider: arrow keys, Page Up/Down, Home and End.
 * ───────────────────────────────────────────────────────── */

export interface CalculatorMark {
  value: number;
  label: string;
}

export interface PricingCalculatorProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onChange"
> {
  min: number;
  max: number;
  step?: number;
  value?: number;
  defaultValue?: number;
  onValueChange?: (value: number) => void;
  /** Monthly price for a value, before any yearly discount. */
  price: (value: number) => number;
  /** The plan a value falls in, e.g. "Growth". */
  plan?: (value: number) => string;
  /** Ticks along the track, e.g. where tiers change. */
  marks?: CalculatorMark[];
  /** What's being counted, e.g. "monthly active users". */
  unit?: string;
  /** Intl.NumberFormat options for the value, e.g. { notation: "compact" }. */
  valueFormat?: Intl.NumberFormatOptions;
  currency?: string;
  /** Locale for every figure, e.g. "en-US". Set it when the page is rendered on a server, so both sides format alike. */
  locales?: string | string[];
  /** Evenly spaced orders of magnitude, for ranges like 1,000 to 1,000,000. */
  scale?: "linear" | "log";
  /** At or above this, show "Let's talk" instead of a price. */
  contactFrom?: number;
  /** e.g. 0.2 shows a Monthly/Yearly switch with "Save 20%". */
  yearlyDiscount?: number;
  /** The button under the price; its words follow the plan. */
  cta?: {
    label: (plan: string) => string;
    contactLabel?: string;
    onClick?: (
      value: number,
      plan: string,
      billing: "monthly" | "yearly",
    ) => void;
  };
  label?: string;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

export function PricingCalculator({
  min,
  max,
  step = 1,
  value: valueProp,
  defaultValue,
  onValueChange,
  price,
  plan = () => "",
  marks = [],
  unit = "",
  valueFormat,
  currency = "USD",
  locales,
  scale = "linear",
  contactFrom,
  yearlyDiscount,
  cta,
  label = "Usage",
  className = "",
  ...props
}: PricingCalculatorProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const [own, setOwn] = React.useState(defaultValue ?? min);
  const value = valueProp ?? own;
  const [billing, setBilling] = React.useState<"monthly" | "yearly">("monthly");
  const [dragging, setDragging] = React.useState(false);
  const [thrown, setThrown] = React.useState(false);
  const trackRef = React.useRef<HTMLDivElement>(null);
  const thumbRef = React.useRef<HTMLDivElement>(null);
  const pointer = React.useRef<number | null>(null);

  // Value ↔ position along the track, linear or by orders of magnitude.
  const toRatio = React.useCallback(
    (v: number) => {
      if (scale === "log" && min > 0)
        return (Math.log(v) - Math.log(min)) / (Math.log(max) - Math.log(min));
      return (v - min) / (max - min);
    },
    [scale, min, max],
  );
  const fromRatio = React.useCallback(
    (r: number) => {
      const c = Math.min(1, Math.max(0, r));
      const raw =
        scale === "log" && min > 0
          ? Math.exp(Math.log(min) + c * (Math.log(max) - Math.log(min)))
          : min + c * (max - min);
      // On a log scale, round to a step that suits the size (1,000s near 10k, 10,000s near 100k).
      const s =
        scale === "log"
          ? Math.max(step, 10 ** Math.max(0, Math.floor(Math.log10(raw)) - 1))
          : step;
      return Math.min(max, Math.max(min, Math.round(raw / s) * s));
    },
    [scale, min, max, step],
  );

  const set = (next: number) => {
    const v = Math.min(max, Math.max(min, next));
    if (valueProp === undefined) setOwn(v);
    onValueChange?.(v);
  };

  const fromPointer = (clientX: number) => {
    const track = trackRef.current;
    if (!track) return value;
    const r = track.getBoundingClientRect();
    return fromRatio((clientX - r.left) / r.width);
  };

  const onPointerDown = (e: React.PointerEvent) => {
    if (e.button !== 0) return;
    e.preventDefault();
    pointer.current = e.pointerId;
    (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
    thumbRef.current?.focus({ preventScroll: true });
    // A press away from the thumb throws it there; a press on it starts a drag.
    const onThumb = (e.target as HTMLElement).closest("[data-thumb]");
    setThrown(!onThumb);
    setDragging(Boolean(onThumb));
    set(fromPointer(e.clientX));
  };
  const onPointerMove = (e: React.PointerEvent) => {
    if (pointer.current !== e.pointerId) return;
    if (!dragging) {
      setThrown(false);
      setDragging(true);
    }
    set(fromPointer(e.clientX));
  };
  const onPointerUp = (e: React.PointerEvent) => {
    if (pointer.current !== e.pointerId) return;
    pointer.current = null;
    setDragging(false);
  };

  const onKeyDown = (e: React.KeyboardEvent) => {
    const r = toRatio(value);
    const nudge = (d: number) => {
      // Each press moves at least one visible step, even where a log scale is coarse.
      const next = fromRatio(r + d);
      return next === value ? value + Math.sign(d) * step : next;
    };
    const moves: Record<string, () => number> = {
      ArrowRight: () => nudge(0.01),
      ArrowUp: () => nudge(0.01),
      ArrowLeft: () => nudge(-0.01),
      ArrowDown: () => nudge(-0.01),
      PageUp: () => nudge(0.1),
      PageDown: () => nudge(-0.1),
      Home: () => min,
      End: () => max,
    };
    if (!(e.key in moves)) return;
    e.preventDefault();
    setThrown(e.key === "Home" || e.key === "End" || e.key.startsWith("Page"));
    set(moves[e.key]());
  };

  const ratio = Math.min(1, Math.max(0, toRatio(value)));
  const contact = contactFrom !== undefined && value >= contactFrom;
  const planName = plan(value);
  const discount = billing === "yearly" && yearlyDiscount ? yearlyDiscount : 0;
  const monthly = price(value) * (1 - discount);
  const currencyFormat = React.useMemo<Intl.NumberFormatOptions>(
    () => ({ style: "currency", currency, maximumFractionDigits: 0 }),
    [currency],
  );
  const valueText = new Intl.NumberFormat(locales, valueFormat).format(value);
  const moveTransition =
    reduced || dragging
      ? "none"
      : thrown
        ? `transform 520ms ${THROW}`
        : `transform 220ms ${EASE}`;
  const fillTransition =
    reduced || dragging
      ? "none"
      : thrown
        ? `transform 520ms ${THROW}`
        : `transform 220ms ${EASE}`;

  return (
    <div className={`w-full ${className}`} {...props}>
      <div className="flex flex-wrap items-end justify-between gap-4">
        <div className="min-w-0">
          {/* The plan's name morphs as you cross a tier. */}
          <p className="h-5 text-[13px] font-medium text-primary">
            <TextMorph>{contact ? "Enterprise" : planName}</TextMorph>
          </p>
          <div className="mt-1 flex h-[60px] items-baseline">
            <span
              className="grid"
              style={{
                gridTemplateColumns: contact ? "0fr" : "1fr",
                opacity: contact ? 0 : 1,
                filter: contact ? "blur(6px)" : "none",
                transition: reduced
                  ? "none"
                  : `grid-template-columns 460ms ${EASE}, opacity 300ms ${EASE}, filter 300ms ${EASE}`,
              }}
            >
              <span className="flex min-w-0 items-baseline gap-1 overflow-hidden whitespace-nowrap">
                <NumberRoll
                  value={Math.round(monthly)}
                  format={currencyFormat}
                  locales={locales}
                  className="text-[52px] font-medium leading-none tracking-[-0.04em] text-foreground"
                />
                <span className="text-[15px] text-muted-foreground">/mo</span>
              </span>
            </span>
            <span
              className="grid"
              style={{
                gridTemplateColumns: contact ? "1fr" : "0fr",
                opacity: contact ? 1 : 0,
                filter: contact ? "none" : "blur(6px)",
                transition: reduced
                  ? "none"
                  : `grid-template-columns 460ms ${EASE}, opacity 300ms ${EASE} 120ms, filter 300ms ${EASE} 120ms`,
              }}
            >
              <span className="min-w-0 overflow-hidden whitespace-nowrap text-[52px] font-medium leading-none tracking-[-0.04em] text-foreground">
                Let’s talk
              </span>
            </span>
          </div>
          <p className="mt-2 min-h-5 text-[13px] leading-5 text-muted-foreground">
            <TextMorph animateWidth={false}>
              {contact
                ? "Volume pricing, SSO and a named contact"
                : discount
                  ? `${new Intl.NumberFormat(locales, currencyFormat).format(Math.round(monthly * 12))} billed yearly`
                  : "Billed monthly, cancel anytime"}
            </TextMorph>
          </p>
        </div>
        {yearlyDiscount ? (
          <PricingToggle
            value={billing}
            onValueChange={(v) => setBilling(v as "monthly" | "yearly")}
            options={[
              { value: "monthly", label: "Monthly" },
              {
                value: "yearly",
                label: "Yearly",
                badge: `Save ${Math.round(yearlyDiscount * 100)}%`,
              },
            ]}
          />
        ) : null}
      </div>

      {/* The slider. */}
      <div className="mt-10 select-none">
        <div
          ref={trackRef}
          onPointerDown={onPointerDown}
          onPointerMove={onPointerMove}
          onPointerUp={onPointerUp}
          onPointerCancel={onPointerUp}
          className="relative flex h-10 cursor-pointer touch-none items-center"
        >
          <div className="absolute inset-x-0 h-1.5 overflow-hidden rounded-full bg-muted shadow-[inset_0_0_0_1px_var(--border)]">
            <div
              className="h-full origin-left rounded-full bg-primary"
              style={{
                transform: `scaleX(${ratio})`,
                transition: fillTransition,
              }}
            />
          </div>
          {marks.map((m) => {
            const r = toRatio(m.value);
            const passed = value >= m.value;
            return (
              <span
                key={m.value}
                aria-hidden="true"
                className="absolute top-1/2 size-1.5 -translate-x-1/2 -translate-y-1/2 rounded-full transition-[background-color,transform] duration-300"
                style={{
                  left: `${r * 100}%`,
                  background: passed
                    ? "var(--primary-foreground)"
                    : "color-mix(in oklab, var(--foreground) 22%, transparent)",
                }}
              />
            );
          })}
          {/* The thumb, with the value riding above it. The rider ends at the thumb and hangs
              off to the left, so it never widens the page the way a box pushed right would. */}
          <div
            className="pointer-events-none absolute inset-y-0 left-0 w-full"
            style={{
              transform: `translateX(${(ratio - 1) * 100}%)`,
              transition: moveTransition,
            }}
          >
            <div
              ref={thumbRef}
              data-thumb=""
              role="slider"
              tabIndex={0}
              aria-label={label}
              aria-valuemin={min}
              aria-valuemax={max}
              aria-valuenow={value}
              aria-valuetext={`${valueText}${unit ? ` ${unit}` : ""}${contact ? ", contact sales" : `, ${new Intl.NumberFormat(locales, currencyFormat).format(Math.round(monthly))} a month`}`}
              aria-describedby={`${id}-plan`}
              onKeyDown={onKeyDown}
              className={`pointer-events-auto absolute left-full top-1/2 flex size-6 -translate-x-1/2 -translate-y-1/2 cursor-grab items-center justify-center rounded-full bg-background shadow-[0_0_0_1px_var(--border)] outline-none transition-[scale] duration-200 focus-visible:ring-2 focus-visible:ring-ring/40 ${
                dragging ? "scale-110 cursor-grabbing" : ""
              }`}
            >
              <span className="size-2 rounded-full bg-primary" />
              {/* Centred over the thumb mid-track, leaning inwards at the ends so it never leaves the track. */}
              <span
                aria-hidden="true"
                className="absolute bottom-full left-1/2 mb-2.5 flex h-7 items-baseline whitespace-nowrap rounded-full bg-background px-2.5 pt-[5px] text-[12.5px] font-medium tabular-nums text-foreground shadow-[inset_0_0_0_1px_var(--border)]"
                style={{
                  transform: `translateX(${-ratio * 100}%)`,
                  transition: moveTransition,
                }}
              >
                <NumberRoll
                  value={value}
                  format={valueFormat}
                  locales={locales}
                  duration={dragging ? 300 : 600}
                />
                {unit && (
                  <span className="ml-1 font-normal text-muted-foreground">
                    {unit.split(" ").slice(-1)[0]}
                  </span>
                )}
              </span>
            </div>
          </div>
        </div>
        {marks.length > 0 && (
          <div className="relative mt-1 h-5 text-[11.5px]">
            {marks.map((m) => (
              <button
                key={m.value}
                type="button"
                tabIndex={-1}
                onClick={() => {
                  setThrown(true);
                  set(m.value);
                }}
                className={`cursor-pointer absolute -translate-x-1/2 whitespace-nowrap transition-colors duration-300 hover:text-foreground ${value >= m.value ? "text-foreground" : "text-muted-foreground"}`}
                style={{ left: `${toRatio(m.value) * 100}%` }}
              >
                {m.label}
              </button>
            ))}
          </div>
        )}
      </div>

      {cta && (
        <div className="mt-8">
          <button
            type="button"
            onClick={() =>
              cta.onClick?.(value, contact ? "Enterprise" : planName, billing)
            }
            className={`cursor-pointer inline-flex h-10 items-center justify-center rounded-full px-5 text-[13.5px] font-medium transition-[background-color,color,box-shadow,transform] duration-300 active:scale-[0.97] ${FOCUS} ${
              contact
                ? "text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent"
                : "bg-primary text-primary-foreground hover:bg-primary/90"
            }`}
          >
            <TextMorph>
              {contact
                ? (cta.contactLabel ?? "Contact sales")
                : cta.label(planName)}
            </TextMorph>
          </button>
        </div>
      )}
      <p id={`${id}-plan`} className="sr-only" aria-live="polite">
        {contact ? "Contact sales for this size" : `${planName} plan`}
      </p>
    </div>
  );
}

"use client";

import * as React from "react";
import { Check, X } from "lucide-react";
import { Faces, FACES_MORPH } from "./faces";
import { NumberRoll } from "./number-roll";
import { PricingToggle } from "./pricing-toggle";
import { StatusButton, type ActionStatus } from "./status-button";
import { StepperInput } from "./stepper-input";
import { TextMorph } from "./text-morph";
import {
  INTERACTION_FOCUS,
  INTERACTION_PRESS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * PRICING PLANS: plans that turn into their own checkout
 *
 *   plans     flat thin line cards; the featured plan is the lit
 *             surface, ruled with fine ledger fine lines. Billing
 *             toggles roll every price the way it moved
 *   choose    the plan you pick turns into its checkout in place,
 *             a slip on the same card: seats on a stepper, the
 *             line items and the total rolling as seats or billing
 *             change, while the other plans step back
 *   checkout  Continue goes Opening checkout → Redirecting through
 *             your onCheckout (create the Stripe or Paddle session
 *             there); a failure keeps the slip and says why
 *   current   with currentPlanId, buttons read Current plan,
 *             Upgrade or Downgrade, for a billing settings page
 * ───────────────────────────────────────────────────────── */

export type Billing = "monthly" | "yearly";

export interface PricingPlan {
  id: string;
  name: string;
  description?: string;
  /** Per month, in major units; per seat when perSeat. Yearly is the monthly rate when billed yearly. */
  price: { monthly: number; yearly: number };
  perSeat?: boolean;
  minSeats?: number;
  maxSeats?: number;
  features: string[];
  /** The plan on the lit surface. */
  featured?: boolean;
  /** A short tag beside the name, e.g. "Most popular". */
  badge?: string;
  /** Button label; defaults to "Get <name>", "Start free" or Upgrade / Downgrade. */
  cta?: string;
  /** A link instead of checkout, e.g. "Contact sales" for an enterprise plan. */
  href?: string;
}

export interface PricingCheckout {
  plan: PricingPlan;
  billing: Billing;
  seats: number;
  /** What's due now, in major units: a month, or a year when billed yearly. */
  total: number;
}

export interface PricingPlansProps {
  plans: PricingPlan[];
  billing?: Billing;
  defaultBilling?: Billing;
  onBillingChange?: (billing: Billing) => void;
  /** The plan the account is on, for a billing settings page. */
  currentPlanId?: string;
  /** Start checkout; resolve once you're redirecting (or done), throw an Error to show its message. */
  onCheckout?: (checkout: PricingCheckout) => Promise<unknown>;
  currency?: string;
  locale?: string;
  className?: string;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const subscribeNothing = () => () => {};
/** False on the server and while hydrating: text is formatted in one fixed locale until then, so the server's and the visitor's never disagree. */
const useHydrated = () =>
  React.useSyncExternalStore(
    subscribeNothing,
    () => true,
    () => false,
  );
const mix = (color: string, amount: number, into = "transparent") =>
  `color-mix(in oklab, ${color} ${amount}%, ${into})`;

/* The lit plan: --primary with a lit corner from --primary-foreground, a deeper lower edge and 1px light edges. */
const LIT_SURFACE: React.CSSProperties = {
  backgroundColor: "var(--primary)",
  backgroundImage: `radial-gradient(120% 90% at 0% 0%, ${mix("var(--primary-foreground)", 22)} 0%, transparent 55%), linear-gradient(170deg, transparent 45%, ${mix("black", 22)} 100%)`,
  boxShadow: `inset 0 1px 0 ${mix("var(--primary-foreground)", 36)}, inset 0 0 0 1px ${mix("var(--primary-foreground)", 12)}`,
};
/* Its signature: fine ledger rules, fading out from the top right. */
const LEDGER: React.CSSProperties = {
  backgroundImage: `repeating-linear-gradient(180deg, transparent 0 11px, ${mix("var(--primary-foreground)", 10)} 11px 12px)`,
  maskImage: "radial-gradient(130% 80% at 100% 0%, black 0%, transparent 70%)",
  WebkitMaskImage:
    "radial-gradient(130% 80% at 100% 0%, black 0%, transparent 70%)",
};
const LIT_ACTION: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, ${mix("var(--primary-foreground)", 16)}, transparent 60%)`,
  boxShadow: `inset 0 1px 0 ${mix("var(--primary-foreground)", 32)}, inset 0 0 0 1px ${mix("black", 10)}`,
};
const COLS: Record<number, string> = {
  1: "",
  2: "@[640px]:grid-cols-2",
  3: "@[640px]:grid-cols-3",
  4: "@[760px]:grid-cols-2 @[1040px]:grid-cols-4",
};

function useMoney(locale: string | undefined, currency: string) {
  return React.useMemo(() => {
    const whole = new Intl.NumberFormat(locale, {
      style: "currency",
      currency,
      maximumFractionDigits: 0,
    });
    const cents = new Intl.NumberFormat(locale, {
      style: "currency",
      currency,
    });
    return { format: (n: number) => (n % 1 ? cents : whole).format(n) };
  }, [locale, currency]);
}

const priceFormat = (
  currency: string,
  n: number,
): Intl.NumberFormatOptions => ({
  style: "currency",
  currency,
  minimumFractionDigits: n % 1 ? 2 : 0,
  maximumFractionDigits: n % 1 ? 2 : 0,
});

export function PricingPlans({
  plans,
  billing: billingProp,
  defaultBilling = "monthly",
  onBillingChange,
  currentPlanId,
  onCheckout,
  currency = "USD",
  locale,
  className = "",
}: PricingPlansProps) {
  const reduced = useInteractionReducedMotion();
  const hydrated = useHydrated();
  const money = useMoney(locale ?? (hydrated ? undefined : "en-US"), currency);
  const baseId = React.useId();
  const [ownBilling, setOwnBilling] = React.useState<Billing>(defaultBilling);
  const billing = billingProp ?? ownBilling;
  const [dir, setDir] = React.useState(1);
  const [openId, setOpenId] = React.useState<string | null>(null);
  const [seats, setSeats] = React.useState<Record<string, number>>({});
  const [status, setStatus] = React.useState<{
    id: string;
    status: ActionStatus;
    error?: string;
  } | null>(null);
  const [ready, setReady] = React.useState(false);
  const slipRefs = React.useRef(new Map<string, HTMLDivElement>());
  const ctaRefs = React.useRef(new Map<string, HTMLElement>());

  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setReady(true));
    return () => cancelAnimationFrame(frame);
  }, []);

  React.useEffect(() => {
    if (!ready || !openId) return;
    slipRefs.current.get(openId)?.focus({ preventScroll: true });
  }, [openId, ready]);

  const setBilling = (next: Billing) => {
    if (next === billing) return;
    setDir(next === "yearly" ? 1 : -1);
    if (billingProp === undefined) setOwnBilling(next);
    onBillingChange?.(next);
  };

  // The toggle's badge says what yearly saves, from the plans themselves.
  const save = Math.max(
    0,
    ...plans
      .filter((p) => p.price.monthly > 0)
      .map((p) => Math.round((1 - p.price.yearly / p.price.monthly) * 100)),
  );
  const options = React.useMemo(
    () => [
      { value: "monthly", label: "Monthly" },
      {
        value: "yearly",
        label: "Yearly",
        ...(save > 0 ? { badge: `Save ${save}%` } : {}),
      },
    ],
    [save],
  );

  const current = plans.find((p) => p.id === currentPlanId);
  const seatsOf = (p: PricingPlan) =>
    p.perSeat ? Math.max(p.minSeats ?? 1, seats[p.id] ?? p.minSeats ?? 1) : 1;
  const totalOf = (p: PricingPlan) =>
    p.price[billing] * seatsOf(p) * (billing === "yearly" ? 12 : 1);
  const busy = status?.status === "pending" || status?.status === "success";

  const close = () => {
    if (busy || !openId) return;
    const id = openId;
    setOpenId(null);
    setStatus(null);
    window.setTimeout(
      () => ctaRefs.current.get(id)?.focus({ preventScroll: true }),
      reduced ? 0 : FACES_MORPH,
    );
  };

  const checkout = async (p: PricingPlan) => {
    if (busy) return;
    setStatus({ id: p.id, status: "pending" });
    try {
      await onCheckout?.({
        plan: p,
        billing,
        seats: seatsOf(p),
        total: totalOf(p),
      });
      setStatus({ id: p.id, status: "success" });
    } catch (e) {
      setStatus({
        id: p.id,
        status: "error",
        error:
          e instanceof Error && e.message
            ? e.message
            : "Couldn’t start checkout. Try again.",
      });
    }
  };

  const ctaLabel = (p: PricingPlan) => {
    if (p.id === currentPlanId) return "Current plan";
    if (current)
      return p.price.monthly >= current.price.monthly
        ? `Upgrade to ${p.name}`
        : `Switch to ${p.name}`;
    return p.cta ?? (p.price.monthly === 0 ? "Start free" : `Get ${p.name}`);
  };

  return (
    <div
      className={`w-full ${className}`}
      onKeyDown={(e) => {
        if (e.key === "Escape" && openId) {
          e.preventDefault();
          close();
        }
      }}
    >
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 960px)" }}
      />
      <div className="@container w-full">
        <div className="flex justify-center">
          <PricingToggle
            value={billing}
            onValueChange={(v) => setBilling(v as Billing)}
            options={options}
          />
        </div>

        <ul
          className={`mt-6 grid grid-cols-1 items-stretch gap-3 ${COLS[Math.min(plans.length, 4)] ?? ""}`}
        >
          {plans.map((p) => {
            const lit = Boolean(p.featured);
            const isOpen = openId === p.id;
            const isCurrent = p.id === currentPlanId;
            const amount = p.price[billing];
            const free = p.price.monthly === 0;
            const st = status?.id === p.id ? status : null;
            const n = seatsOf(p);
            const total = totalOf(p);
            const note = free
              ? "Free forever"
              : billing === "yearly"
                ? `${money.format(amount * 12)}${p.perSeat ? " per seat" : ""} billed yearly`
                : p.perSeat
                  ? "Per seat, billed monthly"
                  : "Billed monthly";
            const muted = lit
              ? "text-primary-foreground/70"
              : "text-muted-foreground";
            const dimmed = openId !== null && !isOpen;

            return (
              <li
                key={p.id}
                className={`relative flex flex-col overflow-clip rounded-[28px] ${isOpen ? "self-start" : ""} ${lit ? "text-primary-foreground" : "border border-border bg-card text-card-foreground"}`}
                style={{
                  ...(lit ? LIT_SURFACE : {}),
                  opacity: dimmed ? 0.5 : 1,
                  transform: dimmed && !reduced ? "scale(0.985)" : "none",
                  transition: reduced
                    ? "opacity 160ms"
                    : `opacity 320ms ${EASE}, transform ${FACES_MORPH}ms ${EASE}`,
                }}
              >
                {lit && (
                  <span
                    aria-hidden="true"
                    className="pointer-events-none absolute inset-0"
                    style={LEDGER}
                  />
                )}
                <Faces
                  active={isOpen ? 1 : 0}
                  reduced={reduced}
                  ready={ready}
                  className="flex-1"
                >
                  {/* The plan. */}
                  <div className="flex h-full flex-col p-6">
                    <div className="flex items-center gap-2">
                      <h3
                        id={`${baseId}-${p.id}`}
                        className="text-[16px] font-medium tracking-[-0.01em]"
                      >
                        {p.name}
                      </h3>
                      {(p.badge || isCurrent) && (
                        <span
                          className={`rounded-full px-2 py-0.5 text-[11.5px] font-medium ${lit ? "bg-primary-foreground/15 text-primary-foreground" : "bg-primary/10 text-primary"}`}
                        >
                          {isCurrent ? "Your plan" : p.badge}
                        </span>
                      )}
                    </div>
                    {p.description && (
                      <p
                        className={`mt-1.5 text-[13.5px] leading-relaxed ${muted}`}
                      >
                        {p.description}
                      </p>
                    )}

                    <div className="mt-6 flex items-baseline gap-1.5">
                      <span className="text-[clamp(40px,7cqw,52px)] font-medium leading-none tracking-[-0.045em] tabular-nums">
                        {free ? (
                          "Free"
                        ) : (
                          <NumberRoll
                            value={amount}
                            locales={locale}
                            format={priceFormat(currency, amount)}
                          />
                        )}
                      </span>
                      {!free && (
                        <span className={`text-[13.5px] ${muted}`}>
                          {p.perSeat ? "/seat/mo" : "/mo"}
                        </span>
                      )}
                    </div>
                    <div
                      className={`relative mt-2 h-5 overflow-hidden text-[12.5px] ${muted}`}
                    >
                      <span
                        key={note}
                        className="absolute inset-0 truncate motion-safe:animate-[ui-note-in_380ms_cubic-bezier(0.23,1,0.32,1)_both]"
                        style={
                          {
                            "--ui-from": `${dir > 0 ? 100 : -100}%`,
                          } as React.CSSProperties
                        }
                      >
                        {note}
                      </span>
                    </div>

                    <div className="mt-6">
                      {p.href && !isCurrent ? (
                        <a
                          ref={(el) => {
                            if (el) ctaRefs.current.set(p.id, el);
                          }}
                          href={p.href}
                          className={`flex h-12 w-full items-center justify-center rounded-full text-[15px] font-medium ${INTERACTION_PRESS} ${INTERACTION_FOCUS} ${lit ? "bg-primary-foreground text-primary" : "text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent"}`}
                        >
                          {p.cta ?? "Contact sales"}
                        </a>
                      ) : free && !isCurrent ? (
                        <StatusButton
                          status={st?.status ?? "idle"}
                          labels={{
                            idle: ctaLabel(p),
                            pending: "Setting up",
                            success: "You’re in",
                            error: "Try again",
                          }}
                          variant="outline"
                          onClick={() => void checkout(p)}
                          className="h-12 w-full text-[15px]"
                        />
                      ) : (
                        <button
                          ref={(el) => {
                            if (el) ctaRefs.current.set(p.id, el);
                          }}
                          type="button"
                          disabled={isCurrent}
                          aria-expanded={isOpen}
                          onClick={() => {
                            setStatus(null);
                            setOpenId(p.id);
                          }}
                          className={`flex h-12 w-full cursor-pointer items-center justify-center rounded-full text-[15px] font-medium disabled:cursor-default ${INTERACTION_PRESS} ${INTERACTION_FOCUS} ${
                            isCurrent
                              ? lit
                                ? "bg-primary-foreground/15 text-primary-foreground/80"
                                : "bg-muted text-muted-foreground"
                              : lit
                                ? "bg-primary-foreground text-primary hover:bg-primary-foreground/90"
                                : "bg-primary text-primary-foreground hover:bg-primary/90"
                          }`}
                          style={!lit && !isCurrent ? LIT_ACTION : undefined}
                        >
                          {ctaLabel(p)}
                        </button>
                      )}
                    </div>
                    {st?.status === "error" && free && (
                      <p
                        role="alert"
                        className="mt-2 text-center text-[12.5px] text-red-600 dark:text-red-400"
                      >
                        {st.error}
                      </p>
                    )}

                    <ul
                      className={`mt-6 space-y-2.5 border-t pt-5 text-[13.5px] ${lit ? "border-primary-foreground/15" : "border-border"}`}
                    >
                      {p.features.map((f) => (
                        <li key={f} className="flex gap-2.5">
                          <span
                            className={`mt-px flex size-[18px] shrink-0 items-center justify-center rounded-full ${lit ? "bg-primary-foreground/15" : "bg-primary/10 text-primary"}`}
                          >
                            <Check
                              aria-hidden="true"
                              className="size-3"
                              strokeWidth={2.5}
                            />
                          </span>
                          <span
                            className={
                              lit
                                ? "text-primary-foreground/90"
                                : "text-foreground"
                            }
                          >
                            {f}
                          </span>
                        </li>
                      ))}
                    </ul>
                  </div>

                  {/* Its checkout: a slip on the same card. */}
                  <div className="p-2.5">
                    <div
                      ref={(el) => {
                        if (el) slipRefs.current.set(p.id, el);
                        else slipRefs.current.delete(p.id);
                      }}
                      tabIndex={-1}
                      role="group"
                      aria-label={`Checkout for ${p.name}`}
                      className="rounded-[20px] border border-border bg-card p-4 text-card-foreground outline-none"
                    >
                      <div className="flex items-center justify-between gap-3">
                        <p className="text-[15px] font-medium tracking-[-0.01em]">
                          {p.name} ·{" "}
                          <TextMorph>
                            {billing === "yearly" ? "Yearly" : "Monthly"}
                          </TextMorph>
                        </p>
                        <button
                          type="button"
                          aria-label="Back to plans"
                          onClick={close}
                          className={`-mr-1.5 flex size-8 cursor-pointer items-center justify-center rounded-full text-muted-foreground hover:bg-accent hover:text-foreground ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`}
                        >
                          <X aria-hidden="true" className="size-4" />
                        </button>
                      </div>

                      {p.perSeat && (
                        <div className="mt-4 flex items-center justify-between gap-3">
                          <span className="text-[13.5px] text-muted-foreground">
                            Seats
                          </span>
                          <StepperInput
                            label="Seats"
                            value={n}
                            onValueChange={(v) =>
                              !busy && setSeats((s) => ({ ...s, [p.id]: v }))
                            }
                            min={p.minSeats ?? 1}
                            max={p.maxSeats ?? 500}
