export function PrivacyMask({
  value,
  label = "Confidential value",
  trigger = "click",
  maskStyle = "blur",
  autoHideMs = 6000,
  copyable = true,
  className = "",
  ...rest
}: PrivacyMaskProps) {
  const reduced = useReducedMotion();
  const [revealed, setRevealed] = React.useState(false);
  const [copied, setCopied] = React.useState(false);
  const autoHideTimer = React.useRef<number | null>(null);
  const copyTimer = React.useRef<number | null>(null);
  const containerRef = React.useRef<HTMLDivElement>(null);

  const clearTimers = React.useCallback(() => {
    if (autoHideTimer.current) {
      window.clearTimeout(autoHideTimer.current);
      autoHideTimer.current = null;
    }
    if (copyTimer.current) {
      window.clearTimeout(copyTimer.current);
      copyTimer.current = null;
    }
  }, []);

  const scheduleAutoHide = React.useCallback(() => {
    if (autoHideMs <= 0) return;
    if (autoHideTimer.current) window.clearTimeout(autoHideTimer.current);
    autoHideTimer.current = window.setTimeout(() => {
      setRevealed(false);
    }, autoHideMs);
  }, [autoHideMs]);

  // Clean up timers on unmount
  React.useEffect(() => {
    return () => clearTimers();
  }, [clearTimers]);

  // Keyboard shortcut: Escape re-masks immediately
  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Escape" && revealed) {
      e.preventDefault();
      setRevealed(false);
    } else if ((e.key === "Enter" || e.key === " ") && trigger === "click") {
      e.preventDefault();
      toggleReveal();
    }
  };

  const toggleReveal = () => {
    setRevealed((prev) => {
      const next = !prev;
      if (next) scheduleAutoHide();
      return next;
    });
  };

  // Pointer & Touch handlers for hold & hover
  const handlePointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if (trigger === "hold") {
      try {
        e.currentTarget.setPointerCapture(e.pointerId);
      } catch {
        // Fallback if pointer capture unsupported
      }
      setRevealed(true);
    }
  };

  const handlePointerUp = (e: React.PointerEvent<HTMLDivElement>) => {
    if (trigger === "hold") {
      try {
        if (e.currentTarget.hasPointerCapture(e.pointerId)) {
          e.currentTarget.releasePointerCapture(e.pointerId);
        }
      } catch {
        // Safe release
      }
      setRevealed(false);
    }
  };

  const handlePointerCancel = () => {
    if (trigger === "hold") {
      setRevealed(false);
    }
  };

  const handleCopy = async (e: React.MouseEvent) => {
    e.stopPropagation();
    try {
      await navigator.clipboard.writeText(value);
      setCopied(true);
      if (copyTimer.current) window.clearTimeout(copyTimer.current);
      copyTimer.current = window.setTimeout(() => setCopied(false), 1800);
    } catch {
      // Fallback
    }
  };

  // Masked display formatting
  const displayMasked = React.useMemo(() => {
    if (maskStyle === "truncate" && value.length > 8) {
      return `${value.slice(0, 4)}••••••••${value.slice(-4)}`;
    }
    if (maskStyle === "dots") {
      return "••••••••••••";
    }
    return value;
  }, [maskStyle, value]);

  const isBlurred = !revealed && maskStyle === "blur";

  return (
    <div
      ref={containerRef}
      role="group"
      aria-label={label}
      tabIndex={0}
      onKeyDown={handleKeyDown}
      onClick={trigger === "click" ? toggleReveal : undefined}
      onMouseEnter={() => {
        if (trigger === "hover") setRevealed(true);
      }}
      onMouseLeave={() => {
        if (trigger === "hover") setRevealed(false);
      }}
      onPointerDown={handlePointerDown}
      onPointerUp={handlePointerUp}
      onPointerCancel={handlePointerCancel}
      className={`group relative inline-flex w-full max-w-full items-center justify-between gap-2 overflow-hidden rounded-lg border border-border bg-card px-2.5 py-1.5 text-card-foreground select-none transition-[border-color,box-shadow,background-color] duration-200 touch-manipulation focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 ${
        trigger === "click"
          ? "cursor-pointer hover:bg-muted/30 active:bg-muted/50"
          : trigger === "hold"
            ? "cursor-pointer"
            : ""
      } ${className}`}
      style={{
        clipPath: "inset(0 round 0.5rem)",
      }}
      {...rest}
    >
      {/* Content value */}
      <div className="relative min-w-0 flex-1 overflow-hidden pr-1">
        <span
          className={`block truncate font-mono text-[12.5px] tabular-nums transition-[filter,opacity] duration-200 ${
            isBlurred
              ? "filter blur-[5px] opacity-60 group-hover:opacity-80"
              : "opacity-100 filter-none"
          }`}
          style={{
            transitionTimingFunction: EASE,
          }}
        >
          {revealed || maskStyle === "blur" ? value : displayMasked}
        </span>
      </div>

      {/* Action Buttons */}
      <div
        className="flex shrink-0 items-center gap-1 border-l border-border/60 pl-1.5 text-muted-foreground"
        onClick={(e) => {
          // If clicking container toggles, let eye click toggle without double trigger
          if (trigger === "click") {
            e.stopPropagation();
            toggleReveal();
          }
        }}
      >
        {/* Toggle Eye Button */}
        <button
          type="button"
          tabIndex={-1}
          aria-label={revealed ? "Hide value" : "Reveal value"}
          className="flex size-7 items-center justify-center rounded-md transition-colors hover:bg-muted hover:text-foreground active:scale-95 cursor-pointer touch-manipulation"
        >
          {revealed ? <EyeOffIcon /> : <EyeIcon />}
        </button>

        {/* Copy Button */}
        {copyable && (
          <button
            type="button"
            tabIndex={-1}
            aria-label={copied ? "Copied" : "Copy to clipboard"}
            onClick={handleCopy}
            className={`flex size-7 items-center justify-center rounded-md transition-colors hover:bg-muted active:scale-95 cursor-pointer touch-manipulation ${
              copied
                ? "text-emerald-600 dark:text-emerald-400"
                : "hover:text-foreground"
            }`}
          >
            <CheckIcon drawn={copied} reduced={reduced} className="size-3.5" />
            {!copied && <CopyIcon />}
          </button>
        )}
      </div>

      {/* Screen reader notification */}
      <span className="sr-only" role="status" aria-live="polite">
        {label}: {revealed ? value : "Hidden"}
      </span>
    </div>
  );
}

"use client";

import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";
import {
  EASE_OUT,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * PROGRESS: how far along, as a bar or a ring
 *
 *   advance   the fill eases to each new value (it never jumps a
 *             step) and the percent rolls the way it moved
 *   unknown   without a value, a short segment sweeps along
 *   done      at 100 the fill turns green, a check draws itself
 *             and the label morphs to `doneLabel`
 *   error     the fill turns red where it stopped
 * ───────────────────────────────────────────────────────── */

export interface ProgressProps {
  /** 0–100; leave it out for "working, no idea how long". */
  value?: number | null;
  /** Shown above a bar, beside the percent. */
  label?: string;
  /** Replaces the label at 100. */
  doneLabel?: string;
  error?: boolean;
  showValue?: boolean;
  variant?: "bar" | "ring";
  /** Ring size in px. */
  size?: number;
  className?: string;
}

function Check({ on, reduced }: { on: boolean; reduced: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="none" className="size-3.5">
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: on ? 0 : 1,
          transition: reduced
            ? "none"
            : `stroke-dashoffset 360ms ${EASE_OUT} 160ms`,
        }}
      />
    </svg>
  );
}

export function Progress({
  value,
  label,
  doneLabel = "Done",
  error,
  showValue = true,
  variant = "bar",
  size = 44,
  className = "",
}: ProgressProps) {
  const reduced = useInteractionReducedMotion();
  const known = value !== undefined && value !== null;
  const v = known ? Math.max(0, Math.min(100, value)) : 0;
  const done = known && v >= 100 && !error;
  const tone = error ? "bg-red-500" : done ? "bg-emerald-500" : "bg-primary";
  const text = error
    ? "text-red-600 dark:text-red-400"
    : done
      ? "text-emerald-600 dark:text-emerald-400"
      : "text-foreground";
  const aria = {
    role: "progressbar" as const,
    "aria-label": label ?? "Progress",
    "aria-valuemin": 0,
    "aria-valuemax": 100,
    "aria-valuenow": known ? Math.round(v) : undefined,
    "aria-busy": !done || undefined,
  };

  if (variant === "ring") {
    const r = 15;
    return (
      <span
        {...aria}
        className={`relative inline-flex shrink-0 items-center justify-center ${className}`}
        style={{ width: size, height: size }}
      >
        <svg
          viewBox="0 0 36 36"
          className={`absolute inset-0 size-full -rotate-90 ${known ? "" : "animate-spin [animation-duration:1.1s]"}`}
          aria-hidden="true"
        >
          <circle
            cx="18"
            cy="18"
            r={r}
            fill="none"
            stroke="currentColor"
            strokeWidth="3"
            className="text-muted"
          />
          <circle
            cx="18"
            cy="18"
            r={r}
            fill="none"
            strokeWidth="3"
            strokeLinecap="round"
            pathLength={100}
            strokeDasharray="100"
            className={`${error ? "stroke-red-500" : done ? "stroke-emerald-500" : "stroke-primary"} transition-[stroke] duration-300`}
            style={{
              strokeDashoffset: known ? 100 - v : 72,
              transition: reduced
                ? "none"
                : `stroke-dashoffset 600ms ${EASE_OUT}, stroke 300ms`,
            }}
          />
        </svg>
        <span
          className={`relative flex items-center justify-center text-[11px] font-medium tabular-nums ${text}`}
        >
          {done ? (
            <Check on reduced={reduced} />
          ) : known && showValue ? (
            <NumberRoll value={Math.round(v)} suffix="%" />
          ) : null}
        </span>
      </span>
    );
  }

  return (
    <div className={`flex w-full flex-col gap-2 ${className}`}>
      {(label || showValue) && (
        <div className="flex items-baseline justify-between gap-3 text-[13px]">
          <span
            className={`flex items-center gap-1.5 font-medium transition-colors duration-300 ${done ? text : "text-foreground"}`}
          >
            <span
              className="grid"
              style={{
                gridTemplateColumns: done ? "1fr" : "0fr",
                transition: reduced
                  ? "none"
                  : `grid-template-columns 320ms ${EASE_OUT}`,
              }}
            >
              <span className="min-w-0 overflow-hidden">
                <Check on={done} reduced={reduced} />
              </span>
            </span>
            {label && <TextMorph>{done ? doneLabel : label}</TextMorph>}
          </span>
          {showValue && known && (
            <span className="tabular-nums text-muted-foreground">
              <NumberRoll value={Math.round(v)} suffix="%" />
            </span>
          )}
        </div>
      )}
      <div
        {...aria}
        className="relative h-1.5 w-full overflow-hidden rounded-full bg-muted"
      >
        {known ? (
          <div
            className={`absolute inset-0 origin-left rounded-full transition-colors duration-300 ${tone}`}
            style={{
              transform: `scaleX(${v / 100})`,
              transition: reduced
                ? "none"
                : `transform 600ms ${EASE_OUT}, background-color 300ms`,
            }}
          />
        ) : (
          <div
            className={`absolute inset-y-0 left-0 w-[30%] rounded-full ${tone} [animation:ui-indeterminate_1.3s_cubic-bezier(0.65,0,0.35,1)_infinite] motion-reduce:[animation-duration:3s]`}
          />
        )}
      </div>
    </div>
  );
}

export default Progress;

"use client";

import * as React from "react";
import { ArrowUp, Paperclip, Square } from "lucide-react";
import { NumberRoll } from "./number-roll";

/* ─────────────────────────────────────────────────────────
 * PROMPT COMPOSER: where the conversation starts
 *
 *   ready      type; Enter sends, Shift+Enter adds a line
 *   submitted  sent: the arrow blurs into a spinner
 *   streaming  the spinner blurs into Stop
 *   error      ready to try again
 *   disabled   with a reason, e.g. a rate limit, folding open
 *              above the field
 *
 * Near the limit a counter opens in and rolls as you type;
 * attachments fold open above the field as the first one lands.
 *
 * status takes useChat's status as is. Files come in through the
 * paperclip, paste or drag and drop; render them as chips in the
 * attachments slot. The toolbar slot fits a mode switcher.
 * ───────────────────────────────────────────────────────── */

export type ComposerStatus = "ready" | "submitted" | "streaming" | "error";

export interface PromptComposerProps extends Omit<
  React.FormHTMLAttributes<HTMLFormElement>,
  "onSubmit" | "defaultValue"
> {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onSubmit: (value: string) => void;
  onStop?: () => void;
  /** Pass useChat's status straight through. */
  status?: ComposerStatus;
  placeholder?: string;
  disabled?: boolean;
  /** Shown above the input while disabled, e.g. "You've reached today's limit." */
  disabledReason?: React.ReactNode;
  /** Enables the paperclip, paste and drop. */
  onFilesSelected?: (files: File[]) => void;
  accept?: string;
  /** Attachment chips, shown above the text. */
  attachments?: React.ReactNode;
  /** Controls at the bottom left, e.g. a mode switcher. */
  toolbar?: React.ReactNode;
  maxLength?: number;
  /** Allow sending with no text, e.g. when files are attached. */
  allowEmpty?: boolean;
  autoFocus?: boolean;
}

const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const MORPH = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Icons trade places through a blur: the old one shrinks away as the new one grows in. */
const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 260ms ${MORPH}, transform 380ms ${MORPH}, filter 260ms ${MORPH}`,
});

/** A block that folds open to its height and shut again, keeping what it showed while it closes. */
function Fold({
  show,
  reduced,
  children,
}: {
  show: boolean;
  reduced: boolean;
  children: React.ReactNode;
}) {
  const [last, setLast] = React.useState(children);
  if (show && children !== last) setLast(children);
  return (
    <div
      aria-hidden={!show || undefined}
      inert={!show}
      className="grid"
      style={{
        gridTemplateRows: show ? "1fr" : "0fr",
        opacity: show ? 1 : 0,
        transition: reduced
          ? "none"
          : `grid-template-rows 380ms ${MORPH}, opacity ${show ? "280ms" : "140ms"} ${MORPH}`,
      }}
    >
      <div className="min-h-0 overflow-hidden">{show ? children : last}</div>
    </div>
  );
}

export function PromptComposer({
  value,
  defaultValue = "",
  onValueChange,
  onSubmit,
  onStop,
  status = "ready",
  placeholder = "Ask anything",
  disabled = false,
  disabledReason,
  onFilesSelected,
  accept,
  attachments,
  toolbar,
  maxLength,
  allowEmpty = false,
  autoFocus,
  className = "",
  ...props
}: PromptComposerProps) {
  const reduced = useReducedMotion();
  const [own, setOwn] = React.useState(defaultValue);
  const [dragging, setDragging] = React.useState(false);
  const text = value ?? own;
  const textareaRef = React.useRef<HTMLTextAreaElement>(null);
  const fileRef = React.useRef<HTMLInputElement>(null);
  const busy = status === "submitted" || status === "streaming";
  const canSend =
    !disabled &&
    !busy &&
    (allowEmpty || text.trim().length > 0) &&
    (maxLength === undefined || text.length <= maxLength);

  const setText = (next: string) => {
    if (value === undefined) setOwn(next);
    onValueChange?.(next);
  };

  // Grow with the text, up to a scrolling maximum.
  React.useLayoutEffect(() => {
    const el = textareaRef.current;
    if (!el) return;
    el.style.height = "auto";
    el.style.height = `${Math.min(el.scrollHeight, 200)}px`;
  }, [text]);

  const submit = () => {
    if (!canSend) return;
    onSubmit(text);
    if (value === undefined) setOwn("");
  };

  const onKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent.isComposing) {
      e.preventDefault();
      submit();
    }
  };

  const takeFiles = (list: FileList | null) => {
    if (!list || list.length === 0 || !onFilesSelected) return false;
    onFilesSelected(Array.from(list));
    return true;
  };

  const action = busy
    ? status === "streaming" && onStop
      ? "stop"
      : "wait"
    : "send";

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        submit();
      }}
      onDragOver={(e) => {
        if (!onFilesSelected || !e.dataTransfer.types.includes("Files")) return;
        e.preventDefault();
        setDragging(true);
      }}
      onDragLeave={(e) => {
        if (!e.currentTarget.contains(e.relatedTarget as Node))
          setDragging(false);
      }}
      onDrop={(e) => {
        if (!onFilesSelected) return;
        e.preventDefault();
        setDragging(false);
        takeFiles(e.dataTransfer.files);
      }}
      className={`relative rounded-2xl border bg-background transition-colors focus-within:border-foreground/25 ${
        dragging ? "border-dashed border-foreground/40" : "border-border"
      } ${className}`}
      {...props}
    >
      <Fold show={Boolean(disabled && disabledReason)} reduced={reduced}>
        <div className="border-b border-border px-3.5 py-2 text-[12px] text-muted-foreground">
          {disabledReason}
        </div>
      </Fold>

      <Fold show={Boolean(attachments)} reduced={reduced}>
        <div className="flex flex-wrap gap-2 px-3 pt-3">{attachments}</div>
      </Fold>

      <textarea
        ref={textareaRef}
        rows={1}
        value={text}
        autoFocus={autoFocus}
        disabled={disabled}
        placeholder={placeholder}
        aria-label={placeholder}
        onChange={(e) => setText(e.target.value)}
        onKeyDown={onKeyDown}
        onPaste={(e) => {
          if (
            takeFiles(e.clipboardData.files) &&
            !e.clipboardData.getData("text")
          )
            e.preventDefault();
        }}
        className="block max-h-[200px] w-full resize-none overflow-y-auto bg-transparent px-3.5 pb-1 pt-3 text-[14px] leading-6 text-foreground outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed disabled:opacity-60"
      />

      <div className="flex items-center gap-1.5 px-2 pb-2 pt-1">
        {onFilesSelected && (
          <>
            <button
              type="button"
              aria-label="Attach files"
              disabled={disabled}
              onClick={() => fileRef.current?.click()}
              className={`cursor-pointer disabled:cursor-default flex size-8 items-center justify-center rounded-full text-muted-foreground transition-colors hover:bg-accent hover:text-foreground disabled:opacity-40 ${FOCUS}`}
            >
              <Paperclip className="size-4" />
            </button>
            <input
              ref={fileRef}
              type="file"
              multiple
              accept={accept}
              className="hidden"
              onChange={(e) => {
                takeFiles(e.target.files);
                e.target.value = "";
              }}
            />
          </>
        )}
        {toolbar}

        <div className="ml-auto flex items-center gap-2.5">
          {maxLength !== undefined && (
            // Opens in near the limit and rolls as you type; red once you're over.
            <span
              aria-hidden={text.length <= maxLength * 0.8 || undefined}
              className="grid"
              style={{
                gridTemplateColumns:
                  text.length > maxLength * 0.8 ? "1fr" : "0fr",
                opacity: text.length > maxLength * 0.8 ? 1 : 0,
                transition: reduced
                  ? "none"
                  : `grid-template-columns 380ms ${MORPH}, opacity 260ms ${MORPH}`,
              }}
            >
              <span
                className={`flex min-w-0 items-baseline overflow-hidden whitespace-nowrap font-mono text-[11px] tabular-nums transition-colors duration-300 ${
                  text.length > maxLength
                    ? "text-red-500"
                    : "text-muted-foreground"
                }`}
              >
                <NumberRoll value={text.length} duration={300} />/{maxLength}
              </span>
            </span>
          )}
          <button
            type={action === "send" ? "submit" : "button"}
            aria-label={
              action === "stop"
                ? "Stop"
                : action === "wait"
                  ? "Sending"
                  : "Send"
            }
            disabled={action === "send" ? !canSend : action === "wait"}
            onClick={action === "stop" ? onStop : undefined}
            className={`cursor-pointer disabled:cursor-default relative flex size-8 items-center justify-center rounded-full bg-primary text-primary-foreground transition-[opacity,transform] duration-200 active:scale-95 disabled:opacity-35 ${FOCUS}`}
          >
            <span
              aria-hidden="true"
              className="absolute inset-0 flex items-center justify-center"
              style={swap(action === "send", reduced)}
            >
              <ArrowUp className="size-4" />
            </span>
            <span
              aria-hidden="true"
              className="absolute inset-0 flex items-center justify-center"
              style={swap(action === "stop", reduced)}
            >
              <Square fill="currentColor" className="size-3" />
            </span>
            <span
              aria-hidden="true"
              className="absolute inset-0 flex items-center justify-center"
              style={swap(action === "wait", reduced)}
            >
              {/* Spins only while it's showing. */}
              <span
                className={`size-3.5 rounded-full border-[1.5px] border-current/35 border-t-current motion-reduce:animate-none ${action === "wait" ? "animate-spin" : ""}`}
              />
            </span>
          </button>
        </div>
      </div>

      <div
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 flex items-center justify-center rounded-2xl bg-background/85 text-[13px] font-medium text-foreground"
        style={{
          opacity: dragging ? 1 : 0,
          transition: reduced ? "none" : `opacity 200ms ${MORPH}`,
        }}
      >
        Drop files to attach
      </div>
    </form>
  );
}

