"use client";

import * as React from "react";
import {
  EASE_OUT,
  EASE_THROW,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * RADIO GROUP: one choice, one moving mark
 *
 *   list    the dot shrinks out of the old circle as it pops
 *           into the new one (a slight overshoot)
 *   cards   options are cards; the selection is one frame that
 *           glides from card to card, its height easing when
 *           the cards differ, instead of rings blinking
 *
 * Real radio inputs underneath: arrow keys, forms and screen
 * readers behave exactly as native radios do.
 * ───────────────────────────────────────────────────────── */

export interface RadioOption {
  value: string;
  label: React.ReactNode;
  description?: React.ReactNode;
  /** Right side of a card, e.g. a price. */
  aside?: React.ReactNode;
  disabled?: boolean;
}

export interface RadioGroupProps {
  options: RadioOption[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Form name; one is made up if you don't pass it. */
  name?: string;
  /** Accessible name of the group (shown as a legend when `showLabel`). */
  label: string;
  showLabel?: boolean;
  variant?: "list" | "cards";
  orientation?: "vertical" | "horizontal";
  disabled?: boolean;
  className?: string;
}

type Mark = { y: number; x: number; w: number; h: number };

export function RadioGroup({
  options,
  value,
  defaultValue,
  onValueChange,
  name,
  label,
  showLabel = false,
  variant = "list",
  orientation = "vertical",
  disabled,
  className = "",
}: RadioGroupProps) {
  const reduced = useInteractionReducedMotion();
  const auto = React.useId();
  const group = name ?? auto;
  const [own, setOwn] = React.useState(defaultValue ?? null);
  const current = value !== undefined ? value : own;
  const listRef = React.useRef<HTMLDivElement>(null);
  const [mark, setMark] = React.useState<Mark | null>(null);
  const [ready, setReady] = React.useState(false);
  const cards = variant === "cards";

  React.useLayoutEffect(() => {
    if (!cards) return;
    const list = listRef.current;
    if (!list) return;
    const measure = () => {
      const el = current
        ? list.querySelector<HTMLElement>(
            `[data-radio="${CSS.escape(current)}"]`,
          )
        : null;
      if (!el) return setMark(null);
      const next = {
        x: el.offsetLeft,
        y: el.offsetTop,
        w: el.offsetWidth,
        h: el.offsetHeight,
      };
      setMark((p) =>
        p &&
        p.x === next.x &&
        p.y === next.y &&
        p.w === next.w &&
        p.h === next.h
          ? p
          : next,
      );
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(list);
    return () => ro.disconnect();
  }, [cards, current, options]);

  React.useEffect(() => {
    if (!mark || ready) return;
    const frame = requestAnimationFrame(() => setReady(true));
    return () => cancelAnimationFrame(frame);
  }, [mark, ready]);

  const pick = (v: string) => {
    if (value === undefined) setOwn(v);
    onValueChange?.(v);
  };

  return (
    <fieldset
      className={`m-0 min-w-0 border-0 p-0 ${className}`}
      disabled={disabled}
    >
      <legend
        className={
          showLabel
            ? "mb-2 px-0.5 text-[13px] font-medium text-foreground"
            : "sr-only"
        }
      >
        {label}
      </legend>
      <div
        ref={listRef}
        className={`relative flex ${orientation === "horizontal" ? "flex-row flex-wrap" : "flex-col"} ${cards ? "gap-2" : orientation === "horizontal" ? "gap-x-5 gap-y-2" : "gap-2.5"}`}
      >
        {cards && (
          <span
            aria-hidden="true"
            className="pointer-events-none absolute left-0 top-0 z-10 rounded-[14px] shadow-[inset_0_0_0_1.5px_var(--primary)]"
            style={{
              transform: `translate3d(${mark?.x ?? 0}px, ${mark?.y ?? 0}px, 0)`,
              width: mark?.w ?? 0,
              height: mark?.h ?? 0,
              opacity: mark ? 1 : 0,
              transition:
                reduced || !ready
                  ? "none"
                  : `transform 420ms ${EASE_THROW}, width 380ms ${EASE_OUT}, height 380ms ${EASE_OUT}, opacity 200ms ${EASE_OUT}`,
            }}
          />
        )}
        {options.map((option) => {
          const on = current === option.value;
          const off = disabled || option.disabled;
          return (
            <label
              key={option.value}
              data-radio={option.value}
              className={`group/radio relative flex select-none items-start gap-2.5 ${off ? "cursor-default opacity-50" : "cursor-pointer"} ${
                cards
                  ? `rounded-[14px] bg-background p-3.5 shadow-[inset_0_0_0_1px_var(--border)] transition-[background-color] duration-200 ${on ? "bg-accent/50" : "hover:bg-accent/40"}`
                  : ""
              }`}
            >
              <span className="relative mt-[2px] inline-flex size-4 shrink-0">
                <input
                  type="radio"
                  name={group}
                  value={option.value}
                  checked={on}
                  disabled={off}
                  onChange={() => pick(option.value)}
                  className="peer absolute inset-0 m-0 size-full cursor-[inherit] appearance-none rounded-full outline-none"
                />
                <span
                  aria-hidden="true"
                  className={`pointer-events-none absolute inset-0 rounded-full bg-background transition-[box-shadow,scale] duration-200 group-active/radio:scale-[0.88] peer-focus-visible:shadow-[inset_0_0_0_1px_var(--ring),0_0_0_3px_color-mix(in_oklab,var(--ring)_20%,transparent)] motion-reduce:group-active/radio:scale-100 ${
                    on
                      ? "shadow-[inset_0_0_0_1.5px_var(--primary)]"
                      : "shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--foreground)_22%,var(--border))] group-hover/radio:shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--foreground)_40%,var(--border))]"
                  }`}
                >
                  <span
                    className="absolute inset-[4px] rounded-full bg-primary"
                    style={{
                      transform: on ? "scale(1)" : "scale(0)",
                      transition: reduced
                        ? "none"
                        : on
                          ? `transform 380ms ${EASE_THROW}`
                          : `transform 200ms ${EASE_OUT}`,
                    }}
                  />
                </span>
              </span>
              <span className="flex min-w-0 flex-1 flex-col gap-0.5">
                <span className="text-[13.5px] font-medium leading-5 text-foreground">
                  {option.label}
                </span>
                {option.description && (
                  <span className="text-[12.5px] leading-snug text-muted-foreground">
                    {option.description}
                  </span>
                )}
              </span>
              {option.aside && (
                <span className="shrink-0 text-[13px] tabular-nums text-foreground">
                  {option.aside}
                </span>
              )}
            </label>
          );
        })}
      </div>
    </fieldset>
  );
}

export default RadioGroup;

"use client";

/* ─────────────────────────────────────────────────────────
 * RANGE RULER: dual needles on a graduated thin line ruler
 *
 *   ruler      an axis with 1px SVG tick marks; major ticks
 *              mark intervals, minor ticks subdivide steps
 *   needles    two tactile thin line sliders with 1px indicators;
 *              needles glide with zero edge-jumping or layout thrash
 *   repulsion  drag the lower needle into the upper one and it
 *              pushes the upper needle forward instead of
 *              clipping; drag backwards and it pushes down
 *   badges     floating metric pills roll with NumberRoll;
 *              when needles get within 48px, badges merge into
 *              a single span readout
 *   mobile     expanded touch targets and track-wide gesture
 *              capture allow effortless finger manipulation
 *
 * Both needles are accessible sliders with full arrow, Home,
 * End, and Page keys.
 * ───────────────────────────────────────────────────────── */

import * as React from "react";
import { NumberRoll } from "./number-roll";
import {
  INTERACTION_FOCUS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";
import { snapRulerValue, useRangeRuler } from "./use-range-ruler";

export type RangeValue = [number, number];

export interface RangeRulerProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onChange" | "defaultValue"
> {
  label?: string;
  value?: RangeValue;
  defaultValue?: RangeValue;
  min?: number;
  max?: number;
  step?: number;
  minDistance?: number;
  unit?: string;
  disabled?: boolean;
  onValueChange?: (value: RangeValue) => void;
  onValueCommit?: (value: RangeValue) => void;
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
}

export function RangeRuler({
  label,
  value,
  defaultValue = [20, 80],
  min = 0,
  max = 100,
  step = 1,
  minDistance = 0,
  unit = "",
  disabled = false,
  onValueChange,
  onValueCommit,
  format,
  locales,
  className = "",
  ...props
}: RangeRulerProps) {
  const reduced = useInteractionReducedMotion();
  const lower = Number.isFinite(min) ? min : 0;
  const upper = Number.isFinite(max) && max > lower ? max : lower + 100;
  const increment = Number.isFinite(step) && step > 0 ? step : 1;

  const [own, setOwn] = React.useState<RangeValue>(defaultValue);
  const currentVal = value ?? own;

  const safeVal: RangeValue = React.useMemo(() => {
    const l = snapRulerValue(
      currentVal[0],
      lower,
      upper - minDistance,
      increment,
    );
    const u = snapRulerValue(currentVal[1], l + minDistance, upper, increment);
    return [l, u];
  }, [currentVal, lower, upper, minDistance, increment]);

  const decimals = Math.min(
    4,
    Math.max(0, (String(increment).split(".")[1] ?? "").length),
  );

  const formatter = React.useMemo(
    () => (format || locales ? new Intl.NumberFormat(locales, format) : null),
    [locales, format],
  );

  const formatNumber = React.useCallback(
    (n: number) => {
      const formatted = formatter ? formatter.format(n) : n.toFixed(decimals);
      return unit ? `${formatted} ${unit}` : formatted;
    },
    [decimals, unit, formatter],
  );

  const formatAria = React.useCallback(
    (n: number) => {
      const formatted = formatter ? formatter.format(n) : n.toFixed(decimals);
      return `${formatted}${unit ? ` ${unit}` : ""}`;
    },
    [decimals, unit, formatter],
  );

  const handleChange = React.useCallback(
    (next: RangeValue) => onValueChange?.(next),
    [onValueChange],
  );

  const handleCommit = React.useCallback(
    (next: RangeValue) => {
      if (value === undefined) setOwn(next);
      onValueCommit?.(next);
    },
    [value, onValueCommit],
  );

  const ruler = useRangeRuler({
    value: safeVal,
    min: lower,
    max: upper,
    step: increment,
    minDistance,
    disabled,
    reduced,
    onChange: handleChange,
    onCommit: handleCommit,
    format: formatAria,
    formatNumber,
  });

  const rangeSpan = Math.max(0.00001, upper - lower);
  const tickCount = Math.min(
    81,
    Math.max(11, Math.round(rangeSpan / increment) + 1),
  );
  const majorInterval = Math.max(1, Math.round(tickCount / 8));

  const ticks = React.useMemo(() => {
    return Array.from({ length: tickCount }, (_, i) => {
      const fraction = i / (tickCount - 1);
      const isMajor = i % majorInterval === 0 || i === tickCount - 1;
      return { fraction, isMajor, key: i };
    });
  }, [tickCount, majorInterval]);

  const lowerHint = React.useId();
  const upperHint = React.useId();

  const lowerPercent = Math.max(
    0,
    Math.min(100, ((safeVal[0] - lower) / rangeSpan) * 100),
  );
  const upperPercent = Math.max(
    0,
    Math.min(100, ((safeVal[1] - lower) / rangeSpan) * 100),
  );

  return (
    <div
      {...props}
      role="group"
      aria-label={label ?? "Range selector"}
      className={`relative flex w-full max-w-xl select-none flex-col text-foreground ${className}`}
    >
      {label && (
        <div className="mb-2 flex items-center justify-between text-[12px] font-medium text-muted-foreground">
          <span>{label}</span>
          <span className="font-mono text-[11px] tabular-nums text-muted-foreground/80">
            {formatNumber(safeVal[0])} — {formatNumber(safeVal[1])}
          </span>
        </div>
      )}

      {/* Floating Readout Badges (No heavy shadows, pure thin line borders) */}
      <div className="relative mb-3 h-7 w-full">
        {ruler.isMerged ? (
          <div className="absolute inset-x-0 flex items-center justify-center">
            <div className="inline-flex items-center gap-1 rounded-full border border-border bg-surface px-2.5 py-0.5 text-[11px] font-medium tabular-nums">
              <span
                ref={(el) => ruler.attachMergedReadout(el)}
                style={{ display: ruler.activeThumb ? "inline" : "none" }}
              >
                {formatNumber(safeVal[0])} – {formatNumber(safeVal[1])}
              </span>
              <span style={{ display: ruler.activeThumb ? "none" : "inline" }}>
                <NumberRoll value={safeVal[0]} duration={380} />
                <span className="mx-1 text-muted-foreground">–</span>
                <NumberRoll value={safeVal[1]} duration={380} />
                {unit && (
                  <span className="ml-1 text-muted-foreground">{unit}</span>
                )}
              </span>
            </div>
          </div>
        ) : (
          <div className="relative size-full">
            <div
              className="absolute -top-0.5 transition-[opacity,left] duration-200"
              style={{
                left: `${lowerPercent}%`,
                transform: "translate(-50%, 0)",
              }}
            >
              <div className="inline-flex items-center rounded-full border border-border bg-surface px-2 py-0.5 text-[10px] font-medium tabular-nums">
                <span
                  ref={(el) => ruler.attachLowerReadout(el)}
                  style={{ display: ruler.activeThumb ? "inline" : "none" }}
                >
                  {formatNumber(safeVal[0])}
                </span>
                <span
                  style={{ display: ruler.activeThumb ? "none" : "inline" }}
                >
                  <NumberRoll value={safeVal[0]} duration={380} />
                  {unit && (
                    <span className="ml-1 text-muted-foreground">{unit}</span>
                  )}
                </span>
              </div>
            </div>

            <div
              className="absolute -top-0.5 transition-[opacity,left] duration-200"
              style={{
                left: `${upperPercent}%`,
                transform: "translate(-50%, 0)",
              }}
            >
              <div className="inline-flex items-center rounded-full border border-border bg-surface px-2 py-0.5 text-[10px] font-medium tabular-nums">
                <span
                  ref={(el) => ruler.attachUpperReadout(el)}
                  style={{ display: ruler.activeThumb ? "inline" : "none" }}
                >
                  {formatNumber(safeVal[1])}
                </span>
                <span
                  style={{ display: ruler.activeThumb ? "none" : "inline" }}
                >
                  <NumberRoll value={safeVal[1]} duration={380} />
                  {unit && (
                    <span className="ml-1 text-muted-foreground">{unit}</span>
                  )}
                </span>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* The Track & Graduated thin line Ruler */}
      <div className="relative py-2">
        {/* SVG Graduated Ruler Ticks */}
        <div className="relative h-6 w-full" aria-hidden="true">
          <svg
            className="size-full overflow-visible text-border"
            preserveAspectRatio="none"
          >
            {/* Base thin line Axis */}
            <line
              x1="0"
              y1="23.5"
              x2="100%"
              y2="23.5"
              stroke="currentColor"
              strokeWidth="1"
            />
            {ticks.map((t) => (
              <line
                key={t.key}
                x1={`${t.fraction * 100}%`}
                y1={t.isMajor ? 8 : 15}
                x2={`${t.fraction * 100}%`}
                y2={23}
                stroke="currentColor"
                strokeWidth="1"
                className={
                  t.isMajor ? "text-muted-foreground/60" : "text-border/80"
                }
              />
            ))}
          </svg>
        </div>

        {/* Track gesture container (allows drag anywhere on track) */}
        <div
          ref={(el) => ruler.attachTrack(el)}
          {...ruler.trackHandlers}
          className="relative h-6 w-full cursor-ew-resize touch-none select-none"
        >
          {/* Active Highlight Band */}
          <div
            ref={(el) => ruler.attachHighlight(el)}
            aria-hidden="true"
            className="pointer-events-none absolute top-0 h-full rounded border-y border-primary/40 bg-primary/10"
            style={{
              left: `${lowerPercent}%`,
              width: `${Math.max(0, upperPercent - lowerPercent)}%`,
            }}
          />

          {/* Lower Needle Thumb */}
          <button
            ref={(el) => ruler.attachLowerThumb(el)}
            {...ruler.lowerHandlers}
            type="button"
            role="slider"
            disabled={disabled}
            aria-label={`Minimum ${label ?? "value"}`}
            aria-valuemin={lower}
            aria-valuemax={safeVal[1] - minDistance}
            aria-valuenow={safeVal[0]}
            aria-valuetext={formatAria(safeVal[0])}
            aria-describedby={lowerHint}
            className={`absolute -top-1 z-10 flex h-8 w-6 cursor-ew-resize items-center justify-center rounded-md border border-border bg-background touch-none select-none disabled:cursor-default disabled:opacity-40 will-change-[left] before:absolute before:-inset-x-3 before:-inset-y-2 before:content-[''] ${INTERACTION_FOCUS}`}
            style={{
              left: `${lowerPercent}%`,
              transform: "translate(-50%, 0)",
            }}
          >
            {/* 1px Vertical Needle */}
            <span className="h-5 w-px bg-primary" />
          </button>

          {/* Upper Needle Thumb */}
          <button
            ref={(el) => ruler.attachUpperThumb(el)}
            {...ruler.upperHandlers}
            type="button"
            role="slider"
            disabled={disabled}
            aria-label={`Maximum ${label ?? "value"}`}
            aria-valuemin={safeVal[0] + minDistance}
            aria-valuemax={upper}
            aria-valuenow={safeVal[1]}
            aria-valuetext={formatAria(safeVal[1])}
            aria-describedby={upperHint}
            className={`absolute -top-1 z-10 flex h-8 w-6 cursor-ew-resize items-center justify-center rounded-md border border-border bg-background touch-none select-none disabled:cursor-default disabled:opacity-40 will-change-[left] before:absolute before:-inset-x-3 before:-inset-y-2 before:content-[''] ${INTERACTION_FOCUS}`}
            style={{
              left: `${upperPercent}%`,
              transform: "translate(-50%, 0)",
            }}
          >
            {/* 1px Vertical Needle */}
            <span className="h-5 w-px bg-primary" />
          </button>
        </div>

        {/* Lower / Upper Bound Labels */}
        <div
          aria-hidden="true"
          className="mt-2 flex justify-between text-[10px] font-mono tabular-nums text-muted-foreground/70"
        >
          <span>{formatNumber(lower)}</span>
          <span>{formatNumber(upper)}</span>
        </div>
      </div>

      <p id={lowerHint} className="sr-only">
        Adjust minimum. Left arrow decreases, right arrow increases. Shift
        increases step by 10. Home sets to minimum, End to maximum.
      </p>
      <p id={upperHint} className="sr-only">
        Adjust maximum. Left arrow decreases, right arrow increases. Shift
        increases step by 10. Home sets to minimum, End to maximum.
      </p>
    </div>
  );
}

"use client";

/* ─────────────────────────────────────────────────────────
 * RATIO BALANCER: constrained multi-segment resource allocator
 *
 *   track      a single 1px thin line bar dividing 100% across
 *              segments; each segment expands or shrinks with
 *              flex-grow
 *   dividers   tactile thin line divider grips; delta-based drag
 *              ensures 1:1 finger tracking with zero initial
 *              jump on mobile and desktop
 *   numbers    percentage readouts roll in place via NumberRoll
 *              upon release; DOM text updates immediately while
 *              dragging
 *   touch      expanded 36px touch targets allow effortless finger
 *              dragging on phones
 *
 * Dividers are accessible separators with ArrowLeft/Right keys.
 * ───────────────────────────────────────────────────────── */

import * as React from "react";
import { NumberRoll } from "./number-roll";
import {
  INTERACTION_FOCUS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";
import {
  normalizeRatios,
  type RatioSegment,
  useRatioBalancer,
} from "./use-ratio-balancer";

export type { RatioSegment };

export interface RatioBalancerProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onChange"
> {
  label?: string;
  segments?: RatioSegment[];
  defaultSegments?: RatioSegment[];
  minRatio?: number;
  disabled?: boolean;
  onValueChange?: (ratios: number[]) => void;
  onValueCommit?: (ratios: number[]) => void;
}

const DEFAULT_SEGMENTS: RatioSegment[] = [
  { id: "inference", label: "Inference", ratio: 50 },
  { id: "training", label: "Training", ratio: 30 },
  { id: "cache", label: "Cache & KV", ratio: 20 },
];

const COLORS = [
  "bg-primary/10 text-primary border-primary/25",
  "bg-foreground/5 text-foreground border-foreground/15",
  "bg-muted text-muted-foreground border-border",
  "bg-accent text-accent-foreground border-border",
  "bg-primary/5 text-foreground border-primary/20",
];

export function RatioBalancer({
  label,
  segments: controlledSegments,
  defaultSegments = DEFAULT_SEGMENTS,
  minRatio = 5,
  disabled = false,
  onValueChange,
  onValueCommit,
  className = "",
  ...props
}: RatioBalancerProps) {
  const reduced = useInteractionReducedMotion();
  const [internalSegments, setInternalSegments] =
    React.useState<RatioSegment[]>(defaultSegments);
  const segments = controlledSegments ?? internalSegments;

  const currentRatios = React.useMemo(
    () => normalizeRatios(segments.map((s) => s.ratio)),
    [segments],
  );

  const handleChange = React.useCallback(
    (nextRatios: number[]) => {
      onValueChange?.(nextRatios);
    },
    [onValueChange],
  );

  const handleCommit = React.useCallback(
    (nextRatios: number[]) => {
      if (!controlledSegments) {
        setInternalSegments((prev) =>
          prev.map((seg, i) => ({
            ...seg,
            ratio: nextRatios[i] ?? seg.ratio,
          })),
        );
      }
      onValueCommit?.(nextRatios);
    },
    [controlledSegments, onValueCommit],
  );

  const balancer = useRatioBalancer({
    segments,
    minRatio,
    disabled,
    reduced,
    onChange: handleChange,
    onCommit: handleCommit,
  });

  return (
    <div
      {...props}
      role="region"
      aria-label={label ?? "Resource ratio balancer"}
      className={`relative flex w-full max-w-xl select-none flex-col text-foreground ${className}`}
    >
      {/* Label and Total */}
      {label && (
        <div className="mb-3 flex items-center justify-between text-[12px] font-medium text-muted-foreground">
          <span>{label}</span>
          <span className="font-mono text-[11px] tabular-nums text-muted-foreground/80">
            100% TOTAL
          </span>
        </div>
      )}

      {/* Main Bar Track (thin line borders only, zero heavy shadows) */}
      <div
        ref={(el) => balancer.attachTrack(el)}
        className="relative flex h-14 w-full overflow-hidden rounded-[14px] border border-border bg-surface p-1"
      >
        {segments.map((seg, i) => {
          const colorClass = COLORS[i % COLORS.length];
          const isLast = i === segments.length - 1;
          const ratio = currentRatios[i] ?? seg.ratio;

          return (
            <React.Fragment key={seg.id}>
              {/* Segment Cell */}
              <div
                ref={(el) => balancer.attachSegment(i, el)}
                className={`relative flex min-w-[42px] flex-col justify-between overflow-hidden rounded-[10px] border px-2.5 py-1.5 transition-[flex-grow] will-change-[flex-grow] ${colorClass}`}
                style={{ flexGrow: ratio }}
              >
                <div className="flex items-center justify-between">
                  <span className="truncate text-[11px] font-medium tracking-tight">
                    {seg.label}
                  </span>
                </div>

                <div className="flex items-baseline justify-between">
                  <span
                    ref={(el) => balancer.attachReadout(i, el)}
                    style={{
                      display:
                        balancer.activeDivider !== null ? "inline" : "none",
                    }}
                    className="font-mono text-[13px] font-medium tabular-nums"
                  >
                    {Math.round(ratio)}%
                  </span>
                  <span
                    style={{
                      display:
                        balancer.activeDivider !== null ? "none" : "inline",
                    }}
                    className="font-mono text-[13px] font-medium tabular-nums"
                  >
                    <NumberRoll
                      value={Math.round(ratio)}
                      suffix="%"
                      duration={380}
                    />
                  </span>
                </div>
              </div>

              {/* Divider Grip (Expanded 36px touch hit area for mobile fingers) */}
              {!isLast && (
                <div className="relative z-10 flex w-3 shrink-0 items-center justify-center">
                  <button
                    ref={(el) => balancer.attachDivider(i, el)}
                    {...balancer.getDividerProps(i)}
                    type="button"
                    role="separator"
                    disabled={disabled}
                    aria-orientation="vertical"
                    aria-label={`Adjust split between ${seg.label} and ${segments[i + 1]?.label}`}
                    style={{ touchAction: "none" }}
                    className={`group relative -inset-y-1 flex h-full w-3 cursor-ew-resize items-center justify-center touch-none select-none rounded before:absolute before:-inset-x-3.5 before:inset-y-0 before:content-[''] disabled:cursor-default disabled:opacity-40 ${INTERACTION_FOCUS}`}
                  >
                    <span className="h-6 w-0.5 rounded-full bg-border transition-colors group-hover:bg-primary group-focus-visible:bg-primary" />
                  </button>
                </div>
              )}
            </React.Fragment>
          );
        })}
      </div>

      {/* Legend & Breakdown */}
      <div className="mt-3 flex flex-wrap items-center justify-between gap-2 text-[11px] text-muted-foreground">
        <span className="flex items-center gap-1.5">
          <span className="size-1.5 rounded-full bg-primary" />
          <span>Drag dividers to reallocate percentages.</span>
        </span>
        <div className="flex items-center gap-3">
          {segments.map((seg) => (
            <span
              key={seg.id}
              className="flex items-center gap-1 font-mono text-[10px] tabular-nums"
            >
              <span>{seg.label}:</span>
              <span className="font-semibold text-foreground">
                {Math.round(currentRatios[segments.indexOf(seg)] ?? seg.ratio)}%
              </span>
            </span>
          ))}
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { Check, Gift } from "lucide-react";
import { CopyButton } from "./copy-button";
import { NumberRoll } from "./number-roll";
import { StatusButton, type ActionStatus } from "./status-button";
import { TagInput, type TagInputTag } from "./tag-input";
import { TextMorph } from "./text-morph";
import { useRowMotion } from "./use-row-motion";
import {
  EASE_THROW,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * REFERRAL: a reward that fills as your friends join
 *
 *   pass      the lit surface: what you give and get, your link
 *             with Copy, and a track of notches, one per friend
 *             the reward needs
 *   invite    emails become chips; Send invites goes Sending →
 *             Sent and the friends slide into the list as Invited
 *   joined    when a friend joins, their face lifts out of the
 *             list and flies up into the next notch, which lights;
 *             "Invited" morphs to "Joined" and the count rolls
 *   unlocked  the last notch lands and the notches close in on
 *             the middle and become the Claim button
 *
 * The programme is yours: pass the link and the friends (with
 * their status from your database), and do the work in onInvite
 * and onClaim. Throw an Error and its message shows in place.
 * ───────────────────────────────────────────────────────── */

export interface ReferralFriend {
  id: string;
  email: string;
  name?: string;
  status: "invited" | "joined";
}

export interface ReferralProps {
  /** Your personal invite link. */
  link: string;
  /** Newest first, from your database. */
  friends: ReferralFriend[];
  /** Friends who need to join for the reward. */
  goal: number;
  /** What you get, e.g. "a free month of Pro". */
  reward: string;
  /** What your friends get, e.g. "Friends get 20% off their first year". */
  offer?: string;
  claimed?: boolean;
  /** Send the invites; throw an Error to say why not (the chips stay). */
  onInvite?: (emails: string[]) => Promise<unknown>;
  /** Give the reward; resolve once it's on the account. */
  onClaim?: () => Promise<unknown>;
  className?: string;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SLOT = 34;
const NO_TAGS: TagInputTag[] = [];
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const mix = (color: string, amount: number, into = "transparent") =>
  `color-mix(in oklab, ${color} ${amount}%, ${into})`;
const PASS: React.CSSProperties = {
  backgroundColor: "var(--primary)",
  backgroundImage: `radial-gradient(120% 90% at 100% 0%, ${mix("var(--primary-foreground)", 22)} 0%, transparent 55%), linear-gradient(190deg, transparent 40%, ${mix("black", 24)} 100%)`,
  boxShadow: `inset 0 1px 0 ${mix("var(--primary-foreground)", 36)}, inset 0 0 0 1px ${mix("var(--primary-foreground)", 12)}`,
};
const CARD: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, var(--card), ${mix("var(--card)", 95, "var(--foreground)")})`,
  boxShadow: `0 0 0 1px var(--border), inset 0 1px 0 ${mix("var(--background)", 85)}`,
};
const LIT: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, ${mix("var(--primary-foreground)", 16)}, transparent 60%)`,
  boxShadow: `inset 0 1px 0 ${mix("var(--primary-foreground)", 32)}, inset 0 0 0 1px ${mix("black", 10)}`,
};

function tint(seed: string): React.CSSProperties {
  let h = 0;
  for (const c of seed) h = (h * 31 + c.charCodeAt(0)) >>> 0;
  const chart = `var(--chart-${(h % 5) + 1}, var(--primary))`;
  return {
    background: mix(chart, 20, "var(--card)"),
    color: mix(chart, 72, "var(--foreground)"),
    boxShadow: `inset 0 0 0 1px ${mix(chart, 26)}`,
  };
}

const nameOf = (f: ReferralFriend) => f.name ?? f.email.split("@")[0];
const initials = (f: ReferralFriend) =>
  (f.name ?? f.email.split("@")[0].replace(/[._-]+/g, " "))
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((w) => w[0]?.toUpperCase())
    .join("");

export function Referral({
  link,
  friends,
  goal,
  reward,
  offer,
  claimed: claimedProp,
  onInvite,
  onClaim,
  className = "",
}: ReferralProps) {
  const reduced = useInteractionReducedMotion();
  const baseId = React.useId();
  const [tags, setTags] = React.useState<TagInputTag[]>(NO_TAGS);
  const [invite, setInvite] = React.useState<{
    status: ActionStatus;
    error?: string;
  }>({ status: "idle" });
  const [claim, setClaim] = React.useState<{
    status: ActionStatus;
    error?: string;
  }>({ status: "idle" });
  const [said, setSaid] = React.useState("");
  // Friends whose faces are still flying up to the pass: their notch lights when they land.
  const [landing, setLanding] = React.useState<ReadonlySet<string>>(
    () => new Set(),
  );

  const sectionRef = React.useRef<HTMLElement>(null);
  const listRef = React.useRef<HTMLUListElement>(null);
  const ghostRef = React.useRef<HTMLDivElement>(null);
  const slotRefs = React.useRef<(HTMLSpanElement | null)[]>([]);

  // Someone just joined: hold their notch unlit while their face flies up to it (decided while rendering, so it never flashes lit).
  const [seen, setSeen] = React.useState(friends);
  if (friends !== seen) {
    const fresh = friends.filter(
      (f) =>
        f.status === "joined" &&
        seen.some((p) => p.id === f.id && p.status === "invited"),
    );
    setSeen(friends);
    if (fresh.length) {
      setSaid(`${fresh.map(nameOf).join(", ")} joined.`);
      if (!reduced)
        setLanding((s) => new Set([...s, ...fresh.map((f) => f.id)]));
    }
  }

  const joined = friends.filter((f) => f.status === "joined").reverse(); // oldest first, so notches fill in order
  const lit = joined.filter((f) => !landing.has(f.id));
  const done = lit.length >= goal;
  const claimed = claimedProp ?? claim.status === "success";
  const left = Math.max(0, goal - lit.length);

  const ranks = React.useMemo(
    () => new Map(friends.map((f, i) => [f.id, i])),
    [friends],
  );
  useRowMotion(listRef, { reduced, ranks, ghosts: ghostRef });

  // Their face lifts out of their row and flies up to their notch, which lights as it lands.
  const statuses = React.useRef(new Map(friends.map((f) => [f.id, f.status])));
  React.useLayoutEffect(() => {
    const before = statuses.current;
    statuses.current = new Map(friends.map((f) => [f.id, f.status]));
    const fresh = friends.filter(
      (f) => f.status === "joined" && before.get(f.id) === "invited",
    );
    if (!fresh.length || reduced) return;
    const section = sectionRef.current;
    const order = friends.filter((f) => f.status === "joined").reverse();
    const land = (id: string) =>
      setLanding((set) => {
        const next = new Set(set);
        next.delete(id);
        return next;
      });
    if (!section)
      return fresh.forEach((f) => requestAnimationFrame(() => land(f.id)));
    const box = section.getBoundingClientRect();
    // Screen px to the block's own px, so the face lands true inside a scaled or zoomed container too.
    const k = box.width / (section.offsetWidth || box.width) || 1;
    const flights: {
      id: string;
      from: DOMRect;
      to: DOMRect;
      f: ReferralFriend;
    }[] = [];
    for (const f of fresh) {
      const face = listRef.current?.querySelector<HTMLElement>(
        `[data-row-id="${f.id}"] [data-face]`,
      );
      const slot = slotRefs.current[order.indexOf(f)];
      if (face && slot)
        flights.push({
          id: f.id,
          from: face.getBoundingClientRect(),
          to: slot.getBoundingClientRect(),
          f,
        });
      else requestAnimationFrame(() => land(f.id));
    }
    flights.forEach(({ id, from, to, f }, i) => {
      const el = document.createElement("span");
      el.setAttribute("aria-hidden", "true");
      el.textContent = initials(f);
      Object.assign(el.style, tint(f.email), {
        position: "absolute",
        left: `${(from.left - box.left) / k}px`,
        top: `${(from.top - box.top) / k}px`,
        width: `${from.width / k}px`,
        height: `${from.height / k}px`,
        borderRadius: "999px",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontSize: "11px",
        fontWeight: "500",
        zIndex: "20",
        pointerEvents: "none",
        willChange: "transform",
      });
      section.appendChild(el);
      const dx = (to.left + to.width / 2 - (from.left + from.width / 2)) / k;
      const dy = (to.top + to.height / 2 - (from.top + from.height / 2)) / k;
      const s = to.width / from.width;
      const a = el.animate(
        [
          { transform: "translate(0,0) scale(1)", offset: 0 },
          {
            transform: `translate(${dx * 0.35}px, ${dy * 0.55 - 36}px) scale(${1.25})`,
            offset: 0.45,
          },
          { transform: `translate(${dx}px, ${dy}px) scale(${s})`, offset: 1 },
        ],
        {
          duration: 820,
          delay: 140 + i * 160,
          easing: "cubic-bezier(0.45,0,0.2,1)",
          fill: "forwards",
        },
      );
      a.onfinish = () => {
        land(id);
        el.animate([{ opacity: 1 }, { opacity: 0 }], {
          duration: 180,
          fill: "forwards",
        }).onfinish = () => el.remove();
      };
      a.oncancel = () => {
        land(id);
        el.remove();
      };
    });
  }, [friends, reduced]);

  const send = async () => {
    const emails = tags.filter((t) => !t.error).map((t) => t.value);
    if (!emails.length || invite.status === "pending") return;
    setInvite({ status: "pending" });
    try {
      await onInvite?.(emails);
      setInvite({ status: "success" });
      setTags(NO_TAGS);
      setSaid(
        `Invited ${emails.length === 1 ? emails[0] : `${emails.length} friends`}.`,
      );
    } catch (e) {
      setInvite({
        status: "error",
        error:
          e instanceof Error && e.message
            ? e.message
            : "Couldn’t send those invites.",
      });
    }
  };

  const claimNow = async () => {
    if (claim.status === "pending" || claimed) return;
    setClaim({ status: "pending" });
    try {
      await onClaim?.();
      setClaim({ status: "success" });
      setSaid(`Claimed ${reward}.`);
    } catch (e) {
      setClaim({
        status: "error",
        error:
          e instanceof Error && e.message
            ? e.message
            : "Couldn’t claim it. Try again.",
      });
    }
  };

  const good = tags.filter((t) => !t.error).length;
  const valid = good > 0;
  const invited = friends.length;

  return (
    <section
      ref={sectionRef}
      aria-labelledby={`${baseId}-title`}
      className={`relative w-full max-w-[420px] rounded-[28px] p-2 text-card-foreground ${className}`}
      style={CARD}
    >
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 420px)" }}
      />
      <div className="@container w-full">
        {/* The one lit surface: the pass, with a notch for every friend the reward needs. */}
        <div
          className="rounded-[22px] p-4 text-primary-foreground"
          style={PASS}
        >
          <div className="flex items-center justify-between gap-3 text-[12.5px]">
            <span className="inline-flex items-center gap-1.5 text-primary-foreground/75">
              <Gift aria-hidden="true" className="size-3.5" />
              Invite friends
            </span>
            <span className="tabular-nums text-primary-foreground/75">
              <NumberRoll
                value={Math.min(lit.length, goal)}
                duration={700}
                className="font-medium text-primary-foreground"
              />{" "}
              of {goal} joined
            </span>
          </div>
          <h2
            id={`${baseId}-title`}
            className="mt-2 text-[21px] font-medium leading-[1.15] tracking-[-0.03em]"
          >
            <TextMorph animateWidth={false}>
              {claimed
                ? "Reward claimed"
                : done
                  ? "You unlocked it"
                  : `${left} more ${left === 1 ? "friend" : "friends"}`}
            </TextMorph>
            <span className="block text-primary-foreground/70">
              {claimed ? `Enjoy ${reward}.` : `and you get ${reward}.`}
            </span>
          </h2>

          {/* The track: notches that light as friends join, then close in and become Claim. */}
          <div className="relative mt-4 grid h-[34px]">
            <div
              className="flex items-center [grid-area:1/1]"
              aria-hidden={done || undefined}
            >
              {Array.from({ length: goal }, (_, i) => {
                const f = lit[i];
                const on = Boolean(f);
                const center = (goal - 1) / 2;
                return (
                  <React.Fragment key={i}>
                    {i > 0 && (
                      <span
                        className="h-px flex-1"
                        style={{
                          background: lit[i]
                            ? "var(--primary-foreground)"
                            : mix("var(--primary-foreground)", 26),
                          opacity: done ? 0 : 1,
                          transition: reduced
                            ? "none"
                            : `background-color 300ms, opacity 240ms ${EASE}`,
                        }}
                      />
                    )}
                    <span
                      ref={(el) => {
                        slotRefs.current[i] = el;
                      }}
                      className="relative flex shrink-0 items-center justify-center rounded-full text-[11px] font-medium"
                      style={{
                        width: SLOT,
                        height: SLOT,
                        color: "var(--primary)",
                        background: on
                          ? "var(--primary-foreground)"
                          : "transparent",
                        boxShadow: on
                          ? `0 0 0 3px ${mix("var(--primary-foreground)", 20)}`
                          : `inset 0 0 0 1px ${mix("var(--primary-foreground)", 40)}`,
                        opacity: done ? 0 : 1,
                        transform:
                          done && !reduced
                            ? `translateX(calc(${center - i} * (100cqw - ${48 + SLOT}px) / ${Math.max(1, goal - 1)} * 0.9)) scale(0.6)`
                            : "none",
                        transition: reduced
                          ? "opacity 160ms"
                          : `background-color 260ms ${EASE}, box-shadow 420ms ${EASE_THROW}, transform 520ms ${EASE} ${i * 30}ms, opacity 360ms ${EASE} ${120 + i * 30}ms`,
                      }}
                    >
                      {on ? (
                        initials(f)
                      ) : (
                        <span
                          className="text-[14px] leading-none"
                          style={{
                            color: mix("var(--primary-foreground)", 55),
                          }}
                        >
                          +
                        </span>
                      )}
                    </span>
                  </React.Fragment>
                );
              })}
            </div>
            <div
              className="[grid-area:1/1]"
              inert={!done || undefined}
              style={{
                clipPath: done
                  ? "inset(0 0 round 999px)"
                  : `inset(0 calc(50% - ${SLOT / 2}px) round 999px)`,
                opacity: done ? 1 : 0,
                transition: reduced
                  ? "opacity 160ms"
                  : `clip-path 560ms ${EASE} 180ms, opacity 200ms ${EASE} ${done ? 180 : 0}ms`,
              }}
            >
              <StatusButton
                status={claimed ? "success" : claim.status}
                labels={{
                  idle: `Claim ${reward}`,
                  pending: "Claiming",
                  success: "Claimed",
                  error: "Try again",
                }}
                icon={<Gift aria-hidden="true" />}
                onClick={() => void claimNow()}
                className="h-[34px] w-full text-[13.5px] hover:opacity-95"
                style={
                  claim.status === "error"
                    ? { background: "var(--primary-foreground)" }
                    : {
                        background: "var(--primary-foreground)",
                        color: "var(--primary)",
                      }
                }
              />
            </div>
          </div>
          {claim.error && (
            <p
              role="alert"
              className="mt-2 text-[12px] text-primary-foreground/85"
            >
              {claim.error}
            </p>
          )}

          {/* Your link, inset into the pass. */}
          <div
            className="mt-4 flex h-10 items-center gap-2 rounded-full pl-4 pr-1"
            style={{
              background: mix("black", 14),
              boxShadow: `inset 0 1px 0 ${mix("black", 12)}, inset 0 0 0 1px ${mix("var(--primary-foreground)", 10)}`,
            }}
          >
            <span className="min-w-0 flex-1 truncate font-mono text-[12.5px] text-primary-foreground/90">
              {link.replace(/^https?:\/\//, "")}
            </span>
            <CopyButton
              text={link}
              label="Copy link"
              copiedLabel="Copied"
              showLabel
              size="sm"
              variant="secondary"
              style={{
                background: "var(--primary-foreground)",
                color: "var(--primary)",
              }}
              className="shrink-0 hover:opacity-90"
            />
          </div>
          {offer && (
            <p className="mt-2 px-1 text-[12px] text-primary-foreground/65">
              {offer}
            </p>
          )}
        </div>

        {/* Flat: invite by email, then the people you've asked. */}
        <form
          className="px-2 pt-3"
          onSubmit={(e) => {
            e.preventDefault();
            void send();
          }}
        >
          <TagInput
            value={tags}
            onValueChange={(next) => {
              setTags(next);
              if (invite.status !== "idle" && invite.status !== "pending")
                setInvite({ status: "idle" });
            }}
            label="Invite by email"
            placeholder="friend@company.com"
            separators={/[\s,;]+/}
            normalize={(v) => v.toLowerCase()}
            validate={(v) =>
              !EMAIL.test(v)
                ? `“${v}” isn’t an email address`
                : friends.some((f) => f.email.toLowerCase() === v)
                  ? `${v} is already invited`
                  : null
            }
            disabled={invite.status === "pending"}
          />
          <div className="mt-2 flex items-center justify-between gap-3">
            <p
              role={invite.error ? "alert" : undefined}
              className={`min-w-0 text-[12px] ${invite.error ? "text-red-600 dark:text-red-400" : "text-muted-foreground"}`}
            >
              {invite.error ?? "Paste a list, or press Enter after each."}
            </p>
            <StatusButton
              type="submit"
              status={invite.status}
              labels={{
                idle: good > 1 ? `Send ${good} invites` : "Send invite",
                pending: "Sending",
                success: "Sent",
                error: "Try again",
              }}
              onReset={() => setInvite({ status: "idle" })}
              resetAfter={1600}
              disabled={!valid && invite.status === "idle"}
              className="h-9 shrink-0 px-4 text-[13px] disabled:opacity-45"
              style={invite.status === "error" ? undefined : LIT}
            />
          </div>
        </form>

        {invited > 0 && (
          <div className="px-2 pb-1 pt-3">
            <div className="flex items-baseline justify-between px-1 text-[12px] text-muted-foreground">
              <span>Invited</span>
              <span className="tabular-nums">
                <NumberRoll value={invited} duration={600} />
              </span>
            </div>
            <div className="relative mt-1">
              <div
                ref={ghostRef}
                aria-hidden="true"
                className="pointer-events-none absolute inset-0"
              />
              <ul ref={listRef} className="relative">
                {friends.map((f) => {
                  const isIn = f.status === "joined";
                  return (
                    <li
                      key={f.id}
                      data-row-id={f.id}
                      className="flex h-11 items-center gap-2.5 border-t border-border/70 px-1 first:border-t-0"
                    >
                      <span
                        data-face
                        aria-hidden="true"
                        className="flex size-7 shrink-0 items-center justify-center rounded-full text-[11px] font-medium"
                        style={{
                          ...tint(f.email),
                          opacity: landing.has(f.id) ? 0.35 : 1,
                          transition: "opacity 200ms",
                        }}
                      >
                        {initials(f)}
                      </span>
                      <span className="min-w-0 flex-1 truncate text-[13.5px]">
                        {f.name ? (
                          <>
                            {f.name}{" "}
                            <span className="text-muted-foreground">
                              {f.email}
                            </span>
                          </>
                        ) : (
                          f.email
                        )}
                      </span>
                      <span
                        className={`inline-flex shrink-0 items-center gap-1 text-[12px] ${isIn ? "font-medium text-emerald-600 dark:text-emerald-400" : "text-muted-foreground"}`}
                        style={{ transition: "color 300ms" }}
                      >
                        <span
                          className="grid"
                          style={{
                            gridTemplateColumns: isIn ? "1fr" : "0fr",
                            transition: reduced
                              ? "none"
                              : `grid-template-columns 320ms ${EASE}`,
                          }}
                        >
                          <span className="min-w-0 overflow-hidden">
                            <Check
                              aria-hidden="true"
                              className="size-3.5"
                              strokeWidth={2.5}
                            />
                          </span>
                        </span>
                        <TextMorph>{isIn ? "Joined" : "Invited"}</TextMorph>
                      </span>
                    </li>
                  );
                })}
              </ul>
            </div>
          </div>
        )}

        <span className="sr-only" role="status">
          {said}
        </span>
      </div>
    </section>
  );
}

