"use client";

import * as React from "react";
import { ChevronLeft, ChevronRight, RotateCcw } from "lucide-react";
import { NumberRoll } from "./number-roll";

/* ─────────────────────────────────────────────────────────
 * RESPONSE VERSIONS: "2 / 3" between regenerated answers
 *
 *   browsing      the arrows step between versions: the answer
 *                 you leave slides out one way through a blur, the
 *                 next comes in from the other side, the height
 *                 eases between them and "2 / 3" rolls
 *   regenerating  the regenerate arrow blurs into a spinner until
 *                 the new version arrives; the count rolls up
 *
 * Wrap the current version's content.
 * ───────────────────────────────────────────────────────── */

export interface ResponseVersionsProps extends React.HTMLAttributes<HTMLDivElement> {
  count: number;
  /** Zero-based index of the version shown. */
  index: number;
  onIndexChange: (index: number) => void;
  onRegenerate?: () => void;
  regenerating?: boolean;
  /** The current version's content. */
  children: React.ReactNode;
}

type Leaving = { key: string; node: React.ReactNode; dir: number };

const MORPH = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const ICON = `cursor-pointer disabled:cursor-default relative flex size-7 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-accent hover:text-foreground disabled:pointer-events-none disabled:opacity-35 ${FOCUS}`;

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Icons trade places through a blur: the old one shrinks away as the new one grows in. */
const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 260ms ${MORPH}, transform 380ms ${MORPH}, filter 260ms ${MORPH}`,
});

/** The version you stepped away from: it leaves toward the side you came from, then removes itself. */
function LeavingPane({
  item,
  onDone,
}: {
  item: Leaving;
  onDone: (key: string) => void;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        {
          opacity: 0,
          filter: "blur(6px)",
          transform: `translateX(${-item.dir * 24}px)`,
        },
      ],
      { duration: 260, easing: MORPH, fill: "forwards" },
    );
    animation.onfinish = () => onDone(item.key);
    return () => animation.cancel();
  }, [item, onDone]);
  return (
    <div
      ref={ref}
      inert
      aria-hidden="true"
      className="pointer-events-none absolute inset-x-0 top-0"
    >
      {item.node}
    </div>
  );
}

export function ResponseVersions({
  count,
  index,
  onIndexChange,
  onRegenerate,
  regenerating = false,
  children,
  className = "",
  ...props
}: ResponseVersionsProps) {
  const reduced = useReducedMotion();
  const boxRef = React.useRef<HTMLDivElement>(null);
  const paneRef = React.useRef<HTMLDivElement>(null);
  const latest = React.useRef<React.ReactNode>(children);
  const fromHeight = React.useRef<number | null>(null);

  // A step: what was showing (as it last rendered) leaves, and the new version comes in from the side you stepped toward.
  const [shown, setShown] = React.useState({ index, step: 0 });
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const [dir, setDir] = React.useState(0);
  if (shown.index !== index) {
    // Keep the visible height before React replaces the pane, including a
    // partially completed resize. A cached natural height jumps on reversal.
    fromHeight.current = boxRef.current?.getBoundingClientRect().height ?? null;
    const d = index > shown.index ? 1 : -1;
    setShown({ index, step: shown.step + 1 });
    setDir(reduced ? 0 : d);
    if (!reduced)
      setLeaving((l) => [
        ...l,
        // A repeated route can still have a pane leaving; each step needs its own key.
        { key: `${shown.step}`, node: latest.current, dir: d },
      ]);
    else if (leaving.length) setLeaving([]);
  }
  const done = React.useCallback(
    (key: string) => setLeaving((l) => l.filter((x) => x.key !== key)),
    [],
  );

  React.useLayoutEffect(() => {
    if (reduced) {
      setLeaving([]);
      setDir(0);
    }
  }, [reduced]);

  React.useLayoutEffect(() => {
    const from = fromHeight.current;
    fromHeight.current = null;
    if (!dir || reduced) return;
    const pane = paneRef.current;
    const box = boxRef.current;
    const enter = pane?.animate(
      [
        {
          opacity: 0,
          filter: "blur(6px)",
          transform: `translateX(${dir * 24}px)`,
        },
        { opacity: 1, filter: "blur(0px)", transform: "none" },
      ],
      { duration: 420, easing: MORPH, delay: 60, fill: "backwards" },
    );
    // The box eases from the old answer's height to the new one's.
    let resize: Animation | undefined;
    const to = box?.getBoundingClientRect().height;
    if (box && from !== null && to !== undefined && Math.abs(to - from) > 0.1) {
      box.style.overflow = "hidden";
      resize = box.animate([{ height: `${from}px` }, { height: `${to}px` }], {
        duration: 420,
        easing: MORPH,
      });
      resize.onfinish = () => {
        box.style.overflow = "";
      };
    }
    return () => {
      enter?.cancel();
      resize?.cancel();
      // Restore synchronously: an old cancellation event must not clear the
      // overflow protection of the next transition.
      if (resize && box) box.style.overflow = "";
    };
  }, [index, dir, reduced]);

  // Remember what this render showed, including streamed content, for the next step.
  React.useLayoutEffect(() => {
    latest.current = children;
  });

  return (
    <div className={className} {...props}>
      <div
        ref={boxRef}
        className={`relative ${!reduced && leaving.length ? "overflow-hidden" : ""}`}
      >
        {!reduced &&
          leaving.map((l) => (
            <LeavingPane key={l.key} item={l} onDone={done} />
          ))}
        <div key={index} ref={paneRef}>
          {children}
        </div>
      </div>

      <div className="mt-3 flex items-center gap-1">
        <button
          type="button"
          aria-label="Previous version"
          disabled={index <= 0}
          onClick={() => onIndexChange(index - 1)}
          className={ICON}
        >
          <ChevronLeft className="size-4" />
        </button>
        <span
          aria-live="polite"
          className="flex min-w-[3.25rem] justify-center gap-[0.5ch] font-mono text-[11.5px] tabular-nums text-muted-foreground"
        >
          <span className="sr-only">Version </span>
          <NumberRoll value={index + 1} duration={600} />
          <span aria-hidden="true">/</span>
          <span className="sr-only">of</span>
          <NumberRoll value={count} duration={600} />
        </span>
        <button
          type="button"
          aria-label="Next version"
          disabled={index >= count - 1}
          onClick={() => onIndexChange(index + 1)}
          className={ICON}
        >
          <ChevronRight className="size-4" />
        </button>
        {onRegenerate && (
          <button
            type="button"
            aria-label={regenerating ? "Regenerating" : "Regenerate"}
            disabled={regenerating}
            onClick={onRegenerate}
            className={`cursor-pointer disabled:cursor-default ${ICON} ml-1`}
          >
            <span
              aria-hidden="true"
              className="absolute inset-0 flex items-center justify-center"
              style={swap(!regenerating, reduced)}
            >
              <RotateCcw className="size-3.5" />
            </span>
            <span
              aria-hidden="true"
              className="absolute inset-0 flex items-center justify-center"
              style={swap(regenerating, reduced)}
            >
              <span
                className={`size-3.5 rounded-full border-[1.5px] border-border border-t-foreground/70 motion-reduce:animate-none ${regenerating ? "animate-spin" : ""}`}
              />
            </span>
          </button>
        )}
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * REVENUE CHART: this year as an area, last year behind it
 *
 *   arrive    the first time it's on screen the chart draws
 *             itself from left to right and the total rolls up
 *             from zero
 *   hover     a thin line follows the pointer from month to month
 *             with a dot on each line, and the header becomes the
 *             readout: the title morphs to "Revenue in August",
 *             the total rolls to that month, the chip and the
 *             last-year line follow
 *   metric    Revenue, Orders, Average order: the pill is thrown
 *             to the choice and both lines morph into their new
 *             shapes while the scale's labels and the figures roll
 *   partial   a year still under way ends its line with a dot at
 *             the latest month
 *
 * The plot is one tab stop: arrow keys move between months and
 * the readout is announced. Every figure is also in a table for
 * screen readers.
 * ───────────────────────────────────────────────────────── */

export interface RevenueMetric {
  id: string;
  /** In the switch and the title, e.g. "Revenue". */
  label: string;
  /** This year, one value per label; may stop early for a year still under way. */
  current: number[];
  /** Last year, one value per label. */
  previous?: number[];
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  /** How the headline adds the months up. */
  total?: "sum" | "average";
}

export interface RevenueChartProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onChange"
> {
  /** Along the bottom, e.g. ["Jan", "Feb", …]. */
  labels: string[];
  /** In the readout, e.g. ["January", …]. Defaults to labels. */
  titles?: string[];
  /** One or more; more than one shows a switch. */
  metrics: RevenueMetric[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (id: string) => void;
  /** The two lines' names, for the legend and the readout. */
  series?: [string, string];
  locales?: string | string[];
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const PLOT = 200;
const TOP = 10; // room above the highest point
const LABELS = 24;
const PAD = 6;
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const LINE = "var(--chart-1, var(--primary))";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const STEPS = 4; // gridlines above the baseline

/** A top for the scale that divides into four round steps: 20,600 → 24,000 (6K a step). */
function niceTop(value: number) {
  if (value <= 0) return STEPS;
  const raw = value / STEPS;
  const mag = 10 ** Math.floor(Math.log10(raw));
  const step =
    [1, 1.5, 2, 2.5, 3, 4, 5, 6, 8, 10]
      .map((m) => m * mag)
      .find((s) => s >= raw) ?? 10 * mag;
  return step * STEPS;
}

/** A smooth line through the points that never overshoots them (monotone cubic, as in d3's curveMonotoneX). */
function monotone(points: [number, number][]) {
  const n = points.length;
  if (!n) return "";
  if (n === 1) return `M${points[0][0]},${points[0][1]}`;
  const m: number[] = [];
  for (let i = 0; i < n - 1; i++)
    m.push(
      (points[i + 1][1] - points[i][1]) /
        (points[i + 1][0] - points[i][0] || 1),
    );
  const t: number[] = [m[0]];
  for (let i = 1; i < n - 1; i++)
    t.push(m[i - 1] * m[i] <= 0 ? 0 : (m[i - 1] + m[i]) / 2);
  t.push(m[n - 2]);
  for (let i = 0; i < n - 1; i++) {
    if (m[i] === 0) {
      t[i] = 0;
      t[i + 1] = 0;
      continue;
    }
    const a = t[i] / m[i];
    const b = t[i + 1] / m[i];
    const s = a * a + b * b;
    if (s > 9) {
      const k = 3 / Math.sqrt(s);
      t[i] = k * a * m[i];
      t[i + 1] = k * b * m[i];
    }
  }
  const r = (v: number) => Math.round(v * 100) / 100;
  let d = `M${r(points[0][0])},${r(points[0][1])}`;
  for (let i = 0; i < n - 1; i++) {
    const [x0, y0] = points[i];
    const [x1, y1] = points[i + 1];
    const dx = (x1 - x0) / 3;
    d += `C${r(x0 + dx)},${r(y0 + t[i] * dx)} ${r(x1 - dx)},${r(y1 - t[i + 1] * dx)} ${r(x1)},${r(y1)}`;
  }
  return d;
}

/** Tweens a list of numbers toward a target, so a new metric reshapes the line instead of replacing it. */
function useTween(target: number[], reduced: boolean, duration = 640) {
  const [value, setValue] = React.useState(target);
  const from = React.useRef(target);
  const targetRef = React.useRef(target);
  React.useLayoutEffect(() => {
    targetRef.current = target;
  });

  const targetKey = target.join(",");

  React.useEffect(() => {
    from.current = reduced ? target : value;
  });

  React.useEffect(() => {
    if (reduced) return;
    const start = from.current;
    const begin = performance.now();
    let frame = 0;
    const step = (now: number) => {
      const currentTarget = targetRef.current;
      const t = Math.min(1, (now - begin) / duration);
      const e = 1 - Math.pow(1 - t, 4);
      const next = currentTarget.map(
        (v, i) =>
          (start[i] ?? start[start.length - 1] ?? 0) +
          (v - (start[i] ?? start[start.length - 1] ?? 0)) * e,
      );
      from.current = next;
      setValue(next);
      if (t < 1) frame = requestAnimationFrame(step);
    };
    frame = requestAnimationFrame(step);
    return () => cancelAnimationFrame(frame);
  }, [targetKey, reduced, duration]);

  return reduced ? target : value;
}

export function RevenueChart({
  labels,
  titles,
  metrics,
  value,
  defaultValue,
  onValueChange,
  series = ["This year", "Last year"],
  locales,
  className = "",
  ...props
}: RevenueChartProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const [own, setOwn] = React.useState(defaultValue ?? metrics[0]?.id);
  const metricId = value ?? own;
  const metric = metrics.find((m) => m.id === metricId) ?? metrics[0];
  const current = metric?.current ?? [];
  const previous = metric?.previous ?? [];
  const format = metric?.format;

  const [visible, setVisible] = React.useState(false);
  const [plotH, setPlotH] = React.useState(PLOT);
  const [active, setActive] = React.useState<number | null>(null);
  const [keyboard, setKeyboard] = React.useState(false);
  const [width, setWidth] = React.useState(0);
  const [pill, setPill] = React.useState({ left: 0, width: 0, ready: false });
  const rootRef = React.useRef<HTMLDivElement>(null);
  const chartRef = React.useRef<HTMLDivElement>(null);
  const plotRef = React.useRef<HTMLDivElement>(null);
  const chipRefs = React.useRef<(HTMLButtonElement | null)[]>([]);

  const max = niceTop(Math.max(0, ...current, ...previous));
  const drawnMax = useTween([max], reduced)[0];
  const cur = useTween(current, reduced);
  const prev = useTween(previous, reduced);

  // The plot's height is set by the card's width in CSS; read it so the drawing fits.
  React.useLayoutEffect(() => {
    const el = chartRef.current;
    if (!el) return;
    const measure = () =>
      setPlotH((h) => {
        const next = el.offsetHeight - LABELS;
        return next > 0 && next !== h ? next : h;
      });
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  React.useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          observer.disconnect();
        }
      },
      { rootMargin: "0px 0px -10% 0px" },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  React.useLayoutEffect(() => {
    const el = plotRef.current;
    if (!el) return;
    const measure = () =>
      setWidth((w) => (w === el.offsetWidth ? w : el.offsetWidth));
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  React.useLayoutEffect(() => {
    const el = chipRefs.current[metrics.findIndex((m) => m.id === metricId)];
    if (!el) return;
    setPill((p) =>
      p.left === el.offsetLeft && p.width === el.offsetWidth
        ? p
        : { left: el.offsetLeft, width: el.offsetWidth, ready: p.width > 0 },
    );
  }, [metricId, metrics]);

  const n = labels.length;
  const x = (i: number) =>
    PAD + (n > 1 ? (i * (width - PAD * 2)) / (n - 1) : (width - PAD * 2) / 2);
  const y = (v: number) => TOP + (plotH - TOP) * (1 - v / (drawnMax || 1));
  const curPoints = cur.map((v, i) => [x(i), y(v)] as [number, number]);
  const prevPoints = prev.map((v, i) => [x(i), y(v)] as [number, number]);
  const curLine = width ? monotone(curPoints) : "";
  const prevLine = width ? monotone(prevPoints) : "";
  const area =
    curLine && curPoints.length > 1
      ? `${curLine}L${curPoints[curPoints.length - 1][0]},${plotH}L${curPoints[0][0]},${plotH}Z`
      : "";

  const add = (list: number[]) =>
    metric?.total === "average"
      ? list.length
        ? list.reduce((s, v) => s + v, 0) / list.length
        : 0
      : list.reduce((s, v) => s + v, 0);
  const lastIndex = current.length - 1;
  // Last year over the same months as this year, so a year under way compares like with like.
  const prevSame = previous.slice(0, current.length);
  const headline = active !== null ? (current[active] ?? 0) : add(current);
  const before =
    active !== null
      ? previous[active]
      : prevSame.length
        ? add(prevSame)
        : undefined;
  const change = before ? (headline - before) / before : null;
  const [lastChange, setLastChange] = React.useState(change ?? 0);
  if (change !== null && change !== lastChange) setLastChange(change);
  const up = (change ?? lastChange) >= 0;
  const fmt = (v: number) => new Intl.NumberFormat(locales, format).format(v);
  const monthName = (i: number) => titles?.[i] ?? labels[i];
  // "last year" reads as words; "2025" reads as "in 2025".
  const then = (label: string) =>
    /^\d/.test(label) ? `in ${label}` : label.toLowerCase();
  const compact = {
    ...format,
    notation: "compact" as const,
    minimumFractionDigits: 0,
    maximumFractionDigits: 1,
  };
  const every = width && n ? Math.max(1, Math.ceil(34 / (width / n))) : 1;
  // Labels thin out on narrow screens; the hovered one always shows, and its close neighbours step aside for it.
  const label = (i: number) =>
    active === i ||
    ((n - 1 - i) % every === 0 &&
      (active === null || every === 1 || Math.abs(i - active) >= every));

  const choose = (next: string) => {
    if (next === metricId) return;
    if (value === undefined) setOwn(next);
    onValueChange?.(next);
  };
  const pointAt = (clientX: number) => {
    const r = plotRef.current?.getBoundingClientRect();
    if (!r || !current.length || n < 2) return null;
    const i = Math.round(
      ((clientX - r.left - PAD) / (r.width - PAD * 2)) * (n - 1),
    );
    return Math.min(lastIndex, Math.max(0, i));
  };
  const onKeyDown = (e: React.KeyboardEvent) => {
    if (!current.length) return;
    const from = active ?? lastIndex;
    const moves: Record<string, number> = {
      ArrowLeft: from - 1,
      ArrowRight: from + 1,
      Home: 0,
      End: lastIndex,
    };
    if (e.key === "Escape") return setActive(null);
    if (!(e.key in moves)) return;
    e.preventDefault();
    setKeyboard(true);
    setActive(
      Math.min(lastIndex, Math.max(0, active === null ? from : moves[e.key])),
    );
  };

  const dot = (
    i: number | null,
    values: number[],
    color: string,
    key: string,
  ) => {
    const on = i !== null && values[i] !== undefined;
    const v = on ? values[i] : (values[values.length - 1] ?? 0);
    return (
      <span
        key={key}
        aria-hidden="true"
        className="pointer-events-none absolute size-2.5 -translate-x-1/2 -translate-y-1/2 rounded-full shadow-[0_0_0_2px_var(--background)]"
        style={{
          left: x(on ? (i as number) : Math.max(0, values.length - 1)),
          top: y(v),
          background: color,
          opacity: on ? 1 : 0,
          scale: on ? "1" : "0.4",
          transition: reduced
            ? "none"
            : `left 260ms ${THROW}, top 260ms ${THROW}, opacity 200ms ${EASE}, scale 260ms ${EASE}`,
        }}
      />
    );
  };

  return (
    <div
      ref={rootRef}
      className={`@container w-full rounded-[22px] bg-background shadow-[0_0_0_1px_var(--border)] ${className}`}
      {...props}
    >
      <div className="p-4 @md:p-5 [--gutter:30px] @md:[--gutter:40px] [--plot:160px] @md:[--plot:200px]">
        <div className="flex flex-wrap items-start justify-between gap-x-4 gap-y-3">
          <div className="min-w-0">
            <p className="text-[12px] text-muted-foreground @md:text-[13px]">
              <TextMorph>
                {active !== null
                  ? `${metric?.label} in ${monthName(active)}`
                  : (metric?.label ?? "")}
              </TextMorph>
            </p>
            <p className="mt-1 flex flex-wrap items-center gap-x-2.5 gap-y-1">
              <span className="text-[22px] font-medium leading-tight tracking-[-0.03em] @md:text-[26px] text-foreground">
                <NumberRoll
                  value={visible ? headline : 0}
                  format={format}
                  locales={locales}
                  duration={active !== null ? 600 : 1000}
                />
              </span>
              <span
                className="grid"
                style={{
                  gridTemplateColumns: change !== null ? "1fr" : "0fr",
                  opacity: change !== null ? 1 : 0,
                  transition: reduced
                    ? "none"
                    : `grid-template-columns 380ms ${EASE}, opacity 240ms ${EASE}`,
                }}
              >
                <span className="min-w-0 [clip-path:inset(-4px_-2px)]">
                  <span
                    className={`inline-flex items-center gap-1 whitespace-nowrap rounded-full px-1.5 py-px text-[12.5px] font-medium transition-colors duration-300 ${
                      up
                        ? "bg-emerald-500/10 text-emerald-600"
                        : "bg-red-500/10 text-red-600 dark:text-red-400"
                    }`}
                  >
                    <svg
                      viewBox="0 0 12 12"
                      aria-hidden="true"
                      className="size-3"
                      style={{
                        transform: up ? "none" : "rotate(180deg)",
                        transition: reduced
                          ? "none"
                          : `transform 420ms ${THROW}`,
                      }}
                    >
                      <path
                        d="M6 9.5V2.5M2.8 5.6 6 2.5l3.2 3.1"
                        fill="none"
                        stroke="currentColor"
                        strokeWidth="1.5"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                      />
                    </svg>
                    <NumberRoll
                      value={visible ? Math.abs(change ?? lastChange) : 0}
                      format={{ style: "percent", maximumFractionDigits: 1 }}
                      duration={700}
                    />
                  </span>
                </span>
              </span>
            </p>
            {before !== undefined && (
              <p className="mt-1 flex items-baseline gap-[0.3em] whitespace-nowrap text-[11.5px] text-muted-foreground @md:text-[12.5px]">
                <NumberRoll
                  value={visible ? before : 0}
                  format={format}
                  locales={locales}
                  duration={700}
                />
                <TextMorph>
                  {active !== null
                    ? `in ${monthName(active)} ${/^\d/.test(series[1]) ? series[1] : series[1].toLowerCase()}`
                    : then(series[1])}
                </TextMorph>
              </p>
            )}
          </div>

          {metrics.length > 1 && (
            <div
              role="radiogroup"
              aria-label="Measure"
              className="relative inline-flex shrink-0 rounded-full bg-muted p-0.5"
            >
              <span
                aria-hidden="true"
                className="absolute inset-y-0.5 left-0 rounded-full bg-background shadow-[0_0_0_1px_var(--border)]"
                style={{
                  width: pill.width,
                  transform: `translateX(${pill.left}px)`,
                  transition:
                    pill.ready && !reduced
                      ? `transform 460ms ${THROW}, width 380ms ${EASE}`
                      : "none",
                }}
              />
              {metrics.map((m, i) => {
                const selected = m.id === metricId;
                return (
                  <button
                    key={m.id}
                    ref={(el) => {
                      chipRefs.current[i] = el;
                    }}
                    type="button"
                    role="radio"
                    aria-checked={selected}
                    tabIndex={selected ? 0 : -1}
                    onClick={() => choose(m.id)}
                    onKeyDown={(e) => {
                      if (e.key !== "ArrowRight" && e.key !== "ArrowLeft")
                        return;
                      e.preventDefault();
                      const next =
                        (i +
                          (e.key === "ArrowRight" ? 1 : -1) +
                          metrics.length) %
                        metrics.length;
                      choose(metrics[next].id);
                      chipRefs.current[next]?.focus();
                    }}
                    className={`cursor-pointer relative h-6 whitespace-nowrap rounded-full px-2.5 text-[11.5px] font-medium @md:h-7 @md:px-3 @md:text-[12.5px] transition-colors duration-300 ${FOCUS} ${
                      selected
                        ? "text-foreground"
                        : "text-muted-foreground hover:text-foreground"
                    }`}
                  >
                    {m.label}
                  </button>
                );
              })}
            </div>
          )}
        </div>

        {/* The legend: a line key for each, so the two never rely on colour alone. */}
        <div className="mt-3 flex items-center gap-4 text-[11.5px] text-muted-foreground @md:mt-4 @md:text-[12px]">
          <span className="flex items-center gap-1.5">
            <span
              aria-hidden="true"
              className="h-0.5 w-3.5 rounded-full"
              style={{ background: LINE }}
            />
            {series[0]}
          </span>
          {previous.length > 0 && (
            <span className="flex items-center gap-1.5">
              <svg
                aria-hidden="true"
                width="14"
                height="2"
                className="text-foreground/35"
              >
                <line
                  x1="1"
                  y1="1"
                  x2="13"
                  y2="1"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeDasharray="3 3"
                  strokeLinecap="round"
                />
              </svg>
              {series[1]}
            </span>
          )}
        </div>

        <div
          ref={chartRef}
          className="relative mt-3"
          style={{ height: `calc(var(--plot) + ${LABELS}px)` }}
        >
          {/* The scale: rolling labels in the gutter and solid fine lines. */}
          {Array.from({ length: STEPS + 1 }, (_, k) => 1 - k / STEPS).map(
            (f) => (
              <div
                key={f}
                aria-hidden="true"
                className="absolute inset-x-0"
                style={{ top: TOP + (plotH - TOP) * (1 - f) }}
              >
                <span
                  className="absolute left-0 top-0 -translate-y-1/2 text-[10px] leading-none tabular-nums text-muted-foreground/80"
                  style={{
                    width: "calc(var(--gutter) - 8px)",
                    textAlign: "right",
                  }}
                >
                  <NumberRoll
                    value={visible ? max * f : 0}
                    format={compact}
                    locales={locales}
                    duration={700}
                  />
                </span>
                <div
                  className="border-t border-border"
                  style={{ marginLeft: "var(--gutter)" }}
                />
              </div>
            ),
          )}

          <div
            ref={plotRef}
            role="group"
            tabIndex={0}
            aria-label={`${metric?.label ?? ""}, ${series[0]} against ${series[1]}. Use the arrow keys to read each month.`}
            onKeyDown={onKeyDown}
            onBlur={() => keyboard && (setActive(null), setKeyboard(false))}
            onPointerMove={(e) => {
              setKeyboard(false);
              setActive(pointAt(e.clientX));
            }}
            onPointerDown={(e) => setActive(pointAt(e.clientX))}
            onPointerLeave={(e) => e.pointerType === "mouse" && setActive(null)}
            className={`absolute inset-y-0 right-0 touch-pan-y select-none rounded-lg ${FOCUS}`}
            style={{ left: "var(--gutter)" }}
          >
            {/* Everything drawn reveals left to right the first time it's seen. */}
            <div
              className="absolute inset-x-0 top-0"
              style={{
                height: plotH,
                clipPath: visible
                  ? "inset(-8px -8px -8px -8px)"
                  : "inset(-8px 100% -8px -8px)",
                transition: reduced ? "none" : `clip-path 1200ms ${EASE}`,
              }}
            >
              <svg
                aria-hidden="true"
                width={width}
                height={plotH}
                className="absolute inset-0 overflow-visible"
              >
                <defs>
                  <linearGradient id={`${id}-wash`} x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0%" stopColor={LINE} stopOpacity="0.14" />
                    <stop offset="100%" stopColor={LINE} stopOpacity="0" />
                  </linearGradient>
                </defs>
                {prevLine && (
                  <path
                    d={prevLine}
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeDasharray="4 5"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    className="text-foreground/30"
                  />
                )}
                {area && <path d={area} fill={`url(#${id}-wash)`} />}
                {curLine && (
                  <path
                    d={curLine}
                    fill="none"
                    stroke={LINE}
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                )}
              </svg>
              {/* The end of a year still under way. */}
              {current.length > 0 && current.length < n && (
                <span
                  aria-hidden="true"
                  className="absolute size-2.5 -translate-x-1/2 -translate-y-1/2 rounded-full shadow-[0_0_0_2px_var(--background)]"
                  style={{
                    left: x(lastIndex),
                    top: y(cur[lastIndex] ?? 0),
                    background: LINE,
                    opacity: active === null ? 1 : 0,
                    transition: `opacity 200ms ${EASE}`,
                  }}
                />
              )}
            </div>

            {/* The hovered month: a thin line down to the baseline and a dot on each line. */}
            <span
              aria-hidden="true"
              className="pointer-events-none absolute top-0 w-px bg-foreground/20"
              style={{
                height: plotH,
                left: active !== null ? x(active) : 0,
                opacity: active !== null ? 1 : 0,
                transition: reduced
                  ? "none"
                  : `left 260ms ${THROW}, opacity 200ms ${EASE}`,
              }}
            />
            {previous.length > 0 &&
              dot(
                active,
                prev,
                "color-mix(in oklab, var(--foreground) 45%, var(--background))",
                "prev",
              )}
            {dot(active, cur, LINE, "cur")}

            {labels.map((l, i) => (
              <span
                key={l + i}
                aria-hidden="true"
                className={`absolute -translate-x-1/2 whitespace-nowrap text-[11px] leading-none transition-colors duration-200 ${active === i ? "text-foreground" : "text-muted-foreground"}`}
                style={{
                  left: x(i),
                  top: plotH + 9,
                  opacity: label(i) ? 1 : 0,
                }}
              >
                {l}
              </span>
            ))}
          </div>
        </div>

        <p aria-live="polite" className="sr-only">
          {keyboard && active !== null
            ? `${monthName(active)}: ${fmt(current[active] ?? 0)}${previous[active] !== undefined ? `, ${series[1].toLowerCase()} ${fmt(previous[active])}` : ""}`
            : ""}
        </p>
        <table className="sr-only">
          <caption>
            {metric?.label}: {fmt(add(current))} {series[0].toLowerCase()}
            {prevSame.length
              ? `, ${fmt(add(prevSame))} ${series[1].toLowerCase()} over the same months`
              : ""}
          </caption>
          <thead>
            <tr>
              <th scope="col">Month</th>
              <th scope="col">{series[0]}</th>
              {previous.length > 0 && <th scope="col">{series[1]}</th>}
            </tr>
          </thead>
          <tbody>
            {labels.map((l, i) => (
              <tr key={l + i}>
                <th scope="row">{monthName(i)}</th>
                <td>{current[i] !== undefined ? fmt(current[i]) : "–"}</td>
                {previous.length > 0 && (
                  <td>{previous[i] !== undefined ? fmt(previous[i]) : "–"}</td>
                )}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";

/* ─────────────────────────────────────────────────────────
 * SCROLL STORY: a how-it-works that tells itself as you scroll
 *
 *   steps     the words scroll past a picture that stays put; the
 *             step crossing the middle of the view lights up and
 *             the others wait at a third of their strength
 *   rail      a thin line down the steps fills with the scroll,
 *             continuously, and each step's dot fills as the line
 *             reaches it
 *   picture   one card that reshapes to each step's picture: its
 *             size eases from one to the next while the old
 *             picture blurs out and the new one rises in (and
 *             plays whatever it plays when it arrives). "02 / 04"
 *             rolls above it
 *   narrow    the picture sticks to the top and the steps slide
 *             underneath it
 *   jump      tapping a step scrolls it to the middle
 *
 * Works with the page's scroll or inside any scrolling box.
 * ───────────────────────────────────────────────────────── */

export interface ScrollStoryStep {
  title: string;
  body?: React.ReactNode;
  /** Mounted when its step arrives, so any animation in it plays then. */
  visual: React.ReactNode;
}

export interface ScrollStoryProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "children"
> {
  steps: ScrollStoryStep[];
  /** Where the picture sits when there's room for two columns. */
  side?: "start" | "end";
  onStepChange?: (index: number) => void;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const WIDE = 520;

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** The nearest box that scrolls vertically, or null for the page. */
function scrollParent(el: HTMLElement | null) {
  for (
    let p = el?.parentElement;
    p && p !== document.body;
    p = p.parentElement
  ) {
    if (/(auto|scroll)/.test(getComputedStyle(p).overflowY)) return p;
  }
  return null;
}

/** The card that changes shape between pictures. */
function Stage({
  index,
  children,
  reduced,
}: {
  index: number;
  children: React.ReactNode;
  reduced: boolean;
}) {
  const innerRef = React.useRef<HTMLDivElement>(null);
  const [size, setSize] = React.useState<{ w: number; h: number } | null>(null);
  const [ghost, setGhost] = React.useState<{
    key: number;
    node: React.ReactNode;
  } | null>(null);
  const last = React.useRef({ index, node: children });

  React.useLayoutEffect(() => {
    const el = innerRef.current;
    if (!el) return;
    const measure = () => setSize({ w: el.offsetWidth, h: el.offsetHeight });
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, [index]);

  // A new picture: keep the old one a moment to blur out underneath, raise the new one.
  React.useLayoutEffect(() => {
    if (index === last.current.index) {
      last.current.node = children;
      return;
    }
    if (!reduced)
      setGhost({ key: last.current.index, node: last.current.node });
    last.current = { index, node: children };
    if (reduced) return;
    innerRef.current?.animate(
      [
        {
          opacity: 0,
          transform: "translateY(10px) scale(0.98)",
          filter: "blur(4px)",
        },
        { opacity: 1, transform: "none", filter: "blur(0px)" },
      ],
      { duration: 420, delay: 90, easing: EASE, fill: "backwards" },
    );
  }, [index, children, reduced]);

  return (
    <div
      className="relative overflow-hidden rounded-[20px] border border-border bg-card"
      style={{
        width: size?.w,
        height: size?.h,
        transition:
          reduced || !size
            ? "none"
            : `width 460ms ${EASE}, height 460ms ${EASE}`,
      }}
    >
      {ghost && (
        <div
          key={`ghost-${ghost.key}`}
          aria-hidden="true"
          className="pointer-events-none absolute left-0 top-0 w-max"
          ref={(el) => {
            if (!el || el.dataset.out) return;
            el.dataset.out = "1";
            const a = el.animate(
              [
                { opacity: 1, filter: "blur(0px)", transform: "none" },
                { opacity: 0, filter: "blur(4px)", transform: "scale(0.97)" },
              ],
              { duration: 240, easing: EASE, fill: "forwards" },
            );
            a.onfinish = () =>
              setGhost((g) => (g?.key === ghost.key ? null : g));
          }}
        >
          {ghost.node}
        </div>
      )}
      <div key={index} ref={innerRef} className="w-max">
        {children}
      </div>
    </div>
  );
}

export function ScrollStory({
  steps,
  side = "end",
  onStepChange,
  className = "",
  style,
  ...props
}: ScrollStoryProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const listRef = React.useRef<HTMLDivElement>(null);
  const stickyRef = React.useRef<HTMLDivElement>(null);
  const trackRef = React.useRef<HTMLSpanElement>(null);
  const fillRef = React.useRef<HTMLSpanElement>(null);
  const stepRefs = React.useRef<(HTMLDivElement | null)[]>([]);
  const dotRefs = React.useRef<(HTMLSpanElement | null)[]>([]);
  const scroller = React.useRef<HTMLElement | null>(null);
  const [active, setActive] = React.useState(0);
  const [viewport, setViewport] = React.useState(0);
  const activeRef = React.useRef(0);
  const changed = React.useRef(onStepChange);
  React.useLayoutEffect(() => {
    changed.current = onStepChange;
  });

  // Where the reading line is: the middle of the view, or the middle of what the sticky picture leaves.
  const line = () => {
    const box = scroller.current?.getBoundingClientRect();
    const top = box ? box.top : 0;
    const height = scroller.current
      ? scroller.current.clientHeight
      : window.innerHeight;
    const wide = (rootRef.current?.clientWidth ?? 0) >= WIDE;
    const stuck = wide ? 0 : (stickyRef.current?.offsetHeight ?? 0);
    return top + stuck + (height - stuck) * (wide ? 0.5 : 0.42);
  };

  // On scroll: the rail fills to the line (written straight to the DOM), and the step at the line becomes active.
  const update = React.useCallback(() => {
    const list = listRef.current;
    const first = dotRefs.current[0];
    const last = dotRefs.current[steps.length - 1];
    if (!list || !first || !last) return;
    const y = line();
    const origin = list.getBoundingClientRect().top;
    const a =
      first.getBoundingClientRect().top + first.offsetHeight / 2 - origin;
    const b = last.getBoundingClientRect().top + last.offsetHeight / 2 - origin;
    if (trackRef.current)
      Object.assign(trackRef.current.style, {
        top: `${a}px`,
        height: `${b - a}px`,
      });
    if (fillRef.current)
      Object.assign(fillRef.current.style, {
        top: `${a}px`,
        height: `${Math.min(b - a, Math.max(0, y - origin - a))}px`,
      });
    let next = 0;
    stepRefs.current.forEach((el, i) => {
      if (el && el.getBoundingClientRect().top <= y) next = i;
    });
    if (next !== activeRef.current) {
      activeRef.current = next;
      setActive(next);
      changed.current?.(next);
    }
  }, [steps.length]);

  React.useLayoutEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    scroller.current = scrollParent(root);
    const target: HTMLElement | Window = scroller.current ?? window;
    let frame = 0;
    const onScroll = () => {
      if (frame) return;
      frame = requestAnimationFrame(() => {
        frame = 0;
        update();
      });
    };
    const measure = () => {
      setViewport(
        scroller.current ? scroller.current.clientHeight : window.innerHeight,
      );
      onScroll();
    };
    measure();
    target.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", measure);
    const observer = new ResizeObserver(measure);
    observer.observe(root);
    if (scroller.current) observer.observe(scroller.current);
    return () => {
      cancelAnimationFrame(frame);
      target.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", measure);
      observer.disconnect();
    };
  }, [update]);

  const jump = (i: number) => {
    const el = stepRefs.current[i];
    if (!el) return;
    const delta = el.getBoundingClientRect().top - line() + 2;
    const behavior: ScrollBehavior = reduced ? "auto" : "smooth";
    if (scroller.current) scroller.current.scrollBy({ top: delta, behavior });
    else window.scrollBy({ top: delta, behavior });
  };

  const pad = (n: number) => String(n).padStart(2, "0");

  return (
    <div
      ref={rootRef}
      className={`@container ${className}`}
      style={{ ...style, ["--story-h" as string]: `${viewport || 600}px` }}
      {...props}
    >
      <div className="grid @min-[520px]:grid-cols-2 @min-[520px]:gap-10">
        {/* The picture: beside the steps when there's room, stuck to the top when there isn't. */}
        <div
          ref={stickyRef}
          className={`sticky top-0 z-10 -mx-2 flex h-[calc(var(--story-h)*0.46)] flex-col items-center justify-center gap-3 border-b border-border bg-background px-2 @min-[520px]:mx-0 @min-[520px]:h-[var(--story-h)] @min-[520px]:border-b-0 @min-[520px]:bg-transparent @min-[520px]:px-0 ${
            side === "end" ? "@min-[520px]:order-last" : ""
          }`}
        >
          <p
            className="text-[11.5px] tabular-nums text-muted-foreground"
            aria-hidden="true"
          >
            <NumberRoll
              value={active + 1}
              format={{ minimumIntegerDigits: 2 }}
              duration={500}
            />{" "}
            / {pad(steps.length)}
          </p>
          <Stage index={active} reduced={reduced}>
            {steps[active]?.visual}
          </Stage>
        </div>

        <div
          ref={listRef}
          className="relative pb-[calc(var(--story-h)*0.12)] pt-8 @min-[520px]:pt-[calc(var(--story-h)*0.38)]"
        >
          <span
            ref={trackRef}
            aria-hidden="true"
            className="absolute left-[5px] w-px bg-border"
          />
          <span
            ref={fillRef}
            aria-hidden="true"
            className="absolute left-[5px] w-px bg-foreground"
          />
          {steps.map((s, i) => {
            const on = i === active;
            const reached = i <= active;
            return (
              <div
                key={i}
                ref={(el) => {
                  stepRefs.current[i] = el;
                }}
                aria-current={on ? "step" : undefined}
                className="relative min-h-[calc(var(--story-h)*0.42)] pl-7 @min-[520px]:min-h-[calc(var(--story-h)*0.55)]"
              >
                <span
                  ref={(el) => {
                    dotRefs.current[i] = el;
                  }}
                  aria-hidden="true"
                  className="absolute left-0 top-[3px] size-[11px] rounded-full border"
                  style={{
                    borderColor: reached
                      ? "var(--foreground)"
                      : "var(--border)",
                    backgroundColor: reached
                      ? "var(--foreground)"
                      : "var(--background)",
                    transform: on ? "scale(1.15)" : "scale(1)",
                    transition: reduced
                      ? "none"
                      : `background-color 240ms ${EASE}, border-color 240ms ${EASE}, transform 320ms cubic-bezier(0.34,1.36,0.64,1)`,
                  }}
                />
                <div
                  style={{
                    opacity: on ? 1 : 0.35,
                    transition: reduced ? "none" : `opacity 400ms ${EASE}`,
                  }}
                >
                  <p className="text-[11.5px] leading-4 tabular-nums text-muted-foreground">
                    {pad(i + 1)}
                  </p>
                  <h3 className="mt-1.5 text-[18px] font-semibold leading-tight tracking-tight text-foreground @min-[520px]:text-[20px]">
                    <button
                      type="button"
                      onClick={() => jump(i)}
                      className="cursor-pointer rounded-[4px] text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40"
                    >
                      {s.title}
                    </button>
                  </h3>
                  {s.body && (
                    <div className="mt-2 max-w-[36ch] text-[13.5px] leading-relaxed text-muted-foreground">
                      {s.body}
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { Input, type InputProps } from "./input";
import {
  EASE_OUT,
  interactionIcon,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * SEARCH INPUT: the field at the top of every list
 *
 *   shortcut  a ⌘K (or "/") hint sits at the end; the key
 *             focuses the field from anywhere on the page, and
 *             the hint steps aside once you type
 *   search    onSearch runs after a pause in typing (debounced);
 *             Enter runs it at once, Escape clears and leaves
 *   loading   the magnifier blurs into a spinner and back
 *   clear     the clear button folds in with the first letter
 * ───────────────────────────────────────────────────────── */

export interface SearchInputProps extends Omit<
  InputProps,
  "leading" | "type" | "clearable"
> {
  /** Called with the query after `debounce` ms without typing, and at once on Enter. */
  onSearch?: (query: string) => void;
  debounce?: number;
  /** Shows a spinner in place of the magnifier. */
  loading?: boolean;
  /** "mod+k" (⌘K / Ctrl K), "/" or null for no shortcut. */
  shortcut?: "mod+k" | "/" | null;
}

function Magnifier() {
  return (
    <svg viewBox="0 0 16 16" fill="none" className="size-3.5">
      <circle cx="7" cy="7" r="4.6" stroke="currentColor" strokeWidth="1.5" />
      <path
        d="M10.4 10.4 13.5 13.5"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
      />
    </svg>
  );
}

const subscribeNoop = () => () => {};
const isMac = () => /Mac|iPhone|iPad/.test(navigator.platform);

export function SearchInput({
  onSearch,
  debounce = 250,
  loading = false,
  shortcut = "mod+k",
  placeholder = "Search",
  value,
  defaultValue,
  onValueChange,
  onKeyDown,
  onFocus,
  onBlur,
  size = "md",
  ref,
  ...props
}: SearchInputProps) {
  const reduced = useInteractionReducedMotion();
  const inner = React.useRef<HTMLInputElement>(null);
  const [text, setText] = React.useState(String(defaultValue ?? ""));
  const [focused, setFocused] = React.useState(false);
  const current = value !== undefined ? String(value) : text;
  const mac = React.useSyncExternalStore(subscribeNoop, isMac, () => true);
  const searchRef = React.useRef(onSearch);
  React.useEffect(() => {
    searchRef.current = onSearch;
  });

  // Debounced search: each keystroke restarts the wait.
  const first = React.useRef(true);
  React.useEffect(() => {
    if (first.current) {
      first.current = false;
      return;
    }
    const timer = window.setTimeout(
      () => searchRef.current?.(current),
      debounce,
    );
    return () => window.clearTimeout(timer);
  }, [current, debounce]);

  // The shortcut focuses the field from anywhere, unless you're typing somewhere else.
  React.useEffect(() => {
    if (!shortcut) return;
    const onKey = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement;
      const typing =
        target.isContentEditable ||
        /^(INPUT|TEXTAREA|SELECT)$/.test(target.tagName);
      const hit =
        shortcut === "/"
          ? e.key === "/" && !typing
          : e.key.toLowerCase() === "k" && (e.metaKey || e.ctrlKey);
      if (!hit) return;
      e.preventDefault();
      inner.current?.focus();
      inner.current?.select();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [shortcut]);

  const showKey = !!shortcut && !focused && !current;
  const keyLabel = shortcut === "/" ? "/" : mac ? "⌘K" : "Ctrl K";

  return (
    <Input
      {...props}
      ref={(el) => {
        inner.current = el;
        if (typeof ref === "function") ref(el);
        else if (ref)
          (ref as React.RefObject<HTMLInputElement | null>).current = el;
      }}
      type="search"
      role="searchbox"
      size={size}
      clearable
      placeholder={placeholder}
      value={value}
      defaultValue={defaultValue}
      inputClassName="[&::-webkit-search-cancel-button]:appearance-none"
      onValueChange={(v) => {
        if (value === undefined) setText(v);
        onValueChange?.(v);
      }}
      onFocus={(e) => {
        setFocused(true);
        onFocus?.(e);
      }}
      onBlur={(e) => {
        setFocused(false);
        onBlur?.(e);
      }}
      onKeyDown={(e) => {
        onKeyDown?.(e);
        if (e.key === "Enter") onSearch?.(current);
        if (e.key === "Escape" && current) {
          e.preventDefault();
          e.currentTarget.blur();
        }
      }}
      leading={
        <span className="relative size-3.5" aria-hidden="true">
          <span
            className="absolute inset-0 flex items-center justify-center"
            style={interactionIcon(!loading, reduced)}
          >
            <Magnifier />
          </span>
          <span
            className="absolute inset-0 flex items-center justify-center"
            style={interactionIcon(loading, reduced)}
          >
            <span
              className={`size-3 rounded-full border-[1.5px] border-current border-t-transparent ${loading ? "animate-spin" : ""}`}
            />
          </span>
        </span>
      }
      trailing={
        shortcut ? (
          <span
            className="grid"
            style={{
              gridTemplateColumns: showKey ? "1fr" : "0fr",
              transition: reduced
                ? "none"
                : `grid-template-columns 320ms ${EASE_OUT}`,
            }}
          >
            <span className="min-w-0 overflow-hidden">
              <kbd
                aria-hidden="true"
                className={`mr-1.5 block whitespace-nowrap rounded-full px-1.5 font-mono text-[10.5px] leading-[18px] text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)]`}
                style={{
                  opacity: showKey ? 1 : 0,
                  filter: showKey ? "none" : "blur(3px)",
                  transition: reduced
                    ? "none"
                    : `opacity 200ms ${EASE_OUT}, filter 200ms ${EASE_OUT}`,
                }}
              >
                {keyLabel}
              </kbd>
            </span>
          </span>
        ) : undefined
      }
    />
  );
}

export default SearchInput;

"use client";

import * as React from "react";
import {
  EASE_OUT,
  EASE_THROW,
  INTERACTION_FOCUS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * SEGMENTED CONTROL: one of a few, side by side
 *
 *   pick     the thumb is thrown to the new segment with a slight
 *            overshoot while its width eases to the new label
 *   press    the thumb gives a little under the finger
 *   keys     a radiogroup: arrows move and select, Home/End jump;
 *            one tab stop for the whole control
 * ───────────────────────────────────────────────────────── */

export interface SegmentOption {
  value: string;
  label: React.ReactNode;
  icon?: React.ReactNode;
  /** Required when `label` isn't text (icon-only segments). */
  ariaLabel?: string;
  disabled?: boolean;
}

export interface SegmentedControlProps {
  options: SegmentOption[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Accessible name of the group. */
  label: string;
  /** 28px, 34px, or 40px tall (matches tactile sliders). */
  size?: "sm" | "md" | "lg";
  /** Stretch to the parent's width with equal segments. */
  block?: boolean;
  className?: string;
  /** Corner radius: "full" (pill, default) or "rounded" (concentric rounded container). */
  radius?: "full" | "rounded";
}

type Mark = { x: number; w: number };

export function SegmentedControl({
  options,
  value,
  defaultValue,
  onValueChange,
  label,
  size = "md",
  block,
  className = "",
  radius = "full",
}: SegmentedControlProps) {
  const reduced = useInteractionReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const [own, setOwn] = React.useState(defaultValue ?? options[0]?.value);
  const current = value !== undefined ? value : own;
  const [mark, setMark] = React.useState<Mark | null>(null);
  const [ready, setReady] = React.useState(false);
  const [pressing, setPressing] = React.useState(false);

  React.useLayoutEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const measure = () => {
      const el = current
        ? root.querySelector<HTMLElement>(
            `[data-segment="${CSS.escape(current)}"]`,
          )
        : null;
      if (!el) return setMark(null);
      const next = { x: el.offsetLeft, w: el.offsetWidth };
      setMark((p) => (p && p.x === next.x && p.w === next.w ? p : next));
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(root);
    root.querySelectorAll("[data-segment]").forEach((el) => ro.observe(el));
    return () => ro.disconnect();
  }, [current, options]);

  React.useEffect(() => {
    if (!mark || ready) return;
    const frame = requestAnimationFrame(() => setReady(true));
    return () => cancelAnimationFrame(frame);
  }, [mark, ready]);

  const pick = (v: string) => {
    if (value === undefined) setOwn(v);
    onValueChange?.(v);
  };

  const onKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    const enabled = options.filter((o) => !o.disabled);
    const index = enabled.findIndex((o) => o.value === current);
    let next = -1;
    if (e.key === "ArrowRight" || e.key === "ArrowDown")
      next = (index + 1) % enabled.length;
    else if (e.key === "ArrowLeft" || e.key === "ArrowUp")
      next = (index - 1 + enabled.length) % enabled.length;
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = enabled.length - 1;
    if (next < 0) return;
    e.preventDefault();
    const v = enabled[next].value;
    pick(v);
    rootRef.current
      ?.querySelector<HTMLElement>(`[data-segment="${CSS.escape(v)}"]`)
      ?.focus();
  };

  const isLg = size === "lg";
  const isSm = size === "sm";
  const isPill = radius === "full";

  // Concentric corner radius matching compact slider geometry
  const rootRadius = isPill
    ? "rounded-full"
    : isLg
      ? "rounded-[13px]"
      : isSm
        ? "rounded-[9px]"
        : "rounded-[11px]";
  const itemRadius = isPill
    ? "rounded-full"
    : isLg
      ? "rounded-[9px]"
      : isSm
        ? "rounded-[7px]"
        : "rounded-[9px]";

  // Proportional sizing: "md" is compact 34px, "lg" is 40px, "sm" is 28px
  const rootPadding = isLg ? "p-1" : "p-0.5";
  const rootHeight = isLg ? "h-10" : isSm ? "h-7" : "h-8.5";
  const indicatorInset = isLg ? "top-1 bottom-1" : "top-0.5 bottom-0.5";
  const itemHeightClass = isLg
    ? "h-8 px-3 text-[13px]"
    : isSm
      ? "h-6 px-2 text-[11.5px]"
      : "h-[30px] px-2.5 text-[12px]";

  return (
    <div
      ref={rootRef}
      role="radiogroup"
      aria-label={label}
      onKeyDown={onKeyDown}
      className={`relative isolate select-none items-center ${rootHeight} ${rootRadius} ${rootPadding} border border-black/[0.04] dark:border-white/[0.06] bg-[#f4f4f6] dark:bg-zinc-900/50 ${
        block ? "flex w-full" : "inline-flex"
      } ${className}`}
    >
      <span
        aria-hidden="true"
        className={`pointer-events-none absolute left-0 ${indicatorInset} ${itemRadius} bg-white dark:bg-zinc-800 border border-black/[0.05] dark:border-white/[0.1] shadow-[0_1px_2px_rgba(0,0,0,0.04)]`}
        style={{
          transform: `translate3d(${mark?.x ?? 0}px, 0, 0) scale(${pressing && !reduced ? 0.97 : 1})`,
          width: mark?.w ?? 0,
          opacity: mark ? 1 : 0,
          transition:
            reduced || !ready
              ? "none"
              : `transform 440ms ${EASE_THROW}, width 400ms ${EASE_OUT}, opacity 200ms ${EASE_OUT}`,
        }}
      />
      {options.map((option) => {
        const on = option.value === current;
        return (
          <button
            key={option.value}
            type="button"
            role="radio"
            aria-checked={on}
            aria-label={option.ariaLabel}
            data-segment={option.value}
            disabled={option.disabled}
            tabIndex={on ? 0 : -1}
            onClick={() => pick(option.value)}
            onPointerDown={() => on && setPressing(true)}
            onPointerUp={() => setPressing(false)}
            onPointerLeave={() => setPressing(false)}
            className={`relative z-10 inline-flex items-center justify-center gap-1.5 whitespace-nowrap ${itemRadius} font-medium cursor-pointer transition-colors duration-200 disabled:cursor-default disabled:opacity-40 [&_svg]:size-3.5 ${itemHeightClass} ${
              block ? "flex-1" : ""
            } ${on ? "text-zinc-950 font-semibold dark:text-white" : "text-zinc-600 hover:text-zinc-950 dark:text-zinc-400 dark:hover:text-zinc-100"} ${INTERACTION_FOCUS}`}
          >
            {option.icon}
            {option.label}
          </button>
        );
      })}
    </div>
  );
}

export default SegmentedControl;

"use client";

import * as React from "react";
import { Field, useFieldIds } from "./field";
import {
  PillSelect,
  type PillOption,
  type PillSelectProps,
} from "./pill-select";

/* ─────────────────────────────────────────────────────────
 * SELECT: a choice from a list, never the browser's dropdown
 *
 *   open     the pill grows into its list (size and corners ease)
 *            from the edge it lines up with; upward when there's
 *            no room below; long lists scroll
 *   pick     the list folds back into the pill and the label
 *            morphs to the choice, which carries a drawn check
 *   keys     arrows glide a highlight, typing finds an option,
 *            Enter picks, Escape folds it back
 *
 * The list lives in a portal, so no toolbar, card or scroller
 * clips it. Labelled and hinted like every other field.
 * ───────────────────────────────────────────────────────── */

export type SelectOption = PillOption;

export interface SelectProps extends Omit<
  PillSelectProps,
  "label" | "value" | "onValueChange"
> {
  /** Shown above; also the accessible name. */
  label: string;
  /** Hide the label visually (it stays the accessible name). */
  hideLabel?: boolean;
  hint?: React.ReactNode;
  error?: React.ReactNode;
  value?: string | null;
  defaultValue?: string | null;
  onValueChange?: (value: string) => void;
  id?: string;
}

export function Select({
  label,
  hideLabel,
  hint,
  error,
  value,
  defaultValue = null,
  onValueChange,
  id,
  className = "",
  block = true,
  size = "md",
  ...props
}: SelectProps) {
  const ids = useFieldIds(id);
  const [own, setOwn] = React.useState<string | null>(defaultValue);
  const current = value !== undefined ? value : own;
  return (
    <Field
      id={ids.id}
      label={hideLabel ? undefined : label}
      hint={hint}
      error={error}
      className={className}
    >
      <PillSelect
        {...props}
        id={ids.id}
        aria-describedby={error ? ids.error : hint ? ids.hint : undefined}
        aria-invalid={error ? true : undefined}
        block={block}
        size={size}
        label={label}
        value={current}
        onValueChange={(v) => {
          if (value === undefined) setOwn(v);
          onValueChange?.(v);
        }}
      />
    </Field>
  );
}

export default Select;

"use client";

import * as React from "react";
import {
  ArrowUp,
  Check,
  ChevronRight,
  RotateCcw,
  Square,
  X,
} from "lucide-react";

/* ─────────────────────────────────────────────────────────
 * SELECTION ACTIONS: select text, rewrite it in place
 *
 *   open       a pill under the selection: a field for your own
 *              instruction, quick actions, more behind the chevron
 *   typing     the actions fold away and the field takes the room
 *   thinking   a spinner and "Improving…" until the first words
 *   streaming  the rewrite streams into the selection itself
 *   result     Keep, Discard or try again
 *   error      it didn't work; try again
 *
 * Give it the text as value. onAction gets the selection and
 * returns the rewrite: a string, a promise of one, or an async
 * iterable of chunks to stream. Keep calls onValueChange.
 * ───────────────────────────────────────────────────────── */

export interface SelectionAction {
  id: string;
  label: string;
  icon?: React.ReactNode;
  /** Shown while it runs, e.g. "Shortening". */
  pendingLabel?: string;
}

export interface SelectionRequest {
  /** The action's id, or "custom" for a typed instruction. */
  id: string;
  /** The selected text. */
  text: string;
  instruction?: string;
  /** The text around the selection, for context. */
  before: string;
  after: string;
  /** Aborted when the person stops or discards. */
  signal: AbortSignal;
}

/** The rewrite, whole or streamed. Return nothing for actions handled elsewhere (e.g. Explain opening a chat). */
export type SelectionResult =
  string | AsyncIterable<string> | Promise<string | void> | void;

export interface SelectionActionsProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "children"
> {
  value: string;
  onValueChange: (value: string) => void;
  /** Always visible. */
  actions: SelectionAction[];
  /** Behind the chevron. */
  more?: SelectionAction[];
  onAction: (request: SelectionRequest) => SelectionResult;
  placeholder?: string;
}

type Mode = "idle" | "thinking" | "streaming" | "result" | "error";
type Edit = {
  start: number;
  end: number;
  original: string;
  id: string;
  label: string;
  instruction?: string;
};

const EASE = "cubic-bezier(0.23,1,0.32,1)";
const GLIDE = "cubic-bezier(0.77,0,0.175,1)";
const FIELD = 148;
const FIELD_MIN = 72;
const HIGHLIGHT = "ui-selection";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const QUIET = `cursor-pointer inline-flex h-7 shrink-0 items-center gap-1.5 whitespace-nowrap rounded-full px-2.5 text-[12.5px] text-foreground transition-[background-color,transform] duration-150 hover:bg-accent active:scale-[0.96] [&_svg]:size-3.5 [&_svg]:text-muted-foreground ${FOCUS}`;
const ICON = `cursor-pointer flex size-7 shrink-0 items-center justify-center rounded-full text-muted-foreground transition-[background-color,color,transform] duration-150 hover:bg-accent hover:text-foreground active:scale-[0.96] [&_svg]:size-3.5 ${FOCUS}`;
const SHIMMER =
  "bg-[linear-gradient(90deg,color-mix(in_oklab,var(--muted-foreground)_55%,transparent)_35%,var(--foreground)_50%,color-mix(in_oklab,var(--muted-foreground)_55%,transparent)_65%)] bg-[length:200%_100%] bg-clip-text text-transparent animate-[ui-shimmer_1.4s_linear_infinite] motion-reduce:animate-none motion-reduce:bg-none motion-reduce:text-foreground/70";

// The Highlight API is newer than some TypeScript DOM libs; reach it through guarded casts.
type Registry = {
  set(name: string, highlight: unknown): void;
  delete(name: string): void;
};
const registry = () =>
  typeof CSS !== "undefined"
    ? (CSS as unknown as { highlights?: Registry }).highlights
    : undefined;
const HighlightClass = () =>
  (globalThis as unknown as { Highlight?: new (...ranges: Range[]) => unknown })
    .Highlight;

const isAsyncIterable = (x: unknown): x is AsyncIterable<string> =>
  typeof x === "object" && x !== null && Symbol.asyncIterator in x;

/** Characters from the start of root to (node, offset). */
function offsetIn(root: Node, node: Node, offset: number) {
  const range = document.createRange();
  range.setStart(root, 0);
  range.setEnd(node, offset);
  return range.toString().length;
}

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** A row that folds to zero width. Its natural width is measured so the fold animates exactly. */
function Fold({
  open,
  width,
  onWidth,
  reduced,
  gap = true,
  children,
}: {
  open: boolean;
  width?: number;
  onWidth?: (width: number) => void;
  reduced: boolean;
  gap?: boolean;
  children: React.ReactNode;
}) {
  const inner = React.useRef<HTMLDivElement>(null);
  React.useLayoutEffect(() => {
    const el = inner.current;
    if (!el || !onWidth) return;
    const report = () => onWidth(el.offsetWidth);
    report();
    const observer = new ResizeObserver(report);
    observer.observe(el);
    return () => observer.disconnect();
  }, [onWidth]);

  return (
    <div
      inert={!open}
      className="flex shrink-0 items-center overflow-hidden"
      style={{
        maxWidth: open ? width : 0,
        opacity: open ? 1 : 0,
        transform: open ? "none" : "translateX(-6px)",
        transition: reduced
          ? "none"
          : `max-width 400ms ${EASE}, opacity 300ms ${EASE}, transform 400ms ${EASE}`,
      }}
    >
      <div
        ref={inner}
        className={`flex w-max shrink-0 items-center gap-0.5 ${gap ? "pl-0.5" : ""}`}
      >
        {children}
      </div>
    </div>
  );
}

const Divider = () => (
  <span aria-hidden="true" className="mx-1 h-4 w-px shrink-0 bg-border" />
);

export function SelectionActions({
  value,
  onValueChange,
  actions,
  more = [],
  onAction,
  placeholder = "Describe edits",
  className = "",
  ...props
}: SelectionActionsProps) {
  const reduced = useReducedMotion();
  const [open, setOpen] = React.useState(false);
  const [ready, setReady] = React.useState(false);
  const [mode, setModeState] = React.useState<Mode>("idle");
  const [edit, setEdit] = React.useState<Edit | null>(null);
  const [chunks, setChunks] = React.useState<string[]>([]);
  const [anchor, setAnchor] = React.useState({ x: 0, y: 0 });
  const [expanded, setExpanded] = React.useState(false);
  const [prompt, setPrompt] = React.useState("");
  const [typingWidth, setTypingWidth] = React.useState<number | null>(null);
  const [rootWidth, setRootWidth] = React.useState(0);
  const [widths, setWidths] = React.useState<Record<string, number>>({});

  const rootRef = React.useRef<HTMLDivElement>(null);
  const textRef = React.useRef<HTMLDivElement>(null);
  const markRef = React.useRef<HTMLSpanElement>(null);
  const barRef = React.useRef<HTMLDivElement>(null);
  const contentRef = React.useRef<HTMLDivElement>(null);
  const keepRef = React.useRef<HTMLButtonElement>(null);
  const rangeRef = React.useRef<Range | null>(null);
  const selRef = React.useRef<{ start: number; end: number } | null>(null);
  const editRef = React.useRef<Edit | null>(null);
  const modeRef = React.useRef<Mode>("idle");
  const openRef = React.useRef(false);
  const draggingRef = React.useRef(false);
  const streamedRef = React.useRef("");
  const controllerRef = React.useRef<AbortController | null>(null);
  const frameRef = React.useRef(0);
  const valueRef = React.useRef(value);
  const onActionRef = React.useRef(onAction);
  React.useLayoutEffect(() => {
    valueRef.current = value;
    onActionRef.current = onAction;
  });

  const setMode = (next: Mode) => {
    modeRef.current = next;
    setModeState(next);
  };

  const report = React.useMemo(() => {
    const make = (key: string) => (n: number) =>
      setWidths((w) => (w[key] === n ? w : { ...w, [key]: n }));
    return {
      primary: make("primary"),
      more: make("more"),
      tail: make("tail"),
      send: make("send"),
    };
  }, []);

  const close = React.useCallback(() => {
    controllerRef.current?.abort();
    registry()?.delete(HIGHLIGHT);
    rangeRef.current = null;
    selRef.current = null;
    editRef.current = null;
    streamedRef.current = "";
    openRef.current = false;
    modeRef.current = "idle";
    setOpen(false);
    setReady(false);
    setModeState("idle");
    setEdit(null);
    setChunks([]);
    setExpanded(false);
    setPrompt("");
    setTypingWidth(null);
  }, []);

  /* Centre on the whole selection, sit under its last line, stay inside the container. */
  const measure = React.useCallback(() => {
    const root = rootRef.current;
    const target: Range | HTMLElement | null =
      markRef.current ?? rangeRef.current;
    if (!root || !target) return null;
    const rects = target.getClientRects();
    const last = rects[rects.length - 1];
    if (!last) return null;
    const bounds = target.getBoundingClientRect();
    const box = root.getBoundingClientRect();
    const half = (barRef.current?.offsetWidth ?? 0) / 2;
    const x = bounds.left - box.left + bounds.width / 2;
    // A bar wider than the text is centred on it rather than pinned to one side.
    const lo = Math.min(half, box.width / 2);
    const hi = Math.max(box.width - half, box.width / 2);
    return {
      x: Math.round(Math.min(Math.max(x, lo), hi)),
      y: Math.round(last.bottom - box.top + 8),
    };
  }, []);

  const place = React.useCallback(() => {
    cancelAnimationFrame(frameRef.current);
    frameRef.current = requestAnimationFrame(() => {
      const next = measure();
      if (next) setAnchor((a) => (a.x === next.x && a.y === next.y ? a : next));
    });
  }, [measure]);

  /* Read the selection inside the text. Ignored while an edit runs or the bar has focus. */
  const evaluate = React.useCallback(() => {
    if (editRef.current || barRef.current?.contains(document.activeElement))
      return;
    const text = textRef.current;
    const node = text?.firstChild;
    const selection = window.getSelection();
    const range =
      selection && selection.rangeCount ? selection.getRangeAt(0) : null;
    if (
      !text ||
      !node ||
      !range ||
      range.collapsed ||
      !text.contains(range.startContainer) ||
      !text.contains(range.endContainer)
    ) {
      if (openRef.current) close();
      return;
    }
    const v = valueRef.current;
    let start = offsetIn(text, range.startContainer, range.startOffset);
    let end = offsetIn(text, range.endContainer, range.endOffset);
    while (start < end && /\s/.test(v[start])) start++;
    while (end > start && /\s/.test(v[end - 1])) end--;
    if (start >= end) {
      if (openRef.current) close();
      return;
    }
    const trimmed = document.createRange();
    trimmed.setStart(node, start);
    trimmed.setEnd(node, end);
    rangeRef.current = trimmed;
    selRef.current = { start, end };
    const Highlight = HighlightClass();
    if (Highlight) registry()?.set(HIGHLIGHT, new Highlight(trimmed));
    const next = measure();
    if (next) setAnchor(next);
    openRef.current = true;
    setOpen(true);
  }, [close, measure]);

  const execute = async (target: Edit) => {
    controllerRef.current?.abort();
    const controller = new AbortController();
    controllerRef.current = controller;
    const v = valueRef.current;
    let out: SelectionResult;
    try {
      out = onActionRef.current({
        id: target.id,
        text: target.original,
        instruction: target.instruction,
        before: v.slice(0, target.start),
        after: v.slice(target.end),
        signal: controller.signal,
      });
    } catch (error) {
      out = Promise.reject(error);
    }
    if (out === undefined) {
      close();
      return;
    }

    window.getSelection()?.removeAllRanges();
    registry()?.delete(HIGHLIGHT);
    editRef.current = target;
    streamedRef.current = "";
    setEdit(target);
    setChunks([]);
    setExpanded(false);
    setPrompt("");
    setTypingWidth(null);
    setMode("thinking");

    try {
      if (isAsyncIterable(out)) {
        for await (const chunk of out) {
          if (controller.signal.aborted) return;
          if (!chunk) continue;
          streamedRef.current += chunk;
          setChunks((c) => [...c, chunk]);
          setMode("streaming");
        }
      } else {
        const whole = await out;
        if (controller.signal.aborted) return;
        if (typeof whole !== "string") {
          close();
          return;
        }
        streamedRef.current = whole;
        setChunks(whole ? [whole] : []);
      }
      if (controller.signal.aborted) return;
      setMode(streamedRef.current.trim() ? "result" : "error");
    } catch {
      if (!controller.signal.aborted) setMode("error");
    }
  };

  const start = (id: string, label: string, instruction?: string) => {
    const sel = selRef.current;
    if (!sel) return;
    execute({
      ...sel,
      original: valueRef.current.slice(sel.start, sel.end),
      id,
      label,
      instruction,
    });
  };

  const keep = () => {
    const target = editRef.current;
    if (!target) return;
    const v = valueRef.current;
    onValueChange(
      v.slice(0, target.start) + streamedRef.current + v.slice(target.end),
    );
    close();
  };

  /* Stopping keeps what has streamed so far for review; with nothing yet, it's a discard. */
  const stop = () => {
    controllerRef.current?.abort();
    if (streamedRef.current.trim()) setMode("result");
    else close();
  };

  const handlers = React.useRef({ close, stop });
  React.useLayoutEffect(() => {
    handlers.current = { close, stop };
  });

  // Follow the selection: after a drag ends, and as keyboard or touch handles adjust it.
  React.useEffect(() => {
    const onSelection = () => {
      if (!draggingRef.current) evaluate();
    };
    const onUp = () => {
      if (!draggingRef.current) return;
      draggingRef.current = false;
      evaluate();
    };
    document.addEventListener("selectionchange", onSelection);
    document.addEventListener("pointerup", onUp);
    return () => {
      document.removeEventListener("selectionchange", onSelection);
      document.removeEventListener("pointerup", onUp);
      controllerRef.current?.abort();
      registry()?.delete(HIGHLIGHT);
    };
  }, [evaluate]);

  // Escape backs out one step; a click outside closes an untouched selection.
  React.useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== "Escape") return;
      const m = modeRef.current;
      if (m === "thinking" || m === "streaming") handlers.current.stop();
      else handlers.current.close();
    };
    const onDown = (e: PointerEvent) => {
      if (!editRef.current && !rootRef.current?.contains(e.target as Node))
        handlers.current.close();
    };
    document.addEventListener("keydown", onKey);
    document.addEventListener("pointerdown", onDown);
    return () => {
      document.removeEventListener("keydown", onKey);
      document.removeEventListener("pointerdown", onDown);
    };
  }, [open]);

  // Turn on the glide only after the bar has painted in place, so it never flies in from a corner.
  React.useEffect(() => {
    if (!open) return;
    let inner = 0;
    const outer = requestAnimationFrame(() => {
      inner = requestAnimationFrame(() => setReady(true));
    });
    return () => {
      cancelAnimationFrame(outer);
      cancelAnimationFrame(inner);
    };
  }, [open]);

  React.useLayoutEffect(() => {
    if (open) place();
  }, [open, mode, chunks, expanded, typingWidth, place]);

  React.useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const observer = new ResizeObserver(() => {
      setRootWidth(root.clientWidth);
      if (openRef.current) place();
    });
    observer.observe(root);
    return () => {
      observer.disconnect();
      cancelAnimationFrame(frameRef.current);
    };
  }, [place]);

  /* When the whole content changes (actions, progress, Keep), morph the bar from its last width. */
  const lastWidth = React.useRef(0);
  const previousMode = React.useRef<Mode>("idle");
  const widthAnimation = React.useRef<Animation | null>(null);
  React.useLayoutEffect(() => {
    const bar = barRef.current;
    const content = contentRef.current;
    if (!bar || !content) {
      lastWidth.current = 0;
      previousMode.current = mode;
      return;
    }
    const next = Math.ceil(content.getBoundingClientRect().width) + 8;
    const previous = lastWidth.current;
    // The new content rises out of a light blur as the bar takes its width (progress → Keep, actions → progress…).
    const busyBoth = (m: Mode) => m === "thinking" || m === "streaming";
    if (
      previousMode.current !== mode &&
      previous &&
      !reduced &&
      !(busyBoth(previousMode.current) && busyBoth(mode))
    ) {
      content.animate(
        [
          { opacity: 0, filter: "blur(4px)" },
          { opacity: 1, filter: "blur(0px)" },
        ],
        {
          duration: 300,
          easing: "cubic-bezier(0.16,1,0.3,1)",
          delay: 60,
          fill: "backwards",
        },
      );
    }
    if (
      previousMode.current !== mode &&
      previous &&
      Math.abs(next - previous) > 1 &&
      !reduced
    ) {
      widthAnimation.current?.cancel();
      const animation = bar.animate(
        [{ width: `${previous}px` }, { width: `${next}px` }],
        { duration: 320, easing: EASE },
      );
      widthAnimation.current = animation;
      animation.onfinish = () => {
        if (widthAnimation.current === animation) widthAnimation.current = null;
      };
    }
    lastWidth.current = next;
    previousMode.current = mode;
  }, [mode, open, reduced]);

  React.useEffect(() => {
    const content = contentRef.current;
    if (!open || !content) return;
    const observer = new ResizeObserver(() => {
      place(); // re-centre as folds open and close
      if (widthAnimation.current?.playState === "running") return;
      lastWidth.current = Math.ceil(content.getBoundingClientRect().width) + 8;
    });
    observer.observe(content);
    return () => {
      observer.disconnect();
      widthAnimation.current?.cancel();
    };
  }, [open, place]);

  // Hand focus to Keep when the rewrite is ready, unless the person has moved on.
  React.useEffect(() => {
    if (mode !== "result") return;
    const active = document.activeElement;
    if (!active || active === document.body || barRef.current?.contains(active))
      keepRef.current?.focus({ preventScroll: true });
  }, [mode]);

  // Arrow keys move between the buttons.
  const onToolbarKey = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (e.key !== "ArrowRight" && e.key !== "ArrowLeft") return;
    const buttons = Array.from(
      barRef.current?.querySelectorAll<HTMLButtonElement>(
        "button:not([disabled])",
      ) ?? [],
    ).filter((b) => !b.closest("[inert]"));
    const i = buttons.indexOf(document.activeElement as HTMLButtonElement);
    if (i < 0) return;
    e.preventDefault();
    buttons[
      (i + (e.key === "ArrowRight" ? 1 : -1) + buttons.length) % buttons.length
    ]?.focus();
  };

  const typing = prompt.trim().length > 0 && typingWidth !== null;
  const send = widths.send ?? 30;
  const restWidth = rootWidth
    ? Math.max(
        FIELD_MIN,
        Math.min(
          FIELD,
          rootWidth -
            8 -
            11 -
            (widths.primary ?? 0) -
            (more.length ? (widths.tail ?? 0) : 0),
        ),
      )
    : FIELD;
  const fieldWidth = typing && typingWidth ? typingWidth - 8 - send : restWidth;
  const busy = mode === "thinking" || mode === "streaming";
  const label = edit?.label ?? "Editing";

  const action = (item: SelectionAction) => (
    <button
      key={item.id}
      type="button"
      onClick={() => start(item.id, item.pendingLabel ?? item.label)}
      className={QUIET}
    >
      {item.icon}
      {item.label}
    </button>
  );

  return (
    <div ref={rootRef} className={`relative ${className}`} {...props}>
      {/* Supply this valid selector directly: Turbopack's CSS parser warns on ::highlight(). */}
      <style>{`::highlight(${HIGHLIGHT}) { background-color: color-mix(in oklab, var(--primary) 18%, transparent); }`}</style>
      <div
        ref={textRef}
        onPointerDown={() => {
          if (editRef.current) return;
          draggingRef.current = true;
          if (openRef.current) close();
        }}
        className="whitespace-pre-wrap"
      >
        {edit ? (
          <>
            {value.slice(0, edit.start)}
            <span
              ref={markRef}
              className="rounded-[3px] bg-primary/15 box-decoration-clone"
            >
              {mode === "streaming" || mode === "result" ? (
                chunks.map((chunk, i) => (
                  <span
                    key={i}
                    className="animate-[ui-fade-in_280ms_ease-out_both] motion-reduce:animate-none"
                  >
                    {chunk}
                  </span>
                ))
              ) : (
                <span
                  className={`transition-opacity duration-300 ${mode === "thinking" ? "opacity-55" : ""}`}
                >
                  {edit.original}
                </span>
              )}
            </span>
            {value.slice(edit.end)}
          </>
        ) : (
          value
        )}
      </div>

      {open && (
        <div
          className="absolute left-0 top-0 z-50"
          style={{
            transform: `translate3d(${anchor.x}px, ${anchor.y}px, 0) translateX(-50%)`,
            transition: ready && !reduced ? `transform 320ms ${GLIDE}` : "none",
          }}
        >
          <div
            ref={barRef}
            role="toolbar"
            aria-label="Edit selection"
            onKeyDown={onToolbarKey}
            // Keep the text selected while clicking the bar (the field still takes focus).
            onPointerDown={(e) => {
              if (!(e.target instanceof HTMLInputElement)) e.preventDefault();
            }}
            className="flex h-9 w-fit max-w-[calc(100vw-32px)] select-none items-center justify-center overflow-hidden rounded-full bg-background p-1 text-foreground shadow-[0_0_0_1px_var(--border)] animate-[ui-pop-in_220ms_cubic-bezier(0.23,1,0.32,1)_both] motion-reduce:animate-none"
            style={{
              width:
                mode === "idle" && typing
                  ? (typingWidth ?? undefined)
                  : undefined,
            }}
          >
            <div
              ref={contentRef}
              className="flex w-max shrink-0 items-center"
              style={{
                width:
                  mode === "idle" && typing && typingWidth
                    ? typingWidth - 8
                    : undefined,
              }}
            >
              {mode === "idle" && (
                <>
                  <Fold
                    open={!expanded}
                    width={fieldWidth}
                    reduced={reduced}
                    gap={false}
                  >
                    <form
                      onSubmit={(e) => {
                        e.preventDefault();
                        if (prompt.trim())
                          start("custom", "Editing", prompt.trim());
                      }}
                      className="flex h-7 items-center"
                      style={{
                        width: fieldWidth,
                        transition: reduced ? "none" : `width 400ms ${EASE}`,
                      }}
                    >
                      <input
                        value={prompt}
                        onChange={(e) => {
                          const next = e.target.value;
                          if (!prompt.trim() && next.trim()) {
                            const now = Math.ceil(
                              barRef.current?.getBoundingClientRect().width ??
                                0,
                            );
                            setTypingWidth(Math.max(now, 8 + FIELD + send));
                          } else if (!next.trim()) setTypingWidth(null);
                          setPrompt(next);
                        }}
                        placeholder={placeholder}
                        aria-label={placeholder}
                        className="h-7 w-full min-w-0 text-ellipsis bg-transparent pl-3 pr-2 text-[12.5px] text-foreground outline-none placeholder:text-muted-foreground"
                      />
                    </form>
                  </Fold>
                  <Fold
                    open={!typing && !expanded}
                    width={9}
                    reduced={reduced}
                    gap={false}
                  >
                    <Divider />
                  </Fold>
                  <Fold
                    open={!typing}
                    width={widths.primary}
                    onWidth={report.primary}
                    reduced={reduced}
                    gap={false}
                  >
                    {actions.map(action)}
                  </Fold>
                  {more.length > 0 && (
                    <>
                      <Fold
                        open={!typing && expanded}
                        width={widths.more}
                        onWidth={report.more}
                        reduced={reduced}
                      >
                        {more.map(action)}
                      </Fold>
                      <Fold
                        open={!typing}
                        width={widths.tail}
                        onWidth={report.tail}
                        reduced={reduced}
                      >
                        <Divider />
                        <button
                          type="button"
                          aria-label={
                            expanded ? "Fewer actions" : "More actions"
                          }
                          aria-expanded={expanded}
                          onClick={() => setExpanded((x) => !x)}
                          className={`cursor-pointer ${ICON} text-foreground`}
                        >
                          <ChevronRight
                            className="transition-transform duration-[400ms]"
                            style={{
                              transform: expanded ? "rotate(180deg)" : "none",
                              transitionTimingFunction: EASE,
                            }}
                          />
                        </button>
                      </Fold>
                    </>
                  )}
                  <Fold
                    open={typing}
                    width={send}
                    onWidth={report.send}
                    reduced={reduced}
                  >
                    <button
                      type="button"
                      aria-label="Send edit"
                      onClick={() =>
                        prompt.trim() &&
                        start("custom", "Editing", prompt.trim())
                      }
                      className={`cursor-pointer flex size-7 shrink-0 items-center justify-center rounded-full bg-primary text-primary-foreground transition-transform duration-150 active:scale-[0.94] ${FOCUS}`}
                    >
                      <ArrowUp className="size-4" strokeWidth={2.4} />
                    </button>
                  </Fold>
                </>
              )}

              {busy && (
                <>
                  <span
                    role="status"
                    className="inline-flex h-7 items-center gap-1.5 whitespace-nowrap pl-2.5 pr-1.5 text-[12.5px] text-muted-foreground"
                  >
                    <span
                      aria-hidden="true"
                      className="size-3 shrink-0 animate-spin rounded-full border-[1.5px] border-border border-t-muted-foreground motion-reduce:animate-none"
                    />
                    {mode === "thinking" ? (
                      <span className={SHIMMER}>{label}…</span>
                    ) : (
                      <span>{label}…</span>
                    )}
                  </span>
                  <Divider />
                  <button
                    type="button"
                    aria-label="Stop"
                    onClick={stop}
                    className={ICON}
                  >
                    <Square className="!size-2.5" fill="currentColor" />
                  </button>
                </>
              )}

              {mode === "result" && (
                <>
                  <span className="sr-only" role="status">
                    Rewrite ready. Keep or discard it.
                  </span>
                  <button
                    ref={keepRef}
                    type="button"
                    onClick={keep}
                    className={`cursor-pointer inline-flex h-7 shrink-0 items-center gap-1 rounded-full bg-primary px-2.5 text-[12.5px] text-primary-foreground transition-[opacity,transform] duration-150 hover:opacity-90 active:scale-[0.96] [&_svg]:size-3.5 ${FOCUS}`}
                  >
                    <Check />
                    Keep
                  </button>
                  <button
                    type="button"
                    onClick={close}
                    className={`cursor-pointer ${QUIET} ml-0.5`}
                  >
                    <X />
                    Discard
                  </button>
                  <Divider />
                  <button
                    type="button"
                    aria-label="Try again"
                    onClick={() => editRef.current && execute(editRef.current)}
                    className={ICON}
                  >
                    <RotateCcw />
                  </button>
                </>
              )}

              {mode === "error" && (
                <>
                  <span
                    role="alert"
                    className="whitespace-nowrap pl-2.5 pr-1 text-[12.5px] text-muted-foreground"
                  >
                    That didn’t work
                  </span>
                  <button
                    type="button"
                    onClick={() => editRef.current && execute(editRef.current)}
                    className={QUIET}
                  >
                    <RotateCcw />
                    Try again
                  </button>
                  <Divider />
                  <button
                    type="button"
                    aria-label="Discard"
                    onClick={close}
                    className={ICON}
                  >
                    <X />
                  </button>
                </>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { StatusButton, type ActionStatus } from "./status-button";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * SETTINGS FORM: a settings page that saves the way people
 * expect it to
 *
 *   switch    toggles and choices save the moment they change:
 *             the thumb is thrown across, "Saving" opens beside
 *             the label, a check draws and fades. If the server
 *             says no, the thumb is thrown back with a shake
 *             and the reason opens under the field
 *   edit      text edits wait for you: a dot swells beside each
 *             changed label and one bar rises at the foot of
 *             the form, "2 unsaved changes", rolling as you go
 *   check     a field with an async check (is this address
 *             free?) asks a moment after you stop typing:
 *             "Checking", then "Available" or why not
 *   save      Save (or ⌘S) sends just what changed; the bar says
 *             Saving, then Saved, and folds away. Errors your
 *             server sends per field open under those fields
 *             and focus goes to the first
 *   reset     the edits blur back to what's saved
 *
 * Fields are plain objects; onSave gets only the changed values
 * and returns what was stored.
 * ───────────────────────────────────────────────────────── */

export type SettingsValue = string | boolean;
export type SettingsValues = Record<string, SettingsValue>;

type Base = { name: string; label: string; description?: string };

export type SettingsField =
  | (Base & { type: "toggle" })
  | (Base & { type: "choice"; options: { value: string; label: string }[] })
  | (Base & {
      type: "text" | "textarea";
      placeholder?: string;
      /** Shown inside the field before the value, e.g. "relay.app/". */
      prefix?: string;
      /** Textarea height in lines. */
      rows?: number;
      maxLength?: number;
      inputMode?: React.HTMLAttributes<HTMLInputElement>["inputMode"];
      autoComplete?: string;
      /** Return a message to refuse the value before it's sent. */
      validate?: (
        value: string,
        values: SettingsValues,
      ) => string | null | undefined | void;
      /** Asked a moment after typing stops: return null when the value is fine, or why it isn't. */
      check?: (
        value: string,
        options: { signal: AbortSignal },
      ) => Promise<string | null | undefined | void>;
      /** What a passed check says. */
      checkPassed?: string;
    });

export interface SettingsSection {
  title: string;
  description?: string;
  fields: SettingsField[];
}

/** Throw this from onSave to put messages under particular fields. */
export class SettingsFormError extends Error {
  fields: Record<string, string>;
  constructor(message: string, fields: Record<string, string> = {}) {
    super(message);
    this.name = "SettingsFormError";
    this.fields = fields;
  }
}

export interface SettingsFormProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "defaultValue" | "onChange"
> {
  sections: SettingsSection[];
  /** Saved values, controlled. */
  value?: SettingsValues;
  defaultValue?: SettingsValues;
  /** The saved values after every successful save. */
  onValueChange?: (values: SettingsValues) => void;
  /** Saves the changed values. Return what was stored (or nothing); throw to keep the edits and say why. */
  onSave: (
    patch: SettingsValues,
    values: SettingsValues,
  ) => Promise<SettingsValues | void> | SettingsValues | void;
  /** Toggles and choices save the moment they change. */
  autosave?: boolean;
  /** Ask before leaving the page with unsaved edits. */
  warnOnLeave?: boolean;
}

type Check = { state: "checking" | "ok" | "no"; message: string };
type TextField = Extract<SettingsField, { type: "text" | "textarea" }>;

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const EMPTY: SettingsValues = {};
const SHAKE = [
  { transform: "none" },
  { transform: "translateX(-4px)" },
  { transform: "translateX(4px)" },
  { transform: "translateX(-2px)" },
  { transform: "none" },
];

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const without = <T,>(o: Record<string, T>, keys: string[]) =>
  Object.fromEntries(
    Object.entries(o).filter(([k]) => !keys.includes(k)),
  ) as Record<string, T>;
const message = (e: unknown, fallback: string) =>
  e instanceof Error && e.message ? e.message : fallback;

function DrawnCheck({
  drawn,
  reduced,
  className = "size-3.5",
}: {
  drawn: boolean;
  reduced: boolean;
  className?: string;
}) {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      aria-hidden="true"
      className={className}
    >
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="1.8"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 380ms ${EASE} 100ms`
              : "none",
        }}
      />
    </svg>
  );
}

function Spinner({ on }: { on: boolean }) {
  return (
    <span
      className={`size-3 rounded-full border-[1.5px] border-current border-t-transparent motion-reduce:animate-none ${on ? "animate-spin" : ""}`}
    />
  );
}

/** Text that changes by lifting the old line out through a blur and the new one in (sentences don't morph letter by letter). */
function Line({
  text,
  className = "",
  reduced,
}: {
  text: string;
  className?: string;
  reduced: boolean;
}) {
  const [shown, setShown] = React.useState(text);
  const [leaving, setLeaving] = React.useState<{ key: number; text: string }[]>(
    [],
  );
  const key = React.useRef(0);
  const ref = React.useRef<HTMLSpanElement>(null);
  if (text !== shown) {
    if (!reduced && shown)
      setLeaving((l) => [...l, { key: ++key.current, text: shown }]);
    setShown(text);
  }
  React.useLayoutEffect(() => {
    if (reduced || !ref.current || !leaving.length) return;
    ref.current.animate(
      [
        { opacity: 0, transform: "translateY(4px)", filter: "blur(3px)" },
        { opacity: 1, transform: "none", filter: "blur(0px)" },
      ],
      { duration: 320, delay: 60, easing: EASE, fill: "backwards" },
    );
  }, [shown]);
  return (
    <span className={`relative block ${className}`}>
      <span ref={ref} className="block">
        {shown}
      </span>
      {leaving.map((l) => (
        <LeavingLine
          key={l.key}
          text={l.text}
          onDone={() => setLeaving((all) => all.filter((x) => x.key !== l.key))}
        />
      ))}
    </span>
  );
}

function LeavingLine({ text, onDone }: { text: string; onDone: () => void }) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const a = ref.current?.animate(
      [
        { opacity: 1, filter: "blur(0px)" },
        { opacity: 0, transform: "translateY(-4px)", filter: "blur(3px)" },
      ],
      { duration: 200, easing: EASE, fill: "forwards" },
    );
    if (a) a.onfinish = onDone;
    return () => a?.cancel();
  }, []);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute inset-x-0 top-0 block"
    >
      {text}
    </span>
  );
}

/** A block that opens and closes by height, keeping its last children while it closes. */
function Fold({
  open,
  reduced,
  children,
}: {
  open: boolean;
  reduced: boolean;
  children: React.ReactNode;
}) {
  const [kept, setKept] = React.useState(children);
  if (open && kept !== children) setKept(children);
  return (
    <div
      className="grid"
      inert={!open}
      aria-hidden={!open || undefined}
      style={{
        gridTemplateRows: open ? "1fr" : "0fr",
        opacity: open ? 1 : 0,
        transition: reduced
          ? "none"
          : `grid-template-rows 380ms ${EASE}, opacity 260ms ${EASE}`,
      }}
    >
      <div className="min-h-0 overflow-clip">{open ? children : kept}</div>
    </div>
  );
}

/** "Saving" → "Saved" beside a label that saved itself; it fades once it's said it. */
function SavedMark({
  status,
  reduced,
}: {
  status: ActionStatus;
  reduced: boolean;
}) {
  const open = status !== "idle";
  const [label, setLabel] = React.useState("Saving");
  const next =
    status === "pending"
      ? "Saving"
      : status === "success"
        ? "Saved"
        : status === "error"
          ? "Not saved"
          : label;
  if (next !== label) setLabel(next);
  return (
    <span
      aria-hidden="true"
      className={`inline-grid align-baseline text-[11.5px] font-normal ${status === "error" ? "text-red-600 dark:text-red-400" : "text-muted-foreground"}`}
      style={{
        gridTemplateColumns: open ? "1fr" : "0fr",
        opacity: open ? 1 : 0,
        transition: reduced
          ? "none"
          : `grid-template-columns 380ms ${EASE}, opacity ${open ? 240 : 600}ms ${EASE}`,
      }}
    >
      <span className="min-w-0 [clip-path:inset(-4px_0)]">
        <span className="inline-flex items-center gap-1 pl-2 whitespace-nowrap">
          <span className="relative grid size-3 place-items-center">
            <span
              className="absolute inset-0 grid place-items-center"
              style={{
                opacity: status === "pending" ? 1 : 0,
                transition: reduced ? "none" : `opacity 200ms ${EASE}`,
              }}
            >
              <Spinner on={status === "pending"} />
            </span>
            <span
              className="absolute inset-0 grid place-items-center"
              style={{
                opacity: status === "success" ? 1 : 0,
                transition: reduced ? "none" : `opacity 200ms ${EASE}`,
              }}
            >
              <DrawnCheck
                drawn={status === "success"}
                reduced={reduced}
                className="size-3"
              />
            </span>
          </span>
          <TextMorph>{label}</TextMorph>
        </span>
      </span>
    </span>
  );
}

function Label({
  field,
  htmlFor,
  dirty,
  status,
  reduced,
  id,
}: {
  field: SettingsField;
  htmlFor?: string;
  dirty: boolean;
  status: ActionStatus;
  reduced: boolean;
  id: string;
}) {
  const Tag = htmlFor ? "label" : "span";
  return (
    <span className="block min-w-0">
      <Tag
        {...(htmlFor ? { htmlFor } : {})}
        id={`${id}-label`}
        className="flex items-center whitespace-nowrap text-[13px] font-medium tracking-[-0.01em]"
      >
        {field.label}
        {/* A dot that swells in beside a label whose value has changed but isn't saved. */}
        <span
          aria-hidden="true"
          className="ml-1.5 size-1.5 shrink-0 rounded-full bg-primary"
          style={{
            transform: dirty ? "scale(1)" : "scale(0)",
            opacity: dirty ? 1 : 0,
            transition: reduced
              ? "none"
              : `transform 420ms ${dirty ? THROW : EASE}, opacity 200ms ${EASE}`,
          }}
        />
        <SavedMark status={status} reduced={reduced} />
      </Tag>
      {field.description && (
        <span
          id={`${id}-desc`}
          className="mt-0.5 block text-[12px] leading-[1.45] text-muted-foreground"
        >
          {field.description}
        </span>
      )}
    </span>
  );
}

function Switch({
  on,
  onToggle,
  labelledBy,
  describedBy,
  shake,
  reduced,
}: {
  on: boolean;
  onToggle: () => void;
  labelledBy: string;
  describedBy?: string;
  shake: number;
  reduced: boolean;
}) {
  const ref = React.useRef<HTMLButtonElement>(null);
  React.useEffect(() => {
    if (shake && !reduced)
      ref.current?.animate(SHAKE, { duration: 380, easing: "ease-out" });
  }, [shake, reduced]);
  return (
    <button
      ref={ref}
      type="button"
      role="switch"
      aria-checked={on}
      aria-labelledby={labelledBy}
      aria-describedby={describedBy}
      onClick={onToggle}
      className={`relative h-5 w-9 shrink-0 cursor-pointer rounded-full transition-[background-color,box-shadow] duration-300 ${FOCUS} ${on ? "bg-primary" : "bg-muted shadow-[inset_0_0_0_1px_var(--border)]"}`}
    >
      <span
        aria-hidden="true"
        className="absolute top-0.5 left-0.5 size-4 rounded-full bg-background shadow-[0_0_0_1px_var(--border)]"
        style={{
          transform: on ? "translateX(16px)" : "none",
          transition: reduced ? "none" : `transform 420ms ${THROW}`,
        }}
      />
    </button>
  );
}

function Choice({
  field,
  value,
  onChange,
  labelledBy,
  shake,
  reduced,
}: {
  field: Extract<SettingsField, { type: "choice" }>;
  value: string;
  onChange: (v: string) => void;
  labelledBy: string;
  shake: number;
  reduced: boolean;
}) {
  const wrap = React.useRef<HTMLDivElement>(null);
  const refs = React.useRef<(HTMLButtonElement | null)[]>([]);
  const [thumb, setThumb] = React.useState({ left: 0, width: 0, ready: false });
  const index = Math.max(
    0,
    field.options.findIndex((o) => o.value === value),
  );

  React.useLayoutEffect(() => {
    const measure = () => {
      const b = refs.current[index];
      if (!b) return;
      setThumb((t) =>
        t.left === b.offsetLeft && t.width === b.offsetWidth && t.ready
          ? t
          : { left: b.offsetLeft, width: b.offsetWidth, ready: t.width > 0 },
      );
    };
    measure();
    const observer = new ResizeObserver(measure);
    if (wrap.current) observer.observe(wrap.current);
    return () => observer.disconnect();
  }, [index]);

  React.useEffect(() => {
    if (shake && !reduced)
      wrap.current?.animate(SHAKE, { duration: 380, easing: "ease-out" });
  }, [shake, reduced]);

  return (
    <div
      ref={wrap}
      role="radiogroup"
      aria-labelledby={labelledBy}
      className="relative inline-flex shrink-0 rounded-full p-0.5 shadow-[inset_0_0_0_1px_var(--border)]"
    >
      <span
        aria-hidden="true"
        className="absolute top-0.5 bottom-0.5 left-0 rounded-full bg-accent shadow-[inset_0_0_0_1px_var(--border)]"
        style={{
          width: thumb.width,
          transform: `translateX(${thumb.left}px)`,
          transition:
            thumb.ready && !reduced
              ? `transform 460ms ${THROW}, width 360ms ${EASE}`
              : "none",
        }}
      />
      {field.options.map((o, i) => {
        const on = i === index;
        return (
          <button
            key={o.value}
            ref={(el) => {
              refs.current[i] = el;
            }}
            type="button"
            role="radio"
            aria-checked={on}
            tabIndex={on ? 0 : -1}
            onClick={() => onChange(o.value)}
            onKeyDown={(e) => {
              const step =
                e.key === "ArrowRight" || e.key === "ArrowDown"
                  ? 1
                  : e.key === "ArrowLeft" || e.key === "ArrowUp"
                    ? -1
                    : 0;
              if (!step) return;
              e.preventDefault();
              const next =
                (i + step + field.options.length) % field.options.length;
              onChange(field.options[next].value);
              refs.current[next]?.focus();
            }}
            className={`relative h-7 cursor-pointer rounded-full px-3 text-[12px] font-medium transition-colors duration-300 ${FOCUS} ${on ? "text-foreground" : "text-muted-foreground hover:text-foreground"}`}
          >
            {o.label}
          </button>
        );
      })}
    </div>
  );
}

function TextInput({
  field,
  id,
  value,
  error,
  check,
  onChange,
  reduced,
  register,
}: {
  field: TextField;
  id: string;
  value: string;
  error?: string;
  check?: Check;
  onChange: (v: string) => void;
  reduced: boolean;
  register: (
    name: string,
    el: HTMLInputElement | HTMLTextAreaElement | null,
  ) => void;
}) {
  const ring =
    error || check?.state === "no"
      ? "shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_45%,transparent)]"
      : "shadow-[inset_0_0_0_1px_var(--border)] focus-within:shadow-[inset_0_0_0_1px_var(--ring)]";
  const common = {
    id,
    name: field.name,
    value,
    placeholder: field.placeholder,
    maxLength: field.maxLength,
    "aria-invalid": Boolean(error || check?.state === "no") || undefined,
    "aria-describedby": `${id}-desc ${id}-note`,
    onChange: (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) =>
      onChange(e.target.value),
  };
  const text =
    "bg-transparent text-[16px] text-foreground outline-none placeholder:text-muted-foreground/70 [@media(pointer:fine)]:text-[13.5px]";
  return (
    <div
      data-field-ring=""
      className={`mt-2 rounded-[10px] transition-shadow duration-200 ${ring}`}
    >
      {field.type === "textarea" ? (
        <textarea
          ref={(el) => register(field.name, el)}
          rows={field.rows ?? 3}
          {...common}
          className={`block w-full resize-none px-3 py-2 leading-[1.5] ${text}`}
        />
      ) : (
        <div className="flex h-9 items-center px-3">
          {field.prefix && (
            <span
              aria-hidden="true"
              className="shrink-0 text-[13.5px] text-muted-foreground select-none"
            >
              {field.prefix}
            </span>
          )}
          <input
            ref={(el) => register(field.name, el)}
            type="text"
            inputMode={field.inputMode}
            autoComplete={field.autoComplete ?? "off"}
            {...common}
            className={`h-full min-w-0 flex-1 ${text}`}
          />
          {field.check && (
            <span
              aria-hidden="true"
              className="relative ml-2 grid size-3.5 shrink-0 place-items-center"
            >
              <span
                className="absolute inset-0 grid place-items-center text-muted-foreground"
                style={{
                  opacity: check?.state === "checking" ? 1 : 0,
                  transition: reduced ? "none" : `opacity 200ms ${EASE}`,
                }}
              >
                <Spinner on={check?.state === "checking"} />
              </span>
              <span
                className="absolute inset-0 grid place-items-center text-emerald-600 dark:text-emerald-400"
                style={{
                  opacity: check?.state === "ok" && !error ? 1 : 0,
                  transition: reduced ? "none" : `opacity 200ms ${EASE}`,
                }}
              >
                <DrawnCheck
                  drawn={check?.state === "ok" && !error}
                  reduced={reduced}
                />
              </span>
            </span>
          )}
        </div>
      )}
    </div>
  );
}

export function SettingsForm({
  sections,
  value,
  defaultValue = EMPTY,
  onValueChange,
  onSave,
  autosave = true,
  warnOnLeave = true,
  className = "",
  ...props
}: SettingsFormProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const [inner, setInner] = React.useState(defaultValue);
  const saved = value ?? inner;
  const [edits, setEdits] = React.useState<SettingsValues>({});
  const [status, setStatus] = React.useState<Record<string, ActionStatus>>({});
  const [errors, setErrors] = React.useState<Record<string, string>>({});
  const [shakes, setShakes] = React.useState<Record<string, number>>({});
  const [checks, setChecks] = React.useState<Record<string, Check>>({});
  const [bar, setBar] = React.useState<ActionStatus>("idle");
  const [barNote, setBarNote] = React.useState<string | null>(null);
  const [lastCount, setLastCount] = React.useState(1);
  const [announce, setAnnounce] = React.useState("");
  const rootRef = React.useRef<HTMLDivElement>(null);
  const inputs = React.useRef(
    new Map<string, HTMLInputElement | HTMLTextAreaElement>(),
  );
  const runs = React.useRef(new Map<string, number>());
  const checkRuns = React.useRef(
    new Map<string, { timer: number; ctrl?: AbortController }>(),
  );
  const latest = React.useRef({ saved, edits });
  React.useLayoutEffect(() => {
    latest.current = { saved, edits };
  });

  const fields = React.useMemo(
    () => sections.flatMap((s) => s.fields),
    [sections],
  );
  const instant = (f: SettingsField) =>
    autosave && (f.type === "toggle" || f.type === "choice");
  const values = { ...saved, ...edits };
  const dirty = fields.filter(
    (f) =>
      !instant(f) &&
      f.name in edits &&
      edits[f.name] !== (saved[f.name] ?? (f.type === "toggle" ? false : "")),
  );
  const count = dirty.length;
  if (count && count !== lastCount) setLastCount(count);
  const barOpen = count > 0 || bar === "pending" || bar === "success";

  const commitSaved = (next: SettingsValues) => {
    if (value === undefined) setInner(next);
    onValueChange?.(next);
  };

  const register = React.useCallback(
    (name: string, el: HTMLInputElement | HTMLTextAreaElement | null) => {
      if (el) inputs.current.set(name, el);
      else inputs.current.delete(name);
    },
    [],
  );

  // Toggles and choices: saved the moment they change; a newer change wins over an older answer.
  const saveNow = async (f: SettingsField, v: SettingsValue) => {
    const run = (runs.current.get(f.name) ?? 0) + 1;
    runs.current.set(f.name, run);
    setEdits((e) => ({ ...e, [f.name]: v }));
    setStatus((s) => ({ ...s, [f.name]: "pending" }));
    setErrors((e) => without(e, [f.name]));
    try {
      const patch = { [f.name]: v };
      const stored = await onSave(patch, { ...latest.current.saved, ...patch });
      if (runs.current.get(f.name) !== run) return;
      commitSaved({ ...latest.current.saved, ...patch, ...(stored ?? {}) });
      setEdits((e) => without(e, [f.name]));
      setStatus((s) => ({ ...s, [f.name]: "success" }));
      setAnnounce(`${f.label} saved.`);
      window.setTimeout(
        () =>
          setStatus((s) =>
            runs.current.get(f.name) === run && s[f.name] === "success"
              ? { ...s, [f.name]: "idle" }
              : s,
          ),
        1600,
      );
    } catch (e) {
      if (runs.current.get(f.name) !== run) return;
      const why =
        e instanceof SettingsFormError
          ? (e.fields[f.name] ?? e.message)
          : message(e, `${f.label} couldn't be saved.`);
      setEdits((x) => without(x, [f.name]));
      setStatus((s) => ({ ...s, [f.name]: "error" }));
      setErrors((x) => ({ ...x, [f.name]: why }));
      setShakes((x) => ({ ...x, [f.name]: (x[f.name] ?? 0) + 1 }));
      setAnnounce(why);
      window.setTimeout(
        () =>
          setStatus((s) =>
            runs.current.get(f.name) === run && s[f.name] === "error"
              ? { ...s, [f.name]: "idle" }
              : s,
          ),
        2400,
      );
    }
  };

  const edit = (f: TextField, v: string) => {
    setEdits((e) => ({ ...e, [f.name]: v }));
    setErrors((e) => without(e, [f.name]));
    setBarNote(null);
    if (bar === "error" || bar === "success") setBar("idle");
    if (!f.check) return;
    const prev = checkRuns.current.get(f.name);
    if (prev) {
      window.clearTimeout(prev.timer);
      prev.ctrl?.abort();
    }
    if (!v || v === saved[f.name]) {
      setChecks((c) => without(c, [f.name]));
      return;
    }
    const entry: { timer: number; ctrl?: AbortController } = { timer: 0 };
    entry.timer = window.setTimeout(async () => {
      const ctrl = new AbortController();
      entry.ctrl = ctrl;
      setChecks((c) => ({
        ...c,
        [f.name]: { state: "checking", message: "Checking" },
      }));
      try {
        const why = await f.check!(v, { signal: ctrl.signal });
        if (ctrl.signal.aborted) return;
        setChecks((c) => ({
          ...c,
          [f.name]: why
            ? { state: "no", message: why }
            : { state: "ok", message: f.checkPassed ?? "Available" },
        }));
      } catch {
        if (!ctrl.signal.aborted) setChecks((c) => without(c, [f.name]));
      }
    }, 450);
    checkRuns.current.set(f.name, entry);
  };

  const focusFirst = (names: string[]) => {
    const first = fields.find((f) => names.includes(f.name));
    const el = first && inputs.current.get(first.name);
    if (!el) return;
    el.focus({ preventScroll: true });
    el.scrollIntoView({
      block: "nearest",
      behavior: reduced ? "auto" : "smooth",
    });
  };

  const save = async () => {
    if (!count || bar === "pending") return;
    const problems: Record<string, string> = {};
    for (const f of dirty) {
      if (f.type !== "text" && f.type !== "textarea") continue;
      const v = String(values[f.name] ?? "");
      const why =
        f.validate?.(v, values) ||
        (checks[f.name]?.state === "no" ? checks[f.name].message : null);
      if (why) problems[f.name] = why;
    }
    if (Object.keys(problems).length) {
      setErrors((e) => ({ ...e, ...problems }));
      setShakes((s) => ({
        ...s,
        ...Object.fromEntries(
          Object.keys(problems).map((k) => [k, (s[k] ?? 0) + 1]),
        ),
      }));
      setBar("error");
      setBarNote(
        Object.keys(problems).length === 1
          ? "One field needs a look."
          : `${Object.keys(problems).length} fields need a look.`,
      );
      focusFirst(Object.keys(problems));
      return;
    }
    const patch = Object.fromEntries(
      dirty.map((f) => [f.name, values[f.name]]),
    );
    setBar("pending");
    setBarNote(null);
    try {
      const stored = await onSave(patch, { ...latest.current.saved, ...patch });
      commitSaved({ ...latest.current.saved, ...patch, ...(stored ?? {}) });
      // Keep edits made while it was saving.
      setEdits((e) =>
        Object.fromEntries(
          Object.entries(e).filter(([k, v]) => !(k in patch) || v !== patch[k]),
        ),
      );
      setChecks((c) => without(c, Object.keys(patch)));
      setBar("success");
      setAnnounce("Changes saved.");
    } catch (e) {
      const fieldErrors = e instanceof SettingsFormError ? e.fields : {};
      setErrors((x) => ({ ...x, ...fieldErrors }));
      setShakes((s) => ({
        ...s,
        ...Object.fromEntries(
          Object.keys(fieldErrors).map((k) => [k, (s[k] ?? 0) + 1]),
        ),
      }));
      setBar("error");
      const why = message(e, "Your changes couldn't be saved.");
      setBarNote(why);
      setAnnounce(why);
      focusFirst(Object.keys(fieldErrors));
    }
  };

  const reset = () => {
    const names = dirty.map((f) => f.name);
    setEdits((e) => without(e, names));
    setErrors((e) => without(e, names));
    setChecks((c) => without(c, names));
    setBar("idle");
    setBarNote(null);
    if (!reduced)
      for (const n of names)
        inputs.current.get(n)?.animate(
          [
            { opacity: 0.2, filter: "blur(3px)" },
            { opacity: 1, filter: "blur(0px)" },
          ],
          { duration: 420, easing: EASE },
        );
    setAnnounce("Changes discarded.");
  };

  // Saved: the bar says so for a moment, then folds away.
  React.useEffect(() => {
    if (bar !== "success") return;
    const timer = window.setTimeout(() => setBar("idle"), 1100);
    return () => window.clearTimeout(timer);
  }, [bar]);

  React.useEffect(() => {
    if (!warnOnLeave || !count) return;
    const onLeave = (e: BeforeUnloadEvent) => {
      e.preventDefault();
      e.returnValue = "";
    };
    window.addEventListener("beforeunload", onLeave);
    return () => window.removeEventListener("beforeunload", onLeave);
  }, [warnOnLeave, count]);

  React.useEffect(
    () => () =>
      checkRuns.current.forEach(
        (c) => (window.clearTimeout(c.timer), c.ctrl?.abort()),
      ),
    [],
  );

  const shown = count || lastCount;
  const left =
    bar === "success"
      ? "Changes saved"
      : (barNote ?? `${shown} unsaved ${shown === 1 ? "change" : "changes"}`);

  return (
    <div
      ref={rootRef}
      className={`@container relative w-full rounded-[22px] border border-border bg-background text-foreground ${className}`}
      onKeyDown={(e) => {
        if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "s") {
          e.preventDefault();
          save();
        }
      }}
      {...props}
    >
      {sections.map((section, si) => (
        <section
          key={section.title}
          aria-labelledby={`${id}-s${si}`}
          className="grid gap-4 border-t border-border px-4 py-4 first:border-t-0 @xl:grid-cols-[minmax(0,180px)_1fr] @xl:gap-8 @md:px-5 @md:py-5"
        >
          <div className="min-w-0">
            <h3
              id={`${id}-s${si}`}
              className="text-[14px] font-medium tracking-[-0.01em]"
            >
              {section.title}
            </h3>
            {section.description && (
              <p className="mt-0.5 text-[12px] leading-[1.45] text-muted-foreground">
                {section.description}
              </p>
            )}
          </div>
          {/* Its own container: a choice sits beside its label only when this column has room. */}
          <div className="@container/fields min-w-0 space-y-4">
            {section.fields.map((f) => {
              const fid = `${id}-${f.name}`;
              const st = status[f.name] ?? "idle";
              const err = errors[f.name];
              const isDirty = dirty.includes(f);
              const check = checks[f.name];
              const note = err ?? (check ? check.message : null);
              const noteTone =
                err || check?.state === "no"
                  ? "text-red-600 dark:text-red-400"
                  : check?.state === "ok"
                    ? "text-emerald-600 dark:text-emerald-400"
                    : "text-muted-foreground";
              return (
                <div key={f.name}>
                  {f.type === "toggle" ? (
                    <div className="flex items-start justify-between gap-4">
                      <Label
                        field={f}
                        dirty={isDirty}
                        status={st}
                        reduced={reduced}
                        id={fid}
                      />
                      <span className="pt-px">
                        <Switch
                          on={Boolean(values[f.name])}
                          onToggle={() =>
                            instant(f)
                              ? saveNow(f, !values[f.name])
                              : setEdits((e) => ({
                                  ...e,
                                  [f.name]: !values[f.name],
                                }))
                          }
                          labelledBy={`${fid}-label`}
                          describedBy={
                            f.description ? `${fid}-desc` : undefined
                          }
                          shake={shakes[f.name] ?? 0}
                          reduced={reduced}
                        />
                      </span>
                    </div>
                  ) : f.type === "choice" ? (
                    <div className="flex flex-col items-start gap-2 @min-[26rem]/fields:flex-row @min-[26rem]/fields:justify-between @min-[26rem]/fields:gap-4">
                      <Label
                        field={f}
                        dirty={isDirty}
                        status={st}
                        reduced={reduced}
                        id={fid}
                      />
                      <Choice
                        field={f}
                        value={String(
                          values[f.name] ?? f.options[0]?.value ?? "",
                        )}
                        onChange={(v) =>
                          v === values[f.name]
                            ? undefined
                            : instant(f)
                              ? saveNow(f, v)
                              : setEdits((e) => ({ ...e, [f.name]: v }))
                        }
                        labelledBy={`${fid}-label`}
                        shake={shakes[f.name] ?? 0}
                        reduced={reduced}
                      />
                    </div>
                  ) : (
                    <>
                      <Label
                        field={f}
                        htmlFor={fid}
                        dirty={isDirty}
                        status={st}
                        reduced={reduced}
                        id={fid}
                      />
                      <TextInput
                        field={f}
                        id={fid}
                        value={String(values[f.name] ?? "")}
                        error={err}
                        check={check}
                        onChange={(v) => edit(f, v)}
                        reduced={reduced}
                        register={register}
                      />
                      {f.maxLength && f.type === "textarea" && (
                        <p
                          aria-hidden="true"
                          className="mt-1 flex justify-end text-[11px] text-muted-foreground tabular-nums"
                        >
                          <NumberRoll
                            value={String(values[f.name] ?? "").length}
                          />
                          &nbsp;/ {f.maxLength}
                        </p>
                      )}
                    </>
                  )}
                  <div id={`${fid}-note`}>
                    <Fold open={Boolean(note)} reduced={reduced}>
                      <p
                        className={`flex items-center gap-1 pt-1.5 text-[11.5px] ${noteTone}`}
                      >
                        <Line text={note ?? ""} reduced={reduced} />
                      </p>
                    </Fold>
                  </div>
                  {f.type !== "toggle" && f.type !== "choice" && (
                    <ShakeOn
                      getTarget={() => inputs.current.get(f.name)}
                      count={shakes[f.name] ?? 0}
                      reduced={reduced}
                    />
                  )}
                </div>
              );
            })}
          </div>
        </section>
      ))}

      {/* One bar for every unsaved edit; it rises from the foot of the form and stays in view while you scroll. */}
      <div className="sticky bottom-0 z-10">
        <Fold open={barOpen} reduced={reduced}>
          <div
            className="flex items-center gap-3 rounded-b-[21px] border-t border-border bg-background px-4 py-3 @md:px-5"
            role="group"
            aria-label="Unsaved changes"
          >
            <p
              className={`min-w-0 flex-1 text-[12.5px] ${bar === "error" ? "text-red-600 dark:text-red-400" : "text-muted-foreground"}`}
            >
              {bar !== "success" && !barNote ? (
                <span className="flex items-baseline tabular-nums">
                  <NumberRoll value={shown} />
                  &nbsp;
                  <TextMorph>
                    {shown === 1 ? "unsaved change" : "unsaved changes"}
                  </TextMorph>
                </span>
              ) : (
                <Line text={left} reduced={reduced} />
              )}
            </p>
            <button
              type="button"
              onClick={reset}
              disabled={bar === "pending" || !count}
              className={`h-7 cursor-pointer rounded-full px-2.5 text-[12px] font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground disabled:cursor-default disabled:opacity-50 disabled:hover:bg-transparent ${FOCUS}`}
            >
              Reset
            </button>
            <StatusButton
              size="sm"
              status={bar}
              labels={{
                idle: "Save",
                pending: "Saving",
                success: "Saved",
                error: "Try again",
              }}
              onClick={save}
            />
          </div>
        </Fold>
      </div>

      <span className="sr-only" role="status">
        {announce}
      </span>
    </div>
  );
}

/** Shakes an input when its count goes up (a refused value). */
function ShakeOn({
  getTarget,
  count,
  reduced,
}: {
  getTarget: () => HTMLElement | undefined;
  count: number;
  reduced: boolean;
}) {
  React.useEffect(() => {
    if (count && !reduced)
      getTarget()
        ?.closest("[data-field-ring]")
        ?.animate(SHAKE, { duration: 380, easing: "ease-out" });
  }, [count, getTarget, reduced]);
  return null;
}

"use client";

import * as React from "react";
import { MODAL_ROOT, SCRIM, useModal } from "./modal";
import {
  EASE_OUT,
  INTERACTION_FOCUS,
  INTERACTION_PRESS,
  projectInertia,
  rubberBand,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * SHEET: a panel that slides in from an edge
 *
 *   open     the page fades back; the panel slides in from its
 *            edge (right, left or bottom) and settles
 *   drag     grab the panel's header (or the bottom sheet's grip)
 *            and pull it toward its edge: it follows 1:1, resists
 *            the other way, and a throw (projected from release
 *            speed) or a pull past a third closes it; otherwise
 *            it springs back
 *   close    Escape, the ✕ or the veil; focus returns to what
 *            opened it
 * ───────────────────────────────────────────────────────── */

// The curve sheets slide on: a soft start and a long settle, like the system drawers on phones.
const DRAWER = "cubic-bezier(0.32, 0.72, 0, 1)";

export interface SheetProps {
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  trigger?: React.ReactElement<React.HTMLAttributes<HTMLElement>>;
  side?: "right" | "left" | "bottom";
  title: React.ReactNode;
  description?: React.ReactNode;
  children?:
    React.ReactNode | ((api: { close: () => void }) => React.ReactNode);
  footer?: React.ReactNode | ((api: { close: () => void }) => React.ReactNode);
  /** Width of a side sheet in px. */
  width?: number;
  className?: string;
}

export function Sheet({
  open: controlled,
  defaultOpen = false,
  onOpenChange,
  trigger,
  side = "right",
  title,
  description,
  children,
  footer,
  width = 400,
  className = "",
}: SheetProps) {
  const reduced = useInteractionReducedMotion();
  const [own, setOwn] = React.useState(defaultOpen);
  const open = controlled ?? own;
  const setOpen = (next: boolean) => {
    if (controlled === undefined) setOwn(next);
    onOpenChange?.(next);
  };
  const close = () => setOpen(false);
  const { dialog, mounted, shown } = useModal(open, close, 320);
  const panel = React.useRef<HTMLDivElement>(null);
  const drag = React.useRef<{
    start: number;
    last: number;
    t: number;
    v: number;
    d: number;
    size: number;
    moved: boolean;
  } | null>(null);
  const titleId = React.useId();
  const bottom = side === "bottom";
  // +1 when moving toward the edge closes it.
  const sign = side === "left" ? -1 : 1;
  const hidden = bottom
    ? "translate3d(0,100%,0)"
    : `translate3d(${sign * 100}%,0,0)`;

  const write = (d: number, animate: boolean) => {
    const el = panel.current;
    if (!el) return;
    el.style.transition = animate ? `transform 420ms ${DRAWER}` : "none";
    el.style.transform = d
      ? bottom
        ? `translate3d(0,${d}px,0)`
        : `translate3d(${sign * d}px,0,0)`
      : "";
  };

  const onPointerDown = (e: React.PointerEvent) => {
    if (
      e.button !== 0 ||
      (e.target as HTMLElement).closest("button, a, input, textarea, select")
    )
      return;
    const el = panel.current;
    if (!el) return;
    const at = bottom ? e.clientY : e.clientX * sign;
    drag.current = {
      start: at,
      last: at,
      t: performance.now(),
      v: 0,
      d: 0,
      size: bottom ? el.offsetHeight : el.offsetWidth,
      moved: false,
    };
    (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
  };
  const onPointerMove = (e: React.PointerEvent) => {
    const g = drag.current;
    if (!g) return;
    const at = bottom ? e.clientY : e.clientX * sign;
    if (!g.moved && Math.abs(at - g.start) < 6) return;
    if (!g.moved) {
      g.moved = true;
      g.start = at; // no jump when the drag takes over from the slop
    }
    const now = performance.now();
    g.v = (at - g.last) / Math.max(1, now - g.t);
    g.last = at;
    g.t = now;
    const raw = at - g.start;
    g.d = raw >= 0 ? raw : rubberBand(raw, g.size, 0.3);
    write(g.d, false);
  };
  const onPointerUp = () => {
    const g = drag.current;
    drag.current = null;
    if (!g || !g.moved) return;
    // Closing leaves the panel where the finger let go; the slide out carries on from there.
    if (projectInertia(g.d, g.v, 0.12) > g.size / 3) close();
    else write(0, true);
  };

  const footerNode = typeof footer === "function" ? footer({ close }) : footer;
  const grip = {
    onPointerDown,
    onPointerMove,
    onPointerUp,
    onPointerCancel: onPointerUp,
  };

  return (
    <>
      {trigger &&
        React.cloneElement(trigger, {
          "aria-haspopup": "dialog",
          onClick: (e: React.MouseEvent<HTMLElement>) => {
            trigger.props.onClick?.(e);
            setOpen(true);
          },
        })}
      {mounted && (
        <dialog ref={dialog} aria-labelledby={titleId} className={MODAL_ROOT}>
          <div
            className={SCRIM}
            onClick={close}
            style={{
              opacity: shown ? 1 : 0,
              transition: `opacity ${shown ? 300 : 240}ms ${EASE_OUT}`,
            }}
          />
          <div
            className={`absolute flex ${bottom ? "inset-x-0 bottom-0 justify-center" : `inset-y-0 ${side === "left" ? "left-0" : "right-0"}`} pointer-events-none p-2`}
            style={{ width: bottom ? undefined : `min(${width}px, 100vw)` }}
          >
            <div
              className="pointer-events-auto flex size-full will-change-transform"
              style={{
                transform: shown || reduced ? "none" : hidden,
                opacity: reduced ? (shown ? 1 : 0) : 1,
                transition: reduced
                  ? "opacity 160ms ease-out"
                  : `transform ${shown ? 500 : 320}ms ${DRAWER}`,
              }}
            >
              <div
                ref={panel}
                data-modal-panel=""
                tabIndex={-1}
                className={`flex w-full flex-col bg-background shadow-[0_0_0_1px_var(--border)] outline-none ${bottom ? "max-h-[85dvh] max-w-[640px] rounded-[22px]" : "h-full rounded-[20px]"} ${className}`}
              >
                {bottom && (
                  <div
                    {...grip}
                    className="flex cursor-grab touch-none justify-center pb-1 pt-2.5 active:cursor-grabbing"
                  >
                    <span className="h-1 w-9 rounded-full bg-border" />
                  </div>
                )}
                <div
                  {...grip}
                  className={`flex touch-none items-start gap-4 px-5 ${bottom ? "pt-2" : "cursor-grab pt-5 active:cursor-grabbing"} pb-3`}
                >
                  <div className="flex min-w-0 flex-1 flex-col gap-1">
                    <h2
                      id={titleId}
                      className="text-[16px] font-semibold tracking-[-0.01em] text-foreground"
                    >
                      {title}
                    </h2>
                    {description && (
                      <p className="text-[13.5px] leading-relaxed text-muted-foreground">
                        {description}
                      </p>
                    )}
                  </div>
                  <button
                    type="button"
                    aria-label="Close"
                    onClick={close}
                    className={`-mr-1.5 flex size-8 shrink-0 items-center justify-center rounded-full text-muted-foreground cursor-pointer hover:bg-accent hover:text-foreground ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`}
                  >
                    <svg viewBox="0 0 16 16" fill="none" className="size-3.5">
                      <path
                        d="M4 4l8 8M12 4l-8 8"
                        stroke="currentColor"
                        strokeWidth="1.6"
                        strokeLinecap="round"
                      />
                    </svg>
                  </button>
                </div>
                <div className="min-h-0 flex-1 overflow-y-auto overscroll-contain px-5 pb-4 text-[13.5px] leading-relaxed text-foreground">
                  {typeof children === "function"
                    ? children({ close })
                    : children}
                </div>
                {footerNode !== undefined && (
                  <div className="flex flex-col-reverse gap-2 border-t border-border px-5 py-4 sm:flex-row sm:justify-end">
                    {footerNode}
                  </div>
                )}
              </div>
            </div>
          </div>
        </dialog>
      )}
    </>
  );
}

export default Sheet;

"use client";

import * as React from "react";
import {
  EASE_OUT,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * SKELETON: the shape of what's coming
 *
 *   wait     muted shapes with one soft band of light sweeping
 *            across them all together, left to right
 *   arrive   with <Skeleton.Swap loading>, the shapes fade out as
 *            the real content rises out of a 4px blur in their
 *            place, so nothing pops; the box eases to the
 *            content's height
 * ───────────────────────────────────────────────────────── */

export interface SkeletonProps extends React.HTMLAttributes<HTMLSpanElement> {
  /** "line" is text height, "circle" a round avatar, "block" a box. */
  shape?: "line" | "circle" | "block";
  width?: number | string;
  height?: number | string;
}

export function Skeleton({
  shape = "line",
  width,
  height,
  className = "",
  style,
  ...props
}: SkeletonProps) {
  const reduced = useInteractionReducedMotion();
  const dims =
    shape === "circle"
      ? { width: width ?? 36, height: height ?? width ?? 36 }
      : {
          width: width ?? "100%",
          height: height ?? (shape === "line" ? 12 : 80),
        };
  return (
    <span
      aria-hidden="true"
      className={`relative block overflow-hidden bg-muted ${shape === "circle" ? "rounded-full" : shape === "line" ? "rounded-full" : "rounded-[12px]"} ${className}`}
      style={{ ...dims, ...style }}
      {...props}
    >
      {!reduced && (
        <span className="absolute inset-0 [animation:ui-skeleton_1.6s_cubic-bezier(0.4,0,0.2,1)_infinite] bg-[linear-gradient(90deg,transparent,color-mix(in_oklab,var(--background)_55%,transparent),transparent)]" />
      )}
    </span>
  );
}

export interface SkeletonSwapProps {
  loading: boolean;
  /** The skeleton shown while loading. */
  fallback: React.ReactNode;
  children: React.ReactNode;
  /** Accessible text while loading. */
  label?: string;
  className?: string;
}

/** Holds a skeleton while `loading`, then hands over to the content in one motion. */
export function SkeletonSwap({
  loading,
  fallback,
  children,
  label = "Loading",
  className = "",
}: SkeletonSwapProps) {
  const reduced = useInteractionReducedMotion();
  const inner = React.useRef<HTMLDivElement>(null);
  const [height, setHeight] = React.useState<number | null>(null);
  // True for the first frames after loading ends, so the content starts from its hidden pose.
  const [arriving, setArriving] = React.useState(false);
  const [wasLoading, setWasLoading] = React.useState(loading);
  if (wasLoading !== loading) {
    setWasLoading(loading);
    setArriving(!loading);
  }

  React.useEffect(() => {
    if (!arriving) return;
    let second = 0;
    const first = requestAnimationFrame(() => {
      second = requestAnimationFrame(() => setArriving(false));
    });
    return () => {
      cancelAnimationFrame(first);
      cancelAnimationFrame(second);
    };
  }, [arriving]);

  // The box eases between the skeleton's height and the content's.
  React.useLayoutEffect(() => {
    const el = inner.current;
    if (!el) return;
    const measure = () =>
      setHeight((h) => (h === el.offsetHeight ? h : el.offsetHeight));
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  const t = (ms: number, delay = 0) =>
    reduced ? "none" : `${ms}ms ${EASE_OUT} ${delay}ms`;

  return (
    <div
      aria-busy={loading || undefined}
      className={`relative overflow-hidden ${className}`}
      style={{
        height: height ?? undefined,
        transition: reduced ? "none" : `height 360ms ${EASE_OUT}`,
      }}
    >
      {loading && (
        <span className="sr-only" role="status">
          {label}
        </span>
      )}
      <div ref={inner}>
        {loading ? (
          fallback
        ) : (
          <div
            style={{
              opacity: arriving ? 0 : 1,
              filter: arriving && !reduced ? "blur(4px)" : "blur(0px)",
              translate: arriving && !reduced ? "0 4px" : "0 0",
              transition: arriving
                ? "none"
                : `opacity ${t(300, 40)}, filter ${t(300, 40)}, translate ${t(420, 40)}`,
            }}
          >
            {children}
          </div>
        )}
      </div>
    </div>
  );
}

