"use client";

import * as React from "react";
import {
  EASE_OUT,
  EASE_THROW,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * SLIDER: one value or a range
 *
 *   click    a press on the track throws the nearest thumb there
 *            (slight overshoot), the fill following it
 *   drag     then it tracks the finger 1:1, snapped to `step`;
 *            two thumbs never cross
 *   bubble   the value rises out of the thumb while you drag or
 *            move it by keyboard, and sinks back after
 *   keys     arrows step, Page Up/Down step ten, Home/End jump
 *
 * Vertical page scroll still works when a drag starts on it.
 * ───────────────────────────────────────────────────────── */

export interface SliderProps {
  /** One number, or two for a range. */
  value?: number | number[];
  defaultValue?: number | number[];
  onValueChange?: (value: number[]) => void;
  /** Called once when a drag or key press ends. */
  onValueCommit?: (value: number[]) => void;
  min?: number;
  max?: number;
  step?: number;
  /** How the bubble and screen readers say a value. */
  format?: (value: number) => string;
  /** Accessible name; for a range, the thumbs get "… minimum" and "… maximum". */
  label: string;
  disabled?: boolean;
  className?: string;
}

const toArray = (v: number | number[] | undefined, fallback: number[]) =>
  v === undefined ? fallback : Array.isArray(v) ? v : [v];

export function Slider({
  value,
  defaultValue,
  onValueChange,
  onValueCommit,
  min = 0,
  max = 100,
  step = 1,
  format = (v) => String(v),
  label,
  disabled,
  className = "",
}: SliderProps) {
  const reduced = useInteractionReducedMotion();
  const trackRef = React.useRef<HTMLDivElement>(null);
  const [own, setOwn] = React.useState(() => toArray(defaultValue, [min]));
  const values = toArray(value, own);
  const [active, setActive] = React.useState<number | null>(null);
  const [mode, setMode] = React.useState<"rest" | "throw" | "drag">("rest");
  const [bubble, setBubble] = React.useState<number | null>(null);
  const latest = React.useRef(values);
  React.useLayoutEffect(() => {
    latest.current = values;
  });

  React.useEffect(() => {
    if (bubble === null || active !== null) return;
    const timer = window.setTimeout(() => setBubble(null), 700);
    return () => window.clearTimeout(timer);
  }, [bubble, active]);

  const snap = (v: number) => {
    const stepped = Math.round((v - min) / step) * step + min;
    return Math.min(max, Math.max(min, Number(stepped.toFixed(6))));
  };
  const pct = (v: number) => ((v - min) / (max - min)) * 100;

  const commit = (index: number, raw: number) => {
    const next = [...latest.current];
    const lo = index > 0 ? next[index - 1] : min;
    const hi = index < next.length - 1 ? next[index + 1] : max;
    next[index] = Math.min(hi, Math.max(lo, snap(raw)));
    if (next[index] === latest.current[index]) return latest.current;
    if (value === undefined) setOwn(next);
    onValueChange?.(next);
    latest.current = next;
    return next;
  };

  const fromPointer = (clientX: number) => {
    const rect = trackRef.current!.getBoundingClientRect();
    return min + ((clientX - rect.left) / rect.width) * (max - min);
  };

  const onPointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if (disabled || e.button !== 0) return;
    const raw = fromPointer(e.clientX);
    // The nearest thumb takes the press; on a tie, the one that can move that way.
    let index = 0;
    values.forEach((v, i) => {
      if (
        Math.abs(v - raw) < Math.abs(values[index] - raw) ||
        (Math.abs(v - raw) === Math.abs(values[index] - raw) && raw > v)
      )
        index = i;
    });
    e.currentTarget.setPointerCapture(e.pointerId);
    setActive(index);
    setBubble(index);
    setMode("throw");
    commit(index, raw);
    trackRef.current?.parentElement
      ?.querySelectorAll<HTMLElement>("[role=slider]")
      [index]?.focus({ preventScroll: true });
  };

  const onPointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    if (active === null) return;
    if (mode !== "drag") setMode("drag");
    commit(active, fromPointer(e.clientX));
  };

  const end = () => {
    if (active === null) return;
    setActive(null);
    setMode("rest");
    onValueCommit?.(latest.current);
  };

  const onKeyDown =
    (index: number) => (e: React.KeyboardEvent<HTMLSpanElement>) => {
      if (disabled) return;
      const big = step * 10;
      const deltas: Record<string, number> = {
        ArrowRight: step,
        ArrowUp: step,
        ArrowLeft: -step,
        ArrowDown: -step,
        PageUp: big,
        PageDown: -big,
      };
      let target: number | null = null;
      if (e.key in deltas) target = values[index] + deltas[e.key];
      else if (e.key === "Home") target = min;
      else if (e.key === "End") target = max;
      if (target === null) return;
      e.preventDefault();
      setMode("throw");
      setBubble(index);
      onValueCommit?.(commit(index, target));
    };

  const motion =
    reduced || mode === "drag"
      ? "none"
      : `left 420ms ${EASE_THROW}, right 420ms ${EASE_THROW}`;
  const range = values.length > 1;
  const lo = range ? pct(values[0]) : 0;
  const hi = pct(values[values.length - 1]);

  return (
    <div
      className={`relative w-full select-none pb-2 pt-8 ${disabled ? "opacity-50" : ""} ${className}`}
    >
      <div className="relative">
        <div
          ref={trackRef}
          onPointerDown={onPointerDown}
          onPointerMove={onPointerMove}
          onPointerUp={end}
          onPointerCancel={end}
          onLostPointerCapture={end}
          className={`relative h-5 [touch-action:pan-y] ${disabled ? "" : "cursor-pointer"}`}
        >
          <div className="absolute inset-x-0 top-1/2 h-1.5 -translate-y-1/2 overflow-hidden rounded-full bg-muted shadow-[inset_0_0_0_1px_var(--border)]">
            <div
              className="absolute inset-y-0 rounded-full bg-primary"
              style={{
                left: `${lo}%`,
                right: `${100 - hi}%`,
                transition: motion,
              }}
            />
          </div>
        </div>
        {values.map((v, i) => (
          <span
            key={i}
            role="slider"
            tabIndex={disabled ? -1 : 0}
            aria-label={
              range ? `${label} ${i === 0 ? "minimum" : "maximum"}` : label
            }
            aria-valuemin={min}
            aria-valuemax={max}
            aria-valuenow={v}
            aria-valuetext={format(v)}
            aria-disabled={disabled || undefined}
            onKeyDown={onKeyDown(i)}
            onBlur={() => setBubble((b) => (b === i ? null : b))}
            className="group/thumb pointer-events-none absolute top-1/2 size-4 -translate-x-1/2 -translate-y-1/2 rounded-full outline-none"
            style={{ left: `${pct(v)}%`, transition: motion }}
          >
            <span
              className={`absolute inset-0 rounded-full bg-background shadow-[0_0_0_1px_color-mix(in_oklab,var(--foreground)_18%,var(--border))] transition-[scale,box-shadow] duration-200 group-focus-visible/thumb:shadow-[0_0_0_1px_var(--ring),0_0_0_4px_color-mix(in_oklab,var(--ring)_20%,transparent)] ${
                active === i && !reduced ? "scale-[1.15]" : ""
              }`}
            />
            <span
              aria-hidden="true"
              className="absolute bottom-[calc(100%_+_8px)] left-1/2 whitespace-nowrap rounded-full bg-foreground px-2 py-0.5 text-[11.5px] font-medium tabular-nums text-background"
              style={{
                opacity: bubble === i ? 1 : 0,
                transform: `translateX(-50%) ${bubble === i ? "none" : "translateY(4px) scale(0.85)"}`,
                filter: bubble === i ? "none" : "blur(3px)",
                transition: reduced
                  ? "none"
                  : `opacity 200ms ${EASE_OUT}, transform 320ms ${EASE_OUT}, filter 200ms ${EASE_OUT}`,
              }}
            >
              {format(v)}
            </span>
          </span>
        ))}
      </div>
    </div>
  );
}

export default Slider;

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";

/* ─────────────────────────────────────────────────────────
 * SORTABLE LIST: reorder by hand, and watch everything move
 *
 *   lift      press the grip and the row lifts: a darker thin line,
 *             a touch larger, above the rest; no shadow
 *   drag      it follows your finger exactly; the rows it passes
 *             slide out of its way, one slot at a time
 *   drop      it settles into its slot with a small overshoot,
 *             every rank number rolls to its new place, and the
 *             row you moved says how far it went ("↑ 2") for a
 *             moment
 *   sort      optional presets ("Votes", "Effort") re-sort the
 *             whole list and every row glides to where it belongs;
 *             the highlight slides to the preset, and fades when
 *             you've made your own order
 *   keys      Space on a grip picks the row up, arrows move it,
 *             Space drops it, Escape puts it back; every step is
 *             announced
 * ───────────────────────────────────────────────────────── */

export interface SortableListSort<T> {
  label: string;
  compare: (a: T, b: T) => number;
}

export interface SortableListProps<T extends { id: string }> extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "children"
> {
  items: T[];
  onReorder: (items: T[]) => void;
  renderItem: (
    item: T,
    state: { index: number; lifted: boolean },
  ) => React.ReactNode;
  /** What to call an item when announcing moves; defaults to its id. */
  getLabel?: (item: T) => string;
  /** Ready-made orders shown as a segmented control above the list. */
  sorts?: SortableListSort<T>[];
  /** Accessible name for the list. */
  label?: string;
}

import {
  EASE_OUT,
  EASE_SETTLE,
  rubberBand,
  projectInertia,
  samplePointer,
  releaseVelocity,
  type PointerSample,
} from "./imported-ui-interaction-motion";

const EASE = EASE_OUT;
const THROW = EASE_SETTLE;
const GAP = 6;
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const move = <T,>(list: T[], from: number, to: number) => {
  const next = list.slice();
  const [item] = next.splice(from, 1);
  next.splice(to, 0, item);
  return next;
};

function Grip() {
  return (
    <svg
      width="10"
      height="14"
      viewBox="0 0 10 14"
      aria-hidden="true"
      className="fill-current"
    >
      {[2, 7, 12].map((y) => (
        <React.Fragment key={y}>
          <circle cx="2.5" cy={y} r="1.25" />
          <circle cx="7.5" cy={y} r="1.25" />
        </React.Fragment>
      ))}
    </svg>
  );
}

export function SortableList<T extends { id: string }>({
  items,
  onReorder,
  renderItem,
  getLabel = (item) => item.id,
  sorts,
  label = "Reorderable list",
  className = "",
  ...props
}: SortableListProps<T>) {
  const reduced = useReducedMotion();
  const uid = React.useId();
  const listRef = React.useRef<HTMLUListElement>(null);
  const rows = React.useRef(new Map<string, HTMLLIElement>());
  const handles = React.useRef(new Map<string, HTMLButtonElement>());
  const offsets = React.useRef(new Map<string, number>());
  const pending = React.useRef<{
    first: Map<string, number>;
    settle?: string;
    focus?: string;
  } | null>(null);
  const drag = React.useRef<{
    id: string;
    from: number;
    to: number;
    startY: number;
    tops: number[];
    heights: number[];
  } | null>(null);
  const samples = React.useRef<PointerSample[]>([]);
  const [lifted, setLifted] = React.useState<string | null>(null);
  const [keyLift, setKeyLift] = React.useState<{
    id: string;
    from: number;
  } | null>(null);
  const [moved, setMoved] = React.useState<{
    id: string;
    by: number;
    key: number;
  } | null>(null);
  const [announce, setAnnounce] = React.useState("");

  // Where every row is on screen right now (its slot plus any shift), for gliding from there.
  const snapshot = () => {
    const first = new Map<string, number>();
    rows.current.forEach((el, id) =>
      first.set(id, el.offsetTop + (offsets.current.get(id) ?? 0)),
    );
    return first;
  };

  const shift = (id: string, y: number, glide: boolean) => {
    const el = rows.current.get(id);
    if (!el) return;
    offsets.current.set(id, y);
    el.style.transition =
      glide && !reduced ? `transform 220ms ${EASE}` : "none";
    el.style.transform = y ? `translateY(${y}px)` : "";
  };

  // After any new order: every row glides from where it was to its new slot.
  const play = React.useCallback(() => {
    const p = pending.current;
    if (!p) return;
    pending.current = null;
    rows.current.forEach((el, id) => {
      el.style.transition = "none";
      el.style.transform = "";
      offsets.current.set(id, 0);
      const from = p.first.get(id);
      if (from === undefined || reduced) return;
      const delta = from - el.offsetTop;
      if (Math.abs(delta) < 0.5) return;
      el.animate(
        [{ transform: `translateY(${delta}px)` }, { transform: "none" }],
        {
          duration: id === p.settle ? 360 : 380,
          easing: id === p.settle ? THROW : EASE,
        },
      );
    });
    if (p.focus) handles.current.get(p.focus)?.focus({ preventScroll: true });
  }, [reduced]);

  React.useLayoutEffect(() => {
    play();
  }, [items, play]);

  const commit = (next: T[], settle?: string, focus?: string) => {
    pending.current = { first: snapshot(), settle, focus };
    onReorder(next);
    // If the order didn't change after all, still put everything back.
    requestAnimationFrame(() => requestAnimationFrame(play));
  };

  const moveSeq = React.useRef(0);
  const showMoved = (id: string, by: number) => {
    if (!by) return;
    const key = ++moveSeq.current;
    setMoved({ id, by, key });
    window.setTimeout(() => setMoved((m) => (m?.key === key ? null : m)), 1800);
  };

  // Pointer dragging: transforms only until the drop.
  const onPointerDown = (
    e: React.PointerEvent<HTMLButtonElement>,
    id: string,
  ) => {
    if (e.button !== 0 || keyLift) return;
    e.preventDefault();
    e.currentTarget.setPointerCapture(e.pointerId);
    const from = items.findIndex((it) => it.id === id);
    const els = items.map((it) => rows.current.get(it.id)!);
    drag.current = {
      id,
      from,
      to: from,
      startY: e.clientY,
      tops: els.map((el) => el.offsetTop),
      heights: els.map((el) => el.offsetHeight),
    };
    samples.current = [];
    samplePointer(samples.current, e.clientY, e.timeStamp);
    setLifted(id);
  };
  const onPointerMove = (e: React.PointerEvent) => {
    const d = drag.current;
    if (!d) return;
    samplePointer(samples.current, e.clientY, e.timeStamp);
    const rawDy = e.clientY - d.startY;
    const minCenter = d.tops[0] + d.heights[0] / 2;
    const maxCenter =
      d.tops[d.tops.length - 1] + d.heights[d.heights.length - 1] / 2;
    const naturalCenter = d.tops[d.from] + d.heights[d.from] / 2 + rawDy;

    // Boundary elasticity: rational rubber-band past list ends
    let center = naturalCenter;
    if (naturalCenter < minCenter) {
      center = minCenter + rubberBand(naturalCenter - minCenter, 140, 0.45);
    } else if (naturalCenter > maxCenter) {
      center = maxCenter + rubberBand(naturalCenter - maxCenter, 140, 0.45);
    }
    const dy = center - (d.tops[d.from] + d.heights[d.from] / 2);

    let to = 0;
    items.forEach((_, i) => {
      if (i !== d.from && naturalCenter > d.tops[i] + d.heights[i] / 2) to++;
    });
    d.to = to;
    shift(d.id, dy, false);
    const step = d.heights[d.from] + GAP;
    items.forEach((it, i) => {
      if (i === d.from) return;
      const y =
        d.from < to && i > d.from && i <= to
          ? -step
          : d.from > to && i < d.from && i >= to
            ? step
            : 0;
      if ((offsets.current.get(it.id) ?? 0) !== y) shift(it.id, y, true);
    });
  };
  const onPointerUp = (e?: React.PointerEvent) => {
    const d = drag.current;
    if (!d) return;
    let to = d.to;
    if (e) {
      samplePointer(samples.current, e.clientY, e.timeStamp);
      const vy = releaseVelocity(samples.current, e.timeStamp);
      if (Math.abs(vy) > 0.35) {
        const rawDy = e.clientY - d.startY;
        const naturalCenter = d.tops[d.from] + d.heights[d.from] / 2 + rawDy;
        const projected = projectInertia(naturalCenter, vy, 0.1);
        let projectedTo = 0;
        items.forEach((_, i) => {
          if (i !== d.from && projected > d.tops[i] + d.heights[i] / 2)
            projectedTo++;
        });
        to = projectedTo;
      }
    }
    drag.current = null;
    setLifted(null);
    const item = items[d.from];
    commit(move(items, d.from, to), d.id);
    showMoved(d.id, d.from - to);
    if (to !== d.from)
      setAnnounce(
        `${getLabel(item)} moved to position ${to + 1} of ${items.length}.`,
      );
  };

  // Keyboard: Space picks up and drops, arrows move one place, Escape puts it back.
  const onKeyDown = (e: React.KeyboardEvent, id: string) => {
    const index = items.findIndex((it) => it.id === id);
    const item = items[index];
    if (e.key === " " || e.key === "Enter") {
      e.preventDefault();
      if (keyLift?.id === id) {
        setKeyLift(null);
        setLifted(null);
        showMoved(id, keyLift.from - index);
        setAnnounce(
          `${getLabel(item)} dropped at position ${index + 1} of ${items.length}.`,
        );
      } else {
        setKeyLift({ id, from: index });
        setLifted(id);
        setAnnounce(
          `${getLabel(item)} picked up, position ${index + 1} of ${items.length}. Arrow keys move it, Space drops it, Escape cancels.`,
        );
      }
      return;
    }
    if (keyLift?.id !== id) return;
    if (e.key === "ArrowUp" || e.key === "ArrowDown") {
      e.preventDefault();
      const to = Math.max(
        0,
        Math.min(items.length - 1, index + (e.key === "ArrowUp" ? -1 : 1)),
      );
      if (to === index) return;
      commit(move(items, index, to), id, id);
      setAnnounce(`${getLabel(item)}, position ${to + 1} of ${items.length}.`);
    }
    if (e.key === "Escape") {
      e.preventDefault();
      commit(move(items, index, keyLift.from), id, id);
      setKeyLift(null);
      setLifted(null);
      setAnnounce(
        `${getLabel(item)} put back at position ${keyLift.from + 1}.`,
      );
    }
  };

  // Presets: which one the current order matches, and a highlight that slides to it.
  const sortRefs = React.useRef<(HTMLButtonElement | null)[]>([]);
  const active = sorts
    ? sorts.findIndex((s) =>
        items.every((it, i) => i === 0 || s.compare(items[i - 1], it) <= 0),
      )
    : -1;
  const [mark, setMark] = React.useState({
    x: 0,
    w: 0,
    on: false,
    slide: false,
  });
  React.useLayoutEffect(() => {
    const el = sortRefs.current[active];
    setMark((m) =>
      el
        ? { x: el.offsetLeft, w: el.offsetWidth, on: true, slide: m.on }
        : { ...m, on: false, slide: false },
    );
  }, [active]);

  return (
    <div className={`w-full ${className}`} {...props}>
      {sorts && sorts.length > 0 && (
        <div className="mb-3 flex items-center justify-between gap-3">
          <div
            role="group"
            aria-label="Sort by"
            className="relative flex rounded-full border border-border p-0.5"
          >
            <span
              aria-hidden="true"
              className="absolute bottom-0.5 left-0 top-0.5 rounded-full bg-accent"
              style={{
                transform: `translateX(${mark.x}px)`,
                width: mark.w,
                opacity: mark.on ? 1 : 0,
                transition: reduced
                  ? "none"
                  : `${mark.slide ? `transform 360ms ${EASE}, width 360ms ${EASE}, ` : ""}opacity 220ms ${EASE}`,
              }}
            />
            {sorts.map((s, i) => (
              <button
                key={s.label}
                ref={(el) => {
                  sortRefs.current[i] = el;
                }}
                type="button"
                aria-pressed={i === active}
                onClick={() => {
                  const next = items.slice().sort(s.compare);
                  commit(next);
                  setAnnounce(`Sorted by ${s.label}.`);
                }}
                className={`cursor-pointer relative h-7 rounded-full px-3 text-[12.5px] transition-colors duration-200 ${FOCUS} ${
                  i === active
                    ? "font-medium text-foreground"
                    : "text-muted-foreground hover:text-foreground"
                }`}
              >
                {s.label}
              </button>
            ))}
          </div>
          <span
            className="text-[12px] text-muted-foreground"
            style={{
              opacity: active === -1 ? 1 : 0,
              transition: reduced ? "none" : `opacity 220ms ${EASE}`,
            }}
            aria-hidden={active !== -1}
          >
            Your order
          </span>
        </div>
      )}

      <ul
        ref={listRef}
        aria-label={label}
        className="relative flex flex-col"
        style={{ gap: GAP }}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onPointerCancel={onPointerUp}
      >
        {items.map((item, index) => {
          const up = lifted === item.id;
          const badge = moved?.id === item.id ? moved : null;
          return (
            <li
              key={item.id}
              ref={(el) => {
                if (el) rows.current.set(item.id, el);
                else rows.current.delete(item.id);
              }}
              className="relative"
              style={{ zIndex: up ? 2 : undefined }}
            >
              <div
                className="relative flex min-h-12 items-center gap-2.5 rounded-[12px] border bg-card py-2 pl-1.5 pr-3"
                style={{
                  borderColor: up
                    ? "color-mix(in oklab, var(--foreground) 28%, transparent)"
                    : "var(--border)",
                  transform: up ? "scale(1.015)" : "none",
                  transition: reduced
                    ? "none"
                    : `transform 200ms ${EASE}, border-color 200ms`,
                }}
              >
                <button
                  ref={(el) => {
                    if (el) handles.current.set(item.id, el);
                    else handles.current.delete(item.id);
                  }}
                  type="button"
                  aria-label={`Reorder ${getLabel(item)}`}
                  aria-describedby={`${uid}-how`}
                  aria-pressed={keyLift?.id === item.id}
                  onPointerDown={(e) => onPointerDown(e, item.id)}
                  onKeyDown={(e) => onKeyDown(e, item.id)}
                  onBlur={() => {
                    if (keyLift?.id === item.id && !pending.current) {
                      setKeyLift(null);
                      setLifted(null);
                    }
                  }}
                  className={`flex h-8 w-6 shrink-0 touch-none items-center justify-center rounded-[8px] text-muted-foreground/70 transition-colors hover:bg-accent hover:text-foreground ${
                    up
                      ? "cursor-grabbing bg-accent text-foreground"
                      : "cursor-grab"
                  } ${FOCUS}`}
                >
                  <Grip />
                </button>
                <span
                  className="w-5 shrink-0 text-[12px] tabular-nums text-muted-foreground"
                  aria-hidden="true"
                >
                  <NumberRoll value={index + 1} duration={500} />
                </span>
                <div className="min-w-0 flex-1">
                  {renderItem(item, { index, lifted: up })}
                </div>
                {/* How far it moved, sitting on the row's top edge so nothing shifts. */}
                {badge && (
                  <span
                    key={badge.key}
                    aria-hidden="true"
                    className="pointer-events-none absolute -top-2.5 right-3 rounded-full border border-border bg-card px-1.5 text-[11px] font-medium leading-[18px] tabular-nums text-foreground"
                    ref={(el) => {
                      if (!el || reduced || el.dataset.in) return;
                      el.dataset.in = "1";
                      el.animate(
                        [
                          {
                            opacity: 0,
                            filter: "blur(4px)",
                            transform: "translateY(4px)",
                          },
                          {
                            opacity: 1,
                            filter: "blur(0px)",
                            transform: "none",
                            offset: 0.15,
                          },
                          {
                            opacity: 1,
                            filter: "blur(0px)",
                            transform: "none",
                            offset: 0.8,
                          },
                          {
                            opacity: 0,
                            filter: "blur(4px)",
                            transform: "translateY(-4px)",
                          },
                        ],
                        { duration: 1800, easing: EASE, fill: "forwards" },
                      );
                    }}
                  >
                    {badge.by > 0 ? "↑" : "↓"} {Math.abs(badge.by)}
                  </span>
                )}
              </div>
            </li>
          );
        })}
      </ul>
      <p id={`${uid}-how`} className="sr-only">
        Press Space to pick up, arrow keys to move, Space to drop, Escape to
        cancel.
      </p>
      <p className="sr-only" role="status">
        {announce}
      </p>
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * SPARKLINE: an ultra-compact inline trendline with scrubber
 *
 *   path       smooth or linear SVG stroke with an optional
 *              subtle gradient fill that fades to transparent
 *   scrubber   pointer movement magnetically tracks the nearest
 *              point, showing a vertical thin line indicator,
 *              a snapped dot, and a micro-tooltip readout
 *   auto-trend colors dynamically: emerald for positive change,
 *              rose for negative, or follows your primary token
 *   table-safe zero layout shift, designed to fit inside a single
 *              data-table cell, stat strip, or card header
 * ───────────────────────────────────────────────────────── */

export type SparklinePoint =
  number | { value: number; date?: string; label?: string };

export interface SparklineProps extends React.HTMLAttributes<HTMLDivElement> {
  data: SparklinePoint[];
  width?: number | string;
  height?: number;
  /** Stroke color mode: "auto" (green if up, red if down), "primary", or custom class. */
  color?: "auto" | "primary" | "muted" | string;
  /** Render style: line only or with gradient area fill. */
  variant?: "line" | "area" | "bars";
  /** Shows the interactive magnetic scrubber and micro-tooltip on hover. */
  showScrubber?: boolean;
  /** Highlights the latest (last) data point with a persistent dot when not hovering. */
  showLastPoint?: boolean;
  /** Stroke line width. Defaults to 1.35px thin line. */
  strokeWidth?: number;
  /** Value format for tooltip. */
  format?: Intl.NumberFormatOptions;
  prefix?: string;
  suffix?: string;
  /** Custom accessible label for screen readers. */
  label?: string;
}

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function parsePoint(p: SparklinePoint): {
  val: number;
  date?: string;
  label?: string;
} {
  if (typeof p === "number") return { val: p };
  return { val: p.value, date: p.date, label: p.label };
}

export function Sparkline({
  data,
  width = "100%",
  height = 32,
  color = "auto",
  variant = "area",
  showScrubber = true,
  showLastPoint = true,
  strokeWidth = 1.35,
  format,
  prefix,
  suffix,
  label = "Metric trend",
  className = "",
  style,
  ...rest
}: SparklineProps) {
  const uid = React.useId();
  const gradId = `spark-grad-${uid.replace(/:/g, "")}`;
  const reduced = useReducedMotion();
  const containerRef = React.useRef<HTMLDivElement>(null);

  const [hoverIndex, setHoverIndex] = React.useState<number | null>(null);
  const [containerWidth, setContainerWidth] = React.useState<number>(100);

  // Parse points
  const points = React.useMemo(() => data.map(parsePoint), [data]);
  const values = React.useMemo(() => points.map((p) => p.val), [points]);

  // Track container width via ResizeObserver
  React.useLayoutEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const ro = new ResizeObserver((entries) => {
      for (const entry of entries) {
        const w = entry.contentRect.width;
        if (w > 0) setContainerWidth(w);
      }
    });
    ro.observe(el);
    setContainerWidth(el.offsetWidth || 100);
    return () => ro.disconnect();
  }, []);

  const minVal = values.length ? Math.min(...values) : 0;
  const maxVal = values.length ? Math.max(...values) : 1;
  const range = maxVal - minVal || 1;

  // Compute trend color
  const isPositive =
    values.length >= 2 ? values[values.length - 1] >= values[0] : true;
  const colorClass = React.useMemo(() => {
    if (color === "auto") {
      return isPositive
        ? "text-emerald-600 dark:text-emerald-400"
        : "text-rose-600 dark:text-rose-400";
    }
    if (color === "primary") return "text-primary";
    if (color === "muted") return "text-muted-foreground";
    return color;
  }, [color, isPositive]);

  // Coordinates
  const padY = 4;
  const usableH = Math.max(1, height - padY * 2);
  const n = points.length;

  const coords = React.useMemo(() => {
    if (n === 0) return [];
    if (n === 1) return [{ x: containerWidth / 2, y: height / 2 }];

    return points.map((p, i) => {
      const x = (i / (n - 1)) * containerWidth;
      const normalizedY = (p.val - minVal) / range;
      const y = height - padY - normalizedY * usableH;
      return { x, y };
    });
  }, [containerWidth, height, minVal, n, padY, points, range, usableH]);

  // Build SVG path strings
  const { linePath, areaPath } = React.useMemo(() => {
    if (coords.length < 2) return { linePath: "", areaPath: "" };

    // Smooth bezier curve generator
    let d = `M ${coords[0].x.toFixed(1)} ${coords[0].y.toFixed(1)}`;
    for (let i = 0; i < coords.length - 1; i++) {
      const p0 = coords[Math.max(0, i - 1)];
      const p1 = coords[i];
      const p2 = coords[i + 1];
      const p3 = coords[Math.min(coords.length - 1, i + 2)];

      const cp1x = p1.x + (p2.x - p0.x) / 6;
      const cp1y = p1.y + (p2.y - p0.y) / 6;
      const cp2x = p2.x - (p3.x - p1.x) / 6;
      const cp2y = p2.y - (p3.y - p1.y) / 6;

      d += ` C ${cp1x.toFixed(1)} ${cp1y.toFixed(1)}, ${cp2x.toFixed(1)} ${cp2y.toFixed(1)}, ${p2.x.toFixed(1)} ${p2.y.toFixed(1)}`;
    }

    const last = coords[coords.length - 1];
    const first = coords[0];
    const area = `${d} L ${last.x.toFixed(1)} ${height} L ${first.x.toFixed(1)} ${height} Z`;

    return { linePath: d, areaPath: area };
  }, [coords, height]);

  // Pointer interactions for magnetic scrubber
  const handlePointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!showScrubber || n < 2 || !containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const relX = e.clientX - rect.left;
    const ratio = Math.max(0, Math.min(1, relX / rect.width));
    const nearestIdx = Math.round(ratio * (n - 1));
    setHoverIndex(nearestIdx);
  };

  const handlePointerLeave = () => {
    setHoverIndex(null);
  };

  const activeIdx = hoverIndex;
  const activeCoord =
    activeIdx !== null && coords[activeIdx] ? coords[activeIdx] : null;
  const activePoint =
    activeIdx !== null && points[activeIdx] ? points[activeIdx] : null;
  const lastCoord = coords.length ? coords[coords.length - 1] : null;

  return (
    <div
      ref={containerRef}
      role="img"
      aria-label={label}
      onPointerDown={handlePointerMove}
      onPointerMove={handlePointerMove}
      onPointerLeave={handlePointerLeave}
      className={`relative inline-flex items-center overflow-visible select-none touch-pan-y ${colorClass} ${className}`}
      style={{
        width,
        height,
        ...style,
      }}
      {...rest}
    >
      <svg
        width={containerWidth}
        height={height}
        className="overflow-visible"
        style={{ display: "block" }}
      >
        <defs>
          <linearGradient id={gradId} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="currentColor" stopOpacity="0.18" />
            <stop offset="100%" stopColor="currentColor" stopOpacity="0.0" />
          </linearGradient>
        </defs>

        {/* Variant Area Fill */}
        {variant === "area" && areaPath && (
          <path
            d={areaPath}
            fill={`url(#${gradId})`}
            className="transition-opacity duration-300"
          />
        )}

        {/* Variant Bars */}
        {variant === "bars" && (
          <g>
            {coords.map((c, i) => {
              const barW = Math.max(
                2,
                Math.min(8, (containerWidth / n) * 0.55),
              );
              const barH = height - c.y;
              const isHovered = activeIdx === i;
              return (
                <rect
                  key={i}
                  x={c.x - barW / 2}
                  y={c.y}
                  width={barW}
                  height={Math.max(2, barH)}
                  rx={1.5}
                  fill="currentColor"
                  opacity={isHovered ? 1 : 0.45}
                  className="transition-[opacity,height] duration-200"
                />
              );
            })}
          </g>
        )}

        {/* Stroke Line */}
        {variant !== "bars" && linePath && (
          <path
            d={linePath}
            fill="none"
            stroke="currentColor"
            strokeWidth={strokeWidth}
            strokeLinecap="round"
            strokeLinejoin="round"
            style={{
              transition: reduced
                ? "none"
                : "d 300ms cubic-bezier(0.16,1,0.3,1)",
            }}
          />
        )}

        {/* Persistent Last Point dot */}
        {showLastPoint &&
          lastCoord &&
          activeIdx === null &&
          variant !== "bars" && (
            <circle
              cx={lastCoord.x}
              cy={lastCoord.y}
              r={2.25}
              fill="currentColor"
              className="transition-transform duration-200"
            />
          )}

        {/* Scrubber Vertical Line & Snapped Dot */}
        {activeCoord && showScrubber && (
          <g className="transition-opacity duration-150">
            {/* 1px Vertical Guide thin line */}
            <line
              x1={activeCoord.x}
              y1={0}
              x2={activeCoord.x}
              y2={height}
              stroke="var(--border)"
              strokeWidth={1}
              strokeDasharray="2 2"
            />

            {/* Glowing Scrubber Dot */}
            <circle
              cx={activeCoord.x}
              cy={activeCoord.y}
              r={3.25}
              fill="var(--background)"
              stroke="currentColor"
              strokeWidth={1.75}
            />
          </g>
        )}
      </svg>

      {/* Floating Micro-Tooltip */}
      {activeCoord && activePoint && showScrubber && (
        <div
          aria-hidden="true"
          className="pointer-events-none absolute -top-8 z-30 flex -translate-x-1/2 flex-col items-center whitespace-nowrap rounded-md border border-border bg-popover px-1.5 py-0.5 text-popover-foreground shadow-[0_1px_4px_rgba(0,0,0,0.06)] dark:shadow-none animate-in fade-in-0 zoom-in-95 duration-100"
          style={{
            left: `${activeCoord.x}px`,
          }}
        >
          <div className="flex items-center gap-1 font-mono text-[11px] font-medium leading-none">
            {prefix && <span>{prefix}</span>}
            <span>
              {format
                ? activePoint.val.toLocaleString(undefined, format)
                : activePoint.val.toLocaleString()}
            </span>
            {suffix && <span>{suffix}</span>}
          </div>
          {activePoint.date && (
            <span className="mt-0.5 text-[9.5px] text-muted-foreground leading-none">
              {activePoint.date}
            </span>
          )}
        </div>
      )}

      {/* Screen reader summary */}
      <span className="sr-only">
        {label}: start {values[0] ?? 0}, end {values[values.length - 1] ?? 0},{" "}
        {isPositive ? "upward trend" : "downward trend"}.
      </span>
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * SPINNER: something is happening
 *
 *   ring     a thin line circle with one arc that sweeps round
 *   dots     three dots that rise in turn
 *   bars     eight petals that fade round like a clock face
 *
 * It takes currentColor and says "Loading" (or your label) to
 * screen readers. Reduced motion turns the ring into a calm
 * pulse and holds the dots and petals still.
 * ───────────────────────────────────────────────────────── */

export interface SpinnerProps extends React.HTMLAttributes<HTMLSpanElement> {
  variant?: "ring" | "dots" | "bars";
  /** 12, 16, 20 or 28px. */
  size?: "xs" | "sm" | "md" | "lg";
  label?: string;
}

const PX = { xs: 12, sm: 16, md: 20, lg: 28 };

export function Spinner({
  variant = "ring",
  size = "sm",
  label = "Loading",
  className = "",
  style,
  ...props
}: SpinnerProps) {
  const px = PX[size];
  return (
    <span
      role="status"
      className={`inline-flex shrink-0 items-center justify-center text-current ${className}`}
      style={{ width: px, height: px, ...style }}
      {...props}
    >
      <span className="sr-only">{label}</span>
      {variant === "ring" && (
        <svg
          viewBox="0 0 24 24"
          fill="none"
          aria-hidden="true"
          className="size-full animate-spin [animation-duration:800ms] motion-reduce:animate-pulse"
        >
          <circle
            cx="12"
            cy="12"
            r="9.5"
            stroke="currentColor"
            strokeOpacity="0.18"
            strokeWidth="2.5"
          />
          <path
            d="M21.5 12a9.5 9.5 0 0 0-9.5-9.5"
            stroke="currentColor"
            strokeWidth="2.5"
            strokeLinecap="round"
          />
        </svg>
      )}
      {variant === "dots" && (
        <span
          aria-hidden="true"
          className="flex items-center"
          style={{ gap: px * 0.14 }}
        >
          {[0, 1, 2].map((i) => (
            <span
              key={i}
              className="rounded-full bg-current [animation:ui-bounce_1.1s_ease-in-out_infinite] motion-reduce:[animation:none]"
              style={{
                width: px * 0.24,
                height: px * 0.24,
                animationDelay: `${i * 140}ms`,
              }}
            />
          ))}
        </span>
      )}
      {variant === "bars" && (
        <svg viewBox="0 0 24 24" aria-hidden="true" className="size-full">
          {Array.from({ length: 8 }, (_, i) => (
            <rect
              key={i}
              x="11"
              y="2"
              width="2"
              height="6"
              rx="1"
              fill="currentColor"
              transform={`rotate(${i * 45} 12 12)`}
              className="[animation:ui-blink_0.8s_linear_infinite] motion-reduce:[animation:none]"
              style={{ animationDelay: `${(i - 8) * 100}ms`, opacity: 0.25 }}
            />
          ))}
        </svg>
      )}
    </span>
  );
}

export default Spinner;

"use client";

import * as React from "react";
import { ChevronDown } from "lucide-react";
import { TextMorph } from "./text-morph";
import {
  INTERACTION_FOCUS,
  interactionIcon,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

export interface SplitMenuItem {
  id: string;
  label: string;
  icon?: React.ReactNode;
  onSelect: () => void;
  destructive?: boolean;
  disabled?: boolean;
}

export interface SplitButtonProps {
  label: string;
  icon?: React.ReactNode;
  onClick?: () => void;
  menuItems: SplitMenuItem[];
  variant?: "primary" | "secondary" | "destructive";
  size?: "sm" | "md" | "lg";
  disabled?: boolean;
  loading?: boolean;
  menuLabel?: string;
  className?: string;
}

// Exact physics & timing from FilterBar
const EASE = "cubic-bezier(0.16,1,0.3,1)";
const UI = "cubic-bezier(0.23,1,0.32,1)";
const OPEN = 280;
const CLOSE = 200;
const ROW_H = 32;

type Phase = "closed" | "opening" | "open" | "closing";
type Box = { left: number; top: number; width: number; height: number };

const variantStyles = {
  primary: {
    container: "bg-primary text-primary-foreground",
    action:
      "hover:bg-primary-foreground/10 active:bg-primary-foreground/15 text-primary-foreground",
    trigger:
      "hover:bg-primary-foreground/10 active:bg-primary-foreground/15 text-primary-foreground",
    divider: "bg-primary-foreground/25",
  },
  secondary: {
    container: "bg-card text-foreground shadow-[inset_0_0_0_1px_var(--border)]",
    action: "hover:bg-accent active:bg-accent/80 text-foreground",
    trigger: "hover:bg-accent active:bg-accent/80 text-foreground",
    divider: "bg-border",
  },
  destructive: {
    container:
      "bg-red-500/10 text-red-600 shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_30%,transparent)] dark:text-red-400",
    action:
      "hover:bg-red-500/15 active:bg-red-500/20 text-red-600 dark:text-red-400",
    trigger:
      "hover:bg-red-500/15 active:bg-red-500/20 text-red-600 dark:text-red-400",
    divider: "bg-red-500/25",
  },
};

const sizeStyles = {
  sm: {
    height: "h-7 text-[12px] rounded-full",
    actionPad: "pl-3 pr-2 gap-1.5",
    triggerPad: "px-2",
    iconSize: 13,
  },
  md: {
    height: "h-9 text-[13px] rounded-full",
    actionPad: "pl-4 pr-2.5 gap-2",
    triggerPad: "px-2.5",
    iconSize: 14,
  },
  lg: {
    height: "h-10 text-[14px] rounded-full",
    actionPad: "pl-5 pr-3 gap-2.5",
    triggerPad: "px-3",
    iconSize: 16,
  },
};

export function SplitButton({
  label,
  icon,
  onClick,
  menuItems,
  variant = "primary",
  size = "md",
  disabled = false,
  loading = false,
  menuLabel = "More actions",
  className = "",
}: SplitButtonProps) {
  const reduced = useInteractionReducedMotion();
  const [phase, setPhase] = React.useState<Phase>("closed");
  const [box, setBox] = React.useState<Box>({
    left: 0,
    top: 0,
    width: 0,
    height: 36,
  });
  const [wrapW, setWrapW] = React.useState(200);
  const [panelH, setPanelH] = React.useState(0);
  const [activeIndex, setActiveIndex] = React.useState(0);

  const wrapRef = React.useRef<HTMLDivElement | null>(null);
  const triggerRef = React.useRef<HTMLButtonElement | null>(null);
  const panelRef = React.useRef<HTMLDivElement | null>(null);
  const timer = React.useRef<number>(0);

  const v = variantStyles[variant];
  const s = sizeStyles[size];
  const inert = disabled || loading;
  const mounted = phase !== "closed";
  const expanded = phase === "open";

  // Open the morphing floating dropdown from the trigger pill
  const openMenu = () => {
    const wrap = wrapRef.current;
    const trigger = triggerRef.current;
    if (!wrap || !trigger) return;
    window.clearTimeout(timer.current);
    const a = trigger.getBoundingClientRect();
    const w = wrap.getBoundingClientRect();
    setBox({
      left: a.left - w.left,
      top: a.top - w.top,
      width: a.width,
      height: a.height,
    });
    setWrapW(w.width);
    setActiveIndex(0);
    setPhase(reduced ? "open" : "opening");
  };

  const closeMenu = React.useCallback(
    (refocus = true) => {
      window.clearTimeout(timer.current);
      if (refocus) {
        triggerRef.current?.focus({ preventScroll: true });
      }
      if (reduced) {
        setPhase("closed");
        return;
      }
      setPhase("closing");
      timer.current = window.setTimeout(() => {
        setPhase("closed");
      }, CLOSE);
    },
    [reduced],
  );

  // FilterBar double-rAF expansion
  React.useEffect(() => {
    if (phase !== "opening") return;
    let inner = 0;
    const outer = requestAnimationFrame(() => {
      inner = requestAnimationFrame(() => setPhase("open"));
    });
    return () => {
      cancelAnimationFrame(outer);
      cancelAnimationFrame(inner);
    };
  }, [phase]);

  // Clean timer on unmount
  React.useEffect(() => () => window.clearTimeout(timer.current), []);

  // Measure content height dynamically
  React.useLayoutEffect(() => {
    const panel = panelRef.current;
    if (!panel) return;
    const measure = () => setPanelH(panel.offsetHeight);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(panel);
    return () => observer.disconnect();
  }, [menuItems, mounted]);

  // Close on outside pointer click
  React.useEffect(() => {
    if (!mounted || phase === "closing") return;
    const onPointerDown = (e: PointerEvent) => {
      if (!wrapRef.current?.contains(e.target as Node)) {
        closeMenu(false);
      }
    };
    document.addEventListener("pointerdown", onPointerDown);
    return () => document.removeEventListener("pointerdown", onPointerDown);
  }, [mounted, phase, closeMenu]);

  // Keyboard navigation
  const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (!mounted || phase === "closing") {
      if (
        e.key === "ArrowDown" &&
        document.activeElement === triggerRef.current
      ) {
        e.preventDefault();
        openMenu();
      }
      return;
    }

    if (e.key === "Escape") {
      e.preventDefault();
      closeMenu(true);
    } else if (e.key === "ArrowDown") {
      e.preventDefault();
      setActiveIndex((prev) => (prev < menuItems.length - 1 ? prev + 1 : 0));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setActiveIndex((prev) => (prev > 0 ? prev - 1 : menuItems.length - 1));
    } else if (e.key === "Home") {
      e.preventDefault();
      setActiveIndex(0);
    } else if (e.key === "End") {
      e.preventDefault();
      setActiveIndex(menuItems.length - 1);
    } else if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      const current = menuItems[activeIndex];
      if (current && !current.disabled) {
        closeMenu(true);
        current.onSelect();
      }
    }
  };

  const handleActionClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    if (inert) {
      e.preventDefault();
      return;
    }
    onClick?.();
  };

  const toggleDropdown = (e: React.MouseEvent<HTMLButtonElement>) => {
    e.stopPropagation();
    if (inert) return;
    if (mounted && phase !== "closing") {
      closeMenu();
    } else {
      openMenu();
    }
  };

  // Dimensions & alignment: matches FilterBar's floating panel geometry
  const PANEL_W = 184;
  const menuWidth = Math.min(PANEL_W, Math.max(160, wrapW));
  const targetLeft = Math.max(0, box.left + box.width - menuWidth);
  const targetTop = box.top + box.height + 6;

  return (
    <div
      ref={wrapRef}
      onKeyDown={handleKeyDown}
      className={`relative isolate inline-flex select-none items-stretch transition-[scale] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] has-[button:active:not(:disabled)]:scale-[0.98] motion-reduce:transition-none motion-reduce:has-[button:active]:scale-100 ${s.height} ${v.container} ${
        disabled ? "opacity-45" : ""
      } ${className}`}
    >
      {/* Primary Action Button */}
      <button
        type="button"
        disabled={inert}
        onClick={handleActionClick}
        aria-busy={loading || undefined}
        className={`relative inline-flex items-center justify-center whitespace-nowrap rounded-l-full font-medium transition-colors duration-200 cursor-pointer disabled:cursor-default ${s.actionPad} ${v.action} ${INTERACTION_FOCUS}`}
      >
        {/* The slot opens for an icon or the spinner; they trade places through a blur. */}
        <span
          aria-hidden="true"
          className="relative flex shrink-0 items-center justify-center"
          style={{
            width: icon || loading ? s.iconSize : 0,
            height: s.iconSize,
            marginRight: icon || loading ? 6 : 0,
            transition: reduced
              ? "none"
              : `width 380ms ${EASE}, margin-right 380ms ${EASE}`,
          }}
        >
          <span
            className="absolute inset-0 flex items-center justify-center"
            style={interactionIcon(!loading, reduced)}
          >
            {icon}
          </span>
          <span
            className="absolute inset-0 flex items-center justify-center"
            style={interactionIcon(loading, reduced)}
          >
            <span
              className={`size-3 rounded-full border-[1.5px] border-current border-t-transparent ${loading ? "animate-spin" : ""}`}
            />
          </span>
        </span>
        <TextMorph>{label}</TextMorph>
      </button>

      {/* Quiet thin line Divider */}
      <span
        aria-hidden="true"
        className={`w-px my-1.5 self-stretch ${v.divider}`}
      />

      {/* Dropdown Chevron Trigger Button */}
      <button
        ref={triggerRef}
        type="button"
        disabled={inert}
        onClick={toggleDropdown}
        aria-label={menuLabel}
        aria-haspopup="menu"
        aria-expanded={mounted && phase !== "closing"}
        className={`relative inline-flex items-center justify-center rounded-r-full transition-colors duration-200 cursor-pointer disabled:cursor-default ${s.triggerPad} ${v.trigger} ${INTERACTION_FOCUS}`}
      >
        <ChevronDown
          size={s.iconSize}
          strokeWidth={1.75}
          style={{
            transform:
              mounted && phase !== "closing" ? "rotate(180deg)" : "none",
            transition: reduced ? "none" : `transform 300ms ${EASE}`,
          }}
        />
      </button>

      {/* Floating Panel: Morphs out from under the trigger pill with spring physics */}
      {mounted && (
        <div
          role="menu"
          aria-label={menuLabel}
          className="absolute z-50 overflow-hidden bg-popover text-popover-foreground"
          style={{
            top: targetTop,
            left: expanded ? targetLeft : box.left,
            width: expanded ? menuWidth : box.width,
            height: expanded ? panelH : box.height,
            borderRadius: expanded ? 12 : box.height / 2,
            opacity: expanded ? 1 : 0,
            boxShadow: "0 0 0 1px var(--border)",
            transition: reduced
              ? "none"
              : phase === "closing"
                ? `width ${CLOSE}ms ${UI}, height ${CLOSE}ms ${UI}, left ${CLOSE}ms ${UI}, border-radius ${CLOSE}ms ${UI}, opacity ${CLOSE}ms ${UI}`
                : `width ${OPEN}ms ${UI}, height ${OPEN}ms ${UI}, left ${OPEN}ms ${UI}, border-radius ${OPEN}ms ${UI}, opacity 160ms ${UI}`,
          }}
        >
          <div
            ref={panelRef}
            inert={!expanded ? true : undefined}
            className="relative p-1"
            style={{
              width: menuWidth,
              opacity: expanded ? 1 : 0,
              transition: reduced
                ? "none"
                : expanded
                  ? `opacity 180ms ${EASE} 60ms`
                  : "opacity 90ms ease-out",
            }}
          >
            {/* The Internal Highlight Glides Between Menu Rows */}
            <span
              aria-hidden="true"
              className="pointer-events-none absolute inset-x-1 top-1 h-8 rounded-[7px] bg-accent"
              style={{
                transform: `translateY(${activeIndex * ROW_H}px)`,
                opacity: activeIndex >= 0 && menuItems.length > 0 ? 1 : 0,
                transition: reduced ? "none" : `transform 160ms ${UI}`,
              }}
            />

            {/* Menu Items */}
            {menuItems.map((item, index) => {
              const isDestructive = item.destructive;
              const isSelected = activeIndex === index;

              return (
                <button
                  key={item.id}
                  type="button"
                  role="menuitem"
                  data-menu-item=""
                  disabled={item.disabled}
                  onPointerEnter={() => !item.disabled && setActiveIndex(index)}
                  onClick={() => {
                    closeMenu(false);
                    item.onSelect();
                  }}
                  className={`relative z-10 flex h-8 w-full items-center gap-2 rounded-[7px] px-2.5 text-[13px] font-medium transition-colors cursor-pointer disabled:cursor-not-allowed disabled:opacity-40 select-none text-left ${
                    isDestructive
                      ? isSelected
                        ? "text-red-600 dark:text-red-400 font-semibold"
                        : "text-red-500/90 dark:text-red-400/90"
                      : isSelected
                        ? "text-foreground font-semibold"
                        : "text-muted-foreground"
                  } ${INTERACTION_FOCUS}`}
                >
                  {item.icon && (
                    <span
                      className={`inline-flex size-3.5 shrink-0 items-center justify-center ${
                        isDestructive ? "text-red-500" : "text-muted-foreground"
                      }`}
                    >
                      {item.icon}
                    </span>
                  )}
                  <span className="truncate flex-1">{item.label}</span>
                </button>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

export default SplitButton;

"use client";

/* ─────────────────────────────────────────────────────────
 * SPLIT PANE: desktop-grade resizable dual surface
 *
 *   divider    1px thin line border with a centered grab pill;
 *              hover expands the line to an active primary accent
 *   drag       zero-lag direct DOM updates; dragging beyond
 *              min/max limits introduces logarithmic rubber-band
 *              resistance
 *   spring     releasing past boundary limits triggers an
 *              analytical WAAPI damped harmonic spring back
 *              to the boundary threshold
 *   snapping   double-clicking the divider smoothly cycles
 *              between 50%, 25%, and 75% preset layouts
 *   collapse   built-in controls fold either pane to 0 width,
 *              docking the thin line divider flush to the edge
 *   touch      expanded touch targets enable fluid dragging on
 *              mobile devices
 *
 * Fully accessible separator semantics with keyboard step.
 * ───────────────────────────────────────────────────────── */

import * as React from "react";
import { ChevronLeft, ChevronRight, GripVertical } from "lucide-react";
import {
  INTERACTION_FOCUS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";
import { useSplitPane } from "./use-split-pane";

export interface SplitPaneProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onChange"
> {
  first: React.ReactNode;
  second: React.ReactNode;
  split?: number;
  defaultSplit?: number;
  minSize?: number;
  maxSize?: number;
  orientation?: "horizontal" | "vertical";
  collapsible?: boolean;
  disabled?: boolean;
  onSplitChange?: (split: number) => void;
  onSplitCommit?: (split: number) => void;
}

export function SplitPane({
  first,
  second,
  split,
  defaultSplit = 50,
  minSize = 15,
  maxSize = 85,
  orientation = "horizontal",
  collapsible = true,
  disabled = false,
  onSplitChange,
  onSplitCommit,
  className = "",
  ...props
}: SplitPaneProps) {
  const reduced = useInteractionReducedMotion();
  const isHorizontal = orientation !== "vertical";

  const pane = useSplitPane({
    orientation,
    split,
    defaultSplit,
    minSize,
    maxSize,
    disabled,
    reduced,
    onChange: onSplitChange,
    onCommit: onSplitCommit,
  });

  return (
    <div
      {...props}
      ref={(el) => pane.attachContainer(el)}
      className={`relative flex select-none overflow-hidden rounded-[14px] border border-border bg-background ${
        isHorizontal ? "flex-row" : "flex-col"
      } ${className}`}
    >
      {/* First Pane */}
      <div
        ref={(el) => pane.attachFirstPane(el)}
        className={`relative min-h-0 min-w-0 overflow-hidden ${
          pane.collapsed === "first" ? "pointer-events-none" : ""
        }`}
        style={{ flexBasis: `${defaultSplit}%` }}
      >
        <div className="size-full overflow-auto">{first}</div>
      </div>

      {/* 1px thin line Divider Container */}
      <div
        className={`relative z-10 shrink-0 touch-none ${
          isHorizontal ? "w-px cursor-col-resize" : "h-px cursor-row-resize"
        }`}
      >
        {/* Full thin line Line */}
        <div
          className={`absolute inset-0 bg-border transition-colors ${
            pane.dragging ? "bg-primary" : "hover:bg-primary/70"
          }`}
        />

        {/* Dead-Centered Draggable Grab Handle Button */}
        <button
          ref={(el) => pane.attachDivider(el)}
          {...pane.dividerProps}
          type="button"
          role="separator"
          disabled={disabled}
          aria-orientation={isHorizontal ? "vertical" : "horizontal"}
          aria-valuenow={Math.round(split ?? defaultSplit)}
          aria-valuemin={minSize}
          aria-valuemax={maxSize}
          aria-label="Resize split panes"
          style={{
            position: "absolute",
            left: "50%",
            top: "50%",
            transform: "translate(-50%, -50%)",
            touchAction: "none",
          }}
          className={`group flex items-center justify-center rounded-full border border-border bg-background text-muted-foreground transition-colors hover:border-primary/50 hover:text-foreground active:scale-95 disabled:cursor-default disabled:opacity-40 before:absolute before:-inset-3 before:content-[''] ${
            isHorizontal
              ? "h-8 w-4.5 cursor-col-resize"
              : "h-4.5 w-8 cursor-row-resize"
          } ${INTERACTION_FOCUS}`}
        >
          <GripVertical className="size-3.5 opacity-60 transition-opacity group-hover:opacity-100" />
        </button>

        {/* Optional Collapsible Controls */}
        {collapsible && !pane.dragging && (
          <div
            style={{
              position: "absolute",
              left: isHorizontal ? "50%" : "12px",
              top: isHorizontal ? "12px" : "50%",
              transform: isHorizontal
                ? "translate(-50%, 0)"
                : "translate(0, -50%)",
            }}
            className={`z-20 flex items-center gap-0.5 ${
              isHorizontal ? "flex-col" : "flex-row"
            }`}
          >
            {pane.collapsed === "first" ? (
              <button
                type="button"
                onClick={pane.expand}
                title="Restore pane"
                className="cursor-pointer rounded-full border border-border bg-surface p-0.5 text-muted-foreground transition-colors hover:text-foreground"
              >
                <ChevronRight className="size-3" />
              </button>
            ) : pane.collapsed === "second" ? (
              <button
                type="button"
                onClick={pane.expand}
                title="Restore pane"
                className="cursor-pointer rounded-full border border-border bg-surface p-0.5 text-muted-foreground transition-colors hover:text-foreground"
              >
                <ChevronLeft className="size-3" />
              </button>
            ) : (
              <div className="flex gap-0.5 opacity-0 transition-opacity group-hover:opacity-100 hover:opacity-100">
                <button
                  type="button"
                  onClick={() => pane.collapse("first")}
                  title="Collapse left"
                  className="cursor-pointer rounded border border-border bg-surface p-0.5 text-muted-foreground hover:text-foreground"
                >
                  <ChevronLeft className="size-2.5" />
                </button>
                <button
                  type="button"
                  onClick={() => pane.collapse("second")}
                  title="Collapse right"
                  className="cursor-pointer rounded border border-border bg-surface p-0.5 text-muted-foreground hover:text-foreground"
                >
                  <ChevronRight className="size-2.5" />
                </button>
              </div>
            )}
          </div>
        )}
      </div>

      {/* Second Pane */}
      <div
        className={`relative min-h-0 min-w-0 flex-1 overflow-hidden ${
          pane.collapsed === "second" ? "pointer-events-none" : ""
        }`}
      >
        <div className="size-full overflow-auto">{second}</div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";

/* ─────────────────────────────────────────────────────────
 * STAGE BARS: a funnel you can read at a glance
 *
 *   arrive    the first time it's on screen the bars grow from
 *             the left one after another and every count and
 *             share rolls up from zero
 *   period    This week, Last week, 30 days: the pill is thrown
 *             to the choice, every bar eases to its new width and
 *             every figure rolls; the drop-off between stages
 *             rolls with them
 *   focus     point at a stage and the others dim, leaving it and
 *             the drop-off into it to read
 *
 * One hue that steps lighter down the funnel, every value
 * labelled on its row, and the whole funnel in a table for
 * screen readers.
 * ───────────────────────────────────────────────────────── */

export interface Stage {
  id: string;
  label: string;
}

export interface StagePeriod {
  id: string;
  /** In the switch, e.g. "This week". */
  label: string;
  /** One count per stage, in the same order. */
  values: number[];
}

export interface StageBarsProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onChange"
> {
  title?: string;
  stages: Stage[];
  periods: StagePeriod[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (id: string) => void;
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const HUE = "var(--chart-1, var(--primary))";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

export function StageBars({
  title = "Funnel",
  stages,
  periods,
  value,
  defaultValue,
  onValueChange,
  format,
  locales,
  className = "",
  ...props
}: StageBarsProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const [own, setOwn] = React.useState(defaultValue ?? periods[0]?.id);
  const periodId = value ?? own;
  const period = periods.find((p) => p.id === periodId) ?? periods[0];
  const values = period?.values ?? [];
  const first = values[0] || 1;

  const [visible, setVisible] = React.useState(false);
  const [focused, setFocused] = React.useState<number | null>(null);
  const [pill, setPill] = React.useState({ left: 0, width: 0, ready: false });
  const rootRef = React.useRef<HTMLDivElement>(null);
  const chipRefs = React.useRef<(HTMLButtonElement | null)[]>([]);

  React.useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          observer.disconnect();
        }
      },
      { rootMargin: "0px 0px -10% 0px" },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  React.useLayoutEffect(() => {
    const el = chipRefs.current[periods.findIndex((p) => p.id === periodId)];
    if (!el) return;
    setPill((p) =>
      p.left === el.offsetLeft && p.width === el.offsetWidth
        ? p
        : { left: el.offsetLeft, width: el.offsetWidth, ready: p.width > 0 },
    );
  }, [periodId, periods]);

  const choose = (next: string) => {
    if (next === periodId) return;
    if (value === undefined) setOwn(next);
    onValueChange?.(next);
  };

  const fmt = (v: number) => new Intl.NumberFormat(locales, format).format(v);
  const overall =
    values.length > 1 ? (values[values.length - 1] ?? 0) / first : 1;

  return (
    <div
      ref={rootRef}
      className={`@container w-full rounded-[22px] bg-background shadow-[0_0_0_1px_var(--border)] ${className}`}
      {...props}
    >
      <div className="p-4 @md:p-5 [--gutter:30px] @md:[--gutter:40px]">
        {/* The title and its control share a row; the figures sit under both. */}
        <div className="flex flex-wrap items-center justify-between gap-x-3 gap-y-2">
          <p className="text-[12px] text-muted-foreground @md:text-[13px]">
            {title}
          </p>
          {periods.length > 1 && (
            <div
              role="radiogroup"
              aria-label="Period"
              className="relative -my-1 inline-flex shrink-0 rounded-full bg-muted p-0.5"
            >
              <span
                aria-hidden="true"
                className="absolute inset-y-0.5 left-0 rounded-full bg-background shadow-[0_0_0_1px_var(--border)]"
                style={{
                  width: pill.width,
                  transform: `translateX(${pill.left}px)`,
                  transition:
                    pill.ready && !reduced
                      ? `transform 460ms ${THROW}, width 380ms ${EASE}`
                      : "none",
                }}
              />
              {periods.map((p, i) => {
                const selected = p.id === periodId;
                return (
                  <button
                    key={p.id}
                    ref={(el) => {
                      chipRefs.current[i] = el;
                    }}
                    type="button"
                    role="radio"
                    aria-checked={selected}
                    tabIndex={selected ? 0 : -1}
                    onClick={() => choose(p.id)}
                    onKeyDown={(e) => {
                      if (e.key !== "ArrowRight" && e.key !== "ArrowLeft")
                        return;
                      e.preventDefault();
                      const next =
                        (i +
                          (e.key === "ArrowRight" ? 1 : -1) +
                          periods.length) %
                        periods.length;
                      choose(periods[next].id);
                      chipRefs.current[next]?.focus();
                    }}
                    className={`cursor-pointer relative h-6 whitespace-nowrap rounded-full px-2.5 text-[11.5px] font-medium @md:h-7 @md:px-3 @md:text-[12.5px] transition-colors duration-300 ${FOCUS} ${
                      selected
                        ? "text-foreground"
                        : "text-muted-foreground hover:text-foreground"
                    }`}
                  >
                    {p.label}
                  </button>
                );
              })}
            </div>
          )}
        </div>
        <p className="mt-0.5 flex items-baseline gap-1.5 text-[22px] font-medium leading-tight tracking-[-0.03em] @md:text-[26px] text-foreground">
          <NumberRoll
            value={visible ? overall : 0}
            format={{ style: "percent", maximumFractionDigits: 1 }}
            duration={1000}
          />
          <span className="text-[13px] font-normal tracking-normal text-muted-foreground">
            made it all the way
          </span>
        </p>

        <ol className="mt-4 @md:mt-6" onPointerLeave={() => setFocused(null)}>
          {stages.map((s, i) => {
            const v = values[i] ?? 0;
            const share = v / first;
            const step = i > 0 && values[i - 1] ? v / values[i - 1] : 1;
            const dim = focused !== null && focused !== i;
            // One hue, a step lighter for each stage further down.
            const strength =
              1 - (stages.length > 1 ? (i / (stages.length - 1)) * 0.5 : 0);
            return (
              <li key={s.id}>
                {i > 0 && (
                  <p
                    aria-hidden="true"
                    className="flex h-5 items-center gap-1 pl-1 text-[10.5px] tabular-nums @md:h-6 @md:text-[11.5px] text-muted-foreground transition-opacity duration-300"
                    style={{ opacity: dim && focused !== i - 1 ? 0.35 : 1 }}
                  >
                    <svg
                      viewBox="0 0 12 12"
                      className="size-3"
                      aria-hidden="true"
                    >
                      <path
                        d="M6 2.5v7M3 6.6 6 9.5l3-2.9"
                        fill="none"
                        stroke="currentColor"
                        strokeWidth="1.4"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                      />
                    </svg>
                    <NumberRoll
                      value={visible ? step : 0}
                      format={{ style: "percent", maximumFractionDigits: 0 }}
                      duration={800}
                    />
                    <span>carried on</span>
                  </p>
                )}
                <div
                  onPointerEnter={() => setFocused(i)}
                  className={`transition-opacity duration-300 ${dim ? "opacity-40" : ""}`}
                >
                  <div className="flex items-baseline justify-between gap-3 text-[12.5px] @md:text-[13px]">
                    <span className="truncate text-foreground">{s.label}</span>
                    <span className="flex shrink-0 items-baseline gap-2 tabular-nums">
                      <span className="font-medium text-foreground">
                        <NumberRoll
                          value={visible ? v : 0}
                          format={format}
                          locales={locales}
                          duration={900}
                        />
                      </span>
                      <span className="w-10 text-right text-[11px] text-muted-foreground @md:w-11 @md:text-[12px]">
                        <NumberRoll
                          value={visible ? share : 0}
                          format={{
                            style: "percent",
                            maximumFractionDigits: share < 0.1 ? 1 : 0,
                          }}
                          duration={900}
                        />
                      </span>
                    </span>
                  </div>
                  <div className="relative mt-1 h-3.5 @md:mt-1.5 @md:h-[18px]">
                    <div
                      aria-hidden="true"
                      className="absolute inset-y-0 left-0 rounded-r-[4px]"
                      style={{
                        width: `${visible ? Math.max(0.5, share * 100) : 0}%`,
                        background: `color-mix(in oklab, ${HUE} ${Math.round(strength * 100)}%, var(--background))`,
                        transition: reduced
                          ? "none"
                          : `width 820ms ${EASE} ${visible ? i * 90 : 0}ms`,
                      }}
                    />
                  </div>
                </div>
              </li>
            );
          })}
        </ol>

        <table className="sr-only">
          <caption>
            {title}, {period?.label}: {Math.round(overall * 1000) / 10}% made it
            from {stages[0]?.label.toLowerCase()} to{" "}
            {stages[stages.length - 1]?.label.toLowerCase()}
          </caption>
          <thead>
            <tr>
              <th scope="col">Stage</th>
              <th scope="col">Count</th>
              <th scope="col">Share of the first stage</th>
              <th scope="col">Share of the stage before</th>
            </tr>
          </thead>
          <tbody>
            {stages.map((s, i) => (
              <tr key={s.id} id={`${id}-${s.id}`}>
                <th scope="row">{s.label}</th>
                <td>{fmt(values[i] ?? 0)}</td>
                <td>{Math.round(((values[i] ?? 0) / first) * 1000) / 10}%</td>
                <td>
                  {i > 0 && values[i - 1]
                    ? `${Math.round(((values[i] ?? 0) / values[i - 1]) * 1000) / 10}%`
                    : "–"}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";

/* ─────────────────────────────────────────────────────────
 * STATS BAND: the numbers arrive when you do
 *
 *   waiting   before it's on screen, quiet zeros
 *   arriving  the fine lines between stats draw themselves,
 *             then each figure rolls up from zero, one after
 *             another, as its label rises in
 *   done      the real numbers, rolling again only if they
 *             change
 *
 * Screen readers get the real figures straight away.
 * ───────────────────────────────────────────────────────── */

export interface Stat {
  value: number;
  label: string;
  /** Intl.NumberFormat options, e.g. { notation: "compact" }. */
  format?: Intl.NumberFormatOptions;
  prefix?: string;
  suffix?: string;
}

export interface StatsBandProps extends React.HTMLAttributes<HTMLDListElement> {
  stats: Stat[];
  /** Time between one stat starting and the next (ms). */
  stagger?: number;
  /** Classes for the figures. */
  numberClassName?: string;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

export function StatsBand({
  stats,
  stagger = 140,
  numberClassName = "text-[28px] @[28rem]:text-[34px] @[36rem]:text-[30px] @[48rem]:text-[36px] @[56rem]:text-[40px] font-medium leading-[1.15] tracking-[-0.04em] text-foreground",
  className = "",
  ...props
}: StatsBandProps) {
  const reduced = useReducedMotion();
  const ref = React.useRef<HTMLDListElement>(null);
  const [seen, setSeen] = React.useState(false);
  const [revealed, setRevealed] = React.useState(0);

  // Start once, the first time most of the band is on screen.
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (!entry.isIntersecting) return;
        setSeen(true);
        observer.disconnect();
      },
      { threshold: 0.5 },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  // Then reveal the stats one after another: the lines draw first, the numbers follow.
  React.useEffect(() => {
    if (!seen || reduced) return;
    const timers = stats.map((_, i) =>
      window.setTimeout(
        () => setRevealed((r) => Math.max(r, i + 1)),
        240 + i * stagger,
      ),
    );
    return () => timers.forEach((t) => window.clearTimeout(t));
  }, [seen, reduced, stats, stagger]);

  return (
    // Laid out by its own width, not the screen's, so it reads right in a narrow column too.
    <div className="w-full">
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 760px)" }}
      />
      <div className="@container w-full">
        <dl
          ref={ref}
          className={`grid grid-cols-2 @[36rem]:grid-flow-col @[36rem]:grid-cols-none @[36rem]:auto-cols-fr ${className}`}
          {...props}
        >
          {stats.map((stat, i) => {
            const shown = i < (seen && reduced ? stats.length : revealed);
            return (
              <div
                key={stat.label}
                className="relative flex min-w-0 flex-col-reverse justify-end px-4 py-4 @[28rem]:py-5 @[48rem]:px-6"
              >
                {/* The thin line before every stat but the first, drawn from the middle out (wide screens). */}
                {i > 0 && (
                  <span
                    aria-hidden="true"
                    className="absolute left-0 top-0 hidden h-full w-px origin-center bg-border @[36rem]:block"
                    style={{
                      transform: seen || reduced ? "none" : "scaleY(0)",
                      transition: reduced
                        ? "none"
                        : `transform 700ms ${EASE} ${i * 80}ms`,
                    }}
                  />
                )}
                <dt
                  className="mt-1 text-[13px] text-muted-foreground"
                  style={{
                    opacity: shown ? 1 : 0,
                    transform: shown ? "none" : "translateY(6px)",
                    transition: reduced
                      ? "none"
                      : `opacity 500ms ${EASE} 120ms, transform 600ms ${EASE} 120ms`,
                  }}
                >
                  {stat.label}
                </dt>
                <dd>
                  <span className="sr-only">
                    {stat.prefix}
                    {new Intl.NumberFormat(undefined, stat.format).format(
                      stat.value,
                    )}
                    {stat.suffix}
                  </span>
                  <span aria-hidden="true">
                    <NumberRoll
                      value={shown ? stat.value : 0}
                      format={stat.format}
                      prefix={stat.prefix}
                      suffix={stat.suffix}
                      duration={1200}
                      className={numberClassName}
                    />
                  </span>
                </dd>
              </div>
            );
          })}
        </dl>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { RelativeTime, type DateLike } from "./relative-time";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * STATUS BARS: a status page that reads at a glance
 *
 *   overall   one line says how things are; it morphs when a
 *             service changes ("All systems operational" →
 *             "Some systems degraded") and its dot changes
 *             colour with it
 *   days      ninety days a service, a bar a day, drawn up
 *             from the baseline left to right; thirty on a
 *             narrow card
 *   read      point at a day (or arrow along with the keys) and
 *             one card glides from bar to bar above them, saying
 *             what happened that day
 *   incidents an open incident shows its updates newest first;
 *             a new update opens in on top and the status pill
 *             morphs (Investigating → Identified → Monitoring →
 *             Resolved). Past incidents fold behind a toggle
 *
 * Everything is props: feed it from your own checks or from
 * Better Stack, Instatus or Atlassian Statuspage.
 * ───────────────────────────────────────────────────────── */

export type { DateLike };
export type ServiceStatus =
  "operational" | "degraded" | "major" | "maintenance";
export type DayStatus =
  "operational" | "degraded" | "major" | "maintenance" | "none";

export interface StatusDay {
  /** "2026-10-14". */
  date: string;
  status: DayStatus;
  /** Minutes the service was degraded or down that day. */
  minutes?: number;
  /** Incident titles that touched this day. */
  incidents?: string[];
}

export interface StatusService {
  id: string;
  name: string;
  status: ServiceStatus;
  /** Uptime over the days shown, as a percentage. */
  uptime?: number;
  /** Oldest first; the last is today. */
  days: StatusDay[];
}

export type IncidentStage =
  "investigating" | "identified" | "monitoring" | "resolved";

export interface StatusIncident {
  id: string;
  title: string;
  impact: "minor" | "major" | "maintenance";
  stage: IncidentStage;
  /** Newest first. */
  updates: {
    id: string;
    at: DateLike;
    stage: IncidentStage;
    message: string;
  }[];
  /** Names of affected services. */
  services?: string[];
}

export interface StatusBarsProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "title"
> {
  services: StatusService[];
  incidents?: StatusIncident[];
  updatedAt?: DateLike;
  title?: string;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const BAR: Record<DayStatus, string> = {
  operational: "bg-emerald-500/80",
  degraded: "bg-amber-500",
  major: "bg-red-500",
  maintenance: "bg-foreground/35",
  none: "bg-muted shadow-[inset_0_0_0_1px_var(--border)]",
};
const WORD: Record<ServiceStatus, string> = {
  operational: "Operational",
  degraded: "Degraded",
  major: "Outage",
  maintenance: "Maintenance",
};
const WORD_TONE: Record<ServiceStatus, string> = {
  operational: "text-emerald-600 dark:text-emerald-400",
  degraded: "text-amber-700 dark:text-amber-400",
  major: "text-red-600 dark:text-red-400",
  maintenance: "text-muted-foreground",
};
const STAGES: Record<IncidentStage, string> = {
  investigating: "Investigating",
  identified: "Identified",
  monitoring: "Monitoring",
  resolved: "Resolved",
};
const NONE: StatusIncident[] = [];

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const DAYS = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
const MONTHS = [
  "Jan",
  "Feb",
  "Mar",
  "Apr",
  "May",
  "Jun",
  "Jul",
  "Aug",
  "Sep",
  "Oct",
  "Nov",
  "Dec",
];
const dayLabel = (iso: string) => {
  const [y, m, d] = iso.split("-").map(Number);
  const t = new Date(y, m - 1, d);
  return `${DAYS[t.getDay()]} ${d} ${MONTHS[m - 1]}`;
};
const span = (min: number) =>
  min < 60
    ? `${min} min`
    : `${Math.floor(min / 60)} h${min % 60 ? ` ${min % 60} min` : ""}`;
const said = (d: StatusDay) =>
  d.status === "none"
    ? "No data"
    : d.status === "operational"
      ? "No incidents"
      : d.status === "maintenance"
        ? `Maintenance${d.minutes ? ` for ${span(d.minutes)}` : ""}`
        : `${d.status === "major" ? "Down" : "Degraded"}${d.minutes ? ` for ${span(d.minutes)}` : ""}`;

function overall(services: StatusService[]) {
  if (services.some((s) => s.status === "major"))
    return { text: "Major outage", tone: "major" as const };
  if (services.some((s) => s.status === "degraded"))
    return { text: "Some systems degraded", tone: "degraded" as const };
  if (services.some((s) => s.status === "maintenance"))
    return { text: "Maintenance in progress", tone: "maintenance" as const };
  return { text: "All systems operational", tone: "operational" as const };
}

/** A sentence that changes by lifting the old one out and the new one in. */
function Line({
  text,
  className = "",
  reduced,
}: {
  text: string;
  className?: string;
  reduced: boolean;
}) {
  const [shown, setShown] = React.useState(text);
  const [old, setOld] = React.useState<{ k: number; t: string }[]>([]);
  const key = React.useRef(0);
  const ref = React.useRef<HTMLSpanElement>(null);
  if (text !== shown) {
    if (!reduced) setOld((o) => [...o, { k: ++key.current, t: shown }]);
    setShown(text);
  }
  React.useLayoutEffect(() => {
    if (!reduced && old.length)
      ref.current?.animate(
        [
          { opacity: 0, transform: "translateY(0.3em)", filter: "blur(4px)" },
          { opacity: 1, transform: "none", filter: "blur(0px)" },
        ],
        { duration: 420, delay: 80, easing: EASE, fill: "backwards" },
      );
  }, [shown]);
  return (
    <span className={`relative inline-block ${className}`}>
      <span ref={ref} className="inline-block">
        {shown}
      </span>
      {old.map((o) => (
        <Gone
          key={o.k}
          text={o.t}
          onDone={() => setOld((all) => all.filter((x) => x.k !== o.k))}
        />
      ))}
    </span>
  );
}

function Gone({ text, onDone }: { text: string; onDone: () => void }) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const a = ref.current?.animate(
      [
        { opacity: 1, filter: "blur(0px)" },
        { opacity: 0, transform: "translateY(-0.3em)", filter: "blur(4px)" },
      ],
      { duration: 220, easing: EASE, fill: "forwards" },
    );
    if (a) a.onfinish = onDone;
    return () => a?.cancel();
  }, []);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute top-0 left-0 whitespace-nowrap"
    >
      {text}
    </span>
  );
}

function Service({ s, reduced }: { s: StatusService; reduced: boolean }) {
  const id = React.useId();
  const barsRef = React.useRef<HTMLDivElement>(null);
  const cardRef = React.useRef<HTMLDivElement>(null);
  const [active, setActive] = React.useState<number | null>(null);
  const [place, setPlace] = React.useState({ x: 0, ready: false });
  const [keyed, setKeyed] = React.useState(false);
  const [spoken, setSpoken] = React.useState("");
  const last = s.days.length - 1;

  // The bars draw up from the baseline, left to right, once.
  React.useLayoutEffect(() => {
    if (reduced) return;
    barsRef.current
      ?.querySelectorAll<HTMLElement>("[data-bar]")
      .forEach((b, i) =>
        b.animate([{ transform: "scaleY(0)" }, { transform: "none" }], {
          duration: 520,
          delay: 60 + i * 5,
          easing: EASE,
          fill: "backwards",
        }),
      );
  }, []);

  // The card glides to sit over the day, kept inside the row.
  React.useLayoutEffect(() => {
    if (active === null) return;
    const bars = barsRef.current;
    const card = cardRef.current;
    const bar = bars?.querySelector<HTMLElement>(`[data-bar="${active}"]`);
    if (!bars || !card || !bar) return;
    const center = bar.offsetLeft + bar.offsetWidth / 2;
    const x = Math.max(
      0,
      Math.min(
        bars.offsetWidth - card.offsetWidth,
        center - card.offsetWidth / 2,
      ),
    );
    setPlace((p) => (p.x === x && p.ready ? p : { x, ready: true }));
  }, [active]);

  const day = active === null ? null : s.days[active];
  const move = (to: number) => {
    const visible = [
      ...(barsRef.current?.querySelectorAll<HTMLElement>("[data-bar]") ?? []),
    ]
      .filter((b) => b.offsetParent !== null)
      .map((b) => Number(b.dataset.bar));
    const first = visible[0] ?? 0;
    const i = Math.max(first, Math.min(last, to));
    setActive(i);
    setKeyed(true);
    const d = s.days[i];
    setSpoken(
      `${dayLabel(d.date)}: ${said(d)}${d.incidents?.length ? `. ${d.incidents.join(". ")}` : ""}`,
    );
  };

  return (
    <div className="py-4 first:pt-0 last:pb-0">
      <div className="flex items-baseline justify-between gap-3">
        <p className="flex min-w-0 items-baseline gap-2">
          <span
            id={`${id}-name`}
            className="truncate text-[13.5px] font-medium tracking-[-0.01em]"
          >
            {s.name}
          </span>
          <span
            className={`shrink-0 text-[11.5px] transition-colors duration-500 ${WORD_TONE[s.status]}`}
          >
            <TextMorph>{WORD[s.status]}</TextMorph>
          </span>
        </p>
        {s.uptime !== undefined && (
          <p className="shrink-0 text-[11.5px] text-muted-foreground tabular-nums">
            <NumberRoll
              value={s.uptime / 100}
              format={{
                style: "percent",
                minimumFractionDigits: 2,
                maximumFractionDigits: 2,
              }}
            />{" "}
            uptime
          </p>
        )}
      </div>

      <div className="relative mt-2">
        {/* One card for every day: it glides between bars instead of a tooltip per bar. */}
        <div
          ref={cardRef}
          aria-hidden="true"
          className="pointer-events-none absolute bottom-full left-0 z-10 mb-2 w-[13.5rem] rounded-[12px] bg-popover px-3 py-2 text-popover-foreground shadow-[inset_0_0_0_1px_var(--border)]"
          style={{
            transform: `translateX(${place.x}px) translateY(${day ? 0 : 4}px)`,
            opacity: day ? 1 : 0,
            transition: reduced
              ? "none"
              : `transform ${place.ready && day ? 320 : 0}ms ${EASE}, opacity 180ms ${EASE}`,
          }}
        >
          {day && (
            <>
              <p className="text-[11.5px] text-muted-foreground">
                {dayLabel(day.date)}
              </p>
              <p
                className={`mt-0.5 text-[12.5px] font-medium ${day.status === "major" ? "text-red-600 dark:text-red-400" : day.status === "degraded" ? "text-amber-700 dark:text-amber-400" : ""}`}
              >
                {said(day)}
              </p>
              {day.incidents?.map((t) => (
                <p
                  key={t}
                  className="mt-1 text-[11.5px] leading-[1.4] text-muted-foreground"
                >
                  {t}
                </p>
              ))}
            </>
          )}
        </div>

        <div
          ref={barsRef}
          role="group"
          tabIndex={0}
          aria-labelledby={`${id}-name`}
          aria-describedby={`${id}-help`}
          onPointerMove={(e) => {
            const bar = (e.target as HTMLElement).closest<HTMLElement>(
              "[data-bar]",
            );
            if (bar) {
              setKeyed(false);
              setActive(Number(bar.dataset.bar));
            }
          }}
          onPointerLeave={() => !keyed && setActive(null)}
          onBlur={() => setActive(null)}
          onKeyDown={(e) => {
            const at = active ?? last;
            if (e.key === "ArrowLeft") move(at - 1);
            else if (e.key === "ArrowRight") move(at + 1);
            else if (e.key === "Home") move(0);
            else if (e.key === "End") move(last);
            else if (e.key === "Escape") return setActive(null);
            else return;
            e.preventDefault();
          }}
          onFocus={() => active === null && move(last)}
          className={`flex h-8 items-stretch gap-[2px] rounded-[4px] ${FOCUS} focus-visible:ring-offset-2 focus-visible:ring-offset-background`}
        >
          {s.days.map((d, i) => (
            <span
              key={d.date}
              data-bar={i}
              className={`min-w-[2px] flex-1 origin-bottom rounded-[2px] transition-[background-color,opacity] duration-500 ${BAR[d.status]} ${i < s.days.length - 30 ? "hidden @lg:block" : ""}`}
              style={{ opacity: active === null || active === i ? 1 : 0.55 }}
            />
          ))}
        </div>
        <span id={`${id}-help`} className="sr-only">
          {`${s.name} is ${WORD[s.status].toLowerCase()}. Arrow keys read each day.`}
        </span>
        <span className="sr-only" role="status">
          {keyed ? spoken : ""}
        </span>
      </div>

      <div className="mt-1.5 flex justify-between text-[11px] text-muted-foreground">
        <span>
          <span className="@lg:hidden">
            {Math.min(30, s.days.length)} days ago
          </span>
          <span className="hidden @lg:inline">{s.days.length} days ago</span>
        </span>
        <span>Today</span>
      </div>
    </div>
  );
}

function Incident({
  inc,
  reduced,
  open,
  onToggle,
}: {
  inc: StatusIncident;
  reduced: boolean;
  open: boolean;
  onToggle?: () => void;
}) {
  const seen = React.useRef(new Set(inc.updates.map((u) => u.id)));
  const listRef = React.useRef<HTMLOListElement>(null);
  // A new update opens in on top.
  React.useLayoutEffect(() => {
    const fresh = inc.updates.filter((u) => !seen.current.has(u.id));
    fresh.forEach((u) => seen.current.add(u.id));
    if (reduced || !fresh.length) return;
    for (const u of fresh) {
      const el = listRef.current?.querySelector<HTMLElement>(
        `[data-update="${CSS.escape(u.id)}"]`,
      );
      el?.animate(
        [
          { opacity: 0, transform: "translateY(-6px)", filter: "blur(4px)" },
          { opacity: 1, transform: "none", filter: "blur(0px)" },
        ],
        { duration: 460, easing: EASE },
      );
    }
  }, [inc.updates, reduced]);
  const tick =
    inc.stage === "resolved"
      ? "bg-emerald-500"
      : inc.impact === "major"
        ? "bg-red-500"
        : inc.impact === "minor"
          ? "bg-amber-500"
          : "bg-foreground/35";
  const updates = open ? inc.updates : inc.updates.slice(0, 1);
  return (
    <article className="relative rounded-[14px] py-3 pr-3 pl-4 shadow-[inset_0_0_0_1px_var(--border)]">
      <span
        aria-hidden="true"
        className={`absolute top-3 bottom-3 left-0 w-0.5 rounded-full transition-colors duration-500 ${tick}`}
      />
      <div className="flex items-start justify-between gap-3">
        <h3 className="min-w-0 text-[13.5px] font-medium tracking-[-0.01em]">
          {inc.title}
        </h3>
        <span
          className={`shrink-0 rounded-full px-2 py-0.5 text-[11px] font-medium shadow-[inset_0_0_0_1px_var(--border)] transition-colors duration-500 ${inc.stage === "resolved" ? "text-emerald-600 dark:text-emerald-400" : "text-foreground"}`}
        >
          <TextMorph>{STAGES[inc.stage]}</TextMorph>
        </span>
      </div>
      {inc.services?.length ? (
        <p className="mt-0.5 text-[11.5px] text-muted-foreground">
          {inc.services.join(", ")}
        </p>
      ) : null}
      <ol ref={listRef} className="mt-2.5 space-y-2.5">
        {updates.map((u) => (
          <li
            key={u.id}
            data-update={u.id}
            className="grid grid-cols-[5.5rem_minmax(0,1fr)] gap-x-3 text-[12.5px]"
          >
            <span className="text-[11.5px] text-muted-foreground">
              <span className="block font-medium text-foreground">
                {STAGES[u.stage]}
              </span>
              <RelativeTime date={u.at} />
            </span>
            <p className="leading-[1.5] text-foreground/90">{u.message}</p>
          </li>
        ))}
      </ol>
      {onToggle && inc.updates.length > 1 && (
        <button
          type="button"
          aria-expanded={open}
          onClick={onToggle}
          className={`mt-2 -ml-2 h-7 cursor-pointer rounded-full px-2 text-[12px] font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
        >
          <TextMorph>
            {open ? "Fewer updates" : `All ${inc.updates.length} updates`}
          </TextMorph>
        </button>
      )}
    </article>
  );
}

export function StatusBars({
  services,
  incidents = NONE,
  updatedAt,
  title = "Status",
