      )}

      <section
        aria-label="Services"
        className="divide-y divide-border px-4 py-4 @md:px-5"
      >
        {services.map((s) => (
          <Service key={s.id} s={s} reduced={reduced} />
        ))}
      </section>

      {past.length > 0 && (
        <section
          aria-label="Past incidents"
          className="border-t border-border px-4 py-3 @md:px-5"
        >
          <button
            type="button"
            aria-expanded={showPast}
            onClick={() => setShowPast((v) => !v)}
            className={`-ml-2 inline-flex h-7 cursor-pointer items-center gap-1.5 rounded-full px-2 text-[12px] font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
          >
            <TextMorph>
              {showPast ? "Hide past incidents" : "Past incidents"}
            </TextMorph>
            <span className="tabular-nums">
              <NumberRoll value={past.length} />
            </span>
          </button>
          <div
            className="grid"
            inert={!showPast}
            style={{
              gridTemplateRows: showPast ? "1fr" : "0fr",
              opacity: showPast ? 1 : 0,
              transition: reduced
                ? "none"
                : `grid-template-rows 460ms ${EASE}, opacity 300ms ${EASE}`,
            }}
          >
            <div className="min-h-0 min-w-0 overflow-clip">
              <div className="space-y-2.5 pt-2.5 pb-1">
                {past.map((inc) => (
                  <Incident
                    key={inc.id}
                    inc={inc}
                    reduced={reduced}
                    open={openPast === inc.id}
                    onToggle={() =>
                      setOpenPast((o) => (o === inc.id ? null : inc.id))
                    }
                  />
                ))}
              </div>
            </div>
          </div>
        </section>
      )}
    </div>
  );
}

"use client";

import * as React from "react";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * STATUS BUTTON: a button that tells you what happened
 *
 *   idle     "Save", with an optional icon
 *   pending  a spinner opens in; the label morphs to "Saving"
 *   success  a check draws itself; "Saved"
 *   error    the button gives a small shake; "Try again"
 *
 * Every change is one motion: the icon slot opens and closes,
 * icons swap through a blur, letters the labels share stay put
 * and the button's width eases to fit.
 * ───────────────────────────────────────────────────────── */

export type ActionStatus = "idle" | "pending" | "success" | "error";

export interface StatusButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  status?: ActionStatus;
  /** Labels per state; defaults to Save, Saving, Saved, Try again. */
  labels?: Partial<Record<ActionStatus, string>>;
  /** Shown before the label while idle. */
  icon?: React.ReactNode;
  variant?: "primary" | "outline" | "ghost";
  /** "sm" is 28px tall, for toolbars and headers. */
  size?: "default" | "sm";
  /** Called this long after success (ms), e.g. to go back to idle. */
  onReset?: () => void;
  resetAfter?: number;
}

const LABELS: Record<ActionStatus, string> = {
  idle: "Save",
  pending: "Saving",
  success: "Saved",
  error: "Try again",
};
const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function Check({ drawn, reduced }: { drawn: boolean; reduced: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="none">
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 420ms ${EASE} 120ms`
              : "none",
        }}
      />
    </svg>
  );
}

function Alert() {
  return (
    <svg viewBox="0 0 16 16" fill="none">
      <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeWidth="1.5" />
      <path
        d="M8 4.75v3.75"
        stroke="currentColor"
        strokeWidth="1.75"
        strokeLinecap="round"
      />
      <circle cx="8" cy="11" r="1" fill="currentColor" />
    </svg>
  );
}

export function StatusButton({
  status = "idle",
  labels,
  icon,
  variant = "primary",
  size = "default",
  onReset,
  resetAfter = 1800,
  className = "",
  onClick,
  ...props
}: StatusButtonProps) {
  const reduced = useReducedMotion();
  const ref = React.useRef<HTMLButtonElement>(null);
  const label = { ...LABELS, ...labels }[status];
  const showIcon = status !== "idle" || Boolean(icon);
  const busy = status === "pending";
  const sm = size === "sm";
  const iconSize = sm ? 14 : 16;

  // A short shake when it fails: the eye catches it even if you looked away.
  React.useEffect(() => {
    if (status !== "error" || reduced) return;
    ref.current?.animate(
      [
        { transform: "none" },
        { transform: "translateX(-4px)" },
        { transform: "translateX(4px)" },
        { transform: "translateX(-2px)" },
        { transform: "none" },
      ],
      { duration: 380, easing: "ease-out" },
    );
  }, [status, reduced]);

  React.useEffect(() => {
    if (status !== "success" || !onReset) return;
    const timer = window.setTimeout(onReset, resetAfter);
    return () => window.clearTimeout(timer);
  }, [status, onReset, resetAfter]);

  const tone =
    status === "error"
      ? "bg-red-500/10 text-red-600 shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_30%,transparent)] dark:text-red-400"
      : variant === "primary"
        ? "bg-primary text-primary-foreground hover:bg-primary/90"
        : variant === "ghost"
          ? `hover:bg-accent hover:text-foreground ${status === "idle" ? "text-muted-foreground" : "text-foreground"}`
          : "text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent";

  const icons: Record<ActionStatus, React.ReactNode> = {
    idle: icon,
    // Spins only while pending, so a hidden spinner never keeps the page busy.
    pending: (
      <span
        className={`${sm ? "size-3" : "size-3.5"} rounded-full border-[1.5px] border-current border-t-transparent opacity-80 motion-reduce:animate-none ${status === "pending" ? "animate-spin" : ""}`}
      />
    ),
    success: <Check drawn={status === "success"} reduced={reduced} />,
    error: <Alert />,
  };

  return (
    <>
      <button
        ref={ref}
        type="button"
        aria-busy={busy || undefined}
        aria-disabled={busy || undefined}
        onClick={(e) => {
          if (busy) return e.preventDefault();
          onClick?.(e);
        }}
        className={`cursor-pointer disabled:cursor-default aria-disabled:cursor-default inline-flex items-center justify-center whitespace-nowrap rounded-full font-medium transition-[background-color,color,box-shadow,scale,padding] duration-300 active:scale-[0.97] motion-reduce:active:scale-100 ${
          sm
            ? `h-7 text-[12px] ${variant === "ghost" ? "px-2.5" : "px-3"}`
            : "h-9 px-4 text-[13px]"
        } ${FOCUS} ${tone} ${className}`}
        {...props}
      >
        <span
          aria-hidden="true"
          className={`relative flex shrink-0 items-center justify-center ${sm ? "h-3.5 [&_svg]:size-3.5" : "h-4 [&_svg]:size-4"}`}
          style={{
            width: showIcon ? iconSize : 0,
            marginRight: showIcon ? (sm ? 5 : 6) : 0,
            transition: reduced
              ? "none"
              : `width 380ms ${EASE}, margin 380ms ${EASE}`,
          }}
        >
          {(Object.keys(icons) as ActionStatus[]).map((s) => (
            <span
              key={s}
              className="absolute inset-0 flex items-center justify-center"
              style={{
                opacity: s === status ? 1 : 0,
                transform: s === status ? "none" : "scale(0.6)",
                filter: s === status ? "none" : "blur(3px)",
                transition: reduced
                  ? "none"
                  : `opacity 260ms ${EASE}, transform 380ms ${EASE}, filter 260ms ${EASE}`,
              }}
            >
              {icons[s]}
            </span>
          ))}
        </span>
        <TextMorph>{label}</TextMorph>
      </button>
      {/* Outside the button, so the announcement isn't read as part of its name. */}
      <span className="sr-only" role="status">
        {status === "idle" ? "" : label}
      </span>
    </>
  );
}

"use client";

import {
  useEffect,
  useEffectEvent,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";
import { lifecycleEase, useLifecycleReducedMotion } from "./lifecycle-motion";

export interface TimelineStep {
  id: string;
  title: string;
  description: ReactNode;
}

export interface StepTimelineProps {
  /** Nonempty steps with unique, stable IDs. */
  steps: readonly TimelineStep[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Opt in to timed progression. */
  autoPlay?: boolean;
  duration?: number;
  disabled?: boolean;
  ariaLabel?: string;
  className?: string;
  style?: CSSProperties;
}

/** An independently usable, expanding step selector with optional timed progress. */
export function StepTimeline({
  steps,
  value,
  defaultValue,
  onValueChange,
  autoPlay = false,
  duration = 5500,
  disabled = false,
  ariaLabel = "Timeline",
  className = "",
  style,
}: StepTimelineProps) {
  const [internalValue, setInternalValue] = useState(
    defaultValue ?? steps[0]?.id,
  );
  const selected =
    steps.find((step) => step.id === (value ?? internalValue))?.id ??
    steps[0]?.id;
  const [restart, setRestart] = useState(0);
  const [paused, setPaused] = useState(false);
  const [hovered, setHovered] = useState(false);
  const [focused, setFocused] = useState(false);
  const [visible, setVisible] = useState(false);
  const [pageVisible, setPageVisible] = useState(true);
  const reduced = useLifecycleReducedMotion();
  const root = useRef<HTMLDivElement>(null);
  const fill = useRef<HTMLSpanElement>(null);
  const animation = useRef<Animation | null>(null);
  const cycling = autoPlay && !disabled && !reduced && steps.length > 1;
  const running =
    cycling && !paused && !hovered && !focused && visible && pageVisible;
  const select = (id: string) => {
    if (disabled) return;
    setInternalValue(id);
    setRestart((n) => n + 1);
    if (id !== selected) onValueChange?.(id);
  };
  const advance = useEffectEvent(() => {
    const next =
      steps[
        (steps.findIndex((step) => step.id === selected) + 1) % steps.length
      ];
    if (next) select(next.id);
  });

  useEffect(() => {
    const node = root.current;
    if (!node) return;
    const observer = new IntersectionObserver(
      ([entry]) => setVisible(entry.isIntersecting),
      { threshold: 0.25 },
    );
    observer.observe(node);
    const update = () => setPageVisible(!document.hidden);
    update();
    document.addEventListener("visibilitychange", update);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", update);
    };
  }, []);

  useEffect(() => {
    if (!cycling || !fill.current) return;
    const playback = fill.current.animate(
      [{ transform: "scaleY(0)" }, { transform: "scaleY(1)" }],
      { duration: Math.max(1000, duration), fill: "both", easing: "linear" },
    );
    playback.pause();
    playback.onfinish = () => advance();
    animation.current = playback;
    return () => {
      playback.cancel();
      animation.current = null;
    };
  }, [selected, restart, cycling, duration]);

  useEffect(() => {
    if (running) animation.current?.play();
    else animation.current?.pause();
  }, [running, selected, restart, cycling, duration]);

  if (!steps.length) return null;
  return (
    <div
      ref={root}
      className={`w-full text-foreground ${className}`}
      style={style}
    >
      <ol
        aria-label={ariaLabel}
        className="m-0 list-none p-0"
        onMouseEnter={() => setHovered(true)}
        onMouseLeave={() => setHovered(false)}
        onFocusCapture={() => setFocused(true)}
        onBlurCapture={(event) => {
          if (!event.currentTarget.contains(event.relatedTarget))
            setFocused(false);
        }}
      >
        {steps.map((step, index) => {
          const active = selected === step.id;
          return (
            <li key={step.id}>
              <button
                type="button"
                aria-pressed={active}
                aria-expanded={active}
                aria-label={step.title}
                disabled={disabled}
                onClick={() => select(step.id)}
                onKeyDown={(event) => {
                  const direction =
                    event.key === "ArrowDown" || event.key === "ArrowRight"
                      ? 1
                      : event.key === "ArrowUp" || event.key === "ArrowLeft"
                        ? -1
                        : 0;
                  const next =
                    event.key === "Home"
                      ? 0
                      : event.key === "End"
                        ? steps.length - 1
                        : direction
                          ? (index + direction + steps.length) % steps.length
                          : null;
                  if (next === null) return;
                  event.preventDefault();
                  select(steps[next].id);
                  root.current
                    ?.querySelectorAll<HTMLButtonElement>("ol button")
                    [next]?.focus();
                }}
                className="group relative block w-full cursor-pointer rounded-sm py-4 pl-7 text-left outline-offset-4 focus-visible:outline-2 focus-visible:outline-ring disabled:cursor-not-allowed disabled:opacity-50"
              >
                <span
                  aria-hidden="true"
                  className="absolute inset-y-1 left-0 w-0.5 overflow-hidden rounded-full bg-border"
                >
                  {active && (
                    <span
                      key={`${step.id}-${restart}`}
                      ref={fill}
                      className="absolute inset-0 origin-top bg-foreground"
                    />
                  )}
                </span>
                <span
                  className={`block transition-colors duration-300 motion-reduce:transition-none ${active ? "text-foreground" : "text-muted-foreground group-hover:text-foreground"}`}
                >
                  <span className="block text-[22px] leading-[1.25] font-normal tracking-[-0.02em] [font-family:var(--timeline-display-font,inherit)] md:text-[24px]">
                    {step.title}
                  </span>
                  <span
                    aria-hidden={!active}
                    inert={!active}
                    className="grid motion-reduce:transition-none"
                    style={{
                      gridTemplateRows: active ? "1fr" : "0fr",
                      transition: reduced
                        ? "none"
                        : `grid-template-rows 500ms ${lifecycleEase}`,
                    }}
                  >
                    <span className="min-h-0 overflow-hidden">
                      <span className="block max-w-96 pt-2 text-[16.5px] leading-[1.55] tracking-[-0.012em] text-pretty text-muted-foreground">
                        {step.description}
                      </span>
                    </span>
                  </span>
                </span>
              </button>
            </li>
          );
        })}
      </ol>
      {autoPlay && !reduced && (
        <button
          type="button"
          disabled={disabled}
          onClick={() => setPaused((current) => !current)}
          className="mt-4 min-h-11 cursor-pointer rounded-full border border-border px-4 text-xs text-muted-foreground outline-offset-4 focus-visible:outline-2 disabled:cursor-not-allowed disabled:opacity-50"
          aria-label={paused ? "Play timeline" : "Pause timeline"}
        >
          {paused ? "Play" : "Pause"}
        </button>
      )}
    </div>
  );
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";

/* ─────────────────────────────────────────────────────────
 * STEPPER INPUT: a tactile number control with acceleration
 *
 *   single tap   increments or decrements by step, rolling
 *                the odometer in the direction of travel
 *   holding      waits 300ms, then accelerates smoothly from
 *                100ms down to 30ms intervals with scaled steps
 *   boundary     hitting min or max bounds disables the action
 *                and gives the container an elastic bumper shake
 *   direct edit  clicking the number reveals an exact input,
 *                committing on blur or Enter, cancelling on Escape
 * ───────────────────────────────────────────────────────── */

export interface StepperInputProps {
  /** Accessible label, e.g. "Team seats" or "Border radius". */
  label: string;
  value?: number;
  defaultValue?: number;
  onValueChange?: (value: number) => void;
  min?: number;
  max?: number;
  step?: number;
  /** Large step for PageUp/PageDown and prolonged acceleration. Defaults to step * 10. */
  largeStep?: number;
  /** Optional unit appended to the number, e.g. "px", "%", "seats". */
  unit?: string;
  /** Format options passed to NumberRoll when not editing. */
  format?: Intl.NumberFormatOptions;
  /** Visual variant: "pill" for rounded-full, "field" for standard form input. */
  variant?: "pill" | "field";
  size?: "sm" | "default";
  disabled?: boolean;
  name?: string;
  className?: string;
}

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function MinusIcon({ className = "size-3.5" }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      aria-hidden="true"
      className={className}
    >
      <path
        d="M3.5 8h9"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
      />
    </svg>
  );
}

function PlusIcon({ className = "size-3.5" }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      aria-hidden="true"
      className={className}
    >
      <path
        d="M8 3.5v9M3.5 8h9"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
      />
    </svg>
  );
}

const shake = (el: HTMLElement | null, reduced: boolean) => {
  if (!el || reduced) return;
  el.animate(
    [
      { transform: "none" },
      { transform: "translateX(-3px)" },
      { transform: "translateX(3px)" },
      { transform: "translateX(-1.5px)" },
      { transform: "none" },
    ],
    { duration: 280, easing: "ease-out", composite: "add" },
  );
};

export function StepperInput({
  label,
  value: controlledValue,
  defaultValue = 0,
  onValueChange,
  min = -Infinity,
  max = Infinity,
  step = 1,
  largeStep,
  unit,
  format,
  variant = "pill",
  size = "default",
  disabled = false,
  name,
  className = "",
}: StepperInputProps) {
  const reduced = useReducedMotion();
  const [uncontrolledValue, setUncontrolledValue] =
    React.useState(defaultValue);
  const isControlled = controlledValue !== undefined;
  const currentVal = isControlled ? controlledValue : uncontrolledValue;

  const [editing, setEditing] = React.useState(false);
  const [editText, setEditText] = React.useState(String(currentVal));

  const rootRef = React.useRef<HTMLDivElement>(null);
  const inputRef = React.useRef<HTMLInputElement>(null);
  const holdTimerRef = React.useRef<number | null>(null);
  const holdIntervalRef = React.useRef<number | null>(null);
  const holdStartRef = React.useRef<number>(0);

  const effectiveLargeStep = largeStep ?? step * 10;
  const atMin = currentVal <= min;
  const atMax = currentVal >= max;

  const clamp = React.useCallback(
    (n: number) => {
      let rounded = Math.round(n / step) * step;
      // Fix floating point precision, e.g. 0.1 + 0.2
      const stepDecimals = (step.toString().split(".")[1] || "").length;
      if (stepDecimals > 0) {
        rounded = Number(rounded.toFixed(stepDecimals));
      }
      return Math.min(max, Math.max(min, rounded));
    },
    [min, max, step],
  );

  const updateVal = React.useCallback(
    (nextRaw: number) => {
      const next = clamp(nextRaw);
      if (next === currentVal) {
        shake(rootRef.current, reduced);
        return false;
      }
      if (!isControlled) {
        setUncontrolledValue(next);
      }
      onValueChange?.(next);
      return true;
    },
    [clamp, currentVal, isControlled, onValueChange, reduced],
  );

  const stopHold = React.useCallback(() => {
    if (holdTimerRef.current !== null) {
      window.clearTimeout(holdTimerRef.current);
      holdTimerRef.current = null;
    }
    if (holdIntervalRef.current !== null) {
      window.clearInterval(holdIntervalRef.current);
      holdIntervalRef.current = null;
    }
  }, []);

  const stepDelta = React.useCallback(
    (dir: 1 | -1, multiplier = 1) => {
      const delta = step * multiplier * dir;
      return updateVal(currentVal + delta);
    },
    [currentVal, step, updateVal],
  );

  const startHold = React.useCallback(
    (dir: 1 | -1) => {
      if (disabled) return;
      stopHold();

      // Immediate first step
      const canMove = stepDelta(dir, 1);
      if (!canMove) return;

      holdStartRef.current = Date.now();

      // 300ms initial pause before rapid firing
      holdTimerRef.current = window.setTimeout(() => {
        const tick = () => {
          const elapsed = Date.now() - holdStartRef.current;
          let mult = 1;
          let intervalTime = 90;

          if (elapsed > 2400) {
            mult = Math.max(1, Math.round(effectiveLargeStep / step));
            intervalTime = 30;
          } else if (elapsed > 1200) {
            mult = Math.max(1, Math.round(effectiveLargeStep / step / 2));
            intervalTime = 55;
          }

          const ok = stepDelta(dir, mult);
          if (!ok) {
            stopHold();
            return;
          }

          holdIntervalRef.current = window.setTimeout(tick, intervalTime);
        };
        tick();
      }, 300);
    },
    [disabled, effectiveLargeStep, step, stepDelta, stopHold],
  );

  React.useEffect(() => {
    return () => stopHold();
  }, [stopHold]);

  const commitEdit = React.useCallback(() => {
    setEditing(false);
    const parsed = parseFloat(editText);
    if (!Number.isNaN(parsed)) {
      updateVal(parsed);
    } else {
      setEditText(String(currentVal));
    }
  }, [currentVal, editText, updateVal]);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (disabled) return;

    if (e.key === "ArrowUp") {
      e.preventDefault();
      stepDelta(1, 1);
    } else if (e.key === "ArrowDown") {
      e.preventDefault();
      stepDelta(-1, 1);
    } else if (e.key === "PageUp") {
      e.preventDefault();
      updateVal(currentVal + effectiveLargeStep);
    } else if (e.key === "PageDown") {
      e.preventDefault();
      updateVal(currentVal - effectiveLargeStep);
    } else if (e.key === "Home" && min !== -Infinity) {
      e.preventDefault();
      updateVal(min);
    } else if (e.key === "End" && max !== Infinity) {
      e.preventDefault();
      updateVal(max);
    } else if (editing) {
      if (e.key === "Enter") {
        e.preventDefault();
        commitEdit();
      } else if (e.key === "Escape") {
        e.preventDefault();
        setEditing(false);
        setEditText(String(currentVal));
      }
    }
  };

  const isSmall = size === "sm";
  const hCls = isSmall ? "h-7" : "h-9";
  const btnW = isSmall ? "w-7" : "w-8";
  const roundedCls = variant === "pill" ? "rounded-full" : "rounded-lg";

  return (
    <div
      ref={rootRef}
      role="group"
      aria-label={label}
      tabIndex={disabled ? -1 : 0}
      onKeyDown={handleKeyDown}
      className={`inline-flex ${hCls} items-center border border-border bg-background p-0.5 select-none ${roundedCls} transition-[box-shadow,border-color] duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 ${disabled ? "opacity-50 pointer-events-none" : ""} ${className}`}
      style={{
        boxShadow: "0 0 0 1px transparent",
      }}
    >
      {/* Hidden input for HTML form submissions */}
      {name && <input type="hidden" name={name} value={currentVal} />}

      {/* Decrement Button */}
      <button
        type="button"
        tabIndex={-1}
        aria-label={`Decrease ${label}`}
        disabled={disabled || atMin}
        onPointerDown={(e) => {
          if (e.pointerType === "mouse" && e.button !== 0) return;
          try {
            e.currentTarget.setPointerCapture(e.pointerId);
          } catch {}
          startHold(-1);
        }}
        onPointerUp={(e) => {
          try {
            if (e.currentTarget.hasPointerCapture(e.pointerId)) {
              e.currentTarget.releasePointerCapture(e.pointerId);
            }
          } catch {}
          stopHold();
        }}
        onPointerCancel={stopHold}
        className={`flex ${btnW} h-full items-center justify-center ${variant === "pill" ? "rounded-full" : "rounded-md"} text-muted-foreground transition-colors hover:bg-muted hover:text-foreground active:scale-95 disabled:pointer-events-none disabled:opacity-30 cursor-pointer disabled:cursor-default touch-manipulation`}
      >
        <MinusIcon />
      </button>

      {/* Value Display / Direct Edit */}
      <div
        className="relative flex min-w-[3.25rem] flex-1 items-center justify-center px-2 font-mono text-[13px] tabular-nums text-foreground cursor-text"
        onClick={() => {
          if (disabled || editing) return;
          setEditing(true);
          setEditText(String(currentVal));
          setTimeout(() => inputRef.current?.select(), 10);
        }}
      >
        {editing ? (
          <input
            ref={inputRef}
            type="text"
            inputMode="numeric"
            value={editText}
            onChange={(e) => setEditText(e.target.value)}
            onBlur={commitEdit}
            className="w-full bg-transparent text-center font-mono text-[13px] text-foreground outline-none [appearance:textfield] [&::-webkit-inner-spin-button]:appearance-none [&::-webkit-outer-spin-button]:appearance-none"
            autoFocus
          />
        ) : (
          <div className="flex items-baseline gap-1" aria-hidden="true">
            <NumberRoll value={currentVal} format={format} duration={260} />
            {unit && (
              <span className="font-sans text-[11px] text-muted-foreground">
                {unit}
              </span>
            )}
          </div>
        )}

        {/* Screen reader live value */}
        <span className="sr-only" role="status" aria-live="polite">
          {label}: {currentVal} {unit ?? ""}
        </span>
      </div>

      {/* Increment Button */}
      <button
        type="button"
        tabIndex={-1}
        aria-label={`Increase ${label}`}
        disabled={disabled || atMax}
        onPointerDown={(e) => {
          if (e.pointerType === "mouse" && e.button !== 0) return;
          try {
            e.currentTarget.setPointerCapture(e.pointerId);
          } catch {}
          startHold(1);
        }}
        onPointerUp={(e) => {
          try {
            if (e.currentTarget.hasPointerCapture(e.pointerId)) {
              e.currentTarget.releasePointerCapture(e.pointerId);
            }
          } catch {}
          stopHold();
        }}
        onPointerCancel={stopHold}
        className={`flex ${btnW} h-full items-center justify-center ${variant === "pill" ? "rounded-full" : "rounded-md"} text-muted-foreground transition-colors hover:bg-muted hover:text-foreground active:scale-95 disabled:pointer-events-none disabled:opacity-30 cursor-pointer disabled:cursor-default touch-manipulation`}
      >
        <PlusIcon />
      </button>
    </div>
  );
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * STEPS CHART: a week of steps against a daily goal
 *
 *   arrive    the first time it's on screen the days grow up out
 *             of the baseline one after another and the total
 *             rolls up from zero
 *   week      ‹ and › step through the weeks: the label morphs,
 *             each day eases to its new height in a wave that
 *             runs the way you went, days that made the goal
 *             turn your primary colour, the totals roll
 *   goal      a line at the goal in your primary colour; days at or over it are
 *             filled, a day still in progress is drawn as an
 *             outline with its fill so far
 *   hover     a thin line column follows the pointer and the
 *             readout at its top slides along, the day morphing
 *             and the steps rolling
 *
 * The plot is one tab stop: arrow keys move between days and the
 * readout is announced. Every day is also in a table for screen
 * readers.
 * ───────────────────────────────────────────────────────── */

export interface StepsDay {
  /** The same in every week (e.g. "mon"), so a day keeps its bar from week to week. */
  key: string;
  /** Under the bar, e.g. "Mon". */
  label: string;
  value: number;
  /** In the readout, e.g. "Thursday 2 October". Defaults to label. */
  title?: string;
  /** A day still under way: drawn as an outline with its fill so far. */
  today?: boolean;
}

export interface StepsWeek {
  id: string;
  /** Between the arrows, e.g. "This week" or "22 to 28 Sept". */
  label: string;
  days: StepsDay[];
}

export interface StepsChartProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onChange"
> {
  /** Oldest first; it opens on the last. */
  weeks: StepsWeek[];
  /** Steps a day. */
  goal?: number;
  value?: string;
  defaultValue?: string;
  onValueChange?: (id: string) => void;
  title?: string;
  locales?: string | string[];
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const PLOT = 176;
const HEADROOM = 30;
const LABELS = 26;
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const COMPACT: Intl.NumberFormatOptions = {
  notation: "compact",
  maximumFractionDigits: 1,
};

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function niceMax(value: number) {
  if (value <= 0) return 1;
  const step = 10 ** Math.floor(Math.log10(value));
  for (const m of [1, 1.2, 1.5, 2, 2.5, 3, 4, 5, 6, 8, 10])
    if (m * step >= value) return m * step;
  return 10 * step;
}

function Arrow({
  dir,
  disabled,
  onClick,
}: {
  dir: -1 | 1;
  disabled: boolean;
  onClick: () => void;
}) {
  return (
    <button
      type="button"
      aria-label={dir < 0 ? "Previous week" : "Next week"}
      aria-disabled={disabled || undefined}
      onClick={() => !disabled && onClick()}
      className={`flex size-7 items-center justify-center rounded-full text-foreground transition-[background-color,opacity] duration-300 ${FOCUS} ${
        disabled ? "cursor-default opacity-30" : "hover:bg-accent"
      }`}
    >
      <svg
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth={1.6}
        strokeLinecap="round"
        strokeLinejoin="round"
        aria-hidden="true"
        className="size-3.5"
      >
        <path d={dir < 0 ? "M10 3.5 5.5 8l4.5 4.5" : "M6 3.5 10.5 8 6 12.5"} />
      </svg>
    </button>
  );
}

export function StepsChart({
  weeks,
  goal = 10_000,
  value,
  defaultValue,
  onValueChange,
  title = "Steps",
  locales,
  className = "",
  ...props
}: StepsChartProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const [own, setOwn] = React.useState(
    defaultValue ?? weeks[weeks.length - 1]?.id,
  );
  const weekId = value ?? own;
  const index = Math.max(
    0,
    weeks.findIndex((w) => w.id === weekId),
  );
  const week = weeks[index];
  const days = week?.days ?? [];

  // The scale holds still across weeks (the busiest week sets it), so heights compare from week to week.
  const max = niceMax(
    Math.max(goal * 1.2, ...weeks.flatMap((w) => w.days.map((d) => d.value))),
  );
  const total = days.reduce((sum, d) => sum + d.value, 0);
  // The average leaves out days still to come and a day still under way.
  const counted = days.filter(
    (d) => d.value > 0 && (!d.today || d.value >= goal),
  );
  const average = counted.length
    ? Math.round(counted.reduce((sum, d) => sum + d.value, 0) / counted.length)
    : 0;
  const met = days.filter((d) => d.value >= goal).length;
  const slot = days.length ? 100 / days.length : 100;
  const scale = (n: number) => (n / max) * (plotH - HEADROOM);

  const [visible, setVisible] = React.useState(false);
  const [plotH, setPlotH] = React.useState(PLOT);
  const [active, setActive] = React.useState<number | null>(null);
  const [keyboard, setKeyboard] = React.useState(false);
  const [dir, setDir] = React.useState(1);
  const [shownIndex, setShownIndex] = React.useState(index);
  const rootRef = React.useRef<HTMLDivElement>(null);
  const barsRef = React.useRef<HTMLDivElement>(null);
  const plotRef = React.useRef<HTMLDivElement>(null);

  // The wave runs the way you went: back in time from the right, forward from the left.
  if (shownIndex !== index) {
    setDir(index > shownIndex ? 1 : -1);
    setShownIndex(index);
  }

  // The plot's height is set by the card's width in CSS; read it so the drawing fits.
  React.useLayoutEffect(() => {
    const el = plotRef.current;
    if (!el) return;
    const measure = () =>
      setPlotH((h) => {
        const next = el.offsetHeight - LABELS;
        return next > 0 && next !== h ? next : h;
      });
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  React.useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          observer.disconnect();
        }
      },
      { rootMargin: "0px 0px -10% 0px" },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  const go = (d: -1 | 1) => {
    const next = weeks[index + d];
    if (!next) return;
    if (value === undefined) setOwn(next.id);
    onValueChange?.(next.id);
  };

  // Days still to come can't be read: the readout stops at today.
  const lastDay = Math.max(
    0,
    days.reduce((last, d, i) => (d.value > 0 || d.today ? i : last), -1),
  );
  const pointAt = (clientX: number) => {
    const r = barsRef.current?.getBoundingClientRect();
    if (!r || !days.length) return null;
    return Math.min(
      lastDay,
      Math.max(0, Math.floor(((clientX - r.left) / r.width) * days.length)),
    );
  };

  const onKeyDown = (e: React.KeyboardEvent) => {
    if (!days.length) return;
    const from =
      active ??
      Math.max(
        0,
        days.findIndex((d) => d.today) === -1
          ? days.length - 1
          : days.findIndex((d) => d.today),
      );
    const moves: Record<string, number> = {
      ArrowLeft: from - 1,
      ArrowRight: from + 1,
      Home: 0,
      End: lastDay,
    };
    if (e.key === "Escape") return setActive(null);
    if (!(e.key in moves)) return;
    e.preventDefault();
    setKeyboard(true);
    setActive(
      Math.min(lastDay, Math.max(0, active === null ? from : moves[e.key])),
    );
  };

  const fmt = (n: number) => new Intl.NumberFormat(locales).format(n);
  const shown = active !== null ? days[active] : null;
  const goalTop = HEADROOM + (plotH - HEADROOM) - scale(goal);

  return (
    <div
      ref={rootRef}
      className={`@container w-full rounded-[22px] bg-background shadow-[0_0_0_1px_var(--border)] ${className}`}
      {...props}
    >
      <div className="p-4 @md:p-5 [--gutter:30px] @md:[--gutter:40px] [--plot:148px] @md:[--plot:176px]">
        {/* The title and the week share a row; the figures sit under both. */}
        <div className="flex items-center justify-between gap-3">
          <p className="truncate text-[12px] text-muted-foreground @md:text-[13px]">
            {title}
          </p>
          <div className="-my-1 -mr-1.5 flex shrink-0 items-center">
            <Arrow dir={-1} disabled={index === 0} onClick={() => go(-1)} />
            <span
              className="min-w-[78px] px-0.5 text-center text-[11.5px] font-medium text-foreground @md:min-w-[92px] @md:text-[12.5px]"
              aria-live="polite"
            >
              <TextMorph direction={dir > 0 ? "up" : "down"}>
                {week?.label ?? ""}
              </TextMorph>
            </span>
            <Arrow
              dir={1}
              disabled={index === weeks.length - 1}
              onClick={() => go(1)}
            />
          </div>
        </div>
        <p className="mt-0.5 flex items-baseline gap-1.5 text-[22px] font-medium leading-tight tracking-[-0.03em] text-foreground @md:text-[26px]">
          <NumberRoll
            value={visible ? total : 0}
            locales={locales}
            duration={1000}
          />
          <span className="text-[12px] font-normal tracking-normal text-muted-foreground">
            steps
          </span>
        </p>
        <p className="mt-1 flex flex-wrap items-baseline gap-x-3 gap-y-0.5 text-[11.5px] text-muted-foreground @md:text-[12.5px]">
          <span className="flex items-baseline gap-[0.3em]">
            <NumberRoll
              value={visible ? average : 0}
              locales={locales}
              duration={800}
              className="text-foreground"
            />
            a day
          </span>
          <span className="flex items-baseline gap-[0.3em]">
            Goal met on
            <NumberRoll
              value={visible ? met : 0}
              duration={700}
              className="text-foreground"
            />
            of {days.length} days
          </span>
        </p>

        <div
          ref={plotRef}
          role="group"
          tabIndex={0}
          aria-label={`${title}, ${week?.label ?? ""}. Use the arrow keys to read each day.`}
          onKeyDown={onKeyDown}
          onBlur={() => keyboard && (setActive(null), setKeyboard(false))}
          onPointerMove={(e) => {
            setKeyboard(false);
            setActive(pointAt(e.clientX));
          }}
          onPointerDown={(e) => setActive(pointAt(e.clientX))}
          onPointerLeave={(e) => e.pointerType === "mouse" && setActive(null)}
          className={`relative mt-4 touch-pan-y @md:mt-5 select-none rounded-lg ${FOCUS}`}
          style={{ height: `calc(var(--plot) + ${LABELS}px)` }}
        >
          {/* The scale: the top and the baseline, and the goal as a line in your primary colour. */}
          {[1, 0].map((f) => (
            <div
              key={f}
              aria-hidden="true"
              className="absolute right-0"
              style={{ left: 0, top: HEADROOM + (1 - f) * (plotH - HEADROOM) }}
            >
              <span
                className="absolute left-0 top-0 -translate-y-1/2 text-[10px] leading-none tabular-nums text-muted-foreground/80"
                style={{
                  width: "calc(var(--gutter) - 8px)",
                  textAlign: "right",
                }}
              >
                <NumberRoll
                  value={max * f}
                  format={COMPACT}
                  locales={locales}
                  duration={700}
                />
              </span>
              <div
                className="border-t border-border"
                style={{ marginLeft: "var(--gutter)" }}
              />
            </div>
          ))}
          <div
            aria-hidden="true"
            className="absolute right-0"
            style={{ left: 0, top: goalTop }}
          >
            <span
              className="absolute left-0 top-0 -translate-y-1/2 text-[10px] font-medium leading-none tabular-nums text-primary"
              style={{ width: "calc(var(--gutter) - 8px)", textAlign: "right" }}
            >
              <NumberRoll
                value={goal}
                format={COMPACT}
                locales={locales}
                duration={700}
              />
            </span>
            <div
              className="border-t border-primary/60"
              style={{ marginLeft: "var(--gutter)" }}
            />
          </div>

          <div
            ref={barsRef}
            className="absolute inset-y-0 right-0"
            style={{ left: "var(--gutter)" }}
          >
            {/* The hovered day: a thin line lane from the readout down to the baseline. */}
            <div
              aria-hidden="true"
              className="pointer-events-none absolute rounded-[10px] bg-foreground/[0.02] shadow-[inset_0_0_0_1px_var(--border)]"
              style={{
                top: 2,
                height: plotH - 2,
                left: active !== null ? `calc(${active * slot}% + 2px)` : 0,
                width: active !== null ? `calc(${slot}% - 4px)` : 0,
                opacity: active !== null ? 1 : 0,
                transition: reduced
                  ? "none"
                  : `left 380ms ${THROW}, width 380ms ${EASE}, opacity 200ms ${EASE}`,
              }}
            />

            {days.map((d, i) => {
              const made = d.value >= goal;
              const hovered = active === i;
              const order = dir > 0 ? i : days.length - 1 - i;
              const tone = d.today
                ? made
                  ? "bg-primary"
                  : "bg-primary/15 shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--primary)_55%,transparent)]"
                : made
                  ? hovered || active === null
                    ? "bg-primary"
                    : "bg-primary/70"
                  : hovered
                    ? "bg-foreground/25"
                    : active !== null
                      ? "bg-foreground/[0.07]"
                      : "bg-foreground/[0.11]";
              return (
                <div
                  key={d.key}
                  aria-hidden="true"
                  className="absolute top-0 h-full"
                  style={{ left: `${i * slot}%`, width: `${slot}%` }}
                >
                  <div
                    className={`absolute bottom-[26px] left-1/2 w-[min(24px,58%)] -translate-x-1/2 rounded-t-[4px] ${tone}`}
                    style={{
                      // Days still to come have no bar at all.
                      height:
                        visible && d.value > 0
                          ? Math.max(2, scale(d.value))
                          : 0,
                      transition: reduced
                        ? "none"
                        : `height 620ms ${EASE} ${order * 34}ms, background-color 320ms ${EASE}, box-shadow 320ms ${EASE}`,
                    }}
                  />
                  <span
                    className={`absolute inset-x-0 bottom-0 text-center text-[11px] leading-[18px] ${d.today ? "font-medium text-foreground" : "text-muted-foreground"}`}
                  >
                    {d.label}
                  </span>
                </div>
              );
            })}

            {/* The readout rides the top of the lane: the day morphs, the steps roll. */}
            <div
              aria-hidden="true"
              className="pointer-events-none absolute top-[5px] flex h-[22px] -translate-x-1/2 items-center gap-1.5 whitespace-nowrap rounded-full bg-background px-2.5 text-[11.5px] shadow-[0_0_0_1px_var(--border)]"
              style={{
                left:
                  active !== null
                    ? `clamp(64px, ${(active + 0.5) * slot}%, calc(100% - 64px))`
                    : "50%",
                opacity: shown ? 1 : 0,
                scale: shown ? "1" : "0.94",
                transition: reduced
                  ? "none"
                  : `left 380ms ${THROW}, opacity 200ms ${EASE}, scale 260ms ${EASE}`,
              }}
            >
              <span className="text-muted-foreground">
                <TextMorph>
                  {shown ? (shown.title ?? shown.label) : " "}
                </TextMorph>
              </span>
              <span className="font-medium tabular-nums text-foreground">
                <NumberRoll
                  value={shown?.value ?? 0}
                  locales={locales}
                  duration={600}
                />
              </span>
            </div>
          </div>
        </div>

        <p aria-live="polite" className="sr-only">
          {keyboard && shown
            ? `${shown.title ?? shown.label}: ${fmt(shown.value)} steps${shown.value >= goal ? ", goal met" : ""}`
            : ""}
        </p>
        <table className="sr-only">
          <caption>
            {title}, {week?.label}: {fmt(total)} steps, goal {fmt(goal)} a day,
            met on {met} of {days.length} days
          </caption>
          <tbody>
            {days.map((d) => (
              <tr key={d.key} id={`${id}-${d.key}`}>
                <th scope="row">{d.title ?? d.label}</th>
                <td>
                  {fmt(d.value)}
                  {d.today ? " so far" : ""}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { AlertCircle } from "lucide-react";
import { NumberRoll } from "./number-roll";
import { StatusButton, type ActionStatus } from "./status-button";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * STEPS FORM: one card that walks you through, and changes shape
 *
 *   header    a bar of segments fills as you go; the step's name
 *             and title morph letter by letter and "2 / 4" rolls
 *   step      the next step slides in from the side you're going
 *             (and back from the other side), out of a blur, while
 *             the card eases to its height
 *   check     Continue runs the step's check: a message shakes the
 *             step and folds open under it; an async check shows
 *             "Checking" in the button first
 *   back      Back folds out of the footer on the first step
 *   submit    on the last step Continue morphs into your action;
 *             it spins, draws a check, and the whole card turns into
 *             what comes next
 *
 * It's a real form: Enter continues, and focus moves to the new
 * step's first field.
 * ───────────────────────────────────────────────────────── */

export interface FormStep {
  id: string;
  /** Short name for the header, e.g. "Plan". */
  label: string;
  title: string;
  description?: React.ReactNode;
  content: React.ReactNode;
  /** Return a message to stop on this step, or nothing to go on. */
  validate?: () =>
    | string
    | null
    | undefined
    | void
    | Promise<string | null | undefined | void>;
}

export interface StepsFormProps extends Omit<
  React.FormHTMLAttributes<HTMLFormElement>,
  "onSubmit" | "children"
> {
  steps: FormStep[];
  /** Runs after the last step's check; throw (with a message) to stay. */
  onSubmit: () => void | Promise<void>;
  /** The last button's labels: idle, while it runs, and when it's done. */
  submitLabels?: Partial<Record<"idle" | "pending" | "success", string>>;
  /** What the card becomes once it's submitted. */
  done?: React.ReactNode;
  onStepChange?: (index: number) => void;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** The part that changes: eases to each step's height, slides the new one in over the old one leaving. */
function Panel({
  id,
  dir,
  children,
  reduced,
}: {
  id: string;
  dir: number;
  children: React.ReactNode;
  reduced: boolean;
}) {
  const innerRef = React.useRef<HTMLDivElement>(null);
  const [height, setHeight] = React.useState<number | null>(null);
  const [ghost, setGhost] = React.useState<{
    id: string;
    node: React.ReactNode;
    dir: number;
  } | null>(null);
  const last = React.useRef({ id, node: children });

  React.useLayoutEffect(() => {
    const el = innerRef.current;
    if (!el) return;
    const measure = () => setHeight(el.offsetHeight);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, [id]);

  React.useLayoutEffect(() => {
    if (id === last.current.id) {
      last.current.node = children;
      return;
    }
    if (!reduced)
      setGhost({ id: last.current.id, node: last.current.node, dir });
    last.current = { id, node: children };
    if (reduced) return;
    innerRef.current?.animate(
      [
        {
          opacity: 0,
          transform: `translateX(${dir * 28}px)`,
          filter: "blur(4px)",
        },
        { opacity: 1, transform: "none", filter: "blur(0px)" },
      ],
      { duration: 420, delay: 60, easing: EASE, fill: "backwards" },
    );
  }, [id, children, dir, reduced]);

  return (
    <div
      className="relative overflow-hidden"
      style={{
        height: height ?? undefined,
        transition:
          reduced || height === null ? "none" : `height 440ms ${EASE}`,
      }}
    >
      {ghost && (
        <div
          key={`ghost-${ghost.id}`}
          aria-hidden="true"
          inert
          className="pointer-events-none absolute inset-x-0 top-0"
          ref={(el) => {
            if (!el || el.dataset.out) return;
            el.dataset.out = "1";
            const a = el.animate(
              [
                { opacity: 1, transform: "none", filter: "blur(0px)" },
                {
                  opacity: 0,
                  transform: `translateX(${ghost.dir * -28}px)`,
                  filter: "blur(4px)",
                },
              ],
              { duration: 260, easing: EASE, fill: "forwards" },
            );
            a.onfinish = () => setGhost((g) => (g?.id === ghost.id ? null : g));
          }}
        >
          {ghost.node}
        </div>
      )}
      <div key={id} ref={innerRef}>
        {children}
      </div>
    </div>
  );
}

export function StepsForm({
  steps,
  onSubmit,
  submitLabels,
  done,
  onStepChange,
  className = "",
  ...props
}: StepsFormProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const formRef = React.useRef<HTMLFormElement>(null);
  const bodyRef = React.useRef<HTMLDivElement>(null);
  const [index, setIndex] = React.useState(0);
  const [dir, setDir] = React.useState(1);
  const [status, setStatus] = React.useState<ActionStatus>("idle");
  const [error, setError] = React.useState<string | null>(null);
  const [finished, setFinished] = React.useState(false);
  const [moved, setMoved] = React.useState(false);
  const step = steps[index];
  const last = index === steps.length - 1;
  const working = status === "pending" || status === "success";

  const go = (next: number) => {
    setDir(next > index ? 1 : -1);
    setIndex(next);
    setError(null);
    setStatus("idle");
    setMoved(true);
    onStepChange?.(next);
  };

  // A new step: put the cursor in its first field (not on first load, which shouldn't steal focus).
  React.useEffect(() => {
    if (!moved) return;
    const field = bodyRef.current?.querySelector<HTMLElement>(
      "[data-autofocus], input:not([type=hidden]), select, textarea",
    );
    field?.focus({ preventScroll: true });
  }, [index, moved]);

  const shake = () => {
    if (reduced) return;
    bodyRef.current?.animate(
      [
        { transform: "none" },
        { transform: "translateX(-6px)" },
        { transform: "translateX(5px)" },
        { transform: "translateX(-3px)" },
        { transform: "translateX(2px)" },
        { transform: "none" },
      ],
      { duration: 380, easing: "ease-out" },
    );
  };

  const next = async () => {
    if (working) return;
    setError(null);
    const check = step.validate?.();
    if (check instanceof Promise) setStatus("pending");
    const message = await check;
    if (message) {
      setStatus("idle");
      setError(message);
      shake();
      return;
    }
    if (!last) return go(index + 1);
    setStatus("pending");
    try {
      await onSubmit();
      setStatus("success");
      window.setTimeout(() => setFinished(true), reduced ? 0 : 750);
    } catch (e) {
      setStatus("error");
      setError(
        e instanceof Error && e.message
          ? e.message
          : "That didn’t work. Try again.",
      );
      shake();
    }
  };

  const labels = last
    ? {
        idle: submitLabels?.idle ?? "Create",
        pending: submitLabels?.pending ?? "Creating",
        success: submitLabels?.success ?? "Created",
        error: "Try again",
      }
    : {
        idle: "Continue",
        pending: "Checking",
        success: "Continue",
        error: "Continue",
      };

  return (
    <form
      ref={formRef}
      noValidate
      aria-labelledby={`${id}-title`}
      onSubmit={(e) => {
        e.preventDefault();
        void next();
      }}
      // Once they start fixing it, the message folds away.
      onInput={() => error && status !== "error" && setError(null)}
      onChange={() => error && status !== "error" && setError(null)}
      className={`@container w-full rounded-[20px] border border-border bg-card text-card-foreground ${className}`}
      {...props}
    >
      {/* Header: folds away once it's done. */}
      <div
        className="grid"
        style={{
          gridTemplateRows: finished ? "0fr" : "1fr",
          transition: reduced ? "none" : `grid-template-rows 420ms ${EASE}`,
        }}
      >
        <div className="overflow-hidden">
          <div className="px-4 pt-4 @md:px-5 @md:pt-5">
            <div className="flex items-center justify-between text-[12px] text-muted-foreground">
              <TextMorph>{step.label}</TextMorph>
              <span className="tabular-nums" aria-hidden="true">
                <NumberRoll value={index + 1} duration={450} /> / {steps.length}
              </span>
            </div>
            <div className="mt-2 flex gap-1" aria-hidden="true">
              {steps.map((s, i) => (
                <span
                  key={s.id}
                  className="h-1 flex-1 overflow-hidden rounded-full bg-muted"
                >
                  <span
                    className="block h-full origin-left rounded-full bg-primary"
                    style={{
                      transform: `scaleX(${i <= index || finished ? 1 : 0})`,
                      transition: reduced
                        ? "none"
                        : `transform 520ms ${EASE} ${i === index && dir > 0 ? 80 : 0}ms`,
                    }}
                  />
                </span>
              ))}
            </div>
            <h2
              id={`${id}-title`}
              className="mt-4 text-[18px] font-semibold leading-tight tracking-tight text-foreground @md:text-[20px]"
            >
              <TextMorph>{step.title}</TextMorph>
            </h2>
          </div>
        </div>
      </div>

      <div ref={bodyRef} className="px-4 @md:px-5">
        <Panel
          id={finished ? "done" : step.id}
          dir={finished ? 1 : dir}
          reduced={reduced}
        >
          {finished ? (
            <div className="py-5">{done}</div>
          ) : (
            <div className="pb-1 pt-1.5">
              {step.description && (
                <div className="mb-4 text-[13px] leading-relaxed text-muted-foreground">
                  {step.description}
                </div>
              )}
              {step.content}
            </div>
          )}
        </Panel>
        {/* What stopped you, folding open under the step. */}
        <div
          className="grid"
          style={{
            gridTemplateRows: error && !finished ? "1fr" : "0fr",
            transition: reduced ? "none" : `grid-template-rows 300ms ${EASE}`,
          }}
        >
          <div className="overflow-hidden">
            <p
              role="alert"
              className="flex items-start gap-1.5 pt-2.5 text-[12.5px] leading-snug text-red-600 dark:text-red-400"
            >
              {error && (
                <AlertCircle
                  aria-hidden="true"
                  className="mt-px size-3.5 shrink-0"
                />
              )}
              {error}
            </p>
          </div>
        </div>
      </div>

      {/* Footer: Back folds away on the first step, everything folds away once it's done. */}
      <div
        className="grid"
        style={{
          gridTemplateRows: finished ? "0fr" : "1fr",
          transition: reduced ? "none" : `grid-template-rows 420ms ${EASE}`,
        }}
      >
        <div className="overflow-hidden">
          <div className="flex items-center gap-2 p-4 pt-5 @md:p-5">
            <div
              className="grid"
              style={{
                gridTemplateColumns: index > 0 ? "1fr" : "0fr",
                transition: reduced
                  ? "none"
                  : `grid-template-columns 360ms ${EASE}`,
              }}
            >
              <div className="overflow-hidden">
                <button
                  type="button"
                  tabIndex={index > 0 ? 0 : -1}
                  aria-hidden={index === 0}
                  disabled={working}
                  onClick={() => go(index - 1)}
                  className={`cursor-pointer disabled:cursor-default h-9 whitespace-nowrap rounded-full px-3.5 text-[13px] font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground disabled:opacity-50 ${FOCUS}`}
                >
                  Back
                </button>
              </div>
            </div>
            <StatusButton
              type="submit"
              status={status}
              labels={labels}
              className="ml-auto"
            />
          </div>
        </div>
      </div>
    </form>
  );
}

"use client";

import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";
import {
  EASE_OUT,
  EASE_THROW,
  INTERACTION_FOCUS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * STEPS: where you are in a flow
 *
 *   advance   the line to the next step fills along its length,
 *             the finished step's number blurs into a check that
 *             draws itself, and the new current step's ring pops in
 *   back      the line drains back and the check gives way to the
 *             number again
 *   narrow    in a small container it becomes "Step 2 of 4 ·
 *             Payment" with a filling bar; the number rolls and the
 *             step's name morphs
 *
 * Finished steps can be links back (`onStepClick`).
 * ───────────────────────────────────────────────────────── */

export interface Step {
  label: string;
  description?: string;
}

export interface StepsProps {
  steps: Step[];
  /** Index of the current step (0-based). steps.length means all done. */
  current: number;
  /** Let people go back to finished steps. */
  onStepClick?: (index: number) => void;
  orientation?: "horizontal" | "vertical";
  className?: string;
}

function Mark({
  index,
  state,
  reduced,
}: {
  index: number;
  state: "done" | "current" | "upcoming";
  reduced: boolean;
}) {
  const done = state === "done";
  return (
    <span
      className={`relative flex size-7 shrink-0 items-center justify-center rounded-full text-[12px] font-medium tabular-nums transition-[background-color,color,box-shadow] duration-300 ${
        done
          ? "bg-primary text-primary-foreground"
          : state === "current"
            ? "bg-background text-foreground shadow-[inset_0_0_0_1.5px_var(--primary)]"
            : "bg-background text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)]"
      }`}
    >
      {state === "current" && !reduced && (
        <span
          key="ring"
          aria-hidden="true"
          className="absolute -inset-1 rounded-full shadow-[0_0_0_1px_color-mix(in_oklab,var(--primary)_35%,transparent)] [animation:ui-pop-in_420ms_cubic-bezier(0.34,1.36,0.64,1)_both]"
        />
      )}
      <span
        className="absolute inset-0 flex items-center justify-center"
        style={{
          opacity: done ? 0 : 1,
          scale: done && !reduced ? "0.6" : "1",
          filter: done && !reduced ? "blur(3px)" : "none",
          transition: reduced
            ? "none"
            : `opacity 200ms ${EASE_OUT}, scale 320ms ${EASE_OUT}, filter 200ms ${EASE_OUT}`,
        }}
      >
        {index + 1}
      </span>
      <svg viewBox="0 0 16 16" fill="none" className="absolute size-3.5">
        <path
          d="M3.5 8.5 6.5 11.5 12.5 4.5"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
          pathLength={1}
          strokeDasharray={1}
          style={{
            strokeDashoffset: done ? 0 : 1,
            transition: reduced
              ? "none"
              : done
                ? `stroke-dashoffset 360ms ${EASE_OUT} 140ms`
                : `stroke-dashoffset 160ms ${EASE_OUT}`,
          }}
        />
      </svg>
    </span>
  );
}

export function Steps({
  steps,
  current,
  onStepClick,
  orientation = "horizontal",
  className = "",
}: StepsProps) {
  const reduced = useInteractionReducedMotion();
  const at = Math.max(0, Math.min(current, steps.length));
  const vertical = orientation === "vertical";
  const state = (i: number) =>
    i < at ? "done" : i === at ? "current" : "upcoming";
  const fill = (i: number) => (i < at ? 1 : 0);

  const list = (
    <ol className={`flex ${vertical ? "flex-col" : "w-full items-start"}`}>
      {steps.map((step, i) => {
        const s = state(i);
        const clickable = !!onStepClick && s === "done";
        const Head = clickable ? "button" : "div";
        return (
          <li
            key={step.label}
            aria-current={s === "current" ? "step" : undefined}
            className={`relative flex ${vertical ? "gap-3 pb-6 last:pb-0" : "flex-1 flex-col items-center gap-2 text-center"}`}
          >
            {/* The line to the next step: a thin line with a fill that runs along it. */}
            {i < steps.length - 1 && (
              <span
                aria-hidden="true"
                className={`absolute bg-border ${vertical ? "left-[13.5px] top-8 bottom-1 w-px" : "left-[calc(50%_+_20px)] right-[calc(-50%_+_20px)] top-[13.5px] h-px"}`}
              >
                <span
                  className={`absolute inset-0 bg-primary ${vertical ? "origin-top" : "origin-left"}`}
                  style={{
                    transform: vertical
                      ? `scaleY(${fill(i)})`
                      : `scaleX(${fill(i)})`,
                    transition: reduced
                      ? "none"
                      : `transform 520ms ${i < at ? EASE_OUT : EASE_THROW}`,
                  }}
                />
              </span>
            )}
            <Head
              {...(clickable
                ? {
                    type: "button" as const,
                    onClick: () => onStepClick(i),
                    "aria-label": `Back to ${step.label}`,
                  }
                : {})}
              className={`relative z-10 rounded-full ${clickable ? `cursor-pointer ${INTERACTION_FOCUS}` : ""}`}
            >
              <Mark index={i} state={s} reduced={reduced} />
            </Head>
            <span
              className={`flex min-w-0 flex-col gap-0.5 ${vertical ? "pt-1" : "px-1"}`}
            >
              <span
                className={`text-[13px] font-medium transition-colors duration-300 ${s === "upcoming" ? "text-muted-foreground" : "text-foreground"}`}
              >
                {step.label}
              </span>
              {step.description && (
                <span className="text-[12px] leading-snug text-muted-foreground">
                  {step.description}
                </span>
              )}
            </span>
          </li>
        );
      })}
    </ol>
  );

  if (vertical)
    return (
      <nav aria-label="Progress" className={className}>
        {list}
      </nav>
    );

  const name = steps[Math.min(at, steps.length - 1)]?.label ?? "";
  return (
    <nav aria-label="Progress" className={`@container w-full ${className}`}>
      <div className="hidden @[24rem]:block">{list}</div>
      {/* Narrow: one line and a bar. */}
      <div className="flex flex-col gap-2 @[24rem]:hidden">
        <div className="flex items-baseline justify-between gap-3 text-[13px]">
          <span className="tabular-nums text-muted-foreground">
            Step <NumberRoll value={Math.min(at + 1, steps.length)} /> of{" "}
            {steps.length}
          </span>
          <span className="font-medium text-foreground">
            <TextMorph>{at >= steps.length ? "Done" : name}</TextMorph>
          </span>
        </div>
        <div className="h-1 overflow-hidden rounded-full bg-muted">
          <div
            className="h-full origin-left rounded-full bg-primary"
            style={{
              transform: `scaleX(${Math.min(1, (at + (at < steps.length ? 0.5 : 0)) / steps.length)})`,
              transition: reduced ? "none" : `transform 520ms ${EASE_OUT}`,
            }}
          />
        </div>
      </div>
    </nav>
  );
}

