"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { playStrip, preloadStrips } from "./cast-sprite";
import { PACK_ART as ART, PACK_FRAMES as F } from "./pack-art";
import { StatusButton, type ActionStatus } from "./status-button";
import { TextMorph } from "./text-morph";
import {
  EASE_OUT,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * STORAGE: Pack and his suitcase
 *
 *   roomy    an animated raccoon, Pack, leans on his case at
 *            his ease
 *   full     crossing 90% the case bulges, a sock and a photo
 *            pop out of the zip, and he climbs on top and keeps
 *            pushing it down
 *   clean up the same clip backwards: the clothes go back in and
 *            he climbs down to lean on it again
 *   upgrade  a roomy trunk, and he cheers beside it
 *
 * Under the stage: what's used of the limit (rolling), a bar of
 * what it's used by, and the two actions.
 * ───────────────────────────────────────────────────────── */

export interface StorageKind {
  id: string;
  label: string;
  bytes: number;
  /** Any CSS colour; defaults to the theme's --chart-1…5. */
  color?: string;
}

export interface StorageProps {
  /** Bytes used. */
  used: number;
  /** Bytes allowed on the plan. */
  limit: number;
  /** What the space is used by, for the bar and its legend. */
  kinds?: StorageKind[];
  /** Free some space (empty the trash, old versions…); update `used` afterwards. */
  onCleanUp?: () => Promise<unknown>;
  cleanUpLabel?: string;
  /** Move to a bigger plan; update `limit` afterwards. */
  onUpgrade?: () => Promise<unknown>;
  upgradeLabel?: string;
  /** Show the roomy trunk (a plan with plenty of space). */
  roomy?: boolean;
  /** What the raccoon is called in his lines. */
  name?: string;
  className?: string;
}

const mix = (color: string, amount: number, into = "transparent") =>
  `color-mix(in oklab, ${color} ${amount}%, ${into})`;
const PF = "var(--primary-foreground)";
const CARD: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, var(--card), ${mix("var(--card)", 95, "var(--foreground)")})`,
  boxShadow: `0 0 0 1px var(--border), inset 0 1px 0 ${mix("var(--background)", 85)}`,
};
/* The one lit surface: a baggage carousel's slats under everything. */
const STAGE: React.CSSProperties = {
  backgroundColor: "var(--primary)",
  backgroundImage: [
    `radial-gradient(55% 80% at 55% 100%, ${mix(PF, 22)} 0%, transparent 70%)`,
    `linear-gradient(175deg, transparent 40%, ${mix("black", 20)} 100%)`,
    `repeating-linear-gradient(90deg, ${mix(PF, 14)} 0 1px, transparent 1px 22px)`,
  ].join(", "),
  backgroundSize: "auto, auto, 100% 14px",
  backgroundRepeat: "no-repeat, no-repeat, no-repeat",
  backgroundPosition: "0 0, 0 0, 0 100%",
  boxShadow: `inset 0 1px 0 ${mix(PF, 36)}, inset 0 0 0 1px ${mix(PF, 12)}`,
};
const LIT: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, ${mix(PF, 16)}, transparent 60%)`,
  boxShadow: `inset 0 1px 0 ${mix(PF, 32)}, inset 0 0 0 1px ${mix("black", 10)}`,
};
const CHART = [
  "var(--chart-1, var(--primary))",
  "var(--chart-2, #10b981)",
  "var(--chart-3, #f59e0b)",
  "var(--chart-4, #8b5cf6)",
  "var(--chart-5, #ef4444)",
];

/* the scene, drawn at 364 × 168 and scaled to the stage */
const W = 364;
const H = 168;
/** One animation frame on the stage: he and his luggage stand in it. */
const FRAME_H = 152;
const FRAME_W = (F.w / F.h) * FRAME_H;

type Mode = "lean" | "full" | "roomy";

/** Pack, animated: each mode is a loop of frames, and the changes between them are clips. */
function PackSprite({ mode, reduced }: { mode: Mode; reduced: boolean }) {
  const sprite = React.useRef<HTMLDivElement>(null);
  const was = React.useRef<Mode | null>(null);

  React.useEffect(() => {
    preloadStrips(Object.values(ART));
  }, []);

  React.useEffect(() => {
    const el = sprite.current;
    if (!el) return;
    const prev = was.current;
    was.current = mode;
    const loop = (clip: "lean" | "push" | "cheer") =>
      playStrip(el, {
        src: ART[clip],
        frames: F.clips[clip].frames,
        fps: F.clips[clip].fps,
        size: FRAME_W,
        height: FRAME_H,
        reduced,
      });
    const idle = {
      lean: () => loop("lean"),
      full: () => loop("push"),
      roomy: () => loop("cheer"),
    }[mode];
    if (prev === null || prev === mode || reduced) return void idle();
    if (prev === "lean" && mode === "full") {
      // the case bulges and he climbs on top to hold it shut
      playStrip(el, {
        src: ART.fill,
        frames: F.clips.fill.frames,
        fps: F.clips.fill.fps,
        size: FRAME_W,
        height: FRAME_H,
        loop: false,
        onEnd: idle,
      });
      return;
    }
    if (prev === "full" && mode === "lean") {
      // the same, backwards: the clothes go back in and he climbs down
      playStrip(el, {
        src: ART.fill,
        frames: F.clips.fill.frames,
        fps: F.clips.fill.fps,
        size: FRAME_W,
        height: FRAME_H,
        loop: false,
        reverse: true,
        onEnd: idle,
      });
      return;
    }
    // a different case altogether: a quick pop between them
    idle();
    el.parentElement?.animate(
      [
        {
          opacity: 0,
          transform: "translateY(6px) scale(0.94)",
          filter: "blur(3px)",
        },
        { opacity: 1, transform: "none", filter: "blur(0px)" },
      ],
      { duration: 420, easing: "cubic-bezier(0.34,1.36,0.64,1)" },
    );
  }, [mode, reduced]);

  return (
    <div
      className="absolute"
      style={{
        left: W / 2 - FRAME_W / 2 + 26,
        top: H - FRAME_H - 4,
        width: FRAME_W,
        height: FRAME_H,
        transformOrigin: "50% 100%",
      }}
    >
      <div ref={sprite} className="size-full" />
    </div>
  );
}

function bytes(n: number) {
  const units = ["B", "KB", "MB", "GB", "TB"];
  let v = Math.max(0, n);
  let i = 0;
  while (v >= 1000 && i < units.length - 1) {
    v /= 1000;
    i++;
  }
  return { value: v, unit: units[i], digits: v < 10 && i > 0 ? 1 : 0 };
}

function Size({ n }: { n: number }) {
  const b = bytes(n);
  return (
    <span className="whitespace-nowrap tabular-nums">
      <NumberRoll
        value={b.value}
        format={{
          maximumFractionDigits: b.digits,
          minimumFractionDigits: b.digits,
        }}
      />{" "}
      {b.unit}
    </span>
  );
}

export function Storage({
  used,
  limit,
  kinds = [],
  onCleanUp,
  cleanUpLabel = "Clean up",
  onUpgrade,
  upgradeLabel = "Upgrade",
  roomy = false,
  name = "Pack",
  className = "",
}: StorageProps) {
  const reduced = useInteractionReducedMotion();
  const baseId = React.useId();
  const [clean, setClean] = React.useState<ActionStatus>("idle");
  const [upgrade, setUpgrade] = React.useState<ActionStatus>("idle");
  const ratio = limit > 0 ? used / limit : 1;
  const full = !roomy && ratio >= 0.9;

  const mode: Mode = roomy ? "roomy" : full ? "full" : "lean";

  const run = async (
    fn: (() => Promise<unknown>) | undefined,
    set: (s: ActionStatus) => void,
  ) => {
    if (!fn) return;
    set("pending");
    try {
      await fn();
      set("success");
      window.setTimeout(() => set("idle"), 1600);
    } catch {
      set("error");
    }
  };

  const mood = roomy
    ? "Room to spare"
    : full
      ? `${name} can’t get it shut`
      : ratio >= 0.75
        ? "Getting snug in there"
        : clean === "success"
          ? "Phew. Room again"
          : "Plenty of room";
  const total = kinds.reduce((s, k) => s + k.bytes, 0);
  const left = Math.max(0, limit - used);

  return (
    <section
      aria-labelledby={`${baseId}-title`}
      className={`relative w-full max-w-[380px] rounded-[28px] p-2 text-card-foreground ${className}`}
      style={CARD}
    >
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 380px)" }}
      />
      <div className="@container w-full">
        <div
          className="relative overflow-clip rounded-[22px] text-primary-foreground"
          style={STAGE}
        >
          <Scene>
            <PackSprite mode={mode} reduced={reduced} />
          </Scene>
          <p className="absolute left-3.5 top-3 z-10 text-[12.5px] font-medium text-primary-foreground/85">
            <TextMorph>{mood}</TextMorph>
          </p>
        </div>

        <div className="px-3 pb-1 pt-3">
          <div className="flex items-baseline justify-between gap-3">
            <h2
              id={`${baseId}-title`}
              className="text-[15px] font-medium tracking-[-0.01em]"
            >
              Storage
            </h2>
            <p
              className={`text-[12.5px] ${full ? "text-amber-700 dark:text-amber-400" : "text-muted-foreground"}`}
            >
              <span className="font-medium text-foreground">
                <Size n={used} />
              </span>{" "}
              of <Size n={limit} />
            </p>
          </div>

          {/* what it's used by: one bar, one segment per kind, and the space left */}
          <div
            className="mt-2.5 flex h-2.5 w-full gap-[2px] overflow-clip rounded-full"
            role="meter"
            aria-label="Storage used"
            aria-valuemin={0}
            aria-valuemax={limit}
            aria-valuenow={used}
            aria-valuetext={`${bytes(used).value.toFixed(bytes(used).digits)} ${bytes(used).unit} of ${bytes(limit).value.toFixed(bytes(limit).digits)} ${bytes(limit).unit} used`}
            style={{ background: mix("var(--foreground)", 7) }}
          >
            {(kinds.length
              ? kinds
              : [{ id: "used", label: "Used", bytes: used }]
            ).map((k, i) => (
              <span
                key={k.id}
                className="h-full shrink-0 first:rounded-l-full"
                style={{
                  width: `${(Math.min(k.bytes, limit) / Math.max(1, limit)) * 100 * (kinds.length && total > used ? used / total : 1)}%`,
                  background: k.color ?? CHART[i % CHART.length],
                  transition: reduced ? "none" : `width 700ms ${EASE_OUT}`,
                }}
              />
            ))}
          </div>
          {kinds.length > 0 && (
            <ul className="mt-2 flex flex-wrap gap-x-3 gap-y-1 text-[12px] text-muted-foreground">
              {kinds.map((k, i) => (
                <li key={k.id} className="flex items-center gap-1.5">
                  <span
                    className="size-2 rounded-full"
                    style={{ background: k.color ?? CHART[i % CHART.length] }}
                  />
                  {k.label}
                  <span className="text-foreground">
                    <Size n={k.bytes} />
                  </span>
                </li>
              ))}
              <li className="flex items-center gap-1.5">
                <span
                  className="size-2 rounded-full"
                  style={{ background: mix("var(--foreground)", 12) }}
                />
                Free
                <span className="text-foreground">
                  <Size n={left} />
                </span>
              </li>
            </ul>
          )}
        </div>

        {(onCleanUp || onUpgrade) && (
          <div className="flex gap-2 px-2 pb-1 pt-3">
            {onCleanUp && (
              <StatusButton
                variant="outline"
                status={clean}
                labels={{
                  idle: cleanUpLabel,
                  pending: "Cleaning up",
                  success: "Cleaned up",
                  error: "Try again",
                }}
                onClick={() => run(onCleanUp, setClean)}
                className="h-10 flex-1 text-[13.5px]"
              />
            )}
            {onUpgrade && !roomy && (
              <StatusButton
                status={upgrade}
                labels={{
                  idle: upgradeLabel,
                  pending: "Upgrading",
                  success: "Upgraded",
                  error: "Try again",
                }}
                onClick={() => run(onUpgrade, setUpgrade)}
                className="h-10 flex-1 text-[13.5px]"
                style={upgrade === "error" ? undefined : LIT}
              />
            )}
          </div>
        )}
      </div>
    </section>
  );
}

/** The stage's scene, drawn at 364 × 168 and scaled to fit. */
function Scene({ children }: { children: React.ReactNode }) {
  const host = React.useRef<HTMLDivElement>(null);
  const scene = React.useRef<HTMLDivElement>(null);
  React.useLayoutEffect(() => {
    const h = host.current;
    const s = scene.current;
    if (!h || !s) return;
    const fit = () =>
      s.style.setProperty("transform", `scale(${h.clientWidth / W})`);
    fit();
    const ro = new ResizeObserver(fit);
    ro.observe(h);
    return () => ro.disconnect();
  }, []);
  return (
    <div
      ref={host}
      aria-hidden="true"
      className="relative w-full"
      style={{ aspectRatio: `${W} / ${H}` }}
    >
      <div
        ref={scene}
        className="absolute left-0 top-0 origin-top-left"
        style={{ width: W, height: H }}
      >
        {children}
      </div>
    </div>
  );
}

export default Storage;

"use client";

import * as React from "react";
import {
  AlertCircle,
  Copy,
  RotateCcw,
  ThumbsDown,
  ThumbsUp,
} from "lucide-react";
import { NumberRoll } from "./number-roll";

/* ─────────────────────────────────────────────────────────
 * STREAMING ANSWER: an AI answer as it arrives
 *
 *   StreamingText   the text so far, with inline citation chips;
 *                   only newly arrived words fade in
 *   AnswerActions   copy (blurs into a check that draws itself),
 *                   regenerate, feedback (the thumb fills with a
 *                   small thrown pop) and a sources stack whose
 *                   count rolls
 *   FollowUps       suggested next questions
 *
 * StreamingText renders whatever you pass it: append to `content`
 * as tokens arrive. Blank lines start new paragraphs, and finished
 * paragraphs don't re-render while the last one grows. For Markdown,
 * pass your renderer as children instead of `content`.
 * ───────────────────────────────────────────────────────── */

export type AnswerCitation = { type: "citation"; label: string; href?: string };
export type AnswerSegment = string | AnswerCitation;
export type AnswerStatus = "streaming" | "done" | "stopped" | "error";
export type AnswerFeedback = "up" | "down" | null;

export interface AnswerSource {
  name: string;
  href?: string;
  /** A favicon or logo, e.g. <img src="…/favicon.ico" alt="" />. */
  icon?: React.ReactNode;
  /** Tailwind background class for the dot when there's no icon. */
  color?: string;
}

const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const DOTS = [
  "bg-blue-500",
  "bg-emerald-500",
  "bg-orange-500",
  "bg-violet-500",
];
const MORPH = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Icons trade places through a blur: the old one shrinks away as the new one grows in. */
const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 260ms ${MORPH}, transform 380ms ${MORPH}, filter 260ms ${MORPH}`,
});

/* ── StreamingText ───────────────────────────────────────── */

export interface StreamingTextProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "content"
> {
  /** The answer so far. Append as tokens arrive. */
  content?: AnswerSegment[];
  status?: AnswerStatus;
  /** Shows a retry button when status is "error". */
  onRetry?: () => void;
  /** Your own renderer (e.g. Markdown) instead of `content`. */
  children?: React.ReactNode;
}

type Token =
  | { kind: "word" | "space"; text: string }
  | { kind: "cite"; citation: AnswerCitation };

function toParagraphs(content: AnswerSegment[]): Token[][] {
  const paragraphs: Token[][] = [[]];
  for (const segment of content) {
    if (typeof segment !== "string") {
      paragraphs[paragraphs.length - 1].push({
        kind: "cite",
        citation: segment,
      });
      continue;
    }
    for (const part of segment.split(/(\n{2,})/)) {
      if (/^\n{2,}$/.test(part)) {
        paragraphs.push([]);
        continue;
      }
      for (const text of part.split(/(\s+)/)) {
        if (text)
          paragraphs[paragraphs.length - 1].push({
            kind: /^\s+$/.test(text) ? "space" : "word",
            text,
          });
      }
    }
  }
  return paragraphs.filter(
    (p, i) => p.length > 0 || i === paragraphs.length - 1,
  );
}

function CitationChip({ citation }: { citation: AnswerCitation }) {
  const className = `mx-0.5 inline-flex -translate-y-px items-center gap-1 rounded-[5px] border border-border bg-muted px-1.5 py-px align-middle font-mono text-[11px] text-foreground animate-[ui-fade-up_240ms_cubic-bezier(0.23,1,0.32,1)_both] motion-reduce:animate-none ${FOCUS}`;
  const inner = (
    <>
      <span
        aria-hidden="true"
        className="size-1.5 shrink-0 rounded-full bg-emerald-500"
      />
      {citation.label}
    </>
  );
  return citation.href ? (
    <a
      href={citation.href}
      target="_blank"
      rel="noreferrer"
      className={`${className} transition-colors hover:bg-accent`}
    >
      {inner}
    </a>
  ) : (
    <span className={className}>{inner}</span>
  );
}

const Caret = () => (
  <span
    aria-hidden="true"
    className="ml-0.5 inline-block h-[1.05em] w-[2px] translate-y-[0.18em] bg-foreground animate-[ui-blink_1s_steps(2,start)_infinite] motion-reduce:animate-none"
  />
);

// Words keep a stable key by position, so only words that just arrived mount and fade in.
const Paragraph = React.memo(
  function Paragraph({
    tokens,
    caret,
  }: {
    tokens: Token[];
    signature: string;
    caret: boolean;
  }) {
    return (
      <p>
        {tokens.map((token, i) =>
          token.kind === "cite" ? (
            <CitationChip key={i} citation={token.citation} />
          ) : token.kind === "space" ? (
            token.text
          ) : (
            <span
              key={i}
              className="animate-[ui-fade-in_420ms_ease-out_both] motion-reduce:animate-none"
            >
              {token.text}
            </span>
          ),
        )}
        {caret && <Caret />}
      </p>
    );
  },
  (a, b) => a.signature === b.signature && a.caret === b.caret,
);

export function StreamingText({
  content = [],
  status = "done",
  onRetry,
  children,
  className = "",
  ...props
}: StreamingTextProps) {
  const streaming = status === "streaming";
  const paragraphs = children === undefined ? toParagraphs(content) : [];

  return (
    <div
      aria-busy={streaming}
      className={`flex flex-col gap-3 text-[13.5px] leading-relaxed text-foreground ${className}`}
      {...props}
    >
      {children ??
        paragraphs.map((tokens, i) => (
          <Paragraph
            key={i}
            tokens={tokens}
            signature={tokens
              .map((t) =>
                t.kind === "cite" ? `\u0000${t.citation.label}` : t.text,
              )
              .join("")}
            caret={streaming && i === paragraphs.length - 1}
          />
        ))}

      {status === "stopped" && (
        <p className="text-xs text-muted-foreground animate-[ui-fade-in_300ms_ease-out_both]">
          Stopped
        </p>
      )}

      {status === "error" && (
        <p className="flex items-center gap-1.5 text-xs text-muted-foreground animate-[ui-fade-in_300ms_ease-out_both]">
          <AlertCircle
            aria-hidden="true"
            className="size-3.5 shrink-0 text-red-500"
          />
          The answer was interrupted.
          {onRetry && (
            <button
              type="button"
              onClick={onRetry}
              className={`cursor-pointer rounded px-1 font-medium text-foreground underline decoration-border underline-offset-2 hover:decoration-foreground ${FOCUS}`}
            >
              Retry
            </button>
          )}
        </p>
      )}
    </div>
  );
}

/* ── AnswerActions ───────────────────────────────────────── */

export interface AnswerActionsProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Text the copy button puts on the clipboard. Hides the button when omitted. */
  copyText?: string;
  onRegenerate?: () => void;
  /** Controlled feedback, e.g. restored from your database. */
  feedback?: AnswerFeedback;
  defaultFeedback?: AnswerFeedback;
  onFeedback?: (value: AnswerFeedback) => void;
  sources?: AnswerSource[];
  onSourcesClick?: () => void;
  /** Disables the buttons, e.g. while the answer is still streaming. */
  disabled?: boolean;
}

function IconButton({
  label,
  pressed,
  disabled,
  onClick,
  children,
}: {
  label: string;
  pressed?: boolean;
  disabled?: boolean;
  onClick: () => void;
  children: React.ReactNode;
}) {
  return (
    <button
      type="button"
      aria-label={label}
      aria-pressed={pressed}
      disabled={disabled}
      onClick={onClick}
      className={`cursor-pointer disabled:cursor-default relative flex size-7 items-center justify-center rounded-md transition-colors duration-150 hover:bg-accent hover:text-foreground disabled:pointer-events-none disabled:opacity-40 ${
        pressed ? "bg-accent text-foreground" : "text-muted-foreground"
      } ${FOCUS}`}
    >
      {children}
    </button>
  );
}

/** A thumb that fills in with a small thrown pop when chosen, and empties when let go. */
function Thumb({
  down,
  filled,
  reduced,
}: {
  down?: boolean;
  filled: boolean;
  reduced: boolean;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  const first = React.useRef(true);
  React.useEffect(() => {
    if (first.current) {
      first.current = false;
      return;
    }
    if (!filled || reduced) return;
    ref.current?.animate(
      [{ transform: "scale(0.8) rotate(-8deg)" }, { transform: "none" }],
      { duration: 420, easing: THROW },
    );
  }, [filled, reduced]);
  const Icon = down ? ThumbsDown : ThumbsUp;
  return (
    <span ref={ref} className="flex">
      <Icon
        className="size-3.5"
        style={{
          fill: filled ? "currentColor" : "transparent",
          transition: reduced ? "none" : `fill 220ms ${MORPH}`,
        }}
      />
    </span>
  );
}

export function AnswerActions({
  copyText,
  onRegenerate,
  feedback,
  defaultFeedback = null,
  onFeedback,
  sources,
  onSourcesClick,
  disabled,
  className = "",
  ...props
}: AnswerActionsProps) {
  const reduced = useReducedMotion();
  const [copied, setCopied] = React.useState(false);
  const [ownFeedback, setOwnFeedback] =
    React.useState<AnswerFeedback>(defaultFeedback);
  const current = feedback !== undefined ? feedback : ownFeedback;

  React.useEffect(() => {
    if (!copied) return;
    const timer = window.setTimeout(() => setCopied(false), 1600);
    return () => window.clearTimeout(timer);
  }, [copied]);

  const copy = async () => {
    if (!copyText) return;
    try {
      await navigator.clipboard.writeText(copyText);
      setCopied(true);
    } catch {
      // Clipboard can be blocked by the browser; nothing to undo.
    }
  };

  const rate = (value: "up" | "down") => {
    const next = current === value ? null : value;
    if (feedback === undefined) setOwnFeedback(next);
    onFeedback?.(next);
  };

  const stack = sources && sources.length > 0 && (
    <>
      <span className="flex items-center -space-x-1.5" aria-hidden="true">
        {sources.slice(0, 3).map((s, i) =>
          s.icon ? (
            <span
              key={s.name}
              className="flex size-3.5 items-center justify-center overflow-hidden rounded-full bg-background ring-2 ring-background"
            >
              {s.icon}
            </span>
          ) : (
            <span
              key={s.name}
              className={`size-3.5 rounded-full ring-2 ring-background ${s.color ?? DOTS[i % DOTS.length]}`}
            />
          ),
        )}
      </span>
      <span className="inline-flex items-baseline gap-[0.3em] tabular-nums">
        <NumberRoll value={sources.length} duration={600} />
        {sources.length === 1 ? "source" : "sources"}
      </span>
    </>
  );

  return (
    <div
      className={`flex items-center justify-between gap-4 ${className}`}
      {...props}
    >
      <div className="flex items-center gap-1">
        {copyText !== undefined && (
          <IconButton label="Copy answer" disabled={disabled} onClick={copy}>
            <span
              aria-hidden="true"
              className="absolute inset-0 flex items-center justify-center"
              style={swap(!copied, reduced)}
            >
              <Copy className="size-3.5" />
            </span>
            <span
              aria-hidden="true"
              className="absolute inset-0 flex items-center justify-center text-emerald-600 dark:text-emerald-400"
              style={swap(copied, reduced)}
            >
              <svg viewBox="0 0 16 16" fill="none" className="size-3.5">
                <path
                  d="M3.5 8.5 6.5 11.5 12.5 4.5"
                  stroke="currentColor"
                  strokeWidth="1.8"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  pathLength={1}
                  strokeDasharray={1}
                  style={{
                    strokeDashoffset: copied ? 0 : 1,
                    transition:
                      copied && !reduced
                        ? `stroke-dashoffset 380ms ${MORPH} 100ms`
                        : "none",
                  }}
                />
              </svg>
            </span>
          </IconButton>
        )}
        {onRegenerate && (
          <IconButton
            label="Regenerate"
            disabled={disabled}
            onClick={onRegenerate}
          >
            <RotateCcw className="size-3.5" />
          </IconButton>
        )}
        <IconButton
          label="Helpful"
          pressed={current === "up"}
          disabled={disabled}
          onClick={() => rate("up")}
        >
          <Thumb filled={current === "up"} reduced={reduced} />
        </IconButton>
        <IconButton
          label="Not helpful"
          pressed={current === "down"}
          disabled={disabled}
          onClick={() => rate("down")}
        >
          <Thumb down filled={current === "down"} reduced={reduced} />
        </IconButton>
      </div>
      {/* Outside the buttons, so their names stay their labels. */}
      <span role="status" className="sr-only">
        {copied ? "Copied" : ""}
      </span>

      {stack &&
        (onSourcesClick ? (
          <button
            type="button"
            onClick={onSourcesClick}
            className={`cursor-pointer flex items-center gap-1.5 rounded-md px-1.5 py-1 text-[11.5px] font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
          >
            {stack}
          </button>
        ) : (
          <span className="flex items-center gap-1.5 text-[11.5px] font-medium text-muted-foreground">
            {stack}
          </span>
        ))}
    </div>
  );
}

