"use client";

import * as React from "react";
import { ArrowDownToLine, ChevronLeft } from "lucide-react";
import { Faces, FACES_MORPH } from "./faces";
import { NumberRoll } from "./number-roll";
import { SegmentedControl } from "./segmented-control";
import { StatusButton, type ActionStatus } from "./status-button";
import { Textarea } from "./textarea";
import { TextMorph } from "./text-morph";
import {
  EASE_THROW,
  INTERACTION_FOCUS,
  INTERACTION_PRESS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * SUBSCRIPTION: a plan you can see through to its next bill
 *
 *   plan      the lit card holds the plan, its price and a ring
 *             that fills through the billing period, the days left
 *             in its middle; under it usage, the card on file and
 *             invoices, all flat
 *   pause     Cancel plan turns the lower half into "Pause
 *             instead?": pick one, two or three months and the date
 *             billing resumes rolls to match
 *   cancel    only past the offer, a reason and a note, then
 *             Cancel subscription; the card says when it ends
 *   resume    a paused or ending plan offers Resume in place
 *
 * Billing is yours: pass the plan, status, period and usage from
 * your provider, and do the work in onPause, onCancel, onResume and
 * onUpdateCard (open your provider's portal there). Throw an Error
 * and its message shows where it happened.
 * ───────────────────────────────────────────────────────── */

export type SubscriptionStatus =
  "active" | "trialing" | "past_due" | "paused" | "canceling";

export interface SubscriptionPlan {
  name: string;
  /** Per interval, major units. */
  price: number;
  interval: "month" | "year";
  seats?: number;
}

export interface SubscriptionUsage {
  id: string;
  label: string;
  used: number;
  limit: number;
  /** e.g. "runs", "GB". */
  unit?: string;
}

export interface SubscriptionCard {
  /** e.g. "Visa". */
  brand: string;
  last4: string;
  expMonth: number;
  expYear: number;
}

export interface SubscriptionInvoice {
  id: string;
  date: Date | string | number;
  amount: number;
  status: "paid" | "open" | "failed";
  /** A PDF or hosted invoice page. */
  url?: string;
}

export interface SubscriptionProps {
  plan: SubscriptionPlan;
  status: SubscriptionStatus;
  periodStart: Date | string | number;
  /** When it renews, or ends while canceling. */
  periodEnd: Date | string | number;
  /** When billing resumes, while paused. */
  resumesAt?: Date | string | number;
  usage?: SubscriptionUsage[];
  card?: SubscriptionCard;
  invoices?: SubscriptionInvoice[];
  /** Open your provider's portal (or a form) to change the card. */
  onUpdateCard?: () => Promise<unknown>;
  /** Go to your plans, e.g. the Pricing plans block. */
  onChangePlan?: () => void;
  /** Pause billing for this many months; shows the offer before cancelling. */
  onPause?: (months: number) => Promise<unknown>;
  onCancel?: (reason: string, comment: string) => Promise<unknown>;
  /** Undo a pause or a cancel that hasn't ended yet. */
  onResume?: () => Promise<unknown>;
  pauseMonths?: number[];
  reasons?: string[];
  currency?: string;
  locale?: string;
  className?: string;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const DAY = 86_400_000;
const PAUSE = [1, 2, 3];
const REASONS = [
  "Too expensive",
  "Not using it enough",
  "Missing a feature",
  "Switching to another tool",
  "Something else",
];
const NONE: never[] = [];
const subscribeNothing = () => () => {};
/** False on the server and while hydrating, so dates are written once, in the visitor's own zone. */
const useHydrated = () =>
  React.useSyncExternalStore(
    subscribeNothing,
    () => true,
    () => false,
  );

const mix = (color: string, amount: number, into = "transparent") =>
  `color-mix(in oklab, ${color} ${amount}%, ${into})`;
const LIT: React.CSSProperties = {
  backgroundColor: "var(--primary)",
  backgroundImage: `radial-gradient(120% 90% at 100% 0%, ${mix("var(--primary-foreground)", 22)} 0%, transparent 55%), linear-gradient(175deg, transparent 40%, ${mix("black", 24)} 100%)`,
  boxShadow: `inset 0 1px 0 ${mix("var(--primary-foreground)", 36)}, inset 0 0 0 1px ${mix("var(--primary-foreground)", 12)}`,
};
const CARD: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, var(--card), ${mix("var(--card)", 95, "var(--foreground)")})`,
  boxShadow: `0 0 0 1px var(--border), inset 0 1px 0 ${mix("var(--background)", 85)}`,
};
const ACTION: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, ${mix("var(--primary-foreground)", 16)}, transparent 60%)`,
  boxShadow: `inset 0 1px 0 ${mix("var(--primary-foreground)", 32)}, inset 0 0 0 1px ${mix("black", 10)}`,
};
const errorOf = (e: unknown, fallback: string) =>
  e instanceof Error && e.message ? e.message : fallback;
const addMonths = (t: number, m: number) => {
  const d = new Date(t);
  d.setMonth(d.getMonth() + m);
  return d.getTime();
};

/** The billing period as a ring: how far through it you are, the days left in the middle. */
function PeriodRing({
  share,
  days,
  dim,
  reduced,
}: {
  share: number;
  days: number | null;
  dim: boolean;
  reduced: boolean;
}) {
  const r = 22;
  const c = 2 * Math.PI * r;
  return (
    <span
      className="relative flex size-[56px] shrink-0 items-center justify-center"
      style={{ opacity: dim ? 0.55 : 1, transition: "opacity 400ms" }}
    >
      <svg
        aria-hidden="true"
        viewBox="0 0 56 56"
        className="absolute inset-0 size-full -rotate-90"
      >
        <circle
          cx="28"
          cy="28"
          r={r}
          fill="none"
          stroke={mix("var(--primary-foreground)", 22)}
          strokeWidth="3"
        />
        <circle
          cx="28"
          cy="28"
          r={r}
          fill="none"
          stroke="var(--primary-foreground)"
          strokeWidth="3"
          strokeLinecap="round"
          strokeDasharray={c}
          style={{
            strokeDashoffset: c * (1 - share),
            transition: reduced ? "none" : `stroke-dashoffset 900ms ${EASE}`,
          }}
        />
        {/* Fine ticks round the ring, one per week of the period. */}
        {Array.from({ length: 12 }, (_, i) => (
          <line
            key={i}
            x1="28"
            y1="1.5"
            x2="28"
            y2="3.5"
            stroke={mix("var(--primary-foreground)", 35)}
            strokeWidth="0.8"
            transform={`rotate(${i * 30} 28 28)`}
          />
        ))}
      </svg>
      <span className="relative text-center leading-none">
        <span className="block text-[16px] font-medium tabular-nums">
          {days === null ? "–" : <NumberRoll value={days} duration={800} />}
        </span>
        <span className="mt-0.5 block text-[9.5px] uppercase tracking-[0.08em] text-primary-foreground/70">
          {days === 1 ? "day" : "days"}
        </span>
      </span>
    </span>
  );
}

export function Subscription({
  plan,
  status,
  periodStart,
  periodEnd,
  resumesAt,
  usage = NONE,
  card,
  invoices = NONE,
  onUpdateCard,
  onChangePlan,
  onPause,
  onCancel,
  onResume,
  pauseMonths = PAUSE,
  reasons = REASONS,
  currency = "USD",
  locale,
  className = "",
}: SubscriptionProps) {
  const reduced = useInteractionReducedMotion();
  const hydrated = useHydrated();
  const baseId = React.useId();
  const loc = locale ?? (hydrated ? undefined : "en-US");
  const [now, setNow] = React.useState<number | null>(null);
  const [ready, setReady] = React.useState(false);
  const [step, setStep] = React.useState<0 | 1 | 2>(0);
  const [months, setMonths] = React.useState(
    pauseMonths[Math.min(1, pauseMonths.length - 1)] ?? 1,
  );
  const [reason, setReason] = React.useState<string | null>(null);
  const [comment, setComment] = React.useState("");
  const [act, setAct] = React.useState<{
    kind: "pause" | "cancel" | "resume" | "card" | null;
    status: ActionStatus;
    error?: string;
  }>({ kind: null, status: "idle" });
  const [said, setSaid] = React.useState("");
  const faceRefs = React.useRef<(HTMLElement | null)[]>([]);

  React.useEffect(() => {
    const frame = requestAnimationFrame(() => {
      setNow(Date.now());
      setReady(true);
    });
    return () => cancelAnimationFrame(frame);
  }, []);

  const start = new Date(periodStart).getTime();
  const end = new Date(periodEnd).getTime();
  const share =
    now === null ? 0 : Math.min(1, Math.max(0, (now - start) / (end - start)));
  // While paused the ring counts down to when billing comes back, not to the old renewal.
  const until =
    status === "paused" && resumesAt !== undefined
      ? new Date(resumesAt).getTime()
      : end;
  const daysLeft =
    now === null ? null : Math.max(0, Math.ceil((until - now) / DAY));
  const date = (t: Date | string | number) =>
    hydrated
      ? new Intl.DateTimeFormat(loc, {
          month: "short",
          day: "numeric",
          year:
            new Date(t).getFullYear() !== new Date(now ?? end).getFullYear()
              ? "numeric"
              : undefined,
        }).format(new Date(t))
      : "";
  const money = (n: number) =>
    new Intl.NumberFormat(loc, {
      style: "currency",
      currency,
      minimumFractionDigits: n % 1 ? 2 : 0,
      maximumFractionDigits: 2,
    }).format(n);
  const resumeAt = addMonths(end, months);
  const busy = act.status === "pending" || act.status === "success";

  const state =
    status === "paused"
      ? `Paused until ${date(resumesAt ?? end)}`
      : status === "canceling"
        ? `Ends ${date(end)}`
        : status === "trialing"
          ? `Trial ends ${date(end)}`
          : status === "past_due"
            ? "Payment failed"
            : `Renews ${date(end)}`;

  const go = (s: 0 | 1 | 2) => {
    if (busy) return;
    setStep(s);
    setAct({ kind: null, status: "idle" });
    // Focus follows once the surface is mostly turned.
    window.setTimeout(
      () => faceRefs.current[s]?.focus({ preventScroll: true }),
      reduced ? 0 : FACES_MORPH / 2,
    );
  };

  const run = async (
    kind: "pause" | "cancel" | "resume" | "card",
    fn: (() => Promise<unknown>) | undefined,
    done: string,
  ) => {
    if (!fn || busy) return;
    setAct({ kind, status: "pending" });
    try {
      await fn();
      setAct({ kind, status: "success" });
      setSaid(done);
      window.setTimeout(
        () => {
          if (kind !== "card") setStep(0);
          setAct({ kind: null, status: "idle" });
        },
        kind === "card" ? 1200 : reduced ? 600 : 900,
      );
    } catch (e) {
      setAct({
        kind,
        status: "error",
        error: errorOf(e, "That didn’t go through. Try again."),
      });
    }
  };

  const st = (kind: "pause" | "cancel" | "resume" | "card") =>
    act.kind === kind ? act.status : "idle";
  const ghost = `inline-flex h-10 cursor-pointer items-center justify-center rounded-full px-4 text-[13.5px] font-medium ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`;
  const ending = status === "paused" || status === "canceling";

  return (
    <section
      aria-labelledby={`${baseId}-plan`}
      className={`w-full max-w-[440px] rounded-[28px] p-2 text-card-foreground ${className}`}
      style={CARD}
    >
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 440px)" }}
      />
      <div className="@container w-full">
        {/* The one lit surface: the plan, and the ring of its billing period. */}
        <div
          className="rounded-[22px] p-4 text-primary-foreground"
          style={{
            ...LIT,
            filter: ending ? "saturate(0.55)" : "none",
            transition: reduced ? "none" : `filter 500ms ${EASE}`,
          }}
        >
          <div className="flex items-start justify-between gap-3">
            <div className="min-w-0">
              <p className="text-[12.5px] text-primary-foreground/70">
                Your plan
              </p>
              <h2
                id={`${baseId}-plan`}
                className="mt-0.5 text-[20px] font-medium leading-tight tracking-[-0.02em]"
              >
                {plan.name}
                {plan.seats ? (
                  <span className="text-primary-foreground/70">
                    {" "}
                    · {plan.seats} seats
                  </span>
                ) : null}
              </h2>
              <p className="mt-2 flex items-baseline gap-1">
                <span className="text-[30px] font-medium leading-none tracking-[-0.04em] tabular-nums">
                  <NumberRoll
                    value={plan.price}
                    locales={locale}
                    format={{
                      style: "currency",
                      currency,
                      minimumFractionDigits: plan.price % 1 ? 2 : 0,
                      maximumFractionDigits: 2,
                    }}
                    duration={800}
                  />
                </span>
                <span className="text-[13px] text-primary-foreground/70">
                  /{plan.interval === "year" ? "yr" : "mo"}
                </span>
              </p>
            </div>
            <PeriodRing
              share={ending ? 1 : share}
              days={daysLeft}
              dim={ending}
              reduced={reduced}
            />
          </div>
          <p
            className={`mt-3 inline-flex h-7 items-center gap-1.5 rounded-full px-2.5 text-[12.5px] font-medium ${status === "past_due" ? "text-amber-200" : ""}`}
            style={{ background: mix("var(--primary-foreground)", 14) }}
            role="status"
          >
            <span
              aria-hidden="true"
              className={`size-1.5 rounded-full ${status === "past_due" ? "bg-amber-400" : ending ? "bg-primary-foreground/55" : "bg-emerald-300"}`}
            />
            <TextMorph>{hydrated ? state : " "}</TextMorph>
          </p>
        </div>

        {/* Flat: the details, or the way out, which always offers a pause first. */}
        <Faces active={step} reduced={reduced} ready={ready}>
          <div
            ref={(el) => {
              faceRefs.current[0] = el;
            }}
            tabIndex={-1}
            className="px-2 pb-1 pt-1 outline-none"
          >
            {usage.length > 0 && (
              <div className="space-y-2.5 px-1 pt-3">
                {usage.map((u) => {
                  const pct = Math.min(1, u.used / u.limit);
                  const hot = pct >= 0.9;
                  return (
                    <div key={u.id}>
                      <div className="flex items-baseline justify-between gap-3 text-[13px]">
                        <span className="text-foreground">{u.label}</span>
                        <span className="tabular-nums text-muted-foreground">
                          <NumberRoll
                            value={u.used}
                            locales={locale}
                            className={
                              hot
                                ? "font-medium text-amber-600 dark:text-amber-400"
                                : "text-foreground"
                            }
                          />{" "}
                          / {new Intl.NumberFormat(loc).format(u.limit)}
                          {u.unit ? ` ${u.unit}` : ""}
                        </span>
                      </div>
                      <div
                        className="mt-1.5 h-1 overflow-hidden rounded-full bg-muted"
                        role="meter"
                        aria-label={u.label}
                        aria-valuemin={0}
                        aria-valuemax={u.limit}
                        aria-valuenow={u.used}
                      >
                        <span
                          className={`block h-full origin-left rounded-full ${hot ? "bg-amber-500" : "bg-primary"}`}
                          style={{
                            transform: `scaleX(${ready ? pct : 0})`,
                            transition: reduced
                              ? "none"
                              : `transform 900ms ${EASE}`,
                          }}
                        />
                      </div>
                    </div>
                  );
                })}
              </div>
            )}

            {card && (
              <div className="mt-3 flex h-12 items-center gap-3 border-t border-border px-1 pt-3">
                <span
                  aria-hidden="true"
                  className="flex h-7 w-10 shrink-0 items-center justify-center rounded-[6px] border border-border bg-background font-mono text-[9px] font-medium uppercase tracking-[0.06em] text-foreground"
                >
                  {card.brand.slice(0, 4)}
                </span>
                <span className="min-w-0 flex-1 text-[13px]">
                  <span className="block truncate text-foreground">
                    {card.brand} •••• {card.last4}
                  </span>
                  <span className="block text-[12px] text-muted-foreground">
                    Expires {String(card.expMonth).padStart(2, "0")}/
                    {String(card.expYear).slice(-2)}
                  </span>
                </span>
                {onUpdateCard && (
                  <StatusButton
                    variant="ghost"
                    size="sm"
                    status={st("card")}
                    labels={{
                      idle: "Update",
                      pending: "Opening",
                      success: "Opened",
                      error: "Try again",
                    }}
                    onClick={() =>
                      void run("card", onUpdateCard, "Opened the payment page.")
                    }
                    className="-mr-1 shrink-0 text-foreground"
                  />
                )}
              </div>
            )}
            {act.kind === "card" && act.error && (
              <p
                role="alert"
                className="px-1 pt-1 text-[12px] text-red-600 dark:text-red-400"
              >
                {act.error}
              </p>
            )}

            {invoices.length > 0 && (
              <div className="mt-3 border-t border-border px-1 pt-2.5">
                <p className="text-[12px] text-muted-foreground">Invoices</p>
                <ul className="mt-1">
                  {invoices.slice(0, 3).map((inv) => (
                    <li
                      key={inv.id}
                      className="flex h-9 items-center gap-3 text-[13px]"
                    >
                      <span className="min-w-0 flex-1 text-foreground">
                        {date(inv.date)}
                      </span>
                      <span
                        className={`rounded-full px-2 py-0.5 text-[11px] font-medium ${inv.status === "paid" ? "bg-emerald-500/10 text-emerald-700 dark:text-emerald-400" : inv.status === "open" ? "bg-amber-500/10 text-amber-700 dark:text-amber-400" : "bg-red-500/10 text-red-600 dark:text-red-400"}`}
                      >
                        {inv.status === "paid"
                          ? "Paid"
                          : inv.status === "open"
                            ? "Open"
                            : "Failed"}
                      </span>
                      <span className="w-[72px] text-right tabular-nums text-foreground">
                        {money(inv.amount)}
                      </span>
                      {inv.url ? (
                        <a
                          href={inv.url}
                          target="_blank"
                          rel="noreferrer"
                          aria-label={`Download the invoice of ${date(inv.date)}`}
                          className={`-mr-1 flex size-7 items-center justify-center rounded-full text-muted-foreground hover:bg-accent hover:text-foreground ${INTERACTION_FOCUS}`}
                        >
                          <ArrowDownToLine
                            aria-hidden="true"
                            className="size-3.5"
                          />
                        </a>
                      ) : (
                        <span className="w-6" />
                      )}
                    </li>
                  ))}
                </ul>
              </div>
            )}

            <div className="mt-2.5 flex gap-2 border-t border-border pt-3">
              {ending && onResume ? (
                <StatusButton
                  status={st("resume")}
                  labels={{
                    idle: status === "paused" ? "Resume now" : "Keep my plan",
                    pending: "Resuming",
                    success: "Resumed",
                    error: "Try again",
                  }}
                  onClick={() =>
                    void run("resume", onResume, "Your plan is back on.")
                  }
                  className="h-10 flex-1 text-[13.5px]"
                  style={st("resume") === "error" ? undefined : ACTION}
                />
              ) : (
                onChangePlan && (
                  <button
                    type="button"
                    onClick={onChangePlan}
                    className={`${ghost} flex-1 text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent`}
                  >
                    Change plan
                  </button>
                )
              )}
              {!ending && (onPause || onCancel) && (
                <button
                  type="button"
                  onClick={() => go(onPause ? 1 : 2)}
                  className={`${ghost} text-muted-foreground hover:bg-accent hover:text-foreground`}
                >
                  Cancel plan
                </button>
              )}
            </div>
            {act.kind === "resume" && act.error && (
              <p
                role="alert"
                className="px-1 pt-1.5 text-[12px] text-red-600 dark:text-red-400"
              >
                {act.error}
              </p>
            )}
          </div>

          {/* Before you go: a pause, with the date it all comes back. */}
          <div
            ref={(el) => {
              faceRefs.current[1] = el;
            }}
            tabIndex={-1}
            role="group"
            aria-labelledby={`${baseId}-pause`}
            className="px-3 pb-1.5 pt-3.5 outline-none"
          >
            <h3
              id={`${baseId}-pause`}
              className="text-[16px] font-medium tracking-[-0.01em]"
            >
              Pause instead?
            </h3>
            <p className="mt-1 text-[13px] leading-relaxed text-muted-foreground">
              Keep everything as it is and pick up where you left off. You won’t
              be charged while it’s paused.
            </p>
            <SegmentedControl
              label="Pause for"
              block
              className="mt-3"
              value={String(months)}
              onValueChange={(v) => setMonths(Number(v))}
              options={pauseMonths.map((m) => ({
                value: String(m),
                label: m === 1 ? "1 month" : `${m} months`,
              }))}
            />
            <p className="mt-2.5 text-[13px] text-muted-foreground">
              Billing resumes on{" "}
              <TextMorph className="font-medium text-foreground">
                {hydrated ? date(resumeAt) : " "}
              </TextMorph>
            </p>
            <StatusButton
              status={st("pause")}
              labels={{
                idle:
                  months === 1
                    ? "Pause for 1 month"
                    : `Pause for ${months} months`,
                pending: "Pausing",
                success: "Paused",
                error: "Try again",
              }}
              onClick={() =>
                void run(
                  "pause",
                  onPause && (() => onPause(months)),
                  `Paused for ${months} months.`,
                )
              }
              className="mt-3.5 h-11 w-full text-[14.5px]"
              style={st("pause") === "error" ? undefined : ACTION}
            />
            {act.kind === "pause" && act.error && (
              <p
                role="alert"
                className="mt-1.5 text-center text-[12px] text-red-600 dark:text-red-400"
              >
                {act.error}
              </p>
            )}
            <div className="mt-1.5 flex justify-between">
              <button
                type="button"
                onClick={() => go(0)}
                disabled={busy}
                className={`${ghost} -ml-2 h-9 px-3 text-muted-foreground hover:bg-accent hover:text-foreground`}
              >
                Keep my plan
              </button>
              {onCancel && (
                <button
                  type="button"
                  onClick={() => go(2)}
                  disabled={busy}
                  className={`${ghost} -mr-2 h-9 px-3 text-muted-foreground hover:bg-accent hover:text-foreground`}
                >
                  No, cancel it
                </button>
              )}
            </div>
          </div>

          {/* Cancel: a reason, then the end date. */}
          <div
            ref={(el) => {
              faceRefs.current[2] = el;
            }}
            tabIndex={-1}
            role="group"
            aria-labelledby={`${baseId}-cancel`}
            className="px-3 pb-1.5 pt-3 outline-none"
          >
            <div className="-ml-1.5 flex items-center gap-1">
              <button
                type="button"
                aria-label="Back"
                disabled={busy}
                onClick={() => go(onPause ? 1 : 0)}
                className={`flex size-8 cursor-pointer items-center justify-center rounded-full text-muted-foreground hover:bg-accent hover:text-foreground ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`}
              >
                <ChevronLeft aria-hidden="true" className="size-[18px]" />
              </button>
              <h3
                id={`${baseId}-cancel`}
                className="text-[16px] font-medium tracking-[-0.01em]"
              >
                Why are you leaving?
              </h3>
            </div>
            <div
              role="radiogroup"
              aria-labelledby={`${baseId}-cancel`}
              className="mt-2.5 flex flex-wrap gap-1.5"
            >
              {reasons.map((r) => {
                const on = r === reason;
                return (
                  <button
                    key={r}
                    type="button"
                    role="radio"
                    aria-checked={on}
                    disabled={busy}
                    onClick={() => setReason(r)}
                    className={`h-8 cursor-pointer rounded-full px-3 text-[12.5px] ${INTERACTION_PRESS} ${INTERACTION_FOCUS} ${on ? "bg-primary/[0.08] font-medium text-primary shadow-[inset_0_0_0_1.5px_var(--primary)]" : "text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent"}`}
                    style={{
                      transition: reduced
                        ? "none"
                        : `box-shadow 260ms ${EASE_THROW}, background-color 200ms`,
                    }}
                  >
                    {r}
                  </button>
                );
              })}
            </div>
            <Textarea
              aria-label="Anything we could have done better?"
              placeholder="Anything we could have done better? (optional)"
              value={comment}
              onValueChange={setComment}
              disabled={busy}
              minRows={2}
              maxRows={4}
              maxLength={500}
              showCount={false}
              className="mt-2.5"
            />
            <StatusButton
              variant="outline"
              status={st("cancel")}
              labels={{
                idle: "Cancel subscription",
                pending: "Cancelling",
                success: "Cancelled",
                error: "Try again",
              }}
              disabled={!reason && st("cancel") === "idle"}
              onClick={() =>
                void run(
                  "cancel",
                  onCancel && (() => onCancel(reason ?? "", comment.trim())),
                  `Cancelled. ${plan.name} stays on until ${date(end)}.`,
                )
              }
              className="mt-2.5 h-11 w-full text-[14.5px] text-red-600 disabled:opacity-45 dark:text-red-400"
            />
            <p
              role={act.kind === "cancel" && act.error ? "alert" : undefined}
              className={`mt-1.5 text-center text-[12px] ${act.kind === "cancel" && act.error ? "text-red-600 dark:text-red-400" : "text-muted-foreground"}`}
            >
              {act.kind === "cancel" && act.error
                ? act.error
                : hydrated
                  ? `You keep ${plan.name} until ${date(end)}.`
                  : " "}
            </p>
          </div>
        </Faces>

        <span className="sr-only" role="status">
          {said}
        </span>
      </div>
    </section>
  );
}

export default Subscription;

"use client";

/* ─────────────────────────────────────────────────────────
 * SWIPE ACTIONS: a list row that slides over its actions
 *
 *   reveal    drag the row (or swipe two fingers on a
 *             trackpad) and the actions under that edge share
 *             the space it uncovers: each cell grows with the
 *             finger and its icon scales in once there's room
 *   open      let go past half the rail, or flick, and the row
 *             springs open with the actions at full size; tap
 *             the row, anywhere else or Escape to close it.
 *             Opening one row closes the others
 *   arm       keep going past most of the row and the first
 *             action takes the whole space, its icon riding the
 *             row's edge (a tick on phones). Let go to run it
 *   remove    an action that removes the row (archive, delete)
 *             slides it off and folds its height away at once;
 *             if the work fails, the row unfolds, slides back,
 *             shakes, and its time reads "Failed"
 *   hover     with a mouse, the row's time gives way to the same
 *             actions as icons, so nothing needs a swipe
 *
 * The icon buttons are the accessible actions: Tab reaches them,
 * and results are announced. The swipe cells repeat them for
 * pointers and stay out of the tab order.
 * ───────────────────────────────────────────────────────── */

import * as React from "react";
import {
  EASE_OUT,
  INTERACTION_FOCUS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";
import { type SwipeSide, useSwipeRow } from "./use-swipe-row";

export type SwipeTone = "neutral" | "primary" | "destructive";

export interface SwipeAction {
  id: string;
  label: string;
  icon: React.ReactNode;
  tone?: SwipeTone;
  /** The row leaves the list (archive, delete): it slides out and folds away at once, and comes back if onAction throws. Remove the item from your list when it resolves. */
  removes?: boolean;
  onAction: () => void | Promise<void>;
}

export interface SwipeActionsProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "children"
> {
  /** Names the row for screen readers, e.g. the message subject. */
  label: string;
  /** Under the left edge, revealed by swiping right. The first one runs on a full swipe. */
  leading?: SwipeAction[];
  /** Under the right edge, revealed by swiping left, listed from the edge inward. The first one runs on a full swipe. */
  trailing?: SwipeAction[];
  /** At the row's end, e.g. the time. With a mouse it gives way to the actions on hover. */
  meta?: React.ReactNode;
  /** Unfold on mount, for a row put back by an undo. */
  enter?: boolean;
  /** A thin line under the row, folding away with it. */
  divider?: boolean;
  disabled?: boolean;
  children: React.ReactNode;
}

const CELL = 76;
const NONE: SwipeAction[] = [];
const TONES: Record<SwipeTone, string> = {
  neutral:
    "bg-muted text-foreground shadow-[inset_1px_0_0_var(--border),inset_-1px_0_0_var(--border)]",
  primary: "bg-primary text-primary-foreground",
  destructive: "bg-destructive text-white",
};
// Cells start off the row; after that the engine owns their transforms, so these objects never change.
const OFF: Record<SwipeSide, React.CSSProperties> = {
  leading: { transform: "translate3d(-100%,0,0)", visibility: "hidden" },
  trailing: { transform: "translate3d(100%,0,0)", visibility: "hidden" },
};
const HIDDEN: React.CSSProperties = { opacity: 0 };

export function SwipeActions({
  label,
  leading = NONE,
  trailing = NONE,
  meta,
  enter = false,
  divider = true,
  disabled = false,
  children,
  className = "",
  ...props
}: SwipeActionsProps) {
  const reduced = useInteractionReducedMotion();
  const [gone, setGone] = React.useState(enter && !reduced);
  const [failed, setFailed] = React.useState(false);
  const [said, setSaid] = React.useState("");
  const busy = React.useRef(false);
  const alive = React.useRef(true);
  const body = React.useRef<HTMLDivElement>(null);
  const timers = React.useRef(new Set<ReturnType<typeof setTimeout>>());
  const lists = React.useRef({ leading, trailing });
  React.useLayoutEffect(() => {
    lists.current = { leading, trailing };
  });
  const wait = (ms: number) =>
    new Promise<void>((resolve) => {
      const t = setTimeout(
        () => {
          timers.current.delete(t);
          resolve();
        },
        reduced ? 0 : ms,
      );
      timers.current.add(t);
    });

  const run = async (
    side: SwipeSide,
    index: number,
    via: "swipe" | "cell" | "button",
  ) => {
    const action = lists.current[side][index];
    if (!action || busy.current || disabled) return;
    busy.current = true;
    setFailed(false);
    try {
      if (action.removes) {
        // Optimistic: the row leaves now, and comes back only if the work fails.
        await row.commit(side, index);
        if (!alive.current) return;
        setGone(true);
        try {
          await action.onAction();
          if (alive.current) setSaid(`${label}: ${action.label} done`);
        } catch {
          if (!alive.current) return;
          setGone(false);
          await wait(360);
          row.restore();
          await wait(420);
          fail(action);
        }
        return;
      }
      if (via === "swipe") await row.commit(side, index);
      else row.close();
      let ok = true;
      try {
        await action.onAction();
      } catch {
        ok = false;
      }
      if (!alive.current) return;
      if (via === "swipe") {
        await wait(140);
        row.restore();
      }
      if (ok) setSaid(`${label}: ${action.label} done`);
      else {
        await wait(380);
        fail(action);
      }
    } finally {
      busy.current = false;
    }
  };
  const fail = (action: SwipeAction) => {
    if (!alive.current) return;
    setFailed(true);
    setSaid(`${label}: ${action.label} failed. Try again.`);
    if (!reduced)
      body.current?.animate(
        [
          { transform: "none" },
          { transform: "translateX(-5px)" },
          { transform: "translateX(5px)" },
          { transform: "translateX(-3px)" },
          { transform: "none" },
        ],
        { duration: 380, easing: "ease-out" },
      );
    const t = setTimeout(() => {
      timers.current.delete(t);
      setFailed(false);
    }, 2600);
    timers.current.add(t);
  };

  const row = useSwipeRow({
    leading: leading.length,
    trailing: trailing.length,
    cellWidth: CELL,
    reduced,
    disabled,
    onFull: (side) => void run(side, 0, "swipe"),
  });

  React.useEffect(() => {
    alive.current = true;
    const pending = timers.current;
    return () => {
      alive.current = false;
      pending.forEach(clearTimeout);
    };
  }, []);
  // A row put back by an undo unfolds once it's mounted.
  React.useEffect(() => {
    if (!gone || !enter) return;
    let b = 0;
    const a = requestAnimationFrame(() => {
      b = requestAnimationFrame(() => setGone(false));
    });
    return () => {
      cancelAnimationFrame(a);
      cancelAnimationFrame(b);
    };
  }, []);
  // Labels changed (Read ↔ Unread): measure the faces again.
  const labels = [...leading, ...trailing].map((a) => a.label).join("|");
  React.useEffect(() => {
    row.remeasure();
  }, [labels]);

  const cellsFor = (side: SwipeSide, list: SwipeAction[]) =>
    list.map((action, i) => (
      <button
        key={`${side}-${action.id}`}
        ref={(el) => row.attachCell(side, i, el)}
        type="button"
        tabIndex={-1}
        aria-hidden="true"
        onClick={() => void run(side, i, "cell")}
        className={`absolute inset-y-0 left-0 w-full cursor-pointer will-change-transform ${TONES[action.tone ?? "neutral"]}`}
        style={OFF[side]}
      >
        <span
          ref={(el) => row.attachFace(side, i, el)}
          className="absolute left-0 top-1/2 flex -translate-y-1/2 flex-col items-center gap-1 whitespace-nowrap text-[11px] font-medium will-change-transform [&_svg]:size-[18px] [&_svg]:stroke-[1.75]"
          style={HIDDEN}
        >
          {action.icon}
          {action.label}
        </span>
      </button>
    ));

  // Mouse users get the same actions as icons: the row's own edge first, so the order matches the swipe.
  const buttons = [
    ...leading.map((a, i) => ({ a, side: "leading" as const, i })),
    ...[...trailing]
      .reverse()
      .map((a) => ({ a, side: "trailing" as const, i: trailing.indexOf(a) })),
  ];

  return (
    <div
      className={`grid ${className}`}
      style={{
        gridTemplateRows: gone ? "0fr" : "1fr",
        opacity: gone ? 0 : 1,
        transition: reduced
          ? "none"
          : `grid-template-rows 380ms ${EASE_OUT} ${gone ? "120ms" : "0ms"}, opacity ${gone ? 260 : 320}ms ${EASE_OUT} ${gone ? "160ms" : "0ms"}`,
      }}
      {...props}
    >
      <div className="min-h-0 overflow-hidden">
        <div
          ref={(el) => row.attachSurface(el)}
          role="group"
          aria-label={label}
          data-failed={failed || undefined}
          onKeyDown={(e) => {
            if (e.key === "Escape" && row.open) {
              e.preventDefault();
              row.close();
            }
          }}
          className={`group/row relative isolate touch-pan-y overflow-hidden ${divider ? "border-b border-border" : ""}`}
        >
          {cellsFor("leading", leading)}
          {cellsFor("trailing", trailing)}
          <div
            ref={(el) => row.attachFront(el)}
            className={`relative z-30 flex items-center gap-3 bg-(--row-bg) px-4 py-3 transition-[background-color] duration-200 will-change-transform [--row-bg:var(--background)] pointer-fine:group-hover/row:[--row-bg:color-mix(in_oklab,var(--muted)_55%,var(--background))] ${disabled ? "opacity-60" : "cursor-grab active:cursor-grabbing"}`}
          >
            <div ref={body} className="min-w-0 flex-1">
              {children}
            </div>
            <div className="relative flex shrink-0 items-center self-stretch">
              <span className="grid text-right text-[11.5px] tabular-nums text-muted-foreground transition-opacity duration-200 pointer-fine:group-hover/row:opacity-0 group-focus-within/row:opacity-0 group-data-[moving]/row:opacity-100! group-data-[failed]/row:opacity-100!">
                <span
                  className="col-start-1 row-start-1 transition-[opacity,filter] duration-300"
                  style={{
                    opacity: failed ? 0 : 1,
                    filter: failed ? "blur(3px)" : "none",
                  }}
                >
                  {meta}
                </span>
                <span
                  className="col-start-1 row-start-1 text-red-600 transition-[opacity,filter] duration-300 dark:text-red-400"
                  style={{
                    opacity: failed ? 1 : 0,
                    filter: failed ? "none" : "blur(3px)",
                  }}
                >
                  Failed
                </span>
              </span>
              {buttons.length > 0 && (
                <div
                  className="pointer-events-none absolute right-0 top-1/2 flex -translate-y-1/2 translate-x-1 items-center gap-0.5 pl-6 opacity-0 transition-[opacity,transform] duration-200 pointer-fine:group-hover/row:pointer-events-auto pointer-fine:group-hover/row:translate-x-0 pointer-fine:group-hover/row:opacity-100 group-focus-within/row:pointer-events-auto group-focus-within/row:translate-x-0 group-focus-within/row:opacity-100 group-data-[moving]/row:pointer-events-none! group-data-[moving]/row:opacity-0! group-data-[failed]/row:pointer-events-none! group-data-[failed]/row:opacity-0!"
                  style={{
                    background:
                      "linear-gradient(to right, transparent, var(--row-bg) 18px)",
                  }}
                >
                  {buttons.map(({ a, side, i }) => (
                    <button
                      key={`${side}-${a.id}`}
                      type="button"
                      aria-label={a.label}
                      title={a.label}
                      disabled={disabled}
                      onClick={() => void run(side, i, "button")}
                      className={`flex size-7 cursor-pointer items-center justify-center rounded-full text-muted-foreground transition-[background-color,color,box-shadow] duration-150 hover:bg-background hover:shadow-[0_0_0_1px_var(--border)] disabled:cursor-default [&_svg]:size-4 [&_svg]:stroke-[1.75] ${a.tone === "destructive" ? "hover:text-red-600 dark:hover:text-red-400" : "hover:text-foreground"} ${INTERACTION_FOCUS}`}
                    >
                      {a.icon}
                    </button>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
      <span role="status" className="sr-only">
        {said}
      </span>
    </div>
  );
}

"use client";

import * as React from "react";
import {
  EASE_OUT,
  EASE_THROW,
  INTERACTION_FOCUS,
  interactionIcon,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * SWITCH: on and off, with weight
 *
 *   press    the thumb stretches toward the side it will go
 *   flip     it's thrown across with a slight overshoot while the
 *            track fills; the fill and thumb move as one
 *   async    if onCheckedChange returns a promise, the switch
 *            flips at once and the thumb spins until it settles;
 *            a rejection throws it back and shakes the track
 * ───────────────────────────────────────────────────────── */

export interface SwitchProps extends Omit<
  React.ButtonHTMLAttributes<HTMLButtonElement>,
  "onChange" | "value"
> {
  checked?: boolean;
  defaultChecked?: boolean;
  /** Return a promise to show the pending thumb; throw to put it back. */
  onCheckedChange?: (checked: boolean) => void | Promise<unknown>;
  label?: React.ReactNode;
  description?: React.ReactNode;
  /** 16px or 20px tall. */
  size?: "sm" | "md";
  /** Put the label before the switch (settings rows). */
  labelPosition?: "start" | "end";
  ref?: React.Ref<HTMLButtonElement>;
}

const SIZES = { sm: { w: 28, h: 16, pad: 2 }, md: { w: 36, h: 20, pad: 2 } };

export function Switch({
  checked,
  defaultChecked = false,
  onCheckedChange,
  label,
  description,
  size = "md",
  labelPosition = "end",
  disabled,
  className = "",
  id,
  ref,
  ...props
}: SwitchProps) {
  const reduced = useInteractionReducedMotion();
  const auto = React.useId();
  const switchId = id ?? auto;
  const track = React.useRef<HTMLSpanElement>(null);
  const [own, setOwn] = React.useState(defaultChecked);
  const [optimistic, setOptimistic] = React.useState<boolean | null>(null);
  const [pressed, setPressed] = React.useState(false);
  const on = optimistic ?? (checked !== undefined ? checked : own);
  const pending = optimistic !== null;
  const s = SIZES[size];
  const thumb = s.h - s.pad * 2;
  const travel = s.w - thumb - s.pad * 2;
  const stretch = pressed && !reduced ? 4 : 0;

  const toggle = () => {
    if (disabled || pending) return;
    const next = !on;
    const result = onCheckedChange?.(next);
    if (result && typeof (result as Promise<unknown>).then === "function") {
      setOptimistic(next);
      (result as Promise<unknown>).then(
        () => {
          if (checked === undefined) setOwn(next);
          setOptimistic(null);
        },
        () => {
          setOptimistic(null);
          if (!reduced)
            track.current?.animate(
              [
                { transform: "none" },
                { transform: "translateX(-3px)" },
                { transform: "translateX(3px)" },
                { transform: "none" },
              ],
              { duration: 320, easing: "ease-out" },
            );
        },
      );
    } else if (checked === undefined) setOwn(next);
  };

  const control = (
    <button
      ref={ref}
      id={switchId}
      type="button"
      role="switch"
      aria-checked={on}
      aria-busy={pending || undefined}
      disabled={disabled}
      onClick={toggle}
      onPointerDown={() => setPressed(true)}
      onPointerUp={() => setPressed(false)}
      onPointerLeave={() => setPressed(false)}
      onBlur={() => setPressed(false)}
      className={`relative inline-flex shrink-0 rounded-full cursor-pointer disabled:cursor-default disabled:opacity-50 ${INTERACTION_FOCUS}`}
      style={{ width: s.w, height: s.h }}
      {...props}
    >
      <span
        ref={track}
        className="absolute inset-0 overflow-hidden rounded-full bg-[color-mix(in_oklab,var(--foreground)_12%,var(--muted))] shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--foreground)_10%,transparent)]"
      >
        <span
          className="absolute inset-0 rounded-full bg-primary"
          style={{
            opacity: on ? 1 : 0,
            transition: reduced ? "none" : `opacity 260ms ${EASE_OUT}`,
          }}
        />
      </span>
      <span
        className="absolute rounded-full bg-background shadow-[0_0_0_1px_color-mix(in_oklab,var(--foreground)_10%,transparent)]"
        style={{
          top: s.pad,
          left: s.pad,
          height: thumb,
          width: thumb + stretch,
          // Stretching toward where it's going: grow from the far edge when on.
          transform: `translateX(${on ? travel - stretch : 0}px)`,
          transition: reduced
            ? "none"
            : `transform 420ms ${EASE_THROW}, width 260ms ${EASE_OUT}`,
        }}
      >
        <span
          className="absolute inset-0 flex items-center justify-center text-primary"
          style={interactionIcon(pending, reduced)}
        >
          <span
            className={`size-[60%] rounded-full border-[1.5px] border-current border-t-transparent ${pending ? "animate-spin" : ""}`}
          />
        </span>
      </span>
    </button>
  );

  if (!label && !description)
    return <span className={className}>{control}</span>;

  return (
    <div
      className={`flex items-start gap-3 ${labelPosition === "start" ? "flex-row-reverse justify-between" : ""} ${className}`}
    >
      <span className="mt-0.5">{control}</span>
      <label
        htmlFor={switchId}
        className={`flex min-w-0 flex-col gap-0.5 ${disabled ? "opacity-50" : "cursor-pointer"}`}
      >
        {label && (
          <span className="text-[13.5px] font-medium leading-5 text-foreground">
            {label}
          </span>
        )}
        {description && (
          <span className="text-[12.5px] leading-snug text-muted-foreground">
            {description}
          </span>
        )}
      </label>
    </div>
  );
}

export default Switch;

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import {
  EASE_OUT,
  EASE_THROW,
  INTERACTION_FOCUS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * TABS: views of one thing, side by side
 *
 *   pick     the indicator (an underline, or a pill) is thrown to
 *            the new tab while its width eases to the label
 *   panel    the new panel slides in from the side you moved
 *            toward, out of a blur, as the old one leaves the other
 *            way; the box eases to the new panel's height
 *   count    a tab's count rolls when it changes
 *   keys     arrows move and select, Home/End jump; the tablist
 *            scrolls the chosen tab into view on narrow screens
 * ───────────────────────────────────────────────────────── */

export interface TabItem {
  value: string;
  label: React.ReactNode;
  icon?: React.ReactNode;
  count?: number;
  content?: React.ReactNode;
  disabled?: boolean;
}

export interface TabsProps {
  items: TabItem[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  variant?: "underline" | "pills";
  /** Accessible name of the tablist. */
  label: string;
  className?: string;
}

type Leaving = {
  value: string;
  dir: number;
  node: React.ReactNode;
  key: string;
};

export function Tabs({
  items,
  value,
  defaultValue,
  onValueChange,
  variant = "underline",
  label,
  className = "",
}: TabsProps) {
  const reduced = useInteractionReducedMotion();
  const baseId = React.useId();
  const listRef = React.useRef<HTMLDivElement>(null);
  const panelRef = React.useRef<HTMLDivElement>(null);
  const [own, setOwn] = React.useState(defaultValue ?? items[0]?.value);
  const current = value !== undefined ? value : own;
  const [mark, setMark] = React.useState<{ x: number; w: number } | null>(null);
  const [ready, setReady] = React.useState(false);
  const [height, setHeight] = React.useState<number | null>(null);
  const [shown, setShown] = React.useState(current);
  const [leaving, setLeaving] = React.useState<Leaving | null>(null);
  const [dir, setDir] = React.useState(1);
  const pills = variant === "pills";

  // When the value changes, the old panel becomes a leaving copy and the new one enters from `dir`.
  if (shown !== current) {
    const from = items.findIndex((i) => i.value === shown);
    const to = items.findIndex((i) => i.value === current);
    const d = to >= from ? 1 : -1;
    setDir(d);
    setLeaving(
      reduced
        ? null
        : {
            value: shown,
            dir: d,
            node: items[from]?.content,
            key: `${shown}>${current}`,
          },
    );
    setShown(current);
  }

  React.useEffect(() => {
    if (!leaving) return;
    const timer = window.setTimeout(() => setLeaving(null), 260);
    return () => window.clearTimeout(timer);
  }, [leaving]);

  React.useLayoutEffect(() => {
    const list = listRef.current;
    if (!list) return;
    const measure = () => {
      const el = list.querySelector<HTMLElement>(
        `[data-tab="${CSS.escape(current ?? "")}"]`,
      );
      if (!el) return setMark(null);
      const next = { x: el.offsetLeft, w: el.offsetWidth };
      setMark((p) => (p && p.x === next.x && p.w === next.w ? p : next));
      // Keep the chosen tab in view inside the scrolling strip, never scrolling the page.
      const strip = list.parentElement;
      if (strip && strip.scrollWidth > strip.clientWidth) {
        const left = el.offsetLeft - 16;
        const right = el.offsetLeft + el.offsetWidth + 16 - strip.clientWidth;
        if (strip.scrollLeft > left)
          strip.scrollTo({ left, behavior: reduced ? "auto" : "smooth" });
        else if (strip.scrollLeft < right)
          strip.scrollTo({
            left: right,
            behavior: reduced ? "auto" : "smooth",
          });
      }
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(list);
    return () => ro.disconnect();
  }, [current, items, reduced]);

  React.useEffect(() => {
    if (!mark || ready) return;
    const frame = requestAnimationFrame(() => setReady(true));
    return () => cancelAnimationFrame(frame);
  }, [mark, ready]);

  React.useLayoutEffect(() => {
    const el = panelRef.current;
    if (!el) return;
    const measure = () =>
      setHeight((h) => (h === el.offsetHeight ? h : el.offsetHeight));
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    return () => ro.disconnect();
  }, [shown]);

  // The entering and leaving panels' motion, played once per change.
  const leavingRef = React.useRef<HTMLDivElement>(null);
  React.useLayoutEffect(() => {
    const el = panelRef.current;
    if (!el || !leaving) return;
    leavingRef.current?.animate(
      [
        { opacity: 1, transform: "none", filter: "blur(0px)" },
        {
          opacity: 0,
          transform: `translateX(${-leaving.dir * 20}px)`,
          filter: "blur(4px)",
        },
      ],
      { duration: 200, easing: EASE_OUT, fill: "forwards" },
    );
    el.animate(
      [
        {
          opacity: 0,
          transform: `translateX(${dir * 20}px)`,
          filter: "blur(4px)",
        },
        { opacity: 1, transform: "none", filter: "blur(0px)" },
      ],
      { duration: 380, easing: EASE_OUT },
    );
  }, [leaving, dir]);

  const pick = (v: string) => {
    if (value === undefined) setOwn(v);
    onValueChange?.(v);
  };

  const onKeyDown = (e: React.KeyboardEvent) => {
    const enabled = items.filter((i) => !i.disabled);
    const index = enabled.findIndex((i) => i.value === current);
    let next = -1;
    if (e.key === "ArrowRight") next = (index + 1) % enabled.length;
    else if (e.key === "ArrowLeft")
      next = (index - 1 + enabled.length) % enabled.length;
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = enabled.length - 1;
    if (next < 0) return;
    e.preventDefault();
    pick(enabled[next].value);
    listRef.current
      ?.querySelector<HTMLElement>(
        `[data-tab="${CSS.escape(enabled[next].value)}"]`,
      )
      ?.focus();
  };

  const hasPanels = items.some((i) => i.content !== undefined);
  const active = items.find((i) => i.value === shown);

  return (
    <div className={`flex w-full min-w-0 flex-col ${className}`}>
      <div
        className={`relative min-w-0 overflow-x-auto [scrollbar-width:none] [&::-webkit-scrollbar]:hidden ${pills ? "" : "shadow-[inset_0_-1px_0_var(--border)]"}`}
      >
        <div
          ref={listRef}
          role="tablist"
          aria-label={label}
          onKeyDown={onKeyDown}
          className={`relative flex w-max items-center ${pills ? "gap-1 rounded-full bg-muted p-1" : "gap-5 px-1"}`}
        >
          <span
            aria-hidden="true"
            className={`pointer-events-none absolute left-0 ${pills ? "top-1 bottom-1 rounded-full bg-background shadow-[0_0_0_1px_var(--border)]" : "bottom-0 h-[2px] rounded-full bg-foreground"}`}
            style={{
              transform: `translateX(${mark?.x ?? 0}px)`,
              width: mark?.w ?? 0,
              opacity: mark ? 1 : 0,
              transition:
                reduced || !ready
                  ? "none"
                  : `transform 440ms ${EASE_THROW}, width 400ms ${EASE_OUT}, opacity 200ms ${EASE_OUT}`,
            }}
          />
          {items.map((item) => {
            const on = item.value === current;
            return (
              <button
                key={item.value}
                type="button"
                role="tab"
                id={`${baseId}-tab-${item.value}`}
                aria-selected={on}
                aria-controls={hasPanels ? `${baseId}-panel` : undefined}
                tabIndex={on ? 0 : -1}
                disabled={item.disabled}
                data-tab={item.value}
                onClick={() => pick(item.value)}
                className={`relative z-10 flex shrink-0 items-center gap-1.5 whitespace-nowrap text-[13px] font-medium cursor-pointer transition-colors duration-200 disabled:cursor-default disabled:opacity-40 [&_svg]:size-3.5 ${
                  pills ? "h-7 rounded-full px-3" : "h-10 rounded-md"
                } ${on ? "text-foreground" : "text-muted-foreground hover:text-foreground"} ${INTERACTION_FOCUS}`}
              >
                {item.icon}
                {item.label}
                {item.count !== undefined && (
                  <span
                    className={`rounded-full px-1.5 text-[11px] tabular-nums transition-colors duration-200 ${on ? "bg-foreground text-background" : "bg-muted text-muted-foreground"} ${pills && !on ? "bg-background" : ""}`}
                  >
                    <NumberRoll value={item.count} />
                  </span>
                )}
              </button>
            );
          })}
        </div>
      </div>
      {hasPanels && (
        <div
          className="relative overflow-hidden"
          style={{
            height: height ?? undefined,
            transition: reduced ? "none" : `height 380ms ${EASE_OUT}`,
          }}
        >
          {leaving && (
            <div
              key={leaving.key}
              aria-hidden="true"
              className="pointer-events-none absolute inset-x-0 top-0 pt-4"
              ref={leavingRef}
            >
              {leaving.node}
            </div>
          )}
          <div
            ref={panelRef}
            id={`${baseId}-panel`}
            role="tabpanel"
            aria-labelledby={`${baseId}-tab-${shown}`}
            tabIndex={0}
            className="pt-4 outline-none"
          >
            {active?.content}
          </div>
        </div>
      )}
    </div>
  );
}

export default Tabs;

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";
import {
  carryFrames,
  flyFrames,
  LEAVE_FRAMES,
  playTokens,
  pulseToken,
  shakeToken,
  snapshotTokens,
  TOKEN_EASE,
  type TokenBox,
  type TokenEnter,
  type TokenSnapshot,
} from "./use-token-flip";

/* ─────────────────────────────────────────────────────────
 * TAG INPUT: the To field, the invite field, the labels field
 *
 *   type      Enter or a comma, and the letters you typed stay
 *             where they are while a thin line shell grows round
 *             them; the caret is already past it
 *   paste     a pasted list spills out of the caret chip by
 *             chip; a duplicate flies into its twin, which
 *             bumps; an invalid one lands red and shakes
 *   resolve   "maya@fernhill.co" morphs into "Maya Chen" while
 *             her initials open in, once resolve() knows her
 *   pick      a suggestion's name is carried from the list
 *             into its chip
 *   back      Backspace in an empty field selects the last
 *             chip; again, and its shell drops away and the
 *             letters are text you can edit
 *   reflow    every chip glides when one leaves or a line
 *             wraps; the field's height eases to fit
 *   collapse  out of focus, lines past `collapse` fold away and
 *             a "+4" counts them
 * ───────────────────────────────────────────────────────── */

export interface TagInputTag {
  id: string;
  /** What was typed or picked, normalised: the address, the label. */
  value: string;
  /** What the chip shows instead, once known: a name for an address. */
  label?: string;
  /** A picture for the chip. Without one, a known label gets its initials. */
  image?: string;
  /** Why the value isn't valid. The chip turns red and stays until it's fixed or removed. */
  error?: string;
}

export interface TagInputSuggestion {
  value: string;
  label?: string;
  image?: string;
  /** A second line in the list; defaults to the value when a label is shown. */
  description?: string;
}

export interface TagInputHandle {
  /** Runs text through the paste path: split, checked and cascaded in. */
  paste: (text: string) => void;
  focus: () => void;
  /** Removes every tag. */
  clear: () => void;
}

export interface TagInputProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "defaultValue" | "onChange"
> {
  value?: TagInputTag[];
  defaultValue?: TagInputTag[];
  onValueChange?: (tags: TagInputTag[]) => void;
  /** Return a message to mark a value invalid. */
  validate?: (value: string) => string | null | undefined | void;
  /** Look a value up once it's added: resolve to a label (and image) for the chip to morph into, or null to leave it. */
  resolve?: (
    value: string,
  ) => Promise<{ label?: string; image?: string } | null | undefined | void>;
  /** A list to filter, or a function that finds matches for what's typed (may be async). */
  suggestions?:
    | TagInputSuggestion[]
    | ((query: string) => TagInputSuggestion[] | Promise<TagInputSuggestion[]>);
  /** Applied to every value before it's checked and compared, e.g. lower-casing addresses. */
  normalize?: (value: string) => string;
  /** What splits typed and pasted text into values. */
  separators?: RegExp;
  /** How many tags the field takes. */
  max?: number;
  /** Shown when a value doesn't fit under `max`. */
  limitMessage?: string;
  /** The suggestion row that adds what's typed as it is; null hides it. */
  createLabel?: ((text: string) => string) | null;
  /** Lines to show while the field is out of focus; the rest fold into a count. */
  collapse?: number;
  /** Accessible name of the field. */
  label?: string;
  placeholder?: string;
  /** A line under the field, replaced by errors and notices while they last. */
  hint?: string;
  /** Submits the valid values, comma-separated, with a form. */
  name?: string;
  disabled?: boolean;
  ref?: React.Ref<TagInputHandle>;
}

type Draft = { value: string; label?: string; image?: string };
type Ghost = {
  key: number;
  kind: "leave" | "fly" | "unspool" | "carry";
  text: string;
  /** Root coordinates. */
  box: TokenBox;
  to?: TokenBox;
  /** Where the letters sit inside the box. */
  inner?: TokenBox;
  twin?: string;
  delay?: number;
  /** Fades in where it starts (a pasted duplicate) instead of already being there. */
  appear?: boolean;
  error?: boolean;
  avatar?: { image?: string; name: string };
};
/** A copy flying to a chip whose place is only known after layout; `after` starts it where it would have landed, after that chip. */
type Flight = {
  kind: "fly" | "carry";
  text: string;
  from: TokenBox | { after: string | null; w: number };
  twin: string;
  delay: number;
};
type Pending = {
  before: TokenSnapshot | null;
  enter: Map<string, TokenEnter>;
  skipInput?: boolean;
  ghosts: Ghost[];
  /** Ghosts flying to a chip whose place is only known after layout. */
  flights: Flight[];
  shake: { id: string; delay: number }[];
  shakeField?: boolean;
  /** Edited text glides out of this box (root coordinates) into the input. */
  inputFrom?: { box: TokenBox; fade: boolean };
  focus?: "input" | string;
};
type Notice = { text: string; tone: "muted" | "warn"; key: number };
type Row = TagInputSuggestion & { create?: boolean };
type How =
  | { type: TokenBox | null }
  | { paste: { x: number; y: number } }
  | { pick: TokenBox };

const EASE = TOKEN_EASE;
const EMPTY: TagInputTag[] = [];
const SEPARATORS = /[,;\n]+/;
const CHIP_H = 28;
/** Labels longer than this many characters are cut to fit a phone-width field; the chip's title has the whole. */
const LONG = 28;
const PAD = 5;
const GAP = 6;
const CREATE = (text: string) => `Add “${text}”`;
const SAME = (v: string) => v;

let seq = 0;
const newId = () => `tag-${Date.now().toString(36)}-${(seq++).toString(36)}`;
const display = (t: { value: string; label?: string }) => t.label || t.value;
const initials = (name: string) =>
  name
    .split(/[\s._-]+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((w) => w[0]!.toUpperCase())
    .join("");
const shift = (b: TokenBox, dx: number, dy: number): TokenBox => ({
  x: b.x + dx,
  y: b.y + dy,
  w: b.w,
  h: b.h,
});

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 240ms ${EASE}, transform 380ms ${EASE}, filter 240ms ${EASE}`,
});

const shellStyle = (
  error: boolean,
  selected: boolean,
): React.CSSProperties => ({
  background: error
    ? "color-mix(in oklab, #ef4444 7%, var(--background))"
    : selected
      ? "var(--accent)"
      : "var(--background)",
  boxShadow: error
    ? `inset 0 0 0 1px color-mix(in oklab, #ef4444 ${selected ? 75 : 45}%, transparent)`
    : selected
      ? "inset 0 0 0 1px color-mix(in oklab, var(--ring) 70%, transparent)"
      : "inset 0 0 0 1px var(--border)",
});

function Avatar({
  image,
  name,
  size,
}: {
  image?: string;
  name: string;
  size: number;
}) {
  return image ? (
    <img
      src={image}
      alt=""
      draggable={false}
      className="shrink-0 rounded-full object-cover"
      style={{ width: size, height: size }}
    />
  ) : (
    <span
      className="flex shrink-0 items-center justify-center rounded-full bg-muted font-medium text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)]"
      style={{ width: size, height: size, fontSize: Math.round(size * 0.4) }}
    >
      {initials(name)}
    </span>
  );
}

function Cross() {
  return (
    <svg viewBox="0 0 12 12" className="size-3" fill="none" aria-hidden="true">
      <path
        d="M3.5 3.5 8.5 8.5M8.5 3.5 3.5 8.5"
        stroke="currentColor"
        strokeWidth="1.4"
        strokeLinecap="round"
      />
    </svg>
  );
}

/** A sentence that changes crossfades whole: the old one lifts away through a blur while the new one rises in. */
function Line({ text, reduced }: { text: string; reduced: boolean }) {
  const [shown, setShown] = React.useState({ text, key: 0 });
  const [leaving, setLeaving] = React.useState<{ text: string; key: number }[]>(
    [],
  );
  if (text !== shown.text) {
    if (shown.text && !reduced) setLeaving((l) => [...l, shown]);
    setShown({ text, key: shown.key + 1 });
  }
  return (
    <span className="relative block">
      <span
        key={shown.key}
        className="block"
        ref={(el) => {
          if (!el || reduced || shown.key === 0 || el.dataset.in) return;
          el.dataset.in = "1";
          el.animate(
            [
              {
                opacity: 0,
                transform: "translateY(0.35em)",
                filter: "blur(4px)",
              },
              { opacity: 1, transform: "none", filter: "blur(0px)" },
            ],
            { duration: 420, delay: 60, easing: EASE, fill: "backwards" },
          );
        }}
      >
        {shown.text || " "}
      </span>
      {leaving.map((l) => (
        <span
          key={l.key}
          aria-hidden="true"
          className="pointer-events-none absolute inset-x-0 top-0 block"
          ref={(el) => {
            if (!el || el.dataset.out) return;
            el.dataset.out = "1";
            el.animate(
              [
                { opacity: 1, transform: "none", filter: "blur(0px)" },
                {
                  opacity: 0,
                  transform: "translateY(-0.35em)",
                  filter: "blur(4px)",
                },
              ],
              { duration: 200, easing: EASE, fill: "forwards" },
            ).onfinish = () =>
              setLeaving((all) => all.filter((x) => x.key !== l.key));
          }}
        >
          {l.text}
        </span>
      ))}
    </span>
  );
}

/** A copy of a chip (or of its letters) that leaves, flies into a twin, drops its shell or carries a name in. */
function GhostChip({
  ghost,
  onDone,
}: {
  ghost: Ghost;
  onDone: (ghost: Ghost) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  const shell = React.useRef<HTMLSpanElement>(null);
  const letters = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    let a: Animation;
    if (ghost.kind === "leave")
      a = el.animate(LEAVE_FRAMES, {
        duration: 280,
        easing: EASE,
        fill: "forwards",
      });
    else if (ghost.kind === "fly" && ghost.to)
      a = el.animate(flyFrames(ghost.box, ghost.to, ghost.appear), {
        duration: ghost.appear ? 820 : 620,
        delay: ghost.delay ?? 0,
        easing: EASE,
        fill: "both",
      });
    else if (ghost.kind === "carry" && ghost.to)
      a = el.animate(carryFrames(ghost.box, ghost.to), {
        duration: 480,
        easing: EASE,
        fill: "both",
      });
    else {
      // The shell shrinks round the letters and fades; the letters fade into the input's own.
      const b = ghost.box;
      const i = ghost.inner ?? b;
      const left = Math.max(0, i.x - b.x - 3);
      const right = Math.max(0, b.x + b.w - (i.x + i.w) - 3);
      shell.current?.animate(
        [
          { clipPath: "inset(0px 0px 0px 0px round 999px)", opacity: 1 },
          {
            clipPath: `inset(4px ${right}px 4px ${left}px round 999px)`,
            opacity: 0,
          },
        ],
        { duration: 360, easing: EASE, fill: "forwards" },
      );
      el.querySelector<HTMLElement>("[data-ghost-avatar]")?.animate(
        LEAVE_FRAMES,
        { duration: 240, easing: EASE, fill: "forwards" },
      );
      a = (letters.current ?? el).animate(
        [
          { opacity: 1, filter: "blur(0px)" },
          { opacity: 0, filter: "blur(4px)" },
        ],
        { duration: 320, easing: EASE, fill: "forwards" },
      );
    }
    a.onfinish = () => onDone(ghost);
    return () => a.cancel();
  }, []);

  const carry = ghost.kind === "carry";
  const inner = ghost.inner;
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className={`pointer-events-none absolute flex items-center whitespace-nowrap will-change-transform ${carry ? "text-[13.5px]" : "rounded-full px-2.5 text-[13px]"} ${
        ghost.error ? "text-red-600 dark:text-red-400" : "text-foreground"
      }`}
      style={{
        left: ghost.box.x,
        top: ghost.box.y,
        width: ghost.box.w,
        height: ghost.box.h,
        transformOrigin: carry ? "left center" : "center",
      }}
    >
      {!carry && (
        <span
          ref={shell}
          className="absolute inset-0 rounded-full"
          style={shellStyle(!!ghost.error, false)}
        />
      )}
      {ghost.avatar && (
        <span data-ghost-avatar="" className="absolute left-1 top-1">
          <Avatar
            image={ghost.avatar.image}
            name={ghost.avatar.name}
            size={20}
          />
        </span>
      )}
      <span
        ref={letters}
        className={inner ? "absolute block py-1" : "relative"}
        style={
          inner
            ? { left: inner.x - ghost.box.x, top: inner.y - ghost.box.y }
            : undefined
        }
      >
        {ghost.text}
      </span>
    </span>
  );
}

export function TagInput({
  value,
  defaultValue,
  onValueChange,
  validate,
  resolve,
  suggestions,
  normalize = SAME,
  separators = SEPARATORS,
  max,
  limitMessage = "No room for more",
  createLabel = CREATE,
  collapse,
  label = "Add tags",
  placeholder,
  hint,
  name,
  disabled = false,
  ref,
  className = "",
  ...props
}: TagInputProps) {
  const reduced = useReducedMotion();
  const uid = React.useId();
  const [own, setOwn] = React.useState<TagInputTag[]>(defaultValue ?? EMPTY);
  const tags = value ?? own;
  const tagsRef = React.useRef(tags);
  const [text, setText] = React.useState("");
  const [resolving, setResolving] = React.useState<ReadonlySet<string>>(
    () => new Set(),
  );
  const [selected, setSelected] = React.useState<string | null>(null);
  const [within, setWithin] = React.useState(false);
  const [inputFocus, setInputFocus] = React.useState(false);
  const [asyncOptions, setAsyncOptions] = React.useState<TagInputSuggestion[]>(
    [],
  );
  const [active, setActive] = React.useState(-1);
  const [dismissed, setDismissed] = React.useState(false);
  const [notice, setNotice] = React.useState<Notice | null>(null);
  const [ghosts, setGhosts] = React.useState<Ghost[]>([]);
  const [announce, setAnnounce] = React.useState("");
  const [tick, setTick] = React.useState(0);
  const [cut, setCut] = React.useState<{
    hidden: string[];
    x: number;
    y: number;
    height: number;
  } | null>(null);
  const pending = React.useRef<Pending | null>(null);
  const rootRef = React.useRef<HTMLDivElement>(null);
  const fieldRef = React.useRef<HTMLDivElement>(null);
  const wrapRef = React.useRef<HTMLDivElement>(null);
  const listRef = React.useRef<HTMLDivElement>(null);
  const inputRef = React.useRef<HTMLInputElement>(null);
  const mirrorRef = React.useRef<HTMLSpanElement>(null);
  const pillRef = React.useRef<HTMLSpanElement>(null);
  const rowRefs = React.useRef<(HTMLDivElement | null)[]>([]);
  const ghostKey = React.useRef(0);
  /** Focus we moved ourselves (after an edit or a removal) doesn't open the suggestions. */
  const quietFocus = React.useRef(false);
  /** Whether the chip being clicked was already selected: a second click (or tap) edits it. */
  const wasSelected = React.useRef(false);
  const alive = React.useRef(true);
  React.useEffect(() => {
    alive.current = true;
    return () => {
      alive.current = false;
    };
  }, []);

  const collapsed = collapse !== undefined && !within && tags.length > 0;
  const collapsedRef = React.useRef(collapsed);
  React.useLayoutEffect(() => {
    tagsRef.current = tags;
    collapsedRef.current = collapsed;
  });

  const commit = (next: TagInputTag[]) => {
    tagsRef.current = next;
    if (value === undefined) setOwn(next);
    onValueChange?.(next);
  };

  const say = (message: string) =>
    setAnnounce((a) => (a === message ? `${message} ` : message));
  const flashSeq = React.useRef(0);
  const flash = (message: string, tone: Notice["tone"]) => {
    const key = ++flashSeq.current;
    setNotice({ text: message, tone, key });
    window.setTimeout(
      () => setNotice((n) => (n?.key === key ? null : n)),
      2600,
    );
  };

  // ── Measuring ──────────────────────────────────────────
  /** From list coordinates to the root's, where ghosts live. */
  const rootOffset = () => {
    const list = listRef.current?.getBoundingClientRect();
    const root = rootRef.current?.getBoundingClientRect();
    return list && root
      ? { dx: list.left - root.left, dy: list.top - root.top }
      : { dx: 0, dy: 0 };
  };
  const textWidth = (s: string) => {
    const m = mirrorRef.current;
    if (!m) return s.length * 7;
    m.textContent = s;
    return m.offsetWidth;
  };
  /** Where a stretch of the input's text is drawn, in list coordinates. */
  const textBox = (start: number, s: string): TokenBox | null => {
    const input = inputRef.current;
    const list = listRef.current;
    if (!input || !list) return null;
    const i = input.getBoundingClientRect();
    const l = list.getBoundingClientRect();
    const h = 18;
    return {
      x:
        i.left -
        l.left +
        textWidth(input.value.slice(0, start)) -
        input.scrollLeft,
      y: i.top - l.top + (i.height - h) / 2,
      w: Math.max(1, textWidth(s)),
      h,
    };
  };
  const caretPoint = () => {
    const input = inputRef.current;
    const b = textBox(input?.selectionStart ?? text.length, "") ?? {
      x: PAD,
      y: PAD,
      w: 1,
      h: 18,
    };
    return { x: b.x, y: b.y + b.h / 2 - CHIP_H / 2 };
  };

  // ── Changes ────────────────────────────────────────────
  /** Queue a change to play after React lays it out. Changes in the same render merge; the earliest snapshot wins. */
  const stage = (p: Partial<Pending>, before?: TokenSnapshot | null) => {
    const prev = pending.current;
    pending.current = {
      ...prev,
      ...p,
      before: prev
        ? prev.before
        : (before ??
          (listRef.current ? snapshotTokens(listRef.current) : null)),
      enter: new Map([...(prev?.enter ?? []), ...(p.enter ?? [])]),
      ghosts: [...(prev?.ghosts ?? []), ...(p.ghosts ?? [])],
      flights: [...(prev?.flights ?? []), ...(p.flights ?? [])],
      shake: [...(prev?.shake ?? []), ...(p.shake ?? [])],
    };
    setTick((t) => t + 1);
  };

  const plan = (drafts: Draft[], base: TagInputTag[]) => {
    const next = base.slice();
    const added: TagInputTag[] = [];
    const dups: {
      draft: Draft;
      twin: string;
      index: number;
      after: string | null;
    }[] = [];
    let overflow = 0;
    let index = 0;
    for (const d of drafts) {
      const v = normalize(d.value.trim());
      if (!v) continue;
      const twin = next.find((t) => t.value === v);
      if (twin) {
        dups.push({
          draft: { ...d, value: v },
          twin: twin.id,
          index: index++,
          after: next[next.length - 1]?.id ?? null,
        });
        continue;
      }
      index++;
      if (max !== undefined && next.length >= max) {
        overflow++;
        continue;
      }
      const error = (validate?.(v) as string | null | undefined) || undefined;
      const tag: TagInputTag = {
        id: newId(),
        value: v,
        ...(d.label ? { label: d.label } : {}),
        ...(d.image ? { image: d.image } : {}),
        ...(error ? { error } : {}),
      };
      next.push(tag);
      added.push(tag);
    }
    return { next, added, dups, overflow };
  };

  const lookUp = (added: TagInputTag[]) => {
    if (!resolve) return;
    const run = added.filter((t) => !t.error && !t.label);
    if (!run.length) return;
    setResolving((s) => new Set([...s, ...run.map((t) => t.id)]));
    for (const tag of run) {
      Promise.resolve()
        .then(() => resolve(tag.value))
        .catch(() => null)
        .then((result) => {
          if (!alive.current) return;
          const found = result as
            { label?: string; image?: string } | null | undefined;
          const fill =
            found && (found.label || found.image)
              ? {
                  ...(found.label ? { label: found.label } : {}),
                  ...(found.image ? { image: found.image } : {}),
                }
              : null;
          const current = tagsRef.current;
          stage({});
          setResolving((s) => {
            const n = new Set(s);
            n.delete(tag.id);
            return n;
          });
          if (fill && current.some((t) => t.id === tag.id)) {
            commit(
              current.map((t) => (t.id === tag.id ? { ...t, ...fill } : t)),
            );
            if (fill.label) say(`${tag.value} is ${fill.label}.`);
          }
        });
    }
  };

  /** Adds values however they came: typed (the letters stay put), pasted (they spill from the caret) or picked (carried from the list). */
  const add = (drafts: Draft[], how: How) => {
    const result = plan(drafts, tagsRef.current);
    const { dx, dy } = rootOffset();
    const delayOf = (i: number) => ("paste" in how ? Math.min(i * 50, 500) : 0);
    const enter = new Map<string, TokenEnter>();
    const shake: Pending["shake"] = [];
    const flights: Flight[] = [];

    result.added.forEach((t, i) => {
      if ("type" in how)
        enter.set(
          t.id,
          how.type ? { from: "text", box: how.type } : { from: "text" },
        );
      else if ("paste" in how)
        enter.set(t.id, {
          from: "point",
          x: how.paste.x,
          y: how.paste.y,
          delay: delayOf(i),
        });
      else {
        enter.set(t.id, { from: "text", hold: 480 });
        flights.push({
          kind: "carry",
          text: display(t),
          from: how.pick,
          twin: t.id,
          delay: 0,
        });
      }
      if (t.error) shake.push({ id: t.id, delay: delayOf(i) + 380 });
    });

    result.dups.forEach((d) => {
      const word = display(d.draft);
      const w = textWidth(word) * (13 / 14) + 20;
      // A typed or picked repeat leaves from where it was; a pasted one turns up, in its turn, where it would have gone.
      const from =
        "pick" in how
          ? {
              x: how.pick.x - 10,
              y: how.pick.y + how.pick.h / 2 - CHIP_H / 2,
              w,
              h: CHIP_H,
            }
          : "paste" in how
            ? { after: d.after, w }
            : how.type
              ? {
                  x: how.type.x - 10 + dx,
                  y: how.type.y + how.type.h / 2 - CHIP_H / 2 + dy,
                  w,
                  h: CHIP_H,
                }
              : { x: dx, y: dy, w, h: CHIP_H };
      flights.push({
        kind: "fly",
        text: word,
        from,
        twin: d.twin,
        delay: delayOf(d.index),
      });
    });

    stage({
      enter,
      shake,
      flights,
      skipInput: "type" in how && !!how.type,
      shakeField: result.overflow > 0,
    });
    if (result.added.length) commit(result.next);
    // The list stays closed until you type again.
    setDismissed(true);
    lookUp(result.added);

    if (result.overflow) flash(limitMessage, "warn");
    else if (result.dups.length)
      flash(
        result.dups.length === 1
          ? `${display(result.dups[0].draft)} is already here`
          : `${result.dups.length} were already here`,
        "muted",
      );
    const invalid = result.added.filter((t) => t.error).length;
    say(
      [
        result.added.length === 1
          ? `Added ${display(result.added[0])}.`
          : result.added.length
            ? `Added ${result.added.length}.`
            : "",
        invalid ? `${invalid} not valid.` : "",
        result.dups.length ? `${result.dups.length} already added.` : "",
        result.overflow ? `${limitMessage}.` : "",
      ]
        .filter(Boolean)
        .join(" "),
    );
  };

  /** The typed text becomes a chip where it stands. */
  const commitText = (raw = text) => {
    const words = raw.split(separators).filter((w) => w.trim());
    if (!words.length) return;
    if (words.length > 1) {
      const point = caretPoint();
      setText("");
      add(
        words.map((w) => ({ value: w })),
        { paste: point },
      );
      return;
    }
    const lead = raw.length - raw.trimStart().length;
    const box = raw === text ? textBox(lead, words[0].trim()) : null;
    setText("");
    add([{ value: words[0] }], { type: box });
  };

  const pasteText = (pasted: string, start: number, end: number) => {
    const combined = text.slice(0, start) + pasted + text.slice(end);
    const point = caretPoint();
    setText("");
    add(
      combined.split(separators).map((w) => ({ value: w })),
      { paste: point },
    );
  };

  const ghostOf = (
    t: TagInputTag,
    kind: Ghost["kind"],
    snap: TokenSnapshot,
  ): Ghost | null => {
    const was = snap.chips.get(t.id);
    if (!was) return null;
    const { dx, dy } = rootOffset();
    const named = !!t.label && t.label !== t.value;
    return {
      key: ++ghostKey.current,
      kind,
      text: display(t),
      box: shift(was.screen, dx, dy),
      inner: shift(was.screenLabel, dx, dy),
      error: !!t.error,
      avatar:
        !t.error && (t.image || named)
          ? { image: t.image, name: display(t) }
          : undefined,
    };
  };

  const remove = (id: string, focus?: "input" | string) => {
    const tag = tagsRef.current.find((t) => t.id === id);
    const list = listRef.current;
    if (!tag || !list || disabled) return;
    const before = snapshotTokens(list);
    const ghost = ghostOf(tag, "leave", before);
    stage({ ghosts: ghost ? [ghost] : [], focus }, before);
    commit(tagsRef.current.filter((t) => t.id !== id));
    say(`Removed ${display(tag)}.`);
  };

  /** Back to text: the shell drops away and its letters become what you're typing. */
  const edit = (id: string) => {
    const tag = tagsRef.current.find((t) => t.id === id);
    const list = listRef.current;
    if (!tag || !list || disabled) return;
    const before = snapshotTokens(list);
    const ghost = ghostOf(tag, "unspool", before);
    // Anything already typed becomes chips first.
    const typed = plan(
      text
        .split(separators)
        .filter((w) => w.trim())
        .map((w) => ({ value: w })),
      tagsRef.current.filter((t) => t.id !== id),
    );
    stage(
      {
        ghosts: ghost ? [ghost] : [],
        skipInput: true,
        inputFrom: ghost?.inner
          ? { box: ghost.inner, fade: display(tag) !== tag.value }
          : undefined,
        focus: "input",
      },
      before,
    );
    commit(typed.next);
    lookUp(typed.added);
    setText(tag.value);
    setDismissed(true);
    say(`Editing ${tag.value}.`);
  };

  const clear = () => {
    const list = listRef.current;
    if (!list || !tagsRef.current.length) return;
    const before = snapshotTokens(list);
    stage(
      {
        ghosts: tagsRef.current.flatMap(
          (t) => ghostOf(t, "leave", before) ?? [],
        ),
      },
      before,
    );
    commit([]);
    say("Cleared.");
  };

  React.useImperativeHandle(ref, () => ({
    paste: (s: string) => pasteText(s, text.length, text.length),
    focus: () => inputRef.current?.focus(),
    clear,
  }));

  // ── Height and collapse ────────────────────────────────
  const measure = React.useCallback(() => {
    const list = listRef.current;
    const wrap = wrapRef.current;
    if (!list || !wrap) return;
    let next: typeof cut = null;
    if (collapsedRef.current && collapse !== undefined) {
      const chips = Array.from(
        list.querySelectorAll<HTMLElement>("[data-token]"),
      );
      const lines = [...new Set(chips.map((c) => c.offsetTop))].sort(
        (a, b) => a - b,
      );
      if (lines.length > collapse) {
        const last = lines[Math.max(0, collapse - 1)];
        const limit =
          list.clientWidth - PAD - (pillRef.current?.offsetWidth ?? 40) - GAP;
        const hidden: string[] = [];
        let x = PAD;
        for (const c of chips) {
          if (c.offsetTop < last) continue;
          if (
            c.offsetTop === last &&
            !hidden.length &&
            c.offsetLeft + c.offsetWidth <= limit
          )
            x = c.offsetLeft + c.offsetWidth + GAP;
          else hidden.push(c.dataset.token!);
        }
        next = { hidden, x, y: last, height: last + CHIP_H + PAD };
      }
    }
    setCut((c) =>
      c === next ||
      (c &&
        next &&
        c.x === next.x &&
        c.y === next.y &&
        c.height === next.height &&
        c.hidden.join() === next.hidden.join())
        ? c
        : next,
    );
    const target = `${next ? next.height : list.offsetHeight}px`;
    if (wrap.style.height !== target) {
      wrap.style.transition =
        wrap.dataset.ready && !reduced ? `height 420ms ${EASE}` : "none";
      wrap.style.height = target;
      wrap.dataset.ready = "1";
    }
  }, [collapse, reduced]);

  // ── Playing a change ───────────────────────────────────
  // TextMorph commits a label's new letters one render after it gets the text, so measure one render later (still before
  // paint): otherwise a chip that resolves to a shorter name would change width after the glide was measured.
  const [playTick, setPlayTick] = React.useState(0);
  React.useLayoutEffect(() => {
    if (pending.current) setPlayTick((t) => t + 1);
  }, [tick]);
  React.useLayoutEffect(() => {
    const p = pending.current;
    const list = listRef.current;
    if (!p || !list) return;
    pending.current = null;
    const after = p.before
      ? playTokens(list, p.before, {
          enter: p.enter,
          skipInput: p.skipInput,
          reduced,
        })
      : snapshotTokens(list);
    const chip = (id: string) =>
      list.querySelector<HTMLElement>(`[data-token="${CSS.escape(id)}"]`);
    p.shake.forEach((s) => shakeToken(chip(s.id), reduced, s.delay));
    if (p.shakeField) shakeToken(fieldRef.current, reduced);

    if (!reduced) {
      const { dx, dy } = rootOffset();
      const flights: Ghost[] = p.flights.flatMap((f) => {
        const twin = after.chips.get(f.twin);
        if (!twin) return [];
        let box: TokenBox;
        if ("after" in f.from) {
          // Where it would have landed: after the chip before it, or at the start of the next line if it doesn't fit.
          const prev = f.from.after
            ? after.chips.get(f.from.after)?.box
            : undefined;
          let x = prev ? prev.x + prev.w + GAP : PAD;
          let y = prev ? prev.y : PAD;
          if (x + f.from.w > list.clientWidth - PAD) {
            x = PAD;
            y += CHIP_H + PAD;
          }
          box = { x: x + dx, y: y + dy, w: f.from.w, h: CHIP_H };
        } else box = f.from;
        return [
          {
            key: ++ghostKey.current,
            kind: f.kind,
            text: f.text,
            box,
            to: shift(f.kind === "carry" ? twin.label : twin.box, dx, dy),
            twin: f.twin,
            delay: f.delay,
            appear: "after" in f.from,
          },
        ];
      });
      if (p.ghosts.length || flights.length)
        setGhosts((g) => [...g, ...p.ghosts, ...flights]);

      const input = inputRef.current;
      if (p.inputFrom && input) {
        const i = input.getBoundingClientRect();
        const root = rootRef.current!.getBoundingClientRect();
        const from = p.inputFrom.box;
        input.parentElement!.animate(
          [
            {
              transform: `translate(${from.x - (i.left - root.left)}px, ${from.y + from.h / 2 - (i.top - root.top + i.height / 2)}px)`,
            },
            { transform: "none" },
          ],
          { duration: 440, easing: EASE },
        );
        if (p.inputFrom.fade)
          input.animate(
            [
              { opacity: 0, filter: "blur(4px)" },
              { opacity: 1, filter: "blur(0px)" },
            ],
            { duration: 360, delay: 80, easing: EASE, fill: "backwards" },
          );
      }
    }

    const input = inputRef.current;
    if (p.focus === "input" && input) {
      quietFocus.current = document.activeElement !== input;
      input.focus({ preventScroll: true });
      const end = input.value.length;
      input.setSelectionRange(end, end);
    } else if (p.focus) chip(p.focus)?.focus({ preventScroll: true });
    // Widths settle here (after TextMorph), so the folded count is measured again too.
    measure();
  }, [playTick]);

  const ghostDone = React.useCallback(
    (ghost: Ghost) => {
      setGhosts((g) => g.filter((x) => x.key !== ghost.key));
      if (ghost.kind === "fly" && ghost.twin)
        pulseToken(
          listRef.current?.querySelector<HTMLElement>(
            `[data-token="${CSS.escape(ghost.twin)}"]`,
          ),
          reduced,
        );
    },
    [reduced],
  );

  React.useLayoutEffect(() => {
    measure();
  }, [measure, collapsed, tags, resolving]);

  React.useEffect(() => {
    const list = listRef.current;
    if (!list) return;
    const observer = new ResizeObserver(() => measure());
    observer.observe(list);
    return () => observer.disconnect();
  }, [measure]);

  // ── Suggestions ────────────────────────────────────────
  React.useEffect(() => {
    if (typeof suggestions !== "function" || !inputFocus) return;
    let live = true;
    const q = text.trim();
    Promise.resolve(suggestions(q)).then((found) => {
      if (live) {
        const taken = new Set(tags.map((t) => t.value));
        const keep = (res: TagInputSuggestion[]) =>
          res.filter((s) => !taken.has(normalize(s.value))).slice(0, 6);
        setAsyncOptions(keep(found));
      }
    });
    return () => {
      live = false;
    };
  }, [text, tags, suggestions, inputFocus, normalize]);

  const options = React.useMemo(() => {
    if (!suggestions || !inputFocus) return [];
    if (typeof suggestions === "function") return asyncOptions;
    const q = text.trim().toLowerCase();
    const taken = new Set(tags.map((t) => t.value));
    const keep = (found: TagInputSuggestion[]) =>
      found.filter((s) => !taken.has(normalize(s.value))).slice(0, 6);
    return keep(
      q
        ? suggestions.filter((s) =>
            [s.value, s.label, s.description].some((f) =>
              f?.toLowerCase().includes(q),
            ),
          )
        : suggestions,
    );
  }, [suggestions, inputFocus, asyncOptions, text, tags, normalize]);

  const query = text.trim();
  const exact = options.some(
    (o) =>
      normalize(o.value) === normalize(query) ||
      o.label?.toLowerCase() === query.toLowerCase(),
  );
  const rows = React.useMemo<Row[]>(
    () => [
      ...options,
      ...(createLabel && query && !exact
        ? [{ value: query, label: createLabel(query), create: true }]
        : []),
    ],
    [options, createLabel, query, exact],
  );
  const open =
    !!suggestions && inputFocus && !dismissed && rows.length > 0 && !disabled;
  const activeRow = open ? Math.min(active, rows.length - 1) : -1;
  // While the list folds away it keeps the rows it had, rather than flashing what an empty query would match.
  const [keptRows, setKeptRows] = React.useState(rows);
  if (open && keptRows !== rows) {
    setKeptRows(rows);
  }
  const shownRows = open ? rows : keptRows;

  // The first match is ready for Enter while you type; nothing is while the field is empty.
  const [prevQueryKey, setPrevQueryKey] = React.useState(
    () => `${text}:${options.length}`,
  );
  const queryKey = `${text}:${options.length}`;
  if (queryKey !== prevQueryKey) {
    setPrevQueryKey(queryKey);
    setActive(text.trim() ? 0 : -1);
  }

  const pick = (row: Row, index: number) => {
    setDismissed(true);
    if (row.create) return commitText(row.value);
    const label = rowRefs.current[index]
      ?.querySelector("[data-option-label]")
      ?.getBoundingClientRect();
    const root = rootRef.current!.getBoundingClientRect();
    const from = label
      ? {
          x: label.left - root.left,
          y: label.top - root.top,
          w: label.width,
          h: label.height,
        }
      : { x: 0, y: 0, w: 1, h: 18 };
    setText("");
    add([{ value: row.value, label: row.label, image: row.image }], {
      pick: from,
    });
  };

  // The highlight glides between rows; its first placement doesn't.
  const [mark, setMark] = React.useState({
    y: 0,
    h: 0,
    on: false,
    slide: false,
  });
  React.useLayoutEffect(() => {
    const el = rowRefs.current[activeRow];
    setMark((m) => {
      if (!el) return m.on ? { ...m, on: false, slide: false } : m;
      const next = {
        y: el.offsetTop,
        h: el.offsetHeight,
        on: true,
        slide: m.on,
      };
      return m.y === next.y &&
        m.h === next.h &&
        m.on === next.on &&
        m.slide === next.slide
        ? m
        : next;
    });
  }, [activeRow, rows.length, open]);
  React.useEffect(() => {
    if (activeRow >= 0)
      rowRefs.current[activeRow]?.scrollIntoView({ block: "nearest" });
  }, [activeRow]);

  // ── Keys ───────────────────────────────────────────────
  const ids = tags.map((t) => t.id);
  const focusChip = (id: string | undefined) => {
    if (!id) return inputRef.current?.focus();
    listRef.current
      ?.querySelector<HTMLElement>(`[data-token="${CSS.escape(id)}"]`)
      ?.focus();
  };

  const onInputKey = (e: React.KeyboardEvent<HTMLInputElement>) => {
    const input = e.currentTarget;
    if (open && (e.key === "ArrowDown" || e.key === "ArrowUp")) {
      e.preventDefault();
      const n = rows.length;
      setActive((a) =>
        e.key === "ArrowDown" ? (a + 1) % n : a <= 0 ? n - 1 : a - 1,
      );
    } else if (e.key === "ArrowDown" && suggestions && dismissed) {
      e.preventDefault();
      setDismissed(false);
    } else if (e.key === "Enter") {
      if (open && activeRow >= 0) {
        e.preventDefault();
        pick(rows[activeRow], activeRow);
      } else if (text.trim()) {
        e.preventDefault();
        commitText();
      }
    } else if (e.key === "Tab" && !e.shiftKey && text.trim()) {
      commitText();
    } else if (e.key === "Escape" && open) {
      e.preventDefault();
      setDismissed(true);
    } else if (
      (e.key === "Backspace" || e.key === "ArrowLeft") &&
      input.selectionStart === 0 &&
      input.selectionEnd === 0 &&
      ids.length
    ) {
      e.preventDefault();
      focusChip(ids[ids.length - 1]);
    }
  };

  const onChipKey = (e: React.KeyboardEvent<HTMLElement>, id: string) => {
    const i = ids.indexOf(id);
    const keys: Record<string, () => void> = {
      ArrowLeft: () => focusChip(ids[Math.max(0, i - 1)]),
      ArrowRight: () => focusChip(ids[i + 1]),
      Home: () => focusChip(ids[0]),
      End: () => focusChip(undefined),
      Escape: () => focusChip(undefined),
      Backspace: () => edit(id),
      Enter: () => edit(id),
      Delete: () => remove(id, ids[i + 1] ?? "input"),
    };
    const run = keys[e.key];
    if (!run) return;
    e.preventDefault();
    run();
  };

  const onType = (next: string) => {
    if (!separators.test(next)) {
      setDismissed(false);
      return setText(next);
    }
    const words = next.split(separators);
    const rest = words.pop() ?? "";
    const done = words.filter((w) => w.trim());
    if (done.length === 1) {
      const lead = next.length - next.trimStart().length;
      const box = textBox(lead, done[0].trim());
      setText(rest);
      add([{ value: done[0] }], { type: box });
    } else if (done.length > 1) {
      const point = caretPoint();
      setText(rest);
      add(
        done.map((w) => ({ value: w })),
        { paste: point },
      );
    } else setText(rest);
  };

  // ── Render ─────────────────────────────────────────────
  const invalid = tags.find((t) => t.error);
  const line =
    notice ??
    (invalid
      ? { text: invalid.error!, tone: "error" as const }
      : hint
        ? { text: hint, tone: "muted" as const }
        : null);
  const lineId = `${uid}-line`;
  const listId = `${uid}-options`;
  const hidden = new Set(cut?.hidden ?? []);
  const tone =
    line?.tone === "error"
      ? "text-red-600 dark:text-red-400"
      : line?.tone === "warn"
        ? "text-amber-700 dark:text-amber-400"
        : "text-muted-foreground";

  return (
    <div
      ref={rootRef}
      className={`relative w-full text-foreground ${className}`}
      onFocus={() => setWithin(true)}
      onBlur={(e) => {
        const root = e.currentTarget;
        // A chip that's removed while focused takes focus with it for a moment; look again once things settle.
        requestAnimationFrame(() => {
          if (root.contains(document.activeElement)) return;
          setWithin(false);
          setSelected(null);
        });
      }}
      {...props}
    >
      <span
        ref={mirrorRef}
        aria-hidden="true"
        className="pointer-events-none invisible absolute left-0 top-0 whitespace-pre text-[14px] [@media(pointer:coarse)]:text-[16px]"
      />

      <div className="relative">
        <div
          ref={fieldRef}
          onMouseDown={(e) => {
            if (
              disabled ||
              (e.target as HTMLElement).closest("[data-token], button, input")
            )
              return;
            e.preventDefault();
            inputRef.current?.focus();
          }}
          className={`cursor-text rounded-[19px] border bg-background transition-[border-color,opacity] duration-200 ${disabled ? "cursor-default opacity-60" : ""}`}
          style={{
            borderColor: inputFocus
              ? "color-mix(in oklab, var(--ring) 55%, var(--border))"
              : "var(--border)",
          }}
        >
          {/* clip, not hidden: a hidden box can still be scrolled, and focusing the input would scroll the chips away. */}
          <div ref={wrapRef} className="overflow-clip">
            <div
              ref={listRef}
              className="relative flex flex-wrap items-center gap-x-1.5"
              style={{ padding: PAD, rowGap: PAD }}
            >
              <div role="list" aria-label={label} className="contents">
                {tags.map((t, i) => {
                  const busy = resolving.has(t.id);
                  const shown = display(t);
                  const named = !!t.label && t.label !== t.value;
                  const slot = busy || !!t.error || !!t.image || named;
                  const gone = hidden.has(t.id);
                  return (
                    <span
                      key={t.id}
                      data-token={t.id}
                      role="listitem"
                      tabIndex={-1}
                      aria-label={`${shown}${named ? `, ${t.value}` : ""}${t.error ? `, ${t.error}` : ""}${busy ? ", looking up" : ""}`}
                      aria-describedby={`${uid}-keys`}
                      title={shown.length > LONG ? shown : undefined}
                      onFocus={() => setSelected(t.id)}
                      onBlur={() => setSelected((s) => (s === t.id ? null : s))}
                      onKeyDown={(e) => onChipKey(e, t.id)}
                      onMouseDown={() => {
                        wasSelected.current = selected === t.id;
                      }}
                      onClick={(e) => {
                        if (
                          wasSelected.current &&
                          !(e.target as HTMLElement).closest("button")
                        )
                          edit(t.id);
                      }}
                      className={`relative inline-flex h-7 max-w-full shrink-0 cursor-default select-none items-center rounded-full text-[13px] outline-none will-change-transform ${
                        t.error
                          ? "text-red-600 dark:text-red-400"
                          : "text-foreground"
                      }`}
                      style={{
                        opacity: gone ? 0 : 1,
                        filter: gone ? "blur(3px)" : "none",
                        pointerEvents: gone ? "none" : undefined,
                        transition: reduced
                          ? "none"
                          : `opacity 260ms ${EASE} ${gone ? 0 : Math.min(i * 18, 180)}ms, filter 260ms ${EASE}`,
                      }}
                    >
                      <span
                        data-token-shell=""
                        aria-hidden="true"
                        className="absolute inset-y-0 left-0 w-full rounded-full transition-[background-color,box-shadow] duration-200"
                        style={shellStyle(!!t.error, selected === t.id)}
                      />
                      <span
                        data-token-extra=""
                        aria-hidden="true"
                        className="relative flex h-5 shrink-0 items-center justify-center"
                        style={{
                          width: slot ? 20 : 0,
                          marginLeft: slot ? 4 : 0,
                        }}
                      >
                        <span
                          className="absolute inset-0 flex items-center justify-center"
                          style={swap(busy, reduced)}
                        >
                          <span
                            className={`size-3 rounded-full border-[1.5px] border-current border-t-transparent text-muted-foreground motion-reduce:animate-none ${busy ? "animate-spin" : ""}`}
                          />
                        </span>
                        <span
                          className="absolute inset-0 flex items-center justify-center"
                          style={swap(!busy && !!t.error, reduced)}
                        >
                          <svg
                            viewBox="0 0 16 16"
                            className="size-3.5"
                            fill="none"
                          >
                            <circle
                              cx="8"
                              cy="8"
                              r="6.25"
                              stroke="currentColor"
                              strokeWidth="1.5"
                            />
                            <path
                              d="M8 4.75v3.75"
                              stroke="currentColor"
                              strokeWidth="1.75"
                              strokeLinecap="round"
                            />
                            <circle cx="8" cy="11" r="1" fill="currentColor" />
                          </svg>
                        </span>
                        <span
                          className="absolute inset-0 flex items-center justify-center"
                          style={swap(
                            !busy && !t.error && (!!t.image || named),
                            reduced,
                          )}
                        >
                          {(t.image || named) && (
                            <Avatar image={t.image} name={shown} size={20} />
                          )}
                        </span>
                      </span>
                      {/* Only a long label clips (inside its own box, which is what glides): a short one never cuts the letters
                          of the address it's morphing from. */}
                      <span
                        data-token-label=""
                        className={`relative whitespace-nowrap py-1 ${shown.length > LONG ? "min-w-0 max-w-[11rem] overflow-hidden" : ""}`}
                        style={{ marginLeft: slot ? 6 : 10, marginRight: 2 }}
                      >
                        <TextMorph animateWidth={false} aria-hidden="true">
                          {shown}
                        </TextMorph>
                      </span>
                      <button
                        type="button"
                        data-token-extra=""
                        tabIndex={-1}
                        aria-label={`Remove ${shown}`}
                        disabled={disabled}
                        onMouseDown={(e) => e.preventDefault()}
                        onClick={() =>
                          remove(
                            t.id,
                            rootRef.current?.contains(document.activeElement)
                              ? "input"
                              : undefined,
                          )
                        }
                        className="relative mr-1 flex size-5 shrink-0 cursor-pointer items-center justify-center rounded-full text-muted-foreground transition-colors hover:bg-accent hover:text-foreground disabled:cursor-default"
                      >
                        <Cross />
                      </button>
                    </span>
                  );
                })}
              </div>

              <span
                data-token-input=""
                className="flex h-7 items-center pl-1.5"
                style={{
                  flex: collapsed ? "0 0 0px" : "1 1 7rem",
                  minWidth: collapsed ? 0 : "7rem",
                }}
              >
                <input
                  ref={inputRef}
                  value={text}
                  disabled={disabled}
                  placeholder={tags.length ? undefined : placeholder}
                  role="combobox"
                  aria-label={label}
                  aria-expanded={open}
                  aria-controls={open ? listId : undefined}
                  aria-activedescendant={
                    activeRow >= 0 ? `${uid}-opt-${activeRow}` : undefined
                  }
                  aria-autocomplete={suggestions ? "list" : undefined}
                  aria-describedby={line ? lineId : undefined}
                  autoComplete="off"
                  spellCheck={false}
                  onFocus={() => {
                    setInputFocus(true);
                    if (!quietFocus.current) setDismissed(false);
                    quietFocus.current = false;
                  }}
                  onBlur={(e) => {
                    setInputFocus(false);
                    if (
                      !rootRef.current?.contains(
                        e.relatedTarget as Node | null,
                      ) &&
                      text.trim()
                    )
                      commitText();
                  }}
                  onChange={(e) => onType(e.target.value)}
                  onPaste={(e) => {
                    const pasted = e.clipboardData.getData("text");
                    if (!separators.test(pasted)) return;
                    e.preventDefault();
                    pasteText(
                      pasted,
                      e.currentTarget.selectionStart ?? text.length,
                      e.currentTarget.selectionEnd ?? text.length,
                    );
                  }}
                  onKeyDown={onInputKey}
                  className="h-7 w-full min-w-0 bg-transparent text-[14px] outline-none placeholder:text-muted-foreground disabled:cursor-default [@media(pointer:coarse)]:text-[16px]"
                />
              </span>

              {/* What folded away, counted at the end of the last line that shows. */}
              <span
                ref={pillRef}
                aria-hidden="true"
                onMouseDown={(e) => {
                  e.preventDefault();
                  inputRef.current?.focus();
                }}
                className="absolute left-0 top-0 inline-flex h-7 cursor-pointer items-center rounded-full px-2.5 text-[12.5px] tabular-nums text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)]"
                style={{
                  transform: `translate(${cut?.x ?? PAD}px, ${cut?.y ?? PAD}px)`,
                  opacity: cut ? 1 : 0,
                  filter: cut ? "none" : "blur(3px)",
                  pointerEvents: cut ? undefined : "none",
                  transition: reduced
                    ? "none"
                    : `opacity 260ms ${EASE} ${cut ? 120 : 0}ms, filter 260ms ${EASE}`,
                }}
              >
                +<NumberRoll value={cut?.hidden.length ?? 0} duration={600} />
              </span>
            </div>
          </div>
        </div>

        {/* Suggestions open clear of the field and unfold from its edge. */}
        <div
          className="absolute inset-x-0 top-full z-20 pt-1.5"
          style={{
            clipPath: open
              ? "inset(0px -2px -2px -2px)"
              : "inset(0px -2px 100% -2px)",
            opacity: open ? 1 : 0,
            visibility: open ? "visible" : "hidden",
            transition: reduced
              ? "none"
              : `clip-path 340ms ${EASE}, opacity 200ms ${EASE}, visibility 0s linear ${open ? "0s" : "340ms"}`,
          }}
        >
          <div
            role="listbox"
            id={listId}
            aria-label={`${label}: suggestions`}
            onMouseDown={(e) => e.preventDefault()}
            className="relative max-h-64 overflow-auto rounded-[14px] border border-border bg-popover p-1 text-popover-foreground"
          >
            <span
              aria-hidden="true"
              className="absolute inset-x-1 top-0 rounded-[10px] bg-accent"
              style={{
                transform: `translateY(${mark.y}px)`,
                height: mark.h,
                opacity: mark.on ? 1 : 0,
                transition: reduced
                  ? "none"
                  : `${mark.slide ? `transform 260ms ${EASE}, height 260ms ${EASE}, ` : ""}opacity 160ms ${EASE}`,
              }}
            />
            {shownRows.map((row, i) => (
              <div
                key={`${row.create ? "create" : "row"}-${row.value}`}
                id={`${uid}-opt-${i}`}
                ref={(el) => {
                  rowRefs.current[i] = el;
                }}
                role="option"
                aria-selected={i === activeRow}
                onMouseMove={() => i !== activeRow && setActive(i)}
                onClick={() => pick(row, i)}
                className="relative flex min-h-10 cursor-pointer items-center gap-2.5 rounded-[10px] px-2 py-1.5"
              >
                {row.create ? (
                  <span className="flex size-6 shrink-0 items-center justify-center rounded-full text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)]">
                    <svg
                      viewBox="0 0 12 12"
                      className="size-3"
                      fill="none"
                      aria-hidden="true"
                    >
                      <path
                        d="M6 2.5v7M2.5 6h7"
                        stroke="currentColor"
                        strokeWidth="1.4"
                        strokeLinecap="round"
                      />
                    </svg>
                  </span>
                ) : (
                  (row.image || row.label) && (
                    <Avatar image={row.image} name={display(row)} size={24} />
                  )
                )}
                <span className="flex min-w-0 flex-col">
                  <span className="truncate text-[13.5px] leading-tight">
                    <span data-option-label="">{display(row)}</span>
                  </span>
                  {!row.create &&
                    (row.description ||
                      (row.label && row.label !== row.value)) && (
                      <span className="truncate text-[12px] leading-tight text-muted-foreground">
                        {row.description ?? row.value}
                      </span>
                    )}
                </span>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Hint, error or notice: one line that morphs, and folds away when there's nothing to say. */}
      <div
        className="grid transition-[grid-template-rows] duration-300"
        style={{
          gridTemplateRows: line ? "1fr" : "0fr",
          transitionTimingFunction: EASE,
        }}
      >
        <div className="min-w-0 overflow-hidden">
          <p
            id={lineId}
            className={`pl-1 pt-2 text-[12.5px] transition-colors duration-300 ${tone}`}
          >
            <Line text={line?.text ?? ""} reduced={reduced} />
          </p>
        </div>
      </div>

      {/* Ghosts: chips that leave, fly into a twin, drop their shell, or carry a name in. */}
      <div
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 z-30"
      >
        {ghosts.map((g) => (
          <GhostChip key={g.key} ghost={g} onDone={ghostDone} />
        ))}
      </div>

      {name && (
        <input
          type="hidden"
          name={name}
          value={tags
            .filter((t) => !t.error)
            .map((t) => t.value)
            .join(",")}
        />
      )}
      <p id={`${uid}-keys`} className="sr-only">
        Backspace edits, Delete removes, arrow keys move between tags.
      </p>
      <p className="sr-only" role="status" aria-live="polite">
        {announce}
      </p>
    </div>
  );
}

"use client";

import * as React from "react";
import { AlertCircle, ChevronDown, FileCode2, RotateCcw } from "lucide-react";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * TASK LOG: what the agent did, task by task, as it does it
 *
 *   running   the task's title carries a sweep of light; its
 *             steps arrive one at a time on a thin line trail,
 *             each opening to its height and rising out of a
 *             light blur, the newest one shimmering
 *   done      the title morphs into the past tense ("Finding
 *             project files" becomes "Found project files") and
 *             the sweep stops; the steps can fold away
 *   error     the title turns red behind an alert, keeping the
 *             steps that ran
 *   rerun     once every task is settled, "Run again" folds in
 *
 * Files in a step sit in small chips; counts and outcomes trail
 * after in a quieter grey. Feed it the tasks you have so far.
 * ───────────────────────────────────────────────────────── */

export type TaskLogStatus = "running" | "done" | "error";

export interface TaskLogStep {
  id: string;
  /** What happened, e.g. "Read" or "Searching \"app/page.tsx\"". */
  text: string;
  /** A file it touched, shown as a chip after the text. */
  file?: string;
  /** A quieter outcome after it, e.g. "0 errors". */
  detail?: string;
}

export interface TaskLogTask {
  id: string;
  /** While it runs, e.g. "Finding project files". */
  title: string;
  /** Once it's done, e.g. "Found project files". Defaults to title. */
  doneTitle?: string;
  icon?: React.ReactNode;
  status: TaskLogStatus;
  steps: TaskLogStep[];
}

export interface TaskLogProps extends React.HTMLAttributes<HTMLDivElement> {
  tasks: TaskLogTask[];
  /** Shows "Run again" once every task is settled. */
  onRerun?: () => void;
  rerunLabel?: string;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
// A light that sweeps across the label: a moving mask, so it also reaches letters that are mid-morph.
const SHEEN =
  "text-foreground [mask-image:linear-gradient(90deg,rgb(0_0_0/0.45)_35%,#000_50%,rgb(0_0_0/0.45)_65%)] [mask-size:200%_100%] animate-[ui-sheen_1.4s_linear_infinite] motion-reduce:animate-none motion-reduce:[mask-image:none]";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Opens to its height and rises out of a blur the first time it appears (not when the log first renders). */
function Arrive({
  animate,
  reduced,
  children,
}: {
  animate: boolean;
  reduced: boolean;
  children: React.ReactNode;
}) {
  const [shown, setShown] = React.useState(!animate || reduced);
  React.useEffect(() => {
    if (shown) return;
    let inner = 0;
    const outer = requestAnimationFrame(
      () => (inner = requestAnimationFrame(() => setShown(true))),
    );
    return () => {
      cancelAnimationFrame(outer);
      cancelAnimationFrame(inner);
    };
  }, [shown]);
  return (
    <div
      className="grid"
      style={{
        gridTemplateRows: shown ? "1fr" : "0fr",
        opacity: shown ? 1 : 0,
        filter: shown ? "none" : "blur(4px)",
        transform: shown ? "none" : "translateY(4px)",
        transition: reduced
          ? "none"
          : `grid-template-rows 380ms ${EASE}, opacity 320ms ${EASE} 60ms, filter 320ms ${EASE} 60ms, transform 380ms ${EASE}`,
      }}
    >
      <div className="min-h-0 overflow-hidden">{children}</div>
    </div>
  );
}

function FileChip({ name }: { name: string }) {
  return (
    <span className="inline-flex h-5 max-w-full items-center gap-1 rounded-md bg-muted px-1.5 font-mono text-[11px] text-foreground/80">
      <FileCode2
        aria-hidden="true"
        className="size-3 shrink-0 text-muted-foreground"
      />
      <span className="truncate">{name}</span>
    </span>
  );
}

function Task({
  task,
  animate,
  mounted,
  reduced,
}: {
  task: TaskLogTask;
  animate: boolean;
  mounted: boolean;
  reduced: boolean;
}) {
  const [open, setOpen] = React.useState(true);
  const listId = React.useId();
  const running = task.status === "running";
  const failed = task.status === "error";
  const title = running ? task.title : (task.doneTitle ?? task.title);
  return (
    <li>
      <Arrive animate={animate} reduced={reduced}>
        <button
          type="button"
          aria-expanded={open}
          aria-controls={listId}
          onClick={() => setOpen((o) => !o)}
          className={`cursor-pointer group flex min-h-7 w-full items-center gap-2 rounded-md py-0.5 text-left text-[13px] ${FOCUS}`}
        >
          <span
            aria-hidden="true"
            className={`flex size-4 shrink-0 items-center justify-center [&_svg]:size-4 [&_svg]:stroke-[1.8] ${failed ? "text-red-500" : "text-muted-foreground"}`}
          >
            {failed ? <AlertCircle /> : task.icon}
          </span>
          <span
            className={`min-w-0 font-medium transition-colors duration-300 ${failed ? "text-red-600 dark:text-red-400" : running ? SHEEN : "text-foreground/80"}`}
          >
            <TextMorph>{title}</TextMorph>
          </span>
          <ChevronDown
            aria-hidden="true"
            className="ml-auto size-3.5 shrink-0 text-muted-foreground opacity-60 transition-opacity group-hover:opacity-100"
            style={{
              transform: open ? "rotate(180deg)" : "none",
              transition: reduced
                ? "none"
                : `transform 320ms ${EASE}, opacity 200ms`,
            }}
          />
        </button>
      </Arrive>
      <div
        id={listId}
        inert={!open}
        className="grid"
        style={{
          gridTemplateRows: open ? "1fr" : "0fr",
          opacity: open ? 1 : 0,
          transition: reduced
            ? "none"
            : `grid-template-rows 380ms ${EASE}, opacity ${open ? "280ms" : "140ms"} ${EASE}`,
        }}
      >
        <ul className="min-h-0 overflow-hidden pb-1 pl-[24px]">
          {task.steps.map((step, i) => {
            const last = i === task.steps.length - 1;
            const live = running && last;
            return (
              <li key={step.id} className="relative">
                <Arrive animate={mounted} reduced={reduced}>
                  {/* The trail: a thin line down from the task, branching to each step, the last one turning the corner. */}
                  <span
                    aria-hidden="true"
                    className="absolute -left-[16px] top-0 w-px bg-border"
                    style={last ? { height: 10 } : { bottom: 0 }}
                  />
                  <span
                    aria-hidden="true"
                    className={`absolute -left-[16px] top-[3px] h-[8px] w-[9px] border-b border-border ${last ? "rounded-bl-[5px] border-l" : ""}`}
                  />
                  <div className="flex min-h-[26px] flex-wrap items-center gap-x-1.5 gap-y-1 py-[3px] text-[12.5px] leading-5 text-muted-foreground">
                    <span className={live ? SHEEN : ""}>{step.text}</span>
                    {step.file && <FileChip name={step.file} />}
                    {step.detail && (
                      <span className="text-muted-foreground/70">
                        {step.detail}
                      </span>
                    )}
                  </div>
                </Arrive>
              </li>
            );
          })}
        </ul>
      </div>
    </li>
  );
}

export function TaskLog({
  tasks,
  onRerun,
  rerunLabel = "Run again",
  className = "",
  ...props
}: TaskLogProps) {
  const reduced = useReducedMotion();
  // Tasks and steps that exist on the first render just sit there; later ones arrive.
  const [mounted, setMounted] = React.useState(false);
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setMounted(true));
    return () => cancelAnimationFrame(frame);
  }, []);
  const settled =
    tasks.length > 0 && tasks.every((t) => t.status !== "running");
  const live = tasks.find((t) => t.status === "running");
  const lastStep = live?.steps[live.steps.length - 1];

  return (
    <div className={`w-full ${className}`} {...props}>
      <ol className="space-y-1">
        {tasks.map((t) => (
          <Task
            key={t.id}
            task={t}
            animate={mounted}
            mounted={mounted}
            reduced={reduced}
          />
        ))}
      </ol>

      {onRerun && (
        <div
          className="grid"
          style={{
            gridTemplateRows: settled ? "1fr" : "0fr",
            opacity: settled ? 1 : 0,
            transition: reduced
              ? "none"
              : `grid-template-rows 380ms ${EASE}, opacity 300ms ${EASE}`,
          }}
        >
          <div className="min-h-0 overflow-hidden">
            <button
              type="button"
              inert={!settled}
              onClick={onRerun}
              className={`cursor-pointer mt-2.5 inline-flex h-8 items-center gap-1.5 rounded-lg px-3 text-[12.5px] font-medium text-foreground shadow-[inset_0_0_0_1px_var(--border)] transition-colors hover:bg-accent ${FOCUS}`}
            >
              <RotateCcw
                aria-hidden="true"
                className="size-3.5 text-muted-foreground"
              />
              {rerunLabel}
            </button>
          </div>
        </div>
      )}

      <p role="status" aria-live="polite" className="sr-only">
        {live
          ? `${live.title}${lastStep ? `: ${lastStep.text}${lastStep.file ? ` ${lastStep.file}` : ""}` : ""}`
          : settled
            ? "All tasks finished"
            : ""}
      </p>
    </div>
  );
}

"use client";

import * as React from "react";
import { AlertCircle, ArrowRight, CircleSlash, RotateCcw } from "lucide-react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * TASK PROGRESS: work that takes minutes, not seconds
 *
 *   running    phases fill left to right; the current one sweeps;
 *              the status line names the phase as it morphs from
 *              one to the next; timer and stats roll; Cancel
 *   done       the last bar fills, a check draws itself, "Finished
 *              in 4m 12s"; Cancel grows into "Open report"
 *   error      the failed phase fills red, the reason opens in,
 *              "Stopped at reading"; the button becomes Retry
 *   cancelled  stopped by the user; the button folds away
 *
 * The button and the status line are one surface each: they
 * change shape and wording instead of being swapped. For deep
 * research, long builds and batch jobs. Tell people they can
 * leave; the card is what they come back to.
 * ───────────────────────────────────────────────────────── */

export type TaskProgressStatus = "running" | "done" | "error" | "cancelled";

export interface TaskStat {
  label: string;
  /** Numbers roll when they change. */
  value: React.ReactNode;
}

export interface TaskProgressProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "title"
> {
  title: string;
  status: TaskProgressStatus;
  /** The stages, e.g. ["Searching", "Reading", "Writing"]. */
  phases: string[];
  /** Index of the current phase. */
  phase: number;
  /** Start time (ms); shows a live timer. */
  startedAt?: number;
  /** Total time (ms), if you know it once finished. */
  duration?: number;
  stats?: TaskStat[];
  /** A line under the progress, e.g. "You can close this tab. We'll keep going." */
  message?: string;
  onCancel?: () => void;
  onOpen?: () => void;
  openLabel?: string;
  errorText?: string;
  onRetry?: () => void;
}

const MORPH = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
// A light that sweeps across the label. A mask, not a text clip, so it reaches letters that are mid-morph.
const SHEEN =
  "text-foreground [mask-image:linear-gradient(90deg,rgb(0_0_0/0.45)_35%,#000_50%,rgb(0_0_0/0.45)_65%)] [mask-size:200%_100%] animate-[ui-sheen_1.4s_linear_infinite] motion-reduce:animate-none motion-reduce:[mask-image:none] motion-reduce:text-foreground/70";
const TWO_DIGITS = { minimumIntegerDigits: 2 };

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Icons trade places through a blur: the old one shrinks away as the new one grows in. */
const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 260ms ${MORPH}, transform 380ms ${MORPH}, filter 260ms ${MORPH}`,
});

function formatTime(ms: number) {
  const s = Math.max(0, Math.floor(ms / 1000));
  return s < 60
    ? `${s}s`
    : `${Math.floor(s / 60)}m ${String(s % 60).padStart(2, "0")}s`;
}

/** A piece of a line that opens out of nothing and folds back into it. */
function Reveal({
  show,
  reduced,
  className = "",
  children,
}: {
  show: boolean;
  reduced: boolean;
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <span
      aria-hidden={!show || undefined}
      className={`grid ${className}`}
      style={{
        gridTemplateColumns: show ? "1fr" : "0fr",
        opacity: show ? 1 : 0,
        filter: show ? "none" : "blur(3px)",
        transition: reduced
          ? "none"
          : `grid-template-columns 460ms ${MORPH}, opacity ${show ? "320ms" : "160ms"} ${MORPH}, filter 320ms ${MORPH}`,
      }}
    >
      <span className="min-w-0 whitespace-nowrap [clip-path:inset(-4px_-2px)]">
        {children}
      </span>
    </span>
  );
}

/** A block that opens to its height and folds back to nothing. */
function Fold({
  show,
  reduced,
  children,
}: {
  show: boolean;
  reduced: boolean;
  children: React.ReactNode;
}) {
  return (
    <div
      aria-hidden={!show || undefined}
      className="grid"
      style={{
        gridTemplateRows: show ? "1fr" : "0fr",
        opacity: show ? 1 : 0,
        transition: reduced
          ? "none"
          : `grid-template-rows 460ms ${MORPH}, opacity ${show ? "320ms" : "160ms"} ${MORPH}`,
      }}
    >
      <div className="min-h-0 overflow-hidden">{children}</div>
    </div>
  );
}

/** Seconds that roll up as they pass; minutes slide open at the first minute. */
function Elapsed({ ms, reduced }: { ms: number; reduced: boolean }) {
  const total = Math.max(0, Math.floor(ms / 1000));
  const minutes = Math.floor(total / 60);
  return (
    <span className="inline-flex items-baseline">
      <Reveal show={minutes > 0} reduced={reduced}>
        <NumberRoll value={minutes} suffix="m" duration={500} />
        &nbsp;
      </Reveal>
      <NumberRoll
        value={minutes ? total % 60 : total}
        format={minutes ? TWO_DIGITS : undefined}
        suffix="s"
        direction="up"
        duration={500}
      />
    </span>
  );
}

function DrawnCheck({ drawn, reduced }: { drawn: boolean; reduced: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="none" className="size-3.5">
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 420ms ${MORPH} 200ms`
              : "none",
        }}
      />
    </svg>
  );
}

export function TaskProgress({
  title,
  status,
  phases,
  phase,
  startedAt,
  duration,
  stats,
  message,
  onCancel,
  onOpen,
  openLabel = "Open result",
  errorText,
  onRetry,
  className = "",
  ...props
}: TaskProgressProps) {
  const reduced = useReducedMotion();
  const running = status === "running";
  const [now, setNow] = React.useState(startedAt ?? 0);
  const [endedAt, setEndedAt] = React.useState<number | undefined>(undefined);
  const cardRef = React.useRef<HTMLDivElement>(null);
  const actionRef = React.useRef<HTMLButtonElement>(null);

  const [seenStartedAt, setSeenStartedAt] = React.useState(startedAt);
  if (startedAt !== seenStartedAt) {
    setSeenStartedAt(startedAt);
    setNow(startedAt ?? 0);
  }

  if (running && endedAt !== undefined) setEndedAt(undefined);

  React.useEffect(() => {
    if (!running) {
      if (endedAt !== undefined) return;
      const frame = requestAnimationFrame(() => setEndedAt(Date.now()));
      return () => cancelAnimationFrame(frame);
    }
    if (startedAt === undefined) return;
    const initial = window.setTimeout(() => setNow(Date.now()), 0);
    const timer = window.setInterval(() => setNow(Date.now()), 1000);
    return () => {
      window.clearTimeout(initial);
      window.clearInterval(timer);
    };
  }, [running, startedAt, endedAt]);

  const elapsed =
    duration ??
    (startedAt === undefined
      ? undefined
      : (running ? now : (endedAt ?? now)) - startedAt);
  const current = Math.min(Math.max(phase, 0), phases.length - 1);

  // The one button: Cancel while it runs, Retry after a failure, the result once done.
  const action =
    running && onCancel
      ? { kind: "cancel", label: "Cancel", run: onCancel }
      : status === "error" && onRetry
        ? { kind: "retry", label: "Retry", run: onRetry }
        : status === "done" && onOpen
          ? { kind: "open", label: openLabel, run: onOpen }
          : null;
  const [lastAction, setLastAction] = React.useState(action);
  if (
    action &&
    (action.kind !== lastAction?.kind || action.label !== lastAction.label)
  )
    setLastAction(action);
  const shown = action ?? lastAction;
  const primary = action?.kind === "open";
  const hasAction = Boolean(action);

  // If the button folds away while focused (Cancel pressed), keep focus on the card instead of the page.
  React.useLayoutEffect(() => {
    if (!hasAction && document.activeElement === actionRef.current)
      cardRef.current?.focus({ preventScroll: true });
  }, [hasAction]);

  const statusLine = running
    ? phases[current]
    : status === "done"
      ? "Finished"
      : status === "error"
        ? `Stopped at ${phases[current].toLowerCase()}`
        : "Cancelled";
  const timeJoin = status === "done" ? "in" : "after";
  const showTime =
    (status === "done" || status === "cancelled") && elapsed !== undefined;
  const iconKey = status === "running" ? null : status;

  return (
    <div
      ref={cardRef}
      tabIndex={-1}
      className={`w-full rounded-xl border border-border bg-background p-4 outline-none ${className}`}
      {...props}
    >
      <div className="flex items-baseline justify-between gap-4">
        <p className="min-w-0 truncate text-[13.5px] font-medium text-foreground">
          {title}
        </p>
        {elapsed !== undefined && (
          <span
            aria-hidden="true"
            className="shrink-0 font-mono text-[11.5px] tabular-nums text-muted-foreground"
          >
            <Elapsed ms={elapsed} reduced={reduced} />
          </span>
        )}
      </div>

      {/* Each phase fills from the left when it's finished; the live one sweeps. */}
      <div className="mt-3.5 flex gap-1" aria-hidden="true">
        {phases.map((p, i) => {
          const complete = status === "done" || i < current;
          const failed = status === "error" && i === current;
          const live = running && i === current;
          return (
            <span
              key={p}
              className="relative h-1 flex-1 overflow-hidden rounded-full bg-border"
            >
              <span
                className={`absolute inset-0 origin-left rounded-full transition-colors duration-300 ${failed ? "bg-red-500" : "bg-foreground"}`}
                style={{
                  transform: complete || failed ? "none" : "scaleX(0)",
                  transition: reduced
                    ? "none"
                    : `transform 620ms ${MORPH}, background-color 300ms`,
                }}
              />
              <span
                className={`absolute inset-y-0 left-0 w-2/5 rounded-full bg-foreground/60 motion-reduce:hidden ${live ? "animate-[ui-scan_1.6s_cubic-bezier(0.45,0,0.55,1)_infinite]" : ""}`}
                style={{
                  opacity: live ? 1 : 0,
                  transition: reduced ? "none" : "opacity 300ms",
                }}
              />
            </span>
          );
        })}
      </div>

      <div aria-hidden="true" className="mt-2 flex gap-1 text-[11.5px]">
        {phases.map((p, i) => (
          <span
            key={p}
            className={`flex-1 truncate transition-colors duration-300 ${status === "error" && i === current ? "text-red-500" : running && i === current ? "text-foreground" : "text-muted-foreground"}`}
          >
            {p}
          </span>
        ))}
      </div>

      <p role="status" aria-live="polite" className="sr-only">
        {status === "done"
          ? `${title} finished${elapsed !== undefined ? ` in ${formatTime(elapsed)}` : ""}`
          : status === "error"
            ? `${title} failed. ${errorText ?? ""}`
            : status === "cancelled"
              ? `${title} cancelled`
              : `${phases[current]}`}
      </p>

      {stats && stats.length > 0 && (
        <p className="mt-3 flex flex-wrap gap-x-3 gap-y-1 text-[12px] text-muted-foreground">
          {stats.map((s) => (
            <span
              key={s.label}
              className="inline-flex items-baseline gap-[0.3em]"
            >
              <span className="font-mono tabular-nums text-foreground">
                {typeof s.value === "number" ? (
                  <NumberRoll value={s.value} duration={700} />
                ) : (
                  s.value
                )}
              </span>
              {s.label}
            </span>
          ))}
        </p>
      )}

      {message && (
        <Fold show={running} reduced={reduced}>
          <p className="pt-2 text-[12px] text-muted-foreground">{message}</p>
        </Fold>
      )}
      <Fold show={status === "error"} reduced={reduced}>
        <p className="pt-3 text-[12.5px] text-red-500">
          {errorText ?? "Something went wrong partway through."}
        </p>
      </Fold>

      <div className="mt-4 flex min-h-8 items-center justify-between gap-3">
        {/* One status line: it names the phase while it runs and becomes the outcome. */}
        <span
          aria-hidden="true"
          className="flex min-w-0 items-center text-[12px] text-muted-foreground"
        >
          <span
            className="relative flex h-3.5 shrink-0 items-center justify-center"
            style={{
              width: iconKey ? 14 : 0,
              marginRight: iconKey ? 6 : 0,
              transition: reduced
                ? "none"
                : `width 380ms ${MORPH}, margin 380ms ${MORPH}`,
            }}
          >
            <span
              className="absolute inset-0 flex items-center justify-center text-emerald-600 dark:text-emerald-400"
              style={swap(iconKey === "done", reduced)}
            >
              <DrawnCheck drawn={iconKey === "done"} reduced={reduced} />
            </span>
            <span
              className="absolute inset-0 flex items-center justify-center text-red-500"
              style={swap(iconKey === "error", reduced)}
            >
              <AlertCircle className="size-3.5" />
            </span>
            <span
              className="absolute inset-0 flex items-center justify-center"
              style={swap(iconKey === "cancelled", reduced)}
            >
              <CircleSlash className="size-3.5" />
            </span>
          </span>
          <span className={`truncate ${running ? SHEEN : ""}`}>
            <TextMorph>{statusLine}</TextMorph>
          </span>
          {elapsed !== undefined && (
            <Reveal show={showTime} reduced={reduced}>
              <span className="inline-flex items-baseline pl-[0.3em] tabular-nums">
                <TextMorph>{timeJoin}</TextMorph>
                &nbsp;
                <Elapsed ms={elapsed} reduced={reduced} />
              </span>
            </Reveal>
          )}
        </span>

        {shown && (
          <Reveal show={Boolean(action)} reduced={reduced} className="shrink-0">
            <span className="block p-0.5">
              <button
                ref={actionRef}
                type="button"
                inert={!action}
                onClick={() => action?.run()}
                className={`cursor-pointer inline-flex h-8 items-center rounded-lg px-3 text-[12.5px] font-medium transition-[background-color,color,box-shadow,transform] duration-300 active:scale-[0.97] ${FOCUS} ${
                  primary
                    ? "bg-primary text-primary-foreground hover:bg-primary/90"
                    : "text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent"
                }`}
              >
                <span
                  aria-hidden="true"
                  className="relative flex h-3 shrink-0 items-center justify-center overflow-hidden"
                  style={{
                    width: shown.kind === "retry" ? 12 : 0,
                    marginRight: shown.kind === "retry" ? 6 : 0,
                    transition: reduced
                      ? "none"
                      : `width 380ms ${MORPH}, margin 380ms ${MORPH}`,
                  }}
                >
                  <RotateCcw
                    className="size-3 shrink-0"
                    style={swap(shown.kind === "retry", reduced)}
                  />
                </span>
                <TextMorph>{shown.label}</TextMorph>
                <span
                  aria-hidden="true"
                  className="relative flex h-3.5 shrink-0 items-center justify-center overflow-hidden"
                  style={{
                    width: shown.kind === "open" ? 14 : 0,
                    marginLeft: shown.kind === "open" ? 6 : 0,
                    transition: reduced
                      ? "none"
                      : `width 380ms ${MORPH}, margin 380ms ${MORPH}`,
                  }}
                >
                  <ArrowRight
                    className="size-3.5 shrink-0"
                    style={swap(shown.kind === "open", reduced)}
                  />
                </span>
              </button>
            </span>
          </Reveal>
        )}
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { Mail, MailX, Trash2 } from "lucide-react";
import { ConfirmAction } from "./confirm-action";
import { NumberRoll } from "./number-roll";
import { RelativeTime, toTime, type DateLike } from "./relative-time";
import { StatusButton, type ActionStatus } from "./status-button";
import { TagInput, type TagInputProps, type TagInputTag } from "./tag-input";
import { RoleMenu, type TeamRole } from "./team-role-menu";
import { TextMorph } from "./text-morph";
import { useRowMotion } from "./use-row-motion";

/* ─────────────────────────────────────────────────────────
 * TEAM MEMBERS: Settings → Members, done properly
 *
 *   invite    addresses go into the invite field (paste a list,
 *             duplicates fly into their twins); "Invite 3" sends
 *             them, and each chip lifts out of the field and
 *             flies down onto its new row in the list
 *   seats     "4 of 5 seats" rolls as people come and go; the
 *             field takes no more than the seats that are left
 *   role      the role pill grows into the list of roles and
 *             folds back with the new one; a spinner rides in
 *             the pill while it saves, and a refusal morphs the
 *             old role back with a shake
 *   resend    pending invites count down "Resend in 0:28",
 *             then offer Resend, which says Sending and Sent
 *             and starts the clock again
 *   remove    the bin stretches into "Remove", a check draws,
 *             the row folds away and the rest glide up
 *
 * Members are plain records; every change is one async
 * function, so it works with Clerk, Better Auth, WorkOS or
 * your own table.
 * ───────────────────────────────────────────────────────── */

export type { TeamRole, DateLike };

export interface TeamMember {
  id: string;
  email: string;
  name?: string;
  image?: string;
  role: string;
  /** "invited" until they accept. */
  status?: "active" | "invited";
  /** When the invite was last sent; the resend clock runs from it. */
  invitedAt?: DateLike;
  lastActiveAt?: DateLike | null;
  /** The person looking at the page. */
  you?: boolean;
  /** Can't be changed or removed here, e.g. the owner. */
  locked?: boolean;
}

export interface TeamMembersProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "defaultValue" | "onChange"
> {
  value?: TeamMember[];
  defaultValue?: TeamMember[];
  onValueChange?: (members: TeamMember[]) => void;
  roles: TeamRole[];
  /** The role new invites start with; the second role by default. */
  inviteRole?: string;
  /** Seats on the plan. Members and pending invites both take one. */
  seats?: number;
  /** Sends invites. Return the new members (status "invited"); throw to keep the addresses and say why. */
  onInvite?: (emails: string[], role: string) => Promise<TeamMember[]>;
  /** Saves a role. Throw to put the old one back. */
  onRoleChange?: (
    member: TeamMember,
    role: string,
  ) => Promise<unknown> | unknown;
  /** Removes a member or cancels an invite. */
  onRemove?: (member: TeamMember) => Promise<unknown> | unknown;
  /** Sends an invite again. */
  onResend?: (member: TeamMember) => Promise<unknown> | unknown;
  /** Seconds before an invite can be sent again. */
  resendAfter?: number;
  /** People to suggest in the invite field (your directory). */
  suggestions?: TagInputProps["suggestions"];
  title?: string;
  description?: string;
}

type Actions = {
  role: (m: TeamMember, role: string) => void;
  remove: (m: TeamMember) => Promise<void>;
  resend: (m: TeamMember) => Promise<void>;
};

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const NONE: TeamMember[] = [];
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const SPLIT = /[\s,;]+/;
const lower = (v: string) => v.toLowerCase();
const validate = (v: string) =>
  EMAIL.test(v) ? null : `“${v}” isn’t an email address`;
const message = (e: unknown, fallback: string) =>
  e instanceof Error && e.message ? e.message : fallback;
const two = { minimumIntegerDigits: 2 };

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const initials = (m: TeamMember) =>
  (m.name ?? m.email)
    .split(/[\s@._-]+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((w) => w[0]!.toUpperCase())
    .join("");

function Avatar({ m }: { m: TeamMember }) {
  if (m.status === "invited")
    return (
      <span
        data-avatar=""
        className="grid size-8 shrink-0 place-items-center rounded-full border border-dashed border-border text-muted-foreground"
      >
        <Mail className="size-3.5" strokeWidth={1.75} aria-hidden="true" />
      </span>
    );
  if (m.image)
    return (
      <img
        data-avatar=""
        src={m.image}
        alt=""
        className="size-8 shrink-0 rounded-full object-cover shadow-[0_0_0_1px_var(--border)]"
      />
    );
  return (
    <span
      data-avatar=""
      aria-hidden="true"
      className="grid size-8 shrink-0 place-items-center rounded-full bg-muted text-[11px] font-medium text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)]"
    >
      {initials(m)}
    </span>
  );
}

/** A piece of a line that opens and closes sideways (a countdown after "Resend in"). */
function Reveal({
  open,
  reduced,
  children,
}: {
  open: boolean;
  reduced: boolean;
  children: React.ReactNode;
}) {
  return (
    <span
      aria-hidden={!open || undefined}
      className="inline-grid"
      style={{
        gridTemplateColumns: open ? "1fr" : "0fr",
        opacity: open ? 1 : 0,
        filter: open || reduced ? "none" : "blur(3px)",
        transition: reduced
          ? "none"
          : `grid-template-columns 380ms ${EASE}, opacity 260ms ${EASE}, filter 260ms ${EASE}`,
      }}
    >
      <span className="min-w-0 [clip-path:inset(-4px_0)]">{children}</span>
    </span>
  );
}

/** "Resend in 0:28", rolling down; then Resend → Sending → Sent, and the clock starts again. */
function Resend({
  since,
  after,
  reduced,
  onResend,
}: {
  since: number;
  after: number;
  reduced: boolean;
  onResend: () => Promise<void>;
}) {
  const [now, setNow] = React.useState<number | null>(null);
  const [status, setStatus] = React.useState<ActionStatus>("idle");
  const left = now === null ? 0 : Math.max(0, since + after * 1000 - now);
  const counting = now !== null && left > 0;
  React.useEffect(() => {
    const timer = window.setTimeout(() => setNow(Date.now()), 0);
    return () => window.clearTimeout(timer);
  }, [since]);
  React.useEffect(() => {
    if (!counting) return;
    const timer = window.setTimeout(
      () => setNow(Date.now()),
      1000 - (Date.now() % 1000) + 10,
    );
    return () => window.clearTimeout(timer);
  }, [counting, now]);
  React.useEffect(() => {
    if (status !== "success" && status !== "error") return;
    const timer = window.setTimeout(
      () => setStatus("idle"),
      status === "success" ? 1400 : 2400,
    );
    return () => window.clearTimeout(timer);
  }, [status]);

  const busy = status === "pending" || status === "success";
  const label =
    status === "pending"
      ? "Sending"
      : status === "success"
        ? "Sent"
        : status === "error"
          ? "Try again"
          : counting
            ? "Resend in"
            : "Resend";
  const s = Math.ceil(left / 1000);
  const ready = !counting && !busy;

  return (
    <button
      type="button"
      aria-disabled={!ready || undefined}
      aria-label={
        counting ? "Resend invite, available shortly" : "Resend invite"
      }
      onClick={async () => {
        if (!ready) return;
        setStatus("pending");
        try {
          await onResend();
          setStatus("success");
        } catch {
          setStatus("error");
        }
      }}
      className={`inline-flex cursor-pointer items-baseline rounded-sm whitespace-nowrap tabular-nums transition-colors duration-200 aria-disabled:cursor-default ${FOCUS} ${
        status === "error"
          ? "text-red-600 dark:text-red-400"
          : ready
            ? "font-medium text-foreground underline-offset-2 hover:underline"
            : ""
      }`}
    >
      <TextMorph>{label}</TextMorph>
      <Reveal open={counting && status === "idle"} reduced={reduced}>
        <span className="inline-flex items-baseline pl-[0.25em]">
          <NumberRoll value={Math.floor(s / 60)} direction="down" />:
          <NumberRoll value={s % 60} format={two} direction="down" />
        </span>
      </Reveal>
    </button>
  );
}

/** A refusal, lifted in over the line under the name and lifted out again. */
function Note({ text, reduced }: { text?: string; reduced: boolean }) {
  const [shown, setShown] = React.useState(text);
  if (text && text !== shown) setShown(text);
  return (
    <span
      aria-hidden="true"
      className="pointer-events-none absolute inset-x-0 top-0 truncate text-red-600 dark:text-red-400"
      style={{
        opacity: text ? 1 : 0,
        transform: text || reduced ? "none" : "translateY(-4px)",
        filter: text || reduced ? "none" : "blur(3px)",
        transition: reduced
          ? "none"
          : `opacity 260ms ${EASE} ${text ? 80 : 0}ms, transform 360ms ${EASE}, filter 260ms ${EASE}`,
      }}
    >
      {shown}
    </span>
  );
}

interface RowProps {
  m: TeamMember;
  roles: TeamRole[];
  saving: boolean;
  shake: number;
  /** Why the last change was refused; shown in place of the line under the name for a while. */
  note?: string;
  gone: boolean;
  canEdit: boolean;
  canRemove: boolean;
  canResend: boolean;
  resendAfter: number;
  reduced: boolean;
  act: React.RefObject<Actions>;
}

const MemberRow = React.memo(function MemberRow({
  m,
  roles,
  saving,
  shake,
  note,
  gone,
  canEdit,
  canRemove,
  canResend,
  resendAfter,
  reduced,
  act,
}: RowProps) {
  const invited = m.status === "invited";
  const display = m.name ?? m.email;
  const role = roles.find((r) => r.value === m.role)?.label ?? m.role;
  const removable = canRemove && !m.locked && !m.you;
  return (
    <li data-row-id={m.id} className="border-t border-border first:border-t-0">
      <div
        className="flex items-center gap-3 px-4 py-2.5 transition-opacity duration-300 @md:px-5"
        style={{ opacity: gone ? 0.5 : 1 }}
      >
        <Avatar m={m} />
        <div className="min-w-0 flex-1">
          <p className="flex min-w-0 items-center gap-1.5 text-[13.5px] font-medium tracking-[-0.01em]">
            <span data-name="" className="truncate">
              {display}
            </span>
            {m.you && (
              <span className="shrink-0 rounded-full px-1.5 text-[11px] font-normal text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)]">
                You
              </span>
            )}
          </p>
          <p className="relative mt-0.5 text-[11.5px] text-muted-foreground">
            <Note text={note} reduced={reduced} />
            <span
              className="flex min-w-0 items-baseline gap-x-1.5"
              style={{
                opacity: note ? 0 : 1,
                filter: note && !reduced ? "blur(3px)" : "none",
                transition: reduced
                  ? "none"
                  : `opacity 220ms ${EASE}, filter 220ms ${EASE}`,
              }}
            >
              {/* On a narrow card the name is enough; the address comes back when there's room. */}
              {m.name && (
                <span className="hidden min-w-0 truncate @md:inline">
                  {m.email}
                </span>
              )}
              {m.name && (invited || m.lastActiveAt) && (
                <span aria-hidden="true" className="hidden @md:inline">
                  ·
                </span>
              )}
              {invited ? (
                <>
                  <span className="shrink-0 @md:hidden">Invited</span>
                  <span className="hidden shrink-0 @md:inline">
                    {m.invitedAt ? (
                      <RelativeTime date={m.invitedAt} prefix="Invited" />
                    ) : (
                      "Invited"
                    )}
                  </span>
                  {canResend && (
                    <>
                      <span aria-hidden="true">·</span>
                      <Resend
                        since={m.invitedAt ? toTime(m.invitedAt) : 0}
                        after={resendAfter}
                        reduced={reduced}
                        onResend={() => act.current.resend(m)}
                      />
                    </>
                  )}
                </>
              ) : m.lastActiveAt ? (
                <RelativeTime
                  className="shrink-0"
                  date={m.lastActiveAt}
                  prefix="Active"
                />
              ) : null}
            </span>
          </p>
        </div>
        {canEdit && !m.locked ? (
          <RoleMenu
            roles={roles}
            value={m.role}
            onValueChange={(r) => act.current.role(m, r)}
            saving={saving}
            shake={shake}
            label={`Role for ${display}`}
          />
        ) : (
          <span className="shrink-0 px-2.5 text-[12px] text-muted-foreground">
            {role}
          </span>
        )}
        {canRemove && (
          <div className="-mr-1 flex min-w-7 shrink-0 justify-end">
            {removable && (
              <ConfirmAction
                icon={
                  invited ? (
                    <MailX strokeWidth={1.75} />
                  ) : (
                    <Trash2 strokeWidth={1.75} />
                  )
                }
                label={
                  invited ? `Cancel invite for ${display}` : `Remove ${display}`
                }
                labels={
                  invited
                    ? {
                        idle: "Cancel invite",
                        pending: "Cancelling",
                        success: "Cancelled",
                        error: "Try again",
                      }
                    : {
                        idle: "Remove",
                        pending: "Removing",
                        success: "Removed",
                        error: "Try again",
                      }
                }
                onConfirm={() => act.current.remove(m)}
              />
            )}
          </div>
        )}
      </div>
    </li>
  );
});

export function TeamMembers({
  value,
  defaultValue = NONE,
  onValueChange,
  roles,
  inviteRole,
  seats,
  onInvite,
  onRoleChange,
  onRemove,
  onResend,
  resendAfter = 30,
  suggestions,
  title = "Members",
  description = "People in this workspace and the invites waiting on them.",
  className = "",
  ...props
}: TeamMembersProps) {
  const reduced = useReducedMotion();
  const [inner, setInner] = React.useState(defaultValue);
  const members = value ?? inner;
  const [tags, setTags] = React.useState<TagInputTag[]>([]);
  const [role, setRole] = React.useState(
    () => inviteRole ?? roles[Math.min(1, roles.length - 1)]?.value ?? "",
  );
  const [sending, setSending] = React.useState<ActionStatus>("idle");
  const [inviteError, setInviteError] = React.useState<string | null>(null);
  const [saving, setSaving] = React.useState<Record<string, boolean>>({});
  const [shakes, setShakes] = React.useState<Record<string, number>>({});
  const [notes, setNotes] = React.useState<Record<string, string>>({});
  const [gone, setGone] = React.useState<string[]>([]);
  const [announce, setAnnounce] = React.useState("");
  const rootRef = React.useRef<HTMLDivElement>(null);
  const fieldRef = React.useRef<HTMLDivElement>(null);
  const listRef = React.useRef<HTMLUListElement>(null);
  const ghostRef = React.useRef<HTMLDivElement>(null);
  const flyRef = React.useRef<HTMLDivElement>(null);
  const flights = React.useRef(
    new Map<string, { rect: DOMRect; label: string }>(),
  );
  const latest = React.useRef(members);
  React.useLayoutEffect(() => {
    latest.current = members;
  });

  const commit = (next: TeamMember[]) => {
    if (value === undefined) setInner(next);
    onValueChange?.(next);
  };

  const used = members.length;
  const left = seats === undefined ? undefined : Math.max(0, seats - used);
  const valid = tags.filter((t) => !t.error);
  const ranks = React.useMemo(
    () => new Map(members.map((m, i) => [m.id, i])),
    [members],
  );
  useRowMotion(listRef, { reduced, ranks, ghosts: ghostRef });

  const act = React.useRef<Actions>(null!);
  React.useLayoutEffect(() => {
    act.current = {
      role: async (m, next) => {
        const prev = m.role;
        const name = m.name ?? m.email;
        const label = roles.find((r) => r.value === next)?.label ?? next;
        commit(
          latest.current.map((x) => (x.id === m.id ? { ...x, role: next } : x)),
        );
        setSaving((s) => ({ ...s, [m.id]: true }));
        try {
          await onRoleChange?.(m, next);
          setAnnounce(`${name} is now ${label}.`);
        } catch (e) {
          commit(
            latest.current.map((x) =>
              x.id === m.id ? { ...x, role: prev } : x,
            ),
          );
          setShakes((s) => ({ ...s, [m.id]: (s[m.id] ?? 0) + 1 }));
          const why = message(e, `${name}'s role couldn't be changed.`);
          setNotes((n) => ({ ...n, [m.id]: why }));
          setAnnounce(why);
          window.setTimeout(
            () =>
              setNotes((n) =>
                n[m.id] === why
                  ? Object.fromEntries(
                      Object.entries(n).filter(([k]) => k !== m.id),
                    )
                  : n,
              ),
            3600,
          );
        } finally {
          setSaving((s) =>
            Object.fromEntries(Object.entries(s).filter(([k]) => k !== m.id)),
          );
        }
      },
      remove: async (m) => {
        await onRemove?.(m);
        setGone((g) => [...g, m.id]);
        setAnnounce(
          m.status === "invited"
            ? `Invite for ${m.email} cancelled.`
            : `${m.name ?? m.email} removed.`,
        );
        // Long enough for the check to draw; then the row folds away.
        window.setTimeout(() => {
          commit(latest.current.filter((x) => x.id !== m.id));
          setGone((g) => g.filter((id) => id !== m.id));
        }, 700);
      },
      resend: async (m) => {
        await onResend?.(m);
        commit(
          latest.current.map((x) =>
            x.id === m.id ? { ...x, invitedAt: new Date() } : x,
          ),
        );
        setAnnounce(`Invite sent to ${m.email} again.`);
      },
    };
  });

  const invite = async () => {
    if (!onInvite || !valid.length || sending === "pending") return;
    setSending("pending");
    setInviteError(null);
    try {
      const added = await onInvite(
        valid.map((t) => t.value),
        role,
      );
      // Where each chip sits now, so its row can fly out of it.
      const at = new Map<string, { rect: DOMRect; label: string }>();
      for (const t of valid) {
        const el = fieldRef.current?.querySelector<HTMLElement>(
          `[data-token="${CSS.escape(t.id)}"]`,
        );
        if (el)
          at.set(t.value.toLowerCase(), {
            rect: el.getBoundingClientRect(),
            label: t.label ?? t.value,
          });
      }
      flights.current = at;
      commit([...added, ...latest.current]);
      setTags((ts) => ts.filter((t) => t.error));
      setSending("success");
      setAnnounce(
        `${added.length} ${added.length === 1 ? "invite" : "invites"} sent.`,
      );
    } catch (e) {
      setSending("error");
      setInviteError(message(e, "The invites couldn't be sent. Try again."));
    }
  };

  // New rows that came from chips: each chip's copy flies from the field onto its row's name.
  React.useLayoutEffect(() => {
    const queued = flights.current;
    if (!queued.size) return;
    flights.current = new Map();
    const root = rootRef.current;
    const layer = flyRef.current;
    const list = listRef.current;
    if (!root || !layer || !list || reduced) return;
    const box = root.getBoundingClientRect();
    let i = 0;
    for (const m of members) {
      const from = queued.get(m.email.toLowerCase());
      if (!from) continue;
      const row = list.querySelector<HTMLElement>(
        `[data-row-id="${CSS.escape(m.id)}"]`,
      );
      const name = row?.querySelector<HTMLElement>("[data-name]");
      const avatar = row?.querySelector<HTMLElement>("[data-avatar]");
      if (!row || !name) continue;
      const to = name.getBoundingClientRect();
      const copy = document.createElement("span");
      copy.textContent = from.label;
      copy.className =
        "absolute left-0 top-0 inline-flex h-7 items-center whitespace-nowrap rounded-full bg-background px-2.5 text-[13px] font-medium text-foreground shadow-[inset_0_0_0_1px_var(--border)] will-change-transform";
      layer.appendChild(copy);
      const x0 = from.rect.left - box.left;
      const y0 = from.rect.top - box.top + (from.rect.height - 28) / 2;
      const x1 = to.left - box.left - 10;
      const y1 = to.top - box.top + to.height / 2 - 14;
      const delay = i++ * 60;
      // Lift off, travel, then hand over to the row's own name: the copy blurs out as the name sharpens in.
      const flight = copy.animate(
        [
          {
            transform: `translate(${x0}px, ${y0}px)`,
            opacity: 1,
            filter: "blur(0px)",
            boxShadow: "inset 0 0 0 1px var(--border)",
            easing: "cubic-bezier(0.3,0,0.2,1)",
          },
          {
            transform: `translate(${x0}px, ${y0 - 6}px)`,
            opacity: 1,
            filter: "blur(0px)",
            offset: 0.14,
            easing: EASE,
          },
          {
            transform: `translate(${x1}px, ${y1}px)`,
            opacity: 1,
            filter: "blur(0px)",
            boxShadow: "inset 0 0 0 1px transparent",
            backgroundColor: "transparent",
            offset: 0.7,
            easing: "linear",
          },
          {
            transform: `translate(${x1}px, ${y1}px)`,
            opacity: 0,
            filter: "blur(4px)",
            boxShadow: "inset 0 0 0 1px transparent",
            backgroundColor: "transparent",
          },
        ],
        { duration: 680, delay, fill: "both" },
      );
      flight.onfinish = flight.oncancel = () => copy.remove();
      name.animate(
        [
          { opacity: 0, filter: "blur(4px)" },
          {
            opacity: 0,
            filter: "blur(4px)",
            offset: (delay + 680 * 0.66) / (delay + 680),
          },
          { opacity: 1, filter: "blur(0px)" },
        ],
        { duration: delay + 680, easing: "linear" },
      );
      avatar?.animate(
        [
          { opacity: 0, transform: "scale(0.6)", filter: "blur(3px)" },
          { opacity: 1, transform: "none", filter: "blur(0px)" },
        ],
        { duration: 420, delay: delay + 360, easing: EASE, fill: "backwards" },
      );
    }
  }, [members, reduced]);

  const count = valid.length;
  return (
    <div
      ref={rootRef}
      className={`@container relative w-full rounded-[22px] border border-border bg-background text-foreground ${className}`}
      {...props}
    >
      <div className="flex items-start justify-between gap-3 px-4 pt-4 pb-3.5 @md:px-5 @md:pt-5">
        <div className="min-w-0">
          <p className="flex items-baseline gap-2 text-[14px] font-medium tracking-[-0.01em]">
            {title}
            <span className="text-[12px] font-normal text-muted-foreground tabular-nums">
              <NumberRoll
                value={members.filter((m) => m.status !== "invited").length}
              />
            </span>
          </p>
          <p className="mt-0.5 text-[12px] text-muted-foreground">
            {description}
          </p>
        </div>
        {seats !== undefined && (
          <p
            className={`flex shrink-0 items-baseline whitespace-nowrap pt-0.5 text-[11.5px] tabular-nums transition-colors duration-300 ${left === 0 ? "text-amber-700 dark:text-amber-400" : "text-muted-foreground"}`}
          >
            <NumberRoll value={used} />
            &nbsp;of&nbsp;
            <NumberRoll value={seats} />
            &nbsp;<TextMorph>{seats === 1 ? "seat" : "seats"}</TextMorph>
          </p>
        )}
      </div>

      {onInvite && (
        <div ref={fieldRef} className="px-4 pb-4 @md:px-5">
          <TagInput
            value={tags}
            onValueChange={(next) => {
              setTags(next);
              setInviteError(null);
              if (sending !== "pending") setSending("idle");
            }}
            label="Invite by email"
            placeholder="Emails, separated by commas"
            hint={
              inviteError ??
              (left === 0
                ? "Every seat is taken. Remove someone or add seats to invite more."
                : "Paste a list or pick from your directory.")
            }
            validate={validate}
            normalize={lower}
            separators={SPLIT}
            suggestions={suggestions}
            createLabel={(text) => `Invite “${text}”`}
            max={left}
            limitMessage={
              left === 1
                ? "One seat left on your plan."
                : `${left} seats left on your plan.`
            }
            collapse={2}
            disabled={sending === "pending"}
          />
          <div className="mt-3 flex items-center justify-end gap-2">
            <RoleMenu
              roles={roles}
              value={role}
              onValueChange={setRole}
              label="Role for new members"
              prefix="as"
            />
            <StatusButton
              size="sm"
              status={sending}
              labels={{
                idle: count > 1 ? `Invite ${count}` : "Invite",
                pending: "Inviting",
                success: "Invited",
                error: "Try again",
              }}
              onClick={invite}
              onReset={() => setSending("idle")}
              aria-disabled={(!count && sending === "idle") || undefined}
              className={
                !count && sending === "idle"
                  ? "pointer-events-none opacity-50"
                  : ""
              }
            />
          </div>
        </div>
      )}

      <div className="relative border-t border-border">
        <ul ref={listRef} aria-label={title} className="relative">
          {members.map((m) => (
            <MemberRow
              key={m.id}
              m={m}
              roles={roles}
              saving={Boolean(saving[m.id])}
              shake={shakes[m.id] ?? 0}
              note={notes[m.id]}
              gone={gone.includes(m.id)}
              canEdit={Boolean(onRoleChange)}
              canRemove={Boolean(onRemove)}
              canResend={Boolean(onResend)}
              resendAfter={resendAfter}
              reduced={reduced}
              act={act}
            />
          ))}
        </ul>
        {/* Rows that went: their own elements, folding away where they stood (see use-row-motion). */}
        <div
          ref={ghostRef}
          aria-hidden="true"
          className="pointer-events-none absolute inset-0"
        />
      </div>

      {/* Chips on their way from the field to their rows. */}
      <div
        ref={flyRef}
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 z-20"
      />
      <span className="sr-only" role="status">
        {announce}
      </span>
    </div>
  );
}

"use client";

import * as React from "react";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * ROLE MENU: a role pill that grows into the list of roles
 *
 *   open      the pill's own surface grows from its right edge
 *             into the panel (size and radius ease) while its
 *             label fades into the list; it opens upward when
 *             there's no room below
 *   pick      the panel folds back into the pill and the label
 *             morphs to the new role; while it saves, the
 *             chevron gives way to a small spinner
 *   refuse    if saving fails the label morphs back and the
 *             pill gives a short shake
 * ───────────────────────────────────────────────────────── */

export interface TeamRole {
  value: string;
  label: string;
  /** One line under the role in the menu: what it can do. */
  description?: string;
}

export interface RoleMenuProps {
  roles: TeamRole[];
  value: string;
  onValueChange: (role: string) => void;
  /** Shows a spinner in place of the chevron. */
  saving?: boolean;
  /** Bumped by the parent to shake the pill (a save failed). */
  shake?: number;
  /** Accessible name, e.g. "Role for Maya Chen". */
  label: string;
  /** Said before the role inside the pill, e.g. "as". */
  prefix?: string;
  disabled?: boolean;
  className?: string;
}

type Phase = "closed" | "opening" | "open" | "closing";

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const DURATION = 420;
const PANEL = 248;
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function Chevron({ up, reduced }: { up: boolean; reduced: boolean }) {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      aria-hidden="true"
      className="size-3"
      style={{
        transform: up ? "rotate(180deg)" : "none",
        transition: reduced ? "none" : `transform 320ms ${EASE}`,
      }}
    >
      <path
        d="M4.5 6.25 8 9.75l3.5-3.5"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

/** The pill's insides, shared by the real pill and the copy that fades out as the surface grows. */
function PillFace({
  prefix,
  label,
  saving,
  up,
  reduced,
}: {
  prefix?: string;
  label: string;
  saving: boolean;
  up: boolean;
  reduced: boolean;
}) {
  return (
    <>
      {prefix && <span className="text-muted-foreground">{prefix}&nbsp;</span>}
      <TextMorph>{label}</TextMorph>
      <span className="relative ml-1 grid size-3 place-items-center text-muted-foreground">
        <span
          className="absolute inset-0 grid place-items-center"
          style={{
            opacity: saving ? 0 : 1,
            transform: saving ? "scale(0.6)" : "none",
            transition: reduced
              ? "none"
              : `opacity 200ms ${EASE}, transform 320ms ${EASE}`,
          }}
        >
          <Chevron up={up} reduced={reduced} />
        </span>
        <span
          className={`absolute inset-0.5 rounded-full border-[1.5px] border-current border-t-transparent motion-reduce:animate-none ${saving ? "animate-spin" : ""}`}
          style={{
            opacity: saving ? 1 : 0,
            transition: reduced ? "none" : `opacity 200ms ${EASE}`,
          }}
        />
      </span>
    </>
  );
}

export function RoleMenu({
  roles,
  value,
  onValueChange,
  saving = false,
  shake = 0,
  label,
  prefix,
  disabled = false,
  className = "",
}: RoleMenuProps) {
  const id = React.useId();
  const reduced = useReducedMotion();
  const [phase, setPhase] = React.useState<Phase>("closed");
  const [active, setActive] = React.useState(0);
  const [pill, setPill] = React.useState({ width: 0, height: 28 });
  const [panelHeight, setPanelHeight] = React.useState(0);
  const [fit, setFit] = React.useState({ up: false, width: PANEL, shift: 0 });
  const [highlight, setHighlight] = React.useState({
    top: 0,
    height: 0,
    ready: false,
  });
  const [quiet, setQuiet] = React.useState(false);
  const wrapRef = React.useRef<HTMLDivElement>(null);
  const triggerRef = React.useRef<HTMLButtonElement>(null);
  const panelRef = React.useRef<HTMLDivElement>(null);
  const listRef = React.useRef<HTMLDivElement>(null);
  const rowRefs = React.useRef<(HTMLDivElement | null)[]>([]);
  const timer = React.useRef(0);
  const selected = roles.find((r) => r.value === value);
  const expanded = phase === "open";
  const mounted = phase !== "closed";
  const [prevPhase, setPrevPhase] = React.useState(phase);
  if (phase !== prevPhase) {
    setPrevPhase(phase);
    if (phase === "closed") {
      setHighlight({ top: 0, height: 0, ready: false });
    }
  }

  const measureFit = () => {
    const wrap = wrapRef.current;
    if (!wrap) return;
    const rect = wrap.getBoundingClientRect();
    const viewport = document.documentElement.clientWidth;
    const width = Math.min(PANEL, viewport - 32);
    // Anchored at the pill's right edge; pushed right if that would leave the screen.
    const shift = Math.max(0, 16 - (rect.right - width));
    const estimate = roles.length * 52 + 12;
    const up =
      window.innerHeight - rect.top < estimate + 24 &&
      rect.bottom > estimate + 24;
    setFit((f) =>
      f.up === up && f.width === width && f.shift === shift
        ? f
        : { up, width, shift },
    );
  };

  const open = () => {
    if (disabled || saving || phase === "open" || phase === "opening") return;
    window.clearTimeout(timer.current);
    measureFit();
    setActive(
      Math.max(
        0,
        roles.findIndex((r) => r.value === value),
      ),
    );
    setPhase(reduced ? "open" : "opening");
  };

  const close = React.useCallback(
    (refocus = true) => {
      window.clearTimeout(timer.current);
      if (refocus) triggerRef.current?.focus({ preventScroll: true });
      if (reduced) return setPhase("closed");
      setPhase("closing");
      timer.current = window.setTimeout(() => setPhase("closed"), DURATION);
    },
    [reduced],
  );

  React.useEffect(() => {
    if (phase !== "opening") return;
    let inner = 0;
    const outer = requestAnimationFrame(
      () => (inner = requestAnimationFrame(() => setPhase("open"))),
    );
    return () => {
      cancelAnimationFrame(outer);
      cancelAnimationFrame(inner);
    };
  }, [phase]);

  React.useEffect(() => () => window.clearTimeout(timer.current), []);

  React.useLayoutEffect(() => {
    const trigger = triggerRef.current;
    if (!trigger) return;
    const measure = () =>
      setPill((p) =>
        p.width === trigger.offsetWidth && p.height === trigger.offsetHeight
          ? p
          : { width: trigger.offsetWidth, height: trigger.offsetHeight },
      );
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(trigger);
    return () => observer.disconnect();
  }, []);

  React.useLayoutEffect(() => {
    const panel = panelRef.current;
    if (!panel) return;
    setPanelHeight(panel.offsetHeight);
  }, [mounted, roles]);

  React.useLayoutEffect(() => {
    const row = rowRefs.current[active];
    if (!row) return;
    const top = row.offsetTop;
    const height = row.offsetHeight;
    setHighlight((h) =>
      h.top === top && h.height === height && h.ready === (h.ready || expanded)
        ? h
        : { top, height, ready: h.ready || expanded },
    );
  }, [active, expanded, mounted]);

  React.useEffect(() => {
    if (expanded) listRef.current?.focus({ preventScroll: true });
  }, [expanded]);

  React.useEffect(() => {
    if (!expanded) return;
    const onDown = (e: PointerEvent) => {
      if (!wrapRef.current?.contains(e.target as Node)) close(false);
    };
    document.addEventListener("pointerdown", onDown);
    return () => document.removeEventListener("pointerdown", onDown);
  }, [expanded, close]);

  // A failed save: the pill shakes where it stands.
  React.useEffect(() => {
    if (!shake || reduced) return;
    triggerRef.current?.animate(
      [
        { transform: "none" },
        { transform: "translateX(-4px)" },
        { transform: "translateX(4px)" },
        { transform: "translateX(-2px)" },
        { transform: "none" },
      ],
      { duration: 380, easing: "ease-out" },
    );
  }, [shake, reduced]);

  const choose = (role: TeamRole) => {
    close();
    if (role.value !== value) onValueChange(role.value);
  };

  const onListKey = (e: React.KeyboardEvent) => {
    const last = roles.length - 1;
    const move = (to: number) => {
      e.preventDefault();
      setActive(Math.max(0, Math.min(last, to)));
    };
    if (e.key === "ArrowDown") move(active === last ? 0 : active + 1);
    else if (e.key === "ArrowUp") move(active === 0 ? last : active - 1);
    else if (e.key === "Home") move(0);
    else if (e.key === "End") move(last);
    else if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      if (roles[active]) choose(roles[active]);
    } else if (e.key === "Tab") close(false);
  };

  const width = expanded ? fit.width : pill.width;
  const height = expanded ? panelHeight : pill.height;
  const t = reduced
    ? "none"
    : `width ${DURATION}ms ${EASE}, height ${DURATION}ms ${EASE}, right ${DURATION}ms ${EASE}, border-radius ${DURATION}ms ${EASE}`;
  const listId = `${id}-roles`;
  const roleLabel = selected?.label ?? value;

  return (
    <div
      ref={wrapRef}
      className={`relative inline-flex shrink-0 ${className}`}
      onKeyDown={(e) => {
        setQuiet(false);
        if (e.key === "Escape" && expanded) {
          e.preventDefault();
          e.stopPropagation();
          close();
        }
      }}
      onBlur={(e) => {
        if (
          expanded &&
          document.hasFocus() &&
          !wrapRef.current?.contains(e.relatedTarget as Node)
        )
          close(false);
      }}
    >
      <button
        ref={triggerRef}
        type="button"
        aria-haspopup="listbox"
        aria-expanded={expanded}
        aria-controls={mounted ? listId : undefined}
        aria-label={`${label}: ${roleLabel}`}
        aria-busy={saving || undefined}
        disabled={disabled}
        onClick={() => (expanded ? close() : open())}
        onPointerDown={() => setQuiet(true)}
        className={`inline-flex h-7 cursor-pointer items-center whitespace-nowrap rounded-full px-2.5 text-[12px] font-medium shadow-[inset_0_0_0_1px_var(--border)] transition-colors duration-150 hover:bg-accent disabled:cursor-default disabled:opacity-60 disabled:hover:bg-transparent aria-busy:cursor-default ${quiet ? "outline-none" : FOCUS}`}
      >
        <PillFace
          prefix={prefix}
          label={roleLabel}
          saving={saving}
          up={expanded}
          reduced={reduced}
        />
      </button>

      {mounted && (
        <div
          onPointerDown={(e) => {
            e.preventDefault();
            setQuiet(true);
          }}
          className="absolute z-30 overflow-hidden bg-popover text-popover-foreground"
          style={{
            [fit.up ? "bottom" : "top"]: 0,
            right: expanded ? -fit.shift : 0,
            width,
            height,
            borderRadius: expanded ? 16 : pill.height / 2,
            // The pill's own cavemio, the whole way: it is the same surface.
            boxShadow: "inset 0 0 0 1px var(--border)",
            transition: t,
          }}
        >
          {/* The pill's label, fading out as the surface grows and back in as it folds. */}
          <span
            aria-hidden="true"
            className={`pointer-events-none absolute right-0 inline-flex h-7 items-center whitespace-nowrap px-2.5 text-[12px] font-medium ${fit.up ? "bottom-0" : "top-0"}`}
            style={{
              opacity: expanded ? 0 : 1,
              transition: reduced
                ? "none"
                : `opacity ${expanded ? 120 : 260}ms ${EASE} ${expanded ? 0 : 120}ms`,
            }}
          >
            <PillFace
              prefix={prefix}
              label={roleLabel}
              saving={saving}
              up={expanded}
              reduced={reduced}
            />
          </span>
          <div
            ref={panelRef}
            className={`absolute right-0 p-1 ${fit.up ? "bottom-0" : "top-0"}`}
            style={{
              width: fit.width,
              opacity: expanded ? 1 : 0,
              transition: reduced
                ? "none"
                : `opacity ${expanded ? 260 : 120}ms ${EASE} ${expanded ? 90 : 0}ms`,
            }}
          >
            <div
              ref={listRef}
              id={listId}
              role="listbox"
              tabIndex={-1}
              aria-label={label}
              aria-activedescendant={`${id}-r${active}`}
              onKeyDown={onListKey}
              className="relative outline-none"
            >
              <span
                aria-hidden="true"
                className="pointer-events-none absolute inset-x-0 top-0 rounded-[12px] bg-accent"
                style={{
                  height: highlight.height,
                  transform: `translateY(${highlight.top}px)`,
                  opacity: highlight.ready ? 1 : 0,
                  transition:
                    highlight.ready && !reduced
                      ? `transform 300ms ${EASE}, height 300ms ${EASE}, opacity 200ms`
                      : "none",
                }}
              />
              {roles.map((r, i) => {
                const on = r.value === value;
                return (
                  <div
                    key={r.value}
                    ref={(el) => {
                      rowRefs.current[i] = el;
                    }}
                    id={`${id}-r${i}`}
                    role="option"
                    aria-selected={on}
                    onPointerMove={() => setActive(i)}
                    onClick={() => choose(r)}
                    className="relative flex cursor-pointer items-start gap-2 rounded-[12px] px-2.5 py-2"
                  >
                    <span className="min-w-0 flex-1">
                      <span className="block text-[12.5px] font-medium">
                        {r.label}
                      </span>
                      {r.description && (
                        <span className="mt-0.5 block text-[11.5px] leading-[1.4] text-muted-foreground">
                          {r.description}
                        </span>
                      )}
                    </span>
                    <svg
                      viewBox="0 0 16 16"
                      fill="none"
                      aria-hidden="true"
                      className="mt-0.5 size-3.5 shrink-0"
                    >
                      <path
                        d="M3.5 8.5 6.5 11.5 12.5 4.5"
                        stroke="currentColor"
                        strokeWidth="1.8"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        pathLength={1}
                        strokeDasharray={1}
                        style={{
                          strokeDashoffset: on && expanded ? 0 : 1,
                          transition: reduced
                            ? "none"
                            : `stroke-dashoffset 380ms ${EASE} 160ms`,
                        }}
                      />
                    </svg>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import * as React from "react";
import { playStrip, preloadStrips } from "./cast-sprite";
import { SKIM_ART, SKIM_FRAMES } from "./skim-art";
import { StatusButton, type ActionStatus } from "./status-button";
import {
  EASE_OUT,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * TERMS: Skim reads them with you
 *
 *   reading  Skim, an owl in reading glasses, sits on the lit
 *            stage with his book; his bubble gives the section
 *            you're on in one plain line ("Your files stay
 *            yours."), and changes as you scroll into the next
 *   dizzy    scroll too fast (or Skip to the end) and his eyes
 *            spin
 *   yawn     linger 4s on one section and he yawns, and again
 *            every 6s you stay
 *   read     reach the end: thumbs up, "Nothing sneaky", and
 *            Accept turns on
 *   accepted Accept → Accepting → Accepted
 *
 * The terms are your sections ({ title, body, tldr }); onAccept
 * gets the version so you can record which one was agreed to.
 * ───────────────────────────────────────────────────────── */

export interface TermsSection {
  id: string;
  title: string;
  body: React.ReactNode;
  /** The section in one plain line, in Skim's bubble. */
  tldr: string;
}

export interface TermsProps {
  sections: TermsSection[];
  /** Which terms these are; onAccept gets it back. */
  version: string;
  /** "Updated 21 October 2026", under the title. */
  updated?: string;
  /** Record the acceptance; throw to say it didn't save. */
  onAccept: (version: string) => Promise<unknown>;
  /** Shows Not now beside Accept. */
  onDecline?: () => void;
  /** Accept stays off until the terms have been scrolled to the end. */
  requireRead?: boolean;
  title?: string;
  /** What the owl is called in his lines. */
  name?: string;
  className?: string;
}

type Pose = "reading" | "dizzy" | "yawn" | "proud";

const mix = (color: string, amount: number, into = "transparent") =>
  `color-mix(in oklab, ${color} ${amount}%, ${into})`;
const PF = "var(--primary-foreground)";
const CARD: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, var(--card), ${mix("var(--card)", 95, "var(--foreground)")})`,
  boxShadow: `0 0 0 1px var(--border), inset 0 1px 0 ${mix("var(--background)", 85)}`,
};
/* The one lit surface, ruled faintly like a page: he's reading, after all. */
const STAGE: React.CSSProperties = {
  backgroundColor: "var(--primary)",
  backgroundImage: [
    `radial-gradient(70% 90% at 15% 100%, ${mix(PF, 20)} 0%, transparent 65%)`,
    `linear-gradient(175deg, transparent 40%, ${mix("black", 20)} 100%)`,
    `repeating-linear-gradient(180deg, transparent 0 17px, ${mix(PF, 9)} 17px 18px)`,
  ].join(", "),
  boxShadow: `inset 0 1px 0 ${mix(PF, 36)}, inset 0 0 0 1px ${mix(PF, 12)}`,
};
const LIT: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, ${mix(PF, 16)}, transparent 60%)`,
  boxShadow: `inset 0 1px 0 ${mix(PF, 32)}, inset 0 0 0 1px ${mix("black", 10)}`,
};
/* one animation frame on the stage (he fills almost all of its height) */
const OWL_FRAME_H = 112;
const OWL_FRAME_W = (SKIM_FRAMES.w / SKIM_FRAMES.h) * OWL_FRAME_H;

/** A line that lifts out through a blur as the next one rises in (sentences don't letter-morph well). */
function Line({ text, reduced }: { text: string; reduced: boolean }) {
  const [shown, setShown] = React.useState([{ text, key: 0 }]);
  const [last, setLast] = React.useState(text);
  if (last !== text) {
    setLast(text);
    setShown((s) => [...s.slice(-1), { text, key: s[s.length - 1].key + 1 }]);
  }
  const mounted = React.useRef(false);
  React.useEffect(() => {
    mounted.current = true;
  }, []);
  return (
    <span className="grid">
      {shown.map((l, i) => {
        const current = i === shown.length - 1;
        return (
          <span
            key={l.key}
            className="col-start-1 row-start-1"
            aria-hidden={!current}
            ref={(el) => {
              if (!el || reduced) return;
              if (current && el.dataset.in !== "1" && mounted.current) {
                el.dataset.in = "1";
                el.animate(
                  [
                    {
                      opacity: 0,
                      transform: "translateY(5px)",
                      filter: "blur(4px)",
                    },
                    { opacity: 1, transform: "none", filter: "blur(0)" },
                  ],
                  {
                    duration: 360,
                    delay: 80,
                    easing: EASE_OUT,
                    fill: "backwards",
                  },
                );
              } else if (!current && el.dataset.out !== "1") {
                el.dataset.out = "1";
                el.animate(
                  [
                    { opacity: 1 },
                    {
                      opacity: 0,
                      transform: "translateY(-5px)",
                      filter: "blur(4px)",
                    },
                  ],
                  { duration: 200, easing: "ease-in", fill: "forwards" },
                ).onfinish = () =>
                  setShown((s) => s.filter((x) => x.key !== l.key));
              }
            }}
            style={reduced && !current ? { opacity: 0 } : undefined}
          >
            {l.text}
          </span>
        );
      })}
    </span>
  );
}

export function Terms({
  sections,
  version,
  updated,
  onAccept,
  onDecline,
  requireRead = true,
  title = "Terms of Service",
  name = "Skim",
  className = "",
}: TermsProps) {
  const reduced = useInteractionReducedMotion();
  const baseId = React.useId();
  const pane = React.useRef<HTMLDivElement>(null);
  const bar = React.useRef<HTMLDivElement>(null);
  const owl = React.useRef<HTMLDivElement>(null);
  const [at, setAt] = React.useState(0);
  const [read, setRead] = React.useState(false);
  const [atEnd, setAtEnd] = React.useState(false);
  const [mood, setMood] = React.useState<"" | "dizzy" | "yawn">("");
  const [status, setStatus] = React.useState<ActionStatus>("idle");
  const last = React.useRef({ y: 0, t: 0 });
  const dizzyTimer = React.useRef(0);
  const yawnTimer = React.useRef(0);

  // linger on one section and he yawns: a 2.2s yawn after 4s without a scroll, then again every 6s you stay; any scroll wakes him
  const restartYawn = React.useCallback(() => {
    window.clearTimeout(yawnTimer.current);
    const yawn = (after: number) => {
      yawnTimer.current = window.setTimeout(() => {
        setMood((m) => (m === "" ? "yawn" : m));
        yawnTimer.current = window.setTimeout(() => {
          setMood((m) => (m === "yawn" ? "" : m));
          yawn(6000);
        }, 2400);
      }, after);
    };
    yawn(4000);
  }, []);
  React.useEffect(() => {
    restartYawn();
    return () => {
      window.clearTimeout(yawnTimer.current);
      window.clearTimeout(dizzyTimer.current);
    };
  }, [restartYawn]);

  const onScroll = (e: React.UIEvent<HTMLDivElement>) => {
    const el = e.currentTarget;
    const max = el.scrollHeight - el.clientHeight;
    const k = max > 0 ? el.scrollTop / max : 1;
    bar.current?.style.setProperty("transform", `scaleX(${k})`);
    // too fast to read: his eyes spin
    const dy = Math.abs(el.scrollTop - last.current.y);
    const dt = e.timeStamp - last.current.t;
    last.current = { y: el.scrollTop, t: e.timeStamp };
    if (dy > el.clientHeight * 1.2 || (dt > 0 && dt < 120 && dy / dt > 1.8)) {
      setMood("dizzy");
      window.clearTimeout(dizzyTimer.current);
      dizzyTimer.current = window.setTimeout(() => setMood(""), 1100);
    } else setMood((m) => (m === "yawn" ? "" : m));
    restartYawn();
    // the section at the reading line, a third of the way down
    const line = el.scrollTop + el.clientHeight / 3;
    let i = 0;
    el.querySelectorAll<HTMLElement>("[data-section]").forEach((s, j) => {
      if (s.offsetTop <= line) i = j;
    });
    if (el.scrollTop >= max - 4) i = sections.length - 1;
    setAt(i);
    setAtEnd(el.scrollTop >= max - 4);
    if (el.scrollTop >= max - 4) setRead(true);
  };

  const skip = () => {
    const el = pane.current;
    if (!el) return;
    setMood("dizzy");
    window.clearTimeout(dizzyTimer.current);
    dizzyTimer.current = window.setTimeout(() => setMood(""), 1300);
    el.scrollTo({
      top: el.scrollHeight,
      behavior: reduced ? "auto" : "smooth",
    });
  };

  const accept = async () => {
    if (status === "pending" || status === "success") return;
    setStatus("pending");
    try {
      await onAccept(version);
      setStatus("success");
    } catch {
      setStatus("error");
    }
  };

  const pose: Pose =
    mood === "dizzy"
      ? "dizzy"
      : status === "success" || (atEnd && mood === "")
        ? "proud"
        : mood === "yawn"
          ? "yawn"
          : "reading";
  const [shownPose, setShownPose] = React.useState(pose);
  if (shownPose !== pose) setShownPose(pose);
  const sprite = React.useRef<HTMLDivElement>(null);
  React.useEffect(() => {
    preloadStrips(Object.values(SKIM_ART));
  }, []);
  // each pose is a loop of frames; the yawn plays once and he goes back to reading
  React.useEffect(() => {
    const clip = SKIM_FRAMES.clips[shownPose];
    playStrip(sprite.current, {
      src: SKIM_ART[shownPose],
      frames: clip.frames,
      fps: clip.fps,
      size: OWL_FRAME_W,
      height: OWL_FRAME_H,
      loop: shownPose !== "yawn",
      reduced,
    });
    if (!reduced && shownPose !== "yawn")
      owl.current?.animate(
        [
          { transform: "scale(0.96) translateY(2px)", opacity: 0.6 },
          { transform: "none", opacity: 1 },
        ],
        { duration: 260, easing: EASE_OUT },
      );
  }, [shownPose, reduced]);

  const say =
    status === "success"
      ? "Thanks for reading. Well, skimming."
      : pose === "dizzy"
        ? "Whoa. Slow down, I’m reading."
        : atEnd
          ? "That’s everything. Nothing sneaky."
          : pose === "yawn"
            ? `Still on ${sections[at]?.title.toLowerCase() ?? "this"}…`
            : (sections[at]?.tldr ?? "");
  const canAccept = !requireRead || read;

  return (
    <section
      aria-labelledby={`${baseId}-title`}
      className={`relative w-full max-w-[380px] rounded-[28px] p-2 text-card-foreground ${className}`}
      style={CARD}
    >
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 380px)" }}
      />
      <div className="@container w-full">
        <div
          className="relative flex h-[132px] items-end overflow-clip rounded-[22px] text-primary-foreground"
          style={STAGE}
        >
          {/* Skim, animated: each pose is a loop of frames */}
          <div
            ref={owl}
            aria-hidden="true"
            className="relative mb-1 ml-1 shrink-0"
            style={{
              height: OWL_FRAME_H,
              width: OWL_FRAME_W,
              transformOrigin: "50% 100%",
            }}
          >
            <div ref={sprite} className="size-full" />
          </div>
          {/* his bubble: the section in one plain line */}
          <div className="relative mb-auto mr-3 mt-4 min-w-0 flex-1">
            <span
              aria-hidden="true"
              className="absolute -left-[5px] top-6 size-2.5 rotate-45 rounded-[2px]"
              style={{ background: PF }}
            />
            <div
              className="relative rounded-[14px] px-3 py-2"
              style={{ background: PF, color: "var(--primary)" }}
            >
              <p className="text-[11px] font-medium opacity-70">
                {name}’s summary · {Math.min(at + 1, sections.length)} of{" "}
                {sections.length}
              </p>
              <p
                className="mt-0.5 text-[13px] font-medium leading-[1.35] @max-[340px]:text-[12px]"
                aria-live="polite"
              >
                <Line text={say} reduced={reduced} />
              </p>
            </div>
          </div>
        </div>

        <div className="px-3 pt-3">
          <div className="flex items-baseline justify-between gap-3">
            <h2
              id={`${baseId}-title`}
              className="text-[15px] font-medium tracking-[-0.01em]"
            >
              {title}
            </h2>
            {!read && (
              <button
                type="button"
                onClick={skip}
                className="shrink-0 cursor-pointer text-[12px] text-muted-foreground underline decoration-border underline-offset-2 hover:text-foreground"
              >
                Skip to the end
              </button>
            )}
          </div>
          {updated && (
            <p className="mt-0.5 text-[12px] text-muted-foreground">
              {updated}
            </p>
          )}
        </div>

        {/* the terms themselves, with how far you've read along the bottom */}
        <div className="relative mx-2 mt-2.5 overflow-clip rounded-[14px] border border-border bg-background">
          <div
            ref={pane}
            tabIndex={0}
            role="region"
            aria-label={title}
            onScroll={onScroll}
            className="h-[188px] overflow-y-auto overscroll-contain px-3.5 py-3 text-[12.5px] leading-[1.6] text-muted-foreground outline-none focus-visible:ring-2 focus-visible:ring-ring/40 focus-visible:ring-inset"
          >
            {sections.map((s, i) => (
              <div key={s.id} data-section className={i ? "mt-3.5" : ""}>
                <h3 className="text-[12.5px] font-medium text-foreground">
                  {i + 1}. {s.title}
                </h3>
                <div className="mt-1 [&_p+p]:mt-2">{s.body}</div>
              </div>
            ))}
          </div>
          <div className="absolute inset-x-0 bottom-0 h-px bg-border" />
          <div
            ref={bar}
            className="absolute inset-x-0 bottom-0 h-px origin-left bg-primary"
            style={{ transform: "scaleX(0)" }}
          />
        </div>

        <div className="flex items-center gap-2 px-2 pb-1 pt-3">
          {onDecline && (
            <StatusButton
              variant="outline"
              labels={{ idle: "Not now" }}
              onClick={onDecline}
              className="h-10 flex-1 text-[13.5px]"
              disabled={status === "pending"}
            />
          )}
          <StatusButton
            status={status}
            labels={{
              idle: canAccept ? "Accept" : "Read to the end to accept",
              pending: "Accepting",
              success: "Accepted",
              error: "Try again",
            }}
            onClick={accept}
            disabled={!canAccept}
            className="h-10 flex-[2] text-[13.5px] disabled:bg-[color-mix(in_oklab,var(--foreground)_7%,transparent)] disabled:text-muted-foreground"
            style={canAccept && status !== "error" ? LIT : undefined}
          />
        </div>
      </div>
    </section>
  );
}

export default Terms;

"use client";

import * as React from "react";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * TESTIMONIALS: one quote, chosen by its people
 *
 *   choose    a row of faces; the chosen one comes forward and
 *             the rest step back
 *   change    the quote's height eases to the new words while
 *             they cross-fade through a soft blur; the name
 *             morphs letter by letter
 *   autoplay  a ring draws itself around the chosen face as the
 *             timer; when it closes, the next person speaks.
 *             Pointing at it pauses
 *
 * The faces are a radio group: arrow keys move between people.
 * ───────────────────────────────────────────────────────── */

export interface Testimonial {
  quote: string;
  name: string;
  role?: string;
  /** A photo URL; without one, tinted initials. */
  avatar?: string;
}

export interface TestimonialsProps extends React.HTMLAttributes<HTMLElement> {
  items: Testimonial[];
  /** Move to the next person every this many ms. */
  autoplay?: number;
  defaultIndex?: number;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const MORPH = 520;
const SIZE = 36;
const RING = 2 * Math.PI * (SIZE / 2 + 4);

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function hue(text: string) {
  let h = 0;
  for (let i = 0; i < text.length; i++) h = (h * 31 + text.charCodeAt(i)) % 360;
  return h;
}

function Face({ item }: { item: Testimonial }) {
  const [failed, setFailed] = React.useState(false);
  if (item.avatar && !failed)
    return (
      <img
        src={item.avatar}
        alt=""
        onError={() => setFailed(true)}
        className="size-full rounded-full object-cover"
      />
    );
  const h = hue(item.name);
  const initials = item.name
    .split(/\s+/)
    .map((w) => w[0])
    .slice(0, 2)
    .join("");
  return (
    <span
      className="flex size-full items-center justify-center rounded-full text-[12px] font-semibold"
      style={{
        background: `color-mix(in oklab, oklch(0.62 0.13 ${h}) 18%, var(--background))`,
        color: `oklch(0.5 0.12 ${h})`,
      }}
    >
      {initials}
    </span>
  );
}

function Quote({
  text,
  leaving,
  reduced,
  quoteRef,
}: {
  text: string;
  leaving: boolean;
  reduced: boolean;
  quoteRef?: (el: HTMLQuoteElement | null) => void;
}) {
  const ref = React.useRef<HTMLQuoteElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el || reduced) return;
    const animation = leaving
      ? el.animate(
          [
            { opacity: 1, filter: "blur(0px)", transform: "none" },
            { opacity: 0, filter: "blur(8px)", transform: "translateY(-8px)" },
          ],
          { duration: MORPH * 0.55, easing: EASE, fill: "forwards" },
        )
      : el.animate(
          [
            { opacity: 0, filter: "blur(8px)", transform: "translateY(10px)" },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          { duration: MORPH, easing: EASE, delay: 90, fill: "backwards" },
        );
    return () => animation.cancel();
  }, [leaving, reduced]);
  return (
    <blockquote
      ref={(el) => {
        ref.current = el;
        quoteRef?.(el);
      }}
      aria-hidden={leaving || undefined}
      className="absolute inset-x-0 top-0 text-balance text-[22px] font-medium leading-[1.35] tracking-[-0.02em] text-foreground"
    >
      <span aria-hidden="true" className="text-muted-foreground/60">
        “
      </span>
      {text}
      <span aria-hidden="true" className="text-muted-foreground/60">
        ”
      </span>
    </blockquote>
  );
}

export function Testimonials({
  items,
  autoplay,
  defaultIndex = 0,
  className = "",
  ...props
}: TestimonialsProps) {
  const reduced = useReducedMotion();
  const [index, setIndex] = React.useState(defaultIndex);
  const [leaving, setLeaving] = React.useState<{ text: string; key: number }[]>(
    [],
  );
  const [height, setHeight] = React.useState<number | null>(null);
  const [paused, setPaused] = React.useState(false);
  const [cycle, setCycle] = React.useState(0);
  const quoteRef = React.useRef<HTMLQuoteElement | null>(null);
  const faceRefs = React.useRef<(HTMLButtonElement | null)[]>([]);
  const counter = React.useRef(0);
  const current = items[index];

  const choose = (next: number, focus = false) => {
    const i = (next + items.length) % items.length;
    setCycle((c) => c + 1);
    if (focus) faceRefs.current[i]?.focus();
    if (i === index) return;
    setLeaving((l) => [
      ...l,
      { text: items[index].quote, key: ++counter.current },
    ]);
    setIndex(i);
  };

  React.useEffect(() => {
    if (!leaving.length) return;
    const timer = window.setTimeout(() => setLeaving([]), MORPH);
    return () => window.clearTimeout(timer);
  }, [leaving]);

  // The quote area takes the height of the words now showing.
  React.useLayoutEffect(() => {
    const el = quoteRef.current;
    if (!el) return;
    const measure = () =>
      setHeight((h) => (h === el.offsetHeight ? h : el.offsetHeight));
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, [index]);

  const setQuoteRef = React.useCallback((el: HTMLQuoteElement | null) => {
    quoteRef.current = el;
  }, []);

  const onKeyDown = (e: React.KeyboardEvent) => {
    const moves: Record<string, number> = {
      ArrowRight: index + 1,
      ArrowDown: index + 1,
      ArrowLeft: index - 1,
      ArrowUp: index - 1,
      Home: 0,
      End: items.length - 1,
    };
    if (!(e.key in moves)) return;
    e.preventDefault();
    choose(moves[e.key], true);
  };

  const playing = Boolean(autoplay) && !reduced && !paused;
  if (!current) return null;

  return (
    <figure
      className={`w-full ${className}`}
      onPointerEnter={() => setPaused(true)}
      onPointerLeave={() => setPaused(false)}
      onFocus={() => setPaused(true)}
      onBlur={(e) =>
        !e.currentTarget.contains(e.relatedTarget as Node) && setPaused(false)
      }
      {...props}
    >
      <div
        className="relative"
        aria-live={autoplay ? "off" : "polite"}
        style={{
          height: height ?? undefined,
          transition:
            reduced || height === null ? "none" : `height ${MORPH}ms ${EASE}`,
        }}
      >
        {leaving.map((l) => (
          <Quote key={l.key} text={l.text} leaving reduced={reduced} />
        ))}
        <Quote
          key={`q${index}`}
          text={current.quote}
          leaving={false}
          reduced={reduced || !leaving.length}
          quoteRef={setQuoteRef}
        />
      </div>

      <figcaption className="mt-6 flex items-baseline gap-2 text-[13.5px]">
        <TextMorph className="font-medium text-foreground">
          {current.name}
        </TextMorph>
        {current.role && (
          <span
            key={current.role}
            className="text-muted-foreground animate-[ui-fade-in_400ms_ease-out_120ms_both] motion-reduce:animate-none"
          >
            {current.role}
          </span>
        )}
      </figcaption>

      <div
        role="radiogroup"
        aria-label="Choose a testimonial"
        onKeyDown={onKeyDown}
        className="mt-5 flex items-center gap-3"
      >
        {items.map((item, i) => {
          const selected = i === index;
          return (
            <button
              key={item.name}
              ref={(el) => {
                faceRefs.current[i] = el;
              }}
              type="button"
              role="radio"
              aria-checked={selected}
              aria-label={`${item.name}${item.role ? `, ${item.role}` : ""}`}
              tabIndex={selected ? 0 : -1}
              onClick={() => choose(i)}
              className="cursor-pointer relative rounded-full outline-none focus-visible:ring-2 focus-visible:ring-ring/40 focus-visible:ring-offset-4 focus-visible:ring-offset-background"
              style={{ width: SIZE, height: SIZE }}
            >
              <span
                className="block size-full overflow-hidden rounded-full transition-[opacity,transform,filter] duration-500"
                style={{
                  opacity: selected ? 1 : 0.45,
                  transform: selected ? "scale(1)" : "scale(0.88)",
                  filter: selected ? "none" : "grayscale(0.6)",
                  transitionTimingFunction: EASE,
                }}
              >
                <Face item={item} />
              </span>
              {/* The ring: full when chosen, or drawing itself as the autoplay timer. */}
              <svg
                aria-hidden="true"
                viewBox={`0 0 ${SIZE + 10} ${SIZE + 10}`}
                className="pointer-events-none absolute -inset-[5px] -rotate-90"
                style={{ width: SIZE + 10, height: SIZE + 10 }}
              >
                <circle
                  key={selected ? `${index}-${cycle}` : "idle"}
                  cx={(SIZE + 10) / 2}
                  cy={(SIZE + 10) / 2}
                  r={SIZE / 2 + 4}
                  fill="none"
                  strokeWidth="1.25"
                  strokeLinecap="round"
                  className="stroke-foreground transition-opacity duration-300"
                  strokeDasharray={RING}
                  onAnimationEnd={() => selected && choose(index + 1)}
                  style={{
                    opacity: selected ? 1 : 0,
                    strokeDashoffset:
                      selected && !(autoplay && !reduced) ? 0 : RING,
                    ...(selected && autoplay && !reduced
                      ? ({
                          "--ui-ring": `${RING}`,
                          animation: `ui-ring-fill ${autoplay}ms linear forwards`,
                          animationPlayState: playing ? "running" : "paused",
                        } as React.CSSProperties)
                      : {}),
                  }}
                />
              </svg>
            </button>
          );
        })}
      </div>
    </figure>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

"use client";

import * as React from "react";
import { Field, fieldSurface, useFieldIds, useShake } from "./imported-field";
import { NumberRoll } from "./number-roll";
import {
  EASE_OUT,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * TEXTAREA: grows with what you write
 *
 *   grow     a hidden copy of the text is measured and the box
 *            eases to its height, between minRows and maxRows,
 *            then scrolls; it never snaps a line taller
 *   scroll   past maxRows the browser's scrollbar never shows:
 *            lines fade out at the top and bottom edges instead of
 *            being sliced, and a 3px thumb inside the padding
 *            shows where you are while you scroll, then fades;
 *            it can be dragged
 *   compose  `footer` (tools) and `action` (send) sit inside the box;
 *            `onSubmit` sends on ⌘↵ / Ctrl+Enter, with the hint rising
 *            in beside the action once there's something to send
 *   count    with maxLength, the count rolls as you type and turns
 *            amber in the last tenth, red at the limit
 *   error    same as every field: red line, hint gives way, shake
 *
 * Text is 16px on phones so iOS never zooms the page on focus.
 * ───────────────────────────────────────────────────────── */

export interface TextareaProps extends Omit<
  React.TextareaHTMLAttributes<HTMLTextAreaElement>,
  "onSubmit"
> {
  label?: React.ReactNode;
  hint?: React.ReactNode;
  error?: React.ReactNode;
  minRows?: number;
  maxRows?: number;
  /** Show "12 / 280" beside the label when maxLength is set. */
  showCount?: boolean;
  /** Tools inside the box, under the text on the left (attach, emoji). */
  footer?: React.ReactNode;
  /** The main action inside the box on the right (send). */
  action?: React.ReactNode;
  /** ⌘↵ / Ctrl+Enter calls this with the text. */
  onSubmit?: (value: string) => void;
  onValueChange?: (value: string) => void;
  ref?: React.Ref<HTMLTextAreaElement>;
  className?: string;
  textareaClassName?: string;
}

const TYPE =
  "px-4 py-[9px] text-[16px] leading-[1.5] sm:text-[13.5px] sm:leading-[1.55]";
const FADE = 14;

const subscribeNoop = () => () => {};
const isMac = () => /Mac|iPhone|iPad/.test(navigator.platform);

export function Textarea({
  label,
  hint,
  error,
  minRows = 3,
  maxRows = 10,
  showCount = true,
  footer,
  action,
  onSubmit,
  onValueChange,
  ref,
  id,
  className = "",
  textareaClassName = "",
  value,
  defaultValue,
  onChange,
  onKeyDown,
  onFocus,
  onBlur,
  maxLength,
  disabled,
  required,
  ...props
}: TextareaProps) {
  const reduced = useInteractionReducedMotion();
  const ids = useFieldIds(id);
  const mac = React.useSyncExternalStore(subscribeNoop, isMac, () => true);
  const [text, setText] = React.useState(String(defaultValue ?? ""));
  const current = value !== undefined ? String(value) : text;
  const mirror = React.useRef<HTMLDivElement>(null);
  const area = React.useRef<HTMLTextAreaElement>(null);
  const thumb = React.useRef<HTMLSpanElement>(null);
  const [height, setHeight] = React.useState<number | null>(null);
  const [overflows, setOverflows] = React.useState(false);
  const [focused, setFocused] = React.useState(false);
  const fadeTimer = React.useRef(0);
  const drag = React.useRef<{ y: number; top: number } | null>(null);
  const shakeRef = useShake<HTMLDivElement>(!!error);

  // Height from the mirror, in whole lines between minRows and maxRows (line metrics read from CSS, so
  // the 16px phone type and the 13.5px desktop type both measure right).
  React.useLayoutEffect(() => {
    const el = mirror.current;
    if (!el) return;
    const measure = () => {
      const style = getComputedStyle(el);
      const line = parseFloat(style.lineHeight) || 21;
      const pad =
        parseFloat(style.paddingTop) + parseFloat(style.paddingBottom);
      const next = Math.round(
        Math.min(
          maxRows * line + pad,
          Math.max(minRows * line + pad, el.offsetHeight),
        ),
      );
      setHeight((h) => (h === next ? h : next));
      setOverflows((o) =>
        o === el.offsetHeight > maxRows * line + pad + 1 ? o : !o,
      );
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    return () => ro.disconnect();
  }, [current, minRows, maxRows]);

  // Edge fades and thumb, written straight to the elements: no render per scroll frame.
  const paint = React.useCallback((show: boolean) => {
    const el = area.current;
    const t = thumb.current;
    if (!el) return;
    const max = el.scrollHeight - el.clientHeight;
    const top = max > 1 ? Math.min(FADE, el.scrollTop) : 0;
    const bottom = max > 1 ? Math.min(FADE, max - el.scrollTop) : 0;
    const mask = `linear-gradient(to bottom, transparent 0, #000 ${top}px, #000 calc(100% - ${bottom}px), transparent 100%)`;
    el.style.maskImage = mask;
    el.style.webkitMaskImage = mask;
    if (!t) return;
    if (max <= 1) {
      t.style.opacity = "0";
      return;
    }
    const track = el.clientHeight - 12;
    const size = Math.max(24, (el.clientHeight / el.scrollHeight) * track);
    t.style.height = `${size}px`;
    t.style.transform = `translateY(${6 + (el.scrollTop / max) * (track - size)}px)`;
    if (show) {
      t.style.opacity = "1";
      window.clearTimeout(fadeTimer.current);
      fadeTimer.current = window.setTimeout(() => {
        if (!drag.current && thumb.current) thumb.current.style.opacity = "0";
      }, 900);
    }
  }, []);

  React.useEffect(() => () => window.clearTimeout(fadeTimer.current), []);
  React.useLayoutEffect(() => paint(false), [paint, height, current]);

  const setRefs = (el: HTMLTextAreaElement | null) => {
    area.current = el;
    if (typeof ref === "function") ref(el);
    else if (ref)
      (ref as React.RefObject<HTMLTextAreaElement | null>).current = el;
  };

  const count = current.length;
  const near = maxLength ? count >= maxLength * 0.9 : false;
  const full = maxLength ? count >= maxLength : false;
  const describedBy =
    [hint && !error ? ids.hint : null, error ? ids.error : null]
      .filter(Boolean)
      .join(" ") || undefined;
  const canSend = !!onSubmit && focused && current.trim().length > 0;

  return (
    <Field
      id={ids.id}
      label={label}
      hint={hint}
      error={error}
      required={required}
      className={className}
      aside={
        maxLength && showCount ? (
          <span
            className={
              full
                ? "text-red-600 dark:text-red-400"
                : near
                  ? "text-amber-600 dark:text-amber-400"
                  : ""
            }
            style={{ transition: "color 200ms" }}
          >
            <NumberRoll value={count} /> / {maxLength}
          </span>
        ) : undefined
      }
    >
      <div
        ref={shakeRef}
        className={`${fieldSurface({ invalid: !!error, disabled, round: false })} flex-col items-stretch`}
      >
        <div className="relative">
          {/* The measuring copy: same type and padding, never seen. */}
          <div
            ref={mirror}
            aria-hidden="true"
            className={`pointer-events-none invisible absolute inset-x-0 top-0 whitespace-pre-wrap break-words ${TYPE} ${textareaClassName}`}
          >
            {current + "​"}
          </div>
          <textarea
            ref={setRefs}
            id={ids.id}
            value={value}
            defaultValue={defaultValue}
            maxLength={maxLength}
            disabled={disabled}
            required={required}
            aria-invalid={error ? true : undefined}
            aria-describedby={describedBy}
            aria-keyshortcuts={
              onSubmit ? "Meta+Enter Control+Enter" : undefined
            }
            onChange={(e) => {
              if (value === undefined) setText(e.target.value);
              onChange?.(e);
              onValueChange?.(e.target.value);
            }}
            onKeyDown={(e) => {
              onKeyDown?.(e);
              if (
                onSubmit &&
                e.key === "Enter" &&
                (e.metaKey || e.ctrlKey) &&
                current.trim()
              ) {
                e.preventDefault();
                onSubmit(current);
              }
            }}
            onFocus={(e) => {
              setFocused(true);
              onFocus?.(e);
            }}
            onBlur={(e) => {
              setFocused(false);
              onBlur?.(e);
            }}
            onScroll={() => paint(true)}
            style={{
              height: height ?? undefined,
              transition: reduced ? "none" : `height 260ms ${EASE_OUT}`,
            }}
            className={`block w-full resize-none bg-transparent outline-none placeholder:text-muted-foreground/70 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden ${overflows ? "pr-6" : ""} ${TYPE} ${textareaClassName}`}
            {...props}
          />
          {/* Our scroll thumb: 3px, inside the padding, shown while scrolling; a wider strip takes the drag. */}
          {overflows && (
            <span
              aria-hidden="true"
              className="absolute right-0 top-0 h-full w-4 touch-none"
              onPointerDown={(e) => {
                const el = area.current;
                if (!el) return;
                e.preventDefault();
                e.currentTarget.setPointerCapture(e.pointerId);
                drag.current = { y: e.clientY, top: el.scrollTop };
                paint(true);
              }}
              onPointerMove={(e) => {
                const el = area.current;
                const d = drag.current;
                if (!el || !d) return;
                const size = parseFloat(thumb.current?.style.height ?? "24");
                const track = el.clientHeight - 12 - size;
                el.scrollTop =
                  d.top +
                  ((e.clientY - d.y) / Math.max(1, track)) *
                    (el.scrollHeight - el.clientHeight);
              }}
              onPointerUp={() => {
                drag.current = null;
                paint(true);
              }}
              onPointerCancel={() => {
                drag.current = null;
              }}
            >
              <span
                ref={thumb}
                className="absolute right-1.5 top-0 w-[3px] rounded-full bg-foreground/25 transition-[opacity,width] duration-300 hover:w-[5px] hover:bg-foreground/35"
                style={{ opacity: 0 }}
              />
            </span>
          )}
        </div>
        {(footer || action || onSubmit) && (
          <div className="flex min-h-10 items-center gap-2 px-2 pb-2">
            <div className="flex min-w-0 flex-1 items-center gap-1">
              {footer}
            </div>
            {onSubmit && (
              <span
                aria-hidden="true"
                className="hidden shrink-0 font-mono text-[11px] text-muted-foreground sm:inline"
                style={{
                  opacity: canSend ? 1 : 0,
                  filter: canSend || reduced ? "none" : "blur(3px)",
                  transition: reduced
                    ? "none"
                    : `opacity 200ms ${EASE_OUT}, filter 200ms ${EASE_OUT}`,
                }}
              >
                {mac ? "⌘↵" : "Ctrl ↵"} to send
              </span>
            )}
            {action}
          </div>
        )}
      </div>
    </Field>
  );
}

export default Textarea;

"use client";

import * as React from "react";
import { flushSync } from "react-dom";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * THEME TOGGLE: the sun sets into a moon, and the room follows
 *
 *   icon       one round button: the sun's rays fold in and turn
 *              away while a shadow slides across the disc and
 *              carves the moon (and back at dawn)
 *   pill       the same icon with a label that morphs, "Light"
 *              into "Dark"
 *   segmented  Light, System and Dark, with a thumb thrown to the
 *              choice; its icon morphs the same way
 *   reveal     the new theme spreads out from the button in a
 *              circle (View Transitions); elsewhere it switches
 *              without a flash of animated colours
 *
 * On its own it remembers the choice, follows the system when
 * asked to and sets the dark class on <html>. Pass value and
 * onValueChange to drive it from next-themes or your own state.
 * ───────────────────────────────────────────────────────── */

export type Theme = "light" | "dark" | "system";

export interface ThemeToggleVariantsProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onChange"
> {
  variant?: "icon" | "pill" | "segmented";
  value?: Theme;
  defaultValue?: Theme;
  onValueChange?: (theme: Theme) => void;
  /** Where an uncontrolled toggle remembers the choice. */
  storageKey?: string;
  /** How an uncontrolled toggle marks dark mode on <html>: the "dark" class, or data-theme. */
  attribute?: "class" | "data-theme";
  /** Spread the new theme from the button in a circle, where the browser can. */
  reveal?: boolean;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 focus-visible:ring-offset-2 focus-visible:ring-offset-background";
const OPTIONS: { value: Theme; label: string }[] = [
  { value: "light", label: "Light" },
  { value: "system", label: "System" },
  { value: "dark", label: "Dark" },
];

const reducedQuery = "(prefers-reduced-motion: reduce)";
const darkQuery = "(prefers-color-scheme: dark)";
const subscribeQuery = (q: string) => (onChange: () => void) => {
  const query = window.matchMedia(q);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useMedia = (q: string) =>
  React.useSyncExternalStore(
    subscribeQuery(q),
    () => window.matchMedia(q).matches,
    () => false,
  );

/**
 * The sun and moon are one drawing: a disc that grows into the moon, eight rays that fold in,
 * and a shadow (a masked-out circle) that slides across to carve the crescent.
 */
function SunMoon({
  dark,
  reduced,
  className = "size-[18px]",
}: {
  dark: boolean;
  reduced: boolean;
  className?: string;
}) {
  const id = React.useId().replace(/:/g, "");
  const t = (ms: number, ease = EASE) =>
    reduced
      ? "none"
      : `transform ${ms}ms ${ease}, opacity ${Math.round(ms * 0.6)}ms ${EASE}`;
  return (
    <svg
      aria-hidden="true"
      viewBox="0 0 24 24"
      fill="none"
      className={className}
    >
      <mask id={`${id}-shadow`}>
        <rect width="24" height="24" fill="white" />
        <circle
          cx="12"
          cy="12"
          r="8"
          fill="black"
          style={{
            transform: dark ? "translate(5px,-5px)" : "translate(14px,-14px)",
            transition: t(560),
          }}
        />
      </mask>
      <circle
        cx="12"
        cy="12"
        r="8"
        fill="currentColor"
        mask={`url(#${id}-shadow)`}
        style={{
          transformOrigin: "12px 12px",
          transform: dark ? "scale(1.05)" : "scale(0.55)",
          transition: t(560, THROW),
        }}
      />
      <g
        stroke="currentColor"
        strokeWidth="1.8"
        strokeLinecap="round"
        style={{
          transformOrigin: "12px 12px",
          transform: dark ? "rotate(-90deg) scale(0.4)" : "none",
          opacity: dark ? 0 : 1,
          transition: t(520),
        }}
      >
        {[0, 45, 90, 135, 180, 225, 270, 315].map((a) => (
          <line
            key={a}
            x1="12"
            y1="2.5"
            x2="12"
            y2="4.5"
            transform={`rotate(${a} 12 12)`}
          />
        ))}
      </g>
    </svg>
  );
}

function SystemIcon() {
  return (
    <svg aria-hidden="true" viewBox="0 0 24 24" fill="none" className="size-4">
      <rect
        x="3"
        y="4.5"
        width="18"
        height="12.5"
        rx="2.5"
        stroke="currentColor"
        strokeWidth="1.7"
      />
      <path
        d="M9 20.5h6M12 17v3.5"
        stroke="currentColor"
        strokeWidth="1.7"
        strokeLinecap="round"
      />
    </svg>
  );
}

/** Switch themes inside a View Transition, revealed as a circle growing out of the button. */
function withReveal(
  from: HTMLElement | null,
  apply: () => void,
  enabled: boolean,
) {
  const doc = document as Document & {
    startViewTransition?: (cb: () => void) => {
      ready: Promise<void>;
      finished: Promise<void>;
    };
  };
  if (!enabled || !from || !doc.startViewTransition) {
    // No transition API: switch with colour transitions held for a frame, so nothing flickers mid-change.
    const hold = document.createElement("style");
    hold.textContent = "*,*::before,*::after{transition:none!important}";
    document.head.appendChild(hold);
    apply();
    void document.body.offsetHeight;
    requestAnimationFrame(() => hold.remove());
    return;
  }
  const r = from.getBoundingClientRect();
  const x = r.left + r.width / 2;
  const y = r.top + r.height / 2;
  const radius = Math.hypot(
    Math.max(x, innerWidth - x),
    Math.max(y, innerHeight - y),
  );
  // Only the circle should move: switch off the browser's default crossfade for this one transition.
  const style = document.createElement("style");
  style.textContent =
    "::view-transition-old(root),::view-transition-new(root){animation:none;mix-blend-mode:normal}";
  document.head.appendChild(style);
  const transition = doc.startViewTransition(() => flushSync(apply));
  transition.ready
    .then(() =>
      document.documentElement.animate(
        {
          clipPath: [
            `circle(0px at ${x}px ${y}px)`,
            `circle(${radius}px at ${x}px ${y}px)`,
          ],
        },
        {
          duration: 620,
          easing: "cubic-bezier(0.65,0,0.35,1)",
          pseudoElement: "::view-transition-new(root)",
        },
      ),
    )
    .catch(() => {});
  transition.finished.finally(() => style.remove());
}

/** The choice saved in this browser, read straight from localStorage (and kept in step with other tabs). */
const subscribeSaved = (onChange: () => void) => {
  window.addEventListener("storage", onChange);
  return () => window.removeEventListener("storage", onChange);
};
const readSaved = (key: string): Theme | null => {
  try {
    const saved = localStorage.getItem(key);
    return saved === "light" || saved === "dark" || saved === "system"
      ? saved
      : null;
  } catch {
    return null;
  }
};

export function ThemeToggleVariants({
  variant = "icon",
  value,
  defaultValue = "system",
  onValueChange,
  storageKey = "theme",
  attribute = "class",
  reveal = true,
  className = "",
  ...props
}: ThemeToggleVariantsProps) {
  const reduced = useMedia(reducedQuery);
  const systemDark = useMedia(darkQuery);
  const controlled = value !== undefined;
  // Uncontrolled: what was picked here, else what this browser saved, else the default. The server and the first paint
  // use the default, and the saved choice lands right after hydration (the first paint never animates).
  const saved = React.useSyncExternalStore(
    subscribeSaved,
    () => readSaved(storageKey),
    () => null,
  );
  const [picked, setPicked] = React.useState<Theme | null>(null);
  const [ready, setReady] = React.useState(false);
  const theme = value ?? picked ?? saved ?? defaultValue;
  const resolved = theme === "system" ? (systemDark ? "dark" : "light") : theme;
  const dark = resolved === "dark";
  const rootRef = React.useRef<HTMLDivElement>(null);
  const segRefs = React.useRef<(HTMLButtonElement | null)[]>([]);
  const [thumb, setThumb] = React.useState({ left: 0, width: 0, ready: false });

  // Motion starts a frame after mount, so restoring a saved choice never animates.
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setReady(true));
    return () => cancelAnimationFrame(frame);
  }, []);

  // Uncontrolled: mark <html> and follow the system while on "system".
  React.useEffect(() => {
    if (controlled) return;
    const root = document.documentElement;
    if (attribute === "class") root.classList.toggle("dark", dark);
    else root.setAttribute("data-theme", resolved);
    root.style.colorScheme = resolved;
  }, [controlled, dark, resolved, attribute]);

  const choose = (next: Theme) => {
    if (next === theme) return;
    const nextDark =
      (next === "system" ? systemDark : next === "dark") !== dark;
    const apply = () => {
      if (!controlled) {
        setPicked(next);
        try {
          localStorage.setItem(storageKey, next);
        } catch {}
        const root = document.documentElement;
        const r = next === "system" ? (systemDark ? "dark" : "light") : next;
        if (attribute === "class") root.classList.toggle("dark", r === "dark");
        else root.setAttribute("data-theme", r);
        root.style.colorScheme = r;
      }
      onValueChange?.(next);
    };
    // Only reveal when the colours actually change (System to Light on a light system doesn't).
    withReveal(rootRef.current, apply, reveal && !reduced && nextDark);
  };

  // Segmented: the thumb sits under the choice.
  const index = Math.max(
    0,
    OPTIONS.findIndex((o) => o.value === theme),
  );
  React.useLayoutEffect(() => {
    if (variant !== "segmented") return;
    const measure = () => {
      const el = segRefs.current[index];
      if (!el) return;
      setThumb((t) =>
        t.left === el.offsetLeft && t.width === el.offsetWidth
          ? t
          : { left: el.offsetLeft, width: el.offsetWidth, ready: t.width > 0 },
      );
    };
    measure();
    const observer = new ResizeObserver(measure);
    segRefs.current.forEach((el) => el && observer.observe(el));
    return () => observer.disconnect();
  }, [variant, index]);

  const motion = reduced || !ready;
  const label = dark ? "Dark" : "Light";

  if (variant === "segmented") {
    return (
      <div
        ref={rootRef}
        role="radiogroup"
        aria-label="Theme"
        onKeyDown={(e) => {
          const moves: Record<string, number> = {
            ArrowRight: index + 1,
            ArrowLeft: index - 1,
            Home: 0,
            End: OPTIONS.length - 1,
          };
          if (!(e.key in moves)) return;
          e.preventDefault();
          const next = (moves[e.key] + OPTIONS.length) % OPTIONS.length;
          choose(OPTIONS[next].value);
          segRefs.current[next]?.focus();
        }}
        className={`relative inline-flex h-9 items-center rounded-full bg-muted p-0.5 ${className}`}
        {...props}
      >
        <span
          aria-hidden="true"
          className="absolute inset-y-0.5 left-0 rounded-full bg-background shadow-[0_0_0_1px_var(--border)]"
          style={{
            width: thumb.width,
            transform: `translateX(${thumb.left}px)`,
            opacity: thumb.width ? 1 : 0,
            transition:
              thumb.ready && !reduced
                ? `transform 460ms ${THROW}, width 380ms ${EASE}`
                : "none",
          }}
        />
        {OPTIONS.map((o, i) => {
          const selected = o.value === theme;
          return (
            <button
              key={o.value}
              ref={(el) => {
                segRefs.current[i] = el;
              }}
              type="button"
              role="radio"
              aria-checked={selected}
              aria-label={o.label}
              tabIndex={selected ? 0 : -1}
              onClick={() => choose(o.value)}
              className={`cursor-pointer relative flex h-8 w-10 items-center justify-center rounded-full transition-colors duration-300 ${FOCUS} ${selected ? "text-foreground" : "text-muted-foreground hover:text-foreground"}`}
            >
              {o.value === "system" ? (
                <SystemIcon />
              ) : (
                <SunMoon
                  dark={o.value === "dark"}
                  reduced={motion}
                  className="size-4"
                />
              )}
            </button>
          );
        })}
      </div>
    );
  }

  return (
    <div ref={rootRef} className={`inline-flex ${className}`} {...props}>
      <button
        type="button"
        // The pill's name starts with the word it shows, so voice control can say it.
        aria-label={
          variant === "pill"
            ? `${label} theme, switch to ${dark ? "light" : "dark"}`
            : `Switch to ${dark ? "light" : "dark"} theme`
        }
        aria-pressed={dark}
        onClick={() => choose(dark ? "light" : "dark")}
        className={`cursor-pointer inline-flex h-9 items-center justify-center rounded-full text-foreground shadow-[inset_0_0_0_1px_var(--border)] transition-[background-color,box-shadow] duration-300 hover:bg-accent active:scale-[0.96] ${FOCUS} ${
          variant === "pill"
            ? "gap-2 pl-2.5 pr-3.5 text-[13px] font-medium"
            : "w-9"
        }`}
      >
        <SunMoon dark={dark} reduced={motion} />
        {variant === "pill" && <TextMorph>{label}</TextMorph>}
      </button>
    </div>
  );
}

"use client";

import { useId, useState, type ComponentPropsWithoutRef } from "react";

import { useThemeWipe } from "./use-theme-wipe";
import { ThemeToggleVariants, type Theme } from "./theme-toggle-variants";

export type ThemeToggleMode = "light" | "dark";

export interface ThemeToggleProps extends Omit<
  ComponentPropsWithoutRef<"button">,
  "children"
> {
  variant?: "icon" | "pill" | "segmented";
  onValueChange?: (theme: Theme) => void;
  storageKey?: string;
  attribute?: "class" | "data-theme";
  reveal?: boolean;
  theme?: ThemeToggleMode;
  defaultTheme?: ThemeToggleMode;
  onThemeChange?: (theme: ThemeToggleMode) => void;
  size?: number;
  /** Opt in to a document reveal. onThemeChange must apply the theme synchronously. */
  pageTransition?: "none" | "circular";
}

const morph =
  "origin-center [transform-box:view-box] transition-[transform,opacity] duration-[420ms] ease-[cubic-bezier(0.16,1,0.3,1)] motion-reduce:transition-none";

function LegacyThemeToggle({
  theme,
  defaultTheme = "light",
  onThemeChange,
  size = 48,
  pageTransition = "none",
  disabled,
  className = "",
  style,
  onClick,
  type = "button",
  "aria-label": label,
  ...props
}: ThemeToggleProps) {
  const [localTheme, setLocalTheme] = useState(defaultTheme);
  const currentTheme = theme ?? localTheme;
  const wipe = useThemeWipe();
  const dark = currentTheme === "dark";
  const maskId = `theme-toggle-${useId().replaceAll(":", "")}`;

  return (
    <button
      {...props}
      type={type}
      disabled={disabled}
      aria-label={label ?? `Switch to ${dark ? "light" : "dark"} mode`}
      aria-pressed={dark}
      data-theme-toggle={currentTheme}
      className={`inline-flex shrink-0 cursor-pointer items-center justify-center rounded-full border-0 bg-white p-0 text-black transition-[background-color,color,scale] duration-200 hover:scale-[1.04] active:scale-95 focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ring disabled:cursor-not-allowed disabled:opacity-40 disabled:hover:scale-100 data-[theme-toggle=dark]:bg-black data-[theme-toggle=dark]:text-white motion-reduce:transition-none motion-reduce:hover:scale-100 motion-reduce:active:scale-100 ${pageTransition === "circular" ? "hover:scale-100! active:scale-100!" : ""} ${className}`}
      style={{
        width: size,
        height: size,
        minWidth: 44,
        minHeight: 44,
        ...style,
      }}
      onClick={(event) => {
        onClick?.(event);
        if (event.defaultPrevented) return;
        wipe(
          event.currentTarget,
          currentTheme,
          pageTransition,
          (next) => {
            if (theme === undefined) setLocalTheme(next);
            onThemeChange?.(next);
          },
          props.nonce,
        );
      }}
    >
      <svg
        aria-hidden="true"
        focusable="false"
        viewBox="0 0 32 32"
        className="size-2/3 overflow-visible"
      >
        <defs>
          <mask
            id={maskId}
            maskUnits="userSpaceOnUse"
            x="0"
            y="0"
            width="32"
            height="32"
          >
            <rect width="32" height="32" fill="white" />
            <circle
              data-theme-toggle-cutout=""
              cx="36"
              cy="-4"
              r="8"
              fill="black"
              className={morph}
              style={{
                transform: dark
                  ? "translate(-16px, 16px)"
                  : "translate(0px, 0px)",
              }}
            />
          </mask>
        </defs>
        <g mask={`url(#${maskId})`}>
          <circle
            cx="16"
            cy="16"
            r="7.5"
            fill="currentColor"
            className={morph}
            style={{ transform: dark ? "scale(1.2)" : "scale(1)" }}
          />
        </g>
        <g
          data-theme-toggle-rays=""
          stroke="currentColor"
          strokeWidth="1.5"
          strokeLinecap="round"
          className={morph}
          style={{
            opacity: dark ? 0 : 1,
            transform: dark
              ? "rotate(45deg) scale(0.5)"
              : "rotate(0deg) scale(1)",
          }}
        >
          {Array.from({ length: 8 }, (_, index) => (
            <line
              key={index}
              x1="16"
              y1="2"
              x2="16"
              y2="6"
              transform={`rotate(${index * 45} 16 16)`}
            />
          ))}
        </g>
      </svg>
    </button>
  );
}

export function ThemeToggle(props: ThemeToggleProps) {
  if (
    props.variant !== undefined ||
    props.onValueChange ||
    props.storageKey ||
    props.attribute ||
    props.reveal !== undefined
  ) {
    const choice = (value: unknown): Theme | undefined =>
      value === "light" || value === "dark" || value === "system"
        ? value
        : undefined;
    return (
      <ThemeToggleVariants
        variant={props.variant}
        value={choice(props.value)}
        defaultValue={choice(props.defaultValue)}
        onValueChange={props.onValueChange}
        storageKey={props.storageKey}
        attribute={props.attribute}
        reveal={props.reveal}
        className={props.className}
        style={props.style}
        id={props.id}
      />
    );
  }
  return <LegacyThemeToggle {...props} />;
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * THINKING INDICATOR: the gap before the first token
 *
 *   orbit  a dot circling a thin line ring
 *   dots   three dots in a soft wave
 *   pulse  a breathing dot
 *   scan   a bar sweeping a short track
 *
 * A label with a sweep of light and a timer whose seconds roll
 * ("Churning 44s") while running. When it's done the mark
 * blurs into a check that draws itself, the label morphs to
 * "Done in" and the time gains its tenths: "Done in 44.6s".
 * ───────────────────────────────────────────────────────── */

export type IndicatorVariant = "orbit" | "dots" | "pulse" | "scan";

export interface ThinkingIndicatorProps extends React.HTMLAttributes<HTMLDivElement> {
  variant?: IndicatorVariant;
  status?: "running" | "done";
  label?: string;
  doneLabel?: string;
  /** Start time (ms); shows a live timer. */
  startedAt?: number;
}

const MORPH = "cubic-bezier(0.16,1,0.3,1)";
// A light that sweeps across the label. A mask, not a text clip, so it reaches letters that are mid-morph.
const SHEEN =
  "text-foreground [mask-image:linear-gradient(90deg,rgb(0_0_0/0.45)_35%,#000_50%,rgb(0_0_0/0.45)_65%)] [mask-size:200%_100%] animate-[ui-sheen_1.4s_linear_infinite] motion-reduce:animate-none motion-reduce:[mask-image:none] motion-reduce:text-foreground/70";
const TENTHS = { minimumFractionDigits: 1, maximumFractionDigits: 1 };
const WHOLE = { maximumFractionDigits: 0 };
const TWO_DIGITS = { minimumIntegerDigits: 2, maximumFractionDigits: 0 };

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Icons trade places through a blur: the old one shrinks away as the new one grows in. */
const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 260ms ${MORPH}, transform 380ms ${MORPH}, filter 260ms ${MORPH}`,
});

function formatElapsed(ms: number) {
  const s = Math.max(0, ms) / 1000;
  return s < 60
    ? `${s.toFixed(1)}s`
    : `${Math.floor(s / 60)}m ${String(Math.floor(s % 60)).padStart(2, "0")}s`;
}

/** Seconds that roll up as they pass; minutes slide open at the first minute; tenths join once it's settled. */
function Elapsed({
  ms,
  settled,
  reduced,
}: {
  ms: number;
  settled: boolean;
  reduced: boolean;
}) {
  const total = Math.max(0, ms) / 1000;
  const minutes = Math.floor(total / 60);
  const seconds = minutes
    ? Math.floor(total % 60)
    : settled
      ? Math.floor(total * 10) / 10
      : Math.floor(total);
  return (
    <span className="inline-flex items-baseline whitespace-nowrap">
      <span
        className="grid"
        style={{
          gridTemplateColumns: minutes ? "1fr" : "0fr",
          opacity: minutes ? 1 : 0,
          transition: reduced
            ? "none"
            : `grid-template-columns 420ms ${MORPH}, opacity 300ms ${MORPH}`,
        }}
      >
        <span className="min-w-0 [clip-path:inset(-4px_0)]">
          <NumberRoll value={minutes} suffix="m" duration={500} />
          &nbsp;
        </span>
      </span>
      <NumberRoll
        value={seconds}
        format={minutes ? TWO_DIGITS : settled ? TENTHS : WHOLE}
        suffix="s"
        direction="up"
        duration={500}
      />
    </span>
  );
}

function Mark({ variant }: { variant: IndicatorVariant }) {
  if (variant === "dots")
    return (
      <span aria-hidden="true" className="flex h-4 items-center gap-[3px]">
        {[0, 150, 300].map((delay) => (
          <span
            key={delay}
            className="size-1 rounded-full bg-foreground animate-[ui-bounce_1.2s_ease-in-out_infinite] motion-reduce:animate-none"
            style={{ animationDelay: `${delay}ms` }}
          />
        ))}
      </span>
    );
  if (variant === "pulse")
    return (
      <span
        aria-hidden="true"
        className="flex size-4 items-center justify-center"
      >
        <span className="size-2.5 rounded-full bg-foreground animate-[ui-breathe_1.6s_ease-in-out_infinite] motion-reduce:animate-none" />
      </span>
    );
  if (variant === "scan")
    return (
      <span aria-hidden="true" className="flex h-4 items-center">
        <span className="relative h-[3px] w-6 overflow-hidden rounded-full bg-border">
          <span className="absolute inset-y-0 left-0 w-2/5 rounded-full bg-foreground animate-[ui-scan_1.1s_cubic-bezier(0.45,0,0.55,1)_infinite] motion-reduce:animate-none" />
        </span>
      </span>
    );
  return (
    <span
      aria-hidden="true"
      className="relative flex size-4 items-center justify-center"
    >
      <span className="absolute inset-[1.5px] rounded-full border border-border" />
      <span className="absolute inset-0 animate-spin [animation-duration:1.4s] motion-reduce:animate-none">
        <span className="absolute left-1/2 top-0 size-[5px] -translate-x-1/2 rounded-full bg-foreground" />
      </span>
    </span>
  );
}

export function ThinkingIndicator({
  variant = "orbit",
  status = "running",
  label = "Thinking",
  doneLabel,
  startedAt,
  className = "",
  ...props
}: ThinkingIndicatorProps) {
  const reduced = useReducedMotion();
  const running = status === "running";
  const [now, setNow] = React.useState(startedAt ?? 0);
  const [endedAt, setEndedAt] = React.useState<number | undefined>(undefined);

  // A new run forgets when the last one ended.
  if (running && endedAt !== undefined) setEndedAt(undefined);

  // Re-render on each whole second of the run (not every frame); when it settles, note the time on the next frame.
  React.useEffect(() => {
    if (!running) {
      if (endedAt !== undefined) return;
      const frame = requestAnimationFrame(() => setEndedAt(Date.now()));
      return () => cancelAnimationFrame(frame);
    }
    if (startedAt === undefined) return;
    let timer = 0;
    const tick = () => {
      const t = Date.now();
      setNow(t);
      timer = window.setTimeout(tick, 1000 - ((t - startedAt) % 1000) + 5);
    };
    timer = window.setTimeout(tick, 0);
    return () => window.clearTimeout(timer);
  }, [running, startedAt, endedAt]);

  // Until the end time is in, the time keeps its running look; then it settles to tenths.
  const settled = !running && endedAt !== undefined;
  const elapsed =
    startedAt === undefined
      ? undefined
      : Math.max(0, (settled ? endedAt : now) - startedAt);
  const showTime =
    elapsed !== undefined && (running || doneLabel === undefined);
  const text = running
    ? label
    : (doneLabel ?? (elapsed !== undefined ? "Done in" : "Done"));

  return (
    <div
      className={`inline-flex items-center gap-2.5 text-[13px] ${className}`}
      {...props}
    >
      <span
        aria-hidden="true"
        className="relative flex h-4 min-w-4 items-center justify-center"
      >
        {/* The mark stops moving once it has faded out. */}
        <span
          className={running ? "" : "[&_*]:[animation-play-state:paused]"}
          style={swap(running, reduced)}
        >
          <Mark variant={variant} />
        </span>
        <span
          className="absolute inset-0 flex items-center justify-center text-muted-foreground"
          style={swap(!running, reduced)}
        >
          <svg viewBox="0 0 16 16" fill="none" className="size-4">
            <path
              d="M3.5 8.5 6.5 11.5 12.5 4.5"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
              pathLength={1}
              strokeDasharray={1}
              style={{
                strokeDashoffset: running ? 1 : 0,
                transition:
                  !running && !reduced
                    ? `stroke-dashoffset 420ms ${MORPH} 120ms`
                    : "none",
              }}
            />
          </svg>
        </span>
      </span>
      <span aria-hidden="true" className="inline-flex items-baseline gap-2">
        <span
          className={`font-medium transition-colors duration-300 ${running ? SHEEN : "text-foreground/75"}`}
        >
          <TextMorph>{text}</TextMorph>
        </span>
        {elapsed !== undefined && (
          <span
            className="-ml-2 grid"
            style={{
              gridTemplateColumns: showTime ? "1fr" : "0fr",
              opacity: showTime ? 1 : 0,
              transition: reduced
                ? "none"
                : `grid-template-columns 420ms ${MORPH}, opacity 300ms ${MORPH}`,
            }}
          >
            <span className="min-w-0 pl-2 tabular-nums text-muted-foreground [clip-path:inset(-4px_0)]">
              <Elapsed ms={elapsed} settled={settled} reduced={reduced} />
            </span>
          </span>
        )}
      </span>
      {/* What it's doing, for screen readers: the label while it works, then the outcome. Never the ticking timer. */}
      <span role="status" aria-live="polite" className="sr-only">
        {running
          ? label
          : showTime && elapsed !== undefined
            ? `${text} ${formatElapsed(elapsed)}`
            : text}
      </span>
    </div>
  );
}

