/* ─────────────────────────────────────────────────────────
 * THINKING TRACE: an expandable record of what an agent did
 *
 *   steps      a checklist: spinner on the live step, which blurs
 *              into a check that draws itself when it's done
 *   reasoning  sentences of reasoning
 *   search     the query, then the sources read
 *   tools      tool calls: reads, edits with +/− counts, commands
 *
 * The header never swaps: "Thinking 6s" morphs into "Thought for
 * 6s" (the seconds roll as they pass), "Searching the web" into
 * "Searched the web", the sparkle into an alert on error. The
 * list eases taller as steps arrive.
 *
 * Drive it from your stream: pass the steps you have so far and a
 * status. It opens while running, folds away once done (stays open
 * on error so the failure is visible), and can always be reopened.
 * ───────────────────────────────────────────────────────── */

export type ThinkingVariant = "steps" | "reasoning" | "search" | "tools";
export type ThinkingStatus = "running" | "done" | "error" | "cancelled";
export type ThinkingStepStatus = "pending" | "running" | "done" | "error";

export interface ThinkingStep {
  /** A step, a sentence of reasoning, a source title or a tool name. */
  label: string;
  /** Supporting text: a count, a domain or a file path. */
  detail?: string;
  /** Makes the row a link, e.g. a search source. */
  href?: string;
  /** Replaces the row's default mark, e.g. a site favicon. */
  icon?: React.ReactNode;
  /** Defaults to "running" for the last step while running, "done" otherwise. */
  status?: ThinkingStepStatus;
  /** Lines added and removed, for edit tool calls. */
  additions?: number;
  deletions?: number;
}

export interface ThinkingTraceProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "title"
> {
  steps: ThinkingStep[];
  variant?: ThinkingVariant;
  status?: ThinkingStatus;
  /** Header while running. Defaults per variant, e.g. "Searching the web". */
  label?: string;
  /** Header once settled. Defaults to e.g. "Thought for 6s" when timing is known. */
  doneLabel?: string;
  /** When the work started (ms). Shows a live timer and times the done label. */
  startedAt?: number;
  /** How long it took (ms), if your stream reports it. */
  duration?: number;
  /** The search query, shown above the sources. */
  query?: string;
  /** Items not listed, shown as "+N more". */
  more?: number;
  /** Replaces the sparkle in the header. */
  icon?: React.ReactNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Makes rows without an href clickable, e.g. to show a tool's output. */
  onStepClick?: (step: ThinkingStep, index: number) => void;
}

const RUNNING_LABEL: Record<ThinkingVariant, string> = {
  steps: "Thinking",
  reasoning: "Thinking",
  search: "Searching the web",
  tools: "Running tools",
};

const SOURCE_TONES = [
  "bg-blue-600",
  "bg-orange-500",
  "bg-emerald-600",
  "bg-violet-600",
];
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const ROW = "flex min-h-7 w-full gap-2 rounded-md px-1.5 py-0.5 text-left";
const MORPH = "cubic-bezier(0.16,1,0.3,1)";
// A light that sweeps across the label. A mask, not a text clip, so it reaches letters that are mid-morph.
const SHEEN =
  "text-foreground [mask-image:linear-gradient(90deg,rgb(0_0_0/0.45)_35%,#000_50%,rgb(0_0_0/0.45)_65%)] [mask-size:200%_100%] animate-[ui-sheen_1.4s_linear_infinite] motion-reduce:animate-none motion-reduce:[mask-image:none] motion-reduce:text-foreground/70";
const TWO_DIGITS = { minimumIntegerDigits: 2 };

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Icons trade places through a blur: the old one shrinks away as the new one grows in. */
const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 260ms ${MORPH}, transform 380ms ${MORPH}, filter 260ms ${MORPH}`,
});

/** A piece of a line that opens out of nothing and folds back into it. */
function Reveal({
  show,
  reduced,
  className = "",
  children,
}: {
  show: boolean;
  reduced: boolean;
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <span
      aria-hidden={!show || undefined}
      className={`grid ${className}`}
      style={{
        gridTemplateColumns: show ? "1fr" : "0fr",
        opacity: show ? 1 : 0,
        filter: show ? "none" : "blur(3px)",
        transition: reduced
          ? "none"
          : `grid-template-columns 420ms ${MORPH}, opacity ${show ? "300ms" : "160ms"} ${MORPH}, filter 300ms ${MORPH}`,
      }}
    >
      <span className="min-w-0 whitespace-nowrap [clip-path:inset(-4px_0)]">
        {children}
      </span>
    </span>
  );
}

/** Seconds that roll up as they pass; minutes slide open at the first minute. */
function Elapsed({ ms, reduced }: { ms: number; reduced: boolean }) {
  const total = Math.max(0, Math.round(ms / 1000));
  const minutes = Math.floor(total / 60);
  return (
    <span className="inline-flex items-baseline">
      <Reveal show={minutes > 0} reduced={reduced}>
        <NumberRoll value={minutes} suffix="m" duration={500} />
        &nbsp;
      </Reveal>
      <NumberRoll
        value={minutes ? total % 60 : total}
        format={minutes ? TWO_DIGITS : undefined}
        suffix="s"
        direction="up"
        duration={500}
      />
    </span>
  );
}

function StepCheck({ drawn, reduced }: { drawn: boolean; reduced: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="none" className="size-3.5">
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 380ms ${MORPH} 100ms`
              : "none",
        }}
      />
    </svg>
  );
}

function toneFor(key: string) {
  let hash = 0;
  for (let i = 0; i < key.length; i++)
    hash = (hash * 31 + key.charCodeAt(i)) | 0;
  return SOURCE_TONES[Math.abs(hash) % SOURCE_TONES.length];
}

function formatDuration(ms: number) {
  const s = Math.max(0, Math.round(ms / 1000));
  return s < 60 ? `${s}s` : `${Math.floor(s / 60)}m ${s % 60}s`;
}

/** Spins only while it's showing, so a faded-out spinner never keeps the page busy. */
function Spinner({ spinning = true }: { spinning?: boolean }) {
  return (
    <span
      aria-hidden="true"
      className={`size-3 shrink-0 rounded-full border-[1.5px] border-border border-t-foreground/70 motion-reduce:animate-none ${spinning ? "animate-spin" : ""}`}
    />
  );
}

export function ThinkingTrace({
  steps,
  variant = "steps",
  status = "done",
  label,
  doneLabel,
  startedAt,
  duration,
  query,
  more,
  icon,
  open,
  defaultOpen,
  onOpenChange,
  onStepClick,
  className = "",
  ...props
}: ThinkingTraceProps) {
  const reduced = useReducedMotion();
  const running = status === "running";
  const [autoOpen, setAutoOpen] = React.useState(running);
  const [userOpen, setUserOpen] = React.useState<boolean | undefined>(
    defaultOpen,
  );
  const expanded = open ?? userOpen ?? autoOpen;
  const panelId = React.useId();
  // Rows present on first render stagger in; rows streamed in later appear as they arrive.
  // The steps already there on mount cascade in; ones that arrive later just appear in turn.
  const [initialCount] = React.useState(steps.length);
  const listRef = React.useRef<HTMLDivElement>(null);
  const [listHeight, setListHeight] = React.useState<number | null>(null);

  // The panel takes the height of its list, so each new step eases it taller instead of jumping.
  React.useLayoutEffect(() => {
    const el = listRef.current;
    if (!el) return;
    const measure = () =>
      setListHeight((h) => (h === el.offsetHeight ? h : el.offsetHeight));
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  // Live timer while running; remember when it settled so the done label can say how long it took.
  const [now, setNow] = React.useState(startedAt ?? 0);
  const [endedAt, setEndedAt] = React.useState<number | undefined>(undefined);
  if (running && endedAt !== undefined) setEndedAt(undefined);
  React.useEffect(() => {
    if (!running) {
      if (endedAt !== undefined) return;
      const frame = requestAnimationFrame(() => setEndedAt(Date.now()));
      return () => cancelAnimationFrame(frame);
    }
    if (startedAt === undefined) return;
    const first = window.setTimeout(() => setNow(Date.now()), 0);
    const timer = window.setInterval(() => setNow(Date.now()), 1000);
    return () => {
      window.clearTimeout(first);
      window.clearInterval(timer);
    };
  }, [running, startedAt, endedAt]);

  // Open while working; fold away after it settles, except on error so the failure stays visible.
  if ((running || status === "error") && !autoOpen) setAutoOpen(true);
  React.useEffect(() => {
    if (running || status === "error") return;
    const timer = window.setTimeout(() => setAutoOpen(false), 900);
    return () => window.clearTimeout(timer);
  }, [running, status]);

  const toggle = () => {
    const next = !expanded;
    if (open === undefined) setUserOpen(next);
    onOpenChange?.(next);
  };

  const took =
    duration ??
    (startedAt !== undefined && endedAt !== undefined
      ? endedAt - startedAt
      : undefined);
  // "Thought for" keeps the timer beside it, so the seconds that ran become the answer.
  const timed =
    status === "done" &&
    !doneLabel &&
    (variant === "steps" || variant === "reasoning") &&
    took !== undefined;
  const settledLabel =
    status === "error"
      ? "Couldn’t finish"
      : status === "cancelled"
        ? "Stopped"
        : variant === "search"
          ? "Searched the web"
          : variant === "tools"
            ? `Ran ${steps.length} ${steps.length === 1 ? "tool" : "tools"}`
            : timed
              ? "Thought for"
              : "Thought it through";
  const text = running
    ? (label ?? RUNNING_LABEL[variant])
    : (doneLabel ?? settledLabel);
  const showTime = (running && startedAt !== undefined) || timed;
  const time = running ? now - (startedAt ?? now) : (took ?? 0);
  const spoken = running
    ? text
    : timed
      ? `${text} ${formatDuration(time)}`
      : text;

  const headerIcons: Record<
    "sparkle" | "error" | "cancelled",
    React.ReactNode
  > = {
    sparkle: <Sparkle className="size-4" fill="currentColor" strokeWidth={0} />,
    error: <AlertCircle className="size-4 text-red-500" />,
    cancelled: <CircleSlash className="size-4" />,
  };
  const headerKey =
    status === "error"
      ? "error"
      : status === "cancelled"
        ? "cancelled"
        : "sparkle";

  return (
    <div className={`flex w-full flex-col ${className}`} {...props}>
      <button
        type="button"
        aria-expanded={expanded}
        aria-controls={panelId}
        onClick={toggle}
        className={`cursor-pointer -mx-1.5 flex w-fit max-w-full items-center gap-2 rounded-lg px-1.5 py-1 text-[13px] font-medium transition-colors duration-100 hover:bg-accent ${FOCUS}`}
      >
        <span
          aria-hidden="true"
          className={`relative flex size-4 shrink-0 transition-colors duration-200 ${running ? "text-foreground/70" : "text-muted-foreground"}`}
        >
          {icon ??
            (Object.keys(headerIcons) as (keyof typeof headerIcons)[]).map(
              (k) => (
                <span
                  key={k}
                  className="absolute inset-0 flex items-center justify-center"
                  style={swap(k === headerKey, reduced)}
                >
                  {headerIcons[k]}
                </span>
              ),
            )}
        </span>
        <span className="flex min-w-0 items-baseline">
          <span
            className={`min-w-0 truncate transition-colors duration-300 ${running ? SHEEN : "text-foreground/75"}`}
          >
            <TextMorph>{text}</TextMorph>
          </span>
          {(startedAt !== undefined || duration !== undefined) && (
            <Reveal show={showTime} reduced={reduced} className="shrink-0">
              <span className="pl-1.5 text-[12.5px] font-normal tabular-nums text-muted-foreground">
                <Elapsed ms={time} reduced={reduced} />
              </span>
            </Reveal>
          )}
        </span>
        <ChevronDown
          aria-hidden="true"
          className={`size-3.5 shrink-0 text-muted-foreground transition-transform duration-300 motion-reduce:transition-none ${expanded ? "rotate-180" : ""}`}
        />
      </button>
      {/* Outside the button, so its name stays its label. Never the ticking timer. */}
      <span role="status" aria-live="polite" className="sr-only">
        {spoken}
      </span>

      <div
        id={panelId}
        inert={!expanded}
        className="overflow-hidden"
        style={{
          height: expanded ? (listHeight ?? "auto") : 0,
          opacity: expanded ? 1 : 0,
          transition:
            reduced || listHeight === null
              ? "none"
              : `height 420ms ${MORPH}, opacity 320ms ${MORPH}`,
        }}
      >
        <div ref={listRef}>
          <div className="relative ml-[5px] mt-1 pl-4">
            <span
              aria-hidden="true"
              className="absolute bottom-1.5 left-[3px] top-0 w-px bg-border"
            />
            <ul className="flex flex-col gap-0.5 py-1">
              {query && (
                <li className="flex h-7 items-center gap-2 px-1.5 text-[12.5px] text-muted-foreground animate-[ui-fade-up_300ms_cubic-bezier(0.23,1,0.32,1)_both] motion-reduce:animate-none">
                  <Search className="size-3.5 shrink-0" aria-hidden="true" />
                  <span className="truncate">{query}</span>
                </li>
              )}

              {steps.map((step, i) => {
                const last = i === steps.length - 1;
                const stepStatus: ThinkingStepStatus =
                  step.status ??
                  (last && running
                    ? "running"
                    : last && status === "error"
                      ? "error"
                      : "done");
                const failed = stepStatus === "error";
                const pending = stepStatus === "pending";
                const align =
                  variant === "reasoning" ? "items-start" : "items-center";

                const mark =
                  variant === "steps" ? (
                    // Every mark is there at once; the one for this step's status shows, and they trade places through a blur.
                    <span
                      aria-hidden="true"
                      className={`relative flex size-3.5 shrink-0 items-center justify-center ${align === "items-start" ? "mt-px" : ""}`}
                    >
                      <span
                        className="absolute inset-0 flex items-center justify-center"
                        style={swap(pending, reduced)}
                      >
                        <span className="size-3 rounded-full border-[1.5px] border-border" />
                      </span>
                      <span
                        className="absolute inset-0 flex items-center justify-center"
                        style={swap(stepStatus === "running", reduced)}
                      >
                        <Spinner spinning={stepStatus === "running"} />
                      </span>
                      <span
                        className="absolute inset-0 flex items-center justify-center text-muted-foreground"
                        style={swap(stepStatus === "done", reduced)}
                      >
                        <StepCheck
                          drawn={stepStatus === "done"}
                          reduced={reduced}
                        />
                      </span>
                      <span
                        className="absolute inset-0 flex items-center justify-center text-red-500"
                        style={swap(failed, reduced)}
                      >
                        <X className="size-3.5" strokeWidth={2.5} />
                      </span>
                    </span>
                  ) : variant === "search" ? (
                    step.icon ? (
                      <span
                        aria-hidden="true"
                        className="flex size-3.5 shrink-0 items-center justify-center overflow-hidden rounded-full"
                      >
                        {step.icon}
                      </span>
                    ) : (
                      <span
                        aria-hidden="true"
                        className={`flex size-3.5 shrink-0 items-center justify-center rounded-full text-white ${failed ? "bg-muted-foreground/40" : toneFor(step.detail ?? step.label)}`}
                      >
                        <Globe className="size-[9px]" strokeWidth={2.5} />
                      </span>
                    )
                  ) : null;

                const trailing =
                  variant === "search" || variant === "tools" ? (
                    <span className="ml-auto flex shrink-0 items-center pl-2">
                      <span
                        className="flex justify-end overflow-hidden"
                        style={{
                          width: stepStatus === "running" ? 12 : 0,
                          ...swap(stepStatus === "running", reduced),
                          transition: reduced
                            ? "none"
                            : `width 380ms ${MORPH}, opacity 260ms ${MORPH}, transform 380ms ${MORPH}, filter 260ms ${MORPH}`,
                        }}
                      >
                        <Spinner spinning={stepStatus === "running"} />
                      </span>
                      <Reveal show={failed} reduced={reduced}>
                        <span className="text-[11.5px] font-medium text-red-500">
                          Failed
                        </span>
                      </Reveal>
                    </span>
                  ) : null;

                const content = (
                  <>
                    {mark}
                    {variant === "tools" ? (
                      <>
                        <span
                          className={`shrink-0 text-[12.5px] font-medium ${pending ? "text-muted-foreground" : "text-foreground"}`}
                        >
                          {step.label}
                        </span>
                        {step.detail && (
                          <span className="min-w-0 truncate font-mono text-[11.5px] text-muted-foreground">
                            {step.detail}
                          </span>
                        )}
                      </>
                    ) : (
                      <>
                        <span
                          className={
                            variant === "reasoning"
                              ? "text-[12.5px] leading-relaxed text-muted-foreground"
                              : `min-w-0 truncate text-[12.5px] font-medium ${pending ? "text-muted-foreground" : "text-foreground"}`
                          }
                        >
                          {step.label}
                        </span>
                        {step.detail && (
                          <span className="shrink-0 text-[11.5px] text-muted-foreground">
                            {step.detail}
                          </span>
                        )}
                      </>
                    )}
                    {step.additions !== undefined && (
                      <span className="shrink-0 font-mono text-[11px] tabular-nums">
                        <span className="text-emerald-600">
                          +{step.additions}
                        </span>{" "}
                        <span className="text-red-500">
                          −{step.deletions ?? 0}
                        </span>
                      </span>
                    )}
                    {trailing}
                  </>
                );
                const delay = i < initialCount ? i * 90 : 0;

                return (
                  <li
                    key={`${i}-${step.label}`}
                    className="animate-[ui-fade-up_320ms_cubic-bezier(0.23,1,0.32,1)_both] motion-reduce:animate-none"
                    style={{ animationDelay: `${delay}ms` }}
                  >
                    {step.href ? (
                      <a
                        href={step.href}
                        target="_blank"
                        rel="noreferrer"
                        className={`${ROW} ${align} transition-colors duration-150 hover:bg-accent ${FOCUS}`}
                      >
                        {content}
                      </a>
                    ) : onStepClick ? (
                      <button
                        type="button"
                        onClick={() => onStepClick(step, i)}
                        className={`${ROW} ${align} cursor-pointer transition-colors duration-150 hover:bg-accent ${FOCUS}`}
                      >
                        {content}
                      </button>
                    ) : (
                      <div className={`${ROW} ${align}`}>{content}</div>
                    )}
                  </li>
                );
              })}

              {more ? (
                <li className="px-1.5 pt-0.5 text-xs text-muted-foreground animate-[ui-fade-in_300ms_ease-out_both] motion-reduce:animate-none">
                  +{more} more
                </li>
              ) : null}
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { durationShort, wallAt } from "./time-range-parse";

/* ─────────────────────────────────────────────────────────
 * TIME BRUSH: drag across any chart to pick the time under it
 *
 *   drag     a band follows the pointer from where you pressed,
 *            with its start, end and length written on it
 *   release  the band's span is passed to onSelect (zoom in),
 *            and the band fades as the chart redraws
 *   cancel   Escape, or a drag too short to mean anything
 *
 * Wrap a chart whose x axis runs from `start` to `end`. Nothing
 * re-renders while you drag: the band is moved directly.
 * ───────────────────────────────────────────────────────── */

export interface TimeBrushProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onSelect"
> {
  /** The time at the chart's left edge. */
  start: Date;
  /** The time at its right edge. */
  end: Date;
  onSelect: (range: { start: Date; end: Date }) => void;
  /** The shortest span worth selecting, in ms. */
  minSpan?: number;
  /** Rounds a time to the nearest edge the chart can show (a day boundary on a daily chart). The band snaps to it while you drag. */
  snap?: (time: number) => number;
  /** How the band writes its edges; hours and minutes by default. `edge` says which end, so a daily chart can name the last day it covers. */
  formatTime?: (time: Date, edge: "start" | "end") => string;
  timeZone?: string;
  disabled?: boolean;
}

const pad = (n: number) => String(n).padStart(2, "0");

export function TimeBrush({
  start,
  end,
  onSelect,
  minSpan = 60_000,
  snap,
  formatTime,
  timeZone,
  disabled = false,
  className = "",
  children,
  ...props
}: TimeBrushProps) {
  const rootRef = React.useRef<HTMLDivElement>(null);
  const bandRef = React.useRef<HTMLDivElement>(null);
  const fillRef = React.useRef<HTMLSpanElement>(null);
  const leftRef = React.useRef<HTMLSpanElement>(null);
  const rightRef = React.useRef<HTMLSpanElement>(null);
  const tagRef = React.useRef<HTMLSpanElement>(null);
  const drag = React.useRef<{
    x0: number;
    id: number;
    left: number;
    width: number;
    from: number;
    to: number;
  } | null>(null);

  const timeAt = (x: number, width: number) =>
    start.getTime() +
    (Math.min(Math.max(x, 0), width) / width) *
      (end.getTime() - start.getTime());
  const xAt = (t: number, width: number) =>
    Math.min(
      Math.max(
        ((t - start.getTime()) / (end.getTime() - start.getTime())) * width,
        0,
      ),
      width,
    );
  const label = (t: number, edge: "start" | "end") => {
    if (formatTime) return formatTime(new Date(t), edge);
    const w = wallAt(t, timeZone);
    return `${pad(w.hour)}:${pad(w.minute)}`;
  };

  const paint = (a: number, b: number, width: number) => {
    const band = bandRef.current;
    const tag = tagRef.current;
    const d = drag.current;
    if (!band || !tag || !d) return;
    let left = Math.max(0, Math.min(a, b));
    let right = Math.min(width, Math.max(a, b));
    d.from = timeAt(left, width);
    d.to = timeAt(right, width);
    if (snap) {
      // The band jumps from edge to edge the chart can show, so what it covers is what you get.
      d.from = Math.max(start.getTime(), snap(d.from));
      d.to = Math.min(end.getTime(), snap(d.to));
      left = xAt(d.from, width);
      right = xAt(d.to, width);
    }
    // Transforms only: a 1px fill scaled to the span, and two cavemio edges moved into place.
    fillRef.current!.style.transform = `translateX(${left}px) scaleX(${right - left})`;
    leftRef.current!.style.transform = `translateX(${left}px)`;
    rightRef.current!.style.transform = `translateX(${right - 1}px)`;
    band.style.opacity = right - left > 2 ? "1" : "0";
    band.style.transition = "none";
    tag.textContent = `${label(d.from, "start")} – ${label(d.to, "end")} · ${durationShort(Math.max(60_000, d.to - d.from))}`;
    // The tag stays on the chart even when the band is near an edge.
    const tw = tag.offsetWidth;
    tag.style.transform = `translateX(${Math.min(Math.max(left + (right - left) / 2 - tw / 2, 0), width - tw)}px)`;
  };

  const finish = (commit: boolean) => {
    const d = drag.current;
    const band = bandRef.current;
    drag.current = null;
    if (band) {
      band.style.transition = "opacity 360ms cubic-bezier(0.16,1,0.3,1)";
      band.style.opacity = "0";
    }
    if (d && commit && d.to - d.from >= minSpan)
      onSelect({ start: new Date(d.from), end: new Date(d.to) });
  };

  React.useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape" && drag.current) finish(false);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  });

  return (
    <div
      ref={rootRef}
      className={`relative select-none ${disabled ? "" : "cursor-crosshair"} ${className}`}
      style={{ touchAction: "pan-y" }}
      onPointerDown={(e) => {
        if (disabled || e.button !== 0) return;
        const r = e.currentTarget.getBoundingClientRect();
        drag.current = {
          x0: e.clientX - r.left,
          id: e.pointerId,
          left: r.left,
          width: r.width,
          from: 0,
          to: 0,
        };
      }}
      onPointerMove={(e) => {
        const d = drag.current;
        if (!d || e.pointerId !== d.id) return;
        const x = e.clientX - d.left;
        if (
          Math.abs(x - d.x0) > 3 &&
          !e.currentTarget.hasPointerCapture(e.pointerId)
        )
          e.currentTarget.setPointerCapture(e.pointerId);
        paint(d.x0, x, d.width);
      }}
      onPointerUp={(e) => {
        const d = drag.current;
        if (!d || e.pointerId !== d.id) return;
        finish(Math.abs(e.clientX - d.left - d.x0) > 6);
      }}
      onPointerCancel={() => finish(false)}
      {...props}
    >
      {children}
      <div
        ref={bandRef}
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 opacity-0"
      >
        <span
          ref={fillRef}
          className="absolute inset-y-0 left-0 w-px origin-left bg-primary/[0.09] will-change-transform"
        />
        <span
          ref={leftRef}
          className="absolute inset-y-0 left-0 w-px bg-primary/70 will-change-transform"
        />
        <span
          ref={rightRef}
          className="absolute inset-y-0 left-0 w-px bg-primary/70 will-change-transform"
        />
        <span
          ref={tagRef}
          className="absolute -top-6 left-0 whitespace-nowrap rounded-full bg-background px-2 py-0.5 font-mono text-[10.5px] tabular-nums text-foreground shadow-[inset_0_0_0_1px_var(--border)] will-change-transform"
        />
      </div>
    </div>
  );
}

/* ─────────────────────────────────────────────────────────
 * TIME RANGE PARSE: what "2h" or "yesterday 14:00–16:00" means
 *
 *   ranges   last N (live), since a moment (live), or a fixed
 *            start and end
 *   typed    15m · 2 hours · last 7 days · today · yesterday ·
 *            this week · last month · since 9 · since monday ·
 *            14:00–16:00 · 9am to 5pm · yesterday 14:00-16:00 ·
 *            16 oct 14:00 – 17 oct 09:00 · ISO dates
 *   zones    wall-clock times are read and written in the zone
 *            you pass (the viewer's own by default)
 * ───────────────────────────────────────────────────────── */

export type TimeRange =
  /** The last `duration` ms, ending now. */
  | { type: "relative"; duration: number }
  /** From `start` until now. */
  | { type: "since"; start: Date }
  | { type: "absolute"; start: Date; end: Date };

export const MINUTE = 60_000;
export const HOUR = 60 * MINUTE;
export const DAY = 24 * HOUR;

type Wall = {
  year: number;
  month: number;
  day: number;
  hour: number;
  minute: number;
};

/* ── Zones ─────────────────────────────────────────────── */

const formatters = new Map<string, Intl.DateTimeFormat>();
function fmt(timeZone?: string) {
  const key = timeZone ?? "";
  let f = formatters.get(key);
  if (!f) {
    f = new Intl.DateTimeFormat("en-US", {
      timeZone,
      hourCycle: "h23",
      year: "numeric",
      month: "numeric",
      day: "numeric",
      hour: "numeric",
      minute: "numeric",
      second: "numeric",
      weekday: "short",
    });
    formatters.set(key, f);
  }
  return f;
}
const WEEKDAY = {
  Sun: 0,
  Mon: 1,
  Tue: 2,
  Wed: 3,
  Thu: 4,
  Fri: 5,
  Sat: 6,
} as Record<string, number>;

/** The wall clock at an instant in a zone. */
export function wallAt(epoch: number, timeZone?: string) {
  const p: Record<string, string> = {};
  for (const part of fmt(timeZone).formatToParts(new Date(epoch)))
    p[part.type] = part.value;
  return {
    year: +p.year,
    month: +p.month,
    day: +p.day,
    hour: +p.hour % 24,
    minute: +p.minute,
    second: +p.second,
    weekday: WEEKDAY[p.weekday] ?? 0,
  };
}

/** The instant a wall-clock time happens in a zone (the earlier one when clocks go back). */
export function fromWall(w: Wall, timeZone?: string) {
  const guess = Date.UTC(w.year, w.month - 1, w.day, w.hour, w.minute);
  const off = (t: number) => {
    const a = wallAt(t, timeZone);
    return (
      Date.UTC(a.year, a.month - 1, a.day, a.hour, a.minute, a.second) -
      Math.floor(t / 1000) * 1000
    );
  };
  const a = guess - off(guess - 6 * HOUR);
  const b = guess - off(guess + 6 * HOUR);
  const fits = (t: number) => {
    const x = wallAt(t, timeZone);
    return x.day === w.day && x.hour === w.hour && x.minute === w.minute;
  };
  if (fits(a) && fits(b)) return Math.min(a, b);
  if (fits(b)) return b;
  // a fits, or the time falls in a gap where clocks jump: either way, the moment the clock passes it.
  return a;
}

const addDays = (w: Wall, n: number): Wall => {
  const d = new Date(Date.UTC(w.year, w.month - 1, w.day + n));
  return {
    ...w,
    year: d.getUTCFullYear(),
    month: d.getUTCMonth() + 1,
    day: d.getUTCDate(),
  };
};
const midnight = (w: Wall): Wall => ({ ...w, hour: 0, minute: 0 });

/* ── Resolving and stepping ────────────────────────────── */

export function resolveTimeRange(
  range: TimeRange,
  now = new Date(),
): { start: Date; end: Date } {
  if (range.type === "relative")
    return { start: new Date(now.getTime() - range.duration), end: now };
  if (range.type === "since") return { start: range.start, end: now };
  return { start: range.start, end: range.end };
}

export const isLive = (range: TimeRange) => range.type !== "absolute";

/** The same length of time, one window earlier (-1) or later (1). A window that would reach now becomes live again. */
export function stepTimeRange(
  range: TimeRange,
  dir: -1 | 1,
  now = new Date(),
): TimeRange {
  const { start, end } = resolveTimeRange(range, now);
  const span = end.getTime() - start.getTime();
  const nextEnd = end.getTime() + dir * span;
  if (dir === 1 && nextEnd >= now.getTime() - 30_000)
    return { type: "relative", duration: span };
  return {
    type: "absolute",
    start: new Date(start.getTime() + dir * span),
    end: new Date(nextEnd),
  };
}

export const sameRange = (a: TimeRange, b: TimeRange) =>
  a.type === b.type &&
  (a.type === "relative"
    ? a.duration === (b as typeof a).duration
    : a.type === "since"
      ? a.start.getTime() === (b as typeof a).start.getTime()
      : a.start.getTime() === (b as typeof a).start.getTime() &&
        a.end.getTime() === (b as typeof a).end.getTime());

/* ── Words ─────────────────────────────────────────────── */

const plural = (n: number, w: string) => `${n} ${w}${n === 1 ? "" : "s"}`;

/** "15 minutes", "4 hours", "7 days". */
export function durationWords(ms: number) {
  if (ms < HOUR || ms % HOUR) return plural(Math.round(ms / MINUTE), "minute");
  if (ms < 2 * DAY || ms % DAY) return plural(Math.round(ms / HOUR), "hour");
  if (ms % (7 * DAY) === 0 && ms / DAY >= 14)
    return plural(ms / (7 * DAY), "week");
  return plural(Math.round(ms / DAY), "day");
}

/** "15m", "2h", "3d", "1h 30m". */
export function durationShort(ms: number) {
  const m = Math.round(ms / MINUTE);
  if (m < 60) return `${m}m`;
  if (m < 48 * 60)
    return m % 60 ? `${Math.floor(m / 60)}h ${m % 60}m` : `${m / 60}h`;
  const d = Math.floor(m / 1440);
  const h = Math.round((m % 1440) / 60);
  return h ? `${d}d ${h}h` : `${d}d`;
}

const pad = (n: number) => String(n).padStart(2, "0");
const MONTHS = [
  "Jan",
  "Feb",
  "Mar",
  "Apr",
  "May",
  "Jun",
  "Jul",
  "Aug",
  "Sep",
  "Oct",
  "Nov",
  "Dec",
];
const DAYS = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

/** What the picker's pill says. */
export function formatTimeRange(
  range: TimeRange,
  {
    now = new Date(),
    timeZone,
    hour12 = false,
    compact = false,
  }: {
    now?: Date;
    timeZone?: string;
    hour12?: boolean;
    compact?: boolean;
  } = {},
) {
  const time = (w: { hour: number; minute: number }) =>
    hour12
      ? `${w.hour % 12 || 12}${w.minute ? `:${pad(w.minute)}` : ""}${w.hour < 12 ? "am" : "pm"}`
      : `${pad(w.hour)}:${pad(w.minute)}`;
  const today = wallAt(now.getTime(), timeZone);
  const yesterday = addDays(today, -1);
  const dayName = (w: Wall & { weekday?: number }) => {
    if (w.year === today.year && w.month === today.month && w.day === today.day)
      return "Today";
    if (
      w.year === yesterday.year &&
      w.month === yesterday.month &&
      w.day === yesterday.day
    )
      return "Yesterday";
    const date = `${w.day} ${MONTHS[w.month - 1]}${w.year !== today.year ? ` ${w.year}` : ""}`;
    return compact
      ? date
      : `${DAYS[new Date(Date.UTC(w.year, w.month - 1, w.day)).getUTCDay()]} ${date}`;
  };
  // Narrow places drop the spaces round the dash and the comma after the day.
  const dash = compact ? "–" : " – ";
  const comma = compact ? " " : ", ";
  if (range.type === "relative") return `Last ${durationWords(range.duration)}`;
  const s = wallAt(range.start.getTime(), timeZone);
  if (range.type === "since") {
    if (!s.hour && !s.minute)
      return dayName(s) === "Today" ? "Today so far" : `Since ${dayName(s)}`;
    return dayName(s) === "Today"
      ? `Since ${time(s)}`
      : `Since ${dayName(s)}${comma}${time(s)}`;
  }
  const e = wallAt(range.end.getTime(), timeZone);
  const sameDay = s.year === e.year && s.month === e.month && s.day === e.day;
  const nextDay = addDays(s, 1);
  // Whole days read as days: "Yesterday", "Mon 12 Oct – Wed 14 Oct".
  if (!s.hour && !s.minute && !e.hour && !e.minute) {
    if (
      nextDay.year === e.year &&
      nextDay.month === e.month &&
      nextDay.day === e.day
    )
      return dayName(s);
    return `${dayName(s)}${dash}${dayName(addDays(e, -1))}`;
  }
  if (sameDay) return `${dayName(s)}${comma}${time(s)}${dash}${time(e)}`;
  return `${dayName(s)} ${time(s)}${dash}${dayName(e)} ${time(e)}`;
}

/* ── Typed ranges ──────────────────────────────────────── */

const UNIT: Record<string, number> = {
  s: 1000,
  sec: 1000,
  secs: 1000,
  second: 1000,
  seconds: 1000,
  m: MINUTE,
  min: MINUTE,
  mins: MINUTE,
  minute: MINUTE,
  minutes: MINUTE,
  h: HOUR,
  hr: HOUR,
  hrs: HOUR,
  hour: HOUR,
  hours: HOUR,
  d: DAY,
  day: DAY,
  days: DAY,
  w: 7 * DAY,
  wk: 7 * DAY,
  week: 7 * DAY,
  weeks: 7 * DAY,
};
const DAY_WORDS: Record<string, number> = {
  sun: 0,
  sunday: 0,
  mon: 1,
  monday: 1,
  tue: 2,
  tues: 2,
  tuesday: 2,
  wed: 3,
  wednesday: 3,
  thu: 4,
  thur: 4,
  thurs: 4,
  thursday: 4,
  fri: 5,
  friday: 5,
  sat: 6,
  saturday: 6,
};
const MONTH_WORDS: Record<string, number> = Object.fromEntries(
  [
    "january",
    "february",
    "march",
    "april",
    "may",
    "june",
    "july",
    "august",
    "september",
    "october",
    "november",
    "december",
  ]
    .flatMap((m, i) => [
      [m, i + 1],
      [m.slice(0, 3), i + 1],
    ])
    .concat([["sept", 9]]),
);

function readTime(t: string): { hour: number; minute: number } | null {
  if (t === "noon" || t === "midday") return { hour: 12, minute: 0 };
  if (t === "midnight") return { hour: 0, minute: 0 };
  const m = t.match(/^(\d{1,2})(?:[:.h](\d{2}))?\s?(am|pm)?$/);
  if (!m) return null;
  let hour = +m[1];
  const minute = m[2] ? +m[2] : 0;
  if (m[3]) {
    if (hour < 1 || hour > 12) return null;
    hour = (hour % 12) + (m[3] === "pm" ? 12 : 0);
  } else if (!m[2] && hour > 24) return null;
  if (hour > 23 || minute > 59) return null;
  return { hour, minute };
}

/** A date word or numbers, relative to today. */
function readDate(t: string, today: Wall & { weekday: number }): Wall | null {
  if (!t || t === "today") return midnight(today);
  if (t === "yesterday") return midnight(addDays(today, -1));
  if (t in DAY_WORDS) {
    const back = (today.weekday - DAY_WORDS[t] + 7) % 7;
    return midnight(addDays(today, -back));
  }
  let m = t.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (m) return { year: +m[1], month: +m[2], day: +m[3], hour: 0, minute: 0 };
  m =
    t.match(/^(\d{1,2})(?:st|nd|rd|th)? (?:of )?([a-z]+)(?: (\d{4}))?$/) ??
    null;
  if (m && MONTH_WORDS[m[2]])
    return {
      year: m[3] ? +m[3] : today.year,
      month: MONTH_WORDS[m[2]],
      day: +m[1],
      hour: 0,
      minute: 0,
    };
  m = t.match(/^([a-z]+) (\d{1,2})(?:st|nd|rd|th)?(?:,? (\d{4}))?$/);
  if (m && MONTH_WORDS[m[1]])
    return {
      year: m[3] ? +m[3] : today.year,
      month: MONTH_WORDS[m[1]],
      day: +m[2],
      hour: 0,
      minute: 0,
    };
  return null;
}

const TIME_TAIL =
  /\s*(noon|midday|midnight|\d{1,2}(?:[:.h]\d{2})?\s?(?:am|pm)?)$/;
const ISO_MOMENT = /^\d{4}-\d{2}-\d{2}[t ]\d{2}:\d{2}/;

/** "yesterday 14:00", "16 oct", "9am", "2026-10-16 14:00" as a wall time. */
function readMoment(
  text: string,
  today: Wall & { weekday: number },
  fallbackDate?: Wall,
): { wall: Wall; dated: boolean; timed: boolean } | null {
  const t = text.trim();
  if (ISO_MOMENT.test(t)) {
    const [d, tm] = t.split(/[t ]/);
    const date = readDate(d, today);
    const time = readTime(tm.slice(0, 5));
    return date && time
      ? { wall: { ...date, ...time }, dated: true, timed: true }
      : null;
  }
  const tail = t.match(TIME_TAIL);
  let datePart = t;
  let time: { hour: number; minute: number } | null = null;
  if (tail) {
    const candidate = readTime(tail[1].replace(/\s/g, ""));
    // "16 oct" ends in digits that aren't a time; only take the tail when what's left is a date (or nothing).
    const rest = t.slice(0, tail.index).trim().replace(/,$/, "");
    if (candidate && (rest === "" || readDate(rest, today))) {
      time = candidate;
      datePart = rest;
    }
  }
  const date = datePart
    ? readDate(datePart, today)
    : (fallbackDate ?? midnight(today));
  if (!date) return null;
  return {
    wall: { ...date, ...(time ?? { hour: 0, minute: 0 }) },
    dated: Boolean(datePart),
    timed: Boolean(time),
  };
}

/** Reads a typed range, or null. */
export function parseTimeRange(
  input: string,
  { now = new Date(), timeZone }: { now?: Date; timeZone?: string } = {},
): TimeRange | null {
  const t = input
    .toLowerCase()
    .trim()
    .replace(/\s+/g, " ")
    .replace(/[–—]/g, "-");
  if (!t) return null;
  const today = wallAt(now.getTime(), timeZone);
  const at = (w: Wall) => new Date(fromWall(w, timeZone));

  // Durations: 15m, 2 hours, last 7 days.
  const dur = t.match(/^(?:last |past )?(\d+(?:\.\d+)?) ?([a-z]+)$/);
  if (dur && UNIT[dur[2]])
    return { type: "relative", duration: Math.round(+dur[1] * UNIT[dur[2]]) };
  const bare = t.match(
    /^(?:last (minute|hour|day)|past (minute|hour|day|week))$/,
  );
  if (bare) return { type: "relative", duration: UNIT[bare[1] ?? bare[2]] };

  if (t === "today") return { type: "since", start: at(midnight(today)) };
  if (t === "yesterday")
    return {
      type: "absolute",
      start: at(midnight(addDays(today, -1))),
      end: at(midnight(today)),
    };
  if (t === "this week")
    return {
      type: "since",
      start: at(midnight(addDays(today, -((today.weekday + 6) % 7)))),
    };
  if (t === "last week") {
    const monday = midnight(addDays(today, -((today.weekday + 6) % 7)));
    return {
      type: "absolute",
      start: at(addDays(monday, -7)),
      end: at(monday),
    };
  }
  if (t === "this month")
    return { type: "since", start: at({ ...midnight(today), day: 1 }) };
  if (t === "last month") {
    const first = { ...midnight(today), day: 1 };
    const prev = new Date(Date.UTC(first.year, first.month - 2, 1));
    return {
      type: "absolute",
      start: at({
        ...first,
        year: prev.getUTCFullYear(),
        month: prev.getUTCMonth() + 1,
      }),
      end: at(first),
    };
  }

  // Since a moment: since 9, since monday, since 16 oct 14:00.
  const since = t.match(/^(?:since|from) (.+)$/);
  if (since && !/ (?:to|until|-) /.test(since[1]) && !/\d-\d/.test(since[1])) {
    const m = readMoment(since[1], today);
    if (!m) return null;
    const start = at(m.wall);
    return start.getTime() < now.getTime() ? { type: "since", start } : null;
  }

  // A span: "a - b", "a to b", or two times joined by a bare hyphen ("yesterday 14:00-16:00").
  const body = t.replace(/^(?:from|between) /, "");
  let span = body.split(/ (?:-|to|until|and) /);
  if (span.length !== 2) {
    const tight = body.match(
      /^(.*?\d{1,2}(?:[:.]\d{2})?\s?(?:am|pm)?)-(\d{1,2}(?:[:.]\d{2})?\s?(?:am|pm)?)$/,
    );
    span = tight ? [tight[1], tight[2]] : [];
  }
  if (span.length === 2) {
    // "yesterday 14:00-16:00": the date on the left carries over to a time-only right side.
    const a = readMoment(span[0], today);
    if (!a) return null;
    const b = readMoment(span[1], today, midnight(a.wall));
    if (!b) return null;
    let start = a.wall;
    let end = b.wall;
    if (!b.timed && b.dated) end = addDays(end, 1); // "16 oct - 17 oct" includes the 17th
    if (fromWall(end, timeZone) <= fromWall(start, timeZone))
      end = addDays(end, 1); // 22:00-02:00 runs past midnight
    // Times without a date that haven't happened yet today mean yesterday's.
    if (!a.dated && fromWall(start, timeZone) > now.getTime()) {
      start = addDays(start, -1);
      end = addDays(end, -1);
    }
    return { type: "absolute", start: at(start), end: at(end) };
  }

  // A single day: monday, 16 oct.
  const day = readMoment(t, today);
  if (day && day.dated && !day.timed)
    return {
      type: "absolute",
      start: at(day.wall),
      end: at(addDays(day.wall, 1)),
    };
  if (day && day.timed && !day.dated)
    return { type: "since", start: at(day.wall) };
  return null;
}

"use client";

import * as React from "react";
import { createPortal } from "react-dom";
import { TextMorph } from "./text-morph";
import { TimeBrush, type TimeBrushProps } from "./time-brush";
import {
  DAY,
  HOUR,
  MINUTE,
  durationShort,
  formatTimeRange,
  isLive,
  parseTimeRange,
  resolveTimeRange,
  sameRange,
  stepTimeRange,
  type TimeRange,
} from "./time-range-parse";

/* ─────────────────────────────────────────────────────────
 * TIME RANGE PICKER: "Last 15 minutes ▾" for logs and metrics
 *
 *   plate    one thin line plate: ‹ earlier, the range, › later,
 *            and Live. The range's words morph as it changes
 *   step     ‹ and › move the window by its own length; stepping
 *            back from "Last 1 hour" fixes it to the hour before,
 *            and stepping forward into now makes it live again
 *   live     the dot breathes while the range follows now;
 *            Paused freezes it where it is
 *   open     the panel unfolds from the plate's edge with the
 *            field focused: type 45m, yesterday, since 9 or
 *            14:00–16:00 and the line under it says what it
 *            means before you press Enter
 *   quick    a highlight glides over the quick ranges; the
 *            current one carries a drawn check; ranges you typed
 *            come back as Recent
 *
 * Pair it with Time brush, which turns a drag across any chart
 * into a range.
 * ───────────────────────────────────────────────────────── */

export type { TimeRange };
export { TimeBrush, type TimeBrushProps };
export { formatTimeRange, parseTimeRange, resolveTimeRange, stepTimeRange };

export interface TimeRangePreset {
  label: string;
  /** A range, or one worked out from now (Today, Yesterday). */
  range: TimeRange | ((now: Date, timeZone?: string) => TimeRange);
}

export interface TimeRangePickerProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "defaultValue" | "onChange"
> {
  value?: TimeRange;
  defaultValue?: TimeRange;
  /** The range, and the start and end it covers right now. */
  onValueChange?: (
    range: TimeRange,
    resolved: { start: Date; end: Date },
  ) => void;
  presets?: TimeRangePreset[];
  /** Read and show times in this IANA zone; the viewer's own by default. */
  timeZone?: string;
  hour12?: boolean;
  /** Which edge of the plate the panel lines up with. */
  align?: "start" | "end";
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Accessible name, e.g. "Time range for logs". */
  label?: string;
  disabled?: boolean;
}

const rel = (duration: number): TimeRange => ({ type: "relative", duration });
export const TIME_RANGE_PRESETS: TimeRangePreset[] = [
  { label: "Last 5 minutes", range: rel(5 * MINUTE) },
  { label: "Last 15 minutes", range: rel(15 * MINUTE) },
  { label: "Last 1 hour", range: rel(HOUR) },
  { label: "Last 4 hours", range: rel(4 * HOUR) },
  { label: "Last 24 hours", range: rel(DAY) },
  { label: "Last 7 days", range: rel(7 * DAY) },
  {
    label: "Today so far",
    range: (now, tz) => parseTimeRange("today", { now, timeZone: tz })!,
  },
  {
    label: "Yesterday",
    range: (now, tz) => parseTimeRange("yesterday", { now, timeZone: tz })!,
  },
];

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/50";
const TOKENS = [
  "--background",
  "--foreground",
  "--popover",
  "--popover-foreground",
  "--border",
  "--accent",
  "--accent-foreground",
  "--primary",
  "--primary-foreground",
  "--muted",
  "--muted-foreground",
  "--ring",
];
const HINT = "Try 45m, yesterday, since 9 or 14:00–16:00";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

// Phones get the tighter label and a plate without the clock or the word Live.
const narrowQuery = "(max-width: 480px)";
const subscribeNarrow = (onChange: () => void) => {
  const query = window.matchMedia(narrowQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useNarrow = () =>
  React.useSyncExternalStore(
    subscribeNarrow,
    () => window.matchMedia(narrowQuery).matches,
    () => false,
  );

function zoneLabel(timeZone?: string) {
  try {
    const zone = timeZone ?? Intl.DateTimeFormat().resolvedOptions().timeZone;
    const off = new Intl.DateTimeFormat("en-US", {
      timeZone: zone,
      timeZoneName: "shortOffset",
    })
      .formatToParts(new Date())
      .find((p) => p.type === "timeZoneName")
      ?.value.replace("GMT", "UTC");
    return `${zone === "UTC" ? "UTC" : (zone.split("/").pop() ?? zone).replace(/_/g, " ")}${off && zone !== "UTC" ? ` · ${off}` : ""}`;
  } catch {
    return "";
  }
}

function Arrow({ dir }: { dir: -1 | 1 }) {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      aria-hidden="true"
      className="size-3.5"
    >
      <path
        d={dir < 0 ? "M9.75 4.5 6.25 8l3.5 3.5" : "M6.25 4.5 9.75 8l-3.5 3.5"}
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

/** A sentence that changes crossfades whole. */
function Line({
  text,
  reduced,
  className = "",
}: {
  text: string;
  reduced: boolean;
  className?: string;
}) {
  const [shown, setShown] = React.useState({ text, key: 0 });
  const [leaving, setLeaving] = React.useState<{ text: string; key: number }[]>(
    [],
  );
  if (text !== shown.text) {
    if (shown.text && !reduced) setLeaving((l) => [...l.slice(-2), shown]);
    setShown({ text, key: shown.key + 1 });
  }
  return (
    <span className={`relative block ${className}`}>
      <span
        key={shown.key}
        className="block truncate"
        ref={(el) => {
          if (!el || reduced || shown.key === 0 || el.dataset.in) return;
          el.dataset.in = "1";
          el.animate(
            [
              {
                opacity: 0,
                transform: "translateY(0.3em)",
                filter: "blur(4px)",
              },
              { opacity: 1, transform: "none", filter: "blur(0px)" },
            ],
            { duration: 340, delay: 40, easing: EASE, fill: "backwards" },
          );
        }}
      >
        {shown.text || " "}
      </span>
      {leaving.map((l) => (
        <span
          key={l.key}
          aria-hidden="true"
          className="pointer-events-none absolute inset-x-0 top-0 block truncate"
          ref={(el) => {
            if (!el || el.dataset.out) return;
            el.dataset.out = "1";
            el.animate(
              [
                { opacity: 1, filter: "blur(0px)" },
                {
                  opacity: 0,
                  transform: "translateY(-0.3em)",
                  filter: "blur(4px)",
                },
              ],
              { duration: 160, easing: EASE, fill: "forwards" },
            ).onfinish = () =>
              setLeaving((all) => all.filter((x) => x.key !== l.key));
          }}
        >
          {l.text}
        </span>
      ))}
    </span>
  );
}

type Phase = "closed" | "opening" | "open" | "closing";

export function TimeRangePicker({
  value,
  defaultValue = rel(HOUR),
  onValueChange,
  presets = TIME_RANGE_PRESETS,
  timeZone,
  hour12 = false,
  align = "end",
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  label = "Time range",
  disabled = false,
  className = "",
  ...props
}: TimeRangePickerProps) {
  const uid = React.useId();
  const reduced = useReducedMotion();
  const narrow = useNarrow();
  const [own, setOwn] = React.useState(defaultValue);
  const range = value ?? own;
  const [now, setNow] = React.useState(() => new Date());
  const [phase, setPhase] = React.useState<Phase>(() =>
    (openProp ?? defaultOpen) ? "opening" : "closed",
  );
  const [fit, setFit] = React.useState({
    x: 0,
    y: 0,
    w: 320,
    up: false,
    theme: {} as Record<string, string>,
  });
  const [typed, setTyped] = React.useState("");
  const [active, setActive] = React.useState(-1);
  const [mark, setMark] = React.useState({
    x: 0,
    y: 0,
    w: 0,
    h: 0,
    on: false,
    slide: false,
  });
  const [recent, setRecent] = React.useState<TimeRange[]>([]);
  const [refused, setRefused] = React.useState(false);
  const [announce, setAnnounce] = React.useState("");
  const anchorRef = React.useRef<HTMLDivElement>(null);
  const triggerRef = React.useRef<HTMLButtonElement>(null);
  const surfaceRef = React.useRef<HTMLDivElement>(null);
  const inputRef = React.useRef<HTMLInputElement>(null);
  const fieldRef = React.useRef<HTMLDivElement>(null);
  const presetRefs = React.useRef<(HTMLButtonElement | null)[]>([]);
  const mounted = phase !== "closed";
  const expanded = phase === "open";
  const live = isLive(range);

  // "Today" and "Last 1 hour" are about now: look at the clock once a minute.
  React.useEffect(() => {
    let t = 0;
    const tick = () => {
      setNow(new Date());
      t = window.setTimeout(tick, 60_000 - (Date.now() % 60_000) + 50);
    };
    t = window.setTimeout(tick, 60_000 - (Date.now() % 60_000) + 50);
    return () => window.clearTimeout(t);
  }, []);

  const words = formatTimeRange(range, {
    now,
    timeZone,
    hour12,
    compact: narrow,
  });
  const resolved = resolveTimeRange(range, now);
  const span = resolved.end.getTime() - resolved.start.getTime();
  const presetRanges = React.useMemo(
    () =>
      presets.map((p) =>
        typeof p.range === "function" ? p.range(now, timeZone) : p.range,
      ),
    [presets, now, timeZone],
  );
  const currentPreset = presetRanges.findIndex((r) => sameRange(r, range));
  const parsed = typed.trim() ? parseTimeRange(typed, { now, timeZone }) : null;

  const commit = (next: TimeRange, how?: "typed") => {
    const at = new Date();
    if (value === undefined) setOwn(next);
    onValueChange?.(next, resolveTimeRange(next, at));
    setAnnounce(formatTimeRange(next, { now: at, timeZone, hour12 }));
    if (how === "typed" && !presetRanges.some((r) => sameRange(r, next)))
      setRecent((list) =>
        [next, ...list.filter((r) => !sameRange(r, next))].slice(0, 3),
      );
  };

  /* ── Panel ── */

  const place = React.useCallback(() => {
    const anchor = anchorRef.current;
    if (!anchor) return;
    const r = anchor.getBoundingClientRect();
    const vw = document.documentElement.clientWidth;
    const vh = window.innerHeight;
    const w = Math.min(320, vw - 16);
    const x = Math.min(
      Math.max(8, align === "end" ? r.right - w : r.left),
      vw - 8 - w,
    );
    const up = vh - r.bottom < 380 && r.top > vh - r.bottom;
    const cs = getComputedStyle(anchor);
    const theme: Record<string, string> = {
      colorScheme: cs.colorScheme,
      fontFamily: cs.fontFamily,
    };
    for (const t of TOKENS) {
      const v = cs.getPropertyValue(t);
      if (v) theme[t] = v;
    }
    setFit({ x, y: up ? vh - r.top + 6 : r.bottom + 6, w, up, theme });
  }, [align]);

  const fresh = () => {
    setTyped("");
    setRefused(false);
    setActive(-1);
    setMark((m) => ({ ...m, on: false, slide: false }));
    setPhase(reduced ? "open" : "opening");
  };
  const begin = () => {
    place();
    fresh();
  };
  const end = React.useCallback(
    (refocus = true) => {
      if (refocus) triggerRef.current?.focus({ preventScroll: true });
      setPhase((p) => (p === "closed" ? p : reduced ? "closed" : "closing"));
    },
    [reduced],
  );
  const request = (next: boolean, refocus = true) => {
    if (openProp === undefined) (next ? begin : () => end(refocus))();
    onOpenChange?.(next);
  };

  // Controlled: follow the open prop as soon as it changes (the panel is placed once it's mounted, below).
  const [seenOpenProp, setSeenOpenProp] = React.useState(openProp);
  if (openProp !== seenOpenProp) {
    setSeenOpenProp(openProp);
    if (openProp && !mounted) fresh();
    if (openProp === false && mounted) setPhase(reduced ? "closed" : "closing");
  }

  React.useLayoutEffect(() => {
    if (mounted) place();
  }, [mounted, place]);

  // Folding away takes 240ms, however it was closed.
  React.useEffect(() => {
    if (phase !== "closing") return;
    const done = window.setTimeout(() => setPhase("closed"), 240);
    return () => window.clearTimeout(done);
  }, [phase]);

  React.useLayoutEffect(() => {
    if (phase !== "opening") return;
    place();
    inputRef.current?.focus({ preventScroll: true });
    let inner = 0;
    const outer = requestAnimationFrame(
      () => (inner = requestAnimationFrame(() => setPhase("open"))),
    );
    return () => {
      cancelAnimationFrame(outer);
      cancelAnimationFrame(inner);
    };
  }, [phase, place]);

  React.useEffect(() => {
    if (!mounted) return;
    const inside = (n: Node) =>
      Boolean(
        anchorRef.current?.contains(n) || surfaceRef.current?.contains(n),
      );
    const onDown = (e: PointerEvent) => {
      if (!inside(e.target as Node)) request(false, false);
    };
    let frame = 0;
    const follow = (e: Event) => {
      if (e.target instanceof Node && surfaceRef.current?.contains(e.target))
        return;
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(place);
    };
    document.addEventListener("pointerdown", onDown);
    window.addEventListener("scroll", follow, true);
    window.addEventListener("resize", follow);
    return () => {
      cancelAnimationFrame(frame);
      document.removeEventListener("pointerdown", onDown);
      window.removeEventListener("scroll", follow, true);
      window.removeEventListener("resize", follow);
    };
  });

  // The highlight glides to the quick range under the pointer or the arrows.
  React.useLayoutEffect(() => {
    if (!mounted) return;
    const el = presetRefs.current[active];
    setMark((m) =>
      el
        ? m.x === el.offsetLeft && m.y === el.offsetTop && m.on
          ? m
          : {
              x: el.offsetLeft,
              y: el.offsetTop,
              w: el.offsetWidth,
              h: el.offsetHeight,
              on: true,
              slide: m.on,
            }
        : m.on
          ? { ...m, on: false, slide: false }
          : m,
    );
  }, [active, mounted]);

  const choose = (i: number) => {
    commit(presetRanges[i]);
    request(false);
  };
  const applyTyped = () => {
    if (!parsed) {
      setRefused(true);
      if (!reduced)
        fieldRef.current?.animate(
          [
            { transform: "none" },
            { transform: "translateX(-4px)" },
            { transform: "translateX(4px)" },
            { transform: "translateX(-2px)" },
            { transform: "none" },
          ],
          { duration: 380, easing: "ease-out" },
        );
      return;
    }
    commit(parsed, "typed");
    request(false);
  };

  const onInputKey = (e: React.KeyboardEvent<HTMLInputElement>) => {
    const n = presets.length;
    const go = (i: number) => {
      e.preventDefault();
      setActive(i);
    };
    if (e.key === "ArrowDown") go(active < 0 ? 0 : Math.min(n - 1, active + 2));
    else if (e.key === "ArrowUp") go(active - 2 < 0 ? -1 : active - 2);
    else if (e.key === "ArrowRight" && active >= 0)
      go(Math.min(n - 1, active + 1));
    else if (e.key === "ArrowLeft" && active >= 0) go(Math.max(0, active - 1));
    else if (e.key === "Enter") {
      e.preventDefault();
      if (active >= 0 && !typed.trim()) choose(active);
      else applyTyped();
    } else if (e.key === "Escape") {
      e.preventDefault();
      e.stopPropagation();
      request(false);
    } else if (e.key === "Tab") {
      e.preventDefault();
      request(false);
    }
  };

  const preview = !typed.trim()
    ? HINT
    : parsed
      ? (() => {
          const r = resolveTimeRange(parsed, now);
          return `${formatTimeRange(parsed, { now, timeZone, hour12 })} · ${durationShort(r.end.getTime() - r.start.getTime())}${isLive(parsed) ? " · live" : ""}`;
        })()
      : refused
        ? `Couldn’t read that. ${HINT}.`
        : HINT;

  const segment = `flex shrink-0 items-center justify-center text-muted-foreground transition-colors hover:bg-accent hover:text-foreground disabled:cursor-default disabled:opacity-35 disabled:hover:bg-transparent ${FOCUS}`;

  return (
    <div
      ref={anchorRef}
      className={`relative inline-flex max-w-full ${className}`}
      {...props}
    >
      <div
        role="group"
        aria-label={label}
        className={`inline-flex h-8 max-w-full items-stretch overflow-hidden rounded-full border border-border bg-background text-[12.5px] ${disabled ? "opacity-60" : ""}`}
      >
        <button
          type="button"
          aria-label={`Earlier: the ${durationShort(span)} before`}
          title="Earlier"
          disabled={disabled}
          onClick={() => commit(stepTimeRange(range, -1, new Date()))}
          className={`w-8 cursor-pointer max-[480px]:w-7 ${segment}`}
        >
          <Arrow dir={-1} />
        </button>
        <span aria-hidden="true" className="my-2 w-px shrink-0 bg-border" />
        <button
          ref={triggerRef}
          type="button"
          disabled={disabled}
          aria-haspopup="dialog"
          aria-expanded={expanded}
          aria-controls={mounted ? `${uid}-panel` : undefined}
          aria-label={`${label}: ${words}`}
          onClick={() => request(!(phase === "open" || phase === "opening"))}
          onKeyDown={(e) => {
            if (e.key === "ArrowDown") {
              e.preventDefault();
              request(true);
            }
          }}
          className={`flex min-w-0 cursor-pointer items-center gap-1.5 px-2.5 font-medium transition-colors hover:bg-accent disabled:cursor-default ${expanded ? "bg-accent" : ""} ${FOCUS}`}
        >
          <svg
            viewBox="0 0 16 16"
            fill="none"
            aria-hidden="true"
            className="size-3.5 shrink-0 text-muted-foreground max-[480px]:hidden"
          >
            <circle
              cx="8"
              cy="8"
              r="5.75"
              stroke="currentColor"
              strokeWidth="1.4"
            />
            <path
              d="M8 5.25V8l1.75 1.25"
              stroke="currentColor"
              strokeWidth="1.4"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
          <span className="min-w-0 overflow-hidden whitespace-nowrap">
            <TextMorph>{words}</TextMorph>
          </span>
          <svg
            viewBox="0 0 16 16"
            fill="none"
            aria-hidden="true"
            className="size-3 shrink-0 text-muted-foreground"
            style={{
              transform: expanded ? "rotate(180deg)" : "none",
              transition: reduced ? "none" : `transform 320ms ${EASE}`,
            }}
          >
            <path
              d="M4.5 6.25 8 9.75l3.5-3.5"
              stroke="currentColor"
              strokeWidth="1.6"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </button>
        <span aria-hidden="true" className="my-2 w-px shrink-0 bg-border" />
        <button
          type="button"
          aria-label={
            live
              ? "Later: already showing the latest"
              : `Later: the ${durationShort(span)} after`
          }
          title={live ? "Already showing the latest" : "Later"}
          disabled={disabled || live}
          onClick={() => commit(stepTimeRange(range, 1, new Date()))}
          className={`w-8 cursor-pointer max-[480px]:w-7 ${segment}`}
        >
          <Arrow dir={1} />
        </button>
        <span aria-hidden="true" className="my-2 w-px shrink-0 bg-border" />
        <button
          type="button"
          aria-pressed={live}
          aria-label={live ? "Live: pause" : "Paused: go live"}
          disabled={disabled}
          onClick={() => {
            const at = new Date();
            const r = resolveTimeRange(range, at);
            commit(
              live
                ? { type: "absolute", start: r.start, end: r.end }
                : rel(r.end.getTime() - r.start.getTime()),
            );
          }}
          className={`cursor-pointer gap-1.5 pl-2.5 pr-3 font-medium max-[480px]:px-2.5 ${segment} ${live ? "text-foreground" : ""}`}
        >
          <span
            aria-hidden="true"
            className="relative flex size-2 items-center justify-center"
          >
            <span
              className={`absolute inset-0 rounded-full bg-emerald-500 ${live && !reduced ? "animate-[ui-breathe_2.4s_ease-in-out_infinite]" : ""}`}
              style={{
                opacity: live ? 1 : 0,
                transform: live ? undefined : "scale(0.4)",
                transition: reduced
                  ? "none"
                  : `opacity 260ms ${EASE}, transform 380ms ${EASE}`,
              }}
            />
            <span
              className="absolute inset-0 rounded-full shadow-[inset_0_0_0_1.5px_currentColor]"
              style={{
                opacity: live ? 0 : 0.8,
                transition: reduced ? "none" : `opacity 260ms ${EASE}`,
              }}
            />
          </span>
          <span className="max-[480px]:hidden">
            <TextMorph>{live ? "Live" : "Paused"}</TextMorph>
          </span>
        </button>
      </div>

      {mounted &&
        createPortal(
          <div
            ref={surfaceRef}
            id={`${uid}-panel`}
            role="dialog"
            aria-label={label}
            onMouseDown={(e) => {
              if (!(e.target as HTMLElement).matches("input"))
                e.preventDefault();
            }}
            className="fixed z-[60] overflow-hidden rounded-[16px] border border-border bg-popover p-1.5 text-popover-foreground"
            style={{
              ...fit.theme,
              left: fit.x,
              [fit.up ? "bottom" : "top"]: fit.y,
              width: fit.w,
              clipPath: expanded
                ? "inset(0px 0px 0px 0px round 16px)"
                : fit.up
                  ? "inset(100% 0px 0px 0px round 16px)"
                  : "inset(0px 0px 100% 0px round 16px)",
              opacity: expanded ? 1 : 0,
              transition: reduced
                ? "none"
                : phase === "closing"
                  ? `clip-path 220ms ${EASE}, opacity 180ms ${EASE} 40ms`
                  : `clip-path 380ms ${EASE}, opacity 200ms ${EASE}`,
            }}
          >
            <div
              ref={fieldRef}
              className="flex h-9 items-center gap-2 rounded-[11px] px-2.5 transition-shadow duration-200"
              style={{
                boxShadow: `inset 0 0 0 1px ${refused && !parsed ? "color-mix(in oklab, #ef4444 45%, transparent)" : "color-mix(in oklab, var(--ring) 45%, var(--border))"}`,
              }}
            >
              <svg
                viewBox="0 0 16 16"
                fill="none"
                aria-hidden="true"
                className="size-3.5 shrink-0 text-muted-foreground"
              >
                <path
                  d="M3 4.5h10M3 8h6M3 11.5h8"
                  stroke="currentColor"
                  strokeWidth="1.4"
                  strokeLinecap="round"
                />
              </svg>
              <input
                ref={inputRef}
                value={typed}
                onChange={(e) => {
                  setTyped(e.target.value);
                  setRefused(false);
                  if (e.target.value) setActive(-1);
                }}
                onKeyDown={onInputKey}
                placeholder="Type a range"
                aria-label="Type a range"
                aria-describedby={`${uid}-preview`}
                aria-activedescendant={
                  active >= 0 ? `${uid}-p${active}` : undefined
                }
                autoComplete="off"
                spellCheck={false}
                className="h-full min-w-0 flex-1 bg-transparent text-[13px] outline-none placeholder:text-muted-foreground [@media(pointer:coarse)]:text-[16px]"
              />
              {parsed && (
                <span className="shrink-0 rounded-full px-1.5 font-mono text-[10.5px] text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)]">
                  ↵
                </span>
              )}
            </div>
            <p
              id={`${uid}-preview`}
              className={`px-1 pb-1 pt-1.5 text-[11.5px] transition-colors duration-200 ${refused && !parsed ? "text-red-600 dark:text-red-400" : parsed ? "text-foreground" : "text-muted-foreground"}`}
            >
              <Line text={preview} reduced={reduced} />
            </p>

            <div
              role="listbox"
              aria-label="Quick ranges"
              className="relative mt-1 grid grid-cols-2 gap-0.5 border-t border-border pt-1.5"
              onMouseLeave={() => setActive(-1)}
            >
              <span
                aria-hidden="true"
                className="pointer-events-none absolute left-0 top-0 rounded-[9px] bg-accent"
                style={{
                  width: mark.w,
                  height: mark.h,
                  transform: `translate(${mark.x}px, ${mark.y}px)`,
                  opacity: mark.on ? 1 : 0,
                  transition: reduced
                    ? "none"
                    : `${mark.slide ? `transform 220ms ${EASE}, width 220ms ${EASE}, ` : ""}opacity 160ms ${EASE}`,
                }}
              />
              {presets.map((p, i) => {
                const on = i === currentPreset;
                return (
                  <button
                    key={p.label}
                    ref={(el) => {
                      presetRefs.current[i] = el;
                    }}
                    id={`${uid}-p${i}`}
                    type="button"
                    role="option"
                    aria-selected={on}
                    tabIndex={-1}
                    onPointerMove={() => active !== i && setActive(i)}
                    onClick={() => choose(i)}
                    className={`relative flex h-8 cursor-pointer items-center justify-between gap-2 rounded-[9px] px-2 text-left text-[12.5px] ${on ? "font-medium text-foreground" : "text-muted-foreground"}`}
                  >
                    <span className="truncate">{p.label}</span>
                    <svg
                      viewBox="0 0 16 16"
                      fill="none"
                      aria-hidden="true"
                      className="size-3 shrink-0 text-foreground"
                    >
                      <path
                        d="M3.5 8.5 6.5 11.5 12.5 4.5"
                        stroke="currentColor"
                        strokeWidth="1.9"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        pathLength={1}
                        strokeDasharray={1}
                        style={{
                          strokeDashoffset: on && expanded ? 0 : 1,
                          transition: reduced
                            ? "none"
                            : `stroke-dashoffset 380ms ${EASE} 160ms`,
                        }}
                      />
                    </svg>
                  </button>
                );
              })}
            </div>

            {recent.length > 0 && (
              <div className="mt-1.5 border-t border-border px-1 pt-2">
                <p className="text-[11px] text-muted-foreground">Recent</p>
                <div className="mt-1.5 flex flex-wrap gap-1 pb-0.5">
                  {recent.map((r) => (
                    <button
                      key={formatTimeRange(r, { now, timeZone, hour12 })}
                      type="button"
                      tabIndex={-1}
                      onClick={() => {
                        commit(r, "typed");
                        request(false);
                      }}
                      className="h-6 max-w-full cursor-pointer truncate rounded-full px-2 text-[11.5px] text-foreground shadow-[inset_0_0_0_1px_var(--border)] transition-colors hover:bg-accent"
                    >
                      {formatTimeRange(r, { now, timeZone, hour12 })}
                    </button>
                  ))}
                </div>
              </div>
            )}

            <p className="mt-1.5 border-t border-border px-1 pb-0.5 pt-2 text-[11px] text-muted-foreground">
              Times in {zoneLabel(timeZone)}
            </p>
          </div>,
          document.body,
        )}

      <span className="sr-only" role="status" aria-live="polite">
        {announce}
      </span>
    </div>
  );
}

"use client";

import * as React from "react";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * TOAST STACK: notifications that keep their place in line
 *
 *   arrive     a toast rises in from the edge through a blur and
 *              the ones before it step back into a thin line stack
 *   stack      three peek out behind the newest, each a little
 *              smaller; hover or focus fans them out into a list
 *   time       a thin line drains along the bottom; hovering or a
 *              hidden tab pauses it
 *   promise    one toast from start to finish: a spinner while it
 *              works, then the words morph and a check draws
 *              itself (or an alert, and it shakes)
 *   action     Undo and friends sit on the right
 *   dismiss    swipe it away, or the close button; the rest close
 *              up behind it
 *
 * Call toast() from anywhere; render <Toaster /> once.
 * ───────────────────────────────────────────────────────── */

export type ToastType = "default" | "success" | "error" | "info" | "loading";
export type ToastPosition =
  | "bottom-right"
  | "bottom-center"
  | "bottom-left"
  | "top-right"
  | "top-center"
  | "top-left";

export interface ToastOptions {
  description?: string;
  type?: ToastType;
  /** How long it stays (ms). Loading toasts stay until they settle. */
  duration?: number;
  action?: { label: string; onClick: () => void };
  /** Reuse an id to update a toast in place. */
  id?: string;
}

interface ToastData extends ToastOptions {
  id: string;
  title: string;
  type: ToastType;
  duration: number;
  /** Bumped when it changes, so its timer starts over. */
  version: number;
  dismissed: boolean;
}

/* ── The store: toast() works from anywhere, <Toaster /> renders it ── */

let toasts: ToastData[] = [];
let counter = 0;
const listeners = new Set<() => void>();
const emit = () => listeners.forEach((l) => l());
const DEFAULT_DURATION = 4000;

function upsert(title: string, options: ToastOptions = {}): string {
  const id = options.id ?? `t${++counter}`;
  const existing = toasts.find((t) => t.id === id);
  const type = options.type ?? "default";
  const next: ToastData = {
    ...existing,
    ...options,
    id,
    title,
    type,
    duration: options.duration ?? existing?.duration ?? DEFAULT_DURATION,
    version: (existing?.version ?? 0) + 1,
    dismissed: false,
  };
  toasts = existing
    ? toasts.map((t) => (t.id === id ? next : t))
    : [next, ...toasts];
  emit();
  return id;
}

export function toast(title: string, options?: ToastOptions) {
  return upsert(title, options);
}
toast.success = (title: string, options?: Omit<ToastOptions, "type">) =>
  upsert(title, { ...options, type: "success" });
toast.error = (title: string, options?: Omit<ToastOptions, "type">) =>
  upsert(title, { ...options, type: "error" });
toast.info = (title: string, options?: Omit<ToastOptions, "type">) =>
  upsert(title, { ...options, type: "info" });
toast.loading = (title: string, options?: Omit<ToastOptions, "type">) =>
  upsert(title, { ...options, type: "loading" });
/** One toast that follows a promise: loading, then success or error, morphing in place. */
toast.promise = <T,>(
  promise: Promise<T>,
  messages: {
    loading: string;
    success: string | ((value: T) => string);
    error: string | ((error: unknown) => string);
    description?: string;
  },
) => {
  const id = upsert(messages.loading, {
    type: "loading",
    description: messages.description,
  });
  promise.then(
    (value) =>
      upsert(
        typeof messages.success === "function"
          ? messages.success(value)
          : messages.success,
        { id, type: "success" },
      ),
    (error) =>
      upsert(
        typeof messages.error === "function"
          ? messages.error(error)
          : messages.error,
        { id, type: "error" },
      ),
  );
  return promise;
};
toast.dismiss = (id?: string) => {
  toasts = toasts.map((t) =>
    id === undefined || t.id === id ? { ...t, dismissed: true } : t,
  );
  emit();
};
const remove = (id: string) => {
  toasts = toasts.filter((t) => t.id !== id);
  emit();
};
const subscribe = (listener: () => void) => {
  listeners.add(listener);
  return () => listeners.delete(listener);
};
const getToasts = () => toasts;
const getNone = () => [] as ToastData[];

/* ── Rendering ── */

export interface ToasterProps extends React.HTMLAttributes<HTMLElement> {
  position?: ToastPosition;
  /** How many show behind the newest when stacked. */
  visible?: number;
  /** Keyboard shortcut that moves focus to the toasts (with Alt). */
  hotkey?: string;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const GAP = 10;
const PEEK = 10;
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Icons trade places through a blur: the old one shrinks away as the new one grows in. */
const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 240ms ${EASE}, transform 360ms ${EASE}, filter 240ms ${EASE}`,
});

function StatusIcon({ type, reduced }: { type: ToastType; reduced: boolean }) {
  const layer = "absolute inset-0 flex items-center justify-center";
  return (
    <span
      aria-hidden="true"
      className="relative flex h-5 shrink-0 items-center justify-center"
      style={{
        width: type === "default" ? 0 : 16,
        marginRight: type === "default" ? 0 : 10,
        transition: reduced
          ? "none"
          : `width 320ms ${EASE}, margin 320ms ${EASE}`,
      }}
    >
      <span className={layer} style={swap(type === "loading", reduced)}>
        <span
          className={`size-3.5 rounded-full border-[1.5px] border-border border-t-foreground/70 motion-reduce:animate-none ${type === "loading" ? "animate-spin" : ""}`}
        />
      </span>
      <span
        className={`${layer} text-emerald-600 dark:text-emerald-400`}
        style={swap(type === "success", reduced)}
      >
        <svg viewBox="0 0 16 16" fill="none" className="size-4">
          <path
            d="M3.5 8.5 6.5 11.5 12.5 4.5"
            stroke="currentColor"
            strokeWidth="1.9"
            strokeLinecap="round"
            strokeLinejoin="round"
            pathLength={1}
            strokeDasharray={1}
            style={{
              strokeDashoffset: type === "success" ? 0 : 1,
              transition:
                type === "success" && !reduced
                  ? `stroke-dashoffset 380ms ${EASE} 100ms`
                  : "none",
            }}
          />
        </svg>
      </span>
      <span
        className={`${layer} text-red-600 dark:text-red-400`}
        style={swap(type === "error", reduced)}
      >
        <svg viewBox="0 0 16 16" fill="none" className="size-4">
          <circle
            cx="8"
            cy="8"
            r="6.25"
            stroke="currentColor"
            strokeWidth="1.5"
          />
          <path
            d="M8 4.75v3.75"
            stroke="currentColor"
            strokeWidth="1.6"
            strokeLinecap="round"
          />
          <circle cx="8" cy="11" r="0.9" fill="currentColor" />
        </svg>
      </span>
      <span
        className={`${layer} text-muted-foreground`}
        style={swap(type === "info", reduced)}
      >
        <svg viewBox="0 0 16 16" fill="none" className="size-4">
          <circle
            cx="8"
            cy="8"
            r="6.25"
            stroke="currentColor"
            strokeWidth="1.5"
          />
          <path
            d="M8 7.25v4"
            stroke="currentColor"
            strokeWidth="1.6"
            strokeLinecap="round"
          />
          <circle cx="8" cy="4.9" r="0.9" fill="currentColor" />
        </svg>
      </span>
    </span>
  );
}

function ToastCard({
  data,
  index,
  expanded,
  frontHeight,
  height,
  offset,
  top,
  side,
  limit,
  paused,
  reduced,
  onHeight,
}: {
  data: ToastData;
  index: number;
  expanded: boolean;
  frontHeight: number;
  height: number;
  offset: number;
  top: boolean;
  side: "left" | "right" | "center";
  limit: number;
  paused: boolean;
  reduced: boolean;
  /** The toast's height, and null when it's gone. */
  onHeight: (id: string, height: number | null) => void;
}) {
  const ref = React.useRef<HTMLLIElement>(null);
  const innerRef = React.useRef<HTMLDivElement>(null);
  const [mounted, setMounted] = React.useState(reduced);
  const [drag, setDrag] = React.useState<{ x: number; active: boolean }>({
    x: 0,
    active: false,
  });
  const [exitX, setExitX] = React.useState(0);
  const start = React.useRef<{ x: number; t: number } | null>(null);
  const leaving = data.dismissed;
  const sign = top ? 1 : -1;

  // Paint below the edge first, then rise into place.
  React.useEffect(() => {
    if (mounted) return;
    let inner = 0;
    const outer = requestAnimationFrame(
      () => (inner = requestAnimationFrame(() => setMounted(true))),
    );
    return () => {
      cancelAnimationFrame(outer);
      cancelAnimationFrame(inner);
    };
  }, [mounted]);

  React.useLayoutEffect(() => {
    const el = innerRef.current;
    if (!el) return;
    const measure = () => onHeight(data.id, el.offsetHeight);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => {
      observer.disconnect();
      onHeight(data.id, null);
    };
  }, [data.id, onHeight]);

  // Leaving: run the exit, then drop it from the store.
  React.useEffect(() => {
    if (!leaving) return;
    const t = window.setTimeout(() => remove(data.id), reduced ? 0 : 340);
    return () => window.clearTimeout(t);
  }, [leaving, data.id, reduced]);

  // A failure gives a small shake.
  const lastType = React.useRef(data.type);
  React.useEffect(() => {
    if (data.type === "error" && lastType.current !== "error" && !reduced)
      innerRef.current?.animate(
        [
          { transform: "none" },
          { transform: "translateX(-4px)" },
          { transform: "translateX(4px)" },
          { transform: "translateX(-2px)" },
          { transform: "none" },
        ],
        { duration: 380, easing: "ease-out" },
      );
    lastType.current = data.type;
  }, [data.type, reduced]);

  const hiddenBehind = index >= limit;
  const scale = expanded || reduced ? 1 : 1 - index * 0.05;
  // Where it sits: fanned out by the heights in front of it, or stacked a rim's width behind the one in front.
  const placed = expanded ? sign * offset : sign * index * PEEK;
  const y = !mounted
    ? -sign * (frontHeight + 24)
    : leaving && !exitX
      ? placed - sign * 12
      : placed;
  const x = leaving ? exitX || 0 : drag.x;
  const opacity = !mounted || leaving || hiddenBehind ? 0 : 1;
  const transform = `translate3d(${x}px, ${y}px, 0) scale(${leaving && !exitX ? scale * 0.96 : scale})`;
  // Stacked behind the newest, a toast takes the newest's height so only its rim shows; fanned out, its own.
  const cardHeight = height
    ? !expanded && index > 0 && frontHeight
      ? frontHeight
      : height
    : undefined;

  const onPointerDown = (e: React.PointerEvent) => {
    if ((e.target as HTMLElement).closest("button")) return;
    start.current = { x: e.clientX, t: performance.now() };
    (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
    setDrag({ x: 0, active: true });
  };
  const onPointerMove = (e: React.PointerEvent) => {
    if (!start.current) return;
    const dx = e.clientX - start.current.x;
    // It follows the finger freely toward the edge, and resists the other way.
    const toward = side === "left" ? -1 : 1;
    setDrag({
      x: dx * toward > 0 || side === "center" ? dx : dx * 0.2,
      active: true,
    });
  };
  const onPointerUp = (e: React.PointerEvent) => {
    if (!start.current) return;
    const dx = e.clientX - start.current.x;
    const speed =
      Math.abs(dx) / Math.max(1, performance.now() - start.current.t);
    start.current = null;
    if (Math.abs(dx) > 90 || (speed > 0.45 && Math.abs(dx) > 24)) {
      setExitX(Math.sign(dx) * ((ref.current?.offsetWidth ?? 360) + 40));
      toast.dismiss(data.id);
    }
    setDrag({ x: 0, active: false });
  };

  return (
    <li
      ref={ref}
      data-toast={data.id}
      role={data.type === "error" ? "alert" : "status"}
      aria-live={data.type === "error" ? "assertive" : "polite"}
      aria-atomic="true"
      aria-hidden={hiddenBehind && !expanded ? true : undefined}
      tabIndex={-1}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onPointerCancel={onPointerUp}
      className={`group/toast pointer-events-auto absolute inset-x-0 touch-pan-y select-none outline-none ${top ? "top-0 origin-bottom" : "bottom-0 origin-top"}`}
      style={{
        zIndex: 100 - index,
        transform,
        opacity,
        filter: !mounted || (leaving && !exitX) ? "blur(4px)" : "none",
        transition: reduced
          ? "none"
          : drag.active
            ? "none"
            : `transform ${leaving ? 340 : 520}ms ${mounted && !leaving && index === 0 ? THROW : EASE}, opacity ${leaving ? 220 : 360}ms ${EASE}, filter 360ms ${EASE}`,
      }}
    >
      <div
        className="relative overflow-hidden rounded-[14px] bg-popover text-popover-foreground shadow-[inset_0_0_0_1px_var(--border)]"
        style={{
          height: cardHeight,
          transition: reduced ? "none" : `height 420ms ${EASE}`,
        }}
      >
        {/* Measured as it naturally is, whatever height the card is showing it at. */}
        <div
          ref={innerRef}
          className="flex min-w-0 items-start p-3.5 pr-10"
          style={{
            opacity: !expanded && index > 0 ? 0 : 1,
            transition: reduced ? "none" : `opacity 260ms ${EASE}`,
          }}
        >
          <StatusIcon type={data.type} reduced={reduced} />
          <div className="min-w-0 flex-1">
            <p className="text-[13.5px] font-medium leading-5 text-foreground">
              <TextMorph animateWidth={false}>{data.title}</TextMorph>
            </p>
            {data.description && (
              <p className="mt-0.5 text-[12.5px] leading-5 text-muted-foreground">
                {data.description}
              </p>
            )}
          </div>
          {data.action && (
            <button
              type="button"
              onClick={() => {
                data.action?.onClick();
                toast.dismiss(data.id);
              }}
              className={`cursor-pointer -my-0.5 ml-3 inline-flex h-7 shrink-0 items-center rounded-full px-3 text-[12px] font-medium text-foreground shadow-[inset_0_0_0_1px_var(--border)] transition-colors hover:bg-accent ${FOCUS}`}
            >
              {data.action.label}
            </button>
          )}
        </div>
        <button
          type="button"
          aria-label="Dismiss"
          onClick={() => toast.dismiss(data.id)}
          className={`cursor-pointer absolute right-2.5 top-3 flex size-6 items-center justify-center rounded-full text-muted-foreground opacity-0 transition-[opacity,color,background-color] duration-200 hover:bg-accent hover:text-foreground focus-visible:opacity-100 group-hover/toast:opacity-100 [@media(hover:none)]:opacity-100 ${FOCUS}`}
        >
          <svg aria-hidden="true" viewBox="0 0 12 12" className="size-3">
            <path
              d="M3 3l6 6M9 3l-6 6"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.5"
              strokeLinecap="round"
            />
          </svg>
        </button>
        {/* The time left, draining along the bottom edge. Restarts when the toast changes. */}
        {data.type !== "loading" && data.duration !== Infinity && (
          <span
            key={data.version}
            aria-hidden="true"
            onAnimationEnd={() => toast.dismiss(data.id)}
            className="absolute inset-x-3.5 bottom-0 h-px origin-left bg-foreground/15"
            style={{
              animation: `ui-progress ${data.duration}ms linear reverse forwards`,
              animationPlayState: paused || leaving ? "paused" : "running",
              opacity: !expanded && index > 0 ? 0 : 1,
            }}
          />
        )}
      </div>
    </li>
  );
}

export function Toaster({
  position = "bottom-right",
  visible = 3,
  hotkey = "t",
  className = "",
  ...props
}: ToasterProps) {
  const reduced = useReducedMotion();
  const list = React.useSyncExternalStore(subscribe, getToasts, getNone);
  const [heights, setHeights] = React.useState<Record<string, number>>({});
  const [hovered, setHovered] = React.useState(false);
  const [focused, setFocused] = React.useState(false);
  const [hidden, setHidden] = React.useState(false);
  const regionRef = React.useRef<HTMLOListElement>(null);

  const top = position.startsWith("top");
  const side = position.endsWith("left")
    ? "left"
    : position.endsWith("right")
      ? "right"
      : "center";
  const expanded = hovered || focused || reduced;
  const paused = hovered || focused || hidden;

  const onHeight = React.useCallback(
    (id: string, h: number | null) =>
      setHeights((m) => {
        if (h !== null) return m[id] === h ? m : { ...m, [id]: h };
        if (!(id in m)) return m;
        const next = { ...m };
        delete next[id];
        return next;
      }),
    [],
  );

  React.useEffect(() => {
    const onVisibility = () => setHidden(document.visibilityState === "hidden");
    onVisibility();
    document.addEventListener("visibilitychange", onVisibility);
    return () => document.removeEventListener("visibilitychange", onVisibility);
  }, []);

  // Alt + T jumps to the newest toast; Escape from there dismisses it.
  React.useEffect(() => {
    if (!hotkey) return;
    const onKey = (e: KeyboardEvent) => {
      if (!e.altKey || e.code !== `Key${hotkey.toUpperCase()}`) return;
      e.preventDefault();
      regionRef.current?.querySelector<HTMLElement>("li")?.focus();
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [hotkey]);

  const shown = list.filter((t) => !t.dismissed);
  const front = shown[0];
  const frontHeight = front ? (heights[front.id] ?? 0) : 0;
  // Each toast's distance from the edge when fanned out: the heights of the ones in front of it.
  const offsets: Record<string, number> = {};
  let acc = 0;
  for (const t of list) {
    offsets[t.id] = acc;
    if (!t.dismissed) acc += (heights[t.id] ?? 0) + GAP;
  }
  const stackHeight = expanded
    ? Math.max(0, acc - GAP)
    : frontHeight + Math.min(shown.length - 1, visible - 1) * PEEK;

  return (
    <section
      aria-label="Notifications (Alt+T)"
      className={`pointer-events-none fixed z-[90] flex w-[min(380px,calc(100vw-32px))] ${top ? "top-4" : "bottom-4"} ${
        side === "left"
          ? "left-4"
          : side === "right"
            ? "right-4"
            : "left-1/2 -translate-x-1/2"
      } ${className}`}
      {...props}
    >
      <ol
        ref={regionRef}
        tabIndex={-1}
        onPointerEnter={() => setHovered(true)}
        onPointerLeave={() => setHovered(false)}
        onFocus={() => setFocused(true)}
        onBlur={(e) =>
          !e.currentTarget.contains(e.relatedTarget as Node) &&
          setFocused(false)
        }
        onKeyDown={(e) => {
          if (e.key !== "Escape") return;
          const id = (e.target as HTMLElement).closest<HTMLElement>(
            "[data-toast]",
          )?.dataset.toast;
          if (id) toast.dismiss(id);
        }}
        className={`relative w-full outline-none ${shown.length ? "pointer-events-auto" : ""}`}
        style={{
          height: stackHeight,
          transition: reduced ? "none" : `height 420ms ${EASE}`,
        }}
      >
        {list.map((t) => {
          const index = t.dismissed
            ? Math.max(
                0,
                shown.findIndex((s) => s.id === t.id),
              )
            : shown.indexOf(t);
          return (
            <ToastCard
              key={t.id}
              data={t}
              index={index < 0 ? 0 : index}
              expanded={expanded}
              frontHeight={frontHeight}
              height={heights[t.id] ?? 0}
              offset={offsets[t.id] ?? 0}
              top={top}
              side={side}
              limit={visible}
              paused={paused}
              reduced={reduced}
              onHeight={onHeight}
            />
          );
        })}
      </ol>
    </section>
  );
}

"use client";

import * as React from "react";
import {
  EASE_OUT,
  INTERACTION_FOCUS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * TOGGLE GROUP: several on/off choices side by side
 *
 *   press    each toggle fills when it's on and empties when off
 *   merge    toggles that are on next to each other join into one
 *            shape: the corners between them square off, so Bold +
 *            Italic read as one pill instead of two blobs
 *   single   <Toggle> on its own is one pressed/unpressed button
 *
 * For one choice out of several, use the segmented control.
 * ───────────────────────────────────────────────────────── */

export interface ToggleOption {
  value: string;
  label: string;
  icon?: React.ReactNode;
  /** Show only the icon; `label` becomes the accessible name. */
  iconOnly?: boolean;
  disabled?: boolean;
}

export interface ToggleGroupProps {
  options: ToggleOption[];
  value?: string[];
  defaultValue?: string[];
  onValueChange?: (value: string[]) => void;
  /** Accessible name of the group. */
  label: string;
  size?: "sm" | "md";
  className?: string;
}

const R = 999;

export function ToggleGroup({
  options,
  value,
  defaultValue = [],
  onValueChange,
  label,
  size = "md",
  className = "",
}: ToggleGroupProps) {
  const reduced = useInteractionReducedMotion();
  const [own, setOwn] = React.useState(defaultValue);
  const on = value ?? own;
  const sm = size === "sm";

  const flip = (v: string) => {
    const next = on.includes(v) ? on.filter((x) => x !== v) : [...on, v];
    if (value === undefined) setOwn(next);
    onValueChange?.(next);
  };

  return (
    <div
      role="group"
      aria-label={label}
      className={`inline-flex items-center rounded-full bg-card p-0.5 shadow-[inset_0_0_0_1px_var(--border)] ${className}`}
    >
      {options.map((o, i) => {
        const pressed = on.includes(o.value);
        const left = pressed && on.includes(options[i - 1]?.value ?? "");
        const right = pressed && on.includes(options[i + 1]?.value ?? "");
        return (
          <button
            key={o.value}
            type="button"
            aria-pressed={pressed}
            aria-label={o.iconOnly ? o.label : undefined}
            disabled={o.disabled}
            onClick={() => flip(o.value)}
            className={`group/tg relative inline-flex shrink-0 items-center justify-center gap-1.5 font-medium cursor-pointer disabled:cursor-default disabled:opacity-40 [&_svg]:size-3.5 ${
              sm ? "h-6 text-[12px]" : "h-8 text-[13px]"
            } ${o.iconOnly ? (sm ? "w-6" : "w-8") : sm ? "px-2.5" : "px-3"} rounded-full ${pressed ? "text-foreground" : "text-muted-foreground hover:text-foreground"} ${INTERACTION_FOCUS}`}
          >
            {/* The fill: corners next to another pressed toggle square off so they read as one. */}
            <span
              aria-hidden="true"
              className="absolute inset-0 bg-[color-mix(in_oklab,var(--foreground)_9%,transparent)] transition-[scale] duration-200 group-active/tg:scale-[0.96] motion-reduce:group-active/tg:scale-100"
              style={{
                opacity: pressed ? 1 : 0,
                borderTopLeftRadius: left ? 4 : R,
                borderBottomLeftRadius: left ? 4 : R,
                borderTopRightRadius: right ? 4 : R,
                borderBottomRightRadius: right ? 4 : R,
                transition: reduced
                  ? "none"
                  : `opacity 220ms ${EASE_OUT}, border-radius 320ms ${EASE_OUT}, scale 200ms ${EASE_OUT}`,
              }}
            />
            <span className="relative inline-flex items-center gap-1.5">
              {o.icon}
              {!o.iconOnly && o.label}
            </span>
          </button>
        );
      })}
    </div>
  );
}

export interface ToggleProps extends Omit<
  React.ButtonHTMLAttributes<HTMLButtonElement>,
  "onChange"
> {
  pressed?: boolean;
  defaultPressed?: boolean;
  onPressedChange?: (pressed: boolean) => void;
  size?: "sm" | "md";
}

/** One pressed/unpressed button. Icon-only toggles need an aria-label. */
export function Toggle({
  pressed: controlled,
  defaultPressed = false,
  onPressedChange,
  size = "md",
  className = "",
  children,
  onClick,
  ...props
}: ToggleProps) {
  const reduced = useInteractionReducedMotion();
  const [own, setOwn] = React.useState(defaultPressed);
  const pressed = controlled ?? own;
  return (
    <button
      type="button"
      aria-pressed={pressed}
      onClick={(e) => {
        onClick?.(e);
        if (e.defaultPrevented) return;
        if (controlled === undefined) setOwn(!pressed);
        onPressedChange?.(!pressed);
      }}
      className={`group/tg relative inline-flex shrink-0 items-center justify-center gap-1.5 rounded-full font-medium cursor-pointer disabled:cursor-default disabled:opacity-40 [&_svg]:size-3.5 ${
        size === "sm"
          ? "h-7 min-w-7 px-2 text-[12px]"
          : "h-9 min-w-9 px-2.5 text-[13px]"
      } ${pressed ? "text-foreground" : "text-muted-foreground hover:bg-accent/50 hover:text-foreground"} ${INTERACTION_FOCUS} ${className}`}
      {...props}
    >
      <span
        aria-hidden="true"
        className="absolute inset-0 rounded-full bg-accent shadow-[inset_0_0_0_1px_var(--border)] transition-[scale] duration-200 group-active/tg:scale-[0.94] motion-reduce:group-active/tg:scale-100"
        style={{
          opacity: pressed ? 1 : 0,
          transition: reduced
            ? "none"
            : `opacity 220ms ${EASE_OUT}, scale 200ms ${EASE_OUT}`,
        }}
      />
      <span className="relative inline-flex items-center gap-1.5">
        {children}
      </span>
    </button>
  );
}

export default ToggleGroup;

"use client";

import * as React from "react";
import { AlertCircle, Ban, ChevronDown, RotateCcw, Wrench } from "lucide-react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * TOOL CALL: one tool invocation, from arguments to result
 *
 *   preparing  the model is still writing the arguments; the
 *              panel eases taller as each one arrives
 *   running    a spinner opens in and the label morphs to
 *              "Running"
 *   done       the spinner blurs into a check that draws itself
 *              and the run time rolls up from zero; the output
 *              rises in as the panel eases to fit it
 *   error      the label morphs to "Failed" in red, with the
 *              message and a retry
 *   denied     the user said no
 *
 * One status pill throughout: its icon slot opens and closes,
 * icons swap through a blur and the label morphs, so it never
 * swaps out. Arguments render as readable fields; nested
 * values as JSON.
 * Pass renderOutput to show a result your own way.
 * ───────────────────────────────────────────────────────── */

export type ToolCallStatus =
  "preparing" | "running" | "done" | "error" | "denied";

export interface ToolCallProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "title"
> {
  /** The tool's name as the model calls it, e.g. "search_flights". */
  name: string;
  /** A human label, e.g. "Search flights". */
  title?: string;
  status: ToolCallStatus;
  /** Arguments, possibly partial while preparing. */
  input?: unknown;
  /** The result, once done. */
  output?: unknown;
  /** Render the result yourself, e.g. as a small card. */
  renderOutput?: (output: unknown) => React.ReactNode;
  errorText?: string;
  onRetry?: () => void;
  /** How long it ran (ms). */
  duration?: number;
  icon?: React.ReactNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
}

const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const MORPH = "cubic-bezier(0.16,1,0.3,1)";
// A light that sweeps across the label. A mask, not a text clip, so it reaches letters that are mid-morph.
const SHEEN =
  "text-foreground [mask-image:linear-gradient(90deg,rgb(0_0_0/0.45)_35%,#000_50%,rgb(0_0_0/0.45)_65%)] [mask-size:200%_100%] animate-[ui-sheen_1.4s_linear_infinite] motion-reduce:animate-none motion-reduce:[mask-image:none] motion-reduce:text-foreground/70";
const LABELS: Record<ToolCallStatus, string> = {
  preparing: "Preparing",
  running: "Running",
  done: "Done",
  error: "Failed",
  denied: "Denied",
};

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Icons trade places through a blur: the old one shrinks away as the new one grows in. */
const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 260ms ${MORPH}, transform 380ms ${MORPH}, filter 260ms ${MORPH}`,
});

function DrawnCheck({ drawn, reduced }: { drawn: boolean; reduced: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="none" className="size-3.5">
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 420ms ${MORPH} 120ms`
              : "none",
        }}
      />
    </svg>
  );
}

/** The run time, in the unit that reads best; it rolls up from zero when the call has just finished. */
function Duration({ ms, rollIn }: { ms: number; rollIn: boolean }) {
  const from = rollIn ? 0 : undefined;
  if (ms < 1000)
    return <NumberRoll value={Math.round(ms)} suffix="ms" from={from} />;
  if (ms < 60000)
    return (
      <NumberRoll
        value={Math.round(ms / 100) / 10}
        format={ONE_DECIMAL}
        suffix="s"
        from={from}
      />
    );
  return (
    <>
      <NumberRoll value={Math.floor(ms / 60000)} suffix="m" from={from} />
      &nbsp;
      <NumberRoll
        value={Math.round((ms % 60000) / 1000)}
        suffix="s"
        from={from}
      />
    </>
  );
}
const ONE_DECIMAL = { minimumFractionDigits: 1, maximumFractionDigits: 1 };

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function Value({ value }: { value: unknown }) {
  if (typeof value === "string")
    return <span className="break-words text-foreground">{value}</span>;
  if (typeof value === "number" || typeof value === "boolean" || value === null)
    return (
      <span className="font-mono text-[12px] text-foreground">
        {String(value)}
      </span>
    );
  return (
    <span className="break-all font-mono text-[11.5px] text-muted-foreground">
      {JSON.stringify(value)}
    </span>
  );
}

function Fields({ value }: { value: unknown }) {
  if (isPlainObject(value)) {
    const entries = Object.entries(value);
    if (entries.length === 0)
      return (
        <p className="text-[12.5px] text-muted-foreground">No arguments</p>
      );
    return (
      <dl className="grid grid-cols-[minmax(0,auto)_1fr] gap-x-4 gap-y-1.5 text-[12.5px]">
        {entries.map(([key, v]) => (
          <React.Fragment key={key}>
            <dt className="truncate font-mono text-[11.5px] leading-5 text-muted-foreground">
              {key}
            </dt>
            <dd className="min-w-0 leading-5">
              <Value value={v} />
            </dd>
          </React.Fragment>
        ))}
      </dl>
    );
  }
  if (typeof value === "string")
    return (
      <p className="whitespace-pre-wrap text-[12.5px] text-foreground">
        {value}
      </p>
    );
  return (
    <pre className="max-h-56 overflow-auto rounded-md bg-muted px-3 py-2 font-mono text-[11.5px] leading-5 text-foreground">
      {JSON.stringify(value, null, 2)}
    </pre>
  );
}

function Label({ children }: { children: React.ReactNode }) {
  return (
    <p className="mb-1.5 text-[11px] font-medium uppercase tracking-[0.06em] text-muted-foreground">
      {children}
    </p>
  );
}

export function ToolCall({
  name,
  title,
  status,
  input,
  output,
  renderOutput,
  errorText,
  onRetry,
  duration,
  icon,
  open,
  defaultOpen = false,
  onOpenChange,
  className = "",
  ...props
}: ToolCallProps) {
  const reduced = useReducedMotion();
  const [ownOpen, setOwnOpen] = React.useState(defaultOpen);
  const [errorSeen, setErrorSeen] = React.useState(false);
  const panelId = React.useId();
  const bodyRef = React.useRef<HTMLDivElement>(null);
  const [bodyHeight, setBodyHeight] = React.useState<number | null>(null);

  // Each time it finishes while you watch, the run time rolls up from zero (a finished call in history just sits).
  const [prevStatus, setPrevStatus] = React.useState(status);
  const [finishes, setFinishes] = React.useState(0);
  if (prevStatus !== status) {
    setPrevStatus(status);
    if (status === "done") setFinishes((n) => n + 1);
  }

  // The panel takes the height of what's in it, so arguments and output arriving ease it taller instead of jumping.
  React.useLayoutEffect(() => {
    const el = bodyRef.current;
    if (!el) return;
    const measure = () =>
      setBodyHeight((h) => (h === el.offsetHeight ? h : el.offsetHeight));
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  // Failures open themselves once, so the reason is visible without a click.
  if (status === "error" && !errorSeen) {
    setErrorSeen(true);
    if (open === undefined) setOwnOpen(true);
  }

  const expanded = open ?? ownOpen;
  const toggle = () => {
    const next = !expanded;
    if (open === undefined) setOwnOpen(next);
    onOpenChange?.(next);
  };

  const showTime = status === "done" && duration !== undefined;
  const icons: Partial<Record<ToolCallStatus, React.ReactNode>> = {
    // Spins only while running, so a hidden spinner never keeps the page busy.
    running: (
      <span
        className={`size-3 rounded-full border-[1.5px] border-border border-t-foreground/70 motion-reduce:animate-none ${status === "running" ? "animate-spin" : ""}`}
      />
    ),
    done: (
      <span className="text-emerald-600 dark:text-emerald-400">
        <DrawnCheck drawn={status === "done"} reduced={reduced} />
      </span>
    ),
    error: <AlertCircle className="size-3.5" />,
    denied: <Ban className="size-3.5" />,
  };
  const badge = (
    <span
      className={`flex items-center text-[12px] transition-colors duration-300 ${status === "error" ? "font-medium text-red-500" : status === "preparing" ? "font-medium" : "text-muted-foreground"}`}
    >
      <span
        aria-hidden="true"
        className="relative flex h-3.5 shrink-0 items-center justify-center"
        style={{
          width: status === "preparing" ? 0 : 14,
          marginRight: status === "preparing" ? 0 : 5,
          transition: reduced
            ? "none"
            : `width 380ms ${MORPH}, margin 380ms ${MORPH}`,
        }}
      >
        {(Object.keys(icons) as ToolCallStatus[]).map((s) => (
          <span
            key={s}
            className="absolute inset-0 flex items-center justify-center"
            style={swap(s === status, reduced)}
          >
            {icons[s]}
          </span>
        ))}
      </span>
      <span className={status === "preparing" ? SHEEN : ""}>
        <TextMorph>{showTime ? "" : LABELS[status]}</TextMorph>
      </span>
      {duration !== undefined && (
        <span
          aria-hidden={!showTime || undefined}
          className="grid"
          style={{
            gridTemplateColumns: showTime ? "1fr" : "0fr",
            opacity: showTime ? 1 : 0,
            transition: reduced
              ? "none"
              : `grid-template-columns 420ms ${MORPH}, opacity 300ms ${MORPH}`,
          }}
        >
          <span className="flex min-w-0 whitespace-nowrap tabular-nums [clip-path:inset(-4px_0)]">
            <Duration
              key={finishes}
              ms={duration}
              rollIn={finishes > 0 && !reduced}
            />
          </span>
        </span>
      )}
    </span>
  );

  return (
    <div
      className={`overflow-hidden rounded-xl border border-border bg-background ${className}`}
      {...props}
    >
      <button
        type="button"
        aria-expanded={expanded}
        aria-controls={panelId}
        onClick={toggle}
        className={`cursor-pointer flex w-full items-center gap-2.5 px-3 py-2.5 text-left transition-colors hover:bg-accent/60 ${FOCUS}`}
      >
        <span
          aria-hidden="true"
          className="flex size-7 shrink-0 items-center justify-center rounded-lg bg-muted text-muted-foreground"
        >
          {icon ?? <Wrench className="size-3.5" />}
        </span>
        <span className="min-w-0 flex-1">
          <span className="block truncate text-[13px] font-medium text-foreground">
            {title ?? name}
          </span>
          {title && (
            <span className="block truncate font-mono text-[11px] text-muted-foreground">
              {name}
            </span>
          )}
        </span>
        <span role="status" aria-live="polite" className="shrink-0">
          {badge}
        </span>
        <ChevronDown
          aria-hidden="true"
          className={`size-3.5 shrink-0 text-muted-foreground transition-transform duration-300 motion-reduce:transition-none ${expanded ? "rotate-180" : ""}`}
        />
      </button>

      <div
        id={panelId}
        inert={!expanded}
        className="overflow-hidden"
        style={{
          height: expanded ? (bodyHeight ?? "auto") : 0,
          opacity: expanded ? 1 : 0,
          transition:
            reduced || bodyHeight === null
              ? "none"
              : `height 420ms ${MORPH}, opacity 300ms ${MORPH}`,
        }}
      >
        <div ref={bodyRef}>
          <div className="flex flex-col gap-4 border-t border-border px-3 py-3">
            {input !== undefined && (
              <section>
                <Label>Input</Label>
                <Fields value={input} />
              </section>
            )}

            {status === "done" && output !== undefined && (
              <section className="animate-[ui-fade-up_300ms_cubic-bezier(0.23,1,0.32,1)_both] motion-reduce:animate-none">
                <Label>Output</Label>
                {renderOutput ? (
                  renderOutput(output)
                ) : (
                  <Fields value={output} />
                )}
              </section>
            )}

            {status === "error" && (
              <section className="flex items-start justify-between gap-3 animate-[ui-fade-up_300ms_cubic-bezier(0.23,1,0.32,1)_both] motion-reduce:animate-none">
                <p className="text-[12.5px] leading-5 text-red-500">
                  {errorText ?? "The tool failed."}
                </p>
                {onRetry && (
                  <button
                    type="button"
                    onClick={onRetry}
                    className={`cursor-pointer flex shrink-0 items-center gap-1.5 rounded-md border border-border px-2 py-1 text-[12px] font-medium text-foreground transition-colors hover:bg-accent ${FOCUS}`}
                  >
                    <RotateCcw aria-hidden="true" className="size-3" />
                    Retry
                  </button>
                )}
              </section>
            )}

            {status === "denied" && (
              <p className="text-[12.5px] text-muted-foreground">
                You declined this action, so it didn’t run.
              </p>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { createPortal } from "react-dom";
import {
  enterStyle,
  themeVars,
  useFloating,
  usePresence,
  type Align,
  type Side,
} from "./floating";
import {
  EASE_OUT,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * TOOLTIP: a name for an icon, and its shortcut
 *
 *   first    after a short rest (500ms) it rises off the trigger
 *            out of a blur, from the side it sits on
 *   warm     moving to the next trigger while one is showing:
 *            no wait, and the new tooltip glides over from where
 *            the last one was, so a toolbar reads as one label
 *            travelling along it
 *   leave    a press, Escape or leaving hides it at once
 *
 * Keyboard focus shows it too; touch never does (a tap acts).
 * ───────────────────────────────────────────────────────── */

export interface TooltipProps {
  /** The trigger: one element that can take focus (usually an icon button). */
  children: React.ReactElement<{ "aria-describedby"?: string }>;
  content: React.ReactNode;
  /** A key or chord shown after the text, e.g. "⌘K". */
  shortcut?: string;
  side?: Side;
  align?: Align;
  /** Rest before the first tooltip shows (ms). */
  delay?: number;
  disabled?: boolean;
}

// Shared across tooltips: where the last one was and when it left, so the next can glide from it.
let last: { x: number; y: number; at: number } | null = null;
const WARM_MS = 450;

export function Tooltip({
  children,
  content,
  shortcut,
  side = "top",
  align = "center",
  delay = 500,
  disabled,
}: TooltipProps) {
  const reduced = useInteractionReducedMotion();
  const anchor = React.useRef<HTMLSpanElement>(null);
  const surface = React.useRef<HTMLDivElement>(null);
  const [open, setOpen] = React.useState(false);
  const [warm, setWarm] = React.useState(false);
  const timer = React.useRef(0);
  const id = React.useId();
  const { mounted, shown } = usePresence(open, 140);
  const place = useFloating({
    open: mounted,
    anchor,
    floating: surface,
    side,
    align,
    offset: 8,
  });
  const [vars, setVars] = React.useState<React.CSSProperties>({});

  const show = (now: boolean) => {
    if (disabled) return;
    window.clearTimeout(timer.current);
    const isWarm = !!last && performance.now() - last.at < WARM_MS;
    if (now || isWarm) {
      setWarm(isWarm);
      setOpen(true);
    } else
      timer.current = window.setTimeout(() => {
        setWarm(false);
        setOpen(true);
      }, delay);
  };
  const hide = () => {
    window.clearTimeout(timer.current);
    setOpen(false);
  };

  React.useEffect(() => () => window.clearTimeout(timer.current), []);

  // Remember where it was as it leaves; the next tooltip glides from here.
  React.useEffect(() => {
    if (!open && place.ready)
      last = { x: place.x, y: place.y, at: performance.now() };
    if (open) last = null;
  }, [open, place.ready, place.x, place.y]);

  React.useLayoutEffect(() => {
    if (mounted) setVars(themeVars(anchor.current));
  }, [mounted]);

  // Warm: glide over from the previous tooltip instead of rising out of a blur.
  const from = React.useRef<{ x: number; y: number } | null>(null);
  React.useLayoutEffect(() => {
    if (open && warm) from.current = last ? { x: last.x, y: last.y } : null;
  }, [open, warm]);
  React.useLayoutEffect(() => {
    const el = surface.current;
    const f = from.current;
    if (!el || !f || !place.ready || reduced) return;
    from.current = null;
    el.animate(
      [
        { transform: `translate(${f.x - place.x}px, ${f.y - place.y}px)` },
        { transform: "none" },
      ],
      { duration: 300, easing: EASE_OUT },
    );
  }, [place.ready, place.x, place.y, reduced]);

  const pose = warm
    ? {
        opacity: shown ? 1 : 0,
        transition: reduced
          ? "none"
          : `opacity ${shown ? 120 : 140}ms ${EASE_OUT}`,
      }
    : enterStyle(shown, place.side, reduced);

  return (
    <>
      <span
        ref={anchor}
        className="inline-flex"
        onPointerEnter={(e) => e.pointerType === "mouse" && show(false)}
        onPointerLeave={hide}
        onPointerDown={hide}
        onFocus={(e) =>
          (e.target as HTMLElement).matches(":focus-visible") && show(true)
        }
        onBlur={hide}
        onKeyDown={(e) => e.key === "Escape" && hide()}
      >
        {React.cloneElement(children, {
          "aria-describedby": open ? id : children.props["aria-describedby"],
        })}
      </span>
      {mounted &&
        createPortal(
          <div
            ref={surface}
            id={id}
            role="tooltip"
            className="pointer-events-none fixed left-0 top-0 z-[60] flex items-center gap-2 whitespace-nowrap rounded-full bg-foreground px-2.5 py-1 text-[12px] font-medium text-background"
            style={{
              ...vars,
              left: place.x,
              top: place.y,
              transformOrigin: place.origin,
              ...pose,
            }}
          >
            {content}
            {shortcut && (
              <kbd className="font-mono text-[10.5px] text-background/60">
                {shortcut}
              </kbd>
            )}
          </div>,
          document.body,
        )}
    </>
  );
}

export default Tooltip;

"use client";

import * as React from "react";
import {
  ChevronRight,
  File,
  Folder,
  FolderOpen,
  Plus,
  Trash2,
} from "lucide-react";
import { useRowMotion } from "./use-row-motion";
import { useTreeDrag } from "./use-tree-drag";

/* ─────────────────────────────────────────────────────────
 * TREE VIEW: the sidebar of pages, folders or files
 *
 *   open      a row's children slide out from under it while
 *             the rows below make room; closing folds them away
 *   carry     drag a row (and everything inside it): up and
 *             down picks the gap, sideways picks the depth, and
 *             a line starting at that depth shows where it lands
 *   into      the middle of a row means "inside it"; a closed
 *             one opens itself if you hold it there
 *   refuse    a rule (canDrop) turns the line amber and says
 *             why under the row you carry; let go and it flies
 *             home
 *   land      the row glides from where you let go into its
 *             place; a save that fails takes it back
 *   edit      F2 or double-click renames in place, + adds a row
 *             inside, Delete removes with Undo
 *   keys      arrows move and open, Alt+arrows move the row
 *             (up, down, in, out)
 *
 * Nodes are a flat list of { id, parent, title }, siblings in
 * the order they stand: the shape a database keeps.
 * ───────────────────────────────────────────────────────── */

export interface TreeNode {
  id: string;
  parent: string | null;
  title: string;
  /** Can't hold other rows (a file, say). */
  leaf?: boolean;
}

export interface TreeViewProps<T extends TreeNode> extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "children" | "defaultValue" | "onSelect"
> {
  nodes?: T[];
  defaultNodes?: T[];
  onNodesChange?: (nodes: T[]) => void;
  /** Ids of the open rows. */
  expanded?: string[];
  defaultExpanded?: string[];
  onExpandedChange?: (ids: string[]) => void;
  selected?: string | null;
  defaultSelected?: string | null;
  /** A row chosen by click, Enter or Space. */
  onSelect?: (node: T) => void;
  /** The row's icon. Defaults to a folder (open or closed) or a file. */
  icon?: (
    node: T,
    state: { expanded: boolean; hasChildren: boolean },
  ) => React.ReactNode;
  /** Why `parent` won't take `node` (null is the top level), or nothing. */
  canDrop?: (node: T, parent: T | null) => string | null | undefined | void;
  /** A row moved. Throw to put it back. */
  onMove?: (node: T, parent: T | null, index: number) => Promise<void> | void;
  /** Shows rename (F2, double-click). Throw to put the old title back. */
  onRename?: (node: T, title: string) => Promise<void> | void;
  /** Shows + on rows that hold others (and at the foot). Return the new node. */
  onCreate?: (parent: T | null, title: string) => T | Promise<T>;
  /** Shows delete. Runs once the chance to undo is over; throw to bring the row back. */
  onDelete?: (node: T) => Promise<void> | void;
  /** The noun for new rows: "page", "file". */
  addLabel?: string;
  undoFor?: number;
  /** Pixels per level. */
  indent?: number;
  label?: string;
}

type Row<T> =
  | {
      kind: "node";
      node: T;
      depth: number;
      hasChildren: boolean;
      open: boolean;
      pos: number;
      size: number;
    }
  | { kind: "empty"; parent: string; depth: number }
  | { kind: "draft"; parent: string | null; depth: number };

type Note = { text: string; tone: "warn" | "error"; key: number };
type Undo<T> = { key: number; node: T; removed: T[]; nodes: T[] };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const GLIDE = 480;
const ROW_H = 30;
const INSET = 26;
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const NO_IDS: string[] = [];
const NO_RANKS: ReadonlyMap<string, number> = new Map();

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Every node under `id`, at any depth. */
function under<T extends TreeNode>(nodes: T[], id: string) {
  const out = new Set<string>();
  const walk = (p: string) =>
    nodes.forEach(
      (n) => n.parent === p && !out.has(n.id) && (out.add(n.id), walk(n.id)),
    );
  walk(id);
  return out;
}

/** Moves a node into `parent`: first (after null), after a sibling, or at the end. */
function place<T extends TreeNode>(
  nodes: T[],
  id: string,
  parent: string | null,
  after: string | null | "end",
): T[] {
  const node = nodes.find((n) => n.id === id);
  if (!node) return nodes;
  const rest = nodes.filter((n) => n.id !== id);
  const sibs = rest.filter((n) => n.parent === parent);
  let at: number;
  if (after === "end")
    at = sibs.length ? rest.indexOf(sibs[sibs.length - 1]) + 1 : rest.length;
  else if (after === null)
    at = sibs.length ? rest.indexOf(sibs[0]) : rest.length;
  else at = rest.findIndex((n) => n.id === after) + 1;
  return [...rest.slice(0, at), { ...node, parent } as T, ...rest.slice(at)];
}

/** A sentence that changes crossfades whole. */
function Line({ text, className = "" }: { text: string; className?: string }) {
  const [shown, setShown] = React.useState({ text, key: 0 });
  const [leaving, setLeaving] = React.useState<{ text: string; key: number }[]>(
    [],
  );
  if (text !== shown.text) {
    if (shown.text) setLeaving((l) => [...l, shown]);
    setShown({ text, key: shown.key + 1 });
  }
  return (
    <span className={`relative block ${className}`}>
      <span
        key={shown.key}
        className="block truncate"
        ref={(el) => {
          if (!el || shown.key === 0 || el.dataset.in) return;
          el.dataset.in = "1";
          el.animate(
            [
              {
                opacity: 0,
                transform: "translateY(0.35em)",
                filter: "blur(4px)",
              },
              { opacity: 1, transform: "none", filter: "blur(0px)" },
            ],
            { duration: 380, delay: 60, easing: EASE, fill: "backwards" },
          );
        }}
      >
        {shown.text || " "}
      </span>
      {leaving.map((l) => (
        <span
          key={l.key}
          aria-hidden="true"
          className="pointer-events-none absolute inset-x-0 top-0 block truncate"
          ref={(el) => {
            if (!el || el.dataset.out) return;
            el.dataset.out = "1";
            el.animate(
              [
                { opacity: 1, filter: "blur(0px)" },
                { opacity: 0, filter: "blur(4px)" },
              ],
              { duration: 180, easing: EASE, fill: "forwards" },
            ).onfinish = () =>
              setLeaving((all) => all.filter((x) => x.key !== l.key));
          }}
        >
          {l.text}
        </span>
      ))}
    </span>
  );
}

type RowActions<T> = {
  click: (e: React.MouseEvent, node: T) => void;
  toggle: (node: T) => void;
  key: (e: React.KeyboardEvent, node: T) => void;
  focus: (node: T) => void;
  rename: (node: T) => void;
  commitRename: (node: T, title: string) => void;
  cancelRename: () => void;
  add: (node: T) => void;
  remove: (node: T) => void;
  icon: (
    node: T,
    state: { expanded: boolean; hasChildren: boolean },
  ) => React.ReactNode;
};

/** One row, memoised on plain values: opening a folder or carrying a row re-renders only the rows it changes. */
function TreeRowView<T extends TreeNode>({
  node,
  depth,
  hasChildren,
  open,
  pos,
  size,
  selected,
  tab,
  dimmed,
  renaming,
  canAdd,
  canDelete,
  canRename,
  indent,
  reduced,
  actions,
}: {
  node: T;
  depth: number;
  hasChildren: boolean;
  open: boolean;
  pos: number;
  size: number;
  selected: boolean;
  tab: boolean;
  dimmed: boolean;
  renaming: boolean;
  canAdd: boolean;
  canDelete: boolean;
  canRename: boolean;
  indent: number;
  reduced: boolean;
  actions: React.RefObject<RowActions<T>>;
}) {
  const holds = !node.leaf;
  return (
    <li
      data-row-id={node.id}
      data-depth={depth}
      data-parent={node.parent ?? ""}
      data-can-hold={holds ? "1" : "0"}
      data-expanded={open ? "1" : "0"}
      data-has-children={hasChildren ? "1" : "0"}
      role="treeitem"
      aria-level={depth + 1}
      aria-setsize={size}
      aria-posinset={pos}
      aria-expanded={holds ? open : undefined}
      aria-selected={selected}
      tabIndex={tab ? 0 : -1}
      onKeyDown={(e) => actions.current.key(e, node)}
      onFocus={(e) =>
        e.target === e.currentTarget && actions.current.focus(node)
      }
      onClick={(e) => actions.current.click(e, node)}
      onDoubleClick={() => canRename && actions.current.rename(node)}
      className={`group/row relative shrink-0 cursor-default select-none rounded-[8px] outline-none [-webkit-touch-callout:none] ${FOCUS}`}
      style={{
        height: ROW_H,
        opacity: dimmed ? 0.4 : 1,
        transition: reduced ? "none" : `opacity 160ms ${EASE}`,
      }}
    >
      <div
        data-row-content
        className={`flex h-full items-center gap-1.5 rounded-[8px] pr-1 text-[13.5px] transition-colors duration-150 ${selected ? "bg-accent font-medium text-foreground" : "text-foreground/85 hover:bg-accent/60"}`}
        style={{ paddingLeft: 4 + depth * indent }}
      >
        {holds ? (
          <button
            type="button"
            tabIndex={-1}
            aria-hidden="true"
            onClick={(e) => {
              e.stopPropagation();
              actions.current.toggle(node);
            }}
            className={`flex size-5 shrink-0 cursor-pointer items-center justify-center rounded-[6px] text-muted-foreground hover:bg-accent hover:text-foreground ${hasChildren ? "" : "opacity-40"}`}
          >
            <ChevronRight
              className="size-3.5"
              strokeWidth={2}
              style={{
                transform: open ? "rotate(90deg)" : "none",
                transition: reduced ? "none" : `transform 260ms ${EASE}`,
              }}
            />
          </button>
        ) : (
          <span className="size-5 shrink-0" aria-hidden="true" />
        )}
        <span
          className="flex size-4 shrink-0 items-center justify-center text-muted-foreground [&_svg]:size-4"
          aria-hidden="true"
        >
          {actions.current.icon(node, { expanded: open, hasChildren })}
        </span>
        {renaming ? (
          <input
            autoFocus
            defaultValue={node.title}
            aria-label={`Rename ${node.title}`}
            onFocus={(e) => e.currentTarget.select()}
            onClick={(e) => e.stopPropagation()}
            onKeyDown={(e) => {
              e.stopPropagation();
              if (e.key === "Enter")
                actions.current.commitRename(node, e.currentTarget.value);
              if (e.key === "Escape") actions.current.cancelRename();
            }}
            onBlur={(e) =>
              actions.current.commitRename(node, e.currentTarget.value)
            }
            className="-ml-1 h-6 min-w-0 flex-1 rounded-[6px] bg-background px-1 text-[13.5px] font-normal outline-none shadow-[inset_0_0_0_1px_var(--ring)] [@media(pointer:coarse)]:text-[16px]"
          />
        ) : (
          <span className="min-w-0 flex-1 truncate">{node.title}</span>
        )}
        {!renaming && (canAdd || canDelete) && (
          // Shown on hover and focus; on touch screens, on the chosen row.
          <span
            className={`flex shrink-0 items-center opacity-0 transition-opacity duration-150 group-hover/row:opacity-100 group-focus-within/row:opacity-100 ${selected ? "[@media(pointer:coarse)]:opacity-100" : "[@media(pointer:coarse)]:hidden"}`}
          >
            {canDelete && (
              <button
                type="button"
                tabIndex={-1}
                aria-label={`Delete ${node.title}`}
                onClick={(e) => {
                  e.stopPropagation();
                  actions.current.remove(node);
                }}
                className="flex size-6 cursor-pointer items-center justify-center rounded-[6px] text-muted-foreground hover:bg-accent hover:text-foreground"
              >
                <Trash2 className="size-3.5" strokeWidth={1.75} />
              </button>
            )}
            {canAdd && holds && (
              <button
                type="button"
                tabIndex={-1}
                aria-label={`Add inside ${node.title}`}
                onClick={(e) => {
                  e.stopPropagation();
                  actions.current.add(node);
                }}
                className="flex size-6 cursor-pointer items-center justify-center rounded-[6px] text-muted-foreground hover:bg-accent hover:text-foreground"
              >
                <Plus className="size-3.5" strokeWidth={1.75} />
              </button>
            )}
          </span>
        )}
      </div>
    </li>
  );
}

const TreeRow = React.memo(TreeRowView) as typeof TreeRowView;

const defaultIcon = (
  node: TreeNode,
  { expanded, hasChildren }: { expanded: boolean; hasChildren: boolean },
) =>
  node.leaf ? (
    <File strokeWidth={1.75} />
  ) : expanded && hasChildren ? (
    <FolderOpen strokeWidth={1.75} />
  ) : (
    <Folder strokeWidth={1.75} />
  );

export function TreeView<T extends TreeNode>({
  nodes: controlled,
  defaultNodes,
  onNodesChange,
  expanded: expandedProp,
  defaultExpanded = NO_IDS,
  onExpandedChange,
  selected: selectedProp,
  defaultSelected = null,
  onSelect,
  icon = defaultIcon,
  canDrop,
  onMove,
  onRename,
  onCreate,
  onDelete,
  addLabel = "page",
  undoFor = 5000,
  indent = 14,
  label = "Pages",
  className = "",
  ...props
}: TreeViewProps<T>) {
  const reduced = useReducedMotion();
  const uid = React.useId();
  const [own, setOwn] = React.useState<T[]>(defaultNodes ?? []);
  const nodes = controlled ?? own;
  const nodesRef = React.useRef(nodes);
  const [openOwn, setOpenOwn] = React.useState<string[]>(defaultExpanded);
  const openIds = expandedProp ?? openOwn;
  const open = React.useMemo(() => new Set(openIds), [openIds]);
  const openRef = React.useRef(open);

  React.useLayoutEffect(() => {
    nodesRef.current = nodes;
    openRef.current = open;
  });

  const [selOwn, setSelOwn] = React.useState<string | null>(defaultSelected);
  const selected = selectedProp === undefined ? selOwn : selectedProp;
  const [focusId, setFocusId] = React.useState<string | null>(null);
  const [lifted, setLifted] = React.useState<string | null>(null);
  const [renaming, setRenaming] = React.useState<string | null>(null);
  const [draft, setDraft] = React.useState<{
    parent: string | null;
    key: number;
  } | null>(null);
  const [note, setNote] = React.useState<Note | null>(null);
  const [undo, setUndo] = React.useState<Undo<T> | null>(null);
  const [holdUndo, setHoldUndo] = React.useState(false);
  const [announce, setAnnounce] = React.useState("");

  const noteSeq = React.useRef(0);
  const draftSeq = React.useRef(0);
  const undoSeq = React.useRef(0);

  const scrollerRef = React.useRef<HTMLDivElement>(null);
  const listRef = React.useRef<HTMLUListElement>(null);
  const ghostRef = React.useRef<HTMLDivElement>(null);
  const previewRef = React.useRef<HTMLDivElement>(null);
  const reasonRef = React.useRef<HTMLParagraphElement>(null);
  const lineRef = React.useRef<HTMLDivElement>(null);
  const ringRef = React.useRef<HTMLDivElement>(null);
  /** Rows that should glide in from somewhere other than their old place (a drop, a depth change). */
  const landing = React.useRef<{
    id?: string;
    from?: { x: number; y: number };
    depths: Map<string, { depth: number; top: number }>;
  } | null>(null);
  const sprung = React.useRef<Set<string>>(new Set());
  const refocus = React.useRef<string | null>(null);
  const typed = React.useRef({ text: "", at: 0 });
  const renamingRef = React.useRef<string | null>(null);

  const say = (text: string) =>
    setAnnounce((a) => (a === text ? `${text} ` : text));
  const warn = (text: string, tone: Note["tone"] = "warn") => {
    const key = ++noteSeq.current;
    setNote({ text, tone, key });
    window.setTimeout(() => setNote((n) => (n?.key === key ? null : n)), 3600);
  };
  const nodeMap = React.useMemo(
    () => new Map(nodes.map((n) => [n.id, n])),
    [nodes],
  );
  const byId = React.useCallback(
    (id: string | null) => (id ? (nodeMap.get(id) ?? null) : null),
    [nodeMap],
  );

  const commit = (next: T[]) => {
    nodesRef.current = next;
    if (controlled === undefined) setOwn(next);
    onNodesChange?.(next);
  };
  const setOpenIds = (next: Set<string>) => {
    openRef.current = next;
    const ids = [...next];
    if (expandedProp === undefined) setOpenOwn(ids);
    onExpandedChange?.(ids);
  };
  const select = (node: T) => {
    if (selectedProp === undefined) setSelOwn(node.id);
    onSelect?.(node);
  };

  // ── The rows in view ───────────────────────────────────
  const rows = React.useMemo(() => {
    const kids = new Map<string | null, T[]>();
    for (const n of nodes) {
      const list = kids.get(n.parent);
      if (list) list.push(n);
      else kids.set(n.parent, [n]);
    }
    const out: Row<T>[] = [];
    const walk = (parent: string | null, depth: number) => {
      const list = kids.get(parent) ?? [];
      list.forEach((node, i) => {
        const hasChildren = (kids.get(node.id)?.length ?? 0) > 0;
        const isOpen = !node.leaf && open.has(node.id);
        out.push({
          kind: "node",
          node,
          depth,
          hasChildren,
          open: isOpen,
          pos: i + 1,
          size: list.length,
        });
        if (!isOpen) return;
        walk(node.id, depth + 1);
        if (draft?.parent === node.id)
          out.push({ kind: "draft", parent: node.id, depth: depth + 1 });
        else if (!hasChildren)
          out.push({ kind: "empty", parent: node.id, depth: depth + 1 });
      });
    };
    walk(null, 0);
    if (draft && draft.parent === null)
      out.push({ kind: "draft", parent: null, depth: 0 });
    return out;
  }, [nodes, open, draft]);
  const nodeRows = rows.filter(
    (r): r is Extract<Row<T>, { kind: "node" }> => r.kind === "node",
  );
  const tabId =
    (focusId && nodeRows.some((r) => r.node.id === focusId) ? focusId : null) ??
    (selected && nodeRows.some((r) => r.node.id === selected)
      ? selected
      : nodeRows[0]?.node.id);

  useRowMotion(listRef, { reduced, ranks: NO_RANKS, ghosts: ghostRef });

  // After a drop or a keyboard move: the moved row comes from where it was let go, rows that changed depth slide sideways.
  React.useLayoutEffect(() => {
    const l = landing.current;
    const list = listRef.current;
    landing.current = null;
    if (!l || !list || reduced) return;
    list
      .querySelectorAll<HTMLElement>("[data-row-id][data-depth]")
      .forEach((el) => {
        const id = el.dataset.rowId!;
        const was = l.depths.get(id);
        if (!was) return;
        const depth = Number(el.dataset.depth);
        if (id === l.id && l.from) {
          el.animate(
            [
              {
                transform: `translate(${l.from.x + (was.depth - depth) * indent}px, ${l.from.y - was.top}px)`,
              },
              { transform: "translate(0px, 0px)" },
            ],
            { duration: GLIDE, easing: EASE, composite: "add" },
          );
          return;
        }
        if (was.depth !== depth)
          el.querySelector<HTMLElement>("[data-row-content]")?.animate(
            [
              { transform: `translateX(${(was.depth - depth) * indent}px)` },
              { transform: "translateX(0px)" },
            ],
            { duration: GLIDE, easing: EASE, composite: "add" },
          );
      });
  });

  // Keep focus on a row that moved (React re-inserts it) or was renamed.
  React.useLayoutEffect(() => {
    const id = refocus.current;
    if (!id) return;
    refocus.current = null;
    listRef.current
      ?.querySelector<HTMLElement>(`[data-row-id="${CSS.escape(id)}"]`)
      ?.focus({ preventScroll: false });
  });

  const snapshot = () => {
    const depths = new Map<string, { depth: number; top: number }>();
    listRef.current
      ?.querySelectorAll<HTMLElement>("[data-row-id][data-depth]")
      .forEach((el) =>
        depths.set(el.dataset.rowId!, {
          depth: Number(el.dataset.depth),
          top: el.offsetTop,
        }),
      );
    return depths;
  };

  /** Why a row can't go into parent, or null. */
  const refusal = (node: T, parent: T | null) => {
    if (parent?.leaf) return `${parent.title} can't hold other rows`;
    if (
      parent &&
      (parent.id === node.id || under(nodesRef.current, node.id).has(parent.id))
    )
      return `Can't move ${node.title} inside itself`;
    return (canDrop?.(node, parent) as string | null | undefined) || null;
  };

  /** Moves a row (optimistically) and saves it; a failed save puts everything back. */
  const moveTo = async (
    node: T,
    parent: string | null,
    after: string | null | "end",
    from?: { x: number; y: number },
  ) => {
    const previous = nodesRef.current;
    const next = place(previous, node.id, parent, after);
    landing.current = { id: node.id, from, depths: snapshot() };
    // The row stays in view: its new parent opens. Rows that only opened while it was carried close again.
    const ids = new Set(openRef.current);
    sprung.current.forEach((id) => id !== parent && ids.delete(id));
    sprung.current.clear();
    if (parent) ids.add(parent);
    setOpenIds(ids);
    commit(next);
    const parentNode = byId(parent);
    const sibs = next.filter((n) => n.parent === parent);
    const index = sibs.findIndex((n) => n.id === node.id);
    say(
      `Moved ${node.title} ${parentNode ? `into ${parentNode.title}` : "to the top level"}, ${index + 1} of ${sibs.length}.`,
    );
    if (!onMove) return;
    try {
      await onMove({ ...node, parent } as T, parentNode, index);
    } catch {
      landing.current = { depths: snapshot() };
      commit(
        place(
          nodesRef.current,
          node.id,
          node.parent,
          (() => {
            const before = previous.filter((n) => n.parent === node.parent);
            const i = before.findIndex((n) => n.id === node.id);
            return i > 0 ? before[i - 1].id : null;
          })(),
        ),
      );
      warn(`Couldn't move ${node.title}. It's back.`, "error");
      say(`Couldn't move ${node.title}. It's back where it was.`);
      window.setTimeout(() => {
        if (reduced) return;
        listRef.current
          ?.querySelector<HTMLElement>(
            `[data-row-id="${CSS.escape(node.id)}"] [data-row-content]`,
          )
          ?.animate(
            [
              { transform: "none" },
              { transform: "translateX(-4px)" },
              { transform: "translateX(4px)" },
              { transform: "translateX(-2px)" },
              { transform: "none" },
            ],
            { duration: 380, easing: "ease-out" },
          );
      }, GLIDE);
    }
  };

  // ── Carrying ───────────────────────────────────────────
  const drag = useTreeDrag({
    list: listRef,
    scroller: scrollerRef,
    preview: previewRef,
    reason: reasonRef,
    line: lineRef,
    ring: ringRef,
    indent,
    inset: INSET,
    check: (id, target) => {
      const node = byId(id) as T | null;
      if (!node) return { same: true, refused: null };
      const parent = byId(target.parent) as T | null;
      const next = place(
        nodesRef.current,
        id,
        target.parent,
        target.into ? "end" : target.after,
      );
      const was = nodesRef.current
        .filter((n) => n.parent === node.parent)
        .findIndex((n) => n.id === id);
      const now = next
        .filter((n) => n.parent === target.parent)
        .findIndex((n) => n.id === id);
      return {
        same: target.parent === node.parent && was === now,
        refused: refusal(node, parent),
      };
    },
    onLift: (id) => {
      setLifted(id);
      setRenaming(null);
      const node = byId(id);
      if (node) say(`Carrying ${node.title}.`);
    },
    onSpring: (id) => {
      sprung.current.add(id);
      const ids = new Set(openRef.current);
      ids.add(id);
      setOpenIds(ids);
    },
    onDrop: (id, target, from) => {
      setLifted(null);
      const node = byId(id) as T | null;
      if (node)
        moveTo(node, target.parent, target.into ? "end" : target.after, from);
    },
    onCancel: (id, refused) => {
      setLifted(null);
      if (sprung.current.size) {
        const ids = new Set(openRef.current);
        sprung.current.forEach((x) => ids.delete(x));
        sprung.current.clear();
        setOpenIds(ids);
      }
      if (refused) {
        warn(refused);
        say(`${byId(id)?.title ?? "The row"} went back. ${refused}.`);
      }
    },
    reduced,
    disabled: !!renaming || !!draft,
  });

  // The copy appears under the pointer; rows that opened mid-carry are measured again.
  React.useLayoutEffect(() => {
    if (lifted) drag.sync();
  }, [lifted, drag]);
  React.useLayoutEffect(() => {
    drag.remeasure();
  }, [open, drag]);

  // ── Opening, renaming, adding, deleting ────────────────
  const toggle = (node: T, to?: boolean) => {
    if (node.leaf) return;
    const ids = new Set(openRef.current);
    const on = to ?? !ids.has(node.id);
    if (on) ids.add(node.id);
    else ids.delete(node.id);
    setOpenIds(ids);
  };

  const commitRename = async (node: T, value: string) => {
    if (renamingRef.current !== node.id) return;
    renamingRef.current = null;
    setRenaming(null);
    refocus.current = node.id;
    const title = value.trim();
    if (!title || title === node.title) return;
    commit(
      nodesRef.current.map((n) =>
        n.id === node.id ? ({ ...n, title } as T) : n,
      ),
    );
    say(`Renamed to ${title}.`);
    try {
      await onRename?.(node, title);
    } catch {
      commit(
        nodesRef.current.map((n) =>
          n.id === node.id ? ({ ...n, title: node.title } as T) : n,
        ),
      );
      warn(`Couldn't rename ${node.title}.`, "error");
    }
  };

  const startRename = (node: T) => {
    if (!onRename) return;
    renamingRef.current = node.id;
    setRenaming(node.id);
  };

  const addInside = (parent: T | null) => {
    if (!onCreate) return;
    if (parent) toggle(parent, true);
    setDraft({ parent: parent?.id ?? null, key: ++draftSeq.current });
  };

  const finishDraft = async (title: string) => {
    const d = draft;
    if (!d) return;
    const name = title.trim();
    setDraft(null);
    if (!name || !onCreate) return;
    try {
      const made = await onCreate(byId(d.parent) as T | null, name);
      const node = { ...made, parent: d.parent } as T;
      commit([...nodesRef.current, node]);
      select(node);
      refocus.current = made.id;
      say(`Added ${made.title}.`);
    } catch {
      warn(`Couldn't add “${name}”.`, "error");
    }
  };

  const remove = (node: T) => {
    if (!onDelete) return;
    if (undo) finishUndo(undo);
    const gone = new Set([node.id, ...under(nodesRef.current, node.id)]);
    const previous = nodesRef.current;
    const i = nodeRows.findIndex((r) => r.node.id === node.id);
    const nextFocus =
      nodeRows.slice(i + 1).find((r) => !gone.has(r.node.id)) ??
      nodeRows.slice(0, i).reverse()[0];
    commit(previous.filter((n) => !gone.has(n.id)));
    setUndo({
      key: ++undoSeq.current,
      node,
      removed: previous.filter((n) => gone.has(n.id)),
      nodes: previous,
    });
    if (nextFocus) refocus.current = nextFocus.node.id;
    say(
      `Deleted ${node.title}${gone.size > 1 ? ` and ${gone.size - 1} inside it` : ""}. Undo is below.`,
    );
  };

  const takeBack = () => {
    if (!undo) return;
    const ids = new Set(undo.removed.map((n) => n.id));
    // Back in their old places among whatever is there now.
    const now = nodesRef.current;
    const restored = undo.nodes
      .filter((n) => ids.has(n.id) || now.some((m) => m.id === n.id))
      .map((n) => (ids.has(n.id) ? n : now.find((m) => m.id === n.id)!));
    commit([
      ...restored,
      ...now.filter((n) => !restored.some((r) => r.id === n.id)),
    ]);
    setUndo(null);
    refocus.current = undo.node.id;
    say(`${undo.node.title} is back.`);
  };

  const finishUndo = async (u: Undo<T>) => {
    setUndo((x) => (x?.key === u.key ? null : x));
    try {
      await onDelete?.(u.node);
    } catch {
      commit([...nodesRef.current, ...u.removed]);
      warn(`Couldn't delete ${u.node.title}. It's back.`, "error");
    }
  };

  // ── Keys ───────────────────────────────────────────────
  const focusRow = (id: string | undefined) => {
    if (!id) return;
    setFocusId(id);
    listRef.current
      ?.querySelector<HTMLElement>(`[data-row-id="${CSS.escape(id)}"]`)
      ?.focus();
  };

  const onRowKey = (e: React.KeyboardEvent, node: T) => {
    if (e.target !== e.currentTarget) return;
    const i = nodeRows.findIndex((r) => r.node.id === node.id);
    const row = nodeRows[i];
    if (!row) return;
    const sibs = nodesRef.current.filter((n) => n.parent === node.parent);
    const si = sibs.findIndex((n) => n.id === node.id);

    if (e.altKey && e.key.startsWith("Arrow")) {
      e.preventDefault();
      let to: { parent: string | null; after: string | null | "end" } | null =
        null;
      if (e.key === "ArrowUp" && si > 0)
        to = { parent: node.parent, after: si > 1 ? sibs[si - 2].id : null };
      if (e.key === "ArrowDown" && si < sibs.length - 1)
        to = { parent: node.parent, after: sibs[si + 1].id };
      if (e.key === "ArrowRight" && si > 0 && !sibs[si - 1].leaf)
        to = { parent: sibs[si - 1].id, after: "end" };
      if (e.key === "ArrowLeft" && node.parent)
        to = { parent: byId(node.parent)?.parent ?? null, after: node.parent };
      if (!to) return;
      const why = refusal(node, byId(to.parent) as T | null);
      if (why) {
        warn(why);
        say(why);
        return;
      }
      refocus.current = node.id;
      moveTo(node, to.parent, to.after);
      return;
    }

    switch (e.key) {
      case "ArrowDown":
        e.preventDefault();
        focusRow(nodeRows[i + 1]?.node.id);
        return;
      case "ArrowUp":
        e.preventDefault();
        focusRow(nodeRows[i - 1]?.node.id);
        return;
      case "Home":
        e.preventDefault();
        focusRow(nodeRows[0]?.node.id);
        return;
      case "End":
        e.preventDefault();
        focusRow(nodeRows[nodeRows.length - 1]?.node.id);
        return;
      case "ArrowRight":
        e.preventDefault();
        if (!node.leaf && !row.open) toggle(node, true);
        else if (row.open && row.hasChildren)
          focusRow(nodeRows[i + 1]?.node.id);
        return;
      case "ArrowLeft":
        e.preventDefault();
        if (row.open) toggle(node, false);
        else if (node.parent) focusRow(node.parent);
        return;
      case "Enter":
      case " ":
        e.preventDefault();
        select(node);
        return;
      case "F2":
        e.preventDefault();
        startRename(node);
        return;
      case "Delete":
      case "Backspace":
        if (!onDelete) return;
        e.preventDefault();
        remove(node);
        return;
    }
    // Type to jump: the next row whose title starts with what was typed.
    if (e.key.length === 1 && !e.metaKey && !e.ctrlKey && !e.altKey) {
      const now = e.timeStamp;
      typed.current = {
        text:
          (now - typed.current.at < 600 ? typed.current.text : "") +
          e.key.toLowerCase(),
        at: now,
      };
      const t = typed.current.text;
      const order = [
        ...nodeRows.slice(i + (t.length === 1 ? 1 : 0)),
        ...nodeRows.slice(0, i + (t.length === 1 ? 1 : 0)),
      ];
      focusRow(
        order.find((r) => r.node.title.toLowerCase().startsWith(t))?.node.id,
      );
    }
  };

  // What the memoised rows call, through one ref, so a row never re-renders just because these were re-created.
  const actions = React.useRef<RowActions<T>>({
    click: () => {},
    toggle: () => {},
    key: () => {},
    focus: () => {},
    rename: () => {},
    commitRename: () => {},
    cancelRename: () => {},
    add: () => {},
    remove: () => {},
    icon: icon as RowActions<T>["icon"],
  });

  React.useLayoutEffect(() => {
    actions.current = {
      click: (e, node) => {
        if (drag.swallowClick() || renaming === node.id) return;
        if (e.detail > 1) return;
        setFocusId(node.id);
        select(node);
      },
      toggle: (node) => toggle(node),
      key: onRowKey,
      focus: (node) => setFocusId(node.id),
      rename: startRename,
      commitRename,
      cancelRename: () => {
        if (renamingRef.current) refocus.current = renamingRef.current;
        renamingRef.current = null;
        setRenaming(null);
      },
      add: (node) => addInside(node),
      remove,
      icon: icon as RowActions<T>["icon"],
    };
  });

  const liftedRow = lifted
    ? nodeRows.find((r) => r.node.id === lifted)
    : undefined;
  const liftedCount = lifted ? under(nodes, lifted).size : 0;

  return (
    <div
      className={`@container flex flex-col text-foreground ${className}`}
      {...props}
    >
      <div
        ref={scrollerRef}
        className="relative min-h-0 flex-1 overflow-y-auto overflow-x-hidden overscroll-contain [scrollbar-width:thin]"
      >
        <ul
          ref={listRef}
          role="tree"
          aria-label={label}
          aria-describedby={`${uid}-how`}
          {...drag.handlers}
          className="relative flex flex-col py-0.5"
        >
          {rows.map((r) => {
            if (r.kind === "empty")
              return (
                <li
                  key={`${r.parent}::empty`}
                  data-row-id={`${r.parent}::empty`}
                  role="none"
                  className="flex shrink-0 items-center text-[12.5px] text-muted-foreground"
                  style={{
                    height: ROW_H,
                    paddingLeft: INSET + r.depth * indent,
                  }}
                >
                  Nothing inside
                </li>
              );
            if (r.kind === "draft")
              return (
                <li
                  key={`draft-${draft?.key}`}
                  data-row-id="__draft"
                  role="none"
                  className="shrink-0"
                  style={{ height: ROW_H }}
                >
                  <div
                    className="flex h-full items-center gap-1.5 pr-1"
                    style={{ paddingLeft: 4 + r.depth * indent }}
                  >
                    <span className="size-5 shrink-0" aria-hidden="true" />
                    <span
                      className="flex size-4 shrink-0 items-center justify-center text-muted-foreground [&_svg]:size-4"
                      aria-hidden="true"
                    >
                      <File strokeWidth={1.75} />
                    </span>
                    <input
                      autoFocus
                      placeholder={`New ${addLabel}`}
                      aria-label={`New ${addLabel}${r.parent ? ` in ${byId(r.parent)?.title}` : ""}`}
                      onKeyDown={(e) => {
                        if (e.key === "Enter")
                          finishDraft(e.currentTarget.value);
                        if (e.key === "Escape") {
                          setDraft(null);
                          if (r.parent) refocus.current = r.parent;
                        }
                      }}
                      onBlur={(e) => finishDraft(e.currentTarget.value)}
                      className="-ml-1 h-6 min-w-0 flex-1 rounded-[6px] bg-background px-1 text-[13.5px] outline-none shadow-[inset_0_0_0_1px_var(--ring)] placeholder:text-muted-foreground [@media(pointer:coarse)]:text-[16px]"
                    />
                  </div>
                </li>
              );
            const id = r.node.id;
            return (
              <TreeRow
                key={id}
                node={r.node}
                depth={r.depth}
                hasChildren={r.hasChildren}
                open={r.open}
                pos={r.pos}
                size={r.size}
                selected={selected === id}
                tab={tabId === id}
                dimmed={
                  !!lifted &&
                  (lifted === id ||
                    (liftedRow ? isUnder(rows, liftedRow, r) : false))
                }
                renaming={renaming === id}
                canAdd={!!onCreate}
                canDelete={!!onDelete}
                canRename={!!onRename}
                indent={indent}
                reduced={reduced}
                actions={actions}
              />
            );
          })}

          {/* Where it lands: a line from the depth it would take, or a ring round the row it would go inside. */}
          <div
            ref={lineRef}
            aria-hidden="true"
            className="pointer-events-none absolute left-0 top-0 h-0.5 opacity-0"
            style={{
              transition: reduced
                ? "none"
                : "transform 90ms ease-out, opacity 120ms ease-out",
            }}
          >
            <span className="absolute inset-0 rounded-full bg-current" />
            <span className="absolute -left-1 -top-[3px] size-2 rounded-full border-[1.5px] border-current bg-background" />
          </div>
          <div
            ref={ringRef}
            aria-hidden="true"
            className="pointer-events-none absolute inset-x-0 top-0 rounded-[8px] opacity-0"
            style={{
              boxShadow: "inset 0 0 0 1.5px currentColor",
              background: "color-mix(in oklab, currentColor 8%, transparent)",
              transition: reduced ? "none" : "opacity 120ms ease-out",
            }}
          />

          {/* The copy you carry. */}
          {liftedRow && (
            <div
              ref={previewRef}
              aria-hidden="true"
              className="pointer-events-none absolute left-0 top-0 z-10 w-full will-change-transform"
            >
              <div
                className="flex items-center gap-1.5 rounded-[8px] bg-background pr-2 text-[13.5px] font-medium shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--foreground)_22%,transparent)]"
                style={{
                  height: ROW_H,
                  marginLeft: liftedRow.depth * indent,
                  paddingLeft: 4,
                  width: `min(100% - ${liftedRow.depth * indent}px, 260px)`,
                }}
              >
                <span className="size-5 shrink-0" />
                <span className="flex size-4 shrink-0 items-center justify-center text-muted-foreground [&_svg]:size-4">
                  {icon(liftedRow.node, {
                    expanded: false,
                    hasChildren: liftedRow.hasChildren,
                  })}
                </span>
                <span className="min-w-0 flex-1 truncate">
                  {liftedRow.node.title}
                </span>
                {liftedCount > 0 && (
                  <span className="shrink-0 rounded-full px-1.5 text-[11px] font-normal tabular-nums text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)]">
                    +{liftedCount}
                  </span>
                )}
              </div>
              <p
                ref={reasonRef}
                hidden
                className="mt-1 text-[11.5px] font-normal text-amber-700 dark:text-amber-400"
                style={{ marginLeft: liftedRow.depth * indent + 30 }}
              />
            </div>
          )}

          {/* Rows that went: their own elements, folding away where they stood (see use-row-motion). */}
          <div
            ref={ghostRef}
            aria-hidden="true"
            className="pointer-events-none absolute inset-0"
          />
        </ul>
      </div>

      {onCreate && (
        <button
          type="button"
          onClick={() => addInside(null)}
          className={`mt-1 flex h-[30px] shrink-0 cursor-pointer items-center gap-1.5 rounded-[8px] pl-1 text-[13px] text-muted-foreground transition-colors hover:bg-accent/60 hover:text-foreground ${FOCUS}`}
        >
          <span
            className="flex size-5 items-center justify-center"
            aria-hidden="true"
          >
            <Plus className="size-3.5" strokeWidth={1.75} />
          </span>
          New {addLabel}
        </button>
      )}

      {/* One line under the tree: Undo while a delete can still be taken back, or what went wrong. */}
      <div
        className="grid shrink-0 transition-[grid-template-rows] duration-300"
        style={{
          gridTemplateRows: undo || note ? "1fr" : "0fr",
          transitionTimingFunction: EASE,
        }}
      >
        <div className="min-h-0 overflow-hidden">
          {undo ? (
            <div
              className="relative mt-1.5 flex h-8 items-center gap-2 rounded-[8px] pl-2.5 pr-1 text-[12.5px] shadow-[inset_0_0_0_1px_var(--border)]"
              onPointerEnter={() => setHoldUndo(true)}
              onPointerLeave={() => setHoldUndo(false)}
            >
              <span className="min-w-0 flex-1 truncate">
                Deleted “{undo.node.title}”
              </span>
              <button
                type="button"
                onClick={takeBack}
                className={`inline-flex h-6 shrink-0 cursor-pointer items-center rounded-[6px] px-2 font-medium hover:bg-accent ${FOCUS}`}
              >
                Undo
              </button>
              <span
                key={undo.key}
                aria-hidden="true"
                className="absolute inset-x-2 bottom-0 h-px origin-left bg-foreground/40"
                style={{
                  animation: `ui-progress ${undoFor}ms linear reverse forwards`,
                  animationPlayState: holdUndo ? "paused" : "running",
                }}
                onAnimationEnd={() => finishUndo(undo)}
              />
            </div>
          ) : (
            <Line
              text={note?.text ?? ""}
              className={`px-2 pt-1.5 text-[12px] ${note?.tone === "error" ? "text-red-600 dark:text-red-400" : "text-amber-700 dark:text-amber-400"}`}
            />
          )}
        </div>
      </div>

      <p id={`${uid}-how`} className="sr-only">
        Arrow keys move between rows and open them. Alt with the arrow keys
        moves a row up, down, into the row above or out of its parent. F2
        renames, Delete deletes. Drag a row to move it; on a touch screen, hold
        it first.
      </p>
      <p className="sr-only" role="status" aria-live="polite">
        {announce}
      </p>
    </div>
  );
}

/** Is `row` inside `parent` (a contiguous run of deeper rows after it)? */
function isUnder<T extends TreeNode>(
  rows: Row<T>[],
  parent: Row<T>,
  row: Row<T>,
) {
  const a = rows.indexOf(parent);
  const b = rows.indexOf(row);
  if (b <= a) return false;
  for (let k = a + 1; k <= b; k++)
    if (rows[k].depth <= parent.depth) return false;
  return true;
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";
import { TimeBrush } from "./time-brush";

/* ─────────────────────────────────────────────────────────
 * TREND CHART: one metric over time, read by pointer or keys
 *
 *   change   same buckets, new numbers (a filter): the line morphs
 *            into place and the scale rolls. New buckets (a range):
 *            the old line stretches or shrinks to where its days sit
 *            on the new axis while the new one fades in over it, so
 *            zooming in looks like zooming in
 *   compare  the period before as a dashed line, drawn in from the
 *            left when it's turned on
 *   hover    a thin line and a dot follow the pointer; one readout
 *            card glides beside them, its date morphing and its
 *            figures rolling
 *   drag     drag across the chart to zoom into those buckets (Time
 *            brush, snapped to bucket edges)
 *   today    a bucket that isn't over yet is drawn dashed, so a dip
 *            at the end isn't news
 * ───────────────────────────────────────────────────────── */

export type TrendInterval = "hour" | "day" | "week" | "month";
/** How the figures read: plain counts (or money, with `format`), percentages (0–100) or durations in seconds. */
export type TrendKind = "count" | "percent" | "duration";

export interface TrendChartProps {
  /** Bucket starts (epoch ms), oldest first. */
  buckets: number[];
  /** One value per bucket. */
  values: number[];
  /** The period before, bucket for bucket; null or left out hides the dashed line. */
  previous?: number[] | null;
  /** How long one bucket is. */
  interval?: TrendInterval;
  kind?: TrendKind;
  /** Number format for counts, e.g. { style: "currency", currency: "USD" }. The scale writes the same format compactly. */
  format?: Intl.NumberFormatOptions;
  /** What one value is called in a sentence: "3,412 visitors". */
  unit?: string;
  /** How the readout names the dashed line. */
  previousLabel?: string;
  /** The time now (epoch ms): a last bucket that ends after it is unfinished and drawn dashed. The clock at mount by default. */
  now?: number;
  /** Called with the span dragged across. Leave it out and the chart can't be brushed. */
  onZoom?: (range: { start: number; end: number }) => void;
  /** A line under the figures in the readout, e.g. who sent that day's visitors. */
  note?: (index: number) => string | null | undefined;
  /** The bucket the pointer or keys are on, for linking other widgets to the readout. */
  onActiveChange?: (index: number | null) => void;
  /** Accessible name. */
  label: string;
  /** For dates and numbers; the viewer's own by default. */
  locale?: string;
  className?: string;
}

type Snapshot = {
  key: string;
  buckets: number[];
  centers: number[];
  values: number[];
  previous: number[] | null;
  domain: [number, number];
  max: number;
  partial: boolean;
  interval: TrendInterval;
};

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const DURATION = 640;
const TOP = 10;
const AXIS = 26;
const STEPS = 4;
const HOUR = 3_600_000;
const DAY = 86_400_000;
const WHOLE: Intl.NumberFormatOptions = { maximumFractionDigits: 0 };

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const ease = (t: number) => 1 - Math.pow(1 - t, 4);
const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
const lerpAll = (a: number[], b: number[], t: number) =>
  b.map((v, i) => lerp(a[i] ?? v, v, t));

/** `t` moved on by one bucket, in calendar terms (a day across a clock change is still one day). */
function nextBucket(t: number, interval: TrendInterval) {
  if (interval === "hour") return t + HOUR;
  const d = new Date(t);
  if (interval === "month") d.setMonth(d.getMonth() + 1);
  else d.setDate(d.getDate() + (interval === "week" ? 7 : 1));
  return d.getTime();
}

/** "2m 41s", "48s", "1h 3m". */
export function formatDuration(seconds: number) {
  const s = Math.round(seconds);
  if (s < 60) return `${s}s`;
  if (s < 3600) return `${Math.floor(s / 60)}m ${s % 60}s`;
  return `${Math.floor(s / 3600)}h ${Math.floor((s % 3600) / 60)}m`;
}

/** A round top for a scale with four steps: 1,840 → 2,000. Durations step in whole minutes. */
function niceTop(value: number, kind: TrendKind) {
  if (value <= 0)
    return kind === "duration" ? 240 : kind === "percent" ? 100 : STEPS;
  if (kind === "percent")
    return Math.min(100, Math.ceil(value / 20) * 20) || 100;
  const raw = value / STEPS;
  if (kind === "duration") {
    const step =
      [15, 30, 60, 90, 120, 180, 300, 600, 900, 1800].find((s) => s >= raw) ??
      Math.ceil(raw / 1800) * 1800;
    return step * STEPS;
  }
  const mag = 10 ** Math.floor(Math.log10(raw));
  const step =
    [1, 1.5, 2, 2.5, 3, 4, 5, 6, 8, 10]
      .map((x) => x * mag)
      .find((s) => s >= raw) ?? 10 * mag;
  return step * STEPS;
}

const r2 = (v: number) => Math.round(v * 100) / 100;

/** A smooth line that never overshoots its points (monotone cubic), split into segments so the last one can be drawn dashed. */
function monotoneSegments(points: [number, number][]) {
  const n = points.length;
  if (!n) return { head: "", segments: [] as string[] };
  const head = `M${r2(points[0][0])},${r2(points[0][1])}`;
  if (n === 1) return { head, segments: [] as string[] };
  const m: number[] = [];
  for (let i = 0; i < n - 1; i++)
    m.push(
      (points[i + 1][1] - points[i][1]) /
        (points[i + 1][0] - points[i][0] || 1),
    );
  const t: number[] = [m[0]];
  for (let i = 1; i < n - 1; i++)
    t.push(m[i - 1] * m[i] <= 0 ? 0 : (m[i - 1] + m[i]) / 2);
  t.push(m[n - 2]);
  for (let i = 0; i < n - 1; i++) {
    if (m[i] === 0) {
      t[i] = 0;
      t[i + 1] = 0;
      continue;
    }
    const a = t[i] / m[i];
    const b = t[i + 1] / m[i];
    const s = a * a + b * b;
    if (s > 9) {
      const k = 3 / Math.sqrt(s);
      t[i] = k * a * m[i];
      t[i + 1] = k * b * m[i];
    }
  }
  const segments: string[] = [];
  for (let i = 0; i < n - 1; i++) {
    const [x0, y0] = points[i];
    const [x1, y1] = points[i + 1];
    const dx = (x1 - x0) / 3;
    segments.push(
      `C${r2(x0 + dx)},${r2(y0 + t[i] * dx)} ${r2(x1 - dx)},${r2(y1 - t[i + 1] * dx)} ${r2(x1)},${r2(y1)}`,
    );
  }
  return { head, segments };
}

/** Dates for one locale: the readout's title, the axis ticks and the brush's edges. */
function dateWords(locale: string | undefined) {
  const day = new Intl.DateTimeFormat(locale, {
    weekday: "short",
    day: "numeric",
    month: "short",
  });
  const short = new Intl.DateTimeFormat(locale, {
    day: "numeric",
    month: "short",
  });
  const hour = new Intl.DateTimeFormat(locale, { hour: "numeric" });
  const clock = new Intl.DateTimeFormat(locale, {
    hour: "2-digit",
    minute: "2-digit",
  });
  const month = new Intl.DateTimeFormat(locale, {
    month: "long",
    year: "numeric",
  });
  const monthShort = new Intl.DateTimeFormat(locale, { month: "short" });
  return {
    /** "Fri 18 Sep" · "Fri 18 Sep, 2 PM" · "Week of 14 Sep" · "September 2026". */
    title: (t: number, interval: TrendInterval) =>
      interval === "hour"
        ? `${day.format(t)}, ${hour.format(t)}`
        : interval === "week"
          ? `Week of ${short.format(t)}`
          : interval === "month"
            ? month.format(t)
            : day.format(t),
    /** "18 Sep", "2 PM", "Sep". */
    tick: (t: number, interval: TrendInterval) =>
      interval === "hour"
        ? hour.format(t)
        : interval === "month"
          ? monthShort.format(t)
          : short.format(t),
    edge: (t: number, interval: TrendInterval) =>
      interval === "hour"
        ? clock.format(t)
        : interval === "month"
          ? monthShort.format(t)
          : short.format(t),
  };
}

function snapshotOf(p: {
  buckets: number[];
  values: number[];
  previous: number[] | null;
  interval: TrendInterval;
  kind: TrendKind;
  now: number | null;
}): Snapshot | null {
  const n = p.buckets.length;
  if (!n) return null;
  const ends = p.buckets.map(
    (b, i) => p.buckets[i + 1] ?? nextBucket(b, p.interval),
  );
  return {
    key: `${p.kind}|${p.interval}|${p.buckets[0]}|${n}|${p.values.join(",")}|${p.previous?.join(",") ?? ""}`,
    buckets: p.buckets,
    centers: p.buckets.map((b, i) => (b + ends[i]) / 2),
    values: p.values,
    previous: p.previous,
    domain: [p.buckets[0], ends[n - 1]],
    max: niceTop(Math.max(0, ...p.values, ...(p.previous ?? [])), p.kind),
    partial: p.now !== null && ends[n - 1] > p.now + 60_000,
    interval: p.interval,
  };
}

const sameBuckets = (a: Snapshot, b: Snapshot) =>
  a.interval === b.interval &&
  a.buckets.length === b.buckets.length &&
  a.buckets[0] === b.buckets[0];

/**
 * A sentence that changes crossfades whole: the old one lifts away through a blur while the
 * new one rises in. (Letters of two sentences don't morph well; labels use TextMorph.)
 */
function Swap({
  text,
  reduced,
  className = "",
}: {
  text: string;
  reduced: boolean;
  className?: string;
}) {
  const [shown, setShown] = React.useState({ text, key: 0 });
  const [leaving, setLeaving] = React.useState<{ text: string; key: number }[]>(
    [],
  );
  if (text !== shown.text) {
    if (shown.text && !reduced) setLeaving((l) => [...l.slice(-2), shown]);
    setShown({ text, key: shown.key + 1 });
  }
  return (
    <span className={`relative block ${className}`}>
      <span
        key={shown.key}
        className="block truncate"
        ref={(el) => {
          if (!el || reduced || shown.key === 0 || el.dataset.in) return;
          el.dataset.in = "1";
          el.animate(
            [
              {
                opacity: 0,
                transform: "translateY(0.3em)",
                filter: "blur(4px)",
              },
              { opacity: 1, transform: "none", filter: "blur(0px)" },
            ],
            { duration: 320, delay: 40, easing: EASE, fill: "backwards" },
          );
        }}
      >
        {shown.text || " "}
      </span>
      {leaving.map((l) => (
        <span
          key={l.key}
          aria-hidden="true"
          className="pointer-events-none absolute inset-x-0 bottom-0 block truncate"
          ref={(el) => {
            if (!el || el.dataset.out) return;
            el.dataset.out = "1";
            el.animate(
              [
                { opacity: 1, filter: "blur(0px)" },
                {
                  opacity: 0,
                  transform: "translateY(-0.3em)",
                  filter: "blur(4px)",
                },
              ],
              { duration: 160, easing: EASE, fill: "forwards" },
            ).onfinish = () =>
              setLeaving((all) => all.filter((x) => x.key !== l.key));
          }}
        >
          {l.text}
        </span>
      ))}
    </span>
  );
}

export function TrendChart({
  buckets,
  values,
  previous = null,
  interval = "day",
  kind = "count",
  format,
  unit,
  previousLabel = "the period before",
  now: nowProp,
  onZoom,
  note,
  onActiveChange,
  label,
  locale,
  className = "",
}: TrendChartProps) {
  const reduced = useReducedMotion();
  const gradientId = `trend-wash-${React.useId().replace(/:/g, "")}`;
  // Without a `now`, the clock at mount (null on the server, so the first paint matches).
  const [mountedAt, setMountedAt] = React.useState<number | null>(null);
  React.useEffect(() => {
    const timer = window.setTimeout(() => setMountedAt(Date.now()), 0);
    return () => window.clearTimeout(timer);
  }, []);
  const now = nowProp ?? mountedAt;
  const target = React.useMemo(
    () => snapshotOf({ buckets, values, previous, interval, kind, now }),
    [buckets, values, previous, interval, kind, now],
  );
  const [frame, setFrame] = React.useState<{
    from: Snapshot | null;
    to: Snapshot | null;
    morph: boolean;
    p: number;
  }>({ from: null, to: null, morph: false, p: 1 });
  const drawnRef = React.useRef(frame);
  React.useLayoutEffect(() => {
    drawnRef.current = frame;
  });
  const [arrived, setArrived] = React.useState(false);
  const [width, setWidth] = React.useState(0);
  const [plotH, setPlotH] = React.useState(200);
  const [active, setActive] = React.useState<number | null>(null);
  const [keyboard, setKeyboard] = React.useState(false);
  const [card, setCard] = React.useState({ w: 180, h: 80 });
  const plotRef = React.useRef<HTMLDivElement>(null);
  const boxRef = React.useRef<HTMLDivElement>(null);
  const cardRef = React.useRef<HTMLDivElement>(null);
  const words = React.useMemo(() => dateWords(locale), [locale]);
  const numbers = React.useMemo(
    () => new Intl.NumberFormat(locale, format ?? WHOLE),
    [locale, format],
  );

  // A new target: start from wherever the drawing is now (mid-change included).
  React.useLayoutEffect(() => {
    if (!target) return;
    const cur = drawnRef.current;
    if (!cur.to || reduced) {
      setFrame({ from: null, to: target, morph: false, p: 1 });
      if (!cur.to)
        requestAnimationFrame(() =>
          requestAnimationFrame(() => setArrived(true)),
        );
      return;
    }
    if (cur.to.key === target.key) return;
    const e = ease(cur.p);
    const here: Snapshot = cur.from
      ? {
          ...cur.to,
          values: cur.morph
            ? lerpAll(cur.from.values, cur.to.values, e)
            : cur.to.values,
          domain: [
            lerp(cur.from.domain[0], cur.to.domain[0], e),
            lerp(cur.from.domain[1], cur.to.domain[1], e),
          ],
          max: lerp(cur.from.max, cur.to.max, e),
        }
      : cur.to;
    const morph = sameBuckets(here, target);
    setFrame({ from: here, to: target, morph, p: 0 });
    const begin = performance.now();
    let raf = 0;
    const step = (t: number) => {
      const p = Math.min(1, (t - begin) / DURATION);
      setFrame((f) => (f.to === target ? { ...f, p } : f));
      if (p < 1) raf = requestAnimationFrame(step);
    };
    raf = requestAnimationFrame(step);
    return () => cancelAnimationFrame(raf);
  }, [target?.key, reduced]);

  // The plot's size comes from CSS (its height steps down in narrow cards).
  React.useLayoutEffect(() => {
    const el = boxRef.current;
    const plot = plotRef.current;
    if (!el || !plot) return;
    const measure = () => {
      setPlotH((h) =>
        el.offsetHeight - AXIS > 0 && el.offsetHeight - AXIS !== h
          ? el.offsetHeight - AXIS
          : h,
      );
      setWidth((w) => (plot.offsetWidth === w ? w : plot.offsetWidth));
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    observer.observe(plot);
    return () => observer.disconnect();
  }, []);

  React.useLayoutEffect(() => {
    const el = cardRef.current;
    if (el && active !== null)
      setCard((c) =>
        Math.abs(c.w - el.offsetWidth) < 1 &&
        Math.abs(c.h - el.offsetHeight) < 1
          ? c
          : { w: el.offsetWidth, h: el.offsetHeight },
      );
  }, [active]);

  const activeRef = React.useRef<number | null>(null);
  const setActiveIndex = (i: number | null) => {
    if (activeRef.current === i) return;
    activeRef.current = i;
    setActive(i);
    onActiveChange?.(i);
  };

  const { from, to, morph, p } = frame;
  const e = ease(p);
  const domain: [number, number] = to
    ? from
      ? [
          lerp(from.domain[0], to.domain[0], e),
          lerp(from.domain[1], to.domain[1], e),
        ]
      : to.domain
    : [0, 1];
  const max = to
    ? from
      ? lerp(from.max, to.max, e)
      : to.max
    : niceTop(0, kind);
  const x = (t: number) =>
    ((t - domain[0]) / (domain[1] - domain[0] || 1)) * width;
  const y = (v: number) =>
    TOP + (plotH - TOP) * (1 - Math.min(1.08, v / (max || 1)));

  // What's drawn: one morphing series, or the old one fading under the new one.
  const layers: { snap: Snapshot; values: number[]; alpha: number }[] = [];
  if (to) {
    if (from && morph)
      layers.push({
        snap: to,
        values: lerpAll(from.values, to.values, e),
        alpha: 1,
      });
    else {
      if (from && p < 1)
        layers.push({ snap: from, values: from.values, alpha: 1 - e });
      layers.push({ snap: to, values: to.values, alpha: from ? e : 1 });
    }
  }
  const shownValues = layers[layers.length - 1]?.values ?? [];

  const paths = (snap: Snapshot, vals: number[]) => {
    const points = snap.centers.map(
      (c, i) => [x(c), y(vals[i] ?? 0)] as [number, number],
    );
    const { head, segments } = monotoneSegments(points);
    const n = points.length;
    const tail = snap.partial && n > 1;
    const solid = head + (tail ? segments.slice(0, -1) : segments).join("");
    const dashed = tail
      ? `M${points[n - 2][0]},${points[n - 2][1]}${segments[n - 2]}`
      : "";
    const area =
      n > 1
        ? `${head}${segments.join("")}L${points[n - 1][0]},${plotH}L${points[0][0]},${plotH}Z`
        : "";
    return { solid, dashed, area };
  };
  const prevPath = (snap: Snapshot, prev: number[]) => {
    const points = snap.centers.map(
      (c, i) => [x(c), y(prev[i] ?? 0)] as [number, number],
    );
    const { head, segments } = monotoneSegments(points);
    return head + segments.join("");
  };

  const comparing = !!to?.previous;
  const [compareShown, setCompareShown] = React.useState(false);
  const [seenComparing, setSeenComparing] = React.useState(comparing);
  if (comparing !== seenComparing) {
    setSeenComparing(comparing);
    if (!comparing) setCompareShown(false);
  }
  React.useEffect(() => {
    if (!comparing) return;
    let b = 0;
    const a = requestAnimationFrame(() => {
      b = requestAnimationFrame(() => setCompareShown(true));
    });
    return () => {
      cancelAnimationFrame(a);
      cancelAnimationFrame(b);
    };
  }, [comparing]);

  const n = to?.buckets.length ?? 0;
  const indexAt = (clientX: number) => {
    const r = plotRef.current?.getBoundingClientRect();
    if (!r || !to || !n) return null;
    const t =
      domain[0] + ((clientX - r.left) / r.width) * (domain[1] - domain[0]);
    let best = 0;
    for (let i = 1; i < n; i++)
      if (Math.abs(to.centers[i] - t) < Math.abs(to.centers[best] - t))
        best = i;
    return best;
  };
  const onKeyDown = (ev: React.KeyboardEvent) => {
    if (!n) return;
    const at = active ?? n - 1;
    const moves: Record<string, number> = {
      ArrowLeft: at - 1,
      ArrowRight: at + 1,
      Home: 0,
      End: n - 1,
    };
    if (ev.key === "Escape") return setActiveIndex(null);
    if (!(ev.key in moves)) return;
    ev.preventDefault();
    setKeyboard(true);
    setActiveIndex(
      Math.min(n - 1, Math.max(0, active === null ? at : moves[ev.key])),
    );
  };

  // Ticks along the bottom: as many as fit, counted back from the newest so it always has one.
  const ticks = (snap: Snapshot) => {
    const gap = snap.interval === "hour" ? 52 : 64;
    const every = width
      ? Math.max(1, Math.ceil(gap / (width / snap.buckets.length)))
      : snap.buckets.length;
    return snap.buckets
      .map((b, i) => ({ b, i }))
      .filter(({ i }) => (snap.buckets.length - 1 - i) % every === 0);
  };

  const fmt = (v: number) =>
    kind === "percent"
      ? `${Math.round(v)}%`
      : kind === "duration"
        ? formatDuration(v)
        : numbers.format(v);
  const scale = (f: number) => {
    const v = (to?.max ?? max) * f;
    if (kind === "duration")
      return (
        <TextMorph>{v ? formatDuration(v).replace(/ 0s$/, "") : "0"}</TextMorph>
      );
    if (kind === "percent")
      return (
        <NumberRoll
          value={v}
          format={WHOLE}
          suffix="%"
          locales={locale}
          duration={700}
        />
      );
    return (
      <NumberRoll
        value={v}
        format={{
          ...format,
          notation: "compact",
          minimumFractionDigits: 0,
          maximumFractionDigits: 1,
        }}
        locales={locale}
        duration={700}
      />
    );
  };

  // The brush snaps to bucket edges, so what it covers is whole buckets.
  const brush = React.useMemo(
    () =>
      to
        ? { start: new Date(to.domain[0]), end: new Date(to.domain[1]) }
        : null,
    [to],
  );
  const snap = (t: number) => {
    if (!to) return t;
    const edges = [...to.buckets, to.domain[1]];
    let best = edges[0];
    for (const edge of edges)
      if (Math.abs(edge - t) < Math.abs(best - t)) best = edge;
    return best;
  };
  const minSpan =
    interval === "hour"
      ? HOUR
      : interval === "day"
        ? DAY - 2 * HOUR
        : interval === "week"
          ? 6 * DAY
          : 27 * DAY;
  const tag = (d: Date, edge: "start" | "end") =>
    words.edge(
      edge === "end" && interval !== "hour" ? d.getTime() - 1 : d.getTime(),
      interval,
    );

  const activeValue = active !== null ? (to?.values[active] ?? 0) : 0;
  const activePrev = active !== null ? (to?.previous?.[active] ?? null) : null;
  const ax = active !== null && to ? x(to.centers[active]) : 0;
  const ay = active !== null ? y(shownValues[active] ?? 0) : 0;
  // The card sits beside the dot, on whichever side has room. In a narrow chart with room on
  // neither side, it moves to the half of the plot the dot isn't in, so it never covers it.
  const flip = ax + 16 + card.w > width;
  const cardX = Math.max(
    0,
    Math.min(width - card.w, flip ? ax - 16 - card.w : ax + 16),
  );
  const cramped = flip && ax - 16 - card.w < 0;
  const cardY = cramped && ay < plotH / 2 ? Math.max(0, plotH - card.h - 4) : 0;
  const noteText = active !== null ? (note?.(active) ?? null) : null;
  const brushable = !!onZoom && !!to && n > 1;

  return (
    <div
      className={`@container relative [--gutter:34px] [--plot:170px] @[560px]:[--gutter:44px] @[560px]:[--plot:232px] ${className}`}
    >
      <div
        ref={boxRef}
        className="relative"
        style={{ height: `calc(var(--plot) + ${AXIS}px)` }}
      >
        {/* The scale: fine lines at fixed heights, figures that roll to the new top. */}
        {Array.from({ length: STEPS + 1 }, (_, k) => 1 - k / STEPS).map((f) => (
          <div
            key={f}
            aria-hidden="true"
            className="absolute inset-x-0"
            style={{ top: TOP + (plotH - TOP) * (1 - f) }}
          >
            <span
              className="absolute left-0 top-0 -translate-y-1/2 whitespace-nowrap text-right text-[10.5px] leading-none tabular-nums text-muted-foreground"
              style={{ width: "calc(var(--gutter) - 10px)" }}
            >
              {to ? scale(f) : null}
            </span>
            <div
              className={`border-t ${f === 0 ? "border-border" : "border-dashed border-border/80"}`}
              style={{ marginLeft: "var(--gutter)" }}
            />
          </div>
        ))}

        <div
          className="absolute right-0 top-0"
          style={{ left: "var(--gutter)", height: plotH }}
        >
          <TimeBrush
            start={brush?.start ?? new Date(0)}
            end={brush?.end ?? new Date(1)}
            onSelect={({ start, end }) => {
              setActiveIndex(null);
              onZoom?.({ start: start.getTime(), end: end.getTime() });
            }}
            snap={snap}
            formatTime={tag}
            minSpan={minSpan}
            disabled={!brushable}
            className="h-full w-full"
          >
            <div
              ref={plotRef}
              role="group"
              tabIndex={0}
              aria-label={`${label}. Arrow keys read each point${onZoom ? "; drag across the chart to zoom in" : ""}.`}
              onKeyDown={onKeyDown}
              onBlur={() =>
                keyboard && (setActiveIndex(null), setKeyboard(false))
              }
              onPointerMove={(ev) => {
                if (ev.buttons & 1 && brushable) return setActiveIndex(null);
                setKeyboard(false);
                setActiveIndex(indexAt(ev.clientX));
              }}
              onPointerDown={(ev) =>
                ev.pointerType !== "mouse" &&
                setActiveIndex(indexAt(ev.clientX))
              }
              onPointerLeave={(ev) =>
                ev.pointerType === "mouse" && setActiveIndex(null)
              }
              className="absolute inset-0 rounded-md outline-none focus-visible:ring-2 focus-visible:ring-ring/40"
            >
              <div
                className="absolute inset-0"
                style={{
                  clipPath: arrived
                    ? "inset(-12px -12px -12px -12px)"
                    : "inset(-12px 100% -12px -12px)",
                  transition: reduced ? "none" : `clip-path 1100ms ${EASE}`,
                }}
              >
                <svg
                  aria-hidden="true"
                  width={width}
                  height={plotH}
                  className="absolute inset-0 overflow-visible"
                >
                  <defs>
                    <linearGradient id={gradientId} x1="0" x2="0" y1="0" y2="1">
                      <stop
                        offset="0%"
                        stopColor="var(--primary)"
                        stopOpacity="0.16"
                      />
                      <stop
                        offset="100%"
                        stopColor="var(--primary)"
                        stopOpacity="0"
                      />
                    </linearGradient>
                  </defs>
                  {width > 0 &&
                    layers.map(({ snap, values: vals, alpha }, li) => {
                      const d = paths(snap, vals);
                      return (
                        <g
                          key={li === layers.length - 1 ? "now" : "was"}
                          opacity={alpha}
                        >
                          <path d={d.area} fill={`url(#${gradientId})`} />
                          <path
                            d={d.solid}
                            fill="none"
                            stroke="var(--primary)"
                            strokeWidth="2"
                            strokeLinecap="round"
                            strokeLinejoin="round"
                          />
                          {d.dashed && (
                            <path
                              d={d.dashed}
                              fill="none"
                              stroke="var(--primary)"
                              strokeWidth="2"
                              strokeLinecap="round"
                              strokeDasharray="3 5"
                            />
                          )}
                        </g>
                      );
                    })}
                </svg>
              </div>

              {/* The period before: drawn in from the left when comparing starts. */}
              <div
                aria-hidden="true"
                className="pointer-events-none absolute inset-0"
                style={{
                  clipPath: compareShown
                    ? "inset(-12px -12px -12px -12px)"
                    : "inset(-12px 100% -12px -12px)",
                  opacity: compareShown ? 1 : 0,
                  transition: reduced
                    ? "none"
                    : `clip-path 900ms ${EASE}, opacity 300ms ${EASE}`,
                }}
              >
                <svg
                  width={width}
                  height={plotH}
                  className="absolute inset-0 overflow-visible"
                >
                  {width > 0 &&
                    layers.map(({ snap, alpha }, li) =>
                      snap.previous ? (
                        <path
                          key={li === layers.length - 1 ? "now" : "was"}
                          d={prevPath(
                            snap,
                            morph && from?.previous && li === layers.length - 1
                              ? lerpAll(from.previous, snap.previous, e)
                              : snap.previous,
                          )}
                          opacity={alpha}
                          fill="none"
                          stroke="var(--muted-foreground)"
                          strokeOpacity="0.7"
                          strokeWidth="1.5"
                          strokeDasharray="4 4"
                        />
                      ) : null,
                    )}
                </svg>
              </div>

              {/* The pointer: a thin line, a dot, and the readout card beside them. */}
              <span
                aria-hidden="true"
                className="pointer-events-none absolute top-0 w-px bg-foreground/15"
                style={{
                  height: plotH,
                  transform: `translateX(${ax}px)`,
                  opacity: active !== null ? 1 : 0,
                  transition: reduced
                    ? "none"
                    : `transform 240ms ${THROW}, opacity 180ms ${EASE}`,
                }}
              />
              <span
                aria-hidden="true"
                className="pointer-events-none absolute left-0 top-0 size-2.5 rounded-full bg-primary shadow-[0_0_0_2.5px_var(--background)]"
                style={{
                  transform: `translate(${ax - 5}px, ${ay - 5}px) scale(${active !== null ? 1 : 0.4})`,
                  opacity: active !== null ? 1 : 0,
                  transition: reduced
                    ? "none"
                    : `transform 240ms ${THROW}, opacity 180ms ${EASE}`,
                }}
              />
              <div
                ref={cardRef}
                aria-hidden="true"
                className="pointer-events-none absolute left-0 top-1 z-10 w-max min-w-[148px] max-w-[240px] rounded-[12px] bg-popover px-3 py-2.5 text-popover-foreground shadow-[0_0_0_1px_var(--border)]"
                style={{
                  transform: `translateX(${cardX}px) translateY(${cardY + (active !== null ? 0 : 4)}px)`,
                  opacity: active !== null ? 1 : 0,
                  transition: reduced
                    ? "none"
                    : `transform 260ms ${THROW}, opacity 180ms ${EASE}`,
                }}
              >
                <p className="whitespace-nowrap text-[11.5px] text-muted-foreground">
                  <TextMorph>
                    {active !== null && to
                      ? words.title(to.buckets[active], to.interval)
                      : " "}
                  </TextMorph>
                </p>
                <p className="mt-1 flex items-baseline gap-1.5 whitespace-nowrap">
                  <span
                    data-slot="figure"
                    className="text-[19px] font-semibold leading-none tracking-[-0.03em] tabular-nums"
                  >
                    {kind === "duration" ? (
                      <TextMorph>{formatDuration(activeValue)}</TextMorph>
                    ) : (
                      <NumberRoll
                        value={activeValue}
                        suffix={kind === "percent" ? "%" : ""}
                        format={kind === "percent" ? WHOLE : (format ?? WHOLE)}
                        locales={locale}
                        duration={500}
                      />
                    )}
                  </span>
                  {unit && (
                    <span className="text-[12px] text-muted-foreground">
                      {unit}
                    </span>
                  )}
                </p>
                {activePrev !== null && (
                  <p className="mt-1.5 flex items-center gap-1.5 whitespace-nowrap text-[11.5px] text-muted-foreground">
                    <span
                      aria-hidden="true"
                      className="w-3 border-t border-dashed border-muted-foreground"
                    />
                    <span className="tabular-nums">{fmt(activePrev)}</span>{" "}
                    {previousLabel}
                  </p>
                )}
                {noteText !== null && (
                  <Swap
                    text={noteText}
                    reduced={reduced}
                    className="mt-1.5 border-t border-border pt-1.5 text-[11.5px] text-foreground"
                  />
                )}
              </div>
            </div>
          </TimeBrush>
        </div>

        {/* Along the bottom. */}
        <div
          aria-hidden="true"
          className="pointer-events-none absolute right-0 [clip-path:inset(-4px_0)]"
          style={{ left: "var(--gutter)", top: plotH + 9, height: 16 }}
        >
          {width > 0 &&
            layers.map(({ snap, alpha }, li) => (
              <div
                key={li === layers.length - 1 ? "now" : "was"}
                style={{ opacity: alpha }}
              >
                {ticks(snap).map(({ b, i }) => {
                  // Labels near an edge hang inward instead of running off the card.
                  const at = x(snap.centers[i]);
                  const shift =
                    at < 22 ? "0%" : at > width - 22 ? "-100%" : "-50%";
                  return (
                    <span
                      key={b}
                      className={`absolute top-0 whitespace-nowrap text-[11px] leading-none transition-colors duration-200 ${active === i && li === layers.length - 1 ? "text-foreground" : "text-muted-foreground"}`}
                      style={{ left: at, transform: `translateX(${shift})` }}
                    >
                      {words.tick(b, snap.interval)}
                    </span>
                  );
                })}
              </div>
            ))}
        </div>
      </div>

      <p aria-live="polite" className="sr-only">
        {keyboard && active !== null && to
          ? `${words.title(to.buckets[active], to.interval)}: ${fmt(to.values[active] ?? 0)}${unit ? ` ${unit}` : ""}${activePrev !== null ? `, ${fmt(activePrev)} ${previousLabel}` : ""}${noteText ? `. ${noteText}` : ""}`
          : ""}
      </p>
      {to && (
        <table className="sr-only">
          <caption>{label}</caption>
          <thead>
            <tr>
              <th scope="col">Period</th>
              <th scope="col">{unit ?? "Value"}</th>
              {to.previous && (
                <th scope="col">
                  {previousLabel.replace(/^\w/, (c) => c.toUpperCase())}
                </th>
              )}
            </tr>
          </thead>
          <tbody>
            {to.buckets.map((b, i) => (
              <tr key={b}>
                <th scope="row">{words.title(b, to.interval)}</th>
                <td>{fmt(to.values[i] ?? 0)}</td>
                {to.previous && <td>{fmt(to.previous[i] ?? 0)}</td>}
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

"use client";

import * as React from "react";

export const EASE_OUT = "cubic-bezier(0.16, 1, 0.3, 1)";
export const EASE_SETTLE = "cubic-bezier(0.22, 1.18, 0.36, 1)";
export const INTERACTION_FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const query = "(prefers-reduced-motion: reduce)";
const subscribe = (notify: () => void) => {
  const media = window.matchMedia(query);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};
export const useInteractionReducedMotion = () =>
  React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => false,
  );

export function useInteractionActivity<T extends Element>() {
  const ref = React.useRef<T>(null);
  const [visible, setVisible] = React.useState(false);
  const [hidden, setHidden] = React.useState(false);
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(([entry]) =>
      setVisible(entry.isIntersecting),
    );
    observer.observe(el);
    const visibility = () => setHidden(document.hidden);
    visibility();
    document.addEventListener("visibilitychange", visibility);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", visibility);
    };
  }, []);
  return { ref, active: visible && !hidden };
}

export function interactionIcon(
  on: boolean,
  reduced: boolean,
): React.CSSProperties {
  return {
    opacity: on ? 1 : 0,
    transform: on ? "none" : "scale(0.6)",
    filter: on ? "blur(0px)" : "blur(3px)",
    transition: reduced
      ? "none"
      : `opacity 220ms ${EASE_OUT}, transform 380ms ${EASE_OUT}, filter 220ms ${EASE_OUT}`,
  };
}

/** Sample recent movement rather than averaging a long drag and losing its release velocity. */
export type PointerSample = { x: number; time: number };
export function samplePointer(
  samples: PointerSample[],
  x: number,
  time: number,
) {
  samples.push({ x, time });
  while (samples.length > 2 && time - samples[0].time > 100) samples.shift();
}
export function releaseVelocity(samples: PointerSample[], now: number) {
  if (samples.length < 2 || now - samples[samples.length - 1].time > 100)
    return 0;
  const first = samples[0],
    last = samples[samples.length - 1];
  return (last.x - first.x) / Math.max(1, last.time - first.time);
}

/** A damped spring sampled by WAAPI: no React renders or perpetual frame loop. */
export function springFrames(
  from: number,
  to: number,
  velocity = 0,
  duration = 520,
) {
  const omega = 20,
    damping = 0.82,
    damped = omega * Math.sqrt(1 - damping * damping);
  const displacement = from - to;
  const coefficient =
    (velocity * 1000 + damping * omega * displacement) / damped;
  return Array.from({ length: 33 }, (_, i) => {
    const t = ((i / 32) * duration) / 1000;
    const value =
      to +
      Math.exp(-damping * omega * t) *
        (displacement * Math.cos(damped * t) +
          coefficient * Math.sin(damped * t));
    return { value: i === 32 ? to : value, offset: i / 32 };
  });
}

"use client";

import * as React from "react";
import { ChevronDown, ChevronRight } from "lucide-react";
import { NumberRoll } from "./number-roll";

/* ─────────────────────────────────────────────────────────
 * USAGE LIMITS: what an agent has left, at a glance
 *
 *   context   one bar for the context window, split by what's
 *             in it (system, tools, files, conversation); the
 *             chevron folds the breakdown open underneath, and
 *             pointing at a part steps the others back
 *   limits    each plan limit as a bar with its share and when
 *             it resets; under a day away it counts down, the
 *             minutes rolling down like a clock
 *   status    a bar turns amber past 80% and red at its limit,
 *             where "Limit reached" folds open beside the share
 *   arrive    the bars grow from the left the first time they're
 *             seen and every figure rolls up from zero
 *
 * All of it is real text; the bars are decoration.
 * ───────────────────────────────────────────────────────── */

export interface ContextPart {
  id: string;
  label: string;
  tokens: number;
}

export interface PlanLimit {
  id: string;
  label: string;
  used: number;
  limit: number;
  /** When it resets (ms or Date). */
  resetsAt?: number | Date;
}

export interface UsageLimitsProps extends React.HTMLAttributes<HTMLDivElement> {
  /** The context window, split into what fills it. */
  context?: { limit: number; parts: ContextPart[] };
  /** The plan's name, e.g. "Max". */
  plan?: string;
  limits: PlanLimit[];
  /** Makes the plan heading a link, e.g. to billing. */
  onPlanClick?: () => void;
  defaultOpen?: boolean;
  locales?: string | string[];
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const COLORS = [
  "var(--chart-1, var(--primary))",
  "var(--chart-4, #8b6fe8)",
  "var(--chart-3, #1baf7a)",
  "var(--chart-2, #e8743b)",
  "var(--chart-5, #e0a21b)",
];
const compact = (n: number, locales?: string | string[]) =>
  new Intl.NumberFormat(locales, {
    notation: "compact",
    maximumFractionDigits: 1,
  }).format(n);

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const tone = (share: number) =>
  share >= 1 ? "bg-red-500" : share >= 0.8 ? "bg-amber-500" : "";

/** "Resets in 2 h 46 min" under a day away, the minutes rolling down; "Resets Tue 3:00 pm" further out. */
function Resets({
  at,
  now,
  locales,
}: {
  at: number;
  now: number | null;
  locales?: string | string[];
}) {
  if (now === null) return <span className="invisible">Resets</span>;
  const left = Math.max(0, at - now);
  if (left > 86_400_000) {
    const d = new Date(at);
    return (
      <span>
        Resets{" "}
        {d.toLocaleString(locales ?? "en-GB", {
          weekday: "short",
          hour: "numeric",
          minute: "2-digit",
        })}
      </span>
    );
  }
  const hours = Math.floor(left / 3_600_000);
  const minutes = Math.ceil((left % 3_600_000) / 60_000);
  return (
    <span className="flex items-baseline gap-[0.25em] whitespace-nowrap">
      Resets in
      {hours > 0 && (
        <>
          <NumberRoll value={hours} direction="down" duration={700} />h
        </>
      )}
      <NumberRoll value={minutes} direction="down" duration={700} />
      min
    </span>
  );
}

export function UsageLimits({
  context,
  plan,
  limits,
  onPlanClick,
  defaultOpen = false,
  locales,
  className = "",
  ...props
}: UsageLimitsProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const [open, setOpen] = React.useState(defaultOpen);
  const [visible, setVisible] = React.useState(false);
  const [focus, setFocus] = React.useState<string | null>(null);
  const [now, setNow] = React.useState<number | null>(null);
  const rootRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          observer.disconnect();
        }
      },
      { rootMargin: "0px 0px -10% 0px" },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  // A clock that ticks on each whole minute, only once mounted (so a server render never reads as "reset").
  React.useEffect(() => {
    let timer = 0;
    const tick = () => {
      setNow(Date.now());
      timer = window.setTimeout(tick, 60_000 - (Date.now() % 60_000) + 50);
    };
    tick();
    return () => window.clearTimeout(timer);
  }, []);

  const used = context ? context.parts.reduce((s, p) => s + p.tokens, 0) : 0;
  const contextShare = context?.limit ? used / context.limit : 0;

  return (
    <div
      ref={rootRef}
      className={`@container w-full rounded-[22px] bg-background shadow-[0_0_0_1px_var(--border)] ${className}`}
      {...props}
    >
      <div className="p-4 @md:p-5">
        {context && (
          <section aria-labelledby={`${id}-context`}>
            <button
              type="button"
              aria-expanded={open}
              aria-controls={`${id}-parts`}
              onClick={() => setOpen((o) => !o)}
              className={`cursor-pointer -mx-1.5 flex w-[calc(100%+12px)] items-baseline justify-between gap-3 rounded-lg px-1.5 py-0.5 text-left ${FOCUS}`}
            >
              <span
                id={`${id}-context`}
                className="text-[12.5px] text-muted-foreground @md:text-[13px]"
              >
                Context window
              </span>
              <span className="flex items-baseline gap-1.5 whitespace-nowrap text-[12px] tabular-nums text-muted-foreground @md:text-[12.5px]">
                <span>
                  <NumberRoll
                    value={visible ? used : 0}
                    format={{ notation: "compact", maximumFractionDigits: 1 }}
                    locales={locales}
                    duration={900}
                  />{" "}
                  / {compact(context.limit, locales)}
                </span>
                <span
                  className={`font-medium ${contextShare >= 1 ? "text-red-600 dark:text-red-400" : contextShare >= 0.8 ? "text-amber-600" : "text-foreground"}`}
                >
                  <NumberRoll
                    value={visible ? contextShare : 0}
                    format={{ style: "percent" }}
                    duration={900}
                  />
                </span>
                <ChevronDown
                  aria-hidden="true"
                  className="size-3.5 self-center"
                  style={{
                    transform: open ? "rotate(180deg)" : "none",
                    transition: reduced ? "none" : `transform 320ms ${EASE}`,
                  }}
                />
              </span>
            </button>

            {/* What fills the window: one segment per part, a 2px gap between them. */}
            <div
              aria-hidden="true"
              className="mt-2 flex h-1.5 gap-[2px] overflow-hidden rounded-full bg-muted"
              onPointerLeave={() => setFocus(null)}
            >
              {context.parts.map((p, i) => (
                <span
                  key={p.id}
                  onPointerEnter={() => setFocus(p.id)}
                  className="h-full first:rounded-l-full"
                  style={{
                    width: `${visible ? (p.tokens / context.limit) * 100 : 0}%`,
                    background: COLORS[i % COLORS.length],
                    opacity: focus && focus !== p.id ? 0.3 : 1,
                    transition: reduced
                      ? "none"
                      : `width 900ms ${EASE} ${i * 70}ms, opacity 240ms ${EASE}`,
                  }}
                />
              ))}
            </div>

            <div
              id={`${id}-parts`}
              inert={!open}
              className="grid"
              style={{
                gridTemplateRows: open ? "1fr" : "0fr",
                opacity: open ? 1 : 0,
                transition: reduced
                  ? "none"
                  : `grid-template-rows 420ms ${EASE}, opacity ${open ? "320ms" : "140ms"} ${EASE}`,
              }}
            >
              <ul
                className="min-h-0 overflow-hidden"
                onPointerLeave={() => setFocus(null)}
              >
                {context.parts.map((p, i) => (
                  <li
                    key={p.id}
                    onPointerEnter={() => setFocus(p.id)}
                    className="flex items-center gap-2 pt-2 text-[12px] transition-opacity duration-200 @md:text-[12.5px]"
                    style={{ opacity: focus && focus !== p.id ? 0.45 : 1 }}
                  >
                    <span
                      aria-hidden="true"
                      className="size-[7px] shrink-0 rounded-full"
                      style={{ background: COLORS[i % COLORS.length] }}
                    />
                    <span className="min-w-0 flex-1 truncate text-muted-foreground">
                      {p.label}
                    </span>
                    <span className="tabular-nums text-foreground">
                      {compact(p.tokens, locales)}
                    </span>
                    <span className="w-9 text-right tabular-nums text-muted-foreground">
                      {Math.round((p.tokens / context.limit) * 100)}%
                    </span>
                  </li>
                ))}
              </ul>
            </div>
          </section>
        )}

        <section
          aria-labelledby={`${id}-plan`}
          className={
            context
              ? "mt-3.5 border-t border-border pt-3 @md:mt-4 @md:pt-3.5"
              : ""
          }
        >
          <h3
            id={`${id}-plan`}
            className="text-[12.5px] font-normal text-muted-foreground @md:text-[13px]"
          >
            {onPlanClick ? (
              <button
                type="button"
                onClick={onPlanClick}
                className={`cursor-pointer -mx-1.5 flex w-[calc(100%+12px)] items-center justify-between rounded-lg px-1.5 py-0.5 text-left hover:text-foreground ${FOCUS}`}
              >
                <span>Plan limits{plan ? ` · ${plan}` : ""}</span>
                <ChevronRight aria-hidden="true" className="size-3.5" />
              </button>
            ) : (
              <span>Plan limits{plan ? ` · ${plan}` : ""}</span>
            )}
          </h3>
          <ul className="mt-1">
            {limits.map((l, i) => {
              const share = l.limit ? l.used / l.limit : 0;
              const reached = share >= 1;
              return (
                <li key={l.id} className="pt-2.5 first:pt-1.5">
                  <div className="flex items-baseline justify-between gap-3 text-[12.5px] @md:text-[13px]">
                    <span className="min-w-0 truncate text-foreground">
                      {l.label}
                    </span>
                    <span className="flex shrink-0 items-baseline gap-2.5 text-[11.5px] text-muted-foreground @md:text-[12px]">
                      {l.resetsAt !== undefined && (
                        <Resets
                          at={+new Date(l.resetsAt)}
                          now={now}
                          locales={locales}
                        />
                      )}
                      {/* "Limit reached" folds open beside the share rather than replacing it. */}
                      <span className="flex items-baseline">
                        <span
                          className="grid"
                          style={{
                            gridTemplateColumns: reached ? "1fr" : "0fr",
                            opacity: reached ? 1 : 0,
                            transition: reduced
                              ? "none"
                              : `grid-template-columns 420ms ${EASE}, opacity 260ms ${EASE}`,
                          }}
                        >
                          <span className="min-w-0 overflow-hidden whitespace-nowrap pr-1.5 font-medium text-red-600 dark:text-red-400 [clip-path:inset(-4px_0)]">
                            Limit reached
                          </span>
                        </span>
                        <span
                          className={`min-w-[2.6em] text-right font-medium tabular-nums ${reached ? "text-red-600 dark:text-red-400" : share >= 0.8 ? "text-amber-600" : "text-foreground"}`}
                        >
                          <NumberRoll
                            value={visible ? Math.min(share, 1) : 0}
                            format={{ style: "percent" }}
                            duration={900}
                          />
                        </span>
                      </span>
                    </span>
                  </div>
                  <div
                    aria-hidden="true"
                    className="mt-1.5 h-1.5 overflow-hidden rounded-full bg-muted"
                  >
                    <div
                      className={`h-full rounded-full transition-colors duration-300 ${tone(share)}`}
                      style={{
                        width: `${visible ? Math.max(share > 0 ? 1.5 : 0, Math.min(share, 1) * 100) : 0}%`,
                        background: tone(share)
                          ? undefined
                          : "var(--chart-1, var(--primary))",
                        transition: reduced
                          ? "none"
                          : `width 900ms ${EASE} ${i * 90}ms, background-color 300ms ${EASE}`,
                      }}
                    />
                  </div>
                </li>
              );
            })}
          </ul>
        </section>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * USAGE METER: how much is left, before it runs out
 *
 *   normal  quiet: "1,240 of 2,000 left"; the numbers roll as
 *           they're spent and the bar eases to match
 *   low     amber once a fifth is left; the way to upgrade
 *           opens in beside the reset date
 *   out     red; the numbers fold away as the words morph to
 *           "No credits left", and "Resets Oct 12" becomes
 *           "You're out until Oct 12."
 *
 * A bar for settings and menus, or a ring small enough for a
 * composer toolbar (context windows, daily limits).
 * ───────────────────────────────────────────────────────── */

export interface UsageMeterProps extends React.HTMLAttributes<HTMLDivElement> {
  used: number;
  limit: number;
  /** What's being counted, e.g. "credits" or "messages". */
  unit?: string;
  label?: string;
  /** When it resets (ms or Date). */
  resetAt?: number | Date;
  variant?: "bar" | "ring";
  /** Share left at which it turns amber. */
  lowAt?: number;
  onUpgrade?: () => void;
  upgradeLabel?: string;
}

const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const MORPH = "cubic-bezier(0.16,1,0.3,1)";
const number = new Intl.NumberFormat("en-US");
const GROUPED = { useGrouping: true };

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** A piece of a line that opens out of nothing and folds back into it. */
function Reveal({
  show,
  reduced,
  className = "",
  children,
}: {
  show: boolean;
  reduced: boolean;
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <span
      aria-hidden={!show || undefined}
      className={`grid ${className}`}
      style={{
        gridTemplateColumns: show ? "1fr" : "0fr",
        opacity: show ? 1 : 0,
        filter: show ? "none" : "blur(3px)",
        transition: reduced
          ? "none"
          : `grid-template-columns 460ms ${MORPH}, opacity ${show ? "320ms" : "160ms"} ${MORPH}, filter 320ms ${MORPH}`,
      }}
    >
      <span className="min-w-0 whitespace-nowrap [clip-path:inset(-4px_-2px)]">
        {children}
      </span>
    </span>
  );
}

export function UsageMeter({
  used,
  limit,
  unit = "credits",
  label = "Usage",
  resetAt,
  variant = "bar",
  lowAt = 0.2,
  onUpgrade,
  upgradeLabel = "Upgrade",
  className = "",
  ...props
}: UsageMeterProps) {
  const reduced = useReducedMotion();
  const left = Math.max(0, limit - used);
  const share = limit > 0 ? Math.min(1, used / limit) : 1;
  const out = left <= 0;
  const low = !out && limit > 0 && left / limit <= lowAt;
  const tone = out ? "bg-red-500" : low ? "bg-amber-500" : "bg-foreground";
  const stroke = out
    ? "stroke-red-500"
    : low
      ? "stroke-amber-500"
      : "stroke-foreground";
  const resets =
    resetAt !== undefined
      ? new Date(resetAt).toLocaleDateString("en-US", {
          month: "short",
          day: "numeric",
        })
      : undefined;
  const summary = out
    ? `No ${unit} left`
    : `${number.format(left)} of ${number.format(limit)} ${unit} left`;

  if (variant === "ring") {
    const c = 2 * Math.PI * 8;
    return (
      <div
        role="meter"
        aria-label={label}
        aria-valuemin={0}
        aria-valuemax={limit}
        aria-valuenow={used}
        aria-valuetext={summary}
        title={`${summary}${resets ? ` · resets ${resets}` : ""}`}
        className={`inline-flex items-center gap-1.5 text-[11.5px] text-muted-foreground ${className}`}
        {...props}
      >
        <svg
          aria-hidden="true"
          viewBox="0 0 20 20"
          className="size-4 -rotate-90"
        >
          <circle
            cx="10"
            cy="10"
            r="8"
            fill="none"
            strokeWidth="2.5"
            className="stroke-border"
          />
          <circle
            cx="10"
            cy="10"
            r="8"
            fill="none"
            strokeWidth="2.5"
            strokeLinecap="round"
            strokeDasharray={c}
            strokeDashoffset={c * (1 - share)}
            className={`${stroke} transition-[stroke-dashoffset,stroke] duration-500 motion-reduce:transition-none`}
          />
        </svg>
        <span
          aria-hidden="true"
          className={`font-mono tabular-nums transition-colors duration-300 ${out ? "text-red-500" : ""}`}
        >
          <NumberRoll
            value={Math.round(share * 100)}
            suffix="%"
            duration={700}
          />
        </span>
      </div>
    );
  }

  return (
    <div className={`w-full ${className}`} {...props}>
      <div className="flex items-baseline justify-between gap-4 text-[12.5px]">
        <span className="font-medium text-foreground">{label}</span>
        {/* The numbers fold away when it runs out; the words that stay glide into "No credits left". */}
        <span
          aria-hidden="true"
          className={`flex items-baseline font-mono text-[12px] tabular-nums transition-colors duration-300 ${out ? "text-red-500" : "text-muted-foreground"}`}
        >
          <Reveal show={!out} reduced={reduced}>
            <span className="inline-flex items-baseline">
              <NumberRoll
                value={left}
                format={GROUPED}
                locales="en-US"
                duration={700}
              />
              &nbsp;of&nbsp;
              <NumberRoll
                value={limit}
                format={GROUPED}
                locales="en-US"
                duration={700}
              />
              &nbsp;
            </span>
          </Reveal>
          <TextMorph>{out ? `No ${unit} left` : `${unit} left`}</TextMorph>
        </span>
      </div>
      <div
        role="meter"
        aria-label={label}
        aria-valuemin={0}
        aria-valuemax={limit}
        aria-valuenow={used}
        aria-valuetext={summary}
        className="mt-2 h-1.5 w-full overflow-hidden rounded-full bg-muted"
      >
        <div
          className={`h-full rounded-full ${tone} transition-[width,background-color] duration-500 ease-[cubic-bezier(0.23,1,0.32,1)] motion-reduce:transition-none`}
          style={{ width: `${share * 100}%` }}
        />
      </div>
      {(resets || onUpgrade) && (
        <div className="mt-2 flex min-h-[18px] items-center justify-between gap-4 text-[12px] text-muted-foreground">
          <span className="min-w-0">
            <TextMorph>
              {out
                ? `You’re out until ${resets ?? "the next reset"}.`
                : resets
                  ? `Resets ${resets}`
                  : ""}
            </TextMorph>
          </span>
          {onUpgrade && (
            // Opens in once it matters: when it's low or out.
            <Reveal show={low || out} reduced={reduced} className="shrink-0">
              <span className="block px-0.5">
                <button
                  type="button"
                  inert={!(low || out)}
                  onClick={onUpgrade}
                  className={`cursor-pointer rounded font-medium text-foreground underline decoration-border underline-offset-4 hover:decoration-foreground ${FOCUS}`}
                >
                  {upgradeLabel}
                </button>
              </span>
            </Reveal>
          )}
        </div>
      )}
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * BOARD DRAG: a card you pick up and carry across columns
 *
 *   lift      after 4px (or a hold on touch) the card itself
 *             follows the pointer exactly, a touch larger, and
 *             tilts with how fast you're carrying it sideways,
 *             settling upright when you stop
 *   gaps      the column under it eases open a gap at the exact
 *             slot while the one it left closes its own; all
 *             transforms, nothing re-laid out per move
 *   refuse    a column that won't take the card (a limit, a
 *             rule) opens no gap; let go and it springs home
 *   scroll    near the board's sides it scrolls sideways, near
 *             the window's top or bottom the page scrolls
 *
 * The hook reports the column and slot only when they change;
 * the component re-renders for those (the card's status chip,
 * the column totals) and runs its own FLIP on drop. Elements:
 * data-column-id (a column), data-column-list (its list),
 * data-card-id (a card's list item).
 * ───────────────────────────────────────────────────────── */

export type BoardOver = {
  card: string;
  column: string;
  index: number;
  refused: string | null;
};

type Options = {
  board: React.RefObject<HTMLElement | null>;
  /** Why a card can't go in a column, or null. */
  refuse: (card: string, column: string) => string | null;
  onOver: (over: BoardOver | null) => void;
  /** Dropped on a slot. The card's tilt and lift are on its element still; FLIP from there. */
  onDrop: (card: string, column: string, index: number) => void;
  /** Dropped where it can't go (and which column refused it), or not moved: it's sprung home already. */
  onCancel: (
    card: string,
    refused: string | null,
    column: string | null,
  ) => void;
  reduced: boolean;
  disabled?: boolean;
};

type ColumnBox = {
  id: string;
  left: number;
  right: number;
  listTop: number;
  list: HTMLElement;
  collapsed: boolean;
  cards: { id: string; el: HTMLElement; top: number; height: number }[];
};

import { EASE_OUT, EASE_SETTLE } from "./imported-ui-interaction-motion";

const EASE = EASE_OUT;
const THROW = EASE_SETTLE;
const GAP = 8;
const HOLD = 300;
const EDGE = 48;

export function useBoardDrag(o: Options) {
  const opts = React.useRef(o);
  React.useLayoutEffect(() => {
    opts.current = o;
  });
  const drag = React.useRef<{
    id: string;
    pointerId: number;
    pointerType: string;
    el: HTMLElement;
    from: string;
    fromIndex: number;
    x0: number;
    y0: number;
    x: number;
    y: number;
    scroll0: number;
    page0: number;
    gap: number;
    columns: ColumnBox[];
    over: { column: string; index: number; refused: string | null } | null;
    active: boolean;
    timer: number;
    vx: number;
    lastX: number;
    lastT: number;
    tilt: number;
    /** The board's box at pickup: only its left and right are needed, and page scrolling doesn't move those. */
    left: number;
    right: number;
    /** The carried card's laid-out centre in its own list, read once at pickup so moves never force a layout. */
    home: number;
  } | null>(null);
  const loop = React.useRef(0);
  /** Scroll positions kept from scroll events: reading scrollLeft or scrollY mid-carry would force a layout every frame. */
  const scroll = React.useRef({ left: 0, top: 0 });

  const write = () => {
    const d = drag.current;
    if (!d) return;
    const dx = d.x - d.x0 + (scroll.current.left - d.scroll0);
    const dy = d.y - d.y0 + (scroll.current.top - d.page0);
    d.el.style.transform = `translate3d(${dx}px, ${dy}px, 0) rotate(${d.tilt}deg) scale(1.03)`;
  };

  /** One loop while carrying: eases the tilt toward the carrying speed and back to upright when still. */
  const run = () => {
    cancelAnimationFrame(loop.current);
    const tick = () => {
      const d = drag.current;
      if (!d?.active) return;
      const now = performance.now();
      if (now - d.lastT > 60) d.vx *= 0.8;
      const target = opts.current.reduced
        ? 0
        : Math.sign(d.vx) * Math.min(5.5, Math.sqrt(Math.abs(d.vx)) * 2.2);
      d.tilt += (target - d.tilt) * 0.22;
      write();
      autoScroll();
      loop.current = requestAnimationFrame(tick);
    };
    loop.current = requestAnimationFrame(tick);
  };

  const measure = (skip: string): ColumnBox[] => {
    const board = opts.current.board.current;
    if (!board) return [];
    return [...board.querySelectorAll<HTMLElement>("[data-column-id]")].map(
      (col) => {
        const r = col.getBoundingClientRect();
        const list = col.querySelector<HTMLElement>("[data-column-list]")!;
        const lr = list.getBoundingClientRect();
        return {
          id: col.dataset.columnId!,
          left: r.left,
          right: r.right,
          listTop: lr.top,
          list,
          collapsed: list.hasAttribute("data-collapsed"),
          cards: [
            ...list.querySelectorAll<HTMLElement>(":scope > [data-card-id]"),
          ]
            .filter((el) => el.dataset.cardId !== skip)
            .map((el) => ({
              id: el.dataset.cardId!,
              el,
              top: el.offsetTop,
              height: el.offsetHeight,
            })),
        };
      },
    );
  };

  /** Which column and slot the card's centre is over (screen positions, adjusted for any scrolling since pickup). */
  const locate = () => {
    const d = drag.current!;
    const sx = scroll.current.left - d.scroll0;
    const sy = scroll.current.top - d.page0;
    const cols = d.columns;
    let col = cols.find((c) => d.x >= c.left - sx && d.x <= c.right - sx);
    if (!col)
      col = cols.reduce(
        (best, c) =>
          Math.abs((c.left + c.right) / 2 - sx - d.x) <
          Math.abs((best.left + best.right) / 2 - sx - d.x)
            ? c
            : best,
        cols[0],
      );
    // The carried card's centre (its laid-out centre plus how far it's been carried), in the target list's coordinates.
    const home = d.columns.find((c) => c.id === d.from)!;
    const cardCentre =
      d.home + (d.y - d.y0) + sy + (home.listTop - col.listTop);
    // A collapsed column shows no cards: it takes the card at its end.
    if (col.collapsed) return { column: col.id, index: col.cards.length };
    let index = 0;
    for (const c of col.cards) if (cardCentre > c.top + c.height / 2) index++;
    return { column: col.id, index };
  };

  const shift = (el: HTMLElement, y: number) => {
    el.style.transition = opts.current.reduced
      ? "none"
      : `transform 240ms ${EASE}`;
    el.style.transform = y ? `translate3d(0, ${y}px, 0)` : "";
  };

  /** Open the gap where the card would land and close the one it left. */
  const arrange = () => {
    const d = drag.current!;
    const { column, index } = locate();
    const refused =
      column === d.from ? null : opts.current.refuse(d.id, column);
    if (
      d.over &&
      d.over.column === column &&
      d.over.index === index &&
      d.over.refused === refused
    )
      return;
    if ((!d.over || d.over.column !== column) && refused) {
      // Entering a column that won't take it: its head says no once.
      const head = d.columns
        .find((c) => c.id === column)
        ?.list.parentElement?.querySelector<HTMLElement>("[data-column-head]");
      if (head && !opts.current.reduced)
        head.animate(
          [
            { transform: "none" },
            { transform: "translateX(-4px)" },
            { transform: "translateX(4px)" },
            { transform: "translateX(-2px)" },
            { transform: "none" },
          ],
          { duration: 380, easing: "ease-out" },
        );
    }
    d.over = { column, index, refused };
    for (const c of d.columns) {
      const lands = !refused && c.id === column;
      const left = c.id === d.from;
      c.cards.forEach((card, i) => {
        let y = 0;
        if (left && !(lands && column === d.from)) {
          // The column it left closes up behind it.
          if (i >= d.fromIndex) y = -d.gap;
        }
        if (lands) {
          if (column === d.from) {
            // Same column: the cards between the old and new slot make way.
            if (index > d.fromIndex && i >= d.fromIndex && i < index)
              y = -d.gap;
            if (index < d.fromIndex && i >= index && i < d.fromIndex) y = d.gap;
          } else if (i >= index) y = d.gap;
        }
        if (card.el.style.transform !== (y ? `translate3d(0, ${y}px, 0)` : ""))
          shift(card.el, y);
      });
      // The column it would land in grows by a card; the one it left keeps its height until the drop.
      c.list.style.transition = opts.current.reduced
        ? "none"
        : `padding-bottom 240ms ${EASE}`;
      c.list.style.paddingBottom =
        lands && column !== d.from ? `${d.gap}px` : "";
    }
    opts.current.onOver({
      card: d.id,
      column,
      index: refused ? -1 : index,
      refused,
    });
  };

  const autoScroll = () => {
    const d = drag.current;
    const board = opts.current.board.current;
    if (!d?.active || !board) return;
    const sideways =
      d.x < d.left + EDGE
        ? -(d.left + EDGE - d.x) / EDGE
        : d.x > d.right - EDGE
          ? (d.x - (d.right - EDGE)) / EDGE
          : 0;
    const upDown =
      d.y < EDGE
        ? -(EDGE - d.y) / EDGE
        : d.y > window.innerHeight - EDGE
          ? (d.y - (window.innerHeight - EDGE)) / EDGE
          : 0;
    // Scroll without reading back: the scroll events update the cached positions before the next frame re-arranges.
    if (sideways) board.scrollLeft = scroll.current.left + sideways * 14;
    if (upDown) window.scrollBy(0, upDown * 12);
    if (sideways || upDown) arrange();
  };

  /** Puts everything back where it was laid out (the card springs home unless asked not to). */
  const release = (home: boolean) => {
    const d = drag.current;
    if (!d) return;
    for (const c of d.columns) {
      c.cards.forEach((card) => {
        shift(card.el, 0);
        card.el.style.willChange = "";
      });
      c.list.style.paddingBottom = "";
    }
    if (home) {
      const from = d.el.style.transform;
      d.el.style.transform = "";
      if (from && !opts.current.reduced)
        d.el.animate([{ transform: from }, { transform: "none" }], {
          duration: 380,
          easing: THROW,
        });
    }
    d.el.style.zIndex = "";
    d.el.style.willChange = "";
    d.el.removeAttribute("data-lifted");
  };

  const activate = () => {
    const d = drag.current;
    if (!d || d.active) return;
    d.active = true;
    if (d.pointerType === "touch") navigator.vibrate?.(8);
    d.columns = measure(d.id);
    d.gap = d.el.offsetHeight + GAP;
    d.home = d.el.offsetTop + d.el.offsetHeight / 2;
    d.el.style.transition = "none";
    d.el.style.zIndex = "50";
    d.el.style.willChange = "transform";
    // Snapping would pull every small auto-scroll step straight back; it's off while a card is carried.
    const board = opts.current.board.current;
    if (board) {
      board.style.scrollSnapType = "none";
      const r = board.getBoundingClientRect();
      d.left = r.left;
      d.right = r.right;
      // Every card that may make way gets its own layer now, once, rather than one by one as each starts to move.
      board
        .querySelectorAll<HTMLElement>("[data-card-id]")
        .forEach((el) => (el.style.willChange = "transform"));
    }
    d.el.setAttribute("data-lifted", "");
    arrange();
    run();
  };

  const end = (dropped: boolean) => {
    const d = drag.current;
    if (!d) return;
    window.clearTimeout(d.timer);
    cancelAnimationFrame(loop.current);
    const board = opts.current.board.current;
    if (board) board.style.scrollSnapType = "";
    if (!d.active) {
      drag.current = null;
      return;
    }
    const over = d.over;
    const moved =
      over && (over.column !== d.from || over.index !== d.fromIndex);
    if (dropped && over && !over.refused && moved) {
      // The component re-lays the board out and runs the FLIP from where everything is now.
      opts.current.onDrop(d.id, over.column, over.index);
      drag.current = null;
      opts.current.onOver(null);
      return;
    }
    release(true);
    drag.current = null;
    opts.current.onOver(null);
    opts.current.onCancel(
      d.id,
      dropped && over?.refused ? over.refused : null,
      over?.column ?? null,
    );
  };

  const onPointerDown = (e: React.PointerEvent<HTMLElement>) => {
    if (
      opts.current.disabled ||
      drag.current ||
      (e.pointerType === "mouse" && e.button !== 0)
    )
      return;
    const target = e.target as HTMLElement;
    if (target.closest("button, input, a, textarea, [data-no-drag]")) return;
    const el = target.closest<HTMLElement>("[data-card-id]");
    if (!el) return;
    const column =
      el.closest<HTMLElement>("[data-column-id]")!.dataset.columnId!;
    const siblings = [
      ...el.parentElement!.querySelectorAll<HTMLElement>(
        ":scope > [data-card-id]",
      ),
    ];
    drag.current = {
      id: el.dataset.cardId!,
      pointerId: e.pointerId,
      pointerType: e.pointerType,
      el,
      from: column,
      fromIndex: siblings.indexOf(el),
      x0: e.clientX,
      y0: e.clientY,
      x: e.clientX,
      y: e.clientY,
      scroll0: (scroll.current.left =
        opts.current.board.current?.scrollLeft ?? 0),
      page0: (scroll.current.top = window.scrollY),
      gap: 0,
      columns: [],
      over: null,
      active: false,
      timer: 0,
      vx: 0,
      lastX: e.clientX,
      lastT: performance.now(),
      tilt: 0,
      left: 0,
      right: 0,
      home: 0,
    };
    if (e.pointerType === "touch") {
      drag.current.timer = window.setTimeout(activate, HOLD);
    } else {
      e.currentTarget.setPointerCapture(e.pointerId);
    }
  };

  const onPointerMove = (e: React.PointerEvent<HTMLElement>) => {
    const d = drag.current;
    if (!d || d.pointerId !== e.pointerId) return;
    if (!d.active) {
      const moved = Math.hypot(e.clientX - d.x0, e.clientY - d.y0);
      if (d.pointerType === "touch") {
        if (moved > 8) end(false);
        return;
      }
      if (moved < 4) return;
      // Compensate 4px pickup slop so initial move displacement starts seamlessly from 0
      d.x0 = e.clientX;
      d.y0 = e.clientY;
      d.x = e.clientX;
      d.y = e.clientY;
      d.lastX = e.clientX;
      d.lastT = performance.now();
      d.scroll0 = scroll.current.left =
        opts.current.board.current?.scrollLeft ?? 0;
      d.page0 = scroll.current.top = window.scrollY;
      activate();
    }
    const now = performance.now();
    const dt = Math.max(1, now - d.lastT);
    d.vx = d.vx * 0.6 + ((e.clientX - d.lastX) / dt) * 0.4;
    d.lastX = e.clientX;
    d.lastT = now;
    d.x = e.clientX;
    d.y = e.clientY;
    arrange();
  };

  const onPointerUp = (e: React.PointerEvent<HTMLElement>) => {
    if (drag.current?.pointerId === e.pointerId) end(true);
  };
  const onPointerCancel = (e: React.PointerEvent<HTMLElement>) => {
    if (drag.current?.pointerId === e.pointerId) end(false);
  };

  // A held card on touch: the page mustn't scroll under it, and no context menu.
  React.useEffect(() => {
    const el = o.board.current;
    if (!el) return;
    const touchMove = (e: TouchEvent) => {
      if (drag.current?.active && e.cancelable) e.preventDefault();
    };
    const menu = (e: Event) => {
      if (drag.current) e.preventDefault();
    };
    const onBoard = () => {
      scroll.current.left = el.scrollLeft;
    };
    const onPage = () => {
      scroll.current.top = window.scrollY;
    };
    el.addEventListener("touchmove", touchMove, { passive: false });
    el.addEventListener("contextmenu", menu);
    el.addEventListener("scroll", onBoard, { passive: true });
    window.addEventListener("scroll", onPage, { passive: true });
    return () => {
      el.removeEventListener("touchmove", touchMove);
      el.removeEventListener("contextmenu", menu);
      el.removeEventListener("scroll", onBoard);
      window.removeEventListener("scroll", onPage);
    };
  }, [o.board]);

  React.useEffect(() => () => cancelAnimationFrame(loop.current), []);

  return {
    handlers: { onPointerDown, onPointerMove, onPointerUp, onPointerCancel },
    /** Where every card is on screen right now (lifted and shifted ones included), for a FLIP after the drop. */
    snapshot: () => {
      const out = new Map<
        string,
        { x: number; y: number; transform: string }
      >();
      opts.current.board.current
        ?.querySelectorAll<HTMLElement>("[data-card-id]")
        .forEach((el) => {
          const r = el.getBoundingClientRect();
          out.set(el.dataset.cardId!, {
            x: r.left + r.width / 2,
            y: r.top + r.height / 2,
            transform: el.hasAttribute("data-lifted") ? el.style.transform : "",
          });
        });
      return out;
    },
    /** Clears what a drag left on the elements (shifts, the lift, list padding) so the new layout can be measured. */
    clear: () => {
      opts.current.board.current
        ?.querySelectorAll<HTMLElement>("[data-card-id]")
        .forEach((el) => {
          el.style.transition = "none";
          el.style.transform = "";
          el.style.zIndex = "";
          el.style.willChange = "";
          el.removeAttribute("data-lifted");
        });
      opts.current.board.current
        ?.querySelectorAll<HTMLElement>("[data-column-list]")
        .forEach((el) => {
          el.style.transition = "none";
          el.style.paddingBottom = "";
        });
    },
  };
}

"use client";

import * as React from "react";
import {
  projectInertia,
  releaseVelocity,
  samplePointer,
  softenVelocity,
  springFrames,
  type PointerSample,
} from "./imported-ui-interaction-motion";

export type DeckThrow = {
  id: string;
  direction: number;
  from: number;
  velocity: number;
};

export function useCardDeckGesture({
  id,
  count,
  reduced,
  onThrow,
  onProgress,
}: {
  id: string | undefined;
  count: number;
  reduced: boolean;
  onThrow: (direction: number, from: number, velocity: number) => boolean;
  /** How far the front card has travelled toward a throw, 0–1; the stack behind rises with it. */
  onProgress: (progress: number, settle: boolean) => void;
}) {
  const rootRef = React.useRef<HTMLDivElement>(null);
  const frontRef = React.useRef<HTMLDivElement>(null);
  const animation = React.useRef<Animation | null>(null);
  const drag = React.useRef<{
    pointer: number;
    startX: number;
    startY: number;
    base: number;
    x: number;
    width: number;
    horizontal: boolean;
    samples: PointerSample[];
  } | null>(null);
  const [dragging, setDragging] = React.useState(false);
  const [prevId, setPrevId] = React.useState(id);
  const [prevReduced, setPrevReduced] = React.useState(reduced);

  if (id !== prevId || reduced !== prevReduced) {
    setPrevId(id);
    setPrevReduced(reduced);
    if (dragging) setDragging(false);
  }

  React.useEffect(
    () => () => {
      animation.current?.cancel();
    },
    [],
  );
  React.useLayoutEffect(() => {
    drag.current = null;
    animation.current?.cancel();
    if (frontRef.current) frontRef.current.style.transform = "";
  }, [id, reduced]);

  const settle = (from: number, velocity: number) => {
    const front = frontRef.current;
    if (!front) return;
    front.style.transform = "";
    if (reduced) return;
    animation.current?.cancel();
    const frames = springFrames(from, 0, velocity, 480, {
      omega: 16,
      damping: 0.74,
    }).map(({ value, offset }) => {
      const lift = -Math.min(10, Math.abs(value) * 0.05);
      const angle =
        Math.sign(value) * Math.min(16, Math.sqrt(Math.abs(value)) * 1.05);
      return {
        transform: `translate3d(${value}px,${lift}px,0) rotate(${angle}deg)`,
        offset,
      };
    });
    animation.current = front.animate(frames, {
      duration: 480,
      easing: "linear",
    });
  };

  const finish = (event: React.PointerEvent, cancelled: boolean) => {
    const state = drag.current;
    if (!state || state.pointer !== event.pointerId) return;
    drag.current = null;
    setDragging(false);
    onProgress(0, true);
    const velocity = releaseVelocity(state.samples, event.timeStamp);
    const projected = projectInertia(state.x, velocity, 0.12);
    const sameDir =
      Math.sign(velocity) === Math.sign(state.x) || Math.abs(velocity) < 0.08;
    const crossed = Math.abs(state.x) > Math.min(95, state.width * 0.28);
    const projectedOut =
      Math.abs(projected) > state.width * 0.32 &&
      sameDir &&
      Math.abs(state.x) > 18;
    const flicked =
      Math.abs(state.x) > 14 &&
      Math.abs(velocity) > 0.42 &&
      Math.sign(velocity) === Math.sign(state.x);

    if (
      !cancelled &&
      state.horizontal &&
      (crossed || projectedOut || flicked)
    ) {
      const dir = state.x < 0 ? 1 : -1;
      if (!onThrow(dir, state.x, velocity)) {
        settle(state.x, velocity);
      }
    } else {
      const launchV = softenVelocity(velocity, state.x, 8);
      settle(state.x, cancelled ? 0 : launchV);
    }
  };

  return {
    rootRef,
    frontRef,
    dragging,
    handlers: {
      onPointerDown(event: React.PointerEvent<HTMLDivElement>) {
        if (
          count < 2 ||
          event.button !== 0 ||
          !event.isPrimary ||
          (event.target as HTMLElement).closest(
            "a,button,input,textarea,select,[data-deck-no-drag]",
          )
        )
          return;
        const transform = getComputedStyle(event.currentTarget).transform;
        const base =
          transform === "none" ? 0 : new DOMMatrixReadOnly(transform).m41;
        animation.current?.cancel();
        if (!reduced) {
          const lift = -Math.min(10, Math.abs(base) * 0.05);
          const angle =
            Math.sign(base) * Math.min(16, Math.sqrt(Math.abs(base)) * 1.05);
          event.currentTarget.style.transform = `translate3d(${base}px,${lift}px,0) rotate(${angle}deg)`;
        }
        event.currentTarget.setPointerCapture(event.pointerId);
        drag.current = {
          pointer: event.pointerId,
          startX: event.clientX,
          startY: event.clientY,
          base,
          x: base,
          width: event.currentTarget.clientWidth,
          horizontal: false,
          samples: [{ x: event.clientX, time: event.timeStamp }],
        };
      },
      onPointerMove(event: React.PointerEvent<HTMLDivElement>) {
        const state = drag.current;
        if (!state || state.pointer !== event.pointerId) return;
        const dx = event.clientX - state.startX,
          dy = event.clientY - state.startY;
        if (!state.horizontal) {
          if (Math.abs(dy) > 8 && Math.abs(dy) > Math.abs(dx)) {
            drag.current = null;
            settle(state.base, 0);
            onProgress(0, true);
            return;
          }
          if (Math.abs(dx) < 6) return;
          state.horizontal = true;
          // Compensate slop so drag originates seamlessly with zero jump
          state.startX = event.clientX;
          state.startY = event.clientY;
          setDragging(true);
        }
        state.x = state.base + (event.clientX - state.startX);
        samplePointer(state.samples, event.clientX, event.timeStamp);
        if (!reduced) {
          const lift = -Math.min(10, Math.abs(state.x) * 0.05);
          const angle =
            Math.sign(state.x) *
            Math.min(16, Math.sqrt(Math.abs(state.x)) * 1.05);
          event.currentTarget.style.transform = `translate3d(${state.x}px,${lift}px,0) rotate(${angle}deg)`;
          onProgress(
            Math.min(1, Math.abs(state.x) / (state.width * 0.55)),
            false,
          );
        }
      },
      onPointerUp: (event: React.PointerEvent) => finish(event, false),
      onPointerCancel: (event: React.PointerEvent) => finish(event, true),
      onLostPointerCapture: (event: React.PointerEvent) => finish(event, true),
    },
    resetFront: () => {
      animation.current?.cancel();
      if (frontRef.current) frontRef.current.style.transform = "";
    },
  };
}

"use client";

import * as React from "react";

/*
 * The morphing chart's engine. Bars, beads, the line and the area are four drawings of the same
 * points, so a change of shape is a choreography over shared geometry, never a cross-fade:
 *
 *   bars → line    each bar condenses up into a bead on its value; a thread is strung through the
 *                  beads from the left, and each bead melts into it as the thread passes
 *   line → bars    the thread is pulled out to the right; each bead swells back as the tail leaves
 *                  it and drips a stick to the axis, which lands and spreads into its bar
 *   line → area    the fill pours down from the line to the axis, left to right
 *   area → line    it drains back up into the line
 *   bars → area    the bars widen until they touch and fade to the wash; the steps they make melt
 *                  into the curve and the thread runs along the top
 *   area → bars    the curve sets into steps, which part into bars and fill in
 *
 * Every change is a tape: a pose that is a pure function of time. One frame loop plays it forward
 * or backward (asking for the shape it came from runs it back from where it is), and a finger can
 * hold it at any frame (scrub). Changes of data and the hover bead ride the same loop, which writes
 * path data and transforms straight to the DOM and sleeps when nothing moves.
 */

export type ChartShape = "bars" | "line" | "area";

export type ChartLayout = { width: number; height: number; top: number };

/** The shapes in the switch's order: scrubbing runs along this axis. */
export const CHART_SHAPES: ChartShape[] = ["bars", "line", "area"];

const DOT = 7;
const STROKE = 2;
const WASH_TOP = 0.22;
const WASH_BOTTOM = 0.03;
const SAMPLES = 10;
const BEAD_TAU = 70;
/** How far a bar bulges before it pinches (as a share of the pinch), and how high a bead hops as it closes. */
const BULGE = 0.18;
const HOP = 2.2;

const clamp01 = (n: number) => Math.max(0, Math.min(1, n));
const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
const inOut = (t: number) =>
  t < 0.5 ? 4 * t * t * t : 1 - (-2 * t + 2) ** 3 / 2;
/** The time at which inOut reaches y. */
const inOutAt = (y: number) =>
  y < 0.5 ? Math.cbrt(y / 4) : 1 - Math.cbrt(2 * (1 - y)) / 2;
const out = (t: number) => 1 - (1 - t) ** 3;
const r2 = (n: number) => Math.round(n * 100) / 100;

/** Tangents of a monotone cubic through the points: smooth, never overshooting a value. */
function tangents(xs: number[], ys: number[]) {
  const n = xs.length;
  if (n < 2) return xs.map(() => 0);
  const m: number[] = [];
  for (let i = 0; i < n - 1; i++)
    m.push((ys[i + 1] - ys[i]) / (xs[i + 1] - xs[i] || 1));
  const t = [m[0]];
  for (let i = 1; i < n - 1; i++)
    t.push(m[i - 1] * m[i] <= 0 ? 0 : (m[i - 1] + m[i]) / 2);
  t.push(m[n - 2]);
  for (let i = 0; i < n - 1; i++) {
    if (m[i] === 0) {
      t[i] = 0;
      t[i + 1] = 0;
      continue;
    }
    const a = t[i] / m[i],
      b = t[i + 1] / m[i],
      s = a * a + b * b;
    if (s > 9) {
      const k = 3 / Math.sqrt(s);
      t[i] = k * a * m[i];
      t[i + 1] = k * b * m[i];
    }
  }
  return t;
}

type Pt = [number, number];
const mix = (p: Pt, q: Pt, s: number): Pt => [
  lerp(p[0], q[0], s),
  lerp(p[1], q[1], s),
];

/** The piece of a cubic between s0 and s1 (de Casteljau twice). */
function piece(
  p0: Pt,
  p1: Pt,
  p2: Pt,
  p3: Pt,
  s0: number,
  s1: number,
): [Pt, Pt, Pt, Pt] {
  // Keep [0, s1].
  const a = mix(p0, p1, s1),
    b = mix(p1, p2, s1),
    c = mix(p2, p3, s1),
    ab = mix(a, b, s1),
    bc = mix(b, c, s1),
    e = mix(ab, bc, s1);
  if (s0 <= 0) return [p0, a, ab, e];
  // Of that, keep [s0 / s1, 1].
  const u = s0 / s1;
  const f = mix(p0, a, u),
    g = mix(a, ab, u),
    h = mix(ab, e, u),
    fg = mix(f, g, u),
    gh = mix(g, h, u);
  return [mix(fg, gh, u), gh, h, e];
}

/**
 * The curve between two x positions. Each segment's control points sit at thirds in x, so x runs
 * linearly with the curve's parameter and a cut at any x is exact.
 */
function curveBetween(
  xs: number[],
  ys: number[],
  t: number[],
  xa: number,
  xb: number,
) {
  let d = "";
  for (let i = 0; i < xs.length - 1; i++) {
    const h = xs[i + 1] - xs[i];
    if (xs[i + 1] <= xa || xs[i] >= xb || h <= 0) continue;
    const s0 = clamp01((xa - xs[i]) / h),
      s1 = clamp01((xb - xs[i]) / h);
    if (s1 - s0 < 1e-4) continue;
    const dx = h / 3;
    const [q0, q1, q2, q3] = piece(
      [xs[i], ys[i]],
      [xs[i] + dx, ys[i] + t[i] * dx],
      [xs[i + 1] - dx, ys[i + 1] - t[i + 1] * dx],
      [xs[i + 1], ys[i + 1]],
      s0,
      s1,
    );
    if (!d) d = `M${r2(q0[0])},${r2(q0[1])}`;
    d += `C${r2(q1[0])},${r2(q1[1])} ${r2(q2[0])},${r2(q2[1])} ${r2(q3[0])},${r2(q3[1])}`;
  }
  return d;
}

/** The same curve, evaluated at x (cubic Hermite on the segment). */
function curveAt(xs: number[], ys: number[], t: number[], x: number) {
  const n = xs.length;
  if (n === 1) return ys[0];
  let i = Math.min(
    n - 2,
    Math.max(0, Math.floor(((x - xs[0]) / (xs[n - 1] - xs[0] || 1)) * (n - 1))),
  );
  while (i > 0 && x < xs[i]) i--;
  while (i < n - 2 && x > xs[i + 1]) i++;
  const h = xs[i + 1] - xs[i] || 1,
    s = clamp01((x - xs[i]) / h);
  const h00 = 2 * s ** 3 - 3 * s ** 2 + 1,
    h10 = s ** 3 - 2 * s ** 2 + s,
    h01 = -2 * s ** 3 + 3 * s ** 2,
    h11 = s ** 3 - s ** 2;
  return h00 * ys[i] + h10 * h * t[i] + h01 * ys[i + 1] + h11 * h * t[i + 1];
}

/** A box with its own top and bottom corner radii. */
function box(
  l: number,
  t: number,
  r: number,
  b: number,
  rt: number,
  rb: number,
) {
  const w = r - l,
    h = b - t;
  if (w <= 0.01 || h <= 0.01) return "";
  rt = Math.max(0, Math.min(rt, w / 2, h / 2));
  rb = Math.max(0, Math.min(rb, w / 2, h - rt));
  return `M${r2(l)},${r2(t + rt)}A${r2(rt)},${r2(rt)} 0 0 1 ${r2(l + rt)},${r2(t)}H${r2(r - rt)}A${r2(rt)},${r2(rt)} 0 0 1 ${r2(r)},${r2(t + rt)}V${r2(b - rb)}A${r2(rb)},${r2(rb)} 0 0 1 ${r2(r - rb)},${r2(b)}H${r2(l + rb)}A${r2(rb)},${r2(rb)} 0 0 1 ${r2(l)},${r2(b - rb)}Z`;
}

type Route = { from: ChartShape; to: ChartShape; t: number; dir: 1 | -1 };

type Pose = {
  /** Per point: widened into a step (merge), condensed into a bead (dot), melted into the thread (zip). */
  m: Float32Array;
  d: Float32Array;
  z: Float32Array;
  cols: boolean;
  /** 0 solid, 1 the area's fading gradient. */
  wash: number;
  areaOn: boolean;
  /** The area's top edge: 0 the curve, 1 steps. */
  step: number;
  /** The thread is drawn between these fractions of the x range. */
  ta: number;
  tb: number;
  /** How far the area's floor has poured: 'full', or pouring in / draining out at time t. */
  pour: "full" | "in" | "out";
  pourT: number;
};

const poseFor = (n: number): Pose => ({
  m: new Float32Array(n),
  d: new Float32Array(n),
  z: new Float32Array(n),
  cols: true,
  wash: 0,
  areaOn: false,
  step: 0,
  ta: 0,
  tb: 0,
  pour: "full",
  pourT: 0,
});

/** Timings shared by the tapes; the stagger shrinks with more points so a sweep stays under ~300ms. */
function timing(n: number) {
  const stag = n > 1 ? Math.min(28, 300 / (n - 1)) : 0;
  const spread = (n - 1) * stag;
  const condense = 460;
  const threadIn = condense * 0.9;
  const sweep = Math.max(420, spread * 1.25 + 90);
  const melt = 260;
  const pull = Math.max(380, spread * 1.1 + 120);
  const drip = 540;
  const widen = 380;
  const swap = widen + spread * 0.5;
  return {
    stag,
    spread,
    condense,
    threadIn,
    sweep,
    melt,
    pull,
    drip,
    widen,
    swap,
  };
}

export function routeDuration(from: ChartShape, to: ChartShape, n: number) {
  const k = timing(n);
  switch (`${from}>${to}`) {
    case "bars>line":
      return k.threadIn + k.sweep + 40 + k.melt;
    case "line>bars":
      return k.pull + 40 + k.drip;
    case "line>area":
      return 760;
    case "area>line":
      return 620;
    case "bars>area":
      return k.swap + 620;
    case "area>bars":
      return 380 + 480 + k.spread * 0.6;
    default:
      return 0;
  }
}

/** The resting pose of a shape. */
function settle(P: Pose, s: ChartShape) {
  P.m.fill(s === "area" ? 1 : 0);
  P.d.fill(s === "line" ? 1 : 0);
  P.z.fill(s === "line" ? 1 : 0);
  P.cols = s !== "area";
  P.wash = s === "area" ? 1 : 0;
  P.areaOn = s === "area";
  P.step = 0;
  P.ta = 0;
  P.tb = s === "bars" ? 0 : 1;
  P.pour = "full";
  P.pourT = 0;
}

/** The pose of a tape at time t. Every field is set, so the tape can run either way or be held. */
function pose(P: Pose, from: ChartShape, to: ChartShape, t: number, n: number) {
  const k = timing(n);
  const u = (i: number) => (n > 1 ? i / (n - 1) : 0);
  settle(P, from);
  switch (`${from}>${to}`) {
    case "bars>line": {
      // The thread's tip eases across; each bead melts once the tip has passed it.
      const tip = inOut(clamp01((t - k.threadIn) / k.sweep));
      for (let i = 0; i < n; i++) {
        P.d[i] = clamp01((t - i * k.stag) / k.condense);
        P.z[i] = clamp01(
          (t - (k.threadIn + k.sweep * inOutAt(u(i)) + 40)) / k.melt,
        );
      }
      P.ta = 0;
      P.tb = tip;
      return;
    }
    case "line>bars": {
      // The tail is pulled to the right; each bead swells just before it's left, then drips its bar.
      const tail = inOut(clamp01(t / k.pull));
      for (let i = 0; i < n; i++) {
        const leave = k.pull * inOutAt(u(i));
        P.z[i] = 1 - out(clamp01((t - Math.max(0, leave - 140)) / 200));
        P.d[i] = 1 - clamp01((t - leave - 40) / k.drip);
      }
      P.ta = tail;
      P.tb = 1;
      return;
    }
    case "line>area": {
      P.cols = false;
      P.areaOn = t > 0;
      P.wash = 1;
      P.ta = 0;
      P.tb = 1;
      P.pour = "in";
      P.pourT = t;
      return;
    }
    case "area>line": {
      const end = routeDuration("area", "line", n);
      P.cols = false;
      P.areaOn = t < end;
      P.wash = 1;
      P.ta = 0;
      P.tb = 1;
      P.pour = "out";
      P.pourT = t;
      return;
    }
    case "bars>area": {
      for (let i = 0; i < n; i++)
        P.m[i] = out(clamp01((t - i * k.stag * 0.5) / k.widen));
      P.wash = out(clamp01(t / k.swap));
      if (t < k.swap) {
        P.step = 1;
        return;
      }
      P.cols = false;
      P.areaOn = true;
      P.step = 1 - inOut(clamp01((t - k.swap) / 460));
      P.ta = 0;
      P.tb = inOut(clamp01((t - k.swap - 160) / 440));
      return;
    }
    case "area>bars": {
      P.step = inOut(clamp01(t / 380));
      P.ta = out(clamp01(t / 260));
      P.tb = 1;
      if (t < 380) return;
      P.areaOn = false;
      P.cols = true;
      for (let i = 0; i < n; i++)
        P.m[i] = 1 - out(clamp01((t - 380 - i * k.stag * 0.6) / 480));
      P.wash = 1 - out(clamp01((t - 380) / (480 + k.spread * 0.6)));
      return;
    }
  }
}

export function useChartMorph({
  count,
  shape,
  reduced,
  barWidth = 24,
}: {
  count: number;
  shape: ChartShape;
  reduced: boolean;
  barWidth?: number;
}) {
  const columns = React.useRef<(SVGPathElement | null)[]>([]);
  const columnGroup = React.useRef<SVGGElement>(null);
  const area = React.useRef<SVGPathElement>(null);
  const line = React.useRef<SVGPathElement>(null);
  const stops = React.useRef<(SVGStopElement | null)[]>([]);
  const bead = React.useRef<HTMLDivElement>(null);
  const rule = React.useRef<HTMLDivElement>(null);

  const st = React.useRef<{
    layout: ChartLayout;
    pose: Pose;
    shown: ChartShape;
    route: Route | null;
    queued: ChartShape | null;
    held: boolean;
    vals: Float32Array;
    from: Float32Array;
    to: Float32Array;
    dataT0: number;
    delay: number;
    max: number;
    maxFrom: number;
    maxTo: number;
    point: number | null;
    beadX: number;
    beadOn: boolean;
    last: number;
    n: number;
  } | null>(null);
  if (st.current == null) {
    const P = poseFor(count);
    settle(P, shape);
    st.current = {
      layout: { width: 0, height: 0, top: 10 },
      pose: P,
      shown: shape,
      route: null,
      queued: null,
      held: false,
      vals: new Float32Array(count),
      from: new Float32Array(count),
      to: new Float32Array(count),
      dataT0: -1,
      delay: 25,
      max: 1,
      maxFrom: 1,
      maxTo: 1,
      point: null,
      beadX: 0,
      beadOn: false,
      last: 0,
      n: count,
    };
  }

  const frame = React.useRef(0);
  const still = React.useRef(reduced);

  React.useLayoutEffect(() => {
    still.current = reduced;
    const S = st.current;
    if (!S) return;
    if (S.pose.m.length !== count) {
      const keep = (a: Float32Array) =>
        Float32Array.from(
          { length: count },
          (_, i) => a[i] ?? a[a.length - 1] ?? 0,
        );
      S.vals = keep(S.vals);
      S.from = keep(S.from);
      S.to = keep(S.to);
      if (S.route) S.shown = S.route.dir > 0 ? S.route.to : S.route.from;
      S.pose = poseFor(count);
      settle(S.pose, S.shown);
      S.route = null;
      S.queued = null;
      S.held = false;
      S.point = S.point !== null && S.point < count ? S.point : null;
    }
    S.n = count;
  });

  const paint = (dt = 0) => {
    const S = st.current;
    if (!S) return;
    const P = S.pose,
      n = S.n;
    const { width: W, height: H, top } = S.layout;
    if (!W || !H || !n) return;
    const band = W / n;
    const bw = Math.min(barWidth, band * 0.56);
    const xs = Array.from({ length: n }, (_, i) => band * (i + 0.5));
    const max = S.max || 1;
    const ys = Array.from(
      S.vals,
      (v) => top + (H - top) * (1 - Math.max(0, v) / max),
    );
    const x0 = xs[0],
      xN = xs[n - 1];
    const tg = tangents(xs, ys);
    const near = (x: number) =>
      ys[Math.max(0, Math.min(n - 1, Math.round((x - x0) / band)))];

    // Columns: bars, steps on their way to the area, or beads.
    const g = columnGroup.current;
    if (g) g.style.display = P.cols ? "" : "none";
    if (P.cols) {
      for (let i = 0; i < n; i++) {
        const el = columns.current[i];
        if (!el) continue;
        const x = xs[i],
          yt = ys[i],
          mi = P.m[i],
          di = P.d[i],
          zi = P.z[i];
        let l = lerp(
          x - bw / 2,
          n > 1 ? Math.max(x0, x - band / 2) : x - band / 2,
          mi,
        );
        let r = lerp(
          x + bw / 2,
          n > 1 ? Math.min(xN, x + band / 2) : x + band / 2,
          mi,
        );
        // Condensing: the bar bulges a touch, pinches to a stick, then the stick retracts up into a bead
        // on the value, which hops as it closes. Run backward, the same curves make a drip that lifts
        // off, falls, and spreads past its width as it lands.
        const ps = clamp01(di / 0.45),
          ls = clamp01((di - 0.3) / 0.7);
        const pinch =
            inOut(ps) - BULGE * Math.sin(Math.PI * clamp01(ps / 0.45)),
          lift = inOut(ls);
        const hop = HOP * Math.sin(Math.PI * clamp01((ls - 0.72) / 0.28));
        const cx = (l + r) / 2,
          w = lerp(r - l, DOT, pinch);
        l = cx - w / 2;
        r = cx + w / 2;
        let t = yt - (DOT / 2) * lift - hop,
          b = lerp(H, yt + DOT / 2, lift) - hop;
        // Melting: the bead shrinks to the thread's thickness, under it, and goes.
        if (zi > 0) {
          if (zi >= 1) {
            el.setAttribute("d", "");
            continue;
          }
          const k = lerp(1, STROKE / DOT, out(zi)),
            cy = (t + b) / 2,
            hw = (r - l) / 2,
            hh = (b - t) / 2;
          l = cx - hw * k;
          r = cx + hw * k;
          t = cy - hh * k;
          b = cy + hh * k;
        }
        const rt = lerp(4 * (1 - mi), DOT / 2, Math.max(0, pinch));
        const rb = (DOT / 2) * lift;
        el.setAttribute("d", box(l, t, r, b, rt, rb));
      }
    }

    // The wash: solid for bars, a fading gradient for the area. Columns paint with a plain fill until it starts.
    const washing = P.wash > 0.001 ? "1" : "";
    if (g && g.dataset.washing !== washing) {
      g.dataset.washing = washing;
      g.setAttribute(
        "fill",
        washing ? (g.dataset.wash ?? "") : "var(--chart-1, var(--primary))",
      );
    }
    const [s0, s1] = stops.current;
    if (s0)
      s0.setAttribute("stop-opacity", String(r2(lerp(1, WASH_TOP, P.wash))));
    if (s1)
      s1.setAttribute("stop-opacity", String(r2(lerp(1, WASH_BOTTOM, P.wash))));

    // The area: a top edge between the curve and steps, a floor that pours down to the axis.
    const a = area.current;
    if (a) {
      a.style.display = P.areaOn && n > 1 ? "" : "none";
      if (P.areaOn && n > 1) {
        if (P.step < 0.001 && P.pour === "full") {
          a.setAttribute(
            "d",
            `${curveBetween(xs, ys, tg, x0, xN)}L${r2(xN)},${H}L${r2(x0)},${H}Z`,
          );
        } else {
          const px: number[] = [];
          for (let i = 0; i < n - 1; i++) {
            for (let k = 0; k < SAMPLES; k++)
              px.push(xs[i] + (k / SAMPLES) * band);
            const mid = xs[i] + band / 2;
            px.push(mid - 0.01, mid + 0.01);
          }
          px.push(xN);
          px.sort((p, q) => p - q);
          const tops = px.map((x) =>
            lerp(curveAt(xs, ys, tg, x), near(x), P.step),
          );
          const floor = (x: number) => {
            const v = (x - x0) / (xN - x0 || 1);
            if (P.pour === "full") return 1;
            if (P.pour === "in") return out(clamp01((P.pourT - v * 300) / 460));
            return 1 - inOut(clamp01((P.pourT - v * 240) / 380));
          };
          let d = `M${r2(px[0])},${r2(tops[0])}`;
          for (let k = 1; k < px.length; k++)
            d += `L${r2(px[k])},${r2(tops[k])}`;
          if (P.pour === "full") d += `L${r2(xN)},${H}L${r2(x0)},${H}Z`;
          else {
            for (let k = px.length - 1; k >= 0; k--)
              d += `L${r2(px[k])},${r2(lerp(tops[k], H, floor(px[k])))}`;
            d += "Z";
          }
          a.setAttribute("d", d);
        }
      }
    }

    // The thread: the curve cut exactly between its tail and its tip.
    const ln = line.current;
    if (ln) {
      const xa = lerp(x0, xN, P.ta),
        xb = lerp(x0, xN, P.tb);
      const on = n > 1 && xb - xa > 0.5;
      ln.style.display = on ? "" : "none";
      if (on) ln.setAttribute("d", curveBetween(xs, ys, tg, xa, xb));
    }

    // The hover bead slides along the thread (it follows the curve, not a straight line), with a cavemio under it.
    const bd = bead.current,
      rl = rule.current;
    if (bd && rl) {
      const showing =
        S.point !== null && n > 1 && (P.areaOn || P.tb - P.ta > 0.98);
      if (S.point !== null) {
        const target = xs[S.point];
        S.beadX =
          !S.beadOn || still.current
            ? target
            : lerp(target, S.beadX, Math.exp(-dt / BEAD_TAU));
        if (Math.abs(S.beadX - target) < 0.05) S.beadX = target;
      }
      if (showing !== S.beadOn) {
        S.beadOn = showing;
        bd.style.opacity = rl.style.opacity = showing ? "1" : "0";
        bd.style.scale = showing ? "1" : "0.4";
      }
      const x = S.beadX,
        y = lerp(curveAt(xs, ys, tg, x), near(x), P.step);
      bd.style.translate = `${r2(x - 4.5)}px ${r2(y - 4.5)}px`;
      rl.style.translate = `${r2(x - 0.5)}px 0`;
    }
  };

  const tick = (now: number) => {
    const S = st.current;
    if (!S) return;
    frame.current = 0;
    const dt = S.last ? Math.min(64, now - S.last) : 16;
    S.last = now;
    let moving = false;
    // Data: each value eases to its new height, a little after its left neighbour.
    if (S.dataT0 >= 0) {
      const t = now - S.dataT0;
      let done = true;
      for (let i = 0; i < S.n; i++) {
        const k = out(clamp01((t - i * S.delay) / 650));
        if (k < 1) done = false;
        S.vals[i] = lerp(S.from[i], S.to[i], k);
      }
      S.max = lerp(S.maxFrom, S.maxTo, out(clamp01(t / 650)));
      if (done) {
        S.dataT0 = -1;
        S.max = S.maxTo;
      } else moving = true;
    }
    // Shape: play the tape the way it's heading; land, then take any shape asked for meanwhile.
    const R = S.route;
    if (R && !S.held) {
      const end = routeDuration(R.from, R.to, S.n);
      R.t = Math.max(0, Math.min(end, R.t + dt * R.dir));
      if ((R.dir > 0 && R.t >= end) || (R.dir < 0 && R.t <= 0)) {
        S.shown = R.dir > 0 ? R.to : R.from;
        settle(S.pose, S.shown);
        S.route = null;
        const next = S.queued;
        S.queued = null;
        if (next && next !== S.shown) {
          S.route = { from: S.shown, to: next, t: 0, dir: 1 };
          moving = true;
        }
      } else {
        pose(S.pose, R.from, R.to, R.t, S.n);
        moving = true;
      }
    }
    // The bead: eases toward its point.
    if (
      S.point !== null &&
      S.beadOn &&
      Math.abs(S.beadX - (S.layout.width / S.n) * (S.point + 0.5)) > 0.05
    )
      moving = true;
    paint(dt);
    if (moving) frame.current = requestAnimationFrame(tick);
    else S.last = 0;
  };

  const kick = () => {
    if (!frame.current) frame.current = requestAnimationFrame(tick);
  };

  React.useEffect(
    () => () => {
      cancelAnimationFrame(frame.current);
      frame.current = 0;
    },
    [],
  );

  /**
   * Where the shape is on the switch's axis (0 bars, 1 line, 2 area). Null while a tape that isn't
   * on that axis runs (line → bars, area → line, bars ↔ area are their own choreographies).
   */
  const position = () => {
    const S = st.current;
    if (!S) return null;
    const R = S.route;
    if (!R) return CHART_SHAPES.indexOf(S.shown);
    const along = R.t / (routeDuration(R.from, R.to, count) || 1);
    if (R.from === "bars" && R.to === "line") return along;
    if (R.from === "line" && R.to === "area") return 1 + along;
    return null;
  };

  const shapeTo = (next: ChartShape) => {
    const S = st.current;
    if (!S) return;
    const R = S.route;
    if (still.current) {
      S.route = null;
      S.queued = null;
      S.held = false;
      S.shown = next;
      settle(S.pose, next);
      paint();
      return;
    }
    if (R) {
      S.held = false;
      if (next === R.to) {
        R.dir = 1;
        S.queued = null;
      } else if (next === R.from) {
        R.dir = -1;
        S.queued = null;
      } else S.queued = next;
      kick();
      return;
    }
    if (next === S.shown) return;
    S.route = { from: S.shown, to: next, t: 0, dir: 1 };
    kick();
  };

  return {
    columns,
    columnGroup,
    area,
    line,
    stops,
    bead,
    rule,
    setColumn: (i: number, el: SVGPathElement | null) => {
      columns.current[i] = el;
    },
    setColumnGroup: (el: SVGGElement | null) => {
      columnGroup.current = el;
    },
    setArea: (el: SVGPathElement | null) => {
      area.current = el;
    },
    setLine: (el: SVGPathElement | null) => {
      line.current = el;
    },
    setStop: (i: number, el: SVGStopElement | null) => {
      stops.current[i] = el;
    },
    setBead: (el: HTMLDivElement | null) => {
      bead.current = el;
    },
    setRule: (el: HTMLDivElement | null) => {
      rule.current = el;
    },
    /** The plot's size changed: redraw where everything is. */
    layout(next: ChartLayout) {
      const S = st.current;
      if (!S) return;
      if (
        S.layout.width === next.width &&
        S.layout.height === next.height &&
        S.layout.top === next.top
      )
        return;
      S.layout = next;
      paint();
    },
    /** New values (and scale); from the values on screen, or from `from` for the first arrival. */
    data(
      values: number[],
      max: number,
      opts: { animate: boolean; from?: number },
    ) {
      const S = st.current;
      if (!S) return;
      for (let i = 0; i < count; i++) {
        S.from[i] = opts.from ?? S.vals[i];
        S.to[i] = values[i] ?? 0;
      }
      S.maxFrom = opts.from !== undefined ? max : S.max;
      S.maxTo = max;
      if (!opts.animate || still.current) {
        S.vals.set(S.to);
        S.max = max;
        S.dataT0 = -1;
        paint();
        return;
      }
      S.delay = count > 1 ? Math.min(40, 420 / (count - 1)) : 0;
      S.dataT0 = performance.now();
      kick();
    },
    /** Head for a shape: run the tape on, run it back if that's where it came from, or queue behind it. */
    shape: shapeTo,
    position,
    /** Hold the tape at a point on the shape axis, 0 (bars) to 2 (area), between neighbours. */
    scrub(p: number) {
      const S = st.current;
      if (!S || still.current) return;
      p = Math.max(0, Math.min(CHART_SHAPES.length - 1, p));
      const i = Math.min(CHART_SHAPES.length - 2, Math.floor(p));
      const from = CHART_SHAPES[i],
        to = CHART_SHAPES[i + 1];
      S.queued = null;
      S.held = true;
      S.route = {
        from,
        to,
        t: (p - i) * routeDuration(from, to, count),
        dir: 1,
      };
      pose(S.pose, from, to, S.route.t, count);
      paint();
    },
    /** Let go of the tape: it runs on to `target`, one of the two shapes either side of it. */
    release(target: ChartShape) {
      const S = st.current;
      if (!S) return;
      const R = S.route;
      S.held = false;
      if (!R || still.current) return shapeTo(target);
      if (target === R.from) R.dir = -1;
      else if (target === R.to) R.dir = 1;
      else S.queued = target;
      kick();
    },
    /** The point the bead sits on, or null to hide it. */
    point(i: number | null) {
      const S = st.current;
      if (!S) return;
      if (i === S.point) return;
      S.point = i;
      kick();
    },
  };
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * CROP GESTURE: a photo you hold, not a box you drag
 *
 *   pan       the photo follows the finger exactly; past an
 *             edge it resists more the further it goes, the way
 *             iOS Photos does, so the crop never shows a gap
 *   pinch     two fingers zoom about the point between them;
 *             wheel and trackpad pinch zoom about the pointer;
 *             below the fit or past the limit it resists too
 *   release   it keeps the speed you let go with and slows
 *             down; anything out of bounds springs back,
 *             critically damped, carrying that speed
 *   rotate    quarter turns, and the bounds re-solve so the
 *             photo still covers the crop
 *
 * One frame loop with fixed 4ms steps, writing transforms to
 * three nested layers (pan, zoom, rotate) and sleeping the
 * moment everything is still. React hears about it once, when
 * it settles. Layers are promoted only while they move, so the
 * photo re-rasterises sharp at its new size.
 * ───────────────────────────────────────────────────────── */

export type CropState = { x: number; y: number; z: number; r: number };
/** The crop in the photo's own pixels: its centre, the side of the square, and the quarter turns applied (degrees). */
export type CropArea = {
  centerX: number;
  centerY: number;
  size: number;
  rotation: number;
};

type Options = {
  /** Side of the crop region at full size, px. */
  size: number;
  /** Natural size of the photo. */
  image: { w: number; h: number } | null;
  maxZoom: number;
  reduced: boolean;
  /** Called once a gesture, wheel, key or spring has settled. */
  onSettle?: (state: CropState) => void;
  refs: {
    pan: React.RefObject<HTMLDivElement | null>;
    zoom: React.RefObject<HTMLDivElement | null>;
    rot: React.RefObject<HTMLDivElement | null>;
    slider: React.RefObject<HTMLInputElement | null>;
    grid: React.RefObject<SVGGElement | null>;
    stage: React.RefObject<HTMLDivElement | null>;
  };
};

import {
  EASE_SETTLE,
  rubberBand,
  softenVelocity,
} from "./imported-ui-interaction-motion";

type Vec = { x: number; y: number };

const K = 260; // spring stiffness, 1/s²
const C = 2 * 0.76 * Math.sqrt(K); // organic damping (zeta ~0.76 with 3% settling breath)
const FRICTION = 4.2; // momentum decay, 1/s
const STEP = 4; // ms
const THROW = EASE_SETTLE;

const clamp = (v: number, lo: number, hi: number) =>
  Math.min(hi, Math.max(lo, v));
/** Resistance past an edge: the further over, the less it gives (iOS's 0.55 constant). */
const band = (over: number, dim: number) => rubberBand(over, dim, 0.55);
/** The raw overshoot that shows as `shown` once banded, so a gesture can start from a photo that's mid-spring. */
const unband = (shown: number, dim: number) => {
  const u = Math.min(0.95, Math.abs(shown) / dim);
  return Math.sign(shown) * (1 / (1 - u) - 1) * (dim / 0.55);
};

export function useCropGesture(o: Options) {
  const opts = React.useRef(o);
  React.useLayoutEffect(() => {
    opts.current = o;
  });

  const state = React.useRef<CropState>({ x: 0, y: 0, z: 1, r: 0 });
  const vel = React.useRef({ x: 0, y: 0, z: 0 });
  const goal = React.useRef<Partial<CropState> | null>(null);
  const loop = React.useRef(0);
  const lastFrame = React.useRef(0);
  const pointers = React.useRef(new Map<number, Vec>());
  const hold = React.useRef<{
    x: number;
    y: number;
    z: number;
    mid: Vec;
    dist: number;
  } | null>(null);
  const samples = React.useRef<{ x: number; y: number; t: number }[]>([]);
  const wheelTimer = React.useRef(0);

  /** How far the photo may move each way at zoom z and rotation r before it would uncover the crop. */
  const limits = (z: number, r: number): Vec => {
    const { image: img, size: d } = opts.current;
    if (!img) return { x: 0, y: 0 };
    const cover = d / Math.min(img.w, img.h);
    const w = (r % 2 ? img.h : img.w) * cover * z;
    const h = (r % 2 ? img.w : img.h) * cover * z;
    return { x: Math.max(0, (w - d) / 2), y: Math.max(0, (h - d) / 2) };
  };

  const promote = (on: boolean) => {
    for (const el of [
      opts.current.refs.pan.current,
      opts.current.refs.zoom.current,
    ])
      if (el) el.style.willChange = on ? "transform" : "";
    if (opts.current.refs.grid.current)
      opts.current.refs.grid.current.style.opacity =
        on && hold.current ? "1" : "0";
  };

  const write = () => {
    const s = state.current;
    if (opts.current.refs.pan.current)
      opts.current.refs.pan.current.style.transform = `translate3d(${s.x}px, ${s.y}px, 0)`;
    if (opts.current.refs.zoom.current)
      opts.current.refs.zoom.current.style.transform = `scale(${s.z})`;
    const input = opts.current.refs.slider.current;
    if (input && document.activeElement !== input)
      input.value = String(clamp(s.z, 1, opts.current.maxZoom));
  };

  const settle = React.useCallback(() => {
    cancelAnimationFrame(loop.current);
    loop.current = 0;
    vel.current = { x: 0, y: 0, z: 0 };
    goal.current = null;
    promote(false);
    opts.current.onSettle?.({ ...state.current });
  }, []);

  const tick = (now: number) => {
    const dt = Math.min(48, now - (lastFrame.current || now - 16));
    lastFrame.current = now;
    const s = state.current;
    const v = vel.current;
    const { maxZoom: max } = opts.current;
    const steps = Math.max(1, Math.round(dt / STEP));
    const h = dt / steps / 1000;
    for (let i = 0; i < steps; i++) {
      const zTo = clamp(goal.current?.z ?? s.z, 1, max);
      v.z += (-K * (s.z - zTo) - C * v.z) * h;
      s.z += v.z * h;
      const lim = limits(s.z, s.r);
      for (const axis of ["x", "y"] as const) {
        const target = goal.current?.[axis];
        const bound = lim[axis];
        if (target !== undefined || Math.abs(s[axis]) > bound) {
          // A goal (keys, rotation) or out of bounds: spring there, keeping whatever speed it has.
          const to = clamp(target ?? s[axis], -bound, bound);
          v[axis] += (-K * (s[axis] - to) - C * v[axis]) * h;
        } else v[axis] *= Math.exp(-FRICTION * h);
        s[axis] += v[axis] * h;
      }
    }
    write();
    const lim = limits(s.z, s.r);
    const zTo = clamp(goal.current?.z ?? s.z, 1, max);
    const still =
      Math.abs(v.x) < 4 &&
      Math.abs(v.y) < 4 &&
      Math.abs(v.z) < 0.01 &&
      Math.abs(s.z - zTo) < 0.0008 &&
      Math.abs(s.x) <= lim.x + 0.3 &&
      Math.abs(s.y) <= lim.y + 0.3 &&
      (goal.current?.x === undefined ||
        Math.abs(s.x - clamp(goal.current.x, -lim.x, lim.x)) < 0.3) &&
      (goal.current?.y === undefined ||
        Math.abs(s.y - clamp(goal.current.y, -lim.y, lim.y)) < 0.3);
    if (still) {
      s.z = zTo;
      const end = limits(s.z, s.r);
      s.x = clamp(goal.current?.x ?? s.x, -end.x, end.x);
      s.y = clamp(goal.current?.y ?? s.y, -end.y, end.y);
      write();
      settle();
      return;
    }
    loop.current = requestAnimationFrame(tick);
  };

  const run = () => {
    if (opts.current.reduced) {
      // No springs: land where it would have, at once.
      const s = state.current;
      s.z = clamp(goal.current?.z ?? s.z, 1, opts.current.maxZoom);
      const lim = limits(s.z, s.r);
      s.x = clamp(goal.current?.x ?? s.x, -lim.x, lim.x);
      s.y = clamp(goal.current?.y ?? s.y, -lim.y, lim.y);
      write();
      settle();
      return;
    }
    promote(true);
    if (!loop.current) {
      lastFrame.current = 0;
      loop.current = requestAnimationFrame(tick);
    }
  };

  const stop = () => {
    cancelAnimationFrame(loop.current);
    loop.current = 0;
  };

  React.useEffect(() => () => cancelAnimationFrame(loop.current), []);

  // ── Pointers ───────────────────────────────────────────
  const centre = (p: Vec): Vec => {
    const r = opts.current.refs.stage.current!.getBoundingClientRect();
    return { x: p.x - (r.left + r.width / 2), y: p.y - (r.top + r.height / 2) };
  };
  const midpoint = (): { mid: Vec; dist: number } => {
    const ps = [...pointers.current.values()];
    if (ps.length < 2) return { mid: centre(ps[0]), dist: 0 };
    return {
      mid: centre({ x: (ps[0].x + ps[1].x) / 2, y: (ps[0].y + ps[1].y) / 2 }),
      dist: Math.hypot(ps[0].x - ps[1].x, ps[0].y - ps[1].y),
    };
  };
  /** Start (or restart, when a finger joins or leaves) from what's shown, unbanded so nothing jumps. */
  const begin = () => {
    const s = state.current;
    const { maxZoom: max } = opts.current;
    const z =
      s.z < 1
        ? 1 - (1 - s.z) / 0.35
        : s.z > max
          ? max + (s.z - max) / 0.3
          : s.z;
    const lim = limits(s.z, s.r);
    const d = opts.current.size;
    const raw = (p: number, bound: number) =>
      Math.abs(p) > bound
        ? Math.sign(p) * bound + unband(p - Math.sign(p) * bound, d)
        : p;
    const { mid, dist } = midpoint();
    hold.current = { x: raw(s.x, lim.x), y: raw(s.y, lim.y), z, mid, dist };
    samples.current = [];
  };

  const follow = () => {
    const g = hold.current;
    if (!g) return;
    const s = state.current;
    const { maxZoom: max, size: d } = opts.current;
    const { mid, dist } = midpoint();
    let z = g.z;
    let x = g.x + (mid.x - g.mid.x);
    let y = g.y + (mid.y - g.mid.y);
    if (pointers.current.size > 1 && g.dist > 0) {
      z = g.z * (dist / g.dist);
      // The point of the photo that was under the fingers stays under them.
      x = mid.x - (g.mid.x - g.x) * (z / g.z);
      y = mid.y - (g.mid.y - g.y) * (z / g.z);
    }
    s.z =
      z < 1
        ? Math.max(0.6, 1 - (1 - z) * 0.35)
        : z > max
          ? max + (z - max) * 0.3
          : z;
    const lim = limits(s.z, s.r);
    s.x =
      Math.abs(x) > lim.x
        ? Math.sign(x) * lim.x + band(x - Math.sign(x) * lim.x, d)
        : x;
    s.y =
      Math.abs(y) > lim.y
        ? Math.sign(y) * lim.y + band(y - Math.sign(y) * lim.y, d)
        : y;
    write();
    const t = performance.now();
    samples.current.push({ x: s.x, y: s.y, t });
    while (samples.current.length > 2 && t - samples.current[0].t > 90)
      samples.current.shift();
  };

  const onPointerDown = (e: React.PointerEvent<HTMLElement>) => {
    if (!opts.current.image || (e.pointerType === "mouse" && e.button !== 0))
      return;
    e.currentTarget.setPointerCapture(e.pointerId);
    pointers.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
    // Catch it mid-flight: whatever was moving stops under the finger.
    stop();
    vel.current = { x: 0, y: 0, z: 0 };
    goal.current = null;
    begin();
    promote(true);
  };
  const onPointerMove = (e: React.PointerEvent<HTMLElement>) => {
    if (!pointers.current.has(e.pointerId)) return;
    pointers.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
    follow();
  };
  const onPointerUp = (e: React.PointerEvent<HTMLElement>) => {
    if (!pointers.current.delete(e.pointerId)) return;
    if (pointers.current.size) return begin();
    const ss = samples.current;
    const first = ss[0];
    const last = ss[ss.length - 1];
    const fresh = last && performance.now() - last.t < 80 && last.t > first.t;
    if (fresh) {
      let vx = ((last.x - first.x) / (last.t - first.t)) * 1000;
      let vy = ((last.y - first.y) / (last.t - first.t)) * 1000;
      const lim = limits(state.current.z, state.current.r);
      if (state.current.x > lim.x && vx > 0) vx = softenVelocity(vx, 0, 8);
      else if (state.current.x < -lim.x && vx < 0)
        vx = softenVelocity(vx, 0, 8);
      if (state.current.y > lim.y && vy > 0) vy = softenVelocity(vy, 0, 8);
      else if (state.current.y < -lim.y && vy < 0)
        vy = softenVelocity(vy, 0, 8);
      vel.current = { x: vx, y: vy, z: 0 };
    } else {
      vel.current = { x: 0, y: 0, z: 0 };
    }
    hold.current = null;
    run();
  };

  // Wheel and trackpad pinch zoom about the pointer. Not passive: the page shouldn't scroll under the photo.
  React.useEffect(() => {
    const el = opts.current.refs.stage.current;
    if (!el) return;
    const onWheel = (e: WheelEvent) => {
      if (!opts.current.image) return;
      e.preventDefault();
      stop();
      const s = state.current;
      const { maxZoom: max } = opts.current;
      const z0 = s.z;
      const z1 = clamp(
        z0 * Math.exp(-e.deltaY * (e.ctrlKey ? 0.012 : 0.0016)),
        1,
        max,
      );
      const p = centre({ x: e.clientX, y: e.clientY });
      const lim = limits(z1, s.r);
      s.x = clamp(p.x - (p.x - s.x) * (z1 / z0), -lim.x, lim.x);
      s.y = clamp(p.y - (p.y - s.y) * (z1 / z0), -lim.y, lim.y);
      s.z = z1;
      promote(true);
      write();
      window.clearTimeout(wheelTimer.current);
      wheelTimer.current = window.setTimeout(settle, 160);
    };
    el.addEventListener("wheel", onWheel, { passive: false });
    return () => {
      el.removeEventListener("wheel", onWheel);
      window.clearTimeout(wheelTimer.current);
    };
  }, [o.image, settle]);

  // ── Commands ───────────────────────────────────────────
  /** Zoom to z about the centre at once (the slider). Call settle() yourself when the slider lets go. */
  const zoomTo = (z: number) => {
    stop();
    const s = state.current;
    const z1 = clamp(z, 1, opts.current.maxZoom);
    const lim = limits(z1, s.r);
    s.x = clamp(s.x * (z1 / s.z), -lim.x, lim.x);
    s.y = clamp(s.y * (z1 / s.z), -lim.y, lim.y);
    s.z = z1;
    promote(true);
    write();
  };

  /** Glide by a step (keys, buttons): the spring takes it there and it settles. */
  const nudge = (dx: number, dy: number) => {
    const s = state.current;
    goal.current = {
      x: (goal.current?.x ?? s.x) + dx,
      y: (goal.current?.y ?? s.y) + dy,
      z: goal.current?.z ?? s.z,
    };
    run();
  };
  const zoomBy = (factor: number) => {
    const s = state.current;
    const z0 = goal.current?.z ?? s.z;
    const z1 = clamp(z0 * factor, 1, opts.current.maxZoom);
    goal.current = {
      x: (goal.current?.x ?? s.x) * (z1 / z0),
      y: (goal.current?.y ?? s.y) * (z1 / z0),
      z: z1,
    };
    run();
  };

  /** A quarter turn clockwise, thrown with a slight overshoot; the photo then springs inside the new bounds. */
  const rotate = () => {
    const s = state.current;
    const from = s.r * 90;
    s.r += 1;
    const el = opts.current.refs.rot.current;
    if (el) {
      el.style.transform = `rotate(${s.r * 90}deg)`;
      if (!opts.current.reduced)
        el.animate(
          [
            { transform: `rotate(${from}deg)` },
            { transform: `rotate(${s.r * 90}deg)` },
          ],
          { duration: 480, easing: THROW },
        );
    }
    goal.current = { x: s.x, y: s.y, z: s.z };
    run();
  };

  /** Back to the fit for a new photo. */
  const reset = () => {
    stop();
    state.current = { x: 0, y: 0, z: 1, r: 0 };
    vel.current = { x: 0, y: 0, z: 0 };
    goal.current = null;
    if (opts.current.refs.rot.current)
      opts.current.refs.rot.current.style.transform = "rotate(0deg)";
    write();
  };

  /** Where the crop sits in the photo's own pixels. */
  const area = (): CropArea | null => {
    const { image: img, size: d } = opts.current;
    if (!img) return null;
    const s = state.current;
    const k = (d / Math.min(img.w, img.h)) * s.z;
    const turn = ((s.r % 4) + 4) % 4;
    const a = (-turn * Math.PI) / 2;
    // The crop's centre relative to the photo's centre, on screen, turned back into the photo's own frame.
    const dx = -s.x;
    const dy = -s.y;
    const ux = (dx * Math.cos(a) - dy * Math.sin(a)) / k;
    const uy = (dx * Math.sin(a) + dy * Math.cos(a)) / k;
    return {
      centerX: img.w / 2 + ux,
      centerY: img.h / 2 + uy,
      size: d / k,
      rotation: turn * 90,
    };
  };

  /** Draws the crop into a square canvas of `output` px and encodes it. */
  const toBlob = async (
    img: HTMLImageElement,
    output: number,
    type: string,
    quality: number,
  ): Promise<Blob> => {
    const { image: dims, size: d } = opts.current;
    if (!dims) throw new Error("No photo");
    const s = state.current;
    const canvas = document.createElement("canvas");
    canvas.width = output;
    canvas.height = output;
    const ctx = canvas.getContext("2d");
    if (!ctx) throw new Error("No canvas");
    const k = (d / Math.min(dims.w, dims.h)) * s.z;
    ctx.imageSmoothingQuality = "high";
    ctx.translate(output / 2, output / 2);
    ctx.scale(output / d, output / d);
    ctx.translate(s.x, s.y);
    ctx.rotate((s.r * Math.PI) / 2);
    ctx.scale(k, k);
    ctx.drawImage(img, -dims.w / 2, -dims.h / 2, dims.w, dims.h);
    return new Promise((resolve, reject) =>
      canvas.toBlob(
        (b) =>
          b ? resolve(b) : reject(new Error("Couldn't encode the photo")),
        type,
        quality,
      ),
    );
  };

  return {
    handlers: {
      onPointerDown,
      onPointerMove,
      onPointerUp,
      onPointerCancel: onPointerUp,
    },
    state: () => ({ ...state.current }),
    zoomTo,
    settle,
    nudge,
    zoomBy,
    rotate,
    reset,
    area,
    toBlob,
  };
}

"use client";

import * as React from "react";

/*
 * The dock's motion engine. One frame loop eases every moving part toward its target and
 * stops when they all settle, so a resting dock costs nothing.
 *
 *   lens     tools near the pointer scale up and the row parts around them. Distances are
 *            measured from fixed rest positions, so growth never feeds back into the pointer
 *            maths. Only transforms move: no layout while you sweep across it.
 *   marker   the selected tool's pad glides to the new tool and rides its magnification.
 *   label    one name that follows the tool under the pointer and lifts above its new height.
 *   surface  the tray widens with the lens, and grows up into the open panel.
 */

export type DockLensOptions = {
  count: number;
  size: number;
  gap: number;
  inset: number;
  magnification: number;
  reduced: boolean;
  onHover: (index: number | null) => void;
};

type Targets = {
  pointer: number | null;
  focus: number | null;
  selected: number;
  open: boolean;
  panelHeight: number;
  panelWidth: number;
};

// Seconds to close ~63% of the gap. While the pointer sweeps the lens is all but attached to it (TRACK); entering and
// leaving the dock, where the targets jump, ease more gently (LENS) so the tools swell and settle instead of snapping.

export function useDockLens({
  count,
  size,
  gap,
  inset,
  magnification,
  reduced,
  onHover,
}: DockLensOptions) {
  const icons = React.useRef<(HTMLElement | null)[]>([]);
  const pad = React.useRef<HTMLDivElement>(null);
  const label = React.useRef<HTMLDivElement>(null);
  const surface = React.useRef<HTMLDivElement>(null);
  const panel = React.useRef<HTMLDivElement>(null);
  const row = React.useRef<HTMLDivElement>(null);

  const target = React.useRef<Targets>({
    pointer: null,
    focus: null,
    selected: 0,
    open: false,
    panelHeight: 0,
    panelWidth: 0,
  });
  const sim = React.useRef({
    s: [] as number[],
    sV: [] as number[],
    o: [] as number[],
    pad: NaN,
    padV: 0,
    labelX: NaN,
    labelLift: 0,
    labelOpacity: 0,
    open: 0,
    openV: 0,
    height: 0,
    heightV: 0,
    width: 0,
    widthV: 0,
    last: 0,
  });
  const frame = React.useRef(0);
  const hovered = React.useRef<number | null>(null);
  const origin = React.useRef<number | null>(null);
  const opts = React.useRef({
    count,
    size,
    gap,
    inset,
    magnification,
    reduced,
    onHover,
  });
  React.useLayoutEffect(() => {
    opts.current = { count, size, gap, inset, magnification, reduced, onHover };
  });

  const tick = React.useCallback(function runTick(now: number) {
    frame.current = 0;
    const {
      count: n,
      size: S,
      gap: G,
      inset: P,
      magnification: M,
      reduced: still,
      onHover: hover,
    } = opts.current;
    const t = target.current;
    const st = sim.current;
    const dt = st.last ? Math.min(0.064, (now - st.last) / 1000) : 1 / 60;
    st.last = now;
    const ease = (tau: number) => (still ? 1 : 1 - Math.exp(-dt / tau));
    let moving = false;
    const approach = (from: number, to: number, k: number) => {
      const next = Number.isNaN(from) ? to : from + (to - from) * k;
      if (Math.abs(next - to) > 0.0005) moving = true;
      return Math.abs(next - to) <= 0.0005 ? to : next;
    };

    const step = S + G;
    const rest = (i: number) => P + i * step + S / 2;
    const anchor = t.focus !== null ? rest(t.focus) : t.pointer;
    const reach = S * 2.4;
    const peak = still ? 1 : t.open ? Math.min(M, 1.22) : M;

    // The lens: scale per tool with organic settling when the pointer leaves
    let extra = 0;
    for (let i = 0; i < n; i++) {
      const d = anchor === null ? Infinity : Math.abs(anchor - rest(i));
      const f = d < reach ? (1 + Math.cos((d / reach) * Math.PI)) / 2 : 0;
      const goal = 1 + (peak - 1) * f;

      if (anchor === null && !still) {
        // Soft harmonic breath as icons return to rest (visualDuration ~0.28s)
        const sCur = st.s[i] ?? 1;
        const kIcon = 260,
          cIcon = 24;
        st.sV[i] =
          (st.sV[i] ?? 0) +
          (-kIcon * (sCur - 1) - cIcon * (st.sV[i] ?? 0)) * dt;
        st.s[i] = sCur + st.sV[i] * dt;
        if (Math.abs(st.s[i] - 1) < 0.002 && Math.abs(st.sV[i]) < 0.02) {
          st.s[i] = 1;
          st.sV[i] = 0;
        } else {
          moving = true;
        }
      } else {
        st.sV[i] = 0;
        st.s[i] = approach(
          st.s[i] ?? 1,
          goal,
          ease(Math.abs(goal - (st.s[i] ?? 1)) > 0.08 ? 0.028 : 0.016),
        );
      }
      extra += S * (st.s[i] - 1);
    }
    let run = 0;
    for (let i = 0; i < n; i++) {
      const e = S * (st.s[i] - 1);
      st.o[i] = run + e / 2 - extra / 2;
      run += e;
      const el = icons.current[i];
      if (el)
        el.style.transform = `translate3d(${st.o[i]}px,0,0) scale(${st.s[i]})`;
    }

    // The pad snaps with a lively harmonic spring (hint of overshoot for magnetic tactile feel)
    const padGoal = rest(t.selected);
    if (still || Number.isNaN(st.pad)) {
      st.pad = padGoal;
      st.padV = 0;
    } else {
      const kPad = 360,
        cPad = 28;
      st.padV =
        (st.padV ?? 0) +
        (-kPad * (st.pad - padGoal) - cPad * (st.padV ?? 0)) * dt;
      st.pad += st.padV * dt;
      if (Math.abs(st.pad - padGoal) < 0.25 && Math.abs(st.padV) < 4) {
        st.pad = padGoal;
        st.padV = 0;
      } else {
        moving = true;
      }
    }
    const u = Math.max(0, Math.min(n - 1, (st.pad - rest(0)) / step));
    const i0 = Math.floor(u),
      i1 = Math.min(n - 1, i0 + 1),
      w = u - i0;
    const padOffset = (st.o[i0] ?? 0) * (1 - w) + (st.o[i1] ?? 0) * w;
    const padScale = (st.s[i0] ?? 1) * (1 - w) + (st.s[i1] ?? 1) * w;
    if (pad.current)
      pad.current.style.transform = `translate3d(${st.pad - S / 2 + padOffset}px,0,0) scale(${padScale})`;

    // The label: glides crisply with the tool and lifts above its height
    const near =
      anchor === null
        ? null
        : Math.max(0, Math.min(n - 1, Math.round((anchor - rest(0)) / step)));
    if (near !== hovered.current && near !== null) hover(near);
    if (near !== null) hovered.current = near;
    const shown = near ?? hovered.current;
    if (shown !== null) {
      st.labelX = approach(
        st.labelX,
        rest(shown) + (st.o[shown] ?? 0),
        ease(0.038),
      );
      st.labelLift = approach(
        st.labelLift,
        S * ((st.s[shown] ?? 1) - 1),
        ease(0.018),
      );
    }
    st.labelOpacity = approach(
      st.labelOpacity,
      near !== null && !t.open ? 1 : 0,
      ease(near !== null ? 0.04 : 0.035),
    );
    if (label.current) {
      label.current.style.transform = `translate3d(${st.labelX}px,${-st.labelLift - (1 - st.labelOpacity) * 4}px,0) translateX(-50%)`;
      label.current.style.opacity = String(st.labelOpacity);
    }

    // The surface: a tray that widens with the lens and grows up into the panel via smooth critically-damped spring
    const restWidth = n * S + (n - 1) * G + 2 * P;
    const hGoal = t.open ? t.panelHeight : 0;
    const wGoal = t.open ? Math.max(restWidth, t.panelWidth) : restWidth;
    const oGoal = t.open ? 1 : 0;

    if (still) {
      st.open = oGoal;
      st.height = hGoal;
      st.width = wGoal;
      st.openV = 0;
      st.heightV = 0;
      st.widthV = 0;
    } else {
      const kSurf = 240,
        cSurf = 31;
      st.heightV =
        (st.heightV ?? 0) +
        (-kSurf * (st.height - hGoal) - cSurf * (st.heightV ?? 0)) * dt;
      st.height += st.heightV * dt;
      if (Math.abs(st.height - hGoal) < 0.3 && Math.abs(st.heightV) < 4) {
        st.height = hGoal;
        st.heightV = 0;
      } else {
        moving = true;
      }

      st.widthV =
        (st.widthV ?? 0) +
        (-kSurf * (st.width - wGoal) - cSurf * (st.widthV ?? 0)) * dt;
      st.width += st.widthV * dt;
      if (Math.abs(st.width - wGoal) < 0.3 && Math.abs(st.widthV) < 4) {
        st.width = wGoal;
        st.widthV = 0;
      } else {
        moving = true;
      }

      st.openV =
        (st.openV ?? 0) +
        (-kSurf * (st.open - oGoal) - cSurf * (st.openV ?? 0)) * dt;
      st.open += st.openV * dt;
      if (Math.abs(st.open - oGoal) < 0.002 && Math.abs(st.openV) < 0.05) {
        st.open = oGoal;
        st.openV = 0;
      } else {
        moving = true;
      }
    }

    const band = S + 2 * P;
    const wide = Math.max(st.width, restWidth + extra);
    if (surface.current) {
      surface.current.style.width = `${wide}px`;
      surface.current.style.height = `${band + st.height}px`;
      surface.current.style.borderRadius = `${band / 2 + (20 - band / 2) * Math.min(1, st.open * 1.6)}px`;
    }
    if (panel.current) {
      panel.current.style.height = `${st.height}px`;
      panel.current.style.width = `${wide - 2}px`;
      panel.current.style.opacity = String(
        Math.max(0, (st.open - 0.35) / 0.65),
      );
      panel.current.style.visibility =
        st.open < 0.01 && !t.open ? "hidden" : "visible";
    }

    if (moving) frame.current = requestAnimationFrame(runTick);
    else st.last = 0;
  }, []);

  const kick = React.useCallback(() => {
    if (!frame.current) frame.current = requestAnimationFrame(tick);
  }, [tick]);

  // A rAF id kept in a ref must be cleared on unmount, or StrictMode's remount thinks the loop is still running.
  React.useEffect(() => {
    // A scroll under a resting pointer moves the row: measure again on the next move.
    const forget = () => {
      origin.current = null;
    };
    window.addEventListener("scroll", forget, { passive: true, capture: true });
    window.addEventListener("resize", forget);
    return () => {
      window.removeEventListener("scroll", forget, { capture: true });
      window.removeEventListener("resize", forget);
      cancelAnimationFrame(frame.current);
      frame.current = 0;
    };
  }, []);
  React.useLayoutEffect(() => {
    sim.current.last = 0;
    tick(performance.now());
  }, [count, size, gap, inset, magnification, reduced, tick]);

  const attachRow = React.useCallback((el: HTMLDivElement | null) => {
    row.current = el;
  }, []);
  const attachPad = React.useCallback((el: HTMLDivElement | null) => {
    pad.current = el;
  }, []);
  const attachLabel = React.useCallback((el: HTMLDivElement | null) => {
    label.current = el;
  }, []);
  const attachSurface = React.useCallback((el: HTMLDivElement | null) => {
    surface.current = el;
  }, []);
  const attachPanel = React.useCallback((el: HTMLDivElement | null) => {
    panel.current = el;
  }, []);
  const attachIcon = React.useCallback(
    (index: number, el: HTMLElement | null) => {
      icons.current[index] = el;
    },
    [],
  );
  const focusIcon = React.useCallback((index: number) => {
    icons.current[index]?.focus({ preventScroll: true });
  }, []);

  const set = React.useCallback(
    (next: Partial<Targets>) => {
      Object.assign(target.current, next);
      kick();
    },
    [kick],
  );

  const pointer = React.useCallback(
    (event: React.PointerEvent) => {
      if (event.pointerType === "touch" || !row.current) return;
      // The row never moves under the lens (only transforms do), so its edge is read once per hover.
      if (origin.current === null)
        origin.current = row.current.getBoundingClientRect().left;
      target.current.focus = null;
      target.current.pointer = event.clientX - origin.current;
      kick();
    },
    [kick],
  );

  const leave = React.useCallback(() => {
    origin.current = null;
    target.current.pointer = null;
    kick();
  }, [kick]);

  return React.useMemo(
    () => ({
      attachIcon,
      attachPad,
      attachLabel,
      attachSurface,
      attachPanel,
      attachRow,
      focusIcon,
      set,
      pointer,
      leave,
    }),
    [
      attachIcon,
      attachPad,
      attachLabel,
      attachSurface,
      attachPanel,
      attachRow,
      focusIcon,
      set,
      pointer,
      leave,
    ],
  );
}

"use client";

import * as React from "react";
import type {
  DropZoneFile,
  DropZoneProps,
  DropZoneRejection,
} from "./drop-zone-types";
import { selectFiles } from "./drop-zone-utils";

type Options = Pick<
  DropZoneProps,
  | "accept"
  | "maxSize"
  | "maxFiles"
  | "multiple"
  | "disabled"
  | "onUpload"
  | "onFilesChange"
  | "onFilesRejected"
>;

export function useDropZone(options: Options) {
  const [rows, setRows] = React.useState<DropZoneFile[]>([]);
  const [rejections, setRejections] = React.useState<DropZoneRejection[]>([]);
  const [announcement, setAnnouncement] = React.useState("");
  const current = React.useRef(rows);
  const latest = React.useRef(options);
  React.useLayoutEffect(() => {
    latest.current = options;
  });
  const controllers = React.useRef(new Map<string, AbortController>());
  const sequence = React.useRef(0);
  const prefix = React.useId();
  const mounted = React.useRef(true);

  React.useEffect(() => {
    mounted.current = true;
    const active = controllers.current;
    return () => {
      mounted.current = false;
      active.forEach((controller) => controller.abort());
      active.clear();
    };
  }, []);

  const commit = React.useCallback((next: DropZoneFile[]) => {
    current.current = next;
    if (mounted.current) setRows(next);
  }, []);

  const patch = React.useCallback(
    (id: string, next: Partial<DropZoneFile>) => {
      if (mounted.current)
        commit(
          current.current.map((row) =>
            row.id === id ? { ...row, ...next } : row,
          ),
        );
    },
    [commit],
  );

  const start = React.useCallback(
    (id: string, file: File) => {
      const upload = latest.current.onUpload;
      if (!upload) {
        patch(id, { status: "ready", progress: 0, error: undefined });
        return;
      }
      controllers.current.get(id)?.abort();
      const controller = new AbortController();
      controllers.current.set(id, controller);
      patch(id, { status: "uploading", progress: 0, error: undefined });
      const active = () =>
        mounted.current &&
        !controller.signal.aborted &&
        controllers.current.get(id) === controller;
      let last = 0;
      Promise.resolve()
        .then(() => {
          if (!active()) return;
          return upload(file, {
            signal: controller.signal,
            progress: (fraction) => {
              if (!active() || !Number.isFinite(fraction)) return;
              const value = Math.max(last, Math.min(1, Math.max(0, fraction)));
              if (value === last) return;
              last = value;
              patch(id, { progress: value });
            },
          });
        })
        .then(
          () => {
            if (!active()) return;
            patch(id, { status: "done", progress: 1 });
            setAnnouncement(`${file.name} uploaded.`);
          },
          (error: unknown) => {
            if (!active()) return;
            const message =
              error instanceof Error && error.message
                ? error.message
                : "Upload failed. Please try again.";
            patch(id, { status: "error", error: message });
            setAnnouncement(`${file.name}: ${message}`);
          },
        )
        .finally(() => {
          if (controllers.current.get(id) === controller)
            controllers.current.delete(id);
        });
    },
    [patch],
  );

  const add = React.useCallback(
    (files: File[]) => {
      const settings = latest.current;
      if (settings.disabled || !files.length) return;
      const { accepted, rejected } = selectFiles(
        files,
        current.current.map((row) => row.file),
        settings,
      );
      setRejections(rejected);
      if (accepted.length) {
        const added: DropZoneFile[] = accepted.map((file) => ({
          id: `${prefix}-${++sequence.current}`,
          file,
          status: settings.onUpload ? "uploading" : "ready",
          progress: 0,
        }));
        if (settings.multiple === false) {
          controllers.current.forEach((controller) => controller.abort());
          controllers.current.clear();
        }
        const next = [
          ...(settings.multiple === false ? [] : current.current),
          ...added,
        ];
        commit(next);
        added.forEach((row) => start(row.id, row.file));
        settings.onFilesChange?.(next.map((row) => row.file));
      }
      setAnnouncement(
        [
          accepted.length
            ? `Added ${accepted.map((file) => file.name).join(", ")}.`
            : "",
          rejected.length
            ? `${rejected.length} file${rejected.length === 1 ? "" : "s"} skipped. Check the file requirements.`
            : "",
        ]
          .filter(Boolean)
          .join(" "),
      );
      if (rejected.length) settings.onFilesRejected?.(rejected);
    },
    [commit, prefix, start],
  );

  const remove = React.useCallback(
    (id: string) => {
      if (latest.current.disabled) return;
      const row = current.current.find((entry) => entry.id === id);
      if (!row) return;
      controllers.current.get(id)?.abort();
      controllers.current.delete(id);
      const next = current.current.filter((entry) => entry.id !== id);
      commit(next);
      setAnnouncement(
        `${row.file.name} ${row.status === "uploading" ? "cancelled" : "removed"}.`,
      );
      latest.current.onFilesChange?.(next.map((entry) => entry.file));
    },
    [commit],
  );

  const retry = React.useCallback(
    (id: string) => {
      if (latest.current.disabled) return;
      const row = current.current.find((entry) => entry.id === id);
      if (row?.status === "error") {
        start(id, row.file);
        setAnnouncement(`Retrying ${row.file.name}.`);
      }
    },
    [start],
  );

  return {
    rows,
    rejections,
    announcement,
    add,
    remove,
    retry,
    dismissRejections: () => setRejections([]),
  };
}

"use client";

import * as React from "react";
import { EASE_OUT } from "./imported-ui-interaction-motion";

export type HoldStatus = "idle" | "holding" | "pending" | "success" | "error";

export function useHoldConfirm(
  onConfirm: () => void | Promise<void>,
  duration: number,
  resetAfter: number,
  disabled: boolean,
  reduced: boolean,
) {
  const [status, setStatus] = React.useState<HoldStatus>("idle");
  const phase = React.useRef<HoldStatus>("idle");
  const progress = React.useRef<SVGCircleElement>(null);
  const animation = React.useRef<Animation | null>(null);
  const timer = React.useRef<ReturnType<typeof setTimeout> | null>(null);
  const resetTimer = React.useRef<ReturnType<typeof setTimeout> | null>(null);
  const held = React.useRef(false);
  const owner = React.useRef<string | null>(null);
  const alive = React.useRef(false);
  const action = React.useRef(onConfirm);
  React.useLayoutEffect(() => {
    action.current = onConfirm;
  });
  const setPhase = (next: HoldStatus) => {
    phase.current = next;
    setStatus(next);
  };
  const cancel = (source?: string) => {
    if (!held.current || (source && source !== owner.current)) return;
    held.current = false;
    if (timer.current) clearTimeout(timer.current);
    const path = progress.current;
    const from = path ? getComputedStyle(path).strokeDashoffset : "1";
    animation.current?.cancel();
    if (path && !reduced)
      animation.current = path.animate(
        [{ strokeDashoffset: from }, { strokeDashoffset: "1" }],
        { duration: 240, easing: EASE_OUT },
      );
    setPhase("idle");
  };
  const begin = (source: string) => {
    if (disabled || held.current || !["idle", "error"].includes(phase.current))
      return;
    if (resetTimer.current) clearTimeout(resetTimer.current);
    held.current = true;
    owner.current = source;
    setPhase("holding");
    animation.current?.cancel();
    if (progress.current)
      animation.current = progress.current.animate(
        [{ strokeDashoffset: "1" }, { strokeDashoffset: "0" }],
        { duration, easing: "linear", fill: "forwards" },
      );
    timer.current = setTimeout(async () => {
      if (!held.current || !alive.current) return;
      held.current = false;
      setPhase("pending");
      try {
        await action.current();
        if (alive.current) setPhase("success");
      } catch {
        if (alive.current) setPhase("error");
      } finally {
        animation.current?.cancel();
        if (alive.current && resetAfter > 0)
          resetTimer.current = setTimeout(() => setPhase("idle"), resetAfter);
      }
    }, duration);
  };
  const cancelRef = React.useRef(cancel);
  React.useLayoutEffect(() => {
    cancelRef.current = cancel;
  });
  React.useEffect(() => {
    alive.current = true;
    const hidden = () => {
      if (document.hidden) cancelRef.current();
    };
    const blur = () => cancelRef.current();
    window.addEventListener("blur", blur);
    document.addEventListener("visibilitychange", hidden);
    return () => {
      alive.current = false;
      held.current = false;
      if (timer.current) clearTimeout(timer.current);
      if (resetTimer.current) clearTimeout(resetTimer.current);
      animation.current?.cancel();
      window.removeEventListener("blur", blur);
      document.removeEventListener("visibilitychange", hidden);
    };
  }, []);
  React.useEffect(() => {
    cancelRef.current();
  }, [reduced]);
  React.useEffect(() => {
    if (disabled) cancelRef.current();
  }, [disabled]);
  return { status, progress, begin, cancel };
}

"use client";

import * as React from "react";

/*
 * The drop zone's membrane. Its border is a ring of points round a rounded rectangle, each free
 * to move along its outward normal. Every point is held to its goal by a spring and to its
 * neighbours by tension, so a pull in one place makes a smooth tent and a release sends a ripple
 * both ways round the edge. One frame loop integrates it and writes the path; it sleeps when the
 * line is still, and a line at rest is drawn as an exact rounded rectangle.
 *
 *   reach    a file outside pulls the nearest stretch of border out to meet it; close to the
 *            edge the bulge reaches past the file, so it is held before it crosses
 *   cross    once the file is inside the stretched line lets go and wobbles back
 *   press    inside, near an edge, the file presses the border out
 *   recoil   a file the zone can't take makes the line shrink away from it
 *   carry    a file leaving through the border drags it along until it slips off
 *   gulp     a drop pulls the whole border in and rings out from the drop point
 *   spit     a refused drop is pushed back out where it landed
 */

export type MembraneForce = {
  x: number;
  y: number;
  kind: "reach" | "recoil" | "carry";
  spread?: number;
};

type Ring = {
  count: number;
  w: number;
  h: number;
  r: number;
  bx: Float32Array;
  by: Float32Array;
  nx: Float32Array;
  ny: Float32Array;
  u: Float32Array;
  v: Float32Array;
  goal: Float32Array;
  acc: Float32Array;
};

const STEP = 1 / 240;
const SPRING = 220; // toward the goal
const TENSION = 15000; // toward the neighbours: a pull makes a tent, a release travels as a ripple
const DRAG = 6.5;
const VISCOSITY = 58; // damping between neighbours, so short wobbles die before long ones
const SPACING = 5; // px of border per point
const REACH = 200; // how far out a file starts to pull
const PULL = 44; // goal at the line itself; tension spreads it, so the line reaches about half of it
const SLIP = 32; // how far a carried file drags the line before it slips off

const round = (n: number) => Math.round(n * 100) / 100;

/** The exact rest shape, on half pixels so the 1px line is crisp. */
function restPath(w: number, h: number, radius: number) {
  const x0 = 0.5,
    y0 = 0.5,
    x1 = w - 0.5,
    y1 = h - 0.5;
  const r = Math.max(0, Math.min(radius - 0.5, (x1 - x0) / 2, (y1 - y0) / 2));
  return `M${x0 + r},${y0}H${x1 - r}A${r},${r} 0 0 1 ${x1},${y0 + r}V${y1 - r}A${r},${r} 0 0 1 ${x1 - r},${y1}H${x0 + r}A${r},${r} 0 0 1 ${x0},${y1 - r}V${y0 + r}A${r},${r} 0 0 1 ${x0 + r},${y0}Z`;
}

/** Points spaced evenly along the rounded rectangle, with their outward normals. */
function buildRing(w: number, h: number, radius: number): Ring {
  const x0 = 0.5,
    y0 = 0.5,
    x1 = w - 0.5,
    y1 = h - 0.5;
  const r = Math.max(0, Math.min(radius - 0.5, (x1 - x0) / 2, (y1 - y0) / 2));
  const sw = x1 - x0 - 2 * r,
    sh = y1 - y0 - 2 * r,
    arc = (Math.PI * r) / 2;
  const length = 2 * sw + 2 * sh + 4 * arc;
  const count = Math.max(48, Math.min(360, Math.round(length / SPACING)));
  const ring: Ring = {
    count,
    w,
    h,
    r,
    bx: new Float32Array(count),
    by: new Float32Array(count),
    nx: new Float32Array(count),
    ny: new Float32Array(count),
    u: new Float32Array(count),
    v: new Float32Array(count),
    goal: new Float32Array(count),
    acc: new Float32Array(count),
  };
  // Edges and corners clockwise from the top-left end of the top edge.
  const parts: {
    len: number;
    at: (t: number) => [number, number, number, number];
  }[] = [
    { len: sw, at: (t) => [x0 + r + t * sw, y0, 0, -1] },
    {
      len: arc,
      at: (t) => corner(x1 - r, y0 + r, -Math.PI / 2 + (t * Math.PI) / 2),
    },
    { len: sh, at: (t) => [x1, y0 + r + t * sh, 1, 0] },
    { len: arc, at: (t) => corner(x1 - r, y1 - r, (t * Math.PI) / 2) },
    { len: sw, at: (t) => [x1 - r - t * sw, y1, 0, 1] },
    {
      len: arc,
      at: (t) => corner(x0 + r, y1 - r, Math.PI / 2 + (t * Math.PI) / 2),
    },
    { len: sh, at: (t) => [x0, y1 - r - t * sh, -1, 0] },
    {
      len: arc,
      at: (t) => corner(x0 + r, y0 + r, Math.PI + (t * Math.PI) / 2),
    },
  ];
  function corner(
    cx: number,
    cy: number,
    a: number,
  ): [number, number, number, number] {
    const c = Math.cos(a),
      s = Math.sin(a);
    return [cx + c * r, cy + s * r, c, s];
  }
  for (let i = 0; i < count; i++) {
    let s = (i / count) * length;
    let k = 0;
    while (k < parts.length - 1 && s > parts[k].len) s -= parts[k++].len;
    const [x, y, nx, ny] = parts[k].at(
      parts[k].len ? Math.min(1, s / parts[k].len) : 0,
    );
    ring.bx[i] = x;
    ring.by[i] = y;
    ring.nx[i] = nx;
    ring.ny[i] = ny;
  }
  return ring;
}

export function useMembrane({
  radius,
  reduced,
}: {
  radius: number;
  reduced: boolean;
}) {
  const box = React.useRef<HTMLElement | null>(null);
  const path = React.useRef<SVGPathElement>(null);
  const arrow = React.useRef<HTMLSpanElement>(null);
  const ring = React.useRef<Ring | null>(null);
  const forces = React.useRef(
    new Map<string, MembraneForce & { inside: boolean }>(),
  );
  const swell = React.useRef(0);
  const frame = React.useRef(0);
  const last = React.useRef(0);
  const turn = React.useRef({ angle: 0, lean: 0, x: 0, y: 0 });
  const still = React.useRef(reduced);
  still.current = reduced;

  const draw = React.useCallback(
    (rest: boolean) => {
      const g = ring.current,
        el = path.current;
      if (!g || !el) return;
      if (rest) return el.setAttribute("d", restPath(g.w, g.h, radius));
      const { count: n, bx, by, nx, ny, u } = g;
      // Quadratic curves through the midpoints: smooth, and straight where the line is straight.
      const px = (i: number) => bx[i] + nx[i] * u[i];
      const py = (i: number) => by[i] + ny[i] * u[i];
      let d = `M${round((px(n - 1) + px(0)) / 2)},${round((py(n - 1) + py(0)) / 2)}`;
      for (let i = 0; i < n; i++) {
        const j = i === n - 1 ? 0 : i + 1;
        d += `Q${round(px(i))},${round(py(i))} ${round((px(i) + px(j)) / 2)},${round((py(i) + py(j)) / 2)}`;
      }
      el.setAttribute("d", `${d}Z`);
    },
    [radius],
  );

  const tick = React.useCallback(
    (now: number) => {
      frame.current = 0;
      const g = ring.current;
      if (!g) return;
      const dt = last.current
        ? Math.min(0.05, (now - last.current) / 1000)
        : 1 / 60;
      last.current = now;
      const { count: n, w, h, bx, by, nx, ny, u, v, goal, acc } = g;

      // Goals: each force bends the stretch of line nearest it; where two overlap the stronger wins.
      goal.fill(0);
      let pointer: (MembraneForce & { inside: boolean }) | null = null;
      for (const f of forces.current.values()) {
        if (f.kind !== "carry") pointer = f;
        const sigma = f.spread ?? 38,
          two = 2 * sigma * sigma,
          far = 9 * sigma * sigma;
        const inside = f.x > 0 && f.x < w && f.y > 0 && f.y < h;
        for (let i = 0; i < n; i++) {
          const dx = f.x - bx[i],
            dy = f.y - by[i];
          const s = dx * nx[i] + dy * ny[i];
          const lateral = dx * dx + dy * dy - s * s;
          if (lateral > far || (!inside && s < -6)) continue;
          const fall = Math.exp(-lateral / two);
          let want: number;
          if (f.kind === "reach")
            want = inside
              ? 10 * Math.exp(s / 28)
              : s < REACH
                ? PULL * (1 - Math.max(0, s) / REACH) ** 2
                : 0;
          else if (f.kind === "recoil")
            want = inside
              ? -7 * Math.exp(s / 28)
              : s < REACH
                ? -12 * (1 - Math.max(0, s) / REACH) ** 2
                : 0;
          else
            want = inside
              ? 18 * Math.exp(s / 22)
              : s < SLIP
                ? (s + 6) * 1.6
                : 0;
          want *= fall;
          if (Math.abs(want) > Math.abs(goal[i])) goal[i] = want;
        }
        // Crossing into the zone releases the stretched line: kick it back so it snaps rather than eases.
        if (f.kind === "reach" && inside && !f.inside) {
          for (let i = 0; i < n; i++) {
            const dx = f.x - bx[i],
              dy = f.y - by[i];
            v[i] -= 150 * Math.exp(-(dx * dx + dy * dy) / (2 * 60 * 60));
          }
        }
        f.inside = inside;
      }
      if (swell.current) for (let i = 0; i < n; i++) goal[i] += swell.current;

      // Integrate in fixed small steps; the tension is stiff.
      for (let t = 0; t < dt - 1e-6; t += STEP) {
        const h2 = Math.min(STEP, dt - t);
        for (let i = 0; i < n; i++) {
          const l = i === 0 ? n - 1 : i - 1,
            r = i === n - 1 ? 0 : i + 1;
          acc[i] =
            SPRING * (goal[i] - u[i]) +
            TENSION * (u[l] + u[r] - 2 * u[i]) -
            DRAG * v[i] +
            VISCOSITY * (v[l] + v[r] - 2 * v[i]);
        }
        for (let i = 0; i < n; i++) {
          v[i] += acc[i] * h2;
          u[i] += v[i] * h2;
        }
      }

      let moving = false,
        flat = true;
      for (let i = 0; i < n; i++) {
        if (Math.abs(u[i] - goal[i]) > 0.03 || Math.abs(v[i]) > 0.4)
          moving = true;
        if (Math.abs(goal[i]) > 0.001 || Math.abs(u[i]) > 0.03) flat = false;
      }
      if (!moving && flat) {
        u.fill(0);
        v.fill(0);
      }
      draw(!moving && flat);

      // The arrow watches a file outside, points into the zone once it is over it, and rests pointing up.
      const a = arrow.current,
        tr = turn.current;
      let angle = 0,
        lean = 0;
      if (pointer) {
        const cx = w / 2,
          cy = h / 2,
          dx = pointer.x - cx,
          dy = pointer.y - cy;
        angle = pointer.inside
          ? pointer.kind === "reach"
            ? 180
            : 0
          : (Math.atan2(dy, dx) * 180) / Math.PI + 90;
        lean = pointer.inside ? 0 : Math.min(4, Math.hypot(dx, dy) / 40);
        tr.x = dx;
        tr.y = dy;
      }
      const k = 1 - Math.exp(-dt / 0.08);
      let delta = ((angle - tr.angle + 540) % 360) - 180;
      if (Math.abs(delta) < 0.05) delta = 0;
      tr.angle += delta * k;
      tr.lean += (lean - tr.lean) * k;
      if (Math.abs(delta) > 0.05 || Math.abs(lean - tr.lean) > 0.02)
        moving = true;
      if (a) {
        const m = Math.hypot(tr.x, tr.y) || 1;
        a.style.transform = `translate3d(${round((tr.x / m) * tr.lean)}px,${round((tr.y / m) * tr.lean)}px,0) rotate(${round(tr.angle)}deg)`;
      }

      if (moving) frame.current = requestAnimationFrame(tick);
      else last.current = 0;
    },
    [draw],
  );

  const kick = React.useCallback(() => {
    if (still.current) return;
    if (!frame.current) frame.current = requestAnimationFrame(tick);
  }, [tick]);

  // Build the ring from the box's size and rebuild it when the box resizes.
  const attach = React.useCallback((el: HTMLElement | null) => {
    box.current = el;
  }, []);
  React.useLayoutEffect(() => {
    const el = box.current;
    if (!el) return;
    const measure = () => {
      const w = el.offsetWidth,
        h = el.offsetHeight;
      if (
        !w ||
        !h ||
        (ring.current && ring.current.w === w && ring.current.h === h)
      )
        return;
      ring.current = buildRing(w, h, radius);
      draw(true);
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => {
      observer.disconnect();
      cancelAnimationFrame(frame.current);
      frame.current = 0;
    };
  }, [radius, draw]);

  React.useEffect(() => {
    if (!reduced) return;
    cancelAnimationFrame(frame.current);
    frame.current = 0;
    last.current = 0;
    turn.current = { angle: 0, lean: 0, x: 0, y: 0 };
    // Reduced motion: no bending. Settle everything where it is.
    forces.current.clear();
    swell.current = 0;
    if (ring.current) {
      ring.current.u.fill(0);
      ring.current.v.fill(0);
    }
    draw(true);
    if (arrow.current) arrow.current.style.transform = "";
  }, [reduced, draw]);

  const impulse = React.useCallback(
    (x: number, y: number, base: number, peak: number, sigma: number) => {
      const g = ring.current;
      if (!g || still.current) return;
      for (let i = 0; i < g.count; i++) {
        const dx = x - g.bx[i],
          dy = y - g.by[i];
        g.v[i] +=
          base + peak * Math.exp(-(dx * dx + dy * dy) / (2 * sigma * sigma));
      }
      kick();
    },
    [kick],
  );

  return React.useMemo(
    () => ({
      attach,
      path,
      arrow,
      /** Set, move or (with null) remove one force, in the box's own coordinates. */
      set(key: string, force: MembraneForce | null) {
        if (still.current) return;
        const prev = forces.current.get(key);
        if (force)
          forces.current.set(key, {
            ...force,
            inside:
              prev?.inside ??
              (force.x > 0 &&
                force.y > 0 &&
                force.x < (ring.current?.w ?? 0) &&
                force.y < (ring.current?.h ?? 0)),
          });
        else if (prev) forces.current.delete(key);
        else return;
        kick();
      },
      /** Push the whole line out (positive) or in by a few pixels. */
      swell(px: number) {
        if (swell.current === px) return;
        swell.current = px;
        kick();
      },
      gulp(x: number, y: number) {
        impulse(x, y, -70, -230, 90);
      },
      spit(x: number, y: number) {
        impulse(x, y, 0, 320, 64);
      },
    }),
    [attach, kick, impulse],
  );
}

"use client";

import * as React from "react";
import { EASE_SETTLE, rubberBand } from "./imported-ui-interaction-motion";

export function snapRulerValue(
  value: number,
  min: number,
  max: number,
  step: number,
) {
  if (!Number.isFinite(value) || value <= min) return min;
  if (value >= max) return max;
  const snapped = min + Math.round((value - min) / step) * step;
  return Number(Math.max(min, Math.min(max, snapped)).toFixed(6));
}

type Range = [number, number];

type RangeRulerOptions = {
  value: Range;
  min: number;
  max: number;
  step: number;
  minDistance?: number;
  disabled: boolean;
  reduced: boolean;
  onChange?: (value: Range) => void;
  onCommit?: (value: Range) => void;
  format: (value: number) => string;
  formatNumber: (value: number) => string;
};

/** High-performance gesture controller for a dual-needle graduated ruler. */
export function useRangeRuler(options: RangeRulerOptions) {
  const trackRef = React.useRef<HTMLDivElement>(null);
  const lowerThumbRef = React.useRef<HTMLButtonElement>(null);
  const upperThumbRef = React.useRef<HTMLButtonElement>(null);
  const highlightRef = React.useRef<HTMLDivElement>(null);
  const lowerReadoutRef = React.useRef<HTMLSpanElement>(null);
  const upperReadoutRef = React.useRef<HTMLSpanElement>(null);
  const mergedReadoutRef = React.useRef<HTMLSpanElement>(null);

  const optionsRef = React.useRef(options);
  React.useLayoutEffect(() => {
    optionsRef.current = options;
  });

  const [activeThumb, setActiveThumb] = React.useState<
    "lower" | "upper" | null
  >(null);
  const [isMerged, setIsMerged] = React.useState(false);

  // Active drag state kept strictly in refs to prevent layout thrash and React re-renders.
  const gesture = React.useRef<{
    id: number;
    thumb: "lower" | "upper";
    startVal: Range;
    currentVal: Range;
    trackLeft: number;
    trackWidth: number;
  } | null>(null);

  const getRatio = React.useCallback((val: number) => {
    const { min, max } = optionsRef.current;
    const span = Math.max(0.00001, max - min);
    return Math.max(0, Math.min(1, (val - min) / span));
  }, []);

  const paint = React.useCallback(
    (range: Range, animate: boolean) => {
      const o = optionsRef.current;
      const [lower, upper] = range;
      const lowerRatio = getRatio(lower);
      const upperRatio = getRatio(upper);

      const lowerPct = (lowerRatio * 100).toFixed(4);
      const upperPct = (upperRatio * 100).toFixed(4);
      const spanPct = Math.max(0, (upperRatio - lowerRatio) * 100).toFixed(4);

      const transition =
        animate && !o.reduced ? `left 360ms ${EASE_SETTLE}` : "none";
      const barTransition =
        animate && !o.reduced
          ? `left 360ms ${EASE_SETTLE}, width 360ms ${EASE_SETTLE}`
          : "none";

      if (lowerThumbRef.current) {
        lowerThumbRef.current.style.transition = transition;
        lowerThumbRef.current.style.left = `${lowerPct}%`;
        lowerThumbRef.current.setAttribute("aria-valuenow", String(lower));
        lowerThumbRef.current.setAttribute("aria-valuetext", o.format(lower));
      }

      if (upperThumbRef.current) {
        upperThumbRef.current.style.transition = transition;
        upperThumbRef.current.style.left = `${upperPct}%`;
        upperThumbRef.current.setAttribute("aria-valuenow", String(upper));
        upperThumbRef.current.setAttribute("aria-valuetext", o.format(upper));
      }

      if (highlightRef.current) {
        highlightRef.current.style.transition = barTransition;
        highlightRef.current.style.left = `${lowerPct}%`;
        highlightRef.current.style.width = `${spanPct}%`;
      }

      if (lowerReadoutRef.current)
        lowerReadoutRef.current.textContent = o.formatNumber(lower);
      if (upperReadoutRef.current)
        upperReadoutRef.current.textContent = o.formatNumber(upper);
      if (mergedReadoutRef.current) {
        mergedReadoutRef.current.textContent =
          lower === upper
            ? o.formatNumber(lower)
            : `${o.formatNumber(lower)} – ${o.formatNumber(upper)}`;
      }

      const track = trackRef.current;
      const trackWidth = track ? track.offsetWidth : 400;
      const pixelGap = (upperRatio - lowerRatio) * trackWidth;
      setIsMerged(pixelGap < 48);
    },
    [getRatio],
  );

  const commit = React.useCallback(
    (next: Range, animate = true) => {
      const o = optionsRef.current;
      const dist = o.minDistance ?? 0;
      let lower = snapRulerValue(next[0], o.min, o.max - dist, o.step);
      let upper = snapRulerValue(next[1], o.min + dist, o.max, o.step);

      if (lower > upper - dist) {
        if (next[0] > o.value[0]) upper = Math.min(o.max, lower + dist);
        else lower = Math.max(o.min, upper - dist);
      }

      const clean: Range = [lower, upper];
      paint(clean, animate);
      o.onChange?.(clean);
      o.onCommit?.(clean);
    },
    [paint],
  );

  const finish = React.useCallback(
    (cancelled: boolean) => {
      const g = gesture.current;
      if (!g) return;
      gesture.current = null;
      setActiveThumb(null);

      if (cancelled) {
        paint(g.startVal, true);
        optionsRef.current.onChange?.(g.startVal);
      } else {
        commit(g.currentVal, false);
      }
    },
    [commit, paint],
  );

  React.useLayoutEffect(() => {
    if (!gesture.current) paint(options.value, true);
  }, [options.value, options.min, options.max, options.reduced, paint]);

  React.useEffect(() => {
    const handleResize = () => {
      if (!gesture.current) paint(optionsRef.current.value, false);
    };
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, [paint]);

  React.useEffect(() => {
    const interrupted = () => finish(true);
    const hidden = () => {
      if (document.hidden) interrupted();
    };
    window.addEventListener("blur", interrupted);
    document.addEventListener("visibilitychange", hidden);
    return () => {
      window.removeEventListener("blur", interrupted);
      document.removeEventListener("visibilitychange", hidden);
    };
  }, [finish]);

  React.useEffect(() => {
    if (options.disabled) finish(true);
  }, [options.disabled, finish]);

  const startDrag = React.useCallback(
    (thumb: "lower" | "upper", event: React.PointerEvent<HTMLElement>) => {
      if (event.button !== 0 || !event.isPrimary || optionsRef.current.disabled)
        return;
      const track = trackRef.current;
      if (!track) return;

      const rect = track.getBoundingClientRect();
      event.currentTarget.setPointerCapture(event.pointerId);

      const targetEl =
        thumb === "lower" ? lowerThumbRef.current : upperThumbRef.current;
      targetEl?.focus({ preventScroll: true });

      gesture.current = {
        id: event.pointerId,
        thumb,
        startVal: [...optionsRef.current.value] as Range,
        currentVal: [...optionsRef.current.value] as Range,
        trackLeft: rect.left,
        trackWidth: Math.max(1, rect.width),
      };

      setActiveThumb(thumb);
      paint(optionsRef.current.value, false);
    },
    [paint],
  );

  const onPointerMove = React.useCallback(
    (event: React.PointerEvent<HTMLElement>) => {
      const g = gesture.current;
      const o = optionsRef.current;
      if (!g || g.id !== event.pointerId) return;

      const clientX = event.clientX;
      const rawFraction = (clientX - g.trackLeft) / g.trackWidth;
      let fraction = rawFraction;
      if (rawFraction < 0) {
        fraction =
          -rubberBand(-rawFraction * g.trackWidth, g.trackWidth, 0.4) /
          g.trackWidth;
      } else if (rawFraction > 1) {
        fraction =
          1 +
          rubberBand((rawFraction - 1) * g.trackWidth, g.trackWidth, 0.4) /
            g.trackWidth;
      }
      const targetVal = snapRulerValue(
        o.min + Math.max(0, Math.min(1, fraction)) * (o.max - o.min),
        o.min,
        o.max,
        o.step,
      );
      const dist = o.minDistance ?? 0;

      let [lower, upper] = g.currentVal;

      if (g.thumb === "lower") {
        lower = Math.min(o.max - dist, targetVal);
        // Repulsion: lower pushes upper forward
        if (lower > upper - dist) {
          upper = Math.min(o.max, lower + dist);
        }
      } else {
        upper = Math.max(o.min + dist, targetVal);
        // Repulsion: upper pushes lower backward
        if (upper < lower + dist) {
          lower = Math.max(o.min, upper - dist);
        }
      }

      if (lower === g.currentVal[0] && upper === g.currentVal[1]) return;

      g.currentVal = [lower, upper];
      paint([lower, upper], false);
      o.onChange?.([lower, upper]);
    },
    [paint],
  );

  const onTrackPointerDown = React.useCallback(
    (event: React.PointerEvent<HTMLDivElement>) => {
      if (event.button !== 0 || !event.isPrimary || optionsRef.current.disabled)
        return;
      // If clicking directly on a thumb button, let the thumb handler handle it
      if ((event.target as HTMLElement).closest("button")) return;

      const track = trackRef.current;
      if (!track) return;
      const rect = track.getBoundingClientRect();
      const fraction = Math.max(
        0,
        Math.min(1, (event.clientX - rect.left) / Math.max(1, rect.width)),
      );
      const clickVal =
        optionsRef.current.min +
        fraction * (optionsRef.current.max - optionsRef.current.min);

      const [lower, upper] = optionsRef.current.value;
      const closer: "lower" | "upper" =
        Math.abs(clickVal - lower) <= Math.abs(clickVal - upper)
          ? "lower"
          : "upper";

      startDrag(closer, event);
      // Immediately process movement to click position
      const targetVal = snapRulerValue(
        clickVal,
        optionsRef.current.min,
        optionsRef.current.max,
        optionsRef.current.step,
      );
      const dist = optionsRef.current.minDistance ?? 0;
      let nextLower = lower;
      let nextUpper = upper;

      if (closer === "lower") {
        nextLower = Math.min(optionsRef.current.max - dist, targetVal);
        if (nextLower > nextUpper - dist)
          nextUpper = Math.min(optionsRef.current.max, nextLower + dist);
      } else {
        nextUpper = Math.max(optionsRef.current.min + dist, targetVal);
        if (nextUpper < nextLower + dist)
          nextLower = Math.max(optionsRef.current.min, nextUpper - dist);
      }

      if (gesture.current) {
        gesture.current.currentVal = [nextLower, nextUpper];
        paint([nextLower, nextUpper], false);
        optionsRef.current.onChange?.([nextLower, nextUpper]);
      }
    },
    [startDrag, paint],
  );

  const makeKeyHandler = React.useCallback(
    (thumb: "lower" | "upper") =>
      (event: React.KeyboardEvent<HTMLButtonElement>) => {
        if (event.key === "Escape") {
          event.preventDefault();
          finish(true);
          return;
        }

        const o = optionsRef.current;
        if (
          ![
            "ArrowLeft",
            "ArrowRight",
            "ArrowUp",
            "ArrowDown",
            "PageUp",
            "PageDown",
            "Home",
            "End",
          ].includes(event.key)
        )
          return;

        event.preventDefault();
        const isUp = ["ArrowRight", "ArrowUp", "PageUp"].includes(event.key);
        const mult = event.key.startsWith("Page") || event.shiftKey ? 10 : 1;
        const delta = o.step * mult * (isUp ? 1 : -1);
        const dist = o.minDistance ?? 0;

        let [lower, upper] = o.value;

        if (thumb === "lower") {
          if (event.key === "Home") lower = o.min;
          else if (event.key === "End") lower = upper - dist;
          else lower = Math.max(o.min, Math.min(o.max - dist, lower + delta));

          if (lower > upper - dist) upper = Math.min(o.max, lower + dist);
        } else {
          if (event.key === "Home") upper = lower + dist;
          else if (event.key === "End") upper = o.max;
          else upper = Math.max(o.min + dist, Math.min(o.max, upper + delta));

          if (upper < lower + dist) lower = Math.max(o.min, upper - dist);
        }

        commit([lower, upper]);
      },
    [commit, finish],
  );

  const attachTrack = React.useCallback((el: HTMLDivElement | null) => {
    trackRef.current = el;
  }, []);
  const attachLowerThumb = React.useCallback((el: HTMLButtonElement | null) => {
    lowerThumbRef.current = el;
  }, []);
  const attachUpperThumb = React.useCallback((el: HTMLButtonElement | null) => {
    upperThumbRef.current = el;
  }, []);
  const attachHighlight = React.useCallback((el: HTMLDivElement | null) => {
    highlightRef.current = el;
  }, []);
  const attachLowerReadout = React.useCallback((el: HTMLSpanElement | null) => {
    lowerReadoutRef.current = el;
  }, []);
  const attachUpperReadout = React.useCallback((el: HTMLSpanElement | null) => {
    upperReadoutRef.current = el;
  }, []);
  const attachMergedReadout = React.useCallback(
    (el: HTMLSpanElement | null) => {
      mergedReadoutRef.current = el;
    },
    [],
  );

  const onPointerUpTrack = React.useCallback(
    (e: React.PointerEvent<HTMLDivElement>) => {
      if (e.pointerId === gesture.current?.id) finish(false);
    },
    [finish],
  );
  const onPointerCancelTrack = React.useCallback(
    (e: React.PointerEvent<HTMLDivElement>) => {
      if (e.pointerId === gesture.current?.id) finish(true);
    },
    [finish],
  );
  const onPointerDownLower = React.useCallback(
    (e: React.PointerEvent<HTMLButtonElement>) => startDrag("lower", e),
    [startDrag],
  );
  const onPointerUpLower = React.useCallback(
    (e: React.PointerEvent<HTMLButtonElement>) => {
      if (e.pointerId === gesture.current?.id) finish(false);
    },
    [finish],
  );
  const onPointerCancelLower = React.useCallback(
    (e: React.PointerEvent<HTMLButtonElement>) => {
      if (e.pointerId === gesture.current?.id) finish(true);
    },
    [finish],
  );
  const onLostPointerCaptureLower = React.useCallback(
    (e: React.PointerEvent<HTMLButtonElement>) => {
      if (e.pointerId === gesture.current?.id) finish(true);
    },
    [finish],
  );
  const onBlur = React.useCallback(() => finish(true), [finish]);
  const onKeyDownLower = React.useMemo(
    () => makeKeyHandler("lower"),
    [makeKeyHandler],
  );

  const onPointerDownUpper = React.useCallback(
    (e: React.PointerEvent<HTMLButtonElement>) => startDrag("upper", e),
    [startDrag],
  );
  const onPointerUpUpper = React.useCallback(
    (e: React.PointerEvent<HTMLButtonElement>) => {
      if (e.pointerId === gesture.current?.id) finish(false);
    },
    [finish],
  );
  const onPointerCancelUpper = React.useCallback(
    (e: React.PointerEvent<HTMLButtonElement>) => {
      if (e.pointerId === gesture.current?.id) finish(true);
    },
    [finish],
  );
  const onLostPointerCaptureUpper = React.useCallback(
    (e: React.PointerEvent<HTMLButtonElement>) => {
      if (e.pointerId === gesture.current?.id) finish(true);
    },
    [finish],
  );
  const onKeyDownUpper = React.useMemo(
    () => makeKeyHandler("upper"),
    [makeKeyHandler],
  );

  const trackHandlers = React.useMemo(
    () => ({
      onPointerDown: onTrackPointerDown,
      onPointerMove,
      onPointerUp: onPointerUpTrack,
      onPointerCancel: onPointerCancelTrack,
    }),
    [onTrackPointerDown, onPointerMove, onPointerUpTrack, onPointerCancelTrack],
  );

  const lowerHandlers = React.useMemo(
    () => ({
      onPointerDown: onPointerDownLower,
      onPointerMove,
      onPointerUp: onPointerUpLower,
      onPointerCancel: onPointerCancelLower,
      onLostPointerCapture: onLostPointerCaptureLower,
      onBlur,
      onKeyDown: onKeyDownLower,
    }),
    [
      onPointerDownLower,
      onPointerMove,
      onPointerUpLower,
      onPointerCancelLower,
      onLostPointerCaptureLower,
      onBlur,
      onKeyDownLower,
    ],
  );

  const upperHandlers = React.useMemo(
    () => ({
      onPointerDown: onPointerDownUpper,
      onPointerMove,
      onPointerUp: onPointerUpUpper,
      onPointerCancel: onPointerCancelUpper,
      onLostPointerCapture: onLostPointerCaptureUpper,
      onBlur,
      onKeyDown: onKeyDownUpper,
    }),
    [
      onPointerDownUpper,
      onPointerMove,
      onPointerUpUpper,
      onPointerCancelUpper,
      onLostPointerCaptureUpper,
      onBlur,
      onKeyDownUpper,
    ],
  );

  return {
    attachTrack,
    attachLowerThumb,
    attachUpperThumb,
    attachHighlight,
    attachLowerReadout,
    attachUpperReadout,
    attachMergedReadout,
    activeThumb,
    isMerged,
    commit,
    trackHandlers,
    lowerHandlers,
    upperHandlers,
  };
}

"use client";

import * as React from "react";
import { EASE_OUT } from "./imported-ui-interaction-motion";

export interface RatioSegment {
  id: string;
  label: string;
  ratio: number;
  color?: string;
}

type Options = {
  segments: RatioSegment[];
  minRatio?: number;
  disabled: boolean;
  reduced: boolean;
  onChange?: (ratios: number[]) => void;
  onCommit?: (ratios: number[]) => void;
};

/** Normalizes ratios to sum cleanly to 100. */
export function normalizeRatios(values: number[]): number[] {
  const sum = values.reduce((a, b) => a + b, 0);
  if (sum === 0) {
    const even = 100 / values.length;
    return values.map(() => Math.round(even));
  }
  let acc = 0;
  const result = values.map((v, i) => {
    if (i === values.length - 1) return Math.max(0, 100 - acc);
    const rounded = Math.round((v / sum) * 100);
    acc += rounded;
    return rounded;
  });
  return result;
}

export function useRatioBalancer(options: Options) {
  const trackRef = React.useRef<HTMLDivElement>(null);
  const segmentRefs = React.useRef<(HTMLDivElement | null)[]>([]);
  const readoutRefs = React.useRef<(HTMLSpanElement | null)[]>([]);
  const dividerRefs = React.useRef<(HTMLButtonElement | null)[]>([]);

  const optionsRef = React.useRef(options);
  React.useLayoutEffect(() => {
    optionsRef.current = options;
  });

  const [activeDivider, setActiveDivider] = React.useState<number | null>(null);

  const gesture = React.useRef<{
    id: number;
    dividerIndex: number;
    startX: number;
    startRatios: number[];
    startRatioLeft: number;
    startRatioRight: number;
    currentRatios: number[];
    trackWidth: number;
  } | null>(null);

  const paint = React.useCallback((ratios: number[], animate: boolean) => {
    const o = optionsRef.current;
    ratios.forEach((ratio, i) => {
      const seg = segmentRefs.current[i];
      if (seg) {
        seg.style.transition =
          animate && !o.reduced ? `flex-grow 360ms ${EASE_OUT}` : "none";
        seg.style.flexGrow = String(ratio);
      }
      const readout = readoutRefs.current[i];
      if (readout) {
        readout.textContent = `${Math.round(ratio)}%`;
      }
    });

    // Update divider aria attributes
    let accumulated = 0;
    ratios.slice(0, -1).forEach((ratio, i) => {
      accumulated += ratio;
      const div = dividerRefs.current[i];
      if (div) {
        div.setAttribute("aria-valuenow", String(Math.round(accumulated)));
      }
    });
  }, []);

  const commit = React.useCallback(
    (next: number[], animate = true) => {
      const clean = normalizeRatios(next);
      paint(clean, animate);
      optionsRef.current.onChange?.(clean);
      optionsRef.current.onCommit?.(clean);
    },
    [paint],
  );

  const finish = React.useCallback(
    (cancelled: boolean) => {
      const g = gesture.current;
      if (!g) return;
      gesture.current = null;
      setActiveDivider(null);

      if (cancelled) {
        paint(g.startRatios, true);
        optionsRef.current.onChange?.(g.startRatios);
      } else {
        commit(g.currentRatios, false);
      }
    },
    [commit, paint],
  );

  React.useLayoutEffect(() => {
    if (!gesture.current) {
      const currentRatios = options.segments.map((s) => s.ratio);
      paint(currentRatios, true);
    }
  }, [options.segments, options.reduced, paint]);

  React.useEffect(() => {
    const interrupted = () => finish(true);
    const hidden = () => {
      if (document.hidden) interrupted();
    };
    window.addEventListener("blur", interrupted);
    document.addEventListener("visibilitychange", hidden);
    return () => {
      window.removeEventListener("blur", interrupted);
      document.removeEventListener("visibilitychange", hidden);
    };
  }, [finish]);

  const startDrag = React.useCallback(
    (dividerIndex: number, event: React.PointerEvent<HTMLButtonElement>) => {
      if (event.button !== 0 || !event.isPrimary || optionsRef.current.disabled)
        return;
      const track = trackRef.current;
      if (!track) return;

      const rect = track.getBoundingClientRect();
      event.currentTarget.setPointerCapture(event.pointerId);
      event.currentTarget.focus({ preventScroll: true });

      const currentRatios = optionsRef.current.segments.map((s) => s.ratio);

      gesture.current = {
        id: event.pointerId,
        dividerIndex,
        startX: event.clientX,
        startRatios: [...currentRatios],
        startRatioLeft: currentRatios[dividerIndex] ?? 50,
        startRatioRight: currentRatios[dividerIndex + 1] ?? 50,
        currentRatios: [...currentRatios],
        trackWidth: Math.max(1, rect.width),
      };

      setActiveDivider(dividerIndex);
      paint(currentRatios, false);
    },
    [paint],
  );

  const onPointerMove = React.useCallback(
    (event: React.PointerEvent<HTMLButtonElement>) => {
      const g = gesture.current;
      const o = optionsRef.current;
      if (!g || g.id !== event.pointerId) return;

      const idx = g.dividerIndex;
      const minRatio = o.minRatio ?? 5;

      // Delta-based calculation guarantees zero initial jump and 1:1 physical tracking
      const deltaX = event.clientX - g.startX;
      const deltaPercent = (deltaX / g.trackWidth) * 100;
      const pairTotal = g.startRatioLeft + g.startRatioRight;

      let newLeft = Math.round(g.startRatioLeft + deltaPercent);
      newLeft = Math.max(minRatio, Math.min(pairTotal - minRatio, newLeft));
      const newRight = pairTotal - newLeft;

      const next = [...g.currentRatios];
      next[idx] = newLeft;
      next[idx + 1] = newRight;

      if (
        next[idx] === g.currentRatios[idx] &&
        next[idx + 1] === g.currentRatios[idx + 1]
      )
        return;

      g.currentRatios = next;
      paint(next, false);
      o.onChange?.(next);
    },
    [paint],
  );

  const makeKeyHandler = React.useCallback(
    (dividerIndex: number) =>
      (event: React.KeyboardEvent<HTMLButtonElement>) => {
        if (event.key === "Escape") {
          event.preventDefault();
          finish(true);
          return;
        }

        if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key))
          return;
        event.preventDefault();

        const o = optionsRef.current;
        const delta =
          (event.shiftKey ? 5 : 1) * (event.key === "ArrowRight" ? 1 : -1);
        const minRatio = o.minRatio ?? 5;
        const segs = o.segments;

        const ratios = segs.map((s) => s.ratio);
        const combined = ratios[dividerIndex] + ratios[dividerIndex + 1];

        let newLeft = ratios[dividerIndex] + delta;
        newLeft = Math.max(minRatio, Math.min(combined - minRatio, newLeft));

        const next = [...ratios];
        next[dividerIndex] = newLeft;
        next[dividerIndex + 1] = combined - newLeft;

        commit(next);
      },
    [commit, finish],
  );

  const attachTrack = React.useCallback((el: HTMLDivElement | null) => {
    trackRef.current = el;
  }, []);
  const attachSegment = React.useCallback(
    (i: number, el: HTMLDivElement | null) => {
      segmentRefs.current[i] = el;
    },
    [],
  );
  const attachReadout = React.useCallback(
    (i: number, el: HTMLSpanElement | null) => {
      readoutRefs.current[i] = el;
    },
    [],
  );
  const attachDivider = React.useCallback(
    (i: number, el: HTMLButtonElement | null) => {
      dividerRefs.current[i] = el;
    },
    [],
  );

  const getDividerProps = React.useCallback(
    (idx: number) => ({
      onPointerDown: (e: React.PointerEvent<HTMLButtonElement>) =>
        startDrag(idx, e),
      onPointerMove,
      onPointerUp: (e: React.PointerEvent<HTMLButtonElement>) => {
        if (e.pointerId === gesture.current?.id) finish(false);
      },
      onPointerCancel: (e: React.PointerEvent<HTMLButtonElement>) => {
        if (e.pointerId === gesture.current?.id) finish(true);
      },
      onLostPointerCapture: (e: React.PointerEvent<HTMLButtonElement>) => {
        if (e.pointerId === gesture.current?.id) finish(true);
      },
      onBlur: () => finish(true),
      onKeyDown: makeKeyHandler(idx),
    }),
    [startDrag, onPointerMove, finish, makeKeyHandler],
  );

  return {
    attachTrack,
    attachSegment,
    attachReadout,
    attachDivider,
    activeDivider,
    commit,
    getDividerProps,
  };
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * ROW MOTION: rows that keep their place on screen
 *
 *   glide     after any render (a sort, a filter, new data from
 *             the server) every row that moved glides from its
 *             old place to its new one. Glides are additive, so
 *             a change that lands mid-glide adds its own offset
 *             instead of restarting anything
 *   travel    a row that sorts onto the page slides in from the
 *             side where it ranked before; one that sorts off
 *             slides out toward its new rank
 *   enter     a row that's new to the list fades in where it
 *             lands while the rows below glide clear of it
 *   leave     a row that's gone folds away where it stood. Its
 *             copy is the row's own element, detached by React
 *             and moved into a layer React never renders into,
 *             so a leaving row costs no render at all
 *   stagger   a sort can ask for the rows to set off one after
 *             another, top first
 *
 * Positions are layout offsets (transforms ignored), kept after
 * every render and whenever the list changes size (a row
 * opening its detail), so they're never stale. Rows are found
 * by data-row-id; ranks are their places in the whole sorted
 * list, not just the page.
 * ───────────────────────────────────────────────────────── */

type Seen = { top: number; height: number; el: HTMLElement };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const GLIDE = 480;

export function useRowMotion(
  container: React.RefObject<HTMLElement | null>,
  {
    reduced,
    resetKey,
    ranks,
    ghosts,
  }: {
    reduced: boolean;
    resetKey?: string | number;
    ranks: ReadonlyMap<string, number>;
    ghosts: React.RefObject<HTMLElement | null>;
  },
) {
  const seen = React.useRef(new Map<string, Seen>());
  const lastRanks = React.useRef(ranks);
  const lastKey = React.useRef(resetKey);
  const staggerNext = React.useRef(false);

  const read = React.useCallback(() => {
    const out = new Map<string, Seen>();
    container.current
      ?.querySelectorAll<HTMLElement>("[data-row-id]")
      .forEach((el) =>
        out.set(el.dataset.rowId!, {
          top: el.offsetTop,
          height: el.offsetHeight,
          el,
        }),
      );
    return out;
  }, [container]);

  /** The row React just removed, back on screen where it stood, leaving: sliding toward where it went, or folding. */
  const leave = (was: Seen, dy: number) => {
    const layer = ghosts.current;
    const el = was.el;
    if (!layer || el.isConnected) return;
    // No getAnimations() here (it flushes style for the whole page): the exit below is added last and replaces any
    // glide still on the element.
    el.removeAttribute("data-row-id");
    el.removeAttribute("tabindex");
    el.setAttribute("aria-hidden", "true");
    el.inert = true;
    Object.assign(el.style, {
      position: "absolute",
      left: "0",
      right: "0",
      top: `${was.top}px`,
      height: `${was.height}px`,
      margin: "0",
      overflow: "hidden",
    });
    layer.appendChild(el);
    const a = el.animate(
      dy
        ? [
            { transform: "translateY(0px)", opacity: 1, filter: "blur(0px)" },
            {
              transform: `translateY(${dy}px)`,
              opacity: 0,
              filter: "blur(3px)",
            },
          ]
        : [
            { opacity: 1, transform: "none", filter: "blur(0px)" },
            { opacity: 0, transform: "scale(0.985)", filter: "blur(4px)" },
          ],
      { duration: dy ? 360 : 280, easing: EASE, fill: "forwards" },
    );
    a.onfinish = a.oncancel = () => el.remove();
  };

  React.useLayoutEffect(() => {
    const el = container.current;
    if (!el) return;
    const before = seen.current;
    const after = read();
    const prevRanks = lastRanks.current;
    seen.current = after;
    lastRanks.current = ranks;
    const stagger = staggerNext.current;
    staggerNext.current = false;
    if (lastKey.current !== resetKey) {
      // A different page: the caller slides the whole body; nothing glides and nothing folds.
      lastKey.current = resetKey;
      return;
    }
    if (reduced || !before.size) return;

    // A typical row's height. Rows that come onto or leave the page only hint at the way they went (a row and a
    // quarter at most), so the list never shows holes while they travel.
    const heights = [...after.values()]
      .map((b) => b.height)
      .sort((a, b) => a - b);
    const rowH = heights[Math.floor(heights.length / 2)] ?? 48;
    const clamp = (dy: number) =>
      Math.max(-rowH * 1.25, Math.min(rowH * 1.25, dy));

    let order = 0;
    after.forEach((now, id) => {
      const row = now.el;
      const was = before.get(id);
      const delay = stagger ? Math.min(order++ * 16, 200) : 0;
      if (was) {
        const dy = was.top - now.top;
        if (Math.abs(dy) < 0.5) return;
        row.animate(
          [
            { transform: `translateY(${dy}px)`, zIndex: 1 },
            { transform: "translateY(0px)", zIndex: 1 },
          ],
          {
            duration: GLIDE,
            delay,
            easing: EASE,
            composite: "add",
            fill: "backwards",
          },
        );
        return;
      }
      const from = prevRanks.get(id);
      const to = ranks.get(id);
      if (from !== undefined && to !== undefined) {
        // It ranked somewhere off the page: it comes in from that side.
        row.animate(
          [
            {
              transform: `translateY(${clamp((from - to) * rowH)}px)`,
              opacity: 0,
              filter: "blur(3px)",
            },
            { transform: "translateY(0px)", opacity: 1, filter: "blur(0px)" },
          ],
          {
            duration: GLIDE,
            delay: delay / 2,
            easing: EASE,
            fill: "backwards",
          },
        );
        return;
      }
      row.animate(
        [
          { opacity: 0, filter: "blur(4px)" },
          { opacity: 1, filter: "blur(0px)" },
        ],
        { duration: 420, delay: 90, easing: EASE, fill: "backwards" },
      );
    });

    // Still in the list, just not on this page: its copy slides toward where it went. Gone for good: it folds.
    before.forEach((was, id) => {
      if (after.has(id)) return;
      const from = prevRanks.get(id);
      const to = ranks.get(id);
      leave(
        was,
        from !== undefined && to !== undefined
          ? clamp((to - from) * rowH) || rowH
          : 0,
      );
    });
  });

  // The list changed size without a render of ours (a detail opening by transition): keep the positions true.
  React.useEffect(() => {
    const el = container.current;
    if (!el) return;
    const observer = new ResizeObserver(() => {
      seen.current = read();
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, [container, read]);

  return {
    /** The next change (a sort) sets the rows off one after another. */
    stagger: () => {
      staggerNext.current = true;
    },
  };
}

"use client";

import * as React from "react";
import {
  EASE_OUT,
  rubberBand,
  springFrames,
} from "./imported-ui-interaction-motion";

type Orientation = "horizontal" | "vertical";

type SplitPaneOptions = {
  orientation?: Orientation;
  split?: number; // 0 to 100
  defaultSplit?: number;
  minSize?: number; // default 15
  maxSize?: number; // default 85
  disabled?: boolean;
  reduced?: boolean;
  onChange?: (split: number) => void;
  onCommit?: (split: number) => void;
};

export function useSplitPane(options: SplitPaneOptions) {
  const containerRef = React.useRef<HTMLDivElement>(null);
  const firstPaneRef = React.useRef<HTMLDivElement>(null);
  const dividerRef = React.useRef<HTMLButtonElement>(null);

  const optionsRef = React.useRef(options);
  React.useLayoutEffect(() => {
    optionsRef.current = options;
  });

  const [dragging, setDragging] = React.useState(false);
  const [collapsed, setCollapsed] = React.useState<"first" | "second" | null>(
    null,
  );

  const gesture = React.useRef<{
    id: number;
    startSplit: number;
    currentSplit: number;
    containerSize: number;
    containerStart: number;
  } | null>(null);

  const min = options.minSize ?? 15;
  const max = options.maxSize ?? 85;

  const paint = React.useCallback((splitPercent: number, animate: boolean) => {
    const o = optionsRef.current;
    const pane = firstPaneRef.current;
    if (pane) {
      pane.style.transition =
        animate && !o.reduced ? `flex-basis 380ms ${EASE_OUT}` : "none";
      pane.style.flexBasis = `${splitPercent}%`;
    }
    dividerRef.current?.setAttribute(
      "aria-valuenow",
      String(Math.round(splitPercent)),
    );
  }, []);

  const commit = React.useCallback(
    (splitPercent: number, animate = true) => {
      const clean = Math.max(min, Math.min(max, splitPercent));
      paint(clean, animate);
      setCollapsed(null);
      optionsRef.current.onChange?.(clean);
      optionsRef.current.onCommit?.(clean);
    },
    [min, max, paint],
  );

  const collapse = React.useCallback(
    (side: "first" | "second") => {
      const pane = firstPaneRef.current;
      if (!pane) return;
      setCollapsed(side);
      const targetPercent = side === "first" ? 0 : 100;
      paint(targetPercent, true);
      optionsRef.current.onChange?.(targetPercent);
      optionsRef.current.onCommit?.(targetPercent);
    },
    [paint],
  );

  const expand = React.useCallback(() => {
    setCollapsed(null);
    commit(optionsRef.current.defaultSplit ?? 50, true);
  }, [commit]);

  const snapCycle = React.useCallback(() => {
    const o = optionsRef.current;
    const current = o.split ?? o.defaultSplit ?? 50;
    let next = 50;
    if (Math.abs(current - 50) < 3) next = 25;
    else if (Math.abs(current - 25) < 3) next = 75;
    else next = 50;
    commit(next, true);
  }, [commit]);

  const finish = React.useCallback(
    (cancelled: boolean) => {
      const g = gesture.current;
      if (!g) return;
      gesture.current = null;
      setDragging(false);

      if (cancelled) {
        paint(g.startSplit, true);
        optionsRef.current.onChange?.(g.startSplit);
      } else {
        // If release was in rubber-band territory beyond min or max, spring back smoothly
        const o = optionsRef.current;
        const current = g.currentSplit;
        if (current < min || current > max) {
          const target = current < min ? min : max;
          const pane = firstPaneRef.current;
          if (pane && !o.reduced) {
            const frames = springFrames(current, target, 0, 480);
            const keyframes = frames.map((f) => ({ flexBasis: `${f.value}%` }));
            const anim = pane.animate(keyframes, {
              duration: 480,
              fill: "forwards",
            });
            anim.onfinish = () => {
              pane.style.flexBasis = `${target}%`;
              anim.cancel();
              commit(target, false);
            };
          } else {
            commit(target, false);
          }
        } else {
          commit(g.currentSplit, false);
        }
      }
    },
    [min, max, commit, paint],
  );

  React.useLayoutEffect(() => {
    if (!gesture.current && collapsed === null) {
      const val = options.split ?? options.defaultSplit ?? 50;
      paint(val, true);
    }
  }, [options.split, options.defaultSplit, options.reduced, collapsed, paint]);

  const startDrag = React.useCallback(
    (event: React.PointerEvent<HTMLButtonElement>) => {
      if (event.button !== 0 || !event.isPrimary || optionsRef.current.disabled)
        return;
      const container = containerRef.current;
      if (!container) return;

      const rect = container.getBoundingClientRect();
      const isHorizontal = optionsRef.current.orientation !== "vertical";
      const containerSize = isHorizontal ? rect.width : rect.height;
      const containerStart = isHorizontal ? rect.left : rect.top;

      event.currentTarget.setPointerCapture(event.pointerId);
      event.currentTarget.focus({ preventScroll: true });

      const currentSplit =
        optionsRef.current.split ?? optionsRef.current.defaultSplit ?? 50;

      gesture.current = {
        id: event.pointerId,
        startSplit: currentSplit,
        currentSplit,
        containerSize: Math.max(1, containerSize),
        containerStart,
      };

      setDragging(true);
      setCollapsed(null);
      paint(currentSplit, false);
    },
    [paint],
  );

  const onPointerMove = React.useCallback(
    (event: React.PointerEvent<HTMLButtonElement>) => {
      const g = gesture.current;
      const o = optionsRef.current;
      if (!g || g.id !== event.pointerId) return;

      const isHorizontal = o.orientation !== "vertical";
      const clientPos = isHorizontal ? event.clientX : event.clientY;
      const rawPercent =
        ((clientPos - g.containerStart) / g.containerSize) * 100;

      // Rubber-band resistance curve beyond min/max limits
      let dampedPercent = rawPercent;
      if (rawPercent < min) {
        const overflow = min - rawPercent;
        dampedPercent = min - rubberBand(overflow, 25, 0.4);
      } else if (rawPercent > max) {
        const overflow = rawPercent - max;
        dampedPercent = max + rubberBand(overflow, 25, 0.4);
      }

      g.currentSplit = dampedPercent;
      paint(dampedPercent, false);
      o.onChange?.(dampedPercent);
    },
    [min, max, paint],
  );

  const onKeyDown = React.useCallback(
    (event: React.KeyboardEvent<HTMLButtonElement>) => {
      if (event.key === "Escape") {
        event.preventDefault();
        finish(true);
        return;
      }

      const isHorizontal = optionsRef.current.orientation !== "vertical";
      const prevKey = isHorizontal ? "ArrowLeft" : "ArrowUp";
      const nextKey = isHorizontal ? "ArrowRight" : "ArrowDown";

      if (![prevKey, nextKey, "Home", "End", "Enter"].includes(event.key))
        return;
      event.preventDefault();

      if (event.key === "Enter") {
        snapCycle();
        return;
      }

      const current =
        optionsRef.current.split ?? optionsRef.current.defaultSplit ?? 50;
      if (event.key === "Home") {
        commit(min);
        return;
      }
      if (event.key === "End") {
        commit(max);
        return;
      }

      const mult = event.shiftKey ? 10 : 1;
      const delta = (event.key === nextKey ? 1 : -1) * mult;
      commit(current + delta);
    },
    [min, max, snapCycle, commit, finish],
  );

  const attachContainer = React.useCallback((el: HTMLDivElement | null) => {
    containerRef.current = el;
  }, []);
  const attachFirstPane = React.useCallback((el: HTMLDivElement | null) => {
    firstPaneRef.current = el;
  }, []);
  const attachDivider = React.useCallback((el: HTMLButtonElement | null) => {
    dividerRef.current = el;
  }, []);

  const onPointerUp = React.useCallback(
    (e: React.PointerEvent<HTMLButtonElement>) => {
      if (e.pointerId === gesture.current?.id) finish(false);
    },
    [finish],
  );
  const onPointerCancel = React.useCallback(
    (e: React.PointerEvent<HTMLButtonElement>) => {
      if (e.pointerId === gesture.current?.id) finish(true);
    },
    [finish],
  );
  const onLostPointerCapture = React.useCallback(
    (e: React.PointerEvent<HTMLButtonElement>) => {
      if (e.pointerId === gesture.current?.id) finish(true);
    },
    [finish],
  );
  const onBlur = React.useCallback(() => finish(true), [finish]);

  const dividerProps = React.useMemo(
    () => ({
      onPointerDown: startDrag,
      onPointerMove,
      onPointerUp,
      onPointerCancel,
      onLostPointerCapture,
      onDoubleClick: snapCycle,
      onBlur,
      onKeyDown,
    }),
    [
      startDrag,
      onPointerMove,
      onPointerUp,
      onPointerCancel,
      onLostPointerCapture,
      snapCycle,
      onBlur,
      onKeyDown,
    ],
  );

  return {
    attachContainer,
    attachFirstPane,
    attachDivider,
    dragging,
    collapsed,
    collapse,
    expand,
    snapCycle,
    dividerProps,
  };
}

"use client";

import * as React from "react";
import {
  projectInertia,
  rubberBand,
  softenVelocity,
} from "./imported-ui-interaction-motion";

/*
 * The swipe row's engine. The row's face slides over two sets of action cells, one under each
 * edge. Every cell is a full-height layer moved by transform only: as the face slides, the cells
 * share the space it uncovers equally, so each one grows with the finger, and their icons scale in
 * once there is room. Past most of the row the first action arms: it takes the whole space, its
 * icon rides the face's edge, and letting go there runs it.
 *
 * Drags, trackpad swipes and releases write transforms straight to the elements. One frame loop
 * runs the spring and the arming, and sleeps when both are still. Nothing renders through React
 * until a row opens, closes or commits.
 */

export type SwipeSide = "leading" | "trailing";

type Options = {
  leading: number;
  trailing: number;
  cellWidth: number;
  reduced: boolean;
  disabled: boolean;
  /** Released while armed: run that side's first action. */
  onFull: (side: SwipeSide) => void;
};

type Sim = {
  x: number;
  v: number;
  target: number;
  spring: "none" | "settle" | "out";
  arm: number;
  armTarget: number;
  armSide: SwipeSide;
  armIndex: number;
  armed: boolean;
  width: number;
  last: number;
  done: (() => void) | null;
  moving: boolean;
};

const clamp = (n: number, lo: number, hi: number) =>
  Math.max(lo, Math.min(hi, n));
const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
const STEP = 1 / 240;

// One open row at a time, as in a mail list: opening one closes the others.
const openRows = new Set<() => void>();

export function useSwipeRow(options: Options) {
  const opts = React.useRef(options);
  React.useLayoutEffect(() => {
    opts.current = options;
  });
  const surface = React.useRef<HTMLDivElement>(null);
  const front = React.useRef<HTMLDivElement>(null);
  const cells = React.useRef<Record<SwipeSide, (HTMLElement | null)[]>>({
    leading: [],
    trailing: [],
  });
  const faces = React.useRef<Record<SwipeSide, (HTMLElement | null)[]>>({
    leading: [],
    trailing: [],
  });
  const faceWidths = React.useRef(new WeakMap<HTMLElement, number>());
  const sim = React.useRef<Sim>({
    x: 0,
    v: 0,
    target: 0,
    spring: "none",
    arm: 0,
    armTarget: 0,
    armSide: "trailing",
    armIndex: 0,
    armed: false,
    width: 0,
    last: 0,
    done: null,
    moving: false,
  });
  const frame = React.useRef(0);
  const [open, setOpen] = React.useState<SwipeSide | null>(null);
  const openRef = React.useRef<SwipeSide | null>(null);
  const closeOthers = React.useRef<() => void>(() => {});

  const width = () => {
    const s = sim.current;
    if (!s.width) s.width = surface.current?.offsetWidth ?? 0;
    return s.width;
  };
  const count = (side: SwipeSide) =>
    side === "leading" ? opts.current.leading : opts.current.trailing;
  const rail = (side: SwipeSide) => count(side) * opts.current.cellWidth;
  const threshold = (side: SwipeSide) =>
    clamp(
      width() * 0.62,
      rail(side) + 40,
      Math.max(rail(side) + 40, width() - 32),
    );

  const paint = React.useCallback(() => {
    const s = sim.current,
      W = width(),
      A = opts.current.cellWidth;
    if (front.current)
      front.current.style.transform = `translate3d(${s.x}px,0,0)`;
    // Mark the row while it's off its rest, so hover affordances stand down until it's back.
    const moving = Math.abs(s.x) > 0.5;
    if (surface.current && moving !== s.moving) {
      s.moving = moving;
      surface.current.toggleAttribute("data-moving", moving);
    }
    for (const side of ["leading", "trailing"] as const) {
      const k = count(side);
      const reveal = side === "trailing" ? Math.max(0, -s.x) : Math.max(0, s.x);
      const slice = k ? reveal / k : 0;
      for (let i = 0; i < k; i++) {
        const cell = cells.current[side][i],
          face = faces.current[side][i];
        if (!cell) continue;
        const armed = s.armSide === side && s.armIndex === i ? s.arm : 0;
        const visible = lerp(slice, reveal, armed);
        // The cell's inner edge: where the face's edge is when this cell has taken over.
        const inner =
          side === "trailing"
            ? lerp(W - (i + 1) * slice, W - reveal, armed)
            : lerp((i + 1) * slice, reveal, armed);
        cell.style.transform = `translate3d(${side === "trailing" ? inner : inner - W}px,0,0)`;
        cell.style.zIndex = String(armed > 0.01 ? 20 : k - i);
        // Closed, a cell sits exactly on the row's edge; at a fractional scale (125% displays, scaled previews) its colour
        // would bleed through as a 1px sliver, so it's hidden until the row moves.
        cell.style.visibility = reveal > 0.5 || armed > 0.01 ? "" : "hidden";
        if (face) {
          // Measured once per face (labels don't change while it moves), so painting never reads layout.
          let fw = faceWidths.current.get(face);
          if (!fw) {
            fw = face.offsetWidth || A * 0.6;
            faceWidths.current.set(face, fw);
          }
          const centre = lerp(slice / 2, Math.min(visible / 2, A / 2), armed);
          const x = side === "trailing" ? centre - fw / 2 : W - centre - fw / 2;
          const p = clamp((visible - 18) / (A * 0.62), 0, 1);
          face.style.transform = `translate3d(${x}px,0,0) scale(${0.72 + 0.28 * p})`;
          face.style.opacity = String(p);
        }
      }
    }
  }, []);

  const tick = React.useCallback(
    function runTick(now: number) {
      frame.current = 0;
      const s = sim.current;
      const dt = s.last ? Math.min(0.05, (now - s.last) / 1000) : 1 / 60;
      s.last = now;
      let moving = false;
      if (s.spring !== "none") {
        // Opening is a little springy (it overshoots outward, showing more of the same actions). Closing and
        // leaving are critically damped, and closing never crosses zero, so the other side's cells never flash.
        const k = 520,
          c = s.spring === "out" || s.target === 0 ? 46 : 36;
        const side = Math.sign(s.x);
        for (let t = 0; t < dt - 1e-6; t += STEP) {
          const h = Math.min(STEP, dt - t);
          s.v += (-k * (s.x - s.target) - c * s.v) * h;
          s.x += s.v * h;
          if (s.target === 0 && side !== 0 && Math.sign(s.x) !== side) {
            s.x = 0;
            s.v = 0;
          }
        }
        if (Math.abs(s.x - s.target) < 0.4 && Math.abs(s.v) < 8) {
          s.x = s.target;
          s.v = 0;
          s.spring = "none";
          const done = s.done;
          s.done = null;
          done?.();
        } else moving = true;
      }
      const ka = 1 - Math.exp(-dt / 0.06);
      s.arm += (s.armTarget - s.arm) * ka;
      if (Math.abs(s.armTarget - s.arm) < 0.002) s.arm = s.armTarget;
      else moving = true;
      paint();
      if (moving) frame.current = requestAnimationFrame(runTick);
      else s.last = 0;
    },
    [paint],
  );

  const kick = React.useCallback(() => {
    if (!frame.current) frame.current = requestAnimationFrame(tick);
  }, [tick]);

  const setOpenSide = React.useCallback((side: SwipeSide | null) => {
    if (openRef.current === side) return;
    openRef.current = side;
    setOpen(side);
    if (side) {
      openRows.forEach((close) => close !== closeOthers.current && close());
      openRows.add(closeOthers.current);
    } else openRows.delete(closeOthers.current);
  }, []);

  /** Spring to a resting place: 0 (closed) or a side's rail (open). */
  const settle = React.useCallback(
    (target: number, velocity = 0) => {
      const s = sim.current;
      s.target = target;
      s.armTarget = 0;
      s.armed = false;
      setOpenSide(target < 0 ? "trailing" : target > 0 ? "leading" : null);
      if (opts.current.reduced) {
        s.x = target;
        s.v = 0;
        s.arm = 0;
        s.spring = "none";
        paint();
        return;
      }
      s.v = velocity;
      s.spring = "settle";
      kick();
    },
    [kick, paint, setOpenSide],
  );

  const close = React.useCallback(() => settle(0), [settle]);
  React.useLayoutEffect(() => {
    closeOthers.current = close;
  });

  /** One action takes the whole row and the face slides off; resolves once it's gone. */
  const commit = React.useCallback(
    (side: SwipeSide, index: number) =>
      new Promise<void>((resolve) => {
        const s = sim.current;
        s.armSide = side;
        s.armIndex = index;
        s.armTarget = 1;
        s.target = (side === "trailing" ? -1 : 1) * (width() + 2);
        setOpenSide(null);
        if (opts.current.reduced) {
          s.x = s.target;
          s.arm = 1;
          s.spring = "none";
          paint();
          resolve();
          return;
        }
        s.spring = "out";
        s.done = resolve;
        kick();
      }),
    [kick, paint, setOpenSide],
  );

  /** Bring the face back after a commit (the action failed, or it doesn't remove the row). */
  const restore = React.useCallback(() => {
    sim.current.armed = false;
    settle(0);
  }, [settle]);

  // Pointer and trackpad gestures.
  React.useEffect(() => {
    const el = surface.current;
    if (!el) return;
    const s = sim.current;
    let drag: {
      id: number;
      x: number;
      y: number;
      origin: number;
      started: boolean;
      samples: { x: number; t: number }[];
    } | null = null;
    let quiet: ReturnType<typeof setTimeout> | null = null;
    let wheelV = 0,
      wheelT = 0;
    let suppress = false;

    const follow = (raw: number) => {
      const W = width();
      const side: SwipeSide = raw < 0 ? "trailing" : "leading";
      const k = count(side);
      let x: number;
      if (!k) {
        x = Math.sign(raw) * rubberBand(Math.abs(raw), 80, 0.4);
      } else {
        const r = Math.abs(raw),
          limit = rail(side);
        x =
          Math.sign(raw) *
          (r <= limit ? r : limit + rubberBand(r - limit, W || 320));
      }
      s.x = x;
      // Arm past the threshold, disarm a little before it, so the boundary doesn't flicker.
      const reveal = Math.abs(x),
        T = k ? threshold(side) : Infinity;
      if (k && !s.armed && reveal >= T) {
        s.armed = true;
        s.armSide = side;
        s.armIndex = 0;
        s.armTarget = 1;
        try {
          if (drag && "vibrate" in navigator) navigator.vibrate(6);
        } catch {
          /* not allowed yet */
        }
      } else if (s.armed && (reveal < T - 24 || s.armSide !== side)) {
        s.armed = false;
        s.armTarget = 0;
      }
      if (s.arm !== s.armTarget) kick();
      else paint();
    };

    const release = (velocity: number) => {
      const side: SwipeSide = s.x < 0 ? "trailing" : "leading";
      const reveal = Math.abs(s.x),
        R = rail(side);
      const vPx = velocity * 1000;
      const dir = side === "trailing" ? -1 : 1;
      const outwardV = dir * vPx;
      const inwardV = -dir * vPx;

      if (s.armed && count(side)) {
        s.armed = false;
        opts.current.onFull(side);
        return;
      }

      // Projected travel based on flick velocity (120ms of inertia)
      const projected = projectInertia(reveal, outwardV / 1000, 0.12);
      const flung = count(side) && outwardV > 400 && projected > R * 0.4;
      const shouldOpen =
        count(side) &&
        inwardV < 300 &&
        (projected > R * 0.5 || (reveal > R * 0.35 && outwardV > 150));

      if (shouldOpen || flung) {
        settle(dir * R, vPx);
      } else {
        const launchV = softenVelocity(vPx, s.x, 8);
        settle(0, launchV);
      }
    };

    const down = (e: PointerEvent) => {
      suppress = false;
      if (opts.current.disabled || e.button !== 0 || !e.isPrimary) return;
      if (s.spring === "out") return;
      const W = surface.current?.offsetWidth ?? 0;
      s.width = W;
      cancelAnimationFrame(frame.current);
      frame.current = 0;
      s.spring = "none";
      s.v = 0;
      drag = {
        id: e.pointerId,
        x: e.clientX,
        y: e.clientY,
        origin: s.x,
        started: false,
        samples: [{ x: e.clientX, t: e.timeStamp }],
      };
    };
    const move = (e: PointerEvent) => {
      if (!drag || e.pointerId !== drag.id) return;
      const dx = e.clientX - drag.x,
        dy = e.clientY - drag.y;
      if (!drag.started) {
        if (Math.abs(dx) < 7 && Math.abs(dy) < 7) return;
        // Mostly vertical: it's a scroll, not a swipe.
        if (Math.abs(dy) > Math.abs(dx)) {
          drag = null;
          if (s.x !== 0 || s.arm) settle(openRef.current ? s.x : 0);
          return;
        }
        drag.started = true;
        // Compensate slop so drag originates seamlessly with zero initial jump:
        drag.x = e.clientX;
        drag.y = e.clientY;
        el.setPointerCapture(e.pointerId);
      }
      drag.samples.push({ x: e.clientX, t: e.timeStamp });
      while (drag.samples.length > 2 && e.timeStamp - drag.samples[0].t > 90)
        drag.samples.shift();
      follow(drag.origin + (e.clientX - drag.x));
    };
    const up = (e: PointerEvent) => {
      if (!drag || e.pointerId !== drag.id) return;
      const d = drag;
      drag = null;
      if (!d.started) {
        // A tap on an open row's face closes it instead of opening whatever is under it.
        if (openRef.current && front.current?.contains(e.target as Node)) {
          suppress = true;
          close();
        } else if (s.x !== 0 && !openRef.current) settle(0);
        return;
      }
      suppress = true;
      const first = d.samples[0],
        last = d.samples[d.samples.length - 1];
      const fresh = e.timeStamp - last.t < 80 && last.t > first.t;
      release(fresh ? (last.x - first.x) / (last.t - first.t) : 0);
    };
    const cancel = (e: PointerEvent) => {
      if (!drag || e.pointerId !== drag.id) return;
      drag = null;
      settle(
        openRef.current
          ? openRef.current === "trailing"
            ? -rail("trailing")
            : rail("leading")
          : 0,
      );
    };
    const click = (e: MouseEvent) => {
      if (!suppress) return;
      suppress = false;
      e.preventDefault();
      e.stopPropagation();
    };
    // Two-finger swipes on a trackpad move the row too; vertical scrolling is left to the page.
    const wheel = (e: WheelEvent) => {
      if (
        opts.current.disabled ||
        s.spring === "out" ||
        Math.abs(e.deltaX) <= Math.abs(e.deltaY)
      )
        return;
      e.preventDefault();
      if (!quiet) {
        s.width = surface.current?.offsetWidth ?? 0;
        cancelAnimationFrame(frame.current);
        frame.current = 0;
        s.spring = "none";
        s.v = 0;
      } else clearTimeout(quiet);
      const now = e.timeStamp;
      const dt = Math.max(8, now - wheelT);
      wheelV = wheelV * 0.6 + (-e.deltaX / dt) * 0.4;
      wheelT = now;
      follow(s.x - e.deltaX);
      quiet = setTimeout(() => {
        quiet = null;
        release(wheelV);
        wheelV = 0;
      }, 110);
    };
    const away = (e: PointerEvent) => {
      if (openRef.current && !el.contains(e.target as Node)) close();
    };
    const resize = new ResizeObserver(() => {
      s.width = el.offsetWidth;
      faceWidths.current = new WeakMap();
      if (openRef.current)
        s.x =
          openRef.current === "trailing" ? -rail("trailing") : rail("leading");
      paint();
    });
    resize.observe(el);
    el.addEventListener("pointerdown", down);
    el.addEventListener("pointermove", move);
    el.addEventListener("pointerup", up);
    el.addEventListener("pointercancel", cancel);
    el.addEventListener("click", click, true);
    el.addEventListener("wheel", wheel, { passive: false });
    document.addEventListener("pointerdown", away);
    paint();
    const closeMine = closeOthers.current;
    return () => {
      if (quiet) clearTimeout(quiet);
      cancelAnimationFrame(frame.current);
      frame.current = 0;
      resize.disconnect();
      openRows.delete(closeMine);
      el.removeEventListener("pointerdown", down);
      el.removeEventListener("pointermove", move);
      el.removeEventListener("pointerup", up);
      el.removeEventListener("pointercancel", cancel);
      el.removeEventListener("click", click, true);
      el.removeEventListener("wheel", wheel);
      document.removeEventListener("pointerdown", away);
    };
  }, []);

  const attachSurface = React.useCallback((el: HTMLDivElement | null) => {
    surface.current = el;
  }, []);
  const attachFront = React.useCallback((el: HTMLDivElement | null) => {
    front.current = el;
  }, []);
  const attachCell = React.useCallback(
    (side: SwipeSide, i: number, el: HTMLElement | null) => {
      cells.current[side][i] = el;
    },
    [],
  );
  const attachFace = React.useCallback(
    (side: SwipeSide, i: number, el: HTMLElement | null) => {
      faces.current[side][i] = el;
    },
    [],
  );

  return {
    surface,
    front,
    cells,
    faces,
    attachSurface,
    attachFront,
    attachCell,
    attachFace,
    open,
    close,
    commit,
    restore,
    openSide: (side: SwipeSide) =>
      settle((side === "trailing" ? -1 : 1) * rail(side)),
    remeasure: () => {
      faceWidths.current = new WeakMap();
      paint();
    },
  };
}

"use client";

import { useEffect, useRef } from "react";
import { flushSync } from "react-dom";

type Mode = "light" | "dark";
type ActiveWipe = { mode: Mode; cancel: () => void };

// A document can have only one view transition, even with several toggles.
const activeWipes = new WeakMap<Document, ActiveWipe>();
const styles = `
html[data-theme-wipe]::view-transition { pointer-events: none; }
html[data-theme-wipe]::view-transition-group(*) { animation: none; }
html[data-theme-wipe]::view-transition-old(root),
html[data-theme-wipe]::view-transition-new(root) {
  animation: none;
  mix-blend-mode: normal;
}`;

export function useThemeWipe() {
  const owned = useRef<ActiveWipe | null>(null);
  useEffect(() => () => owned.current?.cancel(), []);

  return (
    origin: HTMLElement,
    current: Mode,
    effect: "none" | "circular",
    change: (mode: Mode) => void,
    nonce?: string,
  ) => {
    const doc = origin.ownerDocument;
    const win = doc.defaultView;
    const previous = activeWipes.get(doc);
    const mode = (previous?.mode ?? current) === "dark" ? "light" : "dark";
    previous?.cancel();
    let applied = false;
    const apply = () => {
      if (applied) return;
      applied = true;
      flushSync(() => change(mode));
    };
    const reduced = win?.matchMedia("(prefers-reduced-motion: reduce)");
    if (
      effect === "none" ||
      previous ||
      !win ||
      reduced?.matches ||
      doc.visibilityState === "hidden" ||
      !doc.startViewTransition ||
      // Do not interrupt a router-owned transition on browsers exposing it.
      (doc as Document & { activeViewTransition?: ViewTransition | null })
        .activeViewTransition
    ) {
      apply();
      return;
    }

    const root = doc.documentElement;
    const bounds = origin.getBoundingClientRect();
    const x = bounds.left + bounds.width / 2;
    const y = bounds.top + bounds.height / 2;
    const radius = Math.hypot(
      Math.max(x, win.innerWidth - x),
      Math.max(y, win.innerHeight - y),
    );
    // Ship scoped transition CSS with the helper, not the app's stylesheet.
    const sheet = doc.createElement("style");
    if (nonce) sheet.nonce = nonce;
    sheet.textContent = styles;
    doc.head.append(sheet);
    if (!sheet.sheet) {
      sheet.remove();
      apply();
      return;
    }
    const oldAttribute = root.getAttribute("data-theme-wipe");
    let cancelled = false;
    let transition: ViewTransition | undefined;
    let animation: Animation | undefined;
    const cleanup = () => {
      animation?.cancel();
      sheet.remove();
      reduced?.removeEventListener("change", settle);
      win.removeEventListener("resize", settle);
      doc.removeEventListener("visibilitychange", visibility);
      if (activeWipes.get(doc) === run) {
        activeWipes.delete(doc);
        if (oldAttribute === null) root.removeAttribute("data-theme-wipe");
        else root.setAttribute("data-theme-wipe", oldAttribute);
      }
      if (owned.current === run) owned.current = null;
    };
    const run: ActiveWipe = {
      mode,
      cancel() {
        cancelled = true;
        transition?.skipTransition();
        cleanup();
      },
    };
    function settle() {
      run.cancel();
      apply();
    }
    function visibility() {
      if (doc.visibilityState === "hidden") settle();
    }
    owned.current = run;
    activeWipes.set(doc, run);
    root.setAttribute("data-theme-wipe", "");
    reduced?.addEventListener("change", settle);
    win.addEventListener("resize", settle);
    doc.addEventListener("visibilitychange", visibility);

    try {
      transition = doc.startViewTransition(() => {
        if (!cancelled) apply();
      });
      if (cancelled) transition.skipTransition();
      void transition.ready
        .then(() => {
          if (cancelled) return;
          animation = root.animate(
            {
              clipPath: [
                `circle(0px at ${x}px ${y}px)`,
                `circle(${radius}px at ${x}px ${y}px)`,
              ],
            },
            {
              duration: 620,
              easing: "cubic-bezier(0.65, 0, 0.35, 1)",
              pseudoElement: "::view-transition-new(root)",
            },
          );
        })
        .catch(() => {
          if (!cancelled) settle();
        });
      void transition.finished.then(cleanup, cleanup);
    } catch {
      settle();
    }
  };
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TIME GRID: the gestures of a calendar week
 *
 *   create    press on an empty slot and drag: a block grows
 *             from where you pressed to where you are, snapped
 *             to the step; on touch, hold for a moment first,
 *             so a swipe still scrolls
 *   move      drag an event: it keeps the spot you grabbed it
 *             by, snaps in time and jumps day to day
 *   resize    drag its top or bottom edge
 *   scroll    near the top or bottom of the scroller the grid
 *             scrolls itself, faster the closer you get
 *
 * The hook only turns pointers into snapped drafts
 * ({ day, start, end } in minutes) and reports a change of
 * step, not every move; the component lays drafts out like
 * any other event, so the overlap columns re-flow live.
 * Plus the date and overlap helpers it needs.
 * ───────────────────────────────────────────────────────── */

export type GridItem = {
  id: string;
  day: number;
  start: number;
  end: number;
  busy?: boolean;
};
export type GridDraftKind = "create" | "move" | "start" | "end";
export type GridDraft = {
  kind: GridDraftKind;
  id: string;
  day: number;
  start: number;
  end: number;
};

// ── Dates ────────────────────────────────────────────────
export const startOfDay = (d: Date) =>
  new Date(d.getFullYear(), d.getMonth(), d.getDate());
export const addDays = (d: Date, n: number) =>
  new Date(d.getFullYear(), d.getMonth(), d.getDate() + n);
export const startOfWeek = (d: Date, weekStartsOn: number) => {
  const day = startOfDay(d);
  return addDays(day, -((day.getDay() - weekStartsOn + 7) % 7));
};
export const sameDay = (a: Date, b: Date) =>
  a.getFullYear() === b.getFullYear() &&
  a.getMonth() === b.getMonth() &&
  a.getDate() === b.getDate();
export const minutesOf = (d: Date) => d.getHours() * 60 + d.getMinutes();
export const atMinutes = (day: Date, minutes: number) =>
  new Date(day.getFullYear(), day.getMonth(), day.getDate(), 0, minutes);

// ── Overlaps ─────────────────────────────────────────────
/**
 * Side-by-side columns for one day: items that overlap (directly or through a chain) form a cluster, each takes the
 * first column that's free when it starts, and the whole cluster shares the cluster's column count.
 */
export function layoutDay(items: { id: string; start: number; end: number }[]) {
  const out = new Map<string, { col: number; cols: number }>();
  const sorted = [...items].sort((a, b) => a.start - b.start || b.end - a.end);
  let cluster: string[] = [];
  let ends: number[] = [];
  let clusterEnd = -Infinity;
  const flush = () => {
    for (const id of cluster) out.get(id)!.cols = ends.length;
    cluster = [];
    ends = [];
  };
  for (const it of sorted) {
    if (it.start >= clusterEnd && cluster.length) flush();
    let col = ends.findIndex((end) => end <= it.start);
    if (col === -1) {
      col = ends.length;
      ends.push(it.end);
    } else ends[col] = it.end;
    out.set(it.id, { col, cols: 1 });
    cluster.push(it.id);
    clusterEnd = cluster.length === 1 ? it.end : Math.max(clusterEnd, it.end);
  }
  flush();
  return out;
}

// ── Gestures ─────────────────────────────────────────────
type Options = {
  /** The day columns (inside the scroller): pointers are read against it. */
  columns: React.RefObject<HTMLElement | null>;
  scroller: React.RefObject<HTMLElement | null>;
  span: number;
  /** Visible range in minutes from midnight. */
  min: number;
  max: number;
  pxPerMinute: number;
  step: number;
  /** Length of an event made by holding (touch) before dragging. */
  holdDuration: number;
  items: GridItem[];
  /** A new snapped draft, or null when the gesture ends. Called per step, not per move. */
  onDraft: (draft: GridDraft | null) => void;
  /** The gesture ended on a draft. */
  onCommit: (draft: GridDraft) => void;
  /** A press that didn't become a drag: on an event (id) or an empty slot. */
  onTap: (
    target: { id: string } | { day: number; minute: number },
    pointerType: string,
  ) => void;
  disabled?: boolean;
};

type Gesture = {
  pointerId: number;
  pointerType: string;
  kind: GridDraftKind;
  id: string;
  x: number;
  y: number;
  downDay: number;
  downMinute: number;
  /** Minutes between the grab point and the event's start. */
  offset: number;
  item: { day: number; start: number; end: number } | null;
  active: boolean;
  held: boolean;
  timer: number;
  draft: GridDraft | null;
};

const HOLD = 360;
const EDGE = 40;
let seq = 0;

export function useTimeGrid(o: Options) {
  const opts = React.useRef(o);
  React.useLayoutEffect(() => {
    opts.current = o;
  });
  const g = React.useRef<Gesture | null>(null);
  const scrollLoop = React.useRef(0);

  const snap = (m: number) =>
    Math.round(m / opts.current.step) * opts.current.step;
  const floorStep = (m: number) =>
    Math.floor(m / opts.current.step) * opts.current.step;

  /** The grid's box, measured when a gesture starts and adjusted for scrolling, so a drag never forces a layout read. */
  const box = React.useRef<{
    left: number;
    top: number;
    width: number;
    scroll: number;
  } | null>(null);
  /** The scroller's offset, kept from its scroll events: reading scrollTop mid-transition would force a style flush. */
  const scrollY = React.useRef(0);
  const measure = () => {
    const r = opts.current.columns.current!.getBoundingClientRect();
    scrollY.current = opts.current.scroller.current?.scrollTop ?? 0;
    return {
      left: r.left,
      top: r.top,
      width: r.width,
      scroll: scrollY.current,
    };
  };

  /** Pointer position to a day and a minute (unsnapped). */
  const locate = (x: number, y: number) => {
    const { span, min, max, pxPerMinute } = opts.current;
    const r = box.current ?? measure();
    const top = r.top - (scrollY.current - r.scroll);
    const day = Math.min(
      span - 1,
      Math.max(0, Math.floor(((x - r.left) / r.width) * span)),
    );
    const minute = Math.min(max, Math.max(min, min + (y - top) / pxPerMinute));
    return { day, minute };
  };

  const compute = () => {
    const s = g.current;
    if (!s?.active) return;
    const { min, max, step, holdDuration } = opts.current;
    const { day, minute } = locate(s.x, s.y);
    let next: GridDraft;
    if (s.kind === "create") {
      const a = floorStep(s.downMinute);
      const b = snap(minute);
      // Held without moving yet (touch): a block of the default length; then it follows the finger from the anchor.
      if (s.held && Math.abs(minute - s.downMinute) < step / 2)
        next = {
          kind: "create",
          id: s.id,
          day: s.downDay,
          start: a,
          end: Math.min(max, a + holdDuration),
        };
      else if (b > a)
        next = {
          kind: "create",
          id: s.id,
          day: s.downDay,
          start: a,
          end: Math.max(a + step, b),
        };
      else
        next = {
          kind: "create",
          id: s.id,
          day: s.downDay,
          start: Math.max(min, Math.min(b, a)),
          end: a + step,
        };
    } else {
      const it = s.item!;
      const length = it.end - it.start;
      if (s.kind === "move") {
        const start = Math.min(
          max - length,
          Math.max(min, snap(minute - s.offset)),
        );
        next = { kind: "move", id: s.id, day, start, end: start + length };
      } else if (s.kind === "start")
        next = {
          kind: "start",
          id: s.id,
          day: it.day,
          start: Math.min(it.end - step, Math.max(min, snap(minute))),
          end: it.end,
        };
      else
        next = {
          kind: "end",
          id: s.id,
          day: it.day,
          start: it.start,
          end: Math.max(it.start + step, Math.min(max, snap(minute))),
        };
    }
    const prev = s.draft;
    if (
      prev &&
      prev.day === next.day &&
      prev.start === next.start &&
      prev.end === next.end
    )
      return;
    s.draft = next;
    opts.current.onDraft(next);
  };

  /** Near the scroller's top or bottom edge, scroll it (faster the closer) and re-read the pointer against the moved grid. */
  const autoScroll = () => {
    cancelAnimationFrame(scrollLoop.current);
    const tick = () => {
      const s = g.current;
      const sc = opts.current.scroller.current;
      if (!s?.active || !sc) return;
      const r = sc.getBoundingClientRect();
      const up = s.y < r.top + EDGE ? (r.top + EDGE - s.y) / EDGE : 0;
      const down = s.y > r.bottom - EDGE ? (s.y - (r.bottom - EDGE)) / EDGE : 0;
      const speed = (down - up) * 14;
      if (!speed) return;
      const before = sc.scrollTop;
      sc.scrollTop += speed;
      scrollY.current = sc.scrollTop;
      if (scrollY.current !== before) compute();
      scrollLoop.current = requestAnimationFrame(tick);
    };
    scrollLoop.current = requestAnimationFrame(tick);
  };

  const activate = () => {
    const s = g.current;
    if (!s || s.active) return;
    s.active = true;
    if (s.pointerType === "touch") navigator.vibrate?.(8);
    compute();
  };

  const end = (commit: boolean) => {
    const s = g.current;
    if (!s) return;
    window.clearTimeout(s.timer);
    cancelAnimationFrame(scrollLoop.current);
    g.current = null;
    box.current = null;
    try {
      opts.current.columns.current?.releasePointerCapture(s.pointerId);
    } catch {}
    if (s.active) {
      if (commit && s.draft) opts.current.onCommit(s.draft);
      opts.current.onDraft(null);
    } else if (commit) {
      opts.current.onTap(
        s.item
          ? { id: s.id }
          : { day: s.downDay, minute: floorStep(s.downMinute) },
        s.pointerType,
      );
    }
  };

  const onPointerDown = (e: React.PointerEvent<HTMLElement>) => {
    if (
      opts.current.disabled ||
      g.current ||
      (e.pointerType === "mouse" && e.button !== 0)
    )
      return;
    const target = e.target as HTMLElement;
    if (target.closest("input, textarea, [data-grid-ignore]")) return;
    const el = target.closest<HTMLElement>("[data-event-id]");
    const edge = target.closest<HTMLElement>("[data-edge]")?.dataset.edge as
      "start" | "end" | undefined;
    box.current = measure();
    const { day, minute } = locate(e.clientX, e.clientY);
    const item =
      el && !el.dataset.busy
        ? (opts.current.items.find((it) => it.id === el.dataset.eventId) ??
          null)
        : null;
    g.current = {
      pointerId: e.pointerId,
      pointerType: e.pointerType,
      kind: item ? (edge ?? "move") : "create",
      id: item ? item.id : `new-${Date.now().toString(36)}-${seq++}`,
      x: e.clientX,
      y: e.clientY,
      downDay: day,
      downMinute: minute,
      offset: item ? minute - item.start : 0,
      item: item && { day: item.day, start: item.start, end: item.end },
      active: false,
      held: false,
      timer: 0,
      draft: null,
    };
    if (e.pointerType === "touch") {
      // Hold to pick up; moving first is a scroll.
      g.current.timer = window.setTimeout(() => {
        if (!g.current) return;
        g.current.held = true;
        activate();
      }, HOLD);
    } else {
      e.preventDefault();
      e.currentTarget.setPointerCapture(e.pointerId);
    }
  };

  const onPointerMove = (e: React.PointerEvent<HTMLElement>) => {
    const s = g.current;
    if (!s || s.pointerId !== e.pointerId) return;
    const moved = Math.hypot(e.clientX - s.x, e.clientY - s.y);
    if (!s.active) {
      if (s.pointerType === "touch") {
        if (moved > 8) end(false);
        return;
      }
      if (moved < 4) return;
      s.x = e.clientX;
      s.y = e.clientY;
      activate();
    }
    s.x = e.clientX;
    s.y = e.clientY;
    compute();
    autoScroll();
  };

  const onPointerUp = (e: React.PointerEvent<HTMLElement>) => {
    if (g.current?.pointerId === e.pointerId) end(true);
  };
  const onPointerCancel = (e: React.PointerEvent<HTMLElement>) => {
    if (g.current?.pointerId === e.pointerId) end(false);
  };

  // Once a held finger has picked something up, the page mustn't scroll under it (and no context menu).
  React.useEffect(() => {
    const el = o.columns.current;
    if (!el) return;
    const touchMove = (e: TouchEvent) => {
      if (g.current?.active && e.cancelable) e.preventDefault();
    };
    const menu = (e: Event) => {
      if (g.current) e.preventDefault();
    };
    el.addEventListener("touchmove", touchMove, { passive: false });
    el.addEventListener("contextmenu", menu);
    return () => {
      el.removeEventListener("touchmove", touchMove);
      el.removeEventListener("contextmenu", menu);
    };
  }, [o.columns]);

  React.useEffect(() => {
    const sc = o.scroller.current;
    if (!sc) return;
    const onScroll = () => {
      scrollY.current = sc.scrollTop;
    };
    sc.addEventListener("scroll", onScroll, { passive: true });
    return () => sc.removeEventListener("scroll", onScroll);
  }, [o.scroller]);

  React.useEffect(
    () => () => {
      cancelAnimationFrame(scrollLoop.current);
      if (g.current) window.clearTimeout(g.current.timer);
    },
    [],
  );

  return {
    onPointerDown,
    onPointerMove,
    onPointerUp,
    onPointerCancel,
    onLostPointerCapture: onPointerCancel,
  };
}

/* ─────────────────────────────────────────────────────────
 * TOKEN FLIP: chips that keep their place on screen
 *
 *   snapshot  where every chip, its label and the input sit in
 *             the layout, plus where they are on screen right
 *             now; taken at the keystroke, the paste or the
 *             click, never at the last render
 *   play      after React lays the new order out, every chip
 *             glides from its old place to its new one. Glides
 *             are additive: a change that lands mid-glide (a name
 *             resolving while a paste is still landing) adds its
 *             own offset on top, so nothing restarts or jumps.
 *             A chip that changed width eases its shell; a new
 *             chip grows its shell round the letters you typed,
 *             or spills out of the caret when pasted.
 *   ghosts    copies that leave, or fly into a twin, live in an
 *             overlay so the real list never waits for them
 *
 * Transforms, a shell's width and a one-off clip only; nothing
 * here runs per pointer move. Elements are found by data
 * attributes: data-token, data-token-shell, data-token-label,
 * data-token-extra and data-token-input.
 * ───────────────────────────────────────────────────────── */

export type TokenBox = { x: number; y: number; w: number; h: number };
export type TokenChip = {
  /** Layout boxes in list coordinates, transforms ignored. */
  box: TokenBox;
  label: TokenBox;
  /** The shell's width as drawn right now (mid-ease included). */
  shell: number;
  /** Where the chip and its label are on screen right now, in list coordinates. */
  screen: TokenBox;
  screenLabel: TokenBox;
};
export type TokenSnapshot = {
  chips: Map<string, TokenChip>;
  input: TokenBox | null;
};

/**
 * How a new chip arrives. "text": its letters stay where they were typed (box) or where they are (no box) while the
 * shell grows round them; `hold` keeps them hidden while a copy is carried in. "point": it spills out of a point (paste).
 */
export type TokenEnter =
  | { from: "text"; box?: TokenBox; delay?: number; hold?: number }
  | { from: "point"; x: number; y: number; delay: number };

export const TOKEN_EASE = "cubic-bezier(0.16,1,0.3,1)";
export const TOKEN_THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const GLIDE = 440;
const SPILL = 560;
const ENTER = "token-enter";

const chipsOf = (list: HTMLElement) =>
  list.querySelectorAll<HTMLElement>("[data-token]");
const part = (chip: HTMLElement, name: string) =>
  chip.querySelector<HTMLElement>(`[data-token-${name}]`);

const screenBox = (el: Element, origin: DOMRect): TokenBox => {
  const r = el.getBoundingClientRect();
  return {
    x: r.left - origin.left,
    y: r.top - origin.top,
    w: r.width,
    h: r.height,
  };
};

/** The layout box (offsets, so running transforms don't count) in list coordinates. */
function layoutBox(
  el: HTMLElement,
  list: HTMLElement,
  origin: DOMRect,
): TokenBox {
  let x = 0;
  let y = 0;
  let node: HTMLElement | null = el;
  while (node && node !== list) {
    x += node.offsetLeft;
    y += node.offsetTop;
    node = node.offsetParent as HTMLElement | null;
  }
  return node === list
    ? { x, y, w: el.offsetWidth, h: el.offsetHeight }
    : screenBox(el, origin);
}

export function snapshotTokens(list: HTMLElement): TokenSnapshot {
  const origin = list.getBoundingClientRect();
  const chips = new Map<string, TokenChip>();
  chipsOf(list).forEach((chip) => {
    const label = part(chip, "label") ?? chip;
    const shell = part(chip, "shell");
    chips.set(chip.dataset.token!, {
      box: layoutBox(chip, list, origin),
      label: layoutBox(label, list, origin),
      shell: shell
        ? parseFloat(getComputedStyle(shell).width) || chip.offsetWidth
        : chip.offsetWidth,
      screen: screenBox(chip, origin),
      screenLabel: screenBox(label, origin),
    });
  });
  const input = list.querySelector<HTMLElement>("[data-token-input]");
  return { chips, input: input ? layoutBox(input, list, origin) : null };
}

const moved = (dx: number, dy: number) =>
  Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5;

/** An offset that decays to nothing, added on top of whatever else is moving the element. */
function glide(el: HTMLElement, dx: number, dy: number) {
  el.animate(
    [
      { transform: `translate(${dx}px, ${dy}px)` },
      { transform: "translate(0px, 0px)" },
    ],
    { duration: GLIDE, easing: TOKEN_EASE, composite: "add" },
  );
}

const stopMoving = (el: HTMLElement) =>
  el
    .getAnimations()
    .forEach(
      (a) =>
        (a.effect as KeyframeEffect | null)
          ?.getKeyframes()
          .some((k) => "transform" in k) && a.cancel(),
    );

/** A pasted chip spills out of a point (list coordinates) after `delay`, and remembers it in case the layout moves first. */
function spill(
  chip: HTMLElement,
  x: number,
  y: number,
  at: TokenBox,
  delay: number,
) {
  chip.dataset.tokenFromX = String(x);
  chip.dataset.tokenFromY = String(y);
  const a = chip.animate(
    [
      {
        transform: `translate(${x - at.x}px, ${y - at.y}px) scale(0.86)`,
        opacity: 0,
        filter: "blur(4px)",
      },
      { transform: "none", opacity: 1, filter: "blur(0px)" },
    ],
    { duration: SPILL, delay, easing: TOKEN_EASE, fill: "backwards" },
  );
  a.id = ENTER;
}

/**
 * The layout moved while a chip was still spilling in. Stacking a glide on top would drift it (its own offset waits out
 * the delay while the glide decays), so aim it again: from its point if it hasn't left, or on from where it is now.
 */
function reaim(
  chip: HTMLElement,
  entry: Animation,
  was: TokenChip,
  now: TokenBox,
) {
  const delay = Number(entry.effect?.getTiming().delay ?? 0);
  const t = Number(entry.currentTime ?? 0);
  if (t < delay) {
    stopMoving(chip);
    spill(
      chip,
      Number(chip.dataset.tokenFromX),
      Number(chip.dataset.tokenFromY),
      now,
      delay - t,
    );
    return;
  }
  const { opacity, filter } = getComputedStyle(chip);
  stopMoving(chip);
  const s = was.screen;
  const a = chip.animate(
    [
      {
        transform: `translate(${s.x + s.w / 2 - (now.x + now.w / 2)}px, ${s.y + s.h / 2 - (now.y + now.h / 2)}px) scale(${s.w / Math.max(1, now.w)})`,
        opacity,
        filter,
      },
      { transform: "none", opacity: 1, filter: "blur(0px)" },
    ],
    { duration: Math.max(160, SPILL + delay - t), easing: TOKEN_EASE },
  );
  a.id = ENTER;
}

/**
 * Glide everything from `before` to where it sits now. `enter` says how chips that weren't there arrive; `skipInput`
 * keeps the input still (when typed text has just become a chip, the caret is already in place). Returns the new layout.
 */
export function playTokens(
  list: HTMLElement,
  before: TokenSnapshot,
  options: {
    enter?: Map<string, TokenEnter>;
    skipInput?: boolean;
    reduced: boolean;
  },
): TokenSnapshot {
  const { enter, skipInput, reduced } = options;
  const after = snapshotTokens(list);
  if (reduced) return after;

  for (const chip of chipsOf(list)) {
    const id = chip.dataset.token!;
    const now = after.chips.get(id)!;
    const was = before.chips.get(id);
    const shell = part(chip, "shell");
    const label = part(chip, "label");

    if (was) {
      const entry = chip
        .getAnimations()
        .find((a) => a.id === ENTER && a.playState === "running");
      if (moved(was.box.x - now.box.x, was.box.y - now.box.y)) {
        if (entry) reaim(chip, entry, was, now.box);
        else glide(chip, was.box.x - now.box.x, was.box.y - now.box.y);
      }
      // Its width changed (a name arrived, an avatar opened): the shell eases from the width it's drawn at.
      if (shell && Math.abs(was.shell - now.box.w) > 0.5) {
        shell
          .getAnimations()
          .forEach(
            (a) =>
              (a.effect as KeyframeEffect | null)
                ?.getKeyframes()
                .some((k) => "width" in k) && a.cancel(),
          );
        shell.animate(
          [{ width: `${was.shell}px` }, { width: `${now.box.w}px` }],
          { duration: GLIDE, easing: TOKEN_EASE },
        );
      }
      const ldx = was.label.x - was.box.x - (now.label.x - now.box.x);
      if (label && Math.abs(ldx) > 0.5) glide(label, ldx, 0);
      continue;
    }

    const how = enter?.get(id);
    if (!how) continue;
    if (how.from === "text") {
      // The letters stay where they were; the shell grows round them from their own outline.
      const L = now.label;
      const C = now.box;
      const delay = how.delay ?? 0;
      if (label && how.box) {
        label.style.transformOrigin = "left center";
        label.animate(
          [
            {
              transform: `translate(${how.box.x - L.x}px, ${how.box.y + how.box.h / 2 - (L.y + L.h / 2)}px) scale(${how.box.w / Math.max(1, L.w)})`,
            },
            { transform: "none" },
          ],
          { duration: GLIDE, delay, easing: TOKEN_EASE, fill: "backwards" },
        );
      }
      if (label && how.hold)
        label.animate([{ opacity: 0 }, { opacity: 0 }], { duration: how.hold });
      const left = Math.max(0, L.x - C.x - 3);
      const right = Math.max(0, C.x + C.w - (L.x + L.w) - 3);
      shell?.animate(
        [
          {
            clipPath: `inset(4px ${right}px 4px ${left}px round 999px)`,
            opacity: 0,
          },
          { clipPath: `inset(0px 0px 0px 0px round 999px)`, opacity: 1 },
        ],
        { duration: 480, delay, easing: TOKEN_EASE, fill: "backwards" },
      );
      chip.querySelectorAll<HTMLElement>("[data-token-extra]").forEach((el) =>
        el.animate(
          [
            { opacity: 0, transform: "scale(0.6)", filter: "blur(3px)" },
            { opacity: 1, transform: "none", filter: "blur(0px)" },
          ],
          {
            duration: 340,
            delay: delay + 140,
            easing: TOKEN_EASE,
            fill: "backwards",
          },
        ),
      );
    } else {
      // Pasted: the chip spills out of the caret and lands in its place.
      spill(chip, how.x, how.y, now.box, how.delay);
    }
  }

  const input = list.querySelector<HTMLElement>("[data-token-input]");
  if (
    input &&
    before.input &&
    after.input &&
    !skipInput &&
    moved(before.input.x - after.input.x, before.input.y - after.input.y)
  )
    glide(
      input,
      before.input.x - after.input.x,
      before.input.y - after.input.y,
    );
  return after;
}

/** A chip that's already here takes a little bump and its ring flashes: "this one". */
export function pulseToken(
  chip: HTMLElement | null | undefined,
  reduced: boolean,
) {
  if (!chip || reduced) return;
  chip.animate(
    [
      { transform: "scale(1)" },
      { transform: "scale(1.08)" },
      { transform: "scale(1)" },
    ],
    { duration: 420, easing: TOKEN_THROW, composite: "add" },
  );
  part(chip, "shell")?.animate(
    [
      { boxShadow: "inset 0 0 0 1px var(--ring)" },
      { boxShadow: "inset 0 0 0 1px var(--ring)", offset: 0.4 },
      { boxShadow: "inset 0 0 0 1px var(--border)" },
    ],
    { duration: 900, easing: TOKEN_EASE },
  );
}

/** The no: a short shake. */
export function shakeToken(
  el: HTMLElement | null | undefined,
  reduced: boolean,
  delay = 0,
) {
  if (!el || reduced) return;
  el.animate(
    [
      { transform: "translateX(0)" },
      { transform: "translateX(-4px)" },
      { transform: "translateX(4px)" },
      { transform: "translateX(-2px)" },
      { transform: "translateX(0)" },
    ],
    { duration: 380, delay, easing: "ease-out", composite: "add" },
  );
}

/** Keyframes for a ghost leaving where it stood. */
export const LEAVE_FRAMES: Keyframe[] = [
  { opacity: 1, transform: "none", filter: "blur(0px)" },
  { opacity: 0, transform: "scale(0.86)", filter: "blur(4px)" },
];

/** Keyframes for letters carried from one box onto another (same text), landing exactly. */
export function carryFrames(from: TokenBox, to: TokenBox): Keyframe[] {
  const scale = to.w / Math.max(1, from.w);
  return [
    { transform: "none" },
    {
      transform: `translate(${to.x - from.x}px, ${to.y + to.h / 2 - (from.y + from.h / 2)}px) scale(${Math.min(1.2, Math.max(0.8, scale))})`,
    },
  ];
}

/** Keyframes for a ghost flying from one box into another and dissolving as it arrives; `appear` fades it in first. */
export function flyFrames(
  from: TokenBox,
  to: TokenBox,
  appear = false,
): Keyframe[] {
  // Centre onto centre at its own size: letters that grew or shrank in flight would read as a different chip.
  const dx = to.x + to.w / 2 - (from.x + from.w / 2);
  const dy = to.y + to.h / 2 - (from.y + from.h / 2);
  return [
    ...(appear
      ? [
          { transform: "scale(0.86)", opacity: 0, filter: "blur(4px)" },
          { transform: "none", opacity: 1, filter: "blur(0px)", offset: 0.24 },
        ]
      : [{ transform: "none", opacity: 1, filter: "blur(0px)" }]),
    {
      transform: `translate(${dx * 0.7}px, ${dy * 0.7}px)`,
      opacity: 0.85,
      filter: "blur(0px)",
      offset: appear ? 0.62 : 0.5,
    },
    {
      transform: `translate(${dx}px, ${dy}px) scale(0.92)`,
      opacity: 0,
      filter: "blur(3px)",
    },
  ];
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TREE DRAG: carry a row (and everything inside it) to a new
 * place and a new depth
 *
 *   lift      after 4px (or a hold on touch) a copy of the row
 *             follows the pointer; the row and its children dim
 *             where they are, so nothing under the pointer moves
 *   slot      up and down picks the gap between two rows; the
 *             line marking it starts at the depth it will land
 *   depth     sideways picks the depth, one level per indent,
 *             within what that gap allows
 *   into      the middle of a row that holds others means
 *             "inside it, at the end": the row takes a ring;
 *             a closed one opens itself after a moment
 *   scroll    near the edges of the scroller (or the window),
 *             they scroll
 *
 * Nothing re-renders while you carry: the copy, the line and the
 * ring are moved by transforms, and rows are measured once at
 * pickup (again only when a folder opens). Rows are found by
 * data-row-id with data-depth, data-parent, data-can-hold,
 * data-expanded and data-has-children.
 * ───────────────────────────────────────────────────────── */

/** Where a carried row would land: in `parent`, after the sibling `after` (null: first), or `into` it at the end. */
export type TreeTarget = {
  parent: string | null;
  after: string | null;
  into: boolean;
};

type RowBox = {
  id: string;
  top: number;
  height: number;
  depth: number;
  parent: string | null;
  canHold: boolean;
  expanded: boolean;
  hasChildren: boolean;
};

type Options = {
  list: React.RefObject<HTMLElement | null>;
  scroller: React.RefObject<HTMLElement | null>;
  preview: React.RefObject<HTMLElement | null>;
  reason: React.RefObject<HTMLElement | null>;
  line: React.RefObject<HTMLElement | null>;
  ring: React.RefObject<HTMLElement | null>;
  indent: number;
  /** Where depth 0's content starts, px from the list's left. */
  inset: number;
  /** Would this change nothing, and why does the parent refuse it (or null)? */
  check: (
    id: string,
    target: TreeTarget,
  ) => { same: boolean; refused: string | null };
  onLift: (id: string) => void;
  /** A closed row held over for a moment: open it. */
  onSpring: (id: string) => void;
  /** Dropped. `from` is where the copy was (x: how far it was carried sideways, y: its top in list coordinates). */
  onDrop: (
    id: string,
    target: TreeTarget,
    from: { x: number; y: number },
  ) => void;
  /** Put back (refused, or dropped where it was). Called once the copy is home. */
  onCancel: (id: string, refused: string | null) => void;
  reduced: boolean;
  disabled?: boolean;
};

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const HOLD = 300;
const SPRING = 650;
const EDGE = 36;

export function useTreeDrag(o: Options) {
  const opts = React.useRef(o);
  React.useLayoutEffect(() => {
    opts.current = o;
  });
  const drag = React.useRef<{
    id: string;
    pointerId: number;
    pointerType: string;
    /** Takes the pointer once the carry starts (not before, or the row's click would go to it). */
    captor: HTMLElement;
    x0: number;
    y0: number;
    x: number;
    y: number;
    /** The list's top on screen at pickup, and the scroll positions then. */
    top0: number;
    scroll0: number;
    page0: number;
    rows: RowBox[];
    block: Set<string>;
    depth0: number;
    rowTop: number;
    active: boolean;
    timer: number;
    key: string;
    target: TreeTarget | null;
    refused: string | null;
    spring: string | null;
    springTimer: number;
    box: { top: number; bottom: number };
  } | null>(null);
  const loop = React.useRef(0);
  const scroll = React.useRef({ top: 0, page: 0 });
  const swallowClick = React.useRef(false);

  /** The pointer's y in list coordinates, from positions kept since pickup (no layout reads). */
  const listY = () => {
    const d = drag.current!;
    return (
      d.y -
      d.top0 +
      (scroll.current.top - d.scroll0) +
      (scroll.current.page - d.page0)
    );
  };

  const write = () => {
    const d = drag.current;
    const p = opts.current.preview.current;
    if (!d?.active || !p) return;
    p.style.transform = `translate3d(${d.x - d.x0}px, ${d.rowTop + listY() - (d.y0 - d.top0)}px, 0)`;
  };

  const measure = () => {
    const d = drag.current;
    const list = opts.current.list.current;
    if (!d || !list) return;
    d.rows = [
      ...list.querySelectorAll<HTMLElement>("[data-row-id][data-depth]"),
    ].map((el) => ({
      id: el.dataset.rowId!,
      top: el.offsetTop,
      height: el.offsetHeight,
      depth: Number(el.dataset.depth),
      parent: el.dataset.parent || null,
      canHold: el.dataset.canHold === "1",
      expanded: el.dataset.expanded === "1",
      hasChildren: el.dataset.hasChildren === "1",
    }));
    // The carried row and every row under it that's deeper: they travel together and can't be dropped into.
    const i = d.rows.findIndex((r) => r.id === d.id);
    d.block = new Set();
    if (i < 0) return;
    d.rowTop = d.rows[i].top;
    d.depth0 = d.rows[i].depth;
    for (
      let j = i;
      j < d.rows.length && (j === i || d.rows[j].depth > d.depth0);
      j++
    )
      d.block.add(d.rows[j].id);
  };

  const show = (el: HTMLElement | null, on: boolean) => {
    if (el) el.style.opacity = on ? "1" : "0";
  };

  const arrange = () => {
    const d = drag.current!;
    const { indent, inset, line, ring, reason } = opts.current;
    const y = listY();
    const others = d.rows.filter((r) => !d.block.has(r.id));
    const own = d.rows.filter((r) => d.block.has(r.id));
    const ownTop = own[0]?.top ?? 0;
    const ownBottom = own.length
      ? own[own.length - 1].top + own[own.length - 1].height
      : 0;

    let target: TreeTarget | null = null;
    let into: RowBox | null = null;
    let lineY = 0;
    let depth = 0;
    if (!(y >= ownTop && y < ownBottom)) {
      const i = others.findIndex((r) => y < r.top + r.height);
      let slot = others.length;
      if (i >= 0) {
        const r = others[i];
        const at = (y - r.top) / r.height;
        if (y < r.top || at < (r.canHold ? 0.25 : 0.5)) slot = i;
        else if (r.canHold && at <= 0.75) into = r;
        else slot = i + 1;
      }
      if (into) target = { parent: into.id, after: null, into: true };
      else {
        const above = others[slot - 1];
        const below = others[slot];
        const max = above ? above.depth + (above.canHold ? 1 : 0) : 0;
        const min = below ? below.depth : 0;
        depth = Math.max(
          min,
          Math.min(max, d.depth0 + Math.round((d.x - d.x0) / indent)),
        );
        if (!above) target = { parent: null, after: null, into: false };
        else if (depth > above.depth)
          target = { parent: above.id, after: null, into: false };
        else {
          // Climb from the row above to its ancestor at that depth: the carried row goes right after it.
          let k = others.indexOf(above);
          let x = above;
          while (x.depth > depth && k > 0) {
            const want = x.depth - 1;
            while (k > 0 && others[k].depth > want) k--;
            x = others[k];
          }
          target = { parent: x.parent, after: x.id, into: false };
        }
        lineY = above ? above.top + above.height : below ? below.top : 0;
      }
    }

    const key = target
      ? `${target.parent}|${target.after}|${target.into}|${depth}|${lineY}`
      : "none";
    if (key === d.key) return;
    d.key = key;
    const verdict = target
      ? opts.current.check(d.id, target)
      : { same: true, refused: null };
    d.target = target && !verdict.same ? target : null;
    d.refused = d.target ? verdict.refused : null;

    // The line between rows, or the ring round the row it would go inside.
    const l = line.current;
    const g = ring.current;
    const amber = "color-mix(in oklab, #f59e0b 80%, var(--foreground))";
    if (l) {
      show(l, !!d.target && !into);
      if (d.target && !into) {
        const x = inset + depth * indent;
        l.style.transform = `translate3d(${x}px, ${lineY - 1}px, 0)`;
        l.style.width = `calc(100% - ${x + 6}px)`;
        l.style.color = d.refused ? amber : "var(--ring)";
      }
    }
    if (g) {
      show(g, !!d.target && !!into);
      if (d.target && into) {
        g.style.transform = `translate3d(0, ${into.top}px, 0)`;
        g.style.height = `${into.height}px`;
        g.style.color = d.refused ? amber : "var(--ring)";
      }
    }
    const r = reason.current;
    if (r) {
      r.textContent = d.refused ?? "";
      r.hidden = !d.refused;
    }

    // Held over a closed row that has rows inside: it opens after a moment.
    const spring =
      d.target && into && into.hasChildren && !into.expanded && !d.refused
        ? into.id
        : null;
    if (spring !== d.spring) {
      window.clearTimeout(d.springTimer);
      d.spring = spring;
      if (spring)
        d.springTimer = window.setTimeout(() => {
          if (drag.current?.spring === spring) opts.current.onSpring(spring);
        }, SPRING);
    }
  };

  const run = () => {
    cancelAnimationFrame(loop.current);
    const tick = () => {
      const d = drag.current;
      if (!d?.active) return;
      const sc = opts.current.scroller.current;
      const inner =
        d.y < d.box.top + EDGE
          ? -(d.box.top + EDGE - d.y) / EDGE
          : d.y > d.box.bottom - EDGE
            ? (d.y - (d.box.bottom - EDGE)) / EDGE
            : 0;
      const page =
        d.y < EDGE
          ? -(EDGE - d.y) / EDGE
          : d.y > window.innerHeight - EDGE
            ? (d.y - (window.innerHeight - EDGE)) / EDGE
            : 0;
      if (inner && sc && sc.scrollHeight > sc.clientHeight)
        sc.scrollTop =
          scroll.current.top + Math.max(-1, Math.min(1, inner)) * 10;
      else if (page) window.scrollBy(0, Math.max(-1, Math.min(1, page)) * 10);
      if (inner || page) {
        write();
        arrange();
      }
      loop.current = requestAnimationFrame(tick);
    };
    loop.current = requestAnimationFrame(tick);
  };

  const activate = () => {
    const d = drag.current;
    const list = opts.current.list.current;
    if (!d || d.active || !list) return;
    d.active = true;
    if (d.pointerType === "touch") navigator.vibrate?.(8);
    else
      try {
        d.captor.setPointerCapture(d.pointerId);
      } catch {}
    const sc = opts.current.scroller.current;
    const box = (
      sc && sc.scrollHeight > sc.clientHeight ? sc : list
    ).getBoundingClientRect();
    d.box = {
      top: Math.max(0, box.top),
      bottom: Math.min(window.innerHeight, box.bottom),
    };
    d.top0 = list.getBoundingClientRect().top;
    measure();
    opts.current.onLift(d.id);
    run();
  };

  const finish = () => {
    const d = drag.current;
    window.clearTimeout(d?.timer);
    window.clearTimeout(d?.springTimer);
    cancelAnimationFrame(loop.current);
    show(opts.current.line.current, false);
    show(opts.current.ring.current, false);
  };

  const end = (dropped: boolean) => {
    const d = drag.current;
    if (!d) return;
    finish();
    if (!d.active) {
      drag.current = null;
      return;
    }
    swallowClick.current = true;
    window.setTimeout(() => (swallowClick.current = false), 0);
    if (dropped && d.target && !d.refused) {
      const from = { x: d.x - d.x0, y: d.rowTop + listY() - (d.y0 - d.top0) };
      drag.current = null;
      opts.current.onDrop(d.id, d.target, from);
      return;
    }
    // Back home: the copy glides to the row it came from, then the row takes over.
    const refused = dropped ? d.refused : null;
    const p = opts.current.preview.current;
    drag.current = null;
    if (p && !opts.current.reduced) {
      const a = p.animate(
        [
          { transform: p.style.transform },
          { transform: `translate3d(0px, ${d.rowTop}px, 0)` },
        ],
        { duration: 300, easing: THROW, fill: "forwards" },
      );
      a.onfinish = a.oncancel = () => opts.current.onCancel(d.id, refused);
    } else opts.current.onCancel(d.id, refused);
  };

  const onPointerDown = (e: React.PointerEvent<HTMLElement>) => {
    if (
      opts.current.disabled ||
      drag.current ||
      (e.pointerType === "mouse" && e.button !== 0)
    )
      return;
    const t = e.target as HTMLElement;
    if (t.closest("button, input, a, textarea, [data-no-drag]")) return;
    const row = t.closest<HTMLElement>("[data-row-id][data-depth]");
    if (!row) return;
    scroll.current = {
      top: opts.current.scroller.current?.scrollTop ?? 0,
      page: window.scrollY,
    };
    drag.current = {
      id: row.dataset.rowId!,
      pointerId: e.pointerId,
      pointerType: e.pointerType,
      captor: e.currentTarget,
      x0: e.clientX,
      y0: e.clientY,
      x: e.clientX,
      y: e.clientY,
      top0: 0,
      scroll0: scroll.current.top,
      page0: scroll.current.page,
      rows: [],
      block: new Set(),
      depth0: 0,
      rowTop: 0,
      active: false,
      timer: 0,
      key: "",
      target: null,
      refused: null,
      spring: null,
      springTimer: 0,
      box: { top: 0, bottom: 0 },
    };
    if (e.pointerType === "touch")
      drag.current.timer = window.setTimeout(activate, HOLD);
  };

  const onPointerMove = (e: React.PointerEvent<HTMLElement>) => {
    const d = drag.current;
    if (!d || d.pointerId !== e.pointerId) return;
    if (!d.active) {
      const moved = Math.hypot(e.clientX - d.x0, e.clientY - d.y0);
      if (d.pointerType === "touch") {
        if (moved > 8) end(false);
        return;
      }
      if (moved < 4) return;
      activate();
    }
    d.x = e.clientX;
    d.y = e.clientY;
    write();
    arrange();
  };

  const onPointerUp = (e: React.PointerEvent<HTMLElement>) => {
    if (drag.current?.pointerId === e.pointerId) end(true);
  };
  const onPointerCancel = (e: React.PointerEvent<HTMLElement>) => {
    if (drag.current?.pointerId === e.pointerId) end(false);
  };

  // While a row is held on touch the page mustn't scroll under it; scroll positions are kept from events.
  React.useEffect(() => {
    const list = o.list.current;
    const sc = o.scroller.current;
    if (!list) return;
    const touchMove = (e: TouchEvent) => {
      if (drag.current?.active && e.cancelable) e.preventDefault();
    };
    const menu = (e: Event) => {
      if (drag.current) e.preventDefault();
    };
    const onScroll = () => {
      scroll.current.top = sc?.scrollTop ?? 0;
    };
    const onPage = () => {
      scroll.current.page = window.scrollY;
    };
    list.addEventListener("touchmove", touchMove, { passive: false });
    list.addEventListener("contextmenu", menu);
    sc?.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("scroll", onPage, { passive: true });
    return () => {
      list.removeEventListener("touchmove", touchMove);
      list.removeEventListener("contextmenu", menu);
      sc?.removeEventListener("scroll", onScroll);
      window.removeEventListener("scroll", onPage);
    };
  }, [o.list, o.scroller]);

  React.useEffect(
    () => () => {
      cancelAnimationFrame(loop.current);
      window.clearTimeout(drag.current?.timer);
      window.clearTimeout(drag.current?.springTimer);
    },
    [],
  );

  return {
    handlers: { onPointerDown, onPointerMove, onPointerUp, onPointerCancel },
    /** After a row opened mid-carry: measure the rows again and find the slot under the pointer. */
    remeasure: () => {
      const d = drag.current;
      if (!d?.active) return;
      measure();
      d.key = "";
      arrange();
    },
    /** Puts the copy under the pointer (once it has rendered). */
    sync: write,
    /** A carry just ended: the click that follows it isn't a click. */
    swallowClick: () => swallowClick.current,
    ease: EASE,
  };
}

"use client";

import * as React from "react";

/*
 * One wheel's motion engine. The options sit on a ring of SLOTS faces round a cylinder; turning
 * the wheel is one rotateX on the drum (and the same on its copy in the lens), so a fling costs two
 * transforms a frame. Only faces turning round the back are relabelled, so a wheel of 60 minutes or
 * 200 years still has 18 faces. Nothing renders through React while it turns: the value is committed
 * once the wheel comes to rest.
 *
 *   drag     follows the finger one row per row height; past the ends of a wheel that doesn't
 *            loop it stretches with resistance
 *   fling    release velocity is projected forward and rounded to a row, then the wheel decays
 *            onto it exponentially, so it lands without a separate snap
 *   wheel    a mouse notch moves one row; trackpad scrolling turns it freely and settles when quiet
 *   tap      a row above or below the lens turns to the middle
 */

export const SLOTS = 18;
export const STEP = 360 / SLOTS;

export type DrumOptions = {
  count: number;
  loop: boolean;
  itemHeight: number;
  reduced: boolean;
  haptics: boolean;
  label: (index: number) => string;
  disabled: (index: number) => boolean;
  /** The wheel came to rest on this option. */
  onRest: (index: number) => void;
};

const mod = (n: number, m: number) => ((n % m) + m) % m;
const rubber = (x: number) => (1 - 1 / (x * 0.6 + 1)) / 0.6;

export function useWheelDrum(initial: number, options: DrumOptions) {
  const opts = React.useRef(options);
  React.useLayoutEffect(() => {
    opts.current = options;
  });
  const column = React.useRef<HTMLDivElement>(null);
  const drum = React.useRef<HTMLDivElement>(null);
  const lens = React.useRef<HTMLDivElement>(null);
  const faces = React.useRef<(HTMLElement | null)[]>([]);
  const lensFaces = React.useRef<(HTMLElement | null)[]>([]);
  const shown = React.useRef<number[]>([]);
  const sim = React.useRef({
    p: initial,
    from: initial,
    target: initial,
    tau: 0.3,
    t0: 0,
    settling: false,
    spring: false,
    rested: initial,
    tick: Math.round(initial),
    buzz: 0,
    touch: false,
  });
  const frame = React.useRef(0);

  const radius =
    options.itemHeight / (2 * Math.tan((STEP / 2) * (Math.PI / 180)));

  /** Write the drum's rotation and relabel the faces that crossed the back. */
  const paint = React.useCallback((force = false) => {
    const { count, loop, label, disabled, haptics } = opts.current;
    const s = sim.current;
    const r =
      opts.current.itemHeight / (2 * Math.tan((STEP / 2) * (Math.PI / 180)));
    const transform = `translateZ(${-r}px) rotateX(${s.p * STEP}deg)`;
    if (drum.current) drum.current.style.transform = transform;
    if (lens.current) lens.current.style.transform = transform;
    for (let k = 0; k < SLOTS; k++) {
      const i = k + SLOTS * Math.round((s.p - k) / SLOTS);
      if (!force && shown.current[k] === i) continue;
      shown.current[k] = i;
      const real = loop ? mod(i, count) : i;
      const empty = !loop && (i < 0 || i >= count);
      const text = empty || !count ? "" : label(real);
      const off = !empty && count > 0 && disabled(real);
      for (const el of [faces.current[k], lensFaces.current[k]]) {
        if (!el) continue;
        if (el.textContent !== text) el.textContent = text;
        el.toggleAttribute("data-off", off);
      }
    }
    // A tick under the finger for every row that passes the lens (phones that support it).
    const row = Math.round(s.p);
    if (row !== s.tick) {
      s.tick = row;
      const now = performance.now();
      if (
        haptics &&
        s.touch &&
        now - s.buzz > 45 &&
        typeof navigator !== "undefined" &&
        "vibrate" in navigator
      ) {
        s.buzz = now;
        try {
          navigator.vibrate(3);
        } catch {
          /* not allowed yet */
        }
      }
    }
  }, []);

  const rest = React.useCallback(() => {
    const { count, loop, disabled, onRest } = opts.current;
    const s = sim.current;
    s.settling = false;
    if (!count) return;
    const index = loop
      ? mod(Math.round(s.p), count)
      : Math.max(0, Math.min(count - 1, Math.round(s.p)));
    // Landed on an option that can't be chosen: turn on to the nearest one that can.
    if (disabled(index)) {
      for (let d = 1; d < count; d++) {
        const down = index - d,
          up = index + d;
        const ok = (i: number) =>
          (loop || (i >= 0 && i < count)) && !disabled(mod(i, count));
        const next = ok(down) ? down : ok(up) ? up : null;
        if (next !== null) {
          settleTo(Math.round(s.p) + (next - index), 0.16);
          return;
        }
      }
      return;
    }
    s.rested = index;
    onRest(index);
  }, []);

  const step = React.useCallback(
    function runStep(now: number) {
      frame.current = 0;
      const s = sim.current;
      if (!s.settling) return;
      const t = (now - s.t0) / 1000;
      let k: number;
      if (s.spring) {
        // Harmonic spring for overdrag boundaries (omega = 16, zeta = 0.74)
        const omega = 16,
          zeta = 0.74,
          damped = 10.76;
        k =
          Math.exp(-zeta * omega * t) *
          (Math.cos(damped * t) + (zeta / 0.6726) * Math.sin(damped * t));
        if (t > 0.44 || Math.abs(s.p - s.target) < 0.002) {
          s.p = s.target;
          paint();
          rest();
          return;
        }
      } else {
        k = Math.exp(-t / s.tau);
        if (Math.abs(s.p - s.target) < 0.002) {
          s.p = s.target;
          paint();
          rest();
          return;
        }
      }
      s.p = s.target + (s.from - s.target) * k;
      paint();
      frame.current = requestAnimationFrame(runStep);
    },
    [paint],
  );

  function settleTo(target: number, tau: number, spring = false) {
    const s = sim.current;
    s.from = s.p;
    s.target = target;
    s.tau = tau;
    s.spring = spring;
    s.t0 = performance.now();
    s.settling = true;
    if (opts.current.reduced) {
      s.p = target;
      paint();
      rest();
      return;
    }
    cancelAnimationFrame(frame.current);
    frame.current = requestAnimationFrame(step);
  }

  const clampTarget = (target: number) => {
    const { count, loop } = opts.current;
    return loop ? target : Math.max(0, Math.min(count - 1, target));
  };

  /** Turn to an option. Loops take the shorter way round. */
  const turnTo = React.useCallback(
    (index: number, animate = true) => {
      const { count, loop } = opts.current;
      const s = sim.current;
      if (!count) return;
      let target = index;
      if (loop) {
        const base = Math.round(s.settling ? s.target : s.p);
        const delta =
          mod(index - mod(base, count) + count / 2, count) - count / 2;
        target = base + Math.round(delta);
      }
      s.rested = mod(index, count);
      if (!animate) {
        cancelAnimationFrame(frame.current);
        frame.current = 0;
        s.settling = false;
        s.p = s.target = target;
        paint();
        return;
      }
      settleTo(target, 0.16);
    },
    [paint],
  );

  /** Move by whole rows from wherever the wheel is heading (keys, mouse notches). */
  const nudge = React.useCallback((rows: number) => {
    const s = sim.current;
    s.touch = false;
    const base = s.settling ? s.target : Math.round(s.p);
    settleTo(clampTarget(base + rows), 0.11);
  }, []);

  // Pointer, wheel and the initial paint.
  React.useEffect(() => {
    const el = column.current;
    if (!el) return;
    paint(true);
    let drag: {
      id: number;
      y: number;
      p: number;
      moved: boolean;
      samples: { y: number; t: number }[];
    } | null = null;
    let quiet: ReturnType<typeof setTimeout> | null = null;
    const s = sim.current;
    const H = () => opts.current.itemHeight;

    const down = (e: PointerEvent) => {
      if (e.button !== 0 || drag) return;
      el.setPointerCapture(e.pointerId);
      cancelAnimationFrame(frame.current);
      frame.current = 0;
      s.settling = false;
      s.touch = e.pointerType === "touch";
      drag = {
        id: e.pointerId,
        y: e.clientY,
        p: s.p,
        moved: false,
        samples: [{ y: e.clientY, t: e.timeStamp }],
      };
    };
    const move = (e: PointerEvent) => {
      if (!drag || e.pointerId !== drag.id) return;
      const dy = e.clientY - drag.y;
      if (!drag.moved) {
        if (Math.abs(dy) < 3) return;
        drag.moved = true;
        drag.y = e.clientY;
      }
      drag.samples.push({ y: e.clientY, t: e.timeStamp });
      while (drag.samples.length > 2 && e.timeStamp - drag.samples[0].t > 90)
        drag.samples.shift();
      const { count, loop } = opts.current;
      let p = drag.p - (e.clientY - drag.y) / H();
      if (!loop) {
        if (p < 0) p = -rubber(-p);
        else if (p > count - 1) p = count - 1 + rubber(p - (count - 1));
      }
      s.p = p;
      paint();
    };
    const up = (e: PointerEvent) => {
      if (!drag || e.pointerId !== drag.id) return;
      const d = drag;
      drag = null;
      if (!d.moved) {
        // A tap above or below the lens turns that row to the middle.
        const r = el.getBoundingClientRect();
        const r0 =
          opts.current.itemHeight /
          (2 * Math.tan((STEP / 2) * (Math.PI / 180)));
        const off =
          (Math.asin(
            Math.max(
              -1,
              Math.min(1, (e.clientY - (r.top + r.height / 2)) / r0),
            ),
          ) *
            180) /
          Math.PI /
          STEP;
        const rows = Math.round(off);
        if (rows) settleTo(clampTarget(Math.round(s.p) + rows), 0.16);
        else settleTo(clampTarget(Math.round(s.p)), 0.12);
        return;
      }
      const first = d.samples[0],
        last = d.samples[d.samples.length - 1];
      const fresh = e.timeStamp - last.t < 80 && last.t > first.t;
      const velocity = fresh
        ? -((last.y - first.y) / (last.t - first.t)) * (1000 / H())
        : 0; // rows per second
      const { count, loop } = opts.current;
      const outside = !loop && (s.p < 0 || s.p > count - 1);
      const projected = outside ? s.p : s.p + velocity * 0.3;
      const target = clampTarget(Math.round(projected));
      settleTo(
        target,
        outside ? 0.38 : Math.abs(target - s.p) < 0.75 ? 0.12 : 0.3,
        outside,
      );
    };
    const wheel = (e: WheelEvent) => {
      e.preventDefault();
      s.touch = false;
      const px =
        e.deltaMode === 1
          ? e.deltaY * H()
          : e.deltaMode === 2
            ? e.deltaY * H() * 5
            : e.deltaY;
      // A mouse wheel notch is one row; a trackpad turns the wheel freely and settles once it goes quiet.
      if (Math.abs(px) >= 50 && Number.isInteger(e.deltaY)) {
        nudge(Math.sign(px));
        return;
      }
      cancelAnimationFrame(frame.current);
      frame.current = 0;
      s.settling = false;
      const { count, loop } = opts.current;
      let p = s.p + px / H();
      if (!loop) p = Math.max(-0.35, Math.min(count - 1 + 0.35, p));
      s.p = p;
      paint();
      if (quiet) clearTimeout(quiet);
      quiet = setTimeout(
        () => settleTo(clampTarget(Math.round(s.p)), 0.14),
        120,
      );
    };
    el.addEventListener("pointerdown", down);
    el.addEventListener("pointermove", move);
    el.addEventListener("pointerup", up);
    el.addEventListener("pointercancel", up);
    el.addEventListener("wheel", wheel, { passive: false });
    return () => {
      if (quiet) clearTimeout(quiet);
      cancelAnimationFrame(frame.current);
      frame.current = 0;
      el.removeEventListener("pointerdown", down);
      el.removeEventListener("pointermove", move);
      el.removeEventListener("pointerup", up);
      el.removeEventListener("pointercancel", up);
      el.removeEventListener("wheel", wheel);
    };
  }, []);

  // Options changed (a month with fewer days): relabel every face.
  const signature = `${options.count}|${options.loop}`;
  React.useEffect(() => {
    paint(true);
  }, [signature, paint]);

  const attachColumn = React.useCallback((el: HTMLDivElement | null) => {
    column.current = el;
  }, []);
  const attachDrum = React.useCallback((el: HTMLDivElement | null) => {
    drum.current = el;
  }, []);
  const attachLens = React.useCallback((el: HTMLDivElement | null) => {
    lens.current = el;
  }, []);
  const attachFace = React.useCallback((k: number, el: HTMLElement | null) => {
    faces.current[k] = el;
  }, []);
  const attachLensFace = React.useCallback(
    (k: number, el: HTMLElement | null) => {
      lensFaces.current[k] = el;
    },
    [],
  );

  return {
    column,
    drum,
    lens,
    faces,
    lensFaces,
    attachColumn,
    attachDrum,
    attachLens,
    attachFace,
    attachLensFace,
    radius,
    turnTo,
    nudge,
    repaint: () => paint(true),
    resting: () => sim.current.rested,
    moving: () => sim.current.settling,
  };
}

"use client";

import * as React from "react";
import {
  NODE_WIDTH,
  NODE_HEIGHT,
  workflowPath,
  type WorkflowNode,
  type WorkflowEdge,
  type WorkflowPoint,
} from "./workflow-types";

type View = { x: number; y: number; scale: number };
type Gesture = {
  pointer: number;
  startX: number;
  startY: number;
  origin: WorkflowPoint;
  node?: string;
  moved: boolean;
};

export function useWorkflowViewport(
  nodes: WorkflowNode[],
  edges: WorkflowEdge[],
  width: number,
  height: number,
  reduced: boolean,
  onNodeMove?: (id: string, point: WorkflowPoint) => void,
) {
  const viewport = React.useRef<HTMLDivElement>(null);
  const world = React.useRef<HTMLDivElement>(null);
  const [overrides, setOverrides] = React.useState<
    Record<string, WorkflowPoint>
  >({});
  const positions: Record<string, WorkflowPoint> = React.useMemo(
    () =>
      Object.fromEntries(
        nodes.map((node) => [
          node.id,
          overrides[node.id] ?? { x: node.x, y: node.y },
        ]),
      ),
    [nodes, overrides],
  );
  const currentPositions = React.useRef(positions);
  React.useLayoutEffect(() => {
    currentPositions.current = positions;
  });
  const viewRef = React.useRef<View>({ x: 0, y: 0, scale: 1 });
  const gesture = React.useRef<Gesture | null>(null);
  const suppressClick = React.useRef(false);
  const [view, setView] = React.useState<View>({ x: 0, y: 0, scale: 1 });
  const [dragging, setDragging] = React.useState(false);

  const paintView = React.useCallback(
    (next: View, animate = false) => {
      viewRef.current = next;
      if (world.current) {
        world.current.style.transition =
          animate && !reduced
            ? "transform 320ms cubic-bezier(0.16,1,0.3,1)"
            : "none";
        world.current.style.transform = `translate(${next.x}px, ${next.y}px) scale(${next.scale})`;
      }
    },
    [reduced],
  );
  const fit = React.useCallback(
    (minimum = 0.2) => {
      const frame = viewport.current;
      if (!frame) return;
      const scale = Math.max(
        minimum,
        Math.min(
          1.25,
          (frame.clientWidth - 36) / width,
          (frame.clientHeight - 36) / height,
        ),
      );
      const next = {
        x:
          width * scale > frame.clientWidth - 36
            ? 18
            : (frame.clientWidth - width * scale) / 2,
        y: (frame.clientHeight - height * scale) / 2,
        scale,
      };
      paintView(next, true);
      setView(next);
    },
    [width, height, paintView],
  );
  React.useLayoutEffect(() => {
    const frame = viewport.current;
    if (!frame) return;
    const observer = new ResizeObserver(() => fit(0.85));
    observer.observe(frame);
    return () => observer.disconnect();
  }, [fit]);

  const zoom = (factor: number) => {
    const frame = viewport.current;
    if (!frame) return;
    const previous = viewRef.current;
    const scale = Math.max(0.25, Math.min(1.75, previous.scale * factor));
    const cx = frame.clientWidth / 2,
      cy = frame.clientHeight / 2;
    const next = {
      scale,
      x: cx - ((cx - previous.x) * scale) / previous.scale,
      y: cy - ((cy - previous.y) * scale) / previous.scale,
    };
    paintView(next, true);
    setView(next);
  };
  const revealNode = (id: string) => {
    const point = currentPositions.current[id],
      frame = viewport.current;
    if (!point || !frame) return;
    const previous = viewRef.current;
    const left = point.x * previous.scale + previous.x,
      top = point.y * previous.scale + previous.y;
    let x = previous.x,
      y = previous.y;
    if (left < 12) x += 12 - left;
    else if (left + NODE_WIDTH * previous.scale > frame.clientWidth - 12)
      x -= left + NODE_WIDTH * previous.scale - frame.clientWidth + 12;
    if (top < 12) y += 12 - top;
    else if (top + NODE_HEIGHT * previous.scale > frame.clientHeight - 12)
      y -= top + NODE_HEIGHT * previous.scale - frame.clientHeight + 12;
    if (x !== previous.x || y !== previous.y) {
      const next = { ...previous, x, y };
      paintView(next, true);
      setView(next);
    }
  };
  const paintNode = (id: string, point: WorkflowPoint) => {
    currentPositions.current[id] = point;
    const node = world.current?.querySelector<HTMLElement>(
      `[data-workflow-node="${CSS.escape(id)}"]`,
    );
    if (node) node.style.transform = `translate(${point.x}px, ${point.y}px)`;
    edges
      .filter((edge) => edge.from === id || edge.to === id)
      .forEach((edge) => {
        const from = currentPositions.current[edge.from],
          to = currentPositions.current[edge.to];
        if (from && to)
          world.current
            ?.querySelectorAll<SVGPathElement>(
              `[data-workflow-edge="${CSS.escape(edge.id)}"]`,
            )
            .forEach((path) => path.setAttribute("d", workflowPath(from, to)));
      });
  };
  const moveNode = (id: string, dx: number, dy: number) => {
    const point = currentPositions.current[id];
    if (!point) return;
    const next = {
      x: Math.max(0, Math.min(width - NODE_WIDTH, point.x + dx)),
      y: Math.max(0, Math.min(height - NODE_HEIGHT, point.y + dy)),
    };
    paintNode(id, next);
    setOverrides((prev) => ({ ...prev, [id]: next }));
    onNodeMove?.(id, next);
    revealNode(id);
  };
  /**
   * While a gesture runs, the moving part gets its own compositor layer so panning and dragging move pixels instead of
   * repainting them. The layer is dropped afterwards so text re-rasterises crisply at the new zoom.
   */
  const layer = (el: HTMLElement | null | undefined, on: boolean) => {
    if (el) el.style.willChange = on ? "transform" : "";
  };
  const nodeEl = (id?: string) =>
    id
      ? world.current?.querySelector<HTMLElement>(
          `[data-workflow-node="${CSS.escape(id)}"]`,
        )
      : null;
  const finish = (event: React.PointerEvent, cancelled: boolean) => {
    const state = gesture.current;
    if (!state || state.pointer !== event.pointerId) return;
    gesture.current = null;
    layer(state.node ? nodeEl(state.node) : world.current, false);
    setDragging(false);
    suppressClick.current = state.moved;
    if (state.node) {
      if (cancelled) {
        paintNode(state.node, state.origin);
        setOverrides((prev) => ({ ...prev, [state.node!]: state.origin }));
      } else if (state.moved) {
        const point = currentPositions.current[state.node];
        setOverrides((prev) => ({ ...prev, [state.node!]: point }));
        onNodeMove?.(state.node, point);
      }
    } else {
      if (cancelled) paintView({ ...viewRef.current, ...state.origin });
      setView(viewRef.current);
    }
  };

  return {
    viewport,
    world,
    positions,
    view,
    dragging,
    fit: () => fit(),
    zoom,
    revealNode,
    moveNode,
    handlers: {
      onPointerDown(event: React.PointerEvent<HTMLDivElement>) {
        if (
          event.button !== 0 ||
          !event.isPrimary ||
          (event.target as HTMLElement).closest("[data-workflow-control]")
        )
          return;
        const target = (event.target as HTMLElement).closest<HTMLElement>(
          "[data-workflow-node]",
        );
        const node = target?.dataset.workflowNode;
        suppressClick.current = false;
        (target ?? event.currentTarget).setPointerCapture(event.pointerId);
        if (target) target.focus({ preventScroll: true });
        gesture.current = {
          pointer: event.pointerId,
          startX: event.clientX,
          startY: event.clientY,
          node,
          origin: node
            ? { ...currentPositions.current[node] }
            : { x: viewRef.current.x, y: viewRef.current.y },
          moved: false,
        };
      },
      onPointerMove(event: React.PointerEvent<HTMLDivElement>) {
        const state = gesture.current;
        if (!state || state.pointer !== event.pointerId) return;
        const dx = event.clientX - state.startX,
          dy = event.clientY - state.startY;
        if (!state.moved && Math.hypot(dx, dy) < 5) return;
        if (!state.moved) {
          state.moved = true;
          setDragging(true);
          layer(state.node ? nodeEl(state.node) : world.current, true);
        }
        if (state.node)
          paintNode(state.node, {
            x: Math.max(
              0,
              Math.min(
                width - NODE_WIDTH,
                state.origin.x + dx / viewRef.current.scale,
              ),
            ),
            y: Math.max(
              0,
              Math.min(
                height - NODE_HEIGHT,
                state.origin.y + dy / viewRef.current.scale,
              ),
            ),
          });
        else
          paintView({
            ...viewRef.current,
            x: Math.max(
              -width * viewRef.current.scale + 60,
              Math.min(
                (viewport.current?.clientWidth ?? width) - 60,
                state.origin.x + dx,
              ),
            ),
            y: Math.max(
              -height * viewRef.current.scale + 60,
              Math.min(
                (viewport.current?.clientHeight ?? height) - 60,
                state.origin.y + dy,
              ),
            ),
          });
      },
      onPointerUp: (event: React.PointerEvent) => finish(event, false),
      onPointerCancel: (event: React.PointerEvent) => finish(event, true),
      onLostPointerCapture: (event: React.PointerEvent) => finish(event, true),
      onKeyDown(event: React.KeyboardEvent) {
        const state = gesture.current;
        if (event.key !== "Escape" || !state) return;
        event.preventDefault();
        gesture.current = null;
        setDragging(false);
        suppressClick.current = true;
        layer(state.node ? nodeEl(state.node) : world.current, false);
        if (state.node) {
          paintNode(state.node, state.origin);
          setOverrides((prev) => ({ ...prev, [state.node!]: state.origin }));
        } else {
          paintView({ ...viewRef.current, ...state.origin });
          setView(viewRef.current);
        }
      },
      onClickCapture(event: React.MouseEvent) {
        if (suppressClick.current) {
          event.stopPropagation();
          suppressClick.current = false;
        }
      },
    },
  };
}

"use client";

import * as React from "react";
import { HANDLE_ART as ART, HANDLE_GEO as GEO } from "./handle-art";
import { Input } from "./input";
import { StatusButton, type ActionStatus } from "./status-button";
import { TextMorph } from "./text-morph";
import {
  EASE_OUT,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * USERNAME: a penguin holds up the name you want
 *
 *   write    as you type, the name appears on Handle's sign,
 *            letter by letter
 *   free     check() says it's available: he beams, a green tick
 *            lands on the corner of his sign
 *   taken    it isn't: his sign goes blank and his face falls,
 *            and its owner, a smug penguin in a scarf, slides in
 *            hugging a sign with your name on it ("@ana is mine")
 *   try      suggestions come back as chips; one tap writes it
 *   claim    Claim @name → Claiming → Claimed
 *
 * check(name, signal) and onClaim(name) are yours; the field
 * lowercases as you type and keeps to the characters you allow.
 * ───────────────────────────────────────────────────────── */

export interface UsernameProps {
  /** Is the name free? Aborted when a newer name starts. Suggestions show when it isn't. */
  check: (
    name: string,
    signal: AbortSignal,
  ) => Promise<{ available: boolean; suggestions?: string[] }>;
  /** Keep the name; throw to say why not. */
  onClaim: (name: string) => Promise<unknown>;
  defaultValue?: string;
  minLength?: number;
  maxLength?: number;
  /** Characters allowed (the whole name is tested). */
  pattern?: RegExp;
  /** Says what's allowed when the pattern fails. */
  patternHint?: string;
  /** "@", or your domain ("relay.app/"). */
  prefix?: string;
  title?: string;
  /** What the penguin is called in his lines. */
  name?: string;
  className?: string;
}

type Phase =
  "empty" | "short" | "invalid" | "checking" | "free" | "taken" | "error";

const mix = (color: string, amount: number, into = "transparent") =>
  `color-mix(in oklab, ${color} ${amount}%, ${into})`;
const PF = "var(--primary-foreground)";
const CARD: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, var(--card), ${mix("var(--card)", 95, "var(--foreground)")})`,
  boxShadow: `0 0 0 1px var(--border), inset 0 1px 0 ${mix("var(--background)", 85)}`,
};
/* The one lit surface: an ice floe's soft glow under the penguins, and faint snow. */
const STAGE: React.CSSProperties = {
  backgroundColor: "var(--primary)",
  backgroundImage: [
    `radial-gradient(60% 40% at 50% 100%, ${mix(PF, 26)} 0%, transparent 70%)`,
    `linear-gradient(175deg, transparent 40%, ${mix("black", 20)} 100%)`,
    `radial-gradient(circle, ${mix(PF, 28)} 0 1px, transparent 1.5px)`,
    `radial-gradient(circle, ${mix(PF, 18)} 0 1px, transparent 1.5px)`,
  ].join(", "),
  backgroundSize: "auto, auto, 46px 38px, 31px 27px",
  backgroundPosition: "0 0, 0 0, 0 0, 14px 9px",
  boxShadow: `inset 0 1px 0 ${mix(PF, 36)}, inset 0 0 0 1px ${mix(PF, 12)}`,
};
const LIT: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, ${mix(PF, 16)}, transparent 60%)`,
  boxShadow: `inset 0 1px 0 ${mix(PF, 32)}, inset 0 0 0 1px ${mix("black", 10)}`,
};
const INK = "oklch(0.25 0.02 260)";

/* the scene, drawn at 364 × 176 and scaled to the stage */
const W = 364;
const H = 176;
const GROUND = 172;
const OURS = { x: 118, h: 124 };
const OWNER = { x: 272, out: W + 80, h: 124 };
type Pose = "hope" | "joy" | "sad" | "owner";

/** A penguin, standing with its feet at (x, GROUND), with `text` written on its sign. */
function Penguin({
  pose,
  x,
  h,
  text,
  tick,
  style,
}: {
  pose: Pose;
  x: number;
  h: number;
  text: string;
  tick?: boolean;
  style?: React.CSSProperties;
}) {
  const g = GEO[pose];
  const k = h / g.h;
  const w = g.w * k;
  const b = g.board;
  const len = Math.max(1, text.length);
  const font = Math.min(17, ((b.w * k * 0.82) / len) * 1.6);
  return (
    <div
      className="absolute left-0 top-0"
      style={{
        transform: `translate(${x - w / 2}px, ${GROUND - h}px)`,
        width: w,
        height: h,
        ...style,
      }}
    >
      <img
        src={ART[pose]}
        alt=""
        draggable={false}
        className="pointer-events-none absolute inset-0 size-full max-w-none select-none"
      />
      <div
        className="absolute flex items-center justify-center whitespace-nowrap font-semibold tracking-[-0.02em]"
        style={{
          left: (b.x - b.w / 2) * k,
          top: (b.y - b.h / 2) * k,
          width: b.w * k,
          height: b.h * k,
          transform: `rotate(${b.angle}deg)`,
          color: INK,
          fontSize: font,
        }}
      >
        <TextMorph>{text || " "}</TextMorph>
        <span
          className="absolute -right-1.5 -top-1.5 grid size-[18px] place-items-center rounded-full text-white"
          style={{
            background: "var(--color-emerald-500, oklch(0.7 0.16 162))",
            opacity: tick ? 1 : 0,
            transform: tick
              ? "scale(1) rotate(0deg)"
              : "scale(0.3) rotate(-30deg)",
            transition:
              "opacity 200ms, transform 420ms cubic-bezier(0.34,1.36,0.64,1)",
          }}
        >
          <svg viewBox="0 0 16 16" className="size-3" fill="none">
            <path
              d="M3.8 8.3 6.6 11 12.2 5"
              stroke="currentColor"
              strokeWidth="2.2"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </span>
      </div>
    </div>
  );
}

export function Username({
  check,
  onClaim,
  defaultValue = "",
  minLength = 3,
  maxLength = 20,
  pattern = /^[a-z0-9_]+$/,
  patternHint = "Letters, numbers and _ only.",
  prefix = "@",
  title = "Pick a username",
  name = "Handle",
  className = "",
}: UsernameProps) {
  const reduced = useInteractionReducedMotion();
  const baseId = React.useId();
  const [value, setValue] = React.useState(defaultValue.toLowerCase());
  const [result, setResult] = React.useState<{
    name: string;
    available: boolean;
    suggestions: string[];
  } | null>(null);
  const [failed, setFailed] = React.useState<string | null>(null);
  const [claim, setClaim] = React.useState<{
    status: ActionStatus;
    error?: string;
  }>({ status: "idle" });
  const checkRef = React.useRef(check);
  React.useEffect(() => {
    checkRef.current = check;
  });

  const valid = value.length >= minLength && pattern.test(value);
  React.useEffect(() => {
    if (!valid) return;
    const ctrl = new AbortController();
    const timer = window.setTimeout(() => {
      checkRef.current(value, ctrl.signal).then(
        (r) =>
          !ctrl.signal.aborted &&
          setResult({
            name: value,
            available: r.available,
            suggestions: r.suggestions ?? [],
          }),
        () => !ctrl.signal.aborted && setFailed(value),
      );
    }, 380);
    return () => {
      window.clearTimeout(timer);
      ctrl.abort();
    };
  }, [value, valid]);

  const known = result && result.name === value ? result : null;
  const phase: Phase = !value
    ? "empty"
    : !pattern.test(value)
      ? "invalid"
      : value.length < minLength
        ? "short"
        : failed === value
          ? "error"
          : !known
            ? "checking"
            : known.available
              ? "free"
              : "taken";
  const claimed = claim.status === "success";
  const pose: Pose =
    claimed || phase === "free"
      ? "joy"
      : phase === "taken" || phase === "invalid"
        ? "sad"
        : "hope";
  const handle = `${prefix}${value}`;
  const mood = claimed
    ? `Hello, ${handle}`
    : phase === "free"
      ? `${handle} is all yours`
      : phase === "taken"
        ? `“${handle} is mine.”`
        : phase === "checking"
          ? `${name} is asking around`
          : phase === "invalid"
            ? `${name} can’t write that`
            : phase === "short"
              ? "A little longer"
              : phase === "error"
                ? `${name} couldn’t check`
                : `${name} will hold it up`;

  const set = (next: string) => {
    setValue(next.toLowerCase().slice(0, maxLength));
    if (claim.status !== "idle" && claim.status !== "pending")
      setClaim({ status: "idle" });
  };

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (phase !== "free" || claim.status === "pending" || claimed) return;
    setClaim({ status: "pending" });
    try {
      await onClaim(value);
      setClaim({ status: "success" });
    } catch (err) {
      setClaim({
        status: "error",
        error:
          err instanceof Error && err.message
            ? err.message
            : "Couldn’t claim that. Try again.",
      });
    }
  };

  const fade = reduced
    ? "none"
    : `transform 520ms cubic-bezier(0.22,1,0.36,1), opacity 300ms ${EASE_OUT}`;
  const ownerIn = phase === "taken";
  const error =
    phase === "invalid"
      ? patternHint
      : phase === "error"
        ? "Couldn’t check that name. Try again."
        : claim.status === "error"
          ? claim.error
          : undefined;

  return (
    <section
      aria-labelledby={`${baseId}-title`}
      className={`relative w-full max-w-[380px] rounded-[28px] p-2 text-card-foreground ${className}`}
      style={CARD}
    >
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 380px)" }}
      />
      <div className="@container w-full">
        <div
          className="relative overflow-clip rounded-[22px] text-primary-foreground"
          style={STAGE}
        >
          <Scene>
            {(["hope", "joy", "sad"] as const).map((p) => (
              <Penguin
                key={p}
                pose={p}
                x={OURS.x}
                h={OURS.h}
                text={phase === "taken" ? "" : value ? handle : prefix}
                tick={p === "joy" && (phase === "free" || claimed)}
                style={{
                  opacity: p === pose ? 1 : 0,
                  transition: reduced ? "none" : `opacity 220ms ${EASE_OUT}`,
                }}
              />
            ))}
            {/* the one who already has it */}
            <Penguin
              pose="owner"
              x={ownerIn ? OWNER.x : OWNER.out}
              h={OWNER.h}
              text={known && !known.available ? `${prefix}${known.name}` : ""}
              style={{ opacity: ownerIn ? 1 : 0, transition: fade }}
            />
          </Scene>
          <p className="absolute left-3.5 top-3 z-10 max-w-[70%] text-[12.5px] font-medium text-primary-foreground/85">
            <TextMorph>{mood}</TextMorph>
          </p>
        </div>

        <form className="px-3 pb-1 pt-3" onSubmit={submit} noValidate>
          <h2
            id={`${baseId}-title`}
            className="text-[15px] font-medium tracking-[-0.01em]"
          >
            {title}
          </h2>
          <p className="mt-0.5 text-[12.5px] text-muted-foreground">
            {minLength} to {maxLength} characters. You can change it later.
          </p>
          <Input
            className="mt-3"
            aria-label="Username"
            leading={<span className="text-[13.5px]">{prefix}</span>}
            placeholder="yourname"
            value={value}
            onValueChange={set}
            autoComplete="username"
            autoCapitalize="off"
            spellCheck={false}
            maxLength={maxLength}
            error={error}
            hint={
              phase === "taken"
                ? "Taken. Try one of these:"
                : phase === "free"
                  ? "Available."
                  : undefined
            }
          />
          {phase === "taken" && known && known.suggestions.length > 0 && (
            <div
              className="mt-2 flex flex-wrap gap-1.5"
              aria-label="Suggestions"
            >
              {known.suggestions.slice(0, 4).map((s, i) => (
                <button
                  key={s}
                  type="button"
                  onClick={() => set(s)}
                  className="h-7 cursor-pointer rounded-full border border-border bg-background px-2.5 text-[12.5px] hover:bg-accent"
                  style={
                    reduced
                      ? undefined
                      : {
                          animation: `ui-fade-up 320ms ${EASE_OUT} ${i * 50}ms backwards`,
                        }
                  }
                >
                  {prefix}
                  {s}
                </button>
              ))}
            </div>
          )}
          <StatusButton
            type="submit"
            status={claim.status}
            labels={{
              idle: phase === "free" ? `Claim ${handle}` : "Claim",
              pending: "Claiming",
              success: "Claimed",
              error: "Try again",
            }}
            disabled={
              phase !== "free" && claim.status !== "pending" && !claimed
            }
            className="mt-3 h-10 w-full text-[13.5px] disabled:bg-[color-mix(in_oklab,var(--foreground)_7%,transparent)] disabled:text-muted-foreground"
            style={
              phase === "free" && claim.status !== "error" ? LIT : undefined
            }
          />
        </form>
      </div>
      <span className="sr-only" role="status">
        {phase === "free"
          ? `${handle} is available.`
          : phase === "taken"
            ? `${handle} is taken.`
            : claimed
              ? `${handle} is yours.`
              : ""}
      </span>
    </section>
  );
}

/** The stage's scene, drawn at 364 × 176 and scaled to fit. */
function Scene({ children }: { children: React.ReactNode }) {
  const host = React.useRef<HTMLDivElement>(null);
  const scene = React.useRef<HTMLDivElement>(null);
  React.useLayoutEffect(() => {
    const h = host.current;
    const s = scene.current;
    if (!h || !s) return;
    const fit = () =>
      s.style.setProperty("transform", `scale(${h.clientWidth / W})`);
    fit();
    const ro = new ResizeObserver(fit);
    ro.observe(h);
    return () => ro.disconnect();
  }, []);
  return (
    <div
      ref={host}
      aria-hidden="true"
      className="relative w-full"
      style={{ aspectRatio: `${W} / ${H}` }}
    >
      <div
        ref={scene}
        className="absolute left-0 top-0 origin-top-left"
        style={{ width: W, height: H }}
      >
        {children}
      </div>
    </div>
  );
}

export default Username;

"use client";

import * as React from "react";
import { CodeInput } from "./code-input";
import { Coo, type CooHandle } from "./coo-pigeon";
import { NumberRoll } from "./number-roll";
import { StatusButton, type ActionStatus } from "./status-button";
import { TextMorph } from "./text-morph";
import {
  EASE_OUT,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * VERIFY CODE: the pigeon who carried it
 *
 *   waiting  Coo stands on his post across the stage from the
 *            mailbox; its flag is up, your code is in there
 *   reading  every digit you type, he nods along
 *   wrong    he shakes his head; the boxes shake and clear
 *   right    the boxes close into one pill, he puffs his chest
 *            and gives two proud flaps
 *   wait     while the resend clock runs he naps on his post,
 *            z's drifting up and a thought bubble counting the
 *            seconds down; typing wakes him to read along, and
 *            at zero the bubble pops and he hops up, ready
 *   resend   he takes off with a new envelope, flies the route,
 *            pops the mailbox flag and flies home; if the send
 *            fails he comes back with the envelope in his beak
 *
 * onVerify gets the code, onResend sends another; both are
 * yours, whatever sends your codes.
 * ───────────────────────────────────────────────────────── */

export interface VerifyCodeProps {
  /** Where the code went: an email address or a phone number. */
  destination: string;
  channel?: "email" | "sms";
  length?: number;
  /** Check the code. Resolve (or return true) to accept; return false or throw to say it's wrong. */
  onVerify: (code: string) => Promise<boolean | void>;
  /** Send a new code. Return { retryAfter } (seconds) to set the next wait; throw to say it didn't go. */
  onResend: () => Promise<{ retryAfter?: number } | void | unknown>;
  /** Seconds before the first resend. */
  resendAfter?: number;
  /** Shows Change beside the address. */
  onChangeDestination?: () => void;
  title?: string;
  /** What the pigeon is called in his lines. */
  name?: string;
  autoFocus?: boolean;
  className?: string;
}

const mix = (color: string, amount: number, into = "transparent") =>
  `color-mix(in oklab, ${color} ${amount}%, ${into})`;
const PF = "var(--primary-foreground)";
const CARD: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, var(--card), ${mix("var(--card)", 95, "var(--foreground)")})`,
  boxShadow: `0 0 0 1px var(--border), inset 0 1px 0 ${mix("var(--background)", 85)}`,
};
/* The one lit surface, ruled with faint airmail stripes along its foot: the sky he flies through. */
const STAGE: React.CSSProperties = {
  backgroundColor: "var(--primary)",
  backgroundImage: [
    `radial-gradient(90% 70% at 50% 0%, ${mix(PF, 20)} 0%, transparent 62%)`,
    `linear-gradient(175deg, transparent 45%, ${mix("black", 20)} 100%)`,
    `repeating-linear-gradient(-45deg, ${mix(PF, 10)} 0 7px, transparent 7px 14px, ${mix(PF, 5)} 14px 21px, transparent 21px 28px)`,
  ].join(", "),
  backgroundSize: "auto, auto, 100% 7px",
  backgroundRepeat: "no-repeat, no-repeat, repeat-x",
  backgroundPosition: "0 0, 0 0, 0 100%",
  boxShadow: `inset 0 1px 0 ${mix(PF, 36)}, inset 0 0 0 1px ${mix(PF, 12)}`,
};
const COO = {
  "--coo-route": PF,
  "--coo-z": PF,
  "--coo-bubble": PF,
  "--coo-bubble-ink": "var(--primary)",
} as React.CSSProperties;

type Flight = "home" | "away" | "failed";

export function VerifyCode({
  destination,
  channel = "email",
  length = 6,
  onVerify,
  onResend,
  resendAfter = 30,
  onChangeDestination,
  title,
  name = "Coo",
  autoFocus,
  className = "",
}: VerifyCodeProps) {
  const reduced = useInteractionReducedMotion();
  const baseId = React.useId();
  const coo = React.useRef<CooHandle>(null);
  const [phase, setPhase] = React.useState<
    "idle" | "checking" | "wrong" | "right"
  >("idle");
  const [left, setLeft] = React.useState(resendAfter);
  const [send, setSend] = React.useState<ActionStatus>("idle");
  const [flight, setFlight] = React.useState<Flight>("home");
  const typed = React.useRef(0);
  // typing wakes him for a while; then he nods off again if the clock is still running
  const [awake, setAwake] = React.useState(false);
  const awakeTimer = React.useRef(0);
  React.useEffect(() => () => window.clearTimeout(awakeTimer.current), []);

  // whole seconds down to zero; the route drains with them
  React.useEffect(() => {
    if (left <= 0 || flight === "away") return;
    const timer = window.setTimeout(
      () => setLeft((s) => Math.max(0, s - 1)),
      1000,
    );
    return () => window.clearTimeout(timer);
  }, [left, flight]);

  const resend = async () => {
    if (send === "pending" || left > 0 || flight === "away") return;
    setSend("pending");
    setFlight("away");
    coo.current?.send();
    let next = resendAfter;
    let ok = true;
    try {
      const res = await onResend();
      const after = (res as { retryAfter?: number } | undefined)?.retryAfter;
      if (typeof after === "number" && after >= 0) next = after;
    } catch {
      ok = false;
    }
    const home = () => {
      setFlight(ok ? "home" : "failed");
      setSend(ok ? "success" : "error");
      if (ok) {
        setLeft(next);
      }
      window.setTimeout(
        () => setSend((s) => (s === "success" ? "idle" : s)),
        1400,
      );
    };
    if (coo.current) coo.current.delivered(ok, home);
    else home();
  };

  const verify = async (code: string) => {
    setPhase("checking");
    let ok = false;
    try {
      ok = (await onVerify(code)) !== false;
    } catch {
      ok = false;
    }
    setPhase(ok ? "right" : "wrong");
    if (ok) coo.current?.puff();
    else coo.current?.ruffle();
    return ok;
  };

  const where = channel === "sms" ? "number" : "inbox";
  const mood =
    phase === "right"
      ? "Signed for. You’re in."
      : phase === "wrong"
        ? `Not the code ${name} carried`
        : phase === "checking"
          ? `${name} is checking`
          : flight === "away"
            ? `${name} is on his way`
            : flight === "failed"
              ? `${name} couldn’t get through`
              : send === "success"
                ? "A fresh code, delivered"
                : left > 0
                  ? awake
                    ? `${name} is reading along`
                    : `${name} is catching his breath`
                  : `${name} is ready to fly again`;
  const ready = left <= 0 && flight !== "away";

  return (
    <section
      aria-labelledby={`${baseId}-title`}
      className={`relative w-full max-w-[380px] rounded-[28px] p-2 text-card-foreground ${className}`}
      style={{ ...CARD, ...COO }}
    >
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 380px)" }}
      />
      <div className="@container w-full">
        <div
          className="relative overflow-clip rounded-[22px] text-primary-foreground"
          style={STAGE}
        >
          <Coo
            ref={coo}
            wait={flight === "away" || phase === "right" ? 0 : left}
            dozing={
              !awake &&
              flight === "home" &&
              (phase === "idle" || phase === "wrong")
            }
            reduced={reduced}
          />
          <p className="absolute inset-x-0 bottom-3 z-10 text-center text-[12.5px] font-medium text-primary-foreground/85 @max-[340px]:bottom-2 @max-[340px]:text-[11.5px]">
            <TextMorph>{mood}</TextMorph>
          </p>
        </div>

        <div className="px-3 pb-2 pt-3">
          <h2
            id={`${baseId}-title`}
            className="text-[15px] font-medium tracking-[-0.01em]"
          >
            {title ?? `Check your ${where}`}
          </h2>
          <p className="mt-0.5 text-[12.5px] text-muted-foreground">
            {name} brought a {length}-digit code to{" "}
            <span className="font-medium text-foreground">{destination}</span>
            {onChangeDestination ? (
              <>
                {" · "}
                <button
                  type="button"
                  onClick={onChangeDestination}
                  className="cursor-pointer underline decoration-border underline-offset-2 hover:text-foreground"
                >
                  Change
                </button>
              </>
            ) : (
              "."
            )}
          </p>

          <CodeInput
            className="mt-3"
            length={length}
            label="Enter the code"
            autoFocus={autoFocus}
            onValueChange={(v) => {
              setAwake(true);
              window.clearTimeout(awakeTimer.current);
              awakeTimer.current = window.setTimeout(
                () => setAwake(false),
                4000,
              );
              if (v.length > typed.current) coo.current?.peck();
              typed.current = v.length;
              if (phase === "wrong") setPhase("idle");
            }}
            onComplete={verify}
          />

          {/* the resend line folds away once the code is right */}
          <div
            className="grid"
            style={{
              gridTemplateRows: phase === "right" ? "0fr" : "1fr",
              opacity: phase === "right" ? 0 : 1,
              transition: reduced
                ? "none"
                : `grid-template-rows 420ms ${EASE_OUT}, opacity 240ms`,
            }}
          >
            <div className="min-w-0 overflow-hidden" inert={phase === "right"}>
              <div className="mt-2.5 flex h-7 items-center gap-1.5 text-[12px] text-muted-foreground">
                <span>
                  {flight === "failed"
                    ? "Couldn’t send that."
                    : "Didn’t get it?"}
                </span>
                <span className="grid items-center">
                  <span className="sr-only">
                    {ready
                      ? ""
                      : flight === "away"
                        ? "Sending a new code."
                        : "You can resend the code shortly."}
                  </span>
                  <span
                    aria-hidden="true"
                    className="col-start-1 row-start-1 flex items-baseline whitespace-nowrap tabular-nums"
                    style={{
                      opacity: ready ? 0 : 1,
                      filter: ready ? "blur(3px)" : "none",
                      transition: reduced
                        ? "none"
                        : `opacity 260ms ${EASE_OUT}, filter 260ms ${EASE_OUT}`,
                    }}
                  >
                    {flight === "away" ? (
                      <TextMorph>Sending</TextMorph>
                    ) : (
                      <>
                        Resend in {Math.floor(left / 60)}:
                        <NumberRoll
                          value={left % 60}
                          format={{ minimumIntegerDigits: 2 }}
                          direction="down"
                          duration={700}
                        />
                      </>
                    )}
                  </span>
                  <span
                    className="col-start-1 row-start-1"
                    inert={!ready}
                    style={{
                      opacity: ready ? 1 : 0,
                      filter: ready ? "none" : "blur(3px)",
                      transition: reduced
                        ? "none"
                        : `opacity 260ms ${EASE_OUT}, filter 260ms ${EASE_OUT}`,
                    }}
                  >
                    <StatusButton
                      variant="ghost"
                      size="sm"
                      status={send === "pending" ? "idle" : send}
                      labels={{
                        idle: "Resend code",
                        success: "Sent",
                        error: "Try again",
                      }}
                      onClick={resend}
                      className="-ml-2"
                    />
                  </span>
                </span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

export default VerifyCode;

