        this.played = false;
        this.bufferStarted = null;
        this.diagnostics = {
          stats: null,
          bufferAhead: 0,
          bufferBehind: 0,
          stalls: 0,
          bufferingSeconds: 0,
          startupSeconds: null,
          latestError: null,
          events: [],
        };
        this.patch({ buffering: true });
        this.bufferStarted = performance.now();
        if (
          !source.src.trim() ||
          !supportsSource(
            engine,
            detectVideoFormat(source.src, source.type),
            !!source.drm,
          )
        ) {
          this.fail(
            unsupportedError(
              "Choose Shaka for DASH or protected content; HLS.js accepts HLS sources only.",
            ),
          );
          return;
        }
