  const togglePip = useCallback(() => {
    const el = video.current;
    if (!el || !enablePictureInPicture || !support.pip) return;
    setBrowserNotice("");
    void (
      el.ownerDocument.pictureInPictureElement === el
        ? el.ownerDocument.exitPictureInPicture()
        : el.requestPictureInPicture()
    ).catch(() =>
      setBrowserNotice(
        "Picture-in-picture is unavailable for this video or browser.",
      ),
    );
  }, [enablePictureInPicture, support.pip]);
  const toggleExpanded = useCallback(() => {
    if (!fullscreen) setExpanded((value) => (value ? false : enableFullscreen));
  }, [fullscreen, enableFullscreen]);
  const context = useMemo(
    () => ({
      store,
      video,
      frame,
      animated,
      gooey: enableGooey && !reduced,
      expanded,
      fullscreen,
      pip,
      canExpand: enableFullscreen,
      canFullscreen: enableFullscreen && support.fullscreen,
      canPip: enablePictureInPicture && support.pip,
      togglePlayback,
      toggleExpanded,
      toggleFullscreen,
      togglePip,
    }),
    [
      store,
      animated,
      enableGooey,
      reduced,
      expanded,
      fullscreen,
      pip,
      enableFullscreen,
      enablePictureInPicture,
      support,
      togglePlayback,
      toggleExpanded,
      toggleFullscreen,
      togglePip,
    ],
  );
  const keyboard = (event: KeyboardEvent<HTMLDivElement>) => {
    if (
      event.defaultPrevented ||
      event.altKey ||
      event.ctrlKey ||
      event.metaKey ||
      event.nativeEvent.isComposing
    )
      return;
    const key = event.key.toLowerCase();
    const mediaShortcut = key === "m" || key === "f";
    if (event.target instanceof HTMLElement && event.target !== frame.current) {
      if (
        event.target.closest(
          'select,textarea,input:not([type="range"]),[contenteditable="true"]',
        )
      )
        return;
      if (!mediaShortcut && event.target.closest('input,button,[role="menu"]'))
        return;
    }
    if (mediaShortcut && event.repeat) {
      event.preventDefault();
      return;
    }
    const state = store.getSnapshot();
    switch (key) {
      case " ":
      case "k":
        togglePlayback();
        break;
      case "arrowleft":
        store.seek(state.time - 5);
        break;
      case "arrowright":
        store.seek(state.time + 5);
        break;
      case "arrowup":
        store.setVolume(state.volume + 0.05);
        break;
      case "arrowdown":
        store.setVolume(state.volume - 0.05);
        break;
      case "m":
        store.toggleMute();
        break;
      case "f":
        if (fullscreen) toggleFullscreen();
        else toggleExpanded();
        break;
      case "c":
        store.setTextTrack(
          state.captions.some((t) => t.active)
            ? "off"
            : (state.captions[0]?.id ?? "off"),
        );
        break;
      default:
        return;
    }
    event.preventDefault();
  };
  useEffect(() => {
    const el = frame.current;
    if (!el) return;
    const doc = el.ownerDocument;
    const hoverShortcut = (event: globalThis.KeyboardEvent) => {
      const key = event.key.toLowerCase();
      if (
        (key !== "m" && key !== "f") ||
        event.defaultPrevented ||
        event.altKey ||
        event.ctrlKey ||
        event.metaKey ||
        event.isComposing ||
        !el.matches(":hover")
      )
        return;
      // Focused controls use the React handler; only body focus needs hover routing.
      if (event.target !== doc.body && event.target !== doc.documentElement)
        return;
      event.preventDefault();
      if (event.repeat) return;
      if (key === "m") store.toggleMute();
      else if (fullscreen) toggleFullscreen();
      else toggleExpanded();
    };
    doc.addEventListener("keydown", hoverShortcut);
    return () => doc.removeEventListener("keydown", hoverShortcut);
  }, [store, fullscreen, toggleFullscreen, toggleExpanded]);
  return (
    <VideoPlayerContext.Provider value={context}>
      <div
        className={`w-full min-w-0 ${className}`}
        style={style}
        data-video-player=""
      >
        <div
          ref={placeholder}
          className="@container/player-layout relative aspect-video w-full"
        >
          <div
            ref={frame}
            popover="manual"
            tabIndex={0}
            role={expanded ? "dialog" : "region"}
            aria-modal={expanded || undefined}
            aria-label={`${title} video player`}
            onKeyDown={keyboard}
            className="@container absolute inset-0 isolate m-0 block h-full w-full overflow-visible rounded-[20px] border-0 bg-black p-0 text-white outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 [&::backdrop]:bg-black/70 [&::backdrop]:opacity-[var(--video-backdrop,0)]"
            style={{ display: "block", containerType: "size" }}
            data-expanded={expanded}
            data-motion={animated ? "full" : "reduced"}
          >
            <video
              ref={video}
              poster={source?.poster ?? poster}
              muted={muted}
              loop={loop}
              playsInline
              preload="metadata"
              aria-label={title}
              className="absolute inset-0 h-full w-full rounded-[inherit] object-cover"
            />
            <VideoStatus title={title} controls={controls} />
            {controls && <VideoControls />}
            {children}
            {expanded && !controls && (
              <button
                type="button"
                onClick={closeExpanded}
                className="absolute right-4 top-4 rounded-full bg-white/15 backdrop-blur-xl px-4 py-3 focus-visible:outline-2 focus-visible:outline-ring"
              >
                Close cinematic mode
              </button>
            )}
            <p
              role="status"
              className={
                browserNotice
                  ? "absolute left-4 top-4 max-w-[80%] rounded-lg bg-white/15 backdrop-blur-xl px-3 py-2 text-xs"
                  : "sr-only"
              }
            >
              {browserNotice}
            </p>
          </div>
        </div>
        {enableDiagnostics && (
          <Suspense
            fallback={
              <p className="p-3 text-xs text-muted-foreground">
                Loading diagnostics…
              </p>
            }
          >
            <Diagnostics format={mediaSource.type} src={mediaSource.src} />
          </Suspense>
        )}
      </div>
    </VideoPlayerContext.Provider>
  );
}

"use client";

import * as React from "react";
import { Mic, MicOff, RotateCcw, Square, X } from "lucide-react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * VOICE INPUT: dictating a prompt
 *
 *   idle          a mic button
 *   listening     the button stretches into a bar: the mic blurs
 *                 into Stop, a waveform drawn from your mic level,
 *                 a timer whose seconds roll, and Cancel; the live
 *                 transcript opens above
 *   transcribing  the waveform settles flat as "Transcribing"
 *                 rises over it and Stop becomes a spinner; then
 *                 the bar shrinks back into the mic
 *   blocked       the browser denied the microphone; the mic blurs
 *                 into a crossed-out one and how to fix it opens in
 *   error         it didn't catch that; try again
 *
 * One surface throughout: give it the width the bar should fill
 * and the mic stretches across it from its own side (align="end"
 * for a mic beside Send, so it grows leftwards). Your recording
 * code owns the mic: pass
 * status and the current level (0 to 1). Without a level the
 * bars move in a gentle wave.
 * ───────────────────────────────────────────────────────── */

export type VoiceStatus =
  "idle" | "listening" | "transcribing" | "blocked" | "error";

export interface VoiceInputProps extends React.HTMLAttributes<HTMLDivElement> {
  status: VoiceStatus;
  /** Current microphone level, 0 to 1. */
  level?: number;
  /** The words recognised so far. */
  transcript?: string;
  /** When listening started (ms); shows a timer. */
  startedAt?: number;
  onStart?: () => void;
  onStop?: () => void;
  onCancel?: () => void;
  errorText?: string;
  /** Which side the mic sits on; the bar grows from there. "end" suits a mic beside Send. */
  align?: "start" | "end";
}

const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const BARS = 28;
const MORPH = "cubic-bezier(0.16,1,0.3,1)";
// A light that sweeps across the label. A mask, not a text clip, so it reaches letters that are mid-morph.
const SHEEN =
  "text-foreground [mask-image:linear-gradient(90deg,rgb(0_0_0/0.45)_35%,#000_50%,rgb(0_0_0/0.45)_65%)] [mask-size:200%_100%] animate-[ui-sheen_1.4s_linear_infinite] motion-reduce:animate-none motion-reduce:[mask-image:none] motion-reduce:text-foreground/70";
const TWO_DIGITS = { minimumIntegerDigits: 2 };

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Icons trade places through a blur: the old one shrinks away as the new one grows in. */
const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 260ms ${MORPH}, transform 380ms ${MORPH}, filter 260ms ${MORPH}`,
});

/** Content that fades in once its surface has made room, and out before it closes. */
const appear = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  filter: on ? "none" : "blur(4px)",
  transition: reduced
    ? "none"
    : on
      ? `opacity 320ms ${MORPH} 140ms, filter 320ms ${MORPH} 140ms`
      : `opacity 140ms ease-out, filter 140ms ease-out`,
});

export function VoiceInput({
  status,
  level,
  transcript,
  startedAt,
  onStart,
  onStop,
  onCancel,
  errorText,
  align = "start",
  className = "",
  ...props
}: VoiceInputProps) {
  const end = align === "end";
  const reduced = useReducedMotion();
  const listening = status === "listening";
  const transcribing = status === "transcribing";
  const wide = listening || transcribing;
  const alert = status === "blocked" || status === "error";
  const blocked = status === "blocked";
  const [history, setHistory] = React.useState<number[]>(() =>
    Array(BARS).fill(0),
  );
  const [now, setNow] = React.useState(startedAt ?? 0);
  const [lastTranscript, setLastTranscript] = React.useState(transcript);
  if (transcript && transcript !== lastTranscript)
    setLastTranscript(transcript);

  const [seenLevel, setSeenLevel] = React.useState(level);
  if (level !== seenLevel) {
    setSeenLevel(level);
    if (listening && level !== undefined) {
      setHistory((h) => [...h.slice(1), Math.min(1, Math.max(0, level))]);
    }
  }

  const [seenListening, setSeenListening] = React.useState(listening);
  if (listening !== seenListening) {
    setSeenListening(listening);
    if (!listening) {
      setHistory(Array(BARS).fill(0));
    }
  }

  const [seenStartedAt, setSeenStartedAt] = React.useState(startedAt);
  if (startedAt !== seenStartedAt) {
    setSeenStartedAt(startedAt);
    setNow(startedAt ?? 0);
  }

  // The timer re-renders on each whole second, not every frame.
  React.useEffect(() => {
    if (!listening || startedAt === undefined) return;
    let timer = 0;
    const tick = () => {
      const t = Date.now();
      setNow(t);
      timer = window.setTimeout(tick, 1000 - ((t - startedAt) % 1000) + 5);
    };
    timer = window.setTimeout(tick, 0);
    return () => window.clearTimeout(timer);
  }, [listening, startedAt]);

  const seconds =
    startedAt === undefined
      ? 0
      : Math.max(0, Math.floor((now - startedAt) / 1000));
  const icon =
    status === "idle"
      ? "mic"
      : listening
        ? "stop"
        : transcribing
          ? "spin"
          : "off";
  const press = status === "idle" ? onStart : listening ? onStop : undefined;
  const showTranscript = listening && Boolean(transcript);

  return (
    <div className={`flex flex-col ${className}`} {...props}>
      {/* The words so far open above the bar, and fold away with it. */}
      <div
        aria-hidden={!showTranscript || undefined}
        className="grid"
        style={{
          gridTemplateRows: showTranscript ? "1fr" : "0fr",
          opacity: showTranscript ? 1 : 0,
          transition: reduced
            ? "none"
            : `grid-template-rows 380ms ${MORPH}, opacity ${showTranscript ? "300ms" : "160ms"} ${MORPH}`,
        }}
      >
        <div className="min-h-0 overflow-hidden">
          <p
            aria-live="polite"
            className="px-1 pb-2 text-[13px] leading-relaxed text-foreground"
          >
            {transcript ?? lastTranscript}
          </p>
        </div>
      </div>

      <div
        role={alert ? "alert" : undefined}
        className={`flex items-center ${end ? "flex-row-reverse" : ""}`}
      >
        {/* The one surface: a mic button that stretches into the listening bar and shrinks back. */}
        <div
          className={`flex shrink-0 items-center overflow-hidden rounded-full border border-border bg-background ${end ? "flex-row-reverse" : ""}`}
          style={{
            width: wide ? "100%" : 36,
            height: wide ? 44 : 36,
            // The button side keeps the tighter inset, whichever side that is.
            [end ? "paddingRight" : "paddingLeft"]: wide ? 5 : 1,
            [end ? "paddingLeft" : "paddingRight"]: wide ? 8 : 1,
            transition: reduced
              ? "none"
              : `width 520ms ${MORPH}, height 520ms ${MORPH}, padding 520ms ${MORPH}`,
          }}
        >
          <button
            type="button"
            aria-label={
              status === "idle"
                ? "Dictate"
                : listening
                  ? "Stop and transcribe"
                  : transcribing
                    ? "Transcribing"
                    : blocked
                      ? "Microphone blocked"
                      : "Didn’t catch that"
            }
            aria-disabled={!press || undefined}
            onClick={() => press?.()}
            className={`relative flex size-8 shrink-0 items-center justify-center rounded-full transition-[background-color,color,transform] duration-300 ${FOCUS} ${
              listening
                ? "bg-primary text-primary-foreground active:scale-95"
                : alert
                  ? "cursor-default bg-muted text-muted-foreground"
                  : transcribing
                    ? "cursor-default text-muted-foreground"
                    : "text-muted-foreground hover:bg-accent hover:text-foreground"
            }`}
          >
            <span
              aria-hidden="true"
              className="absolute inset-0 flex items-center justify-center"
              style={swap(icon === "mic", reduced)}
            >
              <Mic className="size-4" />
            </span>
            <span
              aria-hidden="true"
              className="absolute inset-0 flex items-center justify-center"
              style={swap(icon === "stop", reduced)}
            >
              <Square className="size-3" fill="currentColor" />
            </span>
            <span
              aria-hidden="true"
              className="absolute inset-0 flex items-center justify-center"
              style={swap(icon === "spin", reduced)}
            >
              <span
                className={`size-3.5 rounded-full border-[1.5px] border-border border-t-foreground/70 motion-reduce:animate-none ${transcribing ? "animate-spin" : ""}`}
              />
            </span>
            <span
              aria-hidden="true"
              className="absolute inset-0 flex items-center justify-center"
              style={swap(icon === "off", reduced)}
            >
              <MicOff className="size-4" />
            </span>
          </button>

          {/* The waveform while listening; it settles flat as "Transcribing" rises over it. */}
          <span
            className="relative mx-2 flex h-6 min-w-0 flex-1 items-center justify-center"
            style={appear(wide, reduced)}
          >
            <span
              aria-hidden="true"
              className="flex h-full items-center justify-center gap-[3px] overflow-hidden"
              style={appear(listening, reduced)}
            >
              {history.map((v, i) =>
                level === undefined ? (
                  <span
                    key={i}
                    className={`h-full w-[3px] shrink-0 origin-center rounded-full bg-foreground/70 motion-reduce:animate-none ${listening ? "animate-[ui-wave_1.1s_ease-in-out_infinite]" : ""}`}
                    style={{
                      animationDelay: `${(i % 7) * 90}ms`,
                      transform: "scaleY(0.35)",
                    }}
                  />
                ) : (
                  <span
                    key={i}
                    className="w-[3px] shrink-0 rounded-full bg-foreground/70 transition-[height] duration-100 motion-reduce:transition-none"
                    style={{
                      height: `${listening ? Math.max(12, v * 100) : 12}%`,
                    }}
                  />
                ),
              )}
            </span>
            <span
              aria-hidden="true"
              className={`absolute inset-y-0 flex items-center text-[13px] font-medium ${end ? "right-1" : "left-1"} ${transcribing ? SHEEN : ""}`}
              style={appear(transcribing, reduced)}
            >
              <TextMorph>
                {transcribing ? "Transcribing" : "Listening"}
              </TextMorph>
            </span>
          </span>

          {startedAt !== undefined && (
            <span
              aria-hidden="true"
              className="flex shrink-0 items-baseline font-mono text-[11.5px] tabular-nums text-muted-foreground"
              style={appear(listening, reduced)}
            >
              <NumberRoll value={Math.floor(seconds / 60)} duration={500} />:
              <NumberRoll
                value={seconds % 60}
                format={TWO_DIGITS}
                direction="up"
                duration={500}
              />
            </span>
          )}
          {onCancel && (
            <button
              type="button"
              aria-label="Cancel"
              inert={!listening}
              onClick={onCancel}
              className={`cursor-pointer ${end ? "mr-1" : "ml-1"} flex size-7 shrink-0 items-center justify-center rounded-full text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
              style={appear(listening, reduced)}
            >
              <X className="size-3.5" />
            </button>
          )}
        </div>

        {/* Blocked or not heard: the reason and the way back open beside the same circle. */}
        <div
          aria-hidden={!alert || undefined}
          className="grid min-w-0 flex-1"
          style={{
            // Folds by height, so while hidden it takes no room (and its text can't stack up in a sliver of width).
            gridTemplateRows: alert ? "1fr" : "0fr",
            ...appear(alert, reduced),
            transition: reduced
              ? "none"
              : `grid-template-rows 420ms ${MORPH}, ${alert ? `opacity 320ms ${MORPH} 120ms, filter 320ms ${MORPH} 120ms` : "opacity 140ms ease-out, filter 140ms ease-out"}`,
          }}
        >
          <div
            className={`flex min-h-0 min-w-0 items-center gap-3 overflow-hidden ${end ? "pr-3" : "pl-3"}`}
          >
            <span className="min-w-0 flex-1 text-[12.5px] leading-5">
              <span className="block font-medium text-foreground">
                <TextMorph animateWidth={false}>
                  {blocked ? "Microphone blocked" : "Didn’t catch that"}
                </TextMorph>
              </span>
              <span className="block text-muted-foreground">
                {errorText ??
                  (blocked
                    ? "Allow the microphone in your browser’s site settings, then try again."
                    : "Speak a little closer to the microphone.")}
              </span>
            </span>
            {onStart && (
              <button
                type="button"
                inert={!alert}
                onClick={onStart}
                className={`cursor-pointer flex shrink-0 items-center gap-1.5 rounded-full px-3 py-1 text-[12px] font-medium text-foreground shadow-[inset_0_0_0_1px_var(--border)] transition-colors hover:bg-accent ${FOCUS}`}
              >
                <RotateCcw aria-hidden="true" className="size-3" />
                Try again
              </button>
            )}
          </div>
        </div>
      </div>
      <span className="sr-only" role="status">
        {listening ? "Listening" : transcribing ? "Transcribing" : ""}
      </span>
    </div>
  );
}

"use client";

import * as React from "react";
import { ChevronDown } from "lucide-react";
import { NumberRoll } from "./number-roll";

/* ─────────────────────────────────────────────────────────
 * VOICE NOTE: a voice message you can read along with
 *
 *   arrive    the waveform grows out of a flat line, bar after
 *             bar, left to right
 *   play      the triangle splits and squares off into pause (one
 *             shape, two halves); bars fill as it plays and the
 *             time rolls up
 *   scrub     press anywhere on the waveform and drag: the bars
 *             under your finger swell like a lens and the time
 *             follows; let go and it carries on from there
 *   speed     1× rolls to 1.5× and 2×
 *   read      "Transcript" folds the words open under the note; a
 *             highlight glides from word to word as they're said,
 *             the words ahead wait in grey, and tapping a word
 *             plays from it
 *   end       it holds full for a beat, then the fill runs back
 *             and pause turns back into play
 *
 * Only one voice note plays at a time on a page.
 * ───────────────────────────────────────────────────────── */

export interface VoiceNoteWord {
  /** The word as written, punctuation included. */
  text: string;
  /** When it's said, in seconds. */
  start: number;
}

export interface VoiceNoteProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "children"
> {
  src: string;
  /** Loudness from 0 to 1, any length; worked out from the audio when left out. */
  peaks?: number[];
  /** Seconds, shown before the audio's own length is known. */
  duration?: number;
  transcript?: VoiceNoteWord[];
  defaultTranscriptOpen?: boolean;
  speeds?: number[];
  /** Mark it as not listened to yet. */
  unread?: boolean;
  /** What it is, for assistive tech, e.g. "Voice note from Sam". */
  label?: string;
  onPlay?: () => void;
  onEnded?: () => void;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const BAR = 3;
const GAP = 2;
const PLAY_EVENT = "cavemio:voice-note-play";

// Play and pause as the same two quads: the halves of a triangle, or two bars.
const SHAPES = {
  play: [
    "polygon(30% 12%, 58% 30%, 58% 70%, 30% 88%)",
    "polygon(58% 30%, 88% 50%, 88% 50%, 58% 70%)",
  ],
  pause: [
    "polygon(22% 14%, 42% 14%, 42% 86%, 22% 86%)",
    "polygon(58% 14%, 78% 14%, 78% 86%, 58% 86%)",
  ],
};

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const clock = (t: number) => {
  const s = Math.max(0, Math.round(t));
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
};

const EMPTY_PEAKS: number[] = [];

/** Squeeze or stretch the peaks to n bars, keeping each stretch's loudest moment. */
function resample(source: number[], n: number) {
  if (!source.length) return Array.from({ length: n }, () => 0);
  return Array.from({ length: n }, (_, i) => {
    const a = Math.floor((i * source.length) / n);
    const b = Math.max(a + 1, Math.floor(((i + 1) * source.length) / n));
    let top = 0;
    for (let k = a; k < b && k < source.length; k++)
      top = Math.max(top, source[k]);
    return top;
  });
}

/** Loudness peaks straight from the audio file, when none were given. */
async function decodePeaks(src: string, n = 128, signal?: AbortSignal) {
  const data = await (await fetch(src, { signal })).arrayBuffer();
  const Ctx =
    window.AudioContext ??
    (window as unknown as { webkitAudioContext: typeof AudioContext })
      .webkitAudioContext;
  const ctx = new Ctx();
  try {
    const audio = await ctx.decodeAudioData(data);
    const channel = audio.getChannelData(0);
    const size = channel.length / n;
    const rms = Array.from({ length: n }, (_, i) => {
      let sum = 0;
      const from = Math.floor(i * size);
      const to = Math.floor((i + 1) * size);
      for (let k = from; k < to; k++) sum += channel[k] * channel[k];
      return Math.sqrt(sum / Math.max(1, to - from));
    });
    const top = Math.max(...rms) || 1;
    return rms.map((v) => Math.min(1, (v / top) ** 0.7));
  } finally {
    void ctx.close();
  }
}

export function VoiceNote({
  src,
  peaks,
  duration: durationProp = 0,
  transcript,
  defaultTranscriptOpen = false,
  speeds = [1, 1.5, 2],
  unread = false,
  label = "Voice note",
  onPlay,
  onEnded,
  className = "",
  ...props
}: VoiceNoteProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const audioRef = React.useRef<HTMLAudioElement>(null);
  const waveRef = React.useRef<HTMLDivElement>(null);
  const wordsRef = React.useRef<HTMLParagraphElement>(null);
  const [duration, setDuration] = React.useState(durationProp);
  const [time, setTime] = React.useState(0);
  const [playing, setPlaying] = React.useState(false);
  const [rewinding, setRewinding] = React.useState(false);
  const [heard, setHeard] = React.useState(!unread);
  const [speed, setSpeed] = React.useState(0);
  const [open, setOpen] = React.useState(defaultTranscriptOpen);
  const [scrub, setScrub] = React.useState<number | null>(null);
  const [bars, setBars] = React.useState(0);
  const [decoded, setDecoded] = React.useState<number[] | null>(null);
  const [grown, setGrown] = React.useState(false);
  const [band, setBand] = React.useState({ x: 0, y: 0, w: 0, h: 0, on: false });
  const resume = React.useRef(false);
  const derived = React.useRef("");

  const source = React.useMemo(
    () => peaks ?? decoded ?? EMPTY_PEAKS,
    [peaks, decoded],
  );
  const heights = React.useMemo(() => resample(source, bars), [source, bars]);
  const length = duration || durationProp || 1;
  const shown = scrub !== null ? scrub * length : time;
  const progress = Math.min(1, shown / length);
  const filled = Math.floor(
    progress * bars + (playing || scrub !== null ? 0.5 : 0),
  );
  const spoken = transcript
    ? transcript.reduce((at, w, i) => (w.start <= shown + 0.05 ? i : at), -1)
    : -1;
  const reading = playing || scrub !== null || (time > 0 && !rewinding);
  const display = reading ? shown : length;

  // As many bars as fit the width.
  React.useLayoutEffect(() => {
    const wave = waveRef.current;
    if (!wave) return;
    const measure = () =>
      setBars(Math.max(12, Math.floor((wave.clientWidth + GAP) / (BAR + GAP))));
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(wave);
    return () => observer.disconnect();
  }, []);

  // No peaks given: read them off the audio itself.
  React.useEffect(() => {
    if (peaks) return;
    const controller = new AbortController();
    decodePeaks(src, 128, controller.signal)
      .then((p) => !controller.signal.aborted && setDecoded(p))
      .catch(() => {});
    return () => controller.abort();
  }, [src, peaks]);

  // The bars grow in once there's something to show.
  React.useEffect(() => {
    if (!source.length || !bars || grown) return;
    const frame = requestAnimationFrame(() => setGrown(true));
    return () => cancelAnimationFrame(frame);
  }, [source.length, bars, grown]);

  const pause = React.useCallback(() => {
    audioRef.current?.pause();
    setPlaying(false);
  }, []);

  const play = async (from?: number) => {
    const audio = audioRef.current;
    if (!audio) return;
    document.dispatchEvent(new CustomEvent(PLAY_EVENT, { detail: id }));
    if (from !== undefined) {
      audio.currentTime = from;
      setTime(from);
    }
    audio.playbackRate = speeds[speed] ?? 1;
    setRewinding(false);
    setPlaying(true);
    setHeard(true);
    try {
      await audio.play();
      onPlay?.();
    } catch {
      setPlaying(false);
    }
  };

  // Another voice note started: this one stops.
  React.useEffect(() => {
    const onOther = (e: Event) => {
      if ((e as CustomEvent<string>).detail !== id) pause();
    };
    document.addEventListener(PLAY_EVENT, onOther);
    return () => document.removeEventListener(PLAY_EVENT, onOther);
  }, [id, pause]);

  // While it plays, follow the audio, but only re-render when a bar, a second or a word changes.
  React.useEffect(() => {
    if (!playing) return;
    let frame = 0;
    const tick = () => {
      const audio = audioRef.current;
      if (audio) {
        const t = audio.currentTime;
        const word = transcript
          ? transcript.reduce((at, w, i) => (w.start <= t + 0.05 ? i : at), -1)
          : -1;
        const key = `${Math.floor((t / length) * bars)}|${Math.floor(t)}|${word}`;
        if (key !== derived.current) {
          derived.current = key;
          setTime(t);
        }
      }
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [playing, length, bars, transcript]);

  // At the end: hold full for a beat, then run the fill back to the start.
  const finish = () => {
    setPlaying(false);
    setTime(length);
    onEnded?.();
    if (audioRef.current) audioRef.current.currentTime = 0;
    setRewinding(true);
    if (reduced) return setTime(0);
    const begin = performance.now() + 500;
    const step = (now: number) => {
      const k = Math.min(1, Math.max(0, (now - begin) / 600));
      setTime(length * (1 - (1 - (1 - k) ** 3)));
      if (k < 1) requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
  };

  const fraction = (clientX: number) => {
    const r = waveRef.current?.getBoundingClientRect();
    return r ? Math.min(1, Math.max(0, (clientX - r.left) / r.width)) : 0;
  };
  const seek = (t: number) => {
    const next = Math.min(length, Math.max(0, t));
    if (audioRef.current) audioRef.current.currentTime = next;
    setRewinding(false);
    setTime(next);
  };

  // The current word's highlight, measured where the word sits.
  React.useLayoutEffect(() => {
    const el = wordsRef.current?.querySelector<HTMLElement>(
      `[data-w="${spoken}"]`,
    );
    setBand((b) =>
      el && open
        ? {
            x: el.offsetLeft,
            y: el.offsetTop,
            w: el.offsetWidth,
            h: el.offsetHeight,
            on: true,
          }
        : { ...b, on: false },
    );
  }, [spoken, open]);

  const lens = (i: number) => {
    if (scrub === null || reduced) return 1;
    const d = i - scrub * bars;
    return 1 + 0.5 * Math.exp(-(d * d) / 8);
  };

  return (
    <div
      role="group"
      aria-label={label}
      className={`@container w-full rounded-[20px] border border-border bg-card p-2 pr-2.5 text-card-foreground ${className}`}
      {...props}
    >
      <audio
        ref={audioRef}
        src={src}
        preload="metadata"
        onLoadedMetadata={(e) =>
          Number.isFinite(e.currentTarget.duration) &&
          setDuration(e.currentTarget.duration)
        }
        onEnded={finish}
        onPause={() =>
          scrub === null && !audioRef.current?.ended && setPlaying(false)
        }
      />

      {/* The button and the speed line up with the waveform, the time sits under it. */}
      <div className="flex items-start gap-2.5">
        <button
          type="button"
          aria-label={playing ? "Pause" : "Play"}
          onClick={() => (playing ? pause() : play())}
          className={`cursor-pointer relative -mt-0.5 flex size-9 shrink-0 items-center justify-center rounded-full bg-primary text-primary-foreground transition-transform active:scale-95 ${FOCUS}`}
        >
          <span aria-hidden="true" className="relative size-3.5">
            {[0, 1].map((half) => (
              <span
                key={half}
                className="absolute inset-0 bg-current"
                style={{
                  clipPath: (playing ? SHAPES.pause : SHAPES.play)[half],
                  transition: reduced ? "none" : `clip-path 320ms ${EASE}`,
                }}
              />
            ))}
          </span>
        </button>

        <div className="min-w-0 flex-1">
          <div
            ref={waveRef}
            role="slider"
            tabIndex={0}
            aria-label="Position"
            aria-valuemin={0}
            aria-valuemax={Math.round(length)}
            aria-valuenow={Math.round(shown)}
            aria-valuetext={`${clock(shown)} of ${clock(length)}`}
            onPointerDown={(e) => {
              if (e.button !== 0) return;
              e.currentTarget.setPointerCapture(e.pointerId);
              resume.current = playing;
              if (playing) audioRef.current?.pause();
              setScrub(fraction(e.clientX));
            }}
            onPointerMove={(e) =>
              scrub !== null && setScrub(fraction(e.clientX))
            }
            onPointerUp={() => {
              if (scrub === null) return;
              const t = scrub * length;
              setScrub(null);
              if (resume.current) play(t);
              else seek(t);
            }}
            onPointerCancel={() => {
              setScrub(null);
              if (resume.current) play();
            }}
            onKeyDown={(e) => {
              const moves: Record<string, number> = {
                ArrowLeft: -2,
                ArrowDown: -2,
                ArrowRight: 2,
                ArrowUp: 2,
              };
              if (e.key in moves) seek(shown + moves[e.key]);
              else if (e.key === "Home") seek(0);
              else if (e.key === "End") seek(length - 0.05);
              else return;
              e.preventDefault();
            }}
            className={`flex h-8 cursor-pointer touch-pan-y select-none items-center rounded-[6px] ${FOCUS}`}
            style={{ gap: GAP }}
          >
            {heights.map((h, i) => (
              <span
                key={i}
                aria-hidden="true"
                className={`shrink-0 rounded-full ${i < filled ? "bg-foreground" : "bg-muted-foreground/35"}`}
                style={{
                  width: BAR,
                  height: grown ? `${Math.max(3 / 32, h) * 100}%` : "3px",
                  transform: `scaleY(${lens(i)})`,
                  transition: reduced
                    ? "none"
                    : `height 520ms ${EASE} ${grown && !playing ? Math.min(i * 7, 420) : 0}ms, transform 160ms ${EASE}, background-color 160ms`,
                }}
              />
            ))}
          </div>
          <div className="mt-0.5 flex h-5 items-center gap-1.5 text-[11.5px] tabular-nums text-muted-foreground">
            <span aria-hidden="true">
              <NumberRoll
                value={Math.floor(Math.round(display) / 60)}
                duration={400}
              />
              :
              <NumberRoll
                value={Math.round(display) % 60}
                format={{ minimumIntegerDigits: 2 }}
                duration={400}
              />
            </span>
            <span
              aria-hidden="true"
              className="size-1.5 rounded-full bg-primary"
              style={{
                transform: heard ? "scale(0)" : "scale(1)",
                opacity: heard ? 0 : 1,
                transition: reduced
                  ? "none"
                  : `transform 300ms ${EASE}, opacity 300ms`,
              }}
            />
            {transcript && (
              <button
                type="button"
                aria-expanded={open}
                aria-controls={`${id}-transcript`}
                onClick={() => setOpen((o) => !o)}
                className={`cursor-pointer ml-auto inline-flex h-5 items-center gap-0.5 rounded-full px-1.5 text-[11.5px] text-muted-foreground transition-colors hover:text-foreground ${FOCUS}`}
              >
                Transcript
                <ChevronDown
                  aria-hidden="true"
                  className="size-3"
                  style={{
                    transform: open ? "rotate(180deg)" : "none",
                    transition: reduced ? "none" : `transform 300ms ${EASE}`,
                  }}
                />
              </button>
            )}
          </div>
        </div>

        <button
          type="button"
          aria-label={`Playback speed, ${speeds[speed]}×`}
          onClick={() => {
            const next = (speed + 1) % speeds.length;
            setSpeed(next);
            if (audioRef.current) audioRef.current.playbackRate = speeds[next];
          }}
          className={`cursor-pointer mt-1 inline-flex h-6 min-w-10 shrink-0 items-center justify-center rounded-full border border-border px-2 text-[11.5px] font-medium tabular-nums text-foreground transition-colors hover:bg-accent ${FOCUS}`}
        >
          <span aria-hidden="true">
            <NumberRoll
              value={speeds[speed]}
              format={{ maximumFractionDigits: 2 }}
              duration={450}
            />
            ×
          </span>
        </button>
      </div>

      {transcript && (
        <div
          id={`${id}-transcript`}
          className="grid"
          style={{
            gridTemplateRows: open ? "1fr" : "0fr",
            transition: reduced ? "none" : `grid-template-rows 420ms ${EASE}`,
          }}
        >
          <div className="overflow-hidden" inert={!open || undefined}>
            <p
              ref={wordsRef}
              className="relative mx-1 mb-1 mt-2 border-t border-border pt-2.5 text-[13px] leading-[1.6]"
              style={{
                opacity: open ? 1 : 0,
                transition: reduced ? "none" : `opacity 300ms ${EASE}`,
              }}
            >
              <span
                aria-hidden="true"
                className="absolute left-0 top-0 rounded-[5px] bg-primary/[0.12]"
                style={{
                  transform: `translate(${band.x - 3}px, ${band.y}px)`,
                  width: band.w + 6,
                  height: band.h,
                  opacity: band.on ? 1 : 0,
                  transition: reduced
                    ? "none"
                    : `transform 260ms ${EASE}, width 260ms ${EASE}, opacity 200ms`,
                }}
              />
              {transcript.map((w, i) => (
                <React.Fragment key={i}>
                  {i > 0 && " "}
                  <span
                    data-w={i}
                    onClick={() => play(w.start)}
                    className={`relative cursor-pointer rounded-[4px] transition-colors duration-200 hover:text-foreground ${
                      spoken === -1 || i <= spoken
                        ? "text-foreground"
                        : "text-muted-foreground"
                    }`}
                  >
                    {w.text}
                  </span>
                </React.Fragment>
              ))}
            </p>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * WAITLIST FIELD: an email field that becomes its own answer
 *
 *   idle     email and "Join the waitlist" in one pill
 *   invalid  the pill gives a small shake, its edge tints and
 *            a hint fades in underneath
 *   joining  the button stretches across the whole field and
 *            a light sweeps through it while the request runs
 *   joined   "You're on the list · #1,248": a check draws
 *            itself and the place number rolls up into view
 *   failed   the button folds back and asks you to try again
 *
 * Give it an onSubmit that returns a promise (resolve with
 * { position } to show the place in line).
 * ───────────────────────────────────────────────────────── */

export interface WaitlistResult {
  position?: number;
}

export interface WaitlistFieldProps extends Omit<
  React.FormHTMLAttributes<HTMLFormElement>,
  "onSubmit"
> {
  onSubmit: (
    email: string,
  ) => Promise<WaitlistResult | void> | WaitlistResult | void;
  /** Show the joined state straight away, e.g. for someone already on the list. */
  joined?: WaitlistResult | null;
  placeholder?: string;
  labels?: Partial<{
    idle: string;
    pending: string;
    success: string;
    error: string;
    invalid: string;
  }>;
}

type Status = "idle" | "pending" | "success" | "error";

const LABELS = {
  idle: "Join the waitlist",
  pending: "Joining",
  success: "You’re on the list",
  error: "Try again",
  invalid: "Enter a full email address",
};
const EASE = "cubic-bezier(0.16,1,0.3,1)";
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const shake = (el: HTMLElement | null) =>
  el?.animate(
    [
      { transform: "none" },
      { transform: "translateX(-5px)" },
      { transform: "translateX(5px)" },
      { transform: "translateX(-2px)" },
      { transform: "none" },
    ],
    { duration: 380, easing: "ease-out" },
  );

export function WaitlistField({
  onSubmit,
  joined,
  placeholder = "you@company.com",
  labels,
  className = "",
  ...props
}: WaitlistFieldProps) {
  const reduced = useReducedMotion();
  const text = { ...LABELS, ...labels };
  const id = React.useId();
  const [status, setStatus] = React.useState<Status>(
    joined ? "success" : "idle",
  );
  const [position, setPosition] = React.useState<number | undefined>(
    joined?.position,
  );
  const [email, setEmail] = React.useState("");
  const [invalid, setInvalid] = React.useState(false);
  const [restWidth, setRestWidth] = React.useState(0);
  const pillRef = React.useRef<HTMLDivElement>(null);
  const measureRef = React.useRef<HTMLSpanElement>(null);
  const inputRef = React.useRef<HTMLInputElement>(null);

  // How wide the button is at rest: measured from its label, so the stretch starts exactly from there.
  const restLabel = status === "error" ? text.error : text.idle;
  React.useLayoutEffect(() => {
    const el = measureRef.current;
    if (!el) return;
    const measure = () =>
      setRestWidth((w) => (w === el.offsetWidth ? w : el.offsetWidth));
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, [restLabel]);

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (status === "pending" || status === "success") return;
    const value = email.trim();
    if (!EMAIL.test(value)) {
      setInvalid(true);
      if (!reduced) shake(pillRef.current);
      inputRef.current?.focus();
      return;
    }
    setInvalid(false);
    setStatus("pending");
    try {
      const result = await onSubmit(value);
      setPosition(result ? result.position : undefined);
      setStatus("success");
    } catch {
      setStatus("error");
      if (!reduced) shake(pillRef.current);
    }
  };

  const covering = status === "pending" || status === "success";
  const transition = reduced
    ? "none"
    : `width 560ms ${EASE}, background-color 300ms ${EASE}`;

  return (
    <form
      noValidate
      onSubmit={submit}
      className={`w-full ${className}`}
      {...props}
    >
      <div
        ref={pillRef}
        className={`relative flex h-12 items-center rounded-full bg-background p-1 transition-[box-shadow] duration-300 ${
          invalid
            ? "shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_55%,transparent)]"
            : "shadow-[inset_0_0_0_1px_var(--border)] focus-within:shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--foreground)_30%,transparent)]"
        }`}
      >
        <label htmlFor={`${id}-email`} className="sr-only">
          Email address
        </label>
        <input
          ref={inputRef}
          id={`${id}-email`}
          type="email"
          inputMode="email"
          autoComplete="email"
          value={email}
          disabled={covering}
          aria-invalid={invalid || undefined}
          aria-describedby={invalid ? `${id}-hint` : undefined}
          onChange={(e) => {
            setEmail(e.target.value);
            if (invalid) setInvalid(false);
          }}
          placeholder={placeholder}
          className="h-full min-w-0 flex-1 bg-transparent pl-4 text-[14px] text-foreground outline-none placeholder:text-muted-foreground disabled:opacity-0"
          style={{
            paddingRight: restWidth + 12,
            transition: reduced ? "none" : "opacity 200ms ease-out",
          }}
        />

        {/* The one surface: rests as a button, stretches over the field, settles as the answer. */}
        <button
          type="submit"
          aria-disabled={covering || undefined}
          className="cursor-pointer disabled:cursor-default aria-disabled:cursor-default absolute bottom-1 right-1 top-1 flex items-center justify-center overflow-hidden rounded-full bg-primary px-4 text-[13px] font-medium text-primary-foreground outline-none focus-visible:ring-2 focus-visible:ring-ring/40 focus-visible:ring-offset-2 focus-visible:ring-offset-background active:scale-[0.98]"
          style={{
            width: covering ? "calc(100% - 8px)" : restWidth || undefined,
            transition,
          }}
        >
          {status === "pending" && (
            <span
              aria-hidden="true"
              className="pointer-events-none absolute inset-0 overflow-hidden rounded-full"
            >
              <span className="absolute inset-y-0 left-0 w-1/2 bg-gradient-to-r from-transparent via-white/25 to-transparent animate-[ui-scan_1.3s_ease-in-out_infinite] motion-reduce:hidden" />
            </span>
          )}
          <span className="relative flex items-center gap-2 whitespace-nowrap">
            <span
              aria-hidden="true"
              className="flex h-4 items-center justify-center overflow-hidden"
              style={{
                width: status === "success" ? 16 : 0,
                transition: reduced ? "none" : `width 380ms ${EASE}`,
              }}
            >
              <svg viewBox="0 0 16 16" fill="none" className="size-4 shrink-0">
                <path
                  d="M3.5 8.5 6.5 11.5 12.5 4.5"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  pathLength={1}
                  strokeDasharray={1}
                  style={{
                    strokeDashoffset: status === "success" ? 0 : 1,
                    transition:
                      status === "success" && !reduced
                        ? `stroke-dashoffset 460ms ${EASE} 260ms`
                        : "none",
                  }}
                />
              </svg>
            </span>
            <TextMorph>
              {status === "pending"
                ? text.pending
                : status === "success"
                  ? text.success
                  : restLabel}
            </TextMorph>
            {status === "success" && position !== undefined && (
              <span className="flex items-center gap-2 animate-[ui-fade-in_300ms_ease-out_200ms_both] motion-reduce:animate-none">
                <span aria-hidden="true" className="opacity-50">
                  ·
                </span>
                <span className="tabular-nums">
                  #
                  <NumberRoll
                    value={position}
                    from={Math.max(0, position - 36)}
                    duration={1100}
                  />
                </span>
              </span>
            )}
          </span>
        </button>

        {/* Measures the resting button, so its width can animate from an exact number. */}
        <span
          ref={measureRef}
          aria-hidden="true"
          className="invisible absolute whitespace-nowrap px-4 text-[13px] font-medium"
        >
          {restLabel}
        </span>
      </div>

      <p
        id={`${id}-hint`}
        className="mt-2 h-4 pl-4 text-[12px] text-red-600 transition-[opacity,transform] duration-300 dark:text-red-400"
        style={{
          opacity: invalid ? 1 : 0,
          transform: invalid ? "none" : "translateY(-3px)",
        }}
      >
        {invalid ? text.invalid : ""}
      </p>
      <span role="status" className="sr-only">
        {status === "success"
          ? `${text.success}${position !== undefined ? `, number ${position}` : ""}`
          : status === "error"
            ? "That didn’t go through. Try again."
            : ""}
      </span>
    </form>
  );
}

"use client";

import * as React from "react";
import { CopyButton } from "./copy-button";
import { Input } from "./input";
import { NumberRoll } from "./number-roll";
import { QUEUE_ART as ART, QUEUE_SIZE as SIZE } from "./queue-art";
import { StatusButton, type ActionStatus } from "./status-button";
import { TextMorph } from "./text-morph";
import {
  EASE_OUT,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * WAITLIST: your place in an actual line
 *
 *   line     a green door on the left of the lit stage and a
 *            line of illustrated people waiting for it; the
 *            spot at the end is a dashed outline that says You?
 *   join     an email and Join: you step into the line, lit,
 *            with your number over your head
 *   skip     every friend who joins through your link: you hop
 *            over the person ahead, they take your place and
 *            wander off, the line closes up and your number
 *            rolls down
 *   in       admitted: the door swings open and you walk in
 *
 * onJoin gets the email and returns your place; position (and
 * admitted) can come from your server afterwards, and every
 * drop in position plays a hop.
 * ───────────────────────────────────────────────────────── */

export interface WaitlistProps {
  /** Add the email; return their place in line and their invite link. Throw to say why not. */
  onJoin: (email: string) => Promise<{ position: number; link?: string }>;
  /** Their place after joining, from your server; each drop plays a hop. */
  position?: number;
  /** Friends who have joined through their link. */
  referrals?: number;
  /** Places each friend moves them up, for the line under the title. */
  perFriend?: number;
  /** Let in: the door opens and they walk through. */
  admitted?: boolean;
  /** What they're waiting for, in the copy. */
  product?: string;
  className?: string;
}

const mix = (color: string, amount: number, into = "transparent") =>
  `color-mix(in oklab, ${color} ${amount}%, ${into})`;
const PF = "var(--primary-foreground)";
const CARD: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, var(--card), ${mix("var(--card)", 95, "var(--foreground)")})`,
  boxShadow: `0 0 0 1px var(--border), inset 0 1px 0 ${mix("var(--background)", 85)}`,
};
/* The one lit surface, with a pavement of thin line slabs under the line. */
const STAGE: React.CSSProperties = {
  backgroundColor: "var(--primary)",
  backgroundImage: [
    `radial-gradient(50% 80% at 12% 70%, ${mix("oklch(0.85 0.12 80)", 26)} 0%, transparent 70%)`,
    `linear-gradient(175deg, transparent 40%, ${mix("black", 20)} 100%)`,
    `linear-gradient(90deg, ${mix(PF, 12)} 1px, transparent 1px)`,
  ].join(", "),
  backgroundSize: "auto, auto, 34px 18px",
  backgroundRepeat: "no-repeat, no-repeat, repeat-x",
  backgroundPosition: "0 0, 0 0, 0 100%",
  boxShadow: `inset 0 1px 0 ${mix(PF, 36)}, inset 0 0 0 1px ${mix(PF, 12)}`,
};
const LIT: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, ${mix(PF, 16)}, transparent 60%)`,
  boxShadow: `inset 0 1px 0 ${mix(PF, 32)}, inset 0 0 0 1px ${mix("black", 10)}`,
};

const W = 364;
const H = 176;
const GROUND = 164;
const PERSON_H = 90;
const DOOR_H = 124;
const SLOT0 = 122;
const GAP = 40;
const YOU_SLOT = 5;
const PEOPLE = ["p1", "p2", "p4", "p5", "p6"] as const;
type Who = (typeof PEOPLE)[number] | "p3";
const YOU: Who = "p3";
const slotX = (slot: number) => SLOT0 + slot * GAP;
const widthOf = (who: Who) => (SIZE[who].w / SIZE[who].h) * PERSON_H;

type Person = { id: number; who: Who; slot: number; leaving?: boolean };
const startLine = (): Person[] =>
  [0, 1, 2, 3, 4].map((i) => ({
    id: i,
    who: PEOPLE[i % PEOPLE.length],
    slot: i,
  }));

export function Waitlist({
  onJoin,
  position: positionProp,
  referrals = 0,
  perFriend = 50,
  admitted = false,
  product = "early access",
  className = "",
}: WaitlistProps) {
  const reduced = useInteractionReducedMotion();
  const baseId = React.useId();
  const [email, setEmail] = React.useState("");
  const [join, setJoin] = React.useState<{
    status: ActionStatus;
    error?: string;
  }>({ status: "idle" });
  const [mine, setMine] = React.useState<{
    position: number;
    link?: string;
  } | null>(null);
  const [line, setLine] = React.useState<Person[]>(startLine);
  const [youSlot, setYouSlot] = React.useState(YOU_SLOT);
  const [skipped, setSkipped] = React.useState(0);
  const nextId = React.useRef(5);
  const youRef = React.useRef<HTMLDivElement>(null);
  const timers = React.useRef<number[]>([]);
  React.useEffect(
    () => () => timers.current.forEach((t) => window.clearTimeout(t)),
    [],
  );

  const joined = mine !== null;
  const position = positionProp ?? mine?.position ?? 0;

  // a drop in position plays one hop per place-jump (up to three, however far it went)
  const [seen, setSeen] = React.useState(position);
  const [hops, setHops] = React.useState(0);
  if (seen !== position) {
    if (joined && seen > 0 && position < seen && !reduced)
      setHops((h) =>
        Math.min(
          3,
          h +
            Math.max(
              1,
              Math.min(
                3,
                Math.round((seen - position) / Math.max(1, perFriend)),
              ),
            ),
        ),
      );
    setSeen(position);
  }

  // one hop: you jump over the person ahead and swap places; they wander off; the line closes up behind a newcomer at the door
  React.useEffect(() => {
    if (hops <= 0) return;
    const ahead = line.find((p) => !p.leaving && p.slot === YOU_SLOT - 1);
    if (!ahead) return;
    youRef.current?.animate(
      [
        { transform: "translateY(0)" },
        { transform: "translateY(-34px)", offset: 0.45 },
        { transform: "translateY(0)" },
      ],
      { duration: 520, easing: "cubic-bezier(0.33, 0, 0.3, 1)" },
    );
    const t1 = window.setTimeout(() => {
      setYouSlot(YOU_SLOT - 1);
      setLine((l) =>
        l.map((p) => (p.id === ahead.id ? { ...p, slot: YOU_SLOT } : p)),
      );
      setSkipped((s) => s + 1);
    }, 0);
    const t2 = window.setTimeout(() => {
      const id = nextId.current++;
      setLine((l) => [
        // a newcomer at the door who doesn't look like the person they'll stand behind
        {
          id,
          who: PEOPLE.filter(
            (w) => w !== l.find((p) => p.slot === 0 && !p.leaving)?.who,
          )[id % (PEOPLE.length - 1)],
          slot: 0,
        },
        ...l
          .filter((p) => !p.leaving)
          .map((p) =>
            p.id === ahead.id
              ? { ...p, slot: YOU_SLOT + 2, leaving: true }
              : { ...p, slot: p.slot + 1 },
          ),
      ]);
      setYouSlot(YOU_SLOT);
    }, 620);
    const t3 = window.setTimeout(() => {
      setLine((l) => l.filter((p) => !p.leaving));
      setHops((h) => h - 1);
    }, 1250);
    timers.current.push(t1, t2, t3);
    // the line state is read once per hop
  }, [hops]);

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (join.status === "pending") return;
    if (!/^\S+@\S+\.\S+$/.test(email.trim())) {
      setJoin({ status: "error", error: "That doesn’t look like an email." });
      return;
    }
    setJoin({ status: "pending" });
    try {
      const res = await onJoin(email.trim());
      setJoin({ status: "success" });
      setMine(res);
      setSeen(positionProp ?? res.position);
    } catch (err) {
      setJoin({
        status: "error",
        error:
          err instanceof Error && err.message
            ? err.message
            : "Couldn’t add you. Try again.",
      });
    }
  };

  const mood = admitted
    ? "You’re in"
    : hops > 0
      ? "Excuse me, coming through"
      : skipped > 0
        ? `Skipped ${skipped} ahead`
        : joined
          ? "You’re in line"
          : "Join the line";
  const ease = `cubic-bezier(0.22, 1, 0.36, 1)`;
  const move = reduced
    ? "none"
    : `transform 560ms ${ease}, opacity 380ms ${EASE_OUT}`;

  return (
    <section
      aria-labelledby={`${baseId}-title`}
      className={`relative w-full max-w-[380px] rounded-[28px] p-2 text-card-foreground ${className}`}
      style={CARD}
    >
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 380px)" }}
      />
      <div className="@container w-full">
        <div
          className="relative overflow-clip rounded-[22px] text-primary-foreground"
          style={STAGE}
        >
          <Scene>
            {/* the door they're all waiting for */}
            {(["door", "doorOpen"] as const).map((d) => (
              <img
                key={d}
                src={ART[d]}
                alt=""
                draggable={false}
                className="pointer-events-none absolute max-w-none select-none"
                style={{
                  left: 10,
                  top: GROUND + 6 - DOOR_H,
                  height: DOOR_H,
                  width: (SIZE[d].w / SIZE[d].h) * DOOR_H,
                  opacity: (d === "doorOpen") === admitted ? 1 : 0,
                  transition: reduced ? "none" : "opacity 420ms ease-out",
                }}
              />
            ))}
            {line.map((p) => (
              <Figure
                key={p.id}
                who={p.who}
                x={slotX(p.slot)}
                style={{ opacity: p.leaving ? 0 : 1, transition: move }}
              />
            ))}
            {/* you: a dashed outline until you join, then lit, with your number */}
            <div
              className="absolute left-0 top-0"
              style={{
                transform: `translateX(${admitted ? 40 : slotX(youSlot)}px)`,
                opacity: admitted ? 0 : 1,
                transition: reduced
                  ? "none"
                  : `transform ${admitted ? 1400 : 520}ms ${ease}, opacity 600ms ease-in ${admitted ? 900 : 0}ms`,
              }}
            >
              <div
                className="absolute rounded-t-full border-[1.5px] border-dashed"
                style={{
                  left: -16,
                  top: GROUND - 64,
                  width: 32,
                  height: 64,
                  borderColor: mix(PF, 55),
                  opacity: joined ? 0 : 1,
                  transition: move,
                }}
              />
              <div
                ref={youRef}
                style={{
                  opacity: joined ? 1 : 0,
                  transform: joined ? "none" : "translateY(10px)",
                  transition: move,
                }}
              >
                <Figure who={YOU} x={0} lit />
              </div>
              <span
                className="absolute flex h-6 items-center whitespace-nowrap rounded-full px-2 text-[12px] font-semibold tabular-nums"
                style={{
                  left: 0,
                  top: GROUND - PERSON_H - 32,
                  transform: "translateX(-50%)",
                  background: PF,
                  color: "var(--primary)",
                }}
              >
                {joined ? (
                  <>
                    #<NumberRoll value={position} direction="down" />
                  </>
                ) : (
                  "You?"
                )}
              </span>
            </div>
          </Scene>
          <p className="absolute left-3.5 top-3 z-10 text-[12.5px] font-medium text-primary-foreground/85">
            <TextMorph>{mood}</TextMorph>
          </p>
        </div>

        {/* before joining: the form; after: your place and your link, in one surface */}
        <div className="grid">
          <div
            className="col-start-1 row-start-1 grid"
            style={{
              gridTemplateRows: joined ? "0fr" : "1fr",
              opacity: joined ? 0 : 1,
              pointerEvents: joined ? "none" : undefined,
              transition: reduced
                ? "none"
                : `grid-template-rows 460ms ${EASE_OUT}, opacity 220ms`,
            }}
          >
            <div className="min-w-0 overflow-clip" inert={joined}>
              <form className="px-3 pb-2 pt-3" onSubmit={submit} noValidate>
                <h2
                  id={`${baseId}-title`}
                  className="text-[15px] font-medium tracking-[-0.01em]"
                >
                  Join the waitlist
                </h2>
                <p className="mt-0.5 text-[12.5px] text-muted-foreground">
                  Get in line for {product}. Friends you invite move you up.
                </p>
                <div className="mt-3 flex flex-col gap-2 @[300px]:flex-row">
                  <Input
                    className="@[300px]:flex-1"
                    type="email"
                    aria-label="Email"
                    placeholder="you@company.com"
                    autoComplete="email"
                    value={email}
                    onValueChange={(v) => {
                      setEmail(v);
                      if (join.status === "error") setJoin({ status: "idle" });
                    }}
                    error={join.status === "error" ? join.error : undefined}
                  />
                  <StatusButton
                    type="submit"
                    status={join.status}
                    labels={{
                      idle: "Join",
                      pending: "Joining",
                      success: "Joined",
                      error: "Join",
                    }}
                    className="h-9 shrink-0 px-5 text-[13.5px]"
                    style={LIT}
                  />
                </div>
              </form>
            </div>
          </div>
          <div
            className="col-start-1 row-start-1 grid"
            style={{
              gridTemplateRows: joined ? "1fr" : "0fr",
              opacity: joined ? 1 : 0,
              pointerEvents: joined ? undefined : "none",
              transition: reduced
                ? "none"
                : `grid-template-rows 460ms ${EASE_OUT}, opacity 260ms 120ms`,
            }}
          >
            <div className="min-w-0 overflow-clip" inert={!joined}>
              <div className="px-3 pb-2 pt-3">
                <p className="text-[15px] font-medium tracking-[-0.01em]">
                  {admitted ? "You’re in" : "You’re on the list"}
                </p>
                <p className="mt-0.5 text-[12.5px] text-muted-foreground">
                  {admitted ? (
                    `Welcome to ${product}. Check your inbox for the way in.`
                  ) : (
                    <>
                      Each friend who joins moves you up {perFriend} places.{" "}
                      <span className="whitespace-nowrap tabular-nums text-foreground">
                        <NumberRoll value={referrals} />{" "}
                        {referrals === 1 ? "friend" : "friends"} so far.
                      </span>
                    </>
                  )}
                </p>
                {mine?.link && !admitted && (
                  <div className="mt-3 flex h-9 items-center gap-2 rounded-full border border-border bg-background pl-3.5 pr-1">
                    <span className="min-w-0 flex-1 truncate font-mono text-[12px] text-muted-foreground">
                      {mine.link}
                    </span>
                    <CopyButton
                      text={mine.link}
                      label="Copy link"
                      showLabel
                      size="sm"
                      variant="secondary"
                    />
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
      <span className="sr-only" role="status">
        {joined
          ? admitted
            ? "You’re in."
            : `You’re number ${position.toLocaleString("en-US")} in line.`
          : ""}
      </span>
    </section>
  );
}

/** The street, drawn at 364 × 176 and scaled to the stage. */
function Scene({ children }: { children: React.ReactNode }) {
  const host = React.useRef<HTMLDivElement>(null);
  const scene = React.useRef<HTMLDivElement>(null);
  React.useLayoutEffect(() => {
    const h = host.current;
    const s = scene.current;
    if (!h || !s) return;
    const fit = () =>
      s.style.setProperty("transform", `scale(${h.clientWidth / W})`);
    fit();
    const ro = new ResizeObserver(fit);
    ro.observe(h);
    return () => ro.disconnect();
  }, []);
  return (
    <div
      ref={host}
      aria-hidden="true"
      className="relative w-full"
      style={{ aspectRatio: `${W} / ${H}` }}
    >
      <div
        ref={scene}
        className="absolute left-0 top-0 origin-top-left"
        style={{ width: W, height: H }}
      >
        {children}
      </div>
    </div>
  );
}

/** One person, standing on the ground with their feet at x. */
function Figure({
  who,
  x,
  lit,
  style,
}: {
  who: Who;
  x: number;
  lit?: boolean;
  style?: React.CSSProperties;
}) {
  const w = widthOf(who);
  return (
    <div
      className="absolute left-0 top-0"
      style={{ transform: `translateX(${x}px)`, ...style }}
    >
      {lit && (
        <span
          className="absolute"
          style={{
            left: -34,
            top: GROUND - 10,
            width: 68,
            height: 18,
            background: `radial-gradient(closest-side, ${mix(PF, 45)}, transparent)`,
          }}
        />
      )}

      <img
        src={ART[who]}
        alt=""
        draggable={false}
        className="pointer-events-none absolute max-w-none select-none"
        style={{
          left: -w / 2,
          top: GROUND - PERSON_H,
          width: w,
          height: PERSON_H,
        }}
      />
    </div>
  );
}

export default Waitlist;

"use client";

import * as React from "react";
import { ArrowDown, ArrowUp, Delete, Eye, EyeOff, X } from "lucide-react";
import { CopyButton } from "./copy-button";
import { NumberRoll } from "./number-roll";
import { StatusButton, type ActionStatus } from "./status-button";
import { TextMorph } from "./text-morph";
import { Faces } from "./faces";
import { useRowMotion } from "./use-row-motion";
import {
  INTERACTION_FOCUS,
  INTERACTION_PRESS,
  interactionIcon,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * WALLET: a balance you can send from, in one surface
 *
 *   card      the balance sits on a card-shaped panel in your
 *             --primary, lit from its top corner and engraved
 *             with fine fine lines like a banknote; the figure
 *             rolls the way it changed, and hiding it folds the
 *             digits into dots
 *   send      the card itself turns into the transfer: the figure
 *             gives way to the amount you type (each new place
 *             rolls open), the actions and activity fold away and
 *             a keypad folds in, all in one surface
 *   sent      the button goes Sending → Sent with a drawn check,
 *             the card turns back, the balance rolls down by the
 *             amount and the new row slides into Activity
 *   request   the same surface asks instead; a request shows as a
 *             pending row until your server marks it paid, then
 *             "Requested" morphs into "Paid" and the balance rolls up
 *
 * The money is yours, not the card's: pass balance and
 * transactions, and do the transfer in onSend / onRequest. Resolve
 * and the card shows it sent; throw and it keeps the amount and
 * says why.
 * ───────────────────────────────────────────────────────── */

export interface WalletContact {
  id: string;
  name: string;
  /** Photo URL; initials on a tint from your chart colours when missing. */
  src?: string;
}

export interface WalletTransaction {
  id: string;
  title: string;
  date: Date | string | number;
  /** Signed, in major units: negative is money out, positive is money in. */
  amount: number;
  /** A request that hasn't been paid yet shows as pending. */
  status?: "pending" | "paid";
  /** Photo URL for the person; initials when missing. */
  src?: string;
  /** A merchant's logo or glyph, shown on a tinted tile instead of initials. */
  icon?: React.ReactNode;
}

export interface WalletTransfer {
  contact: WalletContact;
  /** In major units, always positive. */
  amount: number;
  note: string;
}

export interface WalletProps {
  /** The account holder, on the card. */
  name?: string;
  /** What the account is called, at the top of the card. */
  label?: string;
  /** The last four digits of the card or account, shown masked. */
  last4?: string;
  balance: number;
  contacts?: WalletContact[];
  /** Newest first. */
  transactions?: WalletTransaction[];
  /** Move the money; resolve when your server has it, throw an Error with a message to say why it failed. */
  onSend?: (transfer: WalletTransfer) => Promise<unknown>;
  /** Ask someone for money; resolve once the request exists (add it to transactions as pending). */
  onRequest?: (transfer: WalletTransfer) => Promise<unknown>;
  /** ISO 4217 code. */
  currency?: string;
  locale?: string;
  /** Shown with a copy button while requesting. */
  paymentLink?: string;
  /** Hide the balance (controlled). */
  hidden?: boolean;
  defaultHidden?: boolean;
  onHiddenChange?: (hidden: boolean) => void;
  /** Rows shown before "See all". */
  visibleTransactions?: number;
  className?: string;
}

type Mode = "home" | "send" | "request";

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const MORPH = 460;
const MAX_DIGITS = 9;
const NO_CONTACTS: WalletContact[] = [];
const NO_TRANSACTIONS: WalletTransaction[] = [];
const KEYS = [
  "1",
  "2",
  "3",
  "4",
  "5",
  "6",
  "7",
  "8",
  "9",
  ".",
  "0",
  "back",
] as const;

const subscribeNothing = () => () => {};
/** False on the server and while hydrating: text is formatted in one fixed locale until then, so the server's and the visitor's never disagree. */
const useHydrated = () =>
  React.useSyncExternalStore(
    subscribeNothing,
    () => true,
    () => false,
  );

/* Light is drawn from the theme's own colours: a lit corner of primary-foreground over --primary, a deeper
 * edge mixed toward black, and 1px edges (a highlight along the top, a faint ring all round). */
const mix = (color: string, amount: number, into = "transparent") =>
  `color-mix(in oklab, ${color} ${amount}%, ${into})`;
const PANEL: React.CSSProperties = {
  backgroundColor: "var(--primary)",
  backgroundImage: `radial-gradient(120% 110% at 0% 0%, ${mix("var(--primary-foreground)", 24)} 0%, transparent 52%), linear-gradient(165deg, transparent 35%, ${mix("black", 26)} 100%)`,
  boxShadow: `inset 0 1px 0 ${mix("var(--primary-foreground)", 38)}, inset 0 0 0 1px ${mix("var(--primary-foreground)", 12)}`,
};
const CARD: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, var(--card), ${mix("var(--card)", 95, "var(--foreground)")})`,
  boxShadow: `0 0 0 1px var(--border), inset 0 1px 0 ${mix("var(--background)", 85)}`,
};
const RAISED: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, var(--card), ${mix("var(--card)", 93, "var(--foreground)")})`,
  boxShadow: `inset 0 0 0 1px var(--border), inset 0 1px 0 ${mix("var(--background)", 90)}`,
};
const LIT: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, ${mix("var(--primary-foreground)", 16)}, transparent 60%)`,
  boxShadow: `inset 0 1px 0 ${mix("var(--primary-foreground)", 32)}, inset 0 0 0 1px ${mix("black", 10)}`,
};

/** A stable tint from your chart colours, so the same person always has the same colour. */
function tint(seed: string): React.CSSProperties {
  let h = 0;
  for (const c of seed) h = (h * 31 + c.charCodeAt(0)) >>> 0;
  const chart = `var(--chart-${(h % 5) + 1}, var(--primary))`;
  return {
    background: mix(chart, 20, "var(--card)"),
    color: mix(chart, 72, "var(--foreground)"),
    boxShadow: `inset 0 0 0 1px ${mix(chart, 26)}`,
  };
}

const initials = (name: string) =>
  name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((w) => w[0]?.toUpperCase())
    .join("");

/** A person (photo or initials) or a merchant (its glyph on a rounded tile), tinted the same way everywhere. */
function Face({
  name,
  src,
  icon,
  size,
}: {
  name: string;
  src?: string;
  icon?: React.ReactNode;
  size: number;
}) {
  return (
    <span
      aria-hidden="true"
      className={`relative flex shrink-0 select-none items-center justify-center overflow-hidden font-medium ${icon ? "rounded-[12px]" : "rounded-full"}`}
      style={{
        width: size,
        height: size,
        fontSize: Math.round(size * 0.36),
        ...tint(name),
      }}
    >
      {icon ? (
        <span className="flex [&_svg]:size-[46%] size-full items-center justify-center">
          {icon}
        </span>
      ) : (
        initials(name)
      )}
      {src && (
        <img
          src={src}
          alt=""
          decoding="async"
          className="absolute inset-0 size-full object-cover"
        />
      )}
    </span>
  );
}

/** Fine fine lines engraved into the card, rippling out from its top corner. */
function Engraving() {
  return (
    <svg
      aria-hidden="true"
      viewBox="0 0 320 200"
      preserveAspectRatio="xMaxYMin slice"
      className="pointer-events-none absolute inset-0 size-full text-primary-foreground"
      fill="none"
      stroke="currentColor"
    >
      {Array.from({ length: 16 }, (_, i) => (
        <ellipse
          key={i}
          cx="316"
          cy="-6"
          rx={34 + i * 15}
          ry={20 + i * 9.5}
          transform="rotate(-16 316 -6)"
          strokeWidth="0.75"
          strokeOpacity={i % 4 === 0 ? 0.13 : 0.07}
        />
      ))}
    </svg>
  );
}

/** The card's two faces in one place: the balance and the transfer, sliding past each other. */
function CardFaces({
  composing,
  reduced,
  ready,
  children,
}: {
  composing: boolean;
  reduced: boolean;
  ready: boolean;
  children: [React.ReactNode, React.ReactNode];
}) {
  const face = (on: boolean, side: number): React.CSSProperties => ({
    opacity: on ? 1 : 0,
    transform: on || reduced ? "none" : `translateX(${side * 18}px)`,
    filter: on || reduced ? "none" : "blur(4px)",
    transition: !ready
      ? "none"
      : reduced
        ? "opacity 160ms ease-out"
        : on
          ? `opacity 320ms ${EASE} 90ms, transform ${MORPH}ms ${EASE}, filter 320ms ${EASE} 90ms`
          : `opacity 140ms ease-out, transform ${MORPH}ms ${EASE}, filter 200ms ease-out`,
  });
  return (
    <>
      <div
        inert={composing || undefined}
        aria-hidden={composing || undefined}
        className={`absolute inset-0 flex flex-col ${composing ? "pointer-events-none" : ""}`}
        style={face(!composing, -1)}
      >
        {children[0]}
      </div>
      <div
        inert={!composing || undefined}
        aria-hidden={!composing || undefined}
        className={`absolute inset-0 flex flex-col ${composing ? "" : "pointer-events-none"}`}
        style={face(composing, 1)}
      >
        {children[1]}
      </div>
    </>
  );
}

/** A typed amount kept as a string ("12.5"), so keys never meet floating point. */
function press(raw: string, key: string) {
  if (key === "back") return raw.slice(0, -1);
  if (key === ".") return raw.includes(".") ? raw : `${raw || "0"}.`;
  if (raw.includes(".")) return raw.split(".")[1].length >= 2 ? raw : raw + key;
  if (raw === "0") return key;
  return raw.length >= MAX_DIGITS ? raw : raw + key;
}

function useMoney(locale: string | undefined, currency: string) {
  return React.useMemo(() => {
    const full = new Intl.NumberFormat(locale, { style: "currency", currency });
    const signed = new Intl.NumberFormat(locale, {
      style: "currency",
      currency,
      signDisplay: "exceptZero",
    });
    const decimal =
      new Intl.NumberFormat(locale)
        .formatToParts(1.5)
        .find((p) => p.type === "decimal")?.value ?? ".";
    const day = new Intl.DateTimeFormat(locale, {
      month: "short",
      day: "numeric",
    });
    const time = new Intl.DateTimeFormat(locale, {
      hour: "2-digit",
      minute: "2-digit",
    });
    return {
      format: (n: number) => full.format(n),
      signed: (n: number) => signed.format(n).replace("-", "−"),
      decimal,
      when: (d: Date | string | number) => {
        const date = new Date(d);
        return `${day.format(date)} · ${time.format(date)}`;
      },
    };
  }, [locale, currency]);
}

export function Wallet({
  name = "You",
  label: accountLabel = "Balance",
  last4,
  balance,
  contacts = NO_CONTACTS,
  transactions = NO_TRANSACTIONS,
  onSend,
  onRequest,
  currency = "USD",
  locale,
  paymentLink,
  hidden: hiddenProp,
  defaultHidden = false,
  onHiddenChange,
  visibleTransactions = 2,
  className = "",
}: WalletProps) {
  const reduced = useInteractionReducedMotion();
  const hydrated = useHydrated();
  const money = useMoney(locale ?? (hydrated ? undefined : "en-US"), currency);
  const baseId = React.useId();

  const [mode, setMode] = React.useState<Mode>("home");
  const [contactId, setContactId] = React.useState<string | null>(null);
  const [raw, setRaw] = React.useState("");
  const [note, setNote] = React.useState("");
  const [status, setStatus] = React.useState<ActionStatus>("idle");
  const [error, setError] = React.useState<string | null>(null);
  const [said, setSaid] = React.useState("");
  const [expanded, setExpanded] = React.useState(false);
  const [ownHidden, setOwnHidden] = React.useState(defaultHidden);
  const hidden = hiddenProp ?? ownHidden;

  // What the card shows lags the props while a transfer is on screen, so the balance rolls and the new row
  // arrives where you can see them: once the card has turned back.
  const [shown, setShown] = React.useState({ balance, transactions });
  const [ready, setReady] = React.useState(false);
  const returning = React.useRef(false);

  const composeRef = React.useRef<HTMLDivElement>(null);
  const sendRef = React.useRef<HTMLButtonElement>(null);
  const listRef = React.useRef<HTMLUListElement>(null);
  const ghostRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setReady(true));
    return () => cancelAnimationFrame(frame);
  }, []);

  React.useEffect(() => {
    if (mode !== "home") return;
    const delay = returning.current && !reduced ? MORPH * 0.6 : 0;
    returning.current = false;
    const timer = window.setTimeout(
      () =>
        setShown((p) =>
          p.balance === balance && p.transactions === transactions
            ? p
            : { balance, transactions },
        ),
      delay,
    );
    return () => window.clearTimeout(timer);
  }, [mode, balance, transactions, reduced]);

  // Focus follows the surface: into the transfer when it opens, back to Send when it closes.
  React.useEffect(() => {
    if (!ready || mode === "home") return;
    composeRef.current?.focus({ preventScroll: true });
  }, [mode, ready]);

  const composing = mode !== "home";
  const sending = mode === "send";
  const contact = contacts.find((c) => c.id === contactId) ?? null;
  const first = contact?.name.split(" ")[0] ?? "";
  const amount = Number(raw || "0");
  const cents = Math.round(amount * 100);
  const over = sending && cents > Math.round(shown.balance * 100);
  const valid = Boolean(contact) && cents > 0 && !over;
  const busy = status === "pending" || status === "success";
  const decimals = raw.includes(".") ? raw.split(".")[1].length : 0;

  const rows = expanded
    ? shown.transactions
    : shown.transactions.slice(0, visibleTransactions);
  const ranks = React.useMemo(
    () => new Map(shown.transactions.map((t, i) => [t.id, i])),
    [shown.transactions],
  );
  useRowMotion(listRef, { reduced, ranks, ghosts: ghostRef });

  const open = (next: Mode, id: string | null = null) => {
    setMode(next);
    setContactId(id);
    setRaw("");
    setNote("");
    setStatus("idle");
    setError(null);
    setSaid("");
  };

  const close = (focusSend = true) => {
    if (status === "pending") return;
    returning.current = true;
    setMode("home");
    setStatus("idle");
    setError(null);
    if (focusSend)
      window.setTimeout(
        () => sendRef.current?.focus({ preventScroll: true }),
        reduced ? 0 : MORPH,
      );
  };

  const key = (k: string) => {
    if (busy) return;
    setError(null);
    if (status === "error") setStatus("idle");
    setRaw((r) => press(r, k));
  };

  const submit = async () => {
    if (!valid || !contact || busy) return;
    const transfer = { contact, amount: cents / 100, note: note.trim() };
    const run = sending ? onSend : onRequest;
    setStatus("pending");
    setError(null);
    try {
      await run?.(transfer);
      setStatus("success");
      setSaid(
        sending
          ? `Sent ${money.format(transfer.amount)} to ${contact.name}`
          : `Asked ${contact.name} for ${money.format(transfer.amount)}`,
      );
      window.setTimeout(() => close(), reduced ? 900 : 1100);
    } catch (e) {
      setStatus("error");
      setError(
        e instanceof Error && e.message
          ? e.message
          : "That didn't go through. Try again.",
      );
    }
  };

  const onKeyDown = (e: React.KeyboardEvent) => {
    if (!composing) return;
    if (e.key === "Escape") {
      e.preventDefault();
      close();
      return;
    }
    if ((e.target as HTMLElement).tagName === "INPUT") {
      if (e.key === "Enter") {
        e.preventDefault();
        void submit();
      }
      return;
    }
    if (e.metaKey || e.ctrlKey || e.altKey) return;
    if (/^[0-9]$/.test(e.key) || e.key === "." || e.key === ",") {
      e.preventDefault();
      key(e.key === "," ? "." : e.key);
    } else if (e.key === "Backspace") {
      e.preventDefault();
      key("back");
    } else if (
      e.key === "Enter" &&
      (e.target as HTMLElement).tagName !== "BUTTON"
    ) {
      e.preventDefault();
      void submit();
    }
  };

  const action = !contact
    ? sending
      ? "Choose who to pay"
      : "Choose who to ask"
    : cents === 0
      ? "Enter an amount"
      : over
        ? "More than your balance"
        : `${sending ? "Send" : "Request"} ${money.format(cents / 100)}`;

  const sub =
    error ??
    (over
      ? "That’s more than you have."
      : sending
        ? `Available ${hidden ? "••••" : money.format(shown.balance)}`
        : contact
          ? `${first} gets a request to pay you`
          : "They’ll get a request to pay you");

  const onCard = `cursor-pointer ${INTERACTION_PRESS} focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary-foreground/70`;
  const big = `inline-flex h-12 flex-1 cursor-pointer items-center justify-center gap-2 rounded-full text-[15px] font-medium ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`;
  const figure =
    "text-[clamp(38px,12.5cqw,52px)] font-medium leading-none tracking-[-0.045em] tabular-nums";

  return (
    <section
      aria-label="Wallet"
      onKeyDown={onKeyDown}
      className={`w-full max-w-[400px] rounded-[32px] p-2.5 text-card-foreground ${className}`}
      style={CARD}
    >
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 400px)" }}
      />
      <div className="@container w-full">
        {/* The one colour surface: a card that turns into the transfer. */}
        <div
          className="relative aspect-[1.6/1] overflow-clip rounded-[24px] text-primary-foreground"
          style={PANEL}
        >
          <Engraving />
          <CardFaces composing={composing} reduced={reduced} ready={ready}>
            <div className="flex h-full flex-col justify-between px-5 pb-[18px] pt-4">
              <div className="flex items-center justify-between gap-3">
                <span className="truncate text-[13.5px] font-medium tracking-[-0.01em] text-primary-foreground/90">
                  {accountLabel}
                </span>
                <button
                  type="button"
                  aria-label={hidden ? "Show balance" : "Hide balance"}
                  aria-pressed={hidden}
                  onClick={() => {
                    if (hiddenProp === undefined) setOwnHidden(!hidden);
                    onHiddenChange?.(!hidden);
                  }}
                  className={`-mr-1.5 relative flex size-8 items-center justify-center rounded-full text-primary-foreground/80 hover:bg-primary-foreground/10 hover:text-primary-foreground ${onCard}`}
                >
                  <Eye
                    aria-hidden="true"
                    className="absolute size-[17px]"
                    style={interactionIcon(!hidden, reduced)}
                  />
                  <EyeOff
                    aria-hidden="true"
                    className="absolute size-[17px]"
                    style={interactionIcon(hidden, reduced)}
                  />
                </button>
              </div>

              <div>
                <p className="text-[12.5px] text-primary-foreground/65">
                  Available
                </p>
                <p className={`mt-1.5 grid ${figure}`}>
                  <span className="sr-only">
                    {hidden ? "Balance hidden" : money.format(shown.balance)}
                  </span>
                  <span
                    aria-hidden="true"
                    className="[grid-area:1/1]"
                    style={{
                      opacity: hidden ? 0 : 1,
                      filter: hidden && !reduced ? "blur(6px)" : "none",
                      transition: reduced
                        ? "opacity 160ms"
                        : `opacity 260ms ${EASE}, filter 260ms ${EASE}`,
                    }}
                  >
                    <NumberRoll
                      value={shown.balance}
                      locales={locale}
                      format={{ style: "currency", currency }}
                      duration={1100}
                    />
                  </span>
                  <span
                    aria-hidden="true"
                    className="self-center text-[0.6em] tracking-[0.18em] [grid-area:1/1]"
                    style={{
                      opacity: hidden ? 1 : 0,
                      filter: hidden || reduced ? "none" : "blur(6px)",
                      transition: reduced
                        ? "opacity 160ms"
                        : `opacity 260ms ${EASE} 80ms, filter 260ms ${EASE} 80ms`,
                    }}
                  >
                    ••••••
                  </span>
                </p>
              </div>

              <div className="flex items-center justify-between gap-3 text-[13px] text-primary-foreground/80">
                <span className="truncate font-medium">{name}</span>
                {last4 && (
                  <span className="shrink-0 font-mono text-[12.5px] tracking-[0.14em] text-primary-foreground/70">
                    •••• {last4}
                  </span>
                )}
              </div>
            </div>

            <div
              ref={composeRef}
              tabIndex={-1}
              role="group"
              aria-labelledby={`${baseId}-title`}
              className="flex h-full flex-col justify-between px-5 pb-[18px] pt-4 outline-none"
            >
              <div className="flex items-center justify-between gap-3">
                <h3
                  id={`${baseId}-title`}
                  className="truncate text-[13.5px] font-medium tracking-[-0.01em] text-primary-foreground/90"
                >
                  <TextMorph>{`${sending ? "Send" : "Request"}${contact ? (sending ? ` to ${first}` : ` from ${first}`) : ""}`}</TextMorph>
                </h3>
                <button
                  type="button"
                  aria-label="Cancel"
                  onClick={() => close()}
                  className={`-mr-1.5 flex size-8 items-center justify-center rounded-full text-primary-foreground/80 hover:bg-primary-foreground/10 hover:text-primary-foreground ${onCard}`}
                >
                  <X aria-hidden="true" className="size-[17px]" />
                </button>
              </div>
              <div>
                <p className="text-[12.5px] text-primary-foreground/65">
                  {sending ? "Amount" : "Asking for"}
                </p>
                <p
                  className={`mt-1.5 ${figure} ${raw ? "" : "text-primary-foreground/45"}`}
                  style={{ transition: "color 200ms" }}
                >
                  <span className="sr-only">{`Amount ${money.format(amount)}`}</span>
                  <span aria-hidden="true">
                    <NumberRoll
                      value={amount}
                      locales={locale}
                      format={{
                        style: "currency",
                        currency,
                        minimumFractionDigits: decimals,
                        maximumFractionDigits: 2,
                      }}
                      suffix={raw.endsWith(".") ? money.decimal : ""}
                      duration={520}
                    />
                  </span>
                </p>
              </div>
              <p
                role={error || over ? "alert" : undefined}
                className="truncate text-[13px] text-primary-foreground/80"
              >
                {sub}
              </p>
            </div>
          </CardFaces>
        </div>

        {/* Request and Send, folded away while the card is the transfer. */}
        <div
          inert={composing || undefined}
          className="grid"
          style={{
            gridTemplateRows: composing ? "0fr" : "1fr",
            opacity: composing ? 0 : 1,
            transition: reduced
              ? "opacity 160ms"
              : `grid-template-rows ${MORPH}ms ${EASE}, opacity ${composing ? 140 : 320}ms ${EASE}`,
          }}
        >
          <div className="min-h-0 overflow-clip">
            <div className="flex gap-2 px-0.5 pt-2.5">
              <button
                type="button"
                onClick={() => open("request")}
                className={`${big} text-foreground`}
                style={RAISED}
              >
                <ArrowDown aria-hidden="true" className="size-[18px]" />
                Request
              </button>
              <button
                ref={sendRef}
                type="button"
                onClick={() => open("send")}
                className={`${big} bg-primary text-primary-foreground`}
                style={LIT}
              >
                <ArrowUp aria-hidden="true" className="size-[18px]" />
                Send
              </button>
            </div>
          </div>
        </div>

        {contacts.length > 0 && (
          <div className="px-3 pt-5">
            <p className="text-[12.5px] text-muted-foreground">
              <TextMorph>
                {composing ? (sending ? "To" : "From") : "Send again"}
              </TextMorph>
            </p>
            <div
              role={composing ? "radiogroup" : "group"}
              aria-label={
                composing
                  ? sending
                    ? "Who to pay"
                    : "Who to ask"
                  : "Send again"
              }
              className="-mx-1 mt-2.5 flex gap-1 overflow-x-auto px-1 pb-1 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
            >
              {contacts.map((c) => {
                const on = composing && c.id === contactId;
                return (
                  <button
                    key={c.id}
                    type="button"
                    role={composing ? "radio" : undefined}
                    aria-checked={composing ? on : undefined}
                    aria-label={composing ? c.name : `Send to ${c.name}`}
                    onClick={() => {
                      if (!composing) return open("send", c.id);
                      if (busy) return;
                      setContactId(c.id);
                      setError(null);
                      if (status === "error") setStatus("idle");
                    }}
                    className={`flex min-w-[56px] max-w-[66px] flex-1 cursor-pointer flex-col items-center gap-1.5 rounded-[14px] py-1.5 ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`}
                  >
                    <span
                      className="flex rounded-full"
                      style={{
                        boxShadow: on
                          ? "0 0 0 2px var(--card), 0 0 0 3.5px var(--primary)"
                          : "0 0 0 2px var(--card), 0 0 0 2px transparent",
                        opacity: composing && contactId && !on ? 0.45 : 1,
                        transition: reduced
                          ? "none"
                          : `box-shadow 260ms ${EASE}, opacity 260ms ${EASE}`,
                      }}
                    >
                      <Face name={c.name} src={c.src} size={44} />
                    </span>
                    <span
                      className={`max-w-full truncate text-[12px] ${on ? "font-medium text-foreground" : "text-muted-foreground"}`}
                    >
                      {c.name.split(" ")[0]}
                    </span>
                  </button>
                );
              })}
            </div>
          </div>
        )}

        <Faces active={composing ? 1 : 0} reduced={reduced} ready={ready}>
          <div className="px-3 pb-1.5 pt-3">
            <div className="flex h-7 items-center justify-between">
              <h3 className="text-[12.5px] font-normal text-muted-foreground">
                Activity
              </h3>
              {shown.transactions.length > visibleTransactions && (
                <button
                  type="button"
                  aria-expanded={expanded}
                  onClick={() => setExpanded((v) => !v)}
                  className={`-mr-2 cursor-pointer rounded-full px-2 py-1 text-[12.5px] text-foreground hover:bg-accent ${INTERACTION_FOCUS}`}
                >
                  <TextMorph>{expanded ? "Show less" : "See all"}</TextMorph>
                </button>
              )}
            </div>
            <div className="relative">
              <div
                ref={ghostRef}
                aria-hidden="true"
                className="pointer-events-none absolute inset-0"
              />
              {rows.length ? (
                <ul ref={listRef} className="relative">
                  {rows.map((t) => {
                    const pending = t.status === "pending";
                    return (
                      <li
                        key={t.id}
                        data-row-id={t.id}
                        className="flex items-center gap-3 border-t border-border py-3 first:border-t-0"
                      >
                        <Face
                          name={t.title.replace(/^(To|From)\s+/, "")}
                          src={t.src}
                          icon={t.icon}
                          size={42}
                        />
                        <span className="min-w-0 flex-1">
                          <span className="block truncate text-[14.5px] font-medium tracking-[-0.01em] text-foreground">
                            {t.title}
                          </span>
                          <span
                            className="block text-[12.5px] text-muted-foreground"
                            suppressHydrationWarning
                          >
                            {money.when(t.date)}
                          </span>
                        </span>
                        <span className="flex flex-col items-end">
                          <span
                            className={`text-[15px] font-medium tracking-[-0.01em] tabular-nums ${pending ? "text-muted-foreground" : t.amount > 0 ? "text-emerald-600 dark:text-emerald-400" : "text-foreground"}`}
                            style={{ transition: "color 300ms" }}
                          >
                            {money.signed(t.amount)}
                          </span>
                          {t.status && (
                            <span className="text-[11.5px] text-muted-foreground">
                              <TextMorph>
                                {pending ? "Requested" : "Paid"}
                              </TextMorph>
                            </span>
                          )}
                        </span>
                      </li>
                    );
                  })}
                </ul>
              ) : (
                <p className="py-6 text-center text-[13px] text-muted-foreground">
                  No activity yet
                </p>
              )}
            </div>
          </div>

          <div className="px-1 pb-1 pt-4">
            <input
              value={note}
              onChange={(e) => setNote(e.target.value)}
              maxLength={60}
              disabled={busy}
              placeholder={sending ? "What’s it for?" : "Add a note"}
              aria-label="Note (optional)"
              enterKeyHint={sending ? "send" : "done"}
              className="h-11 w-full rounded-full border border-border bg-transparent px-4 text-[14px] text-foreground outline-none transition-[border-color,box-shadow] placeholder:text-muted-foreground focus:border-ring focus:ring-2 focus:ring-ring/20 max-sm:text-[16px]"
            />
            <div className="mt-2.5 grid grid-cols-3 gap-1.5">
              {KEYS.map((k) => (
                <button
                  key={k}
                  type="button"
                  tabIndex={-1}
                  aria-label={
                    k === "back" ? "Delete" : k === "." ? "Decimal point" : k
                  }
                  onClick={() => key(k)}
                  className={`flex h-12 cursor-pointer items-center justify-center rounded-[16px] text-[20px] font-medium tabular-nums text-foreground hover:bg-accent active:bg-accent ${INTERACTION_PRESS} [-webkit-tap-highlight-color:transparent]`}
                >
                  {k === "back" ? (
                    <Delete
                      aria-hidden="true"
                      className="size-5 text-muted-foreground"
                    />
                  ) : k === "." ? (
                    money.decimal
                  ) : (
                    k
                  )}
                </button>
              ))}
            </div>
            <StatusButton
              status={status}
              labels={{
                idle: action,
                pending: sending ? "Sending" : "Requesting",
                success: sending ? "Sent" : "Requested",
                error: "Try again",
              }}
              disabled={!valid && status !== "error" && !busy}
              onClick={() => void submit()}
              className="mt-2.5 h-12 w-full text-[15px] disabled:opacity-50"
              style={status === "error" ? undefined : LIT}
            />
            {!sending && paymentLink && (
              <div className="mt-2 flex items-center justify-center gap-1 text-[12.5px] text-muted-foreground">
                Or share
                <CopyButton
                  text={paymentLink}
                  label={paymentLink}
                  copiedLabel="Link copied"
                  showLabel
                  size="sm"
                />
              </div>
            )}
          </div>
        </Faces>

        <span className="sr-only" role="status">
          {said}
        </span>
      </div>
    </section>
  );
}

export default Wallet;

"use client";

import * as React from "react";
import { ChevronDown, ChevronRight, Search } from "lucide-react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * WEB RESEARCH: watch the agent search and read
 *
 *   searching  "Searching" shimmers; the live query types in
 *   reading    the label morphs to "Reading" and "7 sites"
 *              rolls up; each page drops its icon into the
 *              stack (the oldest folds away) while its title
 *              rises in underneath as the last one lifts off
 *   done       the line morphs into "3 searches · 9 sources":
 *              counts roll, words morph, the title row folds
 *              shut and a chevron opens in; open it for the list
 *   error      "Search failed", keeping whatever was found
 *   cancelled  "Stopped after 2 searches"
 *   trail      opened, each search is a row on a thin line trail
 *              with its count; a search on one site wears that
 *              site's mark, and the pages it found sit under it
 *              as overlapping marks that fold open into links
 *
 * Feed it the queries and sources as they arrive (tool calls
 * and source parts from the AI SDK); it animates the rest.
 * ───────────────────────────────────────────────────────── */

export type ResearchStatus =
  "searching" | "reading" | "done" | "error" | "cancelled";

export interface ResearchSource {
  url: string;
  title?: string;
  /** An icon URL; without one, a tinted monogram of the site. */
  favicon?: string;
  /** Which search found it (its index in queries), so the trail can group pages under their search. */
  query?: number;
}

export interface ResearchQuery {
  text: string;
  /** A search on one site, e.g. "threadly.com": the row wears that site's mark and reads "Searched Threadly for ...". */
  site?: string;
  /** An icon URL for that site. */
  siteIcon?: string;
  /** How many it found. */
  results?: number;
  /** The word after the count, e.g. "posts". Defaults to "results". */
  resultLabel?: string;
}

export interface WebResearchProps extends React.HTMLAttributes<HTMLDivElement> {
  status: ResearchStatus;
  /** Queries so far, as text or with their site and count; the last one is live while searching. */
  queries: (string | ResearchQuery)[];
  /** Pages read so far, in order. */
  sources: ResearchSource[];
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
}

const EASE = "cubic-bezier(0.23,1,0.32,1)";
const MORPH = "cubic-bezier(0.16,1,0.3,1)";
const STACK = 4;
// A light that sweeps across the label. A mask, not a text clip, so it reaches letters that are mid-morph.
const SHEEN =
  "text-foreground [mask-image:linear-gradient(90deg,rgb(0_0_0/0.45)_35%,#000_50%,rgb(0_0_0/0.45)_65%)] [mask-size:200%_100%] animate-[ui-sheen_1.4s_linear_infinite] motion-reduce:animate-none motion-reduce:[mask-image:none] motion-reduce:text-foreground/70";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function hostname(url: string) {
  try {
    return new URL(url).hostname.replace(/^www\./, "");
  } catch {
    return url;
  }
}

function hue(text: string) {
  let h = 0;
  for (let i = 0; i < text.length; i++) h = (h * 31 + text.charCodeAt(i)) % 360;
  return h;
}

const asQuery = (q: string | ResearchQuery): ResearchQuery =>
  typeof q === "string" ? { text: q } : q;
const siteName = (site: string) => {
  const parts = hostname(`https://${site}`).split(".");
  const name = parts.length > 1 ? parts[parts.length - 2] : parts[0];
  return name.length <= 2
    ? name.toUpperCase()
    : name.charAt(0).toUpperCase() + name.slice(1);
};

const plural = (n: number, word: string) =>
  `${word}${n === 1 ? "" : /(s|sh|ch|x)$/.test(word) ? "es" : "s"}`;

function Favicon({
  source,
  className = "",
}: {
  source: ResearchSource;
  className?: string;
}) {
  const host = hostname(source.url);
  const [failed, setFailed] = React.useState(false);
  if (source.favicon && !failed) {
    return (
      <img
        src={source.favicon}
        alt=""
        onError={() => setFailed(true)}
        className={`rounded-full bg-background object-cover ${className}`}
      />
    );
  }
  const h = hue(host);
  return (
    <span
      aria-hidden="true"
      className={`flex items-center justify-center rounded-full text-[9.5px] font-semibold leading-none ${className}`}
      style={{
        background: `color-mix(in oklab, oklch(0.62 0.13 ${h}) 20%, var(--background))`,
        color: `oklch(0.5 0.12 ${h})`,
      }}
    >
      {host.charAt(0).toUpperCase()}
    </span>
  );
}

/** Types the newest query in, a few characters a frame; earlier text never re-types. */
function useTyped(text: string, active: boolean, reduced: boolean) {
  const [shown, setShown] = React.useState(text);
  React.useEffect(() => {
    if (!active || reduced) return;
    let i = 0;
    let frame = 0;
    const step = () => {
      i = Math.min(text.length, i + 2);
      setShown(text.slice(0, i));
      if (i < text.length) frame = requestAnimationFrame(step);
    };
    frame = requestAnimationFrame(step);
    return () => cancelAnimationFrame(frame);
  }, [text, active, reduced]);
  return !active || reduced ? text : shown;
}

/** A piece of the line that opens out of nothing and folds back into it (width eases, content blurs in). */
function Reveal({
  show,
  reduced,
  className = "",
  children,
}: {
  show: boolean;
  reduced: boolean;
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <span
      aria-hidden={!show || undefined}
      className={`grid min-w-0 ${className}`}
      style={{
        gridTemplateColumns: show ? "1fr" : "0fr",
        opacity: show ? 1 : 0,
        filter: show ? "none" : "blur(4px)",
        transition: reduced
          ? "none"
          : `grid-template-columns 460ms ${MORPH}, opacity ${show ? "320ms" : "180ms"} ${MORPH}, filter 320ms ${MORPH}`,
      }}
    >
      <span className="min-w-0 whitespace-nowrap [clip-path:inset(-4px_-2px)]">
        {children}
      </span>
    </span>
  );
}

/** One icon in the stack: drops in when it's new, folds away when it's pushed out by a newer one. */
function StackIcon({
  shown,
  first,
  enter,
  reduced,
  z,
  children,
}: {
  shown: boolean;
  first: boolean;
  enter: boolean;
  reduced: boolean;
  z: number;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      aria-hidden={!shown || undefined}
      className={`relative flex h-5 shrink-0 ${entering && !reduced ? "animate-[ui-drop-in_420ms_cubic-bezier(0.23,1,0.32,1)_backwards]" : ""}`}
      style={{
        zIndex: z,
        width: shown ? 20 : 0,
        marginLeft: shown && !first ? -6 : 0,
        opacity: shown ? 1 : 0,
        transform: shown ? "none" : "scale(0.6)",
        transition: reduced
          ? "none"
          : `width 420ms ${MORPH}, margin 420ms ${MORPH}, opacity 260ms ${MORPH}, transform 420ms ${MORPH}`,
      }}
    >
      <span className="flex size-5 shrink-0 overflow-hidden rounded-full ring-2 ring-background">
        {children}
      </span>
    </span>
  );
}

/** A one-line ticker: the new text rises in out of a blur while the last one lifts away. */
function Ticker({
  id,
  reduced,
  children,
}: {
  id: string;
  reduced: boolean;
  children: React.ReactNode;
}) {
  const [hasUpdated, setHasUpdated] = React.useState(false);
  const [current, setCurrent] = React.useState<{
    id: string;
    node: React.ReactNode;
  }>({ id, node: children });
  const [leaving, setLeaving] = React.useState<
    { id: string; node: React.ReactNode }[]
  >([]);
  if (current.id !== id) {
    if (!reduced)
      setLeaving((l) =>
        l.some((x) => x.id === current.id) ? l : [...l, current],
      );
    setCurrent({ id, node: children });
    if (!hasUpdated) setHasUpdated(true);
  }
  const done = React.useCallback(
    (leftId: string) => setLeaving((l) => l.filter((x) => x.id !== leftId)),
    [],
  );

  return (
    <span className="relative block h-4">
      {leaving.map((l) => (
        <Tick key={`out-${l.id}`} id={l.id} out onDone={done}>
          {l.node}
        </Tick>
      ))}
      <Tick key={id} id={id} enter={hasUpdated && !reduced}>
        {children}
      </Tick>
    </span>
  );
}

function Tick({
  id,
  out = false,
  enter = false,
  onDone,
  children,
}: {
  id: string;
  out?: boolean;
  enter?: boolean;
  onDone?: (id: string) => void;
  children: React.ReactNode;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  const [entering] = React.useState(enter);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (out) {
      const animation = el.animate(
        [
          { opacity: 1, filter: "blur(0px)", transform: "none" },
          { opacity: 0, filter: "blur(4px)", transform: "translateY(-6px)" },
        ],
        { duration: 220, easing: MORPH, fill: "forwards" },
      );
      animation.onfinish = () => onDone?.(id);
      return () => animation.cancel();
    }
    if (!entering) return;
    const animation = el.animate(
      [
        { opacity: 0, filter: "blur(4px)", transform: "translateY(6px)" },
        { opacity: 1, filter: "blur(0px)", transform: "none" },
      ],
      { duration: 380, easing: MORPH, delay: 60, fill: "backwards" },
    );
    return () => animation.cancel();
  }, [id, out, entering, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden={out || undefined}
      className="absolute inset-0 truncate text-[11.5px] text-muted-foreground/80"
    >
      {children}
    </span>
  );
}

function SourceLink({ source }: { source: ResearchSource }) {
  return (
    <a
      href={source.url}
      target="_blank"
      rel="noreferrer"
      className="flex h-7 items-center gap-2.5 rounded-lg px-1.5 outline-none transition-colors hover:bg-accent focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/40"
    >
      <Favicon source={source} className="size-4 shrink-0" />
      <span className="min-w-0 flex-1 truncate text-[12.5px] text-foreground">
        {source.title ?? hostname(source.url)}
      </span>
      <span className="shrink-0 text-[11.5px] text-muted-foreground">
        {hostname(source.url)}
      </span>
    </a>
  );
}

/** The pages one search found: overlapping marks on a branch of the trail, folding open into links. */
function SourceGroup({
  sources,
  reduced,
}: {
  sources: ResearchSource[];
  reduced: boolean;
}) {
  const [open, setOpen] = React.useState(false);
  const listId = React.useId();
  const shown = sources.slice(0, 5);
  return (
    <div className="relative mb-1 ml-6">
      <span
        aria-hidden="true"
        className="absolute -left-3.5 -top-1 h-[13px] w-2.5 rounded-bl-[5px] border-b border-l border-border"
      />
      <button
        type="button"
        aria-expanded={open}
        aria-controls={listId}
        onClick={() => setOpen((o) => !o)}
        className="cursor-pointer group flex h-6 items-center gap-2 rounded-md text-[12px] text-muted-foreground outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/40"
      >
        Sources
        <span className="flex items-center">
          {shown.map((src, i) => (
            <span
              key={src.url}
              className="flex size-4 overflow-hidden rounded-full ring-2 ring-background"
              style={{ marginLeft: i ? -5 : 0, zIndex: shown.length - i }}
            >
              <Favicon source={src} className="size-full" />
            </span>
          ))}
          {sources.length > shown.length && (
            <span className="ml-1 font-mono text-[10px]">
              +{sources.length - shown.length}
            </span>
          )}
        </span>
        <ChevronDown
          aria-hidden="true"
          className="size-3.5"
          style={{
            transform: open ? "rotate(180deg)" : "none",
            transition: reduced ? "none" : `transform 320ms ${EASE}`,
          }}
        />
        <span className="sr-only">({sources.length})</span>
      </button>
      <div
        id={listId}
        inert={!open}
        className="grid"
        style={{
          gridTemplateRows: open ? "1fr" : "0fr",
          opacity: open ? 1 : 0,
          transition: reduced
            ? "none"
            : `grid-template-rows 380ms ${EASE}, opacity ${open ? "280ms" : "140ms"} ${EASE}`,
        }}
      >
        <ul className="-mx-1.5 min-h-0 overflow-hidden">
          {sources.map((src) => (
            <li key={src.url}>
              <SourceLink source={src} />
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

export function WebResearch({
  status,
  queries,
  sources,
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  className = "",
  ...props
}: WebResearchProps) {
  const reduced = useReducedMotion();
  const [ownOpen, setOwnOpen] = React.useState(defaultOpen);
  const open = openProp ?? ownOpen;
  const setOpen = (next: boolean) => {
    if (openProp === undefined) setOwnOpen(next);
    onOpenChange?.(next);
  };

  const working = status === "searching" || status === "reading";
  const query = queries.length ? asQuery(queries[queries.length - 1]).text : "";
  const typed = useTyped(query, status === "searching", reduced);
  const latest = sources[sources.length - 1];
  const extra = Math.max(0, sources.length - STACK);
  // Pages that don't say which search found them are listed after the trail.
  const ungrouped = sources.filter(
    (src) =>
      src.query === undefined || src.query < 0 || src.query >= queries.length,
  );
  const listId = React.useId();

  // Icons that arrive after the first paint drop in; the ones already there just sit.
  const [mounted, setMounted] = React.useState(false);
  React.useEffect(() => {
    const timer = window.setTimeout(() => setMounted(true), 0);
    return () => window.clearTimeout(timer);
  }, []);

  // One line that rearranges itself: a label, then whichever counts this state needs.
  const label = {
    searching: "Searching",
    reading: "Reading",
    error: "Search failed",
    cancelled: "Stopped after",
    done: "",
  }[status];
  const showSearches = status === "done" || status === "cancelled";
  const showSources =
    sources.length > 0 &&
    (status === "reading" || status === "done" || status === "error");
  const showDot = showSources && (status === "done" || status === "error");
  const sourceWord =
    status === "reading"
      ? plural(sources.length, "site")
      : plural(sources.length, "source");

  const summary =
    status === "searching"
      ? `Searching for ${query}`
      : status === "reading"
        ? `Read ${sources.length} ${sourceWord}`
        : status === "error"
          ? `Search failed${sources.length ? `, ${sources.length} ${sourceWord}` : ""}`
          : status === "cancelled"
            ? `Stopped after ${queries.length} ${plural(queries.length, "search")}`
            : `Done: ${queries.length} ${plural(queries.length, "search")}, ${sources.length} ${sourceWord}`;

  return (
    <div className={`w-full ${className}`} {...props}>
      {/* The same row from first search to final summary, so every piece of it can morph; it becomes a button once there's a list to open. */}
      <button
        type="button"
        disabled={working}
        aria-expanded={working ? undefined : open}
        aria-controls={working ? undefined : listId}
        onClick={() => setOpen(!open)}
        className="group flex min-h-9 w-full items-center gap-2.5 rounded-lg py-1 text-left outline-none focus-visible:ring-2 focus-visible:ring-ring/40 disabled:cursor-default"
      >
        <span
          aria-hidden="true"
          className="relative flex h-5 shrink-0 items-center"
        >
          <StackIcon
            shown={sources.length === 0}
            first
            enter={false}
            reduced={reduced}
            z={0}
          >
            <span className="flex size-full items-center justify-center bg-muted text-muted-foreground">
              <Search
                className={`size-3 ${working ? "animate-[ui-breathe_1.6s_ease-in-out_infinite] motion-reduce:animate-none" : ""}`}
                strokeWidth={2.2}
              />
            </span>
          </StackIcon>
          {sources.map((s, i) => (
            <StackIcon
              key={s.url}
              shown={i >= sources.length - STACK}
              first={i === Math.max(0, sources.length - STACK)}
              enter={mounted && working}
              reduced={reduced}
              z={i + 1}
            >
              <Favicon source={s} className="size-full" />
            </StackIcon>
          ))}
          <Reveal
            show={extra > 0}
            reduced={reduced}
            className="relative z-[999]"
          >
            <span className="ml-[-6px] flex h-5 min-w-5 items-center justify-center rounded-full bg-muted px-1 font-mono text-[9.5px] text-muted-foreground ring-2 ring-background">
              <NumberRoll value={extra} prefix="+" duration={600} />
            </span>
          </Reveal>
        </span>

        <span className="min-w-0 flex-1 text-left">
          <span
            className={`flex min-w-0 items-center text-[13px] leading-5 transition-colors duration-300 ${status === "error" ? "text-red-600 dark:text-red-400" : "text-muted-foreground"}`}
          >
            <span
              className={`shrink-0 font-medium transition-colors duration-300 ${working ? SHEEN : ""}`}
            >
              <TextMorph>{label}</TextMorph>
            </span>
            <Reveal show={showSearches} reduced={reduced} className="shrink-0">
              <span
                className="inline-flex items-baseline transition-[padding] duration-500"
                style={{
                  paddingLeft: label ? 5 : 0,
                  transitionTimingFunction: MORPH,
                }}
              >
                <NumberRoll value={queries.length} duration={700} />
                &nbsp;
                <TextMorph>{plural(queries.length, "search")}</TextMorph>
              </span>
            </Reveal>
            <Reveal show={showDot} reduced={reduced} className="shrink-0">
              <span className="px-1.5 opacity-60">·</span>
            </Reveal>
            <Reveal show={showSources} reduced={reduced} className="shrink-0">
              <span
                className="inline-flex items-baseline transition-[padding] duration-500"
                style={{
                  paddingLeft: showDot ? 0 : 5,
                  transitionTimingFunction: MORPH,
                }}
              >
                <NumberRoll value={sources.length} duration={700} />
                &nbsp;
                <TextMorph>{sourceWord}</TextMorph>
              </span>
            </Reveal>
            <Reveal
              show={status === "searching" && Boolean(query)}
              reduced={reduced}
              className="shrink"
            >
              <span className="block truncate pl-1.5">“{typed}”</span>
            </Reveal>
          </span>
          {/* The page being read; the row folds shut when the work is done. */}
          <span
            aria-hidden={!working || undefined}
            className="grid"
            style={{
              gridTemplateRows: working && latest ? "1fr" : "0fr",
              opacity: working && latest ? 1 : 0,
              transition: reduced
                ? "none"
                : `grid-template-rows 420ms ${MORPH}, opacity 260ms ${MORPH}`,
            }}
          >
            <span className="min-h-0 overflow-hidden">
              <span className="block pt-0.5">
                {latest && (
                  <Ticker id={latest.url} reduced={reduced}>
                    {latest.title ?? hostname(latest.url)}{" "}
                    <span className="text-muted-foreground/60">
                      · {hostname(latest.url)}
                    </span>
                  </Ticker>
                )}
              </span>
            </span>
          </span>
        </span>

        <Reveal show={!working} reduced={reduced} className="shrink-0">
          <ChevronRight
            aria-hidden="true"
            className="size-3.5 text-muted-foreground transition-transform duration-300 group-hover:text-foreground motion-reduce:transition-none"
            style={{
              transform: open ? "rotate(90deg)" : "none",
              transitionTimingFunction: EASE,
            }}
          />
        </Reveal>
      </button>
      {/* Outside the button, so the button's name stays its visible text. */}
      <span role="status" aria-live="polite" className="sr-only">
        {summary}
      </span>

      <div
        id={listId}
        inert={!open || working}
        className="grid"
        style={{
          gridTemplateRows: open && !working ? "1fr" : "0fr",
          transition: reduced ? "none" : `grid-template-rows 380ms ${EASE}`,
        }}
      >
        <div className="min-h-0 overflow-hidden">
          <div className="ml-[9px] mt-1 pl-[19px]">
            {queries.length > 0 && (
              <ul className="pb-1">
                {queries.map((raw, i) => {
                  const q = asQuery(raw);
                  const found = sources.filter((src) => src.query === i);
                  const last =
                    i === queries.length - 1 && ungrouped.length === 0;
                  return (
                    <li key={i} className="relative">
                      {/* The trail: a thin line down the left, a short branch to each search. */}
                      <span
                        aria-hidden="true"
                        className="absolute -left-[19px] top-0 w-px bg-border"
                        style={last ? { height: 15 } : { bottom: 0 }}
                      />
                      <span
                        aria-hidden="true"
                        className="absolute -left-[19px] top-[15px] h-px w-3 bg-border"
                      />
                      <div className="flex items-start gap-2 py-1.5 text-[12.5px] leading-[18px] text-muted-foreground">
                        <span className="mt-px flex size-4 shrink-0 items-center justify-center">
                          {q.site ? (
                            <Favicon
                              source={{
                                url: `https://${q.site}`,
                                favicon: q.siteIcon,
                              }}
                              className="size-4"
                            />
                          ) : (
                            <Search
                              aria-hidden="true"
                              className="size-3.5"
                              strokeWidth={2.1}
                            />
                          )}
                        </span>
                        <span className="min-w-0 flex-1 text-foreground/85">
                          {q.site ? (
                            <>
                              Searched {siteName(q.site)} for{" "}
                              <span className="font-mono text-[11.5px] text-muted-foreground">
                                {q.text}
                              </span>
                            </>
                          ) : (
                            q.text
                          )}
                        </span>
                        {q.results != null && (
                          <span className="shrink-0 whitespace-nowrap tabular-nums">
                            {q.results}{" "}
                            {q.resultLabel ?? plural(q.results, "result")}
                          </span>
                        )}
                      </div>
                      {found.length > 0 && (
                        <SourceGroup sources={found} reduced={reduced} />
                      )}
                    </li>
                  );
                })}
              </ul>
            )}
            {ungrouped.length > 0 && (
              <div
                className={
                  queries.length
                    ? "border-t border-border/60 pb-1 pt-1.5"
                    : "pb-1"
                }
              >
                <ul className="-mx-1.5 max-h-80 overflow-y-auto overflow-x-hidden px-1.5 [scrollbar-color:var(--border)_transparent] [scrollbar-width:thin]">
                  {ungrouped.map((src) => (
                    <li key={src.url}>
                      <SourceLink source={src} />
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { RelativeTime, type DateLike } from "./relative-time";
import { StatusButton, type ActionStatus } from "./status-button";
import { TextMorph } from "./text-morph";
import { useRowMotion } from "./use-row-motion";

/* ─────────────────────────────────────────────────────────
 * WEBHOOK DELIVERIES: what was sent, and what came back
 *
 *   rows      the status code in its colour, the event, when,
 *             and how long the endpoint took; new deliveries
 *             fade in on top while the rest glide down
 *   open      a row opens by height into Request and Response,
 *             the tab highlight sliding between them
 *   redeliver Redeliver → Sending → Sent; the new attempt
 *             arrives on top
 * ───────────────────────────────────────────────────────── */

export interface WebhookDelivery {
  id: string;
  event: string;
  /** The endpoint's HTTP status, or null when it never answered. */
  status: number | null;
  durationMs?: number;
  at: DateLike;
  attempt?: number;
  /** The body sent (JSON as text). */
  request?: string;
  /** What came back. */
  response?: string;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";

const chip = (status: number | null) =>
  status === null || status >= 500
    ? "bg-red-500/10 text-red-700 dark:text-red-400"
    : status >= 300
      ? "bg-amber-500/10 text-amber-800 dark:text-amber-400"
      : "bg-emerald-500/10 text-emerald-700 dark:text-emerald-400";

export function StatusChip({ status }: { status: number | null }) {
  return (
    <span
      className={`inline-flex h-5 w-[2.6rem] shrink-0 items-center justify-center rounded-[6px] font-mono text-[11px] font-medium tabular-nums ${chip(status)}`}
    >
      {status ?? "—"}
    </span>
  );
}

const pretty = (text?: string) => {
  if (!text) return "";
  try {
    return JSON.stringify(JSON.parse(text), null, 2);
  } catch {
    return text;
  }
};

function Bodies({ d, reduced }: { d: WebhookDelivery; reduced: boolean }) {
  const id = React.useId();
  const [tab, setTab] = React.useState<"request" | "response">("request");
  const refs = React.useRef<Record<string, HTMLButtonElement | null>>({});
  const [bar, setBar] = React.useState({ left: 0, width: 0, ready: false });
  React.useLayoutEffect(() => {
    const b = refs.current[tab];
    if (b)
      setBar((p) =>
        p.left === b.offsetLeft && p.width === b.offsetWidth
          ? p
          : { left: b.offsetLeft, width: b.offsetWidth, ready: p.width > 0 },
      );
  }, [tab]);
  const body = pretty(tab === "request" ? d.request : d.response);
  return (
    <div className="mt-1 mb-2 ml-2 rounded-[12px] shadow-[inset_0_0_0_1px_var(--border)] @md:ml-[3.35rem]">
      <div
        role="tablist"
        aria-label="Delivery body"
        className="relative flex gap-1 px-1.5 pt-1.5"
      >
        <span
          aria-hidden="true"
          className="absolute top-1.5 left-0 h-6 rounded-full bg-accent"
          style={{
            width: bar.width,
            transform: `translateX(${bar.left}px)`,
            transition:
              bar.ready && !reduced
                ? `transform 360ms ${EASE}, width 360ms ${EASE}`
                : "none",
          }}
        />
        {(["request", "response"] as const).map((t) => (
          <button
            key={t}
            ref={(el) => {
              refs.current[t] = el;
            }}
            role="tab"
            id={`${id}-${t}`}
            aria-selected={tab === t}
            aria-controls={`${id}-panel`}
            tabIndex={tab === t ? 0 : -1}
            onClick={() => setTab(t)}
            onKeyDown={(e) => {
              if (e.key !== "ArrowLeft" && e.key !== "ArrowRight") return;
              e.preventDefault();
              const next = t === "request" ? "response" : "request";
              setTab(next);
              refs.current[next]?.focus();
            }}
            className={`relative h-6 cursor-pointer rounded-full px-2.5 text-[11.5px] font-medium capitalize transition-colors ${FOCUS} ${tab === t ? "text-foreground" : "text-muted-foreground hover:text-foreground"}`}
          >
            {t}
          </button>
        ))}
      </div>
      <pre
        id={`${id}-panel`}
        role="tabpanel"
        aria-labelledby={`${id}-${tab}`}
        className="max-h-56 overflow-auto px-3 py-2 font-mono text-[11.5px] leading-[1.55] whitespace-pre-wrap break-all text-foreground"
      >
        {body || (
          <span className="text-muted-foreground">
            {tab === "request"
              ? "No body was kept."
              : "The endpoint sent no body."}
          </span>
        )}
      </pre>
    </div>
  );
}

function Redeliver({ onRedeliver }: { onRedeliver: () => Promise<unknown> }) {
  const [status, setStatus] = React.useState<ActionStatus>("idle");
  return (
    <StatusButton
      size="sm"
      variant="ghost"
      status={status}
      labels={{
        idle: "Redeliver",
        pending: "Sending",
        success: "Sent",
        error: "Try again",
      }}
      onReset={() => setStatus("idle")}
      resetAfter={1600}
      onClick={async () => {
        setStatus("pending");
        try {
          await onRedeliver();
          setStatus("success");
        } catch {
          setStatus("error");
        }
      }}
    />
  );
}

const Row = React.memo(function Row({
  d,
  open,
  reduced,
  toggle,
  redeliver,
}: {
  d: WebhookDelivery;
  open: boolean;
  reduced: boolean;
  toggle: React.RefObject<(id: string) => void>;
  redeliver?: React.RefObject<(d: WebhookDelivery) => Promise<unknown>>;
}) {
  return (
    <li data-row-id={d.id} className="border-t border-border first:border-t-0">
      <div className="flex items-center gap-2 py-1.5 pr-1">
        <button
          type="button"
          aria-expanded={open}
          onClick={() => toggle.current(d.id)}
          className={`flex min-w-0 flex-1 cursor-pointer items-center gap-3 rounded-[8px] px-2 py-1 text-left transition-colors hover:bg-accent/70 ${FOCUS}`}
        >
          <StatusChip status={d.status} />
          <span className="min-w-0 flex-1">
            <span className="block truncate font-mono text-[12px] text-foreground">
              {d.event}
            </span>
            <span className="flex min-w-0 items-baseline gap-1.5 overflow-hidden text-[11.5px] whitespace-nowrap text-muted-foreground">
              <RelativeTime className="shrink-0" date={d.at} />
              {/* On a narrow card the time is enough; how long it took shows when there's room. */}
              {d.durationMs !== undefined && (
                <span className="hidden gap-1.5 @sm:inline-flex">
                  <span aria-hidden="true">·</span>
                  <span className="tabular-nums">
                    {Math.round(d.durationMs).toLocaleString("en-GB")} ms
                  </span>
                </span>
              )}
              {d.attempt && d.attempt > 1 ? (
                <>
                  <span aria-hidden="true">·</span>
                  <span className="truncate">attempt {d.attempt}</span>
                </>
              ) : null}
            </span>
          </span>
          <svg
            viewBox="0 0 16 16"
            fill="none"
            aria-hidden="true"
            className="size-3 shrink-0 text-muted-foreground"
            style={{
              transform: open ? "rotate(180deg)" : "none",
              transition: reduced ? "none" : `transform 320ms ${EASE}`,
            }}
          >
            <path
              d="M4.5 6.25 8 9.75l3.5-3.5"
              stroke="currentColor"
              strokeWidth="1.6"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </button>
        {redeliver && <Redeliver onRedeliver={() => redeliver.current(d)} />}
      </div>
      <div
        className="grid"
        inert={!open}
        style={{
          gridTemplateRows: open ? "1fr" : "0fr",
          transition: reduced ? "none" : `grid-template-rows 380ms ${EASE}`,
        }}
      >
        <div className="min-h-0 min-w-0 overflow-clip">
          {open && <Bodies d={d} reduced={reduced} />}
        </div>
      </div>
    </li>
  );
});

export interface DeliveryListProps {
  deliveries: WebhookDelivery[];
  loading: boolean;
  /** More can be loaded. */
  more: boolean;
  onMore?: () => void;
  onRedeliver?: (d: WebhookDelivery) => Promise<unknown>;
  reduced: boolean;
}

export function DeliveryList({
  deliveries,
  loading,
  more,
  onMore,
  onRedeliver,
  reduced,
}: DeliveryListProps) {
  const [open, setOpen] = React.useState<string | null>(null);
  const listRef = React.useRef<HTMLUListElement>(null);
  const ghostRef = React.useRef<HTMLDivElement>(null);
  const ranks = React.useMemo(
    () => new Map(deliveries.map((d, i) => [d.id, i])),
    [deliveries],
  );
  useRowMotion(listRef, { reduced, ranks, ghosts: ghostRef });
  const toggle = React.useRef<(id: string) => void>(() => {});
  const redeliver = React.useRef<(d: WebhookDelivery) => Promise<unknown>>(
    async () => {},
  );
  React.useLayoutEffect(() => {
    toggle.current = (id) => setOpen((o) => (o === id ? null : id));
    redeliver.current = (d) => onRedeliver?.(d) ?? Promise.resolve();
  });

  return (
    <div>
      <div className="relative">
        <ul
          ref={listRef}
          aria-label="Recent deliveries"
          aria-busy={loading || undefined}
          className="relative"
        >
          {deliveries.map((d) => (
            <Row
              key={d.id}
              d={d}
              open={open === d.id}
              reduced={reduced}
              toggle={toggle}
              redeliver={onRedeliver ? redeliver : undefined}
            />
          ))}
        </ul>
        <div
          ref={ghostRef}
          aria-hidden="true"
          className="pointer-events-none absolute inset-0"
        />
      </div>
      {(loading || !deliveries.length || more) && (
        <div className="flex h-9 items-center justify-center gap-2 text-[12px] text-muted-foreground">
          {loading ? (
            <>
              <span className="size-3 animate-spin rounded-full border-[1.5px] border-current border-t-transparent motion-reduce:animate-none" />
              Loading deliveries
            </>
          ) : !deliveries.length ? (
            "Nothing delivered yet. Send a test to see one here."
          ) : (
            <button
              type="button"
              onClick={onMore}
              className={`h-7 cursor-pointer rounded-full px-3 font-medium text-foreground transition-colors hover:bg-accent ${FOCUS}`}
            >
              <TextMorph>Show older</TextMorph>
            </button>
          )}
        </div>
      )}
    </div>
  );
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { PillSelect } from "./imported-pill-select";
import { StatusButton, type ActionStatus } from "./status-button";
import { TextMorph } from "./text-morph";
import type { WebhookDelivery } from "./webhook-deliveries";

/* ─────────────────────────────────────────────────────────
 * WEBHOOK WIRE: "Send test", drawn as the request it is
 *
 *   out       a bead leaves your app and runs the thin line to
 *             the endpoint
 *   waiting   the endpoint's chip pulses while it answers
 *   back      the bead comes home in the answer's colour, and
 *             the result rolls in: "200 OK in 182 ms"
 *   failed    a 5xx, or no answer, comes back red and the
 *             button shakes
 * ───────────────────────────────────────────────────────── */

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const TRAVEL = "cubic-bezier(0.65,0,0.35,1)";

const REASONS: Record<number, string> = {
  200: "OK",
  201: "Created",
  202: "Accepted",
  204: "No Content",
  301: "Moved",
  302: "Found",
  400: "Bad Request",
  401: "Unauthorized",
  403: "Forbidden",
  404: "Not Found",
  405: "Method Not Allowed",
  408: "Request Timeout",
  410: "Gone",
  413: "Too Large",
  422: "Unprocessable",
  429: "Too Many Requests",
  500: "Internal Server Error",
  502: "Bad Gateway",
  503: "Service Unavailable",
  504: "Gateway Timeout",
};
export const reasonFor = (status: number | null) =>
  status === null
    ? "No answer"
    : (REASONS[status] ??
      (status < 300 ? "OK" : status < 500 ? "Refused" : "Server error"));
export const toneFor = (status: number | null) =>
  status === null || status >= 500
    ? "red"
    : status >= 400
      ? "amber"
      : status >= 300
        ? "amber"
        : "emerald";
const COLOR = {
  emerald: "var(--color-emerald-500)",
  amber: "var(--color-amber-500)",
  red: "var(--color-red-500)",
};
const TEXT = {
  emerald: "text-emerald-600 dark:text-emerald-400",
  amber: "text-amber-700 dark:text-amber-400",
  red: "text-red-600 dark:text-red-400",
};

export interface WebhookWireProps {
  /** The endpoint's host, shown at the far end of the wire. */
  host: string;
  /** Events the test can send; the first is picked. */
  events: string[];
  onSend: (event: string) => Promise<WebhookDelivery>;
  /** Called with the delivery the test made, e.g. to add it to the list. */
  onDelivered?: (delivery: WebhookDelivery) => void;
  reduced: boolean;
  autoFocus?: boolean;
  /** Your app's name at the near end. */
  from?: string;
}

export function WebhookWire({
  host,
  events,
  onSend,
  onDelivered,
  reduced,
  autoFocus,
  from = "You",
}: WebhookWireProps) {
  const [event, setEvent] = React.useState(events[0] ?? "");
  const [status, setStatus] = React.useState<ActionStatus>("idle");
  const [result, setResult] = React.useState<{
    status: number | null;
    ms: number;
  } | null>(null);
  const [failure, setFailure] = React.useState<string | null>(null);
  const lineRef = React.useRef<HTMLSpanElement>(null);
  const beadRef = React.useRef<HTMLSpanElement>(null);
  const hostRef = React.useRef<HTMLSpanElement>(null);
  const wrapRef = React.useRef<HTMLDivElement>(null);

  if (!events.includes(event)) {
    setEvent(events[0] ?? "");
  }

  React.useEffect(() => {
    if (autoFocus)
      wrapRef.current
        ?.querySelector<HTMLButtonElement>("button[data-send]")
        ?.focus({ preventScroll: true });
  }, [autoFocus]);

  const send = async () => {
    if (status === "pending" || !event) return;
    setStatus("pending");
    setFailure(null);
    const answer = onSend(event);
    const bead = beadRef.current;
    const line = lineRef.current;
    const far = line ? Math.max(0, line.offsetWidth - 7) : 0;
    let ping: Animation | undefined;
    if (bead && !reduced) {
      bead.style.background = "var(--primary)";
      await bead
        .animate(
          [
            { transform: "translateX(0px)", opacity: 0 },
            { opacity: 1, offset: 0.12 },
            { transform: `translateX(${far}px)`, opacity: 1 },
          ],
          { duration: 620, easing: TRAVEL, fill: "forwards" },
        )
        .finished.catch(() => {});
      ping = hostRef.current?.animate(
        [
          {
            boxShadow:
              "inset 0 0 0 1px var(--border), 0 0 0 0px color-mix(in oklab, var(--primary) 35%, transparent)",
          },
          { boxShadow: "inset 0 0 0 1px var(--border), 0 0 0 6px transparent" },
        ],
        {
          duration: 900,
          iterations: Infinity,
          easing: "ease-out",
        },
      );
    }
    try {
      const d = await answer;
      ping?.cancel();
      const tone = toneFor(d.status);
      if (bead && !reduced) {
        bead.style.background = COLOR[tone];
        await bead
          .animate(
            [
              { transform: `translateX(${far}px)`, opacity: 1 },
              { transform: "translateX(0px)", opacity: 1, offset: 0.88 },
              { transform: "translateX(0px)", opacity: 0 },
            ],
            { duration: 640, easing: TRAVEL, fill: "forwards" },
          )
          .finished.catch(() => {});
      }
      setResult({ status: d.status, ms: Math.round(d.durationMs ?? 0) });
      setStatus(tone === "emerald" ? "success" : "error");
      onDelivered?.(d);
    } catch (e) {
      ping?.cancel();
      bead?.getAnimations().forEach((a) => a.cancel());
      setFailure(
        e instanceof Error && e.message
          ? e.message
          : "The test couldn't be sent.",
      );
      setStatus("error");
    }
  };

  const tone = result ? toneFor(result.status) : null;
  return (
    <div ref={wrapRef}>
      <div className="flex flex-wrap items-center gap-2">
        <PillSelect
          label="Event to send"
          mono
          options={events.map((ev) => ({ value: ev, label: ev }))}
          value={event}
          onValueChange={setEvent}
          width={260}
        />
        <StatusButton
          data-send=""
          size="sm"
          variant="outline"
          status={status}
          labels={{
            idle: "Send test",
            pending: "Sending",
            success: "Delivered",
            error: "Send again",
          }}
          onClick={send}
          onReset={() => setStatus("idle")}
          resetAfter={2200}
        />
      </div>

      {/* The wire: your app, the thin line, the endpoint. */}
      <div
        aria-hidden="true"
        className="mt-3 flex items-center gap-2 font-mono text-[11px]"
      >
        <span className="shrink-0 rounded-full px-2 py-0.5 text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)]">
          {from}
        </span>
        <span ref={lineRef} className="relative h-px min-w-6 flex-1 bg-border">
          <span
            ref={beadRef}
            className="absolute -top-[3px] left-0 size-[7px] rounded-full opacity-0 will-change-transform"
          />
        </span>
        <span
          ref={hostRef}
          className="max-w-[55%] shrink truncate rounded-full px-2 py-0.5 text-foreground shadow-[inset_0_0_0_1px_var(--border)]"
        >
          {host}
        </span>
      </div>

      <div
        className="grid"
        style={{
          gridTemplateRows: result || failure ? "1fr" : "0fr",
          opacity: result || failure ? 1 : 0,
          transition: reduced
            ? "none"
            : `grid-template-rows 380ms ${EASE}, opacity 260ms ${EASE}`,
        }}
      >
        <div className="min-h-0 min-w-0 overflow-clip">
          <p
            role="status"
            className={`flex flex-wrap items-baseline gap-x-1 pt-2 text-[12px] tabular-nums ${failure ? TEXT.red : tone ? TEXT[tone] : "text-muted-foreground"}`}
          >
            {failure ? (
              failure
            ) : result ? (
              <>
                {result.status !== null && (
                  <NumberRoll
                    value={result.status}
                    className="font-mono font-medium"
                  />
                )}
                <TextMorph>{reasonFor(result.status)}</TextMorph>
                <span className="text-muted-foreground">in</span>
                <span className="inline-flex items-baseline text-muted-foreground">
                  <NumberRoll
                    value={result.ms}
                    format={{ maximumFractionDigits: 0 }}
                  />
                  &nbsp;ms
                </span>
              </>
            ) : null}
          </p>
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { Copy, Plus, Trash2 } from "lucide-react";
import { ConfirmAction } from "./confirm-action";
import { NumberRoll } from "./number-roll";
import { RelativeTime, type DateLike } from "./relative-time";
import { StatusButton, type ActionStatus } from "./status-button";
import { TextMorph } from "./text-morph";
import {
  DeliveryList,
  StatusChip,
  type WebhookDelivery,
} from "./webhook-deliveries";
import { WebhookWire } from "./webhook-wire";

/* ─────────────────────────────────────────────────────────
 * WEBHOOKS: Settings → Webhooks, done properly
 *
 *   add       "Add endpoint" opens the form above the list: the
 *             URL and the events it wants. The new endpoint
 *             fades in on top, already open on "Send test"
 *   test      the test is drawn as the request it is: a bead
 *             runs the thin line to the endpoint, waits while it
 *             answers, and comes home in the answer's colour;
 *             "200 OK in 182 ms" rolls in, and the delivery
 *             lands on top of the list
 *   inspect   every delivery opens into its request and
 *             response; Redeliver sends it again and the new
 *             attempt arrives on top
 *   secret    the signing secret stays dots until you reveal
 *             it, then copies with a drawn check
 *   pause     Enabled is a switch that saves itself; Delete
 *             stretches the bin into a confirm and folds the
 *             endpoint away
 *
 * Endpoints and deliveries are plain records; every action is
 * one async function, so it fits Svix, Hookdeck or your own
 * queue.
 * ───────────────────────────────────────────────────────── */

export type { WebhookDelivery, DateLike };

export interface WebhookEndpoint {
  id: string;
  url: string;
  /** The event types it receives. */
  events: string[];
  enabled?: boolean;
  /** Shown on the collapsed row. */
  lastDelivery?: { status: number | null; at: DateLike } | null;
}

export interface WebhookEventType {
  value: string;
  description?: string;
}

export interface WebhooksProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "defaultValue" | "onChange" | "onToggle"
> {
  value?: WebhookEndpoint[];
  defaultValue?: WebhookEndpoint[];
  onValueChange?: (endpoints: WebhookEndpoint[]) => void;
  /** Event types an endpoint can subscribe to. */
  events: WebhookEventType[];
  /** Creates an endpoint. Throw to keep the form and say why. */
  onCreate: (input: {
    url: string;
    events: string[];
  }) => Promise<WebhookEndpoint>;
  /** Sends a test event and returns the delivery it made. */
  onTest: (
    endpoint: WebhookEndpoint,
    event: string,
  ) => Promise<WebhookDelivery>;
  /** Recent deliveries, newest first; pass the oldest one shown to page back. An empty list means there are no more. */
  loadDeliveries?: (
    endpoint: WebhookEndpoint,
    before?: WebhookDelivery,
  ) => Promise<WebhookDelivery[]>;
  onRedeliver?: (
    delivery: WebhookDelivery,
    endpoint: WebhookEndpoint,
  ) => Promise<WebhookDelivery>;
  onRevealSecret?: (endpoint: WebhookEndpoint) => Promise<string>;
  /** Turns an endpoint on or off. Throw to put the switch back. */
  onToggle?: (endpoint: WebhookEndpoint, enabled: boolean) => Promise<unknown>;
  onDelete?: (endpoint: WebhookEndpoint) => Promise<unknown>;
  /** Your app's name, at the near end of the test's wire. */
  appName?: string;
  title?: string;
  description?: string;
}

type Draft = {
  url: string;
  events: string[];
  status: ActionStatus;
  error: string | null;
};
type Log = {
  items: WebhookDelivery[];
  loading: boolean;
  more: boolean;
  loaded: boolean;
};

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const NONE: WebhookEndpoint[] = [];
const SHAKE = [
  { transform: "none" },
  { transform: "translateX(-4px)" },
  { transform: "translateX(4px)" },
  { transform: "translateX(-2px)" },
  { transform: "none" },
];

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const message = (e: unknown, fallback: string) =>
  e instanceof Error && e.message ? e.message : fallback;
const split = (url: string) => {
  try {
    const u = new URL(url);
    return {
      host: u.host,
      path: `${u.pathname === "/" ? "" : u.pathname}${u.search}`,
    };
  } catch {
    return { host: url, path: "" };
  }
};
const checkUrl = (v: string) => {
  try {
    const u = new URL(v.trim());
    if (
      u.protocol === "https:" ||
      (u.protocol === "http:" && /^(localhost|127\.0\.0\.1)$/.test(u.hostname))
    )
      return null;
    return "Endpoints need https:// (http:// works for localhost).";
  } catch {
    return v.trim()
      ? "That isn't a full URL. Start it with https://."
      : "Enter the URL that should receive events.";
  }
};

function Fold({
  open,
  reduced,
  children,
}: {
  open: boolean;
  reduced: boolean;
  children: React.ReactNode;
}) {
  const [kept, setKept] = React.useState(children);
  if (open && kept !== children) {
    setKept(children);
  }
  return (
    <div
      className="grid"
      inert={!open}
      aria-hidden={!open || undefined}
      style={{
        gridTemplateRows: open ? "1fr" : "0fr",
        opacity: open ? 1 : 0,
        transition: reduced
          ? "none"
          : `grid-template-rows 460ms ${EASE}, opacity ${open ? 320 : 180}ms ${EASE}`,
      }}
    >
      <div className="min-h-0 min-w-0 overflow-clip [overflow-clip-margin:6px]">
        {open ? children : kept}
      </div>
    </div>
  );
}

function Check({ drawn, reduced }: { drawn: boolean; reduced: boolean }) {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      aria-hidden="true"
      className="size-3.5"
    >
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="1.9"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 420ms ${EASE} 100ms`
              : "none",
        }}
      />
    </svg>
  );
}

function EventChip({
  value,
  on,
  reduced,
  onToggle,
}: {
  value: string;
  on: boolean;
  reduced: boolean;
  onToggle: () => void;
}) {
  return (
    <button
      type="button"
      aria-pressed={on}
      onClick={onToggle}
      className={`inline-flex h-7 cursor-pointer items-center rounded-full px-2.5 font-mono text-[11.5px] transition-[background-color,color,box-shadow] duration-200 ${FOCUS} ${
        on
          ? "bg-accent text-foreground shadow-[inset_0_0_0_1px_var(--border)]"
          : "text-muted-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:text-foreground"
      }`}
    >
      <span
        className="grid"
        style={{
          gridTemplateColumns: on ? "1fr" : "0fr",
          transition: reduced ? "none" : `grid-template-columns 320ms ${EASE}`,
        }}
      >
        <span className="min-w-0 overflow-clip">
          <span className="mr-1 block">
            <Check drawn={on} reduced={reduced} />
          </span>
        </span>
      </span>
      {value}
    </button>
