});

export function WeekCalendar({
  events: controlled,
  defaultEvents,
  onEventsChange,
  onCreate,
  onUpdate,
  onDelete,
  date,
  defaultDate,
  onDateChange,
  days: daysProp = "auto",
  weekStartsOn = 1,
  startHour = 7,
  endHour = 21,
  step = 15,
  defaultDuration = 30,
  hourHeight = 44,
  height = 420,
  locale,
  label = "Calendar",
  className = "",
  ...props
}: WeekCalendarProps) {
  const reduced = useReducedMotion();
  const uid = React.useId();
  const [own, setOwn] = React.useState<CalendarEvent[]>(defaultEvents ?? EMPTY);
  const events = controlled ?? own;
  const eventsRef = React.useRef(events);
  React.useLayoutEffect(() => {
    eventsRef.current = events;
  });
  const [anchorOwn, setAnchorOwn] = React.useState(() =>
    startOfDay(defaultDate ?? new Date()),
  );
  const anchor = date ? startOfDay(date) : anchorOwn;
  const [width, setWidth] = React.useState(0);
  const [draft, setDraft] = React.useState<GridDraft | null>(null);
  const [naming, setNaming] = React.useState<string | null>(null);
  const [selected, setSelected] = React.useState<string | null>(null);
  const [saving, setSaving] = React.useState<ReadonlySet<string>>(
    () => new Set(),
  );
  const [rolling, setRolling] = React.useState<ReadonlySet<string>>(
    () => new Set(),
  );
  const [gone, setGone] = React.useState<Gone[]>([]);
  const [notice, setNotice] = React.useState<{
    text: string;
    key: number;
  } | null>(null);
  const [announce, setAnnounce] = React.useState("");
  const [cursor, setCursor] = React.useState<{
    day: number;
    minute: number;
  } | null>(null);
  const [now, setNow] = React.useState<Date | null>(null);
  const [slide, setSlide] = React.useState<{ dir: number; key: number } | null>(
    null,
  );
  /** The range we just left: its events slide out the other way while the new ones come in. */
  const [outgoing, setOutgoing] = React.useState<{
    key: number;
    dir: number;
    blocks: { id: string; style: React.CSSProperties; ev: CalendarEvent }[];
  } | null>(null);
  const rootRef = React.useRef<HTMLDivElement>(null);
  const scrollerRef = React.useRef<HTMLDivElement>(null);
  const columnsRef = React.useRef<HTMLDivElement>(null);
  const goneKey = React.useRef(0);
  const nextKey = React.useRef(0);

  // ── Range ──────────────────────────────────────────────
  const span =
    daysProp === "auto"
      ? width === 0 || width >= 560
        ? 7
        : width >= 300
          ? 3
          : 1
      : daysProp;
  const first = React.useMemo(
    () =>
      span === 7
        ? startOfWeek(anchor, weekStartsOn)
        : span === 5
          ? startOfWeek(anchor, 1)
          : anchor,
    [span, anchor, weekStartsOn],
  );
  const days = React.useMemo(
    () => Array.from({ length: span }, (_, i) => addDays(first, i)),
    [first, span],
  );
  const min = startHour * 60;
  const max = endHour * 60;
  const ppm = hourHeight / 60;
  const hour12 = React.useMemo(
    () =>
      new Intl.DateTimeFormat(locale, { hour: "numeric" }).resolvedOptions()
        .hour12 ?? false,
    [locale],
  );
  const fmt = React.useMemo(
    () => ({
      weekday: new Intl.DateTimeFormat(locale, { weekday: "short" }),
      long: new Intl.DateTimeFormat(locale, {
        weekday: "long",
        hour: "numeric",
        minute: "2-digit",
      }),
      time: new Intl.DateTimeFormat(locale, {
        hour: "numeric",
        minute: "2-digit",
      }),
      hour: new Intl.DateTimeFormat(locale, { hour: "numeric" }),
      range: new Intl.DateTimeFormat(locale, {
        month: "short",
        day: "numeric",
      }),
      day: new Intl.DateTimeFormat(locale, {
        weekday: "long",
        month: "long",
        day: "numeric",
      }),
    }),
    [locale],
  );
  const rangeLabel =
    span === 1
      ? fmt.day.format(days[0])
      : (fmt.range.formatRange?.(days[0], days[span - 1]) ??
        `${fmt.range.format(days[0])} – ${fmt.range.format(days[span - 1])}`);

  React.useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const observer = new ResizeObserver(([entry]) =>
      setWidth(Math.round(entry.contentRect.width)),
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  // The clock: on mount (so the server never renders a stale "now"), then once a minute, on the minute.
  React.useEffect(() => {
    let timer = 0;
    const tick = () => {
      const d = new Date();
      setNow(d);
      timer = window.setTimeout(
        tick,
        60_000 - (d.getSeconds() * 1000 + d.getMilliseconds()) + 20,
      );
    };
    tick();
    return () => window.clearTimeout(timer);
  }, []);

  // Open on the working day: an hour and a half before now when today is in view, else at 8.
  const scrolled = React.useRef(false);
  React.useLayoutEffect(() => {
    const sc = scrollerRef.current;
    if (!sc || scrolled.current || !now) return;
    scrolled.current = true;
    const today = days.some((d) => sameDay(d, now));
    const at = today ? minutesOf(now) - 90 : 8 * 60;
    sc.scrollTop = Math.max(0, (at - min) * ppm);
  }, [now, days, min, ppm]);

  const go = (dir: number) => {
    const by = span === 5 ? 7 : span;
    const next = dir === 0 ? startOfDay(new Date()) : addDays(anchor, dir * by);
    const nextFirst =
      span === 7
        ? startOfWeek(next, weekStartsOn)
        : span === 5
          ? startOfWeek(next, 1)
          : next;
    const d = Math.sign(nextFirst.getTime() - first.getTime());
    if (!d) return;
    if (!date) setAnchorOwn(next);
    onDateChange?.(nextFirst);
    if (!reduced)
      setOutgoing({
        key: ++nextKey.current,
        dir: d,
        blocks: shown.map((it) => ({
          id: it.id,
          style: geometry(it),
          ev: it.ev,
        })),
      });
    setSlide((s) => ({ dir: d, key: (s?.key ?? 0) + 1 }));
    setSelected(null);
    setCursor(null);
    setAnnounce(
      span === 1
        ? fmt.day.format(nextFirst)
        : `${fmt.range.formatRange?.(nextFirst, addDays(nextFirst, span - 1)) ?? fmt.range.format(nextFirst)}`,
    );
  };

  // ── Events in view ─────────────────────────────────────
  const commit = (next: CalendarEvent[]) => {
    eventsRef.current = next;
    if (controlled === undefined) setOwn(next);
    onEventsChange?.(next);
  };
  const flash = (text: string) => {
    const key = ++nextKey.current;
    setNotice({ text, key });
    window.setTimeout(
      () => setNotice((n) => (n?.key === key ? null : n)),
      3200,
    );
  };

  const items: Shown[] = React.useMemo(
    () =>
      events.flatMap((ev) => {
        const s = new Date(ev.start);
        const e = new Date(ev.end);
        const day = days.findIndex((d) => sameDay(d, s));
        if (day < 0) return [];
        const end = sameDay(s, e) ? minutesOf(e) : 24 * 60;
        return [
          {
            id: ev.id,
            day,
            start: Math.max(min, minutesOf(s)),
            end: Math.min(max, end),
            busy: ev.busy,
            ev,
          },
        ];
      }),
    [events, days, min, max],
  );

  const shown: Shown[] = !draft
    ? items
    : draft.kind === "create"
      ? [
          ...items,
          {
            id: draft.id,
            day: draft.day,
            start: draft.start,
            end: draft.end,
            draft: true,
            ev: {
              id: draft.id,
              title: "",
              start: atMinutes(days[draft.day], draft.start),
              end: atMinutes(days[draft.day], draft.end),
              tone: 1,
            },
          },
        ]
      : items.map((it) =>
          it.id === draft.id
            ? { ...it, day: draft.day, start: draft.start, end: draft.end }
            : it,
        );

  const layout = new Map<string, { col: number; cols: number }>();
  for (let d = 0; d < span; d++)
    layoutDay(shown.filter((it) => it.day === d && !it.busy)).forEach((v, k) =>
      layout.set(k, v),
    );

  /**
   * Where an event sits. Overlapping events fan out rather than splitting into slivers: each takes its column's start,
   * reaches 1.6 columns across (never past the day), and later columns sit on top, so every title keeps some room.
   */
  const geometry = (it: {
    day: number;
    start: number;
    end: number;
    id: string;
    busy?: boolean;
  }): React.CSSProperties & { zIndex: number } => {
    const l = it.busy
      ? { col: 0, cols: 1 }
      : (layout.get(it.id) ?? { col: 0, cols: 1 });
    const col = 100 / span;
    const reach = Math.min(l.cols - l.col, l.col === l.cols - 1 ? 1 : 1.6);
    return {
      top: (it.start - min) * ppm + 1,
      height: Math.max(MIN_HEIGHT, (it.end - it.start) * ppm - 2),
      left: `calc(${it.day * col + (l.col * col) / l.cols}% + ${l.col ? 0 : 2}px)`,
      width: `calc(${(col / l.cols) * reach}% - ${l.col ? 2 : 4}px)`,
      zIndex: 10 + l.col,
    };
  };

  const overlapsOf = (it: {
    id: string;
    day: number;
    start: number;
    end: number;
  }) =>
    shown
      .filter(
        (o) =>
          o.id !== it.id &&
          o.day === it.day &&
          o.start < it.end &&
          o.end > it.start,
      )
      .map((o) => (o.busy ? "busy time" : o.ev.title || "an event"));

  const describe = (
    ev: { title: string },
    it: { day: number; start: number; end: number },
  ) =>
    `${ev.title || "New event"}, ${fmt.long.format(atMinutes(days[it.day], it.start))} to ${fmt.time.format(atMinutes(days[it.day], it.end))}`;

  const roll = (id: string) => {
    setRolling((s) => new Set(s).add(id));
    window.setTimeout(
      () =>
        setRolling((s) => {
          const n = new Set(s);
          n.delete(id);
          return n;
        }),
      1200,
    );
  };

  const shake = (id: string) => {
    if (reduced) return;
    rootRef.current
      ?.querySelector<HTMLElement>(`[data-event-id="${CSS.escape(id)}"]`)
      ?.animate(
        [
          { transform: "none" },
          { transform: "translateX(-4px)" },
          { transform: "translateX(4px)" },
          { transform: "translateX(-2px)" },
          { transform: "none" },
        ],
        { duration: 380, easing: "ease-out", composite: "add" },
      );
  };

  /** Leaves through a fold: a copy where it was shrinks a little and blurs out. */
  const fold = (ev: CalendarEvent) => {
    const it = items.find((x) => x.id === ev.id);
    if (!it || reduced) return;
    setGone((g) => [...g, { key: ++goneKey.current, ev, style: geometry(it) }]);
  };

  const update = async (
    next: CalendarEvent,
    prev: CalendarEvent,
    how: string,
  ) => {
    commit(eventsRef.current.map((e) => (e.id === next.id ? next : e)));
    roll(next.id);
    const it = {
      day: days.findIndex((d) => sameDay(d, next.start)),
      start: minutesOf(next.start),
      end: minutesOf(next.end),
    };
    const over = it.day >= 0 ? overlapsOf({ id: next.id, ...it }) : [];
    if (it.day >= 0)
      setAnnounce(
        `${how} ${describe(next, it)}.${over.length ? ` Overlaps ${over[0]}.` : ""}`,
      );
    if (!onUpdate) return;
    try {
      await onUpdate(next, prev);
    } catch {
      commit(eventsRef.current.map((e) => (e.id === next.id ? prev : e)));
      roll(next.id);
      flash(`Couldn't move “${prev.title}”. It's back where it was.`);
      setAnnounce(`Couldn't save. ${prev.title} is back where it was.`);
      window.setTimeout(() => shake(next.id), 240);
    }
  };

  const remove = async (ev: CalendarEvent) => {
    fold(ev);
    commit(eventsRef.current.filter((e) => e.id !== ev.id));
    setSelected(null);
    setAnnounce(`Deleted ${ev.title}.`);
    columnsRef.current?.focus({ preventScroll: true });
    if (!onDelete) return;
    try {
      await onDelete(ev);
    } catch {
      commit([...eventsRef.current, ev]);
      flash(`Couldn't delete “${ev.title}”.`);
      window.setTimeout(() => shake(ev.id), 60);
    }
  };

  const create = (day: number, start: number, end: number, id?: string) => {
    const finalId = id ?? `new-${seq++}`;
    const ev: CalendarEvent = {
      id: finalId,
      title: "",
      start: atMinutes(days[day], start),
      end: atMinutes(days[day], end),
      tone: 1,
    };
    commit([...eventsRef.current, ev]);
    setNaming(finalId);
    setSelected(finalId);
    roll(finalId);
  };

  const finishNaming = async (id: string, title: string | null) => {
    if (naming !== id) return;
    setNaming(null);
    const ev = eventsRef.current.find((e) => e.id === id);
    if (!ev) return;
    if (title === null) {
      fold(ev);
      commit(eventsRef.current.filter((e) => e.id !== id));
      setAnnounce("Discarded the new event.");
      return;
    }
    const named = { ...ev, title: title.trim() || "New event" };
    commit(eventsRef.current.map((e) => (e.id === id ? named : e)));
    const it = {
      day: days.findIndex((d) => sameDay(d, named.start)),
      start: minutesOf(named.start),
      end: minutesOf(named.end),
    };
    setAnnounce(`Added ${describe(named, it)}.`);
    if (!onCreate) return;
    setSaving((s) => new Set(s).add(id));
    try {
      const stored = await onCreate(named);
      if (stored && stored.id !== id)
        commit(
          eventsRef.current.map((e) =>
            e.id === id ? { ...named, ...stored } : e,
          ),
        );
    } catch {
      shake(id);
      window.setTimeout(
        () => {
          const cur = eventsRef.current.find((e) => e.id === id);
          if (cur) fold(cur);
          commit(eventsRef.current.filter((e) => e.id !== id));
        },
        reduced ? 0 : 420,
      );
      flash(`Couldn't save “${named.title}”.`);
      setAnnounce(`Couldn't save ${named.title}.`);
    } finally {
      setSaving((s) => {
        const n = new Set(s);
        n.delete(id);
        return n;
      });
    }
  };

  // ── Gestures ───────────────────────────────────────────
  const grid = useTimeGrid({
    columns: columnsRef,
    scroller: scrollerRef,
    span,
    min,
    max,
    pxPerMinute: ppm,
    step,
    holdDuration: defaultDuration,
    items: items.filter((it) => !it.busy && it.id !== naming),
    disabled: !!naming,
    onDraft: setDraft,
    onCommit: (d) => {
      if (d.kind === "create") return create(d.day, d.start, d.end, d.id);
      const prev = eventsRef.current.find((e) => e.id === d.id);
      if (!prev) return;
      const next = {
        ...prev,
        start: atMinutes(days[d.day], d.start),
        end: atMinutes(days[d.day], d.end),
      };
      if (
        next.start.getTime() === new Date(prev.start).getTime() &&
        next.end.getTime() === new Date(prev.end).getTime()
      )
        return;
      setSelected(d.id);
      update(next, prev, d.kind === "move" ? "Moved to" : "Now");
    },
    onTap: (t, pointer) => {
      if ("id" in t) {
        setSelected(t.id);
        rootRef.current
          ?.querySelector<HTMLElement>(`[data-event-id="${CSS.escape(t.id)}"]`)
          ?.focus({ preventScroll: true });
        return;
      }
      setSelected(null);
      // A click makes an event; a tap on a phone only scrolls (hold to make one).
      if (pointer !== "touch")
        create(t.day, t.minute, Math.min(max, t.minute + defaultDuration));
    },
  });

  // ── Keys ───────────────────────────────────────────────
  const onEventKey = (e: React.KeyboardEvent, it: Shown) => {
    if (naming === it.id || it.busy) return;
    const ev = it.ev;
    const move = (dDay: number, dStart: number, dEnd: number) => {
      const day = it.day + dDay;
      if (day < 0 || day >= span) return;
      const start = it.start + dStart;
      const end = it.end + dEnd;
      if (start < min || end > max || end - start < step) return;
      update(
        {
          ...ev,
          start: atMinutes(days[day], start),
          end: atMinutes(days[day], end),
        },
        ev,
        dStart === dEnd ? "Moved to" : "Now",
      );
    };
    const keys: Record<string, () => void> = {
      ArrowUp: () => (e.shiftKey ? move(0, 0, -step) : move(0, -step, -step)),
      ArrowDown: () => (e.shiftKey ? move(0, 0, step) : move(0, step, step)),
      ArrowLeft: () => move(-1, 0, 0),
      ArrowRight: () => move(1, 0, 0),
      Enter: () => setNaming(it.id),
      Delete: () => remove(ev),
      Backspace: () => remove(ev),
      Escape: () => columnsRef.current?.focus({ preventScroll: true }),
    };
    const run = keys[e.key];
    if (!run) return;
    e.preventDefault();
    e.stopPropagation();
    run();
  };

  const onGridKey = (e: React.KeyboardEvent) => {
    if (e.target !== e.currentTarget) return;
    const c = cursor ?? {
      day: Math.max(0, now ? days.findIndex((d) => sameDay(d, now)) : 0),
      minute: 9 * 60,
    };
    const set = (day: number, minute: number) => {
      const next = {
        day: Math.max(0, Math.min(span - 1, day)),
        minute: Math.max(min, Math.min(max - step, minute)),
      };
      setCursor(next);
      setAnnounce(`${fmt.long.format(atMinutes(days[next.day], next.minute))}`);
      const sc = scrollerRef.current;
      const y = (next.minute - min) * ppm;
      if (sc && (y < sc.scrollTop || y > sc.scrollTop + sc.clientHeight - 40))
        sc.scrollTop = y - sc.clientHeight / 3;
    };
    const keys: Record<string, () => void> = {
      ArrowUp: () => set(c.day, c.minute - step),
      ArrowDown: () => set(c.day, c.minute + step),
      ArrowLeft: () => set(c.day - 1, c.minute),
      ArrowRight: () => set(c.day + 1, c.minute),
      PageUp: () => go(-1),
      PageDown: () => go(1),
      Enter: () =>
        create(c.day, c.minute, Math.min(max, c.minute + defaultDuration)),
    };
    const run = keys[e.key];
    if (!run) return;
    e.preventDefault();
    if (!cursor && e.key !== "Enter") setCursor(c);
    run();
  };

  // Handlers the memoised blocks call through a stable ref, so they never re-render just because these were re-created.
  const shownRef = React.useRef(shown);
  const fallbackActions = React.useMemo<BlockActions>(
    () => ({
      key: () => {},
      focus: () => {},
      blur: () => {},
      name: () => {},
    }),
    [],
  );
  const actions = React.useRef<BlockActions>(fallbackActions);
  React.useLayoutEffect(() => {
    shownRef.current = shown;
    actions.current = {
      key: (e, id) => {
        const it = shownRef.current.find((x) => x.id === id);
        if (it) onEventKey(e, it);
      },
      focus: (id) => setSelected(id),
      blur: (id) => setSelected((s) => (s === id ? null : s)),
      name: (id, value) => finishNaming(id, value),
    };
  });

  // ── Render ─────────────────────────────────────────────
  const today = now ? days.findIndex((d) => sameDay(d, now)) : -1;
  const hours = Array.from(
    { length: endHour - startHour },
    (_, i) => startHour + i,
  );
  const gridHeight = (max - min) * ppm;

  return (
    <div
      ref={rootRef}
      className={`w-full text-foreground ${className}`}
      {...props}
    >
      <div className="flex items-center justify-between gap-2">
        <p className="min-w-0 truncate text-[14px] font-medium tracking-[-0.01em]">
          <TextMorph>{rangeLabel}</TextMorph>
        </p>
        <div className="flex shrink-0 items-center gap-0.5">
          <button
            type="button"
            onClick={() => go(0)}
            className={`mr-1 inline-flex h-7 cursor-pointer items-center rounded-full px-2.5 text-[12px] font-medium shadow-[inset_0_0_0_1px_var(--border)] transition-colors hover:bg-accent ${FOCUS}`}
          >
            Today
          </button>
          <button
            type="button"
            aria-label="Previous"
            onClick={() => go(-1)}
            className={`flex size-7 cursor-pointer items-center justify-center rounded-full text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
          >
            <ChevronLeft className="size-4" strokeWidth={1.75} />
          </button>
          <button
            type="button"
            aria-label="Next"
            onClick={() => go(1)}
            className={`flex size-7 cursor-pointer items-center justify-center rounded-full text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
          >
            <ChevronRight className="size-4" strokeWidth={1.75} />
          </button>
        </div>
      </div>
      <div
        className="grid transition-[grid-template-rows] duration-300"
        style={{
          gridTemplateRows: notice ? "1fr" : "0fr",
          transitionTimingFunction: EASE,
        }}
      >
        <div className="min-w-0 overflow-hidden">
          <Line
            text={notice?.text ?? ""}
            className="pt-1.5 text-[12.5px] text-red-600 dark:text-red-400"
          />
        </div>
      </div>

      <div className="mt-3 overflow-hidden rounded-[16px] border border-border">
        {/* Day heads */}
        <div className="flex border-b border-border">
          <div className="w-11 shrink-0" />
          <div
            className="grid flex-1"
            style={{ gridTemplateColumns: `repeat(${span}, minmax(0, 1fr))` }}
          >
            {days.map((d, i) => (
              <DayHead
                key={i}
                weekday={fmt.weekday.format(d)}
                date={d.getDate()}
                today={i === today}
                dir={slide ? (slide.dir > 0 ? "up" : "down") : undefined}
              />
            ))}
          </div>
        </div>

        <div
          ref={scrollerRef}
          className="relative overflow-y-auto overscroll-contain"
          style={{ height }}
        >
          <div className="relative flex" style={{ height: gridHeight }}>
            {/* Hours */}
            <div className="relative w-11 shrink-0" aria-hidden="true">
              {hours.slice(1).map((h) => (
                <span
                  key={h}
                  className="absolute right-2 -translate-y-1/2 text-[10.5px] tabular-nums text-muted-foreground"
                  style={{ top: (h * 60 - min) * ppm }}
                >
                  {fmt.hour.format(atMinutes(days[0], h * 60))}
                </span>
              ))}
            </div>

            <div
              ref={columnsRef}
              tabIndex={0}
              role="group"
              aria-label={`${label}, ${rangeLabel}`}
              aria-describedby={`${uid}-grid-keys`}
              onKeyDown={onGridKey}
              onBlur={(e) => {
                if (!e.currentTarget.contains(e.relatedTarget as Node | null))
                  setCursor(null);
              }}
              {...grid}
              className="relative flex-1 cursor-cell touch-pan-y select-none outline-none"
              style={{
                backgroundImage: `linear-gradient(to bottom, var(--border) 1px, transparent 1px), linear-gradient(to bottom, color-mix(in oklab, var(--border) 45%, transparent) 1px, transparent 1px)`,
                backgroundSize: `100% ${hourHeight}px, 100% ${hourHeight}px`,
                backgroundPosition: `0 ${hourHeight - 0.5}px, 0 ${hourHeight / 2 - 0.5}px`,
              }}
            >
              {/* Day separators */}
              <div
                className="pointer-events-none absolute inset-0 grid"
                style={{
                  gridTemplateColumns: `repeat(${span}, minmax(0, 1fr))`,
                }}
                aria-hidden="true"
              >
                {days.map((_, i) => (
                  <div key={i} className="border-l border-border" />
                ))}
              </div>

              {/* The keyboard's slot */}
              {cursor && (
                <div
                  aria-hidden="true"
                  className="pointer-events-none absolute rounded-[8px] shadow-[inset_0_0_0_1.5px_var(--ring)]"
                  style={{
                    ...geometry({
                      id: "cursor",
                      busy: true,
                      day: cursor.day,
                      start: cursor.minute,
                      end: cursor.minute + defaultDuration,
                    }),
                    transition: reduced
                      ? "none"
                      : `top 180ms ${EASE}, left 220ms ${EASE}`,
                  }}
                />
              )}

              {outgoing && (
                <div
                  key={outgoing.key}
                  aria-hidden="true"
                  className="pointer-events-none absolute inset-0"
                  ref={(el) => {
                    if (!el || el.dataset.out) return;
                    el.dataset.out = "1";
                    el.animate(
                      [
                        { transform: "none", opacity: 1, filter: "blur(0px)" },
                        {
                          transform: `translateX(${-outgoing.dir * 32}px)`,
                          opacity: 0,
                          filter: "blur(4px)",
                        },
                      ],
                      { duration: 260, easing: EASE, fill: "forwards" },
                    ).onfinish = () =>
                      setOutgoing((o) => (o?.key === outgoing.key ? null : o));
                  }}
                >
                  {outgoing.blocks.map((b) => (
                    <div
                      key={b.id}
                      className="absolute overflow-hidden rounded-[8px] px-1.5 py-1 text-[12px] font-medium"
                      style={
                        b.ev.busy
                          ? {
                              ...b.style,
                              backgroundImage:
                                "repeating-linear-gradient(135deg, color-mix(in oklab, var(--foreground) 9%, transparent) 0 1px, transparent 1px 6px)",
                              boxShadow: "inset 0 0 0 1px var(--border)",
                            }
                          : {
                              ...b.style,
                              background: tint(b.ev.tone ?? 1, 13),
                              boxShadow: ring(b.ev.tone ?? 1, 42),
                            }
                      }
                    >
                      <span className="block truncate">
                        {b.ev.busy ? "" : b.ev.title || "New event"}
                      </span>
                    </div>
                  ))}
                </div>
              )}

              {/* Events: one layer for the whole range, so an event dragged across days glides there. */}
              <div
                key={slide?.key ?? 0}
                className="absolute inset-0"
                ref={(el) => {
                  if (!el || !slide || reduced || el.dataset.in) return;
                  el.dataset.in = "1";
                  el.animate(
                    [
                      {
                        transform: `translateX(${slide.dir * 32}px)`,
                        opacity: 0,
                        filter: "blur(4px)",
                      },
                      { transform: "none", opacity: 1, filter: "blur(0px)" },
                    ],
                    { duration: 460, easing: EASE },
                  );
                }}
              >
                {shown.map((it) => {
                  const ev = it.ev;
                  const lifted = draft?.id === it.id;
                  const g = geometry(it);
                  if (it.busy)
                    return (
                      <div
                        key={it.id}
                        data-event-id={it.id}
                        data-busy="1"
                        aria-label={`Busy, ${fmt.long.format(atMinutes(days[it.day], it.start))} to ${fmt.time.format(atMinutes(days[it.day], it.end))}`}
                        role="note"
                        className="pointer-events-none absolute overflow-hidden rounded-[8px] px-1.5 py-1 text-[11px] text-muted-foreground"
                        style={{
                          ...g,
                          backgroundImage:
                            "repeating-linear-gradient(135deg, color-mix(in oklab, var(--foreground) 9%, transparent) 0 1px, transparent 1px 6px)",
                          boxShadow: "inset 0 0 0 1px var(--border)",
                        }}
                      >
                        {ev.title || "Busy"}
                      </div>
                    );
                  const over = lifted ? (overlapsOf(it)[0] ?? "") : "";
                  const tall = (it.end - it.start) * ppm - 2 >= 34;
                  return (
                    <EventBlock
                      key={it.id}
                      id={it.id}
                      title={ev.title}
                      tone={ev.tone ?? 1}
                      draft={!!it.draft}
                      top={g.top as number}
                      height={g.height as number}
                      left={g.left as string}
                      width={g.width as string}
                      zIndex={g.zIndex}
                      lifted={lifted}
                      selected={selected === it.id && !lifted}
                      tall={tall}
                      roomy={tall && (it.end - it.start) * ppm >= 52}
                      over={over}
                      live={lifted || rolling.has(it.id)}
                      naming={naming === it.id}
                      saving={saving.has(it.id)}
                      start={it.start}
                      end={it.end}
                      hour12={hour12}
                      reduced={reduced}
                      label={
                        describe(ev, it) + (over ? `. Overlaps ${over}.` : "")
                      }
                      keysId={`${uid}-event-keys`}
                      actions={actions}
                    />
                  );
                })}

                {gone.map((g) => (
                  <div
                    key={g.key}
                    aria-hidden="true"
                    className="pointer-events-none absolute overflow-hidden rounded-[8px] px-1.5 py-1 text-[12px] font-medium"
                    style={{
                      ...g.style,
                      background: tint(g.ev.tone ?? 1, 13),
                      boxShadow: ring(g.ev.tone ?? 1, 42),
                    }}
                    ref={(el) => {
                      if (!el || el.dataset.out) return;
                      el.dataset.out = "1";
                      el.animate(
                        [
                          {
                            opacity: 1,
                            transform: "none",
                            filter: "blur(0px)",
                          },
                          {
                            opacity: 0,
                            transform: "scale(0.94)",
                            filter: "blur(4px)",
                          },
                        ],
                        { duration: 280, easing: EASE, fill: "forwards" },
                      ).onfinish = () =>
                        setGone((all) => all.filter((x) => x.key !== g.key));
                    }}
                  >
                    {g.ev.title || "New event"}
                  </div>
                ))}
              </div>

              {/* Now */}
              {today >= 0 &&
                now &&
                minutesOf(now) >= min &&
                minutesOf(now) <= max && (
                  <div
                    aria-hidden="true"
                    className="pointer-events-none absolute z-50 h-px bg-primary"
                    style={{
                      top: (minutesOf(now) - min) * ppm,
                      left: `${(today / span) * 100}%`,
                      width: `${100 / span}%`,
                      transition: reduced ? "none" : `top 1s ${EASE}`,
                    }}
                  >
                    <span className="absolute -left-[3.5px] -top-[3px] size-[7px] rounded-full bg-primary" />
                  </div>
                )}
            </div>
          </div>
        </div>
      </div>

      <p id={`${uid}-grid-keys`} className="sr-only">
        Arrow keys pick a time, Enter adds an event there, Page Up and Page Down
        change the {span === 1 ? "day" : "week"}. Tab moves to the events.
      </p>
      <p id={`${uid}-event-keys`} className="sr-only">
        Arrow keys move the event, Shift with up or down changes its length,
        Enter renames it, Delete removes it.
      </p>
      <p className="sr-only" role="status" aria-live="polite">
        {announce}
      </p>
    </div>
  );
}

"use client";

/* ─────────────────────────────────────────────────────────
 * WHEEL PICKER: drums you can fling
 *
 *   drum      every column is a real cylinder: options sit on
 *             its faces and tip away into the dark as they
 *             leave the middle, one transform a frame
 *   lens      the middle row is a separate copy of the drum,
 *             clipped to the band, in full colour; a letter
 *             crossing the band's edge is half one, half the
 *             other, like glass over the wheel
 *   fling     drag and let go: the release speed is projected
 *             forward and the wheel decays onto a row, with a
 *             tick on phones for each row it passes; past the
 *             ends of a wheel that doesn't loop it stretches
 *   settle    the value is committed once the wheel rests, and
 *             a unit beside the lens morphs with it (1 hour,
 *             2 hours). Options that can't be chosen are dimmed
 *             and the wheel turns on past them
 *
 * Each wheel is a spinbutton: arrows step, Page Up and Down
 * jump five, Home and End go to the ends; a mouse notch moves
 * one row and taps on a row bring it to the middle.
 * ───────────────────────────────────────────────────────── */

import * as React from "react";
import { TextMorph } from "./text-morph";
import { useInteractionReducedMotion } from "./imported-ui-interaction-motion";
import { SLOTS, STEP, useWheelDrum } from "./use-wheel-drum";

export type WheelValue = string | number;
export type WheelOption<T extends WheelValue = WheelValue> =
  T | { value: T; label?: string; disabled?: boolean };

export interface WheelPickerProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Row height in px; the drum's radius follows from it. */
  itemHeight?: number;
  /** Ticks on phones that can vibrate, one per row. */
  haptics?: boolean;
  children: React.ReactNode;
}

export interface WheelProps<T extends WheelValue = WheelValue> {
  options: readonly WheelOption<T>[];
  value?: NoInfer<T>;
  defaultValue?: NoInfer<T>;
  onValueChange?: (value: NoInfer<T>) => void;
  /** Turn past the end back to the start, like minutes. */
  loop?: boolean;
  /** What the wheel sets, for screen readers: "Hours". */
  label: string;
  /** Fixed beside the lens: "min", or a function for "1 hour" / "2 hours". */
  unit?: string | ((value: NoInfer<T>) => string);
  /** Where the options sit in their column. */
  align?: "start" | "center" | "end";
  className?: string;
  style?: React.CSSProperties;
}

const Ctx = React.createContext({ itemHeight: 36, haptics: true });
const PERSPECTIVE = 1000;

const valueOf = <T extends WheelValue>(o: WheelOption<T>) =>
  typeof o === "object" ? o.value : o;
const labelOf = <T extends WheelValue>(o: WheelOption<T>) =>
  typeof o === "object" ? (o.label ?? String(o.value)) : String(o);
const offOf = <T extends WheelValue>(o: WheelOption<T>) =>
  typeof o === "object" && Boolean(o.disabled);

export function WheelPicker({
  itemHeight = 36,
  haptics = true,
  className = "",
  style,
  children,
  ...props
}: WheelPickerProps) {
  const H = Math.max(28, Math.min(56, itemHeight));
  const radius = H / (2 * Math.tan((STEP / 2) * (Math.PI / 180)));
  const ctx = React.useMemo(() => ({ itemHeight: H, haptics }), [H, haptics]);
  return (
    <Ctx.Provider value={ctx}>
      <div
        role="group"
        className={`relative flex w-full select-none justify-center px-2 ${className}`}
        style={{ height: Math.round(radius * 2), ...style }}
        {...props}
      >
        <div
          aria-hidden="true"
          className="pointer-events-none absolute inset-x-0 top-1/2 -translate-y-1/2 rounded-[11px] bg-muted"
          style={{ height: H }}
        />
        {children}
      </div>
    </Ctx.Provider>
  );
}

export function Wheel<T extends WheelValue = WheelValue>({
  options,
  value,
  defaultValue,
  onValueChange,
  loop = false,
  label,
  unit,
  align = "center",
  className = "",
  style,
}: WheelProps<T>) {
  const { itemHeight: H, haptics } = React.useContext(Ctx);
  const reduced = useInteractionReducedMotion();
  const count = options.length;
  const indexOf = (v: T | undefined) =>
    Math.max(
      0,
      options.findIndex((o) => valueOf(o) === v),
    );
  const [own, setOwn] = React.useState<T | undefined>(
    defaultValue ?? (count ? valueOf(options[0]) : undefined),
  );
  const current = value !== undefined ? value : own;
  const index = indexOf(current);

  const optionsRef = React.useRef(options);
  const report = React.useRef(onValueChange);
  React.useLayoutEffect(() => {
    optionsRef.current = options;
    report.current = onValueChange;
  });
  const controlled = value !== undefined;
  const committed = React.useRef(index);

  const drum = useWheelDrum(index, {
    count,
    loop,
    itemHeight: H,
    reduced,
    haptics,
    label: (i) => labelOf(optionsRef.current[i]),
    disabled: (i) => offOf(optionsRef.current[i]),
    onRest: (i) => {
      if (i === committed.current) return;
      committed.current = i;
      const next = valueOf(optionsRef.current[i]);
      if (!controlled) setOwn(next);
      report.current?.(next);
    },
  });

  // The value changed from outside (another wheel clamped it, or the app set it): turn to it.
  const first = React.useRef(true);
  React.useEffect(() => {
    if (first.current) {
      first.current = false;
      return;
    }
    if (index === committed.current) return;
    committed.current = index;
    drum.turnTo(index, !reduced);
  }, [index]);

  // Labels or disabled options changed: relabel the faces in place.
  const labels = options
    .map((o) => `${labelOf(o)}${offOf(o) ? "·" : ""}`)
    .join("|");
  React.useEffect(() => {
    drum.repaint();
  }, [labels]);

  // Faces are labelled once here; the drum relabels them directly as it turns.
  const [faceText] = React.useState(() =>
    Array.from({ length: SLOTS }, (_, k) => {
      const i = k + SLOTS * Math.round((index - k) / SLOTS);
      const real = loop ? ((i % count) + count) % count : i;
      return count && (loop || (i >= 0 && i < count))
        ? labelOf(options[real])
        : "";
    }),
  );

  const unitOf = (v: T) =>
    typeof unit === "function" ? unit(v) : (unit ?? "");
  const unitText = current !== undefined && unit ? unitOf(current) : "";
  const widest = unit
    ? options
        .map((o) => unitOf(valueOf(o)))
        .reduce((a, b) => (b.length > a.length ? b : a), "")
    : "";

  const onKeyDown = (e: React.KeyboardEvent) => {
    const moves: Record<string, number> = {
      ArrowUp: -1,
      ArrowDown: 1,
      PageUp: -5,
      PageDown: 5,
    };
    if (e.key in moves) {
      e.preventDefault();
      drum.nudge(moves[e.key]);
    } else if (e.key === "Home" || e.key === "End") {
      e.preventDefault();
      const to = e.key === "Home" ? 0 : count - 1;
      drum.turnTo(to, !reduced);
    }
  };

  const justify =
    align === "start"
      ? "justify-start"
      : align === "end"
        ? "justify-end"
        : "justify-center";
  const faceClass = `absolute inset-x-0 flex items-center whitespace-nowrap px-2.5 tabular-nums [backface-visibility:hidden] data-[off]:opacity-35 ${justify}`;
  const face = (k: number) => ({
    top: -H / 2,
    height: H,
    transform: `rotateX(${-k * STEP}deg) translateZ(${drum.radius}px)`,
  });
  const edge = `calc(50% - ${H / 2}px)`,
    edge2 = `calc(50% + ${H / 2}px)`;
  // The drum fades toward its rim and leaves a hole where the lens copy sits.
  const mask = `linear-gradient(to bottom, transparent 8%, #000 36%, #000 ${edge}, transparent ${edge}, transparent ${edge2}, #000 ${edge2}, #000 64%, transparent 92%)`;
  // The first frame's rotation; after that the drum writes its own transform, so React must never touch it.
  const [current3d] = React.useState(() => ({
    transformStyle: "preserve-3d" as const,
    transform: `translateZ(${-drum.radius}px) rotateX(${index * STEP}deg)`,
  }));

  return (
    <div
      ref={(el) => drum.attachColumn(el)}
      role="spinbutton"
      tabIndex={0}
      aria-label={label}
      aria-valuenow={index}
      aria-valuemin={0}
      aria-valuemax={Math.max(0, count - 1)}
      aria-valuetext={`${count ? labelOf(options[index]) : ""}${unitText ? ` ${unitText}` : ""}`}
      onKeyDown={onKeyDown}
      className={`group relative flex h-full min-w-0 flex-1 cursor-grab touch-none items-center outline-none active:cursor-grabbing ${className}`}
      style={style}
    >
      <div
        className="relative h-full min-w-0 flex-1 tracking-[-0.01em]"
        style={{ fontSize: Math.round(H * 0.56) }}
      >
        <div
          aria-hidden="true"
          className="absolute inset-0 text-muted-foreground"
          style={{
            perspective: PERSPECTIVE,
            maskImage: mask,
            WebkitMaskImage: mask,
          }}
        >
          <div
            ref={(el) => drum.attachDrum(el)}
            className="absolute inset-x-0 top-1/2 h-0 will-change-transform"
            style={current3d}
          >
            {faceText.map((t, k) => (
              <span
                key={k}
                ref={(el) => drum.attachFace(k, el)}
                className={faceClass}
                style={face(k)}
              >
                {t}
              </span>
            ))}
          </div>
        </div>
        <div
          aria-hidden="true"
          className="absolute inset-x-0 top-1/2 -translate-y-1/2 overflow-hidden rounded-[11px] text-foreground group-focus-visible:ring-2 group-focus-visible:ring-ring/50"
          style={{ height: H, perspective: PERSPECTIVE }}
        >
          <div
            ref={(el) => drum.attachLens(el)}
            className="absolute inset-x-0 top-1/2 h-0 will-change-transform"
            style={current3d}
          >
            {faceText.map((t, k) => (
              <span
                key={k}
                ref={(el) => drum.attachLensFace(k, el)}
                className={faceClass}
                style={face(k)}
              >
                {t}
              </span>
            ))}
          </div>
        </div>
      </div>
      {unit && (
        <span
          aria-hidden="true"
          className="relative grid shrink-0 pr-2.5 text-[14px] font-medium text-foreground"
        >
          <span className="invisible col-start-1 row-start-1 whitespace-nowrap">
            {widest}
          </span>
          <span className="col-start-1 row-start-1 whitespace-nowrap">
            <TextMorph animateWidth={false}>{unitText}</TextMorph>
          </span>
        </span>
      )}
    </div>
  );
}

"use client";

import * as React from "react";
import { Circle, Maximize2, Minus, Plus } from "lucide-react";
import { WorkflowConnections } from "./workflow-connections";
import { useWorkflowViewport } from "./use-workflow-viewport";
import {
  INTERACTION_FOCUS,
  useInteractionReducedMotion,
  useInteractionActivity,
} from "./imported-ui-interaction-motion";
import {
  WorkflowStatusMark,
  WORKFLOW_STATUS as STATUS,
} from "./workflow-status";
import { WorkflowInspector } from "./workflow-inspector";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";
import {
  NODE_WIDTH,
  NODE_HEIGHT,
  type WorkflowNode,
  type WorkflowEdge,
  type WorkflowPoint,
} from "./workflow-types";
export type {
  WorkflowNode,
  WorkflowEdge,
  WorkflowPoint,
  WorkflowStatus,
} from "./workflow-types";

export interface WorkflowCanvasProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onSelect"
> {
  nodes: WorkflowNode[];
  edges: WorkflowEdge[];
  width?: number;
  height?: number;
  label?: string;
  onNodeMove?: (id: string, position: WorkflowPoint) => void;
  onNodeSelect?: (id: string | null) => void;
}
const CONTROL = `cursor-pointer disabled:cursor-default flex size-8 items-center justify-center rounded-lg text-muted-foreground transition-colors hover:bg-accent hover:text-foreground disabled:opacity-30 ${INTERACTION_FOCUS}`;

interface WorkflowNodeButtonProps {
  node: WorkflowNode;
  index: number;
  nodes: WorkflowNode[];
  selected: boolean;
  detailsId: string;
  position: WorkflowPoint;
  reduced: boolean;
  active: boolean;
  onChoose: (id: string | null) => void;
  onReveal: (id: string) => void;
  onMove: (id: string, dx: number, dy: number) => void;
  onFocusNode: (id: string) => void;
  onRegister: (id: string, el: HTMLButtonElement | null) => void;
}

function WorkflowNodeButton({
  node,
  index,
  nodes,
  selected,
  detailsId,
  position,
  reduced,
  active,
  onChoose,
  onReveal,
  onMove,
  onFocusNode,
  onRegister,
}: WorkflowNodeButtonProps) {
  const status = node.status ?? "idle";
  return (
    <button
      key={node.id}
      type="button"
      ref={(el) => onRegister(node.id, el)}
      data-workflow-node={node.id}
      aria-label={`${node.title}, ${STATUS[status]}`}
      aria-expanded={selected}
      aria-controls={selected ? detailsId : undefined}
      onClick={() => onChoose(selected ? null : node.id)}
      onFocus={() => onReveal(node.id)}
      onKeyDown={(event) => {
        if (event.key === "Escape") {
          event.preventDefault();
          onChoose(null);
        }
        if (
          event.key === "ArrowLeft" ||
          event.key === "ArrowRight" ||
          event.key === "ArrowDown" ||
          event.key === "ArrowUp"
        ) {
          event.preventDefault();
          if (event.altKey) {
            onMove(
              node.id,
              event.key === "ArrowRight"
                ? 12
                : event.key === "ArrowLeft"
                  ? -12
                  : 0,
              event.key === "ArrowDown"
                ? 12
                : event.key === "ArrowUp"
                  ? -12
                  : 0,
            );
            return;
          }
          const offset =
            event.key === "ArrowRight" || event.key === "ArrowDown" ? 1 : -1;
          onFocusNode(nodes[(index + offset + nodes.length) % nodes.length].id);
        }
      }}
      className={`cursor-pointer absolute left-0 top-0 flex flex-col justify-between rounded-xl border bg-card px-3 py-2.5 text-left text-card-foreground transition-[border-color] duration-300 ${INTERACTION_FOCUS} ${
        status === "error"
          ? "border-destructive/50"
          : selected || status === "running"
            ? "border-primary/70"
            : "border-border"
      }`}
      style={{
        width: NODE_WIDTH,
        height: NODE_HEIGHT,
        transform: `translate(${position.x}px, ${position.y}px)`,
      }}
    >
      <span className="flex w-full items-center gap-2">
        <span className="flex size-5 shrink-0 items-center justify-center rounded-md border border-border bg-muted/40 text-muted-foreground">
          {node.icon ?? <Circle className="size-3" aria-hidden="true" />}
        </span>
        <span className="truncate text-[12px] font-medium">
          <TextMorph>{node.title}</TextMorph>
        </span>
      </span>
      <span className="flex w-full items-center justify-between gap-2">
        <span className="truncate text-[11px] text-muted-foreground">
          <TextMorph>{node.subtitle ?? STATUS[status]}</TextMorph>
        </span>
        <WorkflowStatusMark status={status} reduced={reduced} active={active} />
      </span>
    </button>
  );
}

/** A bounded workflow viewer with movable nodes, a shared pan/zoom transform and live execution states. */
export function WorkflowCanvas({
  nodes,
  edges,
  width = 660,
  height = 340,
  label = "Workflow",
  onNodeMove,
  onNodeSelect,
  className = "",
  ...props
}: WorkflowCanvasProps) {
  const reduced = useInteractionReducedMotion();
  const { ref: activityRef, active } = useInteractionActivity<HTMLDivElement>();
  const [selected, setSelected] = React.useState<string | null>(null);
  const nodeRefs = React.useRef(new Map<string, HTMLButtonElement>());
  const canvasWidth = Math.max(NODE_WIDTH, width),
    canvasHeight = Math.max(NODE_HEIGHT, height);
  const {
    viewport,
    world,
    positions,
    view,
    dragging,
    fit,
    zoom,
    revealNode,
    moveNode,
    handlers,
  } = useWorkflowViewport(
    nodes,
    edges,
    canvasWidth,
    canvasHeight,
    reduced,
    onNodeMove,
  );
  const selectedNode = nodes.find((node) => node.id === selected);
  const detailsId = React.useId();
  const choose = (id: string | null) => {
    setSelected(id);
    onNodeSelect?.(id);
  };

  const registerNode = React.useCallback(
    (id: string, el: HTMLButtonElement | null) => {
      if (el) nodeRefs.current.set(id, el);
      else nodeRefs.current.delete(id);
    },
    [],
  );

  const focusNode = React.useCallback((id: string) => {
    nodeRefs.current.get(id)?.focus({ preventScroll: true });
  }, []);

  return (
    <div
      ref={activityRef}
      role="region"
      aria-label={label}
      className={`w-full overflow-clip rounded-[20px] border border-border bg-background text-foreground ${className}`}
      {...props}
    >
      <div className="flex items-center justify-between gap-3 border-b border-border px-4 py-3">
        <span className="text-[12px] font-medium">{label}</span>
        <span className="font-mono text-[10px] text-muted-foreground">
          <NumberRoll value={nodes.length} /> nodes ·{" "}
          <NumberRoll value={edges.length} /> connections
        </span>
      </div>
      <div
        ref={viewport}
        {...handlers}
        data-lenis-prevent
        className={`relative h-[300px] overflow-clip bg-muted/35 ${dragging ? "cursor-grabbing" : "cursor-grab"}`}
        style={{
          touchAction: "none",
          backgroundImage:
            "radial-gradient(var(--border) 1px, transparent 1px)",
          backgroundSize: "16px 16px",
        }}
      >
        <div
          ref={world}
          className="absolute left-0 top-0 origin-top-left"
          style={{
            width: canvasWidth,
            height: canvasHeight,
            transform: `translate(${view.x}px, ${view.y}px) scale(${view.scale})`,
          }}
        >
          <WorkflowConnections
            nodes={nodes}
            edges={edges}
            positions={positions}
            reduced={reduced}
            width={canvasWidth}
            height={canvasHeight}
          />
          {nodes.map((node, index) => (
            <WorkflowNodeButton
              key={node.id}
              node={node}
              index={index}
              nodes={nodes}
              selected={selected === node.id}
              detailsId={detailsId}
              position={positions[node.id]}
              reduced={reduced}
              active={active}
              onChoose={choose}
              onReveal={revealNode}
              onMove={moveNode}
              onFocusNode={focusNode}
              onRegister={registerNode}
            />
          ))}
        </div>
        <div
          data-workflow-control
          className="absolute bottom-3 left-3 flex items-center gap-0.5 rounded-xl border border-border bg-background p-1"
        >
          <button
            type="button"
            aria-label="Zoom out"
            disabled={view.scale <= 0.25}
            onClick={() => zoom(1 / 1.2)}
            className={CONTROL}
          >
            <Minus className="size-3.5" aria-hidden="true" />
          </button>
          <output
            aria-label="Zoom level"
            className="w-11 text-center font-mono text-[10px] tabular-nums text-muted-foreground"
          >
            <NumberRoll value={Math.round(view.scale * 100)} />%
          </output>
          <button
            type="button"
            aria-label="Zoom in"
            disabled={view.scale >= 1.75}
            onClick={() => zoom(1.2)}
            className={CONTROL}
          >
            <Plus className="size-3.5" aria-hidden="true" />
          </button>
          <span className="mx-1 h-3 w-px bg-border" />
          <button
            type="button"
            aria-label="Fit workflow"
            onClick={fit}
            className={CONTROL}
          >
            <Maximize2 className="size-3.5" aria-hidden="true" />
          </button>
        </div>
      </div>
      <WorkflowInspector
        id={detailsId}
        node={selectedNode}
        reduced={reduced}
        onClose={() => {
          choose(null);
          if (selectedNode) focusNode(selectedNode.id);
        }}
      />
      <p role="status" aria-live="polite" className="sr-only">
        {nodes
          .filter((node) => node.status === "running")
          .map((node) => `${node.title} running`)
          .join(". ") ||
          (nodes.some((node) => node.status === "error")
            ? "Workflow has a failed step."
            : nodes.length > 0 &&
                nodes.every((node) => node.status === "complete")
              ? "Workflow complete."
              : "Workflow ready.")}
      </p>
    </div>
  );
}

"use client";

import * as React from "react";
import {
  workflowPath,
  type WorkflowEdge,
  type WorkflowNode,
  type WorkflowPoint,
} from "./workflow-types";

function Connection({
  edge,
  nodes,
  positions,
  reduced,
  playing,
}: {
  edge: WorkflowEdge;
  nodes: WorkflowNode[];
  positions: Record<string, WorkflowPoint>;
  reduced: boolean;
  playing: boolean;
}) {
  const ref = React.useRef<SVGPathElement>(null);
  const from = nodes.find((node) => node.id === edge.from),
    to = nodes.find((node) => node.id === edge.to);
  const active = from?.status === "complete" && to?.status === "running";
  const completed = from?.status === "complete" && to?.status === "complete";
  const d =
    from && to
      ? workflowPath(positions[from.id] ?? from, positions[to.id] ?? to)
      : "";
  React.useEffect(() => {
    const path = ref.current;
    if (!path || !active || !playing || reduced) return;
    const length = path.getTotalLength();
    path.style.strokeDasharray = `14 ${length}`;
    const animation = path.animate(
      [{ strokeDashoffset: "0" }, { strokeDashoffset: String(-length - 14) }],
      {
        duration: Math.max(700, length / 0.2),
        iterations: Infinity,
        easing: "linear",
      },
    );
    return () => {
      animation.cancel();
      path.style.strokeDasharray = "";
    };
  }, [active, playing, reduced, d]);
  if (!from || !to) return null;
  return (
    <g>
      <path
        data-workflow-edge={edge.id}
        d={d}
        fill="none"
        stroke={active || completed ? "var(--primary)" : "var(--border)"}
        strokeOpacity={active || completed ? 0.35 : 1}
        strokeWidth="1.5"
      />
      {active && (
        <path
          ref={ref}
          data-workflow-edge={edge.id}
          d={d}
          fill="none"
          stroke="var(--primary)"
          strokeWidth="2"
          strokeLinecap="round"
          opacity={reduced ? 0.6 : 1}
        />
      )}
    </g>
  );
}

export function WorkflowConnections({
  nodes,
  edges,
  positions,
  reduced,
  width,
  height,
}: {
  nodes: WorkflowNode[];
  edges: WorkflowEdge[];
  positions: Record<string, WorkflowPoint>;
  reduced: boolean;
  width: number;
  height: number;
}) {
  const ref = React.useRef<SVGSVGElement>(null);
  const [visible, setVisible] = React.useState(false);
  const [hidden, setHidden] = React.useState(false);
  React.useEffect(() => {
    const svg = ref.current;
    if (!svg) return;
    const observer = new IntersectionObserver(([entry]) =>
      setVisible(entry.isIntersecting),
    );
    observer.observe(svg);
    const visibility = () => setHidden(document.hidden);
    visibility();
    document.addEventListener("visibilitychange", visibility);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", visibility);
    };
  }, []);
  return (
    <svg
      ref={ref}
      aria-hidden="true"
      width={width}
      height={height}
      className="pointer-events-none absolute inset-0 overflow-visible"
    >
      {edges.map((edge) => (
        <Connection
          key={edge.id}
          edge={edge}
          nodes={nodes}
          positions={positions}
          reduced={reduced}
          playing={visible && !hidden}
        />
      ))}
    </svg>
  );
}

"use client";

import * as React from "react";
import { X } from "lucide-react";
import { TextMorph } from "./text-morph";
import { EASE_OUT, INTERACTION_FOCUS } from "./imported-ui-interaction-motion";
import { WORKFLOW_STATUS } from "./workflow-status";
import type { WorkflowNode } from "./workflow-types";

export function WorkflowInspector({
  node,
  onClose,
  reduced,
  id,
}: {
  node?: WorkflowNode;
  onClose: () => void;
  reduced: boolean;
  id: string;
}) {
  const [kept, setKept] = React.useState(node);
  if (node && kept !== node) setKept(node);
  const displayed = node ?? kept;
  const content = React.useRef<HTMLDivElement>(null);
  const measure = React.useRef<HTMLDivElement>(null);
  const [height, setHeight] = React.useState(0);
  const hasDisplayed = Boolean(displayed);
  React.useLayoutEffect(() => {
    const el = measure.current;
    if (!el) return;
    const observer = new ResizeObserver(() =>
      setHeight((previous) =>
        previous === el.offsetHeight ? previous : el.offsetHeight,
      ),
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [hasDisplayed]);
  React.useLayoutEffect(() => {
    const el = content.current;
    if (!el || !node || reduced) return;
    const animation = el.animate(
      [
        { opacity: 0, transform: "translateY(6px)" },
        { opacity: 1, transform: "none" },
      ],
      { duration: 300, easing: EASE_OUT },
    );
    return () => animation.cancel();
  }, [node, reduced]);
  return (
    <div
      id={id}
      aria-hidden={!node || undefined}
      inert={!node}
      className="overflow-hidden"
      style={{
        height: node ? height : 0,
        transition: reduced ? "none" : `height 380ms ${EASE_OUT}`,
      }}
    >
      {displayed && (
        <div ref={measure} className="border-t border-border bg-card p-4">
          <div className="flex items-center justify-between gap-3">
            <div>
              <p className="text-[13px] font-medium">
                <TextMorph>{displayed.title}</TextMorph>
              </p>
              <p
                className={`mt-0.5 text-[12px] ${displayed.status === "error" ? "text-destructive" : "text-muted-foreground"}`}
              >
                <TextMorph>
                  {WORKFLOW_STATUS[displayed.status ?? "idle"]}
                </TextMorph>
              </p>
            </div>
            <button
              type="button"
              aria-label="Close node details"
              onClick={onClose}
              className={`cursor-pointer flex size-8 items-center justify-center rounded-lg text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${INTERACTION_FOCUS}`}
            >
              <X className="size-3.5" aria-hidden="true" />
            </button>
          </div>
          <div
            ref={content}
            className="mt-3 text-[13px] leading-relaxed text-muted-foreground"
          >
            {displayed.detail}
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { Circle, CircleAlert } from "lucide-react";
import { interactionIcon } from "./imported-ui-interaction-motion";
import type { WorkflowStatus } from "./workflow-types";

export const WORKFLOW_STATUS: Record<WorkflowStatus, string> = {
  idle: "Ready",
  queued: "Queued",
  running: "Running",
  complete: "Complete",
  error: "Failed",
};

export function WorkflowStatusMark({
  status,
  reduced,
  active,
}: {
  status: WorkflowStatus;
  reduced: boolean;
  active: boolean;
}) {
  return (
    <span aria-hidden="true" className="relative size-3.5 shrink-0">
      <span
        className="absolute inset-0 flex items-center justify-center"
        style={interactionIcon(
          status === "idle" || status === "queued",
          reduced,
        )}
      >
        <Circle
          className={`size-3 text-muted-foreground ${status === "queued" ? "fill-muted-foreground/20" : ""}`}
        />
      </span>
      <span
        className="absolute inset-0"
        style={interactionIcon(status === "running", reduced)}
      >
        <span
          className={`block size-3.5 rounded-full border-[1.5px] border-primary/25 border-t-primary ${status === "running" && !reduced ? "animate-spin" : ""}`}
          style={{ animationPlayState: active ? "running" : "paused" }}
        />
      </span>
      <svg
        viewBox="0 0 16 16"
        className="absolute inset-0 size-3.5 text-primary"
        style={interactionIcon(status === "complete", reduced)}
      >
        <path
          d="m3 8 3 3 7-7"
          fill="none"
          stroke="currentColor"
          strokeWidth="1.6"
          strokeLinecap="round"
          strokeLinejoin="round"
          pathLength={1}
          style={{
            strokeDasharray: 1,
            strokeDashoffset: status === "complete" ? 0 : 1,
            transition: reduced
              ? "none"
              : "stroke-dashoffset 380ms ease-out 80ms",
          }}
        />
      </svg>
      <CircleAlert
        className="absolute inset-0 size-3.5 text-destructive"
        style={interactionIcon(status === "error", reduced)}
      />
    </span>
  );
}

import type * as React from "react";

export type WorkflowStatus =
  "idle" | "queued" | "running" | "complete" | "error";
export type WorkflowPoint = { x: number; y: number };
export interface WorkflowNode extends WorkflowPoint {
  id: string;
  title: string;
  subtitle?: string;
  icon?: React.ReactNode;
  status?: WorkflowStatus;
  detail?: React.ReactNode;
}
export interface WorkflowEdge {
  id: string;
  from: string;
  to: string;
}
export const NODE_WIDTH = 164;
export const NODE_HEIGHT = 78;

/** Rounded elbows for forward connections; a smooth loop for nodes dragged behind their source. */
export function workflowPath(from: WorkflowPoint, to: WorkflowPoint) {
  const x1 = from.x + NODE_WIDTH,
    y1 = from.y + NODE_HEIGHT / 2;
  const x2 = to.x,
    y2 = to.y + NODE_HEIGHT / 2;
  if (x2 - x1 < 40) {
    const reach = Math.max(60, Math.abs(x2 - x1) * 0.6);
    return `M ${x1} ${y1} C ${x1 + reach} ${y1}, ${x2 - reach} ${y2}, ${x2} ${y2}`;
  }
  if (Math.abs(y2 - y1) < 2) return `M ${x1} ${y1} H ${x2}`;
  const mid = (x1 + x2) / 2,
    sign = Math.sign(y2 - y1),
    radius = Math.min(14, Math.abs(y2 - y1) / 2);
  return `M ${x1} ${y1} H ${mid - radius} Q ${mid} ${y1} ${mid} ${y1 + sign * radius} V ${y2 - sign * radius} Q ${mid} ${y2} ${mid + radius} ${y2} H ${x2}`;
}

