.imported-demo {
  width: 100%;
  min-height: 400px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 56px 32px;
  font-size: 14px;
  line-height: 1.6;
}
.imported-demo-stage {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 100%;
  max-width: 640px;
  min-width: 0;
  gap: 24px;
}
.imported-demo-stage > [class~="@container"] {
  align-self: stretch;
}
.imported-demo-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  align-self: center;
  gap: 8px;
  padding: 8px 14px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--background);
  color: var(--foreground);
  font: inherit;
  font-size: 13px;
  cursor: pointer;
}
.imported-demo-button:hover {
  background: var(--muted);
}
.imported-demo-input {
  display: block;
  width: 100%;
  min-height: 36px;
  padding: 6px 10px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--background);
  color: var(--foreground);
  font: inherit;
}
.imported-demo-card {
  padding: 24px;
  border: 1px solid var(--border);
  border-radius: 14px;
  background: var(--card);
}
.imported-demo-feedback {
  min-height: 1.5em;
  color: var(--muted-foreground);
  font-size: 12px;
  text-align: center;
}
.imported-demo-button:focus-visible,
.imported-demo-input:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 3px;
}
@media (max-width: 639px) {
  .imported-demo {
    padding: 40px 16px;
    min-height: 320px;
  }
  .imported-demo-compact {
    padding-inline: 0;
  }
}

.primitive-demo {
  position: relative;
  width: 100%;
  min-height: 380px;
  display: flex;
  flex-direction: column;
  align-items: center;
  font-family: "Geist", sans-serif;
  -webkit-font-smoothing: antialiased;
}
.primitive-stage {
  flex: 1;
  width: 100%;
  min-height: 380px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 64px 32px 96px;
  gap: 32px;
}
.primitive-text {
  font-size: 48px;
  line-height: 1.2;
  font-weight: 500;
  letter-spacing: -0.045em;
}
.primitive-number {
  font-size: clamp(42px, 7vw, 64px);
  line-height: 1.15;
  font-weight: 500;
  letter-spacing: -0.04em;
  max-width: 100%;
}
.primitive-options {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 6px;
  max-width: 420px;
}
.primitive-options button {
  border: 0;
  box-shadow: inset 0 0 0 1px var(--border);
  border-radius: 999px;
  height: 32px;
  padding: 0 12px;
  background: var(--background);
  color: var(--muted-foreground);
  font: inherit;
  font-size: 12.5px;
  cursor: pointer;
  transition:
    background 0.15s,
    color 0.15s;
}
.primitive-options button:hover {
  background: var(--muted);
  color: var(--foreground);
}
.primitive-options button[aria-pressed="true"] {
  background: var(--primary);
  color: var(--primary-foreground);
  box-shadow: none;
}
.primitive-demo button:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 3px;
}
.primitive-tabs {
  position: absolute;
  bottom: 20px;
  display: flex;
  border-radius: 999px;
  background: var(--muted);
  padding: 3px;
  margin: 0;
}
.primitive-tabs button {
  position: relative;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--muted-foreground);
  padding: 5px 14px;
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}
.primitive-tabs button[aria-selected="true"] {
  color: var(--primary-foreground);
}
.video-player-demo-tabs > .primitive-tabs {
  position: relative;
  bottom: auto;
  flex-shrink: 0;
  white-space: nowrap;
}
.primitive-tab-highlight {
  position: absolute;
  top: 3px;
  bottom: 3px;
  left: 0;
  border-radius: 999px;
  background: var(--primary);
  box-shadow: 0 1px 4px #00000012;
  transition:
    transform 380ms cubic-bezier(0.16, 1, 0.3, 1),
    width 380ms cubic-bezier(0.16, 1, 0.3, 1);
  pointer-events: none;
}
@media (prefers-reduced-motion: reduce) {
  .primitive-tab-highlight {
    transition: none;
  }
}
.primitive-headline {
  text-align: center;
  font-size: clamp(25px, 4vw, 40px);
  line-height: 1.25;
  font-weight: 500;
  letter-spacing: -0.04em;
}
.headline-controls {
  position: absolute;
  top: 16px;
  left: 16px;
  margin: 0;
  letter-spacing: normal;
  opacity: 0;
  transition: opacity 150ms;
}
.primitive-demo:hover .headline-controls,
.headline-controls:focus-within {
  opacity: 1;
}
@media (hover: none) {
  .headline-controls {
    opacity: 1;
  }
}
@media (max-width: 639px) {
  .primitive-demo,
  .primitive-stage {
    min-height: 300px;
  }
  .primitive-stage {
    padding: 48px 12px 80px;
  }
}
.primitive-live {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--muted-foreground);
  font-size: 12px;
}
.primitive-live::before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent-ink);
}
@media (max-width: 400px) {
  .primitive-stage {
    padding-inline: 12px;
  }
  .primitive-options button {
    padding: 0 10px;
  }
  .primitive-tabs button {
    padding-inline: 10px;
  }
}

