@utility shimmer {
  mask-image: linear-gradient(110deg, #000 35%, #0006 50%, #000 65%);
  mask-size: 250% 100%;
  animation: attachment-shimmer 2s linear infinite;
  @media (prefers-reduced-motion: reduce) {
    animation: none;
    mask-image: none;
  }
}

@keyframes attachment-shimmer {
  from {
    mask-position: 150% 0;
  }
  to {
    mask-position: -50% 0;
  }
}

