@theme inline {
  @keyframes ui-ping {
    from {
      transform: scale(1);
      opacity: 0.55;
    }
    to {
      transform: scale(2.6);
      opacity: 0;
    }
  }
  @keyframes ui-col-in {
    from {
      max-width: 0;
      opacity: 0;
    }
    to {
      max-width: 1em;
      opacity: 1;
    }
  }
  @keyframes ui-col-out {
    from {
      max-width: 1em;
      opacity: 1;
    }
    to {
      max-width: 0;
      opacity: 0;
    }
  }
  @keyframes ui-fade-in {
    from {
      opacity: 0;
    }
    to {
      opacity: 1;
    }
  }
  @keyframes ui-sheen {
    from {
      mask-position: 150% 0;
    }
    to {
      mask-position: -50% 0;
    }
  }
}

