  --warning: var(--color-amber-700);
  --destructive: var(--color-red-600);
  --ink: var(--foreground);
  --body-ink: var(--text-body);
  --line: var(--border);
  --code-background: var(--surface-code);
  --header-background: color-mix(in srgb, var(--background) 93%, transparent);
  --syntax-keyword: var(--accent-ink);
  --syntax-string: var(--success);
  --syntax-url: var(--accent-ink);
  --syntax-comment: var(--muted-foreground);
  --syntax-number: var(--warning);
  color-scheme: light;
}

[data-theme="dark"] {
  --background: var(--surface-page-dark);
  --foreground: var(--text-strong-dark);
  --card: var(--surface-raised-dark);
  --card-foreground: var(--foreground);
  --popover: var(--surface-raised-dark);
  --popover-foreground: var(--foreground);
  --primary: var(--color-brand-300);
  --primary-foreground: var(--text-strong);
  --accent: var(--color-brand-900);
  --accent-foreground: var(--text-strong-dark);
  --accent-ink: var(--color-brand-300);
  --muted: var(--surface-muted-dark);
  --muted-foreground: var(--text-muted-dark);
  --secondary: var(--muted);
  --secondary-foreground: var(--foreground);
  --border: var(--border-subtle-dark);
  --input: var(--border);
  --ring: var(--color-brand-300);
  --success: var(--color-emerald-400);
  --warning: var(--color-amber-400);
  --destructive: var(--color-red-400);
  --ink: var(--foreground);
  --body-ink: var(--text-body-dark);
  --line: var(--border);
  --code-background: var(--surface-code-dark);
  --header-background: color-mix(in srgb, var(--background) 93%, transparent);
  --syntax-keyword: var(--accent-ink);
  --syntax-string: var(--success);
  --syntax-url: var(--accent-ink);
  --syntax-comment: var(--muted-foreground);
  --syntax-number: var(--warning);
  color-scheme: dark;
}
